passing_property:
// Sample combinational behavior on an external clock; the RTL has no reset.

    // Y matches the implemented O21BAI gate equation.
    check_output_matches_gate_equation: assert property (
        @(posedge clk) disable iff (1'b0) Y == ~((~B1_N) & (A1 | A2))
    );

// B1_N high forces the output high.
    check_b1n_high_forces_y_high: assert property (
        @(posedge clk) disable iff (1'b0) B1_N |-> Y
    );

// Both A inputs low force the output high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) disable iff (1'b0) (!A1 && !A2) |-> Y
    );

// A1 high with active-low B input forces the output low.
    check_a1_high_and_b1n_low_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0) (!B1_N && A1) |-> !Y
    );

// A2 high with active-low B input forces the output low.
    check_a2_high_and_b1n_low_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0) (!B1_N && A2) |-> !Y
    );

// A low output requires B1_N to be low.
    check_y_low_requires_b1n_low: assert property (
        @(posedge clk) disable iff (1'b0) !Y |-> !B1_N
    );

// A low output requires at least one A input high.
    check_y_low_requires_a_input_high: assert property (
        @(posedge clk) disable iff (1'b0) !Y |-> (A1 | A2)
    );

// With B1_N low, a high output requires both A inputs low.
    check_y_high_with_b1n_low_requires_a_inputs_low: assert property (
        @(posedge clk) disable iff (1'b0) (Y && !B1_N) |-> (!A1 && !A2)
    );

// RTL has no reset; all checks are sampled on clk.

    // y must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) y == ((a & ~sel) | (b & sel))
    );

// When sel is low, y follows a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (y == a)
    );

// When sel is high, y follows b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (y == b)
    );

// If both inputs are low, y is low.
    check_both_inputs_low: assert property (
        @(posedge clk) ((a == 1'b0) && (b == 1'b0)) |-> (y == 1'b0)
    );

// If both inputs are high, y is high.
    check_both_inputs_high: assert property (
        @(posedge clk) ((a == 1'b1) && (b == 1'b1)) |-> (y == 1'b1)
    );

// Y must always equal the NOR of A, B, C, and D_N.
    check_nor_equation: assert property (
        @(posedge clk) Y == ~(A | B | C | D_N)
    );

// If all inputs are low, Y must be high.
    check_all_low_drives_high: assert property (
        @(posedge clk) (!A && !B && !C && !D_N) |-> (Y == 1'b1)
    );

// A high forces Y low.
    check_a_high_drives_low: assert property (
        @(posedge clk) A |-> (Y == 1'b0)
    );

// B high forces Y low.
    check_b_high_drives_low: assert property (
        @(posedge clk) B |-> (Y == 1'b0)
    );

// C high forces Y low.
    check_c_high_drives_low: assert property (
        @(posedge clk) C |-> (Y == 1'b0)
    );

// D_N high forces Y low.
    check_d_n_high_drives_low: assert property (
        @(posedge clk) D_N |-> (Y == 1'b0)
    );

// A high Y means all inputs are low.
    check_high_output_requires_all_low: assert property (
        @(posedge clk) (Y == 1'b1) |-> (!A && !B && !C && !D_N)
    );

// A low Y means at least one input is high.
    check_low_output_requires_some_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A || B || C || D_N)
    );

// Addition opcode drives Y with the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk)
        (op === 2'b00) |-> (Y === 8'(A + B))
    );

// Subtraction opcode drives Y with the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk)
        (op === 2'b01) |-> (Y === 8'(A - B))
    );

// Addition returns the 8-bit sum and sets valid.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((result == (a + b)) && (valid == 1'b1))
    );

// Subtraction returns the 8-bit difference and sets valid.
    check_sub_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((result == (a - b)) && (valid == 1'b1))
    );

// Division by zero forces a zero result and clears valid.
    check_div_zero_result: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b == 8'h00)) |-> ((result == 8'h00) && (valid == 1'b0))
    );

// valid can be low only for division by zero.
    check_valid_low_only_on_div_zero: assert property (
        @(posedge clk)
        (valid == 1'b0) |-> ((op == 2'b11) && (b == 8'h00))
    );

// Any case other than division by zero must set valid.
    check_valid_high_otherwise: assert property (
        @(posedge clk)
        (!((op == 2'b11) && (b == 8'h00))) |-> (valid == 1'b1)
    );

// Output matches the implemented nested mux expression.
    check_output_matches_mux_tree: assert property (
        @(posedge clk)
        out == (sel[1] ? (sel[0] ? data3 : data2) : (sel[0] ? data1 : data0))
    );

// sel=00 routes data0 to the output.
    check_sel_00_routes_data0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == data0)
    );

// sel=01 routes data1 to the output.
    check_sel_01_routes_data1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == data1)
    );

// sel=10 routes data2 to the output.
    check_sel_10_routes_data2: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == data2)
    );

// sel=11 routes data3 to the output.
    check_sel_11_routes_data3: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == data3)
    );

// X must equal the AND of A, B, and C.
    check_x_matches_and3: assert property (
        @(posedge clk) X == (A & B & C)
    );

// X high requires all three inputs to be high.
    check_x_high_implies_all_inputs_high: assert property (
        @(posedge clk) X |-> (A && B && C)
    );

// All three inputs high must drive X high.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C) |-> X
    );

// Any low input must force X low.
    check_any_low_input_forces_x_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C)) |-> !X
    );

// Output must implement the mux equation.
    check_mux_function: assert property (
        @(posedge clk) Z === ((S == 1'b0) ? A : B)
    );

// Low select routes A to the output.
    check_select_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Z === A)
    );

// High select routes B to the output.
    check_select_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Z === B)
    );

// If both inputs match, the output must match them as well.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A === B) |-> (Z === A)
    );

// If both inputs are equal, S matches that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) disable iff (1'b0) (D0 == D1) |-> (S == D0)
    );

// Len_int matches the implemented OR-of-products equation.
    check_len_equation: assert property (
        @(posedge clk)
        Len_int == ((n63 & Z_B) | ((~n63) & (~Z_B) & (~n62)))
    );

// Ren_int matches the implemented OR-of-products equation.
    check_ren_equation: assert property (
        @(posedge clk)
        Ren_int == ((Z_B & n62) | ((~n63) & (~Z_B) & (~n62)))
    );

// When Z_B is high, the outputs follow n63 and n62 directly.
    check_outputs_follow_inputs_when_zb_high: assert property (
        @(posedge clk)
        Z_B |-> ((Len_int == n63) && (Ren_int == n62))
    );

// When Z_B is low, both outputs reduce to !n63 & !n62.
    check_outputs_when_zb_low: assert property (
        @(posedge clk)
        (!Z_B) |-> ((Len_int == ((!n63) && (!n62))) && (Ren_int == ((!n63) && (!n62))))
    );

// With Z_B low, any high input forces both outputs low.
    check_outputs_low_when_zb_low_and_any_input_high: assert property (
        @(posedge clk)
        ((!Z_B) && (n63 || n62)) |-> ((!Len_int) && (!Ren_int))
    );

// With all three inputs low, both outputs must be high.
    check_outputs_high_when_all_inputs_low: assert property (
        @(posedge clk)
        ((!Z_B) && (!n63) && (!n62)) |-> (Len_int && Ren_int)
    );

// When sel is 2'b00, out must reflect in[0].
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// When sel is 2'b01, out must reflect in[1].
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// When sel is 2'b10, out must reflect in[2].
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// When sel is 2'b11, out must reflect in[3].
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Y and Z are never driven high together.
    check_outputs_not_both_high: assert property (
        @(posedge clk) !(Y && Z)
    );

// For S=00, any nonzero A selects Y=1 and Z=0.
    check_sel00_a_priority: assert property (
        @(posedge clk)
        (S == 2'b00 && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=00, B selects Y=0 and Z=1 when A is zero.
    check_sel00_b_priority: assert property (
        @(posedge clk)
        (S == 2'b00 && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=00, outputs are 0 when both A and B are zero.
    check_sel00_default_zero: assert property (
        @(posedge clk)
        (S == 2'b00 && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=01, any nonzero B selects Y=0 and Z=1.
    check_sel01_b_priority: assert property (
        @(posedge clk)
        (S == 2'b01 && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=01, A selects Y=1 and Z=0 when B is zero.
    check_sel01_a_priority: assert property (
        @(posedge clk)
        (S == 2'b01 && (B == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=01, outputs are 0 when both B and A are zero.
    check_sel01_default_zero: assert property (
        @(posedge clk)
        (S == 2'b01 && (B == 4'b0000) && (A == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=10, any nonzero C forces both outputs low.
    check_sel10_c_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=10, A selects Y=1 and Z=0 when C is zero.
    check_sel10_a_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=10, B selects Y=0 and Z=1 when C and A are zero.
    check_sel10_b_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=10, outputs are 0 when C, A, and B are all zero.
    check_sel10_default_zero: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=11, any nonzero D forces both outputs low.
    check_sel11_d_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=11, A selects Y=1 and Z=0 when D is zero.
    check_sel11_a_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=11, B selects Y=0 and Z=1 when D and A are zero.
    check_sel11_b_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=11, outputs are 0 when D, A, and B are all zero.
    check_sel11_default_zero: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// S matches the implemented 4-bit addition result.
    check_sum_function: assert property (
        @(posedge clk) S == ((A + B + Cin) & 4'hF)
    );

// V is always low in the implemented logic.
    check_v_always_low: assert property (
        @(posedge clk) V == 1'b0
    );

// With B and Cin low, S passes A through.
    check_pass_a_when_b_and_cin_zero: assert property (
        @(posedge clk) ((B == 4'h0) && (Cin == 1'b0)) |-> (S == A)
    );

// With A and Cin low, S passes B through.
    check_pass_b_when_a_and_cin_zero: assert property (
        @(posedge clk) ((A == 4'h0) && (Cin == 1'b0)) |-> (S == B)
    );

// With both operands low, S reflects Cin in bit 0.
    check_zero_operands_reflect_cin: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0)) |-> (S == {3'b000, Cin})
    );

// All-zero inputs produce zero outputs.
    check_all_zero_inputs: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0) && (Cin == 1'b0)) |-> ((S == 4'h0) && (V == 1'b0))
    );

// bcd[3] is high only for an all-ones input.
    check_bcd_bit3_all_ones: assert property (
        @(posedge clk)
        (bcd[3] == (bin == 4'b1111))
    );

// bcd[2] is high for the four three-ones input patterns.
    check_bcd_bit2_three_high_patterns: assert property (
        @(posedge clk)
        (bcd[2] == (
            (bin == 4'b0111) ||
            (bin == 4'b1011) ||
            (bin == 4'b1101) ||
            (bin == 4'b1110)
        ))
    );

// bcd[1] is high for the four patterns encoded by the RTL.
    check_bcd_bit1_selected_patterns: assert property (
        @(posedge clk)
        (bcd[1] == (
            (bin == 4'b0011) ||
            (bin == 4'b0110) ||
            (bin == 4'b1001) ||
            (bin == 4'b1100)
        ))
    );

// bcd[0] is high for the four patterns encoded by the RTL.
    check_bcd_bit0_selected_patterns: assert property (
        @(posedge clk)
        (bcd[0] == (
            (bin == 4'b0001) ||
            (bin == 4'b1000) ||
            (bin == 4'b1010) ||
            (bin == 4'b1100)
        ))
    );

// Inputs 0, 2, 4, and 5 produce a zero output.
    check_zero_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0000) ||
            (bin == 4'b0010) ||
            (bin == 4'b0100) ||
            (bin == 4'b0101)
        ) |-> (bcd == 4'b0000)
    );

// Inputs 1, 8, and 10 produce 0001.
    check_one_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0001) ||
            (bin == 4'b1000) ||
            (bin == 4'b1010)
        ) |-> (bcd == 4'b0001)
    );

// Inputs 3, 6, and 9 produce 0010.
    check_two_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0011) ||
            (bin == 4'b0110) ||
            (bin == 4'b1001)
        ) |-> (bcd == 4'b0010)
    );

// Inputs 7, 11, 13, and 14 produce 0100.
    check_four_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0111) ||
            (bin == 4'b1011) ||
            (bin == 4'b1101) ||
            (bin == 4'b1110)
        ) |-> (bcd == 4'b0100)
    );

// Input 12 is the only case that produces 0011.
    check_three_output_case: assert property (
        @(posedge clk)
        (bin == 4'b1100) |-> (bcd == 4'b0011)
    );

// Input 15 produces 1000.
    check_eight_output_case: assert property (
        @(posedge clk)
        (bin == 4'b1111) |-> (bcd == 4'b1000)
    );

// gray[3] is a direct copy of bin[3].
    check_gray_bit3_passthrough: assert property (
        @(posedge clk) gray[3] == bin[3]
    );

// gray[2] is bin[3] XOR bin[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray[2] == (bin[3] ^ bin[2])
    );

// gray[1] is bin[2] XOR bin[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray[1] == (bin[2] ^ bin[1])
    );

// gray[0] is bin[1] XOR bin[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray[0] == (bin[1] ^ bin[0])
    );

// The full gray output matches the implemented conversion.
    check_gray_vector_conversion: assert property (
        @(posedge clk) gray == {bin[3], (bin[3] ^ bin[2]), (bin[2] ^ bin[1]), (bin[1] ^ bin[0])}
    );

// A sampled reset leaves the counter at zero on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// An enabled cycle increments the counter by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (q == ($past(q) + 4'b0001))
    );

// A disabled cycle holds the counter value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (q == $past(q))
    );

// The counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (q == 4'b1111)) |=> (q == 4'b0000)
    );

// External sampling clock; RTL has no clock or reset.

    // SUM must match the implemented bitwise XOR with replicated CI.
    check_sum_vector: assert property (
        @(posedge clk) SUM == (A ^ B ^ {4{CI}})
    );

// SUM[0] is A[0] xor B[0] xor CI.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0] ^ CI)
    );

// SUM[1] is A[1] xor B[1] xor CI.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == (A[1] ^ B[1] ^ CI)
    );

// SUM[2] is A[2] xor B[2] xor CI.
    check_sum_bit2: assert property (
        @(posedge clk) SUM[2] == (A[2] ^ B[2] ^ CI)
    );

// SUM[3] is A[3] xor B[3] xor CI.
    check_sum_bit3: assert property (
        @(posedge clk) SUM[3] == (A[3] ^ B[3] ^ CI)
    );

// COUT must match the implemented relation to SUM[3].
    check_cout_from_sum_msb: assert property (
        @(posedge clk) COUT == (SUM[3] ^ (A[3] & B[3] & CI))
    );

// COUT must match the exact implemented MSB equation.
    check_cout_function: assert property (
        @(posedge clk) COUT == (A[3] ^ B[3] ^ CI ^ (A[3] & B[3] & CI))
    );

// With CI low, SUM reduces to A xor B.
    check_sum_ci_low: assert property (
        @(posedge clk) (!CI) |-> (SUM == (A ^ B))
    );

// With CI high, SUM reduces to bitwise complement of A xor B.
    check_sum_ci_high: assert property (
        @(posedge clk) CI |-> (SUM == ~(A ^ B))
    );

// With CI low, COUT reduces to the MSB xor.
    check_cout_ci_low: assert property (
        @(posedge clk) (!CI) |-> (COUT == (A[3] ^ B[3]))
    );

// With CI high, COUT is high only when both MSB inputs are low.
    check_cout_ci_high: assert property (
        @(posedge clk) CI |-> (COUT == ~(A[3] | B[3]))
    );

// Addition mode returns the 8-bit sum of a and b.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == byte_t'(a + b))
    );

// Subtraction mode returns the 8-bit difference of a and b.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == byte_t'(a - b))
    );

// Division by zero forces the result to zero.
    check_div_by_zero_result: assert property (
        @(posedge clk) ((op == 2'b11) && (b == 8'd0)) |-> (result == 8'd0)
    );

// 0101 decodes ctrl low.
    check_case_0101_ctrl_low: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b0101) |-> (ctrl == 1'b0)
    );

// 1101 decodes ctrl high.
    check_case_1101_ctrl_high: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b1101) |-> (ctrl == 1'b1)
    );

// 0110 decodes ctrl high.
    check_case_0110_ctrl_high: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b0110) |-> (ctrl == 1'b1)
    );

// 1110 decodes ctrl low.
    check_case_1110_ctrl_low: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} == 4'b1110) |-> (ctrl == 1'b0)
    );

// All unspecified input combinations drive ctrl low.
    check_default_ctrl_low: assert property (
        @(posedge clk)
        (({xor_info, or_info, round_mode} != 4'b0101) &&
         ({xor_info, or_info, round_mode} != 4'b1101) &&
         ({xor_info, or_info, round_mode} != 4'b0110) &&
         ({xor_info, or_info, round_mode} != 4'b1110)) |-> (ctrl == 1'b0)
    );

// ctrl can only be high for the two explicit high-output cases.
    check_ctrl_high_only_on_explicit_high_cases: assert property (
        @(posedge clk)
        ctrl |-> (({xor_info, or_info, round_mode} == 4'b1101) ||
                  ({xor_info, or_info, round_mode} == 4'b0110))
    );

// ctrl exactly matches the case decode.
    check_ctrl_matches_case_decode: assert property (
        @(posedge clk)
        ctrl == ((({xor_info, or_info, round_mode} == 4'b1101) ||
                  ({xor_info, or_info, round_mode} == 4'b0110)) ? 1'b1 : 1'b0)
    );

// Bit 7 has highest priority and drives the next registered outputs.
    check_bit7_priority: assert property (
        @(posedge clk)
        in[7] |=> (pos == 2'b11 && out_sel == 4'b0001)
    );

// Bit 6 is selected when bit 7 is low.
    check_bit6_priority: assert property (
        @(posedge clk)
        ((in[7] == 1'b0) && (in[6] == 1'b1)) |=> (pos == 2'b10 && out_sel == 4'b0010)
    );

// Bit 5 is selected when bits 7 and 6 are low.
    check_bit5_priority: assert property (
        @(posedge clk)
        ((in[7:6] == 2'b00) && (in[5] == 1'b1)) |=> (pos == 2'b00 && out_sel == 4'b0100)
    );

// Bit 4 is selected when bits 7 through 5 are low.
    check_bit4_priority: assert property (
        @(posedge clk)
        ((in[7:5] == 3'b000) && (in[4] == 1'b1)) |=> (pos == 2'b11 && out_sel == 4'b1000)
    );

// Bit 3 is selected when bits 7 through 4 are low.
    check_bit3_priority: assert property (
        @(posedge clk)
        ((in[7:4] == 4'b0000) && (in[3] == 1'b1)) |=> (pos == 2'b10 && out_sel == 4'b0000)
    );

// Bit 2 is selected when bits 7 through 3 are low.
    check_bit2_priority: assert property (
        @(posedge clk)
        ((in[7:3] == 5'b00000) && (in[2] == 1'b1)) |=> (pos == 2'b01 && out_sel == 4'b0000)
    );

// Bit 1 is selected when bits 7 through 2 are low.
    check_bit1_priority: assert property (
        @(posedge clk)
        ((in[7:2] == 6'b000000) && (in[1] == 1'b1)) |=> (pos == 2'b00 && out_sel == 4'b0000)
    );

// When bits 7 through 1 are clear, bit 0 is ignored and outputs go to zero.
    check_no_selected_bit_or_bit0_only: assert property (
        @(posedge clk)
        (in[7:1] == 7'b0000000) |=> (pos == 2'b00 && out_sel == 4'b0000)
    );

// Reset clears the counter output on the following clock.
    check_reset_clears_output: assert property (
        @(posedge clock) reset |=> (output_value == ZERO)
    );

// Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) reset && enable |=> (output_value == ZERO)
    );

// Enable loads input_value minus the decrement value.
    check_enable_loads_decremented_input: assert property (
        @(posedge clock) disable iff (reset)
        enable |=> (output_value == ($past(input_value) - DEC_VALUE_W))
    );

// When enable is low, the counter output holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (reset)
        !enable |=> (output_value == $past(output_value))
    );

// Reset forces the registered output low.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (data_out == ZERO)
    );

// A sampled reset keeps the output low until the next clock edge.
    check_reset_keeps_zero_next_cycle: assert property (
        @(posedge clk) reset |=> (data_out == ZERO)
    );

// A nonzero output is never observed while reset is sampled high.
    check_nonzero_output_not_during_reset: assert property (
        @(posedge clk) (data_out != ZERO) |-> !reset
    );

// A sampled reset clears the counter on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

// Reset has priority over enable when both are high.
    check_reset_overrides_enable: assert property (
        @(posedge clk) (reset && enable) |=> (out == 4'b0000)
    );

// When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (out == ($past(out) + 4'd1))
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (out == $past(out))
    );

// Incrementing from 4'hF wraps the counter to 4'h0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (out == 4'hF)) |=> (out == 4'h0)
    );

// External clk samples this combinational DUT.

    // Y matches the implemented AND/NOT/OR/NOR function.
    check_full_boolean_function: assert property (
        @(posedge clk)
        Y == ~((A1 & A2) | ((~B1) | C1))
    );

// B1 low forces the OR path high and Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk)
        !B1 |-> !Y
    );

// C1 high forces the OR path high and Y low.
    check_c1_high_forces_y_low: assert property (
        @(posedge clk)
        C1 |-> !Y
    );

// A1 and A2 high force the NOR output low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk)
        (A1 && A2) |-> !Y
    );

// Y high requires B1 high, C1 low, and at least one A input low.
    check_y_high_requires_enable_terms: assert property (
        @(posedge clk)
        Y |-> (B1 && !C1 && (!A1 || !A2))
    );

// B1 high, C1 low, and either A input low force Y high.
    check_enable_terms_force_y_high: assert property (
        @(posedge clk)
        (B1 && !C1 && (!A1 || !A2)) |-> Y
    );

// Y low means at least one blocking term is active.
    check_y_low_requires_blocking_term: assert property (
        @(posedge clk)
        !Y |-> ((A1 && A2) || !B1 || C1)
    );

// cfg_busdev_del is the registered copy of cfg_busdev.
    check_cfg_busdev_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cfg_busdev_del == $past(cfg_busdev))
    );

// cfg_devcsr_del is the registered copy of cfg_devcsr.
    check_cfg_devcsr_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cfg_devcsr_del == $past(cfg_devcsr))
    );

// cfg_linkcsr_del is the registered copy of cfg_linkcsr.
    check_cfg_linkcsr_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cfg_linkcsr_del == $past(cfg_linkcsr))
    );

// cfg_msicsr_del is the registered copy of cfg_msicsr.
    check_cfg_msicsr_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cfg_msicsr_del == $past(cfg_msicsr))
    );

// cfg_prmcsr_del is the registered copy of cfg_prmcsr.
    check_cfg_prmcsr_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cfg_prmcsr_del == $past(cfg_prmcsr))
    );

// cfg_tcvcmap_del is the registered copy of cfg_tcvcmap.
    check_cfg_tcvcmap_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cfg_tcvcmap_del == $past(cfg_tcvcmap))
    );

// app_int_sts_del is the registered copy of app_int_sts.
    check_app_int_sts_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (app_int_sts_del == $past(app_int_sts))
    );

// app_int_sts_ack_del is the registered copy of app_int_sts_ack.
    check_app_int_sts_ack_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (app_int_sts_ack_del == $past(app_int_sts_ack))
    );

// pex_msi_num_del is the registered copy of pex_msi_num.
    check_pex_msi_num_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (pex_msi_num_del == $past(pex_msi_num))
    );

// cpl_err_del is the registered copy of cpl_err.
    check_cpl_err_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cpl_err_del == $past(cpl_err))
    );

// cpl_pending_del is the registered copy of cpl_pending.
    check_cpl_pending_delay: assert property (
        @(posedge clk) disable iff (!rstn)
        1'b1 |=> (cpl_pending_del == $past(cpl_pending))
    );

// The MSB of out is never asserted by this implementation.
    check_out3_constant_low: assert property (
        @(posedge clk) out[3] == 1'b0
    );

// out[2] is asserted only when both input bits are high.
    check_out2_equation: assert property (
        @(posedge clk) out[2] == (in[0] & in[1])
    );

// Input 2'b11 maps to 4'b0100.
    check_input_11_case: assert property (
        @(posedge clk) (in == 2'b11) |-> (out == 4'b0100)
    );

// Outputs must match the full 5-bit addition result.
    check_full_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// No-overflow additions must produce no carry out.
    check_no_overflow_behavior: assert property (
        @(posedge clk)
        (({1'b0, a} + {1'b0, b} + cin) <= 5'd15)
        |-> ({1'b0, sum} == ({1'b0, a} + {1'b0, b} + cin) && cout == 1'b0)
    );

// Overflow additions must wrap the low 4 bits and set carry out.
    check_overflow_behavior: assert property (
        @(posedge clk)
        (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
        |-> ({1'b0, sum} == (({1'b0, a} + {1'b0, b} + cin) - 5'd16) && cout == 1'b1)
    );

// All-zero inputs must produce a zero result.
    check_zero_inputs: assert property (
        @(posedge clk)
        (a == 4'h0 && b == 4'h0 && cin == 1'b0)
        |-> (sum == 4'h0 && cout == 1'b0)
    );

// Maximum inputs must produce 0xF with carry out set.
    check_max_inputs: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'hF && cin == 1'b1)
        |-> (sum == 4'hF && cout == 1'b1)
    );

// Synchronous reset loads counter_value from initial_value.
    check_reset_load: assert property (
        @(posedge clk) reset |=> counter_value == $past(initial_value)
    );

// In up mode, non-maximum values increment by one.
    check_up_increment: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b0 && counter_value != 4'b1111) |=> counter_value == ($past(counter_value) + 4'd1)
    );

// In up mode, 15 wraps to 0.
    check_up_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b0 && counter_value == 4'b1111) |=> counter_value == 4'b0000
    );

// In down mode, non-zero values decrement by one.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b1 && counter_value != 4'b0000) |=> counter_value == ($past(counter_value) - 4'd1)
    );

// In down mode, 0 wraps to 15.
    check_down_wrap: assert property (
        @(posedge clk) disable iff (reset)
        (mode == 1'b1 && counter_value == 4'b0000) |=> counter_value == 4'b1111
    );

// Opcode 00 produces the low 8 bits of the sum.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ({1'b0, result} == (({1'b0, num1} + {1'b0, num2}) & 9'h0ff))
    );

// Opcode 01 produces the low 8 bits of the difference.
    check_subtract_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ({1'b0, result} == (({1'b0, num1} - {1'b0, num2}) & 9'h0ff))
    );

// Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 2'b00)
    );

// Reset has priority even when enable is high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 2'b00)
    );

// Enable increments the counter by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 2'b01))
    );

// Disable holds the counter value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

// The maximum count wraps to zero when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 2'b11)) |=> (count == 2'b00)
    );

// out selects in_0 when sel is 2'b00.
    check_out_sel_00: assert property (
        @(posedge shift) (sel === 2'b00) |-> (out === in_0)
    );

// out selects in_1 when sel is 2'b01.
    check_out_sel_01: assert property (
        @(posedge shift) (sel === 2'b01) |-> (out === in_1)
    );

// out selects in_2 when sel is 2'b10.
    check_out_sel_10: assert property (
        @(posedge shift) (sel === 2'b10) |-> (out === in_2)
    );

// out selects in_3 when sel is 2'b11.
    check_out_sel_11: assert property (
        @(posedge shift) (sel === 2'b11) |-> (out === in_3)
    );

// out stays stable when sel and all mux inputs stay stable.
    check_out_stable_when_mux_inputs_stable: assert property (
        @(posedge shift)
        1'b1 |=> (
            !((sel  === $past(sel))  &&
              (in_0 === $past(in_0)) &&
              (in_1 === $past(in_1)) &&
              (in_2 === $past(in_2)) &&
              (in_3 === $past(in_3))) ||
            (out === $past(out))
        )
    );

// Reset keeps count and done cleared.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |-> (count == 16'd0 && done == 1'b0)
    );

// Reaching max_count wraps count and raises done on the next cycle.
    check_wrap_on_max_count: assert property (
        @(posedge clk) disable iff (rst)
        (count == max_count) |=> (count == 16'd0 && done == 1'b1)
    );

// Any non-max count increments and keeps done low on the next cycle.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst)
        (count != max_count) |=> (count == ($past(count) + 16'd1) && done == 1'b0)
    );

// The first clock after reset release still observes the reset state.
    check_hold_reset_state_after_release: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) |-> (count == 16'd0 && done == 1'b0)
    );

// X must equal the AND of A1, A2, B1, and VPWR.
    check_x_matches_and: assert property (
        @(posedge clk) X == (A1 & A2 & B1 & VPWR)
    );

// When all functional inputs are high, X must be high.
    check_x_high_when_all_inputs_high: assert property (
        @(posedge clk) (A1 && A2 && B1 && VPWR) |-> X
    );

// If any functional input is low, X must be low.
    check_x_low_when_any_input_low: assert property (
        @(posedge clk) ((!A1) || (!A2) || (!B1) || (!VPWR)) |-> !X
    );

// A high X implies all functional inputs are high.
    check_x_implies_all_inputs_high: assert property (
        @(posedge clk) X |-> (A1 && A2 && B1 && VPWR)
    );

// Y must equal A when S is low.
    check_select_a: assert property (
        @(posedge clk) (!S) |-> (Y == A)
    );

// Y must equal B when S is high.
    check_select_b: assert property (
        @(posedge clk) S |-> (Y == B)
    );

// Y must always match the mux select equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (S ? B : A)
    );

// If A and B are equal, Y must match that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

// Combined output must match the 5-bit sum of A, B, and cin.
    check_full_sum_relation: assert property (
        @(posedge clk) {cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, cin})
    );

// The least significant sum bit follows full-adder XOR behavior.
    check_lsb_sum_bit: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ cin)
    );

// The next sum bit uses bit 0 carry as a full-adder would.
    check_bit1_sum_bit: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & cin) | (B[0] & cin)))
    );

// Carry-out is asserted when the arithmetic result is at least 16.
    check_carry_out_threshold: assert property (
        @(posedge clk) cout == (({1'b0, A} + {1'b0, B} + {4'b0000, cin}) >= 5'd16)
    );

// Zero inputs must produce a zero sum and no carry-out.
    check_zero_addition: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && cin == 1'b0) |-> (S == 4'h0 && cout == 1'b0)
    );

// A passes through when B and cin are zero.
    check_a_passthrough: assert property (
        @(posedge clk) (B == 4'h0 && cin == 1'b0) |-> (S == A && cout == 1'b0)
    );

// B passes through when A and cin are zero.
    check_b_passthrough: assert property (
        @(posedge clk) (A == 4'h0 && cin == 1'b0) |-> (S == B && cout == 1'b0)
    );

// Carry-in increments A when B is zero.
    check_cin_increments_a: assert property (
        @(posedge clk) (B == 4'h0 && cin == 1'b1) |-> ({cout, S} == ({1'b0, A} + 5'd1))
    );

// Carry-in increments B when A is zero.
    check_cin_increments_b: assert property (
        @(posedge clk) (A == 4'h0 && cin == 1'b1) |-> ({cout, S} == ({1'b0, B} + 5'd1))
    );

// Adding bitwise complements without carry-in yields all ones and no carry.
    check_complement_without_carry: assert property (
        @(posedge clk) (B == ~A && cin == 1'b0) |-> (S == 4'hF && cout == 1'b0)
    );

// Adding bitwise complements with carry-in yields zero and carry-out.
    check_complement_with_carry: assert property (
        @(posedge clk) (B == ~A && cin == 1'b1) |-> (S == 4'h0 && cout == 1'b1)
    );

// Sum must match the 4-bit addition result.
    check_sum_result: assert property (
        @(posedge clk) sum == (a + b)
    );

// Zero on a passes b through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (a == 4'h0) |-> ((sum == b) && (carry == 1'b0))
    );

// Zero on b passes a through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (b == 4'h0) |-> ((sum == a) && (carry == 1'b0))
    );

// Sampled low reset clears both outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (reset == 1'b0) |-> (out == 4'b0000) && (dout == 4'b0000)
    );

// With dir high, out loads the input value.
    check_out_loads_input_when_dir_high: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b1) |=> (out == $past(in))
    );

// With dir high, dout loads the reversed input value.
    check_dout_loads_reversed_input_when_dir_high: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b1) |=> (dout == {$past(in[0]), $past(in[1]), $past(in[2]), $past(in[3])})
    );

// With dir low, out still loads the input value.
    check_out_loads_input_when_dir_low: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b0) |=> (out == $past(in))
    );

// With dir low, dout holds its previous value.
    check_dout_holds_when_dir_low: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b0) |=> (dout == $past(dout))
    );

// After reset was sampled low, readdata is zero on the next active clock.
    check_post_reset_readdata_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($past(reset_n) === 1'b0) |-> (readdata == 16'h0000)
    );

// A prior read of address 0 returns the prior input, unless reset forced zero.
    check_addr0_read_matches_input_or_reset_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b00)) |->
        ((readdata == $past(in_port)) || (readdata == 16'h0000))
    );

// A prior read of address 1 returns zero.
    check_addr1_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b01)) |-> (readdata == 16'h0000)
    );

// A prior read of address 2 returns zero.
    check_addr2_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b10)) |-> (readdata == 16'h0000)
    );

// A prior read of address 3 returns zero.
    check_addr3_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b11)) |-> (readdata == 16'h0000)
    );

// Address 0 with zero input returns zero on the following clock.
    check_addr0_zero_input_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b00) && ($past(in_port) === 16'h0000)) |->
        (readdata == 16'h0000)
    );

// Any nonzero readdata must come from a prior read of address 0.
    check_nonzero_readdata_from_addr0: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && (readdata != 16'h0000)) |->
        (($past(address) === 2'b00) && (readdata == $past(in_port)))
    );

// Sample on an external clock because this cell is combinational and has no reset.

    // Y matches the buffered 4-input NAND with A_N inverted internally.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(D & C & B & ~A_N)
    );

// All effective NAND inputs high drive the output low.
    check_all_active_inputs_drive_low: assert property (
        @(posedge clk) (!A_N && B && C && D) |-> !Y
    );

// A low output requires the single active-input minterm.
    check_low_output_requires_all_active_inputs: assert property (
        @(posedge clk) !Y |-> (!A_N && B && C && D)
    );

// A_N high forces the output high.
    check_a_n_high_forces_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B low forces the output high.
    check_b_low_forces_high: assert property (
        @(posedge clk) !B |-> Y
    );

// C low forces the output high.
    check_c_low_forces_high: assert property (
        @(posedge clk) !C |-> Y
    );

// D low forces the output high.
    check_d_low_forces_high: assert property (
        @(posedge clk) !D |-> Y
    );

// A high output means at least one input blocks the low minterm.
    check_high_output_has_blocking_input: assert property (
        @(posedge clk) Y |-> (A_N || !B || !C || !D)
    );

// Inputs below 16 return the default value 0.
    check_default_below_16: assert property (
        @(posedge clk) (qp_i < 6'd16) |-> (beta_o == 7'd0)
    );

// Inputs 16 through 28 map to qp_i minus 10.
    check_linear_map_16_to_28: assert property (
        @(posedge clk) ((qp_i >= 6'd16) && (qp_i <= 6'd28)) |-> (beta_o == ({1'b0, qp_i} - 7'd10))
    );

// The first entry of the upper segment maps 29 to 20.
    check_boundary_29_maps_to_20: assert property (
        @(posedge clk) (qp_i == 6'd29) |-> (beta_o == 7'd20)
    );

// Inputs 29 through 51 map to 2 * (qp_i - 19).
    check_even_map_29_to_51: assert property (
        @(posedge clk) ((qp_i >= 6'd29) && (qp_i <= 6'd51)) |-> (beta_o == (({1'b0, qp_i} - 7'd19) << 1))
    );

// The highest explicit table entry maps 51 to 64.
    check_boundary_51_maps_to_64: assert property (
        @(posedge clk) (qp_i == 6'd51) |-> (beta_o == 7'd64)
    );

// Inputs above 51 return the default value 0.
    check_default_above_51: assert property (
        @(posedge clk) (qp_i > 6'd51) |-> (beta_o == 7'd0)
    );

// Select 0 routes d0 to o.
    check_sel_0_routes_d0: assert property (
        @(posedge clk) (s === 3'd0) |-> (o === d0)
    );

// Select 1 routes d1 to o.
    check_sel_1_routes_d1: assert property (
        @(posedge clk) (s === 3'd1) |-> (o === d1)
    );

// Select 2 routes d2 to o.
    check_sel_2_routes_d2: assert property (
        @(posedge clk) (s === 3'd2) |-> (o === d2)
    );

// Select 3 routes d3 to o.
    check_sel_3_routes_d3: assert property (
        @(posedge clk) (s === 3'd3) |-> (o === d3)
    );

// Select 4 routes d4 to o.
    check_sel_4_routes_d4: assert property (
        @(posedge clk) (s === 3'd4) |-> (o === d4)
    );

// Select 5 uses the default path and routes d5 to o.
    check_sel_5_routes_d5: assert property (
        @(posedge clk) (s === 3'd5) |-> (o === d5)
    );

// Select 6 uses the default path and routes d5 to o.
    check_sel_6_routes_d5: assert property (
        @(posedge clk) (s === 3'd6) |-> (o === d5)
    );

// Select 7 uses the default path and routes d5 to o.
    check_sel_7_routes_d5: assert property (
        @(posedge clk) (s === 3'd7) |-> (o === d5)
    );

// 0001 maps to output bit 0.
    check_map_0001: assert property (
        @(posedge clk) (B == 4'b0001) |-> (O == 8'b00000001)
    );

// 0010 maps to output bit 1.
    check_map_0010: assert property (
        @(posedge clk) (B == 4'b0010) |-> (O == 8'b00000010)
    );

// 0100 maps to output bit 2.
    check_map_0100: assert property (
        @(posedge clk) (B == 4'b0100) |-> (O == 8'b00000100)
    );

// 1000 maps to output bit 3.
    check_map_1000: assert property (
        @(posedge clk) (B == 4'b1000) |-> (O == 8'b00001000)
    );

// All other input values drive zero.
    check_default_zero: assert property (
        @(posedge clk)
        ((B != 4'b0001) && (B != 4'b0010) && (B != 4'b0100) && (B != 4'b1000))
        |-> (O == 8'b00000000)
    );

// The upper four output bits are always zero.
    check_upper_bits_zero: assert property (
        @(posedge clk) (O[7:4] == 4'b0000)
    );

// No reset in RTL; combinational behavior is sampled on clk.

    // X must equal the AND of B, C, and the inversion of A_N.
    check_and3b_function: assert property (
        @(posedge clk) X == ((~A_N) & B & C)
    );

// A_N high forces the inverted input low, so X must be low.
    check_a_n_high_blocks_output: assert property (
        @(posedge clk) A_N |-> !X
    );

// B low forces the AND output low.
    check_b_low_blocks_output: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces the AND output low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) !C |-> !X
    );

// When A_N is low and both B and C are high, X must be high.
    check_all_enables_drive_output_high: assert property (
        @(posedge clk) (!A_N && B && C) |-> X
    );

// X high implies A_N is low and both B and C are high.
    check_x_high_requires_all_inputs: assert property (
        @(posedge clk) X |-> (!A_N && B && C)
    );

// With A_N low, X reduces to B AND C.
    check_a_n_low_reduces_to_bc_and: assert property (
        @(posedge clk) !A_N |-> (X == (B & C))
    );

// Output matches the RTL sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        output1 == ((input1 & input2) | (input3 & input4 & input5))
    );

// The input1/input2 AND path forces the output high.
    check_first_path_drives_high: assert property (
        @(posedge clk)
        (input1 & input2) |-> output1
    );

// The input3/input4/input5 AND path forces the output high.
    check_second_path_drives_high: assert property (
        @(posedge clk)
        (input3 & input4 & input5) |-> output1
    );

// A high output must come from at least one implemented path.
    check_output_high_has_valid_cause: assert property (
        @(posedge clk)
        output1 |-> ((input1 & input2) | (input3 & input4 & input5))
    );

// If the first path is inactive, output equals the second path.
    check_no_first_path_means_second_path_only: assert property (
        @(posedge clk)
        !(input1 & input2) |-> (output1 == (input3 & input4 & input5))
    );

// If the second path is inactive, output equals the first path.
    check_no_second_path_means_first_path_only: assert property (
        @(posedge clk)
        !(input3 & input4 & input5) |-> (output1 == (input1 & input2))
    );

// out_always selects b when both select inputs are high.
    check_out_always_selects_b: assert property (
        @(posedge clk) (sel_b1 & sel_b2) |-> (out_always == b)
    );

// out_always selects a when both select inputs are not high.
    check_out_always_selects_a: assert property (
        @(posedge clk) !(sel_b1 & sel_b2) |-> (out_always == a)
    );

// out_and is the 4-input AND of a, b, sel_b1, and sel_b2.
    check_out_and_is_four_input_and: assert property (
        @(posedge clk) out_and == (a & b & sel_b1 & sel_b2)
    );

// out_or is the 4-input OR of a, b, sel_b1, and sel_b2.
    check_out_or_is_four_input_or: assert property (
        @(posedge clk) out_or == (a | b | sel_b1 | sel_b2)
    );

// out_xor is the 4-input XOR of a, b, sel_b1, and sel_b2.
    check_out_xor_is_four_input_xor: assert property (
        @(posedge clk) out_xor == (a ^ b ^ sel_b1 ^ sel_b2)
    );

// When control is low, the output must be low.
    check_output_zero_when_control_low: assert property (
        @(posedge clk) (control === 1'b0) |-> (vout === 1'b0)
    );

// When control is high, the output must match the vref LSB.
    check_output_tracks_vref_lsb_when_control_high: assert property (
        @(posedge clk) (control === 1'b1) |-> (vout === vref[0])
    );

// A high output requires control high and vref[0] high.
    check_high_output_requires_enable_and_lsb: assert property (
        @(posedge clk) (vout === 1'b1) |-> ((control === 1'b1) && (vref[0] === 1'b1))
    );

// Reset forces the counter to zero on the following clock sample.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// When below 15 and not in reset, the counter increments by one.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

// When at 15 and not in reset, the counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hF) |=> (count == 4'h0)
    );

// On every non-reset cycle, the counter value changes.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count != $past(count))
    );

// If reset is sampled low, the next sampled state is 5 and the status outputs are low.
    check_reset_state: assert property (
        @(posedge clk) (!reset) |=> ((q == 4'h5) && (carry_out == 1'b0) && (led == 1'b0))
    );

// With load high, q takes load_value on the next cycle unless async reset intervenes.
    check_load_updates_q: assert property (
        @(posedge clk) disable iff (!reset)
        load |=> ((q == $past(load_value)) || (q == 4'h5))
    );

// Without load, q increments by one when it is not at 15 unless async reset intervenes.
    check_increment_nonterminal: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (q != 4'hF)) |=> ((q == ($past(q) + 4'd1)) || (q == 4'h5))
    );

// Without load, q wraps from 15 to 0 unless async reset intervenes.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (q == 4'hF)) |=> ((q == 4'h0) || (q == 4'h5))
    );

// carry_out is high exactly when q is 15.
    check_carry_matches_q: assert property (
        @(posedge clk) disable iff (!reset)
        (carry_out == (q == 4'hF))
    );

// led always mirrors carry_out.
    check_led_matches_carry: assert property (
        @(posedge clk) disable iff (!reset)
        (led == carry_out)
    );

// High inputs produce a high out after two clocks.
    check_out_high_two_cycles_after_inputs_high: assert property (
        @(posedge clk) (a && b) |-> ##2 out
    );

// A low a forces out low after two clocks.
    check_out_low_two_cycles_after_a_low: assert property (
        @(posedge clk) !a |-> ##2 !out
    );

// A low b forces out low after two clocks.
    check_out_low_two_cycles_after_b_low: assert property (
        @(posedge clk) !b |-> ##2 !out
    );

// Clock: clk; reset: rst_n active-low; logic is sequential.
    // VPWR follows enable on the next clocked state update, and VGND is always low.

    // If reset is low, both outputs are low by the next sampled clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !rst_n |=> (VPWR == 1'b0 && VGND == 1'b0)
    );

// Outside reset, the next sampled outputs match the current enable value.
    check_outputs_follow_enable: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> ((VPWR == $past(enable)) && (VGND == 1'b0))
    );

// When enable is high, the next registered outputs are VPWR=1 and VGND=0.
    check_enable_sets_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        enable |=> (VPWR == 1'b1 && VGND == 1'b0)
    );

// When enable is low, the next registered outputs are VPWR=0 and VGND=0.
    check_disable_clears_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        !enable |=> (VPWR == 1'b0 && VGND == 1'b0)
    );

// Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// In up mode, the counter increments when below 15.
    check_increment_in_up_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && up_down && (count != 4'b1111)) |=> (count == ($past(count) + 4'b0001))
    );

// In up mode, the counter wraps from 15 to 0.
    check_wrap_in_up_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && up_down && (count == 4'b1111)) |=> (count == 4'b0000)
    );

// In down mode, the counter decrements when above 0.
    check_decrement_in_down_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !up_down && (count != 4'b0000)) |=> (count == ($past(count) - 4'b0001))
    );

// In down mode, the counter wraps from 0 to 15.
    check_wrap_in_down_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !up_down && (count == 4'b0000)) |=> (count == 4'b1111)
    );

// Addition mode returns the 4-bit sum.
    check_add_sum: assert property (
        @(posedge clk) (Sub == 1'b0) |-> (S == (A + B))
    );

// Subtraction mode returns the 4-bit difference.
    check_sub_diff: assert property (
        @(posedge clk) (Sub == 1'b1) |-> (S == (A - B))
    );

// Subtraction mode uses A>=B as the Cout flag.
    check_sub_cout_no_borrow: assert property (
        @(posedge clk) (Sub == 1'b1) |-> (Cout == (A >= B))
    );

// Equal operands subtract to zero with Cout asserted.
    check_sub_equal_zero: assert property (
        @(posedge clk) (Sub == 1'b1 && A == B) |-> (S == 4'b0000 && Cout == 1'b1)
    );

// Adding zero passes A through and keeps Cout low.
    check_add_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b0 && B == 4'b0000) |-> (S == A && Cout == 1'b0)
    );

// Subtracting zero passes A through and asserts Cout.
    check_sub_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b1 && B == 4'b0000) |-> (S == A && Cout == 1'b1)
    );

// 0x0 - 0x1 wraps to 0xF with Cout deasserted.
    check_sub_underflow_wrap: assert property (
        @(posedge clk) (Sub == 1'b1 && A == 4'h0 && B == 4'h1) |-> (S == 4'hF && Cout == 1'b0)
    );

// Y equals the implemented 4-input NOR.
    check_y_matches_nor_logic: assert property (
        @(posedge clk) Y == ~(A | B | C_N | D_N)
    );

// All-low inputs drive Y high.
    check_all_inputs_low_set_y_high: assert property (
        @(posedge clk) (!A && !B && !C_N && !D_N) |-> (Y == 1'b1)
    );

// A high drives Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> (Y == 1'b0)
    );

// B high drives Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> (Y == 1'b0)
    );

// C_N high drives Y low.
    check_cn_high_forces_y_low: assert property (
        @(posedge clk) C_N |-> (Y == 1'b0)
    );

// D_N high drives Y low.
    check_dn_high_forces_y_low: assert property (
        @(posedge clk) D_N |-> (Y == 1'b0)
    );

// Y high requires all inputs low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C_N && !D_N)
    );

// Y low requires at least one input high.
    check_y_low_implies_some_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C_N || D_N)
    );

// sel=000 routes data0 to out.
    check_sel_000_routes_data0: assert property (
        @(posedge clk) (sel == 3'b000) |-> (out == data0)
    );

// sel=001 routes data1 to out.
    check_sel_001_routes_data1: assert property (
        @(posedge clk) (sel == 3'b001) |-> (out == data1)
    );

// sel=010 routes data2 to out.
    check_sel_010_routes_data2: assert property (
        @(posedge clk) (sel == 3'b010) |-> (out == data2)
    );

// sel=011 routes data3 to out.
    check_sel_011_routes_data3: assert property (
        @(posedge clk) (sel == 3'b011) |-> (out == data3)
    );

// sel=100 routes data4 to out.
    check_sel_100_routes_data4: assert property (
        @(posedge clk) (sel == 3'b100) |-> (out == data4)
    );

// sel=101 routes data5 to out.
    check_sel_101_routes_data5: assert property (
        @(posedge clk) (sel == 3'b101) |-> (out == data5)
    );

// sel=110 drives the zero-extended reduction-AND result.
    check_sel_110_routes_and_result: assert property (
        @(posedge clk) (sel == 3'b110) |-> (out == {3'b000, &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]}})
    );

// sel=111 drives the same zero-extended reduction-AND result.
    check_sel_111_routes_and_result: assert property (
        @(posedge clk) (sel == 3'b111) |-> (out == {3'b000, &{data5[1:0], data4[1:0], data3[1:0], data2[1:0], data1[1:0], data0[1:0]}})
    );

// Select 00 routes input_signals[0] to the output.
    check_select_00_routes_input0: assert property (
        @(posedge clk)
        (select_signals === 2'b00) |-> (output_signal === input_signals[0])
    );

// Select 01 routes input_signals[1] to the output.
    check_select_01_routes_input1: assert property (
        @(posedge clk)
        (select_signals === 2'b01) |-> (output_signal === input_signals[1])
    );

// Select 10 routes input_signals[2] to the output.
    check_select_10_routes_input2: assert property (
        @(posedge clk)
        (select_signals === 2'b10) |-> (output_signal === input_signals[2])
    );

// Select 11 routes input_signals[3] to the output.
    check_select_11_routes_input3: assert property (
        @(posedge clk)
        (select_signals === 2'b11) |-> (output_signal === input_signals[3])
    );

// H is selected when the top-level select is asserted.
    check_select_h: assert property (
        @(posedge clk)
        SH_i |-> (Y_o == H_i)
    );

// G is selected when SH_i is low and SG_i is high.
    check_select_g: assert property (
        @(posedge clk)
        (!SH_i && SG_i) |-> (Y_o == G_i)
    );

// F is selected when higher-priority selects are low and SF_i is high.
    check_select_f: assert property (
        @(posedge clk)
        (!SH_i && !SG_i && SF_i) |-> (Y_o == F_i)
    );

// E is selected when higher-priority selects are low and SE_i is high.
    check_select_e: assert property (
        @(posedge clk)
        (!SH_i && !SG_i && !SF_i && SE_i) |-> (Y_o == E_i)
    );

// D is selected when higher-priority selects are low and SD_i is high.
    check_select_d: assert property (
        @(posedge clk)
        (!SH_i && !SG_i && !SF_i && !SE_i && SD_i) |-> (Y_o == D_i)
    );

// C is selected when higher-priority selects are low and SC_i is high.
    check_select_c: assert property (
        @(posedge clk)
        (!SH_i && !SG_i && !SF_i && !SE_i && !SD_i && SC_i) |-> (Y_o == C_i)
    );

// B is selected when only the lowest-level select is asserted.
    check_select_b: assert property (
        @(posedge clk)
        (!SH_i && !SG_i && !SF_i && !SE_i && !SD_i && !SC_i && SAB_i) |-> (Y_o == B_i)
    );

// A is selected when all select inputs are deasserted.
    check_select_a: assert property (
        @(posedge clk)
        (!SH_i && !SG_i && !SF_i && !SE_i && !SD_i && !SC_i && !SAB_i) |-> (Y_o == A_i)
    );

// The low output bit is always driven low.
    check_out_lsb_zero: assert property (
        @(posedge clk) out[0] == 1'b0
    );

// sel=00 routes in0 to the high output bit.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == {in0, 1'b0})
    );

// sel=01 routes in1 to the high output bit.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == {in1, 1'b0})
    );

// sel=10 routes in2 to the high output bit.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == {in2, 1'b0})
    );

// sel=11 routes in3 to the high output bit.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == {in3, 1'b0})
    );

// X must implement the OR of the two AND terms.
    check_output_equation: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

// If A1 and A2 are both high, X must be high.
    check_a_term_drives_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// If B1 and B2 are both high, X must be high.
    check_b_term_drives_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If neither AND term is active, X must be low.
    check_no_active_term_drives_low: assert property (
        @(posedge clk) !((A1 & A2) | (B1 & B2)) |-> !X
    );

// If A1 and B1 are both low, both product terms are blocked and X must be low.
    check_a1_b1_low_forces_low: assert property (
        @(posedge clk) (!A1 && !B1) |-> !X
    );

// If A2 and B2 are both low, both product terms are blocked and X must be low.
    check_a2_b2_low_forces_low: assert property (
        @(posedge clk) (!A2 && !B2) |-> !X
    );

// ENCLK is low at each rising-edge sample.
    check_enclk_low_on_posedge: assert property (
        @(posedge CLK)
        (ENCLK === 1'b0)
    );

// Output matches the implemented conditional expression.
    check_absolute_value_function: assert property (
        @(posedge clk) out == ((in < 32'sd0) ? -in : in)
    );

// Non-negative inputs pass through unchanged.
    check_nonnegative_passthrough: assert property (
        @(posedge clk) (in >= 32'sd0) |-> (out == in)
    );

// Negative inputs produce the two's-complement negation.
    check_negative_negation: assert property (
        @(posedge clk) (in < 32'sd0) |-> (out == -in)
    );

// Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 32'sd0) |-> (out == 32'sd0)
    );

// The most-negative input remains unchanged after negation overflow.
    check_min_negative_corner_case: assert property (
        @(posedge clk) (in == 32'sh80000000) |-> (out == 32'sh80000000)
    );

// Negative inputs other than the minimum value yield non-negative outputs.
    check_negative_nonmin_yields_nonnegative: assert property (
        @(posedge clk) ((in < 32'sd0) && (in != 32'sh80000000)) |-> (out >= 32'sd0)
    );

// Input 000 drives only bit 0 low.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b11111110)
    );

// Input 001 drives only bit 1 low.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b11111101)
    );

// Input 010 drives only bit 2 low.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b11111011)
    );

// Input 011 drives only bit 3 low.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b11110111)
    );

// Input 100 drives only bit 4 low.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b11101111)
    );

// Input 101 drives only bit 5 low.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b11011111)
    );

// Input 110 drives only bit 6 low.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b10111111)
    );

// Input 111 drives only bit 7 low.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b01111111)
    );

// Known inputs produce an active-low one-hot output.
    check_active_low_onehot: assert property (
        @(posedge clk) !$isunknown(in) |-> $onehot(~out)
    );

// Unknown input bits select the default all-high output.
    check_default_unknown_input: assert property (
        @(posedge clk) $isunknown(in) |-> (out == 8'b11111111)
    );

// data_out_1 mirrors the low two bits of data_in.
    check_data_out_1_slice: assert property (
        @(posedge clk) data_out_1 == data_in[1:0]
    );

// data_out_2 mirrors the high two bits of data_in.
    check_data_out_2_slice: assert property (
        @(posedge clk) data_out_2 == data_in[3:2]
    );

// parity is the reduction XOR of data_in.
    check_parity_from_input: assert property (
        @(posedge clk) parity == (^data_in)
    );

// The two output fields reconstruct the full input bus.
    check_outputs_reconstruct_input: assert property (
        @(posedge clk) {data_out_2, data_out_1} == data_in
    );

// parity matches the XOR of the split output fields.
    check_parity_from_outputs: assert property (
        @(posedge clk) parity == (^({data_out_2, data_out_1}))
    );

// Output always matches the RTL's conditional function.
    check_absolute_value_function: assert property (
        @(posedge clk)
        abs_value == ((input_num < 0) ? (~input_num + 8'd1) : input_num)
    );

// Non-negative inputs pass through unchanged.
    check_non_negative_passthrough: assert property (
        @(posedge clk)
        (input_num >= 0) |-> (abs_value == input_num)
    );

// Negative inputs produce the two's-complement magnitude.
    check_negative_twos_complement: assert property (
        @(posedge clk)
        (input_num < 0) |-> (abs_value == (~input_num + 8'd1))
    );

// Zero maps to zero.
    check_zero_case: assert property (
        @(posedge clk)
        (input_num == 8'sd0) |-> (abs_value == 8'd0)
    );

// Negative one maps to one.
    check_negative_one_case: assert property (
        @(posedge clk)
        (input_num == -8'sd1) |-> (abs_value == 8'd1)
    );

// The most-negative input wraps to 8'h80 in 8-bit two's complement.
    check_min_negative_case: assert property (
        @(posedge clk)
        (input_num == 8'sh80) |-> (abs_value == 8'h80)
    );

// Reset forces the register output to zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |-> (Q == 4'b0000)
    );

// A load captures D into Q on the next clock.
    check_load_captures_d: assert property (
        @(posedge CLK) disable iff (RST) LD |=> (Q == $past(D))
    );

// With load deasserted, Q holds its previous value.
    check_hold_when_ld_low: assert property (
        @(posedge CLK) disable iff (RST) !LD |=> $stable(Q)
    );

// Loading a new value causes Q to change to that value.
    check_load_new_value_changes_q: assert property (
        @(posedge CLK) disable iff (RST) (LD && (D != Q)) |=> ((Q == $past(D)) && !$stable(Q))
    );

// Loading the current value leaves Q unchanged.
    check_load_same_value_keeps_q_stable: assert property (
        @(posedge CLK) disable iff (RST) (LD && (D == Q)) |=> $stable(Q)
    );

// After reset release, Q stays zero if no load is requested.
    check_reset_release_keeps_zero_without_load: assert property (
        @(posedge CLK) RST ##1 (!RST && !LD) |-> (Q == 4'b0000)
    );

// Combined output must equal the 4-bit addition with carry in.
    check_total_addition: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout, sum} == add5_fn(a, b, cin)
    );

// Bit 0 sum matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry rippled from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[1] == (a[1] ^ b[1] ^ c1_fn(a, b, cin))
    );

// Bit 2 sum uses the carry rippled from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[2] == (a[2] ^ b[2] ^ c2_fn(a, b, cin))
    );

// Bit 3 sum uses the carry rippled from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[3] == (a[3] ^ b[3] ^ c3_fn(a, b, cin))
    );

// Carry out matches the final ripple carry.
    check_carry_out: assert property (
        @(posedge clk) disable iff (1'b0)
        cout == c4_fn(a, b, cin)
    );

// Carry out must be low when the total is below 16.
    check_no_overflow_range: assert property (
        @(posedge clk) disable iff (1'b0)
        (add5_fn(a, b, cin) < 5'd16) |-> !cout
    );

// Carry out must be high when the total is 16 or more.
    check_overflow_range: assert property (
        @(posedge clk) disable iff (1'b0)
        (add5_fn(a, b, cin) >= 5'd16) |-> cout
    );

// Adding zero with no carry-in passes a through unchanged.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (b == 4'b0000 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero with no carry-in passes b through unchanged.
    check_a_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (a == 4'b0000 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// POUT must implement the NOR of PIN1 and PIN2.
    check_pout_equation: assert property (
        @(posedge PHI) POUT == ~(PIN1 | PIN2)
    );

// GOUT must implement the inverted AND of GIN2 with (PIN2 | GIN1).
    check_gout_equation: assert property (
        @(posedge PHI) GOUT == ~(GIN2 & (PIN2 | GIN1))
    );

// If either PIN input is high, POUT must be low.
    check_pout_low_when_any_pin_high: assert property (
        @(posedge PHI) ((PIN1 == 1'b1) || (PIN2 == 1'b1)) |-> (POUT == 1'b0)
    );

// If both PIN inputs are low, POUT must be high.
    check_pout_high_when_both_pins_low: assert property (
        @(posedge PHI) ((PIN1 == 1'b0) && (PIN2 == 1'b0)) |-> (POUT == 1'b1)
    );

// If GIN2 is low, GOUT must be high.
    check_gout_high_when_gin2_low: assert property (
        @(posedge PHI) (GIN2 == 1'b0) |-> (GOUT == 1'b1)
    );

// If both PIN2 and GIN1 are low, GOUT must be high.
    check_gout_high_when_or_term_low: assert property (
        @(posedge PHI) ((PIN2 == 1'b0) && (GIN1 == 1'b0)) |-> (GOUT == 1'b1)
    );

// If GIN2 and PIN2 are high, GOUT must be low.
    check_gout_low_when_gin2_and_pin2_high: assert property (
        @(posedge PHI) ((GIN2 == 1'b1) && (PIN2 == 1'b1)) |-> (GOUT == 1'b0)
    );

// If GIN2 and GIN1 are high, GOUT must be low.
    check_gout_low_when_gin2_and_gin1_high: assert property (
        @(posedge PHI) ((GIN2 == 1'b1) && (GIN1 == 1'b1)) |-> (GOUT == 1'b0)
    );

// Output must match the AND of both inputs.
    check_and_function: assert property (
        @(posedge clk) y == (a & b)
    );

// If input a is low, the output must be low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !a |-> !y
    );

// If input b is low, the output must be low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !b |-> !y
    );

// If both inputs are high, the output must be high.
    check_both_high_drives_y_high: assert property (
        @(posedge clk) (a && b) |-> y
    );

// A high output requires both inputs to be high.
    check_y_high_implies_both_high: assert property (
        @(posedge clk) y |-> (a && b)
    );

// SHIFT=00 selects DIN[0], DIN[0], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_00: assert property (
        @(posedge clk)
        (SHIFT == 2'b00) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[0], DIN[0], DIN[3], DIN[2]}} + cin))
    );

// SHIFT=01 selects DIN[0], DIN[1], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_01: assert property (
        @(posedge clk)
        (SHIFT == 2'b01) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[0], DIN[1], DIN[3], DIN[2]}} + cin))
    );

// SHIFT=10 selects DIN[1], DIN[0], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_10: assert property (
        @(posedge clk)
        (SHIFT == 2'b10) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[1], DIN[0], DIN[3], DIN[2]}} + cin))
    );

// SHIFT=11 selects DIN[1], DIN[1], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_11: assert property (
        @(posedge clk)
        (SHIFT == 2'b11) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[1], DIN[1], DIN[3], DIN[2]}} + cin))
    );

// sum is DOUT plus b plus cin, truncated to 4 bits.
    check_sum_from_dout_b_cin: assert property (
        @(posedge clk)
        ({1'b0, sum} == (({1'b0, DOUT} + {1'b0, b} + cin) & 5'h0f))
    );

// With b and cin both zero, sum matches DOUT.
    check_sum_equals_dout_when_b_and_cin_zero: assert property (
        @(posedge clk)
        ((b == 4'h0) && (cin == 1'b0)) |-> (sum == DOUT)
    );

// X must match the RTL mux and gating function.
    check_output_matches_rtl_function: assert property (
        @(posedge clk)
        X == (
            (
                ((S1 == 1'b0) && (S0 == 1'b0)) ? A0 :
                ((S1 == 1'b0) && (S0 == 1'b1)) ? A1 :
                ((S1 == 1'b1) && (S0 == 1'b0)) ? A2 :
                A3
            ) &
            ((VGND == 1'b0) ? 1'b0 : VPWR) &
            ((VPB  == 1'b0) ? 1'b0 : VNB)
        )
    );

// Select 00 routes A0 through the power gating.
    check_select_00_uses_a0: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b0)) |->
        (X == (A0 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// Select 01 routes A1 through the power gating.
    check_select_01_uses_a1: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b1)) |->
        (X == (A1 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// Select 10 routes A2 through the power gating.
    check_select_10_uses_a2: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b0)) |->
        (X == (A2 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// Select 11 routes A3 through the power gating.
    check_select_11_uses_a3: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b1)) |->
        (X == (A3 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// VGND low forces the output low.
    check_vgnd_low_forces_x_low: assert property (
        @(posedge clk)
        (VGND == 1'b0) |-> (X == 1'b0)
    );

// VPB low forces the output low.
    check_vpb_low_forces_x_low: assert property (
        @(posedge clk)
        (VPB == 1'b0) |-> (X == 1'b0)
    );

// With VGND high, low VPWR blocks the output.
    check_vpwr_low_blocks_x: assert property (
        @(posedge clk)
        ((VGND == 1'b1) && (VPWR == 1'b0)) |-> (X == 1'b0)
    );

// With VPB high, low VNB blocks the output.
    check_vnb_low_blocks_x: assert property (
        @(posedge clk)
        ((VPB == 1'b1) && (VNB == 1'b0)) |-> (X == 1'b0)
    );

// With all power controls high, X reduces to a plain 4:1 mux.
    check_fully_enabled_path_behaves_as_mux: assert property (
        @(posedge clk)
        ((VGND == 1'b1) && (VPB == 1'b1) && (VPWR == 1'b1) && (VNB == 1'b1)) |->
        (
            X == (
                ((S1 == 1'b0) && (S0 == 1'b0)) ? A0 :
                ((S1 == 1'b0) && (S0 == 1'b1)) ? A1 :
                ((S1 == 1'b1) && (S0 == 1'b0)) ? A2 :
                A3
            )
        )
    );

// Out is the previous cycle's input incremented by one.
    check_registered_increment: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(in) + 32'sd1))
    );

// Zero increments to one on the next clock.
    check_zero_to_one: assert property (
        @(posedge clk) (in == 32'sd0) |=> (out == 32'sd1)
    );

// Minus one increments to zero on the next clock.
    check_minus_one_to_zero: assert property (
        @(posedge clk) (in == -32'sd1) |=> (out == 32'sd0)
    );

// Maximum positive value wraps to minimum negative on the next clock.
    check_positive_overflow_wrap: assert property (
        @(posedge clk) (in == 32'sh7fffffff) |=> (out == 32'sh80000000)
    );

// Minimum negative value increments to the next signed value.
    check_negative_min_to_next: assert property (
        @(posedge clk) (in == 32'sh80000000) |=> (out == 32'sh80000001)
    );

// Output matches the XOR tree implemented in the RTL.
    check_output_matches_xor_tree: assert property (
        @(posedge clk)
        output_signal == ((input_signals[0] ^ input_signals[1]) ^ (input_signals[2] ^ input_signals[3]))
    );

// Output is the parity of all four input bits.
    check_output_matches_reduction_xor: assert property (
        @(posedge clk)
        output_signal == ^input_signals
    );

// If the lower pair XOR is 0, the output equals the upper pair XOR.
    check_lower_pair_equal_passes_upper_pair: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == 1'b0) |-> (output_signal == (input_signals[2] ^ input_signals[3]))
    );

// If the lower pair XOR is 1, the output is the inverse of the upper pair XOR.
    check_lower_pair_diff_flips_upper_pair: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == 1'b1) |-> (output_signal == ~(input_signals[2] ^ input_signals[3]))
    );

// If the upper pair XOR is 0, the output equals the lower pair XOR.
    check_upper_pair_equal_passes_lower_pair: assert property (
        @(posedge clk)
        ((input_signals[2] ^ input_signals[3]) == 1'b0) |-> (output_signal == (input_signals[0] ^ input_signals[1]))
    );

// If the upper pair XOR is 1, the output is the inverse of the lower pair XOR.
    check_upper_pair_diff_flips_lower_pair: assert property (
        @(posedge clk)
        ((input_signals[2] ^ input_signals[3]) == 1'b1) |-> (output_signal == ~(input_signals[0] ^ input_signals[1]))
    );

// Equal pair parities force the output low.
    check_matching_pair_parities_drive_zero: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == (input_signals[2] ^ input_signals[3])) |-> (output_signal == 1'b0)
    );

// Different pair parities force the output high.
    check_different_pair_parities_drive_one: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) != (input_signals[2] ^ input_signals[3])) |-> (output_signal == 1'b1)
    );

// Reset forces the register output low.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !rst |-> (data_out == 4'b0000)
    );

// Load alone captures data_in on the next clock.
    check_load_captures_data_in: assert property (
        @(posedge clk) disable iff (!rst)
        (load && !shift) |=> (data_out == $past(data_in))
    );

// Load has priority when load and shift are both asserted.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (!rst)
        (load && shift) |=> (data_out == $past(data_in))
    );

// Shift alone moves the register left and inserts zero.
    check_shift_left_with_zero_fill: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && shift) |=> (data_out == {$past(data_out[2:0]), 1'b0})
    );

// With no load or shift, the register holds its value.
    check_idle_holds_value: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && !shift) |=> (data_out == $past(data_out))
    );

// Bit 0 sum follows the first full-adder equation.
    check_sum_bit0_equation: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 2 sum uses the carry generated by bits 0 and 1.
    check_sum_bit2_ripple: assert property (
        @(posedge clk)
        S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                    & (A[1] ^ B[1])
                )
            )
        )
    );

// Bit 3 sum uses the carry generated by bits 0 through 2.
    check_sum_bit3_ripple: assert property (
        @(posedge clk)
        S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (
                        (A[1] & B[1]) |
                        (
                            ((A[0] & B[0]) | (Cin & (A[0] ^ B[0])))
                            & (A[1] ^ B[1])
                        )
                    )
                    & (A[2] ^ B[2])
                )
            )
        )
    );

// data_out must always match the DUT's combinational function.
    check_bitwise_and_function: assert property (
        @(posedge clk) data_out == (enable ? (data_in & mask) : data_in)
    );

// When disabled, data_out must pass data_in through unchanged.
    check_bypass_when_disabled: assert property (
        @(posedge clk) !enable |-> (data_out == data_in)
    );

// When enabled, data_out must equal data_in masked by mask.
    check_mask_when_enabled: assert property (
        @(posedge clk) enable |-> (data_out == (data_in & mask))
    );

// With a zero mask and enable high, all output bits must be zero.
    check_zero_mask_clears_output: assert property (
        @(posedge clk) enable && (mask == 16'h0000) |-> (data_out == 16'h0000)
    );

// With an all-ones mask and enable high, data_out must equal data_in.
    check_full_mask_passes_input: assert property (
        @(posedge clk) enable && (mask == 16'hFFFF) |-> (data_out == data_in)
    );

// When enabled, data_out cannot assert bits that are masked off.
    check_mask_blocks_cleared_bits: assert property (
        @(posedge clk) enable |-> ((data_out & ~mask) == 16'h0000)
    );

// ctrl=000 selects the 8-bit sum.
    check_ctrl_sum: assert property (
        @(posedge clk) (ctrl == 3'b000) |-> (z == (a + b))
    );

// ctrl=001 selects the 8-bit difference.
    check_ctrl_difference: assert property (
        @(posedge clk) (ctrl == 3'b001) |-> (z == (a - b))
    );

// ctrl=101 selects bitwise AND.
    check_ctrl_and: assert property (
        @(posedge clk) (ctrl == 3'b101) |-> (z == (a & b))
    );

// ctrl=110 selects bitwise OR.
    check_ctrl_or: assert property (
        @(posedge clk) (ctrl == 3'b110) |-> (z == (a | b))
    );

// ctrl=111 selects bitwise XOR.
    check_ctrl_xor: assert property (
        @(posedge clk) (ctrl == 3'b111) |-> (z == (a ^ b))
    );

// Full result must equal A plus B plus carry-in.
    check_full_add_result: assert property (
        @(posedge clk) {Cout, Sum} == (A + B + Cin)
    );

// Sum bit 0 must match the low-bit full-adder parity.
    check_lsb_sum_bit: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Adding zero with no carry-in must pass A through.
    check_a_passthrough: assert property (
        @(posedge clk) ((B == 4'h0) && (Cin == 1'b0)) |-> ({Cout, Sum} == {1'b0, A})
    );

// Adding zero with no carry-in must pass B through.
    check_b_passthrough: assert property (
        @(posedge clk) ((A == 4'h0) && (Cin == 1'b0)) |-> ({Cout, Sum} == {1'b0, B})
    );

// Zero inputs with zero carry-in must produce zero output.
    check_zero_result: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0) && (Cin == 1'b0)) |-> ({Cout, Sum} == 5'h0)
    );

// All-ones inputs with carry-in must produce the maximum 5-bit sum.
    check_max_result: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b1)) |-> ({Cout, Sum} == 5'h1F)
    );

// sum must equal the 4-bit addition of a and b.
    check_sum_matches_4bit_add: assert property (
        @(posedge clk) sum == (a + b)
    );

// When the mathematical sum is 15 or less, sum matches it exactly.
    check_sum_no_wrap: assert property (
        @(posedge clk) (({1'b0, a} + {1'b0, b}) <= 5'd15) |-> (sum == ({1'b0, a} + {1'b0, b}))
    );

// When the mathematical sum exceeds 15, sum wraps modulo 16.
    check_sum_wraps_mod_16: assert property (
        @(posedge clk) (({1'b0, a} + {1'b0, b}) >= 5'd16) |-> (sum == (({1'b0, a} + {1'b0, b}) - 5'd16))
    );

// Adding zero on a leaves b unchanged at the output.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (a == 4'd0) |-> (sum == b)
    );

// Adding zero on b leaves a unchanged at the output.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (b == 4'd0) |-> (sum == a)
    );

// Y must equal the AND of all inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & B1 & B2 & C1 & VPWR & VGND)
    );

// All inputs high must drive Y high.
    check_all_high_drives_y_high: assert property (
        @(posedge clk) (A1 & A2 & B1 & B2 & C1 & VPWR & VGND) |-> Y
    );

// Y high requires every input to be high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A1 & A2 & B1 & B2 & C1 & VPWR & VGND)
    );

// A1 low must force Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A2 low must force Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// B1 low must force Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// B2 low must force Y low.
    check_b2_low_forces_y_low: assert property (
        @(posedge clk) !B2 |-> !Y
    );

// C1 low must force Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// VPWR low must force Y low.
    check_vpwr_low_forces_y_low: assert property (
        @(posedge clk) !VPWR |-> !Y
    );

// VGND low must force Y low.
    check_vgnd_low_forces_y_low: assert property (
        @(posedge clk) !VGND |-> !Y
    );

// A low input drives a high output.
    check_input_low_drives_output_high: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A high input drives a low output.
    check_input_high_drives_output_low: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// The sampled output matches the inversion of the sampled input.
    check_output_matches_inversion: assert property (
        @(posedge clk) ((A === 1'b0) || (A === 1'b1)) |-> (Y === ~A)
    );

// Combined output must equal the 5-bit sum of A, B, and Cin.
    check_full_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Sum[0] must implement the least-significant full-adder sum bit.
    check_sum_bit0: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum[1] must use the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) Sum[1] == (A[1] ^ B[1] ^ carry_bit(A[0], B[0], Cin))
    );

// Sum[2] must use the carry propagated through bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) Sum[2] == (A[2] ^ B[2] ^ carry_bit(A[1], B[1], carry_bit(A[0], B[0], Cin)))
    );

// Sum[3] must use the carry propagated through bits 0 to 2.
    check_sum_bit3: assert property (
        @(posedge clk) Sum[3] == (A[3] ^ B[3] ^ carry_bit(A[2], B[2], carry_bit(A[1], B[1], carry_bit(A[0], B[0], Cin))))
    );

// Cout must be the final carry out of the most-significant bit.
    check_cout: assert property (
        @(posedge clk) Cout == carry_bit(A[3], B[3], carry_bit(A[2], B[2], carry_bit(A[1], B[1], carry_bit(A[0], B[0], Cin))))
    );

// Y must match the implemented NAND-AND logic function.
    check_y_matches_logic: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == (~(A1 & A2) & ~(B1 & B2) & ~(C1 & C2))
    );

// A high-high condition on the A pair forces Y low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & A2) |-> ~Y
    );

// A high-high condition on the B pair forces Y low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (B1 & B2) |-> ~Y
    );

// A high-high condition on the C pair forces Y low.
    check_c_pair_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (C1 & C2) |-> ~Y
    );

// If no input pair is simultaneously high, Y must be high.
    check_no_pair_active_gives_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (~(A1 & A2) & ~(B1 & B2) & ~(C1 & C2)) |-> Y
    );

// A high Y implies none of the three input pairs are simultaneously high.
    check_y_high_implies_no_active_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |-> (~(A1 & A2) & ~(B1 & B2) & ~(C1 & C2))
    );

// A low Y implies at least one input pair is simultaneously high.
    check_y_low_implies_some_active_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        ~Y |-> ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// Full output equals the 5-bit sum of the inputs.
    check_full_sum: assert property (
        @(posedge clk) {C, S} == ({1'b0, A} + {1'b0, B})
    );

// Low sum bits match the low nibble of the addition result.
    check_sum_low_bits: assert property (
        @(posedge clk) {1'b0, S} == (({1'b0, A} + {1'b0, B}) & 5'h0F)
    );

// Carry is high exactly when the sum reaches 16 or more.
    check_carry_matches_overflow: assert property (
        @(posedge clk) C == (({1'b0, A} + {1'b0, B}) >= 5'd16)
    );

// The least significant sum bit is the XOR of input LSBs.
    check_lsb_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

// Adding zero on A passes B through with no carry.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'd0) |-> ({C, S} == {1'b0, B})
    );

// Adding zero on B passes A through with no carry.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'd0) |-> ({C, S} == {1'b0, A})
    );

// The maximum input pair produces decimal 30.
    check_max_plus_max: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF)) |-> ({C, S} == 5'h1E)
    );

// Fifteen plus one produces the carry boundary value 16.
    check_carry_boundary: assert property (
        @(posedge clk) (((A == 4'hF) && (B == 4'h1)) || ((A == 4'h1) && (B == 4'hF))) |-> ({C, S} == 5'h10)
    );

// Ones nibble is a legal BCD digit.
check_ones_digit_valid: assert property (
    @(posedge clk) bcdout[3:0] <= 4'd9
);

// Tens nibble is a legal BCD digit.
check_tens_digit_valid: assert property (
    @(posedge clk) bcdout[7:4] <= 4'd9
);

// Hundreds nibble is a legal BCD digit.
check_hundreds_digit_valid: assert property (
    @(posedge clk) bcdout[11:8] <= 4'd9
);

// Thousands nibble is a legal BCD digit.
check_thousands_digit_valid: assert property (
    @(posedge clk) bcdout[15:12] <= 4'd9
);

// Ten-thousands nibble is a legal BCD digit.
check_ten_thousands_digit_valid: assert property (
    @(posedge clk) bcdout[19:16] <= 4'd9
);

// Single-digit inputs only use the ones nibble.
check_single_digit_mapping: assert property (
    @(posedge clk) (B <= 16'd9) |-> (bcdout == {16'd0, B[3:0]})
);

// Values below 100 keep the upper three BCD digits at zero.
check_two_digit_upper_digits_zero: assert property (
    @(posedge clk) (B < 16'd100) |-> (bcdout[19:8] == 12'd0)
);

// Values below 1000 keep the upper two BCD digits at zero.
check_three_digit_upper_digits_zero: assert property (
    @(posedge clk) (B < 16'd1000) |-> (bcdout[19:12] == 8'd0)
);

// Values below 10000 keep the ten-thousands digit at zero.
check_four_digit_top_digit_zero: assert property (
    @(posedge clk) (B < 16'd10000) |-> (bcdout[19:16] == 4'd0)
);

// Maximum input maps to 65535 in packed BCD.
check_max_input_mapping: assert property (
    @(posedge clk) (B == 16'd65535) |-> (bcdout == {4'd6, 4'd5, 4'd5, 4'd3, 4'd5})
);

// Status is the constant RP_ID value with zeroed upper bits.
    check_status_constant: assert property (
        @(posedge clk) status == {24'h0, RP_ID}
    );

// Destination enable is the registered copy of source enable from the prior cycle.
    check_enable_pipeline: assert property (
        @(posedge clk) 1'b1 |=> (dst_adc_enable == $past(src_adc_enable))
    );

// Destination valid is the registered copy of source valid from the prior cycle.
    check_valid_pipeline: assert property (
        @(posedge clk) 1'b1 |=> (dst_adc_valid == $past(src_adc_valid))
    );

// Destination data is the registered copy of source data from the prior cycle.
    check_data_pipeline: assert property (
        @(posedge clk) 1'b1 |=> (dst_adc_data == $past(src_adc_data))
    );

// SUM is the bitwise XOR of A and B.
    check_sum_matches_bitwise_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// Equal operands force all SUM bits low.
    check_equal_operands_force_zero_sum: assert property (
        @(posedge clk) (A == B) |-> (SUM == 4'b0000)
    );

// Complementary operands force all SUM bits high and propagate CI to COUT.
    check_complementary_operands_propagate_carry: assert property (
        @(posedge clk) (A == ~B) |-> ((SUM == 4'b1111) && (COUT == CI))
    );

// Zero operands clear both SUM and COUT.
    check_zero_operands_clear_outputs: assert property (
        @(posedge clk) (A == 4'b0000 && B == 4'b0000) |-> ((SUM == 4'b0000) && (COUT == 1'b0))
    );

// All-one operands force zero SUM and a asserted carry-out.
    check_all_ones_operands_generate_carry: assert property (
        @(posedge clk) (A == 4'b1111 && B == 4'b1111) |-> ((SUM == 4'b0000) && (COUT == 1'b1))
    );

// Stage 0 captures the current inputs.
    check_stage0_captures_inputs: assert property (
        @(posedge clk)
        (stage === 3'd0) |=> (stage === 3'd1 && A_reg === $past(A) && B_reg === $past(B))
    );

// Stage 0 does not change the outputs.
    check_stage0_holds_outputs: assert property (
        @(posedge clk)
        (stage === 3'd0) |=> (EQ === $past(EQ) && GT === $past(GT))
    );

// Stage 1 advances and keeps the captured operands stable.
    check_stage1_advances_and_holds_operands: assert property (
        @(posedge clk)
        (stage === 3'd1) |=> (stage === 3'd2 && A_reg === $past(A_reg) && B_reg === $past(B_reg))
    );

// Equal captured operands set EQ and clear GT.
    check_stage1_equal_result: assert property (
        @(posedge clk)
        (stage === 3'd1 && ((A_reg == B_reg) === 1'b1))
        |=> (stage === 3'd2 && EQ === 1'b1 && GT === 1'b0)
    );

// Greater captured operands clear EQ and set GT.
    check_stage1_greater_result: assert property (
        @(posedge clk)
        (stage === 3'd1 && ((A_reg == B_reg) !== 1'b1) && ((A_reg > B_reg) === 1'b1))
        |=> (stage === 3'd2 && EQ === 1'b0 && GT === 1'b1)
    );

// The stage 1 else path clears both outputs.
    check_stage1_else_result: assert property (
        @(posedge clk)
        (stage === 3'd1 && ((A_reg == B_reg) !== 1'b1) && ((A_reg > B_reg) !== 1'b1))
        |=> (stage === 3'd2 && EQ === 1'b0 && GT === 1'b0)
    );

// Stage 2 clears the outputs and returns to stage 0.
    check_stage2_clears_outputs_and_wraps: assert property (
        @(posedge clk)
        (stage === 3'd2) |=> (stage === 3'd0 && EQ === 1'b0 && GT === 1'b0 &&
                              A_reg === $past(A_reg) && B_reg === $past(B_reg))
    );

// Unhandled stage values leave all state unchanged.
    check_invalid_stage_holds_state: assert property (
        @(posedge clk)
        (stage !== 3'd0 && stage !== 3'd1 && stage !== 3'd2)
        |=> (stage === $past(stage) && A_reg === $past(A_reg) && B_reg === $past(B_reg) &&
             EQ === $past(EQ) && GT === $past(GT))
    );

// dst_tbm is the OR of all enabled trigger sources.
    check_dst_tbm_selection: assert property (
        @(posedge clk) disable iff (reset)
        dst_tbm == (({5{sel_async}}  & src_async)  |
                    ({5{sel_sync}}   & src_sync)   |
                    ({5{sel_single}} & src_single) |
                    ({5{sel_gen}}    & src_gen)    |
                    ({5{sel_pg}}     & src_pg))
    );

// dst_sync_direct only passes src_sync_direct when chaining is enabled.
    check_dst_sync_direct_chain: assert property (
        @(posedge clk) disable iff (reset)
        dst_sync_direct == (sel_chain & src_sync_direct)
    );

// dst_sync is gated by sel_sync_out and blocked by sel_chain.
    check_dst_sync_selection: assert property (
        @(posedge clk) disable iff (reset)
        dst_sync == ({5{sel_sync_out & !sel_chain}} & dst_tbm)
    );

// dst_tbm_pos is src_async_pos gated by sel_async and src_async[1].
    check_dst_tbm_pos_gate: assert property (
        @(posedge clk) disable iff (reset)
        dst_tbm_pos == (src_async_pos & {4{sel_async & src_async[1]}})
    );

// dst_dir is the OR of all enabled direct sources.
    check_dst_dir_selection: assert property (
        @(posedge clk) disable iff (reset)
        dst_dir == (({5{sel_dir_async}}  & src_async)  |
                    ({5{sel_dir_sync}}   & src_sync)   |
                    ({5{sel_dir_single}} & src_single) |
                    ({5{sel_dir_gen}}    & src_gen)    |
                    ({5{sel_dir_pg}}     & src_pg))
    );

// Chaining forces dst_sync low.
    check_chain_blocks_dst_sync: assert property (
        @(posedge clk) disable iff (reset)
        sel_chain |-> (dst_sync == 5'b0)
    );

// With sync output enabled and no chain, dst_sync matches dst_tbm.
    check_enabled_sync_out_copies_tbm: assert property (
        @(posedge clk) disable iff (reset)
        (sel_sync_out && !sel_chain) |-> (dst_sync == dst_tbm)
    );

// With sync output disabled, dst_sync is zero.
    check_disabled_sync_out_clears_dst_sync: assert property (
        @(posedge clk) disable iff (reset)
        !sel_sync_out |-> (dst_sync == 5'b0)
    );

// If no main source is selected, dst_tbm is zero.
    check_no_main_selects_clear_dst_tbm: assert property (
        @(posedge clk) disable iff (reset)
        !(sel_async || sel_sync || sel_single || sel_gen || sel_pg) |-> (dst_tbm == 5'b0)
    );

// If no direct source is selected, dst_dir is zero.
    check_no_dir_selects_clear_dst_dir: assert property (
        @(posedge clk) disable iff (reset)
        !(sel_dir_async || sel_dir_sync || sel_dir_single || sel_dir_gen || sel_dir_pg) |-> (dst_dir == 5'b0)
    );

// Reset or squash clears q.
    check_clear_on_reset_or_squash: assert property (
        @(posedge clk) (!resetn || !squashn) |=> (q == 32'h00000000)
    );

// Reset has priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (!resetn && en) |=> (q == 32'h00000000)
    );

// Squash has priority over enable.
    check_squash_priority_over_enable: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn && en) |=> (q == 32'h00000000)
    );

// Enable loads d when reset and squash are inactive.
    check_load_when_enabled: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && en) |=> (q == $past(d))
    );

// q holds its value when enable is low and no clear is active.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && !en) |=> $stable(q)
    );

// Reset clears the register on the next sampled cycle.
    check_reset_clears_reg: assert property (
        @(posedge clk) reset |=> (reg_out == 8'h00)
    );

// Reset has priority over write enable.
    check_reset_priority_over_write: assert property (
        @(posedge clk) (reset && wenb) |=> (reg_out == 8'h00)
    );

// A write captures in_data into reg_out.
    check_write_updates_reg: assert property (
        @(posedge clk) disable iff (reset)
        wenb |=> (reg_out == $past(in_data))
    );

// Without a write, the register holds its previous value.
    check_hold_without_write: assert property (
        @(posedge clk) disable iff (reset)
        !wenb |=> (reg_out == $past(reg_out))
    );

// O matches the implemented XOR of the two selected branches.
    check_output_equation: assert property (
        @(posedge clk)
        O == ((((~S) & I0) | (S & I1)) ^ (((~S) & I2) | (S & I3)))
    );

// With S low, O is the XOR of I0 and I2.
    check_select_low_function: assert property (
        @(posedge clk)
        (S == 1'b0) |-> (O == (I0 ^ I2))
    );

// With S high, O is the XOR of I1 and I3.
    check_select_high_function: assert property (
        @(posedge clk)
        (S == 1'b1) |-> (O == (I1 ^ I3))
    );

// With S low, equal selected inputs drive O low.
    check_select_low_equal_inputs_zero: assert property (
        @(posedge clk)
        ((S == 1'b0) && (I0 == I2)) |-> (O == 1'b0)
    );

// With S low, different selected inputs drive O high.
    check_select_low_different_inputs_one: assert property (
        @(posedge clk)
        ((S == 1'b0) && (I0 != I2)) |-> (O == 1'b1)
    );

// With S high, equal selected inputs drive O low.
    check_select_high_equal_inputs_zero: assert property (
        @(posedge clk)
        ((S == 1'b1) && (I1 == I3)) |-> (O == 1'b0)
    );

// With S high, different selected inputs drive O high.
    check_select_high_different_inputs_one: assert property (
        @(posedge clk)
        ((S == 1'b1) && (I1 != I3)) |-> (O == 1'b1)
    );

// Input 0 decodes to bit 0.
    check_decode_0: assert property (
        @(posedge clk) (input_bits == 4'b0000) |-> (output_bits == 16'b0000000000000001)
    );

// Input 1 decodes to bit 1.
    check_decode_1: assert property (
        @(posedge clk) (input_bits == 4'b0001) |-> (output_bits == 16'b0000000000000010)
    );

// Input 2 decodes to bit 2.
    check_decode_2: assert property (
        @(posedge clk) (input_bits == 4'b0010) |-> (output_bits == 16'b0000000000000100)
    );

// Input 3 decodes to bit 3.
    check_decode_3: assert property (
        @(posedge clk) (input_bits == 4'b0011) |-> (output_bits == 16'b0000000000001000)
    );

// Input 4 decodes to bit 4.
    check_decode_4: assert property (
        @(posedge clk) (input_bits == 4'b0100) |-> (output_bits == 16'b0000000000010000)
    );

// Input 5 decodes to bit 5.
    check_decode_5: assert property (
        @(posedge clk) (input_bits == 4'b0101) |-> (output_bits == 16'b0000000000100000)
    );

// Input 6 decodes to bit 6.
    check_decode_6: assert property (
        @(posedge clk) (input_bits == 4'b0110) |-> (output_bits == 16'b0000000001000000)
    );

// Input 7 decodes to bit 7.
    check_decode_7: assert property (
        @(posedge clk) (input_bits == 4'b0111) |-> (output_bits == 16'b0000000010000000)
    );

// Input 8 decodes to bit 8.
    check_decode_8: assert property (
        @(posedge clk) (input_bits == 4'b1000) |-> (output_bits == 16'b0000000100000000)
    );

// Input 9 decodes to bit 9.
    check_decode_9: assert property (
        @(posedge clk) (input_bits == 4'b1001) |-> (output_bits == 16'b0000001000000000)
    );

// Input 10 decodes to bit 10.
    check_decode_10: assert property (
        @(posedge clk) (input_bits == 4'b1010) |-> (output_bits == 16'b0000010000000000)
    );

// Input 11 decodes to bit 11.
    check_decode_11: assert property (
        @(posedge clk) (input_bits == 4'b1011) |-> (output_bits == 16'b0000100000000000)
    );

// Input 12 decodes to bit 12.
    check_decode_12: assert property (
        @(posedge clk) (input_bits == 4'b1100) |-> (output_bits == 16'b0001000000000000)
    );

// Input 13 decodes to bit 13.
    check_decode_13: assert property (
        @(posedge clk) (input_bits == 4'b1101) |-> (output_bits == 16'b0010000000000000)
    );

// Input 14 decodes to bit 14.
    check_decode_14: assert property (
        @(posedge clk) (input_bits == 4'b1110) |-> (output_bits == 16'b0100000000000000)
    );

// Input 15 decodes to bit 15.
    check_decode_15: assert property (
        @(posedge clk) (input_bits == 4'b1111) |-> (output_bits == 16'b1000000000000000)
    );

// X must equal the 4-input AND of A, B, C, and D.
    check_x_matches_and4: assert property (
        @(posedge clk) X === (A & B & C & D)
    );

// If all inputs are high, X must be high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk)
        ((A === 1'b1) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1)) |-> (X === 1'b1)
    );

// If any input is low, X must be low.
    check_any_low_input_drives_x_low: assert property (
        @(posedge clk)
        ((A === 1'b0) || (B === 1'b0) || (C === 1'b0) || (D === 1'b0)) |-> (X === 1'b0)
    );

// A high X requires all inputs to be high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk)
        (X === 1'b1) |-> ((A === 1'b1) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1))
    );

// The 5-bit output value matches unsigned addition of A and B.
    check_total_sum: assert property (
        @(posedge clk)
        {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

// Carry-out is asserted exactly when the 4-bit addition overflows.
    check_carry_out_matches_overflow: assert property (
        @(posedge clk)
        C_out == (({1'b0, A} + {1'b0, B}) >= 5'h10)
    );

// Bit 0 sum is the XOR of the least-significant input bits.
    check_lsb_sum: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0])
    );

// Bit 1 sum includes the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

// Bit 2 sum includes the ripple carry from the lower two bits.
    check_bit2_sum: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & (A[0] & B[0])) |
                  (B[1] & (A[0] & B[0]))))
    );

// Zero on A passes B through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk)
        (A == 4'h0) |-> ({C_out, S} == {1'b0, B})
    );

// Zero on B passes A through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk)
        (B == 4'h0) |-> ({C_out, S} == {1'b0, A})
    );

// Two operands with clear MSBs cannot produce an overflow carry.
    check_no_overflow_small_operands: assert property (
        @(posedge clk)
        (!A[3] && !B[3]) |-> (C_out == 1'b0)
    );

// q matches d from three sampled clock edges earlier.
    check_q_matches_delayed_d: assert property (
        @(posedge clk) 1'b1 |=> ##2 (q == $past(d,3))
    );

// A sampled reset drives the outputs to the reset state by the next clock.
    check_reset_state: assert property (
        @(posedge CLK) RESET |=> (Q == 1'b0 && Q_N == 1'b1)
    );

// Without reset, Q captures D on the next clock.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q == $past(D))
    );

// Without reset, Q_N captures the inverse of D on the next clock.
    check_qn_captures_inverse_d: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q_N == ~$past(D))
    );

// Outside reset, the two outputs remain logical complements.
    check_outputs_are_complements: assert property (
        @(posedge CLK) disable iff (RESET) (Q_N == ~Q)
    );

// F matches the implemented truth table for all sampled inputs.
    check_function_matches_truth_table: assert property (
        @(posedge clk) F == (B ^ C ^ D)
    );

// When BCD is 000, F must be low.
    check_bcd_000_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b000) |-> (F == 1'b0)
    );

// When BCD is 001, F must be high.
    check_bcd_001_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b001) |-> (F == 1'b1)
    );

// When BCD is 010, F must be high.
    check_bcd_010_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b010) |-> (F == 1'b1)
    );

// When BCD is 011, F must be low.
    check_bcd_011_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b011) |-> (F == 1'b0)
    );

// When BCD is 100, F must be high.
    check_bcd_100_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b100) |-> (F == 1'b1)
    );

// When BCD is 101, F must be low.
    check_bcd_101_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b101) |-> (F == 1'b0)
    );

// When BCD is 110, F must be low.
    check_bcd_110_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b110) |-> (F == 1'b0)
    );

// When BCD is 111, F must be high.
    check_bcd_111_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b111) |-> (F == 1'b1)
    );

// Output must be the AND of A and SLEEP_B.
    check_output_function: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// Low SLEEP_B must force X low.
    check_sleep_low_forces_zero: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When enabled, X must match A.
    check_enabled_output_follows_input: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// A high X requires both A and SLEEP_B high.
    check_output_high_requires_enable_and_input: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// A low input must force X low.
    check_low_input_forces_zero: assert property (
        @(posedge clk) !A |-> !X
    );

// Bit 2 sum uses the carry propagated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carry3(A[1], B[1], carry3(A[0], B[0], Cin)))
    );

// Bit 3 sum uses the carry propagated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Cin))))
    );

// The maximum input case produces all ones across Cout and S.
    check_full_overflow_case: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b1)) |-> ({Cout, S} == 5'h1F)
    );

// A sampled low reset clears the counter by the next clock.
    check_reset_clears_counter: assert property (
        @(posedge clk) (!rst) |=> (out == 4'b0000)
    );

// With enable low, the counter holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst) (!en) |=> (out == $past(out))
    );

// With enable high below 4'hF, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) (en && (out != 4'hF)) |=> (out == ($past(out) + 4'd1))
    );

// With enable high at 4'hF, the counter wraps to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (!rst) (en && (out == 4'hF)) |=> (out == 4'h0)
    );

// An enabled cycle always changes the counter value.
    check_change_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) en |=> (out != $past(out))
    );

// Active-high reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'd0)
    );

// From 0, the counter increments to 1.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd0) |=> (count == 3'd1)
    );

// From 1, the counter increments to 2.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd1) |=> (count == 3'd2)
    );

// From 2, the counter increments to 3.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd2) |=> (count == 3'd3)
    );

// From 3, the counter increments to 4.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd3) |=> (count == 3'd4)
    );

// From 4, the counter increments to 5.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd4) |=> (count == 3'd5)
    );

// From 5, the counter increments to 6.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd5) |=> (count == 3'd6)
    );

// From 6, the counter increments to 7.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd6) |=> (count == 3'd7)
    );

// From 7, the counter wraps back to 0.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (reset) (count == 3'd7) |=> (count == 3'd0)
    );

// Each active cycle updates count by one in the selected direction.
    check_next_state_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count == ($past(control) ? ($past(count) + 4'd1) : ($past(count) - 4'd1)))
    );

// control high causes an increment on the next clock.
    check_increment: assert property (
        @(posedge clk) disable iff (reset)
        control |=> (count == ($past(count) + 4'd1))
    );

// control low causes a decrement on the next clock.
    check_decrement: assert property (
        @(posedge clk) disable iff (reset)
        !control |=> (count == ($past(count) - 4'd1))
    );

// Incrementing from 4'hF wraps back to zero.
    check_increment_wrap: assert property (
        @(posedge clk) disable iff (reset)
        control && (count == 4'hF) |=> (count == 4'h0)
    );

// Decrementing from zero wraps to 4'hF.
    check_decrement_wrap: assert property (
        @(posedge clk) disable iff (reset)
        !control && (count == 4'h0) |=> (count == 4'hF)
    );

// SUM is the three-input XOR of A, B, and CI.
    check_sum_parity: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT_N is the inverted carry-out from the three inputs.
    check_coutn_function: assert property (
        @(posedge clk) COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

// The outputs encode a full-adder result with active-low carry.
    check_full_adder_encoding: assert property (
        @(posedge clk) ({1'b0, A} + {1'b0, B} + {1'b0, CI}) == {~COUT_N, SUM}
    );

// All-zero inputs produce zero sum and deasserted carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && COUT_N)
    );

// Any single high input produces sum one and deasserted carry.
    check_one_high_case: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI)) |-> (SUM && COUT_N)
    );

// Any two high inputs produce sum zero and asserted carry.
    check_two_high_case: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI)) |-> (!SUM && !COUT_N)
    );

// All-one inputs produce sum one and asserted carry.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && !COUT_N)
    );

// outv is a direct pass-through of in_vec.
    check_outv_passthrough: assert property (
        @(posedge clk) outv == in_vec
    );

// complement matches the RTL's selected complement function.
    check_complement_exact_function: assert property (
        @(posedge clk) complement == ((sel_comp == 1'b1) ? (~in_vec + 4'b0001) : ~in_vec)
    );

// sel_comp low selects ones' complement.
    check_ones_complement_when_not_selected: assert property (
        @(posedge clk) (sel_comp == 1'b0) |-> (complement == ~in_vec)
    );

// sel_comp high selects twos' complement.
    check_twos_complement_when_selected: assert property (
        @(posedge clk) (sel_comp == 1'b1) |-> (complement == (~in_vec + 4'b0001))
    );

// Ones' complement output is the bitwise inverse of the input.
    check_ones_complement_inverse_relation: assert property (
        @(posedge clk) (sel_comp == 1'b0) |-> ((complement ^ in_vec) == 4'hF)
    );

// Twos' complement output adds with the input to zero modulo 16.
    check_twos_complement_additive_inverse: assert property (
        @(posedge clk) (sel_comp == 1'b1) |-> ((complement + in_vec) == 4'b0000)
    );

// Reset drives the machine to IDLE.
    check_reset_idle: assert property (
        @(posedge clk)
        !rst_ |-> (state_r == IDLE)
    );

// IDLE advances to SEND on the next clock.
    check_idle_to_send: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == IDLE) |=> (state_r == SEND)
    );

// SEND advances to WAIT1 on the next clock.
    check_send_to_wait1: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == SEND) |=> (state_r == WAIT1)
    );

// WAIT1 advances to UPDATE1 on the next clock.
    check_wait1_to_update1: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == WAIT1) |=> (state_r == UPDATE1)
    );

// UPDATE1 advances to WAIT2 on the next clock.
    check_update1_to_wait2: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == UPDATE1) |=> (state_r == WAIT2)
    );

// WAIT2 advances to UPDATE2 on the next clock.
    check_wait2_to_update2: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == WAIT2) |=> (state_r == UPDATE2)
    );

// UPDATE2 wraps back to IDLE on the next clock.
    check_update2_to_idle: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == UPDATE2) |=> (state_r == IDLE)
    );

// Any invalid state encoding returns to IDLE on the next clock.
    check_invalid_state_to_idle: assert property (
        @(posedge clk) disable iff (!rst_)
        !((state_r == IDLE) || (state_r == SEND) || (state_r == WAIT1) ||
          (state_r == UPDATE1) || (state_r == WAIT2) || (state_r == UPDATE2))
        |=> (state_r == IDLE)
    );

// After any non-reset cycle, the next state is always a legal encoding.
    check_next_state_is_legal: assert property (
        @(posedge clk) disable iff (!rst_)
        1'b1 |=> ((state_r == IDLE) || (state_r == SEND) || (state_r == WAIT1) ||
                  (state_r == UPDATE1) || (state_r == WAIT2) || (state_r == UPDATE2))
    );

// A load cycle captures DATA into Q by the next sampled clock.
    check_load_captures_data: assert property (
        @(posedge CLK) LOAD |=> (Q == $past(DATA))
    );

// A non-load cycle shifts Q left and inserts 0 into bit 0.
    check_shift_behavior: assert property (
        @(posedge CLK) !LOAD |=> (Q == {$past(Q[2:0]), 1'b0})
    );

// A non-load cycle always drives the next LSB low.
    check_shift_inserts_zero: assert property (
        @(posedge CLK) !LOAD |=> (Q[0] == 1'b0)
    );

// A non-load cycle moves the prior lower bits into the upper bits.
    check_shift_moves_bits: assert property (
        @(posedge CLK) !LOAD |=> (Q[3:1] == $past(Q[2:0]))
    );

// Four consecutive shift cycles clear the register.
    check_four_shifts_clear_register: assert property (
        @(posedge CLK) ((!LOAD)[*4]) |=> (Q == 4'b0000)
    );

// Y must implement the full combinational function.
    check_output_function: assert property (
        @(posedge clk) Y == ((~(A | B)) & C & D)
    );

// If either NOR input is high, the output must be low.
    check_a_or_b_blocks_output: assert property (
        @(posedge clk) (A || B) |-> !Y
    );

// If C is low, the AND stage must force the output low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) !C |-> !Y
    );

// If D is low, the AND stage must force the output low.
    check_d_low_blocks_output: assert property (
        @(posedge clk) !D |-> !Y
    );

// When A and B are low, Y must match C AND D.
    check_ab_low_reduces_to_cd: assert property (
        @(posedge clk) (!A && !B) |-> (Y == (C && D))
    );

// A high output requires both NOR inputs low and both AND inputs high.
    check_high_output_requires_all_enables: assert property (
        @(posedge clk) Y |-> (!A && !B && C && D)
    );

// Sum[0] matches the bit-0 full-adder equation.
    check_sum_bit0_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum[2] matches the bit-2 ripple-carry equation.
    check_sum_bit2_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[2] == (A[2] ^ B[2] ^
                       ((A[1] & B[1]) |
                        ((A[1] ^ B[1]) &
                         ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))
    );

// Sum[3] matches the bit-3 ripple-carry equation.
    check_sum_bit3_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[3] == (A[3] ^ B[3] ^
                       ((A[2] & B[2]) |
                        ((A[2] ^ B[2]) &
                         ((A[1] & B[1]) |
                          ((A[1] ^ B[1]) &
                           ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))))
    );

// Sampled async clear forces q low by the next clock.
    check_aclr_clears_q: assert property (
        @(posedge clock)
        aclr |=> (q == 3'b000)
    );

// Sync clear forces q low on the following cycle.
    check_sclr_clears_q: assert property (
        @(posedge clock) disable iff (aclr)
        sclr |=> (q == 3'b000)
    );

// Sync clear overrides an enabled count.
    check_sclr_priority_over_count: assert property (
        @(posedge clock) disable iff (aclr)
        sclr && cnt_en |=> (q == 3'b000)
    );

// q increments by one when enabled to count up.
    check_count_up: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && cnt_en && updown |=> (q == ($past(q) + 3'b001))
    );

// q decrements by one when enabled to count down.
    check_count_down: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && cnt_en && !updown |=> (q == ($past(q) - 3'b001))
    );

// q holds its value when no clear or count is requested.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && !cnt_en |=> (q == $past(q))
    );

// Sampled inputs at or below 5 must drive the output high on the next cycle.
    check_low_or_equal_threshold_drives_high: assert property (
        @(posedge clk) (data_in <= 4'd5) |=> (data_out == 1'b1)
    );

// Sampled inputs above 5 must drive the output low on the next cycle.
    check_above_threshold_drives_low: assert property (
        @(posedge clk) (data_in > 4'd5) |=> (data_out == 1'b0)
    );

// The output must match the previous cycle's sampled input compared against 5.
    check_output_matches_previous_input: assert property (
        @(posedge clk) 1'b1 |=> (data_out == (($past(data_in) <= 4'd5) ? 1'b1 : 1'b0))
    );

// The threshold comparison must include the boundary value 5.
    check_boundary_five_is_high: assert property (
        @(posedge clk) (data_in == 4'd5) |=> (data_out == 1'b1)
    );

// The first value above the threshold, 6, must drive the output low.
    check_boundary_six_is_low: assert property (
        @(posedge clk) (data_in == 4'd6) |=> (data_out == 1'b0)
    );

// Y implements the AOI221 combinational equation.
    check_function_equation: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the output low.
    check_c1_forces_output_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force the output low.
    check_a_and_pair_forces_output_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// B1 and B2 high together force the output low.
    check_b_and_pair_forces_output_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// All three NOR inputs low drive the output high.
    check_all_nor_inputs_low_drive_output_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// A high output requires all three NOR inputs to be low.
    check_output_high_requires_all_nor_inputs_low: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 && A2) && !(B1 && B2))
    );

// A low output requires at least one NOR input to be high.
    check_output_low_requires_any_nor_input_high: assert property (
        @(posedge clk) !Y |-> (C1 || (A1 && A2) || (B1 && B2))
    );

// Upper output byte mirrors in_hi.
    check_hi_byte_mapping: assert property (
        @(posedge clk) out[16:9] == in_hi
    );

// Lower output byte mirrors in_lo.
    check_lo_byte_mapping: assert property (
        @(posedge clk) out[8:1] == in_lo
    );

// The upper 16 output bits are the concatenated input bytes.
    check_half_word_concat: assert property (
        @(posedge clk) out[16:1] == {in_hi, in_lo}
    );

// The parity bit matches the reduction XOR of both input bytes.
    check_parity_from_inputs: assert property (
        @(posedge clk) out[0] == ^({in_hi, in_lo})
    );

// The full output is the concatenated half-word with its parity bit.
    check_full_output_encoding: assert property (
        @(posedge clk) out == {in_hi, in_lo, ^({in_hi, in_lo})}
    );

// The parity bit equals the parity of the upper 16 output bits.
    check_parity_consistency: assert property (
        @(posedge clk) out[0] == ^(out[16:1])
    );

// The 17-bit output has even overall parity.
    check_even_output_parity: assert property (
        @(posedge clk) (^out) == 1'b0
    );

// n_limited_reset_o decodes reset_counter <= 1.
    check_limited_reset_decode: assert property (
        @(negedge clock_i) n_limited_reset_o == (reset_counter <= 8'd1)
    );

// n_reset_o decodes reset_counter <= 1 and forced_reset_i.
    check_reset_decode: assert property (
        @(negedge clock_i) n_reset_o == ((reset_counter <= 8'd1) & !forced_reset_i)
    );

// n_reset_o is n_limited_reset_o masked by forced_reset_i.
    check_reset_is_masked_limited_reset: assert property (
        @(negedge clock_i) n_reset_o == (n_limited_reset_o & !forced_reset_i)
    );

// forced_reset_i always drives n_reset_o low.
    check_forced_reset_forces_n_reset_low: assert property (
        @(negedge clock_i) forced_reset_i |-> !n_reset_o
    );

// A nonzero counter increments by one on each falling edge.
    check_counter_increments_while_nonzero: assert property (
        @(negedge clock_i) (reset_counter != 8'd0) |=> (reset_counter == ($past(reset_counter) + 8'd1))
    );

// Once the counter reaches zero, it stays at zero.
    check_counter_holds_at_zero: assert property (
        @(negedge clock_i) (reset_counter == 8'd0) |=> (reset_counter == 8'd0)
    );

// The counter wraps from 8'hFF to 8'h00.
    check_counter_wraps_to_zero: assert property (
        @(negedge clock_i) (reset_counter == 8'hFF) |=> (reset_counter == 8'h00)
    );

// Counts above 1 force both reset outputs low.
    check_midcount_outputs_low: assert property (
        @(negedge clock_i) (reset_counter > 8'd1) |-> (!n_limited_reset_o && !n_reset_o)
    );

// X equals the implemented OR-of-ANDs function.
    check_output_equation: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2) | C1)
    );

// C1 high forces X high.
    check_c1_forces_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together force X high.
    check_a_pair_forces_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high together force X high.
    check_b_pair_forces_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// With no asserted term, X must be low.
    check_no_active_term_means_low: assert property (
        @(posedge clk) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> !X
    );

// A high X must come from C1 or one complete input pair.
    check_high_output_has_valid_cause: assert property (
        @(posedge clk) X |-> (C1 || (A1 & A2) || (B1 & B2))
    );

// A sampled reset drives both outputs low by the next sampled cycle.
  check_reset_clears_outputs: assert property (
    @(posedge clk) reset |=> (count == 4'd0 && overflow == 1'b0)
  );

// A sampled terminal count always rolls the count back to zero.
  check_terminal_count_rolls_to_zero: assert property (
    @(posedge clk) disable iff (reset)
    (count == MAX_COUNT) |=> (count == 4'd0)
  );

// A sampled non-terminal count advances by one, or is driven to zero by reset.
  check_nonterminal_count_progress: assert property (
    @(posedge clk) disable iff (reset)
    (count != MAX_COUNT) |=> ((count == ($past(count) + 4'd1)) || (count == 4'd0))
  );

// A sampled non-terminal count clears overflow on the next cycle.
  check_nonterminal_clears_overflow: assert property (
    @(posedge clk) disable iff (reset)
    (count != MAX_COUNT) |=> (overflow == 1'b0)
  );

// Any observed overflow must come from a terminal count on the prior sampled cycle.
  check_overflow_follows_terminal_count: assert property (
    @(posedge clk) disable iff (reset)
    1'b1 |=> (!overflow || ($past(count) == MAX_COUNT))
  );

// Any observed overflow is accompanied by a zero count.
  check_overflow_implies_zero_count: assert property (
    @(posedge clk) disable iff (reset)
    1'b1 |=> (!overflow || (count == 4'd0))
  );

// mb_reset matches its combinational definition.
    check_mb_reset_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        mb_reset == (mb_debug_sys_rst || ext_reset_in || !dcm_locked)
    );

// Debug reset forces mb_reset high.
    check_mb_reset_on_debug_reset: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        mb_debug_sys_rst |-> mb_reset
    );

// External reset forces mb_reset high.
    check_mb_reset_on_ext_reset: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        ext_reset_in |-> mb_reset
    );

// Loss of dcm lock forces mb_reset high.
    check_mb_reset_on_dcm_unlock: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        !dcm_locked |-> mb_reset
    );

// mb_reset is low when all of its causes are inactive.
    check_mb_reset_clear_condition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        (!mb_debug_sys_rst && !ext_reset_in && dcm_locked) |-> !mb_reset
    );

// bus_struct_reset mirrors ext_reset_in.
    check_bus_struct_reset_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        bus_struct_reset[0] == ext_reset_in
    );

// peripheral_reset mirrors aux_reset_in.
    check_peripheral_reset_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        peripheral_reset[0] == aux_reset_in
    );

// interconnect_aresetn is the inverse of mb_reset.
    check_interconnect_aresetn_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        interconnect_aresetn[0] == !mb_reset
    );

// peripheral_aresetn is low when mb_reset or peripheral_reset is high.
    check_peripheral_aresetn_definition: assert property (
        @(posedge slowest_sync_clk) disable iff (1'b0)
        peripheral_aresetn[0] == !(mb_reset || peripheral_reset[0])
    );

// sel_col matches the 32-pixel horizontal tile index in the draw region.
check_sel_col_decode: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT))
    |-> (sel_col == ((hcounter - LEFT) / TILE_W))
);

// sel_row matches the 16-pixel vertical tile index in the draw region.
check_sel_row_decode: assert property (
    @(posedge clock)
    (vcounter < BOTTOM)
    |-> (sel_row == (vcounter / TILE_H))
);

// out is blank outside the active drawing window.
check_out_zero_outside_window: assert property (
    @(posedge clock)
    (!((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM)))
    |-> (out == 4'b0000)
);

// block 000 always produces blank output in range.
check_block_zero_blank: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b000))
    |-> (out == 4'b0000)
);

// Nonzero narrow blocks draw 8 on the top and bottom of the center strip.
check_narrow_center_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block != 3'b000) && (block[2] == 1'b0) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     (((vcounter % TILE_H) == 11'd0) || ((vcounter % TILE_H) == 11'd15)))
    |-> (out == 4'b1000)
);

// block 001 fills the center strip interior with 1100.
check_narrow_center_fill_block_001: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b001) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1100)
);

// block 010 fills the center strip interior with 1011.
check_narrow_center_fill_block_010: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b010) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1011)
);

// block 011 fills the center strip interior with 1101.
check_narrow_center_fill_block_011: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block == 3'b011) &&
     (((hcounter - LEFT) % TILE_W) > 12'd8) &&
     (((hcounter - LEFT) % TILE_W) < 12'd23) &&
     ((vcounter % TILE_H) != 11'd0) && ((vcounter % TILE_H) != 11'd15))
    |-> (out == 4'b1101)
);

// Nonzero narrow blocks draw 8 on the two center-strip side columns.
check_narrow_side_columns_border: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block != 3'b000) && (block[2] == 1'b0) &&
     ((((hcounter - LEFT) % TILE_W) == 12'd8) ||
      (((hcounter - LEFT) % TILE_W) == 12'd23)))
    |-> (out == 4'b1000)
);

// Narrow blocks other than 011 are blank in the outer columns.
check_narrow_outer_blank_non_011: assert property (
    @(posedge clock)
    ((hcounter >= LEFT) && (hcounter < RIGHT) && (vcounter < BOTTOM) &&
     (block[2] == 1'b0) && (block[1:0] != 2'b11) &&
     ((((hcounter - LEFT) % TILE_W) < 12'd8) ||
      (((hcounter - LEFT) % TILE_W) > 12'd23)))
    |-> (out == 4'b0000)
);

// When VPB is low, X is the 4-input AND of A through D.
    check_and_mode_function: assert property (
        @(posedge clk) (VPB == 1'b0) |-> (X == (A & B & C & D))
    );

// When VPB is high, X is the 4-input OR of A through D.
    check_or_mode_function: assert property (
        @(posedge clk) (VPB == 1'b1) |-> (X == (A | B | C | D))
    );

// In AND mode, all high inputs force X high.
    check_and_mode_all_inputs_high: assert property (
        @(posedge clk) (VPB == 1'b0 && A && B && C && D) |-> (X == 1'b1)
    );

// In OR mode, all low inputs force X low.
    check_or_mode_all_inputs_low: assert property (
        @(posedge clk) (VPB == 1'b1 && !A && !B && !C && !D) |-> (X == 1'b0)
    );

// The widened output is always a sign-extension of the stored value.
    check_output_sign_extension: assert property (
        @(posedge clk) disable iff (reset)
        dout[dout_WIDTH + din0_WIDTH - 1:dout_WIDTH] == {din0_WIDTH{dout[dout_WIDTH - 1]}}
    );

// QN must equal the 3-input NAND of IN1, IN2, and IN3.
    check_nand3_function: assert property (
        @(posedge clk) QN == ~(IN1 & IN2 & IN3)
    );

// When all inputs are high, QN must be low.
    check_all_high_drives_low: assert property (
        @(posedge clk) (IN1 && IN2 && IN3) |-> !QN
    );

// If IN1 is low, QN must be high.
    check_in1_low_drives_high: assert property (
        @(posedge clk) !IN1 |-> QN
    );

// If IN2 is low, QN must be high.
    check_in2_low_drives_high: assert property (
        @(posedge clk) !IN2 |-> QN
    );

// If IN3 is low, QN must be high.
    check_in3_low_drives_high: assert property (
        @(posedge clk) !IN3 |-> QN
    );

// A low QN is only possible when all three inputs are high.
    check_low_output_requires_all_high: assert property (
        @(posedge clk) !QN |-> (IN1 && IN2 && IN3)
    );

// Output must equal the bitwise OR of the inputs.
    check_c_matches_or: assert property (
        @(posedge clk) (c == (a | b))
    );

// Any high bit on a must remain high on c.
    check_a_ones_propagate: assert property (
        @(posedge clk) ((a & ~c) == 8'h00)
    );

// Any high bit on b must remain high on c.
    check_b_ones_propagate: assert property (
        @(posedge clk) ((b & ~c) == 8'h00)
    );

// c must not assert bits that are low on both inputs.
    check_c_has_no_extra_ones: assert property (
        @(posedge clk) ((c & ~(a | b)) == 8'h00)
    );

// Combinational RTL with no reset; sample behavior on clk.

    // The eight 6-bit outputs reconstruct the full XOR result.
    check_full_xor_mapping: assert property (
        @(posedge clk) {b8x, b7x, b6x, b5x, b4x, b3x, b2x, b1x} == (k ^ e)
    );

// b1x carries XOR bits [5:0].
    check_b1x_slice: assert property (
        @(posedge clk) b1x == (k[5:0] ^ e[5:0])
    );

// b2x carries XOR bits [11:6].
    check_b2x_slice: assert property (
        @(posedge clk) b2x == (k[11:6] ^ e[11:6])
    );

// b3x carries XOR bits [17:12].
    check_b3x_slice: assert property (
        @(posedge clk) b3x == (k[17:12] ^ e[17:12])
    );

// b4x carries XOR bits [23:18].
    check_b4x_slice: assert property (
        @(posedge clk) b4x == (k[23:18] ^ e[23:18])
    );

// b5x carries XOR bits [29:24].
    check_b5x_slice: assert property (
        @(posedge clk) b5x == (k[29:24] ^ e[29:24])
    );

// b6x carries XOR bits [35:30].
    check_b6x_slice: assert property (
        @(posedge clk) b6x == (k[35:30] ^ e[35:30])
    );

// b7x carries XOR bits [41:36].
    check_b7x_slice: assert property (
        @(posedge clk) b7x == (k[41:36] ^ e[41:36])
    );

// b8x carries XOR bits [47:42].
    check_b8x_slice: assert property (
        @(posedge clk) b8x == (k[47:42] ^ e[47:42])
    );

// Y matches the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk)
        Y == ((S == 2'b00) ? A :
              (S == 2'b01) ? B :
              (S == 2'b10) ? C :
                             D)
    );

// Select 00 routes A to Y.
    check_select_a: assert property (
        @(posedge clk)
        (S == 2'b00) |-> (Y == A)
    );

// Select 01 routes B to Y.
    check_select_b: assert property (
        @(posedge clk)
        (S == 2'b01) |-> (Y == B)
    );

// Select 10 routes C to Y.
    check_select_c: assert property (
        @(posedge clk)
        (S == 2'b10) |-> (Y == C)
    );

// Select 11 routes D to Y.
    check_select_d: assert property (
        @(posedge clk)
        (S == 2'b11) |-> (Y == D)
    );

// During active-high reset, C is forced to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (C == 4'b0000)
    );

// Outside reset, C matches the bitwise AND of A and B.
    check_and_output_matches_inputs: assert property (
        @(posedge clk) disable iff (reset) (C == (A & B))
    );

// Sampling reset high clears the register by the next clock sample.
    check_reset_clears_data_out: assert property (
        @(posedge clk) reset |=> (data_out == 8'b0)
    );

// With shift high, the next value shifts in a zero at bit 0.
    check_shift_mode_updates_full_register: assert property (
        @(posedge clk) disable iff (reset)
        shift |=> (data_out == { $past(data_out[6:0]), 1'b0 })
    );

// With shift low, the next value shifts in shift_in at bit 0.
    check_load_mode_updates_full_register: assert property (
        @(posedge clk) disable iff (reset)
        !shift |=> (data_out == { $past(data_out[6:0]), $past(shift_in) })
    );

// Upper bits always come from the previous lower bits.
    check_upper_bits_always_shift: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (data_out[7:1] == $past(data_out[6:0]))
    );

// In shift mode, the next LSB is always zero.
    check_shift_mode_inserts_zero: assert property (
        @(posedge clk) disable iff (reset)
        shift |=> (data_out[0] == 1'b0)
    );

// In non-shift mode, the next LSB captures shift_in.
    check_load_mode_captures_shift_in: assert property (
        @(posedge clk) disable iff (reset)
        !shift |=> (data_out[0] == $past(shift_in))
    );

// RTL is combinational; sample its behavior on an external clock.
  // Output must match the RTL expression on every sample.
  check_output_matches_rtl: assert property (
    @(posedge clk)
    out == ((s == 1) ? ((in1[n-1] ^ in2[n-1]) ? in1[n-1] : (in1 > in2)) : (in1 > in2))
  );

// A larger in1 must assert the output.
      check_unsigned_gt_high: assert property (
        @(posedge clk)
        (in1 > in2) |-> out
      );

// A smaller in1 must deassert the output.
      check_unsigned_lt_low: assert property (
        @(posedge clk)
        (in1 < in2) |-> !out
      );

// Equal inputs never assert the output.
      check_unsigned_equal_inputs_low: assert property (
        @(posedge clk)
        (in1 == in2) |-> !out
      );

// After a reset cycle, the counter contribution is cleared.
    check_reset_clears_counter: assert property (
        @(posedge clk)
        rst |=> (out == {4'b0000, ((in < 32'sd0) ? -in : in)})
    );

// The output is always the absolute input plus a 4-bit counter value.
    check_counter_contribution_range: assert property (
        @(posedge clk) disable iff (rst)
        (out >= {4'b0000, ((in < 32'sd0) ? -in : in)}) &&
        ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) <= 36'd15)
    );

// When en is high, the counter increments modulo 16 on the next cycle.
    check_enable_increments_counter: assert property (
        @(posedge clk) disable iff (rst)
        en |=> ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) ==
                (($past(out - {4'b0000, ((in < 32'sd0) ? -in : in)}) + 36'd1) & 36'hF))
    );

// When ld is high and en is low, the next counter value comes from load_data.
    check_load_updates_counter: assert property (
        @(posedge clk) disable iff (rst)
        (!en && ld) |=> (out == ({4'b0000, ((in < 32'sd0) ? -in : in)} + {32'b0, $past(load_data)}))
    );

// When neither en nor ld is high, the counter value holds.
    check_hold_preserves_counter: assert property (
        @(posedge clk) disable iff (rst)
        (!en && !ld) |=> ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) ==
                          $past(out - {4'b0000, ((in < 32'sd0) ? -in : in)}))
    );

// X matches the implemented sum-of-products function.
    check_functional_equivalence: assert property (
        @(posedge clk)
        X == (((~(A1 | A2)) & (~(B1 | B2))) | ((A1 & A2) & (B1 & B2)))
    );

// All four inputs low drives X high.
    check_all_low_sets_x: assert property (
        @(posedge clk)
        ((!A1 && !A2) && (!B1 && !B2)) |-> X
    );

// All four inputs high drives X high.
    check_all_high_sets_x: assert property (
        @(posedge clk)
        ((A1 && A2) && (B1 && B2)) |-> X
    );

// A mixed pair cannot produce X high.
    check_mixed_a_clears_x: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> !X
    );

// B mixed pair cannot produce X high.
    check_mixed_b_clears_x: assert property (
        @(posedge clk)
        (B1 ^ B2) |-> !X
    );

// A low pair with B high pair drives X low.
    check_a_low_b_high_clears_x: assert property (
        @(posedge clk)
        ((!A1 && !A2) && (B1 && B2)) |-> !X
    );

// A high pair with B low pair drives X low.
    check_a_high_b_low_clears_x: assert property (
        @(posedge clk)
        ((A1 && A2) && (!B1 && !B2)) |-> !X
    );

// X can only be high for matching all-low or all-high pairs.
    check_x_high_only_on_matching_extremes: assert property (
        @(posedge clk)
        X |-> (((!A1 && !A2) && (!B1 && !B2)) || ((A1 && A2) && (B1 && B2)))
    );

// Zero must not be flagged as a power of two.
    check_zero_is_not_power_of_two: assert property (
        @(posedge clk) (num == 16'd0) |-> (is_power_of_2 == 1'b0)
    );

// A one-hot input must be flagged as a power of two.
    check_onehot_input_sets_output: assert property (
        @(posedge clk) $onehot(num) |-> (is_power_of_2 == 1'b1)
    );

// A nonzero input with multiple bits set must clear the output.
    check_multibit_input_clears_output: assert property (
        @(posedge clk) ((num != 16'd0) && !$onehot(num)) |-> (is_power_of_2 == 1'b0)
    );

// A high output must only occur for a one-hot input.
    check_high_output_requires_onehot_input: assert property (
        @(posedge clk) (is_power_of_2 == 1'b1) |-> $onehot(num)
    );

// The output must match the RTL power-of-two detection expression.
    check_output_matches_rtl_expression: assert property (
        @(posedge clk) (is_power_of_2 == (((num != 16'd0) && ((num & (num - 16'd1)) == 16'd0)) ? 1'b1 : 1'b0))
    );

// y must always equal 12345 logically right-shifted by a.
    check_shift_result: assert property (
        @(posedge clk) y == (32'd12345 >> a)
    );

// A zero shift must leave the constant unchanged.
    check_shift_by_zero: assert property (
        @(posedge clk) (a == 32'd0) |-> (y == 32'd12345)
    );

// Shift amounts of 14 or more must produce zero.
    check_large_shift_zero: assert property (
        @(posedge clk) (a >= 32'd14) |-> (y == 32'd0)
    );

// Right-shifting 12345 can never set bits above bit 13.
    check_upper_bits_zero: assert property (
        @(posedge clk) y[31:14] == 18'd0
    );

// Combined outputs must match the 5-bit addition of a, b, and cin.
    check_full_add_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Sum must match the lower 4 bits of the addition result.
    check_sum_lower_bits: assert property (
        @(posedge clk) {1'b0, sum} == (({1'b0, a} + {1'b0, b} + cin) & 5'h0F)
    );

// Carry-out must indicate whether the addition result exceeds 4 bits.
    check_carry_overflow: assert property (
        @(posedge clk) cout == (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
    );

// Zero inputs must produce a zero sum and no carry.
    check_zero_addition: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> (sum == 4'h0 && cout == 1'b0)
    );

// Maximum inputs with carry-in must produce 0xF with carry-out asserted.
    check_max_addition: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (sum == 4'hF && cout == 1'b1)
    );

// When en is high just before it falls, out must reflect the live input.
    check_enabled_path_uses_input: assert property (
        @(negedge en) out === in
    );

// Reset forces Q and OVF low.
    check_reset_clears_state: assert property (
        @(posedge clk) !RST |-> ((Q == 4'h0) && (OVF == 1'b0))
    );

// Counting up below 15 increments Q and clears OVF.
    check_count_up_increment: assert property (
        @(posedge clk) disable iff (!RST)
        (UD && (Q != 4'hF)) |=> ((Q == ($past(Q) + 4'h1)) && (OVF == 1'b0))
    );

// Counting up at 15 wraps Q to 0 and sets OVF.
    check_count_up_wrap: assert property (
        @(posedge clk) disable iff (!RST)
        (UD && (Q == 4'hF)) |=> ((Q == 4'h0) && (OVF == 1'b1))
    );

// Counting down above 0 decrements Q and clears OVF.
    check_count_down_decrement: assert property (
        @(posedge clk) disable iff (!RST)
        (!UD && (Q != 4'h0)) |=> ((Q == ($past(Q) - 4'h1)) && (OVF == 1'b0))
    );

// Counting down at 0 wraps Q to 15 and sets OVF.
    check_count_down_wrap: assert property (
        @(posedge clk) disable iff (!RST)
        (!UD && (Q == 4'h0)) |=> ((Q == 4'hF) && (OVF == 1'b1))
    );

// Overflow can only appear with a wrapped boundary value.
    check_ovf_implies_boundary_q: assert property (
        @(posedge clk) disable iff (!RST)
        OVF |-> ((Q == 4'h0) || (Q == 4'hF))
    );

// Midrange counter values must not assert overflow.
    check_midrange_q_has_no_ovf: assert property (
        @(posedge clk) disable iff (!RST)
        ((Q != 4'h0) && (Q != 4'hF)) |-> (OVF == 1'b0)
    );

// The output is a one-cycle delayed copy of dest_out_bin_ff_reg[1].
    check_out_is_one_cycle_delayed_dest_msb: assert property (
        @(posedge aclk) 1'b1 |=> (out == $past(dest_out_bin_ff_reg[1]))
    );

// Reset clears the counter on the next sampled cycle.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 4'b0000)
    );

// Reset takes priority over enable and still clears the counter.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (out == 4'b0000)
    );

// When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        en |=> (out == ($past(out) + 4'd1))
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        !en |=> (out == $past(out))
    );

// Outside reset, the next state is either hold or increment.
    check_only_hold_or_increment: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> ((out == $past(out)) || (out == ($past(out) + 4'd1)))
    );

// Enabling the counter at 4'hF wraps it back to 4'h0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
        (en && (out == 4'hF)) |=> (out == 4'h0)
    );

// A sampled reset must leave the counter at zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Between non-reset samples, count can only advance by one or be cleared to zero.
    check_count_transition_is_increment_or_zero: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> ((count == ($past(count) + 4'd1)) || (count == 4'b0000))
    );

// A sampled maximum count must wrap to zero on the next sample.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (($past(count) != 4'hF) || (count == 4'h0))
    );

// From a sampled zero, the next nonzero value can only be one.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (($past(count) != 4'h0) || (count == 4'h0) || (count == 4'h1))
    );

// out equals a XOR b after the two-cycle pipeline latency.
    check_out_matches_inputs_after_two_cycles: assert property (
        @(posedge clk) 1'b1 |=> ##1 (out == ($past(a, 2) ^ $past(b, 2)))
    );

// Equal inputs produce a low output after the pipeline latency.
    check_equal_inputs_drive_low_after_two_cycles: assert property (
        @(posedge clk) (a == b) |=> ##1 (out == 1'b0)
    );

// Different inputs produce a high output after the pipeline latency.
    check_different_inputs_drive_high_after_two_cycles: assert property (
        @(posedge clk) (a != b) |=> ##1 (out == 1'b1)
    );

// Greater-than inputs encode as 01.
    check_gt_encoding: assert property (
        @(posedge clk)
        (!$isunknown({in_0, in_1}) && (in_0 > in_1)) |-> (out === 2'b01)
    );

// Equal inputs encode as 10.
    check_eq_encoding: assert property (
        @(posedge clk)
        (!$isunknown({in_0, in_1}) && (in_0 == in_1)) |-> (out === 2'b10)
    );

// Less-than inputs encode as 00.
    check_lt_encoding: assert property (
        @(posedge clk)
        (!$isunknown({in_0, in_1}) && (in_0 < in_1)) |-> (out === 2'b00)
    );

// Output is always one of the implemented encodings.
    check_valid_output_code: assert property (
        @(posedge clk)
        (out === 2'b00) || (out === 2'b01) || (out === 2'b10)
    );

// out[0] is asserted only for the greater-than case.
    check_bit0_tracks_gt: assert property (
        @(posedge clk)
        (!$isunknown({in_0, in_1})) |-> (out[0] === (in_0 > in_1))
    );

// out[1] is asserted only for the equal case.
    check_bit1_tracks_eq: assert property (
        @(posedge clk)
        (!$isunknown({in_0, in_1})) |-> (out[1] === (in_0 == in_1))
    );

// s_axi_wready is hardwired high.
    check_wready_constant_high: assert property (
        @(posedge s_aclk) s_axi_wready == 1'b1
    );

// E can only assert when s_axi_wvalid is high.
    check_e_requires_wvalid: assert property (
        @(posedge s_aclk) E[0] |-> s_axi_wvalid
    );

// Without s_axi_wvalid, both observable outputs driven by the full flag stay low.
    check_no_wvalid_forces_outputs_low: assert property (
        @(posedge s_aclk) !s_axi_wvalid |-> (!E[0] && !ram_full_fb_i_reg_0)
    );

// The feedback output is E gated by Q and the read pointer bit.
    check_feedback_output_equation: assert property (
        @(posedge s_aclk) ram_full_fb_i_reg_0 == (E[0] & Q[0] & gnxpm_cdc_rd_pntr_bin_reg_3[0])
    );

// The feedback output can only assert when E is asserted.
    check_feedback_requires_e: assert property (
        @(posedge s_aclk) ram_full_fb_i_reg_0 |-> E[0]
    );

// Loading a 1 into the internal flag makes E track s_axi_wvalid on the next cycle.
    check_load_one_makes_e_track_wvalid: assert property (
        @(posedge s_aclk)
        (out || (!out && gic0_gc0_count_d1_reg_3)) |=> (E[0] == s_axi_wvalid)
    );

// Loading a 1 into the internal flag makes the feedback output track its gates next cycle.
    check_load_one_makes_feedback_track_gates: assert property (
        @(posedge s_aclk)
        (out || (!out && gic0_gc0_count_d1_reg_3)) |=> (ram_full_fb_i_reg_0 == (s_axi_wvalid & Q[0] & gnxpm_cdc_rd_pntr_bin_reg_3[0]))
    );

// Loading a 0 into the internal flag clears both observable outputs on the next cycle.
    check_load_zero_clears_outputs: assert property (
        @(posedge s_aclk)
        (!out && !gic0_gc0_count_d1_reg_3) |=> (!E[0] && !ram_full_fb_i_reg_0)
    );

// No clock or reset exists in the DUT; clk is an external sampling clock.
    // The DUT is purely combinational and implements a 4-input OR.

    // Output must equal the OR of all four inputs.
    check_output_matches_or: assert property (
        @(posedge clk)
        output1 === (input1 | input2 | input3 | input4)
    );

// Any asserted input must drive the output high.
    check_any_high_sets_output: assert property (
        @(posedge clk)
        ((input1 | input2 | input3 | input4) === 1'b1) |-> (output1 === 1'b1)
    );

// All deasserted inputs must drive the output low.
    check_all_low_clears_output: assert property (
        @(posedge clk)
        (input1 === 1'b0 && input2 === 1'b0 && input3 === 1'b0 && input4 === 1'b0) |-> (output1 === 1'b0)
    );

// A high output requires at least one high input.
    check_output_high_implies_input_high: assert property (
        @(posedge clk)
        (output1 === 1'b1) |-> ((input1 | input2 | input3 | input4) === 1'b1)
    );

// A low output requires all inputs to be low.
    check_output_low_implies_all_inputs_low: assert property (
        @(posedge clk)
        (output1 === 1'b0) |-> (input1 === 1'b0 && input2 === 1'b0 && input3 === 1'b0 && input4 === 1'b0)
    );

// Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// In up mode, 15 wraps to 0.
    check_up_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        direction && (count == 4'b1111) |=> (count == 4'b0000)
    );

// In up mode, values below 15 increment by 1.
    check_up_increment: assert property (
        @(posedge clk) disable iff (reset)
        direction && (count != 4'b1111) |=> (count == ($past(count) + 4'd1))
    );

// In down mode, 0 wraps to 15.
    check_down_wrap_from_zero: assert property (
        @(posedge clk) disable iff (reset)
        !direction && (count == 4'b0000) |=> (count == 4'b1111)
    );

// In down mode, values above 0 decrement by 1.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (reset)
        !direction && (count != 4'b0000) |=> (count == ($past(count) - 4'd1))
    );

// Y must always be the bitwise inversion of A.
    check_output_is_inverse: assert property (
        @(posedge clk) (Y === ~A)
    );

// A low input drives Y high.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A high input drives Y low.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// Unknown or high-impedance input produces an unknown output.
    check_unknown_input_produces_unknown_output: assert property (
        @(posedge clk) ((A === 1'bx) || (A === 1'bz)) |-> (Y === 1'bx)
    );

// Adding zero on b with no carry-in leaves a unchanged.
    check_zero_b_identity: assert property (
        @(posedge clk) disable iff (reset)
        (b == 16'h0000 && carry_in == 1'b0) |-> (sum == a && carry_out == 1'b0)
    );

// Adding zero on a with no carry-in leaves b unchanged.
    check_zero_a_identity: assert property (
        @(posedge clk) disable iff (reset)
        (a == 16'h0000 && carry_in == 1'b0) |-> (sum == b && carry_out == 1'b0)
    );

// The least-significant sum bit follows 1-bit full-adder behavior.
    check_lsb_full_adder_relation: assert property (
        @(posedge clk) disable iff (reset)
        sum[0] == (a[0] ^ b[0] ^ carry_in)
    );

// If the low byte does not overflow, the upper byte adds without carry-in.
    check_upper_byte_without_low_carry: assert property (
        @(posedge clk) disable iff (reset)
        (({1'b0, a[7:0]} + {1'b0, b[7:0]} + carry_in) < 9'h100) |->
        ({carry_out, sum[15:8]} == ({1'b0, a[15:8]} + {1'b0, b[15:8]}))
    );

// Reset forces the destination bus low.
    check_reset_clears_dst: assert property (
        @(posedge nvdla_core_clk)
        !nvdla_core_rstn |-> (cacc2glb_done_intr_dst_pd == 2'b00)
    );

// In add mode, the output is the 8-bit sum of a and b.
    check_add_mode_result: assert property (
        @(posedge clk) sel |-> (out == (a + b))
    );

// In subtract mode, the output is the 8-bit difference of a and b.
    check_subtract_mode_result: assert property (
        @(posedge clk) !sel |-> (out == (a - b))
    );

// A select change with stable operands updates output to the newly selected result.
    check_select_change_updates_result: assert property (
        @(posedge clk) ($changed(sel) && $stable(a) && $stable(b)) |-> (out == (sel ? (a + b) : (a - b)))
    );

// Addition wraps around on 8-bit overflow.
    check_add_overflow_wrap: assert property (
        @(posedge clk) (sel && (a == 8'hff) && (b == 8'h01)) |-> (out == 8'h00)
    );

// Subtraction wraps around on 8-bit underflow.
    check_subtract_underflow_wrap: assert property (
        @(posedge clk) (!sel && (a == 8'h00) && (b == 8'h01)) |-> (out == 8'hff)
    );

// A_out[0] is the OR of the two mixed-polarity low-bit terms.
    check_aout0_function: assert property (
        @(posedge clk)
        A_out[0] == ((B_in[0] & (~B_in[1])) | ((~B_in[0]) & B_in[1]))
    );

// A_out[1] is the OR of (~B_in[0] & ~B_in[1]) and ~B_in[2].
    check_aout1_function: assert property (
        @(posedge clk)
        A_out[1] == (((~B_in[0]) & (~B_in[1])) | (~B_in[2]))
    );

// A_out[2] is the OR of B_in[2] and (~B_in[0] & B_in[1]).
    check_aout2_function: assert property (
        @(posedge clk)
        A_out[2] == (B_in[2] | ((~B_in[0]) & B_in[1]))
    );

// The full output vector matches the implemented combinational equations.
    check_aout_vector_function: assert property (
        @(posedge clk)
        A_out == {
            (B_in[2] | ((~B_in[0]) & B_in[1])),
            (((~B_in[0]) & (~B_in[1])) | (~B_in[2])),
            ((B_in[0] & (~B_in[1])) | ((~B_in[0]) & B_in[1]))
        }
    );

// A low B_in[2] forces A_out[1] high through the direct OR term.
    check_b2_low_forces_aout1_high: assert property (
        @(posedge clk)
        (!B_in[2]) |-> A_out[1]
    );

// A high B_in[2] forces A_out[2] high through the direct OR term.
    check_b2_high_forces_aout2_high: assert property (
        @(posedge clk)
        B_in[2] |-> A_out[2]
    );

// Equal low-order input bits clear A_out[0].
    check_equal_low_bits_clear_aout0: assert property (
        @(posedge clk)
        (B_in[0] == B_in[1]) |-> (!A_out[0])
    );

// B_in[0]=0 and B_in[1]=1 drives both the mixed term and A_out[2].
    check_01_low_bits_drive_outputs: assert property (
        @(posedge clk)
        ((!B_in[0]) && B_in[1]) |-> (A_out[0] && A_out[2])
    );

// No reset exists in the RTL; this checker uses an external sampling clock.

    // X must always match the implemented sleep-gated function.
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
        (X == (!SLEEP ? A : 1'b0))
    );

// When SLEEP is high, X is forced low.
    check_sleep_forces_low: assert property (
        @(posedge clk) disable iff (1'b0)
        SLEEP |-> (X == 1'b0)
    );

// When SLEEP is low, X must mirror A.
    check_awake_passes_a: assert property (
        @(posedge clk) disable iff (1'b0)
        (!SLEEP) |-> (X == A)
    );

// A high X can only occur when A is high and SLEEP is low.
    check_high_x_requires_awake_high_a: assert property (
        @(posedge clk) disable iff (1'b0)
        X |-> ((!SLEEP) && A)
    );

// Output must equal the AND of the two inputs.
    check_y_matches_and: assert property (
        @(posedge clk) y == (a & b)
    );

// A high output requires both inputs high.
    check_y_high_requires_both_inputs_high: assert property (
        @(posedge clk) y |-> (a && b)
    );

// Both inputs high must produce a high output.
    check_both_inputs_high_produces_y_high: assert property (
        @(posedge clk) (a && b) |-> y
    );

// A low on input a forces the output low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !a |-> !y
    );

// A low on input b forces the output low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !b |-> !y
    );

// device_out maps probe0 low 16 bits value 0x0001.
    check_device_decode_0001: assert property (
        @(posedge clk) (probe0[15:0] == 16'h0001) |=> (device_out == 16'h0001)
    );

// device_out maps probe0 low 16 bits value 0x0002.
    check_device_decode_0002: assert property (
        @(posedge clk) (probe0[15:0] == 16'h0002) |=> (device_out == 16'h0002)
    );

// device_out maps probe0 low 16 bits value 0x0003.
    check_device_decode_0003: assert property (
        @(posedge clk) (probe0[15:0] == 16'h0003) |=> (device_out == 16'h0003)
    );

// device_out maps probe0 low 16 bits value 0x0004.
    check_device_decode_0004: assert property (
        @(posedge clk) (probe0[15:0] == 16'h0004) |=> (device_out == 16'h0004)
    );

// device_out defaults to 0xFFFF for all other probe0 low 16-bit values.
    check_device_decode_default: assert property (
        @(posedge clk)
        (probe0[15:0] != 16'h0001 &&
         probe0[15:0] != 16'h0002 &&
         probe0[15:0] != 16'h0003 &&
         probe0[15:0] != 16'h0004) |=> (device_out == 16'hFFFF)
    );

// action_out maps probe1 low 48 bits value 0x000000000001.
    check_action_decode_000001: assert property (
        @(posedge clk) (probe1[47:0] == 48'h000000000001) |=> (action_out == 48'h000000000001)
    );

// action_out maps probe1 low 48 bits value 0x000000000002.
    check_action_decode_000002: assert property (
        @(posedge clk) (probe1[47:0] == 48'h000000000002) |=> (action_out == 48'h000000000002)
    );

// action_out maps probe1 low 48 bits value 0x000000000003.
    check_action_decode_000003: assert property (
        @(posedge clk) (probe1[47:0] == 48'h000000000003) |=> (action_out == 48'h000000000003)
    );

// action_out maps probe1 low 48 bits value 0x000000000004.
    check_action_decode_000004: assert property (
        @(posedge clk) (probe1[47:0] == 48'h000000000004) |=> (action_out == 48'h000000000004)
    );

// action_out maps probe1 low 48 bits value 0x000000000005.
    check_action_decode_000005: assert property (
        @(posedge clk) (probe1[47:0] == 48'h000000000005) |=> (action_out == 48'h000000000005)
    );

// action_out maps probe1 low 48 bits value 0x000000000006.
    check_action_decode_000006: assert property (
        @(posedge clk) (probe1[47:0] == 48'h000000000006) |=> (action_out == 48'h000000000006)
    );

// action_out defaults to all ones for all other probe1 low 48-bit values.
    check_action_decode_default: assert property (
        @(posedge clk)
        (probe1[47:0] != 48'h000000000001 &&
         probe1[47:0] != 48'h000000000002 &&
         probe1[47:0] != 48'h000000000003 &&
         probe1[47:0] != 48'h000000000004 &&
         probe1[47:0] != 48'h000000000005 &&
         probe1[47:0] != 48'h000000000006) |=> (action_out == 48'hFFFFFFFFFFFF)
    );

// Y must equal J OR the three 3-input AND terms.
    check_output_equation: assert property (
        @(posedge clk)
        Y == (J | (I & H & G) | (F & E & D) | (C & B & A))
    );

// J asserted must drive Y high.
    check_j_drives_y_high: assert property (
        @(posedge clk)
        J |-> Y
    );

// I, H, and G all high must drive Y high.
    check_ihg_drives_y_high: assert property (
        @(posedge clk)
        (I & H & G) |-> Y
    );

// F, E, and D all high must drive Y high.
    check_fed_drives_y_high: assert property (
        @(posedge clk)
        (F & E & D) |-> Y
    );

// C, B, and A all high must drive Y high.
    check_cba_drives_y_high: assert property (
        @(posedge clk)
        (C & B & A) |-> Y
    );

// Y high must come from J or one of the AND terms.
    check_y_high_has_valid_source: assert property (
        @(posedge clk)
        Y |-> (J | (I & H & G) | (F & E & D) | (C & B & A))
    );

// With all source terms low, Y must be low.
    check_no_source_means_y_low: assert property (
        @(posedge clk)
        !(J | (I & H & G) | (F & E & D) | (C & B & A)) |-> !Y
    );

// Reset forces q low on the following cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 1'b0)
    );

// Reset has priority over set when both are asserted.
    check_reset_priority_over_set: assert property (
        @(posedge clk) (rst && set) |=> (q == 1'b0)
    );

// Set drives q high when reset is not asserted.
    check_set_drives_q_high: assert property (
        @(posedge clk) disable iff (rst) set |=> (q == 1'b1)
    );

// Set overrides d when d is low.
    check_set_priority_over_d: assert property (
        @(posedge clk) disable iff (rst) (set && !d) |=> (q == 1'b1)
    );

// With no reset or set, d=1 is captured into q.
    check_capture_d_high: assert property (
        @(posedge clk) disable iff (rst) (!set && d) |=> (q == 1'b1)
    );

// With no reset or set, d=0 is captured into q.
    check_capture_d_low: assert property (
        @(posedge clk) disable iff (rst) (!set && !d) |=> (q == 1'b0)
    );

// Y must match the RTL combinational equation.
    check_y_matches_rtl_equation: assert property (
        @(posedge clk)
        Y == ((A1 & A2) |
              ((!A1) & (!A2) & B1 & (!C1)) |
              ((!A1) & (!A2) & (!B1) & C1))
    );

// If both A inputs are high, Y must be high.
    check_a_inputs_both_high_set_y: assert property (
        @(posedge clk)
        (A1 && A2) |-> Y
    );

// If A1 and A2 differ, Y must be low.
    check_a_inputs_mismatch_clear_y: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> !Y
    );

// If both A inputs are low, Y must equal B1 XOR C1.
    check_a_inputs_both_low_reduce_to_xor: assert property (
        @(posedge clk)
        ((!A1) && (!A2)) |-> (Y == (B1 ^ C1))
    );

// Bit 2 sum uses the carry from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == sum3(
            A[2],
            B[2],
            carry3(A[1], B[1], carry3(A[0], B[0], Cin))
        )
    );

// Bit 3 sum uses the carry from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == sum3(
            A[3],
            B[3],
            carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Cin)))
        )
    );

// Y matches the implemented OR-of-NOR function.
    check_truth_function: assert property (
        @(posedge clk)
        Y == ((!A1 && !A2 && !A3) || (!B1 && !B2))
    );

// If all A inputs are low, the A-side NOR forces Y high.
    check_all_a_low_sets_y_high: assert property (
        @(posedge clk)
        (!A1 && !A2 && !A3) |-> Y
    );

// If both B inputs are low, the B-side NOR forces Y high.
    check_all_b_low_sets_y_high: assert property (
        @(posedge clk)
        (!B1 && !B2) |-> Y
    );

// If any A input and any B input are high, Y must be low.
    check_a_and_b_activity_sets_y_low: assert property (
        @(posedge clk)
        ((A1 || A2 || A3) && (B1 || B2)) |-> !Y
    );

// A low Y requires at least one asserted A-side input.
    check_y_low_implies_a_activity: assert property (
        @(posedge clk)
        !Y |-> (A1 || A2 || A3)
    );

// A low Y requires at least one asserted B-side input.
    check_y_low_implies_b_activity: assert property (
        @(posedge clk)
        !Y |-> (B1 || B2)
    );

// If Y is high while any A input is high, both B inputs must be low.
    check_y_high_with_a_activity_requires_b_low: assert property (
        @(posedge clk)
        (Y && (A1 || A2 || A3)) |-> (!B1 && !B2)
    );

// If Y is high while any B input is high, all A inputs must be low.
    check_y_high_with_b_activity_requires_a_low: assert property (
        @(posedge clk)
        (Y && (B1 || B2)) |-> (!A1 && !A2 && !A3)
    );

// Reset loads the implemented register and counter values.
    check_reset_loads_state: assert property (
        @(posedge clk) reset |=> (reg1 == 8'h34) && (reg2 == 8'h34) && (counter == 4'h0)
    );

// Reset also produces the expected concatenated result value.
    check_reset_sets_result: assert property (
        @(posedge clk) reset |=> (result == 16'h3434)
    );

// When selected, q_active matches the upper byte of result through reg1.
    check_q_active_matches_result_upper_when_selected: assert property (
        @(posedge clk) disable iff (reset) (select == 1'b1) |-> (q_active == result[15:8])
    );

// input_OUT is the prior-cycle input_IN value.
    check_input_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (input_OUT == $past(input_IN))
    );

// wren_OUT is the prior-cycle wren_IN value.
    check_wren_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (wren_OUT == $past(wren_IN))
    );

// writeAd_OUT is the prior-cycle writeAd_IN value.
    check_writead_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (writeAd_OUT == $past(writeAd_IN))
    );

// ADR_MUX_OUT is the prior-cycle ADR_MUX_IN value.
    check_adr_mux_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (ADR_MUX_OUT == $past(ADR_MUX_IN))
    );

// write_OUT is the prior-cycle write_IN value.
    check_write_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (write_OUT == $past(write_IN))
    );

// PC_load_OUT is the prior-cycle PC_load_IN value.
    check_pc_load_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (PC_load_OUT == $past(PC_load_IN))
    );

// SPR_w_OUT is the prior-cycle SPR_w_IN value.
    check_spr_w_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (SPR_w_OUT == $past(SPR_w_IN))
    );

// SPR_i_OUT is the prior-cycle SPR_i_IN value.
    check_spr_i_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (SPR_i_OUT == $past(SPR_i_IN))
    );

// SPR_d_OUT is the prior-cycle SPR_d_IN value.
    check_spr_d_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (SPR_d_OUT == $past(SPR_d_IN))
    );

// cond_OUT is the prior-cycle cond_IN value.
    check_cond_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (cond_OUT == $past(cond_IN))
    );

// op2_OUT is the prior-cycle op2_IN value.
    check_op2_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (op2_OUT == $past(op2_IN))
    );

// SW_OUT is the prior-cycle SW_IN value.
    check_sw_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (SW_OUT == $past(SW_IN))
    );

// MAD_MUX_OUT is the prior-cycle MAD_MUX_IN value.
    check_mad_mux_out_registered: assert property (
        @(posedge CLK) 1'b1 |=> (MAD_MUX_OUT == $past(MAD_MUX_IN))
    );

// Reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge CLK) RST |=> (count_out == 4'b0000)
    );

// When enabled outside reset, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge CLK) disable iff (RST)
        enable |=> (count_out == ($past(count_out) + 4'b0001))
    );

// When disabled outside reset, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge CLK) disable iff (RST)
        !enable |=> (count_out == $past(count_out))
    );

// Counting from 4'hF wraps the counter to 4'h0.
    check_wraps_after_max: assert property (
        @(posedge CLK) disable iff (RST)
        (enable && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// Reset takes priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge CLK)
        (RST && enable) |=> (count_out == 4'b0000)
    );

// Output vector equals A plus B plus carry-in.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Least significant sum bit matches the first full adder.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 1 sum uses the carry from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (({1'b0, A[0]} + {1'b0, B[0]} + Cin) >= 2'd2))
    );

// Bit 2 sum uses the carry from bits [1:0].
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]} + Cin) >= 3'd4))
    );

// Bit 3 sum uses the carry from bits [2:0].
    check_msb_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]} + Cin) >= 4'd8))
    );

// Carry out is high exactly when the 4-bit addition overflows.
    check_cout_overflow: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

// Adding zero on B with no carry-in passes A through.
    check_add_zero_b: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero on A with no carry-in passes B through.
    check_add_zero_a: assert property (
        @(posedge clk) ((A == 4'b0000) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, B})
    );

// X implements A OR not SLEEP_B.
    check_iso_function: assert property (
        @(posedge clk) X == (A | ~SLEEP_B)
    );

// When awake, X follows A.
    check_transparent_when_awake: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// When sleeping, X is forced high.
    check_clamped_high_when_sleeping: assert property (
        @(posedge clk) !SLEEP_B |-> X
    );

// A high input always forces X high.
    check_high_input_forces_high_output: assert property (
        @(posedge clk) A |-> X
    );

// X can be low only when awake and A is low.
    check_low_output_only_for_awake_low_input: assert property (
        @(posedge clk) !X |-> (SLEEP_B && !A)
    );

// Awake with a low input must produce a low output.
    check_awake_low_input_produces_low_output: assert property (
        @(posedge clk) (SLEEP_B && !A) |-> !X
    );

// Exactly one comparison result flag is asserted.
    check_result_onehot: assert property (
        @(posedge clk)
        (greater || less || equal) &&
        !(greater && less) &&
        !(greater && equal) &&
        !(less && equal)
    );

// Equal is asserted iff the operands are identical.
    check_equal_matches_operands: assert property (
        @(posedge clk)
        equal == (a == b)
    );

// In unsigned mode, outputs match the unsigned comparison.
    check_unsigned_mode_behavior: assert property (
        @(posedge clk)
        unsigned_cmp |-> (
            (greater == (a > b)) &&
            (less == (a < b)) &&
            (equal == (a == b))
        )
    );

// In signed mode, a negative a is less than a non-negative b.
    check_signed_diff_sign_negative_a: assert property (
        @(posedge clk)
        (!unsigned_cmp && (a[31] != b[31]) && a[31]) |-> (!greater && less && !equal)
    );

// In signed mode, a non-negative a is greater than a negative b.
    check_signed_diff_sign_positive_a: assert property (
        @(posedge clk)
        (!unsigned_cmp && (a[31] != b[31]) && !a[31]) |-> (greater && !less && !equal)
    );

// In signed mode with equal sign bits, outputs match the magnitude comparison.
    check_signed_same_sign_behavior: assert property (
        @(posedge clk)
        (!unsigned_cmp && (a[31] == b[31])) |-> (
            (greater == (a > b)) &&
            (less == (a < b)) &&
            (equal == (a == b))
        )
    );

// Sum output matches the XOR of all three inputs.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Cin)
    );

// Carry output matches the implemented carry equation.
    check_carry_function: assert property (
        @(posedge clk) Cout == ((A & B) | ((A ^ B) & Cin))
    );

// All-zero inputs produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !Cin) |-> (!S && !Cout)
    );

// Any single high input produces sum high and carry low.
    check_single_one_case: assert property (
        @(posedge clk)
        ((A && !B && !Cin) || (!A && B && !Cin) || (!A && !B && Cin))
        |-> (S && !Cout)
    );

// Any two high inputs produce sum low and carry high.
    check_two_ones_case: assert property (
        @(posedge clk)
        ((A && B && !Cin) || (A && !B && Cin) || (!A && B && Cin))
        |-> (!S && Cout)
    );

// All-one inputs produce sum high and carry high.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && Cin) |-> (S && Cout)
    );

// With Cin low, the block behaves like a half adder.
    check_half_adder_mode: assert property (
        @(posedge clk) !Cin |-> ((S == (A ^ B)) && (Cout == (A & B)))
    );

// With Cin high, carry reduces to OR of A and B.
    check_cin_high_mode: assert property (
        @(posedge clk) Cin |-> ((S == ~(A ^ B)) && (Cout == (A | B)))
    );

// Reset drives count to zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// Count stays zero while reset remains asserted.
    check_count_held_in_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0)
    );

// Outside reset, count increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Outside reset, the maximum count value wraps to zero.
    check_count_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Sum captures the previous cycle XOR of a and b.
    check_sum_registers_prev_xor: assert property (
        @(posedge clk) 1'b1 |=> (sum == ($past(a) ^ $past(b)))
    );

// Equal inputs produce a zero sum on the next clock.
    check_equal_inputs_produce_zero: assert property (
        @(posedge clk) (a == b) |=> (sum == 2'b00)
    );

// A zero a input passes b through to sum on the next clock.
    check_zero_a_passthrough_b: assert property (
        @(posedge clk) (a == 2'b00) |=> (sum == $past(b))
    );

// A zero b input passes a through to sum on the next clock.
    check_zero_b_passthrough_a: assert property (
        @(posedge clk) (b == 2'b00) |=> (sum == $past(a))
    );

// The decoder only drives zero or a single chip-select bit.
    check_cs_onehot0: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        $onehot0(cs)
    );

// Address 0x63 selects the altavoz chip-select bit.
    check_cs_decode_63: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h63) |-> (cs == 8'b10000000)
    );

// Address 0x64 selects the ultra chip-select bit.
    check_cs_decode_64: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h64) |-> (cs == 8'b01000000)
    );

// Address 0x65 selects the audio chip-select bit.
    check_cs_decode_65: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h65) |-> (cs == 8'b00100000)
    );

// Address 0x66 selects the bt chip-select bit.
    check_cs_decode_66: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h66) |-> (cs == 8'b00010000)
    );

// Address 0x67 selects the mult chip-select bit.
    check_cs_decode_67: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h67) |-> (cs == 8'b00001000)
    );

// Address 0x68 selects the div chip-select bit.
    check_cs_decode_68: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h68) |-> (cs == 8'b00000100)
    );

// Address 0x69 selects the uart chip-select bit.
    check_cs_decode_69: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h69) |-> (cs == 8'b00000010)
    );

// Address 0x70 selects the dp_ram chip-select bit.
    check_cs_decode_70: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (j1_io_addr[15:8] == 8'h70) |-> (cs == 8'b00000001)
    );

// Altavoz select returns audio_dout.
    check_mux_altavoz: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b10000000) |-> (j1_io_din == audio_dout)
    );

// Ultra select returns ultra_dout.
    check_mux_ultra: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b01000000) |-> (j1_io_din == ultra_dout)
    );

// Audio select returns audio_dout.
    check_mux_audio: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b00100000) |-> (j1_io_din == audio_dout)
    );

// BT select returns bt_dout.
    check_mux_bt: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b00010000) |-> (j1_io_din == bt_dout)
    );

// Mult select returns mult_dout.
    check_mux_mult: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b00001000) |-> (j1_io_din == mult_dout)
    );

// Div select returns div_dout.
    check_mux_div: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b00000100) |-> (j1_io_din == div_dout)
    );

// UART select returns uart_dout zero-extended to 16 bits.
    check_mux_uart: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b00000010) |-> (j1_io_din == {15'b0, uart_dout})
    );

// DP RAM select returns dp_ram_dout.
    check_mux_dp_ram: assert property (
        @(posedge sys_clk_i) disable iff (sys_rst_i)
        (cs == 8'b00000001) |-> (j1_io_din == dp_ram_dout)
    );

// y matches the cascaded 4-to-1 mux equation implemented in the RTL.
    check_full_mux_equation: assert property (
        @(posedge clk)
        y === (sel[1] ? (sel[0] ? d : c) : (sel[0] ? b : a))
    );

// When the upper select is low, y comes from the a/b mux path.
    check_sel1_low_uses_ab_path: assert property (
        @(posedge clk)
        (sel[1] === 1'b0) |-> (y === (sel[0] ? b : a))
    );

// When the upper select is high, y comes from the c/d mux path.
    check_sel1_high_uses_cd_path: assert property (
        @(posedge clk)
        (sel[1] === 1'b1) |-> (y === (sel[0] ? d : c))
    );

// sel=00 routes input a to y.
    check_sel_00_routes_a: assert property (
        @(posedge clk)
        (sel === 2'b00) |-> (y === a)
    );

// sel=01 routes input b to y.
    check_sel_01_routes_b: assert property (
        @(posedge clk)
        (sel === 2'b01) |-> (y === b)
    );

// sel=10 routes input c to y.
    check_sel_10_routes_c: assert property (
        @(posedge clk)
        (sel === 2'b10) |-> (y === c)
    );

// sel=11 routes input d to y.
    check_sel_11_routes_d: assert property (
        @(posedge clk)
        (sel === 2'b11) |-> (y === d)
    );

// Q reflects a low D value after two clocks.
    check_q_two_cycle_delay_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        (D === 1'b0) |-> ##2 (Q === 1'b0)
    );

// Q reflects a high D value after two clocks.
    check_q_two_cycle_delay_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (D === 1'b1) |-> ##2 (Q === 1'b1)
    );

// Q_N is always the complement of Q.
    check_outputs_complement: assert property (
        @(posedge CLK) Q_N === ~Q
    );

// Clear forces Q low on the next clock, regardless of PRE.
    check_clear_forces_q_low: assert property (
        @(posedge CLK) CLR |=> (Q == 1'b0)
    );

// Clear forces Q_N high on the next clock, regardless of PRE.
    check_clear_forces_qn_high: assert property (
        @(posedge CLK) CLR |=> (Q_N == 1'b1)
    );

// Preset forces Q high when clear is not asserted.
    check_preset_forces_q_high: assert property (
        @(posedge CLK) (!CLR && PRE) |=> (Q == 1'b1)
    );

// Preset forces Q_N low when clear is not asserted.
    check_preset_forces_qn_low: assert property (
        @(posedge CLK) (!CLR && PRE) |=> (Q_N == 1'b0)
    );

// Without clear or preset, Q captures D on the next clock.
    check_data_capture_without_controls: assert property (
        @(posedge CLK) (!CLR && !PRE) |=> (Q == $past(D))
    );

// Without clear or preset, Q_N matches the complement of captured D.
    check_qn_capture_without_controls: assert property (
        @(posedge CLK) (!CLR && !PRE) |=> (Q_N == ~$past(D))
    );

// The output never uses the unused 2'b11 encoding.
    check_output_encoding: assert property (
        @(posedge clk) (output_value != 2'b11)
    );

// X must implement (A1 & A2) | B1.
    check_function_equation: assert property (
        @(posedge clk) X == ((A1 & A2) | B1)
    );

// B1 high must force X high through the OR stage.
    check_b1_forces_high: assert property (
        @(posedge clk) B1 |-> X
    );

// A1 and A2 high must force X high through the AND stage.
    check_and_term_forces_high: assert property (
        @(posedge clk) (A1 && A2) |-> X
    );

// With B1 low, X must reduce to the A1/A2 AND term.
    check_b1_low_reduces_to_and: assert property (
        @(posedge clk) !B1 |-> (X == (A1 & A2))
    );

// With B1 low and the AND term false, X must be low.
    check_no_active_term_means_low: assert property (
        @(posedge clk) (!B1 && !(A1 && A2)) |-> !X
    );

// A high X must come from B1 or from both A1 and A2.
    check_high_output_has_valid_cause: assert property (
        @(posedge clk) X |-> (B1 || (A1 && A2))
    );

// The outputs match 1-bit addition of A, B, and Ci.
    check_full_adder_numeric_result: assert property (
        @(posedge clk) {Co, S} == ({1'b0, A} + {1'b0, B} + {1'b0, Ci})
    );

// A reset cycle clears the counter and deasserts the pulse by the next clock.
    check_reset_clears_state: assert property (
        @(posedge clock) reset |=> (counter == 25'd0 && oneHertz_enable == 1'b0)
    );

// If A's MSB is greater than B's MSB, Z must be high.
    check_msb_greater_sets_z: assert property (
        @(posedge clk) (A[1] > B[1]) |-> (Z == 1'b1)
    );

// If A's MSB is less than B's MSB, -1 truncates to 1'b1 on Z.
    check_msb_less_sets_z: assert property (
        @(posedge clk) (A[1] < B[1]) |-> (Z == 1'b1)
    );

// With equal MSBs, a greater A LSB drives Z high.
    check_lsb_greater_sets_z: assert property (
        @(posedge clk) ((A[1] == B[1]) && (A[0] > B[0])) |-> (Z == 1'b1)
    );

// With equal MSBs, a lower A LSB also truncates to 1'b1 on Z.
    check_lsb_less_sets_z: assert property (
        @(posedge clk) ((A[1] == B[1]) && (A[0] < B[0])) |-> (Z == 1'b1)
    );

// Equal inputs drive Z low.
    check_equal_inputs_clear_z: assert property (
        @(posedge clk) (A == B) |-> (Z == 1'b0)
    );

// Overall implemented behavior is Z high iff A and B differ.
    check_z_matches_input_inequality: assert property (
        @(posedge clk) (Z == (A != B))
    );

// Reset clears both registered outputs by the next sampled cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (count == 4'd0) && (out == 1'b0)
    );

// Outside reset, count increments by one every cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (count == ($past(count) + 4'd1))
    );

// Outside reset, out toggles every cycle.
    check_out_toggles: assert property (
        @(posedge clk) disable iff (reset)
        !reset |=> (out == ~$past(out))
    );

// Outside reset, count wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset)
        (!reset && (count == 4'hF)) |=> (count == 4'h0)
    );

// A write cycle loads all four outputs from cpu_d.
    check_write_loads_outputs: assert property (
        @(posedge Ncpu_romsel)
        (cpu_rw === 1'b0) |=> (
            {hc161_out3, hc161_out2, hc161_out1, hc161_out0} ===
            {$past(cpu_d[3]), $past(cpu_d[2]), $past(cpu_d[1]), $past(cpu_d[0])}
        )
    );

// A non-write cycle leaves all four outputs unchanged.
    check_read_holds_outputs: assert property (
        @(posedge Ncpu_romsel)
        (cpu_rw === 1'b1) |=> (
            {hc161_out3, hc161_out2, hc161_out1, hc161_out0} ===
            {$past(hc161_out3), $past(hc161_out2), $past(hc161_out1), $past(hc161_out0)}
        )
    );

// The first active clock after reset keeps both body-bias outputs low.
    check_post_reset_body_bias_low: assert property (
        @(posedge clk) disable iff (rst) $past(rst) |-> (VPB == 1'b0 && VNB == 1'b0)
    );

// Every active cycle drives VNB low by the next clock.
    check_vnb_forced_low_every_cycle: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> VNB == 1'b0
    );

// When enable is low, the next clock drives both body-bias outputs low.
    check_disable_clears_body_bias: assert property (
        @(posedge clk) disable iff (rst) !enable |=> (VPB == 1'b0 && VNB == 1'b0)
    );

// When enable is high, the next clock still keeps VNB low.
    check_enable_keeps_vnb_low: assert property (
        @(posedge clk) disable iff (rst) enable |=> VNB == 1'b0
    );

// Reset drives the counter to zero on the following clock.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 4'b0000)
    );

// Reset overrides enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (out == 4'b0000)
    );

// When enabled below max value, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (en && (out != 4'hF)) |=> (out == ($past(out) + 4'd1))
    );

// When enabled at max value, the counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (en && (out == 4'hF)) |=> (out == 4'h0)
    );

// When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!en) |=> (out == $past(out))
    );

// f must match the implemented sum-of-products equation.
    check_f_matches_sum_of_products: assert property (
        @(posedge clk)
        f == ((x[0] & x[1]) | (x[0] & x[2]) | (x[1] & x[3]) | (x[2] & x[3]))
    );

// x[0] and x[1] high must drive f high.
    check_f_high_for_x0_x1: assert property (
        @(posedge clk)
        (x[0] & x[1]) |-> f
    );

// x[0] and x[2] high must drive f high.
    check_f_high_for_x0_x2: assert property (
        @(posedge clk)
        (x[0] & x[2]) |-> f
    );

// x[1] and x[3] high must drive f high.
    check_f_high_for_x1_x3: assert property (
        @(posedge clk)
        (x[1] & x[3]) |-> f
    );

// x[2] and x[3] high must drive f high.
    check_f_high_for_x2_x3: assert property (
        @(posedge clk)
        (x[2] & x[3]) |-> f
    );

// If all implemented product terms are low, f must be low.
    check_f_low_without_product_terms: assert property (
        @(posedge clk)
        !((x[0] & x[1]) | (x[0] & x[2]) | (x[1] & x[3]) | (x[2] & x[3])) |-> !f
    );

// A sampled reset must leave the registered output cleared on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (out == 16'b0)
    );

// The first clock after reset deassertion still sees the cleared register value.
    check_reset_release_keeps_zero_until_update: assert property (
        @(posedge clk) $fell(reset) |-> (out == 16'b0)
    );

// When ctrl is high, the next registered output is {a, b}.
    check_ctrl_high_concatenates_a_then_b: assert property (
        @(posedge clk) disable iff (reset)
        ctrl |=> (out == {$past(a), $past(b)})
    );

// When ctrl is low, the next registered output is {b, a}.
    check_ctrl_low_concatenates_b_then_a: assert property (
        @(posedge clk) disable iff (reset)
        !ctrl |=> (out == {$past(b), $past(a)})
    );

// Y always matches the implemented 4-to-1 mux expression.
    check_mux_function: assert property (
        @(posedge clk) Y === (S1 ? (S0 ? D3 : D2) : (S0 ? D1 : D0))
    );

// Y routes D0 when the select value is 2'b00.
    check_select_00_routes_d0: assert property (
        @(posedge clk) ({S1, S0} === 2'b00) |-> (Y === D0)
    );

// Y routes D1 when the select value is 2'b01.
    check_select_01_routes_d1: assert property (
        @(posedge clk) ({S1, S0} === 2'b01) |-> (Y === D1)
    );

// Y routes D2 when the select value is 2'b10.
    check_select_10_routes_d2: assert property (
        @(posedge clk) ({S1, S0} === 2'b10) |-> (Y === D2)
    );

// Y routes D3 when the select value is 2'b11.
    check_select_11_routes_d3: assert property (
        @(posedge clk) ({S1, S0} === 2'b11) |-> (Y === D3)
    );

// serial_out is the zero-extended LSB of the register.
    check_serial_out_mapping: assert property (
        @(posedge clk) serial_out == {7'b0, parallel_out[0]}
    );

// parallel_load loads data_in into the register on the next cycle.
    check_parallel_load_updates_register: assert property (
        @(posedge clk) parallel_load |=> parallel_out == $past(data_in)
    );

// parallel_load also updates serial_out to the loaded bit 0 on the next cycle.
    check_parallel_load_updates_serial: assert property (
        @(posedge clk) parallel_load |=> serial_out == {7'b0, $past(data_in[0])}
    );

// With no load, shift_dir=1 shifts the register left and inserts 0 in bit 0.
    check_left_shift_updates_register: assert property (
        @(posedge clk) (!parallel_load && shift_dir) |=> parallel_out == {$past(parallel_out[6:0]), 1'b0}
    );

// A left shift forces serial_out to zero on the next cycle.
    check_left_shift_clears_serial_out: assert property (
        @(posedge clk) (!parallel_load && shift_dir) |=> serial_out == 8'h00
    );

// With no load, shift_dir=0 shifts the register right and inserts 0 in bit 7.
    check_right_shift_updates_register: assert property (
        @(posedge clk) (!parallel_load && !shift_dir) |=> parallel_out == {1'b0, $past(parallel_out[7:1])}
    );

// A right shift makes serial_out equal the prior bit 1 on the next cycle.
    check_right_shift_updates_serial: assert property (
        @(posedge clk) (!parallel_load && !shift_dir) |=> serial_out == {7'b0, $past(parallel_out[1])}
    );

// SUM must be the XOR of the three inputs.
    check_sum_xor_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT_N must match the implemented NOR/OR carry network.
    check_coutn_gate_function: assert property (
        @(posedge clk) COUT_N == ((~(A | B)) | (~(A | CI)) | (~(B | CI)))
    );

// The outputs must encode the 2-bit result of A+B+CI.
    check_full_adder_result: assert property (
        @(posedge clk) ({1'b0, A} + {1'b0, B} + {1'b0, CI}) == {~COUT_N, SUM}
    );

// 000 must produce SUM=0 and COUT_N=1.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b1))
    );

// 001 must produce SUM=1 and COUT_N=1.
    check_ci_only_case: assert property (
        @(posedge clk) (!A && !B && CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

// 010 must produce SUM=1 and COUT_N=1.
    check_b_only_case: assert property (
        @(posedge clk) (!A && B && !CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

// 011 must produce SUM=0 and COUT_N=0.
    check_b_ci_case: assert property (
        @(posedge clk) (!A && B && CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

// 100 must produce SUM=1 and COUT_N=1.
    check_a_only_case: assert property (
        @(posedge clk) (A && !B && !CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

// 101 must produce SUM=0 and COUT_N=0.
    check_a_ci_case: assert property (
        @(posedge clk) (A && !B && CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

// 110 must produce SUM=0 and COUT_N=0.
    check_a_b_case: assert property (
        @(posedge clk) (A && B && !CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

// 111 must produce SUM=1 and COUT_N=0.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b0))
    );

// Y must always match the selected rotation of A.
    check_output_matches_select: assert property (
        @(posedge clk)
        Y == ((S == 2'b00) ? A :
              (S == 2'b01) ? {A[2:0], A[3]} :
              (S == 2'b10) ? {A[0], A[3:1]} :
                             {A[1:0], A[3:2]})
    );

// S=00 passes A through unchanged.
    check_sel_00_passthrough: assert property (
        @(posedge clk)
        (S == 2'b00) |-> (Y == A)
    );

// S=01 rotates A left by one bit.
    check_sel_01_rotate_left_1: assert property (
        @(posedge clk)
        (S == 2'b01) |-> (Y == {A[2:0], A[3]})
    );

// S=10 rotates A right by one bit.
    check_sel_10_rotate_right_1: assert property (
        @(posedge clk)
        (S == 2'b10) |-> (Y == {A[0], A[3:1]})
    );

// S=11 rotates A by two bits.
    check_sel_11_rotate_2: assert property (
        @(posedge clk)
        (S == 2'b11) |-> (Y == {A[1:0], A[3:2]})
    );

// Output bit 1 is the OR of the two input MSBs.
    check_out2_bit1_is_msb_or: assert property (
        @(posedge clk) out_2[1] == (in_4[3] | in_4[2])
    );

// Output bit 0 is the OR of the two input MSBs.
    check_out2_bit0_is_msb_or: assert property (
        @(posedge clk) out_2[0] == (in_4[3] | in_4[2])
    );

// Both output bits always match because the OR result is replicated.
    check_out2_bits_match: assert property (
        @(posedge clk) out_2[1] == out_2[0]
    );

// When both input MSBs are low, the output is 2'b00.
    check_zero_when_both_msbs_low: assert property (
        @(posedge clk) (in_4[3:2] == 2'b00) |-> (out_2 == 2'b00)
    );

// When either input MSB is high, the output is 2'b11.
    check_ones_when_any_msb_high: assert property (
        @(posedge clk) (in_4[3] | in_4[2]) |-> (out_2 == 2'b11)
    );

// When disabled, p holds its previous value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) !ce |=> p == $past(p)
    );

// A reset clock edge loads q from init.
    check_reset_loads_init: assert property (
        @(posedge clk) reset |=> (q == $past(init))
    );

// A non-reset clock edge loads q from d.
    check_data_loads_d: assert property (
        @(posedge clk) (!reset) |=> (q == $past(d))
    );

// Across consecutive non-reset cycles, q continues to follow d.
    check_data_loads_d_across_non_reset_cycles: assert property (
        @(posedge clk) disable iff (reset) (!reset) |=> (!reset && (q == $past(d)))
    );

// q always matches the source selected on the previous clock edge.
    check_selected_input_update: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(reset ? init : d))
    );

// out is permanently tied low.
    check_out_tied_low: assert property (
        @(posedge aclk) out == 1'b0
    );

// count_d1_reg is permanently zero.
    check_count_d1_reg_zero: assert property (
        @(posedge aclk) count_d1_reg == 8'h00
    );

// A ready cycle loads tx_fifo_dataout_reg into m_axi_wdata by the next clock.
    check_wdata_captures_tx_fifo_on_ready: assert property (
        @(posedge aclk) m_axi_wready |=> (m_axi_wdata == $past(tx_fifo_dataout_reg))
    );

// Without ready, m_axi_wdata holds its previous value.
    check_wdata_holds_when_not_ready: assert property (
        @(posedge aclk) !m_axi_wready |=> (m_axi_wdata == $past(m_axi_wdata))
    );

// Output must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) S === ((ctrl == 1'b0) ? D0 : D1)
    );

// ctrl low selects D0.
    check_select_d0_when_ctrl_low: assert property (
        @(posedge clk) (ctrl === 1'b0) |-> (S === D0)
    );

// ctrl high selects D1.
    check_select_d1_when_ctrl_high: assert property (
        @(posedge clk) (ctrl === 1'b1) |-> (S === D1)
    );

// When both inputs match, the output matches them as well.
    check_equal_inputs_produce_same_output: assert property (
        @(posedge clk) (D0 === D1) |-> (S === D0)
    );

// Reset drives the counter to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 8'd0)
    );

// When below 255 and not in reset, the counter increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (count != 8'hFF) |=> (count == ($past(count) + 8'd1))
    );

// When at 255 and not in reset, the counter wraps to zero.
    check_count_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (count == 8'hFF) |=> (count == 8'd0)
    );

// Reset clears the sys_clk-domain counter and gate.
    reset_count_gate_state: assert property (
        @(posedge sys_clk_50m) !sys_rst_n |-> (count == 32'd0) && (Gate_1S == 1'b0)
    );

// Reset clears EN_FT in the ch_c domain.
    reset_clears_en_ft: assert property (
        @(posedge ch_c) !sys_rst_n |-> (EN_FT == 1'b0)
    );

// freq_reg holds when the current ch_c edge cannot create a Load rise.
    freq_reg_stable_without_load_rise: assert property (
        @(posedge ch_c) disable iff (!sys_rst_n)
        !(EN_FT && !Gate_1S) |=> (freq_reg == $past(freq_reg))
    );

// X implements the combinational function (~A_N & B & C).
    check_functional_equivalence: assert property (
        @(posedge clk) X === ((~A_N) & B & C)
    );

// A_N high forces the inverted input low and drives X low.
    check_a_n_high_blocks_output: assert property (
        @(posedge clk) (A_N === 1'b1) |-> (X === 1'b0)
    );

// B low forces the 3-input AND output low.
    check_b_low_blocks_output: assert property (
        @(posedge clk) (B === 1'b0) |-> (X === 1'b0)
    );

// C low forces the 3-input AND output low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) (C === 1'b0) |-> (X === 1'b0)
    );

// When all effective AND inputs are high, X must be high.
    check_all_inputs_enable_output_high: assert property (
        @(posedge clk) (A_N === 1'b0 && B === 1'b1 && C === 1'b1) |-> (X === 1'b1)
    );

// X high is only possible for the single true minterm.
    check_output_high_implies_required_inputs: assert property (
        @(posedge clk) (X === 1'b1) |-> (A_N === 1'b0 && B === 1'b1 && C === 1'b1)
    );

// External sampling clock for this combinational DUT.

    // When disabled, the output is forced to zero.
    check_disabled_forces_zero: assert property (
        @(posedge clk) (en === 1'b0) |-> (out === 4'b0000)
    );

// With sel=00 and enable high, out follows in0.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) ((sel === 2'b00) && (en === 1'b1)) |-> (out === in0)
    );

// With sel=01 and enable high, out follows in1.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) ((sel === 2'b01) && (en === 1'b1)) |-> (out === in1)
    );

// With sel=10 and enable high, out follows in2.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) ((sel === 2'b10) && (en === 1'b1)) |-> (out === in2)
    );

// With sel=11 and enable high, out follows in3.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) ((sel === 2'b11) && (en === 1'b1)) |-> (out === in3)
    );

// Any non-matching select value drives the default zero output.
    check_invalid_sel_defaults_zero: assert property (
        @(posedge clk)
        !((sel === 2'b00) || (sel === 2'b01) || (sel === 2'b10) || (sel === 2'b11))
        |-> (out === 4'b0000)
    );

// LD loads DIN on the next clock and overrides count controls.
    check_load_updates_q: assert property (
        @(posedge CLK) LD |=> (Q == $past(DIN))
    );

// When not loading, UP increments Q on the next clock and has priority over DOWN.
    check_up_increments_q: assert property (
        @(posedge CLK) (!LD && UP) |=> (Q == ($past(Q) + 3'd1))
    );

// DOWN decrements Q on the next clock only when LD and UP are both low.
    check_down_decrements_q: assert property (
        @(posedge CLK) (!LD && !UP && DOWN) |=> (Q == ($past(Q) - 3'd1))
    );

// With no active control inputs, Q holds its value.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LD && !UP && !DOWN) |=> (Q == $past(Q))
    );

// S must select D0 when ctrl is low.
    check_select_d0: assert property (
        @(posedge clk) !ctrl |-> (S == D0)
    );

// S must select D1 when ctrl is high.
    check_select_d1: assert property (
        @(posedge clk) ctrl |-> (S == D1)
    );

// S must always match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) S == (ctrl ? D1 : D0)
    );

// gray_out[3] matches the binary MSB.
    check_gray_msb: assert property (
        @(posedge clk) gray_out[3] == bin_in[3]
    );

// gray_out[2] is bin_in[2] XOR bin_in[3].
    check_gray_bit2: assert property (
        @(posedge clk) gray_out[2] == (bin_in[2] ^ bin_in[3])
    );

// gray_out[1] is bin_in[1] XOR bin_in[2].
    check_gray_bit1: assert property (
        @(posedge clk) gray_out[1] == (bin_in[1] ^ bin_in[2])
    );

// gray_out[0] is bin_in[0] XOR bin_in[1].
    check_gray_bit0: assert property (
        @(posedge clk) gray_out[0] == (bin_in[0] ^ bin_in[1])
    );

// Sum is the xor of all three inputs.
    check_sum_definition: assert property (
        @(posedge clk) Sum == (A ^ B ^ Cin)
    );

// Cout matches the implemented carry equation.
    check_cout_definition: assert property (
        @(posedge clk) Cout == ((A & B) | (Cin & (A ^ B)))
    );

// 000 produces no sum bit and no carry.
    check_add_000: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && Cin == 1'b0) |-> ({Cout, Sum} == 2'b00)
    );

// 001 produces sum 1 with no carry.
    check_add_001: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && Cin == 1'b1) |-> ({Cout, Sum} == 2'b01)
    );

// 010 produces sum 1 with no carry.
    check_add_010: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1 && Cin == 1'b0) |-> ({Cout, Sum} == 2'b01)
    );

// 011 produces carry 1 and sum 0.
    check_add_011: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1 && Cin == 1'b1) |-> ({Cout, Sum} == 2'b10)
    );

// 100 produces sum 1 with no carry.
    check_add_100: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0 && Cin == 1'b0) |-> ({Cout, Sum} == 2'b01)
    );

// 101 produces carry 1 and sum 0.
    check_add_101: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0 && Cin == 1'b1) |-> ({Cout, Sum} == 2'b10)
    );

// 110 produces carry 1 and sum 0.
    check_add_110: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && Cin == 1'b0) |-> ({Cout, Sum} == 2'b10)
    );

// 111 produces sum 1 and carry 1.
    check_add_111: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && Cin == 1'b1) |-> ({Cout, Sum} == 2'b11)
    );

// Y must equal the AND of all five inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & A3 & A4 & B1)
    );

// When all inputs are HIGH, Y must be HIGH.
    check_all_inputs_high_drives_y_high: assert property (
        @(posedge clk) (A1 & A2 & A3 & A4 & B1) |-> Y
    );

// A HIGH Y requires all inputs to be HIGH.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A1 & A2 & A3 & A4 & B1)
    );

// A LOW A1 forces Y LOW.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A LOW A2 forces Y LOW.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A LOW A3 forces Y LOW.
    check_a3_low_forces_y_low: assert property (
        @(posedge clk) !A3 |-> !Y
    );

// A LOW A4 forces Y LOW.
    check_a4_low_forces_y_low: assert property (
        @(posedge clk) !A4 |-> !Y
    );

// A LOW B1 forces Y LOW.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// Sum matches XOR of all three inputs.
    check_sum_equation: assert property (
        @(posedge clk) S == (A ^ B ^ C_in)
    );

// Carry matches the implemented carry equation.
    check_carry_equation: assert property (
        @(posedge clk) C_out == ((A & B) | ((A ^ B) & C_in))
    );

// Sum and carry match the 2-bit arithmetic result.
    check_arithmetic_result: assert property (
        @(posedge clk) {C_out, S} == ({1'b0, A} + {1'b0, B} + {1'b0, C_in})
    );

// With no carry-in, the block behaves like a half-adder.
    check_no_carry_in_behavior: assert property (
        @(posedge clk) !C_in |-> ((S == (A ^ B)) && (C_out == (A & B)))
    );

// When both inputs are low, sum follows C_in and carry is low.
    check_zero_operands: assert property (
        @(posedge clk) (!A && !B) |-> ((S == C_in) && (C_out == 1'b0))
    );

// When both inputs are high, sum follows C_in and carry is high.
    check_both_operands_high: assert property (
        @(posedge clk) (A && B) |-> ((S == C_in) && (C_out == 1'b1))
    );

// When A and B differ, carry follows C_in and sum inverts C_in.
    check_operands_different: assert property (
        @(posedge clk) (A ^ B) |-> ((S == ~C_in) && (C_out == C_in))
    );

// The output must match the full 4-to-1 mux selection function.
    check_combined_mux_function: assert property (
        @(posedge clk) out_mux == (sel[1] ? (sel[0] ? d : c) : (sel[0] ? b : a))
    );

// sel=00 routes input a to the output.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out_mux == a)
    );

// sel=01 routes input b to the output.
    check_sel_01_routes_b: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out_mux == b)
    );

// sel=10 routes input c to the output.
    check_sel_10_routes_c: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out_mux == c)
    );

// sel=11 routes input d to the output.
    check_sel_11_routes_d: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out_mux == d)
    );

// X matches the implemented O211 logic function.
    check_function_exact: assert property (
        @(posedge clk) X == (((A1 | A2) & B1) & C1)
    );

// Low B1 forces the AND output low.
    check_b1_gates_output_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Low C1 forces the AND output low.
    check_c1_gates_output_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// With both OR inputs low, the output must be low.
    check_or_inputs_low_force_output_low: assert property (
        @(posedge clk) !(A1 | A2) |-> !X
    );

// A1 can drive X high when both gating inputs are high.
    check_a1_path_drives_high: assert property (
        @(posedge clk) (A1 & B1 & C1) |-> X
    );

// A2 can drive X high when both gating inputs are high.
    check_a2_path_drives_high: assert property (
        @(posedge clk) (A2 & B1 & C1) |-> X
    );

// High X requires B1 to be high.
    check_output_high_implies_b1: assert property (
        @(posedge clk) X |-> B1
    );

// High X requires C1 to be high.
    check_output_high_implies_c1: assert property (
        @(posedge clk) X |-> C1
    );

// High X requires at least one OR input to be high.
    check_output_high_implies_or_term: assert property (
        @(posedge clk) X |-> (A1 | A2)
    );

// X must match the implemented OR-of-ANDs function.
    check_x_function: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2) | C1)
    );

// C1 high must drive X high.
    check_c1_implies_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together must drive X high.
    check_a_pair_implies_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high together must drive X high.
    check_b_pair_implies_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If all OR inputs are low, X must be low.
    check_all_terms_low_implies_x_low: assert property (
        @(posedge clk) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> !X
    );

// X low means none of the three OR terms are asserted.
    check_x_low_only_when_all_terms_low: assert property (
        @(posedge clk) !X |-> (!C1 && !(A1 & A2) && !(B1 & B2))
    );

// Sampling clock only; the DUT itself has no clock or reset.

    // When disabled, all outputs are HIGH.
    check_disabled_all_high: assert property (
        @(posedge clk) !ena |-> (out == 16'hFFFF)
    );

// When enabled, the selected output bit is LOW.
    check_enabled_selected_bit_low: assert property (
        @(posedge clk) ena |-> (out[in] == 1'b0)
    );

// When enabled, all non-selected output bits are HIGH.
    check_enabled_unselected_bits_high: assert property (
        @(posedge clk) ena |-> ((out | (16'h0001 << in)) == 16'hFFFF)
    );

// When enabled, the full active-low decode matches the input value.
    check_enabled_decode_map: assert property (
        @(posedge clk) ena |-> (out == ~(16'h0001 << in))
    );

// Sampled on clk; RTL has no reset and implements a combinational 8-to-1 mux.

    // sel=000 selects in0 onto out.
    check_sel_000_selects_in0: assert property (
        @(posedge clk) (sel == 3'b000) |-> (out === in0)
    );

// sel=001 selects in1 onto out.
    check_sel_001_selects_in1: assert property (
        @(posedge clk) (sel == 3'b001) |-> (out === in1)
    );

// sel=010 selects in2 onto out.
    check_sel_010_selects_in2: assert property (
        @(posedge clk) (sel == 3'b010) |-> (out === in2)
    );

// sel=011 selects in3 onto out.
    check_sel_011_selects_in3: assert property (
        @(posedge clk) (sel == 3'b011) |-> (out === in3)
    );

// sel=100 selects in4 onto out.
    check_sel_100_selects_in4: assert property (
        @(posedge clk) (sel == 3'b100) |-> (out === in4)
    );

// sel=101 selects in5 onto out.
    check_sel_101_selects_in5: assert property (
        @(posedge clk) (sel == 3'b101) |-> (out === in5)
    );

// sel=110 selects in6 onto out.
    check_sel_110_selects_in6: assert property (
        @(posedge clk) (sel == 3'b110) |-> (out === in6)
    );

// sel=111 selects in7 onto out.
    check_sel_111_selects_in7: assert property (
        @(posedge clk) (sel == 3'b111) |-> (out === in7)
    );

// Output must always equal the AND of the two inputs.
    check_output_matches_and: assert property (
        @(posedge clk) X == (A & B)
    );

// If both inputs are high, the output must be high.
    check_both_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A && B) |-> X
    );

// If A is low, the output must be low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) !A |-> !X
    );

// If B is low, the output must be low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) !B |-> !X
    );

// A high output requires both inputs to be high.
    check_output_high_requires_both_inputs_high: assert property (
        @(posedge clk) X |-> (A && B)
    );

// so is tied low when shadow scan is not connected.
    check_so_tied_low: assert property (
        @(posedge clk) (so == {SIZE{1'b0}})
    );

// Y matches the gate-level structure in the RTL.
    check_y_matches_structure: assert property (
        @(posedge clk) Y == ~((~(A2 & A1)) & (~(B2 & B1)))
    );

// Y simplifies to the OR of the two input pairs.
    check_y_matches_simplified_function: assert property (
        @(posedge clk) Y == ((A1 & A2) | (B1 & B2))
    );

// A1 and A2 both high force Y high.
    check_a_pair_drives_y_high: assert property (
        @(posedge clk) (A1 & A2) |-> Y
    );

// B1 and B2 both high force Y high.
    check_b_pair_drives_y_high: assert property (
        @(posedge clk) (B1 & B2) |-> Y
    );

// If neither pair is fully high, Y must be low.
    check_no_complete_pair_drives_y_low: assert property (
        @(posedge clk) (!(A1 & A2) && !(B1 & B2)) |-> !Y
    );

// A low Y means neither input pair is fully high.
    check_y_low_implies_no_complete_pair: assert property (
        @(posedge clk) !Y |-> (!(A1 & A2) && !(B1 & B2))
    );

// Output must match the RTL threshold expression.
    check_output_equation: assert property (
        @(posedge clk)
        data_out == (
            (data_in <= 4'd4)  ? 2'b00 :
            (data_in <= 4'd8)  ? 2'b01 :
            (data_in <= 4'd12) ? 2'b10 : 2'b11
        )
    );

// Inputs 0 through 4 must map to 2'b00.
    check_range_0_to_4: assert property (
        @(posedge clk)
        (data_in <= 4'd4) |-> (data_out == 2'b00)
    );

// Inputs 5 through 8 must map to 2'b01.
    check_range_5_to_8: assert property (
        @(posedge clk)
        ((data_in >= 4'd5) && (data_in <= 4'd8)) |-> (data_out == 2'b01)
    );

// Inputs 9 through 12 must map to 2'b10.
    check_range_9_to_12: assert property (
        @(posedge clk)
        ((data_in >= 4'd9) && (data_in <= 4'd12)) |-> (data_out == 2'b10)
    );

// Inputs 13 through 15 must map to 2'b11.
    check_range_13_to_15: assert property (
        @(posedge clk)
        (data_in >= 4'd13) |-> (data_out == 2'b11)
    );

// The lower threshold value 4 must produce 2'b00.
    check_threshold_at_4: assert property (
        @(posedge clk)
        (data_in == 4'd4) |-> (data_out == 2'b00)
    );

// The next value after 4 must produce 2'b01.
    check_threshold_at_5: assert property (
        @(posedge clk)
        (data_in == 4'd5) |-> (data_out == 2'b01)
    );

// The upper value of the second range must produce 2'b01.
    check_threshold_at_8: assert property (
        @(posedge clk)
        (data_in == 4'd8) |-> (data_out == 2'b01)
    );

// The next value after 8 must produce 2'b10.
    check_threshold_at_9: assert property (
        @(posedge clk)
        (data_in == 4'd9) |-> (data_out == 2'b10)
    );

// The upper value of the third range must produce 2'b10.
    check_threshold_at_12: assert property (
        @(posedge clk)
        (data_in == 4'd12) |-> (data_out == 2'b10)
    );

// The next value after 12 must produce 2'b11.
    check_threshold_at_13: assert property (
        @(posedge clk)
        (data_in == 4'd13) |-> (data_out == 2'b11)
    );

// Select 00 routes iInput0 to oOutput.
    check_select_00_routes_input0: assert property (
        @(posedge clk) (iSelect == 2'b00) |-> (oOutput == iInput0)
    );

// Select 01 routes iInput1 to oOutput.
    check_select_01_routes_input1: assert property (
        @(posedge clk) (iSelect == 2'b01) |-> (oOutput == iInput1)
    );

// Select 10 routes iInput2 to oOutput.
    check_select_10_routes_input2: assert property (
        @(posedge clk) (iSelect == 2'b10) |-> (oOutput == iInput2)
    );

// Select 11 routes iInput3 to oOutput.
    check_select_11_routes_input3: assert property (
        @(posedge clk) (iSelect == 2'b11) |-> (oOutput == iInput3)
    );

// Y matches the NOR of A, B, C, and the inverted D_N input.
    check_nor4b_function: assert property (
        @(posedge clk) (Y === ~(A | B | C | ~D_N))
    );

// Y is high when A, B, and C are low and D_N is high.
    check_output_high_condition: assert property (
        @(posedge clk)
        ((A === 1'b0) && (B === 1'b0) && (C === 1'b0) && (D_N === 1'b1)) |-> (Y === 1'b1)
    );

// Y can only be high when A, B, and C are low and D_N is high.
    check_output_high_only_when_enabled: assert property (
        @(posedge clk)
        (Y === 1'b1) |-> ((A === 1'b0) && (B === 1'b0) && (C === 1'b0) && (D_N === 1'b1))
    );

// A high forces the NOR output low.
    check_a_high_forces_low: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// B high forces the NOR output low.
    check_b_high_forces_low: assert property (
        @(posedge clk) (B === 1'b1) |-> (Y === 1'b0)
    );

// C high forces the NOR output low.
    check_c_high_forces_low: assert property (
        @(posedge clk) (C === 1'b1) |-> (Y === 1'b0)
    );

// D_N low is inverted internally and forces the NOR output low.
    check_dn_low_forces_low: assert property (
        @(posedge clk) (D_N === 1'b0) |-> (Y === 1'b0)
    );

// When select is 00, output follows I[0].
    check_sel_00_routes_i0: assert property (
        @(posedge clk) (S === 2'b00) |-> (O === I[0])
    );

// When select is 01, output follows I[1].
    check_sel_01_routes_i1: assert property (
        @(posedge clk) (S === 2'b01) |-> (O === I[1])
    );

// When select is 10, output is forced low.
    check_sel_10_drives_zero: assert property (
        @(posedge clk) (S === 2'b10) |-> (O === 1'b0)
    );

// When select is 11, output is forced high.
    check_sel_11_drives_one: assert property (
        @(posedge clk) (S === 2'b11) |-> (O === 1'b1)
    );

// Synchronous reset clears count on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled outside reset, count increments by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'b0001))
    );

// When not enabled outside reset, count holds its value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Reset takes priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// Increment wraps from 15 back to 0.
    check_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && count == 4'hf) |=> (count == 4'h0)
    );

// Active-low reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rstn |-> (count == {WIDTH{1'b0}})
    );

// With neither input asserted, count holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!rstn)
        (!up && !down) |=> (count == $past(count))
    );

// With both inputs asserted, count holds its value.
    check_hold_when_up_and_down: assert property (
        @(posedge clk) disable iff (!rstn)
        (up && down) |=> (count == $past(count))
    );

// Enabled clock loads stage 0 from the input stream.
    check_stage0_captures_input: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_0 == $past(in_stream))
    );

// Enabled clock shifts stage 0 into stage 1.
    check_stage1_shifts_stage0: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_1 == $past(pipeline_reg_0))
    );

// Enabled clock shifts stage 1 into stage 2.
    check_stage2_shifts_stage1: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_2 == $past(pipeline_reg_1))
    );

// Enabled clock shifts stage 2 into stage 3.
    check_stage3_shifts_stage2: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_3 == $past(pipeline_reg_2))
    );

// Enabled clock shifts stage 3 into stage 4.
    check_stage4_shifts_stage3: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_4 == $past(pipeline_reg_3))
    );

// Enabled clock shifts stage 4 into stage 5.
    check_stage5_shifts_stage4: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_5 == $past(pipeline_reg_4))
    );

// Enabled clock shifts stage 5 into stage 6.
    check_stage6_shifts_stage5: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_6 == $past(pipeline_reg_5))
    );

// Enabled clock shifts stage 6 into stage 7.
    check_stage7_shifts_stage6: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_7 == $past(pipeline_reg_6))
    );

// Enabled clock shifts stage 7 into stage 8.
    check_stage8_shifts_stage7: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_8 == $past(pipeline_reg_7))
    );

// Enabled clock shifts stage 8 into stage 9.
    check_stage9_shifts_stage8: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_9 == $past(pipeline_reg_8))
    );

// During active-low reset, the registered outputs are cleared.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (!rst_n) |-> ({Cout, S} == 5'b0)
    );

// A sampled reset cycle leaves the outputs cleared at the next sampled clock.
    check_reset_keeps_outputs_cleared_next_cycle: assert property (
        @(posedge clk) (!rst_n) |=> ({Cout, S} == 5'b0)
    );

// On active cycles, the next sampled output is either the registered sum or the reset value.
    check_next_output_is_sum_or_reset_value: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (({Cout, S} == 5'b0) ||
                  ({Cout, S} == $past({1'b0, A} + {1'b0, B} + Cin)))
    );

// With B and Cin low, the next sampled output is either A or the reset value.
    check_b_zero_cin_zero_passthrough_or_reset: assert property (
        @(posedge clk) disable iff (!rst_n)
        (B == 4'b0 && Cin == 1'b0) |=> (({Cout, S} == 5'b0) ||
                                        ({Cout, S} == {1'b0, $past(A)}))
    );

// With A and Cin low, the next sampled output is either B or the reset value.
    check_a_zero_cin_zero_passthrough_or_reset: assert property (
        @(posedge clk) disable iff (!rst_n)
        (A == 4'b0 && Cin == 1'b0) |=> (({Cout, S} == 5'b0) ||
                                        ({Cout, S} == {1'b0, $past(B)}))
    );

// Zero inputs must produce a zero registered output.
    check_zero_inputs_produce_zero_output: assert property (
        @(posedge clk) disable iff (!rst_n)
        (A == 4'b0 && B == 4'b0 && Cin == 1'b0) |=> ({Cout, S} == 5'b0)
    );

// Any non-overflowing addition must register a low carry.
    check_no_overflow_keeps_carry_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |=> (Cout == 1'b0)
    );

// When the input MSB is set, the outputs split into high and low bytes.
    check_msb_set_splits_high_and_low_bytes: assert property (
        @(posedge clk) (in[15] == 1'b1) |-> ((out_hi == in[15:8]) && (out_lo == in[7:0]))
    );

// Counter clears when the increment condition is not met.
    check_counter_clear: assert property (
        @(posedge clk) disable iff (rst)
        ~(down_grant & ~timeout) |=> (counter == '0)
    );

// Counter state follows the RTL next-state function each cycle.
    check_next_state_matches_rtl: assert property (
        @(posedge clk)
        1'b1 |=> (out == ($past(load) ? 3'b000 :
                          ($past(up_down) ? ($past(out) + 3'b001) :
                                            ($past(out) - 3'b001))))
    );

// A load request clears the counter to zero on the next cycle.
    check_load_clears_out: assert property (
        @(posedge clk)
        load |=> (out == 3'b000)
    );

// With load low and up_down high, the counter increments by one.
    check_count_up: assert property (
        @(posedge clk)
        (!load && up_down) |=> (out == ($past(out) + 3'b001))
    );

// With load low and up_down low, the counter decrements by one.
    check_count_down: assert property (
        @(posedge clk)
        (!load && !up_down) |=> (out == ($past(out) - 3'b001))
    );

// Counting up wraps from 7 back to 0.
    check_count_up_wrap: assert property (
        @(posedge clk)
        (!load && up_down && (out == 3'b111)) |=> (out == 3'b000)
    );

// Counting down wraps from 0 back to 7.
    check_count_down_wrap: assert property (
        @(posedge clk)
        (!load && !up_down && (out == 3'b000)) |=> (out == 3'b111)
    );

// Sum output is the XOR of the three inputs.
    check_sum_xor: assert property (
        @(posedge clk) (S == (A ^ B ^ Ci))
    );

// Carry output matches the implemented carry equation.
    check_carry_logic: assert property (
        @(posedge clk) (Co == ((A & B) | ((A ^ B) & Ci)))
    );

// The output pair equals the 2-bit arithmetic sum of the inputs.
    check_binary_sum: assert property (
        @(posedge clk) ({Co, S} == ({1'b0, A} + {1'b0, B} + {1'b0, Ci}))
    );

// All-zero inputs produce zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge clk)
        ((A == 1'b0) && (B == 1'b0) && (Ci == 1'b0))
        |-> ((S == 1'b0) && (Co == 1'b0))
    );

// Exactly one high input produces sum without carry.
    check_single_one_case: assert property (
        @(posedge clk)
        (((A == 1'b1) && (B == 1'b0) && (Ci == 1'b0)) ||
         ((A == 1'b0) && (B == 1'b1) && (Ci == 1'b0)) ||
         ((A == 1'b0) && (B == 1'b0) && (Ci == 1'b1)))
        |-> ((S == 1'b1) && (Co == 1'b0))
    );

// Exactly two high inputs produce carry without sum.
    check_two_one_case: assert property (
        @(posedge clk)
        (((A == 1'b1) && (B == 1'b1) && (Ci == 1'b0)) ||
         ((A == 1'b1) && (B == 1'b0) && (Ci == 1'b1)) ||
         ((A == 1'b0) && (B == 1'b1) && (Ci == 1'b1)))
        |-> ((S == 1'b0) && (Co == 1'b1))
    );

// All-one inputs produce both sum and carry.
    check_all_one_case: assert property (
        @(posedge clk)
        ((A == 1'b1) && (B == 1'b1) && (Ci == 1'b1))
        |-> ((S == 1'b1) && (Co == 1'b1))
    );

// sel=0 maps to bit 0.
    check_decode_sel_0: assert property (
        @(posedge clk) (sel == 4'h0) |-> (out == 16'h0001)
    );

// sel=1 maps to bit 1.
    check_decode_sel_1: assert property (
        @(posedge clk) (sel == 4'h1) |-> (out == 16'h0002)
    );

// sel=2 maps to bit 2.
    check_decode_sel_2: assert property (
        @(posedge clk) (sel == 4'h2) |-> (out == 16'h0004)
    );

// sel=3 maps to bit 3.
    check_decode_sel_3: assert property (
        @(posedge clk) (sel == 4'h3) |-> (out == 16'h0008)
    );

// sel=4 maps to bit 4.
    check_decode_sel_4: assert property (
        @(posedge clk) (sel == 4'h4) |-> (out == 16'h0010)
    );

// sel=5 maps to bit 5.
    check_decode_sel_5: assert property (
        @(posedge clk) (sel == 4'h5) |-> (out == 16'h0020)
    );

// sel=6 maps to bit 6.
    check_decode_sel_6: assert property (
        @(posedge clk) (sel == 4'h6) |-> (out == 16'h0040)
    );

// sel=7 maps to bit 7.
    check_decode_sel_7: assert property (
        @(posedge clk) (sel == 4'h7) |-> (out == 16'h0080)
    );

// sel=8 maps to bit 8.
    check_decode_sel_8: assert property (
        @(posedge clk) (sel == 4'h8) |-> (out == 16'h0100)
    );

// sel=9 maps to bit 9.
    check_decode_sel_9: assert property (
        @(posedge clk) (sel == 4'h9) |-> (out == 16'h0200)
    );

// sel=10 maps to bit 10.
    check_decode_sel_a: assert property (
        @(posedge clk) (sel == 4'hA) |-> (out == 16'h0400)
    );

// sel=11 maps to bit 11.
    check_decode_sel_b: assert property (
        @(posedge clk) (sel == 4'hB) |-> (out == 16'h0800)
    );

// sel=12 maps to bit 12.
    check_decode_sel_c: assert property (
        @(posedge clk) (sel == 4'hC) |-> (out == 16'h1000)
    );

// sel=13 maps to bit 13.
    check_decode_sel_d: assert property (
        @(posedge clk) (sel == 4'hD) |-> (out == 16'h2000)
    );

// sel=14 maps to bit 14.
    check_decode_sel_e: assert property (
        @(posedge clk) (sel == 4'hE) |-> (out == 16'h4000)
    );

// sel=15 maps to bit 15.
    check_decode_sel_f: assert property (
        @(posedge clk) (sel == 4'hF) |-> (out == 16'h8000)
    );

// Unknown select values drive the default zero output.
    check_unknown_sel_default_zero: assert property (
        @(posedge clk) $isunknown(sel) |-> (out == 16'h0000)
    );

// Output is always one-hot or all zero.
    check_out_onehot0: assert property (
        @(posedge clk) $onehot0(out)
    );

// Addition opcode drives the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk) (opcode == 3'b000) |-> ({8'h00, result} == ((A + B) & 16'h00FF))
    );

// Subtraction opcode drives the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk) (opcode == 3'b001) |-> ({8'h00, result} == ((A - B) & 16'h00FF))
    );

// Invalid opcodes drive result to zero.
    check_default_result_zero: assert property (
        @(posedge clk) (opcode[2] == 1'b1) |-> (result == 8'h00)
    );

// q captures a 1 from d on the following clock edge.
    check_q_captures_high_d: assert property (
        @(posedge clk) d |=> q
    );

// q captures a 0 from d on the following clock edge.
    check_q_captures_low_d: assert property (
        @(posedge clk) !d |=> !q
    );

// RTL is combinational and has no reset; assertions are sampled on clk.

    // When M is 0, Y follows the sum path A + B.
    check_mode_zero_sum_path: assert property (
        @(posedge clk) !M |-> (Y == (A + B))
    );

// When M is 1, Y follows the implemented temp_diff expression.
    check_mode_one_direct_path: assert property (
        @(posedge clk) M |-> (Y == (A - ((~B) + 4'b0001)))
    );

// Across both modes, the implemented logic reduces to A + B modulo 16.
    check_output_matches_effective_addition: assert property (
        @(posedge clk) Y == (A + B)
    );

// With B equal to zero, the output matches A.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> (Y == A)
    );

// With A equal to zero, the output matches B.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> (Y == B)
    );

// The least-significant output bit matches the addition XOR bit.
    check_lsb_matches_sum: assert property (
        @(posedge clk) Y[0] == (A[0] ^ B[0])
    );

// Y matches the implemented A211OI logic.
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~((A1 & A2) | B1 | C1)
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        B1 |-> !Y
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        C1 |-> !Y
    );

// A1 and A2 high together force the NOR output low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && A2) |-> !Y
    );

// Y high means all NOR inputs are inactive.
    check_y_high_requires_all_nor_inputs_low: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |-> (!B1 && !C1 && !(A1 && A2))
    );

// If all NOR inputs are low, Y must be high.
    check_all_nor_inputs_low_gives_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (!B1 && !C1 && !(A1 && A2)) |-> Y
    );

// Sum must match the XOR of the three inputs.
    check_sum_function: assert property (
        @(posedge clk) s == (a ^ b ^ cin)
    );

// Carry-out must match the implemented carry equation.
    check_carry_function: assert property (
        @(posedge clk) cout == ((a & b) | (cin & (a ^ b)))
    );

// All-zero inputs must produce zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge clk) (!a && !b && !cin) |-> (!s && !cout)
    );

// Exactly one high input must produce sum high and carry low.
    check_one_hot_case: assert property (
        @(posedge clk)
        ((a && !b && !cin) || (!a && b && !cin) || (!a && !b && cin))
        |-> (s && !cout)
    );

// Exactly two high inputs must produce sum low and carry high.
    check_two_hot_case: assert property (
        @(posedge clk)
        ((a && b && !cin) || (a && !b && cin) || (!a && b && cin))
        |-> (!s && cout)
    );

// All-high inputs must produce sum high and carry high.
    check_all_high_case: assert property (
        @(posedge clk) (a && b && cin) |-> (s && cout)
    );

// sel=00 routes in[0] to out.
    check_select_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// sel=01 routes in[1] to out.
    check_select_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// sel=10 routes in[2] to out.
    check_select_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// sel=11 routes in[3] to out.
    check_select_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Sum matches the operation taken on the previous clock edge.
    check_sum_matches_previous_cycle_operation: assert property (
        @(posedge clk)
        1'b1 |=> (sum == ($past(rst) ? 16'sd0 : ($past(a) + $past(b))))
    );

// A reset cycle drives sum to zero.
    check_reset_clears_sum: assert property (
        @(posedge clk)
        rst |=> (sum == 16'sd0)
    );

// A non-reset cycle loads the previous sum of a and b.
    check_sum_updates_after_nonreset_cycle: assert property (
        @(posedge clk) disable iff (rst)
        !rst |=> (sum == ($past(a) + $past(b)))
    );

// With a equal to zero, sum passes through the previous value of b.
    check_zero_a_passes_b: assert property (
        @(posedge clk) disable iff (rst)
        (!rst && (a == 16'sd0)) |=> (sum == $past(b))
    );

// With b equal to zero, sum passes through the previous value of a.
    check_zero_b_passes_a: assert property (
        @(posedge clk) disable iff (rst)
        (!rst && (b == 16'sd0)) |=> (sum == $past(a))
    );

// Addition selects the low 4 bits of num1 + num2.
    check_add_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 2'b00) |-> (result == ((num1 + num2) & 4'hF))
    );

// Subtraction selects the low 4 bits of num1 - num2.
    check_sub_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 2'b01) |-> (result == ((num1 - num2) & 4'hF))
    );

// Overflow never asserts in this implementation.
    check_overflow_always_low: assert property (
        @(posedge clk) disable iff (rst)
        (overflow == 1'b0)
    );

// AB=00 drives only bit 0 high.
    check_decode_00: assert property (
        @(posedge clk) (AB == 2'b00) |-> (Y == 16'b0000000000000001)
    );

// AB=01 drives only bit 1 high.
    check_decode_01: assert property (
        @(posedge clk) (AB == 2'b01) |-> (Y == 16'b0000000000000010)
    );

// AB=10 drives only bit 2 high.
    check_decode_10: assert property (
        @(posedge clk) (AB == 2'b10) |-> (Y == 16'b0000000000000100)
    );

// AB=11 drives only bit 3 high.
    check_decode_11: assert property (
        @(posedge clk) (AB == 2'b11) |-> (Y == 16'b0000000000001000)
    );

// Unused upper outputs are always low.
    check_upper_bits_zero: assert property (
        @(posedge clk) Y[15:4] == 12'b000000000000
    );

// Exactly one lower output bit is asserted.
    check_lower_nibble_onehot: assert property (
        @(posedge clk) $onehot(Y[3:0])
    );

// Y must always equal the 16-bit sum of A and B.
    check_sum_matches_inputs: assert property (
        @(posedge clk) Y == (A + B)
    );

// Adding zero on B must pass A through unchanged.
    check_zero_on_b: assert property (
        @(posedge clk) (B == 16'h0000) |-> (Y == A)
    );

// Adding zero on A must pass B through unchanged.
    check_zero_on_a: assert property (
        @(posedge clk) (A == 16'h0000) |-> (Y == B)
    );

// Complementary inputs must sum to all ones.
    check_complementary_inputs_all_ones: assert property (
        @(posedge clk) (B == ~A) |-> (Y == 16'hFFFF)
    );

// Adding one to all ones must wrap around to zero.
    check_max_plus_one_wraps: assert property (
        @(posedge clk) ((A == 16'hFFFF) && (B == 16'h0001)) |-> (Y == 16'h0000)
    );

// The least-significant sum bit must match A[0] xor B[0].
    check_lsb_sum_bit: assert property (
        @(posedge clk) Y[0] == (A[0] ^ B[0])
    );

// X matches the OR of A, B, and the NAND of C_N and D_N.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A high forces X high.
    check_a_forces_x_high: assert property (
        @(posedge clk) A |-> (X == 1'b1)
    );

// B high forces X high.
    check_b_forces_x_high: assert property (
        @(posedge clk) B |-> (X == 1'b1)
    );

// C_N low forces X high through the NAND term.
    check_c_n_low_forces_x_high: assert property (
        @(posedge clk) !C_N |-> (X == 1'b1)
    );

// D_N low forces X high through the NAND term.
    check_d_n_low_forces_x_high: assert property (
        @(posedge clk) !D_N |-> (X == 1'b1)
    );

// X can be low only when A and B are low and both NAND inputs are high.
    check_x_low_only_in_all_inactive_case: assert property (
        @(posedge clk) !X |-> (!A && !B && C_N && D_N)
    );

// With A and B low, X reduces to the NAND of C_N and D_N.
    check_ab_low_reduces_to_nand: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~(C_N & D_N))
    );

// When enabled, result captures the sampled bitwise OR of A and B.
    check_enabled_or_update: assert property (
        @(posedge clk) enable |=> (result == $past(A | B))
    );

// If A is zero when enabled, result captures B.
    check_a_zero_passes_b: assert property (
        @(posedge clk) (enable && (A == 8'h00)) |=> (result == $past(B))
    );

// If B is zero when enabled, result captures A.
    check_b_zero_passes_a: assert property (
        @(posedge clk) (enable && (B == 8'h00)) |=> (result == $past(A))
    );

// If both inputs are equal when enabled, result captures that value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (enable && (A == B)) |=> (result == $past(A))
    );

// If A and B have no overlapping 1 bits when enabled, OR matches XOR.
    check_disjoint_inputs_match_xor: assert property (
        @(posedge clk) (enable && ((A & B) == 8'h00)) |=> (result == ($past(A) ^ $past(B)))
    );

// If all 1 bits of A are already present in B when enabled, result captures B.
    check_a_subset_of_b: assert property (
        @(posedge clk) (enable && ((A & B) == A)) |=> (result == $past(B))
    );

// If all 1 bits of B are already present in A when enabled, result captures A.
    check_b_subset_of_a: assert property (
        @(posedge clk) (enable && ((A & B) == B)) |=> (result == $past(A))
    );

// If either input is all ones when enabled, result becomes all ones.
    check_all_ones_dominates: assert property (
        @(posedge clk) (enable && ((A == 8'hFF) || (B == 8'hFF))) |=> (result == 8'hFF)
    );

// No RTL clock or reset; this combinational mux is sampled on an external clock.

    // sel1=1 and sel0=1 routes in0 to out.
    check_sel11_selects_in0: assert property (
        @(posedge clk) (sel1 && sel0) |-> (out == in0)
    );

// sel1=1 and sel0=0 routes in1 to out.
    check_sel10_selects_in1: assert property (
        @(posedge clk) (sel1 && !sel0) |-> (out == in1)
    );

// sel1=0 and sel0=1 routes in2 to out.
    check_sel01_selects_in2: assert property (
        @(posedge clk) (!sel1 && sel0) |-> (out == in2)
    );

// sel1=0 and sel0=0 routes in3 to out.
    check_sel00_selects_in3: assert property (
        @(posedge clk) (!sel1 && !sel0) |-> (out == in3)
    );

// Tap must match the RTL combinational expression.
    check_tap_equation: assert property (
        @(posedge clk)
        tap === ((vin - gnd) ? vin : gnd)
    );

// When vin and gnd are equal binary values, tap selects gnd.
    check_equal_inputs_select_gnd: assert property (
        @(posedge clk)
        (((vin === 1'b0) && (gnd === 1'b0)) || ((vin === 1'b1) && (gnd === 1'b1)))
        |-> (tap === gnd)
    );

// When vin and gnd differ as binary values, tap selects vin.
    check_different_inputs_select_vin: assert property (
        @(posedge clk)
        (((vin === 1'b0) && (gnd === 1'b1)) || ((vin === 1'b1) && (gnd === 1'b0)))
        |-> (tap === vin)
    );

// id_control_signals captures if_control_signals on the previous rising edge.
    check_control_transfer: assert property (
        @(posedge clock) 1'b1 |=> (id_control_signals == $past(if_control_signals))
    );

// eq matches the equality comparison of A and B.
    check_eq_function: assert property (
        @(posedge clk) eq === (A == B)
    );

// gt matches the greater-than comparison of A and B.
    check_gt_function: assert property (
        @(posedge clk) gt === (A > B)
    );

// Equal inputs drive eq high and gt low.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (eq && !gt)
    );

// A greater than B drives gt high and eq low.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (gt && !eq)
    );

// A less than B drives both outputs low.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!eq && !gt)
    );

// eq and gt are never asserted at the same time.
    check_outputs_mutex: assert property (
        @(posedge clk) !(eq && gt)
    );

// During CK low, the gated output must be low.
    check_eck_low_during_ck_low: assert property (
        @(posedge CK) ECK == 1'b0
    );

// During CK high, the gated output must match E & SE.
    check_eck_matches_enables_during_ck_high: assert property (
        @(negedge CK) ECK == (E & SE)
    );

// Active-low reset forces data_out to zero.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !reset |-> (data_out == 32'd0)
    );

// When load is high, data_out captures data_in on the next registered state.
    check_load_captures_data_in: assert property (
        @(posedge clk) disable iff (!reset) load |=> (data_out == $past(data_in))
    );

// When load is low, data_out holds its previous value.
    check_no_load_holds_data_out: assert property (
        @(posedge clk) disable iff (!reset) !load |=> (data_out == $past(data_out))
    );

// A sampled reset must leave ENCLK low on the following clock.
    check_reset_clears_next_cycle: assert property (
        @(posedge CLK) reset |=> (ENCLK == 1'b0)
    );

// From a high state, full enable must toggle ENCLK low by the next sample.
    check_toggle_high_to_low_when_enabled: assert property (
        @(posedge CLK) disable iff (reset)
        (EN && TE && ENCLK) |=> (ENCLK == 1'b0)
    );

// From a low state, missing either enable keeps ENCLK low.
    check_low_holds_without_full_enable: assert property (
        @(posedge CLK) disable iff (reset)
        ((!EN || !TE) && !ENCLK) |=> (ENCLK == 1'b0)
    );

// Without full enable, ENCLK cannot rise by the next sampled clock.
    check_no_rise_without_full_enable: assert property (
        @(posedge CLK) disable iff (reset)
        (!EN || !TE) |=> !$rose(ENCLK)
    );

// A sampled rise must come from a prior low state with both enables high.
    check_rise_has_valid_cause: assert property (
        @(posedge CLK) disable iff (reset)
        $rose(ENCLK) |-> (!$past(reset) && $past(EN) && $past(TE) && !$past(ENCLK))
    );

// Overall output matches the implemented 4:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        out == (sel[1] ? (sel[0] ? in3 : in2) : (sel[0] ? in1 : in0))
    );

// sel=00 routes in0 to out.
    check_sel00_routes_in0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel01_routes_in1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel10_routes_in2: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel11_routes_in3: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == in3)
    );

// sel[1]=0 selects between the lower input pair.
    check_lower_pair_selection: assert property (
        @(posedge clk)
        (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

// sel[1]=1 selects between the upper input pair.
    check_upper_pair_selection: assert property (
        @(posedge clk)
        (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

// Reset clears all state and outputs.
    reset_clears_state: assert property (
        @(posedge clk)
        reset |-> (count == 32'd0) &&
                  (prescaler == 4'd0) &&
                  (prev_in == 32'd0) &&
                  (curr_in == 32'd0) &&
                  (frequency == 16'd0) &&
                  (threshold_exceeded == 1'b0)
    );

// Before the window ends, frequency holds its value.
    frequency_holds_before_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count < 32'd100000000) |=> (frequency == $past(frequency))
    );

// Reaching the window limit updates the flag from the prior frequency comparison.
    threshold_flag_updates_at_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count >= 32'd100000000)
        |=> (threshold_exceeded == ($past(frequency) > $past(threshold)))
    );

// Before the window ends, the threshold flag holds its value.
    threshold_flag_holds_before_window_end: assert property (
        @(posedge clk) disable iff (reset)
        (count < 32'd100000000) |=> (threshold_exceeded == $past(threshold_exceeded))
    );

// sum reflects the 8-bit signed addition of A and B.
    check_sum_matches_addition: assert property (
        @(posedge clk) sum == (A + B)
    );

// With A equal to zero, the outputs mirror B.
    check_zero_left_identity: assert property (
        @(posedge clk) (A == 8'sd0) |-> ((sum == B) && (C == B[7]))
    );

// With B equal to zero, the outputs mirror A.
    check_zero_right_identity: assert property (
        @(posedge clk) (B == 8'sd0) |-> ((sum == A) && (C == A[7]))
    );

// Zero plus zero produces a zero result and clear C.
    check_zero_plus_zero: assert property (
        @(posedge clk) ((A == 8'sd0) && (B == 8'sd0)) |-> ((sum == 8'sd0) && (C == 1'b0))
    );

// When enabled, the next-cycle output matches the sampled input.
    check_capture_when_enabled: assert property (
        @(posedge clk) en |=> (data_out == $past(data_in))
    );

// When disabled, the next-cycle output is forced low.
    check_drive_low_when_disabled: assert property (
        @(posedge clk) !en |=> (data_out == 1'b0)
    );

// Each cycle, the output follows the prior-cycle enable/data function.
    check_registered_output_function: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($past(en) ? $past(data_in) : 1'b0))
    );

// Output matches the RTL mux expression on every sample.
    check_selected_out_matches_mux: assert property (
        @(posedge clk) selected_out === (select ? input2 : input1)
    );

// A low select routes input1 to the output.
    check_select_low_routes_input1: assert property (
        @(posedge clk) (select === 1'b0) |-> (selected_out === input1)
    );

// A high select routes input2 to the output.
    check_select_high_routes_input2: assert property (
        @(posedge clk) (select === 1'b1) |-> (selected_out === input2)
    );

// If both inputs are identical, the output matches that common value.
    check_equal_inputs_match_output: assert property (
        @(posedge clk) (input1 === input2) |-> (selected_out === input1)
    );

// A select change with stable data updates the output to the newly selected input.
    check_select_change_updates_output: assert property (
        @(posedge clk) ($changed(select) && $stable(input1) && $stable(input2)) |-> (selected_out === (select ? input2 : input1))
    );

// LOAD_EN captures DATA_IN on the next cycle.
    check_load_captures_input: assert property (
        @(posedge CLK) LOAD_EN |=> (DATA_OUT == $past(DATA_IN))
    );

// LOAD_EN has priority over SHIFT_EN when both are high.
    check_load_priority_over_shift: assert property (
        @(posedge CLK) (LOAD_EN && SHIFT_EN) |=> (DATA_OUT == $past(DATA_IN))
    );

// SHIFT_EN rotates the register left with wraparound when LOAD_EN is low.
    check_shift_rotate_left: assert property (
        @(posedge CLK) (!LOAD_EN && SHIFT_EN) |=> (
            (DATA_OUT[3] == $past(DATA_OUT[2])) &&
            (DATA_OUT[2] == $past(DATA_OUT[1])) &&
            (DATA_OUT[1] == $past(DATA_OUT[0])) &&
            (DATA_OUT[0] == $past(DATA_OUT[3]))
        )
    );

// With both enables low, DATA_OUT holds its value.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD_EN && !SHIFT_EN) |=> (DATA_OUT == $past(DATA_OUT))
    );

// The RTL always drives a 16-bit value that is zero-extended to 32 bits.
    check_upper_half_zero: assert property (
        @(posedge clk) data_out[31:16] == 16'h0000
    );

// load 0 places a sign-replicated byte in the low 16 bits.
    check_load0_byte_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd0) |-> (data_out == {16'h0000, {8{data_in[7]}}, data_in[7:0]})
    );

// load 1 places a sign-replicated nibble in the low 16 bits.
    check_load1_nibble_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd1) |-> (data_out == {16'h0000, {12{data_in[3]}}, data_in[3:0]})
    );

// load 2 places a sign-replicated 11-bit field in the low 16 bits.
    check_load2_eleven_bit_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd2) |-> (data_out == {16'h0000, {5{data_in[10]}}, data_in[10:0]})
    );

// load 3 zero-extends data_in[3:0] into data_out.
    check_load3_nibble_zero_extend: assert property (
        @(posedge clk)
        (load == 3'd3) |-> (data_out == {28'b0, data_in[3:0]})
    );

// load 4 zero-extends data_in[7:0] into data_out.
    check_load4_byte_zero_extend: assert property (
        @(posedge clk)
        (load == 3'd4) |-> (data_out == {24'b0, data_in[7:0]})
    );

// load 5 places a sign-replicated 5-bit field in the low 16 bits.
    check_load5_five_bit_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd5) |-> (data_out == {16'h0000, {11{data_in[4]}}, data_in[4:0]})
    );

// load 6 or 7 places data_in[4:2] in the low three bits.
    check_load67_extract_bits_4_to_2: assert property (
        @(posedge clk)
        ((load == 3'd6) || (load == 3'd7)) |-> (data_out == {29'b0, data_in[4:2]})
    );

// Output must always be the XOR of the two inputs.
    check_xor_function: assert property (
        @(posedge clk) Sgn_Info == (Sgn_X ^ Sgn_Y)
    );

// 0 ^ 0 must produce 0.
    check_xor_00_case: assert property (
        @(posedge clk) (Sgn_X == 1'b0 && Sgn_Y == 1'b0) |-> (Sgn_Info == 1'b0)
    );

// 0 ^ 1 must produce 1.
    check_xor_01_case: assert property (
        @(posedge clk) (Sgn_X == 1'b0 && Sgn_Y == 1'b1) |-> (Sgn_Info == 1'b1)
    );

// 1 ^ 0 must produce 1.
    check_xor_10_case: assert property (
        @(posedge clk) (Sgn_X == 1'b1 && Sgn_Y == 1'b0) |-> (Sgn_Info == 1'b1)
    );

// 1 ^ 1 must produce 0.
    check_xor_11_case: assert property (
        @(posedge clk) (Sgn_X == 1'b1 && Sgn_Y == 1'b1) |-> (Sgn_Info == 1'b0)
    );

// Count must be zero whenever reset is asserted.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 4'd0)
    );

// Count is still zero on the first sampled cycle after reset was low.
    check_post_reset_sample_is_zero: assert property (
        @(posedge clk) disable iff (!reset)
        $past(!reset) |-> (count == 4'd0)
    );

// After a reset-high cycle, count either increments or was asynchronously cleared to zero.
    check_count_increments_or_async_clears: assert property (
        @(posedge clk) disable iff (!reset)
        $past(reset) |-> ((count == 4'd0) || (count == ($past(count) + 4'd1)))
    );

// COUT must implement the AND of A and B.
    check_cout_matches_and: assert property (
        @(posedge clk) COUT === (A & B)
    );

// SUM must implement the XOR of A and B.
    check_sum_matches_xor: assert property (
        @(posedge clk) SUM === (A ^ B)
    );

// When both inputs are 0, both outputs must be 0.
    check_zero_plus_zero: assert property (
        @(posedge clk)
        ((A === 1'b0) && (B === 1'b0)) |-> ((COUT === 1'b0) && (SUM === 1'b0))
    );

// When exactly one input is 1, SUM must be 1 and COUT must be 0.
    check_one_hot_input_sum_only: assert property (
        @(posedge clk)
        (((A === 1'b0) && (B === 1'b1)) || ((A === 1'b1) && (B === 1'b0)))
        |-> ((COUT === 1'b0) && (SUM === 1'b1))
    );

// When both inputs are 1, COUT must be 1 and SUM must be 0.
    check_one_plus_one_carry_only: assert property (
        @(posedge clk)
        ((A === 1'b1) && (B === 1'b1)) |-> ((COUT === 1'b1) && (SUM === 1'b0))
    );

// Duty-cycle stabilizer output is tied high.
    check_adc_cdcs_constant_high: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        adc_cdcs_o == 1'b1
    );

// ADC clock source output is tied to 2'b10.
    check_adc_clk_source_constant: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        adc_clk_source == 2'b10
    );

// Channel A output matches the prior sampled input transform.
    check_adc_dat_a_transform: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o == { $past(adc_dat_a_i[13]), ~$past(adc_dat_a_i[12:0]) })
    );

// Channel B output matches the prior sampled input transform.
    check_adc_dat_b_transform: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o == { $past(adc_dat_b_i[13]), ~$past(adc_dat_b_i[12:0]) })
    );

// Channel A sign bit is preserved from the sampled input.
    check_adc_dat_a_sign_preserved: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o[13] == $past(adc_dat_a_i[13]))
    );

// Channel A lower bits are inverted from the sampled input.
    check_adc_dat_a_low_bits_inverted: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_a_o[12:0] == ~$past(adc_dat_a_i[12:0]))
    );

// Channel B sign bit is preserved from the sampled input.
    check_adc_dat_b_sign_preserved: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o[13] == $past(adc_dat_b_i[13]))
    );

// Channel B lower bits are inverted from the sampled input.
    check_adc_dat_b_low_bits_inverted: assert property (
        @(posedge adc_clk) disable iff (!adc_rst_i)
        1'b1 |=> (adc_dat_b_o[12:0] == ~$past(adc_dat_b_i[12:0]))
    );

// out matches the implemented combinational expression.
    check_out_matches_implemented_function: assert property (
        @(posedge clk) out == {(a[2] & b), (a[3] & b)}
    );

// The upper nibble is b masked by a[2].
    check_upper_nibble_matches_a2_mask: assert property (
        @(posedge clk) out[7:4] == (a[2] & b)
    );

// The lower nibble is b masked by a[3].
    check_lower_nibble_matches_a3_mask: assert property (
        @(posedge clk) out[3:0] == (a[3] & b)
    );

// Zero on b forces the full output low.
    check_zero_output_when_b_zero: assert property (
        @(posedge clk) (b == 4'h0) |-> (out == 8'h00)
    );

// Zero on a[3:2] forces the full output low.
    check_zero_output_when_a23_zero: assert property (
        @(posedge clk) (a[3:2] == 2'b00) |-> (out == 8'h00)
    );

// X must match the complete combinational function.
    check_full_function: assert property (
        @(posedge clk) X == ((A1 ? A2 : (A3 ^ A4)) ^ B1)
    );

// When A1 selects A2 and B1 is low, X matches A2.
    check_a2_selected_passthrough: assert property (
        @(posedge clk) (A1 && !B1) |-> (X == A2)
    );

// When A1 selects A2 and B1 is high, X is the inverse of A2.
    check_a2_selected_inverted: assert property (
        @(posedge clk) (A1 && B1) |-> (X == ~A2)
    );

// When A1 selects the XOR path and B1 is low, X matches A3 ^ A4.
    check_xor_selected_passthrough: assert property (
        @(posedge clk) (!A1 && !B1) |-> (X == (A3 ^ A4))
    );

// When A1 selects the XOR path and B1 is high, X is the inverse of A3 ^ A4.
    check_xor_selected_inverted: assert property (
        @(posedge clk) (!A1 && B1) |-> (X == ~(A3 ^ A4))
    );

// With B1 low, X passes the selected value unchanged.
    check_b1_low_passthrough: assert property (
        @(posedge clk) (!B1) |-> (X == (A1 ? A2 : (A3 ^ A4)))
    );

// With B1 high, X is the inverse of the selected value.
    check_b1_high_inverts_selected_value: assert property (
        @(posedge clk) B1 |-> (X == ~((A1 ? A2 : (A3 ^ A4))))
    );

// Reset clears the counter on the next sampled clock.
    reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

// With reset low and up_down high, the counter increments by one.
    count_up_step: assert property (
        @(posedge clk) disable iff (reset)
        up_down |=> (out == ($past(out) + 4'd1))
    );

// With reset low and up_down low, the counter decrements by one.
    count_down_step: assert property (
        @(posedge clk) disable iff (reset)
        !up_down |=> (out == ($past(out) - 4'd1))
    );

// Counting up from 4'hF wraps around to 4'h0.
    up_wraps_from_f_to_0: assert property (
        @(posedge clk) disable iff (reset)
        up_down && (out == 4'hF) |=> (out == 4'h0)
    );

// Counting down from 4'h0 wraps around to 4'hF.
    down_wraps_from_0_to_f: assert property (
        @(posedge clk) disable iff (reset)
        !up_down && (out == 4'h0) |=> (out == 4'hF)
    );

// Y must be high when all functional inputs are low.
    check_all_low_drives_high: assert property (
        @(posedge clk)
        ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (Y == 1'b1)
    );

// Y must be low whenever any functional input is high.
    check_any_high_drives_low: assert property (
        @(posedge clk)
        ((A_N == 1'b1) || (B_N == 1'b1) || (C == 1'b1) || (D == 1'b1)) |-> (Y == 1'b0)
    );

// A high Y requires all functional inputs to be low.
    check_y_high_implies_all_low: assert property (
        @(posedge clk)
        (Y == 1'b1) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b0) && (D == 1'b0))
    );

// A low Y requires at least one functional input to be high.
    check_y_low_implies_any_high: assert property (
        @(posedge clk)
        (Y == 1'b0) |-> ((A_N == 1'b1) || (B_N == 1'b1) || (C == 1'b1) || (D == 1'b1))
    );

// A_N high alone is sufficient to force Y low.
    check_a_high_forces_low: assert property (
        @(posedge clk)
        (A_N == 1'b1) |-> (Y == 1'b0)
    );

// B_N high alone is sufficient to force Y low.
    check_b_high_forces_low: assert property (
        @(posedge clk)
        (B_N == 1'b1) |-> (Y == 1'b0)
    );

// C high alone is sufficient to force Y low.
    check_c_high_forces_low: assert property (
        @(posedge clk)
        (C == 1'b1) |-> (Y == 1'b0)
    );

// D high alone is sufficient to force Y low.
    check_d_high_forces_low: assert property (
        @(posedge clk)
        (D == 1'b1) |-> (Y == 1'b0)
    );

// Sum must mirror the internal S bus.
    check_sum_alias: assert property (
        @(posedge clk) Sum == S
    );

// FA0 sum must match the full-adder XOR equation.
    check_fa0_sum_function: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// FA0 carry must match the full-adder carry equation.
    check_fa0_carry_function: assert property (
        @(posedge clk) C[0] == ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))
    );

// FA1 sum must use C[0] as its carry-in.
    check_fa1_sum_function: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ C[0])
    );

// FA1 carry must match the full-adder carry equation.
    check_fa1_carry_function: assert property (
        @(posedge clk) C[1] == ((A[1] & B[1]) | (A[1] & C[0]) | (B[1] & C[0]))
    );

// FA2 sum must use C[1] as its carry-in.
    check_fa2_sum_function: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ C[1])
    );

// FA2 carry must match the full-adder carry equation.
    check_fa2_carry_function: assert property (
        @(posedge clk) C[2] == ((A[2] & B[2]) | (A[2] & C[1]) | (B[2] & C[1]))
    );

// FA3 sum must use C[2] as its carry-in.
    check_fa3_sum_function: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ C[2])
    );

// FA3 carry-out must match the full-adder carry equation.
    check_fa3_carry_function: assert property (
        @(posedge clk) Cout == ((A[3] & B[3]) | (A[3] & C[2]) | (B[3] & C[2]))
    );

// The full 5-bit result must equal A + B + Cin.
    check_overall_addition_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + {{4{1'b0}}, Cin})
    );

// Z matches the implemented combinational function.
    check_boolean_function: assert property (
        @(posedge clk) Z == ((~(AN & BN)) & C)
    );

// C low forces Z low.
    check_c_low_forces_z_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// AN and BN both high block the output when C is high.
    check_an_bn_high_block_output: assert property (
        @(posedge clk) (C && AN && BN) |-> !Z
    );

// AN low with C high makes Z high.
    check_an_low_allows_output: assert property (
        @(posedge clk) (C && !AN) |-> Z
    );

// BN low with C high makes Z high.
    check_bn_low_allows_output: assert property (
        @(posedge clk) (C && !BN) |-> Z
    );

// A high Z requires C to be high.
    check_z_high_requires_c_high: assert property (
        @(posedge clk) Z |-> C
    );

// A high Z requires the AN/BN AND term to be false.
    check_z_high_requires_inverted_and: assert property (
        @(posedge clk) Z |-> !(AN && BN)
    );

// SUM is the XOR of A, B, and CIN.
    check_sum_xor: assert property (
        @(posedge clk) SUM == (A ^ B ^ CIN)
    );

// COUT matches the carry logic implemented in the RTL.
    check_cout_logic: assert property (
        @(posedge clk) COUT == ((A & B) | (CIN & (A ^ B)))
    );

// The outputs together equal the 2-bit sum of the three 1-bit inputs.
    check_full_adder_result: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CIN})
    );

// When A and B are equal, SUM follows CIN.
    check_sum_matches_cin_when_ab_equal: assert property (
        @(posedge clk) (!(A ^ B)) |-> (SUM == CIN)
    );

// When A and B differ, SUM is the inverse of CIN.
    check_sum_inverts_cin_when_ab_differs: assert property (
        @(posedge clk) (A ^ B) |-> (SUM == ~CIN)
    );

// With CIN low, carry reduces to A AND B.
    check_cout_reduces_to_and_when_cin_low: assert property (
        @(posedge clk) (!CIN) |-> (COUT == (A & B))
    );

// With CIN high, carry reduces to A OR B.
    check_cout_reduces_to_or_when_cin_high: assert property (
        @(posedge clk) CIN |-> (COUT == (A | B))
    );

// If both A and B are low, carry must be low.
    check_cout_low_when_ab_low: assert property (
        @(posedge clk) ((!A) && (!B)) |-> (!COUT)
    );

// If both A and B are high, carry must be high.
    check_cout_high_when_ab_high: assert property (
        @(posedge clk) (A && B) |-> COUT
    );

// X must equal the 4-input AND of A, B, C, and D.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// When all four inputs are high, X must be high.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// If A is low, X must be low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (!A) |-> (!X)
    );

// If B is low, X must be low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (!B) |-> (!X)
    );

// If C is low, X must be low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (!C) |-> (!X)
    );

// If D is low, X must be low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (!D) |-> (!X)
    );

// A high X requires all four inputs to be high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

// Reset drives count to zero on the following cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// If reset remains asserted, count stays at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) rst |=> (rst -> (count == 4'd0))
    );

// After reset deasserts, the first sampled count is zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) rst |=> (!rst -> (count == 4'd0))
    );

// Across consecutive non-reset cycles, count increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) !rst |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_rollover: assert property (
        @(posedge clk) disable iff (rst) (!rst && (count == 4'hf)) |=> (count == 4'h0)
    );

// Equal inputs select only equal.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (equal && !greater_than && !less_than)
    );

// A greater than B selects only greater_than.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (!equal && greater_than && !less_than)
    );

// A less than B selects only less_than.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!equal && !greater_than && less_than)
    );

// equal and greater_than cannot be high together.
    check_equal_greater_mutex: assert property (
        @(posedge clk) !(equal && greater_than)
    );

// equal and less_than cannot be high together.
    check_equal_less_mutex: assert property (
        @(posedge clk) !(equal && less_than)
    );

// greater_than and less_than cannot be high together.
    check_greater_less_mutex: assert property (
        @(posedge clk) !(greater_than && less_than)
    );

// One result output must always be asserted.
    check_result_present: assert property (
        @(posedge clk) (equal || greater_than || less_than)
    );

// Overall output matches 4-bit addition with carry in.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Bit 0 sum is the XOR of A[0], B[0], and Cin.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 1 sum uses the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

// Bit 2 sum uses the carry out of the lower two bits.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]} + Cin) >= 3'd4))
    );

// Bit 3 sum uses the carry out of the lower three bits.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]} + Cin) >= 4'd8))
    );

// Cout is the carry out of the full 4-bit addition.
    check_cout_consistency: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

// Zero plus zero with no carry in produces zero.
    check_zero_addition: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == 5'd0)
    );

// Adding zero on B with no carry in passes A through.
    check_add_zero_rhs: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero on A with no carry in passes B through.
    check_add_zero_lhs: assert property (
        @(posedge clk) ((A == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, B})
    );

// With B at zero, Cin increments A by one.
    check_increment_with_cin: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b1)) |-> ({Cout, S} == ({1'b0, A} + 5'd1))
    );

// X equals the AND of all four inputs.
    check_output_matches_and: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All four high inputs drive X high.
    check_all_high_drives_output_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1)) |-> (X == 1'b1)
    );

// A low forces X low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

// B low forces X low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == 1'b0)
    );

// C low forces X low.
    check_c_low_forces_output_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == 1'b0)
    );

// D low forces X low.
    check_d_low_forces_output_low: assert property (
        @(posedge clk) (D == 1'b0) |-> (X == 1'b0)
    );

// A high X requires all four inputs high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1))
    );

// Y matches the implemented combinational function.
    check_output_function: assert property (
        @(posedge clk) Y == ((~(A | B)) & C_N & D_N)
    );

// A high forces the NOR stage low, so Y must be low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high forces the NOR stage low, so Y must be low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C_N low blocks the AND stage, so Y must be low.
    check_cn_low_forces_y_low: assert property (
        @(posedge clk) !C_N |-> !Y
    );

// D_N low blocks the AND stage, so Y must be low.
    check_dn_low_forces_y_low: assert property (
        @(posedge clk) !D_N |-> !Y
    );

// All enabling inputs produce a high output.
    check_enabling_inputs_drive_y_high: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> Y
    );

// A high output implies the required input combination.
    check_y_high_implies_input_combination: assert property (
        @(posedge clk) Y |-> (!A && !B && C_N && D_N)
    );

// Active-low reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset_n |-> (count == 4'b0000)
    );

// When enabled, the counter increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!reset_n)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset_n)
        !enable |=> (count == $past(count))
    );

// When enabled at its maximum value, the counter wraps to zero.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// dmem_wen_exmem is the prior-cycle dmem_wen_idex.
    check_dmem_wen_capture: assert property (
        @(posedge clk)
        1'b1 |=> (dmem_wen_exmem == $past(dmem_wen_idex))
    );

// rf_wen_exmem is the prior-cycle rf_wen_idex.
    check_rf_wen_capture: assert property (
        @(posedge clk)
        1'b1 |=> (rf_wen_exmem == $past(rf_wen_idex))
    );

// branch2_exmem is the prior-cycle branch2_idex.
    check_branch2_capture: assert property (
        @(posedge clk)
        1'b1 |=> (branch2_exmem == $past(branch2_idex))
    );

// mem2reg_exmem is the prior-cycle mem2reg_idex.
    check_mem2reg_capture: assert property (
        @(posedge clk)
        1'b1 |=> (mem2reg_exmem == $past(mem2reg_idex))
    );

// aluout_exmem is the prior-cycle aluout.
    check_aluout_capture: assert property (
        @(posedge clk)
        1'b1 |=> (aluout_exmem == $past(aluout))
    );

// flag_exmem is the prior-cycle flag.
    check_flag_capture: assert property (
        @(posedge clk)
        1'b1 |=> (flag_exmem == $past(flag))
    );

// rdata2_exmem is the prior-cycle rdata2_idex.
    check_rdata2_capture: assert property (
        @(posedge clk)
        1'b1 |=> (rdata2_exmem == $past(rdata2_idex))
    );

// rf_waddr_exmem is the prior-cycle rf_waddr.
    check_rf_waddr_capture: assert property (
        @(posedge clk)
        1'b1 |=> (rf_waddr_exmem == $past(rf_waddr))
    );

// s7_exmem is the prior-cycle s7_idex.
    check_s7_capture: assert property (
        @(posedge clk)
        1'b1 |=> (s7_exmem == $past(s7_idex))
    );

// extended_exmem is the prior-cycle extended_16_idex.
    check_extended_capture: assert property (
        @(posedge clk)
        1'b1 |=> (extended_exmem == $past(extended_16_idex))
    );

// branch_target_exmem is the prior-cycle branch_target_final_muxout.
    check_branch_target_capture: assert property (
        @(posedge clk)
        1'b1 |=> (branch_target_exmem == $past(branch_target_final_muxout))
    );

// nop_lw_exmem is the prior-cycle nop_lw_idex.
    check_nop_lw_capture: assert property (
        @(posedge clk)
        1'b1 |=> (nop_lw_exmem == $past(nop_lw_idex))
    );

// nop_sw_exmem is the prior-cycle nop_sw_idex.
    check_nop_sw_capture: assert property (
        @(posedge clk)
        1'b1 |=> (nop_sw_exmem == $past(nop_sw_idex))
    );

// pc_added_exmem is the prior-cycle pc_added_idex.
    check_pc_added_capture: assert property (
        @(posedge clk)
        1'b1 |=> (pc_added_exmem == $past(pc_added_idex))
    );

// jal_exmem is the prior-cycle jal_idex.
    check_jal_capture: assert property (
        @(posedge clk)
        1'b1 |=> (jal_exmem == $past(jal_idex))
    );

// sel=00 routes in[0] to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel === 2'b00) |-> (out === in[0])
    );

// sel=01 routes in[1] to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel === 2'b01) |-> (out === in[1])
    );

// sel=10 routes in[2] to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel === 2'b10) |-> (out === in[2])
    );

// sel=11 routes in[3] to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel === 2'b11) |-> (out === in[3])
    );

// Any non-matching select value drives the default output of 0.
    check_default_out_zero: assert property (
        @(posedge clk)
        !((sel === 2'b00) || (sel === 2'b01) || (sel === 2'b10) || (sel === 2'b11))
        |-> (out === 1'b0)
    );

// out always matches the mux case selection.
    check_full_mux_behavior: assert property (
        @(posedge clk)
        out === ((sel === 2'b00) ? in[0] :
                 (sel === 2'b01) ? in[1] :
                 (sel === 2'b10) ? in[2] :
                 (sel === 2'b11) ? in[3] :
                                   1'b0)
    );

// Addition opcode produces A + B.
    check_addition_result: assert property (
        @(posedge clk)
        (Op == 3'b000) |-> (result == (A + B))
    );

// Subtraction opcode produces A - B.
    check_subtraction_result: assert property (
        @(posedge clk)
        (Op == 3'b001) |-> (result == (A - B))
    );

// AND opcode produces A & B.
    check_and_result: assert property (
        @(posedge clk)
        (Op == 3'b010) |-> (result == (A & B))
    );

// OR opcode produces A | B.
    check_or_result: assert property (
        @(posedge clk)
        (Op == 3'b011) |-> (result == (A | B))
    );

// XOR opcode produces A ^ B.
    check_xor_result: assert property (
        @(posedge clk)
        (Op == 3'b100) |-> (result == (A ^ B))
    );

// Shift-left opcode produces A shifted left by one.
    check_shift_left_result: assert property (
        @(posedge clk)
        (Op == 3'b101) |-> (result == (A << 1))
    );

// Shift-right opcode produces A shifted right by one.
    check_shift_right_result: assert property (
        @(posedge clk)
        (Op == 3'b110) |-> (result == (A >> 1))
    );

// Result only uses the three encodings implemented in the RTL.
    check_result_encoding: assert property (
        @(posedge clk)
        (result == 2'b00) || (result == 2'b01) || (result == 2'b10)
    );

// If A has MSB set and B does not, result indicates A > B.
    check_msb_a_high_b_low: assert property (
        @(posedge clk)
        ((A[3] == 1'b1) && (B[3] == 1'b0)) |-> (result == 2'b01)
    );

// If B has MSB set and A does not, result indicates A < B.
    check_msb_a_low_b_high: assert property (
        @(posedge clk)
        ((A[3] == 1'b0) && (B[3] == 1'b1)) |-> (result == 2'b10)
    );

// When A is greater than B, result must indicate greater-than.
    check_a_greater_than_b_maps_to_01: assert property (
        @(posedge clk)
        (A > B) |-> (result == 2'b01)
    );

// When A is less than B, result must indicate less-than.
    check_a_less_than_b_maps_to_10: assert property (
        @(posedge clk)
        (A < B) |-> (result == 2'b10)
    );

// When A equals B, result must indicate equality.
    check_a_equal_b_maps_to_00: assert property (
        @(posedge clk)
        (A == B) |-> (result == 2'b00)
    );

// A greater-than result must correspond to A > B.
    check_result_01_implies_a_greater_than_b: assert property (
        @(posedge clk)
        (result == 2'b01) |-> (A > B)
    );

// A less-than result must correspond to A < B.
    check_result_10_implies_a_less_than_b: assert property (
        @(posedge clk)
        (result == 2'b10) |-> (A < B)
    );

// An equality result must correspond to A == B.
    check_result_00_implies_a_equal_b: assert property (
        @(posedge clk)
        (result == 2'b00) |-> (A == B)
    );

// Combined outputs match 1-bit addition of A, B, and CIN.
    check_full_adder_value: assert property (
        @(posedge clk) ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CIN}))
    );

// Carry-out is the majority function of the three inputs.
    check_carry_majority: assert property (
        @(posedge clk) (COUT == ((A & B) | (A & CIN) | (B & CIN)))
    );

// Sum is the odd-parity function of the three inputs.
    check_sum_odd_parity: assert property (
        @(posedge clk) (SUM == (A ^ B ^ CIN))
    );

// All-zero inputs produce zero outputs.
    check_zero_inputs: assert property (
        @(posedge clk) ((!A && !B && !CIN) |-> ({COUT, SUM} == 2'b00))
    );

// Exactly one asserted input produces sum without carry.
    check_single_high_input: assert property (
        @(posedge clk) ((({1'b0, A} + {1'b0, B} + {1'b0, CIN}) == 2'd1) |-> ({COUT, SUM} == 2'b01))
    );

// Exactly two asserted inputs produce carry without sum.
    check_two_high_inputs: assert property (
        @(posedge clk) ((({1'b0, A} + {1'b0, B} + {1'b0, CIN}) == 2'd2) |-> ({COUT, SUM} == 2'b10))
    );

// All-one inputs produce both carry and sum.
    check_all_high_inputs: assert property (
        @(posedge clk) ((A & B & CIN) |-> ({COUT, SUM} == 2'b11))
    );

// The register shifts prior contents and loads the prior serial input into bit 0.
    check_full_shift_update: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out == {$past(parallel_out[2:0]), $past(serial_in)}
    );

// Bit 3 takes the previous value of bit 2.
    check_bit3_shift: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[3] == $past(parallel_out[2])
    );

// Bit 2 takes the previous value of bit 1.
    check_bit2_shift: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[2] == $past(parallel_out[1])
    );

// Bit 1 takes the previous value of bit 0.
    check_bit1_shift: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[1] == $past(parallel_out[0])
    );

// Bit 0 loads the previous serial input.
    check_bit0_load: assert property (
        @(posedge shift)
        1'b1 |=> parallel_out[0] == $past(serial_in)
    );

// After four shift edges, the register reflects the last four serial inputs.
    check_last_four_serial_inputs: assert property (
        @(posedge shift)
        1'b1 ##1 1'b1 ##1 1'b1 ##1 1'b1 |=> parallel_out == {
            $past(serial_in,4),
            $past(serial_in,3),
            $past(serial_in,2),
            $past(serial_in,1)
        }
    );

// Input 00 selects only out0.
    check_decode_00: assert property (
        @(posedge clk) (in == 2'b00) |-> ({out3, out2, out1, out0} == 4'b0001)
    );

// Input 01 selects only out1.
    check_decode_01: assert property (
        @(posedge clk) (in == 2'b01) |-> ({out3, out2, out1, out0} == 4'b0010)
    );

// Input 10 selects only out2.
    check_decode_10: assert property (
        @(posedge clk) (in == 2'b10) |-> ({out3, out2, out1, out0} == 4'b0100)
    );

// Input 11 selects only out3.
    check_decode_11: assert property (
        @(posedge clk) (in == 2'b11) |-> ({out3, out2, out1, out0} == 4'b1000)
    );

// For any binary input, exactly one output is asserted.
    check_outputs_onehot: assert property (
        @(posedge clk)
        ((in == 2'b00) || (in == 2'b01) || (in == 2'b10) || (in == 2'b11))
        |-> $onehot({out3, out2, out1, out0})
    );

// out captures the bitwise AND of the prior-cycle inputs.
    check_out_registered_and: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(a) & $past(b)))
    );

// out_valid is driven high after each clock edge.
    check_out_valid_asserted: assert property (
        @(posedge clk) 1'b1 |=> (out_valid == 1'b1)
    );

// Once out_valid is high, it remains high on later clocks.
    check_out_valid_sticky_high: assert property (
        @(posedge clk) out_valid |=> out_valid
    );

// A zero on either operand produces a zero output on the next cycle.
    check_zero_operand_forces_zero: assert property (
        @(posedge clk) ((a == 8'h00) || (b == 8'h00)) |=> (out == 8'h00)
    );

// All ones on a passes b through to the next-cycle output.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (a == 8'hFF) |=> (out == $past(b))
    );

// All ones on b passes a through to the next-cycle output.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (b == 8'hFF) |=> (out == $past(a))
    );

// 000 maps to 000.
    check_map_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 3'b000)
    );

// 001 maps to 001.
    check_map_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 3'b001)
    );

// 010 maps to 011.
    check_map_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 3'b011)
    );

// 011 maps to 010.
    check_map_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 3'b010)
    );

// 100 maps to 110.
    check_map_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 3'b110)
    );

// 101 maps to 111.
    check_map_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 3'b111)
    );

// 110 maps to 101.
    check_map_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 3'b101)
    );

// 111 maps to 100.
    check_map_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 3'b100)
    );

// Output matches the 3-bit binary-to-Gray formula.
    check_gray_formula: assert property (
        @(posedge clk) out == {in[2], (in[2] ^ in[1]), (in[1] ^ in[0])}
    );

// A sampled active-low reset keeps the output low at the next clock sample.
    check_reset_forces_low_next_sample: assert property (
        @(posedge clk) !rst_n |=> (pwm_out == 1'b0)
    );

// The first sampled cycle after a sampled reset low still sees the output low.
    check_release_from_reset_starts_low: assert property (
        @(posedge clk) (($past(rst_n) === 1'b0) && (rst_n == 1'b1)) |-> (pwm_out == 1'b0)
    );

// A sampled high output must be low on the next clock sample.
    check_high_sample_falls_next_cycle: assert property (
        @(posedge clk) (pwm_out == 1'b1) |=> (pwm_out == 1'b0)
    );

// Any sampled high output must come from a previous low sample out of reset.
    check_high_sample_comes_from_prev_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (((($past(rst_n) === 1'b0) || ($past(rst_n) === 1'b1))) && (pwm_out == 1'b1))
        |-> (($past(rst_n) === 1'b1) && ($past(pwm_out) === 1'b0))
    );

// Low rst implies low q at sampled clock edges.
    check_reset_low_implies_q_low: assert property (
        @(posedge clk)
        1'b1 |=> ((rst == 1'b1) || (q == 1'b0))
    );

// A sampled low rst leaves q low on the next clock.
    check_reset_keeps_q_low_next_clock: assert property (
        @(posedge clk)
        (rst == 1'b0) |=> (q == 1'b0)
    );

// With reset deasserted, sampled d=0 is captured by the next clock.
    check_capture_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (d == 1'b0) |=> (q == 1'b0)
    );

// Whenever q is high, the previous sampled d must have been high.
    check_q_high_has_prior_high_d: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> ((q == 1'b0) || ($past(d) == 1'b1))
    );

// When selectInput is 00, out must equal data0.
    check_select_00: assert property (
        @(posedge clk) (selectInput === 2'b00) |-> (out === data0)
    );

// When selectInput is 01, out must equal data1.
    check_select_01: assert property (
        @(posedge clk) (selectInput === 2'b01) |-> (out === data1)
    );

// When selectInput is 10, out must equal data2.
    check_select_10: assert property (
        @(posedge clk) (selectInput === 2'b10) |-> (out === data2)
    );

// When selectInput is 11, out must equal data3.
    check_select_11: assert property (
        @(posedge clk) (selectInput === 2'b11) |-> (out === data3)
    );

// When selectInput contains X or Z, out must take the default value 00.
    check_default_on_unknown_select: assert property (
        @(posedge clk) $isunknown(selectInput) |-> (out === 2'b00)
    );

// Synchronous reset clears the counter on the next cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// Reset has priority over enable and still clears the counter.
    check_reset_overrides_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 4'd0)
    );

// When enabled outside reset, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 4'd1))
    );

// When not enabled outside reset, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

// A 4-bit maximum value wraps to zero when incremented.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst) (en && (count == 4'hf)) |=> (count == 4'h0)
    );

// Clock: clk. Reset: rst, active-high synchronous.
    // Mixed logic: combinational operand preprocessing with sequential outputs.

    // Synchronous reset clears the registered output and carry on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (rst == 1'b1) |=> ({cout, out} == 5'h00)
    );

// Addition select drives result to a + b.
    check_add_operation: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (result == (a + b))
    );

// Subtraction select drives result to a - b.
    check_sub_operation: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (result == (a - b))
    );

// AND select drives result to a & b.
    check_and_operation: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (result == (a & b))
    );

// OR select drives result to a | b.
    check_or_operation: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (result == (a | b))
    );

// EN low forces ENCLK high on rising-edge samples.
    check_en_low_rise_forces_high: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (ENCLK == 1'b1)
    );

// EN low forces ENCLK high on falling-edge samples.
    check_en_low_fall_forces_high: assert property (
        @(negedge CLK) (EN == 1'b0) |-> (ENCLK == 1'b1)
    );

// EN high with TE low forces ENCLK low on rising-edge samples.
    check_te_low_rise_forces_low: assert property (
        @(posedge CLK) ((EN == 1'b1) && (TE == 1'b0)) |-> (ENCLK == 1'b0)
    );

// EN high with TE low forces ENCLK low on falling-edge samples.
    check_te_low_fall_forces_low: assert property (
        @(negedge CLK) ((EN == 1'b1) && (TE == 1'b0)) |-> (ENCLK == 1'b0)
    );

// EN and TE high make ENCLK follow CLK on rising-edge samples.
    check_clk_passthrough_rise: assert property (
        @(posedge CLK) ((EN == 1'b1) && (TE == 1'b1)) |-> (ENCLK == CLK)
    );

// EN and TE high make ENCLK follow CLK on falling-edge samples.
    check_clk_passthrough_fall: assert property (
        @(negedge CLK) ((EN == 1'b1) && (TE == 1'b1)) |-> (ENCLK == CLK)
    );

// Sum output is the XOR of all three inputs.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ C)
    );

// Carry output matches the implemented carry equation.
    check_carry_function: assert property (
        @(posedge clk) Cout == ((A & B) | ((A ^ B) & C))
    );

// With C low, the block behaves as a half-adder on A and B.
    check_half_adder_mode: assert property (
        @(posedge clk) !C |-> ((S == (A ^ B)) && (Cout == (A & B)))
    );

// With C high, sum inverts A^B and carry is the OR of A and B.
    check_c_high_mode: assert property (
        @(posedge clk) C |-> ((S == ~(A ^ B)) && (Cout == (A | B)))
    );

// When A and B match, sum follows C and carry follows A.
    check_equal_ab_behavior: assert property (
        @(posedge clk) (A == B) |-> ((S == C) && (Cout == A))
    );

// When A and B differ, sum is inverted C and carry follows C.
    check_different_ab_behavior: assert property (
        @(posedge clk) (A != B) |-> ((S == ~C) && (Cout == C))
    );

// y must always equal the RTL expression.
    check_y_matches_rtl_expression: assert property (
        @(posedge clk) y == ((x << 1) + x)
    );

// The least-significant output bit must match the least-significant input bit.
    check_lsb_preserved: assert property (
        @(posedge clk) y[0] == x[0]
    );

// Zero input must produce zero output.
    check_x_zero: assert property (
        @(posedge clk) (x == 4'd0) |-> (y == 6'd0)
    );

// Input value one must produce three.
    check_x_one: assert property (
        @(posedge clk) (x == 4'd1) |-> (y == 6'd3)
    );

// Input value two must produce six.
    check_x_two: assert property (
        @(posedge clk) (x == 4'd2) |-> (y == 6'd6)
    );

// Input value three must produce nine.
    check_x_three: assert property (
        @(posedge clk) (x == 4'd3) |-> (y == 6'd9)
    );

// Input value four must produce twelve.
    check_x_four: assert property (
        @(posedge clk) (x == 4'd4) |-> (y == 6'd12)
    );

// Input value five must produce fifteen.
    check_x_five: assert property (
        @(posedge clk) (x == 4'd5) |-> (y == 6'd15)
    );

// When A is greater than B, max must be A.
    check_max_selects_a: assert property (
        @(posedge clk) (A > B) |-> (max == A)
    );

// When B is greater than A, max must be B.
    check_max_selects_b: assert property (
        @(posedge clk) (B > A) |-> (max == B)
    );

// When A and B are equal, max must be zero.
    check_equal_inputs_drive_zero: assert property (
        @(posedge clk) (A == B) |-> (max == 8'h00)
    );

// A zero max output can only occur when the inputs are equal.
    check_zero_only_on_equal_inputs: assert property (
        @(posedge clk) (max == 8'h00) |-> (A == B)
    );

// max must match the full RTL comparison function.
    check_full_max_function: assert property (
        @(posedge clk) max == ((A > B) ? A : ((B > A) ? B : 8'h00))
    );

// A sampled reset must leave the FSM in zero on the next clock.
    check_reset_state_zero: assert property (
        @(posedge clk) reset |=> (state_reg == zero)
    );

// A sampled reset must leave the debounced output low on the next clock.
    check_reset_db_low: assert property (
        @(posedge clk) reset |=> (db == 1'b0)
    );

// q_next is always q_reg plus one.
    check_counter_next_increment: assert property (
        @(posedge clk) disable iff (reset)
        (q_next == (q_reg + 19'd1))
    );

// m_tick is asserted exactly when q_reg is zero.
    check_mtick_decode: assert property (
        @(posedge clk) disable iff (reset)
        (m_tick == (q_reg == 19'd0))
    );

// The free-running counter increments every clock.
    check_counter_register_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (q_reg == ($past(q_reg) + 19'd1))
    );

// The FSM register loads state_next when reset is not active.
    check_state_register_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (state_reg == $past(state_next))
    );

// zero and wait1 states must drive db low.
    check_db_low_state_decode: assert property (
        @(posedge clk) disable iff (reset)
        ((state_reg == zero) || (state_reg == wait1_1) || (state_reg == wait1_2) || (state_reg == wait1_3))
        |-> (db == 1'b0)
    );

// one and wait0 states must drive db high.
    check_db_high_state_decode: assert property (
        @(posedge clk) disable iff (reset)
        ((state_reg == one) || (state_reg == wait0_1) || (state_reg == wait0_2) || (state_reg == wait0_3))
        |-> (db == 1'b1)
    );

// zero either holds or starts the high-debounce sequence.
    check_zero_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == zero)
        |-> ((!sw && (state_next == zero)) ||
             ( sw && (state_next == wait1_1)))
    );

// wait1_1 either cancels, holds, or advances on m_tick.
    check_wait1_1_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == wait1_1)
        |-> ((!sw && (state_next == zero)) ||
             ( sw && !m_tick && (state_next == wait1_1)) ||
             ( sw &&  m_tick && (state_next == wait1_2)))
    );

// wait1_2 either cancels, holds, or advances on m_tick.
    check_wait1_2_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == wait1_2)
        |-> ((!sw && (state_next == zero)) ||
             ( sw && !m_tick && (state_next == wait1_2)) ||
             ( sw &&  m_tick && (state_next == wait1_3)))
    );

// wait1_3 either cancels, holds, or advances to one on m_tick.
    check_wait1_3_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == wait1_3)
        |-> ((!sw && (state_next == zero)) ||
             ( sw && !m_tick && (state_next == wait1_3)) ||
             ( sw &&  m_tick && (state_next == one)))
    );

// one either holds or starts the low-debounce sequence.
    check_one_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == one)
        |-> (( sw && (state_next == one)) ||
             (!sw && (state_next == wait0_1)))
    );

// wait0_1 either returns to one, holds, or advances on m_tick.
    check_wait0_1_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == wait0_1)
        |-> (( sw && (state_next == one)) ||
             (!sw && !m_tick && (state_next == wait0_1)) ||
             (!sw &&  m_tick && (state_next == wait0_2)))
    );

// wait0_2 either returns to one, holds, or advances on m_tick.
    check_wait0_2_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == wait0_2)
        |-> (( sw && (state_next == one)) ||
             (!sw && !m_tick && (state_next == wait0_2)) ||
             (!sw &&  m_tick && (state_next == wait0_3)))
    );

// wait0_3 either returns to one, holds, or advances to zero on m_tick.
    check_wait0_3_transitions: assert property (
        @(posedge clk) disable iff (reset)
        (state_reg == wait0_3)
        |-> (( sw && (state_next == one)) ||
             (!sw && !m_tick && (state_next == wait0_3)) ||
             (!sw &&  m_tick && (state_next == zero)))
    );

// Active-high synchronous reset clears the counter on the next cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// When enabled below 7, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 3'b111)) |=> (count == ($past(count) + 3'b001))
    );

// When enabled at 7, the counter wraps back to zero.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 3'b111)) |=> (count == 3'b000)
    );

// Ones nibble must be a valid BCD digit.
    check_ones_digit_range: assert property (
        @(posedge clk) bcdout2[3:0] <= 4'd9
    );

// Tens nibble must be a valid BCD digit.
    check_tens_digit_range: assert property (
        @(posedge clk) bcdout2[7:4] <= 4'd9
    );

// Hundreds nibble must be a valid BCD digit.
    check_hundreds_digit_range: assert property (
        @(posedge clk) bcdout2[11:8] <= 4'd9
    );

// Thousands nibble must be a valid BCD digit.
    check_thousands_digit_range: assert property (
        @(posedge clk) bcdout2[15:12] <= 4'd9
    );

// Ten-thousands nibble must be a valid BCD digit.
    check_ten_thousands_digit_range: assert property (
        @(posedge clk) bcdout2[19:16] <= 4'd9
    );

// Zero converts to all-zero BCD.
    check_zero_conversion: assert property (
        @(posedge clk) (B2 == 16'd0) |-> (bcdout2 == 20'h00000)
    );

// Ten converts to 00010 in BCD.
    check_ten_conversion: assert property (
        @(posedge clk) (B2 == 16'd10) |-> (bcdout2 == 20'h00010)
    );

// Ten-thousand converts to 10000 in BCD.
    check_ten_thousand_conversion: assert property (
        @(posedge clk) (B2 == 16'd10000) |-> (bcdout2 == 20'h10000)
    );

// Maximum 16-bit input converts to 65535 in BCD.
    check_max_conversion: assert property (
        @(posedge clk) (B2 == 16'd65535) |-> (bcdout2 == 20'h65535)
    );

// Single-digit inputs only occupy the ones nibble.
    check_single_digit_conversion: assert property (
        @(posedge clk) (B2 <= 16'd9) |-> (bcdout2[19:4] == 16'h0000 && bcdout2[3:0] == B2[3:0])
    );

// Y is the result of three inversions of A.
    check_y_matches_triple_inversion: assert property (
        @(posedge clk) Y == ~A
    );

// A low produces Y high.
    check_output_high_when_input_low: assert property (
        @(posedge clk) !A |-> Y
    );

// A high produces Y low.
    check_output_low_when_input_high: assert property (
        @(posedge clk) A |-> !Y
    );

// Y always differs from A.
    check_output_is_logical_opposite: assert property (
        @(posedge clk) Y != A
    );

// If A is stable across samples, Y is also stable.
    check_output_stable_when_input_stable: assert property (
        @(posedge clk) 1'b1 |=> ($stable(A) |-> $stable(Y))
    );

// If A changes across samples, Y changes too.
    check_output_changes_with_input: assert property (
        @(posedge clk) 1'b1 |=> ($changed(A) |-> $changed(Y))
    );

// Y can only change when A changes across samples.
    check_output_only_changes_with_input: assert property (
        @(posedge clk) 1'b1 |=> ($changed(Y) |-> $changed(A))
    );

// A sampled rise yields a low sampled Y.
    check_output_low_on_input_rise: assert property (
        @(posedge clk) 1'b1 |=> ($rose(A) |-> !Y)
    );

// A sampled fall yields a high sampled Y.
    check_output_high_on_input_fall: assert property (
        @(posedge clk) 1'b1 |=> ($fell(A) |-> Y)
    );

// X must equal the OR of C1, A1&A2, and B1&B2.
    check_exact_or_function: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2) | C1)
    );

// C1 alone is sufficient to drive X high.
    check_c1_forces_output_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together must drive X high.
    check_a_pair_forces_output_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high together must drive X high.
    check_b_pair_forces_output_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If all three OR terms are low, X must be low.
    check_output_low_when_all_terms_low: assert property (
        @(posedge clk) !(C1 | (A1 & A2) | (B1 & B2)) |-> !X
    );

// If X is low, none of the OR terms can be high.
    check_output_low_implies_no_active_term: assert property (
        @(posedge clk) !X |-> (!C1 && !(A1 & A2) && !(B1 & B2))
    );

// If X is high, at least one of the OR terms must be high.
    check_output_high_implies_active_term: assert property (
        @(posedge clk) X |-> (C1 || (A1 & A2) || (B1 & B2))
    );

// The 5-bit output matches the 5-bit arithmetic sum.
    check_total_sum: assert property (
        @(posedge clk) {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

// The least-significant sum bit is the XOR of A[0], B[0], and Ci.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Adding zero with no carry-in returns A with no carry-out.
    check_add_zero_to_a: assert property (
        @(posedge clk) (B == 4'h0 && Ci == 1'b0) |-> (S == A && Co == 1'b0)
    );

// Adding zero with no carry-in returns B with no carry-out.
    check_add_zero_to_b: assert property (
        @(posedge clk) (A == 4'h0 && Ci == 1'b0) |-> (S == B && Co == 1'b0)
    );

// A carry-in by itself increments zero to one without overflow.
    check_carry_in_only: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && Ci == 1'b1) |-> (S == 4'h1 && Co == 1'b0)
    );

// A carry-in propagates through all four stages when A is all ones.
    check_full_carry_propagation: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h0 && Ci == 1'b1) |-> (S == 4'h0 && Co == 1'b1)
    );

// Carry-out stays low when the arithmetic sum fits in 4 bits.
    check_no_overflow_when_sum_fits: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Ci) <= 5'd15) |-> (Co == 1'b0)
    );

// Carry-out goes high when the arithmetic sum exceeds 4 bits.
    check_overflow_when_sum_exceeds: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Ci) >= 5'd16) |-> (Co == 1'b1)
    );

// X matches the implemented sum-of-products function.
    check_x_full_function: assert property (
        @(posedge clk) X == ((A3 & A1 & A2) | (B1 & B2))
    );

// The A-side 3-input product term drives X high.
    check_a_product_sets_x: assert property (
        @(posedge clk) (A3 & A1 & A2) |-> X
    );

// The B-side 2-input product term drives X high.
    check_b_product_sets_x: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// If X is low, both implemented product terms must be low.
    check_x_low_needs_both_products_low: assert property (
        @(posedge clk) (!X) |-> (!(A3 & A1 & A2) && !(B1 & B2))
    );

// With the B-side product term low, X follows the A-side product term.
    check_x_equals_a_product_when_b_product_low: assert property (
        @(posedge clk) !(B1 & B2) |-> (X == (A3 & A1 & A2))
    );

// With the A-side product term low, X follows the B-side product term.
    check_x_equals_b_product_when_a_product_low: assert property (
        @(posedge clk) !(A3 & A1 & A2) |-> (X == (B1 & B2))
    );

// Select 00 routes in[0] to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// Select 01 routes in[1] to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// Select 10 routes in[2] to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// Select 11 routes in[3] to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Y must match the RTL mux expression on every sampled cycle.
    check_mux_function: assert property (
        @(posedge clk)
        Y === ((S == 2'b00) ? A :
               (S == 2'b01) ? B :
               (S == 2'b10) ? C :
                              D)
    );

// Select 00 routes A to Y.
    check_select_a: assert property (
        @(posedge clk)
        (S === 2'b00) |-> (Y === A)
    );

// Select 01 routes B to Y.
    check_select_b: assert property (
        @(posedge clk)
        (S === 2'b01) |-> (Y === B)
    );

// Select 10 routes C to Y.
    check_select_c: assert property (
        @(posedge clk)
        (S === 2'b10) |-> (Y === C)
    );

// Select 11 routes D to Y.
    check_select_d: assert property (
        @(posedge clk)
        (S === 2'b11) |-> (Y === D)
    );

// gt matches the OR of zero-extended bit positions where a is 1 and b is 0.
    check_gt_definition: assert property (
        @(posedge clk) gt == (|(({1'b0, a}) & ~({1'b0, b})))
    );

// lt matches the OR of zero-extended bit positions where a is 0 and b is 1.
    check_lt_definition: assert property (
        @(posedge clk) lt == (|(~({1'b0, a}) & ({1'b0, b})))
    );

// eq matches the AND of zero-extended bitwise equality results.
    check_eq_definition: assert property (
        @(posedge clk) eq == (&((({1'b0, a}) ~^ ({1'b0, b}))))
    );

// Equal inputs must drive eq high and both difference flags low.
    check_equal_inputs_outputs: assert property (
        @(posedge clk) (a == b) |-> (eq && !gt && !lt)
    );

// Different inputs must clear eq and assert at least one difference flag.
    check_different_inputs_outputs: assert property (
        @(posedge clk) (a != b) |-> (!eq && (gt || lt))
    );

// eq is asserted exactly when neither gt nor lt is asserted.
    check_eq_matches_no_gt_lt: assert property (
        @(posedge clk) eq == !(gt || lt)
    );

// gt can only be high when a and b differ.
    check_gt_indicates_difference: assert property (
        @(posedge clk) gt |-> (a != b)
    );

// lt can only be high when a and b differ.
    check_lt_indicates_difference: assert property (
        @(posedge clk) lt |-> (a != b)
    );

// Output must match the RTL minimum computation.
    check_output_matches_rtl: assert property (
        @(posedge clk) min == abcd_min
    );

// The reported minimum cannot exceed input a.
    check_min_le_a: assert property (
        @(posedge clk) min <= a
    );

// The reported minimum cannot exceed input b.
    check_min_le_b: assert property (
        @(posedge clk) min <= b
    );

// The reported minimum cannot exceed input c.
    check_min_le_c: assert property (
        @(posedge clk) min <= c
    );

// The reported minimum cannot exceed input d.
    check_min_le_d: assert property (
        @(posedge clk) min <= d
    );

// The reported minimum must be one of the four inputs.
    check_min_is_input_value: assert property (
        @(posedge clk) (min == a) || (min == b) || (min == c) || (min == d)
    );

// If a is no greater than all other inputs, the output must equal a.
    check_a_when_a_is_minimal: assert property (
        @(posedge clk) ((a <= b) && (a <= c) && (a <= d)) |-> (min == a)
    );

// If b is no greater than all other inputs, the output must equal b.
    check_b_when_b_is_minimal: assert property (
        @(posedge clk) ((b <= a) && (b <= c) && (b <= d)) |-> (min == b)
    );

// If c is no greater than all other inputs, the output must equal c.
    check_c_when_c_is_minimal: assert property (
        @(posedge clk) ((c <= a) && (c <= b) && (c <= d)) |-> (min == c)
    );

// If d is no greater than all other inputs, the output must equal d.
    check_d_when_d_is_minimal: assert property (
        @(posedge clk) ((d <= a) && (d <= b) && (d <= c)) |-> (min == d)
    );

// Selector forces the state register to 00 on the next clock.
    check_selector_clears_state: assert property (
        @(posedge clk_IBUF_BUFG)
        FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// With selector low and AR low, state 00 holds.
    check_hold_00_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b00)) |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// With selector low and AR low, state 01 holds.
    check_hold_01_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b01)) |=> (FSM_sequential_state_reg_reg == 2'b01)
    );

// With selector low and AR low, state 10 holds.
    check_hold_10_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b10)) |=> (FSM_sequential_state_reg_reg == 2'b10)
    );

// With selector low and AR low, state 11 holds.
    check_hold_11_when_ar_low: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && !AR && (FSM_sequential_state_reg_reg == 2'b11)) |=> (FSM_sequential_state_reg_reg == 2'b11)
    );

// With selector low and AR high, state 00 increments to 01.
    check_increment_00_to_01: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b00)) |=> (FSM_sequential_state_reg_reg == 2'b01)
    );

// With selector low and AR high, state 01 increments to 10.
    check_increment_01_to_10: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b01)) |=> (FSM_sequential_state_reg_reg == 2'b10)
    );

// With selector low and AR high, state 10 increments to 11.
    check_increment_10_to_11: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b10)) |=> (FSM_sequential_state_reg_reg == 2'b11)
    );

// With selector low and AR high, state 11 wraps to 00.
    check_increment_11_to_00: assert property (
        @(posedge clk_IBUF_BUFG)
        (!FSM_selector_C && AR && (FSM_sequential_state_reg_reg == 2'b11)) |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// Output matches the RTL priority function.
    check_full_function: assert property (
        @(posedge clk)
        fifo_cnt_inc == (
            empty ? {3'b000, input_tm_cnt} :
            ((ge3_free && (input_tm_cnt == 2'b11)) ? 5'd2 :
             ((ge2_free && (input_tm_cnt >= 2'd2)) ? 5'd1 :
              ((input_tm_cnt >= 2'd1) ? 5'd0 : 5'b11111)))
        )
    );

// When empty is high, the output passes through input_tm_cnt.
    check_empty_pass_through: assert property (
        @(posedge clk)
        empty |-> (fifo_cnt_inc == {3'b000, input_tm_cnt})
    );

// The empty branch has priority over the later branches.
    check_empty_priority: assert property (
        @(posedge clk)
        (empty && ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd3)
    );

// For non-empty and count 3 with ge3_free, the output is 2.
    check_ge3_free_count3: assert property (
        @(posedge clk)
        (!empty && ge3_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd2)
    );

// The ge3_free branch overrides ge2_free when both are true.
    check_ge3_priority_over_ge2: assert property (
        @(posedge clk)
        (!empty && ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd2)
    );

// For non-empty and count 2 with ge2_free, the output is 1.
    check_ge2_free_count2: assert property (
        @(posedge clk)
        (!empty && ge2_free && (input_tm_cnt == 2'b10)) |-> (fifo_cnt_inc == 5'd1)
    );

// For count 3 without ge3_free but with ge2_free, the output is 1.
    check_count3_ge2_without_ge3: assert property (
        @(posedge clk)
        (!empty && !ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd1)
    );

// For non-empty and count 1, the output falls through to 0.
    check_count1_maps_zero: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'b01)) |-> (fifo_cnt_inc == 5'd0)
    );

// For non-empty and count 2 without ge2_free, the output is 0.
    check_count2_without_ge2_maps_zero: assert property (
        @(posedge clk)
        (!empty && !ge2_free && (input_tm_cnt == 2'b10)) |-> (fifo_cnt_inc == 5'd0)
    );

// For non-empty and count 0, the output is all ones.
    check_count0_maps_all_ones: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'b00)) |-> (fifo_cnt_inc == 5'b11111)
    );

// The output only takes values produced by the RTL.
    check_output_legal_values: assert property (
        @(posedge clk)
        (fifo_cnt_inc == 5'd0)  ||
        (fifo_cnt_inc == 5'd1)  ||
        (fifo_cnt_inc == 5'd2)  ||
        (fifo_cnt_inc == 5'd3)  ||
        (fifo_cnt_inc == 5'b11111)
    );

// When A equals B, output must be 00.
    check_equal_implies_code_00: assert property (
        @(posedge clk) disable iff (1'b0) (A == B) |-> (C == 2'b00)
    );

// When A greater than B, output must be 01.
    check_greater_implies_code_01: assert property (
        @(posedge clk) disable iff (1'b0) (A > B) |-> (C == 2'b01)
    );

// When A less than B, output must be 10.
    check_less_implies_code_10: assert property (
        @(posedge clk) disable iff (1'b0) (A < B) |-> (C == 2'b10)
    );

// Output 00 only occurs when A equals B.
    check_code_00_implies_equal: assert property (
        @(posedge clk) disable iff (1'b0) (C == 2'b00) |-> (A == B)
    );

// Output 01 only occurs when A greater than B.
    check_code_01_implies_greater: assert property (
        @(posedge clk) disable iff (1'b0) (C == 2'b01) |-> (A > B)
    );

// Output 10 only occurs when A less than B.
    check_code_10_implies_less: assert property (
        @(posedge clk) disable iff (1'b0) (C == 2'b10) |-> (A < B)
    );

// Output must never be 11.
    check_output_not_11: assert property (
        @(posedge clk) disable iff (1'b0) (C != 2'b11)
    );

// When A != B, output must not be 00.
    check_neq_implies_not_00: assert property (
        @(posedge clk) disable iff (1'b0) (A != B) |-> (C != 2'b00)
    );

// X equals A & ~SLEEP combinationally.
    check_functional_x_equals_a_and_not_sleep: assert property (
        @(posedge clk) X == (A & ~SLEEP)
    );

// When SLEEP is HIGH, X must be LOW.
    check_sleep_high_forces_x_low: assert property (
        @(posedge clk) (SLEEP == 1'b1) |-> (X == 1'b0)
    );

// When SLEEP is LOW, X equals A.
    check_sleep_low_makes_x_equal_a: assert property (
        @(posedge clk) (SLEEP == 1'b0) |-> (X == A)
    );

// If X is HIGH, then A is HIGH and SLEEP is LOW.
    check_x_high_implies_a_high_and_sleep_low: assert property (
        @(posedge clk) (X == 1'b1) |-> (A == 1'b1 && SLEEP == 1'b0)
    );

// If A is LOW, X must be LOW.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

// If A is HIGH and SLEEP is LOW, X must be HIGH.
    check_awake_and_a_high_forces_x_high: assert property (
        @(posedge clk) (A == 1'b1 && SLEEP == 1'b0) |-> (X == 1'b1)
    );

// A rising SLEEP forces X LOW immediately.
    check_sleep_rise_forces_output_low: assert property (
        @(posedge clk) $rose(SLEEP) |-> (X == 1'b0)
    );

// A falling SLEEP makes X equal to A immediately.
    check_sleep_fall_makes_output_follow_a: assert property (
        @(posedge clk) $fell(SLEEP) |-> (X == A)
    );

// COUT implements majority-of-three: (A&B) | (A&CIN) | (B&CIN).
    check_cout_majority: assert property (
        @(posedge clk) disable iff (1'b0)
        COUT == ((A & B) | (A & CIN) | (B & CIN))
    );

// SUM is odd parity of inputs: A ^ B ^ CIN.
    check_sum_parity: assert property (
        @(posedge clk) disable iff (1'b0)
        SUM == (A ^ B ^ CIN)
    );

// When COUT is 1, SUM equals A&B&CIN (only 3 ones case yields SUM=1).
    check_sum_when_cout1: assert property (
        @(posedge clk) disable iff (1'b0)
        (COUT == 1'b1) |-> (SUM == (A & B & CIN))
    );

// When COUT is 0, SUM equals A|B|CIN (exactly one 1 yields SUM=1).
    check_sum_when_cout0: assert property (
        @(posedge clk) disable iff (1'b0)
        (COUT == 1'b0) |-> (SUM == (A | B | CIN))
    );

// All inputs 0 -> outputs 0.
    check_zero_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} == 3'b000) |-> (COUT == 1'b0 && SUM == 1'b0)
    );

// Exactly one input 1 -> SUM=1, COUT=0.
    check_one_hot_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} inside {3'b001,3'b010,3'b100}) |-> (COUT == 1'b0 && SUM == 1'b1)
    );

// Exactly two inputs 1 -> SUM=0, COUT=1.
    check_two_ones_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} inside {3'b011,3'b101,3'b110}) |-> (COUT == 1'b1 && SUM == 1'b0)
    );

// All inputs 1 -> outputs 1.
    check_all_ones_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ({A,B,CIN} == 3'b111) |-> (COUT == 1'b1 && SUM == 1'b1)
    );

// If A equals B, COUT equals that value (majority determined by the pair).
    check_cout_when_A_eq_B: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == B) |-> (COUT == A)
    );

// If A equals B, SUM equals CIN (A^B cancels).
    check_sum_when_A_eq_B: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == B) |-> (SUM == CIN)
    );

///// Functional mapping /////
    // S implements A + (~B + 1), i.e., two's-complement subtraction.
    check_subtractor_function: assert property (
        @(posedge clk) S == (A + ((~B) + 32'd1))
    );

// Adding B back to S yields A (mod 2^32).
    check_add_back_B_yields_A: assert property (
        @(posedge clk) (S + B) == A
    );

// A minus S equals B (mod 2^32).
    check_A_minus_S_equals_B: assert property (
        @(posedge clk) A + ((~S) + 32'd1) == B
    );

///// Special cases /////
    // If inputs are equal, result is zero.
    check_equal_inputs_zero_output: assert property (
        @(posedge clk) (A == B) |-> (S == 32'd0)
    );

// If B is zero, S passes through A.
    check_zero_B_passthrough: assert property (
        @(posedge clk) (B == 32'd0) |-> (S == A)
    );

// If A is zero, S is two's complement of B.
    check_zero_A_twos_complement_B: assert property (
        @(posedge clk) (A == 32'd0) |-> (S == ((~B) + 32'd1))
    );

// If B is all ones, S equals A plus one (mod 2^32).
    check_B_all_ones_inc_A: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |-> (S == (A + 32'd1))
    );

// LSB of result equals XOR of input LSBs.
    check_lsb_is_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

///// Reset behavior /////
  // At reset, internal registers are driven to 0.
  check_reset_regs_zero: assert property (
    @(posedge clk) !reset_n |-> (pwm_timer == 12'd0) && (fifo_rdreq == 1'b0) &&
                               (audiodata_32 == 32'd0) && (audiodata_32_p == 32'd0) &&
                               (data_rdy == 1'b0)
  );

// At reset, PWM outputs are HIGH (timer=0, thresholds=0).
  check_reset_pwm_out_high: assert property (
    @(posedge clk) !reset_n |-> (pwm_out_l == 1'b1) && (pwm_out_r == 1'b1)
  );

// rdreq deasserts one cycle after being observed high at 0x801.
  check_rdreq_clear_after_801: assert property (
    @(posedge clk) disable iff (!reset_n) (pwm_timer == 12'h801 && fifo_rdreq == 1'b1) |-> ##1 (fifo_rdreq == 1'b0)
  );

// rdreq pulse width is exactly one cycle.
  check_rdreq_one_cycle_pulse: assert property (
    @(posedge clk) disable iff (!reset_n) $rose(fifo_rdreq) |-> ##1 (!fifo_rdreq)
  );

// Left PWM is known when inputs to comparator are known.
  check_pwm_out_l_known_when_inputs_known: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({pwm_timer, audiodata_32[15:4]})) |-> (!$isunknown(pwm_out_l))
  );

// Right PWM is known when inputs to comparator are known.
  check_pwm_out_r_known_when_inputs_known: assert property (
    @(posedge clk) disable iff (!reset_n) (!$isunknown({pwm_timer, audiodata_32[31:20]})) |-> (!$isunknown(pwm_out_r))
  );

// If left/right thresholds are equal, PWM outputs must match.
  check_pwms_equal_when_thresholds_equal: assert property (
    @(posedge clk) disable iff (!reset_n) (audiodata_32[15:4] == audiodata_32[31:20]) |-> (pwm_out_l == pwm_out_r)
  );

// Notes: No reset in RTL; combinational logic; assertions are sampled on CLK.

    // When ctrl=1, Y equals A+B (4-bit modulo arithmetic).
    check_add_result: assert property (
        @(posedge CLK) ctrl |-> (Y == (A + B))
    );

// When ctrl=0, Y equals A-B (4-bit modulo arithmetic).
    check_sub_result: assert property (
        @(posedge CLK) !ctrl |-> (Y == (A - B))
    );

// If B is zero, output equals A regardless of ctrl.
    check_b_zero_returns_a: assert property (
        @(posedge CLK) (B == 4'd0) |-> (Y == A)
    );

// If ctrl=1 and A is zero, output equals B.
    check_add_a_zero_returns_b: assert property (
        @(posedge CLK) (ctrl && (A == 4'd0)) |-> (Y == B)
    );

// If ctrl=0 and A==B, output is zero.
    check_sub_self_zero: assert property (
        @(posedge CLK) (!ctrl && (A == B)) |-> (Y == 4'd0)
    );

// Wrap-around example: 0xF + 1 -> 0 when adding.
    check_add_wrap_ff_plus_1: assert property (
        @(posedge CLK) (ctrl && (A == 4'hF) && (B == 4'd1)) |-> (Y == 4'h0)
    );

// Wrap-around example: 0 - 1 -> 0xF when subtracting.
    check_sub_wrap_0_minus_1: assert property (
        @(posedge CLK) (!ctrl && (A == 4'd0) && (B == 4'd1)) |-> (Y == 4'hF)
    );

// Adding zeros yields zero.
    check_add_zero_zero: assert property (
        @(posedge CLK) (ctrl && (A == 4'd0) && (B == 4'd0)) |-> (Y == 4'd0)
    );

// Subtracting zeros yields zero.
    check_sub_zero_zero: assert property (
        @(posedge CLK) (!ctrl && (A == 4'd0) && (B == 4'd0)) |-> (Y == 4'd0)
    );

///// Functional mapping /////
    // Out must match the truth table for every input.
    check_truth_table: assert property (
        @(posedge clk) out == expected_out(in)
    );

///// Inverse mapping (consistency) /////
    // If out is 00, input must be 0000.
    check_inverse_out_00: assert property (
        @(posedge clk) (out == 2'b00) |-> (in == 4'b0000)
    );

// If out is 01, input must be one of single-bit-set values.
    check_inverse_out_01: assert property (
        @(posedge clk) (out == 2'b01) |-> (in inside {4'b0001,4'b0010,4'b0100,4'b1000})
    );

// If out is 10, input must be one of the specified seven values.
    check_inverse_out_10: assert property (
        @(posedge clk) (out == 2'b10) |-> (in inside {4'b0011,4'b0101,4'b0110,4'b1001,4'b1010,4'b1100,4'b1111})
    );

// If out is 11, input must be one of the three-ones values.
    check_inverse_out_11: assert property (
        @(posedge clk) (out == 2'b11) |-> (in inside {4'b0111,4'b1011,4'b1101,4'b1110})
    );

///// Forward mapping by input classes /////
    // If input has exactly one bit set, out must be 01.
    check_onehot_implies_01: assert property (
        @(posedge clk) (in inside {4'b0001,4'b0010,4'b0100,4'b1000}) |-> (out == 2'b01)
    );

// If input has exactly two bits set, out must be 10.
    check_two_ones_implies_10: assert property (
        @(posedge clk) (in inside {4'b0011,4'b0101,4'b0110,4'b1001,4'b1010,4'b1100}) |-> (out == 2'b10)
    );

// If input has exactly three bits set, out must be 11.
    check_three_ones_implies_11: assert property (
        @(posedge clk) (in inside {4'b0111,4'b1011,4'b1101,4'b1110}) |-> (out == 2'b11)
    );

// If input has zero bits set, out must be 00.
    check_zero_ones_implies_00: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 2'b00)
    );

// If input has four bits set, out must be 10 (special case in RTL).
    check_four_ones_implies_10: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 2'b10)
    );

// When S is 0, output must equal A.
    check_select0_routes_A: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

// When S is 1, output must equal B.
    check_select1_routes_B: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

// If A equals B, output must equal that common value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

// With S held at 0, a change on A must be reflected on Y at the next sample.
    check_s0_a_change_updates_y: assert property (
        @(posedge clk) (S === 1'b0 && $past(S) === 1'b0 && (A !== $past(A))) |-> (Y === A)
    );

// With S held at 1, a change on B must be reflected on Y at the next sample.
    check_s1_b_change_updates_y: assert property (
        @(posedge clk) (S === 1'b1 && $past(S) === 1'b1 && (B !== $past(B))) |-> (Y === B)
    );

// On a rising edge of S, output must equal B.
    check_sel_rise_selects_B: assert property (
        @(posedge clk) $rose(S) |-> (Y === B)
    );

// On a falling edge of S, output must equal A.
    check_sel_fall_selects_A: assert property (
        @(posedge clk) $fell(S) |-> (Y === A)
    );

///// Reset behavior /////
    // While reset is asserted (AR=0), D must be 0.
    check_reset_forces_zero: assert property (
        @(posedge m_aclk) (!AR) |-> (D == 4'b0000)
    );

// On reset assertion, D is 0 at this clock.
    check_reset_assert_cycle_zero: assert property (
        @(posedge m_aclk) $fell(AR) |-> (D == 4'b0000)
    );

// After reset deasserts, on the next clock D equals Q sampled at deassertion.
    check_capture_after_reset_release: assert property (
        @(posedge m_aclk) disable iff (!AR) $rose(AR) |-> ##1 (AR && (D == $past(Q)))
    );

// When all inputs are 1, Y must be 0 (NAND3 truth).
    check_all_ones_drives_low: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && C == 1'b1) |-> (Y == 1'b0)
    );

// If A is 0, Y must be 1 (NAND3 truth).
    check_a_zero_forces_high: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b1)
    );

// If B is 0, Y must be 1 (NAND3 truth).
    check_b_zero_forces_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

// If C is 0, Y must be 1 (NAND3 truth).
    check_c_zero_forces_high: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b1)
    );

// Y can be 0 only when A, B, and C are all 1.
    check_only_low_if_all_ones: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A == 1'b1 && B == 1'b1 && C == 1'b1)
    );

// If Y is 1, not all inputs are 1.
    check_high_implies_not_all_ones: assert property (
        @(posedge clk) (Y == 1'b1) |-> !((A == 1'b1) && (B == 1'b1) && (C == 1'b1))
    );

// A falling edge on Y implies all inputs are 1 now.
    check_y_fall_requires_all_ones: assert property (
        @(posedge clk) $fell(Y) |-> (A == 1'b1 && B == 1'b1 && C == 1'b1)
    );

// A rising edge on Y implies at least one input is 0 now.
    check_y_rise_requires_any_zero: assert property (
        @(posedge clk) $rose(Y) |-> (A == 1'b0 || B == 1'b0 || C == 1'b0)
    );

// Q matches previous D on cycles following a non-reset cycle.
    check_capture_from_d_prev_not_reset: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) == 1'b1) |-> (q == $past(d))
    );

// Q is 0 on any cycle immediately following a cycle with reset low.
    check_q_zero_after_prev_reset_low: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) == 1'b0) |-> (q == 1'b0)
    );

// Rising edge on D with reset high drives Q to 1 on the next clock.
    check_d_rise_sets_q_next: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && $rose(d)) |=> (q == 1'b1)
    );

// Falling edge on D with reset high drives Q to 0 on the next clock.
    check_d_fall_clears_q_next: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && $fell(d)) |=> (q == 1'b0)
    );

// When reset high and D equals current Q, Q holds its value next cycle.
    check_q_holds_when_d_equals_q: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && (d == q)) |=> (q == $past(q))
    );

// With no reset over two cycles and stable D, Q remains stable across cycles.
    check_q_stable_when_d_stable: assert property (
        @(posedge clk) disable iff (!reset)
            (($past(reset) == 1'b1) && (reset == 1'b1) && (d == $past(d))) |=> (q == $past(q))
    );

// Output equals A & B.
    check_and_function: assert property (
        @(posedge clk) disable iff (1'b0) (Y == (A & B))
    );

// If either input is 0, output must be 0.
    check_zero_if_any_zero: assert property (
        @(posedge clk) disable iff (1'b0) ((A == 1'b0) || (B == 1'b0)) |-> (Y == 1'b0)
    );

// If both inputs are 1, output must be 1.
    check_one_if_both_one: assert property (
        @(posedge clk) disable iff (1'b0) ((A == 1'b1) && (B == 1'b1)) |-> (Y == 1'b1)
    );

// When B is 1, output follows A.
    check_output_eq_A_when_B_high: assert property (
        @(posedge clk) disable iff (1'b0) (B == 1'b1) |-> (Y == A)
    );

// When A is 1, output follows B.
    check_output_eq_B_when_A_high: assert property (
        @(posedge clk) disable iff (1'b0) (A == 1'b1) |-> (Y == B)
    );

// No reset in DUT; sample on clk.

    // Y equals (A && !B) || (C && !D).
    check_y_function_equivalence: assert property (
        @(posedge clk) Y == ((A && !B) || (C && !D))
    );

// If A is 1 and B is 0, Y must be 1.
    check_y_one_when_term1_true: assert property (
        @(posedge clk) (A && !B) |-> (Y == 1'b1)
    );

// If C is 1 and D is 0, Y must be 1.
    check_y_one_when_term2_true: assert property (
        @(posedge clk) (C && !D) |-> (Y == 1'b1)
    );

// If B and D are both 1, Y must be 0.
    check_y_zero_when_both_inhibit: assert property (
        @(posedge clk) (B && D) |-> (Y == 1'b0)
    );

// If A and C are both 0, Y must be 0.
    check_y_zero_when_no_enablers: assert property (
        @(posedge clk) (!A && !C) |-> (Y == 1'b0)
    );

// Y high implies at least one enabling term is true.
    check_y_high_implies_term_true: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A && !B) || (C && !D))
    );

// Y low implies both terms are false.
    check_y_low_implies_terms_false: assert property (
        @(posedge clk) (Y == 1'b0) |-> (!(A && !B) && !(C && !D))
    );

///// Output clear behavior /////
  // When clr is HIGH, op must be 0 in the same cycle.
  check_op_zero_when_clr_high: assert property (
    @(posedge clk) clr |-> (op == 1'b0)
  );

// If clr is HIGH in two consecutive cycles, op stays 0.
  check_op_zero_stable_while_clr_high: assert property (
    @(posedge clk) ($past(clr) && clr) |-> (op == 1'b0)
  );

///// Combinational function checks (sampled on posedge of A1) /////
    // Y must equal (A1 & A2 & A3) & (B1 | C1).
    check_y_matches_eqn: assert property (
        @(posedge A1) Y == ((A1 & A2 & A3) & (B1 | C1))
    );

// If Y is HIGH, then A1,A2,A3 are HIGH and at least one of B1/C1 is HIGH.
    check_y_high_requires_all_as_and_one_of_bc: assert property (
        @(posedge A1) Y |-> (A1 & A2 & A3 & (B1 | C1))
    );

// If A1 is LOW then Y must be LOW.
    check_y_zero_if_a1_zero: assert property (
        @(posedge A1) !A1 |-> !Y
    );

// If A2 is LOW then Y must be LOW.
    check_y_zero_if_a2_zero: assert property (
        @(posedge A1) !A2 |-> !Y
    );

// If A3 is LOW then Y must be LOW.
    check_y_zero_if_a3_zero: assert property (
        @(posedge A1) !A3 |-> !Y
    );

// If both B1 and C1 are LOW then Y must be LOW.
    check_y_zero_if_b1_and_c1_zero: assert property (
        @(posedge A1) (!B1 && !C1) |-> !Y
    );

// If A1,A2,A3 and B1 are HIGH then Y must be HIGH (independent of C1).
    check_y_one_if_all_as_and_b1_one: assert property (
        @(posedge A1) (A1 && A2 && A3 && B1) |-> Y
    );

// If A1,A2,A3 and C1 are HIGH then Y must be HIGH (independent of B1).
    check_y_one_if_all_as_and_c1_one: assert property (
        @(posedge A1) (A1 && A2 && A3 && C1) |-> Y
    );

// A rising edge on Y can only occur when A1,A2,A3 are HIGH and (B1|C1) is HIGH.
    check_y_rise_requires_inputs: assert property (
        @(posedge A1) $rose(Y) |-> (A1 && A2 && A3 && (B1 || C1))
    );

// Analysis: No reset; combinational logic only; sample assertions on an external clock.
    // Behavior: out = (in < 4) ? (in + 1)[2:0] : (in - 1)[2:0].

    // For in < 4, out equals in + 1 (3-bit result).
    check_low_range_function: assert property (
        @(posedge clk) (in < 4'd4) |-> (out == (in[2:0] + 3'd1))
    );

// For in >= 4, out equals in - 1 (3-bit result).
    check_high_range_function: assert property (
        @(posedge clk) (in >= 4'd4) |-> (out == (in[2:0] - 3'd1))
    );

// Boundary: in == 3 maps to out == 4.
    check_boundary_in3_out4: assert property (
        @(posedge clk) (in == 4'd3) |-> (out == 3'd4)
    );

// Boundary: in == 4 maps to out == 3.
    check_boundary_in4_out3: assert property (
        @(posedge clk) (in == 4'd4) |-> (out == 3'd3)
    );

// Corner: in == 0 maps to out == 1.
    check_in0_out1: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 3'd1)
    );

// The 5-bit {carry_out,sum} equals in0 + in1 + carry_in.
    check_add_result_5bit: assert property (
        @(posedge CLK) disable iff (1'b0) {carry_out, sum} == res5
    );

// sum[0] equals XOR of LSBs and carry_in.
    check_sum0_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[0] == (in0[0] ^ in1[0] ^ carry_in)
    );

// sum[1] equals XOR of bit1s and carry from bit0.
    check_sum1_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[1] == (in0[1] ^ in1[1] ^ c0)
    );

// sum[2] equals XOR of bit2s and carry from bit1.
    check_sum2_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[2] == (in0[2] ^ in1[2] ^ c1)
    );

// sum[3] equals XOR of bit3s and carry from bit2.
    check_sum3_xor: assert property (
        @(posedge CLK) disable iff (1'b0) sum[3] == (in0[3] ^ in1[3] ^ c2)
    );

// carry_out is the majority of bit3s and carry from bit2.
    check_carry_out_majority: assert property (
        @(posedge CLK) disable iff (1'b0) carry_out == ((in0[3] & in1[3]) | (in0[3] & c2) | (in1[3] & c2))
    );

// The 4-bit sum equals the low 4 bits of the arithmetic result.
    check_sum_low_bits_match: assert property (
        @(posedge CLK) disable iff (1'b0) sum == res5[3:0]
    );

///// Reset behavior /////
  // On reset, outputs and internal count are cleared to zero.
  check_reset_clears_outputs: assert property (
    @(posedge clk) rst |-> (activate == 2'b00) && (data == 32'd0) && (strobe == 1'b0) && (count == 24'd0)
  );

///// Activate encoding /////
  // activate is always at most one-hot (00,01,10).
  check_activate_onehot0: assert property (
    @(posedge clk) disable iff (rst) $onehot0(activate)
  );

// activate[0] can only rise from idle with enable and ready[0].
  check_activate0_rise_requires_cond: assert property (
    @(posedge clk) disable iff (rst)
      $rose(activate[0]) |-> $past((activate == 2'b00) && enable && ready[0])
  );

// activate[1] can only rise from idle with enable, ready[0]==0, and ready[1]==1.
  check_activate1_rise_requires_cond: assert property (
    @(posedge clk) disable iff (rst)
      $rose(activate[1]) |-> $past((activate == 2'b00) && enable && (ready[0] == 1'b0) && (ready[1] == 1'b1))
  );

///// Reset behavior /////
  // Synchronous reset drives count to zero on the clock edge.
  check_reset_clears_count: assert property (
    @(posedge clk) rst |-> (count == 4'd0)
  );

// While reset is held across cycles, count stays zero and stable.
  check_continuous_reset_holds_zero: assert property (
    @(posedge clk) (rst && $past(rst)) |-> (count == 4'd0 && $stable(count))
  );

///// Enable and increment semantics /////
  // With en=1 (and no reset), count increments by one on the next cycle.
  check_increment_when_en_high: assert property (
    @(posedge clk) disable iff (rst) (en == 1'b1) |=> (count == $past(count) + 4'd1)
  );

// With en=0 (and no reset), count holds its value on the next cycle.
  check_hold_when_en_low: assert property (
    @(posedge clk) disable iff (rst) (en == 1'b0) |=> (count == $past(count))
  );

// If en=1 at count==15, next count wraps to zero.
  check_wrap_on_max: assert property (
    @(posedge clk) disable iff (rst) (en && (count == 4'hF)) |=> (count == 4'd0)
  );

// Two consecutive cycles of en=1 advance count by two.
  check_two_consecutive_en_increments_by2: assert property (
    @(posedge clk) disable iff (rst) (en ##1 en) |=> (count == $past(count,2) + 4'd2)
  );

// en=1 then en=0 over two cycles advances count by one total.
  check_en_then_hold_advances_by1: assert property (
    @(posedge clk) disable iff (rst) (en ##1 !en) |=> (count == $past(count,2) + 4'd1)
  );

// Two consecutive cycles of en=0 cause no change over those two cycles.
  check_two_cycles_no_en_no_change: assert property (
    @(posedge clk) disable iff (rst) (!en ##1 !en) |=> (count == $past(count,2))
  );

// or_apat_1 is the reduction-OR of apat_1.
    check_or_apat_1_reduce: assert property (
        @(posedge de_clk) disable iff (prst) or_apat_1 == (|apat_1)
    );

// ps16s_2 decodes ps_sel_2 == 2'b01.
    check_ps16s_decode: assert property (
        @(posedge de_clk) disable iff (prst) ps16s_2 == (~ps_sel_2[1] & ps_sel_2[0])
    );

// ps565s_2 decodes ps_sel_2 == 2'b11.
    check_ps565s_decode: assert property (
        @(posedge de_clk) disable iff (prst) ps565s_2 == (&ps_sel_2)
    );

// The two decodes are mutually exclusive.
    check_ps_decode_mutex: assert property (
        @(posedge de_clk) disable iff (prst) !(ps16s_2 && ps565s_2)
    );

// hb_ca_rdy is constantly HIGH.
    check_hb_ca_rdy_const_high: assert property (
        @(posedge de_clk) disable iff (prst) hb_ca_rdy == 1'b1
    );

// de_ca_rdy is constantly HIGH.
    check_de_ca_rdy_const_high: assert property (
        @(posedge de_clk) disable iff (prst) de_ca_rdy == 1'b1
    );

// de_sorg_2 passes mf_sorg_2 when sd_selector is 1.
    check_de_sorg_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (de_sorg_2 == mf_sorg_2)
    );

// de_sorg_2 is zero when sd_selector is 0.
    check_de_sorg_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (de_sorg_2 == 32'b0)
    );

// de_dorg_2 passes mf_dorg_2 when sd_selector is 1.
    check_de_dorg_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (de_dorg_2 == mf_dorg_2)
    );

// de_dorg_2 is zero when sd_selector is 0.
    check_de_dorg_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (de_dorg_2 == 32'b0)
    );

// sorg_2 equals {6'h0, mf_sorg_2[25:4]} when sd_selector is 0.
    check_sorg2_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (sorg_2 == {6'h0, mf_sorg_2[25:4]})
    );

// sorg_2 is zero when sd_selector is 1.
    check_sorg2_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (sorg_2 == 28'b0)
    );

// dorg_2 equals {6'h0, mf_dorg_2[25:4]} when sd_selector is 0.
    check_dorg2_when_sel0: assert property (
        @(posedge de_clk) disable iff (prst) !sd_selector |-> (dorg_2 == {6'h0, mf_dorg_2[25:4]})
    );

// dorg_2 is zero when sd_selector is 1.
    check_dorg2_when_sel1: assert property (
        @(posedge de_clk) disable iff (prst) sd_selector |-> (dorg_2 == 28'b0)
    );

// io_dataOut reflects io_dataIn from two cycles earlier.
    check_output_follows_input_two_cycles: assert property (
        @(posedge io_mainClk) 1 |=> 1 |=> (io_dataOut == $past(io_dataIn,2))
    );

// c0 must equal inclk0.
    check_c0_eq_inclk0: assert property (
        @(posedge inclk0) c0 == inclk0
    );

// c1 must equal inclk0.
    check_c1_eq_inclk0: assert property (
        @(posedge inclk0) c1 == inclk0
    );

// e0 must be the inversion of inclk0.
    check_e0_inverts_inclk0: assert property (
        @(posedge inclk0) e0 == ~inclk0
    );

// locked must be constantly HIGH.
    check_locked_constant_high: assert property (
        @(posedge inclk0) locked == 1'b1
    );

// c0 and c1 must always be equal.
    check_c0_c1_equal: assert property (
        @(posedge inclk0) c0 == c1
    );

// e0 must be the inversion of c0.
    check_e0_inverts_c0: assert property (
        @(posedge inclk0) e0 == ~c0
    );

///// Combinational selection rules /////
    // When enable is LOW, q equals B.
    check_q_equals_B_when_enable_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!enable) |-> (q == B)
    );

// When enable is HIGH and A >= B, q equals A.
    check_q_equals_A_when_enable_high_and_A_ge_B: assert property (
        @(posedge CLK) disable iff (1'b0) (enable && (A >= B)) |-> (q == A)
    );

// When enable is HIGH and A < B, q equals B.
    check_q_equals_B_when_enable_high_and_A_lt_B: assert property (
        @(posedge CLK) disable iff (1'b0) (enable && (A < B)) |-> (q == B)
    );

// If A < B, q must be B regardless of enable.
    check_q_equals_B_when_A_lt_B: assert property (
        @(posedge CLK) disable iff (1'b0) (A < B) |-> (q == B)
    );

// q is always either A or B.
    check_q_is_A_or_B: assert property (
        @(posedge CLK) disable iff (1'b0) ((q == A) || (q == B))
    );

// Functional equivalence: q == (enable && (A >= B) ? A : B).
    check_mux_equivalence: assert property (
        @(posedge CLK) disable iff (1'b0) (q == ((enable && (A >= B)) ? A : B))
    );

// When A == B and enable is HIGH, q equals A.
    check_equal_inputs_with_enable: assert property (
        @(posedge CLK) disable iff (1'b0) (enable && (A == B)) |-> (q == A)
    );

// When A == B and enable is LOW, q equals B.
    check_equal_inputs_without_enable: assert property (
        @(posedge CLK) disable iff (1'b0) (!enable && (A == B)) |-> (q == B)
    );

// Synchronous reset drives count to zero on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 8'h00)
    );

// While reset is held across cycles, count remains zero.
    check_reset_held_forces_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 8'h00)
    );

///// Reset behavior /////
    // While reset is asserted (active-low), counter_out is 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) (!rst_n) |-> (counter_out == 4'b0000)
    );

// X equals (~A_N & B & C).
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((~A_N) & B & C)
    );

// X high implies B&C are 1 and A_N is 0.
    check_x_high_implies_inputs: assert property (
        @(posedge clk) X |-> (B && C && !A_N)
    );

// When !A_N & B & C, X must be high.
    check_inputs_imply_x_high: assert property (
        @(posedge clk) (!A_N && B && C) |-> X
    );

// A_N high forces X low.
    check_an_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// X can only rise when B&C=1 and A_N=0.
    check_rise_requires_inputs_true: assert property (
        @(posedge clk) $rose(X) |-> (B && C && !A_N)
    );

// X can only fall when at least one disabling input is active.
    check_fall_requires_any_input_false: assert property (
        @(posedge clk) $fell(X) |-> (A_N || !B || !C)
    );

// Any disabling input active implies X low.
    check_any_disable_implies_x_low: assert property (
        @(posedge clk) (A_N || !B || !C) |-> !X
    );

///// Synchronous set/reset and data load behavior /////
    // S asserted sets Q to 1 on the next clock (S has priority).
    check_sync_set_dominates: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b1) |=> (Q == 1'b1)
    );

// R asserted with S deasserted clears Q to 0 on the next clock.
    check_sync_reset_when_no_set: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b0 && R == 1'b1) |=> (Q == 1'b0)
    );

// When both S and R are asserted, S dominates and Q becomes 1 on the next clock.
    check_priority_s_over_r: assert property (
        @(posedge CLK) disable iff (1'b0) (S == 1'b1 && R == 1'b1) |=> (Q == 1'b1)
    );

// With S=0 and R=0, Q loads D sampled at the same edge.
    check_data_load_when_no_ctrl: assert property (
        @(posedge CLK) disable iff (1'b0) ##1 ($past(S)==1'b0 && $past(R)==1'b0) |-> (Q == $past(D))
    );

// If no control and D equals prior Q, Q holds its value across the next cycle.
    check_hold_when_d_equals_prev_q: assert property (
        @(posedge CLK) disable iff (1'b0) ##1 ($past(S)==1'b0 && $past(R)==1'b0 && ($past(D) == $past(Q))) |-> (Q == $past(Q))
    );

// Any change in Q is justified by prior S/R/D values.
    check_q_change_has_cause: assert property (
        @(posedge CLK) disable iff (1'b0)
            ##1 $changed(Q) |-> (
                ($past(S) == 1'b1 && $past(Q) != 1'b1) ||
                ($past(S) == 1'b0 && $past(R) == 1'b1 && $past(Q) != 1'b0) ||
                ($past(S) == 1'b0 && $past(R) == 1'b0 && $past(D) != $past(Q))
            )
    );

///// Output relationship /////
    // QN is always the logical complement of Q.
    check_qn_is_complement_of_q: assert property (
        @(posedge CLK) disable iff (1'b0) (QN == ~Q)
    );

// Q and QN are never equal.
    check_q_qn_never_equal: assert property (
        @(posedge CLK) disable iff (1'b0) (Q != QN)
    );

// QN changes iff Q changes between consecutive clocks.
    check_qn_changes_iff_q_changes: assert property (
        @(posedge CLK) disable iff (1'b0) ##1 1'b1 |-> ($changed(QN) == $changed(Q))
    );

///// Functional summary check /////
    // Next Q equals: S?1 : (R?0 : D) using prior-cycle inputs.
    check_next_q_truth_table: assert property (
        @(posedge CLK) disable iff (1'b0)
            ##1 1'b1 |-> (Q == ($past(S) ? 1'b1 : ($past(R) ? 1'b0 : $past(D))))
    );

// On reset, output equals init value that cycle.
    check_reset_assigns_init: assert property (
        @(posedge clock) reset |-> (io_out == io_init)
    );

// Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) (reset && io_enable) |-> (io_out == io_init)
    );

// g_out equals logical AND of inputs.
    check_g_out_is_and: assert property (
        @(posedge clk) g_out == (a & b)
    );

// p_out equals logical OR of inputs.
    check_p_out_is_or: assert property (
        @(posedge clk) p_out == (a | b)
    );

// If AND output is 1, OR output must also be 1.
    check_and_implies_or: assert property (
        @(posedge clk) g_out |-> p_out
    );

// When both inputs are 0, both outputs must be 0.
    check_zero_zero_outputs_zero: assert property (
        @(posedge clk) (!a && !b) |-> (!g_out && !p_out)
    );

// When a=1 and b=0, outputs must be g_out=0, p_out=1.
    check_a1_b0_outputs: assert property (
        @(posedge clk) (a && !b) |-> (!g_out && p_out)
    );

// When a=0 and b=1, outputs must be g_out=0, p_out=1.
    check_a0_b1_outputs: assert property (
        @(posedge clk) (!a && b) |-> (!g_out && p_out)
    );

// When both inputs are 1, both outputs must be 1.
    check_one_one_outputs_one: assert property (
        @(posedge clk) (a && b) |-> (g_out && p_out)
    );

// sum equals 4-bit (a + b + cin) modulo 16.
    check_sum_mod_add: assert property (
        @(posedge cin) sum == (a + b + cin)
    );

///// Bit-level full-adder relations derived from a + b + cin /////
    // LSB: sum[0] = a0 ^ b0 ^ cin.
    check_sum_bit0_xor: assert property (
        @(posedge cin) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// sum[1] with carry from bit 0.
    check_sum_bit1_full_adder: assert property (
        @(posedge cin) sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin)))
    );

// sum[2] with propagated carry.
    check_sum_bit2_full_adder: assert property (
        @(posedge cin)
            sum[2] == (a[2] ^ b[2] ^
                       (((a[1] & b[1]) | ((a[1] ^ b[1]) & ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin))))))
    );

// sum[3] with propagated carry.
    check_sum_bit3_full_adder: assert property (
        @(posedge cin)
            sum[3] == (a[3] ^ b[3] ^
                       ( (a[2] & b[2]) |
                         ( (a[2] ^ b[2]) &
                           ( (a[1] & b[1]) |
                             ( (a[1] ^ b[1]) &
                               ( (a[0] & b[0]) | ( (a[0] ^ b[0]) & cin ) )
                             )
                           )
                         )
                       )
            )
    );

// Output equals bitwise AND of inputs (vector).
    check_and_vector: assert property (
        @(posedge clk) (Y == (A & B))
    );

// Bit 0 output equals AND of inputs bit 0.
    check_and_bit0: assert property (
        @(posedge clk) (Y[0] == (A[0] & B[0]))
    );

// Bit 1 output equals AND of inputs bit 1.
    check_and_bit1: assert property (
        @(posedge clk) (Y[1] == (A[1] & B[1]))
    );

///// Combinational decode mapping checks /////
    // When ctrl[8:6]==000, td_mode must be 0000.
    check_decode_000: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b000) |-> (td_mode == 4'b0000)
    );

// When ctrl[8:6]==001, td_mode must be 1000.
    check_decode_001: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b001) |-> (td_mode == 4'b1000)
    );

// When ctrl[8:6]==010, td_mode must be 0100.
    check_decode_010: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b010) |-> (td_mode == 4'b0100)
    );

// When ctrl[8:6]==011, td_mode must be 1100.
    check_decode_011: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b011) |-> (td_mode == 4'b1100)
    );

// When ctrl[8:6]==100, td_mode must be 0010.
    check_decode_100: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b100) |-> (td_mode == 4'b0010)
    );

// When ctrl[8:6]==101, td_mode must be 1010.
    check_decode_101: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b101) |-> (td_mode == 4'b1010)
    );

// When ctrl[8:6]==110, td_mode must be 0101.
    check_decode_110: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b110) |-> (td_mode == 4'b0101)
    );

// When ctrl[8:6]==111, td_mode must be 1111.
    check_decode_111: assert property (
        @(posedge clk) disable iff (1'b0) (ctrl[8:6] == 3'b111) |-> (td_mode == 4'b1111)
    );

///// Output value constraints /////
    // td_mode must always be one of the defined decode values.
    check_td_mode_value_set: assert property (
        @(posedge clk) disable iff (1'b0) td_mode inside {4'b0000,4'b1000,4'b0100,4'b1100,4'b0010,4'b1010,4'b0101,4'b1111}
    );

// When E=0, X equals (~A & ~B & ~C & D).
    check_E0_equivalence: assert property (
        @(posedge A) (E == 1'b0) |-> (X == (~A & ~B & ~C & D))
    );

// With E=1 and A=0,B=0,C=1, X is 1 regardless of D.
    check_E1_A0B0C1_true: assert property (
        @(posedge A) (E && ~A && ~B && C) |-> (X == 1'b1)
    );

// With E=1 and A=0,B=1,C=0, X is 1 regardless of D.
    check_E1_A0B1C0_true: assert property (
        @(posedge A) (E && ~A && B && ~C) |-> (X == 1'b1)
    );

// With E=1 and A=1,B=0,C=0, X is 1 regardless of D.
    check_E1_A1B0C0_true: assert property (
        @(posedge A) (E && A && ~B && ~C) |-> (X == 1'b1)
    );

// With E=1 and A=1,B=1,C=1, X is 1 regardless of D.
    check_E1_A1B1C1_true: assert property (
        @(posedge A) (E && A && B && C) |-> (X == 1'b1)
    );

// With E=1 and A=1,B=1,C=0, X is always 0.
    check_E1_A1B1C0_false: assert property (
        @(posedge A) (E && A && B && ~C) |-> (X == 1'b0)
    );

// With E=1 and A=1,B=0,C=1,D=1, X must be 1.
    check_E1_A1B0C1_D1_true: assert property (
        @(posedge A) (E && A && ~B && C && D) |-> (X == 1'b1)
    );

// With E=1 and A=1,B=0,C=1,D=0, X must be 0.
    check_E1_A1B0C1_D0_false: assert property (
        @(posedge A) (E && A && ~B && C && ~D) |-> (X == 1'b0)
    );

// With E=1 and A=0,B=0,C=0,D=1, X must be 1.
    check_E1_A0B0C0_D1_true: assert property (
        @(posedge A) (E && ~A && ~B && ~C && D) |-> (X == 1'b1)
    );

// With E=1 and A=0,B=0,C=0,D=0, X must be 0.
    check_E1_A0B0C0_D0_false: assert property (
        @(posedge A) (E && ~A && ~B && ~C && ~D) |-> (X == 1'b0)
    );

// Functional equivalence: X is OR of A,B,C and inverted D_N.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == (A | B | C | ~D_N)
    );

// If any input asserts (A/B/C) or D_N deasserts (0), X must be 1.
    check_any_input_high_implies_x_high: assert property (
        @(posedge CLK) ((A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D_N == 1'b0)) |-> (X == 1'b1)
    );

// The only case for X to be 0 is A=B=C=0 and D_N=1.
    check_only_case_for_x_low: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == 1'b0)
    );

// If X is 0, inputs must be A=B=C=0 and D_N=1.
    check_x_low_implies_inputs_zero: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1))
    );

// If X is 1, at least one of A/B/C is 1 or D_N is 0.
    check_x_high_implies_some_input_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D_N == 1'b0))
    );

// A high alone is sufficient to drive X high.
    check_a_high_drives_x: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

// B high alone is sufficient to drive X high.
    check_b_high_drives_x: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == 1'b1)
    );

// C high alone is sufficient to drive X high.
    check_c_high_drives_x: assert property (
        @(posedge CLK) (C == 1'b1) |-> (X == 1'b1)
    );

// D_N low (active low) alone is sufficient to drive X high.
    check_dn_low_drives_x: assert property (
        @(posedge CLK) (D_N == 1'b0) |-> (X == 1'b1)
    );

// Z equals selected input based on Sel each cycle.
    check_mux_function: assert property (
        @(posedge CLK) Z == (Sel ? B : A)
    );

// When Sel is 0, Z must equal A.
    check_sel0_mapping: assert property (
        @(posedge CLK) (Sel == 1'b0) |-> (Z == A)
    );

// When Sel is 1, Z must equal B.
    check_sel1_mapping: assert property (
        @(posedge CLK) (Sel == 1'b1) |-> (Z == B)
    );

// On Sel rising edge, Z reflects B in the same cycle.
    check_rose_sel_selects_B: assert property (
        @(posedge CLK) $rose(Sel) |-> (Z == B)
    );

// On Sel falling edge, Z reflects A in the same cycle.
    check_fell_sel_selects_A: assert property (
        @(posedge CLK) $fell(Sel) |-> (Z == A)
    );

// Output equals 7 for input 5 or 6; else equals input[2:0].
    check_output_functional_mapping: assert property (
        @(posedge clk) output_val == (((input_val == 4'd5) || (input_val == 4'd6)) ? 3'd7 : input_val[2:0])
    );

// When input is 5 or 6, output must be 7.
    check_special_cases_to_7: assert property (
        @(posedge clk) ((input_val == 4'd5) || (input_val == 4'd6)) |-> (output_val == 3'd7)
    );

// For inputs other than 5 or 6, output must equal input[2:0].
    check_default_passthrough: assert property (
        @(posedge clk) !((input_val == 4'd5) || (input_val == 4'd6)) |-> (output_val == input_val[2:0])
    );

// When ctrl is 1, S equals D1.
    check_ctrl1_routes_D1: assert property (
        @(posedge clk) (ctrl === 1'b1) |-> (S === D1)
    );

// With ctrl=0 and D0 known, S has no X/Z.
    check_no_unknown_when_ctrl0: assert property (
        @(posedge clk) (ctrl === 1'b0 && !$isunknown(D0)) |-> !$isunknown(S)
    );

// With ctrl=1 and D1 known, S has no X/Z.
    check_no_unknown_when_ctrl1: assert property (
        @(posedge clk) (ctrl === 1'b1 && !$isunknown(D1)) |-> !$isunknown(S)
    );

// For sel=00, out mirrors in[0].
    check_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// For sel=11, out mirrors in[3].
    check_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Structural equivalence to the sum-of-products implementation.
    check_structural_equivalence: assert property (
        @(posedge clk)
            out == ((in[0] & ~sel[0] & ~sel[1]) |
                    (in[1] & ~sel[0] &  sel[1]) |
                    (in[2] &  sel[0] & ~sel[1]) |
                    (in[3] &  sel[0] &  sel[1]))
    );

// If all inputs are 0, out must be 0.
    check_zero_inputs_zero_out: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 1'b0)
    );

// If all inputs are 1, out must be 1.
    check_allones_inputs_one_out: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 1'b1)
    );

// No clock/reset in RTL; assertions are sampled on clk without reset gating.
    // Purely combinational 3-to-8 decoder: Y[i] is one-hot minterm of A,B,C.

    // Y0 equals ~(A | B | C)
    check_y0_definition: assert property (
        @(posedge clk) Y0 == ~(A | B | C)
    );

// Y1 equals ~(A | B | ~C)
    check_y1_definition: assert property (
        @(posedge clk) Y1 == ~(A | B | ~C)
    );

// Y2 equals ~(A | ~B | C)
    check_y2_definition: assert property (
        @(posedge clk) Y2 == ~(A | ~B | C)
    );

// Y3 equals ~(A | ~B | ~C)
    check_y3_definition: assert property (
        @(posedge clk) Y3 == ~(A | ~B | ~C)
    );

// Y4 equals ~(~A | B | C)
    check_y4_definition: assert property (
        @(posedge clk) Y4 == ~(~A | B | C)
    );

// Y5 equals ~(~A | B | ~C)
    check_y5_definition: assert property (
        @(posedge clk) Y5 == ~(~A | B | ~C)
    );

// Y6 equals ~(~A | ~B | C)
    check_y6_definition: assert property (
        @(posedge clk) Y6 == ~(~A | ~B | C)
    );

// Y7 equals ~(~A | ~B | ~C)
    check_y7_definition: assert property (
        @(posedge clk) Y7 == ~(~A | ~B | ~C)
    );

// Exactly one output is HIGH for any A,B,C
    check_onehot_outputs: assert property (
        @(posedge clk) $onehot({Y7,Y6,Y5,Y4,Y3,Y2,Y1,Y0})
    );

// Outputs cover all cases (OR of all Y is 1)
    check_outputs_cover_all: assert property (
        @(posedge clk) (|{Y7,Y6,Y5,Y4,Y3,Y2,Y1,Y0}) == 1'b1
    );

// Y implements a 3-input NAND of A,B,C.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B & C)
    );

// When all inputs are HIGH, Y must be LOW.
    check_all_high_drives_low: assert property (
        @(posedge clk) (A && B && C) |-> (Y == 1'b0)
    );

// Y LOW implies all inputs are HIGH.
    check_low_implies_all_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A && B && C)
    );

// If A is LOW, Y must be HIGH (regardless of B and C).
    check_any_low_A_drives_high: assert property (
        @(posedge clk) (!A) |-> (Y == 1'b1)
    );

// If B is LOW, Y must be HIGH (regardless of A and C).
    check_any_low_B_drives_high: assert property (
        @(posedge clk) (!B) |-> (Y == 1'b1)
    );

// If C is LOW, Y must be HIGH (regardless of A and B).
    check_any_low_C_drives_high: assert property (
        @(posedge clk) (!C) |-> (Y == 1'b1)
    );

// If A rises while B and C are HIGH, Y must be LOW.
    check_rise_A_with_BC_high_drives_low: assert property (
        @(posedge clk) ($rose(A) && B && C) |-> (Y == 1'b0)
    );

// If A falls while B and C are HIGH, Y must be HIGH.
    check_fall_A_with_BC_high_drives_high: assert property (
        @(posedge clk) ($fell(A) && B && C) |-> (Y == 1'b1)
    );

// If B rises while A and C are HIGH, Y must be LOW.
    check_rise_B_with_AC_high_drives_low: assert property (
        @(posedge clk) ($rose(B) && A && C) |-> (Y == 1'b0)
    );

// If C rises while A and B are HIGH, Y must be LOW.
    check_rise_C_with_AB_high_drives_low: assert property (
        @(posedge clk) ($rose(C) && A && B) |-> (Y == 1'b0)
    );

// Mux function: out equals selected input.
    check_mux_equivalence: assert property (
        @(posedge clk) out == (select ? data_1 : data_0)
    );

// When select=0, out equals data_0.
    check_select0_routes_data0: assert property (
        @(posedge clk) (select == 1'b0) |-> (out == data_0)
    );

// When select=1, out equals data_1.
    check_select1_routes_data1: assert property (
        @(posedge clk) (select == 1'b1) |-> (out == data_1)
    );

// If inputs are equal, out equals that value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (data_0 == data_1) |-> (out == data_0)
    );

// X implements A & ~SLEEP
    check_function_equivalence: assert property (
        @(posedge clk) X == (A & ~SLEEP)
    );

// When SLEEP is high, X must be 0
    check_isolation_when_sleep: assert property (
        @(posedge clk) SLEEP |-> (X == 1'b0)
    );

// When SLEEP is low, X equals A
    check_transparent_when_awake: assert property (
        @(posedge clk) !SLEEP |-> (X == A)
    );

// X high only if A is high and SLEEP is low
    check_x_high_conditions: assert property (
        @(posedge clk) (X == 1'b1) |-> (A == 1'b1) && (SLEEP == 1'b0)
    );

// If A is low, X must be low
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

// If A is high, X equals ~SLEEP
    check_a_high_sets_x_to_not_sleep: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == ~SLEEP)
    );

// X can only rise when A is high and SLEEP is low
    check_x_rise_requires_a_and_awake: assert property (
        @(posedge clk) $rose(X) |-> (A == 1'b1) && (SLEEP == 1'b0)
    );

// X can only fall when A is low or SLEEP is high
    check_x_fall_requires_a0_or_sleep1: assert property (
        @(posedge clk) $fell(X) |-> (A == 1'b0) || (SLEEP == 1'b1)
    );

// On SLEEP rising edge, X must be 0
    check_x_zero_on_sleep_rise: assert property (
        @(posedge clk) $rose(SLEEP) |-> (X == 1'b0)
    );

// On SLEEP falling edge with A high, X must be 1
    check_x_one_on_sleep_fall_if_a_high: assert property (
        @(posedge clk) ($fell(SLEEP) && (A == 1'b1)) |-> (X == 1'b1)
    );

// On A rising edge with SLEEP low, X must be 1
    check_x_one_on_a_rise_if_awake: assert property (
        @(posedge clk) ($rose(A) && (SLEEP == 1'b0)) |-> (X == 1'b1)
    );

// On A falling edge with SLEEP low, X must be 0
    check_x_zero_on_a_fall_if_awake: assert property (
        @(posedge clk) ($fell(A) && (SLEEP == 1'b0)) |-> (X == 1'b0)
    );

///// pulse update behavior /////
    // On each clk edge, pulse follows this next-state rule: if cycle rose in the last interval, capture ena; else hold value.
    check_pulse_update_rule: assert property (
        @(posedge clk) 1'b1 |=> (pulse == ($rose(cycle) ? $past(ena) : $past(pulse)))
    );

// key_input == 1 maps to led_output == 00001
    map_1_to_00001: assert property (
        @(posedge clk) (key_input == 9'h001) |-> (led_output == 5'b00001)
    );

// key_input == 2 maps to led_output == 00010
    map_2_to_00010: assert property (
        @(posedge clk) (key_input == 9'h002) |-> (led_output == 5'b00010)
    );

// key_input == 4 maps to led_output == 00100
    map_4_to_00100: assert property (
        @(posedge clk) (key_input == 9'h004) |-> (led_output == 5'b00100)
    );

// key_input == 8 maps to led_output == 01000
    map_8_to_01000: assert property (
        @(posedge clk) (key_input == 9'h008) |-> (led_output == 5'b01000)
    );

// key_input == 16 maps to led_output == 10000
    map_16_to_10000: assert property (
        @(posedge clk) (key_input == 9'h010) |-> (led_output == 5'b10000)
    );

// key_input == 32 maps to led_output == 00000
    map_32_to_00000: assert property (
        @(posedge clk) (key_input == 9'h020) |-> (led_output == 5'b00000)
    );

// key_input == 64 maps to led_output == 11111
    map_64_to_11111: assert property (
        @(posedge clk) (key_input == 9'h040) |-> (led_output == 5'b11111)
    );

// For defined keys, led_output has no unknown bits
    no_x_led_when_defined: assert property (
        @(posedge clk)
        ((key_input == 9'h001) || (key_input == 9'h002) || (key_input == 9'h004) ||
         (key_input == 9'h008) || (key_input == 9'h010) || (key_input == 9'h020) ||
         (key_input == 9'h040)) |-> !$isunknown(led_output)
    );

///// Functional correctness /////
    // When Cin is 1, S equals bitwise XNOR of A and B.
    check_s_eq_xnor_when_cin_high: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin) |-> (S == ~(A ^ B))
    );

// When Cin is 0, S equals bitwise AND of A and B.
    check_s_eq_and_when_cin_low: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin) |-> (S == (A & B))
    );

// When inputs are known (no X/Z), output S is known.
    check_s_known_when_inputs_known: assert property (
        @(posedge Cin) disable iff (1'b0) (!$isunknown({A,B,Cin})) |-> (!$isunknown(S))
    );

///// Useful special cases derived from the logic /////
    // With Cin=1 and A==B, S is all ones (XNOR true).
    check_allones_when_cin_high_and_a_eq_b: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin && (A == B)) |-> (S == {32{1'b1}})
    );

// With Cin=1 and A==~B, S is all zeros (XNOR false).
    check_allzeros_when_cin_high_and_a_eq_notb: assert property (
        @(posedge Cin) disable iff (1'b0) (Cin && (A == ~B)) |-> (S == 32'b0)
    );

// With Cin=0 and B all ones, S equals A (A & all1 = A).
    check_s_eq_a_when_cin_low_and_b_allones: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && (B == {32{1'b1}})) |-> (S == A)
    );

// With Cin=0 and A all ones, S equals B (all1 & B = B).
    check_s_eq_b_when_cin_low_and_a_allones: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && (A == {32{1'b1}})) |-> (S == B)
    );

// With Cin=0 and either operand all zeros, S is all zeros.
    check_s_zero_when_cin_low_and_any_zero: assert property (
        @(negedge Cin) disable iff (1'b0) (!Cin && ((A == 32'b0) || (B == 32'b0))) |-> (S == 32'b0)
    );

// While rst is asserted, the following cycle's count is 0 (synchronous reset).
    check_zero_during_reset: assert property (
        @(posedge clk) rst |=> (count == 8'h00)
    );

// DUT has no reset; purely combinational 4-input AND built from 2-input ANDs.

    // and0_out must be 1 when both A and B are 1.
    check_and0_high_when_A_and_B_high: assert property (
        @(posedge clk) (A && B) |-> (and0_out == 1'b1)
    );

// and0_out must be 0 when either A or B is 0.
    check_and0_low_when_A_or_B_low: assert property (
        @(posedge clk) ((!A) || (!B)) |-> (and0_out == 1'b0)
    );

// and1_out must be 1 when both C and D are 1.
    check_and1_high_when_C_and_D_high: assert property (
        @(posedge clk) (C && D) |-> (and1_out == 1'b1)
    );

// and1_out must be 0 when either C or D is 0.
    check_and1_low_when_C_or_D_low: assert property (
        @(posedge clk) ((!C) || (!D)) |-> (and1_out == 1'b0)
    );

// X must be 1 when both sub-AND outputs are 1.
    check_X_high_when_subands_high: assert property (
        @(posedge clk) (and0_out && and1_out) |-> (X == 1'b1)
    );

// X must be 0 when either sub-AND output is 0.
    check_X_low_when_any_suband_low: assert property (
        @(posedge clk) ((!and0_out) || (!and1_out)) |-> (X == 1'b0)
    );

// X must be 1 when all four inputs are 1.
    check_X_high_when_all_inputs_high: assert property (
        @(posedge clk) (A && B && C && D) |-> (X == 1'b1)
    );

// X must be 0 when any input is 0.
    check_X_low_when_any_input_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C) || (!D)) |-> (X == 1'b0)
    );

// and0_out being 1 implies both A and B are 1.
    check_and0_high_implies_A_and_B_high: assert property (
        @(posedge clk) and0_out |-> (A && B)
    );

// and1_out being 1 implies both C and D are 1.
    check_and1_high_implies_C_and_D_high: assert property (
        @(posedge clk) and1_out |-> (C && D)
    );

///// Functional parity checks /////
    // Parity equals XOR of inputs (odd parity).
    check_parity_matches_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) parity == (in1 ^ in2 ^ in3 ^ in4)
    );

// Exactly one input HIGH implies parity HIGH.
    check_onehot_high: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot({in1,in2,in3,in4}) |-> (parity == 1'b1)
    );

// Exactly two inputs HIGH implies parity LOW.
    check_two_high_low: assert property (
        @(posedge CLK) disable iff (!RESETn) ((in1 + in2 + in3 + in4) == 2) |-> (parity == 1'b0)
    );

// Exactly three inputs HIGH implies parity HIGH.
    check_three_high: assert property (
        @(posedge CLK) disable iff (!RESETn) ((in1 + in2 + in3 + in4) == 3) |-> (parity == 1'b1)
    );

// All inputs equal (all 0 or all 1) implies parity LOW.
    check_all_equal_low: assert property (
        @(posedge CLK) disable iff (!RESETn) ((in1 == in2) && (in2 == in3) && (in3 == in4)) |-> (parity == 1'b0)
    );

///// Output mux rules /////
    // For ena != 2'b01, upper nibble of out is always zero.
    check_out_upper_zero_when_ena_not01: assert property (
        @(posedge clk) (ena != 2'b01) |-> (out[7:4] == 4'b0000)
    );

// For sel 110 or 111, output is zero regardless of ena.
    check_out_zero_when_sel_invalid: assert property (
        @(posedge clk) (sel inside {3'b110,3'b111}) |-> (out == 8'b0)
    );

// When ena == 2'b01, out replicates the selected 4-bit value to both nibbles (halves equal).
    check_out_halves_equal_when_ena01: assert property (
        @(posedge clk) (ena == 2'b01) |-> (out[7:4] == out[3:0])
    );

// For ena in {00,10,11}, low nibble equals the selected data nibble (sel=000).
    check_out_low_matches_sel0_e001011: assert property (
        @(posedge clk) (sel == 3'd0) && (ena inside {2'b00,2'b10,2'b11}) |-> (out[3:0] == data0)
    );

// For ena == 01, both nibbles equal selected data nibble (sel=000).
    check_out_rep_sel0_e01: assert property (
        @(posedge clk) (sel == 3'd0) && (ena == 2'b01) |-> ((out[3:0] == data0) && (out[7:4] == data0))
    );

// For sel=001.
    check_out_low_matches_sel1_e001011: assert property (
        @(posedge clk) (sel == 3'd1) && (ena inside {2'b00,2'b10,2'b11}) |-> (out[3:0] == data1)
    );

check_out_rep_sel1_e01: assert property (
        @(posedge clk) (sel == 3'd1) && (ena == 2'b01) |-> ((out[3:0] == data1) && (out[7:4] == data1))
    );

// For sel=010.
    check_out_low_matches_sel2_e001011: assert property (
        @(posedge clk) (sel == 3'd2) && (ena inside {2'b00,2'b10,2'b11}) |-> (out[3:0] == data2)
    );

check_out_rep_sel2_e01: assert property (
        @(posedge clk) (sel == 3'd2) && (ena == 2'b01) |-> ((out[3:0] == data2) && (out[7:4] == data2))
    );

// For sel=011.
    check_out_low_matches_sel3_e001011: assert property (
        @(posedge clk) (sel == 3'd3) && (ena inside {2'b00,2'b10,2'b11}) |-> (out[3:0] == data3)
    );

check_out_rep_sel3_e01: assert property (
        @(posedge clk) (sel == 3'd3) && (ena == 2'b01) |-> ((out[3:0] == data3) && (out[7:4] == data3))
    );

// For sel=100.
    check_out_low_matches_sel4_e001011: assert property (
        @(posedge clk) (sel == 3'd4) && (ena inside {2'b00,2'b10,2'b11}) |-> (out[3:0] == data4)
    );

check_out_rep_sel4_e01: assert property (
        @(posedge clk) (sel == 3'd4) && (ena == 2'b01) |-> ((out[3:0] == data4) && (out[7:4] == data4))
    );

// For sel=101.
    check_out_low_matches_sel5_e001011: assert property (
        @(posedge clk) (sel == 3'd5) && (ena inside {2'b00,2'b10,2'b11}) |-> (out[3:0] == data5)
    );

check_out_rep_sel5_e01: assert property (
        @(posedge clk) (sel == 3'd5) && (ena == 2'b01) |-> ((out[3:0] == data5) && (out[7:4] == data5))
    );

// S equals three-input XOR of A, B, and Ci.
    check_sum_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) S == (A ^ B ^ Ci)
    );

// Co equals majority function (A&B) | (A&Ci) | (B&Ci).
    check_carry_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) Co == ((A & B) | (A & Ci) | (B & Ci))
    );

// Truth table: A=0, B=0, Ci=0 -> S=0, Co=0.
    truth_000: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A && !B && !Ci) |-> (S == 1'b0 && Co == 1'b0)
    );

// Truth table: A=0, B=0, Ci=1 -> S=1, Co=0.
    truth_001: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A && !B && Ci) |-> (S == 1'b1 && Co == 1'b0)
    );

// Truth table: A=0, B=1, Ci=0 -> S=1, Co=0.
    truth_010: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A && B && !Ci) |-> (S == 1'b1 && Co == 1'b0)
    );

// Truth table: A=0, B=1, Ci=1 -> S=0, Co=1.
    truth_011: assert property (
        @(posedge CLK) disable iff (!RESETn) (!A && B && Ci) |-> (S == 1'b0 && Co == 1'b1)
    );

// Truth table: A=1, B=0, Ci=0 -> S=1, Co=0.
    truth_100: assert property (
        @(posedge CLK) disable iff (!RESETn) (A && !B && !Ci) |-> (S == 1'b1 && Co == 1'b0)
    );

// Truth table: A=1, B=0, Ci=1 -> S=0, Co=1.
    truth_101: assert property (
        @(posedge CLK) disable iff (!RESETn) (A && !B && Ci) |-> (S == 1'b0 && Co == 1'b1)
    );

// Truth table: A=1, B=1, Ci=0 -> S=0, Co=1.
    truth_110: assert property (
        @(posedge CLK) disable iff (!RESETn) (A && B && !Ci) |-> (S == 1'b0 && Co == 1'b1)
    );

// Truth table: A=1, B=1, Ci=1 -> S=1, Co=1.
    truth_111: assert property (
        @(posedge CLK) disable iff (!RESETn) (A && B && Ci) |-> (S == 1'b1 && Co == 1'b1)
    );

// When load is asserted (no reset), next count equals data_in sampled this cycle.
    check_load_updates_next: assert property (
        @(posedge clk) disable iff (rst) load |=> (count == $past(data_in))
    );

// When not loading (no reset), next count increments by one modulo WIDTH.
    check_increment_on_no_load: assert property (
        @(posedge clk) disable iff (rst) !load |=> (count == $past(count) + 1'b1)
    );

// With back-to-back loads (no reset), the second load value is observed next.
    check_double_load_last_wins: assert property (
        @(posedge clk) disable iff (rst) (load && !rst) ##1 (load && !rst) |=> (count == $past(data_in))
    );

// Load then no-load (no reset): after two cycles, count equals loaded value + 1.
    check_load_then_increment_result: assert property (
        @(posedge clk) disable iff (rst) (load && !rst) ##1 (!rst && !load) |=> (count == $past(data_in,2) + 1'b1)
    );

// No-load then load (no reset): after two cycles, count equals the load value.
    check_increment_then_load_result: assert property (
        @(posedge clk) disable iff (rst) (!rst && !load) ##1 (load && !rst) |=> (count == $past(data_in))
    );

// When count is max and no load (no reset), next count wraps to zero.
    check_wraparound_when_max: assert property (
        @(posedge clk) disable iff (rst) (!load && (count == {WIDTH{1'b1}})) |=> (count == '0)
    );

// Immediately after reset release with no load, the first update increments from zero.
    check_post_reset_first_no_load_increments: assert property (
        @(posedge clk) disable iff (rst) ($fell(rst) && !load) |=> (count == $past(count) + 1'b1)
    );

// No clock or reset in RTL; pure combinational. Assertions are sampled on posedges of A/B/C.

    ///// Functional equivalence (sampled on multiple inputs) /////
    // Y equals (A&B) | (B&C) when sampled on A.
    check_y_sop_on_A: assert property (
        @(posedge A) Y == ((A & B) | (B & C))
    );

// Y equals (A&B) | (B&C) when sampled on B.
    check_y_sop_on_B: assert property (
        @(posedge B) Y == ((A & B) | (B & C))
    );

// Y equals (A&B) | (B&C) when sampled on C.
    check_y_sop_on_C: assert property (
        @(posedge C) Y == ((A & B) | (B & C))
    );

// Y equals B & (A | C) when sampled on A.
    check_y_factored_on_A: assert property (
        @(posedge A) Y == (B & (A | C))
    );

///// Structural gate-level consistency /////
    // and0 implements A & B.
    check_and0_definition: assert property (
        @(posedge A) and0_out == (A & B)
    );

// not0 implements ~B.
    check_not0_definition: assert property (
        @(posedge A) not0_out == ~B
    );

// not1 implements inversion of not0.
    check_not1_definition: assert property (
        @(posedge A) not1_out == ~not0_out
    );

// and1 implements not1_out & C.
    check_and1_definition: assert property (
        @(posedge A) and1_out == (not1_out & C)
    );

// or0 implements and0_out | and1_out.
    check_or0_definition: assert property (
        @(posedge A) or0_out == (and0_out | and1_out)
    );

// buf0 forwards or0_out to Y.
    check_buf0_definition: assert property (
        @(posedge A) Y == or0_out
    );

///// Simple implications from the Boolean function /////
    // If B is 0 then Y must be 0.
    check_b_zero_forces_y_zero: assert property (
        @(posedge A) (B == 1'b0) |-> (Y == 1'b0)
    );

// Y high implies B is high.
    check_y_implies_b: assert property (
        @(posedge A) (Y == 1'b1) |-> (B == 1'b1)
    );

// If B is high and (A or C) is high then Y is high.
    check_b_and_aorc_implies_y: assert property (
        @(posedge A) (B & (A | C)) |-> (Y == 1'b1)
    );

// If both A and C are low then Y is low.
    check_a0_c0_forces_y0: assert property (
        @(posedge A) ((A == 1'b0) && (C == 1'b0)) |-> (Y == 1'b0)
    );

// EQ must equal (A == B).
    check_eq_definition: assert property (
        @(posedge clk) (EQ === (A == B))
    );

// GT must equal (A > B).
    check_gt_definition: assert property (
        @(posedge clk) (GT === (A > B))
    );

// EQ and GT cannot both be HIGH.
    check_eq_gt_mutex: assert property (
        @(posedge clk) !(EQ && GT)
    );

// If inputs are equal, then EQ=1 and GT=0.
    check_outputs_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT)
    );

// If A is greater than B, then GT=1 and EQ=0.
    check_outputs_when_greater: assert property (
        @(posedge clk) (A > B) |-> (GT && !EQ)
    );

// If A is less than B, then both EQ and GT are 0.
    check_outputs_when_less: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT)
    );

// EQ high implies inputs are equal.
    check_eq_implies_inputs_equal: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// GT high implies A is greater than B.
    check_gt_implies_inputs_ordered: assert property (
        @(posedge clk) GT |-> (A > B)
    );

// EQ high implies GT low.
    check_eq_implies_not_gt: assert property (
        @(posedge clk) EQ |-> !GT
    );

// GT high implies EQ low.
    check_gt_implies_not_eq: assert property (
        @(posedge clk) GT |-> !EQ
    );

// Y equals D & ((A & B) | ~C)
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (!RESETn) Y == (D & ((A & B) | ~C))
    );

// D=0 forces Y=0
    check_D_low_forces_Y_low: assert property (
        @(posedge clk) disable iff (!RESETn) (D == 1'b0) |-> (Y == 1'b0)
    );

// C=0 makes Y follow D
    check_C_low_Y_follows_D: assert property (
        @(posedge clk) disable iff (!RESETn) (C == 1'b0) |-> (Y == D)
    );

// C=1 makes Y == D & A & B
    check_C_high_Y_equals_D_and_A_and_B: assert property (
        @(posedge clk) disable iff (!RESETn) (C == 1'b1) |-> (Y == (D & A & B))
    );

// A=1 and B=1 makes Y follow D
    check_A_and_B_high_Y_follows_D: assert property (
        @(posedge clk) disable iff (!RESETn) (A && B) |-> (Y == D)
    );

// With C=1 and A=0, Y must be 0
    check_C_high_A_low_forces_Y_low: assert property (
        @(posedge clk) disable iff (!RESETn) (C && !A) |-> (Y == 1'b0)
    );

// With C=1 and B=0, Y must be 0
    check_C_high_B_low_forces_Y_low: assert property (
        @(posedge clk) disable iff (!RESETn) (C && !B) |-> (Y == 1'b0)
    );

// Y=1 implies D=1
    check_Y_high_implies_D_high: assert property (
        @(posedge clk) disable iff (!RESETn) (Y == 1'b1) |-> (D == 1'b1)
    );

// Y=1 with C=1 implies A=1 and B=1
    check_Y_high_with_C_high_implies_A_and_B_high: assert property (
        @(posedge clk) disable iff (!RESETn) (Y && C) |-> (A && B)
    );

// With C held low, a rising D causes Y to rise
    check_D_rise_when_C_low_causes_Y_rise: assert property (
        @(posedge clk) disable iff (!RESETn)
            ($past(RESETn) && ($past(C) == 1'b0) && (C == 1'b0) && $rose(D)) |-> (Y == 1'b1)
    );

// With C held low, a falling D causes Y to fall
    check_D_fall_when_C_low_causes_Y_fall: assert property (
        @(posedge clk) disable iff (!RESETn)
            ($past(RESETn) && ($past(C) == 1'b0) && (C == 1'b0) && $fell(D)) |-> (Y == 1'b0)
    );

///// Path selection to driver_sd_avs /////
    // Address mux selects bits [3:2] from the active source.
    check_driver_address_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_address == ((~ao486_rst) ? hdd_avalon_master_address[3:2] : bios_loader_address[3:2])
    );

// Read control is from HDD when ~ao486_rst, else gated BIOS read in 0x0000_0000..0x0000_000F.
    check_driver_read_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_read == ((~ao486_rst) ? hdd_avalon_master_read
                                            : (bios_loader_read && (bios_loader_address[31:4] == 28'h0)))
    );

// Write control is from HDD when ~ao486_rst, else gated BIOS write in 0x0000_0000..0x0000_000F.
    check_driver_write_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_write == ((~ao486_rst) ? hdd_avalon_master_write
                                             : (bios_loader_write && (bios_loader_address[31:4] == 28'h0)))
    );

// Writedata is from the active source without additional gating.
    check_driver_wdata_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        driver_sd_avs_writedata == ((~ao486_rst) ? hdd_avalon_master_writedata : bios_loader_writedata)
    );

///// Return path to masters /////
    // HDD readdata reflects driver data when ~ao486_rst, else 0.
    check_hdd_readdata_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        hdd_avalon_master_readdata == ((~ao486_rst) ? driver_sd_avs_readdata : 32'h0)
    );

// BIOS readdata reflects driver data when ao486_rst, else 0.
    check_bios_readdata_mux: assert property (
        @(posedge clk_sys) disable iff (rst)
        bios_loader_readdata == (ao486_rst ? driver_sd_avs_readdata : 32'h0)
    );

// HDD waitrequest is hardwired LOW.
    check_hdd_waitreq_zero: assert property (
        @(posedge clk_sys) disable iff (rst)
        hdd_avalon_master_waitrequest == 1'b0
    );

// BIOS waitrequest is hardwired LOW.
    check_bios_waitreq_zero: assert property (
        @(posedge clk_sys) disable iff (rst)
        bios_loader_waitrequest == 1'b0
    );

///// BIOS address gating /////
    // When BIOS address is outside 0x0000_0000..0x0000_000F, no read/write reaches the driver.
    check_bios_addr_blocks_access_outside_window: assert property (
        @(posedge clk_sys) disable iff (rst)
        ao486_rst && (bios_loader_address[31:4] != 28'h0) |-> (!driver_sd_avs_read && !driver_sd_avs_write)
    );

///// Functional correctness /////
    // S equals A + B modulo 16 (matches combinational RTL behavior).
    check_sum_mod16: assert property (
        @(posedge clk) S == (A + B)
    );

///// Identities /////
    // Adding zero on A leaves S equal to B.
    check_add_identity_A_zero: assert property (
        @(posedge clk) (A == 4'h0) |-> (S == B)
    );

// Adding zero on B leaves S equal to A.
    check_add_identity_B_zero: assert property (
        @(posedge clk) (B == 4'h0) |-> (S == A)
    );

// Zero plus zero yields zero.
    check_add_zero_zero: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |-> (S == 4'h0)
    );

///// Wrap-around examples (mod-16) /////
    // 15 + 1 wraps to 0.
    check_wrap_F_plus_1_A: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h1) |-> (S == 4'h0)
    );

// 1 + 15 wraps to 0.
    check_wrap_1_plus_F_B: assert property (
        @(posedge clk) (A == 4'h1 && B == 4'hF) |-> (S == 4'h0)
    );

// 15 + 15 yields 14 (mod 16).
    check_15_plus_15: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF) |-> (S == 4'hE)
    );

// Combinational DUT with no clock/reset; assertions sampled on clk.

    // Output equals RTL XOR expression.
    check_xor_equation: assert property (
        @(posedge clk) out_comb == ((a & ~b) | (~a & b))
    );

// Output matches XOR operator directly.
    check_xor_operator_equiv: assert property (
        @(posedge clk) out_comb == (a ^ b)
    );

// Truth table: a=0, b=0 -> out=0.
    check_tt_00: assert property (
        @(posedge clk) (!a && !b) |-> (out_comb == 1'b0)
    );

// Truth table: a=1, b=0 -> out=1.
    check_tt_10: assert property (
        @(posedge clk) (a && !b) |-> (out_comb == 1'b1)
    );

// Truth table: a=0, b=1 -> out=1.
    check_tt_01: assert property (
        @(posedge clk) (!a && b) |-> (out_comb == 1'b1)
    );

// Truth table: a=1, b=1 -> out=0.
    check_tt_11: assert property (
        @(posedge clk) (a && b) |-> (out_comb == 1'b0)
    );

// Output low when inputs are equal.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (a == b) |-> (out_comb == 1'b0)
    );

// Output high when inputs differ.
    check_diff_inputs_one: assert property (
        @(posedge clk) (a != b) |-> (out_comb == 1'b1)
    );

// Commutative form equivalence.
    check_commutative_form: assert property (
        @(posedge clk) out_comb == ((b & ~a) | (~b & a))
    );

// Functional equivalence: out matches the mux/invert expression
    check_functional_equiv: assert property (
        @(posedge clk) out == (C ? (invert ? ~B : B) : A)
    );

// When C==0, out equals A
    check_sel_C0: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == A)
    );

// When C==1 and invert==0, out equals B
    check_sel_C1_inv0: assert property (
        @(posedge clk) ((C == 1'b1) && (invert == 1'b0)) |-> (out == B)
    );

// When C==1 and invert==1, out equals ~B
    check_sel_C1_inv1: assert property (
        @(posedge clk) ((C == 1'b1) && (invert == 1'b1)) |-> (out == ~B)
    );

// When C==1, out equals B XOR invert
    check_C1_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (out == (B ^ invert))
    );

// On C rising, out follows the B/invert path
    check_rose_C: assert property (
        @(posedge clk) $rose(C) |-> (out == (invert ? ~B : B))
    );

// On C falling, out follows A
    check_fell_C: assert property (
        @(posedge clk) $fell(C) |-> (out == A)
    );

// On invert rising while C==1, out becomes ~B
    check_rose_invert_C1: assert property (
        @(posedge clk) (C == 1'b1) && $rose(invert) |-> (out == ~B)
    );

// On invert falling while C==1, out becomes B
    check_fell_invert_C1: assert property (
        @(posedge clk) (C == 1'b1) && $fell(invert) |-> (out == B)
    );

// When B changes and C==1, out updates per invert
    check_B_change_C1: assert property (
        @(posedge clk) (C == 1'b1) && $changed(B) |-> (out == (invert ? ~B : B))
    );

// When A changes and C==0, out updates to A
    check_A_change_C0: assert property (
        @(posedge clk) (C == 1'b0) && $changed(A) |-> (out == A)
    );

///// Reset behavior /////
  // While reset is asserted low, q is forced to 0.
  reset_forces_zero: assert property (
    @(posedge clk) (!reset) |-> (q == 3'b000)
  );

///// Enable gating /////
  // When enable is LOW, q holds its previous value.
  hold_when_disabled: assert property (
    @(posedge clk) disable iff (!reset) (!enable) |=> (q == $past(q))
  );

// q only changes when enable was HIGH in the previous cycle (excluding reset effects).
  change_only_when_enabled: assert property (
    @(posedge clk) disable iff (!reset) (q != $past(q)) |-> $past(enable)
  );

///// Up mode behavior (mode == 0) /////
  // In up mode with enable, non-wrap increment by 1.
  upmode_inc_nonwrap: assert property (
    @(posedge clk) disable iff (!reset) (enable && !mode && (q != 3'b111)) |=> (q == $past(q) + 3'b001)
  );

// In up mode with enable, wrap from 7 to 0.
  upmode_wrap_from_max: assert property (
    @(posedge clk) disable iff (!reset) (enable && !mode && (q == 3'b111)) |=> (q == 3'b000)
  );

// In up mode with enable, wrap occurs iff previous q was 7.
  upmode_wrap_iff_prev_max: assert property (
    @(posedge clk) disable iff (!reset) (enable && !mode) |=> (($past(q) == 3'b111) == (q == 3'b000))
  );

///// Down mode behavior (mode == 1) /////
  // In down mode with enable, non-wrap decrement by 1.
  downmode_dec_nonwrap: assert property (
    @(posedge clk) disable iff (!reset) (enable && mode && (q != 3'b000)) |=> (q == $past(q) - 3'b001)
  );

// In down mode with enable, wrap from 0 to 7.
  downmode_wrap_from_zero: assert property (
    @(posedge clk) disable iff (!reset) (enable && mode && (q == 3'b000)) |=> (q == 3'b111)
  );

// In down mode with enable, wrap occurs iff previous q was 0.
  downmode_wrap_iff_prev_zero: assert property (
    @(posedge clk) disable iff (!reset) (enable && mode) |=> (($past(q) == 3'b000) == (q == 3'b111))
  );

///// General enabled behavior /////
  // When enabled, q must change every cycle (either +/-1 with wrap).
  enabled_always_changes: assert property (
    @(posedge clk) disable iff (!reset) enable |=> (q != $past(q))
  );

// During reset, readdata is 0.
    check_reset_forces_zero: assert property (
        @(posedge clock) (!reset_n) |-> (readdata == 32'h00000000)
    );

// On falling edge of reset_n, readdata is 0 at this sample.
    check_reset_fall_clears_output: assert property (
        @(posedge clock) $fell(reset_n) |-> (readdata == 32'h00000000)
    );

// On rising edge of reset_n, readdata remains 0 in this cycle.
    check_reset_rise_zero_this_cycle: assert property (
        @(posedge clock) $rose(reset_n) |-> (readdata == 32'h00000000)
    );

// If address==0 and remain out of reset, next-cycle readdata is 0xFF.
    check_forward_pipeline_zero: assert property (
        @(posedge clock) disable iff (!reset_n)
            (address == 32'h00000000) |-> ##1 (reset_n && (readdata == 32'h000000FF))
    );

// If address!=0 and remain out of reset, next-cycle readdata is 0x590D8D31.
    check_forward_pipeline_nonzero: assert property (
        @(posedge clock) disable iff (!reset_n)
            (address != 32'h00000000) |-> ##1 (reset_n && (readdata == 32'h590D8D31))
    );

///// Reset behavior /////
    // When rst is HIGH at a clock edge, count must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// During reset, count is known and zero (no X/Z while rst is HIGH).
    check_known_zero_during_reset: assert property (
        @(posedge clk) rst |-> (!$isunknown(count) && count == 4'd0)
    );

// EQ must equal bitwise equality across all four positions.
    check_eq_matches_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
        EQ == ((A == E) && (B == F) && (C == G) && (D == H))
    );

// GT must match the coded lexicographic comparison (with final D >= H).
    check_gt_matches_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
        GT == (
            (A > E) ||
            ((A == E) && (
                (B > F) ||
                ((B == F) && (
                    (C > G) ||
                    ((C == G) && (D >= H))
                ))
            ))
        )
    );

// When all four positions are equal, GT must be high (due to D >= H).
    check_eq_implies_gt: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == E) && (B == F) && (C == G) && (D == H)) |-> (GT == 1'b1)
    );

// If A > E, GT must be high.
    check_a_gt_e_implies_gt: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (A > E) |-> (GT == 1'b1)
    );

// If A == E and B > F, GT must be high.
    check_b_gt_f_implies_gt_when_a_eq_e: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == E) && (B > F)) |-> (GT == 1'b1)
    );

// If A == E, B == F, and C > G, GT must be high.
    check_c_gt_g_implies_gt_when_prefix_equal: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == E) && (B == F) && (C > G)) |-> (GT == 1'b1)
    );

// If A == E, B == F, C == G, and D >= H, GT must be high.
    check_d_ge_h_implies_gt_when_prefix_equal: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == E) && (B == F) && (C == G) && (D >= H)) |-> (GT == 1'b1)
    );

// If A < E, GT must be low.
    check_a_lt_e_implies_not_gt: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (A < E) |-> (GT == 1'b0)
    );

// If A == E and B < F, GT must be low.
    check_b_lt_f_implies_not_gt_when_a_eq_e: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == E) && (B < F)) |-> (GT == 1'b0)
    );

// If A == E, B == F, and C < G, GT must be low.
    check_c_lt_g_implies_not_gt_when_prefix_equal: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == E) && (B == F) && (C < G)) |-> (GT == 1'b0)
    );

// If A == E, B == F, C == G, and D < H, GT must be low.
    check_d_lt_h_implies_not_gt_when_prefix_equal: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((A == E) && (B == F) && (C == G) && (D < H)) |-> (GT == 1'b0)
    );

///// Anode decode /////
    // sel==00 drives anode to 1110
    check_anode_sel00_map: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'b00) |-> (anode == 4'b1110)
    );

// sel==01 drives anode to 1101
    check_anode_sel01_map: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'b01) |-> (anode == 4'b1101)
    );

// sel==10 drives anode to 1011
    check_anode_sel10_map: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'b10) |-> (anode == 4'b1011)
    );

// sel==11 drives anode to 0111
    check_anode_sel11_map: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 2'b11) |-> (anode == 4'b0111)
    );

///// Cathode decode /////
    // digit==0 maps to 0000001
    check_cathode_digit_0: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h0) |-> (cathode == 7'b0000001)
    );

// digit==1 maps to 1001111
    check_cathode_digit_1: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h1) |-> (cathode == 7'b1001111)
    );

// digit==2 maps to 0010010
    check_cathode_digit_2: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h2) |-> (cathode == 7'b0010010)
    );

// digit==3 maps to 0000110
    check_cathode_digit_3: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h3) |-> (cathode == 7'b0000110)
    );

// digit==4 maps to 1001100
    check_cathode_digit_4: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h4) |-> (cathode == 7'b1001100)
    );

// digit==5 maps to 0100100
    check_cathode_digit_5: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h5) |-> (cathode == 7'b0100100)
    );

// digit==6 maps to 0100000
    check_cathode_digit_6: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h6) |-> (cathode == 7'b0100000)
    );

// digit==7 maps to 0001111
    check_cathode_digit_7: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h7) |-> (cathode == 7'b0001111)
    );

// digit==8 maps to 0000000
    check_cathode_digit_8: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h8) |-> (cathode == 7'b0000000)
    );

// digit==9 maps to 0000100
    check_cathode_digit_9: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'h9) |-> (cathode == 7'b0000100)
    );

// digit==A maps to 0001000
    check_cathode_digit_a: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'ha) |-> (cathode == 7'b0001000)
    );

// digit==B maps to 1100000
    check_cathode_digit_b: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'hb) |-> (cathode == 7'b1100000)
    );

// digit==C maps to 0110001
    check_cathode_digit_c: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'hc) |-> (cathode == 7'b0110001)
    );

// digit==D maps to 1000012 (1000010)
    check_cathode_digit_d: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'hd) |-> (cathode == 7'b1000010)
    );

// digit==E maps to 0110000
    check_cathode_digit_e: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'he) |-> (cathode == 7'b0110000)
    );

// digit==F maps to 0111000
    check_cathode_digit_f: assert property (
        @(posedge clk) disable iff (1'b0) (digit == 4'hf) |-> (cathode == 7'b0111000)
    );

// sgmii_txn is the bitwise inverse of sgmii_rxn.
   check_txn_inverts_rxn: assert property (
      @(posedge sgmii_refclk_p) sgmii_txn === (sgmii_rxn ^ 4'b1111)
   );

// sgmii_txp is the bitwise inverse of sgmii_rxp.
   check_txp_inverts_rxp: assert property (
      @(posedge sgmii_refclk_p) sgmii_txp === (sgmii_rxp ^ 4'b1111)
   );

// sgmii_txn[0] equals inverse of sgmii_rxn[0].
   check_txn_b0_inverts_rxn_b0: assert property (
      @(posedge sgmii_refclk_p) sgmii_txn[0] === (~sgmii_rxn[0])
   );

// sgmii_txn[3] equals inverse of sgmii_rxn[3].
   check_txn_b3_inverts_rxn_b3: assert property (
      @(posedge sgmii_refclk_p) sgmii_txn[3] === (~sgmii_rxn[3])
   );

// sgmii_txp[0] equals inverse of sgmii_rxp[0].
   check_txp_b0_inverts_rxp_b0: assert property (
      @(posedge sgmii_refclk_p) sgmii_txp[0] === (~sgmii_rxp[0])
   );

// sgmii_txp[3] equals inverse of sgmii_rxp[3].
   check_txp_b3_inverts_rxp_b3: assert property (
      @(posedge sgmii_refclk_p) sgmii_txp[3] === (~sgmii_rxp[3])
   );

// mdio_mdc mirrors pl_btn.
   check_mdio_follows_btn: assert property (
      @(posedge sgmii_refclk_p) mdio_mdc === pl_btn
   );

// pl_pmod[1] mirrors pl_btn.
   check_pmod1_follows_btn: assert property (
      @(posedge sgmii_refclk_p) pl_pmod[1] === pl_btn
   );

// pl_pmod[1] matches mdio_mdc.
   check_pmod1_matches_mdio: assert property (
      @(posedge sgmii_refclk_p) pl_pmod[1] === mdio_mdc
   );

///// Functional correctness /////
    // X equals the defined boolean function of inputs.
    check_functional_equivalence: assert property (
        @(posedge VPWR) X == (A1 & A2 & A3 & ~B1 & ~B2 & VPWR & ~VGND & VPB & ~VNB)
    );

///// Gating: any required-true input low forces X low /////
    // A1 low forces X low.
    gate_A1_low_forces_X0: assert property (
        @(posedge VPWR) (!A1) |-> (X == 1'b0)
    );

// A2 low forces X low.
    gate_A2_low_forces_X0: assert property (
        @(posedge VPWR) (!A2) |-> (X == 1'b0)
    );

// A3 low forces X low.
    gate_A3_low_forces_X0: assert property (
        @(posedge VPWR) (!A3) |-> (X == 1'b0)
    );

///// Gating: any required-false input high forces X low /////
    // B1 high forces X low.
    gate_B1_high_forces_X0: assert property (
        @(posedge VPWR) (B1) |-> (X == 1'b0)
    );

// B2 high forces X low.
    gate_B2_high_forces_X0: assert property (
        @(posedge VPWR) (B2) |-> (X == 1'b0)
    );

///// Power/body rails gating /////
    // VPWR low forces X low.
    gate_VPWR_low_forces_X0: assert property (
        @(posedge VPWR) (!VPWR) |-> (X == 1'b0)
    );

// VGND high forces X low.
    gate_VGND_high_forces_X0: assert property (
        @(posedge VPWR) (VGND) |-> (X == 1'b0)
    );

// VPB low forces X low.
    gate_VPB_low_forces_X0: assert property (
        @(posedge VPWR) (!VPB) |-> (X == 1'b0)
    );

// VNB high forces X low.
    gate_VNB_high_forces_X0: assert property (
        @(posedge VPWR) (VNB) |-> (X == 1'b0)
    );

///// Transition sanity /////
    // X can only rise when all required conditions are met.
    check_X_rise_requires_minterm: assert property (
        @(posedge VPWR) $rose(X) |-> (A1 & A2 & A3 & ~B1 & ~B2 & VPWR & ~VGND & VPB & ~VNB)
    );

// X can only fall when the minterm is not satisfied.
    check_X_fall_requires_not_minterm: assert property (
        @(posedge VPWR) $fell(X) |-> !(A1 & A2 & A3 & ~B1 & ~B2 & VPWR & ~VGND & VPB & ~VNB)
    );

///// Reset behavior /////
    // When reset is LOW at a clock edge, count must be 0.
    check_reset_low_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 3'd0)
    );

// On a falling edge of reset between clock edges, count must be 0 at this clock.
    check_reset_fall_clears_count: assert property (
        @(posedge clk) $fell(reset) |-> (count == 3'd0)
    );

// While reset is held LOW across consecutive clocks, count remains 0.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (reset == 1'b0) && ($past(reset) == 1'b0) |-> (count == 3'd0)
    );

///// Normal counting rules (enabled when reset is HIGH) /////
    // When reset is HIGH for two consecutive clocks and prior count < 7, increment by 1.
    check_increment_when_below_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && reset && ($past(count) != 3'd7)) |-> (count == ($past(count) + 3'd1))
    );

// When reset is HIGH for two consecutive clocks and prior count == 7, wrap to 0.
    check_wrap_to_zero_from_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && reset && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

// With reset HIGH for two consecutive clocks, count must change every cycle (no stalls).
    check_change_each_cycle_when_enabled: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && reset) |-> (count != $past(count))
    );

check_period_8_when_enabled: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            reset_high_8 |-> (count == $past(count, 8))
    );

///// Reset behavior /////
  // While reset is asserted low, data_out must be zero.
  reset_clears_output: assert property (
    @(posedge clk) !reset |-> (data_out == 8'b0)
  );

///// Load behavior /////
  // When load is high, data_out updates to data_in in the same cycle.
  load_updates_immediately: assert property (
    @(posedge clk) disable iff (!reset) load |-> (data_out == data_in)
  );

///// Rotate behavior when not loading /////
  // When load is low, data_out rotates left by one bit from the previous value.
  rotate_one_step_vector: assert property (
    @(posedge clk) disable iff (!reset) !load |-> (data_out == { $past(data_out[6:0]), $past(data_out[7]) })
  );

// Bit 7 takes previous bit 6 when not loading.
  rotate_bit7_from6: assert property (
    @(posedge clk) disable iff (!reset) !load |-> (data_out[7] == $past(data_out[6]))
  );

// Bit 0 takes previous bit 7 when not loading.
  rotate_bit0_from7: assert property (
    @(posedge clk) disable iff (!reset) !load |-> (data_out[0] == $past(data_out[7]))
  );

// Eight consecutive rotates return data_out to its value from eight cycles earlier.
  rotate_eight_cycle_identity: assert property (
    @(posedge clk) disable iff (!reset) (!load)[*8] |-> (data_out == $past(data_out, 8))
  );

///// Post-reset first-cycle behavior /////
  // On the first cycle after reset deasserts with no load, data_out remains zero.
  first_cycle_after_reset_no_load_zero: assert property (
    @(posedge clk) $rose(reset) && !load |-> (data_out == 8'b0)
  );

// On the first cycle after reset deasserts with load, data_out equals data_in.
  first_cycle_after_reset_with_load_loads: assert property (
    @(posedge clk) $rose(reset) && load |-> (data_out == data_in)
  );

// For any C, if A==B then diff must be 0.
    check_zero_when_inputs_equal: assert property (
        @(posedge CLK) (A == B) |-> (diff == 5'd0)
    );

// For any C, diff==0 implies A==B.
    check_zero_implies_inputs_equal: assert property (
        @(posedge CLK) (diff == 5'd0) |-> (A == B)
    );

// When C=1 and A!=B, diff must be non-zero.
    check_nonzero_when_notequal_and_C1: assert property (
        @(posedge CLK) (C == 1'b1 && (A != B)) |-> (diff != 5'd0)
    );

// When C=0 and A!=B, diff must be non-zero.
    check_nonzero_when_notequal_and_C0: assert property (
        @(posedge CLK) (C == 1'b0 && (A != B)) |-> (diff != 5'd0)
    );

///// Reset behavior /////
    // While RESET is asserted, COUNT must be 0.
    check_reset_clears_count: assert property (
        @(posedge CLK) RESET |-> (COUNT == 4'd0)
    );

///// Load behavior /////
    // On non-zero LOAD, COUNT is updated to LOAD on the next clock.
    check_load_updates_count: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD != 4'd0) |=> (RESET || (COUNT == $past(LOAD)))
    );

///// Counting behavior /////
    // With LOAD == 0 and UP_DOWN == 1, COUNT increments by 1 on the next clock.
    check_increment_when_up: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b1)) |=> (RESET || (COUNT == ($past(COUNT) + 4'd1)))
    );

// With LOAD == 0 and UP_DOWN == 0, COUNT decrements by 1 on the next clock.
    check_decrement_when_down: assert property (
        @(posedge CLK) disable iff (RESET)
            (LOAD == 4'd0 && (UP_DOWN == 1'b0)) |=> (RESET || (COUNT == ($past(COUNT) - 4'd1)))
    );

///// Functional mapping /////
    // When sel is 2-state, output equals the selected input bit.
    check_mux_function_general: assert property (
        @(posedge clk) (sel inside {2'b00,2'b01,2'b10,2'b11}) |-> (data_out === data_in[sel])
    );

// sel==00 routes data_in[0] to data_out.
    check_sel_00_route: assert property (
        @(posedge clk) (sel === 2'b00) |-> (data_out === data_in[0])
    );

// sel==01 routes data_in[1] to data_out.
    check_sel_01_route: assert property (
        @(posedge clk) (sel === 2'b01) |-> (data_out === data_in[1])
    );

// sel==10 routes data_in[2] to data_out.
    check_sel_10_route: assert property (
        @(posedge clk) (sel === 2'b10) |-> (data_out === data_in[2])
    );

// sel==11 routes data_in[3] to data_out.
    check_sel_11_route: assert property (
        @(posedge clk) (sel === 2'b11) |-> (data_out === data_in[3])
    );

// Y must be 1 when A > B.
    check_y_high_when_a_gt_b: assert property (
        @(posedge CLK) (A > B) |-> (Y == 1'b1)
    );

// Y must be 0 when A <= B.
    check_y_low_when_a_le_b: assert property (
        @(posedge CLK) (A <= B) |-> (Y == 1'b0)
    );

// If Y is 1 then A must be greater than B.
    check_y1_implies_a_gt_b: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A > B)
    );

// If MSBs differ and A[1]=1,B[1]=0 then Y must be 1.
    check_msb_diff_a1_b0: assert property (
        @(posedge CLK) (A[1] && !B[1]) |-> (Y == 1'b1)
    );

// If MSBs differ and A[1]=0,B[1]=1 then Y must be 0.
    check_msb_diff_a0_b1: assert property (
        @(posedge CLK) (!A[1] && B[1]) |-> (Y == 1'b0)
    );

// If MSBs equal, comparison reduces to LSB: Y == (A[0] & ~B[0]).
    check_msb_equal_lsb_decides: assert property (
        @(posedge CLK) (A[1] == B[1]) |-> (Y == (A[0] & ~B[0]))
    );

// If A equals B then Y must be 0.
    check_equal_inputs_y0: assert property (
        @(posedge CLK) (A == B) |-> (Y == 1'b0)
    );

// If A is 0 then Y must be 0.
    check_a_zero_y0: assert property (
        @(posedge CLK) (A == 2'b00) |-> (Y == 1'b0)
    );

// If B is 3 then Y must be 0.
    check_b_three_y0: assert property (
        @(posedge CLK) (B == 2'b11) |-> (Y == 1'b0)
    );

// If A is 3 and B is not 3 then Y must be 1.
    check_a_three_gt_non_three: assert property (
        @(posedge CLK) (A == 2'b11 && B != 2'b11) |-> (Y == 1'b1)
    );

///// Functional mapping /////
    // MSB mapping: gray[3] equals binary[3].
    check_gray_bit3_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] === binary[3]
    );

// gray[2] is binary[3] XOR binary[2].
    check_gray_bit2_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] === (binary[3] ^ binary[2])
    );

// gray[1] is binary[2] XOR binary[1].
    check_gray_bit1_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] === (binary[2] ^ binary[1])
    );

// gray[0] is binary[1] XOR binary[0].
    check_gray_bit0_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] === (binary[1] ^ binary[0])
    );

// Full vector mapping matches {b3, b3^b2, b2^b1, b1^b0}.
    check_gray_full_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray === {binary[3], (binary[3]^binary[2]), (binary[2]^binary[1]), (binary[1]^binary[0])}
    );

// Reset low forces count to zero at each clock.
    reset_low_clears_count: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 3'd0)
    );

// Out of reset, next count matches prev control: +1 when 0, -1 when 1.
    count_update_matches_prev_control: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            $past(reset) |-> (count == ($past(control) ? ($past(count) - 3'd1) : ($past(count) + 3'd1)))
    );

// Up-count wraps from 7 to 0 when previous control was 0.
    wrap_up_on_7_to_0: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b0) && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

// Down-count wraps from 0 to 7 when previous control was 1.
    wrap_down_on_0_to_7: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b1) && ($past(count) == 3'd0)) |-> (count == 3'd7)
    );

// Up-count increments by exactly one when not wrapping.
    increment_no_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b0) && ($past(count) != 3'd7)) |-> (count == $past(count) + 3'd1)
    );

// Down-count decrements by exactly one when not wrapping.
    decrement_no_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b1) && ($past(count) != 3'd0)) |-> (count == $past(count) - 3'd1)
    );

// While reset remains asserted across cycles, count stays at zero.
    hold_zero_during_reset: assert property (
        @(posedge clk) (!$past(reset) && !reset) |-> (count == 3'd0)
    );

// Y must equal (~A & ~B) | (~C & ~D).
    check_function_equivalence: assert property (
        @(posedge clk) Y == ((~(A | B)) | (~(C | D)))
    );

// If A and B are both 0, Y must be 1.
    check_y_high_when_ab00: assert property (
        @(posedge clk) (A == 1'b0) && (B == 1'b0) |-> (Y == 1'b1)
    );

// If C and D are both 0, Y must be 1.
    check_y_high_when_cd00: assert property (
        @(posedge clk) (C == 1'b0) && (D == 1'b0) |-> (Y == 1'b1)
    );

// If each pair has at least one '1', Y must be 0.
    check_y_low_when_each_pair_has_one: assert property (
        @(posedge clk) ((A | B) && (C | D)) |-> (Y == 1'b0)
    );

// If A and B are both 1, Y equals (~C & ~D).
    check_y_equals_notC_and_notD_when_ab11: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) |-> (Y == ((~C) & (~D)))
    );

// If Y is 1, at least one pair (A,B) or (C, D) is 00.
    check_y1_implies_some_pair_zero: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((~A & ~B) || (~C & ~D))
    );

// Falling A with B=0 and others stable forces Y=1.
    force_y1_on_A_fall_with_B0: assert property (
        @(posedge clk) $fell(A) && (B == 1'b0) && $stable(B) && $stable(C) && $stable(D) |-> (Y == 1'b1)
    );

// Falling C with D=0 and others stable forces Y=1.
    force_y1_on_C_fall_with_D0: assert property (
        @(posedge clk) $fell(C) && (D == 1'b0) && $stable(A) && $stable(B) && $stable(D) |-> (Y == 1'b1)
    );

// Clock: clk; Reset: rst (active-high, synchronous)
    // Behavior: sequential register with enable; data_out mirrors stored_data combinationally

    // On reset, output becomes 0 on the next cycle.
    reset_clears_output: assert property (
        @(posedge clk) rst |=> (data_out == 8'h00)
    );

// With enable HIGH (and not in reset), next cycle output equals previous data_in.
    write_updates_output: assert property (
        @(posedge clk) disable iff (rst) enable |=> (data_out == $past(data_in))
    );

// With enable LOW (and not in reset), next cycle output holds its value.
    hold_when_enable_low: assert property (
        @(posedge clk) disable iff (rst) !enable |=> (data_out == $past(data_out))
    );

// Two back-to-back enables: at the second-next cycle, output equals data_in from the prior cycle.
    two_writes_in_sequence: assert property (
        @(posedge clk) disable iff (rst) (enable ##1 enable) |=> (data_out == $past(data_in, 1))
    );

// Two cycles with enable LOW: output equals the value from two cycles earlier.
    hold_two_cycles_no_enable: assert property (
        @(posedge clk) disable iff (rst) (!enable ##1 !enable) |=> (data_out == $past(data_out, 2))
    );

// If data_in changes while enable is LOW, output still holds on the next cycle.
    hold_despite_input_change: assert property (
        @(posedge clk) disable iff (rst) (!enable && $changed(data_in)) |=> (data_out == $past(data_out))
    );

// Reset dominates enable: if both are HIGH, next cycle output is 0.
    reset_overrides_enable: assert property (
        @(posedge clk) (rst && enable) |=> (data_out == 8'h00)
    );

// Next cycle valid reflects load HIGH this cycle.
    valid_next_high_when_load_high: assert property (
        @(posedge clk) load |=> (valid == 1'b1)
    );

// Next cycle valid reflects load LOW this cycle.
    valid_next_low_when_load_low: assert property (
        @(posedge clk) !load |=> (valid == 1'b0)
    );

// When load is LOW, out is cleared to zero in the next cycle.
    out_cleared_next_on_no_load: assert property (
        @(posedge clk) !load |=> (out == 4'b0000)
    );

// A falling load clears both valid and out in the next cycle.
    clear_valid_and_out_on_load_fall: assert property (
        @(posedge clk) $fell(load) |=> (!valid && (out == 4'b0000))
    );

// Four consecutive cycles of load HIGH pipeline in to out with 4-cycle latency.
    four_cycle_load_delays_input_to_out: assert property (
        @(posedge clk) load[*4] |=> (out == $past(in,4))
    );

// After four consecutive load HIGH cycles, valid is HIGH in the next cycle.
    valid_high_after_four_loads: assert property (
        @(posedge clk) load[*4] |=> (valid == 1'b1)
    );

// X equals A|B|C|~D_N (truth function of the gate).
    check_function_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn) X == (A | B | C | ~D_N)
    );

// A high forces X high.
    check_A_forces_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (A == 1'b1) |-> (X == 1'b1)
    );

// B high forces X high.
    check_B_forces_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (B == 1'b1) |-> (X == 1'b1)
    );

// C high forces X high.
    check_C_forces_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (C == 1'b1) |-> (X == 1'b1)
    );

// D_N low (i.e., ~D_N high) forces X high.
    check_DN_low_forces_high: assert property (
        @(posedge CLK) disable iff (!RESETn) (D_N == 1'b0) |-> (X == 1'b1)
    );

// All inputs low and D_N high yield X low.
    check_all_low_results_low: assert property (
        @(posedge CLK) disable iff (!RESETn) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == 1'b0)
    );

// X low implies A,B,C are low and D_N is high.
    check_x_low_implies_inputs_low: assert property (
        @(posedge CLK) disable iff (!RESETn) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1))
    );

// C implements (~(A & B)) & (A | B) bitwise.
    check_functional_equation: assert property (
        @(posedge clk) disable iff (1'b0) C === ((~(A & B)) & (A | B))
    );

// C is equivalent to bitwise XOR of A and B.
    check_xor_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) C === (A ^ B)
    );

// If inputs are fully known, output must be fully known.
    check_known_inputs_imply_known_output: assert property (
        @(posedge clk) disable iff (1'b0) (!$isunknown({A,B})) |-> (!$isunknown(C))
    );

// When A equals B, C must be all zeros.
    check_equal_inputs_zero: assert property (
        @(posedge clk) disable iff (1'b0) (A === B) |-> (C === 8'h00)
    );

// When A is bitwise complement of B, C must be all ones.
    check_complement_inputs_ones: assert property (
        @(posedge clk) disable iff (1'b0) (A === ~B) |-> (C === 8'hFF)
    );

// XOR identity: A ^ 0 = A -> C equals B when A is zero.
    check_identity_A_zero: assert property (
        @(posedge clk) disable iff (1'b0) (A === 8'h00) |-> (C === B)
    );

// XOR identity: 0 ^ B = B -> C equals A when B is zero.
    check_identity_B_zero: assert property (
        @(posedge clk) disable iff (1'b0) (B === 8'h00) |-> (C === A)
    );

// XOR with all ones: A ^ FF = ~A -> C equals ~B when A is all ones.
    check_invert_when_A_ones: assert property (
        @(posedge clk) disable iff (1'b0) (A === 8'hFF) |-> (C === ~B)
    );

// XOR with all ones: FF ^ B = ~B -> C equals ~A when B is all ones.
    check_invert_when_B_ones: assert property (
        @(posedge clk) disable iff (1'b0) (B === 8'hFF) |-> (C === ~A)
    );

// Parity consistency: parity(C) equals parity(A) XOR parity(B) when inputs known.
    check_parity_consistency: assert property (
        @(posedge clk) disable iff (1'b0) (!$isunknown({A,B})) |-> ((^C) === ((^A) ^ (^B)))
    );

///// Functional mapping /////
    // For {ABC,EN}=4'b0001, Y must be 8'b00000001.
    map_0001: assert property (
        @(posedge CLK) disable iff (!RESETn) ((ABC == 3'b000) && (EN == 1'b1)) |-> (Y == 8'b00000001)
    );

// For {ABC,EN}=4'b0010, Y must be 8'b00000010.
    map_0010: assert property (
        @(posedge CLK) disable iff (!RESETn) ((ABC == 3'b001) && (EN == 1'b0)) |-> (Y == 8'b00000010)
    );

// For {ABC,EN}=4'b0011, Y must be 8'b00000100.
    map_0011: assert property (
        @(posedge CLK) disable iff (!RESETn) ((ABC == 3'b001) && (EN == 1'b1)) |-> (Y == 8'b00000100)
    );

// For {ABC,EN}=4'b0100, Y must be 8'b00001000.
    map_0100: assert property (
        @(posedge CLK) disable iff (!RESETn) ((ABC == 3'b010) && (EN == 1'b0)) |-> (Y == 8'b00001000)
    );

// For {ABC,EN}=4'b0101, Y must be 8'b00010000.
    map_0101: assert property (
        @(posedge CLK) disable iff (!RESETn) ((ABC == 3'b010) && (EN == 1'b1)) |-> (Y == 8'b00010000)
    );

// For {ABC,EN}=4'b0110, Y must be 8'b00100000.
    map_0110: assert property (
        @(posedge CLK) disable iff (!RESETn) ((ABC == 3'b011) && (EN == 1'b0)) |-> (Y == 8'b00100000)
    );

// For {ABC,EN}=4'b0111, Y must be 8'b01000000.
    map_0111: assert property (
        @(posedge CLK) disable iff (!RESETn) ((ABC == 3'b011) && (EN == 1'b1)) |-> (Y == 8'b01000000)
    );

///// Output shape invariants /////
    // Y is zero or one-hot (at most one bit set).
    check_onehot0: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot0(Y)
    );

// Bit 7 of Y is never asserted.
    check_y7_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y[7] == 1'b0)
    );

// On a non-reset cycle, next out equals current out plus in (16-bit wraparound).
    check_add_update: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> out == $past(out) + $past(in)
    );

// If in is zero and not in reset, out holds its value next cycle.
    check_hold_when_in_zero: assert property (
        @(posedge clk) disable iff (reset) (in == 8'd0) |=> out == $past(out)
    );

// If in is 1 and not in reset, out increments by 1 next cycle.
    check_increment_by_one: assert property (
        @(posedge clk) disable iff (reset) (in == 8'd1) |=> out == $past(out) + 16'd1
    );

// If in is 255 and not in reset, out increments by 255 next cycle.
    check_increment_by_255: assert property (
        @(posedge clk) disable iff (reset) (in == 8'hFF) |=> out == $past(out) + 16'd255
    );

///// Byte swap rules /////
    // out must be the byte-swapped version of in.
    check_byte_swap_mapping_full: assert property (
        @(posedge CLK) disable iff (!RESETn) out == swap_bytes(in)
    );

// Byte swap is an involution: in must equal byte-swap of out.
    check_byte_swap_symmetry: assert property (
        @(posedge CLK) disable iff (!RESETn) in == swap_bytes(out)
    );

// High byte of out equals low byte of in.
    check_out_high_byte_mapping: assert property (
        @(posedge CLK) disable iff (!RESETn) out[31:24] == in[7:0]
    );

// Low byte of out equals high byte of in.
    check_out_low_byte_mapping: assert property (
        @(posedge CLK) disable iff (!RESETn) out[7:0] == in[31:24]
    );

///// Reset behavior /////
  // When reset is asserted LOW, output must be 0.
  check_reset_low_forces_zero: assert property (
    @(posedge clk) (!reset) |-> (output_signal == 4'b0)
  );

// On falling edge of reset, output must be 0 in the same sampled cycle.
  check_reset_fall_forces_zero: assert property (
    @(posedge clk) $fell(reset) |-> (output_signal == 4'b0)
  );

///// Sequential capture of upper nibble /////
  // Out of reset for two cycles: output equals previous cycle's input[15:12].
  check_capture_prev_cycle_nibble: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset)) |-> (output_signal == $past(input_signal[15:12]))
  );

// Bit mapping: output[3] captures previous input_signal[15].
  check_bit3_map_prev15: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset)) |-> (output_signal[3] == $past(input_signal[15]))
  );

// Bit mapping: output[2] captures previous input_signal[14].
  check_bit2_map_prev14: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset)) |-> (output_signal[2] == $past(input_signal[14]))
  );

// Bit mapping: output[1] captures previous input_signal[13].
  check_bit1_map_prev13: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset)) |-> (output_signal[1] == $past(input_signal[13]))
  );

// Bit mapping: output[0] captures previous input_signal[12].
  check_bit0_map_prev12: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset)) |-> (output_signal[0] == $past(input_signal[12]))
  );

///// Stability and change relations /////
  // If high nibble was stable over the last two cycles (and out of reset), output holds its previous value.
  check_output_stable_when_nibble_stable: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset) && $past(reset,2) &&
       ($past(input_signal[15:12]) == $past(input_signal[15:12],2)))
      |-> (output_signal == $past(output_signal))
  );

// If output changed since last cycle (and out of reset), then the prior two-cycle nibbles differed.
  check_output_change_implies_nibble_change: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset) && $past(reset,2) &&
       (output_signal != $past(output_signal)))
      |-> ($past(input_signal[15:12]) != $past(input_signal[15:12],2))
  );

// If the prior two-cycle nibbles differed (and out of reset), output must change this cycle.
  check_nibble_change_implies_output_change: assert property (
    @(posedge clk) disable iff (!reset)
      (reset && $past(reset) && $past(reset,2) &&
       ($past(input_signal[15:12]) != $past(input_signal[15:12],2)))
      |-> (output_signal != $past(output_signal))
  );

///// Reset behavior /////
    // While reset is asserted low, X must be 0.
    check_reset_forces_x_low: assert property (
        @(posedge clk) (rst == 1'b0) |-> (X == 1'b0)
    );

// On the cycle reset deasserts (low->high), X remains 0 (register updates after this edge).
    check_zero_on_reset_release_cycle: assert property (
        @(posedge clk) $rose(rst) |-> (X == 1'b0)
    );

///// Registered 4-input AND behavior /////
    // When out of reset for two cycles, X equals previous cycle's A&B&C&D.
    check_registered_and_equivalence: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> (X == $past(A & B & C & D))
    );

// If all inputs are 1 in this cycle, X will be 1 next cycle (out of reset).
    check_all_ones_implies_x1_next: assert property (
        @(posedge clk) disable iff (!rst) (A & B & C & D) |=> (X == 1'b1)
    );

// If any input is 0 in this cycle, X will be 0 next cycle (out of reset).
    check_any_zero_implies_x0_next: assert property (
        @(posedge clk) disable iff (!rst) !(A & B & C & D) |=> (X == 1'b0)
    );

// After a reset assertion (high->low), X is 0 on the following cycle.
    check_zero_after_reset_assertion_next: assert property (
        @(posedge clk) $fell(rst) |=> (X == 1'b0)
    );

// q is the bitwise complement of data[0].
    check_q_complement_data0: assert property (
        @(posedge clk) q == ~data[0]
    );

// zero is NOR of data[1:0].
    check_zero_is_nor: assert property (
        @(posedge clk) zero == ~(data[0] | data[1])
    );

// zero high implies q high (since data==2'b00).
    check_zero_implies_q: assert property (
        @(posedge clk) zero |-> (q == 1'b1)
    );

// Any data bit high forces zero low.
    check_any_data_one_forces_zero_low: assert property (
        @(posedge clk) (data[0] | data[1]) |-> (zero == 1'b0)
    );

// zero equals q AND not data[1].
    check_zero_equals_q_and_not_data1: assert property (
        @(posedge clk) zero == (q & ~data[1])
    );

// q and data[0] are never both 1.
    check_q_data0_mutex: assert property (
        @(posedge clk) !(q & data[0])
    );

// Truth table: data==2'b00 => q=1, zero=1.
    check_tt_00: assert property (
        @(posedge clk) (data == 2'b00) |-> (q == 1'b1 && zero == 1'b1)
    );

// Truth table: data==2'b01 => q=0, zero=0.
    check_tt_01: assert property (
        @(posedge clk) (data == 2'b01) |-> (q == 1'b0 && zero == 1'b0)
    );

// Truth table: data==2'b10 => q=1, zero=0.
    check_tt_10: assert property (
        @(posedge clk) (data == 2'b10) |-> (q == 1'b1 && zero == 1'b0)
    );

// Truth table: data==2'b11 => q=0, zero=0.
    check_tt_11: assert property (
        @(posedge clk) (data == 2'b11) |-> (q == 1'b0 && zero == 1'b0)
    );

// Asynchronous reset drives clk_o and count to 0.
    reset_forces_zero: assert property (
        @(posedge clk_i) !reset_n |-> (clk_o == 1'b0) && (count == 15'd0)
    );

// When TE==0 at a clock edge, ENCLK updates next cycle to match sampled EN.
    check_update_next_cycle_match_en: assert property (
        @(posedge CLK) (TE == 1'b0) |-> ##1 (ENCLK == $past(EN))
    );

// When TE==0 and EN==1 at a clock edge, ENCLK becomes 1 on the next clock.
    check_update_next_cycle_to_one: assert property (
        @(posedge CLK) (TE == 1'b0 && EN == 1'b1) |-> ##1 (ENCLK == 1'b1)
    );

// When TE==0 and EN==0 at a clock edge, ENCLK becomes 0 on the next clock.
    check_update_next_cycle_to_zero: assert property (
        @(posedge CLK) (TE == 1'b0 && EN == 1'b0) |-> ##1 (ENCLK == 1'b0)
    );

// When TE==1 at a clock edge, ENCLK holds its value to the next clock.
    check_hold_when_te_high: assert property (
        @(posedge CLK) (TE == 1'b1) |-> ##1 (ENCLK == $past(ENCLK))
    );

// out[0] equals in[1] OR in[3].
    check_out0_mapping: assert property (
        @(posedge CLK) disable iff (1'b0) out[0] == (in[1] | in[3])
    );

// out[1] equals in[2] OR in[3].
    check_out1_mapping: assert property (
        @(posedge CLK) disable iff (1'b0) out[1] == (in[2] | in[3])
    );

// out equals {in[2]|in[3], in[1]|in[3]}.
    check_out_vector_mapping: assert property (
        @(posedge CLK) disable iff (1'b0) out == { (in[2] | in[3]), (in[1] | in[3]) }
    );

// If in[3] is 1, out must be 2'b11.
    check_in3_forces_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) in[3] |-> (out == 2'b11)
    );

// If in[3] is 0, out passes through in[2:1] to {out[1],out[0]}.
    check_in3_zero_pass_through: assert property (
        @(posedge CLK) disable iff (1'b0) !in[3] |-> ((out[0] == in[1]) && (out[1] == in[2]))
    );

// If in[1]==0 and in[3]==0 then out[0]==0.
    check_out0_zero_conditions: assert property (
        @(posedge CLK) disable iff (1'b0) (!in[1] && !in[3]) |-> (out[0] == 1'b0)
    );

// If in[2]==0 and in[3]==0 then out[1]==0.
    check_out1_zero_conditions: assert property (
        @(posedge CLK) disable iff (1'b0) (!in[2] && !in[3]) |-> (out[1] == 1'b0)
    );

// All-zero input produces all-zero output.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) disable iff (1'b0) (in == 4'b0000) |-> (out == 2'b00)
    );

// With in[3]==0, in[1]==1 sets out[0].
    check_out0_set_by_in1_when_in3_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (in[1] && !in[3]) |-> (out[0] == 1'b1)
    );

// With in[3]==0, in[2]==1 sets out[1].
    check_out1_set_by_in2_when_in3_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (in[2] && !in[3]) |-> (out[1] == 1'b1)
    );

// Output equals B & C & ~A_N.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (B & C & ~A_N)
    );

// A_N high forces X low.
    check_A_N_high_forces_low: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

// B low forces X low.
    check_B_low_forces_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == 1'b0)
    );

// C low forces X low.
    check_C_low_forces_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == 1'b0)
    );

// When all enables are asserted (A_N=0,B=1,C=1) output is high.
    check_all_inputs_enable_high: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1)) |-> (X == 1'b1)
    );

// X high implies A_N=0, B=1, and C=1.
    check_X_high_implies_inputs: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1))
    );

// If B and C are high, X equals ~A_N.
    check_when_BC_high_X_eq_notA: assert property (
        @(posedge clk) ((B == 1'b1) && (C == 1'b1)) |-> (X == ~A_N)
    );

// If C and ~A_N are high, X equals B.
    check_when_C_and_notA_X_eq_B: assert property (
        @(posedge clk) ((C == 1'b1) && (A_N == 1'b0)) |-> (X == B)
    );

// If B and ~A_N are high, X equals C.
    check_when_B_and_notA_X_eq_C: assert property (
        @(posedge clk) ((B == 1'b1) && (A_N == 1'b0)) |-> (X == C)
    );

// X rising requires B=1, C=1, and A_N=0.
    check_rose_X_requires_enable: assert property (
        @(posedge clk) $rose(X) |-> ((B == 1'b1) && (C == 1'b1) && (A_N == 1'b0))
    );

// X falling requires !(B & C & ~A_N).
    check_fell_X_requires_not_condition: assert property (
        @(posedge clk) $fell(X) |-> !((B == 1'b1) && (C == 1'b1) && (A_N == 1'b0))
    );

// c[2] must mirror d[0].
    check_c2_equals_d0: assert property (
        @(posedge clk) disable iff (1'b0) c[2] == d[0]
    );

// c[4] must mirror d[1].
    check_c4_equals_d1: assert property (
        @(posedge clk) disable iff (1'b0) c[4] == d[1]
    );

// c[5] must mirror d[2].
    check_c5_equals_d2: assert property (
        @(posedge clk) disable iff (1'b0) c[5] == d[2]
    );

// c[6] must mirror d[3].
    check_c6_equals_d3: assert property (
        @(posedge clk) disable iff (1'b0) c[6] == d[3]
    );

// c[8] must mirror d[4].
    check_c8_equals_d4: assert property (
        @(posedge clk) disable iff (1'b0) c[8] == d[4]
    );

// c[9] must mirror d[5].
    check_c9_equals_d5: assert property (
        @(posedge clk) disable iff (1'b0) c[9] == d[5]
    );

// c[10] must mirror d[6].
    check_c10_equals_d6: assert property (
        @(posedge clk) disable iff (1'b0) c[10] == d[6]
    );

// c[11] must mirror d[7].
    check_c11_equals_d7: assert property (
        @(posedge clk) disable iff (1'b0) c[11] == d[7]
    );

// c[12] must mirror d[8].
    check_c12_equals_d8: assert property (
        @(posedge clk) disable iff (1'b0) c[12] == d[8]
    );

// c[13] must mirror d[9].
    check_c13_equals_d9: assert property (
        @(posedge clk) disable iff (1'b0) c[13] == d[9]
    );

// c[14] must mirror d[10].
    check_c14_equals_d10: assert property (
        @(posedge clk) disable iff (1'b0) c[14] == d[10]
    );

// c[0] parity equals d[0]^d[1]^d[3]^d[4]^d[6]^d[8]^d[10].
    check_c0_parity_p0: assert property (
        @(posedge clk) disable iff (1'b0) c[0] == (d[0] ^ d[1] ^ d[3] ^ d[4] ^ d[6] ^ d[8] ^ d[10])
    );

// c[1] parity equals d[0]^d[2]^d[3]^d[5]^d[6]^d[9]^d[10].
    check_c1_parity_p1: assert property (
        @(posedge clk) disable iff (1'b0) c[1] == (d[0] ^ d[2] ^ d[3] ^ d[5] ^ d[6] ^ d[9] ^ d[10])
    );

// c[3] parity equals d[1]^d[2]^d[3]^d[7]^d[8]^d[9]^d[10].
    check_c3_parity_p2: assert property (
        @(posedge clk) disable iff (1'b0) c[3] == (d[1] ^ d[2] ^ d[3] ^ d[7] ^ d[8] ^ d[9] ^ d[10])
    );

// c[7] parity equals d[4]^d[5]^d[6]^d[7]^d[8]^d[9]^d[10].
    check_c7_parity_p3: assert property (
        @(posedge clk) disable iff (1'b0) c[7] == (d[4] ^ d[5] ^ d[6] ^ d[7] ^ d[8] ^ d[9] ^ d[10])
    );

///// Functional mapping checks /////
    // Upper 8 bits of out pass through input byte.
    check_data_passthrough: assert property (
        @(posedge CLK) disable iff (!RESETn) out[8:1] == in
    );

// Parity bit equals XOR reduction of input bits.
    check_parity_from_in: assert property (
        @(posedge CLK) disable iff (!RESETn) out[0] == ^in
    );

// Parity bit equals XOR reduction of out's data field.
    check_parity_matches_data: assert property (
        @(posedge CLK) disable iff (!RESETn) out[0] == ^out[8:1]
    );

// Overall out has even parity (XOR of all 9 bits is 0).
    check_out_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (^out) == 1'b0
    );

///// Corner cases /////
    // All-zero input yields zero data and zero parity.
    check_zero_input_output: assert property (
        @(posedge CLK) disable iff (!RESETn) (in == 8'h00) |-> ((out[8:1] == 8'h00) && (out[0] == 1'b0))
    );

// All-ones input passes through with zero parity.
    check_all_ones_input_output: assert property (
        @(posedge CLK) disable iff (!RESETn) (in == 8'hFF) |-> ((out[8:1] == 8'hFF) && (out[0] == 1'b0))
    );

// Clocks: none in RTL; Resets: none; Logic: pure combinational X = A | B | ~C_N | ~D_N.

    // X equals the defined OR function of inputs.
    check_or_function: assert property (
        @(posedge CLK) disable iff (1'b0) X == (A | B | ~C_N | ~D_N)
    );

// Rising A drives X HIGH in the same cycle.
    check_rose_A_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(A) |-> X
    );

// Rising B drives X HIGH in the same cycle.
    check_rose_B_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $rose(B) |-> X
    );

// Falling C_N (active-low) drives X HIGH in the same cycle.
    check_fell_C_N_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(C_N) |-> X
    );

// Falling D_N (active-low) drives X HIGH in the same cycle.
    check_fell_D_N_sets_X_high: assert property (
        @(posedge CLK) disable iff (1'b0) $fell(D_N) |-> X
    );

// When all inputs are inactive (A=0,B=0,C_N=1,D_N=1), X must be LOW.
    check_all_inactive_makes_X_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B && C_N && D_N) |-> !X
    );

// If X is LOW, then all inputs must be inactive (A=0,B=0,C_N=1,D_N=1).
    check_X_low_means_all_inactive: assert property (
        @(posedge CLK) disable iff (1'b0) (!X) |-> (!A && !B && C_N && D_N)
    );

// If X is HIGH, at least one driving condition must be true.
    check_X_high_has_some_cause: assert property (
        @(posedge CLK) disable iff (1'b0) X |-> (A || B || !C_N || !D_N)
    );

// If A and B are 0, X equals (~C_N | ~D_N).
    check_AB_zero_refines_X: assert property (
        @(posedge CLK) disable iff (1'b0) (!A && !B) |-> (X == (~C_N | ~D_N))
    );

///// Reset behavior /////
    // When reset is asserted LOW, count is forced to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'b0000)
    );

///// Enable-controlled counting /////
    // When enable is LOW, hold the previous count (outside reset).
    check_hold_when_en_low: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b0) |-> (count == $past(count))
    );

// When enable is HIGH and previous count != 15, increment by 1.
    check_increment_when_en_high_no_wrap: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) && ($past(count) != 4'hF) |-> (count == ($past(count) + 4'd1))
    );

// When enable is HIGH and previous count == 15, wrap to 0.
    check_increment_when_en_high_wrap: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) && ($past(count) == 4'hF) |-> (count == 4'h0)
    );

// Any change in count (outside reset) implies enable is HIGH that cycle.
    check_change_implies_en_high: assert property (
        @(posedge clk) disable iff (!rst) (count != $past(count)) |-> (en == 1'b1)
    );

// When enable is HIGH (outside reset), count must change every cycle.
    check_must_change_when_en_high: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) |-> (count != $past(count))
    );

// If enable is HIGH and count is 0 (outside reset), previous count was 15 (wrap origin).
    check_wrap_only_from_max: assert property (
        @(posedge clk) disable iff (!rst) (en == 1'b1) && (count == 4'h0) |-> ($past(count) == 4'hF)
    );

// For sel==00, out is {in[3:2], 2'b00}.
    check_sel00_transform: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == {in[3:2], 2'b00})
    );

// For sel==01, out is in & 4'b1100.
    check_sel01_transform: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == (in & 4'b1100))
    );

// For sel==10, out is in | 4'b0011.
    check_sel10_transform: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == (in | 4'b0011))
    );

// For sel==11, out is in ^ 4'b1010.
    check_sel11_transform: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == (in ^ 4'b1010))
    );

// Bit 2 of out always passes through in[2] for all sel values.
    check_out2_passthrough: assert property (
        @(posedge clk) (out[2] == in[2])
    );

// For sel==00, lower two bits are zero.
    check_sel00_lsb_zero: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out[1:0] == 2'b00)
    );

// For sel==01, lower two bits are zero.
    check_sel01_lsb_zero: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out[1:0] == 2'b00)
    );

// For sel==10, lower two bits are ones.
    check_sel10_lsb_one: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out[1:0] == 2'b11)
    );

// MSB passes through when sel is not 2'b11.
    check_msb_passthrough_unless_xor: assert property (
        @(posedge clk) (sel != 2'b11) |-> (out[3] == in[3])
    );

// For sel==11, bitwise behavior: invert bits 3 and 1, pass bits 2 and 0.
    check_sel11_bitwise_detail: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out[3] == ~in[3] && out[2] == in[2] && out[1] == ~in[1] && out[0] == in[0])
    );

// On A rising edge, Y equals bitwise NOT of A.
    check_y_eq_not_a_on_a_rise: assert property (
        @(posedge A) (Y == ~A)
    );

// On A falling edge, Y equals bitwise NOT of A.
    check_y_eq_not_a_on_a_fall: assert property (
        @(negedge A) (Y == ~A)
    );

// Output equals selected input every cycle.
    check_mux_function: assert property (
        @(posedge clk) disable iff (1'b0) out == (sel ? in2 : in1)
    );

// When sel is 0, out equals in1.
    check_sel0_path: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b0) |-> (out == in1)
    );

// When sel is 1, out equals in2.
    check_sel1_path: assert property (
        @(posedge clk) disable iff (1'b0) (sel == 1'b1) |-> (out == in2)
    );

// Out is always equal to one of the inputs.
    check_out_is_one_of_inputs: assert property (
        @(posedge clk) disable iff (1'b0) ((out == in1) || (out == in2))
    );

// If out differs from in1, sel must be 1.
    check_out_ne_in1_implies_sel1: assert property (
        @(posedge clk) disable iff (1'b0) (out != in1) |-> (sel == 1'b1)
    );

// If out differs from in2, sel must be 0.
    check_out_ne_in2_implies_sel0: assert property (
        @(posedge clk) disable iff (1'b0) (out != in2) |-> (sel == 1'b0)
    );

// After a cycle with reset asserted, dataout must be 0.
    after_reset_dataout_low: assert property (
        @(posedge clock) disable iff (reset) $past(reset) |-> (dataout == 1'b0)
    );

// op=0000: Y equals A + B
    check_add: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0000) |-> (Y == A + B)
    );

// op=0001: Y equals A - B
    check_sub: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0001) |-> (Y == A - B)
    );

// op=0010: Y equals A & B
    check_and: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0010) |-> (Y == (A & B))
    );

// op=0011: Y equals A | B
    check_or: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0011) |-> (Y == (A | B))
    );

// op=0100: Y equals A ^ B
    check_xor: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0100) |-> (Y == (A ^ B))
    );

// op=0101: Y equals bitwise NOT of A
    check_notA: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0101) |-> (Y == ~A)
    );

// op=0110: Y equals A shifted left by 1 with LSB=0
    check_shift_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0110) |-> (Y == {A[14:0], 1'b0})
    );

// op=0111: Y equals A shifted right by 1 with MSB=0
    check_shift_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0111) |-> (Y == {1'b0, A[15:1]})
    );

// op=1000: Y equals A rotated left by 1
    check_rotate_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1000) |-> (Y == {A[14:0], A[15]})
    );

// op=1001: Y equals A rotated right by 1
    check_rotate_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1001) |-> (Y == {A[0], A[15:1]})
    );

// Default case: Y is zero for unimplemented opcodes (1010..1111)
    check_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) (op inside {[4'hA:4'hF]}) |-> (Y == 16'b0)
    );

// Combinational gate: ENCLK = EN && TE && CLK; clock for assertions is CLK; no reset present.

    // ENCLK can only be HIGH when EN and TE are HIGH at the CLK posedge.
    check_enclk_only_when_en_te_high: assert property (
        @(posedge CLK) ENCLK |-> (EN && TE)
    );

// EN LOW forces ENCLK LOW at the CLK posedge.
    check_en_low_forces_enclk_low: assert property (
        @(posedge CLK) (!EN) |-> (!ENCLK)
    );

// TE LOW forces ENCLK LOW at the CLK posedge.
    check_te_low_forces_enclk_low: assert property (
        @(posedge CLK) (!TE) |-> (!ENCLK)
    );

// A rising ENCLK between posedges implies EN or TE rose.
    check_enclk_rise_caused_by_input_rise: assert property (
        @(posedge CLK) $rose(ENCLK) |-> ($rose(EN) || $rose(TE))
    );

// When disabled, outputs and Number are zero.
    check_disabled_defaults: assert property (
        @(posedge clk) (Ein == 1'b0) |-> ((Eout == 1'b0) && (GS == 1'b0) && (Number == 3'b000))
    );

// When enabled, Eout and GS are complements.
    check_eout_gs_complement_when_enabled: assert property (
        @(posedge clk) Ein |-> (Eout == ~GS)
    );

// Eout and GS are never both HIGH.
    check_gs_eout_mutex: assert property (
        @(posedge clk) !(GS && Eout)
    );

// Y must be the bitwise complement of A when sampled on A rising edge.
    check_complement_on_A_posedge: assert property (
        @(posedge A) (Y == ~A)
    );

// Y must be the bitwise complement of A when sampled on Y rising edge.
    check_complement_on_Y_posedge: assert property (
        @(posedge Y) (Y == ~A)
    );

// A and Y are never equal when sampled on A rising edge.
    check_inequality_on_A_posedge: assert property (
        @(posedge A) (Y != A)
    );

// Exactly one of A or Y is 1 when sampled on A rising edge.
    check_one_hot_on_A_posedge: assert property (
        @(posedge A) (A ^ Y) == 1'b1
    );

// Complement relation holds regardless of VPWR events.
    check_complement_on_VPWR_posedge: assert property (
        @(posedge VPWR) (Y == ~A)
    );

// Complement relation holds regardless of VGND events.
    check_complement_on_VGND_posedge: assert property (
        @(posedge VGND) (Y == ~A)
    );

// Complement relation holds regardless of VPB events.
    check_complement_on_VPB_posedge: assert property (
        @(posedge VPB) (Y == ~A)
    );

// Complement relation holds regardless of VNB events.
    check_complement_on_VNB_posedge: assert property (
        @(posedge VNB) (Y == ~A)
    );

// S equals the selected data input (functional equivalence).
    check_mux_functional_equivalence: assert property (
        @(posedge CLK) S == (ctrl ? D1 : D0)
    );

// When ctrl is 0, S equals D0.
    check_select_D0_when_ctrl_0: assert property (
        @(posedge CLK) (ctrl == 1'b0) |-> (S == D0)
    );

// When ctrl is 1, S equals D1.
    check_select_D1_when_ctrl_1: assert property (
        @(posedge CLK) (ctrl == 1'b1) |-> (S == D1)
    );

// On ctrl rising edge, S reflects D1.
    check_output_on_ctrl_rise_selects_D1: assert property (
        @(posedge CLK) $rose(ctrl) |-> (S == D1)
    );

// On ctrl falling edge, S reflects D0.
    check_output_on_ctrl_fall_selects_D0: assert property (
        @(posedge CLK) $fell(ctrl) |-> (S == D0)
    );

// If D0 equals D1, S equals that value regardless of ctrl.
    check_equal_inputs_force_S_equal: assert property (
        @(posedge CLK) (D0 == D1) |-> (S == D0)
    );

///// Functional equivalence /////
    // 5-bit result equals A + B + CIN.
    check_full_sum_equivalence: assert property (
        @(posedge clk) disable iff (!reset_n) {COUT, S} == sum5
    );

///// Bit-level ripple-carry equations /////
    // Bit 0 sum is XOR of A[0], B[0], CIN.
    check_bit0_sum_xor: assert property (
        @(posedge clk) disable iff (!reset_n) S[0] == (A[0] ^ B[0] ^ CIN)
    );

// Bit 1 sum uses carry from bit 0.
    check_bit1_sum_xor_with_c0: assert property (
        @(posedge clk) disable iff (!reset_n) S[1] == (A[1] ^ B[1] ^ c0)
    );

// Bit 2 sum uses carry from bit 1.
    check_bit2_sum_xor_with_c1: assert property (
        @(posedge clk) disable iff (!reset_n) S[2] == (A[2] ^ B[2] ^ c1)
    );

// Bit 3 sum uses carry from bit 2.
    check_bit3_sum_xor_with_c2: assert property (
        @(posedge clk) disable iff (!reset_n) S[3] == (A[3] ^ B[3] ^ c2)
    );

// Final carry-out from bit 3 matches generate/propagate logic.
    check_cout_from_c2: assert property (
        @(posedge clk) disable iff (!reset_n) COUT == ((A[3] & B[3]) | (A[3] & c2) | (B[3] & c2))
    );

///// Sanity behaviors (direct consequences of the adder logic) /////
    // When B==0 and CIN==0, output equals A with no carry.
    check_transparent_when_B_zero_no_cin: assert property (
        @(posedge clk) disable iff (!reset_n) ((B == 4'b0) && (CIN == 1'b0)) |-> (S == A && COUT == 1'b0)
    );

// When A==0 and CIN==0, output equals B with no carry.
    check_transparent_when_A_zero_no_cin: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == 4'b0) && (CIN == 1'b0)) |-> (S == B && COUT == 1'b0)
    );

// All zeros in yields all zeros out.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == 4'b0) && (B == 4'b0) && (CIN == 1'b0)) |-> ((S == 4'b0) && (COUT == 1'b0))
    );

// Only CIN asserted increments by 1 with no carry-out.
    check_only_cin_increments_by_one: assert property (
        @(posedge clk) disable iff (!reset_n) ((A == 4'b0) && (B == 4'b0) && (CIN == 1'b1)) |-> ((S == 4'b0001) && (COUT == 1'b0))
    );

///// Combinational mapping checks /////
    // When in1 equals in2, out must be 2'b00.
    map_eq: assert property (
        @(posedge clk) (in1 == in2) |-> (out == 2'b00)
    );

// When in1 is greater than in2, out must be 2'b01.
    map_gt: assert property (
        @(posedge clk) (in1 > in2) |-> (out == 2'b01)
    );

// When in1 is less than in2, out must be 2'b10.
    map_lt: assert property (
        @(posedge clk) (in1 < in2) |-> (out == 2'b10)
    );

///// Reverse mapping (code implies relation) /////
    // If out is 2'b00, inputs must be equal.
    rev_map_eq: assert property (
        @(posedge clk) (out == 2'b00) |-> (in1 == in2)
    );

// If out is 2'b01, in1 must be greater than in2.
    rev_map_gt: assert property (
        @(posedge clk) (out == 2'b01) |-> (in1 > in2)
    );

// If out is 2'b10, in1 must be less than in2.
    rev_map_lt: assert property (
        @(posedge clk) (out == 2'b10) |-> (in1 < in2)
    );

///// Encoding sanity /////
    // out must never be 2'b11.
    out_never_illegal_11: assert property (
        @(posedge clk) out != 2'b11
    );

// On reset, all outputs clear to zero on the next cycle.
    reset_clears_outputs: assert property (
        @(posedge clock) reset |=> (vote_ID_Instruction == 32'b0)
                            && (vote_ID_PCAdd4 == 32'b0)
                            && (vote_ID_RestartPC == 32'b0)
                            && (vote_ID_IsBDS == 1'b0)
                            && (vote_ID_IsFlushed == 1'b0)
    );

// When ID_Stall is asserted, data fields capture from ID_* on the next cycle.
    id_stall_captures_id_data: assert property (
        @(posedge clock) disable iff (reset)
            ID_Stall |=> (vote_ID_Instruction == $past(ID_Instruction))
                      && (vote_ID_PCAdd4    == $past(ID_PCAdd4))
                      && (vote_ID_RestartPC == $past(ID_RestartPC))
    );

// When !ID_Stall and IF_Stall or IF_Flush, instruction and PCAdd4 zero on next cycle.
    zero_if_fields_on_if_stall_or_flush: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == 32'b0)
                                                  && (vote_ID_PCAdd4 == 32'b0)
    );

// When !ID_Stall and no IF_Stall/Flush, instruction and PCAdd4 pass through from IF_*.
    pass_if_fields_when_no_if_controls: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(IF_Stall || IF_Flush)) |=> (vote_ID_Instruction == $past(IF_Instruction))
                                                   && (vote_ID_PCAdd4    == $past(IF_PCAdd4))
    );

// When !ID_Stall and (ID_IsFlushed or IF_IsBDS), RestartPC comes from ID_RestartPC.
    restartpc_selects_id_on_flush_or_bds: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && (ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(ID_RestartPC))
    );

// When !ID_Stall and not (ID_IsFlushed or IF_IsBDS), RestartPC comes from IF_PC.
    restartpc_selects_if_on_normal_flow: assert property (
        @(posedge clock) disable iff (reset)
            (!ID_Stall && !(ID_IsFlushed || IF_IsBDS)) |=> (vote_ID_RestartPC == $past(IF_PC))
    );

// vote_ID_IsBDS always reflects prior-cycle ID_IsBDS (outside reset).
    flags_follow_id_isbds: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsBDS == $past(ID_IsBDS))
    );

// vote_ID_IsFlushed always reflects prior-cycle ID_IsFlushed (outside reset).
    flags_follow_id_isflushed: assert property (
        @(posedge clock) disable iff (reset)
            1'b1 |=> (vote_ID_IsFlushed == $past(ID_IsFlushed))
    );

///// Reset behavior /////
    // When RESET is asserted low, COUNT must be 0.
    check_reset_drives_zero: assert property (
        @(posedge CLK) (!RESET) |-> (COUNT == 4'd0)
    );

///// Next-state behavior /////
    // General next-state: after a non-reset cycle, COUNT matches LOAD/Data/Inc from previous cycle.
    check_next_state_function: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) |-> COUNT == ($past(LOAD) ? $past(DATA_IN) : (($past(COUNT) + 4'd1) & 4'hF))
    );

// LOAD=1 loads DATA_IN on the next cycle.
    check_load_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) |-> (COUNT == $past(DATA_IN))
    );

// LOAD=0 increments COUNT by 1 modulo 16 on the next cycle.
    check_increment_updates_next: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT == (($past(COUNT) + 4'd1) & 4'hF))
    );

// LOAD=0 causes COUNT to change (it cannot hold its value).
    check_increment_changes_value: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) |-> (COUNT != $past(COUNT))
    );

// With LOAD=0 and COUNT at 15, next COUNT wraps to 0.
    check_wrap_on_max_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && !$past(LOAD) && ($past(COUNT) == 4'hF) |-> (COUNT == 4'h0)
    );

// If LOAD=1, the load path has priority over increment (distinct from +1 result).
    check_load_priority_over_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET) && $past(LOAD) &&
            ($past(DATA_IN) != (($past(COUNT) + 4'd1) & 4'hF)) |-> (COUNT != (($past(COUNT) + 4'd1) & 4'hF))
    );

// Two consecutive cycles with LOAD=0 increment COUNT by 2 modulo 16.
    check_two_cycle_increment_no_load: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && !$past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(COUNT,2) + 4'd2) & 4'hF)
    );

// LOAD followed by no LOAD results in DATA_IN+1 on the second cycle (modulo 16).
    check_load_then_increment: assert property (
        @(posedge CLK) disable iff (!RESET)
            $past(RESET,2) && $past(RESET) && $past(LOAD,2) && !$past(LOAD)
            |-> COUNT == (($past(DATA_IN,2) + 4'd1) & 4'hF)
    );

// out_xor equals (sel_b2 ? b : (sel_b1 ? b : a)) XOR a.
    check_out_xor_from_mux: assert property (
        @(posedge clk) out_xor == ((sel_b2 ? b : (sel_b1 ? b : a)) ^ a)
    );

// out_xor_inv is bitwise inverse of out_xor.
    check_out_xor_inv_is_not: assert property (
        @(posedge clk) out_xor_inv == ~out_xor
    );

// out_logical_inv is logical NOT of out_xor (NOR-reduction).
    check_out_logical_inv_is_nor: assert property (
        @(posedge clk) out_logical_inv == ~(|out_xor)
    );

// When sel_b2 is 1, b is selected and out_xor equals b ^ a.
    check_sel_b2_drives_b_xor_a: assert property (
        @(posedge clk) sel_b2 |-> (out_xor == (b ^ a))
    );

// When sel_b2 is 0 and sel_b1 is 1, b is selected and out_xor equals b ^ a.
    check_sel_b1_drives_when_b2_low: assert property (
        @(posedge clk) (!sel_b2 && sel_b1) |-> (out_xor == (b ^ a))
    );

// When both sel_b2 and sel_b1 are 0, a is selected and out_xor is zero (a ^ a).
    check_both_selects_zero_xor_zero: assert property (
        @(posedge clk) (!sel_b2 && !sel_b1) |-> (out_xor == 4'b0000)
    );

// When both selects are 0, out_xor_inv is all ones (~0).
    check_both_selects_zero_inv_ones: assert property (
        @(posedge clk) (!sel_b2 && !sel_b1) |-> (out_xor_inv == 4'b1111)
    );

// When out_xor is zero, out_logical_inv must be 1.
    check_xor_zero_implies_logical_inv_one: assert property (
        @(posedge clk) (out_xor == 4'b0000) |-> (out_logical_inv == 1'b1)
    );

// Out matches the mux+enable function exactly.
    check_mux_function: assert property (
        @(posedge clk)
        out === (enable ? (sel == 2'b00 ? in0 :
                           sel == 2'b01 ? in1 :
                           sel == 2'b10 ? in2 : in3)
                       : 4'b0)
    );

// When disabled, out must be zero.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) (!enable) |-> (out === 4'b0)
    );

// When enabled and sel==00, out equals in0.
    check_sel00_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b00)) |-> (out === in0)
    );

// When enabled and sel==01, out equals in1.
    check_sel01_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b01)) |-> (out === in1)
    );

// When enabled and sel==10, out equals in2.
    check_sel10_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b10)) |-> (out === in2)
    );

// When enabled and sel==11, out equals in3.
    check_sel11_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b11)) |-> (out === in3)
    );

// If all inputs are equal and enabled, out equals that common value.
    check_equal_inputs_collapse: assert property (
        @(posedge clk) (enable && (in0 === in1) && (in1 === in2) && (in2 === in3)) |-> (out === in0)
    );

// If enabled and out is zero, the selected input must be zero.
    check_zero_out_implies_zero_selected_input: assert property (
        @(posedge clk)
        (enable && (out === 4'b0)) |-> (
            (sel == 2'b00) ? (in0 === 4'b0) :
            (sel == 2'b01) ? (in1 === 4'b0) :
            (sel == 2'b10) ? (in2 === 4'b0) :
                             (in3 === 4'b0)
        )
    );

///// Mapping from ctrl[7:5] to td_mode /////
    // When ctrl[7:5]==3'b000, td_mode must be 4'b0000.
    check_map_000: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b000) |-> (td_mode == 4'b0000)
    );

// When ctrl[7:5]==3'b001, td_mode must be 4'b1000.
    check_map_001: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b001) |-> (td_mode == 4'b1000)
    );

// When ctrl[7:5]==3'b010, td_mode must be 4'b0100.
    check_map_010: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b010) |-> (td_mode == 4'b0100)
    );

// When ctrl[7:5]==3'b011, td_mode must be 4'b1100.
    check_map_011: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b011) |-> (td_mode == 4'b1100)
    );

// When ctrl[7:5]==3'b100, td_mode must be 4'b0010.
    check_map_100: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b100) |-> (td_mode == 4'b0010)
    );

// When ctrl[7:5]==3'b101, td_mode must be 4'b1010.
    check_map_101: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b101) |-> (td_mode == 4'b1010)
    );

// When ctrl[7:5]==3'b110, td_mode must be 4'b0101.
    check_map_110: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b110) |-> (td_mode == 4'b0101)
    );

// When ctrl[7:5]==3'b111, td_mode must be 4'b1111.
    check_map_111: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b111) |-> (td_mode == 4'b1111)
    );

///// General invariants derived from the mapping /////
    // td_mode must always be one of the defined codewords.
    check_td_mode_code_set: assert property (
        @(posedge clk) td_mode inside {4'b0000,4'b1000,4'b0100,4'b1100,4'b0010,4'b1010,4'b0101,4'b1111}
    );

///// Functional correctness /////
    // X equals bitwise OR of all inputs.
    check_or_equivalence: assert property (
        @(posedge CLK) X === (A | B | C | D)
    );

// When all inputs are 0, X must be 0.
    check_all_zero_implies_x_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (X == 1'b0)
    );

// If any input is 1, X must be 1.
    check_any_one_implies_x_one: assert property (
        @(posedge CLK) (A || B || C || D) |-> (X == 1'b1)
    );

// If X is 0, all inputs must be 0.
    check_x_zero_implies_all_zero: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0))
    );

// If X is 1, at least one input must be 1.
    check_x_one_implies_any_one: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A || B || C || D)
    );

///// Individual input dominance when others are 0 /////
    // With B,C,D=0, X must equal A.
    check_dom_a_when_others_zero: assert property (
        @(posedge CLK) ((B == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (X === A)
    );

// With A,C,D=0, X must equal B.
    check_dom_b_when_others_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (X === B)
    );

// With A,B,D=0, X must equal C.
    check_dom_c_when_others_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (D == 1'b0)) |-> (X === C)
    );

// With A,B,C=0, X must equal D.
    check_dom_d_when_others_zero: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X === D)
    );

// Reset sets output_reg to 1 on the next cycle.
    reset_sets_output_reg: assert property (
        @(posedge clk) reset |=> (output_reg == 32'd1)
    );

// Reset has priority over falling-edge detection.
    reset_overrides_fall: assert property (
        @(posedge clk) (reset && $fell(signal)) |=> (output_reg == 32'd1)
    );

// A rising edge of signal does not change output_reg.
    rise_no_update: assert property (
        @(posedge clk) disable iff (reset) $rose(signal) |=> (output_reg == $past(output_reg))
    );

///// Functional mapping for each shift combination (shift_amount[3:1]) /////
    // No shift when [3:1]==000.
    check_shift_0: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b000) |-> (out == data)
    );

// Shift by 2 when [3:1]==001.
    check_shift_2: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b001) |-> (out == (data << 2))
    );

// Shift by 4 when [3:1]==010.
    check_shift_4: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b010) |-> (out == (data << 4))
    );

// Shift by 6 when [3:1]==011.
    check_shift_6: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b011) |-> (out == (data << 6))
    );

// Shift by 8 when [3:1]==100.
    check_shift_8: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b100) |-> (out == (data << 8))
    );

// Shift by 10 when [3:1]==101.
    check_shift_10: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b101) |-> (out == (data << 10))
    );

// Shift by 12 when [3:1]==110.
    check_shift_12: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b110) |-> (out == (data << 12))
    );

// Shift by 14 when [3:1]==111.
    check_shift_14: assert property (
        @(posedge clk) (shift_amount[3:1] == 3'b111) |-> (out == (data << 14))
    );

///// Bit-level structural consequences of left shifts /////
    // LSBs [1:0] are zeroed whenever shift by 2 is selected.
    check_lsb_zero_when_b1: assert property (
        @(posedge clk) shift_amount[1] |-> (out[1:0] == 2'b00)
    );

// LSBs [3:0] are zeroed whenever shift by 4 is selected.
    check_lsb_zero_when_b2: assert property (
        @(posedge clk) shift_amount[2] |-> (out[3:0] == 4'b0000)
    );

// LSBs [7:0] are zeroed whenever shift by 8 is selected.
    check_lsb_zero_when_b3: assert property (
        @(posedge clk) shift_amount[3] |-> (out[7:0] == 8'b0000_0000)
    );

///// Decoder correctness /////
    // Out equals 1 shifted by 'in' (core 4->16 one-hot decode).
    check_decode_function: assert property (
        @(posedge clk) out == (16'h0001 << in)
    );

// Out is exactly one-hot (exactly one bit set).
    check_out_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

///// Specific mappings (spot-checks) /////
    // in == 0 maps to out == 16'h0001.
    check_map_in0: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 16'h0001)
    );

// in == 1 maps to out == 16'h0002.
    check_map_in1: assert property (
        @(posedge clk) (in == 4'd1) |-> (out == 16'h0002)
    );

// in == 14 maps to out == 16'h4000.
    check_map_in14: assert property (
        @(posedge clk) (in == 4'd14) |-> (out == 16'h4000)
    );

// in == 15 maps to out == 16'h8000.
    check_map_in15: assert property (
        @(posedge clk) (in == 4'd15) |-> (out == 16'h8000)
    );

///// Functional behavior /////
    // On match (counter == divisor), next cycle clk_out toggles and counter clears to 0.
    toggle_and_clear_on_match: assert property (
        @(posedge clk_in) disable iff (!rst) (counter == divisor) |=> (clk_out == ~$past(clk_out)) && (counter == 8'h00)
    );

// On no match, next cycle counter increments by 1 (mod 256).
    inc_on_no_match: assert property (
        @(posedge clk_in) disable iff (!rst) (counter != divisor) |=> (counter == (($past(counter) + 8'd1) & 8'hFF))
    );

// On no match, next cycle clk_out holds its value.
    hold_clk_out_on_no_match: assert property (
        @(posedge clk_in) disable iff (!rst) (counter != divisor) |=> (clk_out == $past(clk_out))
    );

// Any change on clk_out implies the previous cycle had a match (counter == divisor).
    clk_out_change_implies_prev_match: assert property (
        @(posedge clk_in) disable iff (!rst) $changed(clk_out) |-> ($past(counter) == $past(divisor))
    );

// Any change on clk_out is a true toggle (new value is inverse of old).
    clk_out_change_is_toggle: assert property (
        @(posedge clk_in) disable iff (!rst) $changed(clk_out) |-> (clk_out == ~$past(clk_out))
    );

// Next counter value is either incremented by 1 (mod 256) or cleared to 0.
    counter_next_is_inc_or_zero: assert property (
        @(posedge clk_in) disable iff (!rst) 1'b1 |=> (counter == (($past(counter) + 8'd1) & 8'hFF)) || (counter == 8'h00)
    );

// No clock/reset in DUT; pure combinational; function: Y = A_N | ~B.

    // Y equals A_N | ~B on A_N rising edge.
    check_function_equiv_posA: assert property (
        @(posedge A_N) (Y === (A_N | ~B))
    );

// Y equals A_N | ~B on A_N falling edge.
    check_function_equiv_negA: assert property (
        @(negedge A_N) (Y === (A_N | ~B))
    );

// Y equals A_N | ~B on B rising edge.
    check_function_equiv_posB: assert property (
        @(posedge B) (Y === (A_N | ~B))
    );

// Y equals A_N | ~B on B falling edge.
    check_function_equiv_negB: assert property (
        @(negedge B) (Y === (A_N | ~B))
    );

// A_N=1 forces Y=1 on A_N rising edge.
    check_A_N_one_forces_Y_one_posA: assert property (
        @(posedge A_N) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// A_N=1 forces Y=1 on A_N falling edge.
    check_A_N_one_forces_Y_one_negA: assert property (
        @(negedge A_N) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// B=0 forces Y=1 on B rising edge.
    check_B_zero_forces_Y_one_posB: assert property (
        @(posedge B) (B == 1'b0) |-> (Y == 1'b1)
    );

// B=0 forces Y=1 on B falling edge.
    check_B_zero_forces_Y_one_negB: assert property (
        @(negedge B) (B == 1'b0) |-> (Y == 1'b1)
    );

// Y==0 iff (A_N==0 && B==1) on A_N rising edge.
    check_only_zero_case_posA: assert property (
        @(posedge A_N) ((Y === 1'b0) == ((A_N === 1'b0) && (B === 1'b1)))
    );

// Y==0 iff (A_N==0 && B==1) on B rising edge.
    check_only_zero_case_posB: assert property (
        @(posedge B) ((Y === 1'b0) == ((A_N === 1'b0) && (B === 1'b1)))
    );

///// Reset behavior /////
    // While reset_n is LOW, data_stand must be 0.
    reset_forces_zero: assert property (
        @(posedge clock_50) !reset_n |-> (data_stand == 9'd0)
    );

///// Functional checks /////
    // When sub==0, sum equals a + b (mod 16).
    check_add_when_sub0: assert property (
        @(posedge CLK) (!sub) |-> (sum == (a + b))
    );

// When sub==1, sum equals a - b (mod 16).
    check_sub_when_sub1: assert property (
        @(posedge CLK) (sub) |-> (sum == (a - b))
    );

// Switching from add to sub with same inputs yields a - b.
    check_toggle_to_sub: assert property (
        @(posedge CLK) ($past(sub)==1'b0 && sub==1'b1 && $stable(a) && $stable(b)) |-> (sum == (a - b))
    );

// Switching from sub to add with same inputs yields a + b.
    check_toggle_to_add: assert property (
        @(posedge CLK) ($past(sub)==1'b1 && sub==1'b0 && $stable(a) && $stable(b)) |-> (sum == (a + b))
    );

// Addition identity: adding zero on b returns a.
    check_add_zero_b: assert property (
        @(posedge CLK) (!sub && (b == 4'd0)) |-> (sum == a)
    );

// Subtraction identity: subtracting zero returns a.
    check_sub_zero_b: assert property (
        @(posedge CLK) (sub && (b == 4'd0)) |-> (sum == a)
    );

// Subtraction of equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge CLK) (sub && (a == b)) |-> (sum == 4'd0)
    );

// No X/Z on output when all inputs are known 0/1.
    check_no_x_on_known_inputs: assert property (
        @(posedge CLK) !$isunknown({a,b,sub}) |-> !$isunknown(sum)
    );

///// Reset behavior /////
    // During reset, reg_out is 0x34.
    check_reg_out_reset_value: assert property (
        @(posedge clk) reset |-> (reg_out == 8'h34)
    );

// During reset, counter_out is 0.
    check_counter_reset_value: assert property (
        @(posedge clk) reset |-> (counter_out == 4'h0)
    );

// Y equals the bitwise AND of A and B.
    check_y_equals_and: assert property (
        @(posedge clk) (Y == (A & B))
    );

// If A is 0, Y must be 0.
    check_zero_when_a_zero: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b0)
    );

// If B is 0, Y must be 0.
    check_zero_when_b_zero: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b0)
    );

// If both A and B are 1, Y must be 1.
    check_one_when_both_one: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1) |-> (Y == 1'b1)
    );

// If Y is 1, then both A and B must be 1.
    check_y_one_implies_inputs_one: assert property (
        @(posedge clk) (Y == 1'b1) |-> (A == 1'b1 && B == 1'b1)
    );

// MSB of binary equals MSB of Gray.
    check_msb_mapping: assert property (
        @(posedge clk) bin_out[7] == gray_input[7]
    );

// bin_out[6] equals bin_out[7] XOR gray_input[6].
    check_chain_b6: assert property (
        @(posedge clk) bin_out[6] == (bin_out[7] ^ gray_input[6])
    );

// bin_out[5] equals bin_out[6] XOR gray_input[5].
    check_chain_b5: assert property (
        @(posedge clk) bin_out[5] == (bin_out[6] ^ gray_input[5])
    );

// bin_out[4] equals bin_out[5] XOR gray_input[4].
    check_chain_b4: assert property (
        @(posedge clk) bin_out[4] == (bin_out[5] ^ gray_input[4])
    );

// bin_out[3] equals bin_out[4] XOR gray_input[3].
    check_chain_b3: assert property (
        @(posedge clk) bin_out[3] == (bin_out[4] ^ gray_input[3])
    );

// bin_out[2] equals bin_out[3] XOR gray_input[2].
    check_chain_b2: assert property (
        @(posedge clk) bin_out[2] == (bin_out[3] ^ gray_input[2])
    );

// bin_out[1] equals bin_out[2] XOR gray_input[1].
    check_chain_b1: assert property (
        @(posedge clk) bin_out[1] == (bin_out[2] ^ gray_input[1])
    );

// bin_out[0] equals bin_out[1] XOR gray_input[0].
    check_chain_b0: assert property (
        @(posedge clk) bin_out[0] == (bin_out[1] ^ gray_input[0])
    );

///// Functional correctness /////
    // Z must equal A XOR B every cycle.
    check_z_eq_a_xor_b: assert property (
        @(posedge clk) (Z === (A ^ B))
    );

// Re-applying XOR with B to Z must recover A.
    check_unxor_back_to_a: assert property (
        @(posedge clk) ((Z ^ B) === A)
    );

// The XOR difference between A and Z must equal B.
    check_a_xor_z_is_b: assert property (
        @(posedge clk) ((A ^ Z) === B)
    );

///// Bit-level mapping /////
    // LSB must be inverted due to B[0]==1.
    check_lsb_inverted: assert property (
        @(posedge clk) (Z[0] === ~A[0])
    );

// Upper bits must pass through due to B[3:1]==0.
    check_upper_pass_through: assert property (
        @(posedge clk) (Z[3:1] === A[3:1])
    );

///// Reset behavior /////
  // Reset high causes Q to be 0 on the following clock.
  check_reset_clears_next: assert property (
    @(posedge CLK) RST |=> (Q == 2'b00)
  );

// If reset was high on the previous clock, Q must be 0 now.
  check_prev_reset_forces_zero: assert property (
    @(posedge CLK) $past(RST) |-> (Q == 2'b00)
  );

// Immediately after reset deasserts, Q is still 0 before any enable update.
  check_deassert_reset_prestate_zero: assert property (
    @(posedge CLK) $past(RST) && !RST |-> (Q == 2'b00)
  );

// While reset stays asserted across consecutive clocks, Q is 0 now.
  check_hold_zero_during_continuous_reset_now: assert property (
    @(posedge CLK) ($past(RST) && RST) |-> (Q == 2'b00)
  );

// While reset stays asserted across consecutive clocks, Q is 0 on the next clock.
  check_hold_zero_during_continuous_reset_next: assert property (
    @(posedge CLK) ($past(RST) && RST) |=> (Q == 2'b00)
  );

///// Enable and wrap behavior (robust to async reset) /////
  // With EN high and Q at 3, the next value wraps to 0 (reset may also force 0).
  check_wrap_on_en_from_3: assert property (
    @(posedge CLK) disable iff (RST) (EN && (Q == 2'b11)) |=> (Q == 2'b00)
  );

// If Q was 0 and EN was low last cycle (not in reset), Q remains 0 now.
  check_zero_stays_zero_without_enable: assert property (
    @(posedge CLK) disable iff (RST) ($past(EN) == 1'b0 && $past(Q) == 2'b00) |-> (Q == 2'b00)
  );

// Combinational full_adder; sample properties on external CLK, gated by active-low RESETn.

    // Sum equals a ^ b ^ cin.
    check_sum_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) sum == ((a ^ b) ^ cin)
    );

// Carry equals (a & b) | ((a ^ b) & cin).
    check_carry_definition: assert property (
        @(posedge CLK) disable iff (!RESETn) carry == ((a & b) | ((a ^ b) & cin))
    );

// Carry equals majority form: (a&b) | (a&cin) | (b&cin).
    check_carry_majority_form: assert property (
        @(posedge CLK) disable iff (!RESETn) carry == ((a & b) | (a & cin) | (b & cin))
    );

// With cin=0, sum reduces to a ^ b.
    check_sum_when_cin0: assert property (
        @(posedge CLK) disable iff (!RESETn) (cin == 1'b0) |-> (sum == (a ^ b))
    );

// With cin=0, carry reduces to a & b.
    check_carry_when_cin0: assert property (
        @(posedge CLK) disable iff (!RESETn) (cin == 1'b0) |-> (carry == (a & b))
    );

// With cin=1, sum equals ~(a ^ b).
    check_sum_when_cin1: assert property (
        @(posedge CLK) disable iff (!RESETn) (cin == 1'b1) |-> (sum == ~(a ^ b))
    );

// With cin=1, carry equals a | b.
    check_carry_when_cin1: assert property (
        @(posedge CLK) disable iff (!RESETn) (cin == 1'b1) |-> (carry == (a | b))
    );

// When a and b differ, carry equals cin.
    check_carry_equals_cin_when_inputs_differ: assert property (
        @(posedge CLK) disable iff (!RESETn) ((a ^ b) == 1'b1) |-> (carry == cin)
    );

// When a and b are equal, sum equals cin.
    check_sum_equals_cin_when_inputs_equal: assert property (
        @(posedge CLK) disable iff (!RESETn) ((a ^ b) == 1'b0) |-> (sum == cin)
    );

// With all ones, sum=1 and carry=1.
    check_all_one_input_case: assert property (
        @(posedge CLK) disable iff (!RESETn) (a & b & cin) |-> ((sum == 1'b1) && (carry == 1'b1))
    );

// Output equals XOR of inputs each cycle.
    check_xor_function: assert property (
        @(posedge CLK) (out_comb_logic == (a ^ b))
    );

// When inputs are equal, output is 0.
    check_out_zero_when_inputs_equal: assert property (
        @(posedge CLK) (a == b) |-> (out_comb_logic == 1'b0)
    );

// When inputs differ, output is 1.
    check_out_one_when_inputs_unequal: assert property (
        @(posedge CLK) (a != b) |-> (out_comb_logic == 1'b1)
    );

// When a is 0, output equals b.
    check_out_eq_b_when_a_zero: assert property (
        @(posedge CLK) (a == 1'b0) |-> (out_comb_logic == b)
    );

// When a is 1, output equals ~b.
    check_out_eq_notb_when_a_one: assert property (
        @(posedge CLK) (a == 1'b1) |-> (out_comb_logic == ~b)
    );

// When b is 0, output equals a.
    check_out_eq_a_when_b_zero: assert property (
        @(posedge CLK) (b == 1'b0) |-> (out_comb_logic == a)
    );

// When b is 1, output equals ~a.
    check_out_eq_nota_when_b_one: assert property (
        @(posedge CLK) (b == 1'b1) |-> (out_comb_logic == ~a)
    );

// Result must be one of the three valid encodings.
    check_allowed_result_encoding: assert property (
        @(posedge clk) (result inside {2'b00, 2'b01, 2'b10})
    );

// If in0 > in1 then result encodes greater-than (01).
    check_gt_implies_code: assert property (
        @(posedge clk) (in0 > in1) |-> (result == 2'b01)
    );

// If in0 < in1 then result encodes less-than (10).
    check_lt_implies_code: assert property (
        @(posedge clk) (in0 < in1) |-> (result == 2'b10)
    );

// If in0 == in1 then result encodes equal (00).
    check_eq_implies_code: assert property (
        @(posedge clk) (in0 == in1) |-> (result == 2'b00)
    );

// If result encodes greater-than (01) then in0 > in1.
    check_code_implies_gt: assert property (
        @(posedge clk) (result == 2'b01) |-> (in0 > in1)
    );

// If result encodes less-than (10) then in0 < in1.
    check_code_implies_lt: assert property (
        @(posedge clk) (result == 2'b10) |-> (in0 < in1)
    );

// If result encodes equal (00) then in0 == in1.
    check_code_implies_eq: assert property (
        @(posedge clk) (result == 2'b00) |-> (in0 == in1)
    );

// If inputs are unequal then result is not equal-code (00).
    check_inequality_implies_nonzero: assert property (
        @(posedge clk) (in0 != in1) |-> (result != 2'b00)
    );

// If result is not equal-code (00) then inputs are unequal.
    check_nonzero_implies_inequality: assert property (
        @(posedge clk) (result != 2'b00) |-> (in0 != in1)
    );

// Clock: clk (posedge). Reset: reset (active-high, async). Sequential: LED <= prev(SW)+1 with 1-cycle latency.

    // While reset is asserted, LED is held at zero.
    check_reset_drives_led_zero: assert property (
        @(posedge clk) reset |-> (LED == 4'b0000)
    );

///// Functional relationship between outputs /////
    // CountFinished is high iff CountValue equals CountTo.
    check_countfinished_definition: assert property (
        @(posedge Clock) disable iff (Reset) (CountFinished == (CountValue == CountTo))
    );

// Out must equal the selected input every cycle.
    mapping_exact: assert property (
        @(posedge clk) out == (sel ? in2 : in1)
    );

// When sel=0, out equals in1.
    sel0_selects_in1: assert property (
        @(posedge clk) !sel |-> (out == in1)
    );

// When sel=1, out equals in2.
    sel1_selects_in2: assert property (
        @(posedge clk) sel |-> (out == in2)
    );

// If in1==in2, out equals that value.
    equal_inputs_imply_out_equal: assert property (
        @(posedge clk) (in1 == in2) |-> (out == in1)
    );

// Out equals one of the two inputs every cycle.
    out_is_one_of_inputs: assert property (
        @(posedge clk) (out == in1) || (out == in2)
    );

///// Functional correctness /////
  // When A == B, eq=1 and gt=0.
  check_equal_case: assert property (
    @(posedge clk) (A == B) |-> (eq == 1'b1 && gt == 1'b0)
  );

// When A > B, gt=1 and eq=0.
  check_greater_case: assert property (
    @(posedge clk) (A > B) |-> (gt == 1'b1 && eq == 1'b0)
  );

// When A < B, eq=0 and gt=0.
  check_less_case: assert property (
    @(posedge clk) (A < B) |-> (eq == 1'b0 && gt == 1'b0)
  );

// eq high implies A == B.
  check_eq_implies_equal: assert property (
    @(posedge clk) eq |-> (A == B)
  );

// gt high implies A > B.
  check_gt_implies_greater: assert property (
    @(posedge clk) gt |-> (A > B)
  );

// eq and gt are never both 1.
  check_outputs_mutex: assert property (
    @(posedge clk) !(eq && gt)
  );

///// Reset behavior /////
    // When clear is asserted low, q must be 0 on the next clock.
    check_clear_forces_zero: assert property (
        @(posedge clk) (clrn == 1'b0) |=> (q == 1'b0)
    );

// When preset is asserted low (and clear is high), q must be 1 on the next clock.
    check_preset_sets_one: assert property (
        @(posedge clk) (clrn == 1'b1 && prn == 1'b0) |=> (q == 1'b1)
    );

// If both clear and preset are low, clear has priority and q must be 0 next clock.
    check_clear_overrides_preset: assert property (
        @(posedge clk) (clrn == 1'b0 && prn == 1'b0) |=> (q == 1'b0)
    );

///// Enable/hold behavior when no resets /////
    // With no resets and enable high, q loads d on the next clock.
    check_enable_loads_d_when_no_resets: assert property (
        @(posedge clk) disable iff (!clrn || !prn) (ena == 1'b1) |=> (q == $past(d))
    );

// With no resets and enable low, q holds its previous value.
    check_hold_when_disabled_when_no_resets: assert property (
        @(posedge clk) disable iff (!clrn || !prn) (ena == 1'b0) |=> (q == $past(q))
    );

// With no resets, the full next-state function matches: q_next = ena ? d : q.
    check_next_state_matches_spec_when_no_resets: assert property (
        @(posedge clk) disable iff (!clrn || !prn)
            1'b1 |=> (q == ($past(ena) ? $past(d) : $past(q)))
    );

// X equals A|B|C|~D_N
    check_function_equation: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// D_N low forces X high
    check_dn_low_forces_x_high: assert property (
        @(posedge clk) (D_N == 1'b0) |-> (X == 1'b1)
    );

// A high forces X high
    check_a_high_forces_x_high: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == 1'b1)
    );

// B high forces X high
    check_b_high_forces_x_high: assert property (
        @(posedge clk) (B == 1'b1) |-> (X == 1'b1)
    );

// C high forces X high
    check_c_high_forces_x_high: assert property (
        @(posedge clk) (C == 1'b1) |-> (X == 1'b1)
    );

// All inputs inactive (A=B=C=0, D_N=1) forces X low
    check_all_inactive_forces_x_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == 1'b0)
    );

// X low implies A=B=C=0 and D_N=1
    check_x_low_implies_all_inactive: assert property (
        @(posedge clk) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1))
    );

// X high implies at least one of A,B,C is high or D_N is low
    check_x_high_implies_some_active: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D_N == 1'b0))
    );

// With D_N high, X equals A|B|C
    check_reduction_when_dn_high: assert property (
        @(posedge clk) (D_N == 1'b1) |-> (X == (A | B | C))
    );

// With A=B=C=0, X equals ~D_N
    check_reduction_when_abc_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X == ~D_N)
    );

// a_low is the low 16 bits of a.
    check_a_low_slice: assert property (
        @(posedge CLK) a_low == a[15:0]
    );

// b_low is the low 16 bits of b.
    check_b_low_slice: assert property (
        @(posedge CLK) b_low == b[15:0]
    );

// a_high is the high 16 bits of a.
    check_a_high_slice: assert property (
        @(posedge CLK) a_high == a[31:16]
    );

// b_high is the high 16 bits of b.
    check_b_high_slice: assert property (
        @(posedge CLK) b_high == b[31:16]
    );

// Low 16-bit adder computes sum_low and carry c1.
    check_low_adder_function: assert property (
        @(posedge CLK) {c1, sum_low} == ({1'b0, a_low} + {1'b0, b_low} + cin)
    );

// High 16-bit adder computes sum_high and carry c2 using c1 as carry-in.
    check_high_adder_function: assert property (
        @(posedge CLK) {c2, sum_high} == ({1'b0, a_high} + {1'b0, b_high} + c1)
    );

// 32-bit sum is the concatenation of high and low sums.
    check_sum_concat: assert property (
        @(posedge CLK) sum == {sum_high, sum_low}
    );

// cout equals the final carry c2.
    check_cout_equals_c2: assert property (
        @(posedge CLK) cout == c2
    );

// sum_low matches low 16 bits of sum.
    check_sum_low_slice_match: assert property (
        @(posedge CLK) sum_low == sum[15:0]
    );

// sum_high matches high 16 bits of sum.
    check_sum_high_slice_match: assert property (
        @(posedge CLK) sum_high == sum[31:16]
    );

// Full 33-bit result equals a + b + cin.
    check_full_width_sum: assert property (
        @(posedge CLK) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

///// Reset behavior /////
    // When reset is asserted LOW at a clock edge, count is forced to 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (count == 3'd0)
    );

// On the first clock after reset deasserts (LOW->HIGH across clocks), count becomes 1.
    check_release_to_one: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && $past(!rst) && rst) |-> (count == 3'd1)
    );

// From a cycle with reset LOW, the next cycle's count is 0 if reset stays LOW, else 1 if reset goes HIGH.
    check_next_cycle_after_reset: assert property (
        @(posedge clk) !rst |-> ##1 ((rst && (count == 3'd1)) || (!rst && (count == 3'd0)))
    );

// When not in reset and count is 0 at a clock edge, it must be due to wrap from 7.
    check_wrap_to_zero_requires_prev_seven: assert property (
        @(posedge clk) disable iff (!rst) ($past(1'b1) && rst && (count == 3'd0)) |-> ($past(count) == 3'd7)
    );

// A high forces X high.
    force_x_high_when_a_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

// B high forces X high.
    force_x_high_when_b_high: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == 1'b1)
    );

// C high forces X high.
    force_x_high_when_c_high: assert property (
        @(posedge CLK) (C == 1'b1) |-> (X == 1'b1)
    );

// D_N low forces X high.
    force_x_high_when_dn_low: assert property (
        @(posedge CLK) (D_N == 1'b0) |-> (X == 1'b1)
    );

// All-neutral inputs drive X low.
    force_x_low_when_all_neutral: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == 1'b0)
    );

// X low implies all inputs neutral.
    x_low_implies_all_neutral: assert property (
        @(posedge CLK) (X == 1'b0) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D_N == 1'b1))
    );

// X high implies at least one asserted (A/B/C) or D_N low.
    x_high_implies_any_input_true: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D_N == 1'b0))
    );

// With B=0,C=0,D_N=1, X equals A.
    x_equals_a_when_b0_c0_dn1: assert property (
        @(posedge CLK) ((B == 1'b0) && (C == 1'b0) && (D_N == 1'b1)) |-> (X == A)
    );

// With A=0,B=0,C=0, X equals !D_N.
    x_equals_notdn_when_a0_b0_c0: assert property (
        @(posedge CLK) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (X == !D_N)
    );

// When all inputs are known, X equals (!D_N) OR A OR B OR C.
    truth_table_when_inputs_known: assert property (
        @(posedge CLK) (!$isunknown({A,B,C,D_N})) |-> (X == ((!D_N) || A || B || C))
    );

// For y==000, Y2 must equal x.
    check_y000_maps_to_x: assert property (
        @(posedge x) (y == 3'b000) |-> (Y2 == x)
    );

// For y==001, Y2 must be 0.
    check_y001_maps_to_0: assert property (
        @(posedge x) (y == 3'b001) |-> (Y2 == 1'b0)
    );

// For y==010, Y2 must equal x.
    check_y010_maps_to_x: assert property (
        @(posedge x) (y == 3'b010) |-> (Y2 == x)
    );

// For y==011, Y2 must be 1.
    check_y011_maps_to_1: assert property (
        @(posedge x) (y == 3'b011) |-> (Y2 == 1'b1)
    );

// For y==100, Y2 must be 1.
    check_y100_maps_to_1: assert property (
        @(posedge x) (y == 3'b100) |-> (Y2 == 1'b1)
    );

// For y==101, Y2 must equal x.
    check_y101_maps_to_x: assert property (
        @(posedge x) (y == 3'b101) |-> (Y2 == x)
    );

// For y==110, Y2 must be 0 (default case).
    check_y110_maps_to_0: assert property (
        @(posedge x) (y == 3'b110) |-> (Y2 == 1'b0)
    );

// For y==111, Y2 must be 0 (default case).
    check_y111_maps_to_0: assert property (
        @(posedge x) (y == 3'b111) |-> (Y2 == 1'b0)
    );

// During reset, X and delay_reg are cleared on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (delay_reg == 4'b0000) && (X == 1'b0)
    );

// DUT is pure combinational: Y == (A & B) | (C & D); no reset present.

    // Y equals (A&B)|(C&D) every sampled cycle.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ((A && B) || (C && D))
    );

// If A and B are both HIGH, Y must be HIGH the same cycle.
    check_y_high_when_ab_true: assert property (
        @(posedge clk) (A && B) |-> (Y == 1'b1)
    );

// If C and D are both HIGH, Y must be HIGH the same cycle.
    check_y_high_when_cd_true: assert property (
        @(posedge clk) (C && D) |-> (Y == 1'b1)
    );

// If neither pair (A&B) nor (C&D) is HIGH, Y must be LOW.
    check_y_low_when_no_pair_true: assert property (
        @(posedge clk) (!(A && B) && !(C && D)) |-> (Y == 1'b0)
    );

// If Y is HIGH, at least one pair (A&B) or (C&D) must be HIGH.
    check_y_high_implies_pair_true: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A && B) || (C && D))
    );

// If Y is LOW, neither (A&B) nor (C&D) is HIGH.
    check_y_low_implies_no_pair_true: assert property (
        @(posedge clk) (Y == 1'b0) |-> (!(A && B) && !(C && D))
    );

///// Basic reset and inversion rules /////
    // When reset is asserted (active low), q must be 0 and q_n must be 1.
    check_reset_forces_outputs: assert property (
        @(negedge clk) (!clr_n) |-> (q == 1'b0) && (q_n == 1'b1)
    );

// q_n is always the logical inverse of q when not in reset.
    check_qn_complement_nonreset_negedge: assert property (
        @(negedge clk) disable iff (!clr_n) (q_n == ~q)
    );

// q_n is always the logical inverse of q on the rising edge as well (not in reset).
    check_qn_complement_nonreset_posedge: assert property (
        @(posedge clk) disable iff (!clr_n) (q_n == ~q)
    );

// q_n remains the logical inverse of q even during reset.
    check_qn_complement_during_reset: assert property (
        @(negedge clk) (!clr_n) |-> (q_n == ~q)
    );

// Output equals the max of the two inputs (unsigned compare).
    check_max_function: assert property (
        @(posedge clk) max_out == (priority_enc_out > comb_circuit_out ? priority_enc_out : comb_circuit_out)
    );

// Output is always equal to one of the two inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge clk) (max_out == priority_enc_out) || (max_out == comb_circuit_out)
    );

// When priority_enc_out > comb_circuit_out, select priority_enc_out.
    check_select_priority_when_greater: assert property (
        @(posedge clk) (priority_enc_out > comb_circuit_out) |-> (max_out == priority_enc_out)
    );

// When priority_enc_out <= comb_circuit_out, select comb_circuit_out.
    check_select_comb_when_not_greater: assert property (
        @(posedge clk) (priority_enc_out <= comb_circuit_out) |-> (max_out == comb_circuit_out)
    );

// On tie, output equals comb_circuit_out.
    check_tie_selects_comb: assert property (
        @(posedge clk) (priority_enc_out == comb_circuit_out) |-> (max_out == comb_circuit_out)
    );

// Output is not less than priority_enc_out.
    check_max_ge_priority: assert property (
        @(posedge clk) max_out >= priority_enc_out
    );

// Output is not less than comb_circuit_out.
    check_max_ge_comb: assert property (
        @(posedge clk) max_out >= comb_circuit_out
    );

// If output equals comb_circuit_out, then comb_circuit_out >= priority_enc_out.
    check_out_eq_comb_implies_comb_ge_priority: assert property (
        @(posedge clk) (max_out == comb_circuit_out) |-> (comb_circuit_out >= priority_enc_out)
    );

// Asynchronous clear holds Q low while asserted.
    check_async_clear_forces_zero: assert property (
        @(posedge CLK) !ACLR |-> (Q == 1'b0)
    );

// X equals logical AND of all four inputs.
    check_output_equals_and4: assert property (
        @(posedge CLK) X == (A && B && C && D)
    );

// If X is HIGH, A must be HIGH.
    check_x_high_implies_a_high: assert property (
        @(posedge CLK) X |-> A
    );

// If X is HIGH, B must be HIGH.
    check_x_high_implies_b_high: assert property (
        @(posedge CLK) X |-> B
    );

// If X is HIGH, C must be HIGH.
    check_x_high_implies_c_high: assert property (
        @(posedge CLK) X |-> C
    );

// If X is HIGH, D must be HIGH.
    check_x_high_implies_d_high: assert property (
        @(posedge CLK) X |-> D
    );

// Y implements Y = C & (~A | ~B).
    check_functional_equivalence: assert property (
        @(posedge CLK) Y == (C & ((~A) | (~B)))
    );

// Y can only be 1 when C is 1.
    check_y_implies_c: assert property (
        @(posedge CLK) Y |-> C
    );

// C=0 forces Y=0.
    check_c0_forces_y0: assert property (
        @(posedge CLK) (!C) |-> (Y == 1'b0)
    );

// If both A and B are 1, Y must be 0 (independent of C).
    check_ab_both_one_forces_y0: assert property (
        @(posedge CLK) (A && B) |-> (Y == 1'b0)
    );

// With C=1 and A=0, Y must be 1.
    check_c1_a0_sets_y1: assert property (
        @(posedge CLK) (C && !A) |-> (Y == 1'b1)
    );

// With C=1 and B=0, Y must be 1.
    check_c1_b0_sets_y1: assert property (
        @(posedge CLK) (C && !B) |-> (Y == 1'b1)
    );

// If Y=1, then C=1 and at least one of A or B is 0.
    check_y1_implies_c_and_one_input_zero: assert property (
        @(posedge CLK) Y |-> (C && ((!A) || (!B)))
    );

// Output equals logical AND of inputs (4-state aware).
    check_out_equals_and: assert property (
        @(posedge clk) out === (a & b)
    );

// When both inputs are 1, out must be 1.
    check_out_one_when_both_one: assert property (
        @(posedge clk) (a === 1'b1 && b === 1'b1) |-> (out === 1'b1)
    );

// When any input is 0, out must be 0.
    check_out_zero_when_any_zero: assert property (
        @(posedge clk) ((a === 1'b0) || (b === 1'b0)) |-> (out === 1'b0)
    );

// Out can be 1 only if both inputs are 1.
    check_out_one_implies_inputs_one: assert property (
        @(posedge clk) (out === 1'b1) |-> (a === 1'b1 && b === 1'b1)
    );

// Rising edge on out only when both inputs are high.
    check_out_rise_requires_both_high: assert property (
        @(posedge clk) $rose(out) |-> (a === 1'b1 && b === 1'b1)
    );

// Falling edge on out only when any input is low.
    check_out_fall_requires_any_low: assert property (
        @(posedge clk) $fell(out) |-> ((a === 1'b0) || (b === 1'b0))
    );

// With known inputs, out is known and equals a & b.
    check_out_known_when_inputs_known: assert property (
        @(posedge clk) ((a inside {1'b0,1'b1}) && (b inside {1'b0,1'b1})) |-> ((out inside {1'b0,1'b1}) && (out === (a & b)))
    );

// Unknown out implies at least one input is unknown.
    check_x_out_implies_x_input: assert property (
        @(posedge clk) (!(out inside {1'b0,1'b1})) |-> ( !(a inside {1'b0,1'b1}) || !(b inside {1'b0,1'b1}) )
    );

// Y must equal the selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (1'b0) Y == ((SEL == 1'b0) ? A : B)
    );

// When SEL is 0, Y must equal A.
    check_sel_zero_path: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b0) |-> (Y == A)
    );

// When SEL is 1, Y must equal B.
    check_sel_one_path: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b1) |-> (Y == B)
    );

// Y must always equal one of the inputs.
    check_output_is_one_of_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == A) || (Y == B)
    );

// If inputs are equal, Y must equal that common value.
    check_equal_inputs: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (Y == A)
    );

// If inputs differ and Y equals A, SEL must be 0.
    check_select_infers_zero_when_outputs_A: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B && Y == A) |-> (SEL == 1'b0)
    );

// If inputs differ and Y equals B, SEL must be 1.
    check_select_infers_one_when_outputs_B: assert property (
        @(posedge CLK) disable iff (1'b0) (A != B && Y == B) |-> (SEL == 1'b1)
    );

// With SEL=0, Y can equal B only if A equals B.
    check_no_bypass_when_sel_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b0 && (Y == B)) |-> (A == B)
    );

// With SEL=1, Y can equal A only if A equals B.
    check_no_bypass_when_sel_one: assert property (
        @(posedge CLK) disable iff (1'b0) (SEL == 1'b1 && (Y == A)) |-> (A == B)
    );

// X equals the structural expression implemented in RTL.
    check_structural_equivalence: assert property (
        @(posedge CLK) X == ((A | B | C_N) & (A | C_N) & (B | C_N))
    );

// X equals the simplified boolean form C_N | (A & B).
    check_simplified_equivalence: assert property (
        @(posedge CLK) X == (C_N | (A & B))
    );

// When C_N is 1, X must be 1.
    check_cn_dominates: assert property (
        @(posedge CLK) C_N |-> (X == 1'b1)
    );

// When C_N is 0, X must equal A & B.
    check_cn0_means_and: assert property (
        @(posedge CLK) (!C_N) |-> (X == (A & B))
    );

// When C_N is 0 and A is 0, X must be 0.
    check_cn0_a0_forces_x0: assert property (
        @(posedge CLK) (!C_N && !A) |-> (X == 1'b0)
    );

// When C_N is 0 and B is 0, X must be 0.
    check_cn0_b0_forces_x0: assert property (
        @(posedge CLK) (!C_N && !B) |-> (X == 1'b0)
    );

// When both A and B are 1, X must be 1.
    check_ab_high_implies_x1: assert property (
        @(posedge CLK) (A && B) |-> (X == 1'b1)
    );

// If X is 1, then at least one of A, B, or C_N is 1.
    check_x_implies_any_input_or_cn: assert property (
        @(posedge CLK) X |-> (A | B | C_N)
    );

// If X is 1, then A or C_N must be 1.
    check_x_implies_a_or_cn: assert property (
        @(posedge CLK) X |-> (A | C_N)
    );

// If X is 1, then B or C_N must be 1.
    check_x_implies_b_or_cn: assert property (
        @(posedge CLK) X |-> (B | C_N)
    );

// X matches the RTL equation: C ? (A^B) : (A|B)
    check_function_equation: assert property (
        @(posedge clk) X == (C ? (A ^ B) : (A | B))
    );

// When C is 1, X is A xor B
    check_select_high_is_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (X == (A ^ B))
    );

// When C is 0, X is A or B
    check_select_low_is_or: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == (A | B))
    );

// With C=0 and A==B, X equals A
    check_c_low_equal_inputs_pass_through: assert property (
        @(posedge clk) (C == 1'b0) && (A == B) |-> (X == A)
    );

// If A=0 and B=0, X must be 0
    check_both_zero_results_zero: assert property (
        @(posedge clk) (A == 1'b0) && (B == 1'b0) |-> (X == 1'b0)
    );

// If A=1, B=1, and C=1, then X must be 0
    check_both_one_c_high_results_zero: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) && (C == 1'b1) |-> (X == 1'b0)
    );

// If A=1, B=1, and C=0, then X must be 1
    check_both_one_c_low_results_one: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) && (C == 1'b0) |-> (X == 1'b1)
    );

// With C=1, differing inputs imply X=1
    check_c_high_inputs_differ_results_one: assert property (
        @(posedge clk) (C == 1'b1) && (A != B) |-> (X == 1'b1)
    );

// With C=1, equal inputs imply X=0
    check_c_high_inputs_equal_results_zero: assert property (
        @(posedge clk) (C == 1'b1) && (A == B) |-> (X == 1'b0)
    );

// With C=0, any input high implies X=1
    check_c_low_any_one_results_one: assert property (
        @(posedge clk) (C == 1'b0) && ((A == 1'b1) || (B == 1'b1)) |-> (X == 1'b1)
    );

// Function: out implements a 2:1 mux: out = (in0 & ~sel) | (in1 & sel).
    check_mux_equation: assert property (
        @(posedge clk) out == ((in0 & ~sel) | (in1 & sel))
    );

// When sel=0, out equals in0.
    check_sel0_path: assert property (
        @(posedge clk) (!sel) |-> (out == in0)
    );

// When sel=1, out equals in1.
    check_sel1_path: assert property (
        @(posedge clk) (sel) |-> (out == in1)
    );

// If inputs are equal, out matches that value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (in0 == in1) |-> (out == in0)
    );

// On sel rising edge, out immediately selects in1.
    check_sel_rise_selects_in1: assert property (
        @(posedge clk) $rose(sel) |-> (out == in1)
    );

// On sel falling edge, out immediately selects in0.
    check_sel_fall_selects_in0: assert property (
        @(posedge clk) $fell(sel) |-> (out == in0)
    );

// When a >= b, out must equal a.
    check_out_eq_a_when_a_ge_b: assert property (
        @(posedge clk) (a >= b) |-> (out == a)
    );

// When b > a, out must equal b.
    check_out_eq_b_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (out == b)
    );

// When a == b, out must equal a.
    check_out_eq_a_when_equal: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// If neither condition holds, out is 0.
    check_out_zero_when_neither: assert property (
        @(posedge clk) (!(a >= b) && !(b > a)) |-> (out == 8'h00)
    );

// Under a >= b, out is at least b.
    check_out_ge_b_when_a_ge_b: assert property (
        @(posedge clk) (a >= b) |-> (out >= b)
    );

// Under b > a, out is at least a.
    check_out_ge_a_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (out >= a)
    );

///// Reset behavior /////
    // When RST is high, Q must be 0 on the next cycle.
    check_reset_clears_Q_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'h0)
    );

// If RST is high in two consecutive cycles, Q must be 0 in the second cycle.
    check_Q_zero_while_reset_held: assert property (
        @(posedge CLK) (RST && $past(RST)) |-> (Q == 4'h0)
    );

// On a rising edge of RST, Q must be 0 on the next cycle.
    check_next_after_reset_assert_zero: assert property (
        @(posedge CLK) $rose(RST) |=> (Q == 4'h0)
    );

// When not in reset, Q must change every cycle (no hold).
    check_counter_advances_each_cycle: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> (Q != $past(Q))
    );

// When not in reset and Q is 0xF, it wraps to 0 on the next cycle.
    check_wrap_from_max_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

// When not in reset and Q is 0xE, it becomes 0xF on the next cycle.
    check_increment_from_E_to_F_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hE) |=> (Q == 4'hF)
    );

// Clock: clk (posedge). No explicit reset. q updates to d when as==0; holds when as==1.

  // When as is LOW, q captures d on the next clock.
  check_load_on_as_low: assert property (
    @(posedge clk) (~as) |=> (q == $past(d))
  );

// When as is HIGH, q holds its previous value on the next clock.
  check_hold_when_as_high: assert property (
    @(posedge clk) (as) |=> (q == $past(q))
  );

// If as is LOW and d differs from current q, q must change next cycle.
  check_update_changes_when_data_diff: assert property (
    @(posedge clk) (~as && (d != q)) |=> (q != $past(q))
  );

// If as is LOW and d equals current q, q must not change next cycle.
  check_update_no_change_when_data_same: assert property (
    @(posedge clk) (~as && (d == q)) |=> (q == $past(q))
  );

// While holding (as HIGH), changes on d do not affect q.
  check_data_changes_do_not_affect_when_as_high: assert property (
    @(posedge clk) (as && $changed(d)) |=> (q == $past(q))
  );

// On a falling edge of as, q captures d on the next clock.
  check_fall_as_triggers_update: assert property (
    @(posedge clk) $fell(as) |=> (q == $past(d))
  );

// On a rising edge of as, q must hold on the next clock.
  check_rise_as_holds_value: assert property (
    @(posedge clk) $rose(as) |=> (q == $past(q))
  );

// Next cycle so=00 when b is 0,1,2.
    map_b_0_1_2_to_so_00: assert property (
        @(posedge clk) (b inside {4'd0,4'd1,4'd2}) |=> (so == 2'b00)
    );

// Next cycle so=01 when b is 3 or 4.
    map_b_3_4_to_so_01: assert property (
        @(posedge clk) (b inside {4'd3,4'd4}) |=> (so == 2'b01)
    );

// Next cycle so=10 when b is 5 or 6.
    map_b_5_6_to_so_10: assert property (
        @(posedge clk) (b inside {4'd5,4'd6}) |=> (so == 2'b10)
    );

// Next cycle so=11 when b is 7.
    map_b_7_to_so_11: assert property (
        @(posedge clk) (b == 4'd7) |=> (so == 2'b11)
    );

// Next cycle so=00 for default cases b=8..15.
    map_b_8_to_15_default_to_so_00: assert property (
        @(posedge clk) (b inside {[4'd8:4'd15]}) |=> (so == 2'b00)
    );

// For b=3..7, next cycle so is never 00.
    not_00_for_b_3_to_7: assert property (
        @(posedge clk) (b inside {[4'd3:4'd7]}) |=> (so != 2'b00)
    );

// Only b=3 or 4 produce next cycle so=01.
    only_3_4_give_01: assert property (
        @(posedge clk) (!(b inside {4'd3,4'd4})) |=> (so != 2'b01)
    );

// Only b=5 or 6 produce next cycle so=10.
    only_5_6_give_10: assert property (
        @(posedge clk) (!(b inside {4'd5,4'd6})) |=> (so != 2'b10)
    );

// Only b=7 produces next cycle so=11.
    only_7_gives_11: assert property (
        @(posedge clk) (b != 4'd7) |=> (so != 2'b11)
    );

///// WEA behavior /////
    // WEA is always 0 after reset.
    check_wea_const_zero: assert property (
        @(posedge clk) disable iff (reset)
            wea == 1'b0
    );

// rsp_valid must mirror cmd_valid each cycle.
    check_rsp_valid_mirror: assert property (
        @(posedge clk) disable iff (reset) (rsp_valid == cmd_valid)
    );

// cmd_ready must mirror rsp_ready each cycle.
    check_cmd_ready_mirror: assert property (
        @(posedge clk) disable iff (reset) (cmd_ready == rsp_ready)
    );

// When select=0, output routes inputs_0.
    mux_select0_routes_in0: assert property (
        @(posedge clk) disable iff (reset) (!cmd_payload_function_id[0]) |-> (rsp_payload_outputs_0 == cmd_payload_inputs_0)
    );

// When select=1, output routes inputs_1.
    mux_select1_routes_in1: assert property (
        @(posedge clk) disable iff (reset) (cmd_payload_function_id[0]) |-> (rsp_payload_outputs_0 == cmd_payload_inputs_1)
    );

// Output equals the ternary mux of select and inputs.
    mux_function_equivalence: assert property (
        @(posedge clk) disable iff (reset) (rsp_payload_outputs_0 == (cmd_payload_function_id[0] ? cmd_payload_inputs_1 : cmd_payload_inputs_0))
    );

///// Reset behavior /////
    // While reset is asserted, drive out_port and readdata to 0.
    reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> (out_port == 6'd0) && (readdata == 32'd0)
    );

///// Read datapath /////
    // Upper readdata bits are always zero.
    readdata_upper_zero_always: assert property (
        @(posedge clk) disable iff (!reset_n) readdata[31:6] == 26'd0
    );

// When address == 0, readdata[5:0] reflects out_port.
    read_addr0_reflects_out_port: assert property (
        @(posedge clk) disable iff (!reset_n) (address == 2'd0) |-> (readdata[5:0] == out_port)
    );

// When address != 0, entire readdata is zero.
    read_addr_nonzero_is_zero: assert property (
        @(posedge clk) disable iff (!reset_n) (address != 2'd0) |-> (readdata == 32'd0)
    );

// On reset release, if no same-cycle write to address 0, out_port remains 0.
    zero_after_reset_release_no_write: assert property (
        @(posedge clk) disable iff (!reset_n)
            $rose(reset_n) && !(chipselect && !write_n && (address == 2'd0)) |-> (out_port == 6'd0)
    );

// Result matches the full case-defined function for all shift_amount values.
    check_function_complete: assert property (
        @(posedge CLK)
            ((shift_amount == 2'b00) && (result == data)) ||
            ((shift_amount == 2'b01) && (result == {data[2:0], 1'b0})) ||
            ((shift_amount == 2'b10) && (result == {data[1:0], 2'b00})) ||
            ((shift_amount == 2'b11) && (result == 4'b0000))
    );

// No shift: result equals data when shift_amount == 2'b00.
    check_no_shift_passthrough: assert property (
        @(posedge CLK) (shift_amount == 2'b00) |-> (result == data)
    );

// Shift by 1: result equals {data[2:0], 1'b0} when shift_amount == 2'b01.
    check_shift1_concat: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

// Shift by 2: result equals {data[1:0], 2'b00} when shift_amount == 2'b10.
    check_shift2_concat: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

// Shift by 3 (2'b11): result is 4'b0000 regardless of data.
    check_shift3_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b11) |-> (result == 4'b0000)
    );

// Shift by 1: LSB is forced to 0.
    check_shift1_lsb_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result[0] == 1'b0)
    );

// Shift by 2: two LSBs are forced to 0.
    check_shift2_lsbs_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result[1:0] == 2'b00)
    );

// Shift by 1: upper bits map to data[2:0].
    check_shift1_upper_map: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result[3:1] == data[2:0])
    );

// Shift by 2: upper two bits map to data[1:0].
    check_shift2_upper_map: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result[3:2] == data[1:0])
    );

///// Combinational mapping checks (sampled on clk) /////
    // gray[3] equals binary[8].
    check_gray3_eq_binary8: assert property (
        @(posedge clk) gray[3] == binary[8]
    );

// gray[2] equals binary[8] XOR binary[7].
    check_gray2_eq_b8_xor_b7: assert property (
        @(posedge clk) gray[2] == (binary[8] ^ binary[7])
    );

// gray[1] equals binary[7] XOR binary[6].
    check_gray1_eq_b7_xor_b6: assert property (
        @(posedge clk) gray[1] == (binary[7] ^ binary[6])
    );

// gray[0] equals binary[6] XOR binary[5].
    check_gray0_eq_b6_xor_b5: assert property (
        @(posedge clk) gray[0] == (binary[6] ^ binary[5])
    );

// During reset, out must be cleared to 0.
    check_reset_clears_out: assert property (
        @(posedge clk) !rst_n |-> (out == 4'b0000)
    );

// When read_en is LOW, out holds its previous value.
    check_out_holds_without_read: assert property (
        @(posedge clk) disable iff (!rst_n) (!read_en) |=> (out == $past(out))
    );

// With read_en HIGH and mux_sel==01, out captures mux_in_0 on next cycle.
    check_read_sel_01_routes_mux_in_0: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b01)) |=> (out == $past(mux_in_0))
    );

// With read_en HIGH and mux_sel==10, out captures mux_in_1 on next cycle.
    check_read_sel_10_routes_mux_in_1: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b10)) |=> (out == $past(mux_in_1))
    );

// With read_en HIGH and mux_sel==11, out captures mux_in_2 on next cycle.
    check_read_sel_11_routes_mux_in_2: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b11)) |=> (out == $past(mux_in_2))
    );

// Functional equivalence: X == (~B1_N) & (A1 | A2).
    check_function_equation: assert property (
        @(posedge CLK) X == ((~B1_N) & (A1 | A2))
    );

// When B1_N is HIGH, X must be LOW.
    check_x_low_when_B1_N_high: assert property (
        @(posedge CLK) (B1_N == 1'b1) |-> (X == 1'b0)
    );

// When both A1 and A2 are LOW, X must be LOW.
    check_x_low_when_A1_A2_low: assert property (
        @(posedge CLK) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// When B1_N is LOW, X equals (A1 | A2).
    check_x_equals_or_under_enable: assert property (
        @(posedge CLK) (B1_N == 1'b0) |-> (X == (A1 | A2))
    );

// If X is HIGH, B1_N must be LOW.
    check_x_high_implies_B1_N_low: assert property (
        @(posedge CLK) (X == 1'b1) |-> (B1_N == 1'b0)
    );

// If X is HIGH, at least one of A1 or A2 must be HIGH.
    check_x_high_implies_A1_or_A2_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A1 || A2)
    );

// If B1_N is LOW and A1 is HIGH, X must be HIGH.
    check_x_high_when_B1_N_low_and_A1_high: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

// If B1_N is LOW and A2 is HIGH, X must be HIGH.
    check_x_high_when_B1_N_low_and_A2_high: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

// If B1_N is LOW and both A1 and A2 are LOW, X must be LOW.
    check_x_low_when_enable_and_inputs_low: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// If X is LOW, then either B1_N is HIGH or both A1 and A2 are LOW.
    check_x_low_implies_block_or_both_low: assert property (
        @(posedge CLK) (X == 1'b0) |-> (B1_N || ((A1 == 1'b0) && (A2 == 1'b0)))
    );

// When sel=0, reg_a_wr_data_out equals alu_data_in.
    check_a_data_when_sel0: assert property (
        @(posedge clk) (write_back_mux_sel == 1'b0) |-> (reg_a_wr_data_out == alu_data_in)
    );

// reg_b_wr_data_out passes through hi_data_in.
    check_b_data_passthrough: assert property (
        @(posedge clk) reg_b_wr_data_out == hi_data_in
    );

// reg_a_wr_en_out passes through reg_a_wr_en_in.
    check_a_wr_en_passthrough: assert property (
        @(posedge clk) reg_a_wr_en_out == reg_a_wr_en_in
    );

// reg_b_wr_en_out passes through reg_b_wr_en_in.
    check_b_wr_en_passthrough: assert property (
        @(posedge clk) reg_b_wr_en_out == reg_b_wr_en_in
    );

// reg_a_wr_addr_out passes through reg_a_wr_addr_in.
    check_a_addr_passthrough: assert property (
        @(posedge clk) reg_a_wr_addr_out == reg_a_wr_addr_in
    );

// reg_b_wr_addr_out passes through reg_b_wr_addr_in.
    check_b_addr_passthrough: assert property (
        @(posedge clk) reg_b_wr_addr_out == reg_b_wr_addr_in
    );

// o_dataout is the mux of i_register_settings and i_datain selected by i_settings.
    check_dataout_mux_function: assert property (
        @(posedge clock) disable iff (!resetn)
            o_dataout == (i_settings ? i_register_settings : i_datain)
    );

// When i_settings is 1, o_dataout equals i_register_settings.
    check_dataout_sel_register_settings: assert property (
        @(posedge clock) disable iff (!resetn)
            i_settings |-> (o_dataout == i_register_settings)
    );

// When i_settings is 0, o_dataout equals i_datain.
    check_dataout_sel_datain: assert property (
        @(posedge clock) disable iff (!resetn)
            !i_settings |-> (o_dataout == i_datain)
    );

// o_dataout_valid passes through from i_datain_valid.
    check_valid_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
            o_dataout_valid == i_datain_valid
    );

// o_datain_stall passes through from i_dataout_stall.
    check_stall_passthrough: assert property (
        @(posedge clock) disable iff (!resetn)
            o_datain_stall == i_dataout_stall
    );

// If i_settings and both data inputs are stable, o_dataout remains stable.
    check_dataout_stable_when_all_inputs_stable: assert property (
        @(posedge clock) disable iff (!resetn)
            $stable(i_settings) && $stable(i_register_settings) && $stable(i_datain)
            |-> $stable(o_dataout)
    );

// If i_datain_valid is stable, o_dataout_valid remains stable.
    check_valid_stable_when_input_valid_stable: assert property (
        @(posedge clock) disable iff (!resetn)
            $stable(i_datain_valid) |-> $stable(o_dataout_valid)
    );

// If i_dataout_stall is stable, o_datain_stall remains stable.
    check_stall_stable_when_input_stall_stable: assert property (
        @(posedge clock) disable iff (!resetn)
            $stable(i_dataout_stall) |-> $stable(o_datain_stall)
    );

// Changes on unselected i_datain do not affect o_dataout when selecting i_register_settings.
    check_independence_unselected_datain: assert property (
        @(posedge clock) disable iff (!resetn)
            i_settings && $stable(i_register_settings) && $changed(i_datain)
            |-> $stable(o_dataout)
    );

// Changes on unselected i_register_settings do not affect o_dataout when selecting i_datain.
    check_independence_unselected_regsettings: assert property (
        @(posedge clock) disable iff (!resetn)
            !i_settings && $stable(i_datain) && $changed(i_register_settings)
            |-> $stable(o_dataout)
    );

// When GATE is high, Q holds its previous sampled value into the next cycle.
    check_hold_when_gate_high: assert property (
        @(posedge CLK) GATE |=> (Q == $past(Q))
    );

// If GATE is high and D toggles, Q still holds its previous value into the next cycle.
    check_hold_when_gate_high_even_if_d_toggles: assert property (
        @(posedge CLK) (GATE && (D != $past(D))) |=> (Q == $past(Q))
    );

// Out equals the input bit indexed by sel.
    check_out_matches_index: assert property (
        @(posedge clk) out == in[sel]
    );

// When sel==00, out must equal in[0].
    check_sel_00_mapping: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// When sel==01, out must equal in[1].
    check_sel_01_mapping: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// When sel==10, out must equal in[2].
    check_sel_10_mapping: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// When sel==11, out must equal in[3].
    check_sel_11_mapping: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Out equals SOP decode of sel and inputs (structural equivalence).
    check_sop_equivalence: assert property (
        @(posedge clk) out ==
            ((~sel[1] & ~sel[0] & in[0]) |
             (~sel[1] &  sel[0] & in[1]) |
             ( sel[1] & ~sel[0] & in[2]) |
             ( sel[1] &  sel[0] & in[3]))
    );

///// Functional equivalence to RTL assign /////
    // X matches A|B|C|D_N when A rises.
    check_or_equiv_on_A_posedge: assert property (
        @(posedge A) X == (A | B | C | D_N)
    );

// X matches A|B|C|D_N when A falls.
    check_or_equiv_on_A_negedge: assert property (
        @(negedge A) X == (A | B | C | D_N)
    );

// X matches A|B|C|D_N when B rises.
    check_or_equiv_on_B_posedge: assert property (
        @(posedge B) X == (A | B | C | D_N)
    );

// X matches A|B|C|D_N when B falls.
    check_or_equiv_on_B_negedge: assert property (
        @(negedge B) X == (A | B | C | D_N)
    );

// X matches A|B|C|D_N when C rises.
    check_or_equiv_on_C_posedge: assert property (
        @(posedge C) X == (A | B | C | D_N)
    );

// X matches A|B|C|D_N when C falls.
    check_or_equiv_on_C_negedge: assert property (
        @(negedge C) X == (A | B | C | D_N)
    );

// X matches A|B|C|D_N when D_N rises.
    check_or_equiv_on_DN_posedge: assert property (
        @(posedge D_N) X == (A | B | C | D_N)
    );

// X matches A|B|C|D_N when D_N falls.
    check_or_equiv_on_DN_negedge: assert property (
        @(negedge D_N) X == (A | B | C | D_N)
    );

///// Reset behavior /////
    // During reset, all EX regs are 0 and ex_instr is 32'b100000.
    check_reset_defaults: assert property (
        @(posedge clk) rst |-> (ex_a==32'b0 && ex_b==32'b0 && ex_d2==32'b0 &&
                                ex_td==5'b0 && ex_Aluc==5'b0 &&
                                ex_WREG==1'b0 && ex_WMEM==1'b0 && ex_LW==1'b0 &&
                                ex_instr==32'b100000)
    );

///// Flush behavior (BJ) /////
    // If BJ is asserted, next cycle EX regs clear to 0 and ex_instr to 32'b100000.
    check_flush_clears_outputs: assert property (
        @(posedge clk) disable iff (rst)
            BJ |=> (ex_a==32'b0 && ex_b==32'b0 && ex_d2==32'b0 &&
                    ex_td==5'b0 && ex_Aluc==5'b0 &&
                    ex_WREG==1'b0 && ex_WMEM==1'b0 && ex_LW==1'b0 &&
                    ex_instr==32'b100000)
    );

///// Pass-through behavior when not flushing /////
    // When BJ is 0, ex_a captures id_a in the next cycle.
    check_pass_through_ex_a: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_a == $past(id_a))
    );

// When BJ is 0, ex_b captures id_b in the next cycle.
    check_pass_through_ex_b: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_b == $past(id_b))
    );

// When BJ is 0, ex_d2 captures id_d2 in the next cycle.
    check_pass_through_ex_d2: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_d2 == $past(id_d2))
    );

// When BJ is 0, ex_td captures id_td in the next cycle.
    check_pass_through_ex_td: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_td == $past(id_td))
    );

// When BJ is 0, ex_Aluc captures id_Aluc in the next cycle.
    check_pass_through_ex_Aluc: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_Aluc == $past(id_Aluc))
    );

// When BJ is 0, ex_WREG captures id_WREG in the next cycle.
    check_pass_through_ex_WREG: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_WREG == $past(id_WREG))
    );

// When BJ is 0, ex_WMEM captures id_WMEM in the next cycle.
    check_pass_through_ex_WMEM: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_WMEM == $past(id_WMEM))
    );

// When BJ is 0, ex_LW captures id_LW in the next cycle.
    check_pass_through_ex_LW: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_LW == $past(id_LW))
    );

// When BJ is 0, ex_instr captures id_instr in the next cycle.
    check_pass_through_ex_instr: assert property (
        @(posedge clk) disable iff (rst) (!BJ) |=> (ex_instr == $past(id_instr))
    );

// When sel==0, out must equal a.
    check_sel0_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When sel==1, out must equal b.
    check_sel1_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// If a and b are equal, out must equal that value regardless of sel.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// Y equals (~(A & B)) & (~(C & D)).
    check_y_eq_nands_and_form: assert property (
        @(posedge CLK) Y == ((~(A & B)) & (~(C & D)))
    );

// Y equals ~((A & B) | (C & D)) by De Morgan.
    check_y_eq_demorgan_or_form: assert property (
        @(posedge CLK) Y == ~( (A & B) | (C & D) )
    );

// If A and B are both 1, Y must be 0.
    check_ab_high_forces_y_low: assert property (
        @(posedge CLK) (A & B) |-> (Y == 1'b0)
    );

// If C and D are both 1, Y must be 0.
    check_cd_high_forces_y_low: assert property (
        @(posedge CLK) (C & D) |-> (Y == 1'b0)
    );

// If neither A&B nor C&D is 1, Y must be 1.
    check_no_pair_and_implies_y_high: assert property (
        @(posedge CLK) (!(A & B) && !(C & D)) |-> (Y == 1'b1)
    );

// If Y is 1, then neither A&B nor C&D is 1.
    check_y_high_implies_no_pair_and: assert property (
        @(posedge CLK) Y |-> (!(A & B) && !(C & D))
    );

// If Y is 0, then at least one of A&B or C&D is 1.
    check_y_low_implies_some_pair_and: assert property (
        @(posedge CLK) (!Y) |-> ((A & B) || (C & D))
    );

// When sel=1, out must equal b.
    check_sel1_routes_b: assert property (
        @(posedge clk) sel |-> (out == b)
    );

// When sel=0, out must equal a.
    check_sel0_routes_a: assert property (
        @(posedge clk) (~sel) |-> (out == a)
    );

// If sel=1 and b=1 then out must be 1.
    check_out1_when_sel1_b1: assert property (
        @(posedge clk) (sel & b) |-> (out == 1'b1)
    );

// If sel=1 and b=0 then out must be 0.
    check_out0_when_sel1_b0: assert property (
        @(posedge clk) (sel & (~b)) |-> (out == 1'b0)
    );

// If sel=0 and a=1 then out must be 1.
    check_out1_when_sel0_a1: assert property (
        @(posedge clk) ((~sel) & a) |-> (out == 1'b1)
    );

// If sel=0 and a=0 then out must be 0.
    check_out0_when_sel0_a0: assert property (
        @(posedge clk) ((~sel) & (~a)) |-> (out == 1'b0)
    );

// When condition==14, take must be 1.
    check_take_cond14_one: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd14) |-> (take === 1'b1)
    );

// For any other condition, take must be 0 (default case).
    check_take_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!(condition inside { 'd0, 'd1, 'd2, 'd3, 'd4, 'd5, 'd6, 'd7, 'd8, 'd9, 'd10, 'd11, 'd12, 'd13, 'd14 })) |-> (take === 1'b0)
    );

///// Functional correctness /////
    // Full 17-bit result must equal unsigned A+B.
    check_fullsum_matches_addition: assert property (
        @(posedge CLK) disable iff (1'b0) {cout, Sbits} == expected_sum
    );

// LSB sum is XOR of LSB inputs (no carry-in).
    check_s0_is_xor: assert property (
        @(posedge CLK) disable iff (1'b0) s0 == (a0 ^ b0)
    );

// MSB of sum must match expected_sum[15].
    check_s15_matches_expected: assert property (
        @(posedge CLK) disable iff (1'b0) s15 == expected_sum[15]
    );

///// Corner cases /////
    // Adding zero on B side passes A through with no carry.
    check_add_zero_B: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 16'h0000) |-> ({cout, Sbits} == {1'b0, A})
    );

// Adding zero on A side passes B through with no carry.
    check_add_zero_A: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 16'h0000) |-> ({cout, Sbits} == {1'b0, B})
    );

// Adding bitwise complement yields all 1s with no carry.
    check_add_complement: assert property (
        @(posedge CLK) disable iff (1'b0) (B == ~A) |-> ({cout, Sbits} == {1'b0, 16'hFFFF})
    );

// Adding 1 on B increments A by 1.
    check_add_one_B: assert property (
        @(posedge CLK) disable iff (1'b0) (B == 16'h0001) |-> ({cout, Sbits} == ({1'b0, A} + 17'd1))
    );

// Adding 1 on A increments B by 1.
    check_add_one_A: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 16'h0001) |-> ({cout, Sbits} == ({1'b0, B} + 17'd1))
    );

///// Carry behavior (unsigned) /////
    // If carry-out is 1, the truncated sum is less than at least one operand.
    check_cout_implies_sum_less_operand: assert property (
        @(posedge CLK) disable iff (1'b0) cout |-> ((Sbits < A) || (Sbits < B))
    );

// If carry-out is 0, the truncated sum is >= both operands.
    check_no_cout_implies_sum_ge_operands: assert property (
        @(posedge CLK) disable iff (1'b0) !cout |-> ((Sbits >= A) && (Sbits >= B))
    );

///// Functional equivalence /////
    // X implements a 4-input NAND of {A,B,C,D_N}.
    check_functional_equation: assert property (
        @(posedge CLK) X == ~(A & B & C & D_N)
    );

///// Basic implications /////
    // When all inputs are 1, X must be 0.
    check_all_ones_implies_X0: assert property (
        @(posedge CLK) (A && B && C && D_N) |-> (X == 1'b0)
    );

// If A is 0, X must be 1.
    check_A_zero_implies_X1: assert property (
        @(posedge CLK) (!A) |-> (X == 1'b1)
    );

// If B is 0, X must be 1.
    check_B_zero_implies_X1: assert property (
        @(posedge CLK) (!B) |-> (X == 1'b1)
    );

// If C is 0, X must be 1.
    check_C_zero_implies_X1: assert property (
        @(posedge CLK) (!C) |-> (X == 1'b1)
    );

// If D_N is 0, X must be 1.
    check_DN_zero_implies_X1: assert property (
        @(posedge CLK) (!D_N) |-> (X == 1'b1)
    );

///// Output transition constraints /////
    // X can only fall when all inputs are 1 in the same cycle.
    check_X_fall_implies_all_ones: assert property (
        @(posedge CLK) $fell(X) |-> (A && B && C && D_N)
    );

// X can only rise when at least one input is 0 in the same cycle.
    check_X_rise_implies_any_zero: assert property (
        @(posedge CLK) $rose(X) |-> (!A || !B || !C || !D_N)
    );

// When I is zero, outputs are all zero.
    check_outputs_when_I_zero: assert property (
        @(posedge clk) (I == 8'b0) |-> (EN == 1'b0 && V == 1'b0 && Q == 3'b000)
    );

// If bit 7 is set, Q wraps to 0 due to i+1 truncation to 3 bits.
    check_q_zero_when_bit7_set: assert property (
        @(posedge clk) I[7] |-> (Q == 3'b000)
    );

// X equals A ^ B ^ C when sampled on A rising edge.
    check_xor_eq_on_A: assert property (
        @(posedge A) X == (A ^ B ^ C)
    );

// X equals A ^ B ^ C when sampled on B rising edge.
    check_xor_eq_on_B: assert property (
        @(posedge B) X == (A ^ B ^ C)
    );

// X equals A ^ B ^ C when sampled on C rising edge.
    check_xor_eq_on_C: assert property (
        @(posedge C) X == (A ^ B ^ C)
    );

// With B=0 and C=0, X follows A.
    check_B0_C0_eq_A: assert property (
        @(posedge A) (B == 1'b0 && C == 1'b0) |-> (X == A)
    );

// With B=1 and C=1, X follows A.
    check_B1_C1_eq_A: assert property (
        @(posedge A) (B == 1'b1 && C == 1'b1) |-> (X == A)
    );

// With B=1 and C=0, X equals bitwise NOT of A.
    check_B1_C0_eq_notA: assert property (
        @(posedge B) (B == 1'b1 && C == 1'b0) |-> (X == ~A)
    );

// With B=0 and C=1, X equals bitwise NOT of A.
    check_B0_C1_eq_notA: assert property (
        @(posedge C) (B == 1'b0 && C == 1'b1) |-> (X == ~A)
    );

// If A equals B, then X equals C.
    check_AeqB_implies_XeqC: assert property (
        @(posedge A) (A == B) |-> (X == C)
    );

// If B equals C, then X equals A.
    check_BeqC_implies_XeqA: assert property (
        @(posedge B) (B == C) |-> (X == A)
    );

// If A equals C, then X equals B.
    check_AeqC_implies_XeqB: assert property (
        @(posedge C) (A == C) |-> (X == B)
    );

///// Direct implementation checks /////
    // b[2] equals ~(a3&a2&a1&a0).
    check_b2_definition: assert property (
        @(posedge CLK) b[2] == ~(a[3] & a[2] & a[1] & a[0])
    );

// b[1] equals conjunction of negated 3-one minterms.
    check_b1_definition: assert property (
        @(posedge CLK) b[1] == ( ~(a[3] & a[2] & a[1] & ~a[0])
                               & ~(a[3] & a[2] & ~a[1] & a[0])
                               & ~(a[3] & ~a[2] & a[1] & a[0])
                               & ~(~a[3] & a[2] & a[1] & a[0]) )
    );

// b[0] equals conjunction of negated 2-one minterms and negated 4-ones.
    check_b0_definition: assert property (
        @(posedge CLK) b[0] == ( ~(a[3] & a[2] & ~a[1] & ~a[0])
                               & ~(a[3] & ~a[2] & a[1] & ~a[0])
                               & ~(a[3] & ~a[2] & ~a[1] & a[0])
                               & ~(~a[3] & a[2] & a[1] & ~a[0])
                               & ~(~a[3] & a[2] & ~a[1] & a[0])
                               & ~(~a[3] & ~a[2] & a[1] & a[0])
                               & ~(a[3] & a[2] & a[1] & a[0]) )
    );

///// Input pattern to output mapping /////
    // For a==4'b1111, b==3'b010.
    check_all_ones_output: assert property (
        @(posedge CLK) (a[3] & a[2] & a[1] & a[0]) |-> (b == 3'b010)
    );

// For exactly three ones, b==3'b101.
    check_three_ones_output: assert property (
        @(posedge CLK)
        ( (a[3] & a[2] & a[1] & ~a[0])
        | (a[3] & a[2] & ~a[1] & a[0])
        | (a[3] & ~a[2] & a[1] & a[0])
        | (~a[3] & a[2] & a[1] & a[0]) ) |-> (b == 3'b101)
    );

///// Output-to-input consistency (only when possible) /////
    // b[2]==0 only when a==4'b1111.
    check_b2_zero_means_all_ones: assert property (
        @(posedge CLK) (b[2] == 1'b0) |-> (a[3] & a[2] & a[1] & a[0])
    );

// b[1]==0 only when exactly three ones.
    check_b1_zero_means_three_ones: assert property (
        @(posedge CLK)
        (b[1] == 1'b0) |-> ( (a[3] & a[2] & a[1] & ~a[0])
                           | (a[3] & a[2] & ~a[1] & a[0])
                           | (a[3] & ~a[2] & a[1] & a[0])
                           | (~a[3] & a[2] & a[1] & a[0]) )
    );

///// Counter behavior /////
    // When not at limit, clk_cnt increments by 1 on the next cycle.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt != 32'd50000) |=> (clk_cnt == $past(clk_cnt) + 32'd1)
    );

// When at limit, clk_cnt wraps to 0 on the next cycle.
    check_counter_wraps: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (clk_cnt == 32'd0)
    );

///// Key last-value capture at sample /////
    // At sample, left_key_last captures current left on next cycle.
    capture_left_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (left_key_last == $past(left))
    );

// At sample, right_key_last captures current right on next cycle.
    capture_right_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (right_key_last == $past(right))
    );

// At sample, up_key_last captures current up on next cycle.
    capture_up_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (up_key_last == $past(up))
    );

// At sample, down_key_last captures current down on next cycle.
    capture_down_last: assert property (
        @(posedge clk) disable iff (!rst) (clk_cnt == 32'd50000) |=> (down_key_last == $past(down))
    );

///// Direction encoding and timing /////
    // direction only takes values 0,1,2,3,4.
    check_direction_encoding: assert property (
        @(posedge clk) disable iff (!rst) direction inside {
            8'b0000_0000, 8'b0000_0001, 8'b0000_0010, 8'b0000_0011, 8'b0000_0100
        }
    );

// A non-zero direction is a one-cycle pulse (next cycle observed as zero).
    direction_one_cycle_pulse: assert property (
        @(posedge clk) disable iff (!rst) (direction != 8'b0000_0000) |=> (direction == 8'b0000_0000)
    );

// Non-zero direction implies previous cycle was a sample with at least one rising key.
    direction_implies_prior_edge: assert property (
        @(posedge clk) disable iff (!rst)
            (direction != 8'b0000_0000) |->
            ($past(clk_cnt) == 32'd50000) &&
            (
                (($past(left_key_last)  == 1'b0) && ($past(left)  == 1'b1)) ||
                (($past(right_key_last) == 1'b0) && ($past(right) == 1'b1)) ||
                (($past(up_key_last)    == 1'b0) && ($past(up)    == 1'b1)) ||
                (($past(down_key_last)  == 1'b0) && ($past(down)  == 1'b1))
            )
    );

///// Direction priority on simultaneous edges (down > up > right > left) /////
    // If down rises at sample, next observed direction is 4.
    dir_on_down_rise: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) && (down_key_last == 1'b0) && (down == 1'b1)
            |=> (direction == 8'b0000_0100)
    );

// If up rises (and down does not) at sample, next observed direction is 3.
    dir_on_up_rise_no_down: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) &&
            (up_key_last == 1'b0) && (up == 1'b1) &&
            !((down_key_last == 1'b0) && (down == 1'b1))
            |=> (direction == 8'b0000_0011)
    );

// If right rises (and up/down do not) at sample, next observed direction is 2.
    dir_on_right_rise_no_up_down: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) &&
            (right_key_last == 1'b0) && (right == 1'b1) &&
            !((up_key_last == 1'b0) && (up == 1'b1)) &&
            !((down_key_last == 1'b0) && (down == 1'b1))
            |=> (direction == 8'b0000_0010)
    );

// If left rises (and right/up/down do not) at sample, next observed direction is 1.
    dir_on_left_rise_no_others: assert property (
        @(posedge clk) disable iff (!rst)
            (clk_cnt == 32'd50000) &&
            (left_key_last == 1'b0) && (left == 1'b1) &&
            !((right_key_last == 1'b0) && (right == 1'b1)) &&
            !((up_key_last == 1'b0) && (up == 1'b1)) &&
            !((down_key_last == 1'b0) && (down == 1'b1))
            |=> (direction == 8'b0000_0001)
    );

// On C edge, if reset is high, Q must be 0 (reset dominates).
    check_reset_dominates_clocked_update: assert property (
        @(posedge C) R |-> (Q == 1'b0)
    );

// Q can be high only when not in reset.
    check_q_one_only_when_not_in_reset: assert property (
        @(posedge C) disable iff (R) (Q == 1'b1) |-> (!R)
    );

// Output equals bitwise AND of a and b.
    check_out_equals_and: assert property (
        @(posedge clk) out == (a & b)
    );

// Every 1 in out must also be 1 in a.
    check_out_subset_a: assert property (
        @(posedge clk) (out & ~a) == 32'b0
    );

// Every 1 in out must also be 1 in b.
    check_out_subset_b: assert property (
        @(posedge clk) (out & ~b) == 32'b0
    );

// If a is all zeros, out is all zeros.
    check_zero_a_implies_zero_out: assert property (
        @(posedge clk) (a == 32'b0) |-> (out == 32'b0)
    );

// If b is all zeros, out is all zeros.
    check_zero_b_implies_zero_out: assert property (
        @(posedge clk) (b == 32'b0) |-> (out == 32'b0)
    );

// If b is all ones, out equals a.
    check_b_all_ones_identity: assert property (
        @(posedge clk) (b == {32{1'b1}}) |-> (out == a)
    );

// If a is all ones, out equals b.
    check_a_all_ones_identity: assert property (
        @(posedge clk) (a == {32{1'b1}}) |-> (out == b)
    );

// If inputs are equal, out equals that value (idempotence).
    check_equal_inputs_idempotent: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// If any output bit is 1, both inputs have at least one 1.
    check_nonzero_out_implies_nonzero_inputs: assert property (
        @(posedge clk) (|out) |-> ((|a) && (|b))
    );

// When select == 2'b11, data_out must be zero.
    check_select_11_routes_zero: assert property (
        @(posedge clk) (select == 2'b11) |-> (data_out == {W{1'b0}})
    );

// When in2 is low, out must be 0
    check_out_zero_when_in2_low: assert property (
        @(posedge clk) (in2 == 1'b0) |-> (out == 1'b0)
    );

// When address is below start_address, out must be 0
    check_out_zero_when_below_range: assert property (
        @(posedge clk) (in1 < start_address) |-> (out == 1'b0)
    );

// If out is high, in2 must be high
    check_out_high_implies_in2_high: assert property (
        @(posedge clk) (out == 1'b1) |-> (in2 == 1'b1)
    );

// Analysis: Clock is clk (posedge). No reset present. Mixed logic: sequential shift_reg update on clk, q combinationally mirrors shift_reg. Behavior: on en, q shifts left with d loaded into q[0]; otherwise q holds.

    ///// Shift/hold behavior /////

    // When disabled, q holds its value across the next cycle.
    check_hold_when_disabled: assert property (
        @(posedge clk) (!en) |=> (q == $past(q))
    );

// When enabled, LSB captures d from the previous cycle.
    check_lsb_captures_d_when_enabled: assert property (
        @(posedge clk) (en) |=> (q[0] == $past(d))
    );

// When enabled, bit[1] takes previous bit[0].
    check_shift_bit1: assert property (
        @(posedge clk) (en) |=> (q[1] == $past(q[0]))
    );

// When enabled, bit[2] takes previous bit[1].
    check_shift_bit2: assert property (
        @(posedge clk) (en) |=> (q[2] == $past(q[1]))
    );

// When enabled, bit[3] takes previous bit[2].
    check_shift_bit3: assert property (
        @(posedge clk) (en) |=> (q[3] == $past(q[2]))
    );

// When enabled, bit[4] takes previous bit[3].
    check_shift_bit4: assert property (
        @(posedge clk) (en) |=> (q[4] == $past(q[3]))
    );

// When enabled, bit[5] takes previous bit[4].
    check_shift_bit5: assert property (
        @(posedge clk) (en) |=> (q[5] == $past(q[4]))
    );

// When enabled, bit[6] takes previous bit[5].
    check_shift_bit6: assert property (
        @(posedge clk) (en) |=> (q[6] == $past(q[5]))
    );

// When enabled, bit[7] takes previous bit[6].
    check_shift_bit7: assert property (
        @(posedge clk) (en) |=> (q[7] == $past(q[6]))
    );

// When enabled, the whole word shifts left with d appended (redundant but comprehensive).
    check_full_word_shift_when_enabled: assert property (
        @(posedge clk) (en) |=> (q == { $past(q[6:0]), $past(d) })
    );

///// Number region (x in 0..3) /////
    // For x<=3, is_number must be 1.
    check_is_number_when_x_le_3: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x <= 3'd3) |-> (is_number == 1'b1)
    );

// For x>3, is_number must be 0.
    check_not_number_when_x_gt_3: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x > 3'd3) |-> (is_number == 1'b0)
    );

// For x<=3, upper nibble of valor must be zero (0..15).
    check_number_val_upper_zero: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x <= 3'd3) |-> (valor[7:4] == 4'h0)
    );

// For x<=3, lower nibble encodes {visor_y, visor_x[1:0]} (y*4 + x).
    check_number_val_lower_nibble: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x <= 3'd3) |-> (valor[3:0] == {visor_y, visor_x[1:0]})
    );

///// Non-number explicit mappings for x=4,5 and y=0..2 /////
    // x=4,y=0 -> 16, non-number.
    check_x4_y0: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd4 && visor_y==2'd0) |-> (valor==8'd16 && is_number==1'b0)
    );

// x=5,y=0 -> 17, non-number.
    check_x5_y0: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd5 && visor_y==2'd0) |-> (valor==8'd17 && is_number==1'b0)
    );

// x=4,y=1 -> 18, non-number.
    check_x4_y1: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd4 && visor_y==2'd1) |-> (valor==8'd18 && is_number==1'b0)
    );

// x=5,y=1 -> 19, non-number.
    check_x5_y1: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd5 && visor_y==2'd1) |-> (valor==8'd19 && is_number==1'b0)
    );

// x=4,y=2 -> 20, non-number.
    check_x4_y2: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd4 && visor_y==2'd2) |-> (valor==8'd20 && is_number==1'b0)
    );

// x=5,y=2 -> 21, non-number.
    check_x5_y2: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd5 && visor_y==2'd2) |-> (valor==8'd21 && is_number==1'b0)
    );

///// Edge rows and defaults /////
    // x=4,y=3 -> 22, non-number.
    check_x4_y3: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd4 && visor_y==2'd3) |-> (valor==8'd22 && is_number==1'b0)
    );

// x=5,y=3 -> default 28, non-number.
    check_x5_y3_default: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x==3'd5 && visor_y==2'd3) |-> (valor==8'd28 && is_number==1'b0)
    );

// For x>=6, default 28, non-number (all y).
    check_x_ge_6_default: assert property (
        @(posedge clk) disable iff (1'b0) (visor_x >= 3'd6) |-> (valor==8'd28 && is_number==1'b0)
    );

// O selects A when I == 4'b0000.
    select_A_when_I_0000: assert property (
        @(posedge CLK) (I == 4'b0000) |-> (O == A)
    );

// O selects B when I == 4'b0001.
    select_B_when_I_0001: assert property (
        @(posedge CLK) (I == 4'b0001) |-> (O == B)
    );

// O selects C when I == 4'b0010.
    select_C_when_I_0010: assert property (
        @(posedge CLK) (I == 4'b0010) |-> (O == C)
    );

// O selects D when I == 4'b0011.
    select_D_when_I_0011: assert property (
        @(posedge CLK) (I == 4'b0011) |-> (O == D)
    );

// O selects E when I == 4'b0100.
    select_E_when_I_0100: assert property (
        @(posedge CLK) (I == 4'b0100) |-> (O == E)
    );

// O drives zero for all other I values (4'b0101 through 4'b1111).
    default_zero_for_other_I: assert property (
        @(posedge CLK) (I inside {[4'h5:4'hF]}) |-> (O == 12'b0)
    );

// O equals the full case expression result for all I values.
    full_mux_behavior: assert property (
        @(posedge CLK)
            O == ((I == 4'h0) ? A :
                  (I == 4'h1) ? B :
                  (I == 4'h2) ? C :
                  (I == 4'h3) ? D :
                  (I == 4'h4) ? E : 12'b0)
    );

// Clock: none in DUT; Reset: none in DUT; Logic: combinational; Behavior: cw_from_mux = cw_from_cu & mux_op.

    // Output equals input masked by mux_op (vector check).
    check_mask_vector: assert property (
        @(posedge clk) cw_from_mux == (cw_from_cu & {23{mux_op}})
    );

// When mux_op is 0, output is all zeros.
    check_zero_when_disabled: assert property (
        @(posedge clk) (mux_op == 1'b0) |-> (cw_from_mux == 23'b0)
    );

// When mux_op is 1, output equals input.
    check_pass_through_when_enabled: assert property (
        @(posedge clk) (mux_op == 1'b1) |-> (cw_from_mux == cw_from_cu)
    );

// Output has no 1s where input has 0s (subset relationship).
    check_output_subset_of_input: assert property (
        @(posedge clk) ((cw_from_mux & ~cw_from_cu) == 23'b0)
    );

// If the input bus is all zeros, output must be zero for any mux_op.
    check_zero_when_input_zero: assert property (
        @(posedge clk) (cw_from_cu == 23'b0) |-> (cw_from_mux == 23'b0)
    );

// X equals A OR NOT B_N.
    check_function_equivalence: assert property (
        @(posedge CLK) X == (A | ~B_N)
    );

// When B_N is 1, X equals A.
    check_bn1_implies_x_eq_a: assert property (
        @(posedge CLK) (B_N == 1'b1) |-> (X == A)
    );

// When B_N is 0, X is 1.
    check_bn0_forces_x_high: assert property (
        @(posedge CLK) (B_N == 1'b0) |-> (X == 1'b1)
    );

// When A is 1, X is 1.
    check_a1_forces_x_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

// When A is 0 and B_N is 1, X is 0.
    check_a0_bn1_forces_x_low: assert property (
        @(posedge CLK) ((A == 1'b0) && (B_N == 1'b1)) |-> (X == 1'b0)
    );

///// Functional correctness against the RTL computation /////
    // a_prim must equal a1_e = (a + b) + rol12(b ^ (c + rol16(d ^ (a + b)))).
    check_a_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) a_prim == a1_e
    );

// b_prim must equal b3_e = rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c1_e ).
    check_b_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) b_prim == b3_e
    );

// c_prim must equal c1_e = (c + rol16(d ^ (a + b))) + d_prim.
    check_c_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) c_prim == c1_e
    );

// d_prim must equal d3_e = rol8( rol16(d ^ (a + b)) ^ a_prim ).
    check_d_prim_matches_reference: assert property (
        @(posedge CLK) disable iff (!RESETn) d_prim == d3_e
    );

///// Closed-form relations directly from inputs /////
    // a_prim equals (a + b) + rol12(b ^ (c + rol16(d ^ (a + b)))).
    check_a_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            a_prim == (a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))
    );

// d_prim equals rol8( rol16(d ^ (a + b)) ^ ((a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))) ).
    check_d_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            d_prim == rol8( rol16(d ^ (a + b)) ^ ((a + b) + rol12(b ^ (c + rol16(d ^ (a + b))))) )
    );

// c_prim equals (c + rol16(d ^ (a + b))) + d_prim.
    check_c_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            c_prim == (c + rol16(d ^ (a + b))) + d_prim
    );

// b_prim equals rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c_prim ).
    check_b_prim_closed_form: assert property (
        @(posedge CLK) disable iff (!RESETn)
            b_prim == rol7( rol12(b ^ (c + rol16(d ^ (a + b)))) ^ c_prim )
    );

///// Reset behavior /////
    // When reset is asserted, count must be 0 in that cycle.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// While reset is held across consecutive cycles, count remains stable (stays 0).
    check_stable_during_held_reset: assert property (
        @(posedge clk) reset && $past(reset) |-> $stable(count)
    );

///// Functional equivalence checks /////
    // out_and equals bitwise AND of all inputs.
    spec_out_and_def: assert property (
        @(posedge clk) out_and == (((in1 & in2) & in3) & in4)
    );

// out_or equals bitwise OR of all inputs.
    spec_out_or_def: assert property (
        @(posedge clk) out_or == (((in1 | in2) | in3) | in4)
    );

// out_xor equals bitwise XOR of all inputs.
    spec_out_xor_def: assert property (
        @(posedge clk) out_xor == (((in1 ^ in2) ^ in3) ^ in4)
    );

///// AND result subset relations /////
    // out_and cannot have 1s where in1 has 0s.
    check_and_subset_in1: assert property (
        @(posedge clk) (out_and & ~in1) == 4'b0000
    );

// out_and cannot have 1s where in2 has 0s.
    check_and_subset_in2: assert property (
        @(posedge clk) (out_and & ~in2) == 4'b0000
    );

// out_and cannot have 1s where in3 has 0s.
    check_and_subset_in3: assert property (
        @(posedge clk) (out_and & ~in3) == 4'b0000
    );

// out_and cannot have 1s where in4 has 0s.
    check_and_subset_in4: assert property (
        @(posedge clk) (out_and & ~in4) == 4'b0000
    );

///// OR result superset relations /////
    // out_or must have 1s wherever in1 has 1s.
    check_or_superset_in1: assert property (
        @(posedge clk) (in1 & ~out_or) == 4'b0000
    );

// out_or must have 1s wherever in2 has 1s.
    check_or_superset_in2: assert property (
        @(posedge clk) (in2 & ~out_or) == 4'b0000
    );

// out_or must have 1s wherever in3 has 1s.
    check_or_superset_in3: assert property (
        @(posedge clk) (in3 & ~out_or) == 4'b0000
    );

// out_or must have 1s wherever in4 has 1s.
    check_or_superset_in4: assert property (
        @(posedge clk) (in4 & ~out_or) == 4'b0000
    );

///// Cross-output relation /////
    // AND result is always a subset of OR result.
    check_and_implies_or: assert property (
        @(posedge clk) (out_and & ~out_or) == 4'b0000
    );

///// Next-state combinational mapping /////
  // For STATE_U: 0->Z, 1->W.
  map_next_from_U: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_U) |-> (o_next_state == (i_input ? STATE_W : STATE_Z))
  );

// For STATE_V: 0->Z, 1->W.
  map_next_from_V: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_V) |-> (o_next_state == (i_input ? STATE_W : STATE_Z))
  );

// For STATE_W: 0->X, 1->U.
  map_next_from_W: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_W) |-> (o_next_state == (i_input ? STATE_U : STATE_X))
  );

// For STATE_X: 0->Y, 1->X (self-loop on 1).
  map_next_from_X: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_X) |-> (o_next_state == (i_input ? STATE_X : STATE_Y))
  );

// For STATE_Y: 0->V, 1->Y (self-loop on 1).
  map_next_from_Y: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_Y) |-> (o_next_state == (i_input ? STATE_Y : STATE_V))
  );

// For STATE_Z: 0->Y, 1->X.
  map_next_from_Z: assert property (
    @(posedge clk) disable iff (rst) (o_current_state == STATE_Z) |-> (o_next_state == (i_input ? STATE_X : STATE_Y))
  );

// For invalid states (110/111): default goes to STATE_U.
  map_next_from_invalid_to_U: assert property (
    @(posedge clk) disable iff (rst) (o_current_state inside {3'b110,3'b111}) |-> (o_next_state == STATE_U)
  );

// next_state is always one of the defined encodings.
  check_next_state_legal: assert property (
    @(posedge clk) disable iff (rst) (o_next_state inside {STATE_U,STATE_V,STATE_W,STATE_X,STATE_Y,STATE_Z})
  );

///// Moore output mapping /////
  // For U/Y/Z, output must be 1.
  check_output_high_states: assert property (
    @(posedge clk) disable iff (rst) (o_current_state inside {STATE_U,STATE_Y,STATE_Z}) |-> (o_output == 1'b1)
  );

// For V/W/X, output must be 0.
  check_output_low_states: assert property (
    @(posedge clk) disable iff (rst) (o_current_state inside {STATE_V,STATE_W,STATE_X}) |-> (o_output == 1'b0)
  );

///// Reset behavior /////
  // After a rising reset, current_state must be STATE_U by the next clock edge.
  reset_sets_state_U_next_cycle: assert property (
    @(posedge clk) $rose(rst) |-> ##1 (o_current_state == STATE_U)
  );

///// Functional correctness /////
    // Output equals bitwise AND of inputs.
    check_and_functionality: assert property (
        @(posedge clk) c === (a & b)
    );

// Commutativity of AND reflected at output.
    check_commutativity: assert property (
        @(posedge clk) c === (b & a)
    );

///// Bit-level correctness /////
    // Bit 0 equals a[0] AND b[0].
    check_bit0: assert property (
        @(posedge clk) c[0] === (a[0] & b[0])
    );

// Bit 1 equals a[1] AND b[1].
    check_bit1: assert property (
        @(posedge clk) c[1] === (a[1] & b[1])
    );

///// Identity and annihilator properties /////
    // When a is all ones, c mirrors b.
    check_identity_a_all_ones: assert property (
        @(posedge clk) (a == 2'b11) |-> (c === b)
    );

// When b is all ones, c mirrors a.
    check_identity_b_all_ones: assert property (
        @(posedge clk) (b == 2'b11) |-> (c === a)
    );

// When a is all zeros, c is zero.
    check_annihilator_a_all_zeros: assert property (
        @(posedge clk) (a == 2'b00) |-> (c === 2'b00)
    );

// When b is all zeros, c is zero.
    check_annihilator_b_all_zeros: assert property (
        @(posedge clk) (b == 2'b00) |-> (c === 2'b00)
    );

///// Subset properties /////
    // Output ones are a subset of a's ones.
    check_output_subset_of_a: assert property (
        @(posedge clk) ((c & ~a) === 2'b00)
    );

// Output ones are a subset of b's ones.
    check_output_subset_of_b: assert property (
        @(posedge clk) ((c & ~b) === 2'b00)
    );

///// Synchronous control behavior /////
    // When RN is asserted at a clock edge, Q must be 0 on the next cycle.
    check_sync_reset_drives_q0: assert property (
        @(posedge CK) RN |=> (Q == 1'b0)
    );

// When SN is asserted (and RN is not), Q must be 1 on the next cycle.
    check_sync_set_drives_q1: assert property (
        @(posedge CK) disable iff (RN) SN |=> (Q == 1'b1)
    );

// When neither RN nor SN is asserted, Q captures D on the next cycle.
    check_data_capture_when_no_ctrl: assert property (
        @(posedge CK) disable iff (RN) (!SN) |=> (Q == $past(D))
    );

// RN has priority over SN when both are asserted; Q must be 0 next cycle.
    check_reset_priority_over_set: assert property (
        @(posedge CK) (RN && SN) |=> (Q == 1'b0)
    );

///// Complementary output /////
    // QN is always the bitwise complement of Q.
    check_qn_complements_q: assert property (
        @(posedge CK) (QN == ~Q)
    );

// When neither RN nor SN is asserted, QN next equals inversion of current D.
    check_qn_reflects_d_on_data_capture: assert property (
        @(posedge CK) disable iff (RN) (!SN) |=> (QN == ~$past(D))
    );

// When SN is asserted (and RN is not), QN must be 0 on the next cycle.
    check_qn_zero_on_set: assert property (
        @(posedge CK) disable iff (RN) SN |=> (QN == 1'b0)
    );

// When RN is asserted, QN must be 1 on the next cycle.
    check_qn_one_on_reset: assert property (
        @(posedge CK) RN |=> (QN == 1'b1)
    );

///// Reset behavior /////
    // Synchronous active-HIGH reset clears all internal state.
    reset_clears_state: assert property (
        @(posedge clk) rst |-> (tone_counter == 32'd0) && (tone_duration == 32'd0) &&
                           (sample_counter == 32'd0) && (sample_period == 32'd0) &&
                           (tone_type == 2'b00)
    );

// During reset, audio_out is LOW (tone_counter is 0 and threshold > 0).
    reset_audio_low: assert property (
        @(posedge clk) rst |-> (audio_out == 1'b0)
    );

///// Reset behavior /////
    // When RST is asserted, Q must be 0 on the next clock.
    reset_forces_zero_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'h0)
    );

///// Counting behavior (disabled during reset) /////
    // When not at max, Q increments by 1 on the next clock.
    count_increments_when_not_max: assert property (
        @(posedge CLK) disable iff (RST) (Q != 4'hF) |=> (Q == $past(Q) + 1'b1)
    );

// When at max, Q wraps to 0 on the next clock.
    count_wraps_when_max: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

// LSB toggles every cycle when not in reset.
    lsb_toggles_without_reset: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> (Q[0] == ~$past(Q[0]))
    );

// QN equals (IN1&IN2) OR (IN3&IN4).
    check_qn_function: assert property (
        @(posedge clk) QN == ((IN1 & IN2) | (IN3 & IN4))
    );

// If IN1 and IN2 are HIGH, QN must be HIGH.
    check_pair12_implies_high: assert property (
        @(posedge clk) (IN1 && IN2) |-> QN
    );

// If IN3 and IN4 are HIGH, QN must be HIGH.
    check_pair34_implies_high: assert property (
        @(posedge clk) (IN3 && IN4) |-> QN
    );

// If neither pair is both HIGH, QN must be LOW.
    check_both_pairs_not_high_implies_low: assert property (
        @(posedge clk) (!(IN1 && IN2) && !(IN3 && IN4)) |-> !QN
    );

// If QN is LOW, neither pair can be both HIGH.
    check_low_implies_no_pair_high: assert property (
        @(posedge clk) !QN |-> (!(IN1 && IN2) && !(IN3 && IN4))
    );

// If QN is HIGH, at least one pair is both HIGH.
    check_high_implies_some_pair_high: assert property (
        @(posedge clk) QN |-> ((IN1 && IN2) || (IN3 && IN4))
    );

// If all inputs are LOW, QN must be LOW.
    check_all_zero_implies_low: assert property (
        @(posedge clk) (!IN1 && !IN2 && !IN3 && !IN4) |-> !QN
    );

// On A rising edge, Y must equal the mux function.
    check_func_on_A_rise: assert property (
        @(posedge A) Y == (SEL ? B : A)
    );

// On A falling edge, Y must equal the mux function.
    check_func_on_A_fall: assert property (
        @(negedge A) Y == (SEL ? B : A)
    );

// On B rising edge, Y must equal the mux function.
    check_func_on_B_rise: assert property (
        @(posedge B) Y == (SEL ? B : A)
    );

// On B falling edge, Y must equal the mux function.
    check_func_on_B_fall: assert property (
        @(negedge B) Y == (SEL ? B : A)
    );

// On SEL rising edge, Y must equal the mux function (select B).
    check_func_on_SEL_rise: assert property (
        @(posedge SEL) Y == (SEL ? B : A)
    );

// On SEL falling edge, Y must equal the mux function (select A).
    check_func_on_SEL_fall: assert property (
        @(negedge SEL) Y == (SEL ? B : A)
    );

///// Functional correctness /////
    // Combined {cout,sum} equals arithmetic a + b + cin (5-bit).
    check_addition_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// LSB sum matches XOR of a[0], b[0], and cin.
    check_sum_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// When inputs are all zero, outputs are zero.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) (a == 4'b0 && b == 4'b0 && cin == 1'b0) |-> (sum == 4'b0 && cout == 1'b0)
    );

// Adding zero on b with cin=0 returns a and no carry.
    check_identity_b_zero_cin_zero: assert property (
        @(posedge clk) (b == 4'b0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero on a with cin=0 returns b and no carry.
    check_identity_a_zero_cin_zero: assert property (
        @(posedge clk) (a == 4'b0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// With b==0, result equals a + cin (proper 5-bit sum).
    check_b_zero_add_cin: assert property (
        @(posedge clk) (b == 4'b0) |-> ({cout, sum} == ({1'b0, a} + cin))
    );

///// Corner cases /////
    // Max operands with cin=0 produce sum=14 and carry=1.
    check_max_plus_zero: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b0) |-> (sum == 4'he && cout == 1'b1)
    );

// Max operands with cin=1 produce sum=15 and carry=1.
    check_max_plus_one: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (sum == 4'hf && cout == 1'b1)
    );

// When a[0]==b[0], LSB of sum equals cin.
    check_lsb_when_a0_eq_b0: assert property (
        @(posedge clk) (a[0] == b[0]) |-> (sum[0] == cin)
    );

// branch_ISR low implies ISR_adr is zero.
    check_branch_zero_implies_zero_addr: assert property (
        @(posedge clock) (branch_ISR == 1'b0) |-> (ISR_adr == 12'h000)
    );

///// Combinational output range /////
    // Q is the 5-bit sum of two 4-bit counters; it can never exceed 30.
    check_q_within_valid_range: assert property (
        @(posedge CLK) disable iff (RST) (Q <= 5'd30)
    );

///// Reset and clear interactions (synchronous, active-high) /////
    // If both RST and CLR are HIGH in a cycle, Q must be 0 in the next cycle.
    check_both_resets_force_zero_next: assert property (
        @(posedge CLK) (RST && CLR) |=> (Q == 5'd0)
    );

// If RST is HIGH and CLR is LOW and LD is HIGH, Q loads DATA next cycle.
    check_rst_and_ld_loads_data_next: assert property (
        @(posedge CLK) (RST && !CLR && LD) |=> (Q == $past(DATA))
    );

// If RST is HIGH and CLR is LOW (LD don't care), Q is in 0..15 next cycle.
    check_rst_without_clr_bounds_next: assert property (
        @(posedge CLK) (RST && !CLR) |=> (Q <= 5'd15)
    );

// If CLR is HIGH (regardless of LD), Q is in 0..15 next cycle (RST not asserted).
    check_clr_bounds_next: assert property (
        @(posedge CLK) disable iff (RST) (CLR) |=> (Q <= 5'd15)
    );

// When RST and CLR and LD are all HIGH together, Q still goes to 0 next cycle (CLR priority over LD and RST forces binary_counter to 0).
    check_ld_ignored_when_both_resets: assert property (
        @(posedge CLK) (RST && CLR && LD) |=> (Q == 5'd0)
    );

///// Free-running behavior when no controls are asserted /////
    // With no RST/CLR/LD and Q <= 14, both 4-bit counters increment without wrap so Q increases by 2 next cycle.
    check_increment_by_two_when_small: assert property (
        @(posedge CLK) disable iff (RST)
            (!RST && !CLR && !LD && (Q <= 5'd14)) |=> (Q == ($past(Q) + 5'd2))
    );

// With two consecutive cycles of no RST/CLR/LD and Q <= 13 at the first, Q increases by 4 after two cycles (no wrap in either counter).
    check_two_cycle_increment_when_small: assert property (
        @(posedge CLK) disable iff (RST)
            ((!RST && !CLR && !LD && (Q <= 5'd13)) ##1 (!RST && !CLR && !LD)) |=> (Q == ($past(Q, 2) + 5'd4))
    );

///// Persistence under sustained resets /////
    // If both RST and CLR hold HIGH for two consecutive cycles, Q remains 0 one cycle later as well.
    check_zero_persists_while_both_resets_hold: assert property (
        @(posedge CLK) ((RST && CLR) ##1 (RST && CLR)) |=> (Q == 5'd0)
    );

///// Reset behavior /////
    // When reset is asserted at the clock edge, gray must be all zeros.
    reset_forces_gray_zero: assert property (
        @(posedge clk) reset |-> (gray == 8'b0)
    );

// Result matches selected add/sub operation.
    check_result_muxed_operation: assert property (
        @(posedge CLK) disable iff (!RESETn) result == (sel ? (a - b) : (a + b))
    );

// When sel=0, result equals a+b.
    check_add_result: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel) |-> (result == (a + b))
    );

// When sel=1, result equals a-b.
    check_sub_result: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel) |-> (result == (a - b))
    );

// For sel=0, commutativity holds: result == b+a.
    check_add_commutative: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel) |-> (result == (b + a))
    );

// For sel=1, inverse identity: (result + b) == a (mod 256).
    check_sub_inverse_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel) |-> ((result + b) == a)
    );

// For sel=0, inverse identity: (result - b) == a (mod 256).
    check_add_inverse_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel) |-> ((result - b) == a)
    );

// If b==0, result equals a for both operations.
    check_b_zero_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (b == 8'h00) |-> (result == a)
    );

// If sel=0 and a==0, result equals b.
    check_a_zero_add_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!sel && (a == 8'h00)) |-> (result == b)
    );

// If sel=1 and a==0, result equals (0 - b) (two's complement).
    check_a_zero_sub_identity: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel && (a == 8'h00)) |-> (result == (8'h00 - b))
    );

// LSB sum equals XOR of A[0], B[0], and Ci.
    bit0_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Carry from bit1 equals (A1&B1) | (CTMP1&(A1^B1)).
    bit1_carry2_is_formula: assert property (
        @(posedge CLK) disable iff (!RESETn) CTMP[2] == ((A[1] & B[1]) | (CTMP[1] & (A[1] ^ B[1])))
    );

// Bit2 sum equals XOR of A[2], B[2], and CTMP[2].
    bit2_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S[2] == (A[2] ^ B[2] ^ CTMP[2])
    );

// Carry from bit2 equals (A2&B2) | (CTMP2&(A2^B2)).
    bit2_carry3_is_formula: assert property (
        @(posedge CLK) disable iff (!RESETn) CTMP[3] == ((A[2] & B[2]) | (CTMP[2] & (A[2] ^ B[2])))
    );

// Bit3 sum equals XOR of A[3], B[3], and CTMP[3].
    bit3_sum_is_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) S[3] == (A[3] ^ B[3] ^ CTMP[3])
    );

// Next-cycle ENCLK equals prior TE when prior EN=1, else holds prior ENCLK.
    check_next_value_mux: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == ($past(EN) ? $past(TE) : $past(ENCLK)))
    );

// When EN is high, ENCLK updates next cycle to prior TE.
    check_update_on_en_high: assert property (
        @(posedge CLK) EN |=> (ENCLK == $past(TE))
    );

// When EN is low, ENCLK holds its previous value next cycle.
    check_hold_when_en_low: assert property (
        @(posedge CLK) !EN |=> (ENCLK == $past(ENCLK))
    );

// While reset is HIGH, outputs must be zero.
  reset_outputs_zero: assert property (
    @(posedge clk) reset |-> (count == 3'b000) && (flag == 1'b0)
  );

// When disabled, count and flag hold their values.
  hold_when_disabled: assert property (
    @(posedge clk) disable iff (reset) (!ena) |=> (count == $past(count)) && (flag == $past(flag))
  );

// When enabled and not at max, count increments and flag clears next cycle.
  increment_when_enabled: assert property (
    @(posedge clk) disable iff (reset) (ena && (count != 3'b111)) |=> (count == $past(count) + 3'b001) && (flag == 1'b0)
  );

// When enabled and at max, wrap to zero and set flag next cycle.
  wrap_and_set_flag: assert property (
    @(posedge clk) disable iff (reset) (ena && (count == 3'b111)) |=> (count == 3'b000) && (flag == 1'b1)
  );

// Flag high implies count is zero in the same cycle.
  flag_implies_count_zero: assert property (
    @(posedge clk) disable iff (reset) flag |-> (count == 3'b000)
  );

// Flag can only rise after an enabled wrap from 7.
  flag_rise_on_wrap_only: assert property (
    @(posedge clk) disable iff (reset) $rose(flag) |-> ($past(ena) && ($past(count) == 3'b111))
  );

// First enabled cycle after wrap (count=0, flag=1) clears flag and sets count to 1.
  clear_flag_on_enable_from_zero: assert property (
    @(posedge clk) disable iff (reset) (ena && (count == 3'b000) && (flag == 1'b1)) |=> (count == 3'b001) && (flag == 1'b0)
  );

// When enabled, count must change on the next cycle (increment or wrap).
  enabled_step_changes_count: assert property (
    @(posedge clk) disable iff (reset) ena |=> (count != $past(count))
  );

// Clock: CLK_N (posedge). Reset: RESET_B active-low. Logic: combinational priority mux.

    // SCD high forces Q to 1.
    check_scd_forces_one: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) SCD |-> (Q == 1'b1)
    );

// SCD has priority over SCE when both are high.
    check_scd_over_sce: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (SCD && SCE) |-> (Q == 1'b1)
    );

// With SCD low, SCE high forces Q to 0.
    check_sce_forces_zero_when_scd0: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (!SCD && SCE) |-> (Q == 1'b0)
    );

// When SCD=0, SCE=0, and RESET_B=1, Q follows D.
    check_default_path_follows_D: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (!SCD && !SCE && (RESET_B == 1'b1)) |-> (Q == D)
    );

// When SCD=0 and SCE=0 during reset, Q is 0.
    check_reset_clears_when_unselected: assert property (
        @(posedge CLK_N) (!RESET_B && !SCD && !SCE) |-> (Q == 1'b0)
    );

// With SCD=0, SCE=1 during reset, Q remains 0 (SCE priority over reset default path).
    check_sce_priority_over_reset: assert property (
        @(posedge CLK_N) (!RESET_B && !SCD && SCE) |-> (Q == 1'b0)
    );

// During reset, SCD still forces Q to 1.
    check_scd_overrides_reset: assert property (
        @(posedge CLK_N) (!RESET_B && SCD) |-> (Q == 1'b1)
    );

// With SCD=1, SCE=1, and reset asserted, Q is 1 (SCD wins).
    check_all_high_scd_wins: assert property (
        @(posedge CLK_N) (!RESET_B && SCD && SCE) |-> (Q == 1'b1)
    );

// Out[0] must be 1 when input >= 5.
    check_out0_high_when_ge5: assert property (
        @(posedge clk) (binary_in >= 4'd5) |-> (binary_out[0] == 1'b1)
    );

// Out[0] must be 0 when input < 5.
    check_out0_low_when_lt5: assert property (
        @(posedge clk) (binary_in < 4'd5) |-> (binary_out[0] == 1'b0)
    );

// Out[0] == 1 implies input >= 5.
    check_out0_implies_ge5: assert property (
        @(posedge clk) (binary_out[0] == 1'b1) |-> (binary_in >= 4'd5)
    );

// Out[0] == 0 implies input < 5.
    check_out0_zero_implies_lt5: assert property (
        @(posedge clk) (binary_out[0] == 1'b0) |-> (binary_in < 4'd5)
    );

// Out[1] must be 1 when LSB of input is 1.
    check_out1_high_when_odd: assert property (
        @(posedge clk) (binary_in[0] == 1'b1) |-> (binary_out[1] == 1'b1)
    );

// Out[1] must be 0 when LSB of input is 0.
    check_out1_low_when_even: assert property (
        @(posedge clk) (binary_in[0] == 1'b0) |-> (binary_out[1] == 1'b0)
    );

// Out[1] == 1 implies LSB of input is 1.
    check_out1_implies_lsb1: assert property (
        @(posedge clk) (binary_out[1] == 1'b1) |-> (binary_in[0] == 1'b1)
    );

// Out[1] == 0 implies LSB of input is 0.
    check_out1_zero_implies_lsb0: assert property (
        @(posedge clk) (binary_out[1] == 1'b0) |-> (binary_in[0] == 1'b0)
    );

///// Gate-level structure checks /////
    // gate1: temp1 is NAND of a and b.
    check_gate1_is_nand: assert property (
        @(posedge clk) disable iff (1'b0) temp1 == ~(a & b)
    );

// gate2: temp2 is NAND of temp1 and c.
    check_gate2_is_nand: assert property (
        @(posedge clk) disable iff (1'b0) temp2 == ~(temp1 & c)
    );

// gate3: temp3 is NAND of temp2 and d.
    check_gate3_is_nand: assert property (
        @(posedge clk) disable iff (1'b0) temp3 == ~(temp2 & d)
    );

// gate4: out is inversion of temp3 (NAND of a signal with itself).
    check_gate4_is_inv: assert property (
        @(posedge clk) disable iff (1'b0) out == ~temp3
    );

///// Functional equivalence /////
    // out equals d & ((a & b) | ~c).
    check_function_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) out == (d & ((a & b) | ~c))
    );

///// Useful implications derived from the logic /////
    // If d is LOW then out must be LOW.
    check_d_low_forces_out_low: assert property (
        @(posedge clk) disable iff (1'b0) (d == 1'b0) |-> (out == 1'b0)
    );

// If c is LOW then out equals d.
    check_c_low_passes_d: assert property (
        @(posedge clk) disable iff (1'b0) (c == 1'b0) |-> (out == d)
    );

// If a and b are both HIGH then out equals d.
    check_ab_high_passes_d: assert property (
        @(posedge clk) disable iff (1'b0) (a && b) |-> (out == d)
    );

// If c is HIGH and (a & b) is LOW then out is LOW.
    check_c_high_and_ab_low_out_low: assert property (
        @(posedge clk) disable iff (1'b0) (c && !(a && b)) |-> (out == 1'b0)
    );

// If c and d are HIGH then out equals a & b.
    check_cd_high_out_equals_ab: assert property (
        @(posedge clk) disable iff (1'b0) (c && d) |-> (out == (a & b))
    );

///// Reset behavior /////
    // When reset is asserted at the clock edge, q is driven to 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (q == 4'b0000)
    );

// If reset is asserted in consecutive cycles, q stays 0 across both cycles.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'b0000 && $past(q) == 4'b0000)
    );

// If reset is high now, next cycle q is 0 if reset stays high, else 1.
    check_next_cycle_after_reset: assert property (
        @(posedge clk) reset |=> (reset ? (q == 4'b0000) : (q == 4'b0001))
    );

///// Sanity /////
    // q is never X/Z when not in reset.
    check_q_known_out_of_reset: assert property (
        @(posedge clk) disable iff (reset) !$isunknown(q)
    );

// Clock: clk posedge. Reset: rst active-high, asynchronous. Sequential 2-FF sync; sync_x is the second flop.

    // When reset is seen HIGH at a clock edge, sync_x is LOW on the next clock.
    check_sync_clears_one_cycle_after_reset_seen: assert property (
        @(posedge clk) rst |=> (sync_x == 1'b0)
    );

// While reset is held HIGH across consecutive clocks, sync_x must be LOW.
    check_sync_low_while_reset_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (sync_x == 1'b0)
    );

// Immediately after reset deasserts at a clock edge, sync_x remains LOW.
    check_sync_low_on_reset_fall: assert property (
        @(posedge clk) $fell(rst) |-> (sync_x == 1'b0)
    );

// If reset was HIGH in the previous cycle, sync_x must be LOW now.
    check_sync_low_if_prev_reset: assert property (
        @(posedge clk) $past(rst) |-> (sync_x == 1'b0)
    );

// Changes on x during held reset cannot affect sync_x; it stays LOW.
    check_input_ignored_during_reset: assert property (
        @(posedge clk) (rst && $past(rst) && (x != $past(x))) |-> (sync_x == 1'b0)
    );

///// Reset behavior /////
    // Synchronous reset drives count_out to zero on the next clock.
    reset_clears_count: assert property (
        @(posedge clk) reset |=> (count_out == 4'b0000)
    );

///// Load behavior /////
    // When load is asserted (no reset), next count_out equals data_in.
    load_updates_count: assert property (
        @(posedge clk) disable iff (reset) load |=> (count_out == $past(data_in))
    );

// Load has priority over up/down counting when both are asserted.
    load_overrides_updown: assert property (
        @(posedge clk) disable iff (reset) (load && up_down) |=> (count_out == $past(data_in))
    );

///// Counting behavior /////
    // When counting up (load=0, up_down=1), next count_out = previous + 1 (mod 16).
    count_up_when_up_down: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count_out == ($past(count_out) + 4'd1))
    );

// When counting down (load=0, up_down=0), next count_out = previous - 1 (mod 16).
    count_down_when_not_up_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count_out == ($past(count_out) - 4'd1))
    );

///// Wrap-around behavior /////
    // Up-count wraps from 15 to 0.
    wrap_on_increment_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// Down-count wraps from 0 to 15.
    wrap_on_decrement_from_min: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (count_out == 4'h0)) |=> (count_out == 4'hF)
    );

// EQ must reflect whether A equals B.
    check_eq_definition: assert property (
        @(posedge clk) (EQ == (A == B))
    );

// When EQ is HIGH, A must equal B.
    check_eq_high_implies_equal: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// When EQ is LOW, A must not equal B.
    check_eq_low_implies_unequal: assert property (
        @(posedge clk) !EQ |-> (A != B)
    );

// out_wire implements XOR of a and b
    check_out_equals_xor: assert property (
        @(posedge CLK) out_wire == (a ^ b)
    );

// When a equals b, out_wire is 0 (XOR truth table)
    check_out_zero_when_equal: assert property (
        @(posedge CLK) (a == b) |-> (out_wire == 1'b0)
    );

// When a differs from b, out_wire is 1 (XOR truth table)
    check_out_one_when_unequal: assert property (
        @(posedge CLK) (a != b) |-> (out_wire == 1'b1)
    );

///// NOR function checks /////
    // y must equal NOR of a and b.
    check_y_is_nor: assert property (
        @(posedge clk) y == ~(a | b)
    );

// If a is 1, y must be 0.
    check_y_zero_if_a_one: assert property (
        @(posedge clk) (a == 1'b1) |-> (y == 1'b0)
    );

// If b is 1, y must be 0.
    check_y_zero_if_b_one: assert property (
        @(posedge clk) (b == 1'b1) |-> (y == 1'b0)
    );

// If both a and b are 0, y must be 1.
    check_y_one_if_both_zero: assert property (
        @(posedge clk) (a == 1'b0 && b == 1'b0) |-> (y == 1'b1)
    );

// If y is 1, both inputs must be 0.
    check_inputs_zero_if_y_one: assert property (
        @(posedge clk) (y == 1'b1) |-> (a == 1'b0 && b == 1'b0)
    );

// If y is 0, at least one input must be 1.
    check_some_input_one_if_y_zero: assert property (
        @(posedge clk) (y == 1'b0) |-> (a == 1'b1 || b == 1'b1)
    );

// module_1: out equals a+b+c+d (8-bit modulo)
    check_sum_out_is_sum: assert property (
        @(posedge CLK) sum_out == (a + b + c + d)
    );

// module_2: out equals in
    check_max_equals_sum_out: assert property (
        @(posedge CLK) max == sum_out
    );

// top_module: max equals a+b+c+d (composition correctness)
    check_max_matches_sum_expr: assert property (
        @(posedge CLK) max == (a + b + c + d)
    );

// All-zero inputs yield zero outputs
    zero_inputs_yield_zero_outputs: assert property (
        @(posedge CLK) (a == 8'h00 && b == 8'h00 && c == 8'h00 && d == 8'h00) |-> (sum_out == 8'h00 && max == 8'h00)
    );

// When ctrl[8:6]==000, td_mode must be 0000.
    check_map_000: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b000) |-> (td_mode == 4'b0000)
    );

// When ctrl[8:6]==001, td_mode must be 1000.
    check_map_001: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b001) |-> (td_mode == 4'b1000)
    );

// When ctrl[8:6]==010, td_mode must be 0100.
    check_map_010: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b010) |-> (td_mode == 4'b0100)
    );

// When ctrl[8:6]==011, td_mode must be 1100.
    check_map_011: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b011) |-> (td_mode == 4'b1100)
    );

// When ctrl[8:6]==100, td_mode must be 0010.
    check_map_100: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b100) |-> (td_mode == 4'b0010)
    );

// When ctrl[8:6]==101, td_mode must be 1010.
    check_map_101: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b101) |-> (td_mode == 4'b1010)
    );

// When ctrl[8:6]==110, td_mode must be 0101.
    check_map_110: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b110) |-> (td_mode == 4'b0101)
    );

// When ctrl[8:6]==111, td_mode must be 1111.
    check_map_111: assert property (
        @(posedge clk) (ctrl[8:6] == 3'b111) |-> (td_mode == 4'b1111)
    );

// td_mode[3] equals ctrl[6] for all encodings.
    check_bit3_matches_ctrl6: assert property (
        @(posedge clk) td_mode[3] == ctrl[6]
    );

// td_mode[2] equals ctrl[7] for all encodings.
    check_bit2_matches_ctrl7: assert property (
        @(posedge clk) td_mode[2] == ctrl[7]
    );

// td_mode[1] equals ctrl[8] & (~ctrl[7] | ctrl[6]).
    check_bit1_function: assert property (
        @(posedge clk) td_mode[1] == (ctrl[8] & (~ctrl[7] | ctrl[6]))
    );

// td_mode[0] equals ctrl[8] & ctrl[7].
    check_bit0_is_and: assert property (
        @(posedge clk) td_mode[0] == (ctrl[8] & ctrl[7])
    );

// Route Y = D0 when S1=0,S0=0 and selects are known.
    route_sel00_to_D0: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b0) && (S0==1'b0)) |-> (Y === D0)
    );

// Route Y = D1 when S1=0,S0=1 and selects are known.
    route_sel01_to_D1: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b0) && (S0==1'b1)) |-> (Y === D1)
    );

// Route Y = D2 when S1=1,S0=0 and selects are known.
    route_sel10_to_D2: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b1) && (S0==1'b0)) |-> (Y === D2)
    );

// Route Y = D3 when S1=1,S0=1 and selects are known.
    route_sel11_to_D3: assert property (
        @(posedge CLK) (!$isunknown(S0) && !$isunknown(S1) && (S1==1'b1) && (S0==1'b1)) |-> (Y === D3)
    );

// Any unknown on S0 or S1 must drive Y to X (due to default in mux2_1).
    xprop_when_select_unknown: assert property (
        @(posedge CLK) ($isunknown(S0) || $isunknown(S1)) |-> (Y === 1'bx)
    );

///// Functional equivalence to reduction operators /////
    // out_and equals bitwise reduction AND of in.
    check_out_and_equals_reduction: assert property (
        @(posedge CLK) (out_and === (&in))
    );

// Reset high at a clock edge forces count to 0 on the next cycle.
    check_reset_next_zero: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

// While reset stays high across cycles, count must be 0.
    check_reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 32'd0)
    );

// If not in reset and count != max_value-1, next count increments by 1.
    check_increment_when_not_wrap: assert property (
        @(posedge clk) disable iff (rst) (count != (max_value - 32'd1)) |-> ##1 (count == $past(count) + 32'd1)
    );

// If not in reset and count == max_value-1, next count wraps to 0.
    check_wrap_when_threshold: assert property (
        @(posedge clk) disable iff (rst) (count == (max_value - 32'd1)) |-> ##1 (count == 32'd0)
    );

// On the first cycle after reset deasserts, next update from 0 follows normal rule.
    check_post_reset_first_update: assert property (
        @(posedge clk) ($past(rst) && !rst) |-> ##1 (count == (($past(max_value) == 32'd1) ? 32'd0 : 32'd1))
    );

// Orientation must be 1 when cc1=1 and cc2=0.
    check_orient_A_forward: assert property (
        @(posedge CLK) (cc1 === 1'b1) && (cc2 === 1'b0) |-> (orientation === 1'b1)
    );

// Orientation must be 0 when cc1=0 and cc2=1.
    check_orient_B_forward: assert property (
        @(posedge CLK) (cc1 === 1'b0) && (cc2 === 1'b1) |-> (orientation === 1'b0)
    );

// On cc1 rising edge with cc2 low, orientation must be 1 in the same cycle.
    check_orient_on_cc1_rise: assert property (
        @(posedge CLK) ($rose(cc1) && (cc2 === 1'b0)) |-> (orientation === 1'b1)
    );

// On cc2 rising edge with cc1 low, orientation must be 0 in the same cycle.
    check_orient_on_cc2_rise: assert property (
        @(posedge CLK) ($rose(cc2) && (cc1 === 1'b0)) |-> (orientation === 1'b0)
    );

// out must equal a & b every cycle.
    check_and_equivalence: assert property (
        @(posedge clk) out == (a & b)
    );

///// Reset behavior /////
  // While reset is asserted (active-low), count must be 0.
  reset_holds_zero: assert property (
    @(posedge clk) (areset == 1'b0) |-> (count == 4'd0)
  );

///// Load behavior /////
  // When load is 1, next count equals current load_value.
  load_updates_count_next: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b1) |=> (count == $past(load_value))
  );

///// Up/Down behavior /////
  // When load is 0 and up_down is 1, next count increments by 1 (mod 16).
  increment_update: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b1) |=> (count == ($past(count) + 4'd1))
  );

// When load is 0 and up_down is 0, next count decrements by 1 (mod 16).
  decrement_update: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b0) |=> (count == ($past(count) - 4'd1))
  );

///// Wrap-around behavior /////
  // Increment wraps from 15 to 0.
  increment_wrap: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b1 && $past(count) == 4'hF) |=> (count == 4'h0)
  );

// Decrement wraps from 0 to 15.
  decrement_wrap: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0 && up_down == 1'b0 && $past(count) == 4'h0) |=> (count == 4'hF)
  );

///// Sanity checks /////
  // When not loading, count must change each cycle by +/-1.
  change_when_no_load: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      (load == 1'b0) |=> (count != $past(count))
  );

// Full next-state equation matches RTL priority and arithmetic.
  next_state_function: assert property (
    @(posedge clk) disable iff (areset == 1'b0)
      1'b1 |=> ( count == ( $past(load) ? $past(load_value)
                                : ( $past(up_down) ? ($past(count) + 4'd1)
                                                   : ($past(count) - 4'd1) ) ) )
  );

// Left shift selected: out equals in << shift_amount.
    check_left_shift_result: assert property (
        @(posedge CLK) (direction == 1'b0) |-> (out == (in << shift_amount))
    );

// Right shift selected: out equals in >> shift_amount.
    check_right_shift_result: assert property (
        @(posedge CLK) (direction == 1'b1) |-> (out == (in >> shift_amount))
    );

// Zero shift amount passes input through regardless of direction.
    check_shift_zero_passthrough: assert property (
        @(posedge CLK) (shift_amount == 3'd0) |-> (out == in)
    );

// Left shift with nonzero amount zero-fills LSB.
    check_left_shift_lsb_zero_when_nonzero: assert property (
        @(posedge CLK) ((direction == 1'b0) && (shift_amount != 3'd0)) |-> (out[0] == 1'b0)
    );

// Right shift with nonzero amount zero-fills MSB.
    check_right_shift_msb_zero_when_nonzero: assert property (
        @(posedge CLK) ((direction == 1'b1) && (shift_amount != 3'd0)) |-> (out[7] == 1'b0)
    );

// Extreme case: left shift by 7 places.
    check_extreme_left_shift7: assert property (
        @(posedge CLK) ((direction == 1'b0) && (shift_amount == 3'd7)) |-> (out == {in[0], 7'b0})
    );

// Extreme case: right shift by 7 places.
    check_extreme_right_shift7: assert property (
        @(posedge CLK) ((direction == 1'b1) && (shift_amount == 3'd7)) |-> (out == {7'b0, in[7]})
    );

// Specific case: left shift by 1 place.
    check_left_shift1_pattern: assert property (
        @(posedge CLK) ((direction == 1'b0) && (shift_amount == 3'd1)) |-> (out == {in[6:0], 1'b0})
    );

// Zero input always yields zero output.
    check_zero_input_yields_zero_output: assert property (
        @(posedge CLK) (in == 8'b0) |-> (out == 8'b0)
    );

///// Reset behavior /////
    // While reset is asserted (clr==0), q must be HIGH.
    reset_forces_q_high: assert property (
        @(posedge clk) !clr |-> (q == 1'b1)
    );

// On a falling edge of clr, q must be HIGH in the same sampled cycle.
    q_high_on_reset_fall: assert property (
        @(posedge clk) $fell(clr) |-> (q == 1'b1)
    );

// q can be 0 only when not in reset.
    q_zero_only_out_of_reset: assert property (
        @(posedge clk) (q == 1'b0) |-> (clr == 1'b1)
    );

// Asserting reset drives count to 0 on the next clock.
    check_reset_clears_next_cycle: assert property (
        @(posedge clk) rst |-> ##1 (count == 4'd0)
    );

// If reset is high two cycles in a row, current count is 0.
    check_held_reset_forces_zero: assert property (
        @(posedge clk) $past(rst) && rst |-> (count == 4'd0)
    );

///// Aggregation (OR) outputs /////
    // m_pi_req is the bitwise OR of all slave s*_pi_req.
    check_m_pi_req_or: assert property (
        @(posedge clk) disable iff (reset) m_pi_req == (s0_pi_req | s1_pi_req | s2_pi_req | s3_pi_req)
    );

// m_iob_read is the bitwise OR of m_iob_write and all slave s*_iob_read.
    check_m_iob_read_or: assert property (
        @(posedge clk) disable iff (reset) m_iob_read == (m_iob_write | s0_iob_read | s1_iob_read | s2_iob_read | s3_iob_read)
    );

// m_dr_split is the OR of all slave s*_dr_split.
    check_m_dr_split_or: assert property (
        @(posedge clk) disable iff (reset) m_dr_split == (s0_dr_split | s1_dr_split | s2_dr_split | s3_dr_split)
    );

// m_rdi_data is the OR of all slave s*_rdi_data.
    check_m_rdi_data_or: assert property (
        @(posedge clk) disable iff (reset) m_rdi_data == (s0_rdi_data | s1_rdi_data | s2_rdi_data | s3_rdi_data)
    );

