            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
                @(posedge clk) gray_code_output[i] == (binary_input[i] ^ binary_input[i+1])
            );

// Gray bit[i] equals XOR of binary bits i and i+1.
            check_bitwise_mapping: assert property (
