///// Functional equivalence: Y = (~A) & B_N /////
    // Y equals (~A & B_N) at A rising edge.
    check_func_posedge_A: assert property (
        @(posedge A) Y == ((~A) & B_N)
    );

// Y equals (~A & B_N) at A falling edge.
    check_func_negedge_A: assert property (
        @(negedge A) Y == ((~A) & B_N)
    );

// Y equals (~A & B_N) at B_N rising edge.
    check_func_posedge_BN: assert property (
        @(posedge B_N) Y == ((~A) & B_N)
    );

// Y equals (~A & B_N) at B_N falling edge.
    check_func_negedge_BN: assert property (
        @(negedge B_N) Y == ((~A) & B_N)
    );

// If A is HIGH, Y must be LOW.
    check_A_high_forces_Y_low: assert property (
        @(posedge B_N) (A == 1'b1) |-> (Y == 1'b0)
    );

// If B_N is LOW, Y must be LOW.
    check_BN_low_forces_Y_low: assert property (
        @(posedge A) (B_N == 1'b0) |-> (Y == 1'b0)
    );

///// Directional effects on output with specific input edges /////
    // With B_N HIGH, Y equals NOT A (sampled on A edge).
    check_BN_high_implies_Y_eq_notA: assert property (
        @(posedge A) (B_N == 1'b1) |-> (Y == (~A))
    );

// Output is the bitwise OR of all inputs.
    check_or_function: assert property (
        @(posedge dclkin) data0out == (sdoin | scein | dclkin | oe)
    );

// If sdoin is HIGH, data0out must be HIGH.
    check_sdoin_drives_out_high: assert property (
        @(posedge dclkin) sdoin |-> data0out
    );

// If scein is HIGH, data0out must be HIGH.
    check_scein_drives_out_high: assert property (
        @(posedge dclkin) scein |-> data0out
    );

// If oe is HIGH, data0out must be HIGH.
    check_oe_drives_out_high: assert property (
        @(posedge dclkin) oe |-> data0out
    );

// Synchronous reset drives count and output_signal to 0 in the next cycle.
    check_reset_clears_both: assert property (
        @(posedge clk) reset |=> (count == 4'd0) && (output_signal == 4'd0)
    );

// With MSB=0 (and not sentinel), output holds its previous value next cycle.
    check_msb0_holds_output: assert property (
        @(posedge clk) disable iff (reset)
            (!((input_signal == 16'hFFFF) || (input_signal == 16'h0000)) && (input_signal[15] == 1'b0) && $past(!reset)) |=> (output_signal == $past(output_signal))
    );

// All 4 outputs equal the AND of the two inputs.
    check_out_matches_and_broadcast: assert property (
        @(posedge clk) disable iff (!rst_n) out == {4{in[0] & in[1]}}
    );

// All output bits are identical at all times.
    check_all_outs_equal: assert property (
        @(posedge clk) disable iff (!rst_n) (out[0] == out[1]) && (out[1] == out[2]) && (out[2] == out[3])
    );

// Outputs are all zero when any input is zero.
    check_out_zero_when_any_input_zero: assert property (
        @(posedge clk) disable iff (!rst_n) ((!in[0]) || (!in[1])) |-> (out == 4'b0000)
    );

// Outputs are all one when both inputs are one.
    check_out_one_when_both_inputs_one: assert property (
        @(posedge clk) disable iff (!rst_n) (in[0] && in[1]) |-> (out == 4'b1111)
    );

// A rising edge on any output implies both inputs are one.
    check_out_rise_implies_inputs_high: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(out[0]) |-> (in[0] && in[1])
    );

// A falling edge on any output implies at least one input is zero.
    check_out_fall_implies_any_input_low: assert property (
        @(posedge clk) disable iff (!rst_n) $fell(out[0]) |-> ((!in[0]) || (!in[1]))
    );

// Output bus can only be all-zeros or all-ones.
    check_out_is_const_bus: assert property (
        @(posedge clk) disable iff (!rst_n) (out == 4'b0000) || (out == 4'b1111)
    );

///// Functional equivalence checks /////
    // X equals A|B when A rises.
    check_func_eq_on_A_posedge: assert property (
        @(posedge A) X == (A | B)
    );

// X equals A|B when A falls.
    check_func_eq_on_A_negedge: assert property (
        @(negedge A) X == (A | B)
    );

// X equals A|B when B rises.
    check_func_eq_on_B_posedge: assert property (
        @(posedge B) X == (A | B)
    );

// X equals A|B when B falls.
    check_func_eq_on_B_negedge: assert property (
        @(negedge B) X == (A | B)
    );

// A falling with B high keeps X high.
    check_x_stays_high_on_a_fall_when_b_high: assert property (
        @(negedge A) (B == 1'b1) |-> (X == 1'b1)
    );

// B falling with A high keeps X high.
    check_x_stays_high_on_b_fall_when_a_high: assert property (
        @(negedge B) (A == 1'b1) |-> (X == 1'b1)
    );

// P equals A & ~n at each sample
    check_p_equals_a_and_notn: assert property (
        @(posedge C) P == (A & ~n)
    );

// When n is 1, P must be 0
    check_p_zero_when_n_high: assert property (
        @(posedge C) n |-> (P == 1'b0)
    );

// When n is 0, P equals A
    check_p_equals_a_when_n_low: assert property (
        @(posedge C) !n |-> (P == A)
    );

// When A is 0, P must be 0
    check_p_zero_when_a_low: assert property (
        @(posedge C) (A == 1'b0) |-> (P == 1'b0)
    );

// When A is 1 and n is 0, P must be 1
    check_p_one_when_a1_n0: assert property (
        @(posedge C) (A && !n) |-> (P == 1'b1)
    );

// P high implies A is 1 and n is 0
    check_p_high_implies_inputs: assert property (
        @(posedge C) (P == 1'b1) |-> (A && !n)
    );

// P low implies A is 0 or n is 1
    check_p_low_implies_inputs: assert property (
        @(posedge C) (P == 1'b0) |-> (!A || n)
    );

///// Functional next-state rules /////
    // Next out equals prior load ? prior in : prior out shifted in with 0 LSB.
    check_next_out_function: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(load) ? $past(in) : { $past(out[2:0]), 1'b0 }))
    );

// When load is 1, next out equals prior in.
    check_load_captures_in_next: assert property (
        @(posedge clk) load |=> (out == $past(in))
    );

// When load is 0, next out equals prior out shifted left with 0 inserted.
    check_no_load_shifts_next: assert property (
        @(posedge clk) !load |=> (out == { $past(out[2:0]), 1'b0 })
    );

// When load is 0, the next out[0] must be 0.
    check_lsb_zero_on_shift: assert property (
        @(posedge clk) !load |=> (out[0] == 1'b0)
    );

///// Valid signaling /////
    // Next valid equals prior load.
    check_valid_follows_prev_load: assert property (
        @(posedge clk) 1'b1 |=> (valid == $past(load))
    );

// When load is 1, next valid must be 1.
    check_load_sets_valid_next: assert property (
        @(posedge clk) load |=> (valid == 1'b1)
    );

///// Long no-load behavior /////
    // After 4 consecutive cycles of no load, out becomes 0.
    check_no_load_flushes_zero_after_four: assert property (
        @(posedge clk) (!load)[*4] |=> (out == 4'b0000)
    );

// X implements (~A_N) & B
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((~A_N) & B)
    );

// If A_N is HIGH, X must be LOW
    check_zero_when_A_N_high: assert property (
        @(posedge clk) A_N |-> (X == 1'b0)
    );

// If B is LOW, X must be LOW
    check_zero_when_B_low: assert property (
        @(posedge clk) !B |-> (X == 1'b0)
    );

// If A_N is LOW and B is HIGH, X must be HIGH
    check_one_when_A_N_low_and_B_high: assert property (
        @(posedge clk) (!A_N && B) |-> (X == 1'b1)
    );

// If X is HIGH, then A_N must be LOW and B must be HIGH
    check_inputs_when_X_high: assert property (
        @(posedge clk) X |-> (!A_N && B)
    );

// If X is LOW while B is HIGH, then A_N must be HIGH
    check_A_N_high_when_X_low_and_B_high: assert property (
        @(posedge clk) ((X == 1'b0) && B) |-> A_N
    );

// If X is LOW while A_N is LOW, then B must be LOW
    check_B_low_when_X_low_and_A_N_low: assert property (
        @(posedge clk) ((X == 1'b0) && !A_N) |-> !B
    );

///// Functional equivalence /////
    // out equals AND of the OR-reductions of a and b.
    check_out_eq_and_of_ors: assert property (
        @(posedge clk) disable iff (1'b0) out == ((a[1] | a[0]) & (b[1] | b[0]))
    );

// out equals the sum-of-products of all a/b bit pairs.
    check_out_eq_sum_of_products: assert property (
        @(posedge clk) disable iff (1'b0) out == ((a[1] & b[1]) | (a[1] & b[0]) | (a[0] & b[1]) | (a[0] & b[0]))
    );

///// Necessary conditions /////
    // If a is zero, out must be zero.
    check_a_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (a == 2'b00) |-> (out == 1'b0)
    );

// If b is zero, out must be zero.
    check_b_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (b == 2'b00) |-> (out == 1'b0)
    );

// If out is one, both a and b must be non-zero.
    check_out1_implies_nonzero_inputs: assert property (
        @(posedge clk) disable iff (1'b0) (out == 1'b1) |-> ((a != 2'b00) && (b != 2'b00))
    );

// If out is zero, at least one of a or b must be zero.
    check_out0_implies_one_zero: assert property (
        @(posedge clk) disable iff (1'b0) (out == 1'b0) |-> ((a == 2'b00) || (b == 2'b00))
    );

///// Sufficient conditions /////
    // If both a and b are non-zero, out must be one.
    check_nonzero_inputs_force_out1: assert property (
        @(posedge clk) disable iff (1'b0) ((a != 2'b00) && (b != 2'b00)) |-> (out == 1'b1)
    );

// If exactly one of a or b is zero, out must be zero.
    check_exactly_one_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (((a == 2'b00) ^ (b == 2'b00))) |-> (out == 1'b0)
    );

///// Reset behavior /////
    // Synchronous clear forces op low on the next cycle.
    reset_clears_op_next: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

///// Update and hold rules /////
    // With clr low, ce sets op high on the next cycle.
    ce_sets_op_high_next: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == 1'b1)
    );

// With clr low and ce low, op holds its value.
    hold_without_ce: assert property (
        @(posedge clk) disable iff (clr) !ce |=> (op == $past(op))
    );

// Once high and with clr low, op stays high.
    sticky_high_without_clr: assert property (
        @(posedge clk) disable iff (clr) (op == 1'b1) |=> (op == 1'b1)
    );

///// Reset behavior /////
    // While reset is asserted (low), count must be 0.
    reset_drives_zero: assert property (
        @(posedge clk) !reset |-> (count == 32'd0)
    );

// On reset deassertion edge, count is 0 in that cycle.
    zero_on_reset_release: assert property (
        @(posedge clk) $rose(reset) |-> (count == 32'd0)
    );

///// Counting behavior /////
    // When disabled, the counter holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
            (!count_en) |=> (count == $past(count))
    );

// When enabled, next value is +1 unless at max_count, then it wraps to 0.
    update_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
            (count_en) |=> (count == (($past(count) == $past(max_count)) ? 32'd0 : ($past(count) + 32'd1)))
    );

// Any change between cycles (out of reset) requires enable in the previous cycle.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && (count != $past(count))) |-> $past(count_en)
    );

// If enabled at all-ones and not equal to max_count, next value wraps to 0 via +1 overflow.
    overflow_wrap_to_zero: assert property (
        @(posedge clk) disable iff (!reset)
            (count_en && (count == 32'hFFFF_FFFF) && (count != max_count)) |=> (count == 32'd0)
    );

// If next value is 0 with enable high previously, cause is wrap-to-zero or max_count match.
    enabled_zero_next_cycle_has_cause: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && $past(count_en) && (count == 32'd0)) |-> (($past(count) == $past(max_count)) || ($past(count) == 32'hFFFF_FFFF))
    );

///// End-to-end 1-cycle pipeline from inputs to out /////
    // If sel==00 this cycle, out equals in0 from this cycle on the next cycle.
    check_out_pipeline_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |=> (out == $past(in0))
    );

// If sel==01 this cycle, out equals in1 from this cycle on the next cycle.
    check_out_pipeline_sel_01: assert property (
        @(posedge clk) (sel == 2'b01) |=> (out == $past(in1))
    );

// If sel==10 this cycle, out equals in2 from this cycle on the next cycle.
    check_out_pipeline_sel_10: assert property (
        @(posedge clk) (sel == 2'b10) |=> (out == $past(in2))
    );

// If sel==11 this cycle, out equals in3 from this cycle on the next cycle.
    check_out_pipeline_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |=> (out == $past(in3))
    );

// With DE=1 now, on the next edge Q equals the current D.
    check_capture_next_cycle_on_current_enable: assert property (
        @(posedge CLK) DE |-> ##1 (Q == $past(D))
    );

// Y equals (~(A|B)) & C_N & D_N when inputs are known.
    check_logic_equation: assert property (
        @(posedge clk) !$isunknown({A,B,C_N,D_N}) |-> (Y == ((~(A | B)) & C_N & D_N))
    );

// Y can be HIGH only when A=0, B=0, C_N=1, D_N=1.
    check_y_high_implies_inputs: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A == 1'b0) && (B == 1'b0) && (C_N == 1'b1) && (D_N == 1'b1))
    );

// A=1 forces Y=0.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b0)
    );

// B=1 forces Y=0.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == 1'b0)
    );

// C_N=0 forces Y=0.
    check_cn_low_forces_y_low: assert property (
        @(posedge clk) (C_N == 1'b0) |-> (Y == 1'b0)
    );

// D_N=0 forces Y=0.
    check_dn_low_forces_y_low: assert property (
        @(posedge clk) (D_N == 1'b0) |-> (Y == 1'b0)
    );

// When A=0, B=0, C_N=1, and D_N=1, Y must be 1.
    check_all_conditions_drive_y_high: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C_N == 1'b1) && (D_N == 1'b1)) |-> (Y == 1'b1)
    );

// A rising edge drives Y low in the same cycle.
    check_rose_a_drives_y_low: assert property (
        @(posedge clk) $rose(A) |-> (Y == 1'b0)
    );

// B rising edge drives Y low in the same cycle.
    check_rose_b_drives_y_low: assert property (
        @(posedge clk) $rose(B) |-> (Y == 1'b0)
    );

// C_N falling edge drives Y low in the same cycle.
    check_fell_cn_drives_y_low: assert property (
        @(posedge clk) $fell(C_N) |-> (Y == 1'b0)
    );

// D_N falling edge drives Y low in the same cycle.
    check_fell_dn_drives_y_low: assert property (
        @(posedge clk) $fell(D_N) |-> (Y == 1'b0)
    );

// Clock: CLOCK (posedge). Reset: RESET (active-high, asynchronous).
    // Logic: Sequential register computing absolute difference; DIFF cleared to 0 on RESET.

    // DIFF must be 0 whenever RESET is asserted at the clock edge.
    reset_forces_zero: assert property (
        @(posedge CLOCK) RESET |-> (DIFF == 12'd0)
    );

///// Functional correctness /////
    // SUM must equal XOR of A, B, CI.
    check_sum_xor3: assert property (
        @(posedge CLK) SUM === (A ^ B ^ CI)
    );

// COUT must equal majority of A, B, CI.
    check_cout_majority: assert property (
        @(posedge CLK) COUT === ((A & B) | (A & CI) | (B & CI))
    );

///// Truth-table spot checks /////
    // When A=B=CI=0, SUM=0 and COUT=0.
    check_tt_all_zero: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b0 && CI==1'b0) |-> (SUM==1'b0 && COUT==1'b0)
    );

// When A=B=CI=1, SUM=1 and COUT=1.
    check_tt_all_one: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b1 && CI==1'b1) |-> (SUM==1'b1 && COUT==1'b1)
    );

// When only A=1, SUM=1 and COUT=0.
    check_tt_only_a: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b0 && CI==1'b0) |-> (SUM==1'b1 && COUT==1'b0)
    );

// When only B=1, SUM=1 and COUT=0.
    check_tt_only_b: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b1 && CI==1'b0) |-> (SUM==1'b1 && COUT==1'b0)
    );

// When only CI=1, SUM=1 and COUT=0.
    check_tt_only_ci: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b0 && CI==1'b1) |-> (SUM==1'b1 && COUT==1'b0)
    );

// When A=B=1 and CI=0, SUM=0 and COUT=1.
    check_tt_ab_two_ones: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b1 && CI==1'b0) |-> (SUM==1'b0 && COUT==1'b1)
    );

// When A=CI=1 and B=0, SUM=0 and COUT=1.
    check_tt_ac_two_ones: assert property (
        @(posedge CLK) (A==1'b1 && B==1'b0 && CI==1'b1) |-> (SUM==1'b0 && COUT==1'b1)
    );

// When B=CI=1 and A=0, SUM=0 and COUT=1.
    check_tt_bc_two_ones: assert property (
        @(posedge CLK) (A==1'b0 && B==1'b1 && CI==1'b1) |-> (SUM==1'b0 && COUT==1'b1)
    );

///// Derived consistency /////
    // COUT high implies at least two inputs are high.
    check_cout_implies_two_high: assert property (
        @(posedge CLK) COUT |-> ((A & B) | (A & CI) | (B & CI))
    );

// COUT low implies fewer than two inputs are high.
    check_cout_low_implies_lt2: assert property (
        @(posedge CLK) !COUT |-> ~((A & B) | (A & CI) | (B & CI))
    );

///// Reset behavior /////
  // While reset is asserted low, outputs are forced to 0/1.
  reset_level_forces_values: assert property (
    @(posedge CLK) !RST |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled falling edge of reset, outputs are 0/1.
  reset_fall_forces_values: assert property (
    @(posedge CLK) $fell(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled rising edge of reset, outputs are still at reset values before capture.
  reset_rise_holds_reset_values_before_capture: assert property (
    @(posedge CLK) $rose(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

///// Output relationship /////
  // QN is always the logical inverse of Q.
  complement_invariant: assert property (
    @(posedge CLK) QN == ~Q
  );

// Q and QN are never both HIGH.
  never_both_high: assert property (
    @(posedge CLK) !(Q && QN)
  );

// Q and QN are never both LOW.
  never_both_low: assert property (
    @(posedge CLK) !(~Q && ~QN)
  );

// A rise on Q implies a fall on QN in the same sample.
  q_rise_implies_qn_fall: assert property (
    @(posedge CLK) $rose(Q) |-> $fell(QN)
  );

// Analysis: No clock/reset in RTL; pure combinational. out=1 iff a<b; sub does not affect out.

    ///// Functional equivalence /////
    // out must reflect comparator result: out == (a < b).
    check_out_equals_less: assert property (
        @(posedge clk) out == (a < b)
    );

///// Case-specific behavior /////
    // When a < b, out is 1.
    check_out_one_when_less: assert property (
        @(posedge clk) (a < b) |-> (out == 1'b1)
    );

// When a >= b, out is 0.
    check_out_zero_when_ge: assert property (
        @(posedge clk) (a >= b) |-> (out == 1'b0)
    );

///// Functional definitions /////
    // X must equal A1 AND A2.
    check_x_and_def: assert property (
        @(posedge A1) X == (A1 & A2)
    );

// Y must equal A1 OR A2.
    check_y_or_def: assert property (
        @(posedge A1) Y == (A1 | A2)
    );

// Z must equal A1 XOR A2.
    check_z_xor_def: assert property (
        @(posedge A1) Z == (A1 ^ A2)
    );

// W must equal B1 AND VPWR.
    check_w_and_def: assert property (
        @(posedge B1) W == (B1 & VPWR)
    );

///// Output relationships implied by the logic /////
    // If X is 1, Y must be 1.
    check_x_implies_y: assert property (
        @(posedge A1) X |-> Y
    );

// If X is 1, Z must be 0.
    check_x_implies_not_z: assert property (
        @(posedge A1) X |-> (Z == 1'b0)
    );

// If Z is 1, X must be 0.
    check_z_implies_not_x: assert property (
        @(posedge A1) Z |-> (X == 1'b0)
    );

// If Z is 1, Y must be 1.
    check_z_implies_y: assert property (
        @(posedge A1) Z |-> Y
    );

// Y equals X OR Z (OR decomposition).
    check_y_equals_x_or_z: assert property (
        @(posedge A1) Y == (X | Z)
    );

// X and Z are mutually exclusive.
    check_x_and_z_disjoint: assert property (
        @(posedge A1) (X & Z) == 1'b0
    );

///// Power gating behavior for W /////
    // W can be 1 only if B1 is 1.
    check_w_requires_b1: assert property (
        @(posedge A1) W |-> B1
    );

// W can be 1 only if VPWR is 1.
    check_w_requires_vpwr: assert property (
        @(posedge A1) W |-> VPWR
    );

// If VPWR is 0 then W must be 0.
    check_vpwr_low_forces_w_low: assert property (
        @(posedge A1) (!VPWR) |-> (W == 1'b0)
    );

///// Sanity on specific input combinations /////
    // When A1 and A2 are both 1: X=1, Y=1, Z=0.
    check_both_one: assert property (
        @(posedge A1) (A1 & A2) |-> (X && Y && (Z == 1'b0))
    );

// When A1 and A2 differ: Z=1, Y=1, X=0.
    check_inputs_differ: assert property (
        @(posedge A1) (A1 ^ A2) |-> (Z && Y && (X == 1'b0))
    );

///// Enable gating /////
    // When disabled, out is zero.
    check_out_zero_when_en_low: assert property (
        @(posedge clk) !en |-> (out == 4'b0000)
    );

///// Output mapping with enable /////
    // When en and sel==00, out equals in0.
    check_out_matches_in0_when_en_sel00: assert property (
        @(posedge clk) (en && (sel == 2'b00)) |-> (out == in0)
    );

// When en and sel==01, out equals in1.
    check_out_matches_in1_when_en_sel01: assert property (
        @(posedge clk) (en && (sel == 2'b01)) |-> (out == in1)
    );

// When en and sel==10, out equals in2.
    check_out_matches_in2_when_en_sel10: assert property (
        @(posedge clk) (en && (sel == 2'b10)) |-> (out == in2)
    );

// When en and sel==11, out equals in3.
    check_out_matches_in3_when_en_sel11: assert property (
        @(posedge clk) (en && (sel == 2'b11)) |-> (out == in3)
    );

///// Basic output relations /////
    // C always mirrors S[0].
    check_c_mirrors_s0: assert property (
        @(posedge clk) C == S[0]
    );

// S equals one of the four priority-selected shift results.
    check_s_in_valid_set: assert property (
        @(posedge clk)
            (S == A) ||
            (S == {A[2:0], 1'b0}) ||
            (S == {A[1:0], 2'b0}) ||
            (S == {A[0], 3'b0})
    );

///// Priority selection by B /////
    // When B[2] is 1, S equals A and C equals A[0].
    check_b2_selects_a: assert property (
        @(posedge clk) B[2] |-> (S == A) && (C == A[0])
    );

// When B[1] is 1 and B[2] is 0, S is A<<1 and C is 0.
    check_b1_selects_shift1: assert property (
        @(posedge clk) (!B[2] && B[1]) |-> (S == {A[2:0], 1'b0}) && (C == 1'b0)
    );

// When only B[0] is 1 (and B[2:1]==0), S is A<<2 and C is 0.
    check_b0_selects_shift2: assert property (
        @(posedge clk) (!B[2] && !B[1] && B[0]) |-> (S == {A[1:0], 2'b0}) && (C == 1'b0)
    );

// When B is 3'b000, S is A<<3 and C is 0.
    check_b000_selects_shift3: assert property (
        @(posedge clk) (!B[2] && !B[1] && !B[0]) |-> (S == {A[0], 3'b0}) && (C == 1'b0)
    );

///// Bit-level consequences /////
    // When B[2] is 0, LSB of S is 0.
    check_s0_zero_when_b2_zero: assert property (
        @(posedge clk) (!B[2]) |-> (S[0] == 1'b0)
    );

// When selecting A<<1, S[3] equals A[2].
    check_msbit_mapping_b1: assert property (
        @(posedge clk) (!B[2] && B[1]) |-> (S[3] == A[2])
    );

// When selecting A<<2, S[3] equals A[1].
    check_msbit_mapping_b0: assert property (
        @(posedge clk) (!B[2] && !B[1] && B[0]) |-> (S[3] == A[1])
    );

// When selecting A<<3, S[3] equals A[0].
    check_msbit_mapping_b000: assert property (
        @(posedge clk) (!B[2] && !B[1] && !B[0]) |-> (S[3] == A[0])
    );

// X equals the bitwise AND of A, B, C, and D.
    check_and_equation: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// X can be HIGH only if all inputs are HIGH.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

// All inputs HIGH implies X is HIGH.
    check_all_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// A LOW forces X LOW.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (!A) |-> (!X)
    );

// B LOW forces X LOW.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (!B) |-> (!X)
    );

// C LOW forces X LOW.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (!C) |-> (!X)
    );

// D LOW forces X LOW.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (!D) |-> (!X)
    );

// X rising edge only when all inputs are HIGH.
    check_x_rise_requires_all_high: assert property (
        @(posedge clk) $rose(X) |-> (A && B && C && D)
    );

// X falling edge implies at least one input is LOW.
    check_x_fall_requires_any_low: assert property (
        @(posedge clk) $fell(X) |-> (!A || !B || !C || !D)
    );

///// Reset behavior /////
    // During reset, motor_speed is forced to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (motor_speed == 8'd0)
    );

// While reset stays asserted across cycles, motor_speed remains zero.
    check_zero_while_reset_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (motor_speed == 8'd0)
    );

// On a falling edge of reset, output at this sample is zero (held from prior reset cycle).
    check_output_zero_on_reset_fall_sample: assert property (
        @(posedge clk) $fell(rst) |-> (motor_speed == 8'd0)
    );

// On a rising edge of reset, async reset clears output to zero by this sample.
    check_output_zero_on_reset_rise_sample: assert property (
        @(posedge clk) $rose(rst) |-> (motor_speed == 8'd0)
    );

// On reset HIGH, next cycle count is driven to 0.
  reset_clears_next: assert property (
    @(posedge clk) reset |=> (count == 4'd0)
  );

// If reset stays HIGH across cycles, count is 0 on the later cycle.
  reset_holds_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == 4'd0)
  );

///// Functional correctness /////
    // SUM equals XOR of inputs.
    check_sum_matches_xor: assert property (
        @(posedge CLK) SUM == (A ^ B ^ CI)
    );

// COUT equals majority-of-three of inputs.
    check_cout_majority: assert property (
        @(posedge CLK) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// 2-bit result {COUT,SUM} equals arithmetic sum of inputs.
    check_addition_consistency: assert property (
        @(posedge CLK) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

///// Simplified cases derived from the equations /////
    // When B equals CI, SUM equals A.
    check_sum_equals_A_when_BeqCI: assert property (
        @(posedge CLK) (B == CI) |-> (SUM == A)
    );

// When A equals B, SUM equals CI.
    check_sum_equals_CI_when_AeqB: assert property (
        @(posedge CLK) (A == B) |-> (SUM == CI)
    );

// For inputs 000, outputs must be 00.
    check_truth_000: assert property (
        @(posedge CLK) (!A && !B && !CI) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

// For inputs 111, outputs must be 11.
    check_truth_111: assert property (
        @(posedge CLK) (A && B && CI) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

// X equals A OR NOT B_N.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A | ~B_N)
    );

// If A is 1, X must be 1.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// If B_N is 0, X must be 1.
    check_bn_low_forces_x_high: assert property (
        @(posedge clk) (~B_N) |-> X
    );

// If A is 0 and B_N is 1, X must be 0.
    check_a0_bn1_forces_x0: assert property (
        @(posedge clk) (!A && B_N) |-> (!X)
    );

// X is 0 only when A is 0 and B_N is 1.
    check_x0_only_when_a0_bn1: assert property (
        @(posedge clk) (!X) |-> (!A && B_N)
    );

// Truth-table corner: A=0, B_N=0 => X=1.
    check_tt_a0_bn0_x1: assert property (
        @(posedge clk) (!A && !B_N) |-> X
    );

// Truth-table corner: A=1, B_N=0 => X=1.
    check_tt_a1_bn0_x1: assert property (
        @(posedge clk) (A && !B_N) |-> X
    );

// Truth-table corner: A=1, B_N=1 => X=1.
    check_tt_a1_bn1_x1: assert property (
        @(posedge clk) (A && B_N) |-> X
    );

// Truth-table corner: A=0, B_N=1 => X=0.
    check_tt_a0_bn1_x0: assert property (
        @(posedge clk) (!A && B_N) |-> (!X)
    );

// strobe HIGH requires enable and strobe_in HIGH.
    strobe_requires_inputs: assert property (
        @(posedge clock) strobe |-> (enable && strobe_in)
    );

// enable LOW forces strobe LOW.
    enable_low_forces_strobe_low: assert property (
        @(posedge clock) (!enable) |-> (strobe == 1'b0)
    );

// strobe_in LOW forces strobe LOW.
    strobe_in_low_forces_strobe_low: assert property (
        @(posedge clock) (!strobe_in) |-> (strobe == 1'b0)
    );

///// Counter update behavior /////
    // On reset, counter clears to zero on next cycle.
    counter_clears_on_reset: assert property (
        @(posedge clock) reset |=> (counter == 8'd0)
    );

///// Mode-0 (magnitude code) behavior /////
    // When sel==00, out_mode0 encodes compare result: 00 if A==B, 01 if A>B, 10 if A<B.
    check_sel00_magnitude_encoding: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0 == ((A == B) ? 2'b00 : ((A > B) ? 2'b01 : 2'b10)))
    );

// When sel!=00, out_mode0 must be 00.
    check_sel_not00_out_zero: assert property (
        @(posedge valid) (sel != 2'b00) |-> (out_mode0 == 2'b00)
    );

// For sel==00, out_mode0[1] reflects (A<B).
    check_sel00_out_msb_is_less: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[1] == (A < B))
    );

// For sel==00, out_mode0[0] reflects (A>B).
    check_sel00_out_lsb_is_greater: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[0] == (A > B))
    );

///// Mode-1 (flag outputs) behavior /////
    // When sel==01, less_than reflects (A<B).
    check_sel01_less_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (less_than == (A < B))
    );

// When sel==01, equal_to reflects (A==B).
    check_sel01_equal_to_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (equal_to == (A == B))
    );

// When sel==01, greater_than reflects (A>B).
    check_sel01_greater_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (greater_than == (A > B))
    );

// When sel==01, exactly one of the three flags is HIGH.
    check_sel01_onehot_result: assert property (
        @(posedge valid) (sel == 2'b01) |-> $onehot({less_than, equal_to, greater_than})
    );

///// Output gating when not in mode-1 /////
    // When sel!=01, less_than must be 0.
    check_sel_not01_less_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (less_than == 1'b0)
    );

// When sel!=01, equal_to must be 0.
    check_sel_not01_equal_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (equal_to == 1'b0)
    );

// When sel!=01, greater_than must be 0.
    check_sel_not01_greater_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (greater_than == 1'b0)
    );

///// Combinational AND truth /////
    // X equals the AND of all inputs and rails.
    check_and_function_equality: assert property (
        @(posedge A) X == (A & B & C & D & VPWR & VGND & VPB & VNB)
    );

///// Dominance of 0 /////
    // If any input/rail is 0, X must be 0.
    check_zero_when_any_input_zero: assert property (
        @(posedge A) ((A==1'b0) || (B==1'b0) || (C==1'b0) || (D==1'b0) ||
                      (VPWR==1'b0) || (VGND==1'b0) || (VPB==1'b0) || (VNB==1'b0))
                      |-> (X==1'b0)
    );

///// All-ones drives X high /////
    // If all inputs/rails are 1, X must be 1.
    check_one_when_all_inputs_one: assert property (
        @(posedge A) (A && B && C && D && VPWR && VGND && VPB && VNB) |-> (X==1'b1)
    );

///// High output implies all inputs high /////
    // If X is 1, then all inputs/rails are 1.
    check_one_implies_all_inputs_one: assert property (
        @(posedge A) (X==1'b1) |-> (A && B && C && D && VPWR && VGND && VPB && VNB)
    );

// DFF: Q_D captures D on rising edge (checked at next rising edge).
  check_dff_capture: assert property (
    @(posedge CLK) 1'b1 |=> (Q_D === $past(D))
  );

// JKFF: J=0,K=0 -> hold previous value (checked at next falling edge).
  check_jkff_hold_00: assert property (
    @(negedge CLK) ({J,K} == 2'b00) |=> (Q_JK === $past(Q_JK))
  );

// JKFF: J=0,K=1 -> reset to 0 (checked at next falling edge).
  check_jkff_reset_01: assert property (
    @(negedge CLK) ({J,K} == 2'b01) |=> (Q_JK == 1'b0)
  );

// JKFF: J=1,K=0 -> set to 1 (checked at next falling edge).
  check_jkff_set_10: assert property (
    @(negedge CLK) ({J,K} == 2'b10) |=> (Q_JK == 1'b1)
  );

// JKFF: J=1,K=1 -> toggle (checked at next falling edge).
  check_jkff_toggle_11: assert property (
    @(negedge CLK) ({J,K} == 2'b11) |=> (Q_JK === ~$past(Q_JK))
  );

// TFF: when T=1, toggle on rising edge (checked at next rising edge).
  check_tff_toggle_when_T1: assert property (
    @(posedge CLK) (T == 1'b1) |=> (Q_T === ~$past(Q_T))
  );

// TFF: when T=0, hold on rising edge (checked at next rising edge).
  check_tff_hold_when_T0: assert property (
    @(posedge CLK) (T == 1'b0) |=> (Q_T === $past(Q_T))
  );

// SRFF: S=0,R=0 -> hold previous value (checked at next falling edge).
  check_srff_hold_00: assert property (
    @(negedge CLK) ({S,R} == 2'b00) |=> (Q_SR === $past(Q_SR))
  );

// SRFF: S=0,R=1 -> reset to 0 (checked at next falling edge).
  check_srff_reset_01: assert property (
    @(negedge CLK) ({S,R} == 2'b01) |=> (Q_SR == 1'b0)
  );

// SRFF: S=1,R=0 -> set to 1 (checked at next falling edge).
  check_srff_set_10: assert property (
    @(negedge CLK) ({S,R} == 2'b10) |=> (Q_SR == 1'b1)
  );

// Sum is bitwise XOR of a, b, and c.
    check_sum_is_xor3: assert property (
        @(posedge CLK) disable iff (1'b0) s == (a ^ b) ^ c
    );

// Carry-out equals (a & b) | (c & (a ^ b)).
    check_carry_function: assert property (
        @(posedge CLK) disable iff (1'b0) c_out == ((a & b) | (c & (a ^ b)))
    );

// Carry-out equals majority function (a&b)|(a&c)|(b&c).
    check_carry_majority_equiv: assert property (
        @(posedge CLK) disable iff (1'b0) c_out == ((a & b) | (a & c) | (b & c))
    );

// s OR c_out equals bitwise OR of inputs.
    check_sum_or_carry_matches_input_or: assert property (
        @(posedge CLK) disable iff (1'b0) (s | c_out) == (a | b | c)
    );

// s AND c_out equals bitwise AND of all three inputs.
    check_sum_and_carry_triplet_and: assert property (
        @(posedge CLK) disable iff (1'b0) (s & c_out) == (a & b & c)
    );

// When c is zero, sum reduces to a ^ b.
    check_sum_when_c_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b0000) |-> (s == (a ^ b))
    );

// When c is zero, carry reduces to a & b.
    check_carry_when_c_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b0000) |-> (c_out == (a & b))
    );

// When c is all ones, sum is bitwise NOT of (a ^ b).
    check_sum_when_c_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b1111) |-> (s == ~(a ^ b))
    );

// When c is all ones, carry is a | b.
    check_carry_when_c_ones: assert property (
        @(posedge CLK) disable iff (1'b0) (c == 4'b1111) |-> (c_out == (a | b))
    );

// When a equals b, sum equals c.
    check_sum_when_a_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a == b) |-> (s == c)
    );

// When c equals a ^ b, sum is zero.
    check_sum_when_c_eq_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (c == (a ^ b)) |-> (s == 4'b0000)
    );

// When c equals a ^ b, carry is a | b.
    check_carry_when_c_eq_xor: assert property (
        @(posedge CLK) disable iff (1'b0) (c == (a ^ b)) |-> (c_out == (a | b))
    );

///// Functional mapping /////
    // When sel==00, out equals d0.
    check_map_sel00_to_d0: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b00) |-> (out == d0)
    );

// When sel==01, out equals d1.
    check_map_sel01_to_d1: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b01) |-> (out == d1)
    );

// When sel==10, out equals d2.
    check_map_sel10_to_d2: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b10) |-> (out == d2)
    );

// When sel==11, out equals d3.
    check_map_sel11_to_d3: assert property (
        @(posedge clk) ({sel1, sel2} == 2'b11) |-> (out == d3)
    );

// If m_axi_arready is HIGH, m_payload_o_reg holds its value into the next cycle.
    ready_high_payload_stable_next: assert property (
        @(posedge aclk) (m_axi_arready == 1'b1) |-> ##1 $stable(m_payload_o_reg)
    );

// Analysis: RTL has no clock/reset and is purely combinational (always @*); this module uses external CLK/RESETn only to clock/gate assertions.

    ///// General range /////
    // aluc must be within 0..14 as all assignments are in this range.
    check_aluc_range: assert property (
        @(posedge CLK) disable iff (!RESETn) (aluc <= 5'd14)
    );

///// Outer op decode (direct mappings) /////
    // When op == 000000, aluc must be 0.
    check_op_000000_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000000) |-> (aluc == 5'd0)
    );

// When op == 000001, aluc must be 1.
    check_op_000001_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000001) |-> (aluc == 5'd1)
    );

// When op == 000010, aluc must be 2.
    check_op_000010_aluc2: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000010) |-> (aluc == 5'd2)
    );

// When op == 000011, aluc must be 3.
    check_op_000011_aluc3: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000011) |-> (aluc == 5'd3)
    );

// When op == 000100, aluc must be 5.
    check_op_000100_aluc5: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000100) |-> (aluc == 5'd5)
    );

// When op == 000101, aluc must be 14.
    check_op_000101_aluc14: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b000101) |-> (aluc == 5'd14)
    );

// When op == 001001, aluc must be 1.
    check_op_001001_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001001) |-> (aluc == 5'd1)
    );

// When op == 001010, aluc must be 13.
    check_op_001010_aluc13: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001010) |-> (aluc == 5'd13)
    );

// For any op not explicitly listed (and not 001000), aluc must be 0 (outer default).
    check_default_other_ops_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!(op inside {6'b001000,6'b000000,6'b000001,6'b000010,6'b000011,6'b000100,6'b000101,6'b001001,6'b001010})) |-> (aluc == 5'd0)
    );

///// Inner func decode when op == 001000 /////
    // func 100000 -> aluc 0
    check_op001000_func100000_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100000) |-> (aluc == 5'd0)
    );

// func 100010 -> aluc 1
    check_op001000_func100010_aluc1: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100010) |-> (aluc == 5'd1)
    );

// func 100100 -> aluc 2
    check_op001000_func100100_aluc2: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100100) |-> (aluc == 5'd2)
    );

// func 100101 -> aluc 3
    check_op001000_func100101_aluc3: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100101) |-> (aluc == 5'd3)
    );

// func 100110 -> aluc 4
    check_op001000_func100110_aluc4: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b100110) |-> (aluc == 5'd4)
    );

// func 101010 -> aluc 5
    check_op001000_func101010_aluc5: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b101010) |-> (aluc == 5'd5)
    );

// func 000000 -> aluc 6
    check_op001000_func000000_aluc6: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000000) |-> (aluc == 5'd6)
    );

// func 000100 -> aluc 7
    check_op001000_func000100_aluc7: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000100) |-> (aluc == 5'd7)
    );

// func 000011 -> aluc 8
    check_op001000_func000011_aluc8: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000011) |-> (aluc == 5'd8)
    );

// func 000111 -> aluc 9
    check_op001000_func000111_aluc9: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000111) |-> (aluc == 5'd9)
    );

// func 000110 -> aluc 11
    check_op001000_func000110_aluc11: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000110) |-> (aluc == 5'd11)
    );

// func 000001 -> aluc 12
    check_op001000_func000001_aluc12: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b000001) |-> (aluc == 5'd12)
    );

// func 011011 -> aluc 14
    check_op001000_func011011_aluc14: assert property (
        @(posedge CLK) disable iff (!RESETn) (op == 6'b001000 && func == 6'b011011) |-> (aluc == 5'd14)
    );

// For op==001000 and any func not listed in the case items, aluc must be 0 (inner default).
    check_op001000_default_other_funcs_aluc0: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (op == 6'b001000 && !(func inside {6'b100000,6'b100010,6'b100100,6'b100101,6'b100110,6'b101010,6'b000000,6'b000100,6'b000011,6'b000111,6'b000010,6'b000110,6'b000001,6'b011011})) |-> (aluc == 5'd0)
    );

///// Functional mapping /////
    // When sel==00, out equals in0.
    select_00_routes_in0: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == in0)
    );

// When sel==01, out equals in1.
    select_01_routes_in1: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == in1)
    );

// When sel==10, out equals in2.
    select_10_routes_in2: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == in2)
    );

// When sel==11, out equals in3.
    select_11_routes_in3: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == in3)
    );

///// Functional correctness /////
    // When A equals B, Z must be HIGH.
    check_z_high_when_equal: assert property (
        @(posedge CLK) disable iff (1'b0) (A == B) |-> (Z == 1'b1)
    );

// When A is greater than B, Z must be HIGH.
    check_z_high_when_greater: assert property (
        @(posedge CLK) disable iff (1'b0) (A > B) |-> (Z == 1'b1)
    );

// When A is less than B, Z must be LOW.
    check_z_low_when_less: assert property (
        @(posedge CLK) disable iff (1'b0) (A < B) |-> (Z == 1'b0)
    );

// SCD=1 at a negedge forces next Q=0 and Q_N=1 (highest priority).
    check_scd_forces_q0: assert property (
        @(negedge CLK_N) (SCD == 1'b1) |=> (Q == 1'b0) && (Q_N == 1'b1)
    );

// With SCD=0 and SCE=1 at a negedge, next Q=1 and Q_N=0.
    check_sce_forces_q1: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b1) |=> (Q == 1'b1) && (Q_N == 1'b0)
    );

// With SCD=0, SCE=0, and SET_B=0 at a negedge, next Q=1 and Q_N=0.
    check_setb_low_forces_q1: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b0) |=> (Q == 1'b1) && (Q_N == 1'b0)
    );

// With SCD=0, SCE=0, SET_B=1, and RESET_B=0 at a negedge, next Q=0 and Q_N=1.
    check_resetb_low_forces_q0: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b1) && (RESET_B == 1'b0) |=> (Q == 1'b0) && (Q_N == 1'b1)
    );

// With no control active at a negedge, next Q follows prior D and Q_N is its inverse.
    check_default_loads_d: assert property (
        @(negedge CLK_N) (SCD == 1'b0) && (SCE == 1'b0) && (SET_B == 1'b1) && (RESET_B == 1'b1) |=> (Q == $past(D)) && (Q_N == ~$past(D))
    );

// After any negedge update, Q_N is the bitwise complement of Q.
    check_outputs_complement_each_cycle: assert property (
        @(negedge CLK_N) 1'b1 |=> (Q_N == ~Q)
    );

// X equals A XOR B when A rises.
    check_x_equals_a_xor_b_on_posedge_A: assert property (
        @(posedge A) X === (A ^ B)
    );

// X equals A XOR B when B rises.
    check_x_equals_a_xor_b_on_posedge_B: assert property (
        @(posedge B) X === (A ^ B)
    );

// (X XOR B) equals A when A rises.
    check_x_xor_b_equals_a_on_posedge_A: assert property (
        @(posedge A) (X ^ B) === A
    );

// (X XOR A) equals B when B rises.
    check_x_xor_a_equals_b_on_posedge_B: assert property (
        @(posedge B) (X ^ A) === B
    );

// Clock: posedge clk. Reset: rst (active-high, async). Sequential: Z registered; Z<=0 on reset else Z<=A*B.

    // While reset is held across consecutive clock edges, Z must be 0.
    check_zero_while_reset_held: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (Z == 16'd0)
    );

// After any cycle where reset is asserted, Z must be 0 on the next clock edge.
    check_reset_assert_drives_zero_next: assert property (
        @(posedge clk) rst |=> (Z == 16'd0)
    );

// On the cycle reset deasserts, Z must still be 0 (was forced by reset in the prior cycle).
    check_zero_on_reset_release_edge: assert property (
        @(posedge clk) $fell(rst) |-> (Z == 16'd0)
    );

// While reset remains asserted across cycles, Z does not change.
    check_zero_stable_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (Z == $past(Z))
    );

// F=0 for 00000
    check_map_00000_is_0: assert property (
