    check_map_10111_is_1: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b10111) |-> (F == 1'b1)
    );

// F=0 for 10110
    check_map_10110_is_0: assert property (
        @(posedge clk) ({A,B,C,D,E} == 5'b10110) |-> (F == 1'b0)
    );

