    );

// in == 9 -> out = 0010000
    check_decode_out_9: assert property (
        @(posedge clk) (in == 4'h9) |=> (out == 7'b0010000)
    );

// in == A -> out = 0001000
    check_decode_out_A: assert property (
        @(posedge clk) (in == 4'hA) |=> (out == 7'b0001000)
    );

// in == B -> out = 0000011
    check_decode_out_B: assert property (
        @(posedge clk) (in == 4'hB) |=> (out == 7'b0000011)
    );

// in == C -> out = 1000110
    check_decode_out_C: assert property (
        @(posedge clk) (in == 4'hC) |=> (out == 7'b1000110)
    );

// in == D -> out = 0100001
    check_decode_out_D: assert property (
        @(posedge clk) (in == 4'hD) |=> (out == 7'b0100001)
    );

// in == E -> out = 0000110
    check_decode_out_E: assert property (
        @(posedge clk) (in == 4'hE) |=> (out == 7'b0000110)
    );

// in == F -> out = 0001110
    check_decode_out_F: assert property (
        @(posedge clk) (in == 4'hF) |=> (out == 7'b0001110)
    );

// F=0 when ABCD=0000
    check_map_0000: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b0000) |-> (F == 1'b0)
    );

// F=1 when ABCD=0001
    check_map_0001: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b0001) |-> (F == 1'b1)
    );

// F=1 when ABCD=0010
    check_map_0010: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b0010) |-> (F == 1'b1)
    );

// F=0 when ABCD=0011
    check_map_0011: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b0011) |-> (F == 1'b0)
    );

// F=1 when ABCD=0100
    check_map_0100: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b0100) |-> (F == 1'b1)
    );

// F=0 when ABCD=0101
    check_map_0101: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b0101) |-> (F == 1'b0)
    );

// F=0 when ABCD=0110
    check_map_0110: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b0110) |-> (F == 1'b0)
    );

// F=1 when ABCD=0111
    check_map_0111: assert property (
