// F=1 when ABCD=1001
    check_map_1001: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1001) |-> (F == 1'b1)
    );

// F=1 when ABCD=1010
    check_map_1010: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1010) |-> (F == 1'b1)
    );

// F=0 when ABCD=1011
    check_map_1011: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1011) |-> (F == 1'b0)
    );

// F=0 when ABCD=1100
    check_map_1100: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1100) |-> (F == 1'b0)
    );

// F=1 when ABCD=1101
    check_map_1101: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1101) |-> (F == 1'b1)
    );

// F=1 when ABCD=1110
    check_map_1110: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1110) |-> (F == 1'b1)
    );

// F=0 when ABCD=1111
    check_map_1111: assert property (
        @(posedge CLK) disable iff (1'b0) ({A,B,C,D} == 4'b1111) |-> (F == 1'b0)
    );

// Synchronous reset drives count to 0 in the same cycle it is asserted.
    reset_clears_now: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// Ver=0 maps to 7-seg 000_0001
    check_decode_0: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h0) |-> (Salida7seg == 7'b000_0001)
    );

// Ver=1 maps to 7-seg 100_1111
    check_decode_1: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h1) |-> (Salida7seg == 7'b100_1111)
    );

// Ver=2 maps to 7-seg 001_0010
    check_decode_2: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h2) |-> (Salida7seg == 7'b001_0010)
    );

// Ver=3 maps to 7-seg 000_0110
    check_decode_3: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h3) |-> (Salida7seg == 7'b000_0110)
    );

// Ver=4 maps to 7-seg 100_1100
    check_decode_4: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h4) |-> (Salida7seg == 7'b100_1100)
    );

// Ver=5 maps to 7-seg 010_0100
    check_decode_5: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h5) |-> (Salida7seg == 7'b010_0100)
    );

// Ver=6 maps to 7-seg 010_0000
    check_decode_6: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h6) |-> (Salida7seg == 7'b010_0000)
    );

// Ver=7 maps to 7-seg 000_1111
    check_decode_7: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h7) |-> (Salida7seg == 7'b000_1111)
    );

// Ver=8 maps to 7-seg 000_0000
    check_decode_8: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h8) |-> (Salida7seg == 7'b000_0000)
    );

// Ver=9 maps to 7-seg 000_0100
    check_decode_9: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'h9) |-> (Salida7seg == 7'b000_0100)
    );

// Ver=10 maps to 7-seg 000_1000
    check_decode_A: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'hA) |-> (Salida7seg == 7'b000_1000)
    );

// Ver=11 maps to 7-seg 110_0000
    check_decode_b: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'hB) |-> (Salida7seg == 7'b110_0000)
    );

// Ver=12 maps to 7-seg 011_0001
    check_decode_C: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'hC) |-> (Salida7seg == 7'b011_0001)
    );

// Ver=13 maps to 7-seg 100_0012 (note: 0010 in RTL)
    check_decode_d: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'hD) |-> (Salida7seg == 7'b100_0010)
    );

// Ver=14 maps to 7-seg 011_0000
    check_decode_E: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'hE) |-> (Salida7seg == 7'b011_0000)
    );

// Ver=15 maps to 7-seg 011_1000
    check_decode_F: assert property (
        @(posedge clk) disable iff (1'b0) (Ver == 4'hF) |-> (Salida7seg == 7'b011_1000)
    );

// No clock or reset in RTL; purely combinational 4:1 mux built from 2:1 muxes.
    // Assertions sampled on CLK; no reset used in disable iff.

    // Y equals A when S1=0 and S0=0.
    select_00_y_eq_a: assert property (
        @(posedge CLK) disable iff (1'b0) (!S1 && !S0) |-> (Y == A)
    );

// Y equals B when S1=0 and S0=1.
    select_01_y_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (!S1 && S0) |-> (Y == B)
    );

// Y equals C when S1=1 and S0=0.
    select_10_y_eq_c: assert property (
        @(posedge CLK) disable iff (1'b0) (S1 && !S0) |-> (Y == C)
    );

// Y equals D when S1=1 and S0=1.
    select_11_y_eq_d: assert property (
        @(posedge CLK) disable iff (1'b0) (S1 && S0) |-> (Y == D)
    );

// Y matches the full nested ternary of a 4:1 mux.
    y_matches_function: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == (S1 ? (S0 ? D : C) : (S0 ? B : A)))
    );

// When S1=0, output selects m1_out.
    y_follows_m1_when_s1_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!S1) |-> (Y == m1_out)
    );

// When S1=1, output selects m2_out.
    y_follows_m2_when_s1_high: assert property (
        @(posedge CLK) disable iff (1'b0) (S1) |-> (Y == m2_out)
    );

// When S0=0, m1_out=A and m2_out=C.
    m1_m2_selects_when_s0_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!S0) |-> ((m1_out == A) && (m2_out == C))
    );

// When S0=1, m1_out=B and m2_out=D.
    m1_m2_selects_when_s0_high: assert property (
        @(posedge CLK) disable iff (1'b0) (S0) |-> ((m1_out == B) && (m2_out == D))
    );

///// Functional correctness /////
    // When ctrl==00, out equals in.
    check_ctrl_00_passthrough: assert property (
        @(posedge CLK) (ctrl == 2'b00) |-> (out == in)
    );

// When ctrl==01, out equals bitwise NOT of in.
    check_ctrl_01_invert: assert property (
        @(posedge CLK) (ctrl == 2'b01) |-> (out == ~in)
    );

// When ctrl==10, out equals in shifted left by 2 with zeros in LSBs.
    check_ctrl_10_shift_left2: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (out == {in[13:0], 2'b00})
    );

// When ctrl==11, out equals in shifted right by 2 with zeros in MSBs.
    check_ctrl_11_shift_right2: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (out == {2'b00, in[15:2]})
    );

// Out matches the selected transformation for all ctrl values.
    check_functional_mapping: assert property (
        @(posedge CLK)
            out ==
                ((ctrl == 2'b00) ? in :
                 (ctrl == 2'b01) ? ~in :
                 (ctrl == 2'b10) ? {in[13:0], 2'b00} :
                                   {2'b00, in[15:2]})
    );

///// Bit-level implications /////
    // For shift-left (10), LSBs of out are zero.
    check_shift_left2_lsb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (out[1:0] == 2'b00)
    );

// For shift-right (11), MSBs of out are zero.
    check_shift_right2_msb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (out[15:14] == 2'b00)
    );

// For shift-left (10), out[15:2] equals in[13:0].
    check_shift_left2_upper_bits: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (out[15:2] == in[13:0])
    );

// For shift-right (11), out[13:0] equals in[15:2].
    check_shift_right2_lower_bits: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (out[13:0] == in[15:2])
    );

// While reset is LOW, result must be zero.
  reset_level_forces_zero: assert property (
    @(posedge clk) (reset == 1'b0) |-> (result == 4'b0000)
  );

// On the first clock after reset deasserts (LOW->HIGH), result is still zero.
  first_clk_after_reset_release_zero: assert property (
    @(posedge clk) (reset == 1'b1) && ($past(reset) == 1'b0) |-> (result == 4'b0000)
  );

// With op=0, next result is (A+B) LSBs from the previous cycle.
  update_sum_when_op0: assert property (
    @(posedge clk) disable iff (!reset)
      $past(reset) && ($past(operation) == 1'b0)
      |-> (result == (($past(A) + $past(B)) & 4'hF))
  );

// With op=1, next result is (A-B) LSBs from the previous cycle.
  update_diff_when_op1: assert property (
    @(posedge clk) disable iff (!reset)
      $past(reset) && ($past(operation) == 1'b1)
      |-> (result == (($past(A) - $past(B)) & 4'hF))
  );

// Start does not update elapsed_time.
    start_does_not_update_elapsed: assert property (
        @(posedge clk) start |=> (elapsed_time == $past(elapsed_time))
    );

// Forward1: M stage has priority when address matches
    fwd1_from_m_when_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (reg_write_m && (reg_write_adr_m == reg_read_adr1_e)) |-> (forward1_e == 2'h1)
    );

// Forward1: W stage selected only if M does not match and W matches
    fwd1_from_w_when_no_m_but_w_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr1_e)) &&
          (reg_write_w && (reg_write_adr_w == reg_read_adr1_e))) |-> (forward1_e == 2'h2)
    );

// Forward1: No match in M or W yields no forwarding
    fwd1_none_when_no_matches: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr1_e)) &&
         ! (reg_write_w && (reg_write_adr_w == reg_read_adr1_e))) |-> (forward1_e == 2'h0)
    );

// Forward1: Encoding is limited to 0/1/2
    fwd1_encoding_valid: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (forward1_e != 2'h3)
    );

// Forward2: M stage has priority when address matches
    fwd2_from_m_when_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (reg_write_m && (reg_write_adr_m == reg_read_adr2_e)) |-> (forward2_e == 2'h1)
    );

// Forward2: W stage selected only if M does not match and W matches
    fwd2_from_w_when_no_m_but_w_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr2_e)) &&
          (reg_write_w && (reg_write_adr_w == reg_read_adr2_e))) |-> (forward2_e == 2'h2)
    );

// Forward2: No match in M or W yields no forwarding
    fwd2_none_when_no_matches: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr2_e)) &&
         ! (reg_write_w && (reg_write_adr_w == reg_read_adr2_e))) |-> (forward2_e == 2'h0)
    );

// Forward2: Encoding is limited to 0/1/2
    fwd2_encoding_valid: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (forward2_e != 2'h3)
    );

// Stalls: stall_f equals stall_d
    stalls_equal: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (stall_f == stall_d)
    );

// Stalls: stall_d equals flush_e
    stall_equals_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (stall_d == flush_e)
    );

// Flush D: flush_d mirrors PC_source
    flush_d_equals_PC_source: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (flush_d == PC_source)
    );

// No hazard on D sources -> no stall/flush_e regardless of mem_to_reg_e
    no_hazard_results_no_stall_or_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!((reg_write_adr_e == reg_read_adr1_d) || (reg_write_adr_e == reg_read_adr2_d))) |-> 
            (stall_f == 1'b0 && stall_d == 1'b0 && flush_e == 1'b0)
    );

// Hazard on D sources with mem_to_reg_e -> assert stall_f/stall_d/flush_e
    hazard_and_memtoreg_cause_stall_and_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        (mem_to_reg_e && ((reg_write_adr_e == reg_read_adr1_d) || (reg_write_adr_e == reg_read_adr2_d))) |-> 
            (stall_f == 1'b1 && stall_d == 1'b1 && flush_e == 1'b1)
    );

// If mem_to_reg_e is 0 then stall_f/stall_d/flush_e must be 0
    memtoreg_low_clears_stall_and_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!mem_to_reg_e) |-> (stall_f == 1'b0 && stall_d == 1'b0 && flush_e == 1'b0)
    );

// Notes: DUT is pure combinational 4:1 MUX; no reset present. Assertions are sampled on external clk.

    // When select == 2'b00, out must equal data0.
    check_sel00_out_data0: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b00) |-> (out == data0)
    );

// When select == 2'b01, out must equal data1.
    check_sel01_out_data1: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b01) |-> (out == data1)
    );

// When select == 2'b10, out must equal data2.
    check_sel10_out_data2: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b10) |-> (out == data2)
    );

// When select == 2'b11, out must equal data3.
    check_sel11_out_data3: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b11) |-> (out == data3)
    );

// With select[1]==0, out equals 2:1 mux of data0/data1 selected by select[0].
    check_lower_branch_mux: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput[1] === 1'b0) |-> (out == ((selectinput[0] == 1'b0) ? data0 : data1))
    );

// With select[1]==1, out equals 2:1 mux of data2/data3 selected by select[0].
    check_upper_branch_mux: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput[1] === 1'b1) |-> (out == ((selectinput[0] == 1'b0) ? data2 : data3))
    );

// Out equals the exact nested conditional structure implemented in RTL.
    check_full_mux_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            out == ((selectinput[1] == 1'b0)
                      ? ((selectinput[0] == 1'b0) ? data0 : data1)
                      : ((selectinput[0] == 1'b0) ? data2 : data3))
    );

// difference implements 8-bit subtraction A - B
    check_difference_function: assert property (
        @(posedge clk) difference == (A - B)
    );

// When A equals B, the difference is zero
    check_zero_when_equal: assert property (
        @(posedge clk) (A == B) |-> (difference == 8'h00)
    );

// When B is zero, the difference equals A
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 8'h00) |-> (difference == A)
    );

// When A is zero, the difference equals two's complement of B
    check_a_zero_twos_complement: assert property (
        @(posedge clk) (A == 8'h00) |-> (difference == (~B + 8'h01))
    );

// Subtracting 8'hFF equals adding 1 (mod 256)
    check_sub_ff_is_inc: assert property (
        @(posedge clk) (B == 8'hFF) |-> (difference == (A + 8'h01))
    );

// (A - B) + B recovers A (mod 256)
    check_add_back_b_recovers_a: assert property (
        @(posedge clk) (difference + B) == A
    );

// A - (A - B) recovers B (mod 256)
    check_reverse_sub_recovers_b: assert property (
        @(posedge clk) (A - difference) == B
    );

// During active-low reset, data_stand is driven to zero.
    check_reset_drives_zero: assert property (
        @(posedge clock_50) !reset_n |-> (data_stand == 14'd0)
    );

// After reset release, data_stand stays zero until the first cycle with clock_recovery HIGH.
    check_zero_until_first_cr_after_reset_release: assert property (
        @(posedge clock_50) disable iff (!reset_n) $rose(reset_n) |-> (data_stand == 14'd0) until (clock_recovery)
    );

// No clock or reset in RTL; purely combinational; function: out = ~in + 1'b1 (4-bit two's complement).

    // out equals bitwise-not(in) plus 1 each cycle.
    check_twos_function: assert property (
        @(posedge clk) out == (~in + 1'b1)
    );

// Two's complement is an involution: ~out + 1 equals in.
    check_involution: assert property (
        @(posedge clk) (~out + 1'b1) == in
    );

// Sum of in and out is zero modulo 16.
    check_sum_zero_mod16: assert property (
        @(posedge clk) (in + out) == 4'h0
    );

// Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'h0) |-> (out == 4'h0)
    );

// Zero output implies zero input (bijectivity at zero).
    check_zero_out_implies_zero_in: assert property (
        @(posedge clk) (out == 4'h0) |-> (in == 4'h0)
    );

// 8 is a fixed point in 4-bit two's complement.
    check_eight_fixed_point: assert property (
        @(posedge clk) (in == 4'h8) |-> (out == 4'h8)
    );

// LSB is preserved by two's complement.
    check_lsb_preserved: assert property (
        @(posedge clk) out[0] == in[0]
    );

// If in equals out, it must be 0 or 8.
    check_fixed_points_only_0_or_8: assert property (
        @(posedge clk) (in == out) |-> ((in == 4'h0) || (in == 4'h8))
    );

// Corner case: -1 (0xF) maps to +1 (0x1).
    check_F_to_1: assert property (
        @(posedge clk) (in == 4'hF) |-> (out == 4'h1)
    );

// Corner case: +1 (0x1) maps to -1 (0xF).
    check_1_to_F: assert property (
        @(posedge clk) (in == 4'h1) |-> (out == 4'hF)
    );

// X equals A & B every cycle.
    check_and_equivalence: assert property (
        @(posedge clk) X == (A & B)
    );

// If X is HIGH, both A and B are HIGH in the same cycle.
    x_high_implies_inputs_high: assert property (
        @(posedge clk) X |-> (A & B)
    );

// If any input is LOW, X must be LOW in the same cycle.
    input_low_forces_x_low: assert property (
        @(posedge clk) (!A || !B) |-> (X == 1'b0)
    );

// X can only rise when both inputs are HIGH.
    x_rise_requires_inputs_high: assert property (
        @(posedge clk) $rose(X) |-> (A & B)
    );

// X can only fall when at least one input is LOW.
    x_fall_requires_any_input_low: assert property (
        @(posedge clk) $fell(X) |-> (!A || !B)
    );

///// Bitwise mapping checks /////
    // G[0] must equal A[0].
    check_g0_map: assert property (
        @(posedge clk) G[0] == A[0]
    );

// G[1] must equal A[0] ^ A[1].
    check_g1_map: assert property (
        @(posedge clk) G[1] == (A[0] ^ A[1])
    );

// G[2] must equal A[1] ^ A[2].
    check_g2_map: assert property (
        @(posedge clk) G[2] == (A[1] ^ A[2])
    );

// G[3] must equal A[2] ^ A[3].
    check_g3_map: assert property (
        @(posedge clk) G[3] == (A[2] ^ A[3])
    );

// G must equal {A2^A3, A1^A2, A0^A1, A0}.
    check_vector_map: assert property (
        @(posedge clk) G == { (A[2]^A[3]), (A[1]^A[2]), (A[0]^A[1]), A[0] }
    );

// Outputs implement exact decoding function: EN ? (1 << {A,B}) : 0
    check_decode_function_vector: assert property (
        @(posedge clk) {Y3,Y2,Y1,Y0} == (EN ? (4'b0001 << {A,B}) : 4'b0000)
    );

// When disabled, all outputs are 0
    check_disabled_all_zero: assert property (
        @(posedge clk) (EN == 1'b0) |-> ({Y3,Y2,Y1,Y0} == 4'b0000)
    );

// When EN and AB==00, Y0=1 and others 0
    check_decode_00: assert property (
        @(posedge clk) (EN && (A==1'b0) && (B==1'b0)) |-> (Y0 && !Y1 && !Y2 && !Y3)
    );

// When EN and AB==01, Y1=1 and others 0
    check_decode_01: assert property (
        @(posedge clk) (EN && (A==1'b0) && (B==1'b1)) |-> (!Y0 && Y1 && !Y2 && !Y3)
    );

// When EN and AB==10, Y2=1 and others 0
    check_decode_10: assert property (
        @(posedge clk) (EN && (A==1'b1) && (B==1'b0)) |-> (!Y0 && !Y1 && Y2 && !Y3)
    );

// When EN and AB==11, Y3=1 and others 0
    check_decode_11: assert property (
        @(posedge clk) (EN && (A==1'b1) && (B==1'b1)) |-> (!Y0 && !Y1 && !Y2 && Y3)
    );

// At most one output is HIGH at any time (onehot0)
    check_outputs_onehot0: assert property (
        @(posedge clk) $onehot0({Y3,Y2,Y1,Y0})
    );

// The OR of outputs equals EN
    check_outputs_or_equals_en: assert property (
        @(posedge clk) ((Y0 || Y1 || Y2 || Y3) == EN)
    );

// If Y0 is HIGH, decoder must be enabled and AB==00
    check_y0_implies_en_ab00: assert property (
        @(posedge clk) Y0 |-> (EN && (A==1'b0) && (B==1'b0))
    );

// If Y3 is HIGH, decoder must be enabled and AB==11
    check_y3_implies_en_ab11: assert property (
        @(posedge clk) Y3 |-> (EN && (A==1'b1) && (B==1'b1))
    );

// While reset is asserted (active-low), Y must be 0 at each clock edge.
  reset_drives_Y_low: assert property (
    @(posedge CLK) !RST |-> (Y == 1'b0)
  );

// Out of reset, Y equals the previous cycle's A & B.
  y_equals_past_and: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) |-> (Y == $past(A & B))
  );

// If previous cycle had A=1 and B=1, then Y must be 1 this cycle.
  y1_when_prev_inputs_11: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && $past(A) && $past(B) |-> (Y == 1'b1)
  );

// If previous cycle had A=0 (regardless of B), then Y must be 0 this cycle.
  y0_when_prev_A0: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && ($past(A) == 1'b0) |-> (Y == 1'b0)
  );

// If previous cycle had B=0 (regardless of A), then Y must be 0 this cycle.
  y0_when_prev_B0: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && ($past(B) == 1'b0) |-> (Y == 1'b0)
  );

// A rising Y implies previous cycle's (A & B) was 1.
  y_rise_implies_prev_and1: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && $rose(Y) |-> ($past(A & B) == 1'b1)
  );

// A falling Y implies previous cycle's (A & B) was 0.
  y_fall_implies_prev_and0: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST) && $fell(Y) |-> ($past(A & B) == 1'b0)
  );

// If (A & B) was stable over the last two cycles, Y must equal its previous value.
  y_stable_when_inputs_stable: assert property (
    @(posedge CLK) disable iff (!RST) $past(RST,2) && ($past(A & B,2) == $past(A & B,1)) |-> (Y == $past(Y))
  );

// Synchronous reset forces state to S0.
  reset_forces_S0: assert property (
    @(posedge clock) reset |-> (state == S0)
  );

// Lights are mutually exclusive (no two ON simultaneously).
  check_lights_mutex: assert property (
    @(posedge clock) disable iff (reset) !(green_light && yellow_light) && !(green_light && red_light) && !(yellow_light && red_light)
  );

// C never encodes 2'b11.
    check_c_never_11: assert property (
        @(posedge CLK) C != 2'b11
    );

// If A == B then C == 2'b00.
    check_eq_implies_c00: assert property (
        @(posedge CLK) (A == B) |-> (C == 2'b00)
    );

// If C == 2'b00 then A == B.
    check_c00_implies_eq: assert property (
        @(posedge CLK) (C == 2'b00) |-> (A == B)
    );

// If A > B then C == 2'b01.
    check_gt_implies_c01: assert property (
        @(posedge CLK) (A > B) |-> (C == 2'b01)
    );

// If C == 2'b01 then A > B.
    check_c01_implies_gt: assert property (
        @(posedge CLK) (C == 2'b01) |-> (A > B)
    );

// If A < B then C == 2'b10.
    check_lt_implies_c10: assert property (
        @(posedge CLK) (A < B) |-> (C == 2'b10)
    );

// If C == 2'b10 then A < B.
    check_c10_implies_lt: assert property (
        @(posedge CLK) (C == 2'b10) |-> (A < B)
    );

// aluc is always within 0..14 per decode table.
    check_aluc_range: assert property (
        @(posedge clk) (aluc <= 5'd14)
    );

///// R-type (op == 6'b000000) /////
    // R-type func 100000 maps to 0.
    map_op0_func_100000_to_0: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100000) |-> (aluc == 5'd0)
    );

// R-type func 100001 maps to 1.
    map_op0_func_100001_to_1: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100001) |-> (aluc == 5'd1)
    );

// R-type func 100010 maps to 2.
    map_op0_func_100010_to_2: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100010) |-> (aluc == 5'd2)
    );

// R-type func 100011 maps to 3.
    map_op0_func_100011_to_3: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100011) |-> (aluc == 5'd3)
    );

// R-type func 100100 maps to 4.
    map_op0_func_100100_to_4: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100100) |-> (aluc == 5'd4)
    );

// R-type func 100101 maps to 5.
    map_op0_func_100101_to_5: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100101) |-> (aluc == 5'd5)
    );

// R-type func 100110 maps to 6.
    map_op0_func_100110_to_6: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100110) |-> (aluc == 5'd6)
    );

// R-type func 100111 maps to 7.
    map_op0_func_100111_to_7: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b100111) |-> (aluc == 5'd7)
    );

// R-type func 101010 maps to 8.
    map_op0_func_101010_to_8: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b101010) |-> (aluc == 5'd8)
    );

// R-type func 101011 maps to 9.
    map_op0_func_101011_to_9: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b101011) |-> (aluc == 5'd9)
    );

// R-type func 000000 maps to 10.
    map_op0_func_000000_to_10: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000000) |-> (aluc == 5'd10)
    );

// R-type func 000010 maps to 11.
    map_op0_func_000010_to_11: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000010) |-> (aluc == 5'd11)
    );

// R-type func 000011 maps to 12.
    map_op0_func_000011_to_12: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000011) |-> (aluc == 5'd12)
    );

// R-type func 000100 maps to 10.
    map_op0_func_000100_to_10: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000100) |-> (aluc == 5'd10)
    );

// R-type func 000110 maps to 11.
    map_op0_func_000110_to_11: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000110) |-> (aluc == 5'd11)
    );

// R-type func 000111 maps to 12.
    map_op0_func_000111_to_12: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000111) |-> (aluc == 5'd12)
    );

// R-type func 000001 maps to 13.
    map_op0_func_000001_to_13: assert property (
        @(posedge clk) (op == 6'b000000 && func == 6'b000001) |-> (aluc == 5'd13)
    );

///// I-type (op != 6'b000000) /////
    // I-type op 001000 maps to 0.
    map_op_001000_to_0: assert property (
        @(posedge clk) (op == 6'b001000) |-> (aluc == 5'd0)
    );

// I-type op 001001 maps to 1.
    map_op_001001_to_1: assert property (
        @(posedge clk) (op == 6'b001001) |-> (aluc == 5'd1)
    );

// I-type op 001100 maps to 4.
    map_op_001100_to_4: assert property (
        @(posedge clk) (op == 6'b001100) |-> (aluc == 5'd4)
    );

// I-type op 001101 maps to 5.
    map_op_001101_to_5: assert property (
        @(posedge clk) (op == 6'b001101) |-> (aluc == 5'd5)
    );

// I-type op 001110 maps to 6.
    map_op_001110_to_6: assert property (
        @(posedge clk) (op == 6'b001110) |-> (aluc == 5'd6)
    );

// I-type op 001010 maps to 8.
    map_op_001010_to_8: assert property (
        @(posedge clk) (op == 6'b001010) |-> (aluc == 5'd8)
    );

// I-type op 001011 maps to 9.
    map_op_001011_to_9: assert property (
        @(posedge clk) (op == 6'b001011) |-> (aluc == 5'd9)
    );

// I-type op 001111 maps to 14.
    map_op_001111_to_14: assert property (
        @(posedge clk) (op == 6'b001111) |-> (aluc == 5'd14)
    );

// I-type default (unlisted op and not R-type) maps to 0.
    map_default_other_ops_to_0: assert property (
        @(posedge clk) ((op != 6'b000000) && !(op inside {
            6'b001000,6'b001001,6'b001100,6'b001101,6'b001110,6'b001010,6'b001011,6'b001111
        })) |-> (aluc == 5'd0)
    );

// line==000 maps to 1110
    map_line_000_to_1110: assert property (
        @(posedge clk) (line == 3'b000) |-> (pixels == 4'b1110)
    );

// line==001 maps to 1010
    map_line_001_to_1010: assert property (
        @(posedge clk) (line == 3'b001) |-> (pixels == 4'b1010)
    );

// line==010 maps to 1010
    map_line_010_to_1010: assert property (
        @(posedge clk) (line == 3'b010) |-> (pixels == 4'b1010)
    );

// line==011 maps to 1010
    map_line_011_to_1010: assert property (
        @(posedge clk) (line == 3'b011) |-> (pixels == 4'b1010)
    );

// line==100 maps to 1110
    map_line_100_to_1110: assert property (
        @(posedge clk) (line == 3'b100) |-> (pixels == 4'b1110)
    );

// line in 101/110/111 maps to 0000 (default)
    map_default_high_lines_to_0000: assert property (
        @(posedge clk) (line inside {3'b101,3'b110,3'b111}) |-> (pixels == 4'b0000)
    );

// Pixels are only one of the three encoded patterns
    pixels_only_expected_values: assert property (
        @(posedge clk) (pixels inside {4'b1110,4'b1010,4'b0000})
    );

// LSB of pixels is always 0
    pixel0_always_zero: assert property (
        @(posedge clk) (pixels[0] == 1'b0)
    );

// Non-default lines produce non-zero pixels
    nonzero_when_specified_line: assert property (
        @(posedge clk) (line inside {3'b000,3'b001,3'b010,3'b011,3'b100}) |-> (pixels != 4'b0000)
    );

// Zero pixels imply default lines (101/110/111)
    zero_pixels_implies_default_lines: assert property (
        @(posedge clk) (pixels == 4'b0000) |-> (line inside {3'b101,3'b110,3'b111})
    );

// 1110 pixels only for lines 000 or 100
    code_1110_implies_end_lines: assert property (
        @(posedge clk) (pixels == 4'b1110) |-> (line == 3'b000 || line == 3'b100)
    );

// 1010 pixels only for lines 001..011
    code_1010_implies_mid_lines: assert property (
        @(posedge clk) (pixels == 4'b1010) |-> (line inside {[3'b001:3'b011]})
    );

// On reset high, next Q is cleared to 0.
    reset_clears_Q: assert property (
        @(posedge clk) reset |=> (Q == 4'b0000)
    );

// When load is high (and not in reset), next Q equals D.
    load_writes_D: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(D))
    );

// When counting up without wrap (Q != 15) and no load, next Q = Q + 1.
    increment_when_up_no_wrap: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (Q != 4'hF)) |=> (Q == ($past(Q) + 4'd1))
    );

// When counting down without wrap (Q != 0) and no load, next Q = Q - 1.
    decrement_when_down_no_wrap: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (Q != 4'h0)) |=> (Q == ($past(Q) - 4'd1))
    );

// Counting up from 15 wraps to 0 when no load.
    wrap_on_increment_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Counting down from 0 wraps to 15 when no load.
    wrap_on_decrement_from_min: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Exact next-state function when not in reset.
    next_state_function: assert property (
        @(posedge clk) disable iff (reset)
            1'b1 |=> Q == ($past(load)
                           ? $past(D)
                           : ($past(up_down)
                              ? (($past(Q) == 4'hF) ? 4'h0 : ($past(Q) + 4'd1))
                              : (($past(Q) == 4'h0) ? 4'hF : ($past(Q) - 4'd1))))
    );

// When counting (no load), Q always changes next cycle.
    count_changes_without_load: assert property (
        @(posedge clk) disable iff (reset) (!load) |=> (Q != $past(Q))
    );

// OR function holds on A rising edge.
    check_or_eq_on_posA: assert property (
        @(posedge A) X == (A | B)
    );

// OR function holds on A falling edge.
    check_or_eq_on_negA: assert property (
        @(negedge A) X == (A | B)
    );

// OR function holds on B rising edge.
    check_or_eq_on_posB: assert property (
        @(posedge B) X == (A | B)
    );

// OR function holds on B falling edge.
    check_or_eq_on_negB: assert property (
        @(negedge B) X == (A | B)
    );

// OR function holds on X rising edge.
    check_or_eq_on_posX: assert property (
        @(posedge X) X == (A | B)
    );

// OR function holds on X falling edge.
    check_or_eq_on_negX: assert property (
        @(negedge X) X == (A | B)
    );

// Reset drives count to 0 on the clock edge while reset is asserted.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// Y equals the 3-input NAND of A, B, C (including X/Z semantics).
    check_nand3_function: assert property (
        @(posedge clk) (Y === ~(A & B & C))
    );

// Y is LOW only when all inputs are HIGH.
    check_y0_only_when_all_high: assert property (
        @(posedge clk) (Y === 1'b0) |-> (A === 1'b1 && B === 1'b1 && C === 1'b1)
    );

// Y HIGH implies at least one input is LOW.
    check_y1_implies_any_zero: assert property (
        @(posedge clk) (Y === 1'b1) |-> (A === 1'b0 || B === 1'b0 || C === 1'b0)
    );

// A LOW forces Y HIGH regardless of other inputs.
    check_a_zero_forces_y_one: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// B LOW forces Y HIGH regardless of other inputs.
    check_b_zero_forces_y_one: assert property (
        @(posedge clk) (B === 1'b0) |-> (Y === 1'b1)
    );

// C LOW forces Y HIGH regardless of other inputs.
    check_c_zero_forces_y_one: assert property (
        @(posedge clk) (C === 1'b0) |-> (Y === 1'b1)
    );

// With all inputs known (0/1), Y must be known (not X/Z).
    check_known_inputs_imply_known_y: assert property (
        @(posedge clk) (! $isunknown({A,B,C})) |-> (! $isunknown(Y))
    );

// Y is never high-impedance (buf is not tri-statable).
    check_y_never_z: assert property (
        @(posedge clk) (Y !== 1'bz)
    );

// No clock/reset in RTL; pure combinational: w0 = A1|A2; O = ~((A1|A2) & B).

    // O equals ~((A1|A2) & B) on A1 rising edge.
    check_func_eq_on_A1_rise: assert property (
        @(posedge A1) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on A1 falling edge.
    check_func_eq_on_A1_fall: assert property (
        @(negedge A1) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on A2 rising edge.
    check_func_eq_on_A2_rise: assert property (
        @(posedge A2) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on A2 falling edge.
    check_func_eq_on_A2_fall: assert property (
        @(negedge A2) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on B rising edge.
    check_func_eq_on_B_rise: assert property (
        @(posedge B) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on B falling edge.
    check_func_eq_on_B_fall: assert property (
        @(negedge B) O == ~((A1 | A2) & B)
    );

// If B is LOW, O must be HIGH (checked on A1 rising edge).
    check_B0_forces_O1_on_A1_rise: assert property (
        @(posedge A1) (B == 1'b0) |-> (O == 1'b1)
    );

// If B is LOW, O must be HIGH (checked on A2 rising edge).
    check_B0_forces_O1_on_A2_rise: assert property (
        @(posedge A2) (B == 1'b0) |-> (O == 1'b1)
    );

// If O is LOW when B is HIGH, at least one of A1/A2 must be HIGH (checked on B rising edge).
    check_O_low_requires_A1_or_A2_when_B_high: assert property (
        @(posedge B) (O == 1'b0) |-> ((A1 == 1'b1) || (A2 == 1'b1))
    );

// For known select values (no X/Z), output equals the selected input bit.
    pass_through_known_select: assert property (
        @(posedge clk) !$isunknown(select) |=> (data_out === data_in[select])
    );

// If select contains X/Z, default branch drives output LOW.
    default_on_unknown_select: assert property (
        @(posedge clk) $isunknown(select) |=> (data_out === 1'b0)
    );

// Gray vector matches combinational mapping from bin.
    check_gray_vector_mapping: assert property (
        @(posedge CLK) gray == { bin[3], (bin[3] ^ bin[2]), (bin[2] ^ bin[1]), (bin[1] ^ bin[0]) }
    );

// MSB maps directly.
    check_gray_bit3_mapping: assert property (
        @(posedge CLK) gray[3] == bin[3]
    );

// Next bit is XOR of bin[3] and bin[2].
    check_gray_bit2_mapping: assert property (
        @(posedge CLK) gray[2] == (bin[3] ^ bin[2])
    );

// Next bit is XOR of bin[2] and bin[1].
    check_gray_bit1_mapping: assert property (
        @(posedge CLK) gray[1] == (bin[2] ^ bin[1])
    );

// LSB is XOR of bin[1] and bin[0].
    check_gray_bit0_mapping: assert property (
        @(posedge CLK) gray[0] == (bin[1] ^ bin[0])
    );

// When reset is asserted LOW at a clock edge, q must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !rst |-> (q == 4'h0)
    );

// On reset deassertion (LOW->HIGH) at a clock edge, q moves from 0 to 1.
    check_q_is_one_on_reset_release: assert property (
        @(posedge clk) $rose(rst) |-> (q == 4'h1)
    );

// If previous q was 0xF and reset is HIGH at consecutive edges, q is 0 (normal wrap) or 1 (reset glitch then increment).
    check_wrap_or_reset_after_prev_F: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) && ($past(q) == 4'hF) && rst |-> (q == 4'h0) || (q == 4'h1)
    );

// When out of reset at consecutive edges, q==0 can only come from previous q==0xF.
    check_zero_only_after_prev_F: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) && rst && (q == 4'h0) |-> ($past(q) == 4'hF)
    );

// When out of reset at consecutive edges, q cannot remain 0xF.
    check_no_F_repeat_without_reset: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) && rst && ($past(q) == 4'hF) |-> (q != 4'hF)
    );

// Clock: clk (posedge). No reset present in RTL.
  // Logic: mixed — result is combinational; overflow is registered each clk.

  ///// Result computation /////
  // When op==0, result equals a + b (combinational).
  result_add_correct: assert property (
    @(posedge clk) (op == 1'b0) |-> (result == (a + b))
  );

// When op==1, result equals a - b (combinational).
  result_sub_correct: assert property (
    @(posedge clk) (op == 1'b1) |-> (result == (a - b))
  );

///// Overflow computation (registered) /////
  // On the next cycle, overflow must be 1 when the RTL's overflow condition holds.
  overflow_set_when_condition: assert property (
    @(posedge clk)
      (
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b1)
  );

// On the next cycle, overflow must be 0 when the RTL's overflow condition does not hold.
  overflow_clear_when_not_condition: assert property (
    @(posedge clk)
      !(
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b0)
  );

// After the first cycle, overflow is always a known 0/1 (registered each clk).
  overflow_binary_after_first_cycle: assert property (
    @(posedge clk) $past(1'b1) |-> (overflow inside {1'b0, 1'b1})
  );

// If reset is 1 on this edge, out must be 0 on the next edge.
    check_reset_clears_out_next: assert property (
        @(posedge CLK) reset |=> (out == 4'd0)
    );

// If not in reset for two consecutive cycles, out equals in1+in2 from the prior cycle.
    check_sum_update_two_cycle_nonreset: assert property (
        @(posedge CLK) disable iff (reset) (!reset ##1 !reset) |-> (out == $past(in1 + in2))
    );

// No reset in RTL; pure combinational logic; assertions are sampled on clk.
  // Behavior: mode=1 -> result=A+B; mode=0 -> result=A+(~B+1) == A-B.

  // In add mode, result equals A + B (4-bit signed wrap-around).
  check_add_mode_is_sum: assert property (
    @(posedge clk) mode |-> (result == $signed(A + B))
  );

// In sub mode, result equals A + two's complement of B (4-bit).
  check_sub_mode_is_A_plus_twoscompB: assert property (
    @(posedge clk) !mode |-> (result == $signed(A + ((~B) + 4'd1)))
  );

// In sub mode, result equals A - B (equivalent form).
  check_sub_mode_is_difference: assert property (
    @(posedge clk) !mode |-> (result == $signed(A - B))
  );

// If B is zero, result passes A in both modes.
  check_B_zero_passthrough: assert property (
    @(posedge clk) (B == 4'sd0) |-> (result == A)
  );

// In add mode with A=0, result equals B.
  check_add_mode_A_zero: assert property (
    @(posedge clk) (mode && (A == 4'sd0)) |-> (result == B)
  );

// In sub mode with A=0, result equals -B (two's complement).
  check_sub_mode_A_zero: assert property (
    @(posedge clk) (!mode && (A == 4'sd0)) |-> (result == $signed(-B))
  );

// In sub mode with A==B, result is zero.
  check_sub_mode_equal_operands_zero: assert property (
    @(posedge clk) (!mode && (A == B)) |-> (result == 4'sd0)
  );

// In add mode with B == -A, result is zero.
  check_add_mode_negated_operands_zero: assert property (
    @(posedge clk) (mode && (B == $signed(-A))) |-> (result == 4'sd0)
  );

// In add mode, result - A equals B (mod-16 arithmetic).
  check_add_mode_invertibility: assert property (
    @(posedge clk) mode |-> ($signed(result - A) == B)
  );

// Internal and_result equals bitwise A & B.
    check_and_result_bitwise_and: assert property (
        @(posedge CLK) disable iff (1'b0) and_result == (A & B)
    );

// Output equals AND-reduction of internal and_result.
    check_output_equals_reduction_of_internal: assert property (
        @(posedge CLK) disable iff (1'b0) output_signal == (&and_result)
    );

// Output equals AND-reduction across bitwise pairs A & B.
    check_output_equals_and_of_pairs: assert property (
        @(posedge CLK) disable iff (1'b0) output_signal == &(A & B)
    );

// If output is 1, then all bits of A and B are 1.
    check_output_one_implies_all_ones: assert property (
        @(posedge CLK) disable iff (1'b0) output_signal |-> ((&A) && (&B))
    );

// If all bits of A and B are 1, then output is 1.
    check_all_ones_implies_output_one: assert property (
        @(posedge CLK) disable iff (1'b0) ((&A) && (&B)) |-> (output_signal == 1'b1)
    );

// If any bit of A is 0, output must be 0.
    check_any_zero_in_A_forces_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (~&A) |-> (output_signal == 1'b0)
    );

// If any bit of B is 0, output must be 0.
    check_any_zero_in_B_forces_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (~&B) |-> (output_signal == 1'b0)
    );

// Output equals bitwise AND of inputs at every sample.
    check_out_equals_and: assert property (
        @(posedge clk) out == (a & b)
    );

// Output high implies both inputs are high.
    check_out_high_implies_inputs_high: assert property (
        @(posedge clk) out |-> (a & b)
    );

// If input a is 0, output must be 0.
    check_zero_a_forces_zero_out: assert property (
        @(posedge clk) !a |-> !out
    );

// If input b is 0, output must be 0.
    check_zero_b_forces_zero_out: assert property (
        @(posedge clk) !b |-> !out
    );

// If input a is 1, output equals b.
    check_a_one_equals_b: assert property (
        @(posedge clk) a |-> (out == b)
    );

// If input b is 1, output equals a.
    check_b_one_equals_a: assert property (
        @(posedge clk) b |-> (out == a)
    );

// If both inputs are 1, output must be 1.
    check_both_one_outputs_one: assert property (
        @(posedge clk) (a & b) |-> out
    );

// MSB generate alone forces Cout high.
    check_cout_from_msb_generate: assert property (
        @(posedge clk)
        (A[3] & B[3]) |-> Cout
    );

// Propagating the derived bit-2 carry through bit 3 forces Cout high.
    check_cout_from_msb_propagate: assert property (
        @(posedge clk)
        (
            ((A[2] & B[2]) |
             (((A[1] & B[1]) |
               (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1]))) & (A[2] | B[2])))
            &
            (A[3] | B[3])
        ) |-> Cout
    );

// The extra lower-carry term in the RTL also forces Cout high.
    check_cout_from_lower_carry_term: assert property (
        @(posedge clk)
        (
            ((A[1] & B[1]) |
             (((A[0] & B[0]) | (Cin & (A[0] | B[0]))) & (A[1] | B[1])))
            &
            ((A[0] & B[0]) | (Cin & (A[0] | B[0])))
        ) |-> Cout
    );

// HI matches pwrgood_pp AND pullup0_out.
    check_hi_definition: assert property (
        @(posedge clk) HI == (pwrgood_pp & pullup0_out)
    );

// LO matches inverted pwrgood_pp AND inverted pulldown0_out.
    check_lo_definition: assert property (
        @(posedge clk) LO == ((~pwrgood_pp) & (~pulldown0_out))
    );

// HI can only be high when pwrgood_pp is high.
    check_hi_requires_pwrgood: assert property (
        @(posedge clk) HI |-> pwrgood_pp
    );

// HI can only be high when pullup0_out is high.
    check_hi_requires_pullup: assert property (
        @(posedge clk) HI |-> pullup0_out
    );

// LO can only be high when pwrgood_pp is low.
    check_lo_requires_no_pwrgood: assert property (
        @(posedge clk) LO |-> ~pwrgood_pp
    );

// LO can only be high when pulldown0_out is low.
    check_lo_requires_no_pulldown: assert property (
        @(posedge clk) LO |-> ~pulldown0_out
    );

// pwrgood_pp low forces HI low.
    check_no_pwrgood_forces_hi_low: assert property (
        @(posedge clk) ~pwrgood_pp |-> ~HI
    );

// pwrgood_pp high forces LO low.
    check_pwrgood_forces_lo_low: assert property (
        @(posedge clk) pwrgood_pp |-> ~LO
    );

// pulldown0_out high forces LO low.
    check_pulldown_high_forces_lo_low: assert property (
        @(posedge clk) pulldown0_out |-> ~LO
    );

// HI and LO cannot be high together.
    check_hi_lo_mutex: assert property (
        @(posedge clk) !(HI & LO)
    );

// Reset clears count on the next clock, regardless of load or enable.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// Load updates count with load_value on the next clock when not in reset.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(load_value))
    );

// Enable increments count by one on the next clock when load is low.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        (!load && enable) |=> (count == ($past(count) + 4'd1))
    );

// Count holds its value when neither load nor enable is asserted.
    check_count_holds_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !enable) |=> (count == $past(count))
    );

// Load has priority over enable when both are asserted together.
    check_load_has_priority_over_enable: assert property (
        @(posedge clk) disable iff (reset)
        (load && enable) |=> (count == $past(load_value))
    );

// A 4-bit increment wraps from 15 back to 0.
    check_enable_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Active-low reset forces the counter output to zero.
    check_reset_clears_output: assert property (
        @(posedge clock)
        !reset |-> (data_out == '0)
    );

// A sampled reset cycle leaves the next sampled output at zero.
    check_reset_keeps_output_zero_next_cycle: assert property (
        @(posedge clock)
        !reset |=> (data_out == '0)
    );

// When enabled and load is high, the next output reflects the prior input unless reset intervened.
    check_load_updates_output: assert property (
        @(posedge clock) disable iff (!reset)
        (enable && load) |=> ((data_out == $past(data_in)) || (data_out == '0))
    );

// When enabled and load is low, the next output increments unless reset intervened.
    check_enable_increments_output: assert property (
        @(posedge clock) disable iff (!reset)
        (enable && !load) |=> ((data_out == ($past(data_out) + {{(DataSize-1){1'b0}}, 1'b1})) || (data_out == '0))
    );

// When enable is low, the output holds its value unless reset intervened.
    check_disable_holds_output: assert property (
        @(posedge clock) disable iff (!reset)
        (!enable) |=> ((data_out == $past(data_out)) || (data_out == '0))
    );

// Load is ignored when enable is low.
    check_load_ignored_when_disabled: assert property (
        @(posedge clock) disable iff (!reset)
        (!enable && load) |=> ((data_out == $past(data_out)) || (data_out == '0))
    );

// S[0] matches the RTL XOR of A[0], B[0], and Cin.
    check_sum_bit0_function: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// S[1] matches the RTL function using S[0] and Cin.
    check_sum_bit1_function: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (S[0] & Cin))
    );

// S[2] matches the RTL function using S[1] and S[0].
    check_sum_bit2_function: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (S[1] & S[0]))
    );

// S[3] matches the RTL function using S[2] and S[1].
    check_sum_bit3_function: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (S[2] & S[1]))
    );

// Cout matches the RTL expression built from the sum bits and Cin.
    check_cout_function: assert property (
        @(posedge clk) Cout == ((S[3] & S[2]) | (S[3] & S[1]) | (S[2] & S[1] & Cin))
    );

// Exact implemented mapping from in to pos.
    check_pos_matches_implemented_logic: assert property (
        @(posedge clk) pos == (((!in[3]) && in[2]) ? 2'b01 : 2'b00)
    );

// If in[3] is set, the output falls through to 00.
    check_in3_forces_pos00: assert property (
        @(posedge clk) in[3] |-> (pos == 2'b00)
    );

// If in[2] is the highest active bit, the output is 01.
    check_in2_maps_to_pos01: assert property (
        @(posedge clk) (!in[3] && in[2]) |-> (pos == 2'b01)
    );

// If in[1] is the highest active bit, the output is 00.
    check_in1_maps_to_pos00: assert property (
        @(posedge clk) (!in[3] && !in[2] && in[1]) |-> (pos == 2'b00)
    );

// If only in[0] can be selected, the output is 00.
    check_in0_maps_to_pos00: assert property (
        @(posedge clk) (!in[3] && !in[2] && !in[1] && in[0]) |-> (pos == 2'b00)
    );

// With no asserted inputs, the output defaults to 00.
    check_no_input_defaults_to_pos00: assert property (
        @(posedge clk) (in == 4'b0000) |-> (pos == 2'b00)
    );

// The implemented logic never produces 10 or 11.
    check_pos_is_limited_to_00_or_01: assert property (
        @(posedge clk) ((pos == 2'b00) || (pos == 2'b01))
    );

// Output 01 can only come from bit 2 winning the chain.
    check_pos01_has_unique_cause: assert property (
        @(posedge clk) (pos == 2'b01) |-> (!in[3] && in[2])
    );

// Valid Arduino selections drive the corresponding input bit.
        check_arduino_selected_pin: assert property (
            @(posedge clk) (sel <= 5'h13) |-> (out_int == in_pin[sel])
        );

// Unmapped Arduino selections drive zero.
        check_arduino_default_zero: assert property (
            @(posedge clk) (sel > 5'h13) |-> (out_int == 1'b0)
        );

// Y implements the 4-input AND of A, B, C, and D.
    check_output_matches_and: assert property (
        @(posedge clk) Y == (A && B && C && D)
    );

// All four inputs high drives Y high.
    check_all_high_implies_y_high: assert property (
        @(posedge clk) (A && B && C && D) |-> Y
    );

// Y can be high only when all four inputs are high.
    check_y_high_requires_all_high: assert property (
        @(posedge clk) Y |-> (A && B && C && D)
    );

// Any low input forces Y low.
    check_any_low_implies_y_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !Y
    );

// A rising Y edge requires all four inputs to be high.
    check_y_rise_requires_all_high: assert property (
        @(posedge clk) $rose(Y) |-> (A && B && C && D)
    );

// A falling Y edge requires at least one input to be low.
    check_y_fall_requires_low_input: assert property (
        @(posedge clk) $fell(Y) |-> (!A || !B || !C || !D)
    );

// When CLK is low, the gated output must be low.
    check_low_phase_output_low: assert property (
        @(posedge CLK) ENCLK == 1'b0
    );

// During CLK high, the gated output must equal EN & ~TE.
    check_high_phase_function: assert property (
        @(negedge CLK) ENCLK == (EN & ~TE)
    );

// If enable is low, the gated output must be low during CLK high.
    check_enable_low_blocks_output: assert property (
        @(negedge CLK) !EN |-> (ENCLK == 1'b0)
    );

// If test enable is high, the gated output must be low during CLK high.
    check_test_enable_blocks_output: assert property (
        @(negedge CLK) TE |-> (ENCLK == 1'b0)
    );

// If enabled and not in test mode, the gated output must be high during CLK high.
    check_enabled_non_test_passes_clock: assert property (
        @(negedge CLK) (EN && !TE) |-> (ENCLK == 1'b1)
    );

// A sampled reset cycle clears the output by the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) !reset_n |=> (out_data == 32'd0)
    );

// When disabled, the registered output holds its prior value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!enable) |=> (out_data == $past(out_data))
    );

// AND opcode writes in_data & in_data on the next clock.
    check_and_operation: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (op_select == 3'b000)) |=> (out_data == $past(in_data & in_data))
    );

// OR opcode writes in_data | in_data on the next clock.
    check_or_operation: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (op_select == 3'b001)) |=> (out_data == $past(in_data | in_data))
    );

// XOR opcode writes in_data ^ in_data on the next clock.
    check_xor_operation: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (op_select == 3'b010)) |=> (out_data == $past(in_data ^ in_data))
    );

// NOT opcode writes ~in_data on the next clock.
    check_not_operation: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (op_select == 3'b011)) |=> (out_data == $past(~in_data))
    );

// ADD opcode writes in_data + in_data on the next clock.
    check_add_operation: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (op_select == 3'b100)) |=> (out_data == $past(in_data + in_data))
    );

// SUB opcode writes in_data - in_data on the next clock.
    check_sub_operation: assert property (
        @(posedge clk) disable iff (!reset_n)
        (enable && (op_select == 3'b101)) |=> (out_data == $past(in_data - in_data))
    );

// End-to-end behavior is an inversion of the input.
    check_out_inverts_input: assert property (
        @(posedge clk) out == ~in
    );

// Out must match the 2:1 mux Boolean equation.
    check_mux_equation: assert property (
        @(posedge clk) out == ((~sel & in0) | (sel & in1))
    );

// When sel is LOW, out must follow in0.
    check_selects_in0: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == in0)
    );

// When sel is HIGH, out must follow in1.
    check_selects_in1: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == in1)
    );

// If both inputs are LOW, out must be LOW.
    check_both_inputs_low: assert property (
        @(posedge clk) ((in0 == 1'b0) && (in1 == 1'b0)) |-> (out == 1'b0)
    );

// If both inputs are HIGH, out must be HIGH.
    check_both_inputs_high: assert property (
        @(posedge clk) ((in0 == 1'b1) && (in1 == 1'b1)) |-> (out == 1'b1)
    );

// With in0 LOW and in1 HIGH, out must equal sel.
    check_output_equals_sel_for_01: assert property (
        @(posedge clk) ((in0 == 1'b0) && (in1 == 1'b1)) |-> (out == sel)
    );

// With in0 HIGH and in1 LOW, out must equal inverse of sel.
    check_output_equals_not_sel_for_10: assert property (
        @(posedge clk) ((in0 == 1'b1) && (in1 == 1'b0)) |-> (out == ~sel)
    );

// Sequential 4-bit counter on clk with active-low reset rst_n.

    // Active-low reset forces q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk)
        (!rst_n) |-> (q == 4'b0000)
    );

// q holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!enable) |=> (q == $past(q))
    );

// q increments by one when enabled and counting up.
    check_increment_when_enabled_up: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && count_up) |=> (q == ($past(q) + 4'd1))
    );

// q decrements by one when enabled and counting down.
    check_decrement_when_enabled_down: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && !count_up) |=> (q == ($past(q) - 4'd1))
    );

// Counting up wraps from 15 to 0.
    check_wrap_up_from_max: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && count_up && (q == 4'hF)) |=> (q == 4'h0)
    );

// Counting down wraps from 0 to 15.
    check_wrap_down_from_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
        (enable && !count_up && (q == 4'h0)) |=> (q == 4'hF)
    );

// A sampled reset leaves all three stages at INIT_VALUE on the next clock.
    check_reset_clears_all_stages_next_clock: assert property (
        @(posedge target_clk)
        reset |=> (signal_meta == INIT_VALUE) &&
                  (signal_d == INIT_VALUE) &&
                  (output_signal == INIT_VALUE)
    );

// The first stage captures input_signal on the next target clock.
    check_signal_meta_captures_input: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> (signal_meta == $past(input_signal))
    );

// The second stage captures signal_meta on the next target clock.
    check_signal_d_captures_signal_meta: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> (signal_d == $past(signal_meta))
    );

// The output stage captures signal_d on the next target clock.
    check_output_captures_signal_d: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> (output_signal == $past(signal_d))
    );

// input_signal reaches signal_d after two target clocks.
    check_signal_d_matches_input_after_two_clocks: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> ##1 (signal_d == $past(input_signal, 2))
    );

// input_signal reaches output_signal after three target clocks.
    check_output_matches_input_after_three_clocks: assert property (
        @(posedge target_clk) disable iff (reset)
        1'b1 |=> ##2 (output_signal == $past(input_signal, 3))
    );

// signal_d stays at INIT_VALUE for two clocks after a reset sample.
    check_signal_d_stays_init_two_clocks_after_reset: assert property (
        @(posedge target_clk)
        reset |=> (signal_d == INIT_VALUE) ##1 (signal_d == INIT_VALUE)
    );

// output_signal stays at INIT_VALUE for three clocks after a reset sample.
    check_output_stays_init_three_clocks_after_reset: assert property (
        @(posedge target_clk)
        reset |=> (output_signal == INIT_VALUE) ##1
                  (output_signal == INIT_VALUE) ##1
                  (output_signal == INIT_VALUE)
    );

// gray_out[2] passes through the binary MSB.
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_out[2] == bin_in[2]
    );

// gray_out[1] is the XOR of bin_in[2] and bin_in[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_out[1] == (bin_in[2] ^ bin_in[1])
    );

// gray_out[0] is the XOR of bin_in[1] and bin_in[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray_out[0] == (bin_in[1] ^ bin_in[0])
    );

// The full output matches the implemented binary-to-Gray conversion.
    check_gray_vector_conversion: assert property (
        @(posedge clk) gray_out == {bin_in[2], (bin_in[2] ^ bin_in[1]), (bin_in[1] ^ bin_in[0])}
    );

// The Gray output reconstructs the original binary input.
    check_gray_inverse_reconstruction: assert property (
        @(posedge clk) bin_in == {gray_out[2], (gray_out[2] ^ gray_out[1]), (gray_out[2] ^ gray_out[1] ^ gray_out[0])}
    );

// Reset drives the register output to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) !not_reset |-> (Q == 8'h00)
    );

// When loading, the next sampled value is D or zero if reset intervenes.
    check_load_captures_d_or_reset_zero: assert property (
        @(posedge clk) disable iff (!not_reset)
        Load |=> ((Q == $past(D)) || (Q == 8'h00))
    );

// Without loading, the next sampled value holds or becomes zero on reset.
    check_hold_preserves_q_or_reset_zero: assert property (
        @(posedge clk) disable iff (!not_reset)
        !Load |=> ((Q == $past(Q)) || (Q == 8'h00))
    );

// Loading an all-zero value produces an all-zero output.
    check_load_zero_updates_zero: assert property (
        @(posedge clk) disable iff (!not_reset)
        (Load && (D == 8'h00)) |=> (Q == 8'h00)
    );

// An all-zero output stays zero when no load occurs.
    check_zero_holds_without_load: assert property (
        @(posedge clk) disable iff (!not_reset)
        (!Load && (Q == 8'h00)) |=> (Q == 8'h00)
    );

// An all-ones state clears to all zeros on the next clock.
    check_all_ones_wraps_to_zero: assert property (
        @(posedge clk) (out == ALL_ONES) |=> (out == ALL_ZEROS)
    );

// An all-zero state remains all zero on the next clock.
    check_all_zero_holds: assert property (
        @(posedge clk) (out == ALL_ZEROS) |=> (out == ALL_ZEROS)
    );

// On non-wrap cycles, bit 0 takes the previous MSB.
            check_lsb_wraparound: assert property (
                @(posedge clk) (out != ALL_ONES) |=> (out[0] == $past(out[m-1]))
            );

// On non-wrap cycles, each upper bit takes the previous lower bit.
                check_shift_from_lower: assert property (
                    @(posedge clk) (out != ALL_ONES) |=> (out[i] == $past(out[i-1]))
                );

// On non-wrap cycles, each upper bit takes the previous lower bit.
                check_shift_from_lower: assert property (
                    @(posedge clk) (out != ALL_ONES) |=> (out[i] == $past(out[i-1]))
                );

// On non-wrap cycles, each upper bit takes the previous lower bit.
                check_shift_from_lower: assert property (
                    @(posedge clk) (out != ALL_ONES) |=> (out[i] == $past(out[i-1]))
                );

// Mode 00 left-shifts input and zero-fills the LSB.
    check_mode_shift_left: assert property (
        @(posedge clk) (mode == 2'b00) |-> (out == {in[2:0], 1'b0})
    );

// Mode 01 right-shifts input and zero-fills the MSB.
    check_mode_shift_right: assert property (
        @(posedge clk) (mode == 2'b01) |-> (out == {1'b0, in[3:1]})
    );

// Mode 10 bitwise-inverts the input.
    check_mode_invert: assert property (
        @(posedge clk) (mode == 2'b10) |-> (out == ~in)
    );

// Mode 11 passes the input through unchanged.
    check_mode_passthrough: assert property (
        @(posedge clk) (mode == 2'b11) |-> (out == in)
    );

// A sampled reset clears the counter by the next clock.
    check_counter_clears_after_reset: assert property (
        @(posedge clk) reset |=> (counter_out == 4'h0)
    );

// A sampled reset clears the stored input2, so sum matches input1 next cycle.
    check_sum_matches_input1_after_reset: assert property (
        @(posedge clk) reset |=> (sum == input1)
    );

// From any non-maximum value, the counter increments on the next active cycle.
    check_counter_increments_from_non_max: assert property (
        @(posedge clk) disable iff (reset)
        (counter_out != 4'hF) |=> (counter_out == ($past(counter_out) + 4'h1))
    );

// From 4'hF, the counter wraps to zero on the next active cycle.
    check_counter_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (counter_out == 4'hF) |=> (counter_out == 4'h0)
    );

// On active cycles, sum uses the current input1 and the previous cycle's input2.
    check_sum_uses_previous_input2: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (sum == (input1 + $past(input2)))
    );

// Active-low reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 4'b0000)
    );

// When load is high, count updates to the sampled data value.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!reset)
        load |=> (count == $past(data))
    );

// When load is low, count increments by one on the next cycle.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (!reset)
        !load |=> (count == ($past(count) + 4'd1))
    );

// Incrementing from 4'hF wraps the counter back to zero.
    check_wraps_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// X must equal the OR of A1/A2/A3 gated by B1.
    check_exact_boolean_function: assert property (
        @(posedge clk) X == ((A1 | A2 | A3) & B1)
    );

// When B1 is low, X must be low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// When all A inputs are low, X must be low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) !(A1 | A2 | A3) |-> !X
    );

// When B1 is high, X must match the OR of A1/A2/A3.
    check_b1_high_passes_or_result: assert property (
        @(posedge clk) B1 |-> (X == (A1 | A2 | A3))
    );

// A high X requires B1 to be high.
    check_x_high_requires_b1: assert property (
        @(posedge clk) X |-> B1
    );

// A high X requires at least one A input to be high.
    check_x_high_requires_or_input: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3)
    );

// A1 asserted with B1 high must drive X high.
    check_a1_path_to_x: assert property (
        @(posedge clk) (A1 & B1) |-> X
    );

// A2 asserted with B1 high must drive X high.
    check_a2_path_to_x: assert property (
        @(posedge clk) (A2 & B1) |-> X
    );

// A3 asserted with B1 high must drive X high.
    check_a3_path_to_x: assert property (
        @(posedge clk) (A3 & B1) |-> X
    );

// A reset cycle clears the counter to zero.
    check_reset_clears_counter: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

// Ebar is low only for the qualified decoded I/O access condition.
    check_ebar_low_on_qualified_access: assert property (
        @(posedge clk)
        ((A9 == 1'b1) & (A8 == 1'b1) & (AEN == 1'b0) & (F == 1'b1) & (IORbar != IOWbar)) |-> (Ebar == 1'b0)
    );

// Ebar is high whenever the qualified decoded I/O access condition is false.
    check_ebar_high_without_qualified_access: assert property (
        @(posedge clk)
        !((A9 == 1'b1) & (A8 == 1'b1) & (AEN == 1'b0) & (F == 1'b1) & (IORbar != IOWbar)) |-> (Ebar == 1'b1)
    );

// DIR is low only during an I/O read cycle.
    check_dir_low_on_read_cycle: assert property (
        @(posedge clk)
        ((IORbar == 1'b0) & (IOWbar == 1'b1)) |-> (DIR == 1'b0)
    );

// DIR is high for all non-read combinations of IORbar and IOWbar.
    check_dir_high_otherwise: assert property (
        @(posedge clk)
        !((IORbar == 1'b0) & (IOWbar == 1'b1)) |-> (DIR == 1'b1)
    );

// Address 00 selects CSbar[0] active low.
    check_csbar_decode_00: assert property (
        @(posedge clk)
        ((A3 == 1'b0) & (A2 == 1'b0)) |-> (CSbar == 4'b1110)
    );

// Address 01 selects CSbar[1] active low.
    check_csbar_decode_01: assert property (
        @(posedge clk)
        ((A3 == 1'b0) & (A2 == 1'b1)) |-> (CSbar == 4'b1101)
    );

// Address 10 selects CSbar[2] active low.
    check_csbar_decode_10: assert property (
        @(posedge clk)
        ((A3 == 1'b1) & (A2 == 1'b0)) |-> (CSbar == 4'b1011)
    );

// Address 11 selects CSbar[3] active low.
    check_csbar_decode_11: assert property (
        @(posedge clk)
        ((A3 == 1'b1) & (A2 == 1'b1)) |-> (CSbar == 4'b0111)
    );

// CSbar always has exactly one active-low chip select.
    check_csbar_one_active_low: assert property (
        @(posedge clk)
        $onehot(~CSbar)
    );

// Output must match the implemented ternary mux expression.
    check_mux_function: assert property (
        @(posedge clk) Y === ((S == 1'b0) ? A : B)
    );

// Select value 0 routes input A to the output.
    check_select_zero_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

// Select value 1 routes input B to the output.
    check_select_one_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

// Equal data inputs force the same value at the output.
    check_equal_inputs_propagate: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

// Reset drives the counter to zero on the following sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// Reset clears both internal stages.
    check_ff_out_reset: assert property (
        @(posedge clk) reset |=> (ff_out == 2'b00)
    );

// A high reset drives the counter to zero on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clock) reset |=> (out == 4'b0000)
    );

// On the first cycle after reset deasserts, the sampled counter value is zero.
    check_post_reset_zero: assert property (
        @(posedge clock) reset ##1 !reset |-> (out == 4'b0000)
    );

// When not at 4'hF, the counter increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clock) disable iff (reset)
        (out != 4'hF) |=> (out == ($past(out) + 4'd1))
    );

// When at 4'hF, the counter wraps back to zero on the next cycle.
    check_count_wraps: assert property (
        @(posedge clock) disable iff (reset)
        (out == 4'hF) |=> (out == 4'h0)
    );

// High enable drives all outputs high after the pipeline delay.
    check_enable_high_all_ones: assert property (
        @(posedge clk) en |-> ##2 (out == DEC_DISABLED)
    );

// Low enable with select 00 clears bit 0 after the pipeline delay.
    check_decode_select_00: assert property (
        @(posedge clk) (!en && (select == 2'b00)) |-> ##2 (out == DEC_SEL_00)
    );

// Low enable with select 01 clears bit 1 after the pipeline delay.
    check_decode_select_01: assert property (
        @(posedge clk) (!en && (select == 2'b01)) |-> ##2 (out == DEC_SEL_01)
    );

// Low enable with select 10 clears bit 2 after the pipeline delay.
    check_decode_select_10: assert property (
        @(posedge clk) (!en && (select == 2'b10)) |-> ##2 (out == DEC_SEL_10)
    );

// Low enable with select 11 clears bit 3 after the pipeline delay.
    check_decode_select_11: assert property (
        @(posedge clk) (!en && (select == 2'b11)) |-> ##2 (out == DEC_SEL_11)
    );

// The upper 12 output bits are always high once the pipeline response appears.
    check_upper_bits_always_high: assert property (
        @(posedge clk) 1'b1 |-> ##2 (out[15:4] == 12'hFFF)
    );

// Low enable produces exactly one active-low bit in the low nibble.
    check_low_enable_active_low_onehot: assert property (
        @(posedge clk) !en |-> ##2 ($onehot(~out[3:0]))
    );

// Output is always one of the RTL-assigned encodings after the pipeline delay.
    check_output_encoding_legal: assert property (
        @(posedge clk) 1'b1 |-> ##2 (
            (out == DEC_DISABLED) ||
            (out == DEC_SEL_00)   ||
            (out == DEC_SEL_01)   ||
            (out == DEC_SEL_10)   ||
            (out == DEC_SEL_11)
        )
    );

// inputs 0001 must produce encoder output 01.
    check_encoder_map_0001: assert property (
        @(posedge clk) disable iff (reset)
        (inputs == 4'b0001) |-> (priority_encoder_output == 2'b01)
    );

// inputs 0010 must produce encoder output 10.
    check_encoder_map_0010: assert property (
        @(posedge clk) disable iff (reset)
        (inputs == 4'b0010) |-> (priority_encoder_output == 2'b10)
    );

// inputs 0100 must produce encoder output 11.
    check_encoder_map_0100: assert property (
        @(posedge clk) disable iff (reset)
        (inputs == 4'b0100) |-> (priority_encoder_output == 2'b11)
    );

// All other input patterns must produce encoder output 00.
    check_encoder_default_map: assert property (
        @(posedge clk) disable iff (reset)
        !(inputs == 4'b0001 || inputs == 4'b0010 || inputs == 4'b0100) |-> (priority_encoder_output == 2'b00)
    );

// A reset on this clock edge clears Q on the following sampled cycle.
    check_counter_reset_clears_q: assert property (
        @(posedge clk)
        reset |=> (Q == 4'b0000)
    );

// When load is asserted out of reset, Q captures D.
    check_counter_load_captures_d: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (Q == $past(D))
    );

// When not loading and counting up, Q increments by one.
    check_counter_counts_up: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down) |=> (Q == ($past(Q) + 4'b0001))
    );

// When not loading and counting down, Q decrements by one.
    check_counter_counts_down: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down) |=> (Q == ($past(Q) - 4'b0001))
    );

// Reset clears the stored output and therefore the readback value.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> (out_port == 1'b0) && (readdata == 1'b0)
    );

// Address 0 reads back the stored output bit.
    check_read_addr0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == out_port)
    );

// Any nonzero address reads back zero.
    check_read_nonzero_addr_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 1'b0)
    );

// A selected write to address 0 updates the output on the next clock.
    check_write_addr0_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata))
    );

// Without a selected write to address 0, the output register holds its value.
    check_no_target_write_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

// Writes to nonzero addresses do not modify the output register.
    check_nonzero_address_write_is_ignored: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

// Active-high synchronous reset clears Q.
    check_reset_clears_q: assert property (
        @(posedge C) R |=> (Q == 1'b0)
    );

// With reset low, set forces Q high.
    check_set_sets_q: assert property (
        @(posedge C) disable iff (R) S |=> (Q == 1'b1)
    );

// With reset and set low, D=1 is loaded into Q.
    check_data_one_loads_q: assert property (
        @(posedge C) disable iff (R) (!S && D) |=> (Q == 1'b1)
    );

// With reset and set low, D=0 is loaded into Q.
    check_data_zero_loads_q: assert property (
        @(posedge C) disable iff (R) (!S && !D) |=> (Q == 1'b0)
    );

// The sampled output must always match the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk) out === ((ctrl == 1'b0) ? in0 : in1)
    );

// When control is low, the output selects in0.
    check_select_in0: assert property (
        @(posedge clk) (ctrl === 1'b0) |-> (out === in0)
    );

// When control is high, the output selects in1.
    check_select_in1: assert property (
        @(posedge clk) (ctrl === 1'b1) |-> (out === in1)
    );

// If both inputs are identical, the output must match that value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (in0 === in1) |-> (out === in0)
    );

// shift_left must implement A logically shifted left by B.
    check_shift_left_function: assert property (
        @(posedge clk) shift_left == (A << B)
    );

// shift_right must implement A logically shifted right by B.
    check_shift_right_function: assert property (
        @(posedge clk) shift_right == (A >> B)
    );

// A zero shift amount must pass A through on shift_left.
    check_shift_left_zero_amount: assert property (
        @(posedge clk) (B == 4'd0) |-> (shift_left == A)
    );

// A zero shift amount must pass A through on shift_right.
    check_shift_right_zero_amount: assert property (
        @(posedge clk) (B == 4'd0) |-> (shift_right == A)
    );

// Left shifts must zero-fill the vacated LSBs.
    check_shift_left_zero_fill: assert property (
        @(posedge clk) (B != 4'd0) |-> ((shift_left & ((16'h0001 << B) - 16'h0001)) == 16'h0000)
    );

// Right shifts must zero-fill the vacated MSBs.
    check_shift_right_zero_fill: assert property (
        @(posedge clk) (B != 4'd0) |-> ((shift_right & (16'hFFFF << (5'd16 - {1'b0, B}))) == 16'h0000)
    );

// A shift by 15 leaves only A[0] in the shift_left MSB.
    check_shift_left_max_amount: assert property (
        @(posedge clk) (B == 4'd15) |-> (shift_left == {A[0], 15'b0})
    );

// A shift by 15 leaves only A[15] in the shift_right LSB.
    check_shift_right_max_amount: assert property (
        @(posedge clk) (B == 4'd15) |-> (shift_right == {15'b0, A[15]})
    );

// Output must implement the 2:1 mux expression.
    check_mux_function: assert property (
        @(posedge clk) data_out == (select ? data_in_1 : data_in_0)
    );

// When select is low, output must follow data_in_0.
    check_select_low_path: assert property (
        @(posedge clk) !select |-> (data_out == data_in_0)
    );

// When select is high, output must follow data_in_1.
    check_select_high_path: assert property (
        @(posedge clk) select |-> (data_out == data_in_1)
    );

// If both inputs are equal, output must equal that shared value.
    check_equal_inputs_consistent_output: assert property (
        @(posedge clk) (data_in_0 == data_in_1) |-> (data_out == data_in_0)
    );

// Clock: clk; reset: active-low asynchronous reset; logic: sequential 3-bit up/down counter.

    // When reset is low, the counter must be at zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 3'b000)
    );

// When counting up, the next count increments by one modulo 8.
    check_count_up_step: assert property (
        @(posedge clk) disable iff (!reset)
        up_down |=> (count == ($past(count) + 3'd1))
    );

// When counting down, the next count decrements by one modulo 8.
    check_count_down_step: assert property (
        @(posedge clk) disable iff (!reset)
        !up_down |=> (count == ($past(count) - 3'd1))
    );

// Incrementing from the maximum value wraps to zero.
    check_up_wraps_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (up_down && (count == 3'b111)) |=> (count == 3'b000)
    );

// Decrementing from zero wraps to the maximum value.
    check_down_wraps_from_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (!up_down && (count == 3'b000)) |=> (count == 3'b111)
    );

// Outside reset, the counter changes on every clock edge.
    check_count_changes_each_cycle: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (count != $past(count))
    );

// Bit 2 sum must use the ripple carry generated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        Sum[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    (A[1] ^ B[1]) &
                    (
                        (A[0] & B[0]) |
                        ((A[0] ^ B[0]) & Cin)
                    )
                )
            )
        )
    );

// Bit 3 sum must use the ripple carry generated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        Sum[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (A[2] ^ B[2]) &
                    (
                        (A[1] & B[1]) |
                        (
                            (A[1] ^ B[1]) &
                            (
                                (A[0] & B[0]) |
                                ((A[0] ^ B[0]) & Cin)
                            )
                        )
                    )
                )
            )
        )
    );

// A sampled reset leaves the registered output cleared on the next clock.
    check_reset_next_cycle_zero: assert property (
        @(posedge clk)
        reset |=> (sum == 32'h00000000)
    );

// In mode 00, TX path enable or low CEB forces ODIV2 low.
            check_mode00_force_odiv2_low: assert property (
                @(posedge I) ((REFCLK_EN_TX_PATH == 1'b1) || (CEB == 1'b0)) |-> (ODIV2 == 1'b0)
            );

// Active-low reset drives readdata low.
    check_reset_low_drives_zero: assert property (
        @(posedge clk) (!reset_n) |-> (readdata == 32'h00000000)
    );

// A sampled reset low keeps readdata cleared into the next cycle.
    check_reset_low_keeps_zero_next_cycle: assert property (
        @(posedge clk) (!reset_n) |=> (readdata == 32'h00000000)
    );

// Address 00 with a low input writes zero on the next clock.
    check_addr00_low_writes_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((address === 2'b00) && (in_port === 1'b0)) |=> (readdata == 32'h00000000)
    );

// Address 01 writes zero on the next clock.
    check_addr01_writes_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address === 2'b01) |=> (readdata == 32'h00000000)
    );

// Address 10 writes zero on the next clock.
    check_addr10_writes_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address === 2'b10) |=> (readdata == 32'h00000000)
    );

// Address 11 writes zero on the next clock.
    check_addr11_writes_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address === 2'b11) |=> (readdata == 32'h00000000)
    );

// Every enabled write keeps the upper 31 bits cleared.
    check_next_readdata_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:1] == 31'b0)
    );

// When enabled, the next sampled Q equals the captured D.
    check_capture_when_enabled: assert property (
        @(posedge CLK) DE |=> (Q == $past(D))
    );

// When disabled, Q holds its previous sampled value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) !DE |=> (Q == $past(Q))
    );

// Any observed Q change requires DE high on the prior clock.
    check_change_requires_enable: assert property (
        @(posedge CLK) 1'b1 |=> ((Q != $past(Q)) |-> $past(DE))
    );

// Any observed Q change matches the prior sampled D.
    check_change_matches_captured_d: assert property (
        @(posedge CLK) 1'b1 |=> ((Q != $past(Q)) |-> (Q == $past(D)))
    );

// If enabled data already matches Q, Q stays unchanged.
    check_same_data_keeps_q: assert property (
        @(posedge CLK) DE && (D == Q) |=> (Q == $past(Q))
    );

// If enabled data differs from Q, Q updates to that data.
    check_new_data_updates_q: assert property (
        @(posedge CLK) DE && (D != Q) |=> ((Q == $past(D)) && (Q != $past(Q)))
    );

// Active-high reset must drive count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 3'b000)
    );

// When up_down is high, count increments on the next clock.
    check_increment_when_up_down_high: assert property (
        @(posedge clk) disable iff (reset)
        up_down |=> (count == ($past(count) + 3'b001))
    );

// When up_down is low, count decrements on the next clock.
    check_decrement_when_up_down_low: assert property (
        @(posedge clk) disable iff (reset)
        !up_down |=> (count == ($past(count) - 3'b001))
    );

// Incrementing from the maximum value wraps back to zero.
    check_wrap_increment_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (up_down && (count == 3'b111)) |=> (count == 3'b000)
    );

// Decrementing from zero wraps back to the maximum value.
    check_wrap_decrement_from_zero: assert property (
        @(posedge clk) disable iff (reset)
        (!up_down && (count == 3'b000)) |=> (count == 3'b111)
    );

// Combinational DUT with no RTL reset, sampled on an external clock.

    // Zero input produces the zero code.
    check_000_maps_to_000: assert property (
        @(posedge clk) (B_in == 3'b000) |-> (A_out == 3'b000)
    );

// Input 001 produces code 001.
    check_001_maps_to_001: assert property (
        @(posedge clk) (B_in == 3'b001) |-> (A_out == 3'b001)
    );

// Input 010 produces code 001.
    check_010_maps_to_001: assert property (
        @(posedge clk) (B_in == 3'b010) |-> (A_out == 3'b001)
    );

// Input 011 produces code 010.
    check_011_maps_to_010: assert property (
        @(posedge clk) (B_in == 3'b011) |-> (A_out == 3'b010)
    );

// Input 100 produces code 001.
    check_100_maps_to_001: assert property (
        @(posedge clk) (B_in == 3'b100) |-> (A_out == 3'b001)
    );

// Input 101 produces code 011.
    check_101_maps_to_011: assert property (
        @(posedge clk) (B_in == 3'b101) |-> (A_out == 3'b011)
    );

// Input 110 produces code 010.
    check_110_maps_to_010: assert property (
        @(posedge clk) (B_in == 3'b110) |-> (A_out == 3'b010)
    );

// Input 111 produces code 001.
    check_111_maps_to_001: assert property (
        @(posedge clk) (B_in == 3'b111) |-> (A_out == 3'b001)
    );

// The implemented encoder never drives the output MSB high.
    check_output_msb_is_zero: assert property (
        @(posedge clk) (A_out[2] == 1'b0)
    );

// A clock seen with reset active drives reset values by the next sample.
    check_reset_drives_outputs: assert property (
        @(posedge clk) !rst |=> ((q == 1'b0) && (q_n == 1'b1))
    );

// q captures d on the next active clock.
    check_q_captures_d: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (q == $past(d))
    );

// q_n captures the inverse of d on the next active clock.
    check_qn_captures_inverted_d: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (q_n == ~$past(d))
    );

// After any clock edge, q and q_n are complementary by the next sample.
    check_outputs_are_complements: assert property (
        @(posedge clk) 1'b1 |=> (q_n == ~q)
    );

// A sampled high d produces q high and q_n low on the next active clock.
    check_d_high_response: assert property (
        @(posedge clk) disable iff (!rst) d |=> ((q == 1'b1) && (q_n == 1'b0))
    );

// A sampled low d produces q low and q_n high on the next active clock.
    check_d_low_response: assert property (
        @(posedge clk) disable iff (!rst) !d |=> ((q == 1'b0) && (q_n == 1'b1))
    );

// Y must equal the 3-input NOR of A, B, and C.
    check_nor_equivalence: assert property (
        @(posedge clk) Y == ~(A | B | C)
    );

// If all inputs are low, Y must be high.
    check_all_inputs_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C) |-> Y
    );

// If any input is high, Y must be low.
    check_any_input_high_drives_y_low: assert property (
        @(posedge clk) (A || B || C) |-> !Y
    );

// A high Y implies all three inputs are low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C)
    );

// A low Y implies at least one input is high.
    check_y_low_implies_some_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C)
    );

// The upper four 32-bit words pass through unchanged.
    check_upper_words_passthrough: assert property (
        @(posedge clk) out_1[255:128] == in[255:128]
    );

// The first transformed lower word is k4 XOR S4(k3).
    check_k4_word_transform: assert property (
        @(posedge clk) out_1[127:96] == (in[127:96] ^ s4_fn(in[159:128]))
    );

// The second transformed lower word is k4 XOR k5 XOR S4(k3).
    check_k5_word_transform: assert property (
        @(posedge clk) out_1[95:64] == (in[127:96] ^ in[95:64] ^ s4_fn(in[159:128]))
    );

// The third transformed lower word is k4 XOR k5 XOR k6 XOR S4(k3).
    check_k6_word_transform: assert property (
        @(posedge clk) out_1[63:32] == (in[127:96] ^ in[95:64] ^ in[63:32] ^ s4_fn(in[159:128]))
    );

// The fourth transformed lower word is k4 XOR k5 XOR k6 XOR k7 XOR S4(k3).
    check_k7_word_transform: assert property (
        @(posedge clk) out_1[31:0] == (in[127:96] ^ in[95:64] ^ in[63:32] ^ in[31:0] ^ s4_fn(in[159:128]))
    );

// out_2 is the lower 128 bits of out_1.
    check_out2_matches_out1_lower_half: assert property (
        @(posedge clk) out_2 == out_1[127:0]
    );

// XORing the first two transformed lower words recovers k5.
    check_xor_recovers_k5: assert property (
        @(posedge clk) (out_1[127:96] ^ out_1[95:64]) == in[95:64]
    );

// XORing the next two transformed lower words recovers k6.
    check_xor_recovers_k6: assert property (
        @(posedge clk) (out_1[95:64] ^ out_1[63:32]) == in[63:32]
    );

// XORing the last two transformed lower words recovers k7.
    check_xor_recovers_k7: assert property (
        @(posedge clk) (out_1[63:32] ^ out_1[31:0]) == in[31:0]
    );

// Output is always the logical inverse of the input.
    check_output_is_inverse: assert property (
        @(posedge clk) disable iff (1'b0)
        (RESET_OUT === !RESET_IN)
    );

// Low input drives a high output.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) disable iff (1'b0)
        (RESET_IN === 1'b0) |-> (RESET_OUT === 1'b1)
    );

// High input drives a low output.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) disable iff (1'b0)
        (RESET_IN === 1'b1) |-> (RESET_OUT === 1'b0)
    );

// High output implies the input is low.
    check_high_output_means_low_input: assert property (
        @(posedge clk) disable iff (1'b0)
        (RESET_OUT === 1'b1) |-> (RESET_IN === 1'b0)
    );

// Low output implies the input is high.
    check_low_output_means_high_input: assert property (
        @(posedge clk) disable iff (1'b0)
        (RESET_OUT === 1'b0) |-> (RESET_IN === 1'b1)
    );

// LD has highest priority and loads a 1 on the next cycle.
    check_load_one: assert property (
        @(posedge CLK) (LD && IN_FLAG) |=> OUT_FLAG
    );

// LD has highest priority and loads a 0 on the next cycle.
    check_load_zero: assert property (
        @(posedge CLK) (LD && !IN_FLAG) |=> !OUT_FLAG
    );

// SET drives the flag high when LD is low.
    check_set_when_selected: assert property (
        @(posedge CLK) (!LD && SET) |=> OUT_FLAG
    );

// CLR drives the flag low when LD and SET are low.
    check_clear_when_selected: assert property (
        @(posedge CLK) (!LD && !SET && CLR) |=> !OUT_FLAG
    );

// With no control active, a high flag holds its value.
    check_hold_high: assert property (
        @(posedge CLK) (!LD && !SET && !CLR && OUT_FLAG) |=> OUT_FLAG
    );

// With no control active, a low flag holds its value.
    check_hold_low: assert property (
        @(posedge CLK) (!LD && !SET && !CLR && !OUT_FLAG) |=> !OUT_FLAG
    );

// X must match the implemented AO221 logic function.
    check_full_function: assert property (
        @(posedge clk) X === (((A1 & A2) | (B1 & B2)) | C1)
    );

// The A1/A2 product term must drive X high.
    check_a_term_drives_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// The B1/B2 product term must drive X high.
    check_b_term_drives_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// C1 must drive X high through the OR stage.
    check_c1_drives_high: assert property (
        @(posedge clk) C1 |-> X
    );

// If all three OR inputs are low, X must be low.
    check_no_term_drives_low: assert property (
        @(posedge clk) !(((A1 & A2) | (B1 & B2)) | C1) |-> !X
    );

// A low X means the A1/A2 product term is not asserted.
    check_x_low_implies_a_term_low: assert property (
        @(posedge clk) !X |-> !(A1 & A2)
    );

// A low X means the B1/B2 product term is not asserted.
    check_x_low_implies_b_term_low: assert property (
        @(posedge clk) !X |-> !(B1 & B2)
    );

// A low X means C1 is not asserted.
    check_x_low_implies_c1_low: assert property (
        @(posedge clk) !X |-> !C1
    );

// S low selects A.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

// S high selects B.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

// A selected path is reflected when A changes.
    check_selected_a_change_reflected: assert property (
        @(posedge clk) ($stable(S) && (S === 1'b0) && $changed(A)) |-> (Y === A)
    );

// B selected path is reflected when B changes.
    check_selected_b_change_reflected: assert property (
        @(posedge clk) ($stable(S) && (S === 1'b1) && $changed(B)) |-> (Y === B)
    );

// Rising select makes the output follow B.
    check_select_rise_routes_b: assert property (
        @(posedge clk) $rose(S) |-> (Y === B)
    );

// Falling select makes the output follow A.
    check_select_fall_routes_a: assert property (
        @(posedge clk) $fell(S) |-> (Y === A)
    );

// X matches the implemented OR/NAND/BUF boolean function.
    check_boolean_function: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A high forces X high.
    check_a_high_sets_output: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_high_sets_output: assert property (
        @(posedge clk) B |-> X
    );

// Low C_N forces X high through the NAND term.
    check_c_n_low_sets_output: assert property (
        @(posedge clk) !C_N |-> X
    );

// Low D_N forces X high through the NAND term.
    check_d_n_low_sets_output: assert property (
        @(posedge clk) !D_N |-> X
    );

// X low requires all OR inputs to be inactive.
    check_output_low_requires_all_inactive: assert property (
        @(posedge clk) !X |-> (!A && !B && C_N && D_N)
    );

// All inactive OR inputs produce a low X.
    check_all_inactive_gives_low: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> !X
    );

// Reset drives both state elements low.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        reset |-> (q == 16'b0) && (serial_out == 1'b0)
    );

// Load captures parallel_load and reports the previous MSB.
    check_load_updates_register: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (q == $past(parallel_load)) && (serial_out == $past(q[15]))
    );

// Shift-left moves q left with zero fill and reports the previous MSB.
    check_shift_left_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!load && shift_left) |=> (q == {$past(q[14:0]), 1'b0}) && (serial_out == $past(q[15]))
    );

// Shift-right moves q right with zero fill and reports the previous LSB.
    check_shift_right_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !shift_left && shift_right) |=> (q == {1'b0, $past(q[15:1])}) && (serial_out == $past(q[0]))
    );

// With no command, q holds its value and serial_out reflects the held MSB.
    check_idle_holds_register: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !shift_left && !shift_right) |=> (q == $past(q)) && (serial_out == $past(q[15]))
    );

// Load has priority over either shift request.
    check_load_priority_over_shifts: assert property (
        @(posedge clk) disable iff (reset)
        (load && (shift_left || shift_right)) |=> (q == $past(parallel_load)) && (serial_out == $past(q[15]))
    );

// Shift-left has priority over shift-right when load is low.
    check_shift_left_priority_over_shift_right: assert property (
        @(posedge clk) disable iff (reset)
        (!load && shift_left && shift_right) |=> (q == {$past(q[14:0]), 1'b0}) && (serial_out == $past(q[15]))
    );

// No clock or reset exists in the RTL; sample the combinational function on clk.

    // Y must equal the 4-input NOR of A, B, C, and D.
    check_nor_function: assert property (
        @(posedge clk) (Y == ~(A | B | C | D))
    );

// If all inputs are low, Y must be high.
    check_all_inputs_low_drives_high: assert property (
        @(posedge clk) ((!A && !B && !C && !D) |-> (Y == 1'b1))
    );

// If any input is high, Y must be low.
    check_any_input_high_drives_low: assert property (
        @(posedge clk) ((A || B || C || D) |-> (Y == 1'b0))
    );

// The output must match the RTL's full nested minimum expression.
    check_min_full_function: assert property (
        @(posedge clk)
        min == (
            (((a < b) ? a : b) < ((c < d) ? c : d)) ?
            ((a < b) ? a : b) :
            ((c < d) ? c : d)
        )
    );

// The reported minimum cannot be greater than a.
    check_min_le_a: assert property (
        @(posedge clk)
        min <= a
    );

// The reported minimum cannot be greater than b.
    check_min_le_b: assert property (
        @(posedge clk)
        min <= b
    );

// The reported minimum cannot be greater than c.
    check_min_le_c: assert property (
        @(posedge clk)
        min <= c
    );

// The reported minimum cannot be greater than d.
    check_min_le_d: assert property (
        @(posedge clk)
        min <= d
    );

// The minimum value must match at least one input value.
    check_min_matches_input: assert property (
        @(posedge clk)
        (min == a) || (min == b) || (min == c) || (min == d)
    );

// If a is no greater than the other inputs, min must equal a.
    check_a_when_a_is_smallest: assert property (
        @(posedge clk)
        ((a <= b) && (a <= c) && (a <= d)) |-> (min == a)
    );

// If b is no greater than the other inputs, min must equal b.
    check_b_when_b_is_smallest: assert property (
        @(posedge clk)
        ((b <= a) && (b <= c) && (b <= d)) |-> (min == b)
    );

// If c is no greater than the other inputs, min must equal c.
    check_c_when_c_is_smallest: assert property (
        @(posedge clk)
        ((c <= a) && (c <= b) && (c <= d)) |-> (min == c)
    );

// If d is no greater than the other inputs, min must equal d.
    check_d_when_d_is_smallest: assert property (
        @(posedge clk)
        ((d <= a) && (d <= b) && (d <= c)) |-> (min == d)
    );

// With no select lines asserted, the output is zero.
    check_no_selects_zero: assert property (
        @(posedge clk)
        (!l0 && !l1 && !l2 && !l3 && !l4 && !l5 && !l6) |-> (out == 8'h00)
    );

// With only l0 asserted, the output equals v0.
    check_only_l0_selected: assert property (
        @(posedge clk)
        ( l0 && !l1 && !l2 && !l3 && !l4 && !l5 && !l6) |-> (out == v0)
    );

// With only l1 asserted, the output equals v1.
    check_only_l1_selected: assert property (
        @(posedge clk)
        (!l0 &&  l1 && !l2 && !l3 && !l4 && !l5 && !l6) |-> (out == v1)
    );

// With only l2 asserted, the output equals v2.
    check_only_l2_selected: assert property (
        @(posedge clk)
        (!l0 && !l1 &&  l2 && !l3 && !l4 && !l5 && !l6) |-> (out == v2)
    );

// With only l3 asserted, the output equals v3.
    check_only_l3_selected: assert property (
        @(posedge clk)
        (!l0 && !l1 && !l2 &&  l3 && !l4 && !l5 && !l6) |-> (out == v3)
    );

// With only l4 asserted, the output equals v4.
    check_only_l4_selected: assert property (
        @(posedge clk)
        (!l0 && !l1 && !l2 && !l3 &&  l4 && !l5 && !l6) |-> (out == v4)
    );

// With only l5 asserted, the output equals v5.
    check_only_l5_selected: assert property (
        @(posedge clk)
        (!l0 && !l1 && !l2 && !l3 && !l4 &&  l5 && !l6) |-> (out == v5)
    );

// With only l6 asserted, v0[7] is broadcast to all output bits.
    check_only_l6_selected: assert property (
        @(posedge clk)
        (!l0 && !l1 && !l2 && !l3 && !l4 && !l5 &&  l6) |-> (out == {8{v0[7]}})
    );

// q updates according to the registered priority mux.
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(sel0 ? in0 : (sel1 ? in1 : q)))
    );

// sel0 causes q to load in0 on the next sampled cycle.
    check_load_in0: assert property (
        @(posedge clk) sel0 |=> (q == $past(in0))
    );

// sel1 causes q to load in1 when sel0 is not asserted.
    check_load_in1: assert property (
        @(posedge clk) (!sel0 && sel1) |=> (q == $past(in1))
    );

// q holds its value when neither select is asserted.
    check_hold_value: assert property (
        @(posedge clk) (!sel0 && !sel1) |=> (q == $past(q))
    );

// Low nibble matches the first 4-bit CLA result.
    check_nibble0_sum: assert property (
        @(posedge clk) out[3:0] == (A[3:0] + B[3:0] + C_in)
    );

// Second nibble matches a 4-bit add with carry from bits [3:0].
    check_nibble1_sum: assert property (
        @(posedge clk)
        out[7:4] == (A[7:4] + B[7:4] + (({1'b0, A[3:0]} + {1'b0, B[3:0]} + C_in) > 5'h0F))
    );

// Nibble [15:12] matches a 4-bit add with carry from bits [11:0].
    check_nibble3_sum: assert property (
        @(posedge clk)
        out[15:12] == (A[15:12] + B[15:12] + (({1'b0, A[11:0]} + {1'b0, B[11:0]} + C_in) > 13'h0FFF))
    );

// Nibble [23:20] matches a 4-bit add with carry from bits [19:0].
    check_nibble5_sum: assert property (
        @(posedge clk)
        out[23:20] == (A[23:20] + B[23:20] + (({1'b0, A[19:0]} + {1'b0, B[19:0]} + C_in) > 21'h0FFFFF))
    );

// Top nibble matches the final 4-bit CLA result with propagated carry.
    check_nibble7_sum: assert property (
        @(posedge clk)
        out[31:28] == (A[31:28] + B[31:28] + (({1'b0, A[27:0]} + {1'b0, B[27:0]} + C_in) > 29'h0FFFFFFF))
    );

// Combined carry_out and out equal the full 33-bit sum.
    check_full_sum: assert property (
        @(posedge clk) {carry_out, out} == ({1'b0, A} + {1'b0, B} + C_in)
    );

// Overflow matches the signed-add overflow condition.
    check_overflow_equation: assert property (
        @(posedge clk)
        overflow == ((A[31] & B[31] & ~out[31]) | (~A[31] & ~B[31] & out[31]))
    );

// Opposite-sign operands cannot produce signed overflow.
    check_opposite_sign_no_overflow: assert property (
        @(posedge clk) (A[31] ^ B[31]) |-> !overflow
    );

// Adding zero on B with no carry-in passes A through unchanged.
    check_zero_b_passthrough: assert property (
        @(posedge clk)
        ((B == 32'h0000_0000) && !C_in) |-> ((out == A) && !carry_out && !overflow)
    );

// Adding zero on A with no carry-in passes B through unchanged.
    check_zero_a_passthrough: assert property (
        @(posedge clk)
        ((A == 32'h0000_0000) && !C_in) |-> ((out == B) && !carry_out && !overflow)
    );

// Active-low reset clears the registered output.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !reset_n |-> (data_out == 4'b0000)
    );

// Each active clock loads data_out with the prior sampled switches value.
    check_data_out_captures_switches: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (data_out == $past(switches))
    );

// After reset deasserts, data_out remains cleared until the next clocked update.
    check_reset_release_holds_zero_until_update: assert property (
        @(posedge clk) disable iff (!reset_n)
        $rose(reset_n) |-> (data_out == 4'b0000)
    );

// Loading both counters with the same value makes OUT zero.
    check_load_drives_zero_out: assert property (
        @(posedge clk) load |=> (OUT == 4'h0)
    );

// X must equal the OR of the three logic inputs.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// X LOW means all three logic inputs are LOW.
    check_x_low_implies_all_inputs_low: assert property (
        @(posedge clk) !X |-> (!A && !B && !C)
    );

// All three logic inputs LOW must drive X LOW.
    check_all_inputs_low_drive_x_low: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// A HIGH must drive X HIGH.
    check_a_high_drives_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B HIGH must drive X HIGH.
    check_b_high_drives_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C HIGH must drive X HIGH.
    check_c_high_drives_x_high: assert property (
        @(posedge clk) C |-> X
    );

// Y must implement the full 4:1 mux function.
    check_mux_function: assert property (
        @(posedge clk)
        Y == (((S1 == 1'b0) && (S0 == 1'b0)) ? A :
              ((S1 == 1'b0) && (S0 == 1'b1)) ? B :
              ((S1 == 1'b1) && (S0 == 1'b0)) ? C :
                                               D)
    );

// When select is 00, Y must equal A.
    check_select_00: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b0)) |-> (Y == A)
    );

// When select is 01, Y must equal B.
    check_select_01: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b1)) |-> (Y == B)
    );

// When select is 10, Y must equal C.
    check_select_10: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b0)) |-> (Y == C)
    );

// When select is 11, Y must equal D.
    check_select_11: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b1)) |-> (Y == D)
    );

// Active-low reset clears d_out_1.
    check_reset_clears_dout1: assert property (
        @(posedge clk) !reset |-> (d_out_1 == 1'b0)
    );

// Active-low reset clears d_out_2.
    check_reset_clears_dout2: assert property (
        @(posedge clk) !reset |-> (d_out_2 == 1'b0)
    );

// The first clock after reset release still sees cleared outputs.
    check_outputs_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (!reset) $past(!reset) |-> ((d_out_1 == 1'b0) && (d_out_2 == 1'b0))
    );

// d_out_1 captures d_in on the next active clock.
    check_dout1_captures_din: assert property (
        @(posedge clk) disable iff (!reset) reset |=> (d_out_1 == $past(d_in))
    );

// d_out_2 captures the previous d_out_1 ^ d_in on the next active clock.
    check_dout2_captures_xor: assert property (
        @(posedge clk) disable iff (!reset) reset |=> (d_out_2 == ($past(d_out_1) ^ $past(d_in)))
    );

// Clock is C; there is no explicit reset; xorout is combinational and Q updates on C.

    // S high and R low force Q high on the next clocked state.
    check_sync_set: assert property (
        @(posedge C) disable iff (1'b0)
        (S == 1'b1 && R == 1'b0) |=> (Q == 1'b1)
    );

// R high and S low force Q low on the next clocked state.
    check_sync_reset: assert property (
        @(posedge C) disable iff (1'b0)
        (S == 1'b0 && R == 1'b1) |=> (Q == 1'b0)
    );

// With S and R low, the else path can only use the prior Q or prior T value.
    check_else_low_low_source: assert property (
        @(posedge C) disable iff (1'b0)
        (S == 1'b0 && R == 1'b0) |=> ((Q == $past(Q)) || (Q == $past(T)))
    );

// With S and R high, the else path can only use the prior Q or prior T value.
    check_else_high_high_source: assert property (
        @(posedge C) disable iff (1'b0)
        (S == 1'b1 && R == 1'b1) |=> ((Q == $past(Q)) || (Q == $past(T)))
    );

// If the else-path data choices match at a clock edge, Q must retain that value.
    check_equal_sr_matching_data_holds_q: assert property (
        @(posedge C) disable iff (1'b0)
        ((S == R) && (T == Q)) |=> (Q == $past(Q))
    );

// Reset forces the count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) (!rst) |-> (count == 4'b0000)
    );

// With enable low, the count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst)
        (!en) |=> (count == $past(count))
    );

// With enable high, the count increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (!rst)
        (en && (count == 4'hf)) |=> (count == 4'h0)
    );

// Any count change must be caused by a previously enabled cycle.
    check_change_requires_enable: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(rst) && (count != $past(count))) |-> $past(en)
    );

// Combined outputs match the 5-bit addition result.
    check_full_sum_match: assert property (
        @(posedge clk) {cout, s} == expected_sum(a, b, cin)
    );

// s matches the lower 4 bits of the addition result.
    check_sum_low_bits: assert property (
        @(posedge clk) s == expected_s(a, b, cin)
    );

// cout matches the carry bit of the addition result.
    check_carry_out: assert property (
        @(posedge clk) cout == expected_cout(a, b, cin)
    );

// The sum LSB is the xor of the input LSBs and carry-in.
    check_lsb_xor: assert property (
        @(posedge clk) s[0] == (a[0] ^ b[0] ^ cin)
    );

// Zero inputs produce zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> ({cout, s} == 5'h00)
    );

// 4'hF + 4'h1 wraps the sum and raises carry-out.
    check_wrap_carry_case: assert property (
        @(posedge clk) (a == 4'hF && b == 4'h1 && cin == 1'b0) |-> ({cout, s} == 5'h10)
    );

// 4'hF + 4'hF + 1 produces the maximum 5-bit result.
    check_max_case: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> ({cout, s} == 5'h1F)
    );

// Carry matches the upper bit of sum.
    check_carry_matches_sum_msb: assert property (
        @(posedge clk) carry == sum[8]
    );

// Zero inputs produce zero outputs.
    check_zero_plus_zero: assert property (
        @(posedge clk) (A == 8'h00 && B == 8'h00) |-> (sum == 9'h000 && carry == 1'b0)
    );

// X matches the implemented OR-of-four function.
    check_exact_function: assert property (
        @(posedge clk) X == (C1 || B1 || D1 || (A1 && A2))
    );

// Any asserted direct OR input forces X high.
    check_direct_or_inputs_drive_high: assert property (
        @(posedge clk) (C1 || B1 || D1) |-> X
    );

// The A1/A2 product term forces X high.
    check_and_term_drives_high: assert property (
        @(posedge clk) (A1 && A2) |-> X
    );

// If all contributing terms are low, X must be low.
    check_all_terms_low_drive_low: assert property (
        @(posedge clk) (!C1 && !B1 && !D1 && (!A1 || !A2)) |-> !X
    );

// A low X means no input term is asserting the OR.
    check_low_output_implies_low_terms: assert property (
        @(posedge clk) !X |-> (!C1 && !B1 && !D1 && (!A1 || !A2))
    );

// With direct OR inputs low, a high X must come from A1&A2.
    check_high_output_requires_and_term_without_direct_or: assert property (
        @(posedge clk) (X && !C1 && !B1 && !D1) |-> (A1 && A2)
    );

// S[0] is the XOR of A[0] and B[0].
    check_sum_bit0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

// S[1] is the XOR of A[1] and B[1].
    check_sum_bit1_xor: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1])
    );

// S[2] is the XOR of A[2] and B[2].
    check_sum_bit2_xor: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2])
    );

// S[3] is the XOR of A[3] and B[3].
    check_sum_bit3_xor: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3])
    );

// S[4] is the reduction XNOR of the bitwise XOR result.
    check_msb_parity_xnor: assert property (
        @(posedge clk) S[4] == (~^(A ^ B))
    );

// Parity equals the XOR reduction of all 16 data bits.
    check_parity_matches_reduction_xor: assert property (
        @(posedge clk) parity == (^data)
    );

// Parity equals the XOR of the low-byte and high-byte parities.
    check_parity_matches_byte_parities: assert property (
        @(posedge clk) parity == ((^data[7:0]) ^ (^data[15:8]))
    );

// All-zero input produces even parity.
    check_zero_data_even_parity: assert property (
        @(posedge clk) (data == 16'h0000) |-> (parity == 1'b0)
    );

// All-one input produces even parity.
    check_all_ones_even_parity: assert property (
        @(posedge clk) (data == 16'hFFFF) |-> (parity == 1'b0)
    );

// Any one-hot input produces odd parity.
    check_onehot_data_odd_parity: assert property (
        @(posedge clk) $onehot(data) |-> (parity == 1'b1)
    );

// RTL is combinational with no reset; clk is a sampling clock.

    // Addition mode drives the 8-bit sum.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> (out == ((in1 + in2) & 8'hFF))
    );

// Subtraction mode drives the 8-bit difference.
    check_subtraction_mode: assert property (
        @(posedge clk)
        (op == 2'b01) |-> (out == ((in1 - in2) & 8'hFF))
    );

// Clock: clk; reset: active-high synchronous reset.
    // Function: 4-bit counter that increments when enabled and wraps from 10 to 0.

    // Reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// When enabled and not at 10, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'b1010)) |=> (count == ($past(count) + 4'b0001))
    );

// When enabled at 10, the counter wraps to zero.
    check_wrap_at_ten: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'b1010)) |=> (count == 4'b0000)
    );

// When scan is disabled, the output is forced low.
    check_output_zero_when_scan_disabled: assert property (
        @(posedge CLK) (!SCE || SCD) |-> (Q == 1'b0)
    );

// A high output is only possible when scan is enabled.
    check_q_high_requires_scan_enabled: assert property (
        @(posedge CLK) Q |-> (SCE && !SCD)
    );

// A qualified load is visible on Q one cycle later if scan stays enabled.
    check_load_updates_q_when_visible: assert property (
        @(posedge CLK) (SCE && !SCD && DE) |=> ((!SCE || SCD) || (Q == $past(D)))
    );

// Without a qualified load, Q holds its visible value across enabled cycles.
    check_hold_across_enabled_cycles_without_load: assert property (
        @(posedge CLK) (SCE && !SCD && !DE) |=> ((!SCE || SCD) || (Q == $past(Q)))
    );

// VPWR is tied high by the RTL.
    check_vpwr_tied_high: assert property (
        @(posedge CLK) (VPWR == 1'b1)
    );

// VGND is tied low by the RTL.
    check_vgnd_tied_low: assert property (
        @(posedge CLK) (VGND == 1'b0)
    );

// VPB is tied high by the RTL.
    check_vpb_tied_high: assert property (
        @(posedge CLK) (VPB == 1'b1)
    );

// VNB is tied low by the RTL.
    check_vnb_tied_low: assert property (
        @(posedge CLK) (VNB == 1'b0)
    );

// Input low forces all outputs low.
    check_input_low_clears_out: assert property (
        @(posedge clk) (in == 1'b0) |-> (out == '0)
    );

// Output is always either zero or one-hot.
    check_output_is_onehot0: assert property (
        @(posedge clk) $onehot0(out)
    );

// Any asserted output requires input high.
    check_asserted_output_requires_input_high: assert property (
        @(posedge clk) (out != '0) |-> (in == 1'b1)
    );

// Q implements the RESET ? 0 : D function.
    check_functional_relation: assert property (
        @(posedge clk) (Q == (RESET ? 1'b0 : D))
    );

// RESET forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge clk) RESET |-> (Q == 1'b0)
    );

// RESET overrides D even when D is high.
    check_reset_dominates_d_high: assert property (
        @(posedge clk) (RESET && D) |-> (Q == 1'b0)
    );

// With RESET inactive, a high D is passed to Q.
    check_d_high_passes_to_q: assert property (
        @(posedge clk) disable iff (RESET) D |-> (Q == 1'b1)
    );

// With RESET inactive, a low D is passed to Q.
    check_d_low_passes_to_q: assert property (
        @(posedge clk) disable iff (RESET) !D |-> (Q == 1'b0)
    );

// Combinational 4-input AND; clk is only used to sample the RTL and there is no reset.

    // X must match the AND of all four inputs.
    check_output_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// Any low input forces X low.
    check_any_low_forces_x_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C) || (!D)) |-> (!X)
    );

// All inputs high drive X high.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// A high X requires every input to be high.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

// Bit 0 sum matches the first full-adder XOR.
    check_bit0_sum: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) sum[2] == (a[2] ^ b[2] ^ maj3(a[1], b[1], maj3(a[0], b[0], cin)))
    );

// Bit 3 sum uses the carry generated from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk) sum[3] == (a[3] ^ b[3] ^ maj3(a[2], b[2], maj3(a[1], b[1], maj3(a[0], b[0], cin))))
    );

// A low reset drives count to zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk)
        !rst |=> (count == 4'h0)
    );

// If reset stays low, count remains zero.
    check_reset_holds_count_zero: assert property (
        @(posedge clk)
        (!rst && $past(!rst)) |-> (count == 4'h0)
    );

// Counting up increments by one when not at the maximum.
    check_increment_from_non_max: assert property (
        @(posedge clk) disable iff (!rst)
        (dir && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

// Counting up wraps from 4'hF to 4'h0.
    check_increment_wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (dir && (count == 4'hF)) |=> (count == 4'h0)
    );

// Counting down decrements by one when not at zero.
    check_decrement_from_non_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (!dir && (count != 4'h0)) |=> (count == ($past(count) - 4'd1))
    );

// Counting down wraps from 4'h0 to 4'hF.
    check_decrement_wrap_from_zero: assert property (
        @(posedge clk) disable iff (!rst)
        (!dir && (count == 4'h0)) |=> (count == 4'hF)
    );

// Reset clears q on the following clock sample.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 1'b0)
    );

// Reset takes priority over load when both are high.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (reset && ld) |=> (q == 1'b0)
    );

// When load is high and reset is low, q captures d.
    check_load_captures_d: assert property (
        @(posedge clk) disable iff (reset) ld |=> (q == $past(d))
    );

// When load is low and reset is low, q holds its value.
    check_hold_when_load_low: assert property (
        @(posedge clk) disable iff (reset) !ld |=> (q == $past(q))
    );

// Output must equal the AND of the two inputs.
    check_output_is_and: assert property (
        @(posedge clk) vcbab45 == (v0e28cb & v3ca442)
    );

// A HIGH output requires both inputs to be HIGH.
    check_high_output_requires_both_inputs_high: assert property (
        @(posedge clk) vcbab45 |-> (v0e28cb && v3ca442)
    );

// A LOW first input forces the output LOW.
    check_low_first_input_forces_low_output: assert property (
        @(posedge clk) !v0e28cb |-> !vcbab45
    );

// A LOW second input forces the output LOW.
    check_low_second_input_forces_low_output: assert property (
        @(posedge clk) !v3ca442 |-> !vcbab45
    );

// Both HIGH inputs force the output HIGH.
    check_both_inputs_high_force_high_output: assert property (
        @(posedge clk) (v0e28cb && v3ca442) |-> vcbab45
    );

// Y must always be the 4-input NOR of A, B, C, and D.
    check_nor4_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

// If all inputs are low, Y must be high.
    check_all_inputs_low_drive_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

// If A is high, Y must be low.
    check_a_high_drives_low: assert property (
        @(posedge clk) A |-> !Y
    );

// If B is high, Y must be low.
    check_b_high_drives_low: assert property (
        @(posedge clk) B |-> !Y
    );

// If C is high, Y must be low.
    check_c_high_drives_low: assert property (
        @(posedge clk) C |-> !Y
    );

// If D is high, Y must be low.
    check_d_high_drives_low: assert property (
        @(posedge clk) D |-> !Y
    );

// If Y is high, all inputs must be low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

// Y matches the input selected on the previous rising clock edge.
    check_registered_mux_function: assert property (
        @(posedge clk)
        1'b1 |=> (
            (($past(S) == 2'b00) && (Y == $past(A))) ||
            (($past(S) == 2'b01) && (Y == $past(B))) ||
            (($past(S) == 2'b10) && (Y == $past(C))) ||
            (($past(S) == 2'b11) && (Y == $past(D)))
        )
    );

// Selecting A loads A into Y on the next sampled cycle.
    check_select_a_updates_y: assert property (
        @(posedge clk)
        (S == 2'b00) |=> (Y == $past(A))
    );

// Selecting B loads B into Y on the next sampled cycle.
    check_select_b_updates_y: assert property (
        @(posedge clk)
        (S == 2'b01) |=> (Y == $past(B))
    );

// Selecting C loads C into Y on the next sampled cycle.
    check_select_c_updates_y: assert property (
        @(posedge clk)
        (S == 2'b10) |=> (Y == $past(C))
    );

// Selecting D loads D into Y on the next sampled cycle.
    check_select_d_updates_y: assert property (
        @(posedge clk)
        (S == 2'b11) |=> (Y == $past(D))
    );

// max must equal D shifted right by the upper nibble of D.
    check_output_matches_shift_rule: assert property (
        @(posedge clk) max == (D >> D[15:12])
    );

// When the upper nibble is zero, max must pass D through unchanged.
    check_passthrough_when_shift_zero: assert property (
        @(posedge clk) (D[15:12] == 4'h0) |-> (max == D)
    );

// A zero input must produce a zero output.
    check_zero_input_produces_zero: assert property (
        @(posedge clk) (D == 16'h0000) |-> (max == 16'h0000)
    );

// When the shift amount is fifteen, only the original MSB can remain.
    check_max_shift_case: assert property (
        @(posedge clk) (D[15:12] == 4'hF) |-> (max == {15'b0, D[15]})
    );

// Right shifting cannot increase the unsigned value.
    check_output_not_greater_than_input: assert property (
        @(posedge clk) max <= D
    );

// Any nonzero shift must clear the output MSB.
    check_msb_clears_on_nonzero_shift: assert property (
        @(posedge clk) (D[15:12] != 4'h0) |-> (max[15] == 1'b0)
    );

// Clock: CK. No reset is present in the RTL.
    // Q is sequential; QN is combinationally driven as ~Q.

    // QN must always be the complement of Q.
    check_qn_complement: assert property (
        @(posedge CK) QN === ~Q
    );

// S asserted at a clock edge forces Q high on that update.
    check_sync_set: assert property (
        @(posedge CK) S |=> (Q === 1'b1)
    );

// When both S and R are asserted, set has priority.
    check_set_priority_over_reset: assert property (
        @(posedge CK) (S && R) |=> (Q === 1'b1)
    );

// R asserted without S forces Q low on that update.
    check_sync_reset: assert property (
        @(posedge CK) (!S && R) |=> (Q === 1'b0)
    );

// With S and R deasserted, D=1 is captured into Q.
    check_data_capture_one: assert property (
        @(posedge CK) (!S && !R && D) |=> (Q === 1'b1)
    );

// With S and R deasserted, D=0 is captured into Q.
    check_data_capture_zero: assert property (
        @(posedge CK) (!S && !R && !D) |=> (Q === 1'b0)
    );

// Reset drives all outputs to their defined reset values.
    check_reset_values: assert property (
        @(posedge clk) reset |-> (odata == 8'h00 && opa == 8'hFF && opb == 8'hFF && opc == 8'hFF)
    );

// Address 00 makes odata reflect the previous opa value.
    check_odata_reads_opa: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b00) |=> (odata == $past(opa))
    );

// Address 01 makes odata reflect the previous opb value.
    check_odata_reads_opb: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b01) |=> (odata == $past(opb))
    );

// Address 10 makes odata reflect the previous opc value.
    check_odata_reads_opc: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b10) |=> (odata == $past(opc))
    );

// Address 11 makes odata return zero.
    check_odata_zero_on_ctrl_addr: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b11) |=> (odata == 8'h00)
    );

// A write to address 00 updates opa and leaves opb/opc unchanged.
    check_write_opa: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b00)) |=> (opa == $past(idata) && opb == $past(opb) && opc == $past(opc))
    );

// A write to address 01 updates opb and leaves opa/opc unchanged.
    check_write_opb: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b01)) |=> (opa == $past(opa) && opb == $past(idata) && opc == $past(opc))
    );

// A write to address 10 updates opc and leaves opa/opb unchanged.
    check_write_opc: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b10)) |=> (opa == $past(opa) && opb == $past(opb) && opc == $past(idata))
    );

// A write to address 11 updates only the selected opc bit.
    check_write_opc_bit: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b11)) |=> (
            opa == $past(opa) &&
            opb == $past(opb) &&
            opc == (($past(opc) & ~(8'h01 << $past(idata[3:1]))) |
                    ({8{$past(idata[0])}} &  (8'h01 << $past(idata[3:1]))))
        )
    );

// With write disabled, the output ports hold their previous values.
    check_no_write_holds_ports: assert property (
        @(posedge clk) disable iff (reset)
        we_n |=> (opa == $past(opa) && opb == $past(opb) && opc == $past(opc))
    );

// Output always matches the mux select expression.
    check_mux_function: assert property (
        @(posedge clk) S == (ctrl ? D1 : D0)
    );

// Low control selects D0.
    check_select_d0: assert property (
        @(posedge clk) !ctrl |-> (S == D0)
    );

// High control selects D1.
    check_select_d1: assert property (
        @(posedge clk) ctrl |-> (S == D1)
    );

// Equal data inputs force the output to that common value.
    check_equal_inputs: assert property (
        @(posedge clk) (D0 == D1) |-> (S == D0)
    );

// Z must match the implemented gate-level RTL expression.
    check_output_matches_rtl: assert property (
        @(posedge clk) Z == ((~((~(A & B)) & EN)) & (A & B))
    );

// When both inputs are high, Z must be high regardless of EN.
    check_ab_high_drive_z_high: assert property (
        @(posedge clk) (A & B) |-> Z
    );

// Z can only be high when both inputs are high.
    check_z_high_requires_ab_high: assert property (
        @(posedge clk) Z |-> (A & B)
    );

// If either input is low, Z must be low regardless of EN.
    check_any_low_drives_z_low: assert property (
        @(posedge clk) ((!A) || (!B)) |-> (!Z)
    );

// Full 5-bit result must equal a + b + cin.
    check_full_result_matches_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Bit 0 sum must match the 1-bit full-adder XOR equation.
    check_lsb_sum_matches_full_adder: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum must use the carry generated from bit 0.
    check_bit1_sum_uses_bit0_carry: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

// Carry-out must indicate overflow of the 4-bit addition.
    check_cout_matches_overflow: assert property (
        @(posedge clk) cout == (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
    );

// Zero inputs must produce a zero result.
    check_zero_inputs_return_zero: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000) && (cin == 1'b0)) |-> ((sum == 4'b0000) && (cout == 1'b0))
    );

// Adding zero with no carry-in must pass a through unchanged.
    check_a_passthrough_when_b_and_cin_are_zero: assert property (
        @(posedge clk) ((b == 4'b0000) && (cin == 1'b0)) |-> ((sum == a) && (cout == 1'b0))
    );

// Adding zero with no carry-in must pass b through unchanged.
    check_b_passthrough_when_a_and_cin_are_zero: assert property (
        @(posedge clk) ((a == 4'b0000) && (cin == 1'b0)) |-> ((sum == b) && (cout == 1'b0))
    );

// Maximum inputs must produce all ones with carry-out asserted.
    check_max_input_case: assert property (
        @(posedge clk) ((a == 4'b1111) && (b == 4'b1111) && (cin == 1'b1)) |-> ((sum == 4'b1111) && (cout == 1'b1))
    );

// Z is the registered 4-bit sum of A and B from the previous clock.
    check_registered_sum: assert property (
        @(posedge clk) 1'b1 |=> (Z == (($past(A) + $past(B)) & 4'hF))
    );

// Adding zero to zero produces zero on the next clock.
    check_zero_plus_zero: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |=> (Z == 4'h0)
    );

// Adding zero on B passes A through to Z on the next clock.
    check_a_plus_zero: assert property (
        @(posedge clk) (B == 4'h0) |=> (Z == $past(A))
    );

// Adding zero on A passes B through to Z on the next clock.
    check_zero_plus_b: assert property (
        @(posedge clk) (A == 4'h0) |=> (Z == $past(B))
    );

// Overflow from 4'hF + 4'h1 wraps around in 4 bits.
    check_overflow_wrap_f_plus_1: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h1) |=> (Z == 4'h0)
    );

// Overflow from 4'hF + 4'hF keeps only the low 4 bits.
    check_overflow_wrap_f_plus_f: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF) |=> (Z == 4'hE)
    );

// Y matches the implemented 2:1 mux equation.
    check_mux_function: assert property (
        @(posedge clk) Y === ((~S & A0) | (S & A1))
    );

// When S is low, Y selects A0.
    check_select_a0: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A0)
    );

// When S is high, Y selects A1.
    check_select_a1: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === A1)
    );

// If both data inputs are low, Y is low.
    check_both_zero_force_zero: assert property (
        @(posedge clk) ((A0 === 1'b0) && (A1 === 1'b0)) |-> (Y === 1'b0)
    );

// The low nibble matches the truncated 4-bit addition.
    check_sum_low_nibble_matches_add: assert property (
        @(posedge clk) SUM[3:0] == (A + B)
    );

// If the full mathematical sum fits in 4 bits, SUM matches it exactly.
    check_no_overflow_matches_full_sum: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B}) <= 5'd15) |-> (SUM == ({1'b0, A} + {1'b0, B}))
    );

// On a mismatch, out is not assigned and must hold its value.
    check_out_hold_on_mismatch: assert property (
        @(posedge clk)
        (in != out) |=> (out == $past(out))
    );

// While input matches output and count is below the threshold, out holds.
    check_out_hold_while_matched_below_threshold: assert property (
        @(posedge clk)
        (in == out && count < debounce_cycles) |=> (out == $past(out))
    );

// Once count reaches the threshold with input matching output, out is assigned from in.
    check_out_update_while_matched_at_threshold: assert property (
        @(posedge clk)
        (in == out && count >= debounce_cycles) |=> (out == $past(in))
    );

// Synchronous reset clears the counter on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset takes priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// Counter holds its value when enable is low outside reset.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// Counter increments by one when enable is high outside reset.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'b0001))
    );

// Counter wraps from 15 back to 0 when enabled.
    check_count_rolls_over_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// A zero opcode updates result with the previous cycle's sum.
    check_add_operation: assert property (
        @(posedge clk) (op == 8'h00) |=> (result == ($past(a) + $past(b)))
    );

// A nonzero opcode updates result with the previous cycle's difference.
    check_sub_operation: assert property (
        @(posedge clk) (op != 8'h00) |=> (result == ($past(a) - $past(b)))
    );

// Result always reflects the previous cycle's selected arithmetic.
    check_result_function: assert property (
        @(posedge clk) 1'b1 |=> (result == (($past(op) == 8'h00) ? ($past(a) + $past(b)) : ($past(a) - $past(b))))
    );

// Synchronous reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge CLK) disable iff (1'b0)
        R |=> (Q == 1'b0)
    );

// Reset has priority over preset when both are high.
    check_reset_priority_over_preset: assert property (
        @(posedge CLK) disable iff (1'b0)
        (R && S) |=> (Q == 1'b0)
    );

// Preset forces Q high when reset is low.
    check_preset_forces_q_high: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!R && S) |=> (Q == 1'b1)
    );

// With reset and preset low, D=1 is captured into Q.
    check_data_capture_one: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!R && !S && D) |=> (Q == 1'b1)
    );

// With reset and preset low, D=0 is captured into Q.
    check_data_capture_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!R && !S && !D) |=> (Q == 1'b0)
    );

// Qbar is always the complement of Q.
    check_qbar_is_complement: assert property (
        @(posedge CLK) disable iff (1'b0)
        (Qbar == ~Q)
    );

// out_hi is the upper byte of in.
    check_out_hi_split: assert property (
        @(posedge clk) out_hi == in[15:8]
    );

// out_lo is the lower byte of in.
    check_out_lo_split: assert property (
        @(posedge clk) out_lo == in[7:0]
    );

// outv directly mirrors select.
    check_outv_matches_select: assert property (
        @(posedge clk) outv == select
    );

// o2, o1, and o0 directly mirror the select bits.
    check_select_bit_outputs: assert property (
        @(posedge clk) {o2, o1, o0} == select
    );

// final_output keeps select in its low three bits.
    check_final_output_low_bits: assert property (
        @(posedge clk) final_output[2:0] == select
    );

// For select 000, the upper bits carry out_hi[4:0].
    check_final_output_upper_sel_000: assert property (
        @(posedge clk) (select == 3'b000) |-> (final_output[7:3] == in[12:8])
    );

// For select 001, the upper bits carry out_hi[5:1].
    check_final_output_upper_sel_001: assert property (
        @(posedge clk) (select == 3'b001) |-> (final_output[7:3] == in[13:9])
    );

// For select 010, the upper bits carry out_hi[6:2].
    check_final_output_upper_sel_010: assert property (
        @(posedge clk) (select == 3'b010) |-> (final_output[7:3] == in[14:10])
    );

// For select 011, the upper bits carry out_hi[7:3].
    check_final_output_upper_sel_011: assert property (
        @(posedge clk) (select == 3'b011) |-> (final_output[7:3] == in[15:11])
    );

// For select 100, the upper bits are zero-extended out_hi[7:4].
    check_final_output_upper_sel_100: assert property (
        @(posedge clk) (select == 3'b100) |-> (final_output[7:3] == {1'b0, in[15:12]})
    );

// For select 101, the upper bits are zero-extended out_hi[7:5].
    check_final_output_upper_sel_101: assert property (
        @(posedge clk) (select == 3'b101) |-> (final_output[7:3] == {2'b00, in[15:13]})
    );

// For select 110, the upper bits are zero-extended out_hi[7:6].
    check_final_output_upper_sel_110: assert property (
        @(posedge clk) (select == 3'b110) |-> (final_output[7:3] == {3'b000, in[15:14]})
    );

// For select 111, the upper bits are zero-extended out_hi[7].
    check_final_output_upper_sel_111: assert property (
        @(posedge clk) (select == 3'b111) |-> (final_output[7:3] == {4'b0000, in[15]})
    );

// reg_wr_en is always included in reg_en.
    check_reg_wr_en_implies_reg_en: assert property (
        @(posedge clk) disable iff (!rst_n)
        reg_wr_en |-> reg_en
    );

// After reset release, both outputs stay low for two clocks.
    check_reset_release_clears_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        $rose(rst_n) |-> (!reg_en && !reg_wr_en) ##1 (!reg_en && !reg_wr_en)
    );

// A write rising edge creates a one-cycle reg_wr_en pulse two clocks later.
    check_wr_rise_generates_single_pulse: assert property (
        @(posedge clk) disable iff (!rst_n)
        $rose(wr_en) |-> ##1 (!reg_wr_en) ##1 (reg_wr_en && reg_en) ##1 (!reg_wr_en)
    );

// A read rising edge drives reg_en two clocks later.
    check_rd_rise_generates_reg_en: assert property (
        @(posedge clk) disable iff (!rst_n)
        $rose(rd_en) |-> ##2 reg_en
    );

// reg_wr_en cannot remain high on back-to-back clocks.
    check_reg_wr_en_single_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
        reg_wr_en |=> !reg_wr_en
    );

// X implements (~A_N & ~B_N & C & D).
    check_output_matches_function: assert property (
        @(posedge clk) X == ((!A_N) && (!B_N) && C && D)
    );

// All required input conditions drive X HIGH.
    check_output_high_when_all_terms_true: assert property (
        @(posedge clk) ((!A_N) && (!B_N) && C && D) |-> X
    );

// X HIGH implies every input term is satisfied.
    check_output_high_implies_valid_inputs: assert property (
        @(posedge clk) X |-> ((!A_N) && (!B_N) && C && D)
    );

// A_N HIGH forces X LOW.
    check_a_n_high_forces_output_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B_N HIGH forces X LOW.
    check_b_n_high_forces_output_low: assert property (
        @(posedge clk) B_N |-> !X
    );

// C LOW or D LOW forces X LOW.
    check_c_or_d_low_forces_output_low: assert property (
        @(posedge clk) ((!C) || (!D)) |-> !X
    );

// q is d delayed by four sampled clock edges.
    check_q_is_delayed_d: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ##3 (q == $past(d,4))
    );

// Full Gray output matches the implemented binary-to-Gray conversion.
    check_gray_vector_mapping: assert property (
        @(posedge clk)
        gray == {binary[3], (binary[3] ^ binary[2]), (binary[2] ^ binary[1]), (binary[1] ^ binary[0])}
    );

// gray[3] is a direct copy of binary[3].
    check_gray_bit3_passthrough: assert property (
        @(posedge clk)
        gray[3] == binary[3]
    );

// gray[2] is binary[3] XOR binary[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk)
        gray[2] == (binary[3] ^ binary[2])
    );

// gray[1] is binary[2] XOR binary[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk)
        gray[1] == (binary[2] ^ binary[1])
    );

// gray[0] is binary[1] XOR binary[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk)
        gray[0] == (binary[1] ^ binary[0])
    );

// Y must match the implemented NAND/OR/NAND logic function.
    check_output_function: assert property (
        @(posedge clk) Y == ((A1_N & A2_N) | ((~B1) & (~B2)))
    );

// If both B inputs are low, Y must be high.
    check_b_inputs_low_force_y_high: assert property (
        @(posedge clk) ((~B1) & (~B2)) |-> Y
    );

// If both A inputs are high, Y must be high.
    check_a_inputs_high_force_y_high: assert property (
        @(posedge clk) (A1_N & A2_N) |-> Y
    );

// If any B input is high and either A input is low, Y must be low.
    check_active_b_and_low_a_force_y_low: assert property (
        @(posedge clk) ((B1 | B2) & ((~A1_N) | (~A2_N))) |-> (~Y)
    );

// A low Y must only occur when any B is high and either A is low.
    check_y_low_has_required_condition: assert property (
        @(posedge clk) (~Y) |-> ((B1 | B2) & ((~A1_N) | (~A2_N)))
    );

// A high Y must only occur when both A are high or both B are low.
    check_y_high_has_required_condition: assert property (
        @(posedge clk) Y |-> ((A1_N & A2_N) | ((~B1) & (~B2)))
    );

// Sum must match the RTL combinational equation.
    check_sum_equation: assert property (
        @(posedge clk)
        sum == ((~a & ~b) ^ (c_in ^ (a & b)))
    );

// Carry-out must match the RTL combinational equation.
    check_cout_equation: assert property (
        @(posedge clk)
        c_out == ((a & b) | ((~a & ~b) & c_in))
    );

// When both inputs are 0, sum inverts c_in and carry-out follows c_in.
    check_both_zero_behavior: assert property (
        @(posedge clk)
        ((!a) && (!b)) |-> ((sum == (~c_in)) && (c_out == c_in))
    );

// When both inputs are 1, sum inverts c_in and carry-out is asserted.
    check_both_one_behavior: assert property (
        @(posedge clk)
        (a && b) |-> ((sum == (~c_in)) && (c_out == 1'b1))
    );

// When inputs differ, sum follows c_in and carry-out is deasserted.
    check_mismatched_inputs_behavior: assert property (
        @(posedge clk)
        (a ^ b) |-> ((sum == c_in) && (c_out == 1'b0))
    );

// out is always even because the computed sum is doubled.
    check_out_is_even: assert property (
        @(posedge clk)
        out[0] == 1'b0
    );

// Zero input must produce zero output.
    check_zero_input_zero_output: assert property (
        @(posedge clk)
        (in == 16'h0000) |-> (out == 16'h0000)
    );

// A sampled reset leaves the counter at zero by the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) rst |=> (out == 4'd0)
    );

// When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst) en |=> (out == ($past(out) + 4'd1))
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (out == $past(out))
    );

// When enabled at 15, the 4-bit counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst) (en && (out == 4'hF)) |=> (out == 4'h0)
    );

// Sequential-only logic on clk; reset is active high and asynchronous.
    // count is a 4-bit output that increments and wraps from 9 to 0.

    // A sampled reset forces the counter to be 0 on the next clock.
    reset_forces_zero_next: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// A sampled value of 9 wraps back to 0 on the next clock.
    wrap_from_nine: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'd9) |=> (count == 4'd0)
    );

// Any non-9 value increments, unless an async reset pulse clears count to 0 between clocks.
    increment_or_clear_from_non_nine: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'd9) |=> ((count == ($past(count) + 4'd1)) || (count == 4'd0))
    );

// Reset clears the counter to zero.
    check_reset_clears_out: assert property (
        @(posedge CLK) RESET |=> (OUT == 4'b0000)
    );

// UP_DOWN high increments the counter on the next clock.
    check_increment_when_up: assert property (
        @(posedge CLK) disable iff (RESET)
        UP_DOWN |=> (OUT == ($past(OUT) + 4'd1))
    );

// UP_DOWN low decrements the counter on the next clock.
    check_decrement_when_down: assert property (
        @(posedge CLK) disable iff (RESET)
        !UP_DOWN |=> (OUT == ($past(OUT) - 4'd1))
    );

// Counting up wraps from 15 back to 0.
    check_increment_wrap: assert property (
        @(posedge CLK) disable iff (RESET)
        (UP_DOWN && (OUT == 4'hF)) |=> (OUT == 4'h0)
    );

// Counting down wraps from 0 back to 15.
    check_decrement_wrap: assert property (
        @(posedge CLK) disable iff (RESET)
        (!UP_DOWN && (OUT == 4'h0)) |=> (OUT == 4'hF)
    );

// SUM[0] matches the RTL XOR of the least-significant input bits.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0])
    );

// SUM[1] matches the RTL XOR with the bit-0 generate term.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

// SUM[2] matches the RTL XOR with the OR of lower generate terms.
    check_sum_bit2: assert property (
        @(posedge clk) SUM[2] == ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | (A[0] & B[0])))
    );

// SUM[3] matches the RTL XOR with the OR of all lower generate terms.
    check_sum_bit3: assert property (
        @(posedge clk) SUM[3] == ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | (A[1] & B[1]) | (A[0] & B[0])))
    );

// The full SUM bus matches the combined RTL equations.
    check_sum_vector: assert property (
        @(posedge clk) SUM == {
            ((A[3] ^ B[3]) ^ ((A[2] & B[2]) | (A[1] & B[1]) | (A[0] & B[0]))),
            ((A[2] ^ B[2]) ^ ((A[1] & B[1]) | (A[0] & B[0]))),
            ((A[1] ^ B[1]) ^ (A[0] & B[0])),
            (A[0] ^ B[0])
        }
    );

// 0xFF plus 0x01 must wrap to 0x00 on the 8-bit output.
    check_ff_plus_one_wraps: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'h01)) |-> (sum == 8'h00)
    );

// 0xFF plus 0xFF must produce 0xFE on the 8-bit output.
    check_ff_plus_ff: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'hFF)) |-> (sum == 8'hFE)
    );

// A sampled low reset drives count to zero by the next clock.
    check_reset_drives_zero: assert property (
        @(posedge clk) !reset |=> (count == 3'b000)
    );

// A high load causes count to take the previous cycle's input value.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!reset)
        load |=> (count == $past(input_value))
    );

// Load overrides wrap behavior when count is 7.
    check_load_priority_over_wrap: assert property (
        @(posedge clk) disable iff (!reset)
        (load && (count == 3'b111)) |=> (count == $past(input_value))
    );

// Without load, a count of 7 wraps back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (count == 3'b111)) |=> (count == 3'b000)
    );

// Without load, counts below 7 increment by one.
    check_increment_when_not_loaded: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (count != 3'b111)) |=> (count == ($past(count) + 3'b001))
    );

// Reset clears the counter on the following cycle.
    check_reset_clears_counter: assert property (
        @(posedge clk) reset |=> (counter == 16'd0)
    );

// Enable increments the counter by one.
    check_counter_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        ena |=> (counter == ($past(counter) + 16'd1))
    );

// Disabled cycles hold the counter value.
    check_counter_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !ena |=> (counter == $past(counter))
    );

// The selector is the 4-bit shifted decode of sel[2:0].
    check_select_input_decode: assert property (
        @(posedge clk) disable iff (reset)
        (select_input == (4'b0001 << sel[2:0]))
    );

// The mux output is always zero-extended from a 4-bit slice.
    check_mux_output_zero_extended: assert property (
        @(posedge clk) disable iff (reset)
        (mux_output[7:4] == 4'b0000)
    );

// The mux output matches the RTL's selected input nibble.
    check_mux_output_selected_nibble: assert property (
        @(posedge clk) disable iff (reset)
        (mux_output ==
            ((sel[2:0] == 3'd0) ? {4'b0000, in[7:4]}   :
             (sel[2:0] == 3'd1) ? {4'b0000, in[11:8]}  :
             (sel[2:0] == 3'd2) ? {4'b0000, in[19:16]} :
             (sel[2:0] == 3'd3) ? {4'b0000, in[35:32]} :
                                  {4'b0000, in[3:0]}))
    );

// The adder output is the low 12 bits of counter plus mux_output.
    check_add_output_matches_sum: assert property (
        @(posedge clk) disable iff (reset)
        (add_output == (counter[11:0] + {4'b0000, mux_output}))
    );

// The module output is add_output[11:4].
    check_out_matches_add_output_slice: assert property (
        @(posedge clk) disable iff (reset)
        (out == add_output[11:4])
    );

// After reset, the adder reflects a zero counter plus mux_output.
    check_reset_zeroes_counter_contribution: assert property (
        @(posedge clk) reset |=> (add_output == {4'b0000, mux_output})
    );

// After reset, the visible output is zero.
    check_reset_forces_out_zero: assert property (
        @(posedge clk) reset |=> (out == 8'd0)
    );

// Sample clock for this combinational DUT; RTL has no reset.

    // When empty is high, the output mirrors tm_count with zero extension.
    check_empty_passthrough: assert property (
        @(posedge clk)
        empty |-> (fifocount_inc == {3'b000, tm_count})
    );

// When not empty and tm_count is 0, the output is all ones.
    check_nonempty_tm_count_0: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd0)) |-> (fifocount_inc == 5'b11111)
    );

// When not empty and tm_count is 1, the output is zero.
    check_nonempty_tm_count_1: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd1)) |-> (fifocount_inc == 5'd0)
    );

// When not empty and tm_count is 2, free2 selects between 1 and 0.
    check_nonempty_tm_count_2: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd2)) |-> (fifocount_inc == (free2 ? 5'd1 : 5'd0))
    );

// When not empty and tm_count is 3, free3 has priority over free2.
    check_nonempty_tm_count_3: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd3)) |-> (fifocount_inc == (free3 ? 5'd2 : (free2 ? 5'd1 : 5'd0)))
    );

// After sel rises and b is held stable, out must reflect b on the next sample.
    check_sel_rise_selects_b_when_held: assert property (
        @(posedge clk)
        ($rose(sel) && $stable(a) && $stable(b)) ##1 (sel && $stable(b)) |-> (out == b)
    );

// After sel falls and a is held stable, out must reflect a on the next sample.
    check_sel_fall_selects_a_when_held: assert property (
        @(posedge clk)
        ($fell(sel) && $stable(a) && $stable(b)) ##1 (!sel && $stable(a)) |-> (out == a)
    );

// Sum is the XOR of A, B, and Ci.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry-out matches the implemented generate/propagate equation.
    check_carry_function: assert property (
        @(posedge clk) Co == ((A & B) | ((A ^ B) & Ci))
    );

// With Ci low, the adder behaves as a half adder.
    check_half_adder_mode: assert property (
        @(posedge clk) !Ci |-> ((S == (A ^ B)) && (Co == (A & B)))
    );

// With Ci high, sum inverts A^B and carry is A or B.
    check_carry_in_mode: assert property (
        @(posedge clk) Ci |-> ((S == ~(A ^ B)) && (Co == (A | B)))
    );

// When A and B match, sum follows Ci and carry follows A.
    check_equal_inputs_behavior: assert property (
        @(posedge clk) !(A ^ B) |-> ((S == Ci) && (Co == A))
    );

// When A and B differ, sum is the inverse of Ci and carry follows Ci.
    check_unequal_inputs_behavior: assert property (
        @(posedge clk) (A ^ B) |-> ((S == ~Ci) && (Co == Ci))
    );

// Y must match the RTL NOR equation of A, B, and C_N.
    check_nor3b_equation: assert property (
        @(posedge clk) disable iff (1'b0) Y == ~(A | B | C_N)
    );

// If all functional inputs are low, Y must be high.
    check_all_inputs_low_sets_y_high: assert property (
        @(posedge clk) disable iff (1'b0) !(A | B | C_N) |-> Y
    );

// If any functional input is high, Y must be low.
    check_any_input_high_sets_y_low: assert property (
        @(posedge clk) disable iff (1'b0) (A | B | C_N) |-> !Y
    );

// Reset clears the observable outputs and status flags.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        rst |-> (!output_axis_tvalid && !busy && !overrun_error && !frame_error && (output_axis_tdata == '0))
    );

// Overrun and frame error are never asserted together.
    check_error_mutex: assert property (
        @(posedge clk) disable iff (rst)
        !(overrun_error && frame_error)
    );

// An overrun indication always leaves the output valid asserted.
    check_overrun_implies_valid: assert property (
        @(posedge clk) disable iff (rst)
        overrun_error |-> output_axis_tvalid
    );

// An overrun indication occurs while the receiver is still busy.
    check_overrun_implies_busy: assert property (
        @(posedge clk) disable iff (rst)
        overrun_error |-> busy
    );

// Overrun can only occur if output valid was already set in the prior cycle.
    check_overrun_requires_prior_valid: assert property (
        @(posedge clk) disable iff (rst)
        overrun_error |-> $past(output_axis_tvalid)
    );

// A frame error is reported while the receiver is still busy.
    check_frame_error_implies_busy: assert property (
        @(posedge clk) disable iff (rst)
        frame_error |-> busy
    );

// Valid stays asserted while backpressured.
    check_valid_holds_under_backpressure: assert property (
        @(posedge clk) disable iff (rst)
        (output_axis_tvalid && !output_axis_tready) |=> output_axis_tvalid
    );

// Overrun error is a single-cycle pulse.
    check_overrun_single_cycle: assert property (
        @(posedge clk) disable iff (rst)
        overrun_error |=> !overrun_error
    );

// Frame error is a single-cycle pulse.
    check_frame_error_single_cycle: assert property (
        @(posedge clk) disable iff (rst)
        frame_error |=> !frame_error
    );

// A new assertion of valid happens while the receiver is busy.
    check_valid_rise_while_busy: assert property (
        @(posedge clk) disable iff (rst)
        $rose(output_axis_tvalid) |-> busy
    );

// No DUT clock or reset; sample this combinational logic on clk.

    // SUM must equal the 3-input XOR of A, B, and CI.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT must equal the majority/carry function of A, B, and CI.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// All-zero inputs must produce zero SUM and zero COUT.
    check_zero_inputs: assert property (
        @(posedge clk) ({A, B, CI} == 3'b000) |-> ({COUT, SUM} == 2'b00)
    );

// Any one-hot input pattern must produce SUM=1 and COUT=0.
    check_one_hot_inputs: assert property (
        @(posedge clk)
        (({A, B, CI} == 3'b001) ||
         ({A, B, CI} == 3'b010) ||
         ({A, B, CI} == 3'b100)) |-> ({COUT, SUM} == 2'b01)
    );

// Any two-hot input pattern must produce SUM=0 and COUT=1.
    check_two_hot_inputs: assert property (
        @(posedge clk)
        (({A, B, CI} == 3'b011) ||
         ({A, B, CI} == 3'b101) ||
         ({A, B, CI} == 3'b110)) |-> ({COUT, SUM} == 2'b10)
    );

// All-one inputs must produce SUM=1 and COUT=1.
    check_all_one_inputs: assert property (
        @(posedge clk) ({A, B, CI} == 3'b111) |-> ({COUT, SUM} == 2'b11)
    );

// Left-shift mode outputs the 16-bit sum shifted left by shift_amt.
    check_left_shift_result: assert property (
        @(posedge clk)
        shift_dir |-> (out == ((in1 + in2) << shift_amt))
    );

// Right-shift mode outputs the 16-bit sum shifted right by shift_amt.
    check_right_shift_result: assert property (
        @(posedge clk)
        !shift_dir |-> (out == ((in1 + in2) >> shift_amt))
    );

// A zero shift leaves the 16-bit adder result unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk)
        (shift_amt == 4'd0) |-> (out == (in1 + in2))
    );

// Left shifts fill the vacated low bits with zeros.
    check_left_shift_zero_fill_low: assert property (
        @(posedge clk)
        shift_dir |-> ((out & ~(16'hFFFF << shift_amt)) == 16'h0000)
    );

// Right shifts fill the vacated high bits with zeros.
    check_right_shift_zero_fill_high: assert property (
        @(posedge clk)
        !shift_dir |-> ((out & ~(16'hFFFF >> shift_amt)) == 16'h0000)
    );

// Output matches the implemented mux equation.
    check_output_matches_mux_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        O == (((S == 4'b0000) ? I[0] : 1'b0) |
              ((S == 4'b0001) ? I[1] : 1'b0) |
              ((S == 4'b0010) ? I[2] : 1'b0) |
              ((S == 4'b0011) ? I[3] : 1'b0))
    );

// Select code 0 forwards I[0].
    check_select_0_forwards_i0: assert property (
        @(posedge clk) disable iff (1'b0)
        (S == 4'b0000) |-> (O == I[0])
    );

// Select code 1 forwards I[1].
    check_select_1_forwards_i1: assert property (
        @(posedge clk) disable iff (1'b0)
        (S == 4'b0001) |-> (O == I[1])
    );

// Select code 2 forwards I[2].
    check_select_2_forwards_i2: assert property (
        @(posedge clk) disable iff (1'b0)
        (S == 4'b0010) |-> (O == I[2])
    );

// Select code 3 forwards I[3].
    check_select_3_forwards_i3: assert property (
        @(posedge clk) disable iff (1'b0)
        (S == 4'b0011) |-> (O == I[3])
    );

// Unused select codes force the output low.
    check_unused_selects_drive_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (S > 4'd3) |-> (O == 1'b0)
    );

// A high output must come from the selected low four input bits.
    check_output_high_has_valid_source: assert property (
        @(posedge clk) disable iff (1'b0)
        O |-> (((S == 4'b0000) && I[0]) ||
               ((S == 4'b0001) && I[1]) ||
               ((S == 4'b0010) && I[2]) ||
               ((S == 4'b0011) && I[3]))
    );

// Synchronous reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

// Load updates count with load_value on the next cycle.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(load_value))
    );

// Load has priority over enable when both are asserted.
    check_load_priority_over_enable: assert property (
        @(posedge clk) disable iff (reset)
        (load && enable) |=> (count == $past(load_value))
    );

// Enable increments count by one when load is low.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !load) |=> (count == ($past(count) + 32'd1))
    );

// Count holds its value when no control input is asserted.
    check_idle_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !enable) |=> (count == $past(count))
    );

// Y equals the implemented NOR/AND function of the inputs.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ((~A) & (~B) & C_N & D_N)
    );

// A high forces the NOR term low and keeps Y low.
    check_a_blocks_output: assert property (
        @(posedge clk) A |-> !Y
    );

// B high forces the NOR term low and keeps Y low.
    check_b_blocks_output: assert property (
        @(posedge clk) B |-> !Y
    );

// C_N low blocks the final AND and keeps Y low.
    check_c_n_low_blocks_output: assert property (
        @(posedge clk) !C_N |-> !Y
    );

// D_N low blocks the final AND and keeps Y low.
    check_d_n_low_blocks_output: assert property (
        @(posedge clk) !D_N |-> !Y
    );

// When all enabling conditions are met, Y is high.
    check_output_high_condition: assert property (
        @(posedge clk) ((~A) & (~B) & C_N & D_N) |-> Y
    );

// Y high implies the exact enabling input combination.
    check_output_high_implies_inputs: assert property (
        @(posedge clk) Y |-> ((~A) & (~B) & C_N & D_N)
    );

// sel equal to 0 routes a to out.
    check_sel_zero_routes_a: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === a)
    );

// Any sel value other than 0 routes b to out.
    check_sel_not_zero_routes_b: assert property (
        @(posedge clk) (sel !== 1'b0) |-> (out === b)
    );

// Equal data inputs must appear unchanged at out.
    check_equal_inputs_preserved: assert property (
        @(posedge clk) (a === b) |-> (out === a)
    );

// With different inputs, out matching a means sel is 0.
    check_output_a_requires_sel_zero: assert property (
        @(posedge clk) ((a !== b) && (out === a)) |-> (sel === 1'b0)
    );

// With different inputs, out matching b means sel is not 0.
    check_output_b_requires_sel_not_zero: assert property (
        @(posedge clk) ((a !== b) && (out === b)) |-> (sel !== 1'b0)
    );

// Reset clears the counter to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// A count of nine rolls over to zero on the next clock.
    check_wrap_from_nine: assert property (
        @(posedge clk) (count == 4'd9) |=> (count == 4'd0)
    );

// Any non-reset state other than nine increments by one.
    check_increment_otherwise: assert property (
        @(posedge clk) disable iff (rst)
        (count != 4'd9) |=> (count == ($past(count) + 4'd1))
    );

// When not in reset, the counter value changes every clock.
    check_count_changes_without_reset: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (count != $past(count))
    );

// A reset cycle leaves count at zero on the following cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

// Count holds when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Count wraps to zero when enabled at max_count.
    check_wrap_when_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == max_count) |=> (count == 32'd0)
    );

// Count increments by one when enabled away from max_count.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != max_count) |=> (count == ($past(count) + 32'd1))
    );

// ENCLK reflects the prior cycle's EN && !TE value.
    check_enclk_matches_registered_gate: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == ($past(EN) && !$past(TE)))
    );

// EN high with TE low makes ENCLK high on the next clock.
    check_enable_sets_enclk: assert property (
        @(posedge CLK) (EN && !TE) |=> ENCLK
    );

// EN low or TE high makes ENCLK low on the next clock.
    check_disable_clears_enclk: assert property (
        @(posedge CLK) (!EN || TE) |=> !ENCLK
    );

// After reset deasserts, parity_out is still cleared on that clock edge.
    check_reset_release_clears_output: assert property (
        @(posedge clk) disable iff (reset)
        $fell(reset) |-> (parity_out == 1'b0)
    );

// Even input parity drives parity_out high on the next clock.
    check_even_parity_sets_output: assert property (
        @(posedge clk) disable iff (reset)
        (~^data_in) |=> (parity_out == 1'b1)
    );

// Odd input parity drives parity_out low on the next clock.
    check_odd_parity_clears_output: assert property (
        @(posedge clk) disable iff (reset)
        (^data_in) |=> (parity_out == 1'b0)
    );

// Reset drives the counter to zero.
    check_reset_clears_counter: assert property (
        @(posedge clk) reset |-> (pwm_counter == PWM_ZERO)
    );

// Reset drives the threshold to zero.
    check_reset_clears_threshold: assert property (
        @(posedge clk) reset |-> (pwm_threshold == PWM_ZERO)
    );

// Reset drives the PWM output low.
    check_reset_clears_pwm_out: assert property (
        @(posedge clk) reset |-> (pwm_out == 1'b0)
    );

// The PWM output holds when enable is low.
    check_pwm_out_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (pwm_out == $past(pwm_out))
    );

// data_out reflects the data_in value from the previous posedge.
    check_data_out_reflects_prev_data_in: assert property (
        @(posedge clk) 1'b1 |=> (data_out == $past(data_in))
    );

// Q_N remains the complement of Q outside reset.
    check_qn_complement: assert property (
        @(posedge CLK) disable iff (VPB == 1'b0) Q_N == ~Q
    );

// A low VPB on a clock edge clears Q by the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge CLK) (VPB == 1'b0) |=> Q == 1'b0
    );

// Outside reset, Q captures D on the following sampled cycle.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (VPB == 1'b0) 1'b1 |=> Q == $past(D)
    );

// A low VPB on a clock edge drives Q_N high by the next sampled cycle.
    check_reset_sets_qn_high: assert property (
        @(posedge CLK) (VPB == 1'b0) |=> Q_N == 1'b1
    );

// The divider flips on every rising edge of clk.
    check_clk_divider_toggles: assert property (
        @(posedge clk) 1'b1 |=> (clk_divider == ~$past(clk_divider))
    );

// When the divider is high, the next clk edge must not update the counter.
    check_count_stable_on_divider_fall: assert property (
        @(posedge clk) (clk_divider == 1'b1) |=> (count == $past(count))
    );

// When the divider is high, the next clk edge must not update the output.
    check_out_stable_on_divider_fall: assert property (
        @(posedge clk) (clk_divider == 1'b1) |=> (out === $past(out))
    );

// On an active divider edge below terminal count, the counter increments.
    check_count_increments_on_divider_rise: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count != 32'd50000000)) |=> (count == ($past(count) + 32'd1))
    );

// On an active divider edge at terminal count, the counter wraps to zero.
    check_count_wraps_on_terminal: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count == 32'd50000000)) |=> (count == 32'd0)
    );

// Below terminal count, the output holds through an active divider edge.
    check_out_holds_below_terminal: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count != 32'd50000000)) |=> (out === $past(out))
    );

// At terminal count, the output inverts through an active divider edge.
    check_out_toggles_on_terminal: assert property (
        @(posedge clk) ((clk_divider == 1'b0) && (count == 32'd50000000)) |=> (out === ~$past(out))
    );

// Any counter change must come from a divider rise on the prior clk.
    check_count_changes_only_on_divider_rise: assert property (
        @(posedge clk) 1'b1 |=> ((count != $past(count)) |-> ($past(clk_divider) == 1'b0))
    );

// Any output change must come from terminal count on a divider rise.
    check_out_changes_only_on_terminal: assert property (
        @(posedge clk) 1'b1 |=> ((out !== $past(out)) |-> (($past(clk_divider) == 1'b0) && ($past(count) == 32'd50000000)))
    );

// When enable is high, the output follows input a.
    check_select_a: assert property (
        @(posedge clk) (enable === 1'b1) |-> (mux_out === a)
    );

// When enable is not high, the output follows input b.
    check_select_b: assert property (
        @(posedge clk) (enable !== 1'b1) |-> (mux_out === b)
    );

// When both inputs match, the output matches that common value.
    check_equal_inputs_common_value: assert property (
        @(posedge clk) (a === b) |-> (mux_out === a)
    );

// When sel is 0, the output matches data_in[0].
    check_select_low: assert property (
        @(posedge clk) (sel === 1'b0) |-> (data_out === data_in[0])
    );

// When sel is 1, the output matches data_in[1].
    check_select_high: assert property (
        @(posedge clk) (sel === 1'b1) |-> (data_out === data_in[1])
    );

// The output always matches the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) data_out === ((sel == 1'b0) ? data_in[0] : data_in[1])
    );

// out_lo selects the low or high input byte based on in[8].
    check_out_lo_selected_byte: assert property (
        @(posedge clk) out_lo == (in[8] ? in[15:8] : in[7:0])
    );

// out_hi selects the complementary input byte based on in[8].
    check_out_hi_selected_byte: assert property (
        @(posedge clk) out_hi == (in[8] ? in[7:0] : in[15:8])
    );

// When in[8] is low, the outputs preserve the original byte order.
    check_original_order_when_sel_low: assert property (
        @(posedge clk) !in[8] |-> ({out_hi, out_lo} == {in[15:8], in[7:0]})
    );

// When in[8] is high, the outputs swap the input byte order.
    check_swapped_order_when_sel_high: assert property (
        @(posedge clk) in[8] |-> ({out_hi, out_lo} == {in[7:0], in[15:8]})
    );

// The outputs are always the two input bytes in one of the two possible orders.
    check_outputs_form_input_byte_permutation: assert property (
        @(posedge clk) (({out_hi, out_lo} == {in[15:8], in[7:0]}) ||
                        ({out_hi, out_lo} == {in[7:0], in[15:8]}))
    );

// The two outputs are equal exactly when the two input bytes are equal.
    check_output_equality_matches_input_equality: assert property (
        @(posedge clk) ((out_hi == out_lo) == (in[15:8] == in[7:0]))
    );

// Reset clears the counter on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// Reset takes priority over enable when both are high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'h0)
    );

// When enabled outside reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// External clk samples this combinational DUT; the RTL has no reset.

    // Y matches the implemented AND of the four inverted inputs.
    check_output_function: assert property (
        @(posedge clk) Y == ((~A) & (~B) & (~C) & (~D))
    );

// All inputs low must drive Y high.
    check_all_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

// Y high means all inputs are low.
    check_y_high_requires_all_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

// Y low means at least one input is high.
    check_y_low_requires_some_input_high: assert property (
        @(posedge clk) (!Y) |-> (A || B || C || D)
    );

// A high forces Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high forces Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high forces Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D high forces Y low.
    check_d_high_forces_y_low: assert property (
        @(posedge clk) D |-> !Y
    );

// When inputs are equal, only equal is asserted.
    check_equal_case: assert property (
        @(posedge clk) (a == b) |-> (equal && !greater && !less)
    );

// When a is greater than b, only greater is asserted.
    check_greater_case: assert property (
        @(posedge clk) (a > b) |-> (!equal && greater && !less)
    );

// When a is less than b, only less is asserted.
    check_less_case: assert property (
        @(posedge clk) (a < b) |-> (!equal && !greater && less)
    );

// equal high means the inputs must match.
    check_equal_implies_inputs_equal: assert property (
        @(posedge clk) equal |-> (a == b)
    );

// greater high means a must be larger than b.
    check_greater_implies_a_gt_b: assert property (
        @(posedge clk) greater |-> (a > b)
    );

// less high means a must be smaller than b.
    check_less_implies_a_lt_b: assert property (
        @(posedge clk) less |-> (a < b)
    );

// Exactly one comparison result is asserted at a time.
    check_outputs_onehot: assert property (
        @(posedge clk)
        (equal || greater || less) &&
        !(equal && greater) &&
        !(equal && less) &&
        !(greater && less)
    );

// Active-low reset forces dout to zero on any sampled clock.
    check_reset_clears_dout: assert property (
        @(posedge clk) (!rst) |-> (dout == 4'b0000)
    );

// A sampled reset low leaves dout at zero on the following sampled clock.
    check_post_reset_stays_zero: assert property (
        @(posedge clk) (!rst) |=> (dout == 4'b0000)
    );

// With enable low, dout either holds its value or has been asynchronously cleared to zero.
    check_disabled_cycle_holds_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (!en) |=> ((dout == 4'b0000) || (dout == $past(dout)))
    );

// With enable high, dout either captures the prior din or has been asynchronously cleared to zero.
    check_enabled_cycle_loads_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> ((dout == 4'b0000) || (dout == $past(din)))
    );

// Output equals the OR of the three inputs.
    check_output_matches_or: assert property (
        @(posedge clk) O == (A1 | A2 | A3)
    );

// Output is low when all inputs are low.
    check_all_inputs_low_drives_output_low: assert property (
        @(posedge clk) (!(A1 | A2 | A3)) |-> (!O)
    );

// A high A1 input forces the output high.
    check_a1_high_drives_output_high: assert property (
        @(posedge clk) A1 |-> O
    );

// A high A2 input forces the output high.
    check_a2_high_drives_output_high: assert property (
        @(posedge clk) A2 |-> O
    );

// A high A3 input forces the output high.
    check_a3_high_drives_output_high: assert property (
        @(posedge clk) A3 |-> O
    );

// Output always matches the implemented mux expression.
    check_mux_function: assert property (
        @(posedge clk) data_out === (scan_mode ? data_in_scan : data_in_func)
    );

// When scan mode is enabled, the scan input is selected.
    check_scan_path_selected: assert property (
        @(posedge clk) (scan_mode === 1'b1) |-> (data_out === data_in_scan)
    );

// When scan mode is disabled, the functional input is selected.
    check_functional_path_selected: assert property (
        @(posedge clk) (scan_mode === 1'b0) |-> (data_out === data_in_func)
    );

// If both inputs are equal, the output matches that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (data_in_scan === data_in_func) |-> (data_out === data_in_scan)
    );

// in1=00 always produces zero.
    check_in1_zero_forces_zero: assert property (
        @(posedge clk) (in1 == 2'b00) |-> (res == 3'b000)
    );

// in2=00 always produces zero.
    check_in2_zero_forces_zero: assert property (
        @(posedge clk) (in2 == 2'b00) |-> (res == 3'b000)
    );

// in1=01 maps res to zero-extended in2.
    check_in1_one_maps_in2_direct: assert property (
        @(posedge clk) (in1 == 2'b01) |-> (res == {1'b0, in2})
    );

// in1=10 maps res to in2 shifted left by one.
    check_in1_two_maps_in2_shifted: assert property (
        @(posedge clk) (in1 == 2'b10) |-> (res == {in2, 1'b0})
    );

// in1=11 and in2=00 produces zero.
    check_in1_three_in2_zero: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b00)) |-> (res == 3'b000)
    );

// in1=11 and in2=01 produces 110.
    check_in1_three_in2_one: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b01)) |-> (res == 3'b110)
    );

// in1=11 and in2=10 produces 011.
    check_in1_three_in2_two: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b10)) |-> (res == 3'b011)
    );

// in1=11 and in2=11 produces 111.
    check_in1_three_in2_three: assert property (
        @(posedge clk) ((in1 == 2'b11) && (in2 == 2'b11)) |-> (res == 3'b111)
    );

// If clear stays low across clocks, the counter must be zero.
    check_clear_holds_zero: assert property (
        @(posedge clk)
        (!clear ##1 !clear) |-> (count_out == 4'b0000)
    );

// Load captures data_in on the next clock unless async clear forces zero.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!clear)
        load |=> ((count_out == $past(data_in)) || (count_out == 4'b0000))
    );

// Without load, up_down high increments on the next clock unless async clear forces zero.
    check_increment_behavior: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && up_down) |=> ((count_out == ($past(count_out) + 4'b0001)) || (count_out == 4'b0000))
    );

// Without load, up_down low decrements on the next clock unless async clear forces zero.
    check_decrement_behavior: assert property (
        @(posedge clk) disable iff (!clear)
        (!load && !up_down) |=> ((count_out == ($past(count_out) - 4'b0001)) || (count_out == 4'b0000))
    );

// Reset forces count, state, and output to zero.
    check_reset_values: assert property (
        @(posedge clk) !rst_n |-> (count == 10'd0 && state == 2'b00 && out == 1'b0)
    );

// Synchronous reset clears both registered outputs.
    check_reset_clears_outputs: assert property (
        @(posedge Clk) Rst |=> ({Cout, Sum} == 5'b00000)
    );

// With enable low, the registered outputs hold their value.
    check_hold_when_disabled: assert property (
        @(posedge Clk) disable iff (Rst)
        !En |=> $stable({Cout, Sum})
    );

// With enable high, the next state is the previous sum plus Cin, A, and B.
    check_enable_updates_outputs: assert property (
        @(posedge Clk) disable iff (Rst)
        En |=> ({Cout, Sum} == ({1'b0, $past(Sum)} + $past(Cin) + $past(A) + $past(B)))
    );

// With enable high and all three addends high, the state increments by three.
    check_all_addends_high_increment_by_three: assert property (
        @(posedge Clk) disable iff (Rst)
        (En && Cin && A && B) |=> ({Cout, Sum} == ({1'b0, $past(Sum)} + 5'd3))
    );

// Synchronous reset clears the full register.
    check_reset_clears_q: assert property (
        @(posedge clk)
        reset |=> (q == 16'h0000)
    );

// Low byte updates from d when enabled and selected.
    check_low_byte_write: assert property (
        @(posedge clk) disable iff (reset)
        (en && byte_lo) |=> (q[7:0] == $past(d[7:0]))
    );

// Low byte holds its value when not written.
    check_low_byte_hold: assert property (
        @(posedge clk) disable iff (reset)
        (!en || !byte_lo) |=> (q[7:0] == $past(q[7:0]))
    );

// High byte updates from d when enabled and selected.
    check_high_byte_write: assert property (
        @(posedge clk) disable iff (reset)
        (en && byte_hi) |=> (q[15:8] == $past(d[15:8]))
    );

// High byte holds its value when not written.
    check_high_byte_hold: assert property (
        @(posedge clk) disable iff (reset)
        (!en || !byte_hi) |=> (q[15:8] == $past(q[15:8]))
    );

// port_rd_data is a direct pass-through of rd_data.
    check_port_rd_data_passthrough: assert property (
        @(posedge clk) port_rd_data === rd_data
    );

// When only port0 is enabled, rd_addr selects port0 and rd_en is asserted.
    check_port0_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0001)
        |-> ((rd_en === 1'b1) && (rd_addr === port0_rd_addr))
    );

// When only port1 is enabled, rd_addr selects port1 and rd_en is asserted.
    check_port1_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0010)
        |-> ((rd_en === 1'b1) && (rd_addr === port1_rd_addr))
    );

// When only port2 is enabled, rd_addr selects port2 and rd_en is asserted.
    check_port2_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0100)
        |-> ((rd_en === 1'b1) && (rd_addr === port2_rd_addr))
    );

// When only port3 is enabled, rd_addr selects port3 and rd_en is asserted.
    check_port3_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_1000)
        |-> ((rd_en === 1'b1) && (rd_addr === port3_rd_addr))
    );

// When only port4 is enabled, rd_addr selects port4 and rd_en is asserted.
    check_port4_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0001_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port4_rd_addr))
    );

// When only port5 is enabled, rd_addr selects port5 and rd_en is asserted.
    check_port5_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0010_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port5_rd_addr))
    );

// When only port6 is enabled, rd_addr selects port6 and rd_en is asserted.
    check_port6_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0100_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port6_rd_addr))
    );

// When only port7 is enabled, rd_addr selects port7 and rd_en is asserted.
    check_port7_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b1000_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port7_rd_addr))
    );

// When no ports are enabled, rd_en is deasserted.
    check_no_port_enabled: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0000)
        |-> (rd_en === 1'b0)
    );

// A sampled reset cycle clears all flip-flop outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (q_d == 1'b0) && (q_jk == 1'b0) && (q_t == 1'b0) && (q_sr == 1'b0)
    );

// The D flip-flop captures d on each active clock edge.
    check_dff_captures_d: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (q_d == $past(d))
    );

// The JK flip-flop toggles when both j and k are high.
    check_jkff_toggles_when_jk_high: assert property (
        @(posedge clk) disable iff (rst) (j && k) |=> (q_jk == ~$past(q_jk))
    );

// The JK flip-flop holds its state when j and k are not both high.
    check_jkff_holds_when_not_jk_high: assert property (
        @(posedge clk) disable iff (rst) (!(j && k)) |=> (q_jk == $past(q_jk))
    );

// The T flip-flop toggles when t is high.
    check_tff_toggles_when_t_high: assert property (
        @(posedge clk) disable iff (rst) t |=> (q_t == ~$past(q_t))
    );

// The T flip-flop holds its state when t is low.
    check_tff_holds_when_t_low: assert property (
        @(posedge clk) disable iff (rst) (!t) |=> (q_t == $past(q_t))
    );

// The SR flip-flop sets when s is high and r is low.
    check_srff_sets_when_s_high_r_low: assert property (
        @(posedge clk) disable iff (rst) (s && !r) |=> (q_sr == 1'b1)
    );

// The SR flip-flop clears when s is low and r is high.
    check_srff_clears_when_s_low_r_high: assert property (
        @(posedge clk) disable iff (rst) (!s && r) |=> (q_sr == 1'b0)
    );

// The SR flip-flop holds its state when s and r are equal.
    check_srff_holds_when_s_equals_r: assert property (
        @(posedge clk) disable iff (rst) ((s && r) || (!s && !r)) |=> (q_sr == $past(q_sr))
    );

// Reset low at a sampled clock forces Q low by the next clock.
    check_reset_clears_q_next_clock: assert property (
        @(posedge C) !R |=> (Q == 1'b0)
    );

// With reset high, a sampled 0 on D is captured as 0 on the next clock.
    check_capture_zero_on_clock: assert property (
        @(posedge C) (R && !D) |=> (Q == 1'b0)
    );

// A high Q must come from a prior clock with reset high and D high.
    check_q_high_requires_prior_high_input: assert property (
        @(posedge C) disable iff (!R) 1'b1 |=> (Q |-> $past(R && D))
    );

// The 5-bit output matches A + B + Cin.
    check_total_addition: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// The LSB sum bit is the XOR of A[0], B[0], and Cin.
    check_lsb_sum: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// With B at zero, the result is A plus Cin.
    check_add_zero_b: assert property (
        @(posedge clk) (B == 4'h0) |-> ({Cout, Sum} == ({1'b0, A} + Cin))
    );

// With A at zero, the result is B plus Cin.
    check_add_zero_a: assert property (
        @(posedge clk) (A == 4'h0) |-> ({Cout, Sum} == ({1'b0, B} + Cin))
    );

// If only bit 0 can contribute, bits above bit 1 must stay low.
    check_bit0_only_range: assert property (
        @(posedge clk) (A[3:1] == 3'b000 && B[3:1] == 3'b000) |-> (Sum[3:2] == 2'b00 && Cout == 1'b0)
    );

// Adding 1 to 4'hF must ripple a carry through all four stages.
    check_full_carry_propagation: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h0 && Cin == 1'b1) |-> (Sum == 4'h0 && Cout == 1'b1)
    );

// A plus its bitwise complement with Cin set must produce zero with carry out.
    check_twos_complement_identity: assert property (
        @(posedge clk) (B == ~A && Cin == 1'b1) |-> (Sum == 4'h0 && Cout == 1'b1)
    );

// A plus its bitwise complement with Cin clear must produce 4'hF.
    check_complement_without_carry_in: assert property (
        @(posedge clk) (B == ~A && Cin == 1'b0) |-> (Sum == 4'hF && Cout == 1'b0)
    );

// With no lower-bit carry, the MSB stage behaves as a single full adder.
    check_msb_no_lower_carry: assert property (
        @(posedge clk) (A[2:0] == 3'b000 && B[2:0] == 3'b000 && Cin == 1'b0) |->
            (Sum[2:0] == 3'b000 && Sum[3] == (A[3] ^ B[3]) && Cout == (A[3] & B[3]))
    );

// No clock or reset exists in the RTL.
    // Logic is purely combinational: Y is the buffered inversion of A.

    // Before A rises, the inverter output must be high.
    check_a_rise_starts_with_y_high: assert property (
        @(posedge A) Y === 1'b1
    );

// Before A falls, the inverter output must be low.
    check_a_fall_starts_with_y_low: assert property (
        @(negedge A) Y === 1'b0
    );

// Before Y rises, the input must be high.
    check_y_rise_starts_with_a_high: assert property (
        @(posedge Y) A === 1'b1
    );

// Before Y falls, the input must be low.
    check_y_fall_starts_with_a_low: assert property (
        @(negedge Y) A === 1'b0
    );

// When disabled, the output must be forced low.
    check_disable_forces_zero: assert property (
        @(posedge clk) (EN == 1'b1) |-> (X == 1'b0)
    );

// When enabled with select 00, X must follow A0.
    check_select_a0_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b0 && S1 == 1'b0) |-> (X == A0)
    );

// When enabled with select 01, X must follow A1.
    check_select_a1_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b0 && S1 == 1'b1) |-> (X == A1)
    );

// When enabled with select 10, X must follow A2.
    check_select_a2_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b1 && S1 == 1'b0) |-> (X == A2)
    );

// When enabled with select 11, X must follow A3.
    check_select_a3_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b1 && S1 == 1'b1) |-> (X == A3)
    );

// X must always match the implemented mux equation.
    check_output_matches_mux_equation: assert property (
        @(posedge clk)
        X == ((EN == 1'b0) ? ((S0 & S1) ? A3 : (S0 ? A2 : (S1 ? A1 : A0))) : 1'b0)
    );

// sel=000 drives out from the OR of data0 and data1.
    check_sel_000_or_data0_data1: assert property (
        @(posedge clk) (sel == 3'b000) |-> (out == (data0 | data1))
    );

// sel=001 uses the same effective data0/data1 OR result.
    check_sel_001_or_data0_data1: assert property (
        @(posedge clk) (sel == 3'b001) |-> (out == (data0 | data1))
    );

// sel=010 drives out from replicated OR of data2[3] and data3[3].
    check_sel_010_replicated_msb_or: assert property (
        @(posedge clk) (sel == 3'b010) |-> (out == {4{data2[3] | data3[3]}})
    );

// sel=011 drives out from replicated OR of data2[0] and data3[0].
    check_sel_011_replicated_lsb_or: assert property (
        @(posedge clk) (sel == 3'b011) |-> (out == {4{data2[0] | data3[0]}})
    );

// sel=100 forces the output to zero.
    check_sel_100_forces_zero: assert property (
        @(posedge clk) (sel == 3'b100) |-> (out == 4'b0000)
    );

// Unhandled sel values drive zero.
    check_sel_default_forces_zero: assert property (
        @(posedge clk) ((sel == 3'b101) || (sel == 3'b110) || (sel == 3'b111)) |-> (out == 4'b0000)
    );

// When ctrl is low, the output must pass D0.
    check_select_d0: assert property (
        @(posedge clk) disable iff (1'b0)
        (ctrl == 1'b0) |-> (S == D0)
    );

// When ctrl is high, the output must pass D1.
    check_select_d1: assert property (
        @(posedge clk) disable iff (1'b0)
        (ctrl == 1'b1) |-> (S == D1)
    );

// The output must always match the mux select expression.
    check_mux_function: assert property (
        @(posedge clk) disable iff (1'b0)
        S == (ctrl ? D1 : D0)
    );

// Reset drives the registered output to 000 on the next cycle.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (out == 3'b000)
    );

// 000 rotates back to 000 in normal operation.
    check_state_000_to_000: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b000) |=> (out == 3'b000)
    );

// 001 rotates to 010 in normal operation.
    check_state_001_to_010: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b001) |=> (out == 3'b010)
    );

// 010 rotates to 100 in normal operation.
    check_state_010_to_100: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b010) |=> (out == 3'b100)
    );

// 011 rotates to 110 in normal operation.
    check_state_011_to_110: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b011) |=> (out == 3'b110)
    );

// 100 rotates to 001 in normal operation.
    check_state_100_to_001: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b100) |=> (out == 3'b001)
    );

// 101 rotates to 011 in normal operation.
    check_state_101_to_011: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b101) |=> (out == 3'b011)
    );

// 110 rotates to 101 in normal operation.
    check_state_110_to_101: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b110) |=> (out == 3'b101)
    );

// 111 rotates back to 111 in normal operation.
    check_state_111_to_111: assert property (
        @(posedge clk) disable iff (reset) (out == 3'b111) |=> (out == 3'b111)
    );

// Data-path registers capture the EX-stage values on each clock.
    check_data_capture: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_aluresult == $past(ex_aluresult) &&
                  me_d2        == $past(ex_d2) &&
                  me_td        == $past(ex_td))
    );

// Control registers capture the EX-stage control bits on each clock.
    check_control_capture: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_WREG == $past(ex_WREG) &&
                  me_WMEM == $past(ex_WMEM) &&
                  me_LW   == $past(ex_LW))
    );

// The instruction register captures the EX-stage instruction on each clock.
    check_instr_capture: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (me_instr == $past(ex_instr))
    );

// Output always matches the implemented mux equation.
    check_output_matches_mux_equation: assert property (
        @(posedge clk) Y === ((S == 1'b0) ? A : B)
    );

// When select is 0, output follows A.
    check_select_zero_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

// When select is 1, output follows B.
    check_select_one_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

// If both inputs are equal, output matches that common value.
    check_equal_inputs_propagate: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

// Y is always the inversion of A.
    check_inverter_function: assert property (
        @(posedge clk) Y === ~A
    );

// A sampled low must produce Y sampled high.
    check_low_input_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A sampled high must produce Y sampled low.
    check_high_input_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// Q rotates by one bit on each rising edge.
    check_rotate_vector: assert property (
        @(posedge Clk) 1'b1 |=> (Q == $past({Q[2:0], Q[3]}))
    );

// Q[3] takes the previous value of Q[2].
    check_q3_from_prev_q2: assert property (
        @(posedge Clk) 1'b1 |=> (Q[3] == $past(Q[2]))
    );

// Q[2] takes the previous value of Q[1].
    check_q2_from_prev_q1: assert property (
        @(posedge Clk) 1'b1 |=> (Q[2] == $past(Q[1]))
    );

// Q[1] takes the previous value of Q[0].
    check_q1_from_prev_q0: assert property (
        @(posedge Clk) 1'b1 |=> (Q[1] == $past(Q[0]))
    );

// Q[0] takes the previous value of Q[3].
    check_q0_from_prev_q3: assert property (
        @(posedge Clk) 1'b1 |=> (Q[0] == $past(Q[3]))
    );

// Four rotations return Q to its earlier value.
    check_period_four: assert property (
        @(posedge Clk) 1'b1 |=> ##3 (Q == $past(Q, 4))
    );

// Carry matches the implemented AND of A&B and A^B.
    check_carry_equation: assert property (
        @(posedge clk) CO == ((A & B) & (A ^ B))
    );

// Sum matches the implemented XOR of A^B with CO.
    check_sum_equation: assert property (
        @(posedge clk) S == ((A ^ B) ^ CO)
    );

// The implemented carry term is mutually exclusive and always low.
    check_carry_always_low: assert property (
        @(posedge clk) CO == 1'b0
    );

// With carry low, the sum reduces to A XOR B.
    check_sum_reduces_to_xor: assert property (
        @(posedge clk) S == (A ^ B)
    );

// equal matches bitwise equality of A and B.
    check_equal_flag: assert property (
        @(posedge clk) equal == (A == B)
    );

// signed_larger matches the signed A > B comparison.
    check_signed_larger_flag: assert property (
        @(posedge clk) signed_larger == ($signed(A) > $signed(B))
    );

// signed_smaller matches the signed A < B comparison.
    check_signed_smaller_flag: assert property (
        @(posedge clk) signed_smaller == ($signed(A) < $signed(B))
    );

// signed_larger and signed_smaller cannot both be high.
    check_compare_flags_mutex: assert property (
        @(posedge clk) !(signed_larger && signed_smaller)
    );

// larger_num selects A when signed_larger is true, else B.
    check_larger_num_select: assert property (
        @(posedge clk) larger_num == (signed_larger ? A : B)
    );

// smaller_num selects A when signed_smaller is true, else B.
    check_smaller_num_select: assert property (
        @(posedge clk) smaller_num == (signed_smaller ? A : B)
    );

// Output must match the complete enable-controlled 4:1 mux function.
    check_full_mux_function: assert property (
        @(posedge clk)
        out == ((en == 1'b1) ?
                ((sel == 2'b00) ? in0 :
                 (sel == 2'b01) ? in1 :
                 (sel == 2'b10) ? in2 : in3) :
                4'b0000)
    );

// Output must be zero whenever the mux is disabled.
    check_output_zero_when_disabled: assert property (
        @(posedge clk)
        (en == 1'b0) |-> (out == 4'b0000)
    );

// When enabled with sel=00, output must equal in0.
    check_select_in0_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b00)) |-> (out == in0)
    );

// When enabled with sel=01, output must equal in1.
    check_select_in1_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b01)) |-> (out == in1)
    );

// When enabled with sel=10, output must equal in2.
    check_select_in2_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b10)) |-> (out == in2)
    );

// When enabled with sel=11, output must equal in3.
    check_select_in3_when_enabled: assert property (
        @(posedge clk)
        ((en == 1'b1) && (sel == 2'b11)) |-> (out == in3)
    );

// out0 is driven as the inverse of the input.
    check_out0_inverse_of_in: assert property (
        @(posedge clk) out0 == ~in
    );

// out3 directly follows the input.
    check_out3_matches_in: assert property (
        @(posedge clk) out3 == in
    );

// out1 is always low.
    check_out1_constant_low: assert property (
        @(posedge clk) out1 == 1'b0
    );

// out2 is always low.
    check_out2_constant_low: assert property (
        @(posedge clk) out2 == 1'b0
    );

// Exactly one output is high on every sampled cycle.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({out0, out1, out2, out3})
    );

// A low input selects only out0.
    check_input_low_selects_out0: assert property (
        @(posedge clk) (in == 1'b0) |-> (out0 && !out1 && !out2 && !out3)
    );

// A high input selects only out3.
    check_input_high_selects_out3: assert property (
        @(posedge clk) (in == 1'b1) |-> (!out0 && !out1 && !out2 && out3)
    );

// out matches the inverted-input AND function in the RTL.
    check_out_matches_inverted_and: assert property (
        @(posedge clk) out == ((~in[0]) & (~in[1]) & (~in[2]))
    );

// An all-zero input vector drives out high.
    check_all_zero_input_drives_high: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 1'b1)
    );

// A high in[0] forces out low.
    check_in0_high_forces_out_low: assert property (
        @(posedge clk) in[0] |-> (out == 1'b0)
    );

// A high in[1] forces out low.
    check_in1_high_forces_out_low: assert property (
        @(posedge clk) in[1] |-> (out == 1'b0)
    );

// A high in[2] forces out low.
    check_in2_high_forces_out_low: assert property (
        @(posedge clk) in[2] |-> (out == 1'b0)
    );

// First active cycle after reset release still shows the cleared state.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        $rose(reset_n) |-> (out_port == 32'h00000000 && readdata == 32'h00000000)
    );

// Without an active write, the accumulator state holds.
    check_no_write_holds_state: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n) |=> (out_port == $past(out_port))
    );

// Address 0 writes add writedata into the accumulator.
    check_write_add: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == ($past(out_port) + $past(writedata)))
    );

// Address 1 writes subtract writedata from the accumulator.
    check_write_sub: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b01)) |=> (out_port == ($past(out_port) - $past(writedata)))
    );

// Address 2 writes AND writedata with the accumulator.
    check_write_and: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b10)) |=> (out_port == ($past(out_port) & $past(writedata)))
    );

// Address 3 writes OR writedata with the accumulator.
    check_write_or: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b11)) |=> (out_port == ($past(out_port) | $past(writedata)))
    );

// When address[1] is low, readdata mirrors the current state.
    check_read_low_addresses_return_state: assert property (
        @(posedge clk) disable iff (!reset_n)
        !address[1] |-> (readdata == out_port)
    );

// When address[1] is high, readdata is zero.
    check_read_high_addresses_return_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        address[1] |-> (readdata == 32'h00000000)
    );

// Output implements the RTL equation y = ~a & ~b.
    check_output_equation: assert property (
        @(posedge clk) y == (~a & ~b)
    );

// When both inputs are low, the output must be high.
    check_both_low_drive_high: assert property (
        @(posedge clk) (!a && !b) |-> y
    );

// A high on input a forces the output low.
    check_a_high_drives_low: assert property (
        @(posedge clk) a |-> !y
    );

// A high on input b forces the output low.
    check_b_high_drives_low: assert property (
        @(posedge clk) b |-> !y
    );

// No reset is present in the RTL; sample combinational behavior on clk.

    // EQ is high exactly when all four inputs are equal.
    check_eq_definition: assert property (
        @(posedge clk) EQ === ((A == B) && (B == C) && (C == D))
    );

// GT is high exactly for strict descending order or the all-equal case.
    check_gt_definition: assert property (
        @(posedge clk) GT === (((A > B) && (B > C) && (C > D)) || ((A == B) && (B == C) && (C == D)))
    );

// All equal inputs drive both EQ and GT high.
    check_all_equal_outputs_high: assert property (
        @(posedge clk) ((A == B) && (B == C) && (C == D)) |-> ((EQ === 1'b1) && (GT === 1'b1))
    );

// Strict descending inputs drive GT high and EQ low.
    check_strict_descending_outputs: assert property (
        @(posedge clk) ((A > B) && (B > C) && (C > D)) |-> ((GT === 1'b1) && (EQ === 1'b0))
    );

// EQ can only be high when GT is also high.
    check_eq_implies_gt: assert property (
        @(posedge clk) (EQ === 1'b1) |-> (GT === 1'b1)
    );

// GT without EQ means the inputs are strictly descending.
    check_gt_without_eq_means_descending: assert property (
        @(posedge clk) ((GT === 1'b1) && (EQ === 1'b0)) |-> ((A > B) && (B > C) && (C > D))
    );

// Any break in the equality chain keeps EQ low.
    check_mismatch_clears_eq: assert property (
        @(posedge clk) !((A == B) && (B == C) && (C == D)) |-> (EQ === 1'b0)
    );

// Inputs outside the two GT cases keep GT low.
    check_nonqualifying_inputs_clear_gt: assert property (
        @(posedge clk) !(((A > B) && (B > C) && (C > D)) || ((A == B) && (B == C) && (C == D))) |-> (GT === 1'b0)
    );

// Y matches the OR-NAND-buffer logic function.
    check_y_matches_o31ai_function: assert property (
        @(posedge clk) Y == ~(B1 & (A1 | A2 | A3))
    );

// A low B1 forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) !B1 |-> Y
    );

// With all A inputs low, the OR term is low and Y is high.
    check_all_a_low_forces_y_high: assert property (
        @(posedge clk) (!A1 && !A2 && !A3) |-> Y
    );

// B1 high and any asserted A input forces Y low.
    check_b1_and_any_a_high_forces_y_low: assert property (
        @(posedge clk) (B1 && (A1 || A2 || A3)) |-> !Y
    );

// The A1 path participates in driving Y low when B1 is high.
    check_a1_with_b1_forces_y_low: assert property (
        @(posedge clk) (B1 && A1) |-> !Y
    );

// The A2 path participates in driving Y low when B1 is high.
    check_a2_with_b1_forces_y_low: assert property (
        @(posedge clk) (B1 && A2) |-> !Y
    );

// The A3 path participates in driving Y low when B1 is high.
    check_a3_with_b1_forces_y_low: assert property (
        @(posedge clk) (B1 && A3) |-> !Y
    );

// A low Y requires B1 high and the OR term high.
    check_y_low_requires_active_nand_inputs: assert property (
        @(posedge clk) !Y |-> (B1 && (A1 || A2 || A3))
    );

// If B1 is high and Y is high, the OR term must be low.
    check_y_high_with_b1_requires_or_term_low: assert property (
        @(posedge clk) (B1 && Y) |-> (!A1 && !A2 && !A3)
    );

// Addition opcode computes the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk) (opcode == 2'b00) |-> (result == u8_t'(A + B))
    );

// Subtraction opcode computes the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk) (opcode == 2'b01) |-> (result == u8_t'(A - B))
    );

// Division by zero returns the error code 8'hFF.
    check_division_by_zero_result: assert property (
        @(posedge clk) (opcode == 2'b11 && B == 8'h00) |-> (result == 8'hFF)
    );

// Gray matches the prior cycle binary-to-Gray conversion.
    check_gray_registered_mapping: assert property (
        @(posedge clk) 1'b1 |=> (gray === ({1'b0, $past(bin[3:1])} ^ $past(bin)))
    );

// Gray[3] is the registered MSB of bin.
    check_gray_bit3_mapping: assert property (
        @(posedge clk) 1'b1 |=> (gray[3] === $past(bin[3]))
    );

// Gray[2] is the registered XOR of bin[3] and bin[2].
    check_gray_bit2_mapping: assert property (
        @(posedge clk) 1'b1 |=> (gray[2] === ($past(bin[3]) ^ $past(bin[2])))
    );

// Gray[1] is the registered XOR of bin[2] and bin[1].
    check_gray_bit1_mapping: assert property (
        @(posedge clk) 1'b1 |=> (gray[1] === ($past(bin[2]) ^ $past(bin[1])))
    );

// Gray[0] is the registered XOR of bin[1] and bin[0].
    check_gray_bit0_mapping: assert property (
        @(posedge clk) 1'b1 |=> (gray[0] === ($past(bin[1]) ^ $past(bin[0])))
    );

// Output matches the RTL XOR chain of all four inputs.
    check_out_matches_rtl_xor_chain: assert property (
        @(posedge clk) out == (c ^ d ^ (a ^ b))
    );

// A sampled active-low reset must leave Q low at the next clock sample.
    check_reset_forces_q_low: assert property (
        @(posedge CLK)
        !RESET_B |=> (Q == 1'b0)
    );

// With reset inactive, SCE forces Q low whenever SCD is low.
    check_sce_forces_q_low: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && SCE) |=> (Q == 1'b0)
    );

// With reset inactive and both controls low, D=0 is captured into Q.
    check_d_zero_captured: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && !SCE && !D) |=> (Q == 1'b0)
    );

// Q can rise only from the SCD path or from capturing D=1 with both controls low.
    check_q_rise_has_valid_source: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        $rose(Q) |-> ($past(SCD) || (!$past(SCD) && !$past(SCE) && $past(D)))
    );

// Output matches the OR of the two inputs.
    check_or_function: assert property (
        @(posedge clk) X == (A | B)
    );

// Both inputs low forces the output low.
    check_both_low_drive_low: assert property (
        @(posedge clk) (!A && !B) |-> (X == 1'b0)
    );

// A high input forces the output high.
    check_a_high_drives_high: assert property (
        @(posedge clk) A |-> (X == 1'b1)
    );

// B high input forces the output high.
    check_b_high_drives_high: assert property (
        @(posedge clk) B |-> (X == 1'b1)
    );

// A low output implies both inputs are low.
    check_low_output_requires_low_inputs: assert property (
        @(posedge clk) !X |-> (!A && !B)
    );

// Combinational DUT; clk is only used to sample assertions.

    // sel=00 routes the low 32 bits of in0 and zero-extends the result.
    check_sel_00_routes_in0_low: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == {32'b0, in0[31:0]})
    );

// sel=01 routes the high 32 bits of in0 and zero-extends the result.
    check_sel_01_routes_in0_high: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == {32'b0, in0[63:32]})
    );

// sel=10 routes the low 32 bits of in1 and zero-extends the result.
    check_sel_10_routes_in1_low: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == {32'b0, in1[31:0]})
    );

// sel=11 routes the high 32 bits of in1 and zero-extends the result.
    check_sel_11_routes_in1_high: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == {32'b0, in1[63:32]})
    );

// The upper 32 bits of out are always zero due to 32-to-64 bit assignment.
    check_upper_half_zero: assert property (
        @(posedge clk) out[63:32] == 32'b0
    );

// X implements A OR B OR the NAND of C_N and D_N.
    check_function_equation: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A being high forces X high.
    check_a_forces_high: assert property (
        @(posedge clk) A |-> X
    );

// B being high forces X high.
    check_b_forces_high: assert property (
        @(posedge clk) B |-> X
    );

// C_N being low forces X high through the NAND term.
    check_c_n_low_forces_high: assert property (
        @(posedge clk) !C_N |-> X
    );

// D_N being low forces X high through the NAND term.
    check_d_n_low_forces_high: assert property (
        @(posedge clk) !D_N |-> X
    );

// X is low only in the all-inactive input case.
    check_all_inactive_drives_low: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> !X
    );

// Clock: clk. No reset is present in the RTL.
    // Mixed logic: registered modulo-8 counter with combinational output cycle.

    // enn high synchronously clears the counter to zero.
    check_clear_on_enn: assert property (
        @(posedge clk) enn |=> cycle == 3'b000
    );

// With enn low and no rollover, the counter increments by one.
    check_increment_when_enn_low: assert property (
        @(posedge clk) (!enn && cycle != 3'b111) |=> cycle == ($past(cycle) + 3'b001)
    );

// With enn low at the maximum value, the counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) (!enn && cycle == 3'b111) |=> cycle == 3'b000
    );

// Eight consecutive count cycles return to the starting value.
    check_full_modulo_cycle: assert property (
        @(posedge clk) (!enn)[*8] |=> cycle == $past(cycle, 8)
    );

// A clear followed by one count cycle produces a value of one.
    check_clear_then_count: assert property (
        @(posedge clk) enn ##1 !enn |=> cycle == 3'b001
    );

// Synchronous reset drives ENCLK low on the next clock.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RST |=> (ENCLK == 1'b0)
    );

// Reset has priority over TE when both are asserted.
    check_reset_overrides_te: assert property (
        @(posedge CLK) (RST && TE) |=> (ENCLK == 1'b0)
    );

// When TE is high, EN=1 is captured into ENCLK.
    check_te_captures_one: assert property (
        @(posedge CLK) disable iff (RST) (TE && EN) |=> (ENCLK == 1'b1)
    );

// When TE is high, EN=0 is captured into ENCLK.
    check_te_captures_zero: assert property (
        @(posedge CLK) disable iff (RST) (TE && !EN) |=> (ENCLK == 1'b0)
    );

// When TE is low, a high ENCLK value is held.
    check_hold_high_when_te_low: assert property (
        @(posedge CLK) disable iff (RST) (!TE && ENCLK) |=> (ENCLK == 1'b1)
    );

// When TE is low, a low ENCLK value is held.
    check_hold_low_when_te_low: assert property (
        @(posedge CLK) disable iff (RST) (!TE && !ENCLK) |=> (ENCLK == 1'b0)
    );

// upper_byte is sum[15:8].
    check_decoder_upper_byte: assert property (
        @(posedge clk) (upper_byte == sum[15:8])
    );

// lower_byte is sum[7:0].
    check_decoder_lower_byte: assert property (
        @(posedge clk) (lower_byte == sum[7:0])
    );

// When select is high, out follows product.
    check_output_select_product: assert property (
        @(posedge clk) select |-> (out == product)
    );

// When select is low, the 16-bit decoder path truncates to lower_byte.
    check_output_select_decoder_low_byte: assert property (
        @(posedge clk) !select |-> (out == lower_byte)
    );

// out matches the implemented 8-bit mux behavior.
    check_output_mux_behavior: assert property (
        @(posedge clk) (out == (select ? product : lower_byte))
    );

// Reset drives the observable clock state to 00:00:12 AM by the next sampled cycle.
    check_reset_state: assert property (
        @(posedge clk) reset |=> (sec == 6'd0 && min == 6'd0 && hr == 5'd12 && ampm == 1'b0)
    );

// When seconds have not wrapped, only seconds increment.
    check_second_increment: assert property (
        @(posedge clk) disable iff (reset)
        (sec < 6'd49) |=> (sec == ($past(sec) + 6'd1) &&
                           min == $past(min) &&
                           hr == $past(hr) &&
                           ampm == $past(ampm))
    );

// At second wrap, minutes increment and hours/AMPM hold when minutes have not wrapped.
    check_minute_increment: assert property (
        @(posedge clk) disable iff (reset)
        (sec == 6'd49 && min < 6'd59) |=> (sec == 6'd0 &&
                                           min == ($past(min) + 6'd1) &&
                                           hr == $past(hr) &&
                                           ampm == $past(ampm))
    );

// At 1 through 10 with full rollover, the hour increments by one and AM/PM holds.
    check_hour_increment_midrange: assert property (
        @(posedge clk) disable iff (reset)
        (sec == 6'd49 && min == 6'd59 && hr >= 5'd1 && hr <= 5'd10) |=> (sec == 6'd0 &&
                                                                           min == 6'd0 &&
                                                                           hr == ($past(hr) + 5'd1) &&
                                                                           ampm == $past(ampm))
    );

// Sum registers the previous cycle's 4-bit addition of A, B, and Cin.
    check_sum_matches_previous_add: assert property (
        @(posedge Clock) 1'b1 |=> (Sum == ($past(A) + $past(B) + $past(Cin)))
    );

// Protocol 0 reports success.
    check_protocol0_status: assert property (
        @(posedge clk)
        (protocol_select == 1'b0) |=> (ack == 1'b1 && err == 1'b0)
    );

// Protocol 1 reports success.
    check_protocol1_status: assert property (
        @(posedge clk)
        (protocol_select == 1'b1) |=> (ack == 1'b1 && err == 1'b0)
    );

// An invalid protocol drives error and leaves out_data unchanged.
    check_invalid_protocol_response: assert property (
        @(posedge clk)
        ((protocol_select !== 1'b0) && (protocol_select !== 1'b1)) |=> (ack == 1'b0 && err == 1'b1 && out_data == $past(out_data))
    );

// ack and err are always complementary after each update.
    check_ack_err_complementary: assert property (
        @(posedge clk)
        1'b1 |=> (ack ^ err)
    );

// Load updates OUT_FLAG from IN_FLAG.
    check_load_updates_flag: assert property (
        @(posedge CLK) LD |=> (OUT_FLAG == $past(IN_FLAG))
    );

// SET drives OUT_FLAG high when load is not selected.
    check_set_updates_flag: assert property (
        @(posedge CLK) (!LD && SET) |=> (OUT_FLAG == 1'b1)
    );

// CLR drives OUT_FLAG low when neither load nor set is selected.
    check_clear_updates_flag: assert property (
        @(posedge CLK) (!LD && !SET && CLR) |=> (OUT_FLAG == 1'b0)
    );

// OUT_FLAG holds its value when no control is asserted.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LD && !SET && !CLR) |=> (OUT_FLAG == $past(OUT_FLAG))
    );

// LOAD has priority over SET and CLR.
    check_load_priority: assert property (
        @(posedge CLK) (LD && (SET || CLR)) |=> (OUT_FLAG == $past(IN_FLAG))
    );

// SET has priority over CLR when load is not asserted.
    check_set_priority_over_clear: assert property (
        @(posedge CLK) (!LD && SET && CLR) |=> (OUT_FLAG == 1'b1)
    );

// DUT is combinational; clk is an external sampling clock and there is no reset.

    // Y matches the implemented AOI21 boolean function.
    check_boolean_function: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// A high B1 input forces Y low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> ~Y
    );

// High A1 and A2 force the AND term high and drive Y low.
    check_and_term_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> ~Y
    );

// When B1 is low, Y reduces to the inverse of A1&A2.
    check_b1_low_reduces_to_nand: assert property (
        @(posedge clk) (~B1) |-> (Y == ~(A1 & A2))
    );

// A high output requires B1 to be low.
    check_y_high_requires_b1_low: assert property (
        @(posedge clk) Y |-> ~B1
    );

// A high output requires the A1/A2 AND term to be low.
    check_y_high_requires_and_term_low: assert property (
        @(posedge clk) Y |-> (~A1 | ~A2)
    );

// A low output must be caused by B1 or the A1/A2 AND term being high.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) (~Y) |-> (B1 | (A1 & A2))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset takes priority over enable.
    check_reset_overrides_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// When enabled below max, the counter increments by one.
    check_count_increments_below_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at max, the counter wraps to zero.
    check_count_wraps_at_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// When not enabled, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// Outputs must register the previous cycle's 5-bit addition.
    check_registered_addition: assert property (
        @(posedge clk)
        1'b1 |=> ({Cout, S} == ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)))
    );

// Overflow in the current cycle must set carry on the next cycle.
    check_overflow_sets_carry: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) > 5'd15) |=> (Cout == 1'b1)
    );

// No overflow in the current cycle must clear carry on the next cycle.
    check_no_overflow_clears_carry: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |=> (Cout == 1'b0)
    );

// Zero inputs must produce zero outputs on the next cycle.
    check_zero_case: assert property (
        @(posedge clk)
        (A == 4'd0 && B == 4'd0 && Cin == 1'b0) |=> (S == 4'd0 && Cout == 1'b0)
    );

// A sum of 15 must produce 0xF with no carry on the next cycle.
    check_boundary_fifteen: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) == 5'd15) |=> (S == 4'hF && Cout == 1'b0)
    );

// A sum of 16 must wrap to 0 with carry on the next cycle.
    check_boundary_sixteen: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) == 5'd16) |=> (S == 4'd0 && Cout == 1'b1)
    );

// Maximum inputs must produce 0xF with carry on the next cycle.
    check_max_input_case: assert property (
        @(posedge clk)
        (A == 4'hF && B == 4'hF && Cin == 1'b1) |=> (S == 4'hF && Cout == 1'b1)
    );

// Output is zero when ctrl selects 2'b00.
    check_ctrl_zero_output_zero: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (data_out == 4'b0000)
    );

// Output is all ones when ctrl selects 2'b01.
    check_ctrl_one_output_ones: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (data_out == 4'b1111)
    );

// Output passes data_in through when ctrl selects 2'b10.
    check_ctrl_two_passthrough: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (data_out == data_in)
    );

// Output is inverted data_in when ctrl selects 2'b11.
    check_ctrl_three_invert: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (data_out == ~data_in)
    );

// Output always matches the RTL mux expression.
    check_full_output_mapping: assert property (
        @(posedge clk)
        data_out == ((ctrl == 2'b00) ? 4'b0000 :
                     (ctrl == 2'b01) ? 4'b1111 :
                     (ctrl == 2'b10) ? data_in :
                                       ~data_in)
    );

// Y must equal the AND of all four inputs.
    check_y_matches_and4: assert property (
        @(posedge clk) Y == (A & B & C & D)
    );

// Y high requires all four inputs high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A & B & C & D)
    );

// All four inputs high must drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Y
    );

// Any low input must drive Y low.
    check_any_low_input_drives_y_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !Y
    );

// Combinational DUT sampled on external clk; RTL has no reset.

    // SUM equals the XOR parity of A, B, and CIN.
    check_sum_parity: assert property (
        @(posedge clk) SUM == ((A ^ B) ^ CIN)
    );

// COUT equals the implemented XOR chain of A, B, and CIN.
    check_cout_parity: assert property (
        @(posedge clk) COUT == ((A ^ B) ^ CIN)
    );

// SUM and COUT are always identical in this RTL.
    check_outputs_identical: assert property (
        @(posedge clk) SUM == COUT
    );

// Even input parity drives both outputs low.
    check_even_parity_low: assert property (
        @(posedge clk) !((A ^ B) ^ CIN) |-> ((SUM == 1'b0) && (COUT == 1'b0))
    );

// Odd input parity drives both outputs high.
    check_odd_parity_high: assert property (
        @(posedge clk) ((A ^ B) ^ CIN) |-> ((SUM == 1'b1) && (COUT == 1'b1))
    );

// A zero divisor forces the result to zero.
    check_divide_by_zero_returns_zero: assert property (
        @(posedge clk) (b == 32'd0) |-> (r == 32'd0)
    );

// D=0 must decode to the active-low seven-segment pattern for 0.
    check_decode_0: assert property (
        @(posedge clk) (D == 4'h0) |-> (S == 7'b0000001)
    );

// D=1 must decode to the active-low seven-segment pattern for 1.
    check_decode_1: assert property (
        @(posedge clk) (D == 4'h1) |-> (S == 7'b1001111)
    );

// D=2 must decode to the active-low seven-segment pattern for 2.
    check_decode_2: assert property (
        @(posedge clk) (D == 4'h2) |-> (S == 7'b0010010)
    );

// D=3 must decode to the active-low seven-segment pattern for 3.
    check_decode_3: assert property (
        @(posedge clk) (D == 4'h3) |-> (S == 7'b0000110)
    );

// D=4 must decode to the active-low seven-segment pattern for 4.
    check_decode_4: assert property (
        @(posedge clk) (D == 4'h4) |-> (S == 7'b1001100)
    );

// D=5 must decode to the active-low seven-segment pattern for 5.
    check_decode_5: assert property (
        @(posedge clk) (D == 4'h5) |-> (S == 7'b0100100)
    );

// D=6 must decode to the active-low seven-segment pattern for 6.
    check_decode_6: assert property (
        @(posedge clk) (D == 4'h6) |-> (S == 7'b0100000)
    );

// D=7 must decode to the active-low seven-segment pattern for 7.
    check_decode_7: assert property (
        @(posedge clk) (D == 4'h7) |-> (S == 7'b0001111)
    );

// D=8 must decode to the active-low seven-segment pattern for 8.
    check_decode_8: assert property (
        @(posedge clk) (D == 4'h8) |-> (S == 7'b0000000)
    );

// D=9 must decode to the active-low seven-segment pattern for 9.
    check_decode_9: assert property (
        @(posedge clk) (D == 4'h9) |-> (S == 7'b0000100)
    );

// D=A must decode to the active-low seven-segment pattern for A.
    check_decode_a: assert property (
        @(posedge clk) (D == 4'hA) |-> (S == 7'b0001000)
    );

// D=B must decode to the active-low seven-segment pattern for B.
    check_decode_b: assert property (
        @(posedge clk) (D == 4'hB) |-> (S == 7'b1100000)
    );

// D=C must decode to the active-low seven-segment pattern for C.
    check_decode_c: assert property (
        @(posedge clk) (D == 4'hC) |-> (S == 7'b0110001)
    );

// D=D must decode to the active-low seven-segment pattern for D.
    check_decode_d: assert property (
        @(posedge clk) (D == 4'hD) |-> (S == 7'b1000010)
    );

// D=E must decode to the active-low seven-segment pattern for E.
    check_decode_e: assert property (
        @(posedge clk) (D == 4'hE) |-> (S == 7'b0110000)
    );

// D=F must decode to the active-low seven-segment pattern for F.
    check_decode_f: assert property (
        @(posedge clk) (D == 4'hF) |-> (S == 7'b0111000)
    );

// Low SET_B overrides D and forces Q high on the next cycle.
    check_set_overrides_data: assert property (
        @(posedge CLK) (SET_B == 1'b0) |=> (Q == 1'b1)
    );

// With SET_B high and D low, Q captures 0 on the next cycle.
    check_capture_zero: assert property (
        @(posedge CLK) (SET_B == 1'b1) && (D == 1'b0) |=> (Q == 1'b0)
    );

// With SET_B high and D high, Q captures 1 on the next cycle.
    check_capture_one: assert property (
        @(posedge CLK) (SET_B == 1'b1) && (D == 1'b1) |=> (Q == 1'b1)
    );

// Reset clears Q on the clock edge.
    check_reset_clears_q: assert property (
        @(posedge C) R |=> (Q == 1'b0)
    );

// When enabled outside reset, Q captures D on the clock edge.
    check_enable_captures_d: assert property (
        @(posedge C) disable iff (R) E |=> (Q == $past(D))
    );

// When disabled outside reset, Q holds its previous value.
    check_disable_holds_q: assert property (
        @(posedge C) disable iff (R) !E |=> (Q == $past(Q))
    );

// Output is always the bitwise inverse of the input.
    check_output_matches_inverse: assert property (
        @(posedge clk) ones_comp == ~binary
    );

// Output bit 0 is the inverse of input bit 0.
    check_bit0_inverse: assert property (
        @(posedge clk) ones_comp[0] == ~(binary[0])
    );

// Output bit 1 is the inverse of input bit 1.
    check_bit1_inverse: assert property (
        @(posedge clk) ones_comp[1] == ~(binary[1])
    );

// Output bit 2 is the inverse of input bit 2.
    check_bit2_inverse: assert property (
        @(posedge clk) ones_comp[2] == ~(binary[2])
    );

// Output bit 3 is the inverse of input bit 3.
    check_bit3_inverse: assert property (
        @(posedge clk) ones_comp[3] == ~(binary[3])
    );

// sel_a has highest priority and selects a.
    check_sel_a_priority: assert property (
        @(posedge clk) sel_a |-> (out_mux == a)
    );

// When sel_a is low and both sel_b controls are low, b is selected.
    check_select_b_when_sel_b_low: assert property (
        @(posedge clk) (!sel_a && !sel_b1 && !sel_b2) |-> (out_mux == b)
    );

// When sel_a is low and both sel_b controls are high, c is selected.
    check_select_c_when_sel_b_high: assert property (
        @(posedge clk) (!sel_a && sel_b1 && sel_b2) |-> (out_mux == c)
    );

// When sel_a is low and the sel_b controls differ, d is selected.
    check_select_d_when_sel_b_mixed: assert property (
        @(posedge clk) (!sel_a && ((sel_b1 && !sel_b2) || (!sel_b1 && sel_b2))) |-> (out_mux == d)
    );

// Left-shift mode matches in shifted left by shift_amount.
    check_logical_left_shift: assert property (
        @(posedge clk)
        (shift_type == 2'b00) |-> (out == (in << shift_amount))
    );

// Right-shift mode matches in shifted right by shift_amount.
    check_logical_right_shift: assert property (
        @(posedge clk)
        (shift_type == 2'b01) |-> (out == (in >> shift_amount))
    );

// Default mode passes the input through unchanged.
    check_default_passthrough: assert property (
        @(posedge clk)
        (shift_type == 2'b11) |-> (out == in)
    );

// A zero shift amount leaves the output equal to the input.
    check_zero_shift_passthrough: assert property (
        @(posedge clk)
        (shift_amount == 5'd0) |-> (out == in)
    );

// Arithmetic right shift preserves a 1 sign bit for negative inputs.
    check_arith_shift_negative_sign_fill: assert property (
        @(posedge clk)
        (shift_type == 2'b10 && shift_amount != 5'd0 && in[31] == 1'b1) |-> (out[31] == 1'b1)
    );

// Arithmetic right shift preserves a 0 sign bit for non-negative inputs.
    check_arith_shift_positive_sign_fill: assert property (
        @(posedge clk)
        (shift_type == 2'b10 && shift_amount != 5'd0 && in[31] == 1'b0) |-> (out[31] == 1'b0)
    );

// While reset is asserted, outputs reflect a zeroed buffer and +1 chains.
    check_reset_output_values: assert property (
        @(posedge clk)
        !reset_n |-> ((Data_A == 12'd0) && (Data_B == 12'd1) &&
                      (Data_C == 12'd2) && (Data_D == 12'd3) &&
                      (Data_E == 12'd0) && (Data_F == 12'd1) &&
                      (Data_G == 12'd2) && (Data_H == 12'd3))
    );

// Data_E is always a duplicate of Data_A.
    check_data_e_matches_data_a: assert property (
        @(posedge clk) disable iff (!reset_n)
        (Data_E == Data_A)
    );

// Data_B is always Data_A plus one.
    check_data_b_from_data_a: assert property (
        @(posedge clk) disable iff (!reset_n)
        (Data_B == (Data_A + 12'd1))
    );

// Data_C is always Data_B plus one.
    check_data_c_from_data_b: assert property (
        @(posedge clk) disable iff (!reset_n)
        (Data_C == (Data_B + 12'd1))
    );

// Data_D is always Data_C plus one.
    check_data_d_from_data_c: assert property (
        @(posedge clk) disable iff (!reset_n)
        (Data_D == (Data_C + 12'd1))
    );

// Data_F is always Data_E plus one.
    check_data_f_from_data_e: assert property (
        @(posedge clk) disable iff (!reset_n)
        (Data_F == (Data_E + 12'd1))
    );

// Data_G is always Data_F plus one.
    check_data_g_from_data_f: assert property (
        @(posedge clk) disable iff (!reset_n)
        (Data_G == (Data_F + 12'd1))
    );

// Data_H is always Data_G plus one.
    check_data_h_from_data_g: assert property (
        @(posedge clk) disable iff (!reset_n)
        (Data_H == (Data_G + 12'd1))
    );

// Data_A wraps to zero when the prior value is 511 or higher.
    check_data_a_wraps_at_511_or_more: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($past(reset_n) && ($past(Data_A) >= 12'd511)) |-> (Data_A == 12'd0)
    );

// abc 000 decodes to bit 0 set.
    check_decode_000: assert property (
        @(posedge clk) (abc == 3'b000) |-> (d == 8'b00000001)
    );

// abc 001 decodes to bit 1 set.
    check_decode_001: assert property (
        @(posedge clk) (abc == 3'b001) |-> (d == 8'b00000010)
    );

// abc 010 decodes to bit 2 set.
    check_decode_010: assert property (
        @(posedge clk) (abc == 3'b010) |-> (d == 8'b00000100)
    );

// abc 011 decodes to bit 3 set.
    check_decode_011: assert property (
        @(posedge clk) (abc == 3'b011) |-> (d == 8'b00001000)
    );

// abc 100 decodes to bit 4 set.
    check_decode_100: assert property (
        @(posedge clk) (abc == 3'b100) |-> (d == 8'b00010000)
    );

// abc 101 decodes to bit 5 set.
    check_decode_101: assert property (
        @(posedge clk) (abc == 3'b101) |-> (d == 8'b00100000)
    );

// abc 110 decodes to bit 6 set.
    check_decode_110: assert property (
        @(posedge clk) (abc == 3'b110) |-> (d == 8'b01000000)
    );

// abc 111 decodes to bit 7 set.
    check_decode_111: assert property (
        @(posedge clk) (abc == 3'b111) |-> (d == 8'b10000000)
    );

// Reset clears both visible storage outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> ((out_port == 1'b0) && (readdata == 32'h00000000))
    );

// A valid write to address 0 updates the memory LSB seen on out_port.
    check_write_to_addr0_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[0]))
    );

// Without a valid write, the memory LSB seen on out_port holds its value.
    check_no_valid_write_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

// A valid read from address 0 captures the current memory LSB into readdata bit 0.
    check_read_from_addr0_updates_readdata_lsb: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && write_n && (address == 2'b00)) |=> (readdata[0] == $past(out_port))
    );

// Without a valid read, readdata holds its previous value.
    check_no_valid_read_holds_readdata: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && write_n && (address == 2'b00)) |=> (readdata == $past(readdata))
    );

// A write followed by a read on the next cycle returns the written 32-bit data.
    check_write_then_next_read_returns_written_data: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00))
        ##1
        (chipselect && write_n && (address == 2'b00))
        |=> (readdata == $past(writedata, 2))
    );

// When sel is 2'b00, data_out matches data_in[0].
    check_sel_00_routes_data_in0: assert property (
        @(posedge clk) (sel === 2'b00) |-> (data_out === data_in[0])
    );

// When sel is 2'b01, data_out matches data_in[1].
    check_sel_01_routes_data_in1: assert property (
        @(posedge clk) (sel === 2'b01) |-> (data_out === data_in[1])
    );

// When sel is 2'b10, data_out matches data_in[2].
    check_sel_10_routes_data_in2: assert property (
        @(posedge clk) (sel === 2'b10) |-> (data_out === data_in[2])
    );

// When sel is 2'b11, data_out matches data_in[3].
    check_sel_11_routes_data_in3: assert property (
        @(posedge clk) (sel === 2'b11) |-> (data_out === data_in[3])
    );

// Purely combinational cell sampled on an external clock; no reset in RTL.

    // Y matches the NOR of A, B, C, and inverted D_N.
    check_nor4b_function: assert property (
        @(posedge clk) (Y == ~(A | B | C | (~D_N)))
    );

// A high forces the NOR output low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> (Y == 1'b0)
    );

// B high forces the NOR output low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> (Y == 1'b0)
    );

// C high forces the NOR output low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> (Y == 1'b0)
    );

// D_N low forces the inverted D input high, so Y must be low.
    check_dn_low_forces_y_low: assert property (
        @(posedge clk) (!D_N) |-> (Y == 1'b0)
    );

// Y is high for the unique input combination A=B=C=0 and D_N=1.
    check_all_low_and_dn_high_sets_y: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> (Y == 1'b1)
    );

// Y high implies the unique enabling input combination.
    check_y_high_requires_unique_input_state: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && D_N)
    );

// Active-low reset forces readdata low.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

// Upper 24 bits stay zero after each enabled clock.
    check_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:8] == 24'b0)
    );

// Nonzero addresses produce zero on the next sampled cycle.
    check_nonzero_address_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 32'b0)
    );

// Address 0 can only return zero or the prior input byte.
    check_addr0_returns_zero_or_input: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |=> ((readdata == 32'b0) || (readdata == {24'b0, $past(in_port)}))
    );

// After an enabled clock, readdata is zero or a zero-extended prior input.
    check_readdata_is_zero_or_prior_input: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> ((readdata == 32'b0) || (($past(address) == 2'b00) && (readdata == {24'b0, $past(in_port)})))
    );

// Zero input at address 0 yields zero on the next sampled cycle.
    check_zero_input_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((address == 2'b00) && (in_port == 8'h00)) |=> (readdata == 32'b0)
    );

// Disabled display outputs a blank pattern.
    check_blank_when_disabled: assert property (
        @(posedge clk) !enable |-> out == (INVERT ? ~7'b0000000 : 7'b0000000)
    );

// Enabled display outputs the selected hex digit pattern.
    check_enabled_hex_decode: assert property (
        @(posedge clk) enable |-> out == (INVERT ? ~hex_enc(in) : hex_enc(in))
    );

// Upper-byte output matches input[15:8].
    check_out_hi_matches_input_upper: assert property (
        @(posedge clk) out_hi == in[15:8]
    );

// Lower-byte output matches input[7:0].
    check_out_lo_matches_input_lower: assert property (
        @(posedge clk) out_lo == in[7:0]
    );

// Parity output data field matches input[7:0].
    check_out_parity_data_matches_input_lower: assert property (
        @(posedge clk) out_parity[7:0] == in[7:0]
    );

// Parity output data field matches the lower-byte output.
    check_out_parity_data_matches_out_lo: assert property (
        @(posedge clk) out_parity[7:0] == out_lo
    );

// Parity bit equals the reduction XOR of the parity data field.
    check_out_parity_bit_matches_data_xor: assert property (
        @(posedge clk) out_parity[8] == ^out_parity[7:0]
    );

// Full parity vector has zero overall reduction XOR.
    check_out_parity_vector_even_xor: assert property (
        @(posedge clk) (^out_parity) == 1'b0
    );

// out_or is the bitwise inverse of the lower-byte output.
    check_out_or_is_inverse_of_out_lo: assert property (
        @(posedge clk) out_or == ~out_lo
    );

// out_or matches the inverted lower byte of the input.
    check_out_or_matches_inverted_input_lower: assert property (
        @(posedge clk) out_or == ~in[7:0]
    );

// Clock: clk
    // Active-low reset: resetn
    // Sequential counter with wrap flag

    // If reset stays low across clocks, both outputs stay cleared.
    check_reset_holds_outputs_cleared: assert property (
        @(posedge clk)
        (!resetn ##1 !resetn) |-> ((count == 16'd0) && (flag == 1'b0))
    );

// Reaching max_count forces count back to zero on the next cycle.
    check_wrap_resets_count: assert property (
        @(posedge clk) disable iff (!resetn)
        (count == max_count) |=> (count == 16'd0)
    );

// Reaching max_count raises flag on the next cycle.
    check_wrap_sets_flag: assert property (
        @(posedge clk) disable iff (!resetn)
        (count == max_count) |=> (flag == 1'b1)
    );

// When not at max_count, count increments by one on the next cycle.
    check_non_wrap_increments_count: assert property (
        @(posedge clk) disable iff (!resetn)
        (count != max_count) |=> (count == ($past(count) + 16'd1))
    );

// When not at max_count, flag is cleared on the next cycle.
    check_non_wrap_clears_flag: assert property (
        @(posedge clk) disable iff (!resetn)
        (count != max_count) |=> (flag == 1'b0)
    );

// Reset drives the register to 0 on the next sampled cycle.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (reg_0x18 == 8'h00)
    );

// Reset takes priority over a simultaneous active-low write.
    check_reset_overrides_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |=> (reg_0x18 == 8'h00)
    );

// An active-low write captures in_data into the register.
    check_write_captures_in_data: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0) |=> (reg_0x18 == $past(in_data))
    );

// With write disabled, the register holds its previous value.
    check_hold_without_write: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1) |=> (reg_0x18 == $past(reg_0x18))
    );

// gray[0] is a direct copy of bin[0].
    check_gray_bit0_passthrough: assert property (
        @(posedge clk) gray[0] == bin[0]
    );

// gray[1] is the XOR of bin[0] and bin[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray[1] == (bin[0] ^ bin[1])
    );

// gray[2] matches the RTL XOR chain of w2 and w1.
    check_gray_bit2_xor_chain: assert property (
        @(posedge clk) gray[2] == ((bin[1] ^ bin[2]) ^ (bin[0] ^ bin[1]))
    );

// gray[3] matches the RTL XOR chain of w3, w2, and bin[3].
    check_gray_bit3_xor_chain: assert property (
        @(posedge clk) gray[3] == ((bin[2] ^ bin[3]) ^ (bin[1] ^ bin[2]) ^ bin[3])
    );

// The full gray bus matches the implemented bit equations.
    check_gray_vector_function: assert property (
        @(posedge clk) gray == {
            ((bin[2] ^ bin[3]) ^ (bin[1] ^ bin[2]) ^ bin[3]),
            ((bin[1] ^ bin[2]) ^ (bin[0] ^ bin[1])),
            (bin[0] ^ bin[1]),
            bin[0]
        }
    );

// clk_out must go high on the cycle after enable is high.
    check_clk_out_set_on_enable: assert property (
        @(posedge clk) enable |=> (clk_out == 1'b1)
    );

// clk_out must go low on the cycle after enable is low.
    check_clk_out_clear_on_disable: assert property (
        @(posedge clk) !enable |=> (clk_out == 1'b0)
    );

// clk_out must always match the previous cycle's enable value.
    check_clk_out_matches_prior_enable: assert property (
        @(posedge clk) 1'b1 |=> (clk_out == $past(enable))
    );

// Output equals the 4-bit two's complement of the input.
    check_output_twos_complement: assert property (
        @(posedge clk) b == ((~a) + 4'd1)
    );

// Input and output sum to zero modulo 16.
    check_additive_inverse_mod16: assert property (
        @(posedge clk) (a + b) == 4'd0
    );

// Zero remains unchanged by two's complement.
    check_zero_fixed_point: assert property (
        @(posedge clk) (a == 4'd0) |-> (b == 4'd0)
    );

// 4'b1000 remains unchanged in 4-bit two's complement.
    check_most_negative_fixed_point: assert property (
        @(posedge clk) (a == 4'b1000) |-> (b == 4'b1000)
    );

// No clock or reset exists in the RTL; sample the combinational logic on clk.

    // Shift 0 passes the input through unchanged.
    check_shift_0_passthrough: assert property (
        @(posedge clk) (shift == 4'd0) |-> (out == in)
    );

// Shift 1 replicates the sign bit once and shifts right by 1.
    check_shift_1_behavior: assert property (
        @(posedge clk) (shift == 4'd1) |-> (out == {in[15], in[15:1]})
    );

// Shift 2 replicates the sign bit twice and shifts right by 2.
    check_shift_2_behavior: assert property (
        @(posedge clk) (shift == 4'd2) |-> (out == {{2{in[15]}}, in[15:2]})
    );

// Shift 3 replicates the sign bit three times and shifts right by 3.
    check_shift_3_behavior: assert property (
        @(posedge clk) (shift == 4'd3) |-> (out == {{3{in[15]}}, in[15:3]})
    );

// Shift 4 replicates the sign bit four times and shifts right by 4.
    check_shift_4_behavior: assert property (
        @(posedge clk) (shift == 4'd4) |-> (out == {{4{in[15]}}, in[15:4]})
    );

// Shift 5 replicates the sign bit five times and shifts right by 5.
    check_shift_5_behavior: assert property (
        @(posedge clk) (shift == 4'd5) |-> (out == {{5{in[15]}}, in[15:5]})
    );

// Shift 6 replicates the sign bit six times and shifts right by 6.
    check_shift_6_behavior: assert property (
        @(posedge clk) (shift == 4'd6) |-> (out == {{6{in[15]}}, in[15:6]})
    );

// Shift 7 replicates the sign bit seven times and shifts right by 7.
    check_shift_7_behavior: assert property (
        @(posedge clk) (shift == 4'd7) |-> (out == {{7{in[15]}}, in[15:7]})
    );

// Shift 8 replicates the sign bit eight times and shifts right by 8.
    check_shift_8_behavior: assert property (
        @(posedge clk) (shift == 4'd8) |-> (out == {{8{in[15]}}, in[15:8]})
    );

// Shift 9 replicates the sign bit nine times and shifts right by 9.
    check_shift_9_behavior: assert property (
        @(posedge clk) (shift == 4'd9) |-> (out == {{9{in[15]}}, in[15:9]})
    );

// Shift 10 replicates the sign bit ten times and shifts right by 10.
    check_shift_10_behavior: assert property (
        @(posedge clk) (shift == 4'd10) |-> (out == {{10{in[15]}}, in[15:10]})
    );

// Shift 11 replicates the sign bit eleven times and shifts right by 11.
    check_shift_11_behavior: assert property (
        @(posedge clk) (shift == 4'd11) |-> (out == {{11{in[15]}}, in[15:11]})
    );

// Shift 12 replicates the sign bit twelve times and shifts right by 12.
    check_shift_12_behavior: assert property (
        @(posedge clk) (shift == 4'd12) |-> (out == {{12{in[15]}}, in[15:12]})
    );

// Shift 13 replicates the sign bit thirteen times and shifts right by 13.
    check_shift_13_behavior: assert property (
        @(posedge clk) (shift == 4'd13) |-> (out == {{13{in[15]}}, in[15:13]})
    );

// Shift 14 replicates the sign bit fourteen times and shifts right by 14.
    check_shift_14_behavior: assert property (
        @(posedge clk) (shift == 4'd14) |-> (out == {{14{in[15]}}, in[15:14]})
    );

// Shift 15 fills the entire output with the input sign bit.
    check_shift_15_behavior: assert property (
        @(posedge clk) (shift == 4'd15) |-> (out == {16{in[15]}})
    );

// Held reset keeps count at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (count == 3'd0)
    );

// Reset release leaves count at zero before counting resumes.
    check_reset_release_leaves_zero: assert property (
        @(posedge clk) (!rst && $past(rst)) |-> (count == 3'd0)
    );

// Count increments from 0 to 1.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd0) |=> (count == 3'd1)
    );

// Count increments from 1 to 2.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd1) |=> (count == 3'd2)
    );

// Count increments from 2 to 3.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd2) |=> (count == 3'd3)
    );

// Count increments from 3 to 4.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd3) |=> (count == 3'd4)
    );

// Count increments from 4 to 5.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd4) |=> (count == 3'd5)
    );

// Count increments from 5 to 6.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd5) |=> (count == 3'd6)
    );

// Count increments from 6 to 7.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd6) |=> (count == 3'd7)
    );

// Count wraps from 7 back to 0.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (rst) (count == 3'd7) |=> (count == 3'd0)
    );

// The output matches the sampled input rotated by the sampled shift amount after two clocks.
    check_two_cycle_pipeline_rotation: assert property (
        @(posedge clk)
        1'b1 |-> ##2 out == rotl16($past(in, 2), $past(shift_amount, 2))
    );

// A sampled zero shift returns the sampled input two clocks later.
    check_zero_shift_case: assert property (
        @(posedge clk)
        (shift_amount == 4'h0) |-> ##2 out == $past(in, 2)
    );

// A sampled shift of one rotates the sampled MSB into bit 0 two clocks later.
    check_shift_one_case: assert property (
        @(posedge clk)
        (shift_amount == 4'h1) |-> ##2 out == {$past(in[14:0], 2), $past(in[15], 2)}
    );

// A sampled shift of eight swaps the sampled upper and lower bytes two clocks later.
    check_shift_eight_case: assert property (
        @(posedge clk)
        (shift_amount == 4'h8) |-> ##2 out == {$past(in[7:0], 2), $past(in[15:8], 2)}
    );

// A sampled shift of fifteen rotates sampled bit 0 into bit 15 two clocks later.
    check_shift_fifteen_case: assert property (
        @(posedge clk)
        (shift_amount == 4'hF) |-> ##2 out == {$past(in[0], 2), $past(in[15:1], 2)}
    );

// A sampled zero input remains zero after the two-cycle pipeline delay.
    check_zero_input_preserved: assert property (
        @(posedge clk)
        (in == 16'h0000) |-> ##2 out == 16'h0000
    );

// A sampled all-ones input remains all ones after the two-cycle pipeline delay.
    check_all_ones_input_preserved: assert property (
        @(posedge clk)
        (in == 16'hFFFF) |-> ##2 out == 16'hFFFF
    );

// Select value 000 routes din1 to dout.
    check_sel_000_routes_din1: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b000) |-> (dout == din1)
    );

// Select value 001 routes din2 to dout.
    check_sel_001_routes_din2: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b001) |-> (dout == din2)
    );

// Select value 010 routes din3 to dout.
    check_sel_010_routes_din3: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b010) |-> (dout == din3)
    );

// Select value 011 routes din4 to dout.
    check_sel_011_routes_din4: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b011) |-> (dout == din4)
    );

// Select value 100 routes din5 to dout.
    check_sel_100_routes_din5: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b100) |-> (dout == din5)
    );

// Select value 101 routes din6 to dout.
    check_sel_101_routes_din6: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b101) |-> (dout == din6)
    );

// Select value 110 routes din7 to dout.
    check_sel_110_routes_din7: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b110) |-> (dout == din7)
    );

// Select value 111 routes din8 to dout.
    check_sel_111_routes_din8: assert property (
        @(posedge clk)
        (din9[2:0] == 3'b111) |-> (dout == din8)
    );

// out reflects the OR of a and b from two clocks earlier.
    check_out_two_cycle_latency: assert property (
        @(posedge clk) 1'b1 |=> ##1 (out == ($past(a, 2) | $past(b, 2)))
    );

// X must match the RTL's final structural expression.
    check_x_matches_structural_expression: assert property (
        @(posedge clk) X == (AB_CD & AC_BD & AD_BC)
    );

// X must be high iff at least one 3-input product term is high.
    check_x_matches_three_high_function: assert property (
        @(posedge clk) X == (ABC | ABD | ACD | BCD)
    );

// A, B, and C high must drive X high.
    check_abc_implies_x: assert property (
        @(posedge clk) ABC |-> X
    );

// A, B, and D high must drive X high.
    check_abd_implies_x: assert property (
        @(posedge clk) ABD |-> X
    );

// A, C, and D high must drive X high.
    check_acd_implies_x: assert property (
        @(posedge clk) ACD |-> X
    );

// B, C, and D high must drive X high.
    check_bcd_implies_x: assert property (
        @(posedge clk) BCD |-> X
    );

// Without any 3-input product term, X must be low.
    check_no_three_high_inputs_means_x_low: assert property (
        @(posedge clk) !(ABC | ABD | ACD | BCD) |-> !X
    );

// Output must equal the AND of the two inputs.
    check_y_matches_and: assert property (
        @(posedge clk) Y == (A & B)
    );

// Both inputs high must drive the output high.
    check_both_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A && B) |-> Y
    );

// A low must force the output low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) (!A) |-> (!Y)
    );

// B low must force the output low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (!B) |-> (!Y)
    );

// A high output requires both inputs high.
    check_y_high_requires_both_inputs_high: assert property (
        @(posedge clk) Y |-> (A && B)
    );

// abusWire2 captures abusWire1 from the prior clock.
    check_abus_transfer: assert property (
        @(posedge clk) 1'b1 |=> (abusWire2 == $past(abusWire1))
    );

// bbusWire2 captures bbusWire1 from the prior clock.
    check_bbus_transfer: assert property (
        @(posedge clk) 1'b1 |=> (bbusWire2 == $past(bbusWire1))
    );

// DselectWire2 captures DselectWire1 from the prior clock.
    check_dselect_transfer: assert property (
        @(posedge clk) 1'b1 |=> (DselectWire2 == $past(DselectWire1))
    );

// immWire2 captures immWire1 from the prior clock.
    check_imm_transfer: assert property (
        @(posedge clk) 1'b1 |=> (immWire2 == $past(immWire1))
    );

// SWire2 captures SWire1 from the prior clock.
    check_s_transfer: assert property (
        @(posedge clk) 1'b1 |=> (SWire2 == $past(SWire1))
    );

// CinWire2 captures CinWire1 from the prior clock.
    check_cin_transfer: assert property (
        @(posedge clk) 1'b1 |=> (CinWire2 == $past(CinWire1))
    );

// immBit2 captures immBit1 from the prior clock.
    check_immbit_transfer: assert property (
        @(posedge clk) 1'b1 |=> (immBit2 == $past(immBit1))
    );

// out_inv matches its combinational equation.
    check_out_inv_equation: assert property (
        @(posedge clk) out_inv == ((~A & invert) | (A & ~invert))
    );

// out_inv passes A through when invert is low.
    check_out_inv_passthrough: assert property (
        @(posedge clk) !invert |-> (out_inv == A)
    );

// out_inv inverts A when invert is high.
    check_out_inv_inverted: assert property (
        @(posedge clk) invert |-> (out_inv == ~A)
    );

// Y matches the NAND of ~A, B, and C.
    check_y_equation: assert property (
        @(posedge clk) Y == ~(~A & B & C)
    );

// Y is high whenever A is high.
    check_y_high_when_a_high: assert property (
        @(posedge clk) A |-> Y
    );

// Y is high whenever B is low.
    check_y_high_when_b_low: assert property (
        @(posedge clk) !B |-> Y
    );

// Y is high whenever C is low.
    check_y_high_when_c_low: assert property (
        @(posedge clk) !C |-> Y
    );

// Y goes low when ~A, B, and C are all high.
    check_y_low_when_nand_inputs_high: assert property (
        @(posedge clk) (!A && B && C) |-> !Y
    );

// Y low implies the NAND input term is true.
    check_y_low_only_when_nand_inputs_high: assert property (
        @(posedge clk) !Y |-> (!A && B && C)
    );

// Reset clears state and DATA_OUT on the next clock.
    check_reset_clears_registers: assert property (
        @(posedge CLK) !RST_N |=> (state == 16'h0000) && (DATA_OUT == 16'h0000)
    );

// In add mode, Z is the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) (ctrl == 1'b0) |-> (Z == (A + B))
    );

// In subtract mode, Z is the 4-bit difference of A and B.
    check_subtract_mode_result: assert property (
        @(posedge clk) (ctrl == 1'b1) |-> (Z == (A - B))
    );

// Subtracting equal operands produces zero.
    check_equal_operands_subtract_to_zero: assert property (
        @(posedge clk) (ctrl == 1'b1 && A == B) |-> (Z == 4'b0000)
    );

// Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk)
        rst |=> (cnt == 4'd0)
    );

// A single increment advances the count by one below 15.
    check_increment_advances_count: assert property (
        @(posedge clk) disable iff (rst)
        (inc && !dec && (cnt != 4'd15)) |=> (cnt == ($past(cnt) + 4'd1))
    );

// Increment wraps from 15 back to 0.
    check_increment_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (inc && !dec && (cnt == 4'd15)) |=> (cnt == 4'd0)
    );

// A single decrement reduces the count by one above 0.
    check_decrement_reduces_count: assert property (
        @(posedge clk) disable iff (rst)
        (dec && !inc && (cnt != 4'd0)) |=> (cnt == ($past(cnt) - 4'd1))
    );

// Decrement wraps from 0 back to 15.
    check_decrement_wraps_to_max: assert property (
        @(posedge clk) disable iff (rst)
        (dec && !inc && (cnt == 4'd0)) |=> (cnt == 4'd15)
    );

// With no increment or decrement, the count holds.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (rst)
        (!inc && !dec) |=> (cnt == $past(cnt))
    );

// With increment and decrement both high, the count holds.
    check_hold_when_both_asserted: assert property (
        @(posedge clk) disable iff (rst)
        (inc && dec) |=> (cnt == $past(cnt))
    );

// Reset forces the output to zero.
    check_reset_zero: assert property (
        @(posedge clk) rst |-> (out == 4'b0000)
    );

// Outside reset, output is the upper two input bits followed by zeros.
    check_shift_mapping: assert property (
        @(posedge clk) disable iff (rst)
            (out == {in[3:2], 2'b00})
    );

// The low two output bits are always zero.
    check_low_bits_zero: assert property (
        @(posedge clk) (out[1:0] == 2'b00)
    );

// Outside reset, the high two output bits mirror the high input bits.
    check_upper_bits_match: assert property (
        @(posedge clk) disable iff (rst)
            (out[3:2] == in[3:2])
    );

// SUM matches A xor B xor inverted CIN.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// COUT matches the majority of A, B, and inverted CIN.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// If both A and B are high, COUT must be high.
    check_cout_when_ab_high: assert property (
        @(posedge clk) (A && B) |-> COUT
    );

// If both A and B are low, COUT must be low.
    check_cout_when_ab_low: assert property (
        @(posedge clk) (!A && !B) |-> !COUT
    );

// With exactly one of A or B high, COUT follows inverted CIN.
    check_cout_single_high_input: assert property (
        @(posedge clk) (A ^ B) |-> (COUT == ~CIN)
    );

// With equal A and B, SUM follows inverted CIN.
    check_sum_equal_inputs: assert property (
        @(posedge clk) !(A ^ B) |-> (SUM == ~CIN)
    );

// With different A and B, SUM follows CIN.
    check_sum_different_inputs: assert property (
        @(posedge clk) (A ^ B) |-> (SUM == CIN)
    );

// When CIN is high, SUM is XOR and COUT is AND of A and B.
    check_cin_high_behavior: assert property (
        @(posedge clk) CIN |-> ((SUM == (A ^ B)) && (COUT == (A & B)))
    );

// When CIN is low, SUM is XNOR and COUT is OR of A and B.
    check_cin_low_behavior: assert property (
        @(posedge clk) !CIN |-> ((SUM == ~(A ^ B)) && (COUT == (A | B)))
    );

// The least-significant sum bit matches the first full-adder stage.
    check_lsb_sum_equation: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Zero plus zero with no carry-in produces zero and no carry-out.
    check_zero_addition: assert property (
        @(posedge clk)
        (a == 4'b0000 && b == 4'b0000 && cin == 1'b0)
        |-> (sum == 4'b0000 && cout == 1'b0)
    );

// Adding zero with no carry-in passes a through unchanged.
    check_a_passthrough_when_b_zero: assert property (
        @(posedge clk)
        (b == 4'b0000 && cin == 1'b0)
        |-> (sum == a && cout == 1'b0)
    );

// Adding zero with no carry-in passes b through unchanged.
    check_b_passthrough_when_a_zero: assert property (
        @(posedge clk)
        (a == 4'b0000 && cin == 1'b0)
        |-> (sum == b && cout == 1'b0)
    );

// A carry-in propagates through all four bits when a is all ones and b is zero.
    check_full_carry_propagation_from_cin: assert property (
        @(posedge clk)
        (a == 4'b1111 && b == 4'b0000 && cin == 1'b1)
        |-> (sum == 4'b0000 && cout == 1'b1)
    );

// The maximum input case produces all ones with carry-out asserted.
    check_maximum_addition_case: assert property (
        @(posedge clk)
        (a == 4'b1111 && b == 4'b1111 && cin == 1'b1)
        |-> (sum == 4'b1111 && cout == 1'b1)
    );

// LOAD overrides the case update and clears Q.
    check_load_clears_q: assert property (
        @(posedge CLK) LOAD |=> (Q == 4'b0000)
    );

// With LOAD low and UP/DOWN=00, Q decrements.
    check_decrement_on_00: assert property (
        @(posedge CLK) (!LOAD && !UP && !DOWN) |=> (Q == ($past(Q) - 4'd1))
    );

// With LOAD low and UP/DOWN=01, Q increments.
    check_increment_on_01: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN) |=> (Q == ($past(Q) + 4'd1))
    );

// With LOAD low and UP/DOWN=10, Q holds.
    check_hold_on_10: assert property (
        @(posedge CLK) (!LOAD && UP && !DOWN) |=> (Q == $past(Q))
    );

// With LOAD low and UP/DOWN=11, Q holds.
    check_hold_on_11: assert property (
        @(posedge CLK) (!LOAD && UP && DOWN) |=> (Q == $past(Q))
    );

// Output always matches the selected case expression.
    check_output_function: assert property (
        @(posedge clk)
        out === ((ctrl === 3'b000) ? (A & B) :
                 (ctrl === 3'b001) ? (A | B) :
                 (ctrl === 3'b010) ? (A ^ B) :
                                     8'h00)
    );

// ctrl 000 selects the bitwise AND result.
    check_and_operation: assert property (
        @(posedge clk)
        (ctrl === 3'b000) |-> (out === (A & B))
    );

// ctrl 001 selects the bitwise OR result.
    check_or_operation: assert property (
        @(posedge clk)
        (ctrl === 3'b001) |-> (out === (A | B))
    );

// ctrl 010 selects the bitwise XOR result.
    check_xor_operation: assert property (
        @(posedge clk)
        (ctrl === 3'b010) |-> (out === (A ^ B))
    );

// All other ctrl values drive the default zero output.
    check_default_zero: assert property (
        @(posedge clk)
        (ctrl !== 3'b000 && ctrl !== 3'b001 && ctrl !== 3'b010) |-> (out === 8'h00)
    );

// X must match the implemented OR-of-A and inverted SLEEP_B.
    check_function_equation: assert property (
        @(posedge clk) X == (A | ~SLEEP_B)
    );

// When not sleeping, X must pass A through.
    check_pass_through_when_awake: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// When sleeping, X must be clamped high.
    check_clamp_high_when_sleep: assert property (
        @(posedge clk) !SLEEP_B |-> (X == 1'b1)
    );

// A max input wraps the registered output to zero on the next cycle.
    check_wrap_from_max: assert property (
        @(posedge clk) (data_in == 4'b1111) |=> (data_out == 4'b0000)
    );

// A non-max input increments by one on the next cycle.
    check_increment_from_nonmax: assert property (
        @(posedge clk) (data_in != 4'b1111) |=> (data_out == ($past(data_in) + 4'b0001))
    );

// The output always matches the previous cycle's input transform.
    check_output_matches_previous_input: assert property (
        @(posedge clk) 1'b1 |=> (data_out == (($past(data_in) == 4'b1111) ? 4'b0000 : ($past(data_in) + 4'b0001)))
    );

// The output is zero exactly when the previous input was 4'hf.
    check_zero_output_only_after_max: assert property (
        @(posedge clk) 1'b1 |=> ((data_out == 4'b0000) == ($past(data_in) == 4'b1111))
    );

// Active-low reset forces out_port to all ones.
    reset_sets_out_port_all_ones: assert property (
        @(posedge clk) !reset_n |-> (out_port == 10'b1111111111)
    );

// A selected write to address 0 updates out_port with writedata[9:0].
    write_to_data_register_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[9:0]))
    );

// Without a selected write to address 0, out_port holds its value.
    no_data_register_write_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

// Reads from address 0 return out_port in the low 10 bits.
    read_addr0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {22'b0, out_port})
    );

// Reads from nonzero addresses return zero.
    read_other_addresses_return_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

// Readdata upper bits are always zero.
    read_upper_bits_are_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:10] == 22'b0)
    );

// Y must equal the XNOR of A and B.
    check_xnor_equivalence: assert property (
        @(posedge clk) Y === (A ~^ B)
    );

// A=0 and B=0 must drive Y high.
    check_both_low_drive_high: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (Y === 1'b1)
    );

// A=0 and B=1 must drive Y low.
    check_a_low_b_high_drive_low: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b1)) |-> (Y === 1'b0)
    );

// A=1 and B=0 must drive Y low.
    check_a_high_b_low_drive_low: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b0)) |-> (Y === 1'b0)
    );

// A=1 and B=1 must drive Y high.
    check_both_high_drive_high: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (Y === 1'b1)
    );

// Load copies the input when shift is low.
    check_load_only_captures_input: assert property (
        @(posedge clk) (load && !shift) |=> out == $past(in)
    );

// Load has priority over shift when both controls are high.
    check_load_priority_over_shift: assert property (
        @(posedge clk) (load && shift) |=> out == $past(in)
    );

// Shift inserts a zero into bit 0.
    check_shift_clears_lsb: assert property (
        @(posedge clk) (!load && shift) |=> out[0] == 1'b0
    );

// Shift moves the previous bit 0 into bit 1.
    check_shift_moves_bit1: assert property (
        @(posedge clk) (!load && shift) |=> out[1] == $past(out[0])
    );

// Shift moves the previous bit 1 into bit 2.
    check_shift_moves_bit2: assert property (
        @(posedge clk) (!load && shift) |=> out[2] == $past(out[1])
    );

// Shift moves the previous bit 2 into bit 3.
    check_shift_moves_bit3: assert property (
        @(posedge clk) (!load && shift) |=> out[3] == $past(out[2])
    );

// Without load or shift, the register holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!load && !shift) |=> out == $past(out)
    );

// out_mux selects data0 when sel is 0.
    check_out_mux_sel0: assert property (
        @(posedge clk) (sel == 3'd0) |-> (out_mux == data0)
    );

// out_mux selects data1 when sel is 1.
    check_out_mux_sel1: assert property (
        @(posedge clk) (sel == 3'd1) |-> (out_mux == data1)
    );

// out_mux selects data2 when sel is 2.
    check_out_mux_sel2: assert property (
        @(posedge clk) (sel == 3'd2) |-> (out_mux == data2)
    );

// out_mux selects data3 when sel is 3.
    check_out_mux_sel3: assert property (
        @(posedge clk) (sel == 3'd3) |-> (out_mux == data3)
    );

// out_mux selects data4 when sel is 4.
    check_out_mux_sel4: assert property (
        @(posedge clk) (sel == 3'd4) |-> (out_mux == data4)
    );

// out_mux selects data5 when sel is 5.
    check_out_mux_sel5: assert property (
        @(posedge clk) (sel == 3'd5) |-> (out_mux == data5)
    );

// out_mux is zero when sel is outside 0 through 5.
    check_out_mux_default_zero: assert property (
        @(posedge clk) ((sel == 3'd6) || (sel == 3'd7)) |-> (out_mux == 4'b0000)
    );

// out_3bit mirrors sel.
    check_out_3bit_matches_sel: assert property (
        @(posedge clk) out_3bit == sel
    );

// o2 mirrors sel[2].
    check_o2_matches_sel_bit2: assert property (
        @(posedge clk) o2 == sel[2]
    );

// o1 mirrors sel[1].
    check_o1_matches_sel_bit1: assert property (
        @(posedge clk) o1 == sel[1]
    );

// o0 mirrors sel[0].
    check_o0_matches_sel_bit0: assert property (
        @(posedge clk) o0 == sel[0]
    );

// Reset has priority over set and data on the next gated clock.
    check_reset_priority: assert property (
        @(posedge G) disable iff (1'b0)
        (R == 1'b1) |=> ((Q === 1'b0) && (QN === 1'b1))
    );

// Set drives Q high when reset is not asserted.
    check_set_action: assert property (
        @(posedge G) disable iff (1'b0)
        ((R == 1'b0) && (S == 1'b1)) |=> ((Q === 1'b1) && (QN === 1'b0))
    );

// With set and reset low, Q loads D on the next gated clock.
    check_data_load: assert property (
        @(posedge G) disable iff (1'b0)
        ((R == 1'b0) && (S == 1'b0)) |=> ((Q === $past(D)) && (QN === ~$past(D)))
    );

// QN is always the complement of Q.
    check_qn_complement: assert property (
        @(posedge G) disable iff (1'b0)
        (QN === ~Q)
    );

// Y follows the implemented combinational equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == (A1 || (A2 && !A1) || (A3 && !A2 && !A1))
    );

// A1 asserted drives Y high.
    check_a1_drives_y_high: assert property (
        @(posedge clk)
        A1 |-> Y
    );

// With A1 low, A2 asserted drives Y high.
    check_a2_drives_y_high_when_a1_low: assert property (
        @(posedge clk)
        (!A1 && A2) |-> Y
    );

// With A1 and A2 low, A3 asserted drives Y high.
    check_a3_drives_y_high_when_a1_a2_low: assert property (
        @(posedge clk)
        (!A1 && !A2 && A3) |-> Y
    );

// When all contributing inputs are low, Y is low.
    check_all_inputs_low_drives_y_low: assert property (
        @(posedge clk)
        (!A1 && !A2 && !A3) |-> !Y
    );

// A high Y requires at least one of A1, A2, or A3 high.
    check_y_high_requires_active_input: assert property (
        @(posedge clk)
        Y |-> (A1 || A2 || A3)
    );

// A low Y requires all of A1, A2, and A3 low.
    check_y_low_requires_all_inputs_low: assert property (
        @(posedge clk)
        !Y |-> (!A1 && !A2 && !A3)
    );

// Combinational DUT sampled on an external clock.
    // No reset is present in the RTL.

    // ctrl=00 selects D0 onto S.
    check_select_d0: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (S == D0)
    );

// ctrl=01 selects D1 onto S.
    check_select_d1: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (S == D1)
    );

// ctrl=10 selects D2 onto S.
    check_select_d2: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (S == D2)
    );

// ctrl=11 selects D3 onto S.
    check_select_d3: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (S == D3)
    );

// q must match the previous cycle's address mapping.
    check_q_matches_previous_address: assert property (
        @(posedge clock)
        1'b1 |=> (q == (($past(address) >= 15'd4096) ? 12'b0 : $past(address[11:0])))
    );

// Out-of-range addresses must drive q to zero on the next clock.
    check_zero_for_out_of_range_address: assert property (
        @(posedge clock)
        (address >= 15'd4096) |=> (q == 12'b0)
    );

// In-range addresses must pass their low 12 bits to q on the next clock.
    check_passthrough_for_in_range_address: assert property (
        @(posedge clock)
        (address < 15'd4096) |=> (q == $past(address[11:0]))
    );

// The highest in-range address must pass through unchanged.
    check_boundary_4095_passthrough: assert property (
        @(posedge clock)
        (address == 15'd4095) |=> (q == 12'hFFF)
    );

// The first out-of-range address must map to zero.
    check_boundary_4096_zeroed: assert property (
        @(posedge clock)
        (address == 15'd4096) |=> (q == 12'b0)
    );

// SO always reflects the LSB of Q.
    check_so_matches_q_lsb: assert property (
        @(posedge CLK) SO == Q[0]
    );

// SI high loads 4'b0001 into Q on the next clock.
    check_si_high_loads_one: assert property (
        @(posedge CLK) SI |=> Q == 4'b0001
    );

// SI high makes SO high on the next clock.
    check_si_high_sets_so: assert property (
        @(posedge CLK) SI |=> SO == 1'b1
    );

// SI high clears the upper three bits on the next clock.
    check_si_high_clears_upper_bits: assert property (
        @(posedge CLK) SI |=> Q[3:1] == 3'b000
    );

// SI low updates Q from the previous Q[2:0] and SO.
    check_si_low_updates_q: assert property (
        @(posedge CLK) !SI |=> Q == {$past(Q[2:0]), $past(SO)}
    );

// SI low shifts the previous Q[2:0] into Q[3:1].
    check_si_low_updates_upper_bits: assert property (
        @(posedge CLK) !SI |=> Q[3:1] == $past(Q[2:0])
    );

// SI low keeps SO equal to its previous value.
    check_si_low_holds_so: assert property (
        @(posedge CLK) !SI |=> SO == $past(SO)
    );

// SI low duplicates the previous SO into Q[1:0].
    check_si_low_duplicates_so_into_low_bits: assert property (
        @(posedge CLK) !SI |=> Q[1:0] == {$past(SO), $past(SO)}
    );

// Result matches the implemented comparator function.
    check_function_map: assert property (
        @(posedge clk) result == ((A == B) ? 2'b00 : ((A > B) ? 2'b01 : 2'b10))
    );

// Equal inputs produce 00.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

// A greater than B produces 01.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

// A less than B produces 10.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b10)
    );

// 00 indicates equal inputs.
    check_result_equal_encoding: assert property (
        @(posedge clk) (result == 2'b00) |-> (A == B)
    );

// 01 indicates A is greater than B.
    check_result_greater_encoding: assert property (
        @(posedge clk) (result == 2'b01) |-> (A > B)
    );

// 10 indicates A is less than B.
    check_result_less_encoding: assert property (
        @(posedge clk) (result == 2'b10) |-> (A < B)
    );

// 11 is never a valid output encoding.
    check_no_invalid_encoding: assert property (
        @(posedge clk) (result != 2'b11)
    );

// Load copies the input into the register.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> out == $past(in)
    );

// Without load, the register rotates left with wraparound.
    check_shift_rotates_register: assert property (
        @(posedge clk) !load |=> out == {$past(out[2:0]), $past(out[3])}
    );

// On a shift cycle, the previous MSB wraps into bit 0.
    check_shift_wraps_msb_to_lsb: assert property (
        @(posedge clk) !load |=> out[0] == $past(out[3])
    );

// On a shift cycle, bits [3:1] come from the previous [2:0].
    check_shift_moves_lower_bits_up: assert property (
        @(posedge clk) !load |=> out[3:1] == $past(out[2:0])
    );

// The serial output is always the previous cycle's MSB.
    check_ser_out_tracks_previous_msb: assert property (
        @(posedge clk) 1'b1 |=> ser_out == $past(out[3])
    );

// On a shift cycle, serial output matches the wrapped bit on out[0].
    check_shift_ser_out_matches_lsb: assert property (
        @(posedge clk) !load |=> ser_out == out[0]
    );

// Reset forces count to zero by the next clock sample.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// Without reset, count increments by one on each clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (count == ($past(count) + 4'd1))
    );

// A maximum count value wraps back to zero on the next clock.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'hf) |=> (count == 4'h0)
    );

// SEL=00 routes A to Y.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (SEL == 2'b00) |-> (Y == A)
    );

// SEL=01 routes B to Y.
    check_sel_01_routes_b: assert property (
        @(posedge clk) (SEL == 2'b01) |-> (Y == B)
    );

// SEL=10 routes C to Y.
    check_sel_10_routes_c: assert property (
        @(posedge clk) (SEL == 2'b10) |-> (Y == C)
    );

// SEL=11 routes D to Y.
    check_sel_11_routes_d: assert property (
        @(posedge clk) (SEL == 2'b11) |-> (Y == D)
    );

// Result goes high when A is less than or equal to B.
    check_result_when_le: assert property (
        @(posedge clk) ((A <= B) === 1'b1) |-> (result === 1'b1)
    );

// Result goes low when the comparison is not true.
    check_result_when_not_le: assert property (
        @(posedge clk) ((A <= B) !== 1'b1) |-> (result === 1'b0)
    );

// Reset holds both registers low.
    check_reset_clears_state: assert property (
        @(posedge clk)
        rst |-> ((s == 1'b0) && (z == 1'b0))
    );

// x must equal the AND of all seven inputs.
    check_x_matches_all_inputs_and: assert property (
        @(posedge clk) x == (a & b & c & d & e & f & g)
    );

// All seven high must drive x high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (a & b & c & d & e & f & g) |-> x
    );

// Any low input must drive x low.
    check_any_low_input_drives_x_low: assert property (
        @(posedge clk) !(a & b & c & d & e & f & g) |-> !x
    );

// Output must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) y === ((sel == 1'b0) ? a : b)
    );

// When select is 0, output must equal input a.
    check_select_a_path: assert property (
        @(posedge clk) (sel === 1'b0) |-> (y === a)
    );

// When select is 1, output must equal input b.
    check_select_b_path: assert property (
        @(posedge clk) (sel === 1'b1) |-> (y === b)
    );

// If both data inputs are 0, output must be 0.
    check_both_inputs_zero: assert property (
        @(posedge clk) ((a === 1'b0) && (b === 1'b0)) |-> (y === 1'b0)
    );

// If both data inputs are 1, output must be 1.
    check_both_inputs_one: assert property (
        @(posedge clk) ((a === 1'b1) && (b === 1'b1)) |-> (y === 1'b1)
    );

// Q captures SE on an enabled clock edge.
    check_capture_when_enabled: assert property (
        @(posedge CK) EN |=> (Q == $past(SE))
    );

// Q holds its previous value when EN is low.
    check_hold_when_disabled: assert property (
        @(posedge CK) !EN |=> (Q == $past(Q))
    );

// Enabling with different data causes Q to change.
    check_enabled_new_data_updates_q: assert property (
        @(posedge CK) EN && (SE != Q) |=> $changed(Q)
    );

// Enabling with the same data leaves Q unchanged.
    check_enabled_same_data_keeps_q: assert property (
        @(posedge CK) EN && (SE == Q) |=> !$changed(Q)
    );

// The output vector always equals the bitwise complement of the input vector.
    check_vector_complement: assert property (
        @(posedge clk) out == ~a
    );

// Output bit 0 always matches the complement of input bit 0.
    check_bit0_complement: assert property (
        @(posedge clk) out[0] == ~a[0]
    );

// Output bit 1 always matches the complement of input bit 1.
    check_bit1_complement: assert property (
        @(posedge clk) out[1] == ~a[1]
    );

// Output bit 2 always matches the complement of input bit 2.
    check_bit2_complement: assert property (
        @(posedge clk) out[2] == ~a[2]
    );

// Output bit 3 always matches the complement of input bit 3.
    check_bit3_complement: assert property (
        @(posedge clk) out[3] == ~a[3]
    );

// Bits [9:8] are always zero in the formatted ROM word.
    check_rom_data_middle_bits_zero: assert property (
        @(posedge clk) rom_data[9:8] == 2'b00
    );

// Address 0 returns the input format upper byte entry.
    check_rom_addr_0_entry: assert property (
        @(posedge clk) (rom_address == 5'd0) |-> (rom_data == {6'h02, 2'b00, LCM_INPUT_FORMAT_UB})
    );

// Address 1 returns the input format lower byte entry.
    check_rom_addr_1_entry: assert property (
        @(posedge clk) (rom_address == 5'd1) |-> (rom_data == {6'h03, 2'b00, LCM_INPUT_FORMAT_LB})
    );

// Address 2 returns the power entry.
    check_rom_addr_2_entry: assert property (
        @(posedge clk) (rom_address == 5'd2) |-> (rom_data == {6'h04, 2'b00, LCM_POWER})
    );

// Address 3 returns the direction and phase entry.
    check_rom_addr_3_entry: assert property (
        @(posedge clk) (rom_address == 5'd3) |-> (rom_data == {6'h05, 2'b00, LCM_DIRECTION_AND_PHASE})
    );

// Address 4 returns the horizontal start position entry.
    check_rom_addr_4_entry: assert property (
        @(posedge clk) (rom_address == 5'd4) |-> (rom_data == {6'h06, 2'b00, LCM_HORIZONTAL_START_POSITION})
    );

// Address 5 returns the vertical start position entry.
    check_rom_addr_5_entry: assert property (
        @(posedge clk) (rom_address == 5'd5) |-> (rom_data == {6'h07, 2'b00, LCM_VERTICAL_START_POSITION})
    );

// Address 6 returns the ENB negative position entry.
    check_rom_addr_6_entry: assert property (
        @(posedge clk) (rom_address == 5'd6) |-> (rom_data == {6'h08, 2'b00, LCM_ENB_NEGATIVE_POSITION})
    );

// Address 7 returns the contrast gain entry.
    check_rom_addr_7_entry: assert property (
        @(posedge clk) (rom_address == 5'd7) |-> (rom_data == {6'h09, 2'b00, LCM_GAIN_OF_CONTRAST})
    );

// Address 8 returns the red sub-contrast gain entry.
    check_rom_addr_8_entry: assert property (
        @(posedge clk) (rom_address == 5'd8) |-> (rom_data == {6'h0A, 2'b00, LCM_R_GAIN_OF_SUB_CONTRAST})
    );

// Address 9 returns the blue sub-contrast gain entry.
    check_rom_addr_9_entry: assert property (
        @(posedge clk) (rom_address == 5'd9) |-> (rom_data == {6'h0B, 2'b00, LCM_B_GAIN_OF_SUB_CONTRAST})
    );

// Address 10 returns the brightness offset entry.
    check_rom_addr_10_entry: assert property (
        @(posedge clk) (rom_address == 5'd10) |-> (rom_data == {6'h0C, 2'b00, LCM_OFFSET_OF_BRIGHTNESS})
    );

// Address 11 returns the VCOM high level entry.
    check_rom_addr_11_entry: assert property (
        @(posedge clk) (rom_address == 5'd11) |-> (rom_data == {6'h10, 2'b00, LCM_VCOM_HIGH_LEVEL})
    );

// Address 12 returns the VCOM low level entry.
    check_rom_addr_12_entry: assert property (
        @(posedge clk) (rom_address == 5'd12) |-> (rom_data == {6'h11, 2'b00, LCM_VCOM_LOW_LEVEL})
    );

// Address 13 returns the PCD high level entry.
    check_rom_addr_13_entry: assert property (
        @(posedge clk) (rom_address == 5'd13) |-> (rom_data == {6'h12, 2'b00, LCM_PCD_HIGH_LEVEL})
    );

// Address 14 returns the PCD low level entry.
    check_rom_addr_14_entry: assert property (
        @(posedge clk) (rom_address == 5'd14) |-> (rom_data == {6'h13, 2'b00, LCM_PCD_LOW_LEVEL})
    );

// Address 15 returns the first gamma correction entry.
    check_rom_addr_15_entry: assert property (
        @(posedge clk) (rom_address == 5'd15) |-> (rom_data == {6'h14, 2'b00, LCM_GAMMA_CORRECTION_0})
    );

// Address 16 returns the second gamma correction entry.
    check_rom_addr_16_entry: assert property (
        @(posedge clk) (rom_address == 5'd16) |-> (rom_data == {6'h15, 2'b00, LCM_GAMMA_CORRECTION_1})
    );

// Address 17 returns the third gamma correction entry.
    check_rom_addr_17_entry: assert property (
        @(posedge clk) (rom_address == 5'd17) |-> (rom_data == {6'h16, 2'b00, LCM_GAMMA_CORRECTION_2})
    );

// Address 18 returns the fourth gamma correction entry.
    check_rom_addr_18_entry: assert property (
        @(posedge clk) (rom_address == 5'd18) |-> (rom_data == {6'h17, 2'b00, LCM_GAMMA_CORRECTION_3})
    );

// Address 19 returns the fifth gamma correction entry.
    check_rom_addr_19_entry: assert property (
        @(posedge clk) (rom_address == 5'd19) |-> (rom_data == {6'h18, 2'b00, LCM_GAMMA_CORRECTION_4})
    );

// Addresses outside 0 to 19 return zero.
    check_rom_default_entry: assert property (
        @(posedge clk) (rom_address > 5'd19) |-> (rom_data == 16'h0000)
    );

// Y must equal the AND of all four inputs.
    check_y_matches_and4: assert property (
        @(posedge clk) Y == (A & B & C & D)
    );

// If all inputs are high, Y must be high.
    check_all_high_implies_y_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Y
    );

// If any input is low, Y must be low.
    check_any_low_implies_y_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C) || (!D)) |-> !Y
    );

// Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled below 15, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'b1111)) |=> (count == ($past(count) + 4'b0001))
    );

// When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// At 15, the counter holds even if enable is asserted.
    check_hold_at_terminal_count: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'b1111)) |=> (count == $past(count))
    );

// Outside reset, the counter never decreases.
    check_count_monotonic_without_reset: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count >= $past(count))
    );

// out_xor must be the zero-extended XOR of the two 16-bit input halves.
    check_out_xor_value: assert property (
        @(posedge clk) out_xor == {16'h0000, (in[31:16] ^ in[15:0])}
    );

// out_and must be the zero-extended AND of the two 16-bit input halves.
    check_out_and_value: assert property (
        @(posedge clk) out_and == {16'h0000, (in[31:16] & in[15:0])}
    );

// The upper 16 bits of out_xor must be zero.
    check_out_xor_upper_zero: assert property (
        @(posedge clk) out_xor[31:16] == 16'h0000
    );

// The upper 16 bits of out_and must be zero.
    check_out_and_upper_zero: assert property (
        @(posedge clk) out_and[31:16] == 16'h0000
    );

// The lower 16 bits of out_xor must match the XOR result.
    check_out_xor_lower_bits: assert property (
        @(posedge clk) out_xor[15:0] == (in[31:16] ^ in[15:0])
    );

// The lower 16 bits of out_and must match the AND result.
    check_out_and_lower_bits: assert property (
        @(posedge clk) out_and[15:0] == (in[31:16] & in[15:0])
    );

// Output is the 4-bit input incremented by one modulo 16.
    check_out_modulo_increment: assert property (
        @(posedge clk) out == (in + 4'b0001)
    );

// Overflow is asserted exactly when the input is 4'hF.
    check_overflow_matches_max_input: assert property (
        @(posedge clk) overflow == (in == 4'b1111)
    );

// Maximum input wraps the output to zero and raises overflow.
    check_max_input_wraps: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 4'b0000 && overflow == 1'b1)
    );

// Non-maximum input does not raise overflow.
    check_non_max_input_no_overflow: assert property (
        @(posedge clk) (in != 4'b1111) |-> (overflow == 1'b0)
    );

// Non-maximum input increments the output by one.
    check_non_max_input_increments: assert property (
        @(posedge clk) (in != 4'b1111) |-> (out == (in + 4'b0001))
    );

// Y matches the OR of the three reduction-AND terms.
    check_y_definition: assert property (
        @(posedge clk) Y == ((&A1) | (&A2) | (&A3))
    );

// A1 being all ones forces Y high.
    check_a1_all_ones_sets_y: assert property (
        @(posedge clk) (&A1) |-> Y
    );

// A2 being all ones forces Y high.
    check_a2_all_ones_sets_y: assert property (
        @(posedge clk) (&A2) |-> Y
    );

// A3 being all ones forces Y high.
    check_a3_all_ones_sets_y: assert property (
        @(posedge clk) (&A3) |-> Y
    );

// If no input bus is all ones, Y must be low.
    check_no_full_bus_means_y_low: assert property (
        @(posedge clk) (!(&A1) && !(&A2) && !(&A3)) |-> !Y
    );

// A high Y requires at least one bus to be all ones.
    check_y_high_requires_full_bus: assert property (
        @(posedge clk) Y |-> ((&A1) || (&A2) || (&A3))
    );

// A low Y means A1 is not all ones.
    check_y_low_excludes_a1_full: assert property (
        @(posedge clk) !Y |-> !(&A1)
    );

// A low Y means A2 is not all ones.
    check_y_low_excludes_a2_full: assert property (
        @(posedge clk) !Y |-> !(&A2)
    );

// A low Y means A3 is not all ones.
    check_y_low_excludes_a3_full: assert property (
        @(posedge clk) !Y |-> !(&A3)
    );

// byte_num 0 drives the fixed 0x01000000 padding value.
    check_byte0_constant: assert property (
        @(posedge clk) (byte_num == 2'd0) |-> (out == 32'h01000000)
    );

// byte_num 1 preserves the top byte and pads the lower 24 bits.
    check_byte1_mapping: assert property (
        @(posedge clk) (byte_num == 2'd1) |-> (out == {in[31:24], 24'h010000})
    );

// byte_num 2 preserves the top two bytes and pads the lower 16 bits.
    check_byte2_mapping: assert property (
        @(posedge clk) (byte_num == 2'd2) |-> (out == {in[31:16], 16'h0100})
    );

// byte_num 3 preserves the top three bytes and pads the low byte.
    check_byte3_mapping: assert property (
        @(posedge clk) (byte_num == 2'd3) |-> (out == {in[31:8], 8'h01})
    );

// sum is the XOR of a, b, and cin.
    check_sum_function: assert property (
        @(posedge clk) sum == (a ^ b ^ cin)
    );

// cout is high when at least two inputs are high.
    check_cout_function: assert property (
        @(posedge clk) cout == ((a & b) | (a & cin) | (b & cin))
    );

// All-zero inputs produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!a && !b && !cin) |-> (!sum && !cout)
    );

// Exactly one high input produces sum high and carry low.
    check_single_high_case: assert property (
        @(posedge clk)
        ((a && !b && !cin) || (!a && b && !cin) || (!a && !b && cin))
        |-> (sum && !cout)
    );

// Exactly two high inputs produce sum low and carry high.
    check_two_high_case: assert property (
        @(posedge clk)
        ((a && b && !cin) || (a && !b && cin) || (!a && b && cin))
        |-> (!sum && cout)
    );

// SCD clears the flop outputs on the next clock.
    check_scan_clear_outputs: assert property (
        @(posedge CLK) SCD |=> (Q == 1'b0) && (Q_N == 1'b1)
    );

// SCD has priority over SCE when both are high.
    check_scan_clear_priority: assert property (
        @(posedge CLK) (SCD && SCE) |=> (Q == 1'b0) && (Q_N == 1'b1)
    );

// With SCE high and SCD low, Q holds and Q_N follows the held Q complement.
    check_scan_enable_hold: assert property (
        @(posedge CLK) (!SCD && SCE) |=> (Q == $past(Q)) && (Q_N == ~($past(Q)))
    );

// With both controls low, the flop loads D and drives its complement on Q_N.
    check_data_load: assert property (
        @(posedge CLK) (!SCD && !SCE) |=> (Q == $past(D)) && (Q_N == ~($past(D)))
    );

// After each clocked update, Q_N is the complement of Q.
    check_outputs_complementary: assert property (
        @(posedge CLK) 1'b1 |=> (Q_N == ~Q)
    );

// Reset forces count to zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// out_and is the bitwise AND of all four inputs.
    check_out_and_function: assert property (
        @(posedge clk) (out_and === (in1 & in2 & in3 & in4))
    );

// out_or is the bitwise OR of all four inputs.
    check_out_or_function: assert property (
        @(posedge clk) (out_or === (in1 | in2 | in3 | in4))
    );

// out_xor is the bitwise XOR of all four inputs.
    check_out_xor_function: assert property (
        @(posedge clk) (out_xor === (in1 ^ in2 ^ in3 ^ in4))
    );

// final_output is data0 AND out_and when sel is 000.
    check_final_output_and_mode: assert property (
        @(posedge clk) (sel === 3'b000) |-> (final_output === (data0 & out_and))
    );

// final_output is data1 OR out_or when sel is 001.
    check_final_output_or_mode: assert property (
        @(posedge clk) (sel === 3'b001) |-> (final_output === (data1 | out_or))
    );

// final_output is data2 XOR out_xor when sel is 010.
    check_final_output_xor_mode: assert property (
        @(posedge clk) (sel === 3'b010) |-> (final_output === (data2 ^ out_xor))
    );

// final_output falls back to zero for all other sel values.
    check_final_output_default_zero: assert property (
        @(posedge clk)
        ((sel !== 3'b000) && (sel !== 3'b001) && (sel !== 3'b010))
        |-> (final_output === 4'b0000)
    );

// Outputs register the previous cycle's 5-bit addition result.
    check_registered_sum_and_carry: assert property (
        @(posedge clk) 1'b1 |=> ({C_out, S} == $past({1'b0, A} + {1'b0, B} + C_in))
    );

// Zero inputs produce a zero result on the next clock.
    check_zero_addition: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && C_in == 1'b0) |=> ({C_out, S} == 5'h00)
    );

// 15 + 0 + 1 produces a carry-out and zero sum on the next clock.
    check_single_carry_case: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h0 && C_in == 1'b1) |=> ({C_out, S} == 5'h10)
    );

// The maximum input combination produces 31 on the next clock.
    check_maximum_sum_case: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && C_in == 1'b1) |=> ({C_out, S} == 5'h1F)
    );

// Combinational DUT with no native reset; clk is the formal sampling clock.

    // Output vector matches the XOR of the two inputs.
    check_output_matches_xor: assert property (
        @(posedge clk) out_comb_logic == (a ^ b)
    );

// Bit 0 of the output is a[0] XOR b[0].
    check_bit0_matches_xor: assert property (
        @(posedge clk) out_comb_logic[0] == (a[0] ^ b[0])
    );

// Bit 1 of the output is a[1] XOR b[1].
    check_bit1_matches_xor: assert property (
        @(posedge clk) out_comb_logic[1] == (a[1] ^ b[1])
    );

// Bit 2 of the output is a[2] XOR b[2].
    check_bit2_matches_xor: assert property (
        @(posedge clk) out_comb_logic[2] == (a[2] ^ b[2])
    );

// Bit 3 of the output is a[3] XOR b[3].
    check_bit3_matches_xor: assert property (
        @(posedge clk) out_comb_logic[3] == (a[3] ^ b[3])
    );

// Equal inputs produce a zero output.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (a == b) |-> (out_comb_logic == 4'b0000)
    );

// Zero on b passes a through to the output.
    check_b_zero_passes_a: assert property (
        @(posedge clk) (b == 4'b0000) |-> (out_comb_logic == a)
    );

// Zero on a passes b through to the output.
    check_a_zero_passes_b: assert property (
        @(posedge clk) (a == 4'b0000) |-> (out_comb_logic == b)
    );

// If both inputs are equal, output must equal that common value.
    check_equal_inputs: assert property (
        @(posedge clk) (a == b) |-> (y == a)
    );

// Output must always match one of the two inputs.
    check_output_matches_an_input: assert property (
        @(posedge clk) (y == a) || (y == b)
    );

// Y must match the RTL Boolean equation.
    check_output_equation: assert property (
        @(posedge clk) Y == (A && B && !C && !D)
    );

// When A, B, !C, and !D are all true, Y must be high.
    check_y_high_on_match: assert property (
        @(posedge clk) (A && B && !C && !D) |-> Y
    );

// When the required input combination is not present, Y must be low.
    check_y_low_off_match: assert property (
        @(posedge clk) !(A && B && !C && !D) |-> !Y
    );

// Sum bit 2 uses the carry propagated through bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (A[2] ^ B[2] ^ fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin)))
    );

// Sum bit 3 uses the carry propagated through bits 0 to 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (A[3] ^ B[3] ^ fa_carry(A[2], B[2], fa_carry(A[1], B[1], fa_carry(A[0], B[0], cin))))
    );

// If A is greater than B, G must equal A.
    check_select_a_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (G == A)
    );

// If A is less than or equal to B, G must equal B.
    check_select_b_when_a_le_b: assert property (
        @(posedge clk) (A <= B) |-> (G == B)
    );

// G must never be smaller than A.
    check_g_not_less_than_a: assert property (
        @(posedge clk) (G >= A)
    );

// G must never be smaller than B.
    check_g_not_less_than_b: assert property (
        @(posedge clk) (G >= B)
    );

// G must always match one of the two inputs.
    check_g_matches_one_input: assert property (
        @(posedge clk) ((G == A) || (G == B))
    );

// If A and B are equal, G must equal that shared value.
    check_equal_inputs_return_that_value: assert property (
        @(posedge clk) (A == B) |-> (G == A)
    );

// RTL is combinational; clk is only used to sample assertions.
    // The RTL has no reset.

    // out must equal the XOR of the AND/OR intermediates plus one.
    check_output_equation: assert property (
        @(posedge clk) out == (((in1 & in2) ^ (in1 | in2)) + 8'h01)
    );

// Equal inputs make the XOR term zero, so out must be one.
    check_equal_inputs_result_one: assert property (
        @(posedge clk) (in1 == in2) |-> (out == 8'h01)
    );

// If in1 is zero, the logic reduces to in2 plus one.
    check_zero_in1_behavior: assert property (
        @(posedge clk) (in1 == 8'h00) |-> (out == (in2 + 8'h01))
    );

// If in2 is zero, the logic reduces to in1 plus one.
    check_zero_in2_behavior: assert property (
        @(posedge clk) (in2 == 8'h00) |-> (out == (in1 + 8'h01))
    );

// Complementary inputs produce 8'hFF before increment, so out wraps to zero.
    check_complementary_inputs_wrap: assert property (
        @(posedge clk) (in1 == ~in2) |-> (out == 8'h00)
    );

// Combinational DUT sampled on clk; no reset is present in the RTL.

    // Sum output implements three-input XOR.
    check_sum_matches_three_input_xor: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry output is asserted only by A and B both being high.
    check_carry_matches_ab_and: assert property (
        @(posedge clk) Co == (A & B)
    );

// With Ci low, sum reduces to A xor B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) (!Ci) |-> (S == (A ^ B))
    );

// With Ci high, sum is the inversion of A xor B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) Ci |-> (S == ~(A ^ B))
    );

// When A and B are equal, sum follows Ci.
    check_sum_tracks_cin_when_ab_equal: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

// When A and B differ, sum is the inverse of Ci.
    check_sum_inverts_cin_when_ab_different: assert property (
        @(posedge clk) (A != B) |-> (S == ~Ci)
    );

// Carry must be high whenever both A and B are high.
    check_carry_high_when_ab_high: assert property (
        @(posedge clk) (A && B) |-> Co
    );

// Carry must be low whenever either A or B is low.
    check_carry_low_when_either_operand_low: assert property (
        @(posedge clk) ((!A) || (!B)) |-> (!Co)
    );

// X implements the boolean function (A1 & A2) | B1.
    check_output_function: assert property (
        @(posedge clk) X == ((A1 & A2) | B1)
    );

// B1 high must force X high.
    check_b1_forces_high: assert property (
        @(posedge clk) B1 |-> X
    );

// With B1 low, X must equal the AND of A1 and A2.
    check_and_path_when_b1_low: assert property (
        @(posedge clk) !B1 |-> (X == (A1 & A2))
    );

// If A1 is low while B1 is low, X must be low.
    check_a1_low_blocks_output_without_b1: assert property (
        @(posedge clk) (!B1 && !A1) |-> !X
    );

// If A2 is low while B1 is low, X must be low.
    check_a2_low_blocks_output_without_b1: assert property (
        @(posedge clk) (!B1 && !A2) |-> !X
    );

// When both A inputs are high, X must be high.
    check_a_inputs_high_drive_output: assert property (
        @(posedge clk) (A1 && A2) |-> X
    );

// sel=000 selects data0 and inverts bits [3:1].
    check_sel_000_maps_data0: assert property (
        @(posedge clk)
        (sel === 3'b000) |-> ({o2, o1, o0} === ~data0[3:1])
    );

// sel=001 selects data1 and inverts bits [3:1].
    check_sel_001_maps_data1: assert property (
        @(posedge clk)
        (sel === 3'b001) |-> ({o2, o1, o0} === ~data1[3:1])
    );

// sel=010 selects data2 and inverts bits [3:1].
    check_sel_010_maps_data2: assert property (
        @(posedge clk)
        (sel === 3'b010) |-> ({o2, o1, o0} === ~data2[3:1])
    );

// sel=011 selects data3 and inverts bits [3:1].
    check_sel_011_maps_data3: assert property (
        @(posedge clk)
        (sel === 3'b011) |-> ({o2, o1, o0} === ~data3[3:1])
    );

// sel=100 selects data4 and inverts bits [3:1].
    check_sel_100_maps_data4: assert property (
        @(posedge clk)
        (sel === 3'b100) |-> ({o2, o1, o0} === ~data4[3:1])
    );

// sel=101 selects data5 and inverts bits [3:1].
    check_sel_101_maps_data5: assert property (
        @(posedge clk)
        (sel === 3'b101) |-> ({o2, o1, o0} === ~data5[3:1])
    );

// Any unsupported sel value drives all outputs high.
    check_default_sel_drives_ones: assert property (
        @(posedge clk)
        (!((sel === 3'b000) || (sel === 3'b001) || (sel === 3'b010) ||
           (sel === 3'b011) || (sel === 3'b100) || (sel === 3'b101)))
        |-> ({o2, o1, o0} === 3'b111)
    );

// Active-low reset drives the output to zero.
    check_reset_clears_output: assert property (
        @(negedge clk) !nreset |-> (out == '0)
    );

// The first falling edge after reset release still sees a zero output.
    check_release_edge_output_zero: assert property (
        @(negedge clk) (!nreset ##1 nreset) |-> (out == '0)
    );

// Each enabled falling edge makes out match the input from the prior falling edge.
    check_output_tracks_prior_input: assert property (
        @(negedge clk) disable iff (!nreset) 1'b1 |=> (out == $past(in))
    );

// External sampling clock; RTL has no clock or reset.

    // In add mode, S is the 4-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) (Cn == 1'b0) |-> (S == (A + B))
    );

// In subtract mode, S is the 4-bit difference A minus B.
    check_sub_result: assert property (
        @(posedge clk) (Cn == 1'b1) |-> (S == (A - B))
    );

// In add mode, V matches the implemented overflow equation.
    check_add_overflow_exact: assert property (
        @(posedge clk) (Cn == 1'b0) |-> (V == ((A[3] & B[3] & ~S[3]) | (~A[3] & ~B[3] & S[3])))
    );

// In subtract mode, V matches the implemented overflow equation.
    check_sub_overflow_exact: assert property (
        @(posedge clk) (Cn == 1'b1) |-> (V == ((A[3] & ~B[3] & ~S[3]) | (~A[3] & B[3] & S[3])))
    );

// Adding two negative operands with a non-negative result sets overflow.
    check_add_neg_neg_to_pos_overflow: assert property (
        @(posedge clk) ((Cn == 1'b0) && A[3] && B[3] && ~S[3]) |-> (V == 1'b1)
    );

// Adding two non-negative operands with a negative result sets overflow.
    check_add_pos_pos_to_neg_overflow: assert property (
        @(posedge clk) ((Cn == 1'b0) && ~A[3] && ~B[3] && S[3]) |-> (V == 1'b1)
    );

// Adding operands with opposite signs cannot overflow.
    check_add_mixed_sign_no_overflow: assert property (
        @(posedge clk) ((Cn == 1'b0) && (A[3] != B[3])) |-> (V == 1'b0)
    );

// Subtracting a non-negative operand from a negative operand can overflow high.
    check_sub_neg_minus_pos_overflow: assert property (
        @(posedge clk) ((Cn == 1'b1) && A[3] && ~B[3] && ~S[3]) |-> (V == 1'b1)
    );

// Subtracting a negative operand from a non-negative operand can overflow low.
    check_sub_pos_minus_neg_overflow: assert property (
        @(posedge clk) ((Cn == 1'b1) && ~A[3] && B[3] && S[3]) |-> (V == 1'b1)
    );

// Subtracting same-sign operands cannot overflow.
    check_sub_same_sign_no_overflow: assert property (
        @(posedge clk) ((Cn == 1'b1) && (A[3] == B[3])) |-> (V == 1'b0)
    );

// No DUT clock/reset; this checker samples the combinational interface on clk.

    // out_valid is exactly the enable signal.
    check_out_valid_matches_en: assert property (
        @(posedge clk) out_valid == en
    );

// out is the AND of both inputs gated by enable.
    check_out_matches_function: assert property (
        @(posedge clk) out == (in1 & in2 & en)
    );

// When enable is low, out must be low.
    check_disable_forces_out_low: assert property (
        @(posedge clk) !en |-> !out
    );

// A high out requires both inputs high and enable asserted.
    check_out_high_requires_all_inputs: assert property (
        @(posedge clk) out |-> (in1 && in2 && en && out_valid)
    );

// When enabled and both inputs are high, out must be high.
    check_enabled_high_inputs_drive_out: assert property (
        @(posedge clk) (en && in1 && in2) |-> out
    );

// Output matches the gated XOR function.
    check_gated_xor_function: assert property (
        @(posedge clk) out == (control ? (a ^ b) : 1'b0)
    );

// Output is forced low when control is deasserted.
    check_control_low_forces_zero: assert property (
        @(posedge clk) !control |-> (out == 1'b0)
    );

// Output equals a XOR b when control is asserted.
    check_control_high_passes_xor: assert property (
        @(posedge clk) control |-> (out == (a ^ b))
    );

// With control asserted, equal inputs produce a low output.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (control && (a == b)) |-> (out == 1'b0)
    );

// With control asserted, different inputs produce a high output.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (control && (a != b)) |-> (out == 1'b1)
    );

// X is the NOR of B1 and C1; A1 and A2 do not affect X.
    check_x_matches_nor_function: assert property (
        @(posedge clk) X == ~(B1 | C1)
    );

// If both NOR inputs are low, X must be high.
    check_x_high_when_b1_c1_low: assert property (
        @(posedge clk) (!B1 && !C1) |-> X
    );

// If B1 is high, X must be low.
    check_x_low_when_b1_high: assert property (
        @(posedge clk) B1 |-> !X
    );

// If C1 is high, X must be low.
    check_x_low_when_c1_high: assert property (
        @(posedge clk) C1 |-> !X
    );

// A high X means both NOR inputs are low.
    check_x_high_implies_b1_c1_low: assert property (
        @(posedge clk) X |-> (!B1 && !C1)
    );

// A low X means at least one NOR input is high.
    check_x_low_implies_b1_or_c1_high: assert property (
        @(posedge clk) !X |-> (B1 || C1)
    );

// Sampling clock for this combinational DUT; the RTL has no reset.

    // In add mode, the output is the 16-bit sum of the inputs.
    check_add_mode_result: assert property (
        @(posedge clk) !control |-> (out == (in0 + in1))
    );

// In subtract mode, the output is the 16-bit difference of the inputs.
    check_sub_mode_result: assert property (
        @(posedge clk) control |-> (out == (in0 - in1))
    );

// The output always matches the operation selected by control.
    check_selected_operation: assert property (
        @(posedge clk) out == (control ? (in0 - in1) : (in0 + in1))
    );

// Check the direct add path when select is low.
    check_direct_add_path: assert property (
        @(posedge clk) (!select && C) |-> (out == (A + B))
    );

// Check the direct subtract path when select is low.
    check_direct_sub_path: assert property (
        @(posedge clk) (!select && !C) |-> (out == (A - B))
    );

// Check the two's complement of the add result when select is high.
    check_twos_comp_add_path: assert property (
        @(posedge clk) (select && C) |-> (out == ((~(A + B)) + 4'b0001))
    );

// Check the two's complement of the subtract result when select is high.
    check_twos_comp_sub_path: assert property (
        @(posedge clk) (select && !C) |-> (out == ((~(A - B)) + 4'b0001))
    );

// Check the full output function for all input combinations.
    check_full_output_function: assert property (
        @(posedge clk)
        out == (select ? ((~(C ? (A + B) : (A - B))) + 4'b0001)
                       :  (C ? (A + B) : (A - B)))
    );

// When sel is 0, C must be the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) (sel === 1'b0) |-> (C === (A + B))
    );

// When sel is not 0, C must be the bitwise AND of A and B.
    check_and_mode_result: assert property (
        @(posedge clk) (sel !== 1'b0) |-> (C === (A & B))
    );

// q_int shifts left and captures d[0] on each falling clock edge.
    check_qint_shift_register: assert property (
        @(negedge clk) 1'b1 |=> q_int == {$past(q_int[6:0]), $past(d[0])}
    );

// dff_sel increments by one when sel is high.
    check_dff_sel_increment: assert property (
        @(negedge clk) sel |=> dff_sel == ($past(dff_sel) + 4'd1)
    );

// dff_sel decrements by one when sel is low.
    check_dff_sel_decrement: assert property (
        @(negedge clk) !sel |=> dff_sel == ($past(dff_sel) - 4'd1)
    );

// q passes q_int through when dff_sel[3] is high.
    check_q_passthrough_when_msb_set: assert property (
        @(posedge clk) dff_sel[3] |-> q == {q_int[7:4], q_int[3:0]}
    );

// q swaps the q_int nibbles when dff_sel[3] is low.
    check_q_nibble_swap_when_msb_clear: assert property (
        @(posedge clk) !dff_sel[3] |-> q == {q_int[3:0], q_int[7:4]}
    );

// out must be high when A is greater than B.
    check_out_high_on_greater: assert property (
        @(posedge clk) (A > B) |-> (out == 1'b1)
    );

// out must be low when A is less than B.
    check_out_low_on_less: assert property (
        @(posedge clk) (A < B) |-> (out == 1'b0)
    );

// out must be low when A equals B.
    check_out_low_on_equal: assert property (
        @(posedge clk) (A == B) |-> (out == 1'b0)
    );

// out can only be high for a greater-than comparison.
    check_out_high_implies_greater: assert property (
        @(posedge clk) (out == 1'b1) |-> (A > B)
    );

// Y matches the implemented NOR-of-terms function.
    check_y_matches_boolean_function: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 asserted forces Y low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 both asserted force Y low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// B1 and B2 both asserted force Y low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// With no active NOR input term, Y must be high.
    check_no_active_term_sets_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// If Y is low, at least one NOR input term must be active.
    check_y_low_has_active_cause: assert property (
        @(posedge clk) !Y |-> (C1 || (A1 && A2) || (B1 && B2))
    );

// If Y is high, all NOR input terms must be inactive.
    check_y_high_means_all_terms_inactive: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 && A2) && !(B1 && B2))
    );

// The concatenated output matches 4-bit addition with carry-in.
    check_total_addition: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Sum bit 0 is the XOR of the LSB inputs and carry-in.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum bit 1 uses the carry generated by bit 0.
    check_bit1_sum_from_carry0: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

// Sum bit 2 uses the carry generated by bit 1.
    check_bit2_sum_from_carry1: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                   (A[1] ^ B[1]))))
    );

// Sum bit 3 uses the carry generated by bit 2.
    check_bit3_sum_from_carry2: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  (((A[1] & B[1]) |
                    (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                     (A[1] ^ B[1]))) &
                   (A[2] ^ B[2]))))
    );

// SUM must equal the XOR of the three inputs.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ CIN)
    );

// COUT must equal the full-adder carry equation.
    check_cout_equation: assert property (
        @(posedge clk) COUT == ((A & B) | (B & CIN) | (A & CIN))
    );

// All-zero inputs must produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CIN) |-> (!SUM && !COUT)
    );

// All-one inputs must produce sum one and carry one.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CIN) |-> (SUM && COUT)
    );

// Exactly one high input must produce sum one and carry zero.
    check_one_hot_input_case: assert property (
        @(posedge clk)
        ((A && !B && !CIN) || (!A && B && !CIN) || (!A && !B && CIN))
        |-> (SUM && !COUT)
    );

// Exactly two high inputs must produce sum zero and carry one.
    check_two_hot_input_case: assert property (
        @(posedge clk)
        ((A && B && !CIN) || (A && !B && CIN) || (!A && B && CIN))
        |-> (!SUM && COUT)
    );

// When A and B are both high, carry must be asserted.
    check_ab_generates_carry: assert property (
        @(posedge clk) (A && B) |-> COUT
    );

// When B and CIN are both high, carry must be asserted.
    check_bcin_generates_carry: assert property (
        @(posedge clk) (B && CIN) |-> COUT
    );

// When A and CIN are both high, carry must be asserted.
    check_acin_generates_carry: assert property (
        @(posedge clk) (A && CIN) |-> COUT
    );

// When sel is low, out passes A.
    check_selects_a_when_sel_low: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === A)
    );

// When sel is high, out passes B.
    check_selects_b_when_sel_high: assert property (
        @(posedge clk) (sel === 1'b1) |-> (out === B)
    );

// A rising sel switches the output to B.
    check_sel_rise_switches_to_b: assert property (
        @(posedge clk) $rose(sel) |-> (out === B)
    );

// A falling sel switches the output to A.
    check_sel_fall_switches_to_a: assert property (
        @(posedge clk) $fell(sel) |-> (out === A)
    );

// Q_bar is always the inverse of Q.
    check_qbar_complement: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (Q_bar == ~Q)
    );

// When enabled, SET drives the set state and overrides RESET.
    check_set_path: assert property (
        @(posedge CLK) disable iff (1'b0)
        (EN && SET) |=> (Q == 1'b1 && Q_bar == 1'b0)
    );

// When enabled and SET is low, RESET drives the reset state.
    check_reset_path: assert property (
        @(posedge CLK) disable iff (1'b0)
        (EN && !SET && RESET) |=> (Q == 1'b0 && Q_bar == 1'b1)
    );

// When enabled with no set/reset, the flop captures D.
    check_data_capture_path: assert property (
        @(posedge CLK) disable iff (1'b0)
        (EN && !SET && !RESET) |=> (Q == $past(D) && Q_bar == (~$past(D)))
    );

// When not enabled, both outputs hold their previous values.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!EN) |=> ($stable(Q) && $stable(Q_bar))
    );

// Output matches the implemented combinational equation.
    check_output_matches_rtl: assert property (
        @(posedge clk)
        output_y == (((input_a | input_b | input_c) && !(input_b & input_c)) ||
                     (input_a && !(input_a & input_b) && !(input_a & input_c)) ||
                     (input_b && !(input_a & input_b) && !(input_b & input_c)) ||
                     (input_c && !(input_a & input_c) && !(input_b & input_c)))
    );

// Output is LOW when all inputs are LOW.
    check_all_inputs_low: assert property (
        @(posedge clk)
        (!input_a && !input_b && !input_c) |-> !output_y
    );

// Output is HIGH when input_a is HIGH and input_b/input_c are not both HIGH.
    check_input_a_without_bc_pair: assert property (
        @(posedge clk)
        (input_a && !(input_b && input_c)) |-> output_y
    );

// Output is HIGH when input_a is LOW and exactly one of input_b/input_c is HIGH.
    check_exactly_one_of_b_or_c_without_a: assert property (
        @(posedge clk)
        (!input_a && ((input_b && !input_c) || (!input_b && input_c))) |-> output_y
    );

// Output is LOW whenever input_b and input_c are both HIGH.
    check_b_and_c_force_low: assert property (
        @(posedge clk)
        (input_b && input_c) |-> !output_y
    );

// When disabled, data holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) !en |=> $stable(data)
    );

// Enabled address 0 maps to 8'hFF.
    check_addr_0_map: assert property (
        @(posedge clk) (en && (addr == 4'h0)) |=> (data == 8'hFF)
    );

// Enabled address 1 maps to 8'h81.
    check_addr_1_map: assert property (
        @(posedge clk) (en && (addr == 4'h1)) |=> (data == 8'h81)
    );

// Enabled address 2 maps to 8'hEF.
    check_addr_2_map: assert property (
        @(posedge clk) (en && (addr == 4'h2)) |=> (data == 8'hEF)
    );

// Enabled address 3 maps to 8'h64.
    check_addr_3_map: assert property (
        @(posedge clk) (en && (addr == 4'h3)) |=> (data == 8'h64)
    );

// Enabled address 4 maps to 8'hF7.
    check_addr_4_map: assert property (
        @(posedge clk) (en && (addr == 4'h4)) |=> (data == 8'hF7)
    );

// Enabled address 5 maps to 8'h11.
    check_addr_5_map: assert property (
        @(posedge clk) (en && (addr == 4'h5)) |=> (data == 8'h11)
    );

// Enabled address 6 maps to 8'hF7.
    check_addr_6_map: assert property (
        @(posedge clk) (en && (addr == 4'h6)) |=> (data == 8'hF7)
    );

// Enabled address 7 maps to 8'h8C.
    check_addr_7_map: assert property (
        @(posedge clk) (en && (addr == 4'h7)) |=> (data == 8'h8C)
    );

// Enabled address 8 maps to 8'h08.
    check_addr_8_map: assert property (
        @(posedge clk) (en && (addr == 4'h8)) |=> (data == 8'h08)
    );

// Enabled address 9 maps to 8'h3C.
    check_addr_9_map: assert property (
        @(posedge clk) (en && (addr == 4'h9)) |=> (data == 8'h3C)
    );

// Enabled addresses A-F map to 8'h00.
    check_default_map: assert property (
        @(posedge clk)
        (en && ((addr == 4'hA) || (addr == 4'hB) || (addr == 4'hC) ||
                (addr == 4'hD) || (addr == 4'hE) || (addr == 4'hF)))
        |=> (data == 8'h00)
    );

// X must equal the majority-of-three function.
    check_output_matches_majority: assert property (
        @(posedge clk) X == ((A & B) | (A & C) | (B & C))
    );

// A and B high together must drive X high.
    check_ab_pair_sets_x: assert property (
        @(posedge clk) (A & B) |-> X
    );

// A and C high together must drive X high.
    check_ac_pair_sets_x: assert property (
        @(posedge clk) (A & C) |-> X
    );

// B and C high together must drive X high.
    check_bc_pair_sets_x: assert property (
        @(posedge clk) (B & C) |-> X
    );

// With no input pair high, X must be low.
    check_no_pair_clears_x: assert property (
        @(posedge clk) (!(A & B) && !(A & C) && !(B & C)) |-> !X
    );

// A high X requires at least one input pair to be high.
    check_x_requires_two_high_inputs: assert property (
        @(posedge clk) X |-> ((A & B) | (A & C) | (B & C))
    );

// mode=0 selects the reachable left-shift case item.
    check_mode0_left_shift: assert property (
        @(posedge clk)
        (mode === 1'b0) |-> (data_out === (data_in << shift_amount))
    );

// mode=1 selects the reachable right-shift case item.
    check_mode1_right_shift: assert property (
        @(posedge clk)
        (mode === 1'b1) |-> (data_out === (data_in >> shift_amount))
    );

// mode=0 with shift_amount=0 leaves the input unchanged.
    check_left_shift_0: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd0) |-> (data_out === data_in)
    );

// mode=0 with shift_amount=1 shifts left by one bit.
    check_left_shift_1: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd1) |-> (data_out === {data_in[2:0], 1'b0})
    );

// mode=0 with shift_amount=2 shifts left by two bits.
    check_left_shift_2: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd2) |-> (data_out === {data_in[1:0], 2'b00})
    );

// mode=0 with shift_amount=3 shifts left by three bits.
    check_left_shift_3: assert property (
        @(posedge clk)
        (mode === 1'b0 && shift_amount === 2'd3) |-> (data_out === {data_in[0], 3'b000})
    );

// mode=1 with shift_amount=0 leaves the input unchanged.
    check_right_shift_0: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd0) |-> (data_out === data_in)
    );

// mode=1 with shift_amount=1 shifts right by one bit.
    check_right_shift_1: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd1) |-> (data_out === {1'b0, data_in[3:1]})
    );

// mode=1 with shift_amount=2 shifts right by two bits.
    check_right_shift_2: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd2) |-> (data_out === {2'b00, data_in[3:2]})
    );

// mode=1 with shift_amount=3 shifts right by three bits.
    check_right_shift_3: assert property (
        @(posedge clk)
        (mode === 1'b1 && shift_amount === 2'd3) |-> (data_out === {3'b000, data_in[3]})
    );

// O matches the RTL mux equation.
    check_o_equation: assert property (
        @(posedge clk) O == ((S & DI) | (~S & CI))
    );

// CO matches the RTL carry equation.
    check_co_equation: assert property (
        @(posedge clk) CO == ((CI & S) | (DI & (CI | S)))
    );

// When S is high, O selects DI.
    check_o_selects_di_when_s_high: assert property (
        @(posedge clk) S |-> (O == DI)
    );

// When S is low, O selects CI.
    check_o_selects_ci_when_s_low: assert property (
        @(posedge clk) !S |-> (O == CI)
    );

// When S is high, CO reduces to CI OR DI.
    check_co_reduces_to_or_when_s_high: assert property (
        @(posedge clk) S |-> (CO == (CI | DI))
    );

// When S is low, CO reduces to CI AND DI.
    check_co_reduces_to_and_when_s_low: assert property (
        @(posedge clk) !S |-> (CO == (CI & DI))
    );

// Equal data inputs force both outputs to that shared value.
    check_equal_inputs_drive_equal_outputs: assert property (
        @(posedge clk) (CI == DI) |-> ((O == CI) && (CO == CI))
    );

// Low reset forces count to zero.
    check_reset_low_clears_count: assert property (
        @(posedge clk) !async_reset |-> (count == 2'b00)
    );

// First clock after reset release starts from zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) ($past(!async_reset) && async_reset) |-> (count == 2'b00)
    );

// Enable 00 holds the count value.
    check_hold_on_enable_00: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b00) |=> (count == $past(count))
    );

// Enable 01 increments the count by one.
    check_increment_on_enable_01: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b01) |=> (count == ($past(count) + 2'b01))
    );

// Enable 10 decrements the count by one.
    check_decrement_on_enable_10: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b10) |=> (count == ($past(count) - 2'b01))
    );

// Enable 11 follows the default hold behavior.
    check_hold_on_enable_11: assert property (
        @(posedge clk) disable iff (!async_reset)
        (enable == 2'b11) |=> (count == $past(count))
    );

// Reset clears all registers on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk)
        reset |=> (pipeline_reg1 == 4'b0) &&
                  (pipeline_reg2 == 4'b0) &&
                  (pipeline_reg3 == 4'b0) &&
                  (out == 4'b0)
    );

// Any reset cycle leaves ENCLK low by the next observed clock.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RESET |=> (ENCLK == 1'b0)
    );

// With EN low, the RTL takes the else branch and drives ENCLK low.
    check_en_low_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (!EN) |=> (ENCLK == 1'b0)
    );

// With EN and TE high, the TE branch drives ENCLK low.
    check_te_high_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (EN && TE) |=> (ENCLK == 1'b0)
    );

// A high pulse appears on the next high phase when EN is high and TE is low.
    check_pulse_when_enabled: assert property (
        @(posedge CLK) (EN && !TE) |=> @(negedge CLK) (ENCLK == 1'b1)
    );

// No high pulse appears on the next high phase when the gate condition is false.
    check_no_pulse_when_blocked: assert property (
        @(posedge CLK) (!(EN && !TE)) |=> @(negedge CLK) (ENCLK == 1'b0)
    );

// TE overrides EN and suppresses the gated clock pulse.
    check_test_enable_overrides_enable: assert property (
        @(posedge CLK) (EN && TE) |=> @(negedge CLK) (ENCLK == 1'b0)
    );

// ENCLK is low at every sampled rising edge.
    check_enclk_low_on_rising_edge: assert property (
        @(posedge CLK) (ENCLK == 1'b0)
    );

// Synchronous reset clears the counter to 00 on the next clock.
    check_reset_clears_to_zero: assert property (
        @(posedge CLK) RST |=> ((Q1 == 1'b0) && (Q0 == 1'b0))
    );

// State 00 advances to 01 when reset is not asserted.
    check_state_00_to_01: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b0) && (Q0 == 1'b0)) |=> ((Q1 == 1'b0) && (Q0 == 1'b1))
    );

// State 01 advances to 10 when reset is not asserted.
    check_state_01_to_10: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b0) && (Q0 == 1'b1)) |=> ((Q1 == 1'b1) && (Q0 == 1'b0))
    );

// State 10 advances to 01 when reset is not asserted.
    check_state_10_to_01: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b1) && (Q0 == 1'b0)) |=> ((Q1 == 1'b0) && (Q0 == 1'b1))
    );

// State 11 is forced back to 00 on the next clock.
    check_state_11_to_00: assert property (
        @(posedge CLK) disable iff (RST)
        ((Q1 == 1'b1) && (Q0 == 1'b1)) |=> ((Q1 == 1'b0) && (Q0 == 1'b0))
    );

// The next sampled state is never 11 outside of reset.
    check_next_state_not_11: assert property (
        @(posedge CLK) disable iff (RST)
        1'b1 |=> !((Q1 == 1'b1) && (Q0 == 1'b1))
    );

// A high LOAD transfers A into Q on the next sampled cycle.
    check_load_captures_a: assert property (
        @(posedge CLK) LOAD |=> (Q == $past(A))
    );

// A low LOAD causes Q to retain its previous value.
    check_hold_when_load_low: assert property (
        @(posedge CLK) !LOAD |=> (Q == $past(Q))
    );

// Q follows the prior cycle's LOAD-controlled update rule.
    check_q_transition_rule: assert property (
        @(posedge CLK) 1'b1 |=> ($past(LOAD) ? (Q == $past(A)) : (Q == $past(Q)))
    );

// sel=8'hFF selects in[31:0], reverses its bytes, and adds the two values.
    check_sel_ff_selects_word0: assert property (
        @(posedge clk) (sel == 8'hFF) |-> (out == (in[31:0] + byte_reverse32(in[31:0])))
    );

// sel=8'hFE selects in[63:32], reverses its bytes, and adds the two values.
    check_sel_fe_selects_word1: assert property (
        @(posedge clk) (sel == 8'hFE) |-> (out == (in[63:32] + byte_reverse32(in[63:32])))
    );

// sel=8'hFD selects in[95:64], reverses its bytes, and adds the two values.
    check_sel_fd_selects_word2: assert property (
        @(posedge clk) (sel == 8'hFD) |-> (out == (in[95:64] + byte_reverse32(in[95:64])))
    );

// sel=8'hFC selects in[127:96], reverses its bytes, and adds the two values.
    check_sel_fc_selects_word3: assert property (
        @(posedge clk) (sel == 8'hFC) |-> (out == (in[127:96] + byte_reverse32(in[127:96])))
    );

// sel=8'hFB selects in[159:128], reverses its bytes, and adds the two values.
    check_sel_fb_selects_word4: assert property (
        @(posedge clk) (sel == 8'hFB) |-> (out == (in[159:128] + byte_reverse32(in[159:128])))
    );

// sel=8'hFA selects in[191:160], reverses its bytes, and adds the two values.
    check_sel_fa_selects_word5: assert property (
        @(posedge clk) (sel == 8'hFA) |-> (out == (in[191:160] + byte_reverse32(in[191:160])))
    );

// sel=8'hF9 selects in[223:192], reverses its bytes, and adds the two values.
    check_sel_f9_selects_word6: assert property (
        @(posedge clk) (sel == 8'hF9) |-> (out == (in[223:192] + byte_reverse32(in[223:192])))
    );

// sel=8'hF8 selects in[255:224], reverses its bytes, and adds the two values.
    check_sel_f8_selects_word7: assert property (
        @(posedge clk) (sel == 8'hF8) |-> (out == (in[255:224] + byte_reverse32(in[255:224])))
    );

// No reset in RTL; assertions are sampled on an external clock.

    // The concatenated outputs equal the 5-bit sum of A, B, and CIN.
    check_full_sum_function: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0, CIN})
    );

// COUT is asserted exactly when the addition overflows 4 bits.
    check_cout_matches_overflow: assert property (
        @(posedge clk) COUT == (({1'b0, A} + {1'b0, B} + {4'b0, CIN}) >= 5'd16)
    );

// With B and CIN low, the adder passes A through with no carry.
    check_a_passthrough_zero_addend: assert property (
        @(posedge clk) (B == 4'h0 && CIN == 1'b0) |-> (SUM == A && COUT == 1'b0)
    );

// With A and CIN low, the adder passes B through with no carry.
    check_b_passthrough_zero_addend: assert property (
        @(posedge clk) (A == 4'h0 && CIN == 1'b0) |-> (SUM == B && COUT == 1'b0)
    );

// All-zero inputs produce an all-zero result.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && CIN == 1'b0) |-> (SUM == 4'h0 && COUT == 1'b0)
    );

// A carry-in alone increments zero to one without overflow.
    check_cin_only_case: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && CIN == 1'b1) |-> (SUM == 4'h1 && COUT == 1'b0)
    );

// The maximum input combination produces 5'h1f.
    check_maximum_input_case: assert property (
        @(posedge clk) (A == 4'hf && B == 4'hf && CIN == 1'b1) |-> (SUM == 4'hf && COUT == 1'b1)
    );

// When reset is asserted low, the counter is cleared.
    reset_clears_count: assert property (
        @(posedge clk)
        !rst |-> (count == 4'd0)
    );

// When enabled outside reset, the counter increments by one.
    enable_increments_count: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> (count == ($past(count) + 4'd1))
    );

// When not enabled outside reset, the counter holds its value.
    disable_holds_count: assert property (
        @(posedge clk) disable iff (!rst)
        !en |=> (count == $past(count))
    );

// Y implements the RTL gate function.
    check_function_implemented: assert property (
        @(posedge clk) Y == ~(D & C & B & ~A_N)
    );

// All active inputs drive the NAND output low.
    check_all_active_inputs_drive_low: assert property (
        @(posedge clk) (!A_N && B && C && D) |-> !Y
    );

// A low output only occurs for the active input combination.
    check_low_output_only_when_all_active: assert property (
        @(posedge clk) !Y |-> (!A_N && B && C && D)
    );

// With B, C, and D high, Y follows A_N.
    check_a_n_controls_output_when_bcd_high: assert property (
        @(posedge clk) (B && C && D) |-> (Y == A_N)
    );

// With A_N low and C/D high, Y is the inverse of B.
    check_b_controls_output_when_a_ncd_active: assert property (
        @(posedge clk) (!A_N && C && D) |-> (Y == !B)
    );

// With A_N low and B/D high, Y is the inverse of C.
    check_c_controls_output_when_a_nbd_active: assert property (
        @(posedge clk) (!A_N && B && D) |-> (Y == !C)
    );

// With A_N low and B/C high, Y is the inverse of D.
    check_d_controls_output_when_a_nbc_active: assert property (
        @(posedge clk) (!A_N && B && C) |-> (Y == !D)
    );

// A high output means at least one input is in its inactive state.
    check_high_output_has_valid_cause: assert property (
        @(posedge clk) Y |-> (A_N || !B || !C || !D)
    );

// LT is never asserted by this implementation.
    check_lt_output_always_low: assert property (
        @(posedge clk)
        (LT == 1'b0)
    );

// OUT matches A+B in add mode.
    check_out_matches_sum_in_add_mode: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (OUT == (A + B))
    );

// COUT matches OUT[3] in add mode.
    check_cout_matches_out_msb_in_add_mode: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (COUT == OUT[3])
    );

// OUT matches ~B+1 in subtract mode.
    check_out_matches_twos_complement_b_in_sub_mode: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (OUT == ((~B) + 4'd1))
    );

// Y matches the 3-input NAND of A, B, and C.
    check_nand_function: assert property (
        @(posedge clk) Y === ~(A & B & C)
    );

// When all three inputs are high, Y must be low.
    check_all_high_drives_low: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1) && (C === 1'b1)) |-> (Y === 1'b0)
    );

// If any input is low, Y must be high.
    check_any_low_drives_high: assert property (
        @(posedge clk) ((A === 1'b0) || (B === 1'b0) || (C === 1'b0)) |-> (Y === 1'b1)
    );

// A low Y can only occur when all inputs are high.
    check_low_output_requires_all_high: assert property (
        @(posedge clk) (Y === 1'b0) |-> ((A === 1'b1) && (B === 1'b1) && (C === 1'b1))
    );

// A high Y requires at least one input to be low.
    check_high_output_requires_any_low: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A === 1'b0) || (B === 1'b0) || (C === 1'b0))
    );

// On a load cycle, q must capture data_in by the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (q == $past(data_in))
    );

// On a non-load cycle, q must rotate left by one bit by the next clock.
    check_shift_rotates_q: assert property (
        @(posedge clk) !load |=> (q == { $past(q[2]), $past(q[1]), $past(q[0]), $past(q[3]) })
    );

// Every cycle, q must follow the RTL next-state function from the prior cycle.
    check_next_state_function: assert property (
        @(posedge clk) 1'b1 |=> (q == ($past(load) ? $past(data_in)
                                                 : { $past(q[2]), $past(q[1]), $past(q[0]), $past(q[3]) }))
    );

// During a shift, q[3] must take the previous q[2].
    check_shift_bit3_mapping: assert property (
        @(posedge clk) !load |=> (q[3] == $past(q[2]))
    );

// During a shift, q[2] must take the previous q[1].
    check_shift_bit2_mapping: assert property (
        @(posedge clk) !load |=> (q[2] == $past(q[1]))
    );

// During a shift, q[1] must take the previous q[0].
    check_shift_bit1_mapping: assert property (
        @(posedge clk) !load |=> (q[1] == $past(q[0]))
    );

// During a shift, q[0] must wrap from the previous q[3].
    check_shift_bit0_mapping: assert property (
        @(posedge clk) !load |=> (q[0] == $past(q[3]))
    );

// Addition mode drives the sum and clears the other outputs.
    check_addition_mode_outputs: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((add_out == calc_add(a, b)) &&
                           (sub_out == 16'sh0000) &&
                           (mul_out == 16'sh0000) &&
                           (div_out == 16'sh0000))
    );

// Subtraction mode drives the difference and clears the other outputs.
    check_subtraction_mode_outputs: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((add_out == 16'sh0000) &&
                           (sub_out == calc_sub(a, b)) &&
                           (mul_out == 16'sh0000) &&
                           (div_out == 16'sh0000))
    );

// Division by zero returns 16'hFFFF and clears the other outputs.
    check_division_mode_zero_divisor: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b == 16'sh0000)) |-> ((add_out == 16'sh0000) &&
                                                 (sub_out == 16'sh0000) &&
                                                 (mul_out == 16'sh0000) &&
                                                 (div_out == 16'shFFFF))
    );

// Y matches the implemented combinational equation.
    check_y_matches_function: assert property (
        @(posedge clk) Y == ((A1 && A2) || (A3 && A4) || B1)
    );

// B1 high is sufficient to drive Y high.
    check_b1_drives_y_high: assert property (
        @(posedge clk) B1 |-> Y
    );

// A1 and A2 high together are sufficient to drive Y high.
    check_a1_a2_drive_y_high: assert property (
        @(posedge clk) (A1 && A2) |-> Y
    );

// A3 and A4 high together are sufficient to drive Y high.
    check_a3_a4_drive_y_high: assert property (
        @(posedge clk) (A3 && A4) |-> Y
    );

// Y low means all three OR terms are low.
    check_y_low_requires_all_terms_low: assert property (
        @(posedge clk) !Y |-> (!(A1 && A2) && !(A3 && A4) && !B1)
    );

// Output is zero when the shift amount exceeds the 4-bit width.
    check_zero_when_shift_too_large: assert property (
        @(posedge clk) (B > 4'd3) |-> (out == 4'b0000)
    );

// Output equals A shifted left by B for valid shift amounts.
    check_shift_for_valid_range: assert property (
        @(posedge clk) (B <= 4'd3) |-> (out == (A << B))
    );

// A zero shift amount passes A through unchanged.
    check_no_shift_when_B_zero: assert property (
        @(posedge clk) (B == 4'd0) |-> (out == A)
    );

// A shift amount of one inserts one zero at the LSB.
    check_shift_by_one: assert property (
        @(posedge clk) (B == 4'd1) |-> (out == {A[2:0], 1'b0})
    );

// A shift amount of two inserts two zeros at the LSBs.
    check_shift_by_two: assert property (
        @(posedge clk) (B == 4'd2) |-> (out == {A[1:0], 2'b00})
    );

// A shift amount of three leaves only A[0] in the MSB position.
    check_shift_by_three: assert property (
        @(posedge clk) (B == 4'd3) |-> (out == {A[0], 3'b000})
    );

// X must match the implemented combinational function.
    check_exact_function: assert property (
        @(posedge clk) X == ((A1 & A2) & (VPWR > VGND))
    );

// A low A1 input forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A low A2 input forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) !A2 |-> !X
    );

// An invalid power comparison forces X low.
    check_power_not_good_forces_x_low: assert property (
        @(posedge clk) !(VPWR > VGND) |-> !X
    );

// A high X requires both inputs high and power valid.
    check_x_high_requires_inputs_and_power: assert property (
        @(posedge clk) X |-> (A1 && A2 && (VPWR > VGND))
    );

// Both inputs high with valid power must drive X high.
    check_all_conditions_drive_x_high: assert property (
        @(posedge clk) (A1 && A2 && (VPWR > VGND)) |-> X
    );

// Synchronous reset clears q and overflow.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |=> (q == 16'h0000 && overflow == 1'b0)
    );

// Load captures d into q and clears overflow.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (rst)
        ld |=> (q == $past(d) && overflow == 1'b0)
    );

// When not loading and not at max, q increments and overflow stays low.
    check_increment_behavior: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (q != 16'hFFFF)) |=> (q == ($past(q) + 16'h0001) && overflow == 1'b0)
    );

// When not loading at max count, q wraps to zero and overflow is set.
    check_wrap_sets_overflow: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (q == 16'hFFFF)) |=> (q == 16'h0000 && overflow == 1'b1)
    );

// A wrap-generated overflow pulse lasts only one cycle.
    check_overflow_single_cycle_on_wrap: assert property (
        @(posedge clk) disable iff (rst)
        (!ld && (q == 16'hFFFF)) |=> (overflow == 1'b1) ##1 (overflow == 1'b0)
    );

// Sum equals the XOR of the three inputs.
    check_sum_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        S == (A ^ B ^ Cin)
    );

// Carry equals the full-adder carry function.
    check_carry_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == ((A & B) | (Cin & (A ^ B)))
    );

// With Cin low, the adder behaves like a half adder.
    check_cin_low_half_adder: assert property (
        @(posedge clk) disable iff (1'b0)
        (Cin == 1'b0) |-> ((S == (A ^ B)) && (Cout == (A & B)))
    );

// With Cin high, sum is XNOR and carry is OR.
    check_cin_high_behavior: assert property (
        @(posedge clk) disable iff (1'b0)
        (Cin == 1'b1) |-> ((S == ~(A ^ B)) && (Cout == (A | B)))
    );

// All-zero inputs produce zero sum and zero carry.
    check_all_zero_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A && !B && !Cin) |-> (!S && !Cout)
    );

// All-one inputs produce sum one and carry one.
    check_all_one_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        (A && B && Cin) |-> (S && Cout)
    );

// Any one-high input pattern produces sum one and no carry.
    check_single_high_input_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A && !B && !Cin) || (!A && B && !Cin) || (!A && !B && Cin))
        |-> (S && !Cout)
    );

// Any two-high input pattern produces no sum and carry one.
    check_two_high_input_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A && B && !Cin) || (A && !B && Cin) || (!A && B && Cin))
        |-> (!S && Cout)
    );

// Reset forces the output to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 32'h00000000)
    );

// Outside reset, the output matches the implemented concatenation.
    check_nonreset_output_encoding: assert property (
        @(posedge clk) disable iff (reset) (out == {in, {16{!in[15]}}})
    );

// Outside reset, the upper 16 bits mirror the input.
    check_nonreset_upper_half_matches_input: assert property (
        @(posedge clk) disable iff (reset) (out[31:16] == in)
    );

// Outside reset, a set input MSB makes the lower 16 bits all zero.
    check_negative_input_low_half_zero: assert property (
        @(posedge clk) disable iff (reset) in[15] |-> (out[15:0] == 16'h0000)
    );

// Outside reset, a clear input MSB makes the lower 16 bits all one.
    check_nonnegative_input_low_half_ones: assert property (
        @(posedge clk) disable iff (reset) !in[15] |-> (out[15:0] == 16'hFFFF)
    );

// clk_bus directly mirrors clk_i.
    check_clk_bus_matches_clk_i: assert property (
        @(posedge clk_i) clk_bus === clk_i
    );

// clk_core is always a known binary value when sampled.
    check_clk_core_known: assert property (
        @(posedge clk_i) (clk_core === 1'b0) || (clk_core === 1'b1)
    );

// A sampled low clk_core flips high on the next clk_i edge.
    check_clk_core_low_to_high: assert property (
        @(posedge clk_i) (clk_core === 1'b0) |=> (clk_core === 1'b1)
    );

// A sampled high clk_core flips low on the next clk_i edge.
    check_clk_core_high_to_low: assert property (
        @(posedge clk_i) (clk_core === 1'b1) |=> (clk_core === 1'b0)
    );

// q repeats its sampled value every four clocks.
    check_q_four_cycle_repeat: assert property (
        @(posedge clk) 1'b1 |-> ##4 (q == $past(q, 4))
    );

// A high forces the selected AND result to zero.
    check_a_high_forces_zero: assert property (
        @(posedge clk)
        (A === 1'b1) |-> (X === 1'b0)
    );

// With A low and B known, the output is the inverse of B.
    check_a_low_inverts_b: assert property (
        @(posedge clk)
        (A === 1'b0 && !$isunknown(B)) |-> (X === ~B)
    );

// For known inputs, the implemented function is a NOR.
    check_known_inputs_match_nor: assert property (
        @(posedge clk)
        (!$isunknown({A, B})) |-> (X === ~(A | B))
    );

// Known inputs must produce a known output.
    check_known_inputs_drive_known_output: assert property (
        @(posedge clk)
        (!$isunknown({A, B})) |-> (!$isunknown(X))
    );

// A high output is only possible when both inputs are low.
    check_output_high_only_for_both_low: assert property (
        @(posedge clk)
        (X === 1'b1) |-> (A === 1'b0 && B === 1'b0)
    );

// A sampled reset cycle leaves all registered outputs at zero by the next negedge.
    check_reset_clears_outputs: assert property (
        @(negedge clk)
        rst |=> ({hsync_out, vsync_out, blnk_out, rgb_out} == 27'b0)
    );

// Without reset, the next negedge outputs are either reset-zero or the prior negedge input sample.
    check_negedge_transfer: assert property (
        @(negedge clk) disable iff (rst)
        1'b1 |=> (
            ({hsync_out, vsync_out, blnk_out, rgb_out} == 27'b0) ||
            ({hsync_out, vsync_out, blnk_out, rgb_out} ==
             $past({hsync_in, vsync_in, blnk_in, rgb_in}))
        )
    );

// BSout must match the defined S-box lookup for Bin.
    check_sbox7_lookup_table: assert property (
        @(posedge clk) BSout == sbox7_model(Bin)
    );

// When SUB is high, S must be the 4-bit difference A - B.
    check_subtract_result: assert property (
        @(posedge clk) SUB |-> (S == (A - B))
    );

// When SUB is low, S must be the 4-bit sum A + B.
    check_add_result: assert property (
        @(posedge clk) !SUB |-> (S == (A + B))
    );

// Y must match the implemented A221OI boolean function.
    check_y_matches_boolean_function: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        C1 |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & A2) |-> !Y
    );

// B1 and B2 high together force Y low.
    check_b1_b2_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (B1 & B2) |-> !Y
    );

// If all three NOR inputs are inactive, Y must be high.
    check_all_terms_inactive_give_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (!C1 && !(A1 & A2) && !(B1 & B2)) |-> Y
    );

// Y high implies none of the three NOR inputs are active.
    check_y_high_implies_all_terms_inactive: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |-> (!C1 && !(A1 & A2) && !(B1 & B2))
    );

// Y low implies at least one NOR input is active.
    check_y_low_implies_some_term_active: assert property (
        @(posedge clk) disable iff (1'b0)
        !Y |-> (C1 || (A1 & A2) || (B1 & B2))
    );

// Output is never multi-hot.
    check_out_onehot0: assert property (
        @(posedge clk) disable iff (1'b0) $onehot0(out)
    );

// Input 000 selects bit 0.
    check_decode_000: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b000) |-> (out == 8'b00000001)
    );

// Input 001 selects bit 1.
    check_decode_001: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b001) |-> (out == 8'b00000010)
    );

// Input 010 selects bit 2.
    check_decode_010: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b010) |-> (out == 8'b00000100)
    );

// Input 011 selects bit 3.
    check_decode_011: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b011) |-> (out == 8'b00001000)
    );

// Input 100 selects bit 4.
    check_decode_100: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b100) |-> (out == 8'b00010000)
    );

// Input 101 selects bit 5.
    check_decode_101: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b101) |-> (out == 8'b00100000)
    );

// Input 110 selects bit 6.
    check_decode_110: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b110) |-> (out == 8'b01000000)
    );

// Input 111 selects bit 7.
    check_decode_111: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b111) |-> (out == 8'b10000000)
    );

// Unknown input values drive the default zero output.
    check_decode_unknown_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) $isunknown(in) |-> (out == 8'b00000000)
    );

// Combinational DUT sampled on an external formal clock; no reset is present.

    // B=0 maps to E=3.
    check_map_0_to_3: assert property (
        @(posedge clk) (B == 4'h0) |-> (E == 4'h3)
    );

// B=1 maps to E=4.
    check_map_1_to_4: assert property (
        @(posedge clk) (B == 4'h1) |-> (E == 4'h4)
    );

// B=2 maps to E=5.
    check_map_2_to_5: assert property (
        @(posedge clk) (B == 4'h2) |-> (E == 4'h5)
    );

// B=3 maps to E=6.
    check_map_3_to_6: assert property (
        @(posedge clk) (B == 4'h3) |-> (E == 4'h6)
    );

// B=4 maps to E=7.
    check_map_4_to_7: assert property (
        @(posedge clk) (B == 4'h4) |-> (E == 4'h7)
    );

// B=5 maps to E=8.
    check_map_5_to_8: assert property (
        @(posedge clk) (B == 4'h5) |-> (E == 4'h8)
    );

// B=6 maps to E=9.
    check_map_6_to_9: assert property (
        @(posedge clk) (B == 4'h6) |-> (E == 4'h9)
    );

// B=7 maps to E=10.
    check_map_7_to_a: assert property (
        @(posedge clk) (B == 4'h7) |-> (E == 4'hA)
    );

// B=8 maps to E=11.
    check_map_8_to_b: assert property (
        @(posedge clk) (B == 4'h8) |-> (E == 4'hB)
    );

// B=9 maps to E=12.
    check_map_9_to_c: assert property (
        @(posedge clk) (B == 4'h9) |-> (E == 4'hC)
    );

// B=10 maps to E=13.
    check_map_a_to_d: assert property (
        @(posedge clk) (B == 4'hA) |-> (E == 4'hD)
    );

// B=11 maps to E=14.
    check_map_b_to_e: assert property (
        @(posedge clk) (B == 4'hB) |-> (E == 4'hE)
    );

// B=12 maps to E=15.
    check_map_c_to_f: assert property (
        @(posedge clk) (B == 4'hC) |-> (E == 4'hF)
    );

// B=13 maps to E=0.
    check_map_d_to_0: assert property (
        @(posedge clk) (B == 4'hD) |-> (E == 4'h0)
    );

// B=14 maps to E=1.
    check_map_e_to_1: assert property (
        @(posedge clk) (B == 4'hE) |-> (E == 4'h1)
    );

// B=15 maps to E=2.
    check_map_f_to_2: assert property (
        @(posedge clk) (B == 4'hF) |-> (E == 4'h2)
    );

// RST is the active-high synchronous reset.
    // EN controls a 4-bit sequential up-counter on CLK.

    // Reset loads the counter with zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |=> (Q == 4'b0000)
    );

// When enabled, the counter increments by one.
    check_enable_increments_q: assert property (
        @(posedge CLK) disable iff (RST)
        EN |=> (Q == ($past(Q) + 4'd1))
    );

// When not enabled, the counter holds its value.
    check_disable_holds_q: assert property (
        @(posedge CLK) disable iff (RST)
        !EN |=> (Q == $past(Q))
    );

// Counting from 4'hF wraps the 4-bit counter to zero.
    check_counter_wraps: assert property (
        @(posedge CLK) disable iff (RST)
        (EN && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// SUM is the parity of A, B, and CI.
    check_sum_matches_xor: assert property (
        @(posedge clk) disable iff (1'b0)
        SUM == (A ^ B ^ CI)
    );

// COUT is high when at least two inputs are high.
    check_cout_matches_majority: assert property (
        @(posedge clk) disable iff (1'b0)
        COUT == ((A & B) | (A & CI) | (B & CI))
    );

// The outputs match the two-bit addition of A, B, and CI.
    check_outputs_match_binary_addition: assert property (
        @(posedge clk) disable iff (1'b0)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// All-zero inputs produce zero carry and zero sum.
    check_zero_input_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A && !B && !CI) |-> (!COUT && !SUM)
    );

// Any one-hot input combination produces sum only.
    check_onehot_input_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI)) |-> (!COUT && SUM)
    );

// Any two-hot input combination produces carry only.
    check_twohot_input_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI)) |-> (COUT && !SUM)
    );

// All-one inputs produce both carry and sum.
    check_all_high_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (A && B && CI) |-> (COUT && SUM)
    );

// Y matches the OR of A_N, B_N, and the NAND of C and D.
    check_output_equation: assert property (
        @(posedge clk) Y == (A_N | B_N | ~(C & D))
    );

// A_N high directly forces Y high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B_N high directly forces Y high.
    check_b_n_high_forces_y_high: assert property (
        @(posedge clk) B_N |-> Y
    );

// C low makes the internal NAND term high, forcing Y high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> Y
    );

// D low makes the internal NAND term high, forcing Y high.
    check_d_low_forces_y_high: assert property (
        @(posedge clk) !D |-> Y
    );

// When all effective inputs are active, Y must be low.
    check_all_active_drives_y_low: assert property (
        @(posedge clk) (!A_N && !B_N && C && D) |-> !Y
    );

// Y can be low only for the single active-low minterm.
    check_y_low_only_under_active_minterm: assert property (
        @(posedge clk) !Y |-> (!A_N && !B_N && C && D)
    );

// Reset forces the counter output to zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) !RESET |-> (Q == 4'b0000)
    );

// Below 4'hF, the counter increments by one each active clock.
    check_count_increments: assert property (
        @(posedge CLK) disable iff (!RESET)
        (Q != 4'hF) |=> (Q == ($past(Q) + 4'd1))
    );

// At 4'hF, the counter wraps back to zero on the next active clock.
    check_count_wraps: assert property (
        @(posedge CLK) disable iff (!RESET)
        (Q == 4'hF) |=> (Q == 4'h0)
    );

// Y always equals the NOR of A and B.
    check_nor_equation: assert property (
        @(posedge clk) (Y === ~(A | B))
    );

// When both inputs are low, Y is high.
    check_both_low_drive_y_high: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (Y === 1'b1)
    );

// A high forces Y low.
    check_a_high_drives_y_low: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// B high forces Y low.
    check_b_high_drives_y_low: assert property (
        @(posedge clk) (B === 1'b1) |-> (Y === 1'b0)
    );

// A1, A2, and A3 high must force X high.
    check_a1_a2_a3_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// A1, A2, and A4 high must force X high.
    check_a1_a2_a4_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A4) |-> X
    );

// A1, A3, and A4 high must force X high.
    check_a1_a3_a4_sets_x: assert property (
        @(posedge clk) (A1 & A3 & A4) |-> X
    );

// A2, A3, and A4 high must force X high.
    check_a2_a3_a4_sets_x: assert property (
        @(posedge clk) (A2 & A3 & A4) |-> X
    );

// A1, A2, and B1 high must force X high.
    check_a1_a2_b1_sets_x: assert property (
        @(posedge clk) (A1 & A2 & B1) |-> X
    );

// A1, A3, and B1 high must force X high.
    check_a1_a3_b1_sets_x: assert property (
        @(posedge clk) (A1 & A3 & B1) |-> X
    );

// A1, A4, and B1 high must force X high.
    check_a1_a4_b1_sets_x: assert property (
        @(posedge clk) (A1 & A4 & B1) |-> X
    );

// A2, A3, and B1 high must force X high.
    check_a2_a3_b1_sets_x: assert property (
        @(posedge clk) (A2 & A3 & B1) |-> X
    );

// A2, A4, and B1 high must force X high.
    check_a2_a4_b1_sets_x: assert property (
        @(posedge clk) (A2 & A4 & B1) |-> X
    );

// A3, A4, and B1 high must force X high.
    check_a3_a4_b1_sets_x: assert property (
        @(posedge clk) (A3 & A4 & B1) |-> X
    );

// X must match the implemented bitwise mux equation.
    check_mux_equation: assert property (
        @(posedge clk) X === ((sel & B) | ((~sel) & A))
    );

// With sel low and A known, X follows A.
    check_sel_low_selects_a: assert property (
        @(posedge clk) (sel === 1'b0 && !$isunknown(A)) |-> (X === A)
    );

// With sel high and B known, X follows B.
    check_sel_high_selects_b: assert property (
        @(posedge clk) (sel === 1'b1 && !$isunknown(B)) |-> (X === B)
    );

// With sel low and A unknown, X becomes unknown.
    check_sel_low_unknown_a_propagates: assert property (
        @(posedge clk) (sel === 1'b0 && $isunknown(A)) |-> $isunknown(X)
    );

// With sel high and B unknown, X becomes unknown.
    check_sel_high_unknown_b_propagates: assert property (
        @(posedge clk) (sel === 1'b1 && $isunknown(B)) |-> $isunknown(X)
    );

// If both data inputs are 0, X is forced low.
    check_both_zero_force_zero: assert property (
        @(posedge clk) (A === 1'b0 && B === 1'b0) |-> (X === 1'b0)
    );

// Load copies data_in into the register on the next clock.
    check_load_copies_input: assert property (
        @(posedge clk)
        load |=> (data_out == $past(data_in))
    );

// With load low and control high, the register rotates left by one bit.
    check_shift_left_rotate: assert property (
        @(posedge clk)
        (!load && control) |=> (data_out == {$past(data_out[6:0]), $past(data_out[7])})
    );

// With load low and control low, the register rotates right by one bit.
    check_shift_right_rotate: assert property (
        @(posedge clk)
        (!load && !control) |=> (data_out == {$past(data_out[0]), $past(data_out[7:1])})
    );

// Every clock follows the RTL next-state update function.
    check_next_state_function: assert property (
        @(posedge clk)
        1'b1 |=> (
            data_out == (
                $past(load) ? $past(data_in) :
                ($past(control) ? {$past(data_out[6:0]), $past(data_out[7])}
                                : {$past(data_out[0]), $past(data_out[7:1])})
            )
        )
    );

// External sampling clock; DUT is purely combinational and has no reset.

    // X must match the exact RTL combinational equation.
    check_x_matches_equation: assert property (
        @(posedge clk)
        X === (A1 & A2 & ~B1_N & ~VPWR & ~VGND & ((VPB & ~VNB) | (~VPB & VNB)))
    );

// All required true conditions must drive X high.
    check_full_enable_drives_x_high: assert property (
        @(posedge clk)
        (A1 === 1'b1 && A2 === 1'b1 && B1_N === 1'b0 && VPWR === 1'b0 && VGND === 1'b0 &&
         (((VPB === 1'b1) && (VNB === 1'b0)) || ((VPB === 1'b0) && (VNB === 1'b1))))
        |-> (X === 1'b1)
    );

// A1 low forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk)
        (A1 === 1'b0) |-> (X === 1'b0)
    );

// A2 low forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk)
        (A2 === 1'b0) |-> (X === 1'b0)
    );

// B1_N high forces X low.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk)
        (B1_N === 1'b1) |-> (X === 1'b0)
    );

// VPWR high forces X low.
    check_vpwr_high_forces_x_low: assert property (
        @(posedge clk)
        (VPWR === 1'b1) |-> (X === 1'b0)
    );

// VGND high forces X low.
    check_vgnd_high_forces_x_low: assert property (
        @(posedge clk)
        (VGND === 1'b1) |-> (X === 1'b0)
    );

// Equal body-bias pins force X low.
    check_equal_body_pins_force_x_low: assert property (
        @(posedge clk)
        (((VPB === 1'b0) && (VNB === 1'b0)) || ((VPB === 1'b1) && (VNB === 1'b1)))
        |-> (X === 1'b0)
    );

// X high implies every enabling input condition is satisfied.
    check_x_high_implies_required_conditions: assert property (
        @(posedge clk)
        (X === 1'b1)
        |-> (A1 === 1'b1 && A2 === 1'b1 && B1_N === 1'b0 && VPWR === 1'b0 && VGND === 1'b0 &&
             (((VPB === 1'b1) && (VNB === 1'b0)) || ((VPB === 1'b0) && (VNB === 1'b1))))
    );

// adc_clk mirrors rx_clk at the sampling edge.
    check_adc_clk_mirrors_rx_clk: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_clk == rx_clk)
    );

// adc_or_a is tied low.
    check_adc_or_a_tied_low: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_or_a == 1'b0)
    );

// adc_or_b is tied low.
    check_adc_or_b_tied_low: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_or_b == 1'b0)
    );

// adc_data_a[63:48] matches the s3 byte mapping.
    check_adc_data_a_s3_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[63:48] == {rx_data[31:24], rx_data[63:56]})
    );

// adc_data_a[47:32] matches the s2 byte mapping.
    check_adc_data_a_s2_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[47:32] == {rx_data[23:16], rx_data[55:48]})
    );

// adc_data_a[31:16] matches the s1 byte mapping.
    check_adc_data_a_s1_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[31:16] == {rx_data[15:8], rx_data[47:40]})
    );

// adc_data_a[15:0] matches the s0 byte mapping.
    check_adc_data_a_s0_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_a[15:0] == {rx_data[7:0], rx_data[39:32]})
    );

// adc_data_b[63:48] matches the s3 byte mapping.
    check_adc_data_b_s3_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[63:48] == {rx_data[95:88], rx_data[127:120]})
    );

// adc_data_b[47:32] matches the s2 byte mapping.
    check_adc_data_b_s2_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[47:32] == {rx_data[87:80], rx_data[119:112]})
    );

// adc_data_b[31:16] matches the s1 byte mapping.
    check_adc_data_b_s1_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[31:16] == {rx_data[79:72], rx_data[111:104]})
    );

// adc_data_b[15:0] matches the s0 byte mapping.
    check_adc_data_b_s0_mapping: assert property (
        @(posedge rx_clk) disable iff (adc_rst)
        (adc_data_b[15:0] == {rx_data[71:64], rx_data[103:96]})
    );

// adc_status clears one cycle after reset is sampled high.
    check_adc_status_clears_after_reset: assert property (
        @(posedge rx_clk)
        adc_rst |=> (adc_status == 1'b0)
    );

// adc_status sets one cycle after reset is sampled low.
    check_adc_status_sets_after_nonreset: assert property (
        @(posedge rx_clk)
        !adc_rst |=> (adc_status == 1'b1)
    );

// Y must equal the AND of all four data inputs.
    check_output_equation: assert property (
        @(posedge clk) Y == (A & B & C & D)
    );

// All four HIGH inputs must drive Y HIGH.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Y
    );

// A HIGH Y requires all four data inputs to be HIGH.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A & B & C & D)
    );

// Any LOW data input must force Y LOW.
    check_any_low_input_forces_output_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !Y
    );

// X equals A sampled four clocks earlier.
    check_four_cycle_delay: assert property (
        @(posedge clk) 1'b1 |-> ##4 (X == $past(A, 4))
    );

// A high sample must appear at X four clocks later.
    check_high_propagation: assert property (
        @(posedge clk) A |-> ##4 X
    );

// A low sample must appear at X four clocks later.
    check_low_propagation: assert property (
        @(posedge clk) !A |-> ##4 !X
    );

// S[0] matches the first sum assignment.
    check_sum_bit0_equation: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ C_in)
    );

// S[1] matches the second sum assignment.
    check_sum_bit1_equation: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ C_in)
    );

// S[2] matches the third sum assignment.
    check_sum_bit2_equation: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ C_in)
    );

// S[3] matches the fourth sum assignment.
    check_sum_bit3_equation: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ C_in)
    );

// The full sum bus matches the per-bit XOR structure.
    check_sum_vector_equation: assert property (
        @(posedge clk) S == ((A ^ B) ^ {4{C_in}})
    );

// With C_in low, S reduces to A XOR B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) (C_in == 1'b0) |-> (S == (A ^ B))
    );

// With C_in high, S is the inverse of A XOR B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) (C_in == 1'b1) |-> (S == ~(A ^ B))
    );

// C_out matches the RTL carry expression.
    check_cout_equation: assert property (
        @(posedge clk) C_out == ((((A[0] & B[0]) & (A[1] ^ B[1])) | (A[1] & B[1])))
    );

// A generate on bit 1 forces C_out high.
    check_cout_from_bit1_generate: assert property (
        @(posedge clk) (A[1] & B[1]) |-> (C_out == 1'b1)
    );

// The lower carry-propagate term forces C_out high.
    check_cout_from_low_propagate: assert property (
        @(posedge clk) ((A[0] & B[0]) & (A[1] ^ B[1])) |-> (C_out == 1'b1)
    );

// If neither carry term is present, C_out stays low.
    check_cout_low_when_no_carry_term: assert property (
        @(posedge clk) (!(A[1] & B[1]) && !((A[0] & B[0]) & (A[1] ^ B[1]))) |-> (C_out == 1'b0)
    );

// BCD 0 maps to binary 0.
    check_bcd_0_maps_to_0: assert property (
        @(posedge clk) (bcd == 4'd0) |-> (bin == 8'd0)
    );

// BCD 1 maps to binary 1.
    check_bcd_1_maps_to_1: assert property (
        @(posedge clk) (bcd == 4'd1) |-> (bin == 8'd1)
    );

// BCD 2 maps to binary 2.
    check_bcd_2_maps_to_2: assert property (
        @(posedge clk) (bcd == 4'd2) |-> (bin == 8'd2)
    );

// BCD 3 maps to binary 3.
    check_bcd_3_maps_to_3: assert property (
        @(posedge clk) (bcd == 4'd3) |-> (bin == 8'd3)
    );

// BCD 4 maps to binary 4.
    check_bcd_4_maps_to_4: assert property (
        @(posedge clk) (bcd == 4'd4) |-> (bin == 8'd4)
    );

// BCD 5 maps to binary 5.
    check_bcd_5_maps_to_5: assert property (
        @(posedge clk) (bcd == 4'd5) |-> (bin == 8'd5)
    );

// BCD 6 maps to binary 6.
    check_bcd_6_maps_to_6: assert property (
        @(posedge clk) (bcd == 4'd6) |-> (bin == 8'd6)
    );

// BCD 7 maps to binary 7.
    check_bcd_7_maps_to_7: assert property (
        @(posedge clk) (bcd == 4'd7) |-> (bin == 8'd7)
    );

// BCD 8 maps to binary 8.
    check_bcd_8_maps_to_8: assert property (
        @(posedge clk) (bcd == 4'd8) |-> (bin == 8'd8)
    );

// BCD 9 maps to binary 9.
    check_bcd_9_maps_to_9: assert property (
        @(posedge clk) (bcd == 4'd9) |-> (bin == 8'd9)
    );

// Invalid BCD values map to the error code 8'hFF.
    check_invalid_bcd_maps_to_error: assert property (
        @(posedge clk) (bcd >= 4'd10) |-> (bin == 8'hFF)
    );

// The error code is only produced for invalid BCD values.
    check_error_code_only_for_invalid_bcd: assert property (
        @(posedge clk) (bin == 8'hFF) |-> (bcd >= 4'd10)
    );

// Sample the combinational DUT on an external verification clock.

    // Output must match the four-input AND expression.
    check_out_matches_and: assert property (
        @(posedge clk) out === (a & b & c & d)
    );

// All inputs high drives the output high.
    check_all_high_drives_out_high: assert property (
        @(posedge clk) ((a === 1'b1) && (b === 1'b1) && (c === 1'b1) && (d === 1'b1)) |-> (out === 1'b1)
    );

// A high output requires all inputs high.
    check_out_high_requires_all_high: assert property (
        @(posedge clk) (out === 1'b1) |-> ((a === 1'b1) && (b === 1'b1) && (c === 1'b1) && (d === 1'b1))
    );

// Any low input forces the output low.
    check_any_low_forces_out_low: assert property (
        @(posedge clk) ((a === 1'b0) || (b === 1'b0) || (c === 1'b0) || (d === 1'b0)) |-> (out === 1'b0)
    );

// A sampled reset cycle leaves the count at zero on the next sampled clock.
    reset_leaves_count_zero_next_cycle: assert property (
        @(posedge clk) !rst |=> (count == 4'b0000)
    );

// When reset is released, count is still zero before counting resumes.
    reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff (!rst) $rose(rst) |-> (count == 4'b0000)
    );

// With up_down high, count increments by one on the next clock.
    count_increments_when_up: assert property (
        @(posedge clk) disable iff (!rst) up_down |=> (count == ($past(count) + 4'b0001))
    );

// With up_down low, count decrements by one on the next clock.
    count_decrements_when_down: assert property (
        @(posedge clk) disable iff (!rst) !up_down |=> (count == ($past(count) - 4'b0001))
    );

// Counting up wraps from 4'hF back to 4'h0.
    up_wraps_from_f_to_zero: assert property (
        @(posedge clk) disable iff (!rst) up_down && (count == 4'hF) |=> (count == 4'h0)
    );

// Counting down wraps from 4'h0 back to 4'hF.
    down_wraps_from_zero_to_f: assert property (
        @(posedge clk) disable iff (!rst) !up_down && (count == 4'h0) |=> (count == 4'hF)
    );

// Output matches the decoder equation.
    check_decode_equation: assert property (
        @(posedge clk) out == (8'b00000001 << in)
    );

// Decoder output is always one-hot.
    check_out_is_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// Input 0 selects output bit 0.
    check_in_0_decodes_bit0: assert property (
        @(posedge clk) (in == 3'd0) |-> (out == 8'b00000001)
    );

// Input 1 selects output bit 1.
    check_in_1_decodes_bit1: assert property (
        @(posedge clk) (in == 3'd1) |-> (out == 8'b00000010)
    );

// Input 2 selects output bit 2.
    check_in_2_decodes_bit2: assert property (
        @(posedge clk) (in == 3'd2) |-> (out == 8'b00000100)
    );

// Input 3 selects output bit 3.
    check_in_3_decodes_bit3: assert property (
        @(posedge clk) (in == 3'd3) |-> (out == 8'b00001000)
    );

// Input 4 selects output bit 4.
    check_in_4_decodes_bit4: assert property (
        @(posedge clk) (in == 3'd4) |-> (out == 8'b00010000)
    );

// Input 5 selects output bit 5.
    check_in_5_decodes_bit5: assert property (
        @(posedge clk) (in == 3'd5) |-> (out == 8'b00100000)
    );

// Input 6 selects output bit 6.
    check_in_6_decodes_bit6: assert property (
        @(posedge clk) (in == 3'd6) |-> (out == 8'b01000000)
    );

// Input 7 selects output bit 7.
    check_in_7_decodes_bit7: assert property (
        @(posedge clk) (in == 3'd7) |-> (out == 8'b10000000)
    );

// data_out must show the shifted register value each cycle.
    check_data_out_shift_update: assert property (
        @(posedge clk) 1'b1 |=> data_out == {$past(data_out[2:0]), $past(data_in[0])}
    );

// data_out[0] must load the previous data_in[0].
    check_data_out_bit0_loads_data_in0: assert property (
        @(posedge clk) 1'b1 |=> data_out[0] == $past(data_in[0])
    );

// data_out[1] must receive the previous data_out[0].
    check_data_out_bit1_shifts_from_bit0: assert property (
        @(posedge clk) 1'b1 |=> data_out[1] == $past(data_out[0])
    );

// data_out[2] must receive the previous data_out[1].
    check_data_out_bit2_shifts_from_bit1: assert property (
        @(posedge clk) 1'b1 |=> data_out[2] == $past(data_out[1])
    );

// data_out[3] must receive the previous data_out[2].
    check_data_out_bit3_shifts_from_bit2: assert property (
        @(posedge clk) 1'b1 |=> data_out[3] == $past(data_out[2])
    );

// eq must match the equality comparison of a and b.
    check_eq_matches_comparison: assert property (
        @(posedge clk) eq == (a == b)
    );

// gt must match the greater-than comparison of a and b.
    check_gt_matches_comparison: assert property (
        @(posedge clk) gt == (a > b)
    );

// eq and gt cannot both be asserted at the same time.
    check_eq_gt_mutex: assert property (
        @(posedge clk) !(eq && gt)
    );

// When a is less than b, neither eq nor gt may be asserted.
    check_lt_case_outputs: assert property (
        @(posedge clk) (a < b) |-> (!eq && !gt)
    );

// If eq is asserted, the inputs must be equal.
    check_eq_implies_equal_inputs: assert property (
        @(posedge clk) eq |-> (a == b)
    );

// If gt is asserted, a must be greater than b.
    check_gt_implies_input_order: assert property (
        @(posedge clk) gt |-> (a > b)
    );

// 000 converts to 0000.
    check_map_000_to_0000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 4'b0000)
    );

// 001 and 101 convert to 0001.
    check_map_001_101_to_0001: assert property (
        @(posedge clk) ((in == 3'b001) || (in == 3'b101)) |-> (out == 4'b0001)
    );

// 010 and 110 convert to 0010.
    check_map_010_110_to_0010: assert property (
        @(posedge clk) ((in == 3'b010) || (in == 3'b110)) |-> (out == 4'b0010)
    );

// 011 and 111 convert to 0100.
    check_map_011_111_to_0100: assert property (
        @(posedge clk) ((in == 3'b011) || (in == 3'b111)) |-> (out == 4'b0100)
    );

// 100 converts to 1000.
    check_map_100_to_1000: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 4'b1000)
    );

// 0000 can only come from 000.
    check_rev_0000_from_000: assert property (
        @(posedge clk) (out == 4'b0000) |-> (in == 3'b000)
    );

// 0001 can only come from 001 or 101.
    check_rev_0001_from_001_101: assert property (
        @(posedge clk) (out == 4'b0001) |-> ((in == 3'b001) || (in == 3'b101))
    );

// 0010 can only come from 010 or 110.
    check_rev_0010_from_010_110: assert property (
        @(posedge clk) (out == 4'b0010) |-> ((in == 3'b010) || (in == 3'b110))
    );

// 0100 can only come from 011 or 111.
    check_rev_0100_from_011_111: assert property (
        @(posedge clk) (out == 4'b0100) |-> ((in == 3'b011) || (in == 3'b111))
    );

// 1000 can only come from 100.
    check_rev_1000_from_100: assert property (
        @(posedge clk) (out == 4'b1000) |-> (in == 3'b100)
    );

// When E is low, the output must be low.
    check_output_low_when_e_low: assert property (
        @(posedge CK) !E |-> !ECK
    );

// A sampled low E clears the stored state by the next clock sample.
    check_clear_visible_next_clock: assert property (
        @(posedge CK) !E |=> !ECK
    );

// Sampling D=0 with SE high forces the next sampled output low.
    check_capture_zero_drives_low: assert property (
        @(posedge CK) disable iff (!E) (SE && !D) |=> !ECK
    );

// In hold mode, a sampled low output stays low on the next clock sample.
    check_hold_preserves_low: assert property (
        @(posedge CK) disable iff (!E) (!SE && !ECK) |=> !ECK
    );

// Concatenated carry and sum match 5-bit addition.
    check_total_sum: assert property (
        @(posedge clk)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0, cin})
    );

// Bit 0 sum matches the full-adder XOR equation.
    check_sum0_equation: assert property (
        @(posedge clk)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry generated by bit 0.
    check_sum1_equation: assert property (
        @(posedge clk)
        sum[1] == (a[1] ^ b[1] ^
                   ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

// With b at zero, the adder reduces to a plus carry-in.
    check_b_zero_increment: assert property (
        @(posedge clk)
        (b == 4'h0) |-> ({cout, sum} == ({1'b0, a} + {4'b0, cin}))
    );

// With a at zero, the adder reduces to b plus carry-in.
    check_a_zero_increment: assert property (
        @(posedge clk)
        (a == 4'h0) |-> ({cout, sum} == ({1'b0, b} + {4'b0, cin}))
    );

// All-zero inputs produce an all-zero result.
    check_zero_result: assert property (
        @(posedge clk)
        (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> ({cout, sum} == 5'h00)
    );

// 0xF plus carry-in overflows to zero with carry out.
    check_boundary_ff_plus_one: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'h0 && cin == 1'b1) |-> ({cout, sum} == 5'h10)
    );

// Adding 0x8 and 0x8 generates a carry with zero sum.
    check_msb_carry_case: assert property (
        @(posedge clk)
        (a == 4'h8 && b == 4'h8 && cin == 1'b0) |-> ({cout, sum} == 5'h10)
    );

// Maximum operands with carry-in produce 0x1F.
    check_max_plus_max_plus_cin: assert property (
        @(posedge clk)
        (a == 4'hF && b == 4'hF && cin == 1'b1) |-> ({cout, sum} == 5'h1F)
    );

// Reset clears working and counter.
    check_reset_clears_state: assert property (
        @(posedge iCLOCK) !inRESET |-> (oWORKING == 1'b0 && oCOUNTER == 64'h0)
    );

// A configuration write updates working from iCONF_ENA.
    check_conf_write_updates_working: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        iCONF_WRITE |=> (oWORKING == $past(iCONF_ENA))
    );

// Without a configuration write, working holds its value.
    check_working_holds_without_conf_write: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        !iCONF_WRITE |=> (oWORKING == $past(oWORKING))
    );

// When working is set, the counter increments by one.
    check_working_increments_counter: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        oWORKING |=> (oCOUNTER == ($past(oCOUNTER) + 64'd1))
    );

// When stopped and not writing, the counter holds.
    check_stopped_no_write_holds_counter: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && !iCOUNT_WRITE) |=> (oCOUNTER == $past(oCOUNTER))
    );

// When stopped and low word is unmasked, bits [31:0] load from iCOUNT_COUNTER.
    check_stopped_write_loads_low_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && !inCOUNT_DQM[0]) |=> (oCOUNTER[31:0] == $past(iCOUNT_COUNTER[31:0]))
    );

// When stopped and low word is masked, bits [31:0] hold.
    check_stopped_write_masks_low_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && inCOUNT_DQM[0]) |=> (oCOUNTER[31:0] == $past(oCOUNTER[31:0]))
    );

// When stopped and high word is unmasked, bits [63:32] load from iCOUNT_COUNTER.
    check_stopped_write_loads_high_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && !inCOUNT_DQM[1]) |=> (oCOUNTER[63:32] == $past(iCOUNT_COUNTER[63:32]))
    );

// When stopped and high word is masked, bits [63:32] hold.
    check_stopped_write_masks_high_half: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!oWORKING && iCOUNT_WRITE && inCOUNT_DQM[1]) |=> (oCOUNTER[63:32] == $past(oCOUNTER[63:32]))
    );

// TE forces ENCLK high.
    check_enclk_high_when_te: assert property (
        @(posedge CLK) TE |=> (ENCLK == 1'b1)
    );

// With both controls low, ENCLK is driven low.
    check_enclk_low_when_disabled: assert property (
        @(posedge CLK) (!TE && !EN) |=> (ENCLK == 1'b0)
    );

// ALUOp 00 selects the add operation.
    check_aluop_00_maps_to_add: assert property (
        @(posedge clk) (ALUOp == 2'b00) |-> (ALUOperation == ALU_add)
    );

// ALUOp 01 selects the subtract operation.
    check_aluop_01_maps_to_sub: assert property (
        @(posedge clk) (ALUOp == 2'b01) |-> (ALUOperation == ALU_sub)
    );

// R-type add funct selects the add operation.
    check_rtype_add_maps_to_add: assert property (
        @(posedge clk) ((ALUOp == 2'b10) && (Funct == F_add)) |-> (ALUOperation == ALU_add)
    );

// R-type sub funct selects the subtract operation.
    check_rtype_sub_maps_to_sub: assert property (
        @(posedge clk) ((ALUOp == 2'b10) && (Funct == F_sub)) |-> (ALUOperation == ALU_sub)
    );

// R-type and funct selects the and operation.
    check_rtype_and_maps_to_and: assert property (
        @(posedge clk) ((ALUOp == 2'b10) && (Funct == F_and)) |-> (ALUOperation == ALU_and)
    );

// R-type or funct selects the or operation.
    check_rtype_or_maps_to_or: assert property (
        @(posedge clk) ((ALUOp == 2'b10) && (Funct == F_or)) |-> (ALUOperation == ALU_or)
    );

// R-type slt funct selects the set-less-than operation.
    check_rtype_slt_maps_to_slt: assert property (
        @(posedge clk) ((ALUOp == 2'b10) && (Funct == F_slt)) |-> (ALUOperation == ALU_slt)
    );

// A sampled low reset clears OUT by the next clock.
    check_reset_clears_out: assert property (
        @(posedge CLK) (!RST) |=> (OUT == 4'd0)
    );

// On reset deassertion, the sampled counter value starts from zero.
    check_release_reset_starts_from_zero: assert property (
        @(posedge CLK) $rose(RST) |-> (OUT == 4'd0)
    );

// When enabled, the counter increments by one on the next clock.
    check_increment_when_enabled: assert property (
        @(posedge CLK) disable iff (!RST)
        EN |=> (OUT == ($past(OUT) + 4'd1))
    );

// When disabled, the counter holds its value on the next clock.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!RST)
        !EN |=> (OUT == $past(OUT))
    );

// When enabled at 15, the 4-bit counter wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge CLK) disable iff (!RST)
        (EN && (OUT == 4'hF)) |=> (OUT == 4'h0)
    );

// 000 maps to 000.
    check_b000_maps_to_g000: assert property (
        @(posedge clk) (B == 3'b000) |-> (G == 3'b000)
    );

// 001 maps to 001.
    check_b001_maps_to_g001: assert property (
        @(posedge clk) (B == 3'b001) |-> (G == 3'b001)
    );

// 010 maps to 011.
    check_b010_maps_to_g011: assert property (
        @(posedge clk) (B == 3'b010) |-> (G == 3'b011)
    );

// 011 maps to 010.
    check_b011_maps_to_g010: assert property (
        @(posedge clk) (B == 3'b011) |-> (G == 3'b010)
    );

// 100 maps to 110.
    check_b100_maps_to_g110: assert property (
        @(posedge clk) (B == 3'b100) |-> (G == 3'b110)
    );

// 101 maps to 111.
    check_b101_maps_to_g111: assert property (
        @(posedge clk) (B == 3'b101) |-> (G == 3'b111)
    );

// 110 maps to 101.
    check_b110_maps_to_g101: assert property (
        @(posedge clk) (B == 3'b110) |-> (G == 3'b101)
    );

// 111 maps to 100.
    check_b111_maps_to_g100: assert property (
        @(posedge clk) (B == 3'b111) |-> (G == 3'b100)
    );

// Output equals the three-input XOR of A, B, and C.
    check_x_matches_xor3_function: assert property (
        @(posedge clk) X === (A ^ B ^ C)
    );

// When A and B are equal known bits, output matches C.
    check_ab_equal_output_matches_c: assert property (
        @(posedge clk)
        (((A === 1'b0) && (B === 1'b0)) || ((A === 1'b1) && (B === 1'b1)))
        |-> (X === C)
    );

// When A and B differ as known bits, output inverts C.
    check_ab_different_output_inverts_c: assert property (
        @(posedge clk)
        (((A === 1'b0) && (B === 1'b1)) || ((A === 1'b1) && (B === 1'b0)))
        |-> (X === ~C)
    );

// When B and C are equal known bits, output matches A.
    check_bc_equal_output_matches_a: assert property (
        @(posedge clk)
        (((B === 1'b0) && (C === 1'b0)) || ((B === 1'b1) && (C === 1'b1)))
        |-> (X === A)
    );

// When B and C differ as known bits, output inverts A.
    check_bc_different_output_inverts_a: assert property (
        @(posedge clk)
        (((B === 1'b0) && (C === 1'b1)) || ((B === 1'b1) && (C === 1'b0)))
        |-> (X === ~A)
    );

// When A and C are equal known bits, output matches B.
    check_ac_equal_output_matches_b: assert property (
        @(posedge clk)
        (((A === 1'b0) && (C === 1'b0)) || ((A === 1'b1) && (C === 1'b1)))
        |-> (X === B)
    );

// When A and C differ as known bits, output inverts B.
    check_ac_different_output_inverts_b: assert property (
        @(posedge clk)
        (((A === 1'b0) && (C === 1'b1)) || ((A === 1'b1) && (C === 1'b0)))
        |-> (X === ~B)
    );

// Output matches the direct ternary addition branch.
    check_sum_matches_no_sign_ext: assert property (
        @(posedge clk) o == (a + b + c)
    );

// Zero inputs produce a zero output.
    check_zero_output_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0) && (c == '0)) |-> (o == '0)
    );

// With only a present, o is zero-extended a.
    check_a_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((b == '0) && (c == '0)) |-> (o == {{2{1'b0}}, a})
    );

// With only b present, o is zero-extended b.
    check_b_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (c == '0)) |-> (o == {{2{1'b0}}, b})
    );

// With only c present, o is zero-extended c.
    check_c_passthrough_no_sign_ext: assert property (
        @(posedge clk) ((a == '0) && (b == '0)) |-> (o == {{2{1'b0}}, c})
    );

// Reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// Enable increments the counter by one modulo 16.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

// Reset has priority even if enable is also high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 4'b0000)
    );

// Combined output must equal the 5-bit sum of A, B, and Cin.
    check_combined_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// The least-significant sum bit must match A[0] xor B[0] xor Cin.
    check_lsb_xor_behavior: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// With both operands zero, the output must only reflect Cin.
    check_zero_operands_cin_only: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |-> ({Cout, Sum} == {4'b0000, Cin})
    );

// With A zero and Cin low, the output must pass B through with no carry.
    check_a_zero_b_passthrough: assert property (
        @(posedge clk) (A == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, B})
    );

// With B zero and Cin low, the output must pass A through with no carry.
    check_b_zero_a_passthrough: assert property (
        @(posedge clk) (B == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, A})
    );

// Carry-out must be low when the computed sum fits in 4 bits.
    check_no_overflow_no_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |-> (Cout == 1'b0)
    );

// Carry-out must be high when the computed sum exceeds 4 bits.
    check_overflow_sets_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> (Cout == 1'b1)
    );

// The maximum input combination must produce the maximum 5-bit result.
    check_maximum_input_sum: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> ({Cout, Sum} == 5'h1F)
    );

// Output matches the implemented OR-of-ANDs function.
    check_out_matches_boolean_function: assert property (
        @(posedge clk) out == ((in1 & in2) | (in3 & in4) | in5)
    );

// Fifth input directly forces the output high.
    check_in5_forces_out_high: assert property (
        @(posedge clk) in5 |-> out
    );

// First input pair forces the output high when both are high.
    check_first_pair_forces_out_high: assert property (
        @(posedge clk) (in1 & in2) |-> out
    );

// Second input pair forces the output high when both are high.
    check_second_pair_forces_out_high: assert property (
        @(posedge clk) (in3 & in4) |-> out
    );

// A high output must come from at least one implemented source term.
    check_out_high_has_active_source: assert property (
        @(posedge clk) out |-> ((in1 & in2) | (in3 & in4) | in5)
    );

// Output stays low when all three OR terms are low.
    check_out_low_when_all_terms_low: assert property (
        @(posedge clk) ((!(in1 & in2)) && (!(in3 & in4)) && (!in5)) |-> (!out)
    );

// Clock is posedge C; this RTL has no reset.
    // With CE high and R low, Q loads D1.
    check_capture_d1: assert property (
        @(posedge C) disable iff (1'b0)
        (CE === 1'b1 && R === 1'b0) |=> (Q === $past(D1))
    );

// With CE high and R not low, Q loads D2.
    check_capture_d2: assert property (
        @(posedge C) disable iff (1'b0)
        (CE === 1'b1 && R !== 1'b0) |=> (Q === $past(D2))
    );

// With CE not high, Q holds its previous value.
    check_hold_when_ce_not_high: assert property (
        @(posedge C) disable iff (1'b0)
        (CE !== 1'b1) |=> (Q === $past(Q))
    );

// c_out must equal group generate OR propagated c_in.
    check_cout_group_relation: assert property (
        @(posedge clk)
        c_out == (G | (P & c_in))
    );

// A sampled low reset leaves every stage cleared by the next clock.
    check_reset_clears_all_stages: assert property (
        @(posedge clk)
        !reset |=> ((q1 == 8'h00) && (q2 == 8'h00) && (q3 == 8'h00) && (q == 8'h00))
    );

// On the first clock after reset deassertion, all stages are still zero.
    check_release_all_stages_zero: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |-> ((q1 == 8'h00) && (q2 == 8'h00) && (q3 == 8'h00) && (q == 8'h00))
    );

// One clock after reset deassertion, the tail stages remain zero.
    check_release_second_clock_zero_tail: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |=> ((q2 == 8'h00) && (q3 == 8'h00) && (q == 8'h00))
    );

// Two clocks after reset deassertion, q3 and q remain zero.
    check_release_third_clock_zero_tail: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |=> ##1 ((q3 == 8'h00) && (q == 8'h00))
    );

// Three clocks after reset deassertion, q is still zero.
    check_release_fourth_clock_q_zero: assert property (
        @(posedge clk) disable iff (!reset)
        $rose(reset) |=> ##2 (q == 8'h00)
    );

// A zero input sample reaches q1 on the next clock.
    check_zero_input_captured_into_q1: assert property (
        @(posedge clk) disable iff (!reset)
        (d == 8'h00) |=> (q1 == 8'h00)
    );

// A zero in q1 shifts into q2 on the next clock.
    check_zero_q1_shifts_into_q2: assert property (
        @(posedge clk) disable iff (!reset)
        (q1 == 8'h00) |=> (q2 == 8'h00)
    );

// A zero in q2 shifts into q3 on the next clock.
    check_zero_q2_shifts_into_q3: assert property (
        @(posedge clk) disable iff (!reset)
        (q2 == 8'h00) |=> (q3 == 8'h00)
    );

// A zero in q3 shifts into q on the next clock.
    check_zero_q3_shifts_into_q: assert property (
        @(posedge clk) disable iff (!reset)
        (q3 == 8'h00) |=> (q == 8'h00)
    );

// Four consecutive zero input samples force a zero at the output.
    check_four_zero_inputs_produce_zero_q: assert property (
        @(posedge clk) disable iff (!reset)
        ((d == 8'h00) ##1 (d == 8'h00) ##1 (d == 8'h00) ##1 (d == 8'h00)) |=> (q == 8'h00)
    );

// arbpc0 grant output is the inverse of the active-low bufp1 grant input.
    check_arbpc0_grant_inversion: assert property (
        @(posedge clk) arbpc0_pcxdp_grant_pa == ~arbpc0_pcxdp_grant_bufp1_pa_l
    );

// arbpc0 q0 hold output is the inverse of the bufp1 q0 hold input.
    check_arbpc0_q0_hold_inversion: assert property (
        @(posedge clk) arbpc0_pcxdp_q0_hold_pa_l == ~arbpc0_pcxdp_q0_hold_bufp1_pa
    );

// arbpc0 qsel0 output is the inverse of the active-low bufp1 qsel0 input.
    check_arbpc0_qsel0_inversion: assert property (
        @(posedge clk) arbpc0_pcxdp_qsel0_pa == ~arbpc0_pcxdp_qsel0_bufp1_pa_l
    );

// arbpc0 qsel1 output is the inverse of the bufp1 qsel1 input.
    check_arbpc0_qsel1_inversion: assert property (
        @(posedge clk) arbpc0_pcxdp_qsel1_pa_l == ~arbpc0_pcxdp_qsel1_bufp1_pa
    );

// arbpc0 shift output is the inverse of the active-low bufp1 shift input.
    check_arbpc0_shift_inversion: assert property (
        @(posedge clk) arbpc0_pcxdp_shift_px == ~arbpc0_pcxdp_shift_bufp1_px_l
    );

// arbpc2 grant output is the inverse of the active-low bufp1 grant input.
    check_arbpc2_grant_inversion: assert property (
        @(posedge clk) arbpc2_pcxdp_grant_pa == ~arbpc2_pcxdp_grant_bufp1_pa_l
    );

// arbpc2 q0 hold output is the inverse of the bufp1 q0 hold input.
    check_arbpc2_q0_hold_inversion: assert property (
        @(posedge clk) arbpc2_pcxdp_q0_hold_pa_l == ~arbpc2_pcxdp_q0_hold_bufp1_pa
    );

// arbpc2 qsel0 output is the inverse of the active-low bufp1 qsel0 input.
    check_arbpc2_qsel0_inversion: assert property (
        @(posedge clk) arbpc2_pcxdp_qsel0_pa == ~arbpc2_pcxdp_qsel0_bufp1_pa_l
    );

// arbpc2 qsel1 output is the inverse of the bufp1 qsel1 input.
    check_arbpc2_qsel1_inversion: assert property (
        @(posedge clk) arbpc2_pcxdp_qsel1_pa_l == ~arbpc2_pcxdp_qsel1_bufp1_pa
    );

// arbpc2 shift output is the inverse of the active-low bufp1 shift input.
    check_arbpc2_shift_inversion: assert property (
        @(posedge clk) arbpc2_pcxdp_shift_px == ~arbpc2_pcxdp_shift_bufp1_px_l
    );

// The stall output is a direct pass-through of the stall input.
    check_stall_passthrough: assert property (
        @(posedge clk) scache0_pcx_stall_bufp0even_pq == scache0_pcx_stall_pq
    );

// Resistive mode loads the ADC value to full scale.
    check_adc_value_loads_full_scale_in_resistive: assert property (
        @(posedge touch_signal) sensor_type == 1 |=> adc_value == 8'hFF
    );

// Resistive mode drives touch_detected from the prior ADC comparison.
    check_touch_detected_from_adc_threshold: assert property (
        @(posedge touch_signal) sensor_type == 1 |=> touch_detected == ($past(adc_value) > threshold)
    );

// Unsupported sensor_type values leave touch_detected unchanged.
    check_touch_detected_holds_for_invalid_mode: assert property (
        @(posedge touch_signal) (sensor_type != 0) && (sensor_type != 1) |=> touch_detected == $past(touch_detected)
    );

// Reset low forces the counter output to 00.
    check_reset_forces_zero: assert property (
        @(posedge CLK) !RESET_B |-> (Q == 2'b00)
    );

// A sampled reset keeps the counter at 00 through the next sample.
    check_reset_holds_zero_to_next_sample: assert property (
        @(posedge CLK) !RESET_B |=> (Q == 2'b00)
    );

// From 00, the counter advances to 01 unless an async reset returns it to 00.
    check_count_00_advances_or_resets: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b00) |=> ((Q == 2'b01) || (Q == 2'b00))
    );

// From 01, the counter advances to 10 unless an async reset returns it to 00.
    check_count_01_advances_or_resets: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b01) |=> ((Q == 2'b10) || (Q == 2'b00))
    );

// From 10, the counter advances to 11 unless an async reset returns it to 00.
    check_count_10_advances_or_resets: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b10) |=> ((Q == 2'b11) || (Q == 2'b00))
    );

// From 11, the counter wraps back to 00.
    check_count_11_wraps_to_zero: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (Q == 2'b11) |=> (Q == 2'b00)
    );

// Y must equal the NOR of A and B_N.
    check_nor_equation: assert property (
        @(posedge clk) disable iff (1'b0) Y == ~(A | B_N)
    );

// When both inputs are low, Y must be high.
    check_both_low_drives_high: assert property (
        @(posedge clk) disable iff (1'b0) (!A && !B_N) |-> Y
    );

// A high must force Y low.
    check_a_high_drives_low: assert property (
        @(posedge clk) disable iff (1'b0) A |-> !Y
    );

// B_N high must force Y low.
    check_b_high_drives_low: assert property (
        @(posedge clk) disable iff (1'b0) B_N |-> !Y
    );

// Y high implies both inputs are low.
    check_high_output_requires_both_low: assert property (
        @(posedge clk) disable iff (1'b0) Y |-> (!A && !B_N)
    );

// A din1 sample on a rising edge must be observed on out at the following falling edge.
    check_din1_sample_reaches_next_negedge: assert property (
        @(posedge clk)
        1'b1 |=> @(negedge clk) (out == $past(din1, 1, 1'b1, @(posedge clk)))
    );

// A din2 sample on a rising edge must be observed on out at the next rising edge.
    check_din2_sample_reaches_next_posedge: assert property (
        @(posedge clk)
        1'b1 |=> (out == $past(din2))
    );

// No shift selects the direct Gray-code encoding.
    check_no_shift_gray_mapping: assert property (
        @(posedge clk)
        (shift_amount == 2'b00) |-> (
            shifted_gray_code_output ==
            {binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0])}
        )
    );

// Shift amount 1 rotates the Gray code left by 1 bit.
    check_shift_by_1_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b01) |-> (
            shifted_gray_code_output ==
            {(binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3]}
        )
    );

// Shift amount 2 rotates the Gray code left by 2 bits.
    check_shift_by_2_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b10) |-> (
            shifted_gray_code_output ==
            {(binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2])}
        )
    );

// Shift amount 3 rotates the Gray code left by 3 bits.
    check_shift_by_3_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b11) |-> (
            shifted_gray_code_output ==
            {(binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1])}
        )
    );

// First NAND implements ~(A & B).
    check_nand1_function: assert property (
        @(posedge clk) nand1_out == ~(A & B)
    );

// Second NAND implements ~(nand1_out & C).
    check_nand2_function: assert property (
        @(posedge clk) nand2_out == ~(nand1_out & C)
    );

// Final self-NAND inverts nand2_out onto Y.
    check_output_inverter_function: assert property (
        @(posedge clk) Y == ~(nand2_out & nand2_out)
    );

// Y is the AND of C and nand1_out.
    check_output_equals_c_and_nand1: assert property (
        @(posedge clk) Y == (nand1_out & C)
    );

// End-to-end output is C & ~(A & B).
    check_output_boolean_function: assert property (
        @(posedge clk) Y == (C & ~(A & B))
    );

// C low forces Y low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b0)
    );

// With C high, Y reduces to ~(A & B).
    check_c_high_reduces_to_not_ab: assert property (
        @(posedge clk) (C == 1'b1) |-> (Y == ~(A & B))
    );

// A and B both high force Y low.
    check_ab_high_forces_y_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (Y == 1'b0)
    );

// C high with either A or B low forces Y high.
    check_c_high_and_not_ab_drives_y_high: assert property (
        @(posedge clk) ((C == 1'b1) && ((A == 1'b0) || (B == 1'b0))) |-> (Y == 1'b1)
    );

// RESET clears COUNT on the next clock.
    check_reset_clears_count: assert property (
        @(posedge CLK) RESET |=> (COUNT == 8'h00)
    );

// RESET overrides LOAD when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge CLK) (RESET && LOAD) |=> (COUNT == 8'h00)
    );

// LOAD copies LOAD_DATA into COUNT on the next clock.
    check_load_updates_count: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (COUNT == $past(LOAD_DATA))
    );

// Without LOAD, COUNT increments by one on the next clock.
    check_increment_when_idle: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (COUNT == ($past(COUNT) + 8'd1))
    );

// After reset release with no load, counting restarts from zero.
    check_count_starts_after_reset: assert property (
        @(posedge CLK) (RESET ##1 (!RESET && !LOAD)) |=> (COUNT == 8'h01)
    );

// A loaded value increments on the following idle cycle.
    check_increment_after_load: assert property (
        @(posedge CLK) disable iff (RESET)
        (LOAD ##1 (!LOAD)) |=> (COUNT == ($past(LOAD_DATA, 2) + 8'd1))
    );

// Output must match the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk) y === ((sel == 1'b0) ? a : b)
    );

// Low select routes a to y.
    check_select_low_routes_a: assert property (
        @(posedge clk) (sel === 1'b0) |-> (y === a)
    );

// High select routes b to y.
    check_select_high_routes_b: assert property (
        @(posedge clk) (sel === 1'b1) |-> (y === b)
    );

// Equal inputs force the same output regardless of select.
    check_equal_inputs_same_output: assert property (
        @(posedge clk) (a === b) |-> (y === a)
    );

// A sampled 1 reaches q three clocks later.
    check_sampled_one_delayed_three: assert property (
        @(posedge clk) d |-> ##3 q
    );

// A sampled 0 reaches q three clocks later.
    check_sampled_zero_delayed_three: assert property (
        @(posedge clk) !d |-> ##3 !q
    );

// Three consecutive 1s propagate to q three cycles later.
    check_run_of_ones_propagates: assert property (
        @(posedge clk) (d ##1 d ##1 d) |=> (q ##1 q ##1 q)
    );

// Three consecutive 0s propagate to q three cycles later.
    check_run_of_zeros_propagates: assert property (
        @(posedge clk) (!d ##1 !d ##1 !d) |=> (!q ##1 !q ##1 !q)
    );

// An alternating 1-0-1 input pattern propagates to q.
    check_pattern_101_propagates: assert property (
        @(posedge clk) (d ##1 !d ##1 d) |=> (q ##1 !q ##1 q)
    );

// An alternating 0-1-0 input pattern propagates to q.
    check_pattern_010_propagates: assert property (
        @(posedge clk) (!d ##1 d ##1 !d) |=> (!q ##1 q ##1 !q)
    );

// X must equal the three-input XOR of A, B, and C.
    check_x_matches_xor3: assert property (
        @(posedge clk) X == (A ^ B ^ C)
    );

// If B and C match, X reduces to A.
    check_x_reduces_to_a_when_b_eq_c: assert property (
        @(posedge clk) (B == C) |-> (X == A)
    );

// If A and C match, X reduces to B.
    check_x_reduces_to_b_when_a_eq_c: assert property (
        @(posedge clk) (A == C) |-> (X == B)
    );

// If A and B match, X reduces to C.
    check_x_reduces_to_c_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (X == C)
    );

// Exactly one high input produces a high output.
    check_x_high_for_one_hot_inputs: assert property (
        @(posedge clk)
        ((A && !B && !C) || (!A && B && !C) || (!A && !B && C)) |-> X
    );

// Exactly two high inputs produce a low output.
    check_x_low_for_two_hot_inputs: assert property (
        @(posedge clk)
        ((A && B && !C) || (A && !B && C) || (!A && B && C)) |-> !X
    );

// All-low inputs produce a low output.
    check_x_low_for_all_zero: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// All-high inputs produce a high output.
    check_x_high_for_all_one: assert property (
        @(posedge clk) (A && B && C) |-> X
    );

// High control selects a left shift by one.
    check_left_shift_value: assert property (
        @(posedge clk) (control_signal == 1'b1) |-> (shifted_num == (input_num << 1))
    );

// Low control selects a right shift by one.
    check_right_shift_value: assert property (
        @(posedge clk) (control_signal == 1'b0) |-> (shifted_num == (input_num >> 1))
    );

// Left shift drives a zero into bit 0.
    check_left_shift_lsb_zero: assert property (
        @(posedge clk) (control_signal == 1'b1) |-> (shifted_num[0] == 1'b0)
    );

// Right shift drives a zero into bit 7.
    check_right_shift_msb_zero: assert property (
        @(posedge clk) (control_signal == 1'b0) |-> (shifted_num[7] == 1'b0)
    );

// Left shift maps input bits [6:0] to output bits [7:1].
    check_left_shift_bit_map: assert property (
        @(posedge clk) (control_signal == 1'b1) |-> (shifted_num[7:1] == input_num[6:0])
    );

// Right shift maps input bits [7:1] to output bits [6:0].
    check_right_shift_bit_map: assert property (
        @(posedge clk) (control_signal == 1'b0) |-> (shifted_num[6:0] == input_num[7:1])
    );

// When sel is 00, out must equal in0.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel === 2'b00) |-> (out === in0)
    );

// When sel is 01, out must equal in1.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel === 2'b01) |-> (out === in1)
    );

// When sel is 10, out must equal in2.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel === 2'b10) |-> (out === in2)
    );

// When sel is 11, out must equal in3.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel === 2'b11) |-> (out === in3)
    );

// For any non-binary sel value, the default case drives out low.
    check_default_drives_low: assert property (
        @(posedge clk)
        (!(sel === 2'b00) && !(sel === 2'b01) && !(sel === 2'b10) && !(sel === 2'b11))
        |-> (out === 1'b0)
    );

// Value 4 jumps to 9 on the next clock.
    check_jump_from_four_to_nine: assert property (
        @(posedge clk) (out == 4'd4) |=> (out == 4'd9)
    );

// Value 15 wraps to 0 on the next clock.
    check_wrap_from_fifteen_to_zero: assert property (
        @(posedge clk) (out == 4'd15) |=> (out == 4'd0)
    );

// All other values increment by one on the next clock.
    check_increment_for_normal_states: assert property (
        @(posedge clk) ((out != 4'd4) && (out != 4'd15)) |=> (out == ($past(out) + 4'd1))
    );

// After the 4-to-9 jump, the following value is 10.
    check_continue_after_four_jump: assert property (
        @(posedge clk) (out == 4'd4) |=> ##1 (out == 4'd10)
    );

// After the 15-to-0 wrap, the following value is 1.
    check_continue_after_fifteen_wrap: assert property (
        @(posedge clk) (out == 4'd15) |=> ##1 (out == 4'd1)
    );

// Output must equal the AND of the inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) y == (a & b)
    );

// A HIGH output requires input a to be HIGH.
    check_y_high_implies_a_high: assert property (
        @(posedge clk) y |-> a
    );

// A HIGH output requires input b to be HIGH.
    check_y_high_implies_b_high: assert property (
        @(posedge clk) y |-> b
    );

// Both inputs HIGH must drive the output HIGH.
    check_both_inputs_high_implies_y_high: assert property (
        @(posedge clk) (a & b) |-> y
    );

// Synchronous reset clears q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 64'b0)
    );

// Reset overrides load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && ld) |=> (q == 64'b0)
    );

// Load causes q to capture d on the next sampled cycle.
    check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst) ld |=> (q == $past(d))
    );

// Without load, q holds its previous value.
    check_hold_when_load_low: assert property (
        @(posedge clk) disable iff (rst) !ld |=> (q == $past(q))
    );

// Reset forces both trace outputs to zero.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        !jrst_n |-> (atm == 36'b0 && dtm == 36'b0)
    );

// A read captures the address and read data.
    check_read_captures_addr_and_data: assert property (
        @(posedge clk) disable iff (!jrst_n)
        cpu_d_read |=> (atm == {14'b0, $past(cpu_d_address)} &&
                        dtm == {4'b0,  $past(cpu_d_readdata)})
    );

// A write captures the address and write data when no read is present.
    check_write_captures_addr_and_data: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && cpu_d_write) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                          dtm == {4'b0,  $past(cpu_d_writedata)})
    );

// A wait with no read or write clears both outputs.
    check_wait_clears_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && !cpu_d_write && cpu_d_wait) |=> (atm == 36'b0 && dtm == 36'b0)
    );

// With no control activity, both outputs hold their previous values.
    check_idle_holds_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && !cpu_d_write && !cpu_d_wait) |=> (atm == $past(atm) && dtm == $past(dtm))
    );

// Read has priority over write and wait.
    check_read_has_priority_over_write_or_wait: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (cpu_d_read && (cpu_d_write || cpu_d_wait)) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                                         dtm == {4'b0,  $past(cpu_d_readdata)})
    );

// Write has priority over wait when no read is present.
    check_write_has_priority_over_wait: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (!cpu_d_read && cpu_d_write && cpu_d_wait) |=> (atm == {14'b0, $past(cpu_d_address)} &&
                                                        dtm == {4'b0,  $past(cpu_d_writedata)})
    );

// DUT is combinational with no reset; clk is the assertion sampling clock.

    // LED_0 is high only when SW_0 is exactly low.
    check_led0_active_low: assert property (
        @(posedge clk) LED_0 === (SW_0 === 1'b0)
    );

// LED_1 is high only when SW_1 is exactly low.
    check_led1_active_low: assert property (
        @(posedge clk) LED_1 === (SW_1 === 1'b0)
    );

// LED_2 is high only when SW_2 is exactly low.
    check_led2_active_low: assert property (
        @(posedge clk) LED_2 === (SW_2 === 1'b0)
    );

// LED_3 is high only when SW_3 is exactly low.
    check_led3_active_low: assert property (
        @(posedge clk) LED_3 === (SW_3 === 1'b0)
    );

// LOAD also updates the visible output on the next cycle.
    check_load_updates_output: assert property (
        @(posedge clk)
        LOAD |=> (Q == $past(DIN))
    );

// Reset forces the FSM into NSG.
    check_reset_state_nsg: assert property (
        @(posedge clk) reset |=> (state_reg == NSG)
    );

// After reset, the NSG output pattern is driven.
    check_reset_outputs_nsg: assert property (
        @(posedge clk) reset |=> (NSG_LED == 1'b1 && EWG_LED == 1'b0 && yellow_LED == 1'b0)
    );

// 0000 maps to 0001.
    check_decode_0000: assert property (
        @(posedge clk) (sw == 4'b0000) |-> (led == 4'b0001)
    );

// 0001 maps to 0010.
    check_decode_0001: assert property (
        @(posedge clk) (sw == 4'b0001) |-> (led == 4'b0010)
    );

// 0010 maps to 0011.
    check_decode_0010: assert property (
        @(posedge clk) (sw == 4'b0010) |-> (led == 4'b0011)
    );

// 0011 maps to 0100.
    check_decode_0011: assert property (
        @(posedge clk) (sw == 4'b0011) |-> (led == 4'b0100)
    );

// 0100 maps to 0101.
    check_decode_0100: assert property (
        @(posedge clk) (sw == 4'b0100) |-> (led == 4'b0101)
    );

// 0101 maps to 0110.
    check_decode_0101: assert property (
        @(posedge clk) (sw == 4'b0101) |-> (led == 4'b0110)
    );

// 0110 maps to 0111.
    check_decode_0110: assert property (
        @(posedge clk) (sw == 4'b0110) |-> (led == 4'b0111)
    );

// 0111 maps to 1000.
    check_decode_0111: assert property (
        @(posedge clk) (sw == 4'b0111) |-> (led == 4'b1000)
    );

// 1000 maps to 1001.
    check_decode_1000: assert property (
        @(posedge clk) (sw == 4'b1000) |-> (led == 4'b1001)
    );

// 1001 maps to 1010.
    check_decode_1001: assert property (
        @(posedge clk) (sw == 4'b1001) |-> (led == 4'b1010)
    );

// 1010 maps to 1011.
    check_decode_1010: assert property (
        @(posedge clk) (sw == 4'b1010) |-> (led == 4'b1011)
    );

// 1011 maps to 1100.
    check_decode_1011: assert property (
        @(posedge clk) (sw == 4'b1011) |-> (led == 4'b1100)
    );

// 1100 maps to 1101.
    check_decode_1100: assert property (
        @(posedge clk) (sw == 4'b1100) |-> (led == 4'b1101)
    );

// 1101 maps to 1110.
    check_decode_1101: assert property (
        @(posedge clk) (sw == 4'b1101) |-> (led == 4'b1110)
    );

// 1110 maps to 1111.
    check_decode_1110: assert property (
        @(posedge clk) (sw == 4'b1110) |-> (led == 4'b1111)
    );

// 1111 wraps to 0000.
    check_decode_1111: assert property (
        @(posedge clk) (sw == 4'b1111) |-> (led == 4'b0000)
    );

// Flags 00 and 11 always pass the input through.
    check_common_regions_passthrough: assert property (
        @(posedge clk)
        ((shift_region_flag == 2'b00) || (shift_region_flag == 2'b11)) |-> (data_out == data)
    );

// With operation low and region 01, only the sign bit is inverted.
    check_op0_region01_inverts_sign: assert property (
        @(posedge clk)
        ((operation == 1'b0) && (shift_region_flag == 2'b01)) |-> (data_out == (data ^ SIGN_TOGGLE_MASK))
    );

// With operation low and region 10, the output matches the input.
    check_op0_region10_passthrough: assert property (
        @(posedge clk)
        ((operation == 1'b0) && (shift_region_flag == 2'b10)) |-> (data_out == data)
    );

// With operation high and region 10, only the sign bit is inverted.
    check_op1_region10_inverts_sign: assert property (
        @(posedge clk)
        ((operation == 1'b1) && (shift_region_flag == 2'b10)) |-> (data_out == (data ^ SIGN_TOGGLE_MASK))
    );

// With operation high and region 01, the output matches the input.
    check_op1_region01_passthrough: assert property (
        @(posedge clk)
        ((operation == 1'b1) && (shift_region_flag == 2'b01)) |-> (data_out == data)
    );

// Any output difference from the input is a sign-bit-only change.
    check_only_sign_bit_can_change: assert property (
        @(posedge clk)
        (data_out != data) |-> ((data_out ^ data) == SIGN_TOGGLE_MASK)
    );

// Output differs from input only in the two active inversion cases.
    check_difference_only_in_active_cases: assert property (
        @(posedge clk)
        (data_out != data) |-> (((operation == 1'b0) && (shift_region_flag == 2'b01)) ||
                                ((operation == 1'b1) && (shift_region_flag == 2'b10)))
    );

// Complete combinational mapping from inputs to output.
    check_complete_mapping: assert property (
        @(posedge clk)
        data_out == ((((operation == 1'b0) && (shift_region_flag == 2'b01)) ||
                      ((operation == 1'b1) && (shift_region_flag == 2'b10)))
                     ? (data ^ SIGN_TOGGLE_MASK) : data)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset has priority over load.
    check_reset_overrides_load: assert property (
        @(posedge clk) (reset && load) |=> (count == 4'b0000)
    );

// A load updates the counter with data_in.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(data_in))
    );

// Without load, the counter increments by one.
    check_increment_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        !load |=> (count == ($past(count) + 4'b0001))
    );

// The counter wraps from 15 back to 0.
    check_wraparound_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Every non-reset cycle follows the load-or-increment next-state rule.
    check_exact_nonreset_transition: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count == ($past(load) ? $past(data_in) : ($past(count) + 4'b0001)))
    );

// Once q is low, the AND-based update keeps it low on the next cycle.
    check_q_sticky_low: assert property (
        @(posedge clk)
        !q |=> !q
    );

// read_1 forwards write_0 when enabled, else read_0.
    check_read1_mux: assert property (
        @(posedge CLK) read_1 == (EN_write_0 ? write_0 : read_0)
    );

// read_2 forwards write_1 when enabled, else read_1.
    check_read2_mux: assert property (
        @(posedge CLK) read_2 == (EN_write_1 ? write_1 : read_1)
    );

// read_3 forwards write_2 when enabled, else read_2.
    check_read3_mux: assert property (
        @(posedge CLK) read_3 == (EN_write_2 ? write_2 : read_2)
    );

// read_4 forwards write_3 when enabled, else read_3.
    check_read4_mux: assert property (
        @(posedge CLK) read_4 == (EN_write_3 ? write_3 : read_3)
    );

// read_5 forwards write_4 when enabled, else read_4.
    check_read5_mux: assert property (
        @(posedge CLK) read_5 == (EN_write_4 ? write_4 : read_4)
    );

// read_6 forwards write_5 when enabled, else read_5.
    check_read6_mux: assert property (
        @(posedge CLK) read_6 == (EN_write_5 ? write_5 : read_5)
    );

// read_7 forwards write_6 when enabled, else read_6.
    check_read7_mux: assert property (
        @(posedge CLK) read_7 == (EN_write_6 ? write_6 : read_6)
    );

// read_7 reflects the highest-priority enabled write among ports 0 through 6.
    check_read7_priority_chain: assert property (
        @(posedge CLK)
        read_7 == (
            EN_write_6 ? write_6 :
            EN_write_5 ? write_5 :
            EN_write_4 ? write_4 :
            EN_write_3 ? write_3 :
            EN_write_2 ? write_2 :
            EN_write_1 ? write_1 :
            EN_write_0 ? write_0 : read_0
        )
    );

// A write on port 7 overrides all earlier stages for the next read_0 value.
    check_write7_overrides_next_state: assert property (
        @(posedge CLK)
        EN_write_7 |=> read_0 == $past(write_7)
    );

// G1 matches the implemented inversion and AND logic.
    check_g1_function: assert property (
        @(posedge clk) (G1 === ((~R1) & R2))
    );

// G2 matches the implemented inversion and AND logic.
    check_g2_function: assert property (
        @(posedge clk) (G2 === ((~R2) & R1))
    );

// The two grants are never asserted at the same time.
    check_grants_mutex: assert property (
        @(posedge clk) !((G1 === 1'b1) && (G2 === 1'b1))
    );

// When both requests are low, both grants are low.
    check_both_requests_low: assert property (
        @(posedge clk) ((R1 === 1'b0) && (R2 === 1'b0)) |-> ((G1 === 1'b0) && (G2 === 1'b0))
    );

// When both requests are high, both grants are low.
    check_both_requests_high: assert property (
        @(posedge clk) ((R1 === 1'b1) && (R2 === 1'b1)) |-> ((G1 === 1'b0) && (G2 === 1'b0))
    );

// R1 low and R2 high produces only G1.
    check_r2_only_grants_g1: assert property (
        @(posedge clk) ((R1 === 1'b0) && (R2 === 1'b1)) |-> ((G1 === 1'b1) && (G2 === 1'b0))
    );

// R1 high and R2 low produces only G2.
    check_r1_only_grants_g2: assert property (
        @(posedge clk) ((R1 === 1'b1) && (R2 === 1'b0)) |-> ((G1 === 1'b0) && (G2 === 1'b1))
    );

// A high G1 can only occur for the implemented input combination.
    check_g1_implies_inputs: assert property (
        @(posedge clk) (G1 === 1'b1) |-> ((R1 === 1'b0) && (R2 === 1'b1))
    );

// A high G2 can only occur for the implemented input combination.
    check_g2_implies_inputs: assert property (
        @(posedge clk) (G2 === 1'b1) |-> ((R1 === 1'b1) && (R2 === 1'b0))
    );

// A=0 maps to 0,0.
    check_a0_mapping: assert property (
        @(posedge clk) (A == 4'd0) |-> ((OUT1 == 4'd0) && (OUT2 == 4'd0))
    );

// A=1 maps to 0,1.
    check_a1_mapping: assert property (
        @(posedge clk) (A == 4'd1) |-> ((OUT1 == 4'd0) && (OUT2 == 4'd1))
    );

// A=2 maps to 0,2.
    check_a2_mapping: assert property (
        @(posedge clk) (A == 4'd2) |-> ((OUT1 == 4'd0) && (OUT2 == 4'd2))
    );

// A=3 maps to 0,3.
    check_a3_mapping: assert property (
        @(posedge clk) (A == 4'd3) |-> ((OUT1 == 4'd0) && (OUT2 == 4'd3))
    );

// A=4 maps to 1,0.
    check_a4_mapping: assert property (
        @(posedge clk) (A == 4'd4) |-> ((OUT1 == 4'd1) && (OUT2 == 4'd0))
    );

// A=5 maps to 1,1.
    check_a5_mapping: assert property (
        @(posedge clk) (A == 4'd5) |-> ((OUT1 == 4'd1) && (OUT2 == 4'd1))
    );

// A=6 maps to 1,2.
    check_a6_mapping: assert property (
        @(posedge clk) (A == 4'd6) |-> ((OUT1 == 4'd1) && (OUT2 == 4'd2))
    );

// A=7 maps to 1,3.
    check_a7_mapping: assert property (
        @(posedge clk) (A == 4'd7) |-> ((OUT1 == 4'd1) && (OUT2 == 4'd3))
    );

// A=8 maps to 2,0.
    check_a8_mapping: assert property (
        @(posedge clk) (A == 4'd8) |-> ((OUT1 == 4'd2) && (OUT2 == 4'd0))
    );

// A=9 maps to 2,1.
    check_a9_mapping: assert property (
        @(posedge clk) (A == 4'd9) |-> ((OUT1 == 4'd2) && (OUT2 == 4'd1))
    );

// Inputs above 9 drive both outputs to zero.
    check_default_mapping: assert property (
        @(posedge clk) (A >= 4'd10) |-> ((OUT1 == 4'd0) && (OUT2 == 4'd0))
    );

// Output is high when A is greater than B.
    check_out_high_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (out == 1'b1)
    );

// Output is low when A is less than B.
    check_out_low_when_a_lt_b: assert property (
        @(posedge clk) (A < B) |-> (out == 1'b0)
    );

// Output is low when A equals B.
    check_out_low_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (out == 1'b0)
    );

// Output always matches the comparison result.
    check_out_matches_comparison: assert property (
        @(posedge clk) out == (A > B)
    );

// Reset forces the output low.
    reset_drives_output_low: assert property (
        @(posedge clk) globalreset |-> (output_xhdl0 == 1'b0)
    );

// No clock or reset exists in the RTL; sample this combinational decoder on clk.

    // BCD 0 decodes to binary 0.
    check_bcd_0_maps_to_0: assert property (
        @(posedge clk) (bcd_in == 4'b0000) |-> (bin_out == 8'b00000000)
    );

// BCD 1 decodes to binary 1.
    check_bcd_1_maps_to_1: assert property (
        @(posedge clk) (bcd_in == 4'b0001) |-> (bin_out == 8'b00000001)
    );

// BCD 2 decodes to binary 2.
    check_bcd_2_maps_to_2: assert property (
        @(posedge clk) (bcd_in == 4'b0010) |-> (bin_out == 8'b00000010)
    );

// BCD 3 decodes to binary 3.
    check_bcd_3_maps_to_3: assert property (
        @(posedge clk) (bcd_in == 4'b0011) |-> (bin_out == 8'b00000011)
    );

// BCD 4 decodes to binary 4.
    check_bcd_4_maps_to_4: assert property (
        @(posedge clk) (bcd_in == 4'b0100) |-> (bin_out == 8'b00000100)
    );

// BCD 5 decodes to binary 5.
    check_bcd_5_maps_to_5: assert property (
        @(posedge clk) (bcd_in == 4'b0101) |-> (bin_out == 8'b00000101)
    );

// BCD 6 decodes to binary 6.
    check_bcd_6_maps_to_6: assert property (
        @(posedge clk) (bcd_in == 4'b0110) |-> (bin_out == 8'b00000110)
    );

// BCD 7 decodes to binary 7.
    check_bcd_7_maps_to_7: assert property (
        @(posedge clk) (bcd_in == 4'b0111) |-> (bin_out == 8'b00000111)
    );

// BCD 8 decodes to binary 8.
    check_bcd_8_maps_to_8: assert property (
        @(posedge clk) (bcd_in == 4'b1000) |-> (bin_out == 8'b00001000)
    );

// BCD 9 decodes to binary 9.
    check_bcd_9_maps_to_9: assert property (
        @(posedge clk) (bcd_in == 4'b1001) |-> (bin_out == 8'b00001001)
    );

// Inputs outside valid BCD range use the default zero output.
    check_invalid_bcd_maps_to_zero: assert property (
        @(posedge clk) (bcd_in > 4'd9) |-> (bin_out == 8'b00000000)
    );

// The output never exceeds the implemented 0-to-9 range.
    check_bin_out_range: assert property (
        @(posedge clk) (bin_out <= 8'd9)
    );

// When S is low, the mux output selects A.
    check_select_a: assert property (
        @(posedge clk) (S == 1'b0) |-> (Y == A)
    );

// When S is high, the mux output selects B.
    check_select_b: assert property (
        @(posedge clk) (S == 1'b1) |-> (Y == B)
    );

// The output always matches the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk) Y == ((S == 1'b0) ? A : B)
    );

// Reset forces the default baud divisor.
    check_reset_forces_default_baud: assert property (
        @(posedge CLKIN) RST |-> (baud_rate == B9600)
    );

// A reset cycle clears the counter and output by the next clock.
    check_reset_clears_counter_and_output: assert property (
        @(posedge CLKIN) RST |=> ((clk_cntr == 20'd0) && (CLKOUT == 1'b0))
    );

// A sampled reset cycle leaves the counter cleared.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// In up mode below 15, the counter increments by one.
    check_up_mode_increments: assert property (
        @(posedge clk) disable iff (rst)
        (up_down && (count != 4'hf)) |=> (count == ($past(count) + 4'h1))
    );

// In up mode at 15, the counter wraps to 0.
    check_up_mode_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (up_down && (count == 4'hf)) |=> (count == 4'h0)
    );

// In down mode above 0, the counter decrements by one.
    check_down_mode_decrements: assert property (
        @(posedge clk) disable iff (rst)
        ((!up_down) && (count != 4'h0)) |=> (count == ($past(count) - 4'h1))
    );

// In down mode at 0, the counter wraps to 15.
    check_down_mode_wraps_to_fifteen: assert property (
        @(posedge clk) disable iff (rst)
        ((!up_down) && (count == 4'h0)) |=> (count == 4'hf)
    );

// Combinational DUT sampled on an external clock; no reset is present in the RTL.

    // dout matches the implemented mux tree.
    check_dout_matches_mux_tree: assert property (
        @(posedge clk)
        dout === (
            (din7[2] == 1'b0) ?
                (
                    (din7[1] == 1'b0) ?
                        ((din7[0] == 1'b0) ? din1 : din2) :
                        ((din7[0] == 1'b0) ? din3 : din4)
                ) :
                ((din7[0] == 1'b0) ? din5 : din6)
        )
    );

// Select 000 routes din1.
    check_sel_000_routes_din1: assert property (
        @(posedge clk) (din7 == 3'b000) |-> (dout === din1)
    );

// Select 001 routes din2.
    check_sel_001_routes_din2: assert property (
        @(posedge clk) (din7 == 3'b001) |-> (dout === din2)
    );

// Select 010 routes din3.
    check_sel_010_routes_din3: assert property (
        @(posedge clk) (din7 == 3'b010) |-> (dout === din3)
    );

// Select 011 routes din4.
    check_sel_011_routes_din4: assert property (
        @(posedge clk) (din7 == 3'b011) |-> (dout === din4)
    );

// Selects 100 and 110 both route din5.
    check_sel_100_110_route_din5: assert property (
        @(posedge clk) ((din7 == 3'b100) || (din7 == 3'b110)) |-> (dout === din5)
    );

// Selects 101 and 111 both route din6.
    check_sel_101_111_route_din6: assert property (
        @(posedge clk) ((din7 == 3'b101) || (din7 == 3'b111)) |-> (dout === din6)
    );

// Synchronous reset forces Q to zero by the next clock sample.
    check_reset_clears_counter: assert property (
        @(posedge CK) RST |=> (Q == 4'b0000)
    );

// On reset assertion, sampled Q still reflects the previous non-reset increment.
    check_last_count_visible_on_reset_assertion: assert property (
        @(posedge CK)
        (RST && !$past(RST)) |-> (Q == ($past(Q) + 4'd1))
    );

// OUT must equal the 4-bit two's complement of A.
    check_twos_complement_function: assert property (
        @(posedge clk) OUT == (~A + 4'b0001)
    );

// A and OUT must add to zero modulo 16.
    check_additive_inverse: assert property (
        @(posedge clk) (A + OUT) == 4'b0000
    );

// Zero input must produce zero output.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (A == 4'b0000) |-> (OUT == 4'b0000)
    );

// 4'b1000 must map to itself in 4-bit two's complement.
    check_min_value_self_inverse: assert property (
        @(posedge clk) (A == 4'b1000) |-> (OUT == 4'b1000)
    );

// Two's complement preserves the least-significant bit.
    check_lsb_preserved: assert property (
        @(posedge clk) OUT[0] == A[0]
    );

// The SDA synchronizer shifts in the sampled SDA value each clock.
    check_sda_shift_register: assert property (
        @(posedge clk) disable iff (!rst)
        (sda_reg[0] == $past(sda)) &&
        (sda_reg[1] == $past(sda_reg[0]))
    );

// falling_edge is asserted only for the 2'b10 SDA history pattern.
    check_falling_edge_decode: assert property (
        @(posedge clk) disable iff (!rst)
        (falling_edge == (sda_reg == 2'b10))
    );

// rising_edge is asserted only for the 2'b01 SDA history pattern.
    check_rising_edge_decode: assert property (
        @(posedge clk) disable iff (!rst)
        (rising_edge == (sda_reg == 2'b01))
    );

// A qualifying falling edge sets the indexed start bit and increments start_cnt.
    check_start_capture_update: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(falling_edge) && ($past(start_cnt) < 8'd3)) |->
            (start_cnt == ($past(start_cnt) + 8'd1)) &&
            (start_bits == ($past(start_bits) | (3'b001 << $past(start_cnt))))
    );

// Without a qualifying falling edge, start_bits and start_cnt hold their values.
    check_start_capture_hold: assert property (
        @(posedge clk) disable iff (!rst)
        !($past(falling_edge) && ($past(start_cnt) < 8'd3)) |->
            (start_cnt == $past(start_cnt)) &&
            (start_bits == $past(start_bits))
    );

// The timing state stays idle until all three start bits have been seen.
    check_timer_idle_before_start: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) != 3'b111) |->
            (time_cnt == $past(time_cnt)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == $past(data_start))
    );

// Before data_start, time_cnt increments up to 44500.
    check_preamble_timer_increment: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && !$past(data_start) && ($past(time_cnt) < 32'd44500)) |->
            (time_cnt == ($past(time_cnt) + 32'd1)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b0)
    );

// At 44500 counts, the preamble timer resets and data_start asserts.
    check_preamble_done_sets_data_start: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && !$past(data_start) && ($past(time_cnt) == 32'd44500)) |->
            (time_cnt == 32'd0) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b1)
    );

// During data collection, time_cnt increments until the bit period completes.
    check_bit_timer_increment: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && $past(data_start) &&
         ($past(cyc_cnt) < 8'd11) && ($past(time_cnt) < 32'd89000)) |->
            (time_cnt == ($past(time_cnt) + 32'd1)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b1)
    );

// At 89000 counts, the bit timer resets and cyc_cnt increments.
    check_bit_timer_wrap_advances_cycle: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && $past(data_start) &&
         ($past(cyc_cnt) < 8'd11) && ($past(time_cnt) == 32'd89000)) |->
            (time_cnt == 32'd0) &&
            (cyc_cnt == ($past(cyc_cnt) + 8'd1)) &&
            (data_start == 1'b1)
    );

// A falling edge in the valid sample window writes a 1 into the current bit.
    check_falling_edge_samples_one: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(falling_edge) &&
         ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
         ($past(cyc_cnt) < 8'd11)) |->
            (recieved_data == ($past(recieved_data) | (11'h001 << $past(cyc_cnt))))
    );

// A rising edge in the valid sample window writes a 0 into the current bit.
    check_rising_edge_samples_zero: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(rising_edge) &&
         ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
         ($past(cyc_cnt) < 8'd11)) |->
            (recieved_data == ($past(recieved_data) & ~(11'h001 << $past(cyc_cnt))))
    );

// recieve_status reflects whether the previous recieved_data matched the fixed pattern.
    check_status_matches_previous_data: assert property (
        @(posedge clk) disable iff (!rst)
        (recieve_status == ((($past(recieved_data) == 11'b00011110101) ? 1'b1 : 1'b0)))
    );

// Y matches the implemented gate equation.
    check_boolean_function: assert property (
        @(posedge clk) Y == (A_N | ~B)
    );

// A_N high forces Y high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

// The only low-output case is A_N low with B high.
    check_low_output_case: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1)) |-> (Y == 1'b0)
    );

// A low Y implies A_N is low and B is high.
    check_y_low_implies_inputs: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B == 1'b1))
    );

// out1 must implement (in1 & in2) | ~in3.
    check_output_equation: assert property (
        @(posedge clk) out1 == ((in1 & in2) | (~in3))
    );

// A low in3 forces out1 high.
    check_in3_low_forces_out1_high: assert property (
        @(posedge clk) (in3 == 1'b0) |-> (out1 == 1'b1)
    );

// With in3 high, out1 reduces to in1 & in2.
    check_in3_high_reduces_to_and: assert property (
        @(posedge clk) (in3 == 1'b1) |-> (out1 == (in1 & in2))
    );

// Both data inputs high force out1 high.
    check_both_inputs_high_force_out1_high: assert property (
        @(posedge clk) ((in1 == 1'b1) && (in2 == 1'b1)) |-> (out1 == 1'b1)
    );

// With in3 high, a low in1 forces out1 low.
    check_in3_high_and_in1_low_force_out1_low: assert property (
        @(posedge clk) ((in3 == 1'b1) && (in1 == 1'b0)) |-> (out1 == 1'b0)
    );

// With in3 high, a low in2 forces out1 low.
    check_in3_high_and_in2_low_force_out1_low: assert property (
        @(posedge clk) ((in3 == 1'b1) && (in2 == 1'b0)) |-> (out1 == 1'b0)
    );

// A low out1 can occur only when in3 is high and one input is low.
    check_low_output_characterization: assert property (
        @(posedge clk) (out1 == 1'b0) |-> ((in3 == 1'b1) && ((in1 == 1'b0) || (in2 == 1'b0)))
    );

// If out1 is high while in3 is high, both inputs must be high.
    check_high_output_with_in3_high_requires_both_inputs: assert property (
        @(posedge clk) ((out1 == 1'b1) && (in3 == 1'b1)) |-> ((in1 == 1'b1) && (in2 == 1'b1))
    );

// Load writes load_val into count_out on the next clock, unless async reset clears it.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> ((count_out == $past(load_val)) || (count_out == 32'd0))
    );

// Load takes priority over counting when both controls are asserted.
    check_load_has_priority_over_count: assert property (
        @(posedge clk) disable iff (reset)
        (load && count_en) |=> ((count_out == $past(load_val)) || (count_out == 32'd0))
    );

// Without load or count enable, count_out holds its value, unless async reset clears it.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !count_en) |=> ((count_out == $past(count_out)) || (count_out == 32'd0))
    );

// When counting up at max_count, the counter wraps to zero.
    check_count_up_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && count_dir && (count_out == max_count)) |=> (count_out == 32'd0)
    );

// When counting up below max_count, the counter increments by one, unless async reset clears it.
    check_count_up_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && count_dir && (count_out != max_count))
        |=> ((count_out == ($past(count_out) + 32'd1)) || (count_out == 32'd0))
    );

// When counting down from zero, the counter wraps to max_count, unless async reset clears it.
    check_count_down_wraps_to_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && !count_dir && (count_out == 32'd0))
        |=> ((count_out == $past(max_count)) || (count_out == 32'd0))
    );

// When counting down above zero, the counter decrements by one, unless async reset clears it.
    check_count_down_decrements: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && !count_dir && (count_out != 32'd0))
        |=> ((count_out == ($past(count_out) - 32'd1)) || (count_out == 32'd0))
    );

// Reset forces the state register to IDLE.
    check_reset_sets_idle: assert property (
        @(posedge clk) !rst_n |-> (cur_state == ST_IDLE)
    );

// Reset keeps ack low.
    check_reset_clears_ack: assert property (
        @(posedge clk) !rst_n |-> (ack == 1'b0)
    );

// J=0 and K=0 must hold Q low.
    check_hold_low: assert property (
        @(posedge clk)
        (J === 1'b0 && K === 1'b0 && Q === 1'b0) |=> (Q === 1'b0)
    );

// J=0 and K=0 must hold Q high.
    check_hold_high: assert property (
        @(posedge clk)
        (J === 1'b0 && K === 1'b0 && Q === 1'b1) |=> (Q === 1'b1)
    );

// J=0 and K=1 must drive Q low.
    check_reset_output_low: assert property (
        @(posedge clk)
        (J === 1'b0 && K === 1'b1) |=> (Q === 1'b0)
    );

// J=1 and K=0 must drive Q high.
    check_set_output_high: assert property (
        @(posedge clk)
        (J === 1'b1 && K === 1'b0) |=> (Q === 1'b1)
    );

// J=1 and K=1 must toggle Q from low to high.
    check_toggle_low_to_high: assert property (
        @(posedge clk)
        (J === 1'b1 && K === 1'b1 && Q === 1'b0) |=> (Q === 1'b1)
    );

// J=1 and K=1 must toggle Q from high to low.
    check_toggle_high_to_low: assert property (
        @(posedge clk)
        (J === 1'b1 && K === 1'b1 && Q === 1'b1) |=> (Q === 1'b0)
    );

// S=00 routes A to Y.
    check_select_a: assert property (
        @(posedge clk) (S === 2'b00) |-> (Y === A)
    );

// S=01 routes B to Y.
    check_select_b: assert property (
        @(posedge clk) (S === 2'b01) |-> (Y === B)
    );

// S=10 routes C to Y.
    check_select_c: assert property (
        @(posedge clk) (S === 2'b10) |-> (Y === C)
    );

// S=11 routes D to Y.
    check_select_d: assert property (
        @(posedge clk) (S === 2'b11) |-> (Y === D)
    );

// Reset forces the counter to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset_n |-> (count == 3'b000)
    );

// A non-maximum count increments by one on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count != 3'b111) |=> (count == ($past(count) + 3'b001))
    );

// The maximum count wraps back to zero on the next clock.
    check_wrap_after_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count == 3'b111) |=> (count == 3'b000)
    );

// Estado 6C selects seconds, minutes, and hours on the next cycle.
    check_estado_6c_selects_time: assert property (
        @(posedge clk)
        (Estado == 8'h6C) |=> (
            (Salida_1 == {2'b00, $past(Cuenta_Segundos)}) &&
            (Salida_2 == {2'b00, $past(Cuenta_Minutos)}) &&
            (Salida_3 == {3'b000, $past(Cuenta_Horas)})
        )
    );

// Estado 75 selects seconds, minutes, and hours on the next cycle.
    check_estado_75_selects_time: assert property (
        @(posedge clk)
        (Estado == 8'h75) |=> (
            (Salida_1 == {2'b00, $past(Cuenta_Segundos)}) &&
            (Salida_2 == {2'b00, $past(Cuenta_Minutos)}) &&
            (Salida_3 == {3'b000, $past(Cuenta_Horas)})
        )
    );

// All other Estado values select year, month, and day on the next cycle.
    check_other_estado_selects_date: assert property (
        @(posedge clk)
        (Estado != 8'h6C && Estado != 8'h75) |=> (
            (Salida_1 == {3'b000, $past(Cuenta_Year)}) &&
            (Salida_2 == {4'b0000, $past(Cuenta_Mes)}) &&
            (Salida_3 == {1'b0, $past(Cuenta_Dia)})
        )
    );

// Y must equal the NAND of all four inputs.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B & C & D)
    );

// When all inputs are HIGH, Y must be LOW.
    check_all_inputs_high_drive_y_low: assert property (
        @(posedge clk) (A & B & C & D) |-> !Y
    );

// If the inputs are not all HIGH, Y must be HIGH.
    check_not_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (~(A & B & C & D)) |-> Y
    );

// Y LOW can only occur when all inputs are HIGH.
    check_y_low_implies_all_inputs_high: assert property (
        @(posedge clk) !Y |-> (A & B & C & D)
    );

// Y HIGH means the inputs are not all HIGH.
    check_y_high_implies_not_all_inputs_high: assert property (
        @(posedge clk) Y |-> ~(A & B & C & D)
    );

// Out is the carry result of the third full-adder stage.
    check_out_matches_stage3_carry: assert property (
        @(posedge clk)
        out == (
            ((in0 ^ in1 ^ {4{sel[0]}}) & (in2 ^ in3 ^ {4{sel[0]}})) |
            ({4{sel[1]}} & ((in0 ^ in1 ^ {4{sel[0]}}) ^ (in2 ^ in3 ^ {4{sel[0]}})))
        )
    );

// With sel[1] low, out is the AND of the first two stage sums.
    check_sel1_low_uses_and_of_stage_sums: assert property (
        @(posedge clk)
        (sel[1] == 1'b0) |-> (
            out == ((in0 ^ in1 ^ {4{sel[0]}}) & (in2 ^ in3 ^ {4{sel[0]}}))
        )
    );

// With sel[1] high, out is the OR of the first two stage sums.
    check_sel1_high_uses_or_of_stage_sums: assert property (
        @(posedge clk)
        (sel[1] == 1'b1) |-> (
            out == ((in0 ^ in1 ^ {4{sel[0]}}) | (in2 ^ in3 ^ {4{sel[0]}}))
        )
    );

// sel=00 produces the AND of the pairwise XOR terms.
    check_sel00_and_of_xors: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == ((in0 ^ in1) & (in2 ^ in3)))
    );

// sel=01 produces the AND of the pairwise XNOR terms.
    check_sel01_and_of_xnors: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == ((in0 ~^ in1) & (in2 ~^ in3)))
    );

// sel=10 produces the OR of the pairwise XOR terms.
    check_sel10_or_of_xors: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == ((in0 ^ in1) | (in2 ^ in3)))
    );

// sel=11 produces the OR of the pairwise XNOR terms.
    check_sel11_or_of_xnors: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == ((in0 ~^ in1) | (in2 ~^ in3)))
    );

// Y implements the XNOR of A and B.
    check_xnor_equivalence: assert property (
        @(posedge clk) (Y == ~(A ^ B))
    );

// Equal inputs drive Y high.
    check_equal_inputs_drive_high: assert property (
        @(posedge clk) (A == B) |-> (Y == 1'b1)
    );

// Different inputs drive Y low.
    check_unequal_inputs_drive_low: assert property (
        @(posedge clk) (A != B) |-> (Y == 1'b0)
    );

// With B low, Y is the inverse of A.
    check_b_low_inverts_a: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == ~A)
    );

// With B high, Y matches A.
    check_b_high_matches_a: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == A)
    );

// X must equal the three-input XOR of A, B, and C.
    check_x_matches_xor3: assert property (
        @(posedge clk) X == (A ^ B ^ C)
    );

// With C low, X reduces to A XOR B.
    check_c_low_reduces_to_ab_xor: assert property (
        @(posedge clk) !C |-> (X == (A ^ B))
    );

// With C high, X is the inverse of A XOR B.
    check_c_high_inverts_ab_xor: assert property (
        @(posedge clk) C |-> (X == ~(A ^ B))
    );

// When A and B match, X must equal C.
    check_equal_ab_reduces_to_c: assert property (
        @(posedge clk) (A == B) |-> (X == C)
    );

// When A and B differ, X must equal the inverse of C.
    check_unequal_ab_inverts_c: assert property (
        @(posedge clk) (A != B) |-> (X == ~C)
    );

// All-zero inputs must drive X low.
    check_all_zero_drives_zero: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// All-one inputs must drive X high.
    check_all_one_drives_one: assert property (
        @(posedge clk) (A && B && C) |-> X
    );

// Y must always equal A AND B.
    check_output_matches_and: assert property (
        @(posedge clk) Y == (A & B)
    );

// A LOW must force Y LOW.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b0)
    );

// B LOW must force Y LOW.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b0)
    );

// Both inputs HIGH must drive Y HIGH.
    check_both_high_drive_y_high: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1) |-> (Y == 1'b1)
    );

// Y HIGH requires both inputs HIGH.
    check_y_high_requires_both_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (A == 1'b1 && B == 1'b1)
    );

// out_hi is always either zero or the upper input byte.
    check_out_hi_is_zero_or_upper_byte: assert property (
        @(posedge clk)
        ((out_hi == 8'b0) || (out_hi == in[15:8]))
    );

// out_lo is always either zero or the lower input byte.
    check_out_lo_is_zero_or_lower_byte: assert property (
        @(posedge clk)
        ((out_lo == 8'b0) || (out_lo == in[7:0]))
    );

// A nonzero out_hi requires out_lo to be zero.
    check_nonzero_out_hi_excludes_out_lo: assert property (
        @(posedge clk)
        (out_hi != 8'b0) |-> (out_lo == 8'b0)
    );

// A nonzero out_lo requires out_hi to be zero.
    check_nonzero_out_lo_excludes_out_hi: assert property (
        @(posedge clk)
        (out_lo != 8'b0) |-> (out_hi == 8'b0)
    );

// Reset drives the output low.
    check_reset_clears_out: assert property (
        @(posedge clk) !reset |-> (out == 8'b0)
    );

// Enabled logic selects a when a is nonzero.
    check_select_a_when_enabled_and_a_nonzero: assert property (
        @(posedge clk) disable iff (!reset)
        (en && (a != 8'b0)) |=> (out == $past(a))
    );

// Enabled logic selects b when a is zero.
    check_select_b_when_enabled_and_a_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (en && (a == 8'b0)) |=> (out == $past(b))
    );

// Disabled logic clears the output.
    check_zero_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        (!en) |=> (out == 8'b0)
    );

// Output follows the previous cycle's full decision tree.
    check_full_next_state_function: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (out == ($past(en) ? (($past(a) != 8'b0) ? $past(a) : $past(b)) : 8'b0))
    );

// No reset is present in the RTL.
    // The DUT is combinational, so checks are sampled on clk.

    // EQ must match the implemented zero-detect of A-B.
    check_eq_matches_rtl_expression: assert property (
        @(posedge clk) EQ == (&(~(A - B)))
    );

// EQ must assert when A and B are equal.
    check_eq_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ == 1'b1)
    );

// EQ must deassert when A and B are different.
    check_eq_when_inputs_different: assert property (
        @(posedge clk) (A != B) |-> (EQ == 1'b0)
    );

// GT is tied low by the RTL logic.
    check_gt_tied_low: assert property (
        @(posedge clk) GT == 1'b0
    );

// q reflects the add result from two cycles earlier.
    check_q_add_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ##2 (q == (($past(data1, 2) + $past(data2, 2)) & 4'hF))
    );

// q reflects the subtract result from two cycles earlier.
    check_q_sub_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ##2 (q == (($past(data1, 2) - $past(data2, 2)) & 4'hF))
    );

// q reflects the bitwise AND result from two cycles earlier.
    check_q_and_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b10) |-> ##2 (q == ($past(data1, 2) & $past(data2, 2)))
    );

// q reflects the bitwise OR result from two cycles earlier.
    check_q_or_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b11) |-> ##2 (q == ($past(data1, 2) | $past(data2, 2)))
    );

// q always matches the operation selected two cycles earlier.
    check_q_matches_selected_operation: assert property (
        @(posedge clk)
        1'b1 |-> ##2 (
            q == (
                ($past(op, 2) == 2'b00) ? ((($past(data1, 2) + $past(data2, 2)) & 4'hF)) :
                ($past(op, 2) == 2'b01) ? ((($past(data1, 2) - $past(data2, 2)) & 4'hF)) :
                ($past(op, 2) == 2'b10) ? (($past(data1, 2) & $past(data2, 2))) :
                                          (($past(data1, 2) | $past(data2, 2)))
            )
        )
    );

// AND opcodes drive the bitwise AND of a and b.
    check_and_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0001) || (aluc == 4'b1001)) |-> (result == (a & b))
    );

// OR opcodes drive the bitwise OR of a and b.
    check_or_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0101) || (aluc == 4'b1101)) |-> (result == (a | b))
    );

// XOR opcodes drive the bitwise XOR of a and b.
    check_xor_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b1010) || (aluc == 4'b0010)) |-> (result == (a ^ b))
    );

// LUI opcodes drive zero-extended b[15:0].
    check_lui_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0110) || (aluc == 4'b1110)) |-> (result == {16'b0, b[15:0]})
    );

// ADD opcodes drive a + b.
    check_add_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0000) || (aluc == 4'b1000)) |-> (result == addresult)
    );

// SUB opcodes drive a - b.
    check_sub_opcodes: assert property (
        @(posedge clk) ((aluc == 4'b0100) || (aluc == 4'b1100)) |-> (result == subresult)
    );

// SLL opcode drives b shifted left by a.
    check_sll_opcode: assert property (
        @(posedge clk) (aluc == 4'b0011) |-> (result == (b << a))
    );

// SRL opcode drives b shifted right by a.
    check_srl_opcode: assert property (
        @(posedge clk) (aluc == 4'b0111) |-> (result == (b >> a))
    );

// The default opcode 1011 also drives a + b.
    check_default_add_opcode: assert property (
        @(posedge clk) (aluc == 4'b1011) |-> (result == addresult)
    );

// With no selects asserted, output must be zero.
    check_no_selects_drive_zero: assert property (
        @(posedge clk)
        (!(sel0 || sel1 || sel2 || sel3 || sel4 || sel5 || sel6 || sel7 || sel8))
        |-> (out == {DW{1'b0}})
    );

// If only sel8 is asserted, output must equal in8.
    check_only_sel8_passes_in8: assert property (
        @(posedge clk)
        (sel8 && !(sel0 || sel1 || sel2 || sel3 || sel4 || sel5 || sel6 || sel7))
        |-> (out == in8)
    );

// ctrl is high for input encoding 1101.
    check_ctrl_high_on_1101: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} === 4'b1101) |-> (ctrl === 1'b1)
    );

// ctrl is high for input encoding 0110.
    check_ctrl_high_on_0110: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} === 4'b0110) |-> (ctrl === 1'b1)
    );

// ctrl is low for every encoding other than the two one-driving cases.
    check_ctrl_low_on_all_other_encodings: assert property (
        @(posedge clk)
        !(({xor_info, or_info, round_mode} === 4'b1101) ||
          ({xor_info, or_info, round_mode} === 4'b0110)) |-> (ctrl === 1'b0)
    );

// A high ctrl implies one of the two one-driving encodings.
    check_ctrl_high_only_on_defined_cases: assert property (
        @(posedge clk)
        (ctrl === 1'b1) |-> (({xor_info, or_info, round_mode} === 4'b1101) ||
                             ({xor_info, or_info, round_mode} === 4'b0110))
    );

// X[3] matches the assigned AND of A[1] and A[0].
    check_x3_equation: assert property (
        @(posedge clk) X[3] == (A[1] & A[0])
    );

// X[2] matches the assigned AND of A[0] and the inverse of A[1].
    check_x2_equation: assert property (
        @(posedge clk) X[2] == (A[0] & (~A[1]))
    );

// X[1] matches the assigned AND of the inverses of A[2] and A[1].
    check_x1_equation: assert property (
        @(posedge clk) X[1] == ((~A[2]) & (~A[1]))
    );

// X[0] matches the assigned AND of the inverses of A[3] and A[2].
    check_x0_equation: assert property (
        @(posedge clk) X[0] == ((~A[3]) & (~A[2]))
    );

// X matches the complete combinational assignment from A.
    check_x_vector_equation: assert property (
        @(posedge clk) X == { (A[1] & A[0]), (A[0] & (~A[1])), ((~A[2]) & (~A[1])), ((~A[3]) & (~A[2])) }
    );

// X[3] and X[2] cannot both be high because they require opposite values of A[1].
    check_upper_bits_mutex: assert property (
        @(posedge clk) !(X[3] && X[2])
    );

// Addition mode updates sum and clears the other outputs.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((sum  == ((A + B) & 4'hF)) &&
                           (diff == 4'h0) &&
                           (prod == 4'h0) &&
                           (quot == 4'h0))
    );

// Subtraction mode updates diff and clears the other outputs.
    check_subtraction_mode: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((sum  == 4'h0) &&
                           (diff == ((A - B) & 4'hF)) &&
                           (prod == 4'h0) &&
                           (quot == 4'h0))
    );

// Division by zero forces quot low and clears the other outputs.
    check_division_by_zero_mode: assert property (
        @(posedge clk)
        ((op == 2'b11) && (B == 4'h0)) |-> ((sum  == 4'h0) &&
                                            (diff == 4'h0) &&
                                            (prod == 4'h0) &&
                                            (quot == 4'h0))
    );

// clk is an external sampling clock because the RTL has no native clock or reset.

    // op=00 returns the truncated sum.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> (result == ((reg_a + reg_b) & 4'hf))
    );

// op=01 returns the truncated difference.
    check_subtract_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> (result == ((reg_a - reg_b) & 4'hf))
    );

// Reset drives the register output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (output_data == 4'b0000)
    );

// Parallel load captures input_data on the next clock.
    check_parallel_load: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load |=> (output_data == $past(input_data))
    );

// Shift moves the stored value left and inserts zero in the LSB.
    check_shift_left: assert property (
        @(posedge clk) disable iff (reset)
        (shift && !parallel_load) |=> (output_data == {$past(output_data[2:0]), 1'b0})
    );

// Parallel load has priority over shift when both are asserted.
    check_load_priority: assert property (
        @(posedge clk) disable iff (reset)
        (parallel_load && shift) |=> (output_data == $past(input_data))
    );

// The register holds its value when neither control is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && !shift) |=> (output_data == $past(output_data))
    );

// gray_out must match the implemented XOR/shift equation.
    check_gray_equation: assert property (
        @(posedge clk) gray_out == (bin_in ^ {bin_in[7], bin_in[7:1]})
    );

// The implemented MSB equation forces gray_out[7] low.
    check_gray_msb_zero: assert property (
        @(posedge clk) gray_out[7] == 1'b0
    );

// The lower seven bits must match adjacent-bit XORs from bin_in.
    check_gray_lower_bits_equation: assert property (
        @(posedge clk) gray_out[6:0] == (bin_in[6:0] ^ bin_in[7:1])
    );

// gray_out[6] is bin_in[6] XOR bin_in[7].
    check_gray_bit6_xor: assert property (
        @(posedge clk) gray_out[6] == (bin_in[6] ^ bin_in[7])
    );

// gray_out[5] is bin_in[5] XOR bin_in[6].
    check_gray_bit5_xor: assert property (
        @(posedge clk) gray_out[5] == (bin_in[5] ^ bin_in[6])
    );

// gray_out[4] is bin_in[4] XOR bin_in[5].
    check_gray_bit4_xor: assert property (
        @(posedge clk) gray_out[4] == (bin_in[4] ^ bin_in[5])
    );

// gray_out[3] is bin_in[3] XOR bin_in[4].
    check_gray_bit3_xor: assert property (
        @(posedge clk) gray_out[3] == (bin_in[3] ^ bin_in[4])
    );

// gray_out[2] is bin_in[2] XOR bin_in[3].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray_out[2] == (bin_in[2] ^ bin_in[3])
    );

// gray_out[1] is bin_in[1] XOR bin_in[2].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_out[1] == (bin_in[1] ^ bin_in[2])
    );

// gray_out[0] is bin_in[0] XOR bin_in[1].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray_out[0] == (bin_in[0] ^ bin_in[1])
    );

// result must equal the bitwise AND of X and Y.
    check_result_matches_bitwise_and: assert property (
        @(posedge clk) result == (X & Y)
    );

// The flag must reflect whether result is at least 5.
    check_flag_matches_result_threshold: assert property (
        @(posedge clk) greater_than_or_equal_to_5 == (result >= 4'd5)
    );

// A high flag implies the result is 5 or greater.
    check_flag_high_implies_result_ge_5: assert property (
        @(posedge clk) greater_than_or_equal_to_5 |-> (result >= 4'd5)
    );

// A low flag implies the result is less than 5.
    check_flag_low_implies_result_lt_5: assert property (
        @(posedge clk) !greater_than_or_equal_to_5 |-> (result < 4'd5)
    );

// The flag must also match the threshold of the ANDed inputs directly.
    check_flag_matches_and_threshold: assert property (
        @(posedge clk) greater_than_or_equal_to_5 == ((X & Y) >= 4'd5)
    );

// Lower pair follows instance a.
    check_lower_pair_drive: assert property (
        @(posedge clk) {Z10[1], Z10[0]} == (OE ? 2'b10 : 2'b01)
    );

// Upper pair follows instance b with inverted OE.
    check_upper_pair_drive: assert property (
        @(posedge clk) {Z10[3], Z10[2]} == (OE ? 2'b01 : 2'b10)
    );

// Middle bits both track OE.
    check_middle_bits_follow_oe: assert property (
        @(posedge clk) {Z10[2], Z10[1]} == {2{OE}}
    );

// Outer bits both track inverted OE.
    check_outer_bits_follow_inverted_oe: assert property (
        @(posedge clk) {Z10[3], Z10[0]} == {2{~OE}}
    );

// OE high produces the full driven bus pattern.
    check_bus_pattern_when_oe_high: assert property (
        @(posedge clk) OE |-> (Z10 == 4'b0110)
    );

// OE low produces the full driven bus pattern.
    check_bus_pattern_when_oe_low: assert property (
        @(posedge clk) !OE |-> (Z10 == 4'b1001)
    );

// In add mode, result is the 4-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) !SUB |-> (result == (A + B))
    );

// In subtract mode, result is the 4-bit difference of A and B.
    check_sub_result: assert property (
        @(posedge clk) SUB |-> (result == (A - B))
    );

// OVFL always matches the MSB of result.
    check_ovfl_matches_result_msb: assert property (
        @(posedge clk) OVFL == result[3]
    );

// The outputs match the selected arithmetic operation every cycle.
    check_selected_operation: assert property (
        @(posedge clk) result == (SUB ? (A - B) : (A + B))
    );

// ENCLK is asserted on the next clock when both EN and TE are high.
    check_enclk_asserts_when_en_and_te_high: assert property (
        @(posedge CLK) (EN && TE) |=> (ENCLK == 1'b1)
    );

// ENCLK is deasserted on the next clock when either EN or TE is low.
    check_enclk_deasserts_when_en_or_te_low: assert property (
        @(posedge CLK) (!EN || !TE) |=> (ENCLK == 1'b0)
    );

// LOAD has highest priority and copies in to OUT.
    check_load_captures_input: assert property (
        @(posedge CLK) LOAD |=> (OUT == $past(in))
    );

// UP increments OUT when LOAD is low and OUT is not at max.
    check_count_up_step: assert property (
        @(posedge CLK) (!LOAD && UP && (OUT != 4'hF)) |=> (OUT == ($past(OUT) + 4'd1))
    );

// UP wraps OUT from 15 to 0 when LOAD is low.
    check_count_up_wrap: assert property (
        @(posedge CLK) (!LOAD && UP && (OUT == 4'hF)) |=> (OUT == 4'h0)
    );

// DOWN decrements OUT when selected and OUT is not zero.
    check_count_down_step: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (OUT != 4'h0)) |=> (OUT == ($past(OUT) - 4'd1))
    );

// DOWN wraps OUT from 0 to 15 when selected.
    check_count_down_wrap: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (OUT == 4'h0)) |=> (OUT == 4'hF)
    );

// OUT holds its value when no control input is asserted.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD && !UP && !DOWN) |=> (OUT == $past(OUT))
    );

// A sampled reset drives the counter to zero by the next clock.
    reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// A count of 9 rolls over to 0 on the next clock.
    count_rolls_over_at_nine: assert property (
        @(posedge clk) disable iff (reset)
            (count == 4'd9) |=> (count == 4'd0)
    );

// Any non-9 count advances by one, or is forced to 0 by async reset.
    count_advances_or_resets_otherwise: assert property (
        @(posedge clk) disable iff (reset)
            (count != 4'd9) |=> ((count == ($past(count) + 4'd1)) || (count == 4'd0))
    );

// Exact 0xFF low-byte pattern maps to 255.
    check_ff_maps_to_255: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFF)) |-> (out == 8'd255)
    );

// Exact 0xFE low-byte pattern maps to 254.
    check_fe_maps_to_254: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFE)) |-> (out == 8'd254)
    );

// Exact 0xFC low-byte pattern maps to 253.
    check_fc_maps_to_253: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFC)) |-> (out == 8'd253)
    );

// Exact 0xF8 low-byte pattern maps to 252.
    check_f8_maps_to_252: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hF8)) |-> (out == 8'd252)
    );

// Exact 0xF0 low-byte pattern maps to 251.
    check_f0_maps_to_251: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hF0)) |-> (out == 8'd251)
    );

// Exact 0xE0 low-byte pattern maps to 250.
    check_e0_maps_to_250: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hE0)) |-> (out == 8'd250)
    );

// Y matches the nested mux equation implemented by the RTL.
    check_full_mux_equation: assert property (
        @(posedge clk)
        Y === ((S1 == 1'b0) ? ((S0 == 1'b0) ? A : B)
                            : ((S0 == 1'b0) ? C : D))
    );

// When S1 is low, Y must come from the A/B mux selected by S0.
    check_lower_pair_when_s1_low: assert property (
        @(posedge clk)
        (S1 === 1'b0) |-> (Y === ((S0 == 1'b0) ? A : B))
    );

// When S1 is high, Y must come from the C/D mux selected by S0.
    check_upper_pair_when_s1_high: assert property (
        @(posedge clk)
        (S1 === 1'b1) |-> (Y === ((S0 == 1'b0) ? C : D))
    );

// Selecting S1=0 and S0=0 routes A to Y.
    check_select_a_path: assert property (
        @(posedge clk)
        ((S1 === 1'b0) && (S0 === 1'b0)) |-> (Y === A)
    );

// Selecting S1=0 and S0=1 routes B to Y.
    check_select_b_path: assert property (
        @(posedge clk)
        ((S1 === 1'b0) && (S0 === 1'b1)) |-> (Y === B)
    );

// Selecting S1=1 and S0=0 routes C to Y.
    check_select_c_path: assert property (
        @(posedge clk)
        ((S1 === 1'b1) && (S0 === 1'b0)) |-> (Y === C)
    );

// Selecting S1=1 and S0=1 routes D to Y.
    check_select_d_path: assert property (
        @(posedge clk)
        ((S1 === 1'b1) && (S0 === 1'b1)) |-> (Y === D)
    );

// Y must equal the AND of all four inputs.
    check_y_matches_four_input_and: assert property (
        @(posedge clk) Y == (A1 & A2 & A3 & A4)
    );

// All inputs high must drive Y high.
    check_y_high_when_all_inputs_high: assert property (
        @(posedge clk) (A1 && A2 && A3 && A4) |-> Y
    );

// A high Y requires all inputs to be high.
    check_y_high_only_when_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A1 && A2 && A3 && A4)
    );

// Any low input must force Y low.
    check_y_low_when_any_input_low: assert property (
        @(posedge clk) (!A1 || !A2 || !A3 || !A4) |-> !Y
    );

// When CTRL is low, C is the 4-bit sum of A and B.
    check_add_mode_sum: assert property (
        @(posedge clk) (CTRL == 1'b0) |-> (C == (A + B))
    );

// When CTRL is high, C is the sum of zero-extended A[3:1] and B[3:1].
    check_shift_mode_sum: assert property (
        @(posedge clk) (CTRL == 1'b1) |-> (C == ({1'b0, A[3:1]} + {1'b0, B[3:1]}))
    );

// In add mode, a zero B operand leaves A unchanged.
    check_add_mode_b_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (B == 4'b0000)) |-> (C == A)
    );

// In add mode, a zero A operand leaves B unchanged.
    check_add_mode_a_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (A == 4'b0000)) |-> (C == B)
    );

// In add mode, overflow wraps to 4 bits on C.
    check_add_mode_overflow_wrap: assert property (
        @(posedge clk) ((CTRL == 1'b0) && (A == 4'hF) && (B == 4'h1)) |-> (C == 4'h0)
    );

// In shifted mode, zero upper bits on B leave zero-extended A[3:1].
    check_shift_mode_b_upper_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (B[3:1] == 3'b000)) |-> (C == {1'b0, A[3:1]})
    );

// In shifted mode, zero upper bits on A leave zero-extended B[3:1].
    check_shift_mode_a_upper_zero_identity: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b000)) |-> (C == {1'b0, B[3:1]})
    );

// In shifted mode, the LSB of C is the sum bit from A[1] and B[1].
    check_shift_mode_lsb: assert property (
        @(posedge clk) (CTRL == 1'b1) |-> (C[0] == (A[1] ^ B[1]))
    );

// In shifted mode, zero upper slices on both operands force C to zero.
    check_shift_mode_upper_zero_gives_zero: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b000) && (B[3:1] == 3'b000)) |-> (C == 4'b0000)
    );

// In shifted mode, carry from the selected upper bits propagates into C[3].
    check_shift_mode_carry_example: assert property (
        @(posedge clk) ((CTRL == 1'b1) && (A[3:1] == 3'b111) && (B[3:1] == 3'b001)) |-> (C == 4'b1000)
    );

// Positive-sign decode cases drive Round_Flag_o high.
    check_round_flag_positive_sign_cases: assert property (
        @(posedge clk)
        (
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10101) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10110) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10111)
        ) |-> (Round_Flag_o == 1'b1)
    );

// Negative-sign decode cases drive Round_Flag_o high.
    check_round_flag_negative_sign_cases: assert property (
        @(posedge clk)
        (
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01001) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01010) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01011)
        ) |-> (Round_Flag_o == 1'b1)
    );

// All unlisted decode cases drive Round_Flag_o low.
    check_round_flag_default_zero: assert property (
        @(posedge clk)
        (
            ({Sign_Result_i, Round_Type_i, Data_i} != 5'b10101) &&
            ({Sign_Result_i, Round_Type_i, Data_i} != 5'b10110) &&
            ({Sign_Result_i, Round_Type_i, Data_i} != 5'b10111) &&
            ({Sign_Result_i, Round_Type_i, Data_i} != 5'b01001) &&
            ({Sign_Result_i, Round_Type_i, Data_i} != 5'b01010) &&
            ({Sign_Result_i, Round_Type_i, Data_i} != 5'b01011)
        ) |-> (Round_Flag_o == 1'b0)
    );

// A high Round_Flag_o only occurs on one of the listed cases.
    check_round_flag_high_only_on_listed_cases: assert property (
        @(posedge clk)
        (Round_Flag_o == 1'b1) |-> (
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10101) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10110) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10111) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01001) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01010) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01011)
        )
    );

// Round_Flag_o matches the complete combinational decode.
    check_round_flag_complete_truth_table: assert property (
        @(posedge clk)
        Round_Flag_o == (
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10101) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10110) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b10111) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01001) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01010) ||
            ({Sign_Result_i, Round_Type_i, Data_i} == 5'b01011)
        )
    );

// reg_in0 captures in0 on the prior clock.
    check_reg_in0_samples_in0: assert property (
        @(posedge clk) 1'b1 |=> (reg_in0 === $past(in0))
    );

// reg_in1 captures in1 on the prior clock.
    check_reg_in1_samples_in1: assert property (
        @(posedge clk) 1'b1 |=> (reg_in1 === $past(in1))
    );

// reg_out encodes less-than for the prior registered inputs.
    check_reg_out_less_than: assert property (
        @(posedge clk) (reg_in0 < reg_in1) |=> (reg_out === 2'b00)
    );

// reg_out encodes equality for the prior registered inputs.
    check_reg_out_equal: assert property (
        @(posedge clk) (reg_in0 == reg_in1) |=> (reg_out === 2'b01)
    );

// reg_out encodes greater-than for the prior registered inputs.
    check_reg_out_greater_than: assert property (
        @(posedge clk) (reg_in0 > reg_in1) |=> (reg_out === 2'b10)
    );

// reg_out always uses one of the implemented encodings after the first update.
    check_reg_out_valid_encoding: assert property (
        @(posedge clk) 1'b1 |=> ((reg_out === 2'b00) || (reg_out === 2'b01) || (reg_out === 2'b10))
    );

// out always mirrors reg_out.
    check_out_mirrors_reg_out: assert property (
        @(posedge clk) (out === reg_out)
    );

// out reports less-than two clocks after the input comparison.
    check_out_less_than_latency: assert property (
        @(posedge clk) (in0 < in1) |-> ##2 (out === 2'b00)
    );

// out reports equality two clocks after the input comparison.
    check_out_equal_latency: assert property (
        @(posedge clk) (in0 == in1) |-> ##2 (out === 2'b01)
    );

// out reports greater-than two clocks after the input comparison.
    check_out_greater_than_latency: assert property (
        @(posedge clk) (in0 > in1) |-> ##2 (out === 2'b10)
    );

// Output must equal the reduction-OR of the input bus.
    check_out_matches_reduction_or: assert property (
        @(posedge clk) out == (|in)
    );

// A zero input vector must drive the output low.
    check_zero_input_drives_low: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 1'b0)
    );

// Any non-zero input vector must drive the output high.
    check_nonzero_input_drives_high: assert property (
        @(posedge clk) (in != 4'b0000) |-> (out == 1'b1)
    );

// Y must implement ~( (A & B) | (C & D) ).
    check_output_equation: assert property (
        @(posedge clk) Y == ~((A & B) | (C & D))
    );

// If A and B are both HIGH, Y must be LOW.
    check_ab_pair_forces_low: assert property (
        @(posedge clk) ((A & B) == 1'b1) |-> (Y == 1'b0)
    );

// If C and D are both HIGH, Y must be LOW.
    check_cd_pair_forces_low: assert property (
        @(posedge clk) ((C & D) == 1'b1) |-> (Y == 1'b0)
    );

// If neither pair is HIGH together, Y must be HIGH.
    check_no_pair_high_drives_high: assert property (
        @(posedge clk) (((A & B) == 1'b0) && ((C & D) == 1'b0)) |-> (Y == 1'b1)
    );

// A LOW Y requires at least one HIGH input pair.
    check_low_output_has_active_pair: assert property (
        @(posedge clk) (Y == 1'b0) |-> (((A & B) == 1'b1) || ((C & D) == 1'b1))
    );

// Output matches a logical left shift of D by A.
    check_shift_relation: assert property (
        @(posedge clk) S == (D << A)
    );

// A value of 0 passes D through unchanged.
    check_shift_by_0: assert property (
        @(posedge clk) (A == 2'b00) |-> (S == D)
    );

// A value of 1 shifts D left by 1 with zero fill.
    check_shift_by_1: assert property (
        @(posedge clk) (A == 2'b01) |-> (S == {D[2:0], 1'b0})
    );

// A value of 2 shifts D left by 2 with zero fill.
    check_shift_by_2: assert property (
        @(posedge clk) (A == 2'b10) |-> (S == {D[1:0], 2'b00})
    );

// A value of 3 shifts D left by 3 with zero fill.
    check_shift_by_3: assert property (
        @(posedge clk) (A == 2'b11) |-> (S == {D[0], 3'b000})
    );

// out1 must match the RTL expression driven from in1 and T.
    check_out1_matches_rtl: assert property (
        @(posedge clk)
        out1 == (($signed(((in1 < 0) ? -in1 : in1)) <= T) ? in1 : $signed(((in1 < 0) ? -T : T)))
    );

// out2 must match the RTL expression driven from in2 and T.
    check_out2_matches_rtl: assert property (
        @(posedge clk)
        out2 == (($signed(((in2 < 0) ? -in2 : in2)) <= T) ? in2 : $signed(((in2 < 0) ? -T : T)))
    );

// If in1 is within the signed threshold comparison, out1 passes through.
    check_out1_passthrough: assert property (
        @(posedge clk)
        ($signed(((in1 < 0) ? -in1 : in1)) <= T) |-> (out1 == in1)
    );

// If in2 is within the signed threshold comparison, out2 passes through.
    check_out2_passthrough: assert property (
        @(posedge clk)
        ($signed(((in2 < 0) ? -in2 : in2)) <= T) |-> (out2 == in2)
    );

// If in1 exceeds the signed threshold comparison, out1 selects T or -T.
    check_out1_clamps_to_threshold_value: assert property (
        @(posedge clk)
        ($signed(((in1 < 0) ? -in1 : in1)) > T) |-> (out1 == $signed(((in1 < 0) ? -T : T)))
    );

// If in2 exceeds the signed threshold comparison, out2 selects T or -T.
    check_out2_clamps_to_threshold_value: assert property (
        @(posedge clk)
        ($signed(((in2 < 0) ? -in2 : in2)) > T) |-> (out2 == $signed(((in2 < 0) ? -T : T)))
    );

// Equal channel inputs must produce equal channel outputs.
    check_equal_inputs_produce_equal_outputs: assert property (
        @(posedge clk)
        (in1 == in2) |-> (out1 == out2)
    );

// Reset forces out low.
    check_reset_forces_out_low: assert property (
        @(posedge clock)
        (reset == 1'b1) |-> (out == 1'b0)
    );

// Clear forces out high when reset is not asserted.
    check_clear_forces_out_high: assert property (
        @(posedge clock) disable iff (reset)
        (clear == 1'b1) |-> (out == 1'b1)
    );

// X matches the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) X == ((A0 & ~S) | (A1 & S))
    );

// When S is low, X selects A0.
    check_select_a0_when_s_low: assert property (
        @(posedge clk) (S == 1'b0) |-> (X == A0)
    );

// When S is high, X selects A1.
    check_select_a1_when_s_high: assert property (
        @(posedge clk) (S == 1'b1) |-> (X == A1)
    );

// If both data inputs are low, X is low.
    check_output_low_when_both_inputs_low: assert property (
        @(posedge clk) ((A0 == 1'b0) && (A1 == 1'b0)) |-> (X == 1'b0)
    );

// If both data inputs are high, X is high.
    check_output_high_when_both_inputs_high: assert property (
        @(posedge clk) ((A0 == 1'b1) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

// If both data inputs match, X equals that common value.
    check_output_matches_common_input: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

// With A0 low and A1 high, X follows S.
    check_output_follows_s_for_01_inputs: assert property (
        @(posedge clk) ((A0 == 1'b0) && (A1 == 1'b1)) |-> (X == S)
    );

// With A0 high and A1 low, X follows inverted S.
    check_output_follows_not_s_for_10_inputs: assert property (
        @(posedge clk) ((A0 == 1'b1) && (A1 == 1'b0)) |-> (X == ~S)
    );

// Synchronous reset forces count to zero on the following clock.
    reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 3'b000)
    );

// On consecutive non-reset cycles, count increments by one.
    count_advances_by_one: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 3'd1))
    );

// The 3-bit counter wraps from 7 back to 0.
    count_wraps_from_max: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b111) |=> (count == 3'b000)
    );

// 00 selects A.
    check_select_00_routes_a: assert property (
        @(posedge clk) ((S1 == 1'b0) && (S0 == 1'b0)) |-> (X == A)
    );

// 01 selects B.
    check_select_01_routes_b: assert property (
        @(posedge clk) ((S1 == 1'b0) && (S0 == 1'b1)) |-> (X == B)
    );

// 10 selects C.
    check_select_10_routes_c: assert property (
        @(posedge clk) ((S1 == 1'b1) && (S0 == 1'b0)) |-> (X == C)
    );

// 11 selects D.
    check_select_11_routes_d: assert property (
        @(posedge clk) ((S1 == 1'b1) && (S0 == 1'b1)) |-> (X == D)
    );

// No carry-out passes through the low 8-bit sum.
    check_no_carry_passthrough: assert property (
        @(posedge clk) !temp_sum[8] |-> (sum == temp_sum[7:0] && cout == 1'b0)
    );

// Carry-out with temp_sum[7] low saturates sum to 8'h7F.
    check_carry_msb0_saturates_7f: assert property (
        @(posedge clk) (temp_sum[8] && !temp_sum[7]) |-> (sum == 8'h7F && cout == 1'b1)
    );

// Carry-out with temp_sum[7] high saturates sum to 8'h80.
    check_carry_msb1_saturates_80: assert property (
        @(posedge clk) (temp_sum[8] && temp_sum[7]) |-> (sum == 8'h80 && cout == 1'b1)
    );

// cout matches the carry-out bit of the addition.
    check_cout_matches_carry: assert property (
        @(posedge clk) cout == temp_sum[8]
    );

// sum always matches the RTL's selected output value.
    check_sum_matches_selected_result: assert property (
        @(posedge clk) sum == (temp_sum[8] ? (temp_sum[7] ? 8'h80 : 8'h7F) : temp_sum[7:0])
    );

// X must equal the OR of all four inputs.
    check_output_matches_or_function: assert property (
        @(posedge clk) X == (A | B | C | D)
    );

// If any input is HIGH, X must be HIGH.
    check_output_high_when_any_input_high: assert property (
        @(posedge clk) (A | B | C | D) |-> X
    );

// If all inputs are LOW, X must be LOW.
    check_output_low_when_all_inputs_low: assert property (
        @(posedge clk) !(A | B | C | D) |-> !X
    );

// If X is HIGH, at least one input must be HIGH.
    check_output_high_implies_some_input_high: assert property (
        @(posedge clk) X |-> (A | B | C | D)
    );

// X implements the OR-then-AND logic function.
    check_x_matches_logic_function: assert property (
        @(posedge clk) X == ((A1 || A2) && B1 && C1 && D1)
    );

// A high X requires B1 to be high.
    check_x_high_requires_b1: assert property (
        @(posedge clk) X |-> B1
    );

// A high X requires C1 to be high.
    check_x_high_requires_c1: assert property (
        @(posedge clk) X |-> C1
    );

// A high X requires D1 to be high.
    check_x_high_requires_d1: assert property (
        @(posedge clk) X |-> D1
    );

// A high X requires at least one A input to be high.
    check_x_high_requires_a1_or_a2: assert property (
        @(posedge clk) X |-> (A1 || A2)
    );

// All required terms high drive X high.
    check_all_terms_high_drive_x: assert property (
        @(posedge clk) ((A1 || A2) && B1 && C1 && D1) |-> X
    );

// If both A inputs are low, X must be low.
    check_both_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// If B1 is low, X must be low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// If C1 is low, X must be low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// If D1 is low, X must be low.
    check_d1_low_forces_x_low: assert property (
        @(posedge clk) !D1 |-> !X
    );

// Output must follow the RTL's add/subtract function for all input values.
    check_function_relation: assert property (
        @(posedge clk)
        out == ((in <= 4'd7) ? (in + 4'd3) : (in - 4'd3))
    );

// Inputs 0 through 7 must take the add-by-3 branch.
    check_add_branch: assert property (
        @(posedge clk)
        (in <= 4'd7) |-> (out == (in + 4'd3))
    );

// Inputs 8 through 15 must take the subtract-by-3 branch.
    check_subtract_branch: assert property (
        @(posedge clk)
        (in > 4'd7) |-> (out == (in - 4'd3))
    );

// The lower boundary of the add branch must map 0 to 3.
    check_zero_boundary: assert property (
        @(posedge clk)
        (in == 4'd0) |-> (out == 4'd3)
    );

// The upper boundary of the add branch must map 7 to 10.
    check_seven_boundary: assert property (
        @(posedge clk)
        (in == 4'd7) |-> (out == 4'd10)
    );

// The lower boundary of the subtract branch must map 8 to 5.
    check_eight_boundary: assert property (
        @(posedge clk)
        (in == 4'd8) |-> (out == 4'd5)
    );

// The upper input value must map 15 to 12.
    check_fifteen_boundary: assert property (
        @(posedge clk)
        (in == 4'd15) |-> (out == 4'd12)
    );

// The computed output must always remain within the implemented numeric range.
    check_output_range: assert property (
        @(posedge clk)
        (out >= 4'd3) && (out <= 4'd12)
    );

// A sampled reset forces the output low by the next clock.
    check_reset_clears_output_by_next_clock: assert property (
        @(posedge clk) rst |=> (data_out == 1'b0)
    );

// The first clock after reset release still has a low output.
    check_first_clock_after_reset_release_is_low: assert property (
        @(posedge clk) (rst ##1 !rst) |-> (data_out == 1'b0)
    );

// The second clock after reset release still has a low output.
    check_second_clock_after_reset_release_is_low: assert property (
        @(posedge clk) (rst ##1 !rst ##1 !rst) |-> (data_out == 1'b0)
    );

// Without reset interruption, data_out is data_in delayed by two clocks.
    check_two_cycle_input_to_output_delay: assert property (
        p_two_cycle_input_to_output_delay
    );

// Valid output always matches the state output.
    check_valid_matches_state: assert property (
        @(posedge clk)
        v_d_m_areg_flits == d_m_areg_state
    );

// Reset synchronously clears data and deasserts valid/state.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        rst |=> (!v_d_m_areg_flits && !d_m_areg_state && (d_m_areg_flits == 176'h0))
    );

// mem_done_access synchronously clears data and deasserts valid/state.
    check_mem_done_clears_outputs: assert property (
        @(posedge clk)
        mem_done_access |=> (!v_d_m_areg_flits && !d_m_areg_state && (d_m_areg_flits == 176'h0))
    );

// A valid input load sets state and valid on the next cycle.
    check_load_sets_state_and_valid: assert property (
        @(posedge clk) disable iff (rst)
        (!mem_done_access && v_d_flits_m) |=> (d_m_areg_state && v_d_m_areg_flits)
    );

// A valid input load captures the lower 144 bits on the next cycle.
    check_load_captures_lower_flits: assert property (
        @(posedge clk) disable iff (rst)
        (!mem_done_access && v_d_flits_m) |=> (d_m_areg_flits[143:0] == $past(d_flits_m))
    );

// A valid input load zero-extends the upper 32 bits.
    check_load_zero_extends_upper_flits: assert property (
        @(posedge clk) disable iff (rst)
        (!mem_done_access && v_d_flits_m) |=> (d_m_areg_flits[175:144] == 32'h0)
    );

// Without a clear or load, the outputs hold their previous values.
    check_idle_holds_outputs: assert property (
        @(posedge clk) disable iff (rst)
        (!mem_done_access && !v_d_flits_m) |=> ($stable(d_m_areg_flits) &&
                                                $stable(v_d_m_areg_flits) &&
                                                $stable(d_m_areg_state))
    );

// Once set, state and valid remain asserted until a clear occurs.
    check_state_is_sticky_until_clear: assert property (
        @(posedge clk) disable iff (rst)
        (d_m_areg_state && !mem_done_access) |=> (d_m_areg_state && v_d_m_areg_flits)
    );

// Y must always be the inversion of A.
    check_inverter_function: assert property (
        @(posedge clk) Y === ~A
    );

// A rising at the sample point must drive Y low.
    check_a_rise_drives_y_low: assert property (
        @(posedge clk) $rose(A) |-> (Y === 1'b0)
    );

// A falling at the sample point must drive Y high.
    check_a_fall_drives_y_high: assert property (
        @(posedge clk) $fell(A) |-> (Y === 1'b1)
    );

// Carry-out is the majority function of a, b, and cin.
    check_cout_majority: assert property (
        @(posedge clk)
        cout == ((a & b) | (a & cin) | (b & cin))
    );

// Sum matches the combinational function implemented by the RTL.
    check_sum_function: assert property (
        @(posedge clk)
        sum == (cin ? ~(a ^ b) : (a | b))
    );

// With cin low, sum becomes OR and carry becomes AND of a and b.
    check_cin_low_behavior: assert property (
        @(posedge clk)
        !cin |-> ((sum == (a | b)) && (cout == (a & b)))
    );

// With cin high, sum becomes XNOR and carry becomes OR of a and b.
    check_cin_high_behavior: assert property (
        @(posedge clk)
        cin |-> ((sum == ~(a ^ b)) && (cout == (a | b)))
    );

// When both data inputs are low, carry is low and sum follows cin.
    check_ab_zero_behavior: assert property (
        @(posedge clk)
        (!a && !b) |-> ((!cout) && (sum == cin))
    );

// When the data inputs differ, carry follows cin and sum inverts cin.
    check_ab_different_behavior: assert property (
        @(posedge clk)
        (a ^ b) |-> ((cout == cin) && (sum == ~cin))
    );

// When both data inputs are high, both outputs are high.
    check_ab_one_behavior: assert property (
        @(posedge clk)
        (a && b) |-> (cout && sum)
    );

// In add mode, Q equals A + B + CIN.
    check_add_mode_result: assert property (
        @(posedge clk) (MODE == 1'b0) |-> (Q == (A + B + CIN))
    );

// In subtract mode, Q equals A - B - CIN.
    check_subtract_mode_result: assert property (
        @(posedge clk) (MODE == 1'b1) |-> (Q == (A - B - CIN))
    );

// With B and CIN cleared, the output passes A through.
    check_passthrough_when_b_and_cin_zero: assert property (
        @(posedge clk) (B == 16'h0000 && CIN == 1'b0) |-> (Q == A)
    );

// With all arithmetic inputs zero, the output is zero.
    check_zero_result_for_zero_inputs: assert property (
        @(posedge clk) (A == 16'h0000 && B == 16'h0000 && CIN == 1'b0) |-> (Q == 16'h0000)
    );

// Subtracting equal operands with no borrow-in yields zero.
    check_subtract_equal_operands_zero: assert property (
        @(posedge clk) (MODE == 1'b1 && A == B && CIN == 1'b0) |-> (Q == 16'h0000)
    );

// Reset drives the outputs to zero by the next clock sample.
    check_reset_clears_outputs: assert property (
        @(posedge CLOCK)
        Reset |=> (Q == 8'd0 && TerminalCount == 1'b0)
    );

// Hold mode keeps Q unchanged and clears TerminalCount.
    check_hold_mode: assert property (
        @(posedge CLOCK) disable iff (Reset)
        ({S1, S0} == 2'b00) |=> (Q == $past(Q) && TerminalCount == 1'b0)
    );

// Count-up mode increments Q when it is not at EndCount.
    check_count_up_increment: assert property (
        @(posedge CLOCK) disable iff (Reset)
        ({S1, S0} == 2'b01 && Q != EndCount) |=> (Q == ($past(Q) + 8'd1) && TerminalCount == 1'b0)
    );

// Count-up mode wraps to BeginCount and raises TerminalCount at EndCount.
    check_count_up_wrap: assert property (
        @(posedge CLOCK) disable iff (Reset)
        ({S1, S0} == 2'b01 && Q == EndCount) |=> (Q == $past(BeginCount) && TerminalCount == 1'b1)
    );

// Count-down mode decrements Q when it is not at BeginCount.
    check_count_down_decrement: assert property (
        @(posedge CLOCK) disable iff (Reset)
        ({S1, S0} == 2'b10 && Q != BeginCount) |=> (Q == ($past(Q) - 8'd1) && TerminalCount == 1'b0)
    );

// Count-down mode wraps to EndCount and raises TerminalCount at BeginCount.
    check_count_down_wrap: assert property (
        @(posedge CLOCK) disable iff (Reset)
        ({S1, S0} == 2'b10 && Q == BeginCount) |=> (Q == $past(EndCount) && TerminalCount == 1'b1)
    );

// Parallel load mode loads P into Q and clears TerminalCount.
    check_parallel_load: assert property (
        @(posedge CLOCK) disable iff (Reset)
        ({S1, S0} == 2'b11) |=> (Q == $past(P) && TerminalCount == 1'b0)
    );

// Output matches the full 4-to-1 mux equation.
    check_full_mux_function: assert property (
        @(posedge clk) y == (s1 ? (s0 ? d : c) : (s0 ? b : a))
    );

// When s1 is low, y comes from the a/b mux selected by s0.
    check_lower_half_selected: assert property (
        @(posedge clk) !s1 |-> (y == (s0 ? b : a))
    );

// When s1 is high, y comes from the c/d mux selected by s0.
    check_upper_half_selected: assert property (
        @(posedge clk) s1 |-> (y == (s0 ? d : c))
    );

// When s0 is low, y selects between a and c using s1.
    check_s0_low_path: assert property (
        @(posedge clk) !s0 |-> (y == (s1 ? c : a))
    );

// When s0 is high, y selects between b and d using s1.
    check_s0_high_path: assert property (
        @(posedge clk) s0 |-> (y == (s1 ? d : b))
    );

// a high AND result reaches out after three cycles.
    check_out_latency_high: assert property (
        @(posedge clk) (a & b) |=> ##2 out
    );

// a low AND result reaches out after three cycles.
    check_out_latency_low: assert property (
        @(posedge clk) !(a & b) |=> ##2 !out
    );

// Reset clears the registered outputs and final_output on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (q_reg == 8'b0) && (q_count == 3'b0) && (final_output == 8'b0)
    );

// q_reg takes the current d value on each non-reset clock.
    check_q_reg_captures_d: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q_reg == $past(d))
    );

// q_count adds d[2:0] modulo 8 on each non-reset clock.
    check_q_count_accumulates_low_bits: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q_count == $past(q_count + d[2:0]))
    );

// q_count holds when the low three bits of d are zero.
    check_q_count_holds_on_zero_addend: assert property (
        @(posedge clk) disable iff (reset) (d[2:0] == 3'b000) |=> (q_count == $past(q_count))
    );

// q_count wraps from 7 to 0 when adding 1.
    check_q_count_wraps_on_overflow: assert property (
        @(posedge clk) disable iff (reset) (q_count == 3'b111 && d[2:0] == 3'b001) |=> (q_count == 3'b000)
    );

// final_output matches q_reg masked by the zero-extended q_count.
    check_final_output_mask_relation: assert property (
        @(posedge clk) disable iff (reset) (final_output == (q_reg & {5'b0, q_count}))
    );

// final_output upper five bits are always zero.
    check_final_output_upper_bits_zero: assert property (
        @(posedge clk) disable iff (reset) (final_output[7:3] == 5'b0)
    );

// A sampled 1 on D is captured into Q on the next clock when reset stays low.
    check_capture_one: assert property (
        @(posedge CLK) disable iff (RESET) D |=> (Q == 1'b1)
    );

// A sampled 0 on D is captured into Q on the next clock when reset stays low.
    check_capture_zero: assert property (
        @(posedge CLK) disable iff (RESET) !D |=> (Q == 1'b0)
    );

// A reset seen on a clock keeps Q low at the following clock.
    check_reset_seen_on_clock_keeps_q_low: assert property (
        @(posedge CLK) RESET |=> (Q == 1'b0)
    );

// A reset assertion between clocks clears Q by the next clock edge.
    check_async_reset_clears_q_by_next_clock: assert property (
        @(posedge RESET) 1'b1 |=> @(posedge CLK) (Q == 1'b0)
    );

// Active-low reset clears the counter output.
    check_reset_clears_out: assert property (
        @(posedge clk) !rst |-> (out == 4'b0000)
    );

// Enabled cycles increment the counter by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> (out == ($past(out) + 4'd1))
    );

// Disabled cycles hold the counter value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst)
        !en |=> (out == $past(out))
    );

// The next state follows the prior cycle's enable.
    check_next_state_follows_enable: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (out == ($past(en) ? ($past(out) + 4'd1) : $past(out)))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_wrap_on_overflow: assert property (
        @(posedge clk) disable iff (!rst)
        (en && (out == 4'hF)) |=> (out == 4'h0)
    );

// When S is exactly 0, X must follow A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) (S === 1'b0) |-> (X === A0)
    );

// When S is not exactly 0, X must follow A1.
    check_select_not_low_routes_a1: assert property (
        @(posedge clk) (S !== 1'b0) |-> (X === A1)
    );

// When disabled, the output is forced to zero.
    check_output_zero_when_disabled: assert property (
        @(posedge clk) !EN |-> (Y == 8'b0)
    );

// When enabled and SEL selects D0, the output matches D0.
    check_select_d0_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b00)) |-> (Y == D0)
    );

// When enabled and SEL selects D1, the output matches D1.
    check_select_d1_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b01)) |-> (Y == D1)
    );

// When enabled and SEL selects D2, the output matches D2.
    check_select_d2_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b10)) |-> (Y == D2)
    );

// When enabled and SEL selects D3, the output matches D3.
    check_select_d3_when_enabled: assert property (
        @(posedge clk) (EN && (SEL == 2'b11)) |-> (Y == D3)
    );

// Clock: CLK; reset: RST is active-high and synchronous.
    // Function: sequential DFF with reset priority, then set, then D capture.

    // When reset is asserted on a rising clock edge, Q clears low.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |=> (Q == 1'b0)
    );

// When SET is asserted without reset, Q is driven high.
    check_set_sets_q: assert property (
        @(posedge CLK) disable iff (RST) SET |=> (Q == 1'b1)
    );

// With no control active and D high, Q captures a 1.
    check_data_high_captures_q: assert property (
        @(posedge CLK) disable iff (RST) (!SET && D) |=> (Q == 1'b1)
    );

// With no control active and D low, Q captures a 0.
    check_data_low_captures_q: assert property (
        @(posedge CLK) disable iff (RST) (!SET && !D) |=> (Q == 1'b0)
    );

// Output matches bitwise invert plus one.
    check_twos_complement_exact: assert property (
        @(posedge clk) twos_complement_output == (~binary_input + 4'b0001)
    );

// Output is the 4-bit arithmetic negation of the input.
    check_arithmetic_negation: assert property (
        @(posedge clk) twos_complement_output == (4'b0000 - binary_input)
    );

// Zero is its own two's complement.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (binary_input == 4'b0000) |-> (twos_complement_output == 4'b0000)
    );

// 4'b1000 is its own two's complement in 4 bits.
    check_most_negative_self_inverse: assert property (
        @(posedge clk) (binary_input == 4'b1000) |-> (twos_complement_output == 4'b1000)
    );

// Nonzero inputs sum with their two's complement to zero modulo 16.
    check_nonzero_sum_wraps_to_zero: assert property (
        @(posedge clk) (binary_input != 4'b0000) |-> ((twos_complement_output + binary_input) == 4'b0000)
    );

// clk is the only clock.
    // clear is a synchronous active-high clear.
    // The logic is sequential; op selects add, sub, mul, or div.

    // Clear forces result to zero.
    check_clear_sets_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        clear |=> (result == 8'h00)
    );

// op=00 updates result with a+b.
    check_add_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (!clear && (op == 2'b00)) |=> (result == (($past(a) + $past(b)) & 8'hFF))
    );

// op=01 updates result with a-b.
    check_sub_result: assert property (
        @(posedge clk) disable iff (1'b0)
        (!clear && (op == 2'b01)) |=> (result == (($past(a) - $past(b)) & 8'hFF))
    );

// data_out is always zero or one-hot.
    check_data_out_onehot0: assert property (
        @(posedge clk) disable iff (1'b0)
        $onehot0(data_out)
    );

// Only bits 1, 2, 4, 8, and 16 can ever be set.
    check_data_out_valid_bit_positions: assert property (
        @(posedge clk) disable iff (1'b0)
        ((data_out & ~32'h00010116) == 32'h00000000)
    );

// Bit 0 is never driven high by this RTL.
    check_data_out_bit0_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (data_out[0] == 1'b0)
    );

// encode_in == 0 selects bit 1.
    check_encode_0_pattern: assert property (
        @(posedge clk) disable iff (1'b0)
        (encode_in == 5'd0) |-> (data_out == 32'h00000002)
    );

// encode_in == 1 selects bit 2.
    check_encode_1_pattern: assert property (
        @(posedge clk) disable iff (1'b0)
        (encode_in == 5'd1) |-> (data_out == 32'h00000004)
    );

// encode_in == 2 selects bit 4.
    check_encode_2_pattern: assert property (
        @(posedge clk) disable iff (1'b0)
        (encode_in == 5'd2) |-> (data_out == 32'h00000010)
    );

// encode_in == 3 selects bit 8.
    check_encode_3_pattern: assert property (
        @(posedge clk) disable iff (1'b0)
        (encode_in == 5'd3) |-> (data_out == 32'h00000100)
    );

// encode_in == 4 selects bit 16.
    check_encode_4_pattern: assert property (
        @(posedge clk) disable iff (1'b0)
        (encode_in == 5'd4) |-> (data_out == 32'h00010000)
    );

// encode_in values 5 through 31 leave data_out at zero.
    check_encode_ge5_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (encode_in >= 5'd5) |-> (data_out == 32'h00000000)
    );

// EQ must reflect equality of A and B.
    check_eq_definition: assert property (
        @(posedge clk) EQ == (A == B)
    );

// GT must reflect unsigned greater-than of A over B.
    check_gt_definition: assert property (
        @(posedge clk) GT == (A > B)
    );

// LT must reflect unsigned less-than of A under B.
    check_lt_definition: assert property (
        @(posedge clk) LT == (A < B)
    );

// EQ and GT cannot be high together.
    check_eq_excludes_gt: assert property (
        @(posedge clk) !(EQ && GT)
    );

// EQ and LT cannot be high together.
    check_eq_excludes_lt: assert property (
        @(posedge clk) !(EQ && LT)
    );

// GT and LT cannot be high together.
    check_gt_excludes_lt: assert property (
        @(posedge clk) !(GT && LT)
    );

// One comparison result must always be true.
    check_total_order_covered: assert property (
        @(posedge clk) (EQ || GT || LT)
    );

// Equal inputs must drive only EQ high.
    check_equal_case_outputs: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

// A greater than B must drive only GT high.
    check_greater_case_outputs: assert property (
        @(posedge clk) (A > B) |-> (GT && !EQ && !LT)
    );

// A less than B must drive only LT high.
    check_less_case_outputs: assert property (
        @(posedge clk) (A < B) |-> (LT && !EQ && !GT)
    );

// Enabled counter increments by one on the next clock.
    check_counter_increments_on_enable: assert property (
        @(posedge clk) disable iff (!reset)
        enable |=> (counter == ($past(counter) + 4'd1))
    );

// Disabled counter holds its value on the next clock.
    check_counter_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        !enable |=> (counter == $past(counter))
    );

// Counter wraps from 4'hF to 4'h0 when enabled.
    check_counter_wraps_after_max: assert property (
        @(posedge clk) disable iff (!reset)
        (enable && (counter == 4'hF)) |=> (counter == 4'h0)
    );

// Select high makes q follow data_in.
    check_q_selects_data_in: assert property (
        @(posedge clk) disable iff (!reset)
        select |-> (q == data_in)
    );

// Select low and control high make q drive 8'hFF.
    check_q_selects_ff_on_control: assert property (
        @(posedge clk) disable iff (!reset)
        (!select && control) |-> (q == 8'hFF)
    );

// Select low and control low make q drive the zero-extended counter.
    check_q_selects_counter_on_control_low: assert property (
        @(posedge clk) disable iff (!reset)
        (!select && !control) |-> (q == {4'h0, counter})
    );

// During reset, the counter path drives zero on q.
    check_q_counter_path_zero_during_reset: assert property (
        @(posedge clk) (!reset && !select && !control) |-> (q == 8'h00)
    );

// Reset drives q to zero by the following clock edge.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |=> (q == 4'b0000)
    );

// When enabled, q increments by one on the next clock.
    check_increment_when_enabled: assert property (
        @(posedge CLK) disable iff (RST)
        EN |=> (q == ($past(q) + 4'd1))
    );

// When disabled, q holds its value on the next clock.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RST)
        !EN |=> (q == $past(q))
    );

// A terminal count increment wraps q from 4'hF to 4'h0.
    check_wrap_from_max_count: assert property (
        @(posedge CLK) disable iff (RST)
        EN && (q == 4'hF) |=> (q == 4'h0)
    );

// Select value 00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b00) |-> (out === in0)
    );

// Select value 01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b01) |-> (out === in1)
    );

// Select value 10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b10) |-> (out === in2)
    );

// Select value 11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b11) |-> (out === in3)
    );

// Start high drives the kill switch on the next cycle.
    check_start_high_sets_kill_sw: assert property (
        @(posedge clk)
        start |=> (kill_sw == 1'b1)
    );

// Reset clears the counter on the next clocked state.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// When not in reset, the counter increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (count == ($past(count) + 4'd1))
    );

// When not in reset, the counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

// SUM[0] matches the first full adder with zero carry-in.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0])
    );

// SUM[1] matches the second stage using the bit-0 carry.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

// SUM[2] matches the third stage using the propagated carry.
    check_sum_bit2: assert property (
        @(posedge clk)
        SUM[2] == (A[2] ^ B[2] ^
                   ((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))))
    );

// SUM[3] matches the fourth stage using the propagated carry.
    check_sum_bit3: assert property (
        @(posedge clk)
        SUM[3] == (A[3] ^ B[3] ^
                   ((A[2] & B[2]) |
                    (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) &
                     (A[2] ^ B[2]))))
    );

// SUM matches 4-bit addition with overflow discarded.
    check_sum_matches_addition: assert property (
        @(posedge clk) SUM == (A + B)
    );

// Reset forces q low and qn high.
    check_reset_values: assert property (
        @(posedge clk) reset |=> (q == 1'b0 && qn == 1'b1)
    );

// Set forces q high and qn low when reset is not asserted.
    check_set_values: assert property (
        @(posedge clk) disable iff (reset) set |=> (q == 1'b1 && qn == 1'b0)
    );

// Data 1 is captured when neither reset nor set is asserted.
    check_capture_d_high: assert property (
        @(posedge clk) disable iff (reset) (!set && d) |=> (q == 1'b1 && qn == 1'b0)
    );

// Data 0 is captured when neither reset nor set is asserted.
    check_capture_d_low: assert property (
        @(posedge clk) disable iff (reset) (!set && !d) |=> (q == 1'b0 && qn == 1'b1)
    );

// q and qn remain complementary after each non-reset clock.
    check_complementary_outputs: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (qn == ~q)
    );

// EQ must match the RTL compare equation.
    check_eq_matches_rtl_equation: assert property (
        @(posedge clk) EQ === ~(|(A ^ B))
    );

// No bit differences must drive EQ high.
    check_no_bit_difference_sets_eq: assert property (
        @(posedge clk) (~(|(A ^ B))) |-> (EQ === 1'b1)
    );

// Any bit difference must drive EQ low.
    check_any_bit_difference_clears_eq: assert property (
        @(posedge clk) (|(A ^ B)) |-> (EQ === 1'b0)
    );

// EQ high implies the inputs have no differing bits.
    check_eq_high_implies_no_bit_difference: assert property (
        @(posedge clk) (EQ === 1'b1) |-> (~(|(A ^ B)))
    );

// EQ low implies at least one input bit differs.
    check_eq_low_implies_bit_difference: assert property (
        @(posedge clk) (EQ === 1'b0) |-> (|(A ^ B))
    );

// out[0] is asserted only for input 3'b000.
    check_out0_decode: assert property (
        @(posedge clk) out[0] == (~in[2] & ~in[1] & ~in[0])
    );

// out[1] is asserted only for input 3'b001.
    check_out1_decode: assert property (
        @(posedge clk) out[1] == (~in[2] & ~in[1] &  in[0])
    );

// out[2] is asserted only for input 3'b010.
    check_out2_decode: assert property (
        @(posedge clk) out[2] == (~in[2] &  in[1] & ~in[0])
    );

// out[3] is asserted only for input 3'b011.
    check_out3_decode: assert property (
        @(posedge clk) out[3] == (~in[2] &  in[1] &  in[0])
    );

// out[4] is asserted only for input 3'b100.
    check_out4_decode: assert property (
        @(posedge clk) out[4] == ( in[2] & ~in[1] & ~in[0])
    );

// out[5] is asserted only for input 3'b101.
    check_out5_decode: assert property (
        @(posedge clk) out[5] == ( in[2] & ~in[1] &  in[0])
    );

// out[6] is asserted only for input 3'b110.
    check_out6_decode: assert property (
        @(posedge clk) out[6] == ( in[2] &  in[1] & ~in[0])
    );

// out[7] is asserted only for input 3'b111.
    check_out7_decode: assert property (
        @(posedge clk) out[7] == ( in[2] &  in[1] &  in[0])
    );

// The decoder output is always exactly one-hot.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// The full output vector matches a left-shifted one-hot decode of input.
    check_full_vector_decode: assert property (
        @(posedge clk) out == (8'b0000_0001 << in)
    );

// Outputs are forced low when enable is deasserted.
    check_outputs_zero_when_disabled: assert property (
        @(posedge clk) !en |-> (sum == 4'b0000 && carry == 1'b0)
    );

// Sum matches the 4-bit addition when enable is asserted.
    check_sum_matches_addition_when_enabled: assert property (
        @(posedge clk) en |-> (sum == (a + b))
    );

// Carry matches the implemented masked MSB behavior when enabled.
    check_carry_matches_a_msb_when_enabled: assert property (
        @(posedge clk) en |-> (carry == a[3])
    );

// Sum always follows the enable-gated combinational equation.
    check_sum_function: assert property (
        @(posedge clk) sum == (en ? (a + b) : 4'b0000)
    );

// Carry always follows the enable-gated combinational equation.
    check_carry_function: assert property (
        @(posedge clk) carry == (en ? a[3] : 1'b0)
    );

// 0 - 0 - 0 gives zero difference and no borrow.
    check_zero_minus_zero_no_borrowin: assert property (
        @(posedge clk) (!A && !B && !Bin) |-> (D == 1'b0 && Bout == 1'b0)
    );

// 0 - 1 - 0 gives difference one and borrow one.
    check_zero_minus_one_no_borrowin: assert property (
        @(posedge clk) (!A && B && !Bin) |-> (D == 1'b1 && Bout == 1'b1)
    );

// 1 - 0 - 0 gives difference one and no borrow.
    check_one_minus_zero_no_borrowin: assert property (
        @(posedge clk) (A && !B && !Bin) |-> (D == 1'b1 && Bout == 1'b0)
    );

// 1 - 1 - 0 gives zero difference and no borrow.
    check_one_minus_one_no_borrowin: assert property (
        @(posedge clk) (A && B && !Bin) |-> (D == 1'b0 && Bout == 1'b0)
    );

// out matches the combinational priority mux function.
    check_mux_function: assert property (
        @(posedge clk)
        out == (set ? 1'b1 :
                (clr ? 1'b0 :
                 ((sel == 2'b00) ? in0 :
                  ((sel == 2'b01) ? in1 :
                   ((sel == 2'b10) ? in2 : 1'b0)))))
    );

// set has highest priority and forces out high.
    check_set_priority: assert property (
        @(posedge clk)
        set |-> (out == 1'b1)
    );

// clr forces out low when set is low.
    check_clr_priority: assert property (
        @(posedge clk)
        (!set && clr) |-> (out == 1'b0)
    );

// sel 00 passes in0 when set and clr are low.
    check_sel_in0: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b00)) |-> (out == in0)
    );

// sel 01 passes in1 when set and clr are low.
    check_sel_in1: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b01)) |-> (out == in1)
    );

// sel 10 passes in2 when set and clr are low.
    check_sel_in2: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b10)) |-> (out == in2)
    );

// sel 11 forces out low when set and clr are low.
    check_sel_11_zero: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b11)) |-> (out == 1'b0)
    );

// Prefix 10 or 01 maps to exp 7 and lin[15:6].
    check_exp7_class: assert property (
        @(posedge clk)
        (((lin[15:14] == 2'b10) || (lin[15:14] == 2'b01)) |-> ((man == lin[15:6]) && (exp == 3'd7)))
    );

// Prefix 110 or 001 maps to exp 6 and lin[14:5].
    check_exp6_class: assert property (
        @(posedge clk)
        (((lin[15:13] == 3'b110) || (lin[15:13] == 3'b001)) |-> ((man == lin[14:5]) && (exp == 3'd6)))
    );

// Prefix 1110 or 0001 maps to exp 5 and lin[13:4].
    check_exp5_class: assert property (
        @(posedge clk)
        (((lin[15:12] == 4'b1110) || (lin[15:12] == 4'b0001)) |-> ((man == lin[13:4]) && (exp == 3'd5)))
    );

// Prefix 11110 or 00001 maps to exp 4 and lin[12:3].
    check_exp4_class: assert property (
        @(posedge clk)
        (((lin[15:11] == 5'b11110) || (lin[15:11] == 5'b00001)) |-> ((man == lin[12:3]) && (exp == 3'd4)))
    );

// Prefix 111110 or 000001 maps to exp 3 and lin[11:2].
    check_exp3_class: assert property (
        @(posedge clk)
        (((lin[15:10] == 6'b111110) || (lin[15:10] == 6'b000001)) |-> ((man == lin[11:2]) && (exp == 3'd3)))
    );

// Prefix 1111110 or 0000001 maps to exp 2 and lin[10:1].
    check_exp2_class: assert property (
        @(posedge clk)
        (((lin[15:9] == 7'b1111110) || (lin[15:9] == 7'b0000001)) |-> ((man == lin[10:1]) && (exp == 3'd2)))
    );

// Prefix 1111111 or 0000000 maps to exp 1 and lin[9:0].
    check_exp1_class: assert property (
        @(posedge clk)
        (((lin[15:9] == 7'b1111111) || (lin[15:9] == 7'b0000000)) |-> ((man == lin[9:0]) && (exp == 3'd1)))
    );

// The exponent is never driven to zero.
    check_exp_nonzero: assert property (
        @(posedge clk)
        (exp != 3'd0)
    );

// Reset clears Q0 by the next clock sample.
    reset_clears_Q0: assert property (
        @(posedge CLK)
        RESET |=> (Q0 == 4'b0000)
    );

// Reset clears Q1 by the next clock sample.
    reset_clears_Q1: assert property (
        @(posedge CLK)
        RESET |=> (Q1 == 4'b0000)
    );

// Reset clears Q2 by the next clock sample.
    reset_clears_Q2: assert property (
        @(posedge CLK)
        RESET |=> (Q2 == 4'b0000)
    );

// Reset clears Q3 by the next clock sample.
    reset_clears_Q3: assert property (
        @(posedge CLK)
        RESET |=> (Q3 == 4'b0000)
    );

// LOAD causes Q0 to capture D0.
    load_captures_D0_into_Q0: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q0 == $past(D0))
    );

// LOAD causes Q1 to capture D1.
    load_captures_D1_into_Q1: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q1 == $past(D1))
    );

// LOAD causes Q2 to capture D2.
    load_captures_D2_into_Q2: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q2 == $past(D2))
    );

// LOAD causes Q3 to capture D3.
    load_captures_D3_into_Q3: assert property (
        @(posedge CLK) disable iff (RESET)
        LOAD |=> (Q3 == $past(D3))
    );

// Shift mode moves Q1 into Q0.
    shift_moves_Q1_into_Q0: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q0 == $past(Q1))
    );

// Shift mode moves Q2 into Q1.
    shift_moves_Q2_into_Q1: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q1 == $past(Q2))
    );

// Shift mode moves Q3 into Q2.
    shift_moves_Q3_into_Q2: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q2 == $past(Q3))
    );

// Shift mode moves D0 into Q3.
    shift_moves_D0_into_Q3: assert property (
        @(posedge CLK) disable iff (RESET)
        !LOAD |=> (Q3 == $past(D0))
    );

// Any unmapped state drives the default output 00.
    check_out_for_unmapped_state: assert property (
        @(posedge clk) disable iff (rst)
        !((state == STATE_RESET) || (state == STATE_A) || (state == STATE_B) || (state == STATE_C) ||
          (state == STATE_D) || (state == STATE_E) || (state == STATE_F) || (state == STATE_G))
        |-> (out == OUT_00)
    );

// Address 0 returns 'H' on the next clock.
    check_addr_0_returns_H: assert property (
        @(posedge clk) (addr == 4'd0) |=> (data == 8'h48)
    );

// Address 1 returns 'e' on the next clock.
    check_addr_1_returns_e: assert property (
        @(posedge clk) (addr == 4'd1) |=> (data == 8'h65)
    );

// Address 2 returns 'l' on the next clock.
    check_addr_2_returns_l: assert property (
        @(posedge clk) (addr == 4'd2) |=> (data == 8'h6c)
    );

// Address 3 returns 'l' on the next clock.
    check_addr_3_returns_l: assert property (
        @(posedge clk) (addr == 4'd3) |=> (data == 8'h6c)
    );

// Address 4 returns 'o' on the next clock.
    check_addr_4_returns_o: assert property (
        @(posedge clk) (addr == 4'd4) |=> (data == 8'h6f)
    );

// Address 5 returns space on the next clock.
    check_addr_5_returns_space: assert property (
        @(posedge clk) (addr == 4'd5) |=> (data == 8'h20)
    );

// Address 6 returns 'W' on the next clock.
    check_addr_6_returns_W: assert property (
        @(posedge clk) (addr == 4'd6) |=> (data == 8'h57)
    );

// Address 7 returns 'o' on the next clock.
    check_addr_7_returns_o: assert property (
        @(posedge clk) (addr == 4'd7) |=> (data == 8'h6f)
    );

// Address 8 returns 'r' on the next clock.
    check_addr_8_returns_r: assert property (
        @(posedge clk) (addr == 4'd8) |=> (data == 8'h72)
    );

// Address 9 returns 'l' on the next clock.
    check_addr_9_returns_l: assert property (
        @(posedge clk) (addr == 4'd9) |=> (data == 8'h6c)
    );

// Address 10 returns 'd' on the next clock.
    check_addr_10_returns_d: assert property (
        @(posedge clk) (addr == 4'd10) |=> (data == 8'h64)
    );

// Address 11 returns '!' on the next clock.
    check_addr_11_returns_bang: assert property (
        @(posedge clk) (addr == 4'd11) |=> (data == 8'h21)
    );

// Address 12 returns newline on the next clock.
    check_addr_12_returns_lf: assert property (
        @(posedge clk) (addr == 4'd12) |=> (data == 8'h0a)
    );

// Out-of-range addresses return space on the next clock.
    check_addr_out_of_range_returns_space: assert property (
        @(posedge clk) (addr > 4'd13) |=> (data == 8'h20)
    );

// Arithmetic overflow must set Cout.
    check_overflow_sets_cout: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B} + Cin) > 5'd15) |-> (Cout == 1'b1)
    );

// X must equal C1 OR B1 OR (A1 AND A2).
    check_output_equation: assert property (
        @(posedge clk) X == (C1 | B1 | (A1 & A2))
    );

// C1 high must drive X high through the OR gate.
    check_c1_drives_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// B1 high must drive X high through the OR gate.
    check_b1_drives_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// A1 and A2 high together must drive X high through the AND term.
    check_a1_a2_drive_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// If all OR inputs are low, X must be low.
    check_all_terms_low_drive_x_low: assert property (
        @(posedge clk) (!C1 && !B1 && !(A1 & A2)) |-> !X
    );

// A greater than B produces 01.
    check_a_gt_b_encoding: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

// Equal inputs produce 00.
    check_a_eq_b_encoding: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

// A less than B produces 11.
    check_a_lt_b_encoding: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b11)
    );

// The LSB is high when A and B differ.
    check_result_lsb_matches_inequality: assert property (
        @(posedge clk) (result[0] == (A != B))
    );

// The MSB is high only when A is less than B.
    check_result_msb_matches_less_than: assert property (
        @(posedge clk) (result[1] == (A < B))
    );

// The unused encoding 10 is never generated.
    check_no_unused_encoding: assert property (
        @(posedge clk) (result != 2'b10)
    );

// When the 5-bit sum is 15 or less, S matches the exact sum.
    check_sum_no_overflow: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) <= 5'd15) |-> ({1'b0, S} == ({1'b0, A} + {1'b0, B}))
    );

// When the 5-bit sum exceeds 15, S wraps to the low 4 bits.
    check_sum_overflow_wrap: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) > 5'd15) |-> ({1'b0, S} == (({1'b0, A} + {1'b0, B}) - 5'd16))
    );

// A zero B input leaves the output equal to A.
    check_b_zero_identity: assert property (
        @(posedge clk)
        (B == 4'd0) |-> (S == A)
    );

// A zero A input leaves the output equal to B.
    check_a_zero_identity: assert property (
        @(posedge clk)
        (A == 4'd0) |-> (S == B)
    );

// The largest non-overflowing sum passes through unchanged.
    check_boundary_sum_fifteen: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) == 5'd15) |-> (S == 4'd15)
    );

// The first overflowing sum wraps to zero.
    check_boundary_sum_sixteen: assert property (
        @(posedge clk)
        (({1'b0, A} + {1'b0, B}) == 5'd16) |-> (S == 4'd0)
    );

// Reset clears the counter and output by the next sampled clock.
    check_reset_clears_state: assert property (
        @(posedge clk) reset |=> (r == 20'd0 && out == 1'b0)
    );

// The first cycle after reset release still sees a cleared state.
    check_reset_release_starts_cleared: assert property (
        @(posedge clk) reset ##1 !reset |-> (r == 20'd0 && out == 1'b0)
    );

// X matches the implemented gate equation.
    check_implemented_majority_equation: assert property (
        @(posedge clk) (X == ((A & B) | ((A | B) & C)))
    );

// A and B high force X high.
    check_ab_high_sets_x: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (X == 1'b1)
    );

// A and C high force X high.
    check_ac_high_sets_x: assert property (
        @(posedge clk) ((A == 1'b1) && (C == 1'b1)) |-> (X == 1'b1)
    );

// B and C high force X high.
    check_bc_high_sets_x: assert property (
        @(posedge clk) ((B == 1'b1) && (C == 1'b1)) |-> (X == 1'b1)
    );

// A and B low force X low.
    check_ab_low_clears_x: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (X == 1'b0)
    );

// A and C low force X low.
    check_ac_low_clears_x: assert property (
        @(posedge clk) ((A == 1'b0) && (C == 1'b0)) |-> (X == 1'b0)
    );

// B and C low force X low.
    check_bc_low_clears_x: assert property (
        @(posedge clk) ((B == 1'b0) && (C == 1'b0)) |-> (X == 1'b0)
    );

// out1 matches the 3-input NAND of a1, b1, and c1.
    check_out1_nand_function: assert property (
        @(posedge clk) out1 == ~(a1 & b1 & c1)
    );

// out2 matches the 3-input NAND of a2, b2, and c2.
    check_out2_nand_function: assert property (
        @(posedge clk) out2 == ~(a2 & b2 & c2)
    );

// out3 matches the 3-input NAND of a3, b3, and c3.
    check_out3_nand_function: assert property (
        @(posedge clk) out3 == ~(a3 & b3 & c3)
    );

// Reset forces the output to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) RESET |-> (RESULT == 32'd0)
    );

// Opcode 00 selects addition.
    check_add_operation: assert property (
        @(posedge clk) disable iff (RESET)
        (OPCODE == 2'b00) |-> (RESULT == (A + B))
    );

// Opcode 01 selects subtraction.
    check_sub_operation: assert property (
        @(posedge clk) disable iff (RESET)
        (OPCODE == 2'b01) |-> (RESULT == (A - B))
    );

// init_counter_done matches the terminal-count compare.
    check_done_flag_definition: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (init_counter_done == (init_counter == INIT_CNT))
    );

// A reset clock clears the counter to zero.
    check_counter_resets_to_zero: assert property (
        @(posedge sdram_clk)
        (!sdram_rst_) |=> (init_counter == 16'h0000)
    );

// The counter increments by one while not done.
    check_counter_increments_before_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (!init_counter_done) |=> (init_counter == ($past(init_counter) + 16'd1))
    );

// The counter stops changing once done is high.
    check_counter_holds_when_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        init_counter_done |=> (init_counter == $past(init_counter))
    );

// INIT_CNT-1 advances to the done condition on the next cycle.
    check_done_after_penultimate_count: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (init_counter == INIT_CNT_MINUS_ONE) |=> init_counter_done
    );

// PAA stays low when done was low on the prior clock.
    check_paa_low_after_not_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        (!init_counter_done) |=> (!PAA)
    );

// PAA goes high when done was high on the prior clock.
    check_paa_high_after_done: assert property (
        @(posedge sdram_clk) disable iff (!sdram_rst_)
        init_counter_done |=> PAA
    );

// SET_MODE is driven high after every clock edge.
    check_set_mode_driven_high: assert property (
        @(posedge sdram_clk)
        1'b1 |=> (SET_MODE == 1'b1)
    );

// y must equal a plus a shifted right by two.
    check_shift_add_function: assert property (
        @(posedge clk) y == (a + (a >> 2))
    );

// Zero input must produce zero output.
    check_zero_input: assert property (
        @(posedge clk) (a == 16'h0000) |-> (y == 16'h0000)
    );

// Inputs below four are unchanged because a>>2 is zero.
    check_small_input_identity: assert property (
        @(posedge clk) (a <= 16'd3) |-> (y == a)
    );

// Up to 16'hCCCC, the 16-bit sum does not wrap and cannot be less than a.
    check_nonoverflow_region_ge_input: assert property (
        @(posedge clk) (a <= 16'hCCCC) |-> (y >= a)
    );

// From 16'hCCCD upward, the 16-bit sum wraps and becomes less than a.
    check_overflow_region_lt_input: assert property (
        @(posedge clk) (a >= 16'hCCCD) |-> (y < a)
    );

// The largest non-overflowing input produces all ones.
    check_max_nonoverflow_case: assert property (
        @(posedge clk) (a == 16'hCCCC) |-> (y == 16'hFFFF)
    );

// The first overflowing input wraps the 16-bit result to zero.
    check_first_overflow_case: assert property (
        @(posedge clk) (a == 16'hCCCD) |-> (y == 16'h0000)
    );

// shift=0 passes A through.
    check_shift_0_identity: assert property (
        @(posedge clk) (shift == 4'b0000) |-> (Y == A)
    );

// shift=1 rotates A left by 1 bit.
    check_shift_1_rotate_left_1: assert property (
        @(posedge clk) (shift == 4'b0001) |-> (Y == {A[14:0], A[15]})
    );

// shift=2 rotates A left by 2 bits.
    check_shift_2_rotate_left_2: assert property (
        @(posedge clk) (shift == 4'b0010) |-> (Y == {A[13:0], A[15:14]})
    );

// shift=3 rotates A left by 3 bits.
    check_shift_3_rotate_left_3: assert property (
        @(posedge clk) (shift == 4'b0011) |-> (Y == {A[12:0], A[15:13]})
    );

// shift=4 rotates A left by 4 bits.
    check_shift_4_rotate_left_4: assert property (
        @(posedge clk) (shift == 4'b0100) |-> (Y == {A[11:0], A[15:12]})
    );

// shift=5 rotates A left by 5 bits.
    check_shift_5_rotate_left_5: assert property (
        @(posedge clk) (shift == 4'b0101) |-> (Y == {A[10:0], A[15:11]})
    );

// shift=6 rotates A left by 6 bits.
    check_shift_6_rotate_left_6: assert property (
        @(posedge clk) (shift == 4'b0110) |-> (Y == {A[9:0], A[15:10]})
    );

// shift=7 rotates A left by 7 bits.
    check_shift_7_rotate_left_7: assert property (
        @(posedge clk) (shift == 4'b0111) |-> (Y == {A[8:0], A[15:9]})
    );

// shift=8 rotates A left by 8 bits.
    check_shift_8_rotate_left_8: assert property (
        @(posedge clk) (shift == 4'b1000) |-> (Y == {A[7:0], A[15:8]})
    );

// shift=9 rotates A left by 9 bits.
    check_shift_9_rotate_left_9: assert property (
        @(posedge clk) (shift == 4'b1001) |-> (Y == {A[6:0], A[15:7]})
    );

// shift=10 rotates A left by 10 bits.
    check_shift_10_rotate_left_10: assert property (
        @(posedge clk) (shift == 4'b1010) |-> (Y == {A[5:0], A[15:6]})
    );

// shift=11 rotates A left by 11 bits.
    check_shift_11_rotate_left_11: assert property (
        @(posedge clk) (shift == 4'b1011) |-> (Y == {A[4:0], A[15:5]})
    );

// shift=12 rotates A left by 12 bits.
    check_shift_12_rotate_left_12: assert property (
        @(posedge clk) (shift == 4'b1100) |-> (Y == {A[3:0], A[15:4]})
    );

// shift=13 rotates A left by 13 bits.
    check_shift_13_rotate_left_13: assert property (
        @(posedge clk) (shift == 4'b1101) |-> (Y == {A[2:0], A[15:3]})
    );

// shift=14 rotates A left by 14 bits.
    check_shift_14_rotate_left_14: assert property (
        @(posedge clk) (shift == 4'b1110) |-> (Y == {A[1:0], A[15:2]})
    );

// shift=15 rotates A left by 15 bits.
    check_shift_15_rotate_left_15: assert property (
        @(posedge clk) (shift == 4'b1111) |-> (Y == {A[0], A[15:1]})
    );

// Sum output matches the XOR of A, B, and Ci.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry output matches Ci gated by A and B being equal.
    check_carry_function: assert property (
        @(posedge clk) Co == (Ci & ~(A ^ B))
    );

// Carry must be LOW whenever carry-in is LOW.
    check_carry_requires_ci: assert property (
        @(posedge clk) !Ci |-> !Co
    );

// Carry must be LOW whenever A and B differ.
    check_carry_low_when_inputs_differ: assert property (
        @(posedge clk) (A ^ B) |-> !Co
    );

// Carry follows Ci whenever A and B are equal.
    check_carry_follows_ci_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (Co == Ci)
    );

// Sum follows Ci whenever A and B are equal.
    check_sum_follows_ci_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

// Sum is the inverse of Ci whenever A and B differ.
    check_sum_inverts_ci_when_inputs_differ: assert property (
        @(posedge clk) (A != B) |-> (S == ~Ci)
    );

// Incrementing from the maximum value wraps count to zero.
    check_enable_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (en && !load && (count == {WIDTH{1'b1}})) |=> ((count == {WIDTH{1'b0}}) && (max_flag == 1'b0))
    );

// Without load or enable, count holds its value.
    check_idle_holds_count: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && !en) |=> (count == $past(count))
    );

// Reset clears the counter to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// When disabled without reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// When enabled below max, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'hF)) |=> (count == ($past(count) + 4'h1))
    );

// When enabled at max, the counter wraps back to zero.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// External sampling clock; DUT logic is combinational with active-low reset_n.

    // Active-low reset forces all outputs to zero.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        (!reset_n) |-> ((add == 32'd0) && (sub == 32'd0) && (mul == 32'd0) && (div == 32'd0))
    );

// add must match the sum of a and b outside reset.
    check_add_matches_sum: assert property (
        @(posedge clk) disable iff (!reset_n)
        (add == (a + b))
    );

// sub must match the difference of a and b outside reset.
    check_sub_matches_difference: assert property (
        @(posedge clk) disable iff (!reset_n)
        (sub == (a - b))
    );

// div must be zero when the divisor is zero.
    check_div_zero_on_zero_divisor: assert property (
        @(posedge clk) disable iff (!reset_n)
        (b == 32'd0) |-> (div == 32'd0)
    );

// Output must equal the AND of all six inputs.
    check_output_matches_and: assert property (
        @(posedge clk)
        out_signal == (in_signal1 & in_signal2 & in_signal3 & in_signal4 & in_signal5 & in_signal6)
    );

// A high output requires all six inputs to be high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk)
        out_signal |-> (in_signal1 & in_signal2 & in_signal3 & in_signal4 & in_signal5 & in_signal6)
    );

// All six high inputs must drive the output high.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk)
        (in_signal1 & in_signal2 & in_signal3 & in_signal4 & in_signal5 & in_signal6) |-> out_signal
    );

// A low in_signal1 must force the output low.
    check_input1_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal1 |-> !out_signal
    );

// A low in_signal2 must force the output low.
    check_input2_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal2 |-> !out_signal
    );

// A low in_signal3 must force the output low.
    check_input3_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal3 |-> !out_signal
    );

// A low in_signal4 must force the output low.
    check_input4_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal4 |-> !out_signal
    );

// A low in_signal5 must force the output low.
    check_input5_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal5 |-> !out_signal
    );

// A low in_signal6 must force the output low.
    check_input6_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal6 |-> !out_signal
    );

// Combinational RTL; clk is a sampling clock for formal and there is no reset.

    // Opcode 00 selects 4-bit wrapped addition.
    check_add_result: assert property (
        @(posedge clk) (opcode == 2'b00) |-> (result == ((A + B) & 4'hF))
    );

// Opcode 01 selects 4-bit wrapped subtraction.
    check_sub_result: assert property (
        @(posedge clk) (opcode == 2'b01) |-> (result == ((A - B) & 4'hF))
    );

// Output matches the implemented combinational function.
    check_exact_function: assert property (
        @(posedge clk) disable iff (1'b0)
        out_value == ((in_value <= 4'd7) ? in_value[2:0] : 3'b111)
    );

// Inputs 0 through 7 pass their low three bits to the output.
    check_low_range_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (in_value <= 4'd7) |-> (out_value == in_value[2:0])
    );

// Inputs above 7 force the output to 3'b111.
    check_high_range_saturation: assert property (
        @(posedge clk) disable iff (1'b0)
        (in_value > 4'd7) |-> (out_value == 3'b111)
    );

// No assertion-disabling reset exists; set and reset are synchronous controls.

    // Set forces q high and q_n low on the next clock.
    check_set_behavior: assert property (
        @(posedge clk) disable iff (1'b0)
            set |=> (q == 1'b1 && q_n == 1'b0)
    );

// Reset forces q low and q_n high when set is low.
    check_reset_behavior: assert property (
        @(posedge clk) disable iff (1'b0)
            (!set && reset) |=> (q == 1'b0 && q_n == 1'b1)
    );

// With set and reset low, d=1 is captured on the next clock.
    check_capture_one: assert property (
        @(posedge clk) disable iff (1'b0)
            (!set && !reset && d) |=> (q == 1'b1 && q_n == 1'b0)
    );

// With set and reset low, d=0 is captured on the next clock.
    check_capture_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            (!set && !reset && !d) |=> (q == 1'b0 && q_n == 1'b1)
    );

// If set and reset are both high, set has priority.
    check_set_priority: assert property (
        @(posedge clk) disable iff (1'b0)
            (set && reset) |=> (q == 1'b1 && q_n == 1'b0)
    );

// After each clocked update, q and q_n remain complementary.
    check_complementary_outputs: assert property (
        @(posedge clk) disable iff (1'b0)
            1'b1 |=> (q_n == ~q)
    );

// posedge clk is the only clock; duv_rst_ip is an active-high synchronous reset.
    // The design is a sequential counter with a combinational output mirror.

    // A reset cycle forces the next sampled output to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) duv_rst_ip |=> (out == 32'd0)
    );

// Two consecutive non-reset cycles increment the output by one.
    check_out_increments_without_reset: assert property (
        @(posedge clk) disable iff (duv_rst_ip)
        (!duv_rst_ip ##1 !duv_rst_ip) |-> (out == ($past(out) + 32'd1))
    );

// If reset stays asserted for two cycles, the later sampled output is zero.
    check_out_zero_during_held_reset: assert property (
        @(posedge clk) duv_rst_ip ##1 duv_rst_ip |-> (out == 32'd0)
    );

// When reset is released after a reset cycle, the first non-reset sample is zero.
    check_first_cycle_after_reset_release_is_zero: assert property (
        @(posedge clk) duv_rst_ip ##1 !duv_rst_ip |-> (out == 32'd0)
    );

// One cycle after reset release, the counter advances to one.
    check_second_cycle_after_reset_release_is_one: assert property (
        @(posedge clk) duv_rst_ip ##1 !duv_rst_ip |=> (out == 32'd1)
    );

// The 32-bit counter wraps from all ones to zero on the next non-reset cycle.
    check_out_wraps_after_max: assert property (
        @(posedge clk) disable iff (duv_rst_ip)
        (out == 32'hFFFF_FFFF) |=> (out == 32'd0)
    );

// Sequential counter on clk with active-high reset.

    // Reset forces count to zero at any sampled clock edge.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 32'd0)
    );

// A sampled reset leaves count at zero until the next sampled edge.
    check_reset_holds_zero_to_next_sample: assert property (
        @(posedge clk) reset |=> (count == 32'd0)
    );

// Reaching max_count wraps the counter to zero on the next sample.
    check_wraps_to_zero_at_max: assert property (
        @(posedge clk) disable iff (reset)
        (count == max_count) |=> (count == 32'd0)
    );

// An all-ones count returns to zero on the next sample.
    check_all_ones_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (count == 32'hFFFF_FFFF) |=> (count == 32'd0)
    );

// Each non-reset update is either +1 or a reset/wrap to zero.
    check_update_is_increment_or_zero: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> ((count == 32'd0) || (count == ($past(count) + 32'd1)))
    );

// From zero, the next sampled value can only stay zero or move to one.
    check_zero_moves_to_zero_or_one: assert property (
        @(posedge clk) disable iff (reset)
        (count == 32'd0) |=> ((count == 32'd0) || (count == 32'd1))
    );

// With count and max_count both zero, zero is retained on the next sample.
    check_zero_max_keeps_zero: assert property (
        @(posedge clk) disable iff (reset)
        ((count == 32'd0) && (max_count == 32'd0)) |=> (count == 32'd0)
    );

// When the first adder carry_out is low, top selects the first adder sum.
    check_select_sum1_when_first_carry_low: assert property (
        @(posedge clk) !adder_carry_fn(a, b) |-> s == adder_sum_fn(a, b)
    );

// When the decoder is not enabled, all outputs remain HIGH.
    check_disabled_outputs_high: assert property (
        @(posedge clk)
        (!en[0] || en[1] || en[2]) |-> (out[0] && out[1] && out[2] && out[3] && out[4] && out[5] && out[6] && out[7])
    );

// When enabled with input 000, only out[0] is LOW.
    check_decode_000: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] && !in[2] && !in[1] && !in[0]) |-> (!out[0] && out[1] && out[2] && out[3] && out[4] && out[5] && out[6] && out[7])
    );

// When enabled with input 001, only out[1] is LOW.
    check_decode_001: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] && !in[2] && !in[1] &&  in[0]) |-> (out[0] && !out[1] && out[2] && out[3] && out[4] && out[5] && out[6] && out[7])
    );

// When enabled with input 010, only out[2] is LOW.
    check_decode_010: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] && !in[2] &&  in[1] && !in[0]) |-> (out[0] && out[1] && !out[2] && out[3] && out[4] && out[5] && out[6] && out[7])
    );

// When enabled with input 011, only out[3] is LOW.
    check_decode_011: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] && !in[2] &&  in[1] &&  in[0]) |-> (out[0] && out[1] && out[2] && !out[3] && out[4] && out[5] && out[6] && out[7])
    );

// When enabled with input 100, only out[4] is LOW.
    check_decode_100: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] &&  in[2] && !in[1] && !in[0]) |-> (out[0] && out[1] && out[2] && out[3] && !out[4] && out[5] && out[6] && out[7])
    );

// When enabled with input 101, only out[5] is LOW.
    check_decode_101: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] &&  in[2] && !in[1] &&  in[0]) |-> (out[0] && out[1] && out[2] && out[3] && out[4] && !out[5] && out[6] && out[7])
    );

// When enabled with input 110, only out[6] is LOW.
    check_decode_110: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] &&  in[2] &&  in[1] && !in[0]) |-> (out[0] && out[1] && out[2] && out[3] && out[4] && out[5] && !out[6] && out[7])
    );

// When enabled with input 111, only out[7] is LOW.
    check_decode_111: assert property (
        @(posedge clk)
        (en[0] && !en[1] && !en[2] &&  in[2] &&  in[1] &&  in[0]) |-> (out[0] && out[1] && out[2] && out[3] && out[4] && out[5] && out[6] && !out[7])
    );

// Q advances by one each cycle, wrapping from 15 to 0.
    check_counter_transition_relation: assert property (
        @(posedge CLK)
        1'b1 |=> (Q == (($past(Q) == 4'hf) ? 4'h0 : ($past(Q) + 4'h1)))
    );

// A count of 15 wraps to 0 on the next clock.
    check_wrap_from_f_to_0: assert property (
        @(posedge CLK)
        (Q == 4'hf) |=> (Q == 4'h0)
    );

// Any count below 15 increments by one on the next clock.
    check_increment_below_f: assert property (
        @(posedge CLK)
        (Q != 4'hf) |=> (Q == ($past(Q) + 4'h1))
    );

// The counter never holds the same value on consecutive clocks.
    check_no_stall_between_cycles: assert property (
        @(posedge CLK)
        1'b1 |=> (Q != $past(Q))
    );

// A value of 0 can only be reached from 15.
    check_zero_only_after_f: assert property (
        @(posedge CLK)
        1'b1 |=> ((Q != 4'h0) || ($past(Q) == 4'hf))
    );

// A value of 15 can only be reached from 14.
    check_f_only_after_e: assert property (
        @(posedge CLK)
        1'b1 |=> ((Q != 4'hf) || ($past(Q) == 4'he))
    );

// Y matches the implemented 4:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        Y == ((A && !S1 && !S0) ||
              (B && !S1 &&  S0) ||
              (C &&  S1 && !S0) ||
              (D &&  S1 &&  S0))
    );

// When S1S0 is 00, Y follows A.
    check_select_00_routes_a: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == A)
    );

// When S1S0 is 01, Y follows B.
    check_select_01_routes_b: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Y == B)
    );

// When S1S0 is 10, Y follows C.
    check_select_10_routes_c: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Y == C)
    );

// When S1S0 is 11, Y follows D.
    check_select_11_routes_d: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Y == D)
    );

// Clock: clk; the RTL has no reset.
    // out_comb is the registered XOR of a and b with two-cycle latency.

    // A low sampled XOR must produce a low output two clocks later.
    check_xor_zero_produces_low: assert property (
        @(posedge clk)
        ((a ^ b) == 1'b0) |-> ##2 (out_comb == 1'b0)
    );

// A high sampled XOR must produce a high output two clocks later.
    check_xor_one_produces_high: assert property (
        @(posedge clk)
        ((a ^ b) == 1'b1) |-> ##2 (out_comb == 1'b1)
    );

// SELECT 15 must route IN16 to OUT.
    check_select_15_routes_in16: assert property (
        @(posedge clk) (SELECT === 4'b1111) |-> (OUT === IN16)
    );

// Full output must match the implemented XOR with zero-extended data_in_2.
    check_full_xor_relation: assert property (
        @(posedge clk) data_out == (data_in_1 ^ {92'b0, data_in_2})
    );

// Upper 92 bits of the output must pass through from data_in_1 unchanged.
    check_upper_bits_passthrough: assert property (
        @(posedge clk) data_out[99:8] == data_in_1[99:8]
    );

// Lower 8 bits of the output must be the XOR of the lower byte and data_in_2.
    check_lower_byte_xor_relation: assert property (
        @(posedge clk) data_out[7:0] == (data_in_1[7:0] ^ data_in_2)
    );

// XORing the output lower byte with data_in_1 lower byte must recover data_in_2.
    check_lower_byte_recovers_input2: assert property (
        @(posedge clk) (data_out[7:0] ^ data_in_1[7:0]) == data_in_2
    );

// A zero data_in_2 must make the output identical to data_in_1.
    check_zero_data_in_2_passthrough: assert property (
        @(posedge clk) (data_in_2 == 8'h00) |-> (data_out == data_in_1)
    );

// A zero data_in_1 must make the output the zero-extended data_in_2.
    check_zero_data_in_1_zero_extended_output: assert property (
        @(posedge clk) (data_in_1 == 100'b0) |-> (data_out == {92'b0, data_in_2})
    );

// Matching lower-byte inputs must cancel to zero on the lower output byte.
    check_matching_lower_bytes_cancel: assert property (
        @(posedge clk) (data_in_2 == data_in_1[7:0]) |-> (data_out[7:0] == 8'h00)
    );

// With d0 low, out0 selects in0.
    check_out0_select_in0: assert property (
        @(posedge clk) disable iff (reset) (!d0) |-> (out0 == in0)
    );

// With d0 high, out0 selects in1.
    check_out0_select_in1: assert property (
        @(posedge clk) disable iff (reset) d0 |-> (out0 == in1)
    );

// With d1 low, out1 selects in2.
    check_out1_select_in2: assert property (
        @(posedge clk) disable iff (reset) (!d1) |-> (out1 == in2)
    );

// With d1 high, out1 selects in3.
    check_out1_select_in3: assert property (
        @(posedge clk) disable iff (reset) d1 |-> (out1 == in3)
    );

// A high reset drives out2 low on the next clock.
    check_out2_reset_forces_low: assert property (
        @(posedge clk) reset |=> (out2 == 1'b0)
    );

// With reset low and d2 low, out2 captures the inverse of in0.
    check_out2_select_in0: assert property (
        @(posedge clk) (!reset && !d2) |=> (out2 == ~$past(in0))
    );

// With reset low and d2 high, out2 captures the inverse of in1.
    check_out2_select_in1: assert property (
        @(posedge clk) (!reset && d2) |=> (out2 == ~$past(in1))
    );

// With d3 low, out3 captures in2 on the next clock.
    check_out3_select_in2: assert property (
        @(posedge clk) (!d3) |=> (out3 == $past(in2))
    );

// With d3 high, out3 captures in3 on the next clock.
    check_out3_select_in3: assert property (
        @(posedge clk) d3 |=> (out3 == $past(in3))
    );

// A sampled reset forces the counter to zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count_out == 4'h0)
    );

// When up_down is high, the counter increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        up_down |=> (count_out == ($past(count_out) + 4'h1))
    );

// When up_down is low, the counter decrements by one.
    check_count_decrements: assert property (
        @(posedge clk) disable iff (reset)
        !up_down |=> (count_out == ($past(count_out) - 4'h1))
    );

// The counter wraps from 15 to 0 when counting up.
    check_count_wraps_up: assert property (
        @(posedge clk) disable iff (reset)
        (up_down && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// The counter wraps from 0 to 15 when counting down.
    check_count_wraps_down: assert property (
        @(posedge clk) disable iff (reset)
        (!up_down && (count_out == 4'h0)) |=> (count_out == 4'hF)
    );

// Sampled with an external formal clock; the RTL is combinational and has no reset.

    // selector 0 routes d0_i to d_o.
    check_select_0_routes_d0: assert property (
        @(posedge clk) (selector_i == 4'd0) |-> (d_o == d0_i)
    );

// selector 1 routes d1_i to d_o.
    check_select_1_routes_d1: assert property (
        @(posedge clk) (selector_i == 4'd1) |-> (d_o == d1_i)
    );

// selector 2 routes d2_i to d_o.
    check_select_2_routes_d2: assert property (
        @(posedge clk) (selector_i == 4'd2) |-> (d_o == d2_i)
    );

// selector 3 routes d3_i to d_o.
    check_select_3_routes_d3: assert property (
        @(posedge clk) (selector_i == 4'd3) |-> (d_o == d3_i)
    );

// selector 4 routes d4_i to d_o.
    check_select_4_routes_d4: assert property (
        @(posedge clk) (selector_i == 4'd4) |-> (d_o == d4_i)
    );

// selector 5 routes d5_i to d_o.
    check_select_5_routes_d5: assert property (
        @(posedge clk) (selector_i == 4'd5) |-> (d_o == d5_i)
    );

// selector 6 routes d6_i to d_o.
    check_select_6_routes_d6: assert property (
        @(posedge clk) (selector_i == 4'd6) |-> (d_o == d6_i)
    );

// selector 7 routes d7_i to d_o.
    check_select_7_routes_d7: assert property (
        @(posedge clk) (selector_i == 4'd7) |-> (d_o == d7_i)
    );

// selector 8 routes d8_i to d_o.
    check_select_8_routes_d8: assert property (
        @(posedge clk) (selector_i == 4'd8) |-> (d_o == d8_i)
    );

// selector 9 routes d9_i to d_o.
    check_select_9_routes_d9: assert property (
        @(posedge clk) (selector_i == 4'd9) |-> (d_o == d9_i)
    );

// selector 10 routes d10_i to d_o.
    check_select_10_routes_d10: assert property (
        @(posedge clk) (selector_i == 4'd10) |-> (d_o == d10_i)
    );

// selector 11 routes d11_i to d_o.
    check_select_11_routes_d11: assert property (
        @(posedge clk) (selector_i == 4'd11) |-> (d_o == d11_i)
    );

// selector 12 routes d12_i to d_o.
    check_select_12_routes_d12: assert property (
        @(posedge clk) (selector_i == 4'd12) |-> (d_o == d12_i)
    );

// selector 13 routes d13_i to d_o.
    check_select_13_routes_d13: assert property (
        @(posedge clk) (selector_i == 4'd13) |-> (d_o == d13_i)
    );

// selector 14 routes d14_i to d_o.
    check_select_14_routes_d14: assert property (
        @(posedge clk) (selector_i == 4'd14) |-> (d_o == d14_i)
    );

// selector 15 routes d15_i to d_o.
    check_select_15_routes_d15: assert property (
        @(posedge clk) (selector_i == 4'd15) |-> (d_o == d15_i)
    );

// Y matches the implemented NAND-with-inverted-A function.
    check_function_equation: assert property (
        @(posedge clk) Y == ~(B & ~A_N & C)
    );

// A_N high forces the inverted A input low, so Y must be high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> (Y == 1'b1)
    );

// B low disables the NAND term, so Y must be high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) !B |-> (Y == 1'b1)
    );

// C low disables the NAND term, so Y must be high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> (Y == 1'b1)
    );

// Y is low only when A_N is low and both B and C are high.
    check_all_active_drives_y_low: assert property (
        @(posedge clk) (!A_N && B && C) |-> (Y == 1'b0)
    );

// A low output requires all effective NAND inputs to be active.
    check_y_low_requires_all_active: assert property (
        @(posedge clk) (Y == 1'b0) |-> (!A_N && B && C)
    );

// ENCLK reflects the AND of EN and TE captured on the previous clock edge.
    check_enclk_matches_registered_and: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == $past(EN & TE))
    );

// When both EN and TE are high, ENCLK is high on the following cycle.
    check_enclk_sets_when_en_and_te_high: assert property (
        @(posedge CLK) (EN & TE) |=> ENCLK
    );

// When EN is low, ENCLK is low on the following cycle.
    check_enclk_clears_when_en_low: assert property (
        @(posedge CLK) !EN |=> !ENCLK
    );

// When TE is low, ENCLK is low on the following cycle.
    check_enclk_clears_when_te_low: assert property (
        @(posedge CLK) !TE |=> !ENCLK
    );

// TWOPOS follows its combinational equation.
    check_twopos_equation: assert property (
        @(posedge clk) TWOPOS == ~(INA & INB & (~INC))
    );

// TWONEG follows its combinational equation.
    check_twoneg_equation: assert property (
        @(posedge clk) TWONEG == ~(~((~INA) & (~INB) & INC))
    );

// ONEPOS follows its combinational equation.
    check_onepos_equation: assert property (
        @(posedge clk) ONEPOS == (((~INA) & INB & (~INC)) | ((~INC) & (~INB) & INA))
    );

// ONENEG follows its combinational equation.
    check_oneneg_equation: assert property (
        @(posedge clk) ONENEG == ((INA & (~INB) & INC) | (INC & INB & (~INA)))
    );

// ONEPOS and ONENEG are never high together.
    check_one_outputs_mutually_exclusive: assert property (
        @(posedge clk) !(ONEPOS && ONENEG)
    );

// Any one-magnitude output requires INA and INB to differ.
    check_one_outputs_require_input_mismatch: assert property (
        @(posedge clk) (ONEPOS || ONENEG) |-> (INA ^ INB)
    );

// Matching INA and INB clear both one-magnitude outputs.
    check_equal_inputs_clear_one_outputs: assert property (
        @(posedge clk) !(INA ^ INB) |-> (!ONEPOS && !ONENEG)
    );

// ONEPOS can only be high when INC is low.
    check_onepos_only_when_inc_low: assert property (
        @(posedge clk) ONEPOS |-> !INC
    );

// ONENEG can only be high when INC is high.
    check_oneneg_only_when_inc_high: assert property (
        @(posedge clk) ONENEG |-> INC
    );

// TWOPOS is low only for INA=1, INB=1, INC=0.
    check_twopos_low_only_for_110: assert property (
        @(posedge clk) !TWOPOS |-> (INA && INB && !INC)
    );

// TWONEG is high only for INA=0, INB=0, INC=1.
    check_twoneg_high_only_for_001: assert property (
        @(posedge clk) TWONEG |-> (!INA && !INB && INC)
    );

// Reset clears the counter on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// With reset low, enable increments count by one modulo 16.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// With reset low and enable low, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Select 00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b00) |-> (out === in0)
    );

// Select 01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b01) |-> (out === in1)
    );

// Select 10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b10) |-> (out === in2)
    );

// Select 11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) ({sel1, sel0} === 2'b11) |-> (out === in3)
    );

// Increment requests decode to increment outputs on the next cycle.
    check_increment_request_to_increment_outputs: assert property (
        @(posedge Clock) disable iff (Reset)
        IncrementData |=> (AddOne && WriteOrRead)
    );

// Load-only requests decode to load outputs on the next cycle.
    check_load_only_request_to_load_outputs: assert property (
        @(posedge Clock) disable iff (Reset)
        (!IncrementData && LoadData) |=> (!AddOne && WriteOrRead)
    );

// No request decodes to read outputs on the next cycle.
    check_no_request_to_read_outputs: assert property (
        @(posedge Clock) disable iff (Reset)
        (!IncrementData && !LoadData) |=> (!AddOne && !WriteOrRead)
    );

// IncrementData has priority when both requests are asserted.
    check_increment_priority_over_load: assert property (
        @(posedge Clock) disable iff (Reset)
        (IncrementData && LoadData) |=> (AddOne && WriteOrRead)
    );

// Any request drives WriteOrRead high on the next cycle.
    check_request_sets_writeorread: assert property (
        @(posedge Clock) disable iff (Reset)
        (IncrementData || LoadData) |=> WriteOrRead
    );

// AddOne is never asserted without WriteOrRead.
    check_addone_implies_writeorread: assert property (
        @(posedge Clock) disable iff (Reset)
        AddOne |-> WriteOrRead
    );

// After reset is released, outputs still reflect the initial decode.
    check_outputs_idle_after_reset_release: assert property (
        @(posedge Clock) disable iff (Reset)
        $fell(Reset) |-> (!AddOne && !WriteOrRead)
    );

// Combinational decoder sampled on an external clock; no reset in the RTL.

    // When disabled, all outputs must be low.
    check_disable_drives_zero: assert property (
        @(posedge clk) !EN |-> (Y == 4'b0000)
    );

// Y[0] is high exactly when EN=1 and AB=00.
    check_y0_decode: assert property (
        @(posedge clk) Y[0] == (EN && !A && !B)
    );

// Y[1] is high exactly when EN=1 and AB=01.
    check_y1_decode: assert property (
        @(posedge clk) Y[1] == (EN && !A && B)
    );

// Y[2] is high exactly when EN=1 and AB=10.
    check_y2_decode: assert property (
        @(posedge clk) Y[2] == (EN && A && !B)
    );

// Y[3] is high exactly when EN=1 and AB=11.
    check_y3_decode: assert property (
        @(posedge clk) Y[3] == (EN && A && B)
    );

// When enabled, the output must be one of the four one-hot decode values.
    check_enabled_output_code: assert property (
        @(posedge clk) EN |-> ((Y == 4'b0001) || (Y == 4'b0010) || (Y == 4'b0100) || (Y == 4'b1000))
    );

// The output must always be zero or a valid one-hot decode value.
    check_output_legal_values: assert property (
        @(posedge clk) (Y == 4'b0000) || (Y == 4'b0001) || (Y == 4'b0010) || (Y == 4'b0100) || (Y == 4'b1000)
    );

// No reset in RTL; sample the combinational function on clk.

    // X must equal B1 OR (A1 AND A2 AND A3).
    check_function_exact: assert property (
        @(posedge clk) X == (B1 | (A1 & A2 & A3))
    );

// B1 high must force X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// With B1 low, X must match the 3-input AND term.
    check_and_path_when_b1_low: assert property (
        @(posedge clk) !B1 |-> (X == (A1 & A2 & A3))
    );

// All three A inputs high must force X high.
    check_all_a_high_forces_x_high: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// X low implies B1 is low and at least one A input is low.
    check_x_low_condition: assert property (
        @(posedge clk) !X |-> (!B1 && (!A1 || !A2 || !A3))
    );

// out0 is driven by in only for select 000.
    check_out0_decode: assert property (
        @(posedge clk)
        out0 === (((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out1 is driven by in only for select 001.
    check_out1_decode: assert property (
        @(posedge clk)
        out1 === (((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// out2 is driven by in only for select 010.
    check_out2_decode: assert property (
        @(posedge clk)
        out2 === (((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out3 is driven by in only for select 011.
    check_out3_decode: assert property (
        @(posedge clk)
        out3 === (((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// out4 is driven by in only for select 100.
    check_out4_decode: assert property (
        @(posedge clk)
        out4 === (((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out5 is driven by in only for select 101.
    check_out5_decode: assert property (
        @(posedge clk)
        out5 === (((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// out6 is driven by in only for select 110.
    check_out6_decode: assert property (
        @(posedge clk)
        out6 === (((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b0)) ? in : 1'b0)
    );

// out7 is driven by in only for select 111.
    check_out7_decode: assert property (
        @(posedge clk)
        out7 === (((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b1)) ? in : 1'b0)
    );

// A low input forces every output low.
    check_input_low_clears_outputs: assert property (
        @(posedge clk)
        (in === 1'b0) |-> ({out7, out6, out5, out4, out3, out2, out1, out0} === 8'b00000000)
    );

// If en is high on a clock edge, enclk is high on the next clock edge.
    check_en_high_sets_enclk: assert property (
        @(posedge clk) (en === 1'b1) |=> (enclk === 1'b1)
    );

// If en is low on a clock edge, enclk is low on the next clock edge.
    check_en_low_clears_enclk: assert property (
        @(posedge clk) (en === 1'b0) |=> (enclk === 1'b0)
    );

// enclk reflects the en value sampled on the previous clock edge.
    check_enclk_tracks_previous_en: assert property (
        @(posedge clk) ((en === 1'b1) || (en === 1'b0)) |=> (enclk === $past(en))
    );

// SUM is the parity of A, B, and CI.
    check_sum_parity: assert property (
        @(posedge clk) (SUM == (A ^ B ^ CI))
    );

// COUT_N matches the implemented OR-of-NOR carry complement logic.
    check_cout_n_nor_or_function: assert property (
        @(posedge clk) (COUT_N == ((~(A | B)) | (~(A | CI)) | (~(B | CI))))
    );

// All-zero inputs produce SUM low and COUT_N high.
    check_zero_input_case: assert property (
        @(posedge clk)
        ((A == 1'b0) && (B == 1'b0) && (CI == 1'b0))
        |-> ((SUM == 1'b0) && (COUT_N == 1'b1))
    );

// Exactly one high input produces SUM high and COUT_N high.
    check_single_high_case: assert property (
        @(posedge clk)
        (((A == 1'b1) && (B == 1'b0) && (CI == 1'b0)) ||
         ((A == 1'b0) && (B == 1'b1) && (CI == 1'b0)) ||
         ((A == 1'b0) && (B == 1'b0) && (CI == 1'b1)))
        |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

// Exactly two high inputs produce SUM low and COUT_N low.
    check_double_high_case: assert property (
        @(posedge clk)
        (((A == 1'b1) && (B == 1'b1) && (CI == 1'b0)) ||
         ((A == 1'b1) && (B == 1'b0) && (CI == 1'b1)) ||
         ((A == 1'b0) && (B == 1'b1) && (CI == 1'b1)))
        |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

// All-high inputs produce SUM high and COUT_N low.
    check_all_high_case: assert property (
        @(posedge clk)
        ((A == 1'b1) && (B == 1'b1) && (CI == 1'b1))
        |-> ((SUM == 1'b1) && (COUT_N == 1'b0))
    );

// Output matches the selected input masked by zero-extended c.
    check_out_matches_rtl_function: assert property (
        @(posedge clk)
        out == (((sel_b1 & sel_b2) ? b : a) & {4'b0000, c})
    );

// When both select inputs are high, b drives the masked output.
    check_selects_choose_b: assert property (
        @(posedge clk)
        (sel_b1 & sel_b2) |-> (out == (b & {4'b0000, c}))
    );

// When either select input is low, a drives the masked output.
    check_selects_choose_a: assert property (
        @(posedge clk)
        !(sel_b1 & sel_b2) |-> (out == (a & {4'b0000, c}))
    );

// Upper output bits are always zero because c is only 4 bits wide.
    check_upper_nibble_forced_zero: assert property (
        @(posedge clk)
        out[7:4] == 4'b0000
    );

// A zero mask clears the entire output.
    check_zero_mask_clears_output: assert property (
        @(posedge clk)
        (c == 4'h0) |-> (out == 8'h00)
    );

// Reset drives both registers low.
    check_reset_clears_registers: assert property (
        @(posedge clk)
        !rst_n |-> ((out_100kHz == 1'b0) && (counter == 16'd0))
    );

// Reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// When below 15, the counter increments by one.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

// A count of 15 wraps back to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hF) |=> (count == 4'h0)
    );

// Zero advances to one when reset is low.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'h0) |=> (count == 4'h1)
    );

// Fourteen advances to fifteen when reset is low.
    check_fourteen_advances_to_fifteen: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hE) |=> (count == 4'hF)
    );

// X must match the implemented NAND of A and B_N.
    check_nand_function: assert property (
        @(posedge clk) X == ~(A & B_N)
    );

// A low forces X high.
    check_a_low_forces_x_high: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b1)
    );

// B_N low forces X high.
    check_bn_low_forces_x_high: assert property (
        @(posedge clk) (B_N == 1'b0) |-> (X == 1'b1)
    );

// Both inputs high force X low.
    check_both_high_drive_x_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B_N == 1'b1)) |-> (X == 1'b0)
    );

// Select 11 routes input 3 to the output.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel === 2'b11) |-> (out === in3)
    );

// Combinational DUT sampled on clk; no reset is present in the RTL.

    // When select is high, the output must match input 1.
    check_select_high_routes_in1: assert property (
        @(posedge clk) (mux_sel === 1'b1) |-> (mux_out === mux_in1)
    );

// When select is anything other than high, the output must match input 0.
    check_select_not_high_routes_in0: assert property (
        @(posedge clk) (mux_sel !== 1'b1) |-> (mux_out === mux_in0)
    );

// The output must always match one of the two inputs.
    check_output_matches_one_input: assert property (
        @(posedge clk) (mux_out === mux_in0) || (mux_out === mux_in1)
    );

// Count is zero on the sampled clock where reset deasserts.
    check_reset_release_zero: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == 3'b000)
    );

// Count advances from 0 to 1 outside reset.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b000) |=> (count == 3'b001)
    );

// Count advances from 1 to 2 outside reset.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b001) |=> (count == 3'b010)
    );

// Count advances from 2 to 3 outside reset.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b010) |=> (count == 3'b011)
    );

// Count advances from 3 to 4 outside reset.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b011) |=> (count == 3'b100)
    );

// Count advances from 4 to 5 outside reset.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b100) |=> (count == 3'b101)
    );

// Count advances from 5 to 6 outside reset.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b101) |=> (count == 3'b110)
    );

// Count advances from 6 to 7 outside reset.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b110) |=> (count == 3'b111)
    );

// Count wraps from 7 back to 0 outside reset.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (rst) (count == 3'b111) |=> (count == 3'b000)
    );

// When S selects A, OUT must equal A.
    check_select_00_routes_a: assert property (
        @(posedge clk) (S == 2'b00) |-> (OUT == A)
    );

// When S selects B, OUT must equal B.
    check_select_01_routes_b: assert property (
        @(posedge clk) (S == 2'b01) |-> (OUT == B)
    );

// When S selects C, OUT must equal C.
    check_select_10_routes_c: assert property (
        @(posedge clk) (S == 2'b10) |-> (OUT == C)
    );

// When S selects D, OUT must equal D.
    check_select_11_routes_d: assert property (
        @(posedge clk) (S == 2'b11) |-> (OUT == D)
    );

// Output must implement the mux equation.
    check_mux_equation: assert property (
        @(posedge clk) out == ((data0 & ~sel) | (data1 & sel))
    );

// When select is low, output must follow data0.
    check_select_low: assert property (
        @(posedge clk) !sel |-> (out == data0)
    );

// When select is high, output must follow data1.
    check_select_high: assert property (
        @(posedge clk) sel |-> (out == data1)
    );

// If both inputs are low, output must be low.
    check_both_inputs_low: assert property (
        @(posedge clk) (!data0 && !data1) |-> !out
    );

// If both inputs are high, output must be high.
    check_both_inputs_high: assert property (
        @(posedge clk) (data0 && data1) |-> out
    );

// Sum must match the selected top-level datapath.
    check_sum_selected_function: assert property (
        @(posedge clk) sum == (sel ? in2 : (in1 ^ in2))
    );

// When sel is high, the output must route in2.
    check_sel_high_routes_in2: assert property (
        @(posedge clk) sel |-> (sum == in2)
    );

// When sel is low, the output must be the bitwise XOR path.
    check_sel_low_routes_bitwise_xor: assert property (
        @(posedge clk) !sel |-> (sum == (in1 ^ in2))
    );

// Equal inputs on the XOR path must produce zero.
    check_sel_low_equal_inputs_zero: assert property (
        @(posedge clk) (!sel && (in1 == in2)) |-> (sum == 8'h00)
    );

// Zero on in2 must pass in1 through the XOR path.
    check_sel_low_in2_zero_passthrough: assert property (
        @(posedge clk) (!sel && (in2 == 8'h00)) |-> (sum == in1)
    );

// Zero on in1 must pass in2 through the XOR path.
    check_sel_low_in1_zero_passthrough: assert property (
        @(posedge clk) (!sel && (in1 == 8'h00)) |-> (sum == in2)
    );

// All ones on in2 must invert in1 on the XOR path.
    check_sel_low_in2_ones_inverts_in1: assert property (
        @(posedge clk) (!sel && (in2 == 8'hFF)) |-> (sum == ~in1)
    );

// Sample the combinational decoder on clk; the RTL has no reset.

    // A=0 and B=0 must drive only O[0] high.
    check_decode_00: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (O === 16'h0001)
    );

// A=0 and B=1 must drive only O[1] high.
    check_decode_01: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b1)) |-> (O === 16'h0002)
    );

// A=1 and B=0 must drive only O[2] high.
    check_decode_10: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b0)) |-> (O === 16'h0004)
    );

// A=1 and B=1 must drive only O[3] high.
    check_decode_11: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (O === 16'h0008)
    );

// Unknown or non-binary inputs must select the default all-zero output.
    check_default_zero_on_unknown: assert property (
        @(posedge clk)
        ((((A !== 1'b0) && (A !== 1'b1)) || ((B !== 1'b0) && (B !== 1'b1))))
        |-> (O === 16'h0000)
    );

// The RTL never drives any output bit above O[3].
    check_upper_outputs_zero: assert property (
        @(posedge clk) (O[15:4] === 12'h000)
    );

// The active decoded output in O[3:0] is one-hot or all-zero.
    check_low_nibble_onehot0: assert property (
        @(posedge clk) $onehot0(O[3:0])
    );

// Synchronous reset clears the counter on the following clock.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 4'h0)
    );

// When enabled below 15, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        enable && (out != 4'hF) |=> (out == ($past(out) + 4'h1))
    );

// When enabled at 15, the counter wraps back to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
        enable && (out == 4'hF) |=> (out == 4'h0)
    );

// When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        !enable |=> (out == $past(out))
    );

// With Bin low, the block reduces to a half subtractor on A and B.
    check_no_borrow_in_reduction: assert property (
        @(posedge clk) !Bin |-> ((D == (A ^ B)) && (Bout == (~A & B)))
    );

// No active select asserts o_error.
    check_no_select_error: assert property (
        @(posedge clk) (!i_select0 && !i_select1 && !i_select2 && !i_select3) |-> o_error
    );

// Exactly one active select clears o_error.
    check_onehot_select_no_error: assert property (
        @(posedge clk)
        (( i_select0 && !i_select1 && !i_select2 && !i_select3) ||
         (!i_select0 &&  i_select1 && !i_select2 && !i_select3) ||
         (!i_select0 && !i_select1 &&  i_select2 && !i_select3) ||
         (!i_select0 && !i_select1 && !i_select2 &&  i_select3)) |-> !o_error
    );

// Two or more active selects assert o_error.
    check_multiple_selects_error: assert property (
        @(posedge clk)
        ((i_select0 && i_select1) ||
         (i_select0 && i_select2) ||
         (i_select0 && i_select3) ||
         (i_select1 && i_select2) ||
         (i_select1 && i_select3) ||
         (i_select2 && i_select3)) |-> o_error
    );

// Add mode outputs the 16-bit sum.
    check_add_mode_function: assert property (
        @(posedge clk) !control |-> (result == (minuend + subtrahend))
    );

// Subtract mode adds the 16-bit two's complement of subtrahend.
    check_sub_mode_function: assert property (
        @(posedge clk) control |-> (result == (minuend + ((~subtrahend) + 16'h0001)))
    );

// Adding zero leaves the minuend unchanged.
    check_add_zero_subtrahend_identity: assert property (
        @(posedge clk) (!control && (subtrahend == 16'h0000)) |-> (result == minuend)
    );

// Subtracting zero leaves the minuend unchanged.
    check_sub_zero_subtrahend_identity: assert property (
        @(posedge clk) (control && (subtrahend == 16'h0000)) |-> (result == minuend)
    );

// With zero minuend in add mode, result matches subtrahend.
    check_add_zero_minuend_passthrough: assert property (
        @(posedge clk) (!control && (minuend == 16'h0000)) |-> (result == subtrahend)
    );

// Subtracting equal operands produces zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (control && (minuend == subtrahend)) |-> (result == 16'h0000)
    );

// With zero minuend in subtract mode, result is the two's complement of subtrahend.
    check_sub_zero_minuend_twos_complement: assert property (
        @(posedge clk) (control && (minuend == 16'h0000)) |-> (result == ((~subtrahend) + 16'h0001))
    );

// Y must equal the OR of all four inputs.
    check_y_matches_four_input_or: assert property (
        @(posedge clk) Y == (A | B | C | D)
    );

// If all inputs are low, Y must be low.
    check_all_inputs_low_drive_y_low: assert property (
        @(posedge clk) !(A | B | C | D) |-> !Y
    );

// A high must force Y high.
    check_a_high_drives_y_high: assert property (
        @(posedge clk) A |-> Y
    );

// B high must force Y high.
    check_b_high_drives_y_high: assert property (
        @(posedge clk) B |-> Y
    );

// C high must force Y high.
    check_c_high_drives_y_high: assert property (
        @(posedge clk) C |-> Y
    );

// D high must force Y high.
    check_d_high_drives_y_high: assert property (
        @(posedge clk) D |-> Y
    );

// Y low implies all inputs are low.
    check_y_low_implies_all_inputs_low: assert property (
        @(posedge clk) !Y |-> !(A | B | C | D)
    );

// Y high implies at least one input is high.
    check_y_high_implies_any_input_high: assert property (
        @(posedge clk) Y |-> (A | B | C | D)
    );

// Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'b0000)
    );

// A sampled reset cycle is followed by count still being zero on the next clock.
    check_reset_holds_count_zero: assert property (
        @(posedge clk) !rst |=> (count == 4'b0000)
    );

// Outside reset, count increments by one every clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 4'hF back to 4'h0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Count advances from zero to one when running.
    check_count_advances_from_zero: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'h0) |=> (count == 4'h1)
    );

// Any nonzero count value can only occur when reset is inactive.
    check_nonzero_count_requires_reset_inactive: assert property (
        @(posedge clk) (count != 4'b0000) |-> rst
    );

// A low reset forces the counter to zero by the next sampled clock.
    check_reset_clears_count: assert property (
        @(posedge clk) (!reset) |=> (count == 4'b0000)
    );

// A load cycle copies load_value into count.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!reset)
        (load == 1'b1) |=> (count == $past(load_value))
    );

// A non-load cycle increments count when it is not at maximum.
    check_increment_no_wrap: assert property (
        @(posedge clk) disable iff (!reset)
        ((load == 1'b0) && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

// A non-load cycle wraps count from 4'hF to 4'h0.
    check_increment_wraps_to_zero: assert property (
        @(posedge clk) disable iff (!reset)
        ((load == 1'b0) && (count == 4'hF)) |=> (count == 4'h0)
    );

// Every active cycle follows the RTL next-state relation.
    check_next_state_relation: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (
            (($past(load) == 1'b1) && (count == $past(load_value))) ||
            (($past(load) == 1'b0) && (count == ($past(count) + 4'd1)))
        )
    );

// A clock edge with reset asserted clears readdata by the next sampled cycle.
    check_reset_clears_readdata: assert property (
        @(posedge clk)
        (!reset_n) |=> (readdata == 32'b0)
    );

// Address 0 captures in_port into readdata on the following cycle.
    check_address_zero_captures_input: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |=> (readdata == {21'b0, $past(in_port)})
    );

// Any nonzero address produces zero readdata on the following cycle.
    check_nonzero_address_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 32'b0)
    );

// Every non-reset update keeps the upper bits of readdata at zero.
    check_readdata_zero_extended: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:11] == 21'b0)
    );

// TABLE_B1 lower-half address changes map to positive odd values.
    check_b1_lower_half_mapping: assert property (
        @(posedge clk)
        ($changed(TABLE_B1_ADDR) && !TABLE_B1_ADDR[3]) |-> (TABLE_B1_OUT == {TABLE_B1_ADDR, 1'b1})
    );

// TABLE_B1 upper-half address changes map to negative odd values.
    check_b1_upper_half_mapping: assert property (
        @(posedge clk)
        ($changed(TABLE_B1_ADDR) && TABLE_B1_ADDR[3]) |-> (TABLE_B1_OUT == {1'b1, ~TABLE_B1_ADDR[2:0], 1'b1})
    );

// Any updated TABLE_B1 value remains odd.
    check_b1_output_is_odd_on_addr_change: assert property (
        @(posedge clk)
        $changed(TABLE_B1_ADDR) |-> (TABLE_B1_OUT[0] == 1'b1)
    );

// Any updated TABLE_B1 sign bit matches the address MSB.
    check_b1_sign_matches_addr_msb_on_addr_change: assert property (
        @(posedge clk)
        $changed(TABLE_B1_ADDR) |-> (TABLE_B1_OUT[4] == TABLE_B1_ADDR[3])
    );

// TABLE_B2 address changes into 0 through 3 map to 57.
    check_b2_low_group_mapping: assert property (
        @(posedge clk)
        ($changed(TABLE_B2_ADDR) && (TABLE_B2_ADDR <= 3'h3)) |-> (TABLE_B2_OUT == 8'd57)
    );

// TABLE_B2 address 4 maps to 77.
    check_b2_addr4_mapping: assert property (
        @(posedge clk)
        ($changed(TABLE_B2_ADDR) && (TABLE_B2_ADDR == 3'h4)) |-> (TABLE_B2_OUT == 8'd77)
    );

// TABLE_B2 address 5 maps to 102.
    check_b2_addr5_mapping: assert property (
        @(posedge clk)
        ($changed(TABLE_B2_ADDR) && (TABLE_B2_ADDR == 3'h5)) |-> (TABLE_B2_OUT == 8'd102)
    );

// TABLE_B2 address 6 maps to 128.
    check_b2_addr6_mapping: assert property (
        @(posedge clk)
        ($changed(TABLE_B2_ADDR) && (TABLE_B2_ADDR == 3'h6)) |-> (TABLE_B2_OUT == 8'd128)
    );

// TABLE_B2 address 7 maps to 153.
    check_b2_addr7_mapping: assert property (
        @(posedge clk)
        ($changed(TABLE_B2_ADDR) && (TABLE_B2_ADDR == 3'h7)) |-> (TABLE_B2_OUT == 8'd153)
    );

// Reset clears the divided clock and the counter.
    check_reset_clears_state: assert property (
        @(posedge CLK)
        RST |-> (CLKOUT == 1'b0) && (clkCount == 24'h000000)
    );

// The counter never exceeds its terminal count.
    check_count_within_range: assert property (
        @(posedge CLK) disable iff (RST)
        clkCount <= cntEndVal
    );

// Before terminal count, the counter advances by one or is asynchronously reset.
    check_nonterminal_count_advances_or_resets: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount < cntEndVal) |=> ((clkCount == ($past(clkCount) + 24'h000001)) || (clkCount == 24'h000000))
    );

// Before terminal count, the output holds its value or is asynchronously reset low.
    check_nonterminal_output_holds_or_resets_low: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount < cntEndVal) |=> ((CLKOUT == $past(CLKOUT)) || (CLKOUT == 1'b0))
    );

// At terminal count, the counter wraps back to zero.
    check_terminal_count_wraps_to_zero: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount == cntEndVal) |=> (clkCount == 24'h000000)
    );

// At terminal count, the output toggles or is asynchronously reset low.
    check_terminal_output_toggles_or_resets_low: assert property (
        @(posedge CLK) disable iff (RST)
        (clkCount == cntEndVal) |=> ((CLKOUT == ~$past(CLKOUT)) || (CLKOUT == 1'b0))
    );

// On sampled reset deassertion, state is still the cleared reset state.
    check_reset_release_state_cleared: assert property (
        @(posedge CLK) disable iff (RST)
        $fell(RST) |-> (CLKOUT == 1'b0) && (clkCount == 24'h000000)
    );

// One cycle after reset release, counting starts or reset has re-cleared state.
    check_first_cycle_after_reset_release: assert property (
        @(posedge CLK) disable iff (RST)
        $fell(RST) |=> (CLKOUT == 1'b0) && ((clkCount == 24'h000001) || (clkCount == 24'h000000))
    );

// Reset forces the registered output to 00.
    check_reset_drives_out_zero: assert property (
        @(posedge clk) rst |=> (out == 2'b00)
    );

// Input 0001 updates the output to 00 on the next clock.
    check_input_0001_maps_to_00: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b0001) |=> (out == 2'b00)
    );

// Input 0010 updates the output to 01 on the next clock.
    check_input_0010_maps_to_01: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b0010) |=> (out == 2'b01)
    );

// Input 0100 updates the output to 10 on the next clock.
    check_input_0100_maps_to_10: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b0100) |=> (out == 2'b10)
    );

// Input 1000 updates the output to 11 on the next clock.
    check_input_1000_maps_to_11: assert property (
        @(posedge clk) disable iff (rst)
        (in == 4'b1000) |=> (out == 2'b11)
    );

// Any other input pattern updates the output to 00 on the next clock.
    check_all_other_inputs_map_to_00: assert property (
        @(posedge clk) disable iff (rst)
        ((in != 4'b0001) && (in != 4'b0010) && (in != 4'b0100) && (in != 4'b1000)) |=> (out == 2'b00)
    );

// In unsigned mode, eq matches the unsigned comparison.
  check_unsigned_eq: assert property (
    @(posedge clk) (cmp_mode === 1'b0) |-> (eq === (num1 == num2))
  );

// In signed mode, eq matches the signed comparison.
  check_signed_eq: assert property (
    @(posedge clk) (cmp_mode === 1'b1) |-> (eq === ($signed(num1) == $signed(num2)))
  );

// Equality is independent of comparison mode.
  check_eq_mode_independent: assert property (
    @(posedge clk) (eq === (num1 == num2))
  );

// Exactly one comparison result is asserted.
  check_results_complete_and_exclusive: assert property (
    @(posedge clk) ((gt || eq || lt) && !(gt && eq) && !(gt && lt) && !(eq && lt))
  );

// Equal inputs produce only the equality result.
  check_equal_inputs_select_eq_only: assert property (
    @(posedge clk) (num1 == num2) |-> (eq && !gt && !lt)
  );

// Outputs match the 2-bit sum of the three 1-bit inputs.
    check_output_matches_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// SUM is the odd-parity function of A, B, and CI.
    check_sum_is_input_parity: assert property (
        @(posedge clk)
        SUM == (A ^ B ^ CI)
    );

// COUT is high when at least two inputs are high.
    check_cout_is_majority: assert property (
        @(posedge clk)
        COUT == ((A & B) | (A & CI) | (B & CI))
    );

// All-zero inputs produce zero outputs.
    check_zero_inputs: assert property (
        @(posedge clk)
        (!A && !B && !CI) |-> ({COUT, SUM} == 2'b00)
    );

// All-one inputs produce both outputs high.
    check_all_one_inputs: assert property (
        @(posedge clk)
        (A && B && CI) |-> ({COUT, SUM} == 2'b11)
    );

// Exactly one high input produces SUM only.
    check_one_high_input: assert property (
        @(posedge clk)
        (( A && !B && !CI) ||
         (!A &&  B && !CI) ||
         (!A && !B &&  CI)) |-> ({COUT, SUM} == 2'b01)
    );

// Exactly two high inputs produce COUT only.
    check_two_high_inputs: assert property (
        @(posedge clk)
        (( A &&  B && !CI) ||
         ( A && !B &&  CI) ||
         (!A &&  B &&  CI)) |-> ({COUT, SUM} == 2'b10)
    );

// Data master constant outputs stay fixed.
    check_data_master_constants: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((d_address == 29'd0) &&
         (d_byteenable == 4'b1111) &&
         (d_writedata == 32'd0))
    );

// Instruction address is tied low.
    check_instruction_address_constant: assert property (
        @(posedge clk) disable iff (!reset_n)
        (i_address == 29'd0)
    );

// Debug and auxiliary outputs are tied low.
    check_debug_outputs_constant_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((debug_mem_slave_debugaccess_to_roms == 1'b0) &&
         (debug_reset_request == 1'b0) &&
         (debug_mem_slave_readdata == 32'd0) &&
         (debug_mem_slave_waitrequest == 1'b0) &&
         (dummy_ci_port == 1'b0))
    );

// A reset cycle clears both read strobes.
    check_reset_clears_reads: assert property (
        @(posedge clk)
        (!reset_n) |=> ((d_read == 1'b0) && (i_read == 1'b0))
    );

// A reset request clears both read strobes.
    check_reset_req_clears_reads: assert property (
        @(posedge clk) disable iff (!reset_n)
        reset_req |=> ((d_read == 1'b0) && (i_read == 1'b0))
    );

// Data waitrequest deasserts both data strobes.
    check_d_waitrequest_deasserts_data_access: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!reset_req && d_waitrequest) |=> ((d_read == 1'b0) && (d_write == 1'b0))
    );

// With no data waitrequest, read asserts and write stays low.
    check_d_ready_asserts_read_only: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!reset_req && !d_waitrequest) |=> ((d_read == 1'b1) && (d_write == 1'b0))
    );

// Instruction waitrequest deasserts the instruction read.
    check_i_waitrequest_deasserts_read: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!reset_req && i_waitrequest) |=> (i_read == 1'b0)
    );

// With no instruction waitrequest, instruction read asserts.
    check_i_ready_asserts_read: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!reset_req && !i_waitrequest) |=> (i_read == 1'b1)
    );

// RTL is combinational with no reset; assertions are sampled on clk.

    // C must equal the implemented two's complement of A.
    check_twos_complement_definition: assert property (
        @(posedge clk) C == (~A + 4'b0001)
    );

// A and C must sum to zero modulo 16.
    check_additive_inverse_wrap: assert property (
        @(posedge clk) (A + C) == 4'h0
    );

// Zero input must produce zero output.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (A == 4'h0) |-> (C == 4'h0)
    );

// Input 1 must produce 4'hF.
    check_one_maps_to_all_ones: assert property (
        @(posedge clk) (A == 4'h1) |-> (C == 4'hF)
    );

// Input 4'h8 is its own 4-bit two's complement.
    check_min_value_is_self_inverse: assert property (
        @(posedge clk) (A == 4'h8) |-> (C == 4'h8)
    );

// Input 4'hF must produce 4'h1.
    check_all_ones_maps_to_one: assert property (
        @(posedge clk) (A == 4'hF) |-> (C == 4'h1)
    );

// Two's complement preserves the least-significant bit.
    check_lsb_preserved: assert property (
        @(posedge clk) C[0] == A[0]
    );

// Synchronous reset clears the program counter.
    check_reset_clears_pc: assert property (
        @(posedge clk) reset |=> (direinstru == 32'd0)
    );

// With no branch request, the program counter increments by 4.
    check_no_branch_request_increments_pc: assert property (
        @(posedge clk) disable iff (reset)
        (!SaltoCond) |=> (direinstru == ($past(direinstru) + 32'd4))
    );

// A high oZero prevents the conditional branch and keeps the increment-by-4 behavior.
    check_zero_blocks_branch: assert property (
        @(posedge clk) disable iff (reset)
        (SaltoCond && oZero) |=> (direinstru == ($past(direinstru) + 32'd4))
    );

// A taken conditional branch loads extSigno shifted left by 2.
    check_taken_branch_loads_target: assert property (
        @(posedge clk) disable iff (reset)
        (SaltoCond && !oZero) |=> (direinstru == ($past(extSigno) << 2))
    );

// X must equal the selected input.
    check_mux_function: assert property (
        @(posedge clk) X == (SEL ? B : A)
    );

// SEL low must route A to X.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (X == A)
    );

// SEL high must route B to X.
    check_sel_high_routes_b: assert property (
        @(posedge clk) SEL |-> (X == B)
    );

// Equal inputs must pass through regardless of SEL.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A == B) |-> (X == A)
    );

// A=0 and B=1 makes X follow SEL.
    check_01_case: assert property (
        @(posedge clk) (!A && B) |-> (X == SEL)
    );

// A=1 and B=0 makes X follow inverted SEL.
    check_10_case: assert property (
        @(posedge clk) (A && !B) |-> (X == ~SEL)
    );

// Y[0] is the XOR of the LSB inputs and carryin.
    check_y0_lsb_sum: assert property (
        @(posedge clk) Y[0] == (A[0] ^ B[0] ^ carryin)
    );

// Y[1] uses the carry generated or propagated from bit 0.
    check_y1_sum_with_bit0_carry: assert property (
        @(posedge clk)
        Y[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & carryin)))
    );

// Y[2] uses the carry generated or propagated through bits 1:0.
    check_y2_sum_with_bit1to0_carry: assert property (
        @(posedge clk)
        Y[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  ((A[1] ^ B[1]) &
                   ((A[0] & B[0]) | ((A[0] ^ B[0]) & carryin)))))
    );

// Y[3] uses the carry generated or propagated through bits 2:0.
    check_y3_sum_with_bit2to0_carry: assert property (
        @(posedge clk)
        Y[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  ((A[2] ^ B[2]) &
                   ((A[1] & B[1]) |
                    ((A[1] ^ B[1]) &
                     ((A[0] & B[0]) | ((A[0] ^ B[0]) & carryin)))))))
    );

// Y matches the 4-bit sum of A, B, and carryin.
    check_y_matches_4bit_sum: assert property (
        @(posedge clk) Y == (A + B + carryin)
    );

// carryout is low when bit 0 is 00.
    check_carryout_low_when_bit0_is_zero_zero: assert property (
        @(posedge clk) ((A[0] == 1'b0) && (B[0] == 1'b0)) |-> (carryout == 1'b0)
    );

// carryout is high when bit 0 is 11.
    check_carryout_high_when_bit0_is_one_one: assert property (
        @(posedge clk) ((A[0] == 1'b1) && (B[0] == 1'b1)) |-> (carryout == 1'b1)
    );

// Output must implement the mux function defined by the select inputs.
    check_mux_function_exact: assert property (
        @(posedge clk) out_always === (((sel_b1 === 1'b1) && (sel_b2 === 1'b1)) ? b : a)
    );

// When both select inputs are high, the output must follow b.
    check_select_b_when_both_high: assert property (
        @(posedge clk) ((sel_b1 === 1'b1) && (sel_b2 === 1'b1)) |-> (out_always === b)
    );

// In every other select case, the output must follow a.
    check_select_a_otherwise: assert property (
        @(posedge clk) ((sel_b1 !== 1'b1) || (sel_b2 !== 1'b1)) |-> (out_always === a)
    );

// When TE is high and EN is 1, ENCLK is 1 on the next sampled cycle.
    check_capture_one_when_te_high: assert property (
        @(posedge CLK) (TE && EN) |=> (ENCLK == 1'b1)
    );

// When TE is high and EN is 0, ENCLK is 0 on the next sampled cycle.
    check_capture_zero_when_te_high: assert property (
        @(posedge CLK) (TE && !EN) |=> (ENCLK == 1'b0)
    );

// When TE is low, ENCLK holds its previous sampled value.
    check_hold_when_te_low: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

// ENCLK can change only if TE was high on the previous clock edge.
    check_change_requires_prior_te: assert property (
        @(posedge CLK) 1'b1 |=> ((ENCLK == $past(ENCLK)) || $past(TE))
    );

// Bit 0 sum matches the first full-adder XOR equation.
    check_sum_bit0_logic: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 2 sum uses the ripple carry generated through bit 1.
    check_sum_bit2_logic: assert property (
        @(posedge clk)
        S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))
            )
        )
    );

// Bit 3 sum uses the ripple carry generated through bit 2.
    check_sum_bit3_logic: assert property (
        @(posedge clk)
        S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (
                        (A[1] & B[1]) |
                        (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) & (A[1] ^ B[1]))
                    ) &
                    (A[2] ^ B[2])
                )
            )
        )
    );

// Output must equal the one-hot decode of the input.
    check_decode_equation: assert property (
        @(posedge clk) out == (16'h0001 << in)
    );

// Decoder output must always be one-hot.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// The bit selected by the input must be high.
    check_selected_bit_high: assert property (
        @(posedge clk) out[in] == 1'b1
    );

// Input value 0 must select bit 0.
    check_decode_zero: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 16'h0001)
    );

// Input value 15 must select bit 15.
    check_decode_fifteen: assert property (
        @(posedge clk) (in == 4'd15) |-> (out == 16'h8000)
    );

// out must exactly reflect whether A is greater than B.
    check_out_matches_gt_compare: assert property (
        @(posedge clk) (out == (A > B))
    );

// Greater-than case drives out high.
    check_out_high_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (out == 1'b1)
    );

// Less-than case drives out low.
    check_out_low_when_a_lt_b: assert property (
        @(posedge clk) (A < B) |-> (out == 1'b0)
    );

// Equal case drives out low.
    check_out_low_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (out == 1'b0)
    );

// Y must match the implemented OR-of-ANDs logic.
    check_output_definition: assert property (
        @(posedge clk) Y == ((A & ~B) | (C & ~D))
    );

// A high and B low must drive Y high.
    check_ab_term_sets_output: assert property (
        @(posedge clk) (A && !B) |-> Y
    );

// C high and D low must drive Y high.
    check_cd_term_sets_output: assert property (
        @(posedge clk) (C && !D) |-> Y
    );

// Y must be low when both product terms are false.
    check_output_low_when_both_terms_false: assert property (
        @(posedge clk) (!(A && !B) && !(C && !D)) |-> !Y
    );

// clock_50 is the sequential clock.
    // reset_n is an active-low reset.
    // data_stand conditionally captures data_rec when clock_recovery is high.

    // When reset is sampled low, data_stand is zero by the next clock sample.
    check_reset_clears_data_stand: assert property (
        @(posedge clock_50) !reset_n |=> (data_stand == 8'd0)
    );

// The registered next value follows the RTL update function.
    check_registered_update_function: assert property (
        @(posedge clock_50) disable iff (!reset_n)
        1'b1 |=> (data_stand == ($past(clock_recovery) ? $past(data_rec) : $past(data_stand)))
    );

// When clock_recovery is high, data_stand captures data_rec.
    check_capture_when_recovery_high: assert property (
        @(posedge clock_50) disable iff (!reset_n)
        clock_recovery |=> (data_stand == $past(data_rec))
    );

// When clock_recovery is low, data_stand holds its previous value.
    check_hold_when_recovery_low: assert property (
        @(posedge clock_50) disable iff (!reset_n)
        !clock_recovery |=> (data_stand == $past(data_stand))
    );

// D is always the 2-bit sum of Q and Q_reg_2.
    check_d_matches_sum: assert property (
        @(posedge CLK) disable iff (!AR) D == (Q + Q_reg_2)
    );

// D[0] is the sum LSB of the two input words.
    check_d_lsb_matches_input_lsb_sum: assert property (
        @(posedge CLK) disable iff (!AR) D[0] == (Q[0] ^ Q_reg_2[0])
    );

// D[1] includes the carry from bit 0.
    check_d_msb_matches_input_msb_sum: assert property (
        @(posedge CLK) disable iff (!AR) D[1] == (Q[1] ^ Q_reg_2[1] ^ (Q[0] & Q_reg_2[0]))
    );

// Q_reg_0 captures the previous cycle's D[0] when not in reset.
    check_q_reg_0_captures_previous_d0: assert property (
        @(posedge CLK) disable iff (!AR) 1'b1 |=> (Q_reg_0[0] == $past(D[0]))
    );

// Low reset clears q on the next cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) !resetn |=> (q == 26'b0)
    );

// Low squash clears q on the next cycle.
    check_squash_clears_q: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn) |=> (q == 26'b0)
    );

// Enable captures d into q on the next cycle.
    check_enable_captures_d: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && en) |=> (q == $past(d))
    );

// Without enable or clear, q holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!resetn) (squashn && !en) |=> (q == $past(q))
    );

// Squash takes priority over enable.
    check_squash_overrides_enable: assert property (
        @(posedge clk) disable iff (!resetn) (!squashn && en) |=> (q == 26'b0)
    );

// Y must always be the bitwise inverse of Z.
    check_output_is_bitwise_inverse: assert property (
        @(posedge clk) (Y === ~Z)
    );

// A high Z must produce a low Y.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) (Z === 1'b1) |-> (Y === 1'b0)
    );

// A low Z must produce a high Y.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) (Z === 1'b0) |-> (Y === 1'b1)
    );

// Sum matches the three-input XOR equation.
    check_sum_equation: assert property (
        @(posedge clk) (S == (A ^ B ^ Cin))
    );

// Carry matches the implemented carry equation.
    check_carry_equation: assert property (
        @(posedge clk) (Cout == ((A & B) | (Cin & (A ^ B))))
    );

// 000 produces zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !Cin) |-> (!S && !Cout)
    );

// 100 produces sum one and no carry.
    check_only_a_high_case: assert property (
        @(posedge clk) (A && !B && !Cin) |-> (S && !Cout)
    );

// 010 produces sum one and no carry.
    check_only_b_high_case: assert property (
        @(posedge clk) (!A && B && !Cin) |-> (S && !Cout)
    );

// 001 produces sum one and no carry.
    check_only_cin_high_case: assert property (
        @(posedge clk) (!A && !B && Cin) |-> (S && !Cout)
    );

// 110 produces zero sum and carry one.
    check_a_b_high_case: assert property (
        @(posedge clk) (A && B && !Cin) |-> (!S && Cout)
    );

// 101 produces zero sum and carry one.
    check_a_cin_high_case: assert property (
        @(posedge clk) (A && !B && Cin) |-> (!S && Cout)
    );

// 011 produces zero sum and carry one.
    check_b_cin_high_case: assert property (
        @(posedge clk) (!A && B && Cin) |-> (!S && Cout)
    );

// 111 produces sum one and carry one.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && Cin) |-> (S && Cout)
    );

// Combinational 4:1 mux; RTL has no clock or reset, so clk is the sampling clock.

    // Z matches the RTL sum-of-products equation.
    check_output_matches_sop: assert property (
        @(posedge clk)
        Z == ((A & ~S1 & ~S0) |
              (B & ~S1 &  S0) |
              (C &  S1 & ~S0) |
              (D &  S1 &  S0))
    );

// Z matches the selected input.
    check_output_matches_selected_input: assert property (
        @(posedge clk)
        Z == (S1 ? (S0 ? D : C) : (S0 ? B : A))
    );

// When S1S0 is 00, Z routes A.
    check_select_00_routes_a: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Z == A)
    );

// When S1S0 is 01, Z routes B.
    check_select_01_routes_b: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Z == B)
    );

// When S1S0 is 10, Z routes C.
    check_select_10_routes_c: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Z == C)
    );

// When S1S0 is 11, Z routes D.
    check_select_11_routes_d: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Z == D)
    );

// Z matches the implemented combinational equation.
    check_output_equation: assert property (
        @(posedge clk) Z == (TE_B & (A | B | C) & ~(A & B & C))
    );

// TE_B low forces Z low.
    check_teb_low_forces_z_low: assert property (
        @(posedge clk) (TE_B == 1'b0) |-> (Z == 1'b0)
    );

// All-zero inputs force Z low.
    check_all_zero_inputs_force_z_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0)) |-> (Z == 1'b0)
    );

// All-one inputs force Z low.
    check_all_one_inputs_force_z_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1) && (C == 1'b1)) |-> (Z == 1'b0)
    );

// With TE_B high, mixed data inputs drive Z high.
    check_enabled_mixed_inputs_force_z_high: assert property (
        @(posedge clk)
        ((TE_B == 1'b1) && ((A | B | C) == 1'b1) && ((A & B & C) == 1'b0))
        |-> (Z == 1'b1)
    );

// A high output requires TE_B to be high.
    check_z_requires_teb_high: assert property (
        @(posedge clk) (Z == 1'b1) |-> (TE_B == 1'b1)
    );

// A high output requires inputs to be neither all-zero nor all-one.
    check_z_requires_mixed_inputs: assert property (
        @(posedge clk) (Z == 1'b1) |-> (((A | B | C) == 1'b1) && ((A & B & C) == 1'b0))
    );

// Disabled decoder drives all outputs low.
    check_disable_drives_zero: assert property (
        @(posedge clk) (!EN) |-> (Y == 8'b00000000)
    );

// Input 000 selects bit 0 when enabled.
    check_decode_000: assert property (
        @(posedge clk) (EN && !A && !B && !C) |-> (Y == 8'b00000001)
    );

// Input 001 selects bit 1 when enabled.
    check_decode_001: assert property (
        @(posedge clk) (EN && !A && !B && C) |-> (Y == 8'b00000010)
    );

// Input 010 selects bit 2 when enabled.
    check_decode_010: assert property (
        @(posedge clk) (EN && !A && B && !C) |-> (Y == 8'b00000100)
    );

// Input 011 selects bit 3 when enabled.
    check_decode_011: assert property (
        @(posedge clk) (EN && !A && B && C) |-> (Y == 8'b00001000)
    );

// Input 100 selects bit 4 when enabled.
    check_decode_100: assert property (
        @(posedge clk) (EN && A && !B && !C) |-> (Y == 8'b00010000)
    );

// Input 101 selects bit 5 when enabled.
    check_decode_101: assert property (
        @(posedge clk) (EN && A && !B && C) |-> (Y == 8'b00100000)
    );

// Input 110 selects bit 6 when enabled.
    check_decode_110: assert property (
        @(posedge clk) (EN && A && B && !C) |-> (Y == 8'b01000000)
    );

// Input 111 selects bit 7 when enabled.
    check_decode_111: assert property (
        @(posedge clk) (EN && A && B && C) |-> (Y == 8'b10000000)
    );

// Enabled decoder output must be one-hot encoded.
    check_enabled_output_onehot: assert property (
        @(posedge clk) EN |-> (
            (Y == 8'b00000001) ||
            (Y == 8'b00000010) ||
            (Y == 8'b00000100) ||
            (Y == 8'b00001000) ||
            (Y == 8'b00010000) ||
            (Y == 8'b00100000) ||
            (Y == 8'b01000000) ||
            (Y == 8'b10000000)
        )
    );

// Clock: posedge clk.
    // Reset: synchronous active-high.
    // Behavior: reset has priority over set, then d is captured.

    // Reset drives q low and q_n high.
    check_reset_state: assert property (
        @(posedge clk) reset |=> (q == 1'b0 && q_n == 1'b1)
    );

// Set drives q high and q_n low when reset is inactive.
    check_set_state: assert property (
        @(posedge clk) disable iff (reset) set |=> (q == 1'b1 && q_n == 1'b0)
    );

// A low d is captured when set and reset are low.
    check_capture_zero: assert property (
        @(posedge clk) disable iff (reset) (!set && !d) |=> (q == 1'b0 && q_n == 1'b1)
    );

// A high d is captured when set and reset are low.
    check_capture_one: assert property (
        @(posedge clk) disable iff (reset) (!set && d) |=> (q == 1'b1 && q_n == 1'b0)
    );

// The outputs remain complementary after each clocked update.
    check_complementary_outputs: assert property (
        @(posedge clk) 1'b1 |=> (q_n == ~q)
    );

// When reset is asserted, the output is cleared to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 8'b0)
    );

// When shift is asserted, the next output value matches the input bus.
    check_shift_updates_out_from_in: assert property (
        @(posedge clk) disable iff (reset)
        shift |=> (out == $past(in))
    );

// When shift is deasserted, the output holds its previous value.
    check_no_shift_holds_out: assert property (
        @(posedge clk) disable iff (reset)
        !shift |=> (out == $past(out))
    );

// Output must implement the selected invert or pass-through function.
    check_output_function: assert property (
        @(posedge clk) data_out == (enable ? ~data_in : data_in)
    );

// When enable is low, output must pass input through unchanged.
    check_passthrough_when_disabled: assert property (
        @(posedge clk) !enable |-> (data_out == data_in)
    );

// When enable is high, output must be the bitwise inverse of input.
    check_invert_when_enabled: assert property (
        @(posedge clk) enable |-> (data_out == ~data_in)
    );

// Bit 0 must follow the selected function.
    check_bit0_function: assert property (
        @(posedge clk) data_out[0] == (enable ? ~data_in[0] : data_in[0])
    );

// Bit 1 must follow the selected function.
    check_bit1_function: assert property (
        @(posedge clk) data_out[1] == (enable ? ~data_in[1] : data_in[1])
    );

// Bit 2 must follow the selected function.
    check_bit2_function: assert property (
        @(posedge clk) data_out[2] == (enable ? ~data_in[2] : data_in[2])
    );

// Bit 3 must follow the selected function.
    check_bit3_function: assert property (
        @(posedge clk) data_out[3] == (enable ? ~data_in[3] : data_in[3])
    );

// Y must match the RTL mux equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ((S1 & S0 & D) | (S1 & ~S0 & C) | (~S1 & S0 & B) | (~S1 & ~S0 & A))
    );

// Select 00 routes A to Y.
    check_select_00_routes_a: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == A)
    );

// Select 01 routes B to Y.
    check_select_01_routes_b: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Y == B)
    );

// Select 10 routes C to Y.
    check_select_10_routes_c: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Y == C)
    );

// Select 11 routes D to Y.
    check_select_11_routes_d: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Y == D)
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel === 2'b00) |-> (out === in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel === 2'b01) |-> (out === in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel === 2'b10) |-> (out === in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel === 2'b11) |-> (out === in3)
    );

// Any non-binary select value drives the default zero output.
    check_invalid_sel_routes_zero: assert property (
        @(posedge clk)
        !((sel === 2'b00) || (sel === 2'b01) || (sel === 2'b10) || (sel === 2'b11))
        |-> (out === 4'b0000)
    );

// in1 has highest priority and selects the S0 output pattern.
    check_in1_priority_output: assert property (
        @(posedge clk) in1 |-> (out1 == 1'b1 && out2 == 1'b0)
    );

// in2 selects the S1 output pattern when in1 is low.
    check_in2_priority_output: assert property (
        @(posedge clk) (!in1 && in2) |-> (out1 == 1'b0 && out2 == 1'b1)
    );

// in3 selects the S2 output pattern when higher-priority inputs are low.
    check_in3_priority_output: assert property (
        @(posedge clk) (!in1 && !in2 && in3) |-> (out1 == 1'b1 && out2 == 1'b1)
    );

// No asserted inputs selects the S3 output pattern.
    check_no_input_output: assert property (
        @(posedge clk) (!in1 && !in2 && !in3) |-> (out1 == 1'b0 && out2 == 1'b0)
    );

// Output 10 only occurs when in1 is asserted.
    check_output_10_source: assert property (
        @(posedge clk) (out1 == 1'b1 && out2 == 1'b0) |-> in1
    );

// Output 01 only occurs when in1 is low and in2 is asserted.
    check_output_01_source: assert property (
        @(posedge clk) (out1 == 1'b0 && out2 == 1'b1) |-> (!in1 && in2)
    );

// Output 11 only occurs when only in3 wins the priority selection.
    check_output_11_source: assert property (
        @(posedge clk) (out1 == 1'b1 && out2 == 1'b1) |-> (!in1 && !in2 && in3)
    );

// Output 00 only occurs when all inputs are deasserted.
    check_output_00_source: assert property (
        @(posedge clk) (out1 == 1'b0 && out2 == 1'b0) |-> (!in1 && !in2 && !in3)
    );

// X must match the implemented comparison behavior.
    check_output_matches_implemented_logic: assert property (
        @(posedge clk)
        X == ((A > C) ? 1'b1 : 1'b0)
    );

// A high and C low must drive X high.
    check_output_high_when_a_high_c_low: assert property (
        @(posedge clk)
        ((A == 1'b1) && (C == 1'b0)) |-> (X == 1'b1)
    );

// X can only be high when A is high and C is low.
    check_output_high_only_for_a_gt_c: assert property (
        @(posedge clk)
        (X == 1'b1) |-> ((A == 1'b1) && (C == 1'b0))
    );

// When C is low, X must track A.
    check_output_tracks_a_when_c_low: assert property (
        @(posedge clk)
        (C == 1'b0) |-> (X == A)
    );

// When A is high, X must be the inverse of C.
    check_output_tracks_inverse_c_when_a_high: assert property (
        @(posedge clk)
        (A == 1'b1) |-> (X == ~C)
    );

// If A is low or C is high, X must be low.
    check_output_low_when_not_a_gt_c: assert property (
        @(posedge clk)
        ((A == 1'b0) || (C == 1'b1)) |-> (X == 1'b0)
    );

// Active-low reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge CLK)
        !RESET |-> (Q == 1'b0)
    );

// A sampled reset leaves Q low through the next clock sample.
    check_reset_value_persists_to_next_clock: assert property (
        @(posedge CLK)
        !RESET |=> (Q == 1'b0)
    );

// When enabled, Q captures D on the clock edge.
    check_load_when_enabled: assert property (
        @(posedge CLK) disable iff (!RESET)
        EN |=> (Q == $past(D))
    );

// When disabled, Q holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!RESET)
        !EN |=> (Q == $past(Q))
    );

// Y matches the implemented NOT/NOR/AND logic.
    check_output_function: assert property (
        @(posedge clk) Y == ~(~B1_N | (A1 & A2))
    );

// A low B1_N forces the output low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) !B1_N |-> !Y
    );

// When both A inputs are high, the output must be low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1_N high and A1 low, the output must be high.
    check_a1_low_allows_y_high: assert property (
        @(posedge clk) (B1_N && !A1) |-> Y
    );

// With B1_N high and A2 low, the output must be high.
    check_a2_low_allows_y_high: assert property (
        @(posedge clk) (B1_N && !A2) |-> Y
    );

// A high output requires B1_N to be high.
    check_y_high_requires_b1n_high: assert property (
        @(posedge clk) Y |-> B1_N
    );

// A high output requires the A-input AND term to be low.
    check_y_high_requires_and_term_low: assert property (
        @(posedge clk) Y |-> !(A1 && A2)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (Q == 3'b000)
    );

// When not in reset and counting up, Q increments by one.
    check_count_up: assert property (
        @(posedge clk) disable iff (reset)
        up_down |=> (Q == ($past(Q) + 3'd1))
    );

// When not in reset and counting down, Q decrements by one.
    check_count_down: assert property (
        @(posedge clk) disable iff (reset)
        !up_down |=> (Q == ($past(Q) - 3'd1))
    );

// Counting up from 7 wraps back to 0.
    check_wrap_up_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (Q == 3'b111 && up_down) |=> (Q == 3'b000)
    );

// Counting down from 0 wraps back to 7.
    check_wrap_down_from_zero: assert property (
        @(posedge clk) disable iff (reset)
        (Q == 3'b000 && !up_down) |=> (Q == 3'b111)
    );

// A sampled reset cycle leaves result cleared through the next clock edge.
    check_reset_clears_result: assert property (
        @(posedge clk) rst |=> (result == 8'h00)
    );

// When add is selected, result updates to the prior cycle's a + b.
    check_add_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 1'b0) |=> (result == ($past(a) + $past(b)))
    );

// When subtract is selected, result updates to the prior cycle's a - b.
    check_sub_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == 1'b1) |=> (result == ($past(a) - $past(b)))
    );

// X must equal the AND function implemented by the RTL.
    check_x_matches_and_of_inputs: assert property (
        @(posedge clk) X === ((A === 1'b1) && (B === 1'b1) && (C === 1'b1))
    );

// When all inputs are exactly 1, X must be 1.
    check_x_high_when_all_inputs_high: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1) && (C === 1'b1)) |-> (X === 1'b1)
    );

// If any input is not exactly 1, X must be 0.
    check_x_low_when_any_input_not_high: assert property (
        @(posedge clk) ((A !== 1'b1) || (B !== 1'b1) || (C !== 1'b1)) |-> (X === 1'b0)
    );

// RTL has no native clock or reset; clk is used only for assertion sampling.
    // The logic is purely combinational and implements Y = S0 ? (A & ~B) : (A & B).

    // Y must always match the muxed AND function implemented in the RTL.
    check_mux_function_exact: assert property (
        @(posedge clk) Y == (S0 ? (A & ~B) : (A & B))
    );

// When S0 is low, Y must select the A & B path.
    check_select_low_path: assert property (
        @(posedge clk) !S0 |-> (Y == (A & B))
    );

// When S0 is high, Y must select the A & ~B path.
    check_select_high_path: assert property (
        @(posedge clk) S0 |-> (Y == (A & ~B))
    );

// If A is low, both product terms are low and Y must be low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// A high Y requires A high and the selected B polarity to be true.
    check_y_high_requires_active_path: assert property (
        @(posedge clk) Y |-> (A && (S0 ? ~B : B))
    );

// If B matches S0, neither selected product term can drive Y high.
    check_b_matches_select_forces_y_low: assert property (
        @(posedge clk) !(B ^ S0) |-> !Y
    );

// In add mode, result captures A + B on the next clock.
    check_add_mode_result: assert property (
        @(posedge clk) (Sub == 1'b0) |=> (result == ($past(A) + $past(B)))
    );

// In subtract mode, result captures A - B on the next clock.
    check_sub_mode_result: assert property (
        @(posedge clk) (Sub == 1'b1) |=> (result == ($past(A) - $past(B)))
    );

// Result always reflects the operation selected on the previous clock.
    check_selected_operation_result: assert property (
        @(posedge clk) 1'b1 |=> (result == ($past(Sub) ? ($past(A) - $past(B)) : ($past(A) + $past(B))))
    );

// Subtracting equal operands produces zero on the next clock.
    check_equal_operands_subtract_zero: assert property (
        @(posedge clk) (Sub == 1'b1 && A == B) |=> (result == 4'b0000)
    );

// Adding zero on B passes A through on the next clock.
    check_add_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b0 && B == 4'b0000) |=> (result == $past(A))
    );

// A sampled reset forces the next sampled counter value to zero.
    check_reset_forces_zero_next_cycle: assert property (
        @(posedge clk)
        reset |=> (out == 4'h0)
    );

// Non-maximum values increment by one on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (out != 4'hF) |=> (out == ($past(out) + 4'h1))
    );

// The counter wraps from 15 back to zero on the next clock.
    check_wrap_after_max: assert property (
        @(posedge clk) disable iff (reset)
        (out == 4'hF) |=> (out == 4'h0)
    );

// Every active clock changes the counter value.
    check_counter_advances_each_active_cycle: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out != $past(out))
    );

// First branch forces output1 high.
    check_first_branch_sets_high: assert property (
        @(posedge clk) (input1 && input2) |-> (output1 == 1'b1)
    );

// Second branch forces output1 low when the first branch is not taken.
    check_second_branch_sets_low: assert property (
        @(posedge clk) (!(input1 && input2) && !input3 && !input4) |-> (output1 == 1'b0)
    );

// Third branch forces output1 high when higher-priority branches are not taken.
    check_third_branch_sets_high: assert property (
        @(posedge clk) (!(input1 && input2) && (input3 || input4) && input5 && input6 && input7) |-> (output1 == 1'b1)
    );

// Default branch passes input8 when no earlier branch matches.
    check_default_branch_follows_input8: assert property (
        @(posedge clk) (!(input1 && input2) && (input3 || input4) && !(input5 && input6 && input7)) |-> (output1 == input8)
    );

// output1 matches the full priority-ordered combinational function.
    check_full_priority_function: assert property (
        @(posedge clk)
        output1 == ((input1 && input2) ? 1'b1 :
                    ((!input3 && !input4) ? 1'b0 :
                    ((input5 && input6 && input7) ? 1'b1 : input8)))
    );

// RTL has no clock or reset; sample the combinational logic on an external clock.

    // Output matches the NAND of the input with itself.
    check_self_nand_function: assert property (
        @(posedge clk) out === ~(in & in)
    );

// Output behaves as the inversion of the input.
    check_inverter_function: assert property (
        @(posedge clk) out === ~in
    );

// A low input drives the output high.
    check_low_input_drives_high: assert property (
        @(posedge clk) (in == 1'b0) |-> (out == 1'b1)
    );

// A high input drives the output low.
    check_high_input_drives_low: assert property (
        @(posedge clk) (in == 1'b1) |-> (out == 1'b0)
    );

// Y must match the implemented NOT/AND/NOR/BUF logic.
    check_y_matches_implemented_logic: assert property (
        @(posedge clk) (Y == (~((~B1_N) | (A1 & A2))))
    );

// A low B1_N forces the NOR output, and therefore Y, low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) (B1_N == 1'b0) |-> (Y == 1'b0)
    );

// High A1 and A2 drive the AND term high and force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) ((A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b0)
    );

// With B1_N high and A1 low, the NOR output must be high.
    check_b1n_high_a1_low_drives_y_high: assert property (
        @(posedge clk) ((B1_N == 1'b1) && (A1 == 1'b0)) |-> (Y == 1'b1)
    );

// With B1_N high and A2 low, the NOR output must be high.
    check_b1n_high_a2_low_drives_y_high: assert property (
        @(posedge clk) ((B1_N == 1'b1) && (A2 == 1'b0)) |-> (Y == 1'b1)
    );

// The 5-bit output must equal A + B + CIN.
    check_total_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0000, CIN})
    );

// The least-significant sum bit matches the first full-adder XOR.
    check_lsb_sum: assert property (
        @(posedge clk)
        SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

// Carry-out reflects overflow of the 4-bit addition.
    check_cout_overflow: assert property (
        @(posedge clk)
        COUT == (({1'b0, A} + {1'b0, B} + {4'b0000, CIN}) > 5'd15)
    );

// With no carry-in, the result matches A + B.
    check_add_without_cin: assert property (
        @(posedge clk)
        !CIN |-> ({COUT, SUM} == ({1'b0, A} + {1'b0, B}))
    );

// With carry-in asserted, the result matches A + B + 1.
    check_add_with_cin: assert property (
        @(posedge clk)
        CIN |-> ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + 5'b00001))
    );

// Adding zero to A with no carry-in returns A and no carry-out.
    check_a_identity: assert property (
        @(posedge clk)
        (B == 4'b0000 && !CIN) |-> (SUM == A && COUT == 1'b0)
    );

// Adding zero to B with no carry-in returns B and no carry-out.
    check_b_identity: assert property (
        @(posedge clk)
        (A == 4'b0000 && !CIN) |-> (SUM == B && COUT == 1'b0)
    );

// Zero plus zero produces only the carry-in in the result.
    check_zero_inputs: assert property (
        @(posedge clk)
        (A == 4'b0000 && B == 4'b0000) |-> ({COUT, SUM} == {4'b0000, CIN})
    );

// A carry-in propagates through all bits when the other operand is all ones.
    check_cin_propagation: assert property (
        @(posedge clk)
        (((A == 4'hF) && (B == 4'h0) && (CIN == 1'b1)) ||
         ((A == 4'h0) && (B == 4'hF) && (CIN == 1'b1)))
        |-> (SUM == 4'h0 && COUT == 1'b1)
    );

// Maximum inputs with carry-in overflow and leave SUM at all ones.
    check_max_input_overflow: assert property (
        @(posedge clk)
        (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> (SUM == 4'hF && COUT == 1'b1)
    );

// Active-low reset forces the counter and both combinational outputs to zero.
    check_reset_clears_all: assert property (
        @(posedge CLK) !CLR |-> (counter_output == 4'd0 && bitwise_and_output == 4'd0 && Y == 4'd0)
    );

// The bitwise_and block outputs counter_output AND DATA.
    check_bitwise_and_function: assert property (
        @(posedge CLK) disable iff (!CLR)
        bitwise_and_output == (counter_output & DATA)
    );

// The functional_module outputs bitwise_and_output AND counter_output.
    check_final_output_function: assert property (
        @(posedge CLK) disable iff (!CLR)
        Y == (bitwise_and_output & counter_output)
    );

// The final output matches the intermediate AND result.
    check_output_matches_intermediate: assert property (
        @(posedge CLK) disable iff (!CLR)
        Y == bitwise_and_output
    );

// The top-level output equals counter_output masked by DATA.
    check_output_mask_relation: assert property (
        @(posedge CLK) disable iff (!CLR)
        Y == (counter_output & DATA)
    );

// Zero DATA forces both combinational outputs low.
    check_zero_data_forces_zero_output: assert property (
        @(posedge CLK) disable iff (!CLR)
        (DATA == 4'd0) |-> (bitwise_and_output == 4'd0 && Y == 4'd0)
    );

// All-ones DATA passes counter_output through both combinational stages.
    check_all_ones_data_passes_counter: assert property (
        @(posedge CLK) disable iff (!CLR)
        (DATA == 4'hF) |-> (bitwise_and_output == counter_output && Y == counter_output)
    );

// All-ones counter_output passes DATA through both combinational stages.
    check_all_ones_counter_passes_data: assert property (
        @(posedge CLK) disable iff (!CLR)
        (counter_output == 4'hF) |-> (bitwise_and_output == DATA && Y == DATA)
    );

// ENCLK must be low while CLK is low.
    check_enclk_low_on_low_clk_phase: assert property (
        @(posedge CLK) ENCLK == 1'b0
    );

// During CLK high, ENCLK must equal EN masked by active-low TE.
    check_enclk_matches_gate_on_high_clk_phase: assert property (
        @(negedge CLK) ENCLK == (EN & ~TE)
    );

// Outside TE-low reset, TE high must block the gated clock.
    check_te_high_blocks_enclk: assert property (
        @(negedge CLK) disable iff (!TE) ENCLK == 1'b0
    );

// With TE low, ENCLK must follow EN during CLK high.
    check_te_low_passes_en_to_enclk: assert property (
        @(negedge CLK) !TE |-> (ENCLK == EN)
    );

// A high ENCLK requires EN high and TE low.
    check_enclk_high_has_valid_controls: assert property (
        @(negedge CLK) ENCLK |-> (EN && !TE)
    );

// Output stays within the values produced by the case mapping.
    check_out_valid_range: assert property (
        @(posedge clk) disable iff (rst)
        (out <= 7)
    );

// Output 0 is a stable fixed point.
    check_out_zero_stays_zero: assert property (
        @(posedge clk) disable iff (rst)
        (out == '0) |=> (out == '0)
    );

// Output 1 is a stable fixed point.
    check_out_one_stays_one: assert property (
        @(posedge clk) disable iff (rst)
        (out == 1) |=> (out == 1)
    );

// Bit 1 is the XOR of the first two cross products.
    check_bit1_partial_sum: assert property (
        @(posedge clk) out[1] == ((in1[1] & in2[0]) ^ (in1[0] & in2[1]))
    );

// Bit 2 includes the carry generated from bit 1 accumulation.
    check_bit2_partial_sum: assert property (
        @(posedge clk)
        out[2] == ((in1[2] & in2[0]) ^
                   (in1[1] & in2[1]) ^
                   (in1[0] & in2[2]) ^
                   ((in1[1] & in2[0]) & (in1[0] & in2[1])))
    );

// Multiplying by 8 shifts the second operand left by three.
    check_shift_by_msb_in1: assert property (
        @(posedge clk) (in1 == 4'h8) |-> (out == ({4'b0000, in2} << 3))
    );

// Multiplying by 8 shifts the first operand left by three.
    check_shift_by_msb_in2: assert property (
        @(posedge clk) (in2 == 4'h8) |-> (out == ({4'b0000, in1} << 3))
    );

// select 11 routes in3 to out.
    check_select_11_routes_in3: assert property (
        @(posedge clk) (select == 2'b11) |-> (out === in3)
    );

// X matches the implemented NOR-NOR-BUF function.
    check_boolean_function: assert property (
        @(posedge clk) X == ((A1 | A2) & ~B1_N)
    );

// A high B1_N input forces the output low.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk) (B1_N == 1'b1) |-> (X == 1'b0)
    );

// When both A inputs are low, the output must be low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// A1 high with B1_N low drives the output high.
    check_a1_with_b1n_low_drives_x_high: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

// A2 high with B1_N low drives the output high.
    check_a2_with_b1n_low_drives_x_high: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

// A high output requires B1_N low and at least one A input high.
    check_x_high_has_valid_enables: assert property (
        @(posedge clk) (X == 1'b1) |-> ((B1_N == 1'b0) && ((A1 == 1'b1) || (A2 == 1'b1)))
    );

// Reset clears the counter on the next clock sample.
    check_reset_clears_q: assert property (
        @(posedge clock) reset |=> (Q == 4'b0000)
    );

// Reset has priority even when count enable is high.
    check_reset_priority_over_enable: assert property (
        @(posedge clock) reset && count_enable |=> (Q == 4'b0000)
    );

// When enabled without reset, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clock) disable iff (reset) count_enable |=> (Q == ($past(Q) + 4'd1))
    );

// When disabled without reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (reset) !count_enable |=> (Q == $past(Q))
    );

// out matches the implemented NAND network.
    check_out_equation: assert property (
        @(posedge clk)
        out == (
            (~((~S[1]) & S[0])) &
            (~((~S[1]) & (~S[0]))) &
            (~((~(S[1] & S[0])) & A[0] & A[1])) &
            (~((~(S[1] & (~S[0]))) & A[1] & A[2]))
        )
    );

// When S[1] is low, the output is forced low.
    check_s1_low_forces_out_low: assert property (
        @(posedge clk)
        (S[1] == 1'b0) |-> (out == 1'b0)
    );

// For select 2'b10, out is the NAND of A[0] and A[1].
    check_sel_10_function: assert property (
        @(posedge clk)
        (S == 2'b10) |-> (out == ~(A[0] & A[1]))
    );

// For select 2'b11, out is the NAND of A[1] and A[2].
    check_sel_11_function: assert property (
        @(posedge clk)
        (S == 2'b11) |-> (out == ~(A[1] & A[2]))
    );

// With S[1] high and A[1] low, the output must be high.
    check_s1_high_a1_low_forces_out_high: assert property (
        @(posedge clk)
        ((S[1] == 1'b1) && (A[1] == 1'b0)) |-> (out == 1'b1)
    );

// For select 2'b10, A[0] and A[1] both high drive out low.
    check_sel_10_pair_high_forces_out_low: assert property (
        @(posedge clk)
        ((S == 2'b10) && (A[0] == 1'b1) && (A[1] == 1'b1)) |-> (out == 1'b0)
    );

// For select 2'b10, if A[0:1] are not both high then out is high.
    check_sel_10_pair_not_high_forces_out_high: assert property (
        @(posedge clk)
        ((S == 2'b10) && !(A[0] & A[1])) |-> (out == 1'b1)
    );

// For select 2'b11, A[1] and A[2] both high drive out low.
    check_sel_11_pair_high_forces_out_low: assert property (
        @(posedge clk)
        ((S == 2'b11) && (A[1] == 1'b1) && (A[2] == 1'b1)) |-> (out == 1'b0)
    );

// For select 2'b11, if A[1:2] are not both high then out is high.
    check_sel_11_pair_not_high_forces_out_high: assert property (
        @(posedge clk)
        ((S == 2'b11) && !(A[1] & A[2])) |-> (out == 1'b1)
    );

// X must equal the 3-input XOR of A, B, and C.
    check_x_matches_xor3: assert property (
        @(posedge clk) X === (A ^ B ^ C)
    );

// 000 must drive X low.
    check_x_low_for_000: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0) && (C === 1'b0)) |-> (X === 1'b0)
    );

// 001 must drive X high.
    check_x_high_for_001: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0) && (C === 1'b1)) |-> (X === 1'b1)
    );

// 010 must drive X high.
    check_x_high_for_010: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b1) && (C === 1'b0)) |-> (X === 1'b1)
    );

// 011 must drive X low.
    check_x_low_for_011: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b1) && (C === 1'b1)) |-> (X === 1'b0)
    );

// 100 must drive X high.
    check_x_high_for_100: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b0) && (C === 1'b0)) |-> (X === 1'b1)
    );

// 101 must drive X low.
    check_x_low_for_101: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b0) && (C === 1'b1)) |-> (X === 1'b0)
    );

// 110 must drive X low.
    check_x_low_for_110: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1) && (C === 1'b0)) |-> (X === 1'b0)
    );

// 111 must drive X high.
    check_x_high_for_111: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1) && (C === 1'b1)) |-> (X === 1'b1)
    );

// GPIOe write enable is never asserted by this RTL.
    check_gpioe_always_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        GPIOe0000000_we == 1'b0
    );

// RAM write enable can only occur on the RAM decode with mem_w asserted.
    check_data_ram_we_qualification: assert property (
        @(posedge clk) disable iff (1'b0)
        data_ram_we |-> ((addr_bus[31:28] == 4'h0) && mem_w)
    );

// Counter write enable can only occur on 0xF with addr_bus[2]=1 and mem_w asserted.
    check_counter_we_qualification: assert property (
        @(posedge clk) disable iff (1'b0)
        counter_we |-> ((addr_bus[31:28] == 4'hf) && addr_bus[2] && mem_w)
    );

// GPIOf write enable can only occur on 0xE or 0xF with addr_bus[2]=0 and mem_w asserted.
    check_gpiof_we_qualification: assert property (
        @(posedge clk) disable iff (1'b0)
        GPIOf0000000_we |-> (((addr_bus[31:28] == 4'he) || ((addr_bus[31:28] == 4'hf) && !addr_bus[2])) && mem_w)
    );

// The write enables are mutually exclusive.
    check_write_enable_mutex: assert property (
        @(posedge clk) disable iff (1'b0)
        !((data_ram_we && counter_we) ||
          (data_ram_we && GPIOf0000000_we) ||
          (data_ram_we && GPIOe0000000_we) ||
          (counter_we && GPIOf0000000_we) ||
          (counter_we && GPIOe0000000_we) ||
          (GPIOf0000000_we && GPIOe0000000_we))
    );

// Output matches the implemented two-stage registered prefix-XOR transform of B.
    check_output_vector_transform: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G == {($past(B[3],2) ^ $past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)),
               ($past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)),
               ($past(B[1],2) ^ $past(B[0],2)),
               $past(B[0],2)})
    );

// G[0] is B[0] delayed through the registered pipeline.
    check_g0_pipeline_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[0] == $past(B[0],2))
    );

// G[1] is the prefix XOR of sampled B[1:0].
    check_g1_prefix_xor_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[1] == ($past(B[1],2) ^ $past(B[0],2)))
    );

// G[2] is the prefix XOR of sampled B[2:0].
    check_g2_prefix_xor_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[2] == ($past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)))
    );

// G[3] is the prefix XOR of sampled B[3:0].
    check_g3_prefix_xor_mapping: assert property (
        @(posedge clk)
        1'b1 |-> ##2
        (G[3] == ($past(B[3],2) ^ $past(B[2],2) ^ $past(B[1],2) ^ $past(B[0],2)))
    );

// Reset drives q to 0.
    check_reset_clears_q: assert property (
        @(posedge clk) !post_cb.areset |-> (post_cb.q == 4'b0000)
    );

// Load captures data on the clock edge.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && load |-> (post_cb.q == data)
    );

// Load has priority over enable.
    check_load_priority_over_enable: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && load && ena |-> (post_cb.q == data)
    );

// Enable rotates q as {q[2:0], q[3]} when not loading.
    check_enable_rotates_q: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && !load && ena |-> (post_cb.q == {q[2:0], q[3]})
    );

// With neither load nor enable, q holds its value.
    check_idle_holds_q: assert property (
        @(posedge clk) disable iff (!post_cb.areset)
        areset && !load && !ena |-> (post_cb.q == q)
    );

// in_ready directly mirrors out_ready.
    check_in_ready_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (in_ready == out_ready)
    );

// out_data directly mirrors in_data.
    check_out_data_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (out_data == in_data)
    );

// out_startofpacket directly mirrors in_startofpacket.
    check_out_startofpacket_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (out_startofpacket == in_startofpacket)
    );

// out_endofpacket directly mirrors in_endofpacket.
    check_out_endofpacket_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (out_endofpacket == in_endofpacket)
    );

// Channel 0 passes in_valid through to out_valid.
    check_out_valid_passthrough_channel_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (in_channel == 8'h00) |-> (out_valid == in_valid)
    );

// Nonzero channels force out_valid low.
    check_out_valid_blocked_nonzero_channel: assert property (
        @(posedge clk) disable iff (!reset_n)
        (in_channel > 8'h00) |-> (out_valid == 1'b0)
    );

// Combined outputs equal the computed 5-bit sum.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == sum
    );

// S reflects the low 4 bits of the computed sum.
    check_sum_bits: assert property (
        @(posedge clk) S == sum[3:0]
    );

// Cout reflects the high bit of the computed sum.
    check_carry_bit: assert property (
        @(posedge clk) Cout == sum[4]
    );

// Zero B and zero carry-in return A.
    check_identity_with_a: assert property (
        @(posedge clk) (B == 4'd0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, A})
    );

// Zero A and zero carry-in return B.
    check_identity_with_b: assert property (
        @(posedge clk) (A == 4'd0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, B})
    );

// Maximum inputs produce the maximum 5-bit result.
    check_maximum_input_case: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> ({Cout, S} == 5'h1F)
    );

// Combinational DUT with no reset; assertions are sampled on an external clock.

    // match must equal the AND of all per-bit equality results.
    check_match_bitwise_implementation: assert property (
        @(posedge clk)
        match == (
            (in1[0] == in2[0]) &
            (in1[1] == in2[1]) &
            (in1[2] == in2[2]) &
            (in1[3] == in2[3]) &
            (in1[4] == in2[4]) &
            (in1[5] == in2[5]) &
            (in1[6] == in2[6]) &
            (in1[7] == in2[7])
        )
    );

// Equal input vectors must produce a match.
    check_equal_inputs_set_match: assert property (
        @(posedge clk)
        (in1 == in2) |-> (match == 1'b1)
    );

// Unequal input vectors must clear match.
    check_unequal_inputs_clear_match: assert property (
        @(posedge clk)
        (in1 != in2) |-> (match == 1'b0)
    );

// A high match output means the two inputs are equal.
    check_match_high_means_equal: assert property (
        @(posedge clk)
        (match == 1'b1) |-> (in1 == in2)
    );

// A low match output means the two inputs are not equal.
    check_match_low_means_unequal: assert property (
        @(posedge clk)
        (match == 1'b0) |-> (in1 != in2)
    );

// When sel is 00, out must match in0.
    check_select_in0: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b00) |-> (out == in0)
    );

// When sel is 01, out must match in1.
    check_select_in1: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b01) |-> (out == in1)
    );

// When sel is 10, out must match in2.
    check_select_in2: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b10) |-> (out == in2)
    );

// When sel is 11, out must match in3.
    check_select_in3: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b11) |-> (out == in3)
    );

// During reset, the output register stays cleared.
    check_reset_clears_out: assert property (
        @(posedge clk) !reset |-> (out == 8'h00)
    );

// ENCLK goes high one cycle after EN&TE is exactly true.
    check_enclk_sets_when_en_and_te_high: assert property (
        @(posedge CLK) ((EN & TE) === 1'b1) |=> (ENCLK === 1'b1)
    );

// ENCLK goes low one cycle after EN&TE is anything other than true.
    check_enclk_clears_when_en_and_te_not_high: assert property (
        @(posedge CLK) ((EN & TE) !== 1'b1) |=> (ENCLK === 1'b0)
    );

// A low or unknown EN forces ENCLK low on the next cycle.
    check_enclk_low_when_en_not_one: assert property (
        @(posedge CLK) (EN !== 1'b1) |=> (ENCLK === 1'b0)
    );

// A low or unknown TE forces ENCLK low on the next cycle.
    check_enclk_low_when_te_not_one: assert property (
        @(posedge CLK) (TE !== 1'b1) |=> (ENCLK === 1'b0)
    );

// Output must always match the RTL mux expression.
    check_out_matches_rtl_function: assert property (
        @(posedge clk) out == (sel[7] ? in[sel[6:0]] : 1'b0)
    );

// When the select MSB is low, the output is forced low.
    check_out_zero_when_sel_msb_low: assert property (
        @(posedge clk) !sel[7] |-> (out == 1'b0)
    );

// When the select MSB is high, the output matches the indexed input bit.
    check_out_matches_selected_input_when_enabled: assert property (
        @(posedge clk) sel[7] |-> (out == in[sel[6:0]])
    );

// Combinational DUT sampled on an external clock; RTL has no reset.

    // Y matches the implemented NAND-with-inverted-A function.
    check_nand3b_boolean_function: assert property (
        @(posedge clk) Y == ~(B & ~A_N & C)
    );

// Y can be LOW only for the single active minterm.
    check_output_low_only_on_active_minterm: assert property (
        @(posedge clk) !Y |-> (!A_N && B && C)
    );

// The active minterm drives Y LOW.
    check_active_minterm_drives_low: assert property (
        @(posedge clk) (!A_N && B && C) |-> !Y
    );

// A_N HIGH forces Y HIGH through the inverted A input.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B LOW forces Y HIGH.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) !B |-> Y
    );

// C LOW forces Y HIGH.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> Y
    );

// A sampled reset must leave count at 000 on the next clock.
    check_reset_clears_count_next_cycle: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

// At the sampled clock where reset deasserts, count is still 000.
    check_release_cycle_count_zero: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> (count == 3'b000)
    );

// One clock after reset deassertion, count remains 000.
    check_release_plus1_count_zero: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> (count == 3'b000)
    );

// Two clocks after reset deassertion, count is still 000.
    check_release_plus2_count_zero: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> ##1 (count == 3'b000)
    );

// Three clocks after reset deassertion, count becomes 111.
    check_release_plus3_count_ones: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> ##2 (count == 3'b111)
    );

// Four clocks after reset deassertion, count remains 111.
    check_release_plus4_count_ones: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> ##3 (count == 3'b111)
    );

// Five clocks after reset deassertion, count returns to 000.
    check_release_plus5_count_zero: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> ##4 (count == 3'b000)
    );

// Six clocks after reset deassertion, count remains 000.
    check_release_plus6_count_zero: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> ##5 (count == 3'b000)
    );

// Seven clocks after reset deassertion, count becomes 111 again.
    check_release_plus7_count_ones: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> ##6 (count == 3'b111)
    );

// Eight clocks after reset deassertion, count remains 111.
    check_release_plus8_count_ones: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |=> ##7 (count == 3'b111)
    );

// An input LSB of 1 must drive output 01.
    check_lsb_one_maps_to_01: assert property (
        @(posedge clk) (input_bits[0] === 1'b1) |-> (output_bits == 2'b01)
    );

// Any non-1 LSB value must drive output 10.
    check_lsb_not_one_maps_to_10: assert property (
        @(posedge clk) (input_bits[0] !== 1'b1) |-> (output_bits == 2'b10)
    );

// output_bits[0] reflects whether the LSB is exactly 1.
    check_output_bit0_matches_true_branch: assert property (
        @(posedge clk) output_bits[0] == (input_bits[0] === 1'b1)
    );

// output_bits[1] reflects the else branch selection.
    check_output_bit1_matches_else_branch: assert property (
        @(posedge clk) output_bits[1] == (input_bits[0] !== 1'b1)
    );

// The output must always be one of the two assigned encodings.
    check_output_encoding_is_valid: assert property (
        @(posedge clk) ((output_bits == 2'b01) || (output_bits == 2'b10))
    );

// A valid GR write captures data and destination.
    check_gr_capture_on_valid: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_GR_VALID) |=> (
            (oFDR_GR_VALID == 1'b1) &&
            (oFDR_GR_DATA == $past(iWB_GR_DATA)) &&
            (oFDR_GR_DEST == $past(iWB_GR_DEST)) &&
            (oFDR_GR_DEST_SYSREG == $past(iWB_GR_DEST_SYSREG))
        )
    );

// Without a valid GR write, the GR forwarding state holds.
    check_gr_hold_without_write: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_GR_VALID) |=> (
            $stable(oFDR_GR_VALID) &&
            $stable(oFDR_GR_DATA) &&
            $stable(oFDR_GR_DEST) &&
            $stable(oFDR_GR_DEST_SYSREG)
        )
    );

// WB SPR write has priority and sets SPR valid.
    check_spr_capture_from_wb: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b1) &&
            (oFDR_SPR_DATA == $past(iWB_SPR_DATA))
        )
    );

// Auto SPR write forwards auto data and leaves valid low.
    check_spr_capture_from_auto: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_SPR_VALID && iWB_AUTO_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b0) &&
            (oFDR_SPR_DATA == $past(iWB_AUTO_SPR_DATA))
        )
    );

// Without SPR writes, current SPR data is forwarded with valid high.
    check_spr_forward_current_data: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_SPR_VALID && !iWB_AUTO_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b1) &&
            (oFDR_SPR_DATA == $past(iCUUR_SPR_DATA))
        )
    );

// A valid FRCR write captures FRCR data.
    check_frcr_capture_from_wb: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_FRCR_VALID) |=> (
            (oFDR_FRCR_VALID == 1'b1) &&
            (oFDR_FRCR_DATA == $past(iWB_FRCR_DATA))
        )
    );

// Without an FRCR write, current FRCR data is forwarded with valid high.
    check_frcr_forward_current_data: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_FRCR_VALID) |=> (
            (oFDR_FRCR_VALID == 1'b1) &&
            (oFDR_FRCR_DATA == $past(iCUUR_FRCR_DATA))
        )
    );

// In add mode, SUM matches A + B.
    check_add_mode_result: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (SUM == (A + B))
    );

// In subtract mode, SUM matches A - B.
    check_sub_mode_result: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (SUM == (A - B))
    );

// With B equal to zero, SUM must equal A in either mode.
    check_zero_b_identity: assert property (
        @(posedge clk) (B == 4'b0000) |-> (SUM == A)
    );

// In subtract mode, equal operands must produce zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (SUB == 1'b1 && A == B) |-> (SUM == 4'b0000)
    );

// No RTL clock/reset; sample this combinational logic on an external clock.

    // When disabled, the result is forced to zero.
    check_disable_forces_zero: assert property (
        @(posedge clk) !en |-> (R == 8'h00)
    );

// Opcode 00 performs 8-bit addition when enabled.
    check_addition_result: assert property (
        @(posedge clk) en && (opcode == 2'b00) |-> (R == ((A + B) & 8'hFF))
    );

// Opcode 01 performs 8-bit subtraction when enabled.
    check_subtraction_result: assert property (
        @(posedge clk) en && (opcode == 2'b01) |-> (R == ((A - B) & 8'hFF))
    );

// X equals A gated by the inverse of SLEEP.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((~SLEEP) & A)
    );

// SLEEP high forces X low.
    check_sleep_forces_low: assert property (
        @(posedge clk) (SLEEP == 1'b1) |-> (X == 1'b0)
    );

// When not sleeping, X matches A.
    check_awake_passes_a: assert property (
        @(posedge clk) (SLEEP == 1'b0) |-> (X == A)
    );

// A low forces X low.
    check_a_low_forces_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

// X high requires SLEEP low and A high.
    check_x_high_requires_inputs: assert property (
        @(posedge clk) (X == 1'b1) |-> ((SLEEP == 1'b0) && (A == 1'b1))
    );

// z matches the RTL boolean expression.
    check_output_equation: assert property (
        @(posedge clk) z == ((a & b) ^ (c | ~b))
    );

// When b is low, z is always high.
    check_b_low_forces_z_high: assert property (
        @(posedge clk) !b |-> (z == 1'b1)
    );

// When b is high, z reduces to a XOR c.
    check_b_high_reduces_to_xor: assert property (
        @(posedge clk) b |-> (z == (a ^ c))
    );

// With b high and equal inputs, z is low.
    check_b_high_equal_inputs_drive_low: assert property (
        @(posedge clk) (b && (a == c)) |-> (z == 1'b0)
    );

// With b high and different inputs, z is high.
    check_b_high_different_inputs_drive_high: assert property (
        @(posedge clk) (b && (a != c)) |-> (z == 1'b1)
    );

// z can be low only when b is high and a equals c.
    check_low_output_condition: assert property (
        @(posedge clk) !z |-> (b && (a == c))
    );

// Output matches the RTL assign expression.
    check_out_definition: assert property (
        @(posedge clk) out === ((en == 1'b1) ? (in1 & in2) : 1'b0)
    );

// When disabled, the output is forced low.
    check_disable_forces_zero: assert property (
        @(posedge clk) (en === 1'b0) |-> (out === 1'b0)
    );

// When enabled, the output equals the AND of the inputs.
    check_enabled_matches_and: assert property (
        @(posedge clk) (en === 1'b1) |-> (out === (in1 & in2))
    );

// A high output requires enable and both inputs high.
    check_out_high_requires_all_high: assert property (
        @(posedge clk) (out === 1'b1) |-> ((en === 1'b1) && (in1 === 1'b1) && (in2 === 1'b1))
    );

// Enable high with both inputs high drives the output high.
    check_all_high_drives_high: assert property (
        @(posedge clk) ((en === 1'b1) && (in1 === 1'b1) && (in2 === 1'b1)) |-> (out === 1'b1)
    );

// Enable high with in1 low drives the output low.
    check_in1_low_blocks_output: assert property (
        @(posedge clk) ((en === 1'b1) && (in1 === 1'b0)) |-> (out === 1'b0)
    );

// Enable high with in2 low drives the output low.
    check_in2_low_blocks_output: assert property (
        @(posedge clk) ((en === 1'b1) && (in2 === 1'b0)) |-> (out === 1'b0)
    );

// Output must equal the input with only the MSB inverted.
    check_invert_msb_function: assert property (
        @(posedge clk) o_inverted === {~i_binary[3], i_binary[2:0]}
    );

// Output MSB must be the inverse of the input MSB.
    check_output_msb_inverted: assert property (
        @(posedge clk) o_inverted[3] === ~i_binary[3]
    );

// Output lower three bits must pass through unchanged.
    check_output_lower_bits_passthrough: assert property (
        @(posedge clk) o_inverted[2:0] === i_binary[2:0]
    );

// No RTL clock/reset; clk is only a sampling clock for these checks.
    // Observable behavior is purely combinational on in, out_hi, out_lo, and final_out.

    // out_hi must always equal the upper byte of in.
    check_out_hi_slice: assert property (
        @(posedge clk) out_hi == in[15:8]
    );

// out_lo must always equal the lower byte of in.
    check_out_lo_slice: assert property (
        @(posedge clk) out_lo == in[7:0]
    );

// The two byte outputs must reconstruct the input word.
    check_output_bytes_reconstruct_input: assert property (
        @(posedge clk) {out_hi, out_lo} == in
    );

// final_out lower byte must equal the sum of out_hi and out_lo.
    check_final_out_lower_byte_sum: assert property (
        @(posedge clk) final_out[7:0] == (out_hi + out_lo)
    );

// A reset cycle leaves the counter at zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// The first sampled cycle after reset deassertion still sees zero.
    check_reset_release_starts_at_zero: assert property (
        @(posedge clk) (rst ##1 !rst) |-> (count == 4'b0000)
    );

// After reset deasserts and one running cycle passes, count becomes one.
    check_reset_release_then_increment: assert property (
        @(posedge clk) (rst ##1 !rst ##1 !rst) |-> (count == 4'b0001)
    );

// When not in reset, the counter increments by one each clock.
    check_count_increments_by_one: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'b0001))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps_from_f_to_0: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// The output always matches the mux function.
    check_output_matches_mux_function: assert property (
        @(posedge clk)
        out == ((sel == 2'b00) ? (en ? in0 : 8'h00) :
                (sel == 2'b01) ? (en ? in1 : 8'h00) :
                (sel == 2'b10) ? (en ? in2 : 8'h00) :
                                 (en ? in3 : 8'h00))
    );

// When disabled, the output is zero.
    check_disabled_drives_zero: assert property (
        @(posedge clk) !en |-> (out == 8'h00)
    );

// Select 0 routes in0 when enabled.
    check_sel0_routes_in0: assert property (
        @(posedge clk) (en && (sel == 2'b00)) |-> (out == in0)
    );

// Select 1 routes in1 when enabled.
    check_sel1_routes_in1: assert property (
        @(posedge clk) (en && (sel == 2'b01)) |-> (out == in1)
    );

// Select 2 routes in2 when enabled.
    check_sel2_routes_in2: assert property (
        @(posedge clk) (en && (sel == 2'b10)) |-> (out == in2)
    );

// Select 3 routes in3 when enabled.
    check_sel3_routes_in3: assert property (
        @(posedge clk) (en && (sel == 2'b11)) |-> (out == in3)
    );

// ENCLK is a direct copy of the internal latch output on CLK samples.
    check_enclk_matches_eck_on_clk: assert property (
        @(posedge CLK) ENCLK == ECK
    );

// ENCLK is a direct copy of the internal latch output on TE samples.
    check_enclk_matches_eck_on_te: assert property (
        @(posedge TE) ENCLK == ECK
    );

// TE high at a CLK edge forces the stored enable high by the next CLK sample.
    check_te_high_on_clk_sets_high: assert property (
        @(posedge CLK) TE |=> (ECK && ENCLK)
    );

// EN high with TE low at a CLK edge loads a high value by the next CLK sample.
    check_en_high_without_te_sets_high: assert property (
        @(posedge CLK) (!TE && EN) |=> (ECK && ENCLK)
    );

// A TE rising edge asynchronously sets the stored enable high by the next CLK sample.
    check_te_rise_sets_high_by_next_clk: assert property (
        @(posedge TE) 1'b1 |=> @(posedge CLK) (ECK && ENCLK)
    );

// select 0 routes data_i00 to data_o.
    check_select_00_routes_data_i00: assert property (
        @(posedge clk) (select == 5'd0) |-> (data_o == data_i00)
    );

// select 1 routes data_i01 to data_o.
    check_select_01_routes_data_i01: assert property (
        @(posedge clk) (select == 5'd1) |-> (data_o == data_i01)
    );

// select 2 routes data_i02 to data_o.
    check_select_02_routes_data_i02: assert property (
        @(posedge clk) (select == 5'd2) |-> (data_o == data_i02)
    );

// select 3 routes data_i03 to data_o.
    check_select_03_routes_data_i03: assert property (
        @(posedge clk) (select == 5'd3) |-> (data_o == data_i03)
    );

// select 4 routes data_i04 to data_o.
    check_select_04_routes_data_i04: assert property (
        @(posedge clk) (select == 5'd4) |-> (data_o == data_i04)
    );

// select 5 routes data_i05 to data_o.
    check_select_05_routes_data_i05: assert property (
        @(posedge clk) (select == 5'd5) |-> (data_o == data_i05)
    );

// select 6 routes data_i06 to data_o.
    check_select_06_routes_data_i06: assert property (
        @(posedge clk) (select == 5'd6) |-> (data_o == data_i06)
    );

// select 7 routes data_i07 to data_o.
    check_select_07_routes_data_i07: assert property (
        @(posedge clk) (select == 5'd7) |-> (data_o == data_i07)
    );

// select 8 routes data_i08 to data_o.
    check_select_08_routes_data_i08: assert property (
        @(posedge clk) (select == 5'd8) |-> (data_o == data_i08)
    );

// select 9 routes data_i09 to data_o.
    check_select_09_routes_data_i09: assert property (
        @(posedge clk) (select == 5'd9) |-> (data_o == data_i09)
    );

// select 10 routes data_i10 to data_o.
    check_select_10_routes_data_i10: assert property (
        @(posedge clk) (select == 5'd10) |-> (data_o == data_i10)
    );

// select 11 routes data_i11 to data_o.
    check_select_11_routes_data_i11: assert property (
        @(posedge clk) (select == 5'd11) |-> (data_o == data_i11)
    );

// select 12 routes data_i12 to data_o.
    check_select_12_routes_data_i12: assert property (
        @(posedge clk) (select == 5'd12) |-> (data_o == data_i12)
    );

// select 13 routes data_i13 to data_o.
    check_select_13_routes_data_i13: assert property (
        @(posedge clk) (select == 5'd13) |-> (data_o == data_i13)
    );

// select 14 routes data_i14 to data_o.
    check_select_14_routes_data_i14: assert property (
        @(posedge clk) (select == 5'd14) |-> (data_o == data_i14)
    );

// select 15 routes data_i15 to data_o.
    check_select_15_routes_data_i15: assert property (
        @(posedge clk) (select == 5'd15) |-> (data_o == data_i15)
    );

// select 16 routes data_i16 to data_o.
    check_select_16_routes_data_i16: assert property (
        @(posedge clk) (select == 5'd16) |-> (data_o == data_i16)
    );

// select 17 routes data_i17 to data_o.
    check_select_17_routes_data_i17: assert property (
        @(posedge clk) (select == 5'd17) |-> (data_o == data_i17)
    );

// select 18 routes data_i18 to data_o.
    check_select_18_routes_data_i18: assert property (
        @(posedge clk) (select == 5'd18) |-> (data_o == data_i18)
    );

// select 19 routes data_i19 to data_o.
    check_select_19_routes_data_i19: assert property (
        @(posedge clk) (select == 5'd19) |-> (data_o == data_i19)
    );

// select 20 routes data_i20 to data_o.
    check_select_20_routes_data_i20: assert property (
        @(posedge clk) (select == 5'd20) |-> (data_o == data_i20)
    );

// select 21 routes data_i21 to data_o.
    check_select_21_routes_data_i21: assert property (
        @(posedge clk) (select == 5'd21) |-> (data_o == data_i21)
    );

// select 22 routes data_i22 to data_o.
    check_select_22_routes_data_i22: assert property (
        @(posedge clk) (select == 5'd22) |-> (data_o == data_i22)
    );

// select 23 routes data_i23 to data_o.
    check_select_23_routes_data_i23: assert property (
        @(posedge clk) (select == 5'd23) |-> (data_o == data_i23)
    );

// select 24 routes data_i24 to data_o.
    check_select_24_routes_data_i24: assert property (
        @(posedge clk) (select == 5'd24) |-> (data_o == data_i24)
    );

// select 25 routes data_i25 to data_o.
    check_select_25_routes_data_i25: assert property (
        @(posedge clk) (select == 5'd25) |-> (data_o == data_i25)
    );

// select 26 routes data_i26 to data_o.
    check_select_26_routes_data_i26: assert property (
        @(posedge clk) (select == 5'd26) |-> (data_o == data_i26)
    );

// select 27 routes data_i27 to data_o.
    check_select_27_routes_data_i27: assert property (
        @(posedge clk) (select == 5'd27) |-> (data_o == data_i27)
    );

// select 28 routes data_i28 to data_o.
    check_select_28_routes_data_i28: assert property (
        @(posedge clk) (select == 5'd28) |-> (data_o == data_i28)
    );

// select 29 routes data_i29 to data_o.
    check_select_29_routes_data_i29: assert property (
        @(posedge clk) (select == 5'd29) |-> (data_o == data_i29)
    );

// select 30 routes data_i30 to data_o.
    check_select_30_routes_data_i30: assert property (
        @(posedge clk) (select == 5'd30) |-> (data_o == data_i30)
    );

// select 31 routes data_i31 to data_o.
    check_select_31_routes_data_i31: assert property (
        @(posedge clk) (select == 5'd31) |-> (data_o == data_i31)
    );

// A known prior binary input produces a known gray output.
    check_known_input_known_output: assert property (
        @(posedge clk) !$isunknown($past(binary)) |-> !$isunknown(gray)
    );

// Y matches the implemented NOR-of-AND function.
    check_y_function: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// A high B1 forces the NOR output low.
    check_b1_high_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A high A1/A2 product term forces the NOR output low.
    check_and_term_high_forces_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// Y is high when both inputs to the NOR are low.
    check_both_nor_inputs_low_gives_y_high: assert property (
        @(posedge clk) (!B1 && !(A1 && A2)) |-> Y
    );

// A high Y implies B1 is low.
    check_y_high_implies_b1_low: assert property (
        @(posedge clk) Y |-> !B1
    );

// With B1 low, a low Y implies the AND term is high.
    check_b1_low_and_y_low_implies_and_term_high: assert property (
        @(posedge clk) (!B1 && !Y) |-> (A1 && A2)
    );

// eq matches the equality comparison.
    check_eq_matches_inputs: assert property (
        @(posedge clk) (eq === (in1 == in2))
    );

// gt matches the greater-than comparison.
    check_gt_matches_inputs: assert property (
        @(posedge clk) (gt === (in1 > in2))
    );

// lt matches the less-than comparison.
    check_lt_matches_inputs: assert property (
        @(posedge clk) (lt === (in1 < in2))
    );

// Comparison outputs never assert together.
    check_outputs_mutually_exclusive: assert property (
        @(posedge clk) (!(eq && gt) && !(eq && lt) && !(gt && lt))
    );

// One comparison result is always indicated.
    check_outputs_complete: assert property (
        @(posedge clk) (eq || gt || lt)
    );

// Equal inputs drive only eq high.
    check_equal_case_result: assert property (
        @(posedge clk) ((in1 == in2) |-> (eq && !gt && !lt))
    );

// Larger in1 drives only gt high.
    check_greater_case_result: assert property (
        @(posedge clk) ((in1 > in2) |-> (!eq && gt && !lt))
    );

// Smaller in1 drives only lt high.
    check_less_case_result: assert property (
        @(posedge clk) ((in1 < in2) |-> (!eq && !gt && lt))
    );

// When reset is active low, count must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset_n |-> (count == 4'h0)
    );

// A non-maximum count increments by one on the next clock.
    check_count_increments_nonmax: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

// The counter wraps from 15 back to 0 on the next clock.
    check_count_wraps_at_max: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count == 4'hF) |=> (count == 4'h0)
    );

// After reset is released, the first counted value is 1.
    check_first_count_after_reset_release: assert property (
        @(posedge clk) disable iff (!reset_n)
        $rose(reset_n) |=> (count == 4'h1)
    );

// When sel is 00, data_out must equal data_in0.
    check_sel_00_routes_input0: assert property (
        @(posedge clk) ({sel1, sel0} == 2'b00) |-> (data_out == data_in0)
    );

// When sel is 01, data_out must equal data_in1.
    check_sel_01_routes_input1: assert property (
        @(posedge clk) ({sel1, sel0} == 2'b01) |-> (data_out == data_in1)
    );

// When sel is 10, data_out must equal data_in2.
    check_sel_10_routes_input2: assert property (
        @(posedge clk) ({sel1, sel0} == 2'b10) |-> (data_out == data_in2)
    );

// When sel is 11, data_out must equal data_in3.
    check_sel_11_routes_input3: assert property (
        @(posedge clk) ({sel1, sel0} == 2'b11) |-> (data_out == data_in3)
    );

// clk_gated reflects the previous cycle's enable value.
    check_clk_gated_tracks_previous_enable: assert property (
        @(posedge clk) 1'b1 |=> (clk_gated == $past(enable))
    );

// A high enable drives clk_gated high on the next sampled cycle.
    check_enable_high_sets_clk_gated: assert property (
        @(posedge clk) enable |=> (clk_gated == 1'b1)
    );

// A low enable drives clk_gated low on the next sampled cycle.
    check_enable_low_clears_clk_gated: assert property (
        @(posedge clk) !enable |=> (clk_gated == 1'b0)
    );

// When sleep is asserted low, the output is forced low.
    check_sleep_forces_zero: assert property (
        @(posedge clk) (SLEEP_B == 1'b0) |-> (X == 1'b0)
    );

// When sleep is deasserted high, the output passes input A.
    check_awake_passes_input: assert property (
        @(posedge clk) (SLEEP_B == 1'b1) |-> (X == A)
    );

// A high output requires both A and SLEEP_B to be high.
    check_high_output_requires_both_high: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A == 1'b1) && (SLEEP_B == 1'b1))
    );

// The output implements the AND of A and SLEEP_B.
    check_and_function: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// X must match the full mux sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        X == ((A0 & ~S0 & ~S1) |
              (A1 &  S0 & ~S1) |
              (A2 & ~S0 &  S1) |
              (A3 &  S0 &  S1))
    );

// When select is 00, X must follow A0.
    check_select_00: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b0)) |-> (X == A0)
    );

// When select is 01, X must follow A1.
    check_select_01: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b1)) |-> (X == A1)
    );

// When select is 10, X must follow A2.
    check_select_10: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b0)) |-> (X == A2)
    );

// When select is 11, X must follow A3.
    check_select_11: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b1)) |-> (X == A3)
    );

// With S1 low, X must select between A0 and A1 using S0.
    check_s1_low_lower_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b0) |-> (X == ((A0 & ~S0) | (A1 & S0)))
    );

// With S1 high, X must select between A2 and A3 using S0.
    check_s1_high_upper_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b1) |-> (X == ((A2 & ~S0) | (A3 & S0)))
    );

// With S0 low, X must select between A0 and A2 using S1.
    check_s0_low_even_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b0) |-> (X == ((A0 & ~S1) | (A2 & S1)))
    );

// With S0 high, X must select between A1 and A3 using S1.
    check_s0_high_odd_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b1) |-> (X == ((A1 & ~S1) | (A3 & S1)))
    );

// data_out captures the previous cycle's data_in value.
    check_data_capture: assert property (
        @(posedge clk) 1'b1 |=> (data_out == $past(data_in))
    );

// When enabled in up mode, Q increments on the next clock.
    check_increment_when_enabled_up: assert property (
        @(posedge clk)
        (CE && UD) |=> (Q == ($past(Q) + 4'd1))
    );

// When enabled in down mode, Q decrements on the next clock.
    check_decrement_when_enabled_down: assert property (
        @(posedge clk)
        (CE && !UD) |=> (Q == ($past(Q) - 4'd1))
    );

// When not enabled, Q loads D on the next clock.
    check_load_d_when_disabled: assert property (
        @(posedge clk)
        (!CE) |=> (Q == $past(D))
    );

// Counting up from 4'hF wraps Q to 4'h0.
    check_up_wraparound: assert property (
        @(posedge clk)
        (CE && UD && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Counting down from 4'h0 wraps Q to 4'hF.
    check_down_wraparound: assert property (
        @(posedge clk)
        (CE && !UD && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Q always follows the RTL next-state function.
    check_complete_next_state: assert property (
        @(posedge clk)
        1'b1 |=> (Q == ($past(CE) ? ($past(UD) ? ($past(Q) + 4'd1) : ($past(Q) - 4'd1)) : $past(D)))
    );

// RTL is combinational with no reset; clk is only used to sample assertions.

    // tri_o_out selects tri_o_in when gpio_sel is low.
    check_tri_o_gpio_path: assert property (
        @(posedge clk) (gpio_sel === 1'b0) |-> (tri_o_out === tri_o_in)
    );

// tri_o_out selects tx_o_in when gpio_sel is high.
    check_tri_o_uart_path: assert property (
        @(posedge clk) (gpio_sel === 1'b1) |-> (tri_o_out === tx_o_in)
    );

// tri_t_out selects tri_t_in when gpio_sel is low.
    check_tri_t_gpio_path: assert property (
        @(posedge clk) (gpio_sel === 1'b0) |-> (tri_t_out === tri_t_in)
    );

// tri_t_out selects tx_t_in when gpio_sel is high.
    check_tri_t_uart_path: assert property (
        @(posedge clk) (gpio_sel === 1'b1) |-> (tri_t_out === tx_t_in)
    );

// GPIO mode routes tri_i_out to tri_i_in and clears rx_i_in.
    check_input_demux_gpio_mode: assert property (
        @(posedge clk) (gpio_sel === 1'b0) |-> ((tri_i_in === tri_i_out) && (rx_i_in === 1'b0))
    );

// UART mode routes tri_i_out to rx_i_in and clears tri_i_in.
    check_input_demux_uart_mode: assert property (
        @(posedge clk) (gpio_sel === 1'b1) |-> ((tri_i_in === 1'b0) && (rx_i_in === tri_i_out))
    );

// Output matches the RTL mux expression on every sampled cycle.
    check_mux_function: assert property (
        @(posedge clk) Y === ((SEL == 1'b1) ? A : B)
    );

// When select is HIGH, output follows A.
    check_select_high_routes_a: assert property (
        @(posedge clk) (SEL === 1'b1) |-> (Y === A)
    );

// When select is LOW, output follows B.
    check_select_low_routes_b: assert property (
        @(posedge clk) (SEL === 1'b0) |-> (Y === B)
    );

// Equal inputs produce the same output regardless of select.
    check_equal_inputs_same_output: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

// Reset drives the counter to zero by the next sampled clock edge.
    check_reset_clears_count: assert property (
        @(posedge iCLK) iRST |=> (oCNT == 4'h0)
    );

// When active and below 15, the counter increments by one each cycle.
    check_counter_increments: assert property (
        @(posedge iCLK) disable iff (iRST)
        (oCNT != 4'hF) |=> (oCNT == ($past(oCNT) + 4'h1))
    );

// When active at 15, the 4-bit counter wraps back to zero.
    check_counter_wraps_to_zero: assert property (
        @(posedge iCLK) disable iff (iRST)
        (oCNT == 4'hF) |=> (oCNT == 4'h0)
    );

// Reset forces count to zero by the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Without reset, count increments by one every cycle.
    check_count_increments_without_reset: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// A maximum count value rolls over to zero.
    check_count_rolls_over_from_max: assert property (
        @(posedge clk) disable iff (reset) (count == 4'hF) |=> (count == 4'h0)
    );

// X matches the inverted four-input AND function.
    check_x_function: assert property (
        @(posedge clk) (X == ~(A_N & B & C & D))
    );

// When all inputs are high, X must be low.
    check_all_high_drives_x_low: assert property (
        @(posedge clk) (A_N & B & C & D) |-> (X == 1'b0)
    );

// If X is low, all four inputs must be high.
    check_x_low_requires_all_high: assert property (
        @(posedge clk) (X == 1'b0) |-> (A_N & B & C & D)
    );

// A low A_N forces X high.
    check_a_n_low_drives_x_high: assert property (
        @(posedge clk) (!A_N) |-> (X == 1'b1)
    );

// A low B forces X high.
    check_b_low_drives_x_high: assert property (
        @(posedge clk) (!B) |-> (X == 1'b1)
    );

// A low C forces X high.
    check_c_low_drives_x_high: assert property (
        @(posedge clk) (!C) |-> (X == 1'b1)
    );

// A low D forces X high.
    check_d_low_drives_x_high: assert property (
        @(posedge clk) (!D) |-> (X == 1'b1)
    );

// X matches the AND of all four functional inputs.
    check_output_matches_and4: assert property (
        @(posedge clk) (X === (A & B & C & D))
    );

// All four inputs high drive X high.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1)) |-> (X === 1'b1)
    );

// X can be high only when all four inputs are high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) (X === 1'b1) |-> ((A === 1'b1) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1))
    );

// A low forces X low.
    check_a_low_forces_output_low: assert property (
        @(posedge clk) (A === 1'b0) |-> (X === 1'b0)
    );

// B low forces X low.
    check_b_low_forces_output_low: assert property (
        @(posedge clk) (B === 1'b0) |-> (X === 1'b0)
    );

// C low forces X low.
    check_c_low_forces_output_low: assert property (
        @(posedge clk) (C === 1'b0) |-> (X === 1'b0)
    );

// D low forces X low.
    check_d_low_forces_output_low: assert property (
        @(posedge clk) (D === 1'b0) |-> (X === 1'b0)
    );

// An enabled rising edge loads D into Q.
    check_load_on_enable: assert property (
        @(posedge C) E |=> (Q == $past(D))
    );

// A disabled rising edge leaves Q unchanged.
    check_hold_on_disable: assert property (
        @(posedge C) !E |=> (Q == $past(Q))
    );

// Enabled new data must change Q on the next sampled cycle.
    check_change_on_new_enabled_data: assert property (
        @(posedge C) (E && (D != Q)) |=> (Q != $past(Q))
    );

// Enabled same data must leave Q unchanged.
    check_no_change_on_same_enabled_data: assert property (
        @(posedge C) (E && (D == Q)) |=> (Q == $past(Q))
    );

// When S is low, Y selects A.
    check_select_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

// When S is high, Y selects B.
    check_select_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

// A low-to-high selector change makes Y select B.
    check_switch_to_b: assert property (
        @(posedge clk) ($past(S) === 1'b0 && S === 1'b1) |-> (Y === B)
    );

// A high-to-low selector change makes Y select A.
    check_switch_to_a: assert property (
        @(posedge clk) ($past(S) === 1'b1 && S === 1'b0) |-> (Y === A)
    );

// When load is low, the output holds its value.
    check_out_holds_when_ld_low: assert property (
        @(posedge CLK) disable iff (RST)
        !LD |=> (OUT == $past(OUT))
    );

// No clock or reset exists in the RTL; sample this combinational logic on clk.

    // SEL=00 routes IN0[0] to F.
    check_sel_00_routes_in0_lsb: assert property (
        @(posedge clk) (SEL === 2'b00) |-> (F === IN0[0])
    );

// SEL=01 routes IN1[0] to F.
    check_sel_01_routes_in1_lsb: assert property (
        @(posedge clk) (SEL === 2'b01) |-> (F === IN1[0])
    );

// SEL=10 routes IN2[0] to F.
    check_sel_10_routes_in2_lsb: assert property (
        @(posedge clk) (SEL === 2'b10) |-> (F === IN2[0])
    );

// SEL=11 routes IN3[0] to F.
    check_sel_11_routes_in3_lsb: assert property (
        @(posedge clk) (SEL === 2'b11) |-> (F === IN3[0])
    );

// Sync reset forces count to zero on the next clock.
    check_sync_reset_clears_count: assert property (
        @(posedge clk) disable iff (!areset)
        reset |=> (count == 4'd0)
    );

// Load copies L into count on the next clock when reset is low.
    check_load_captures_L: assert property (
        @(posedge clk) disable iff (!areset)
        (!reset && load) |=> (count == $past(L))
    );

// Reset has priority over load in the count update logic.
    check_reset_overrides_load: assert property (
        @(posedge clk) disable iff (!areset)
        (reset && load) |=> (count == 4'd0)
    );

// Output always matches the RTL combinational expression.
    check_out_matches_rtl: assert property (
        @(posedge clk) out == (in[3] ? ((~in) + 4'd1) : in)
    );

// Non-negative inputs pass through unchanged.
    check_non_negative_passthrough: assert property (
        @(posedge clk) !in[3] |-> (out == in)
    );

// Inputs with MSB set are converted using two's complement.
    check_negative_twos_complement: assert property (
        @(posedge clk) in[3] |-> (out == ((~in) + 4'd1))
    );

// For inputs with MSB set, input and output sum to zero modulo 16.
    check_negative_mod16_zero_sum: assert property (
        @(posedge clk) in[3] |-> ((out + in) == 4'd0)
    );

// The most-negative 4-bit value remains unchanged after two's complement.
    check_min_negative_fixed_point: assert property (
        @(posedge clk) (in == 4'b1000) |-> (out == 4'b1000)
    );

// Sample the combinational RTL on an external formal clock.
    // Y must match the implemented OR-of-ANDs equation.
    check_output_equation: assert property (
        @(posedge clk) Y == ((A1_N & A2_N) | (B1 & B2))
    );

// If the A1_N/A2_N term is high, Y must be high.
    check_a_term_drives_high: assert property (
        @(posedge clk) (A1_N & A2_N) |-> Y
    );

// If the B1/B2 term is high, Y must be high.
    check_b_term_drives_high: assert property (
        @(posedge clk) (B1 & B2) |-> Y
    );

// If neither product term is high, Y must be low.
    check_no_terms_means_low: assert property (
        @(posedge clk) (!(A1_N & A2_N) && !(B1 & B2)) |-> !Y
    );

// A high Y must be caused by at least one product term.
    check_y_high_has_cause: assert property (
        @(posedge clk) Y |-> ((A1_N & A2_N) || (B1 & B2))
    );

// Any case with B low and C high must drive X high.
    check_notb_c_forces_high: assert property (
        @(posedge clk)
        (~B & C) |-> (X == 1'b1)
    );

// A high, B low, and D high must drive X high.
    check_a_notb_d_forces_high: assert property (
        @(posedge clk)
        (A & ~B & D) |-> (X == 1'b1)
    );

// A, B, and C high must drive X high.
    check_abc_forces_high: assert property (
        @(posedge clk)
        (A & B & C) |-> (X == 1'b1)
    );

// The minterm A=0, B=1, C=0, D=0 must drive X high.
    check_na_b_nc_nd_forces_high: assert property (
        @(posedge clk)
        (~A & B & ~C & ~D) |-> (X == 1'b1)
    );

// A=0, B=0, and C=0 always produce X low.
    check_na_nb_nc_forces_low: assert property (
        @(posedge clk)
        (~A & ~B & ~C) |-> (X == 1'b0)
    );

// B high, C low, and D high must drive X low.
    check_b_nc_d_forces_low: assert property (
        @(posedge clk)
        (B & ~C & D) |-> (X == 1'b0)
    );

// A high, B high, and C low must drive X low.
    check_ab_nc_forces_low: assert property (
        @(posedge clk)
        (A & B & ~C) |-> (X == 1'b0)
    );

// The minterm A=0, B=1, C=1, D=0 must drive X low.
    check_na_b_c_nd_forces_low: assert property (
        @(posedge clk)
        (~A & B & C & ~D) |-> (X == 1'b0)
    );

// Output always matches the inverted input.
    check_inversion_function: assert property (
        @(posedge clk) (Y === ~A)
    );

// A sampled low input produces a sampled high output.
    check_low_input_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A sampled high input produces a sampled low output.
    check_high_input_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// An unknown or high-Z input produces an unknown output.
    check_unknown_input_unknown_output: assert property (
        @(posedge clk) ((A !== 1'b0) && (A !== 1'b1)) |-> (Y === 1'bx)
    );

// When A is greater than B, out must encode greater-than.
    check_gt_encoding: assert property (
        @(posedge clk) (A > B) |-> (out == 2'b01)
    );

// When A is less than B, out must encode less-than.
    check_lt_encoding: assert property (
        @(posedge clk) (A < B) |-> (out == 2'b10)
    );

// When A equals B, out must encode equality.
    check_eq_encoding: assert property (
        @(posedge clk) (A == B) |-> (out == 2'b11)
    );

// out=01 must only occur when A is greater than B.
    check_code_01_means_gt: assert property (
        @(posedge clk) (out == 2'b01) |-> (A > B)
    );

// out=10 must only occur when A is less than B.
    check_code_10_means_lt: assert property (
        @(posedge clk) (out == 2'b10) |-> (A < B)
    );

// out=11 must only occur when A equals B.
    check_code_11_means_eq: assert property (
        @(posedge clk) (out == 2'b11) |-> (A == B)
    );

// The comparator never drives the unused code 00.
    check_no_unused_code: assert property (
        @(posedge clk) out != 2'b00
    );

// When SEL is low, OUT must follow A.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (SEL == 1'b0) |-> (OUT == A)
    );

// When SEL is high, OUT must follow B.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (SEL == 1'b1) |-> (OUT == B)
    );

// When both inputs are equal, OUT must match that common value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A == B) |-> (OUT == A)
    );

// OUT must match the implemented 2:1 mux equation.
    check_mux_boolean_equation: assert property (
        @(posedge clk) OUT == ((A & ~SEL) | (B & SEL))
    );

// SET synchronously forces Q high.
    check_sync_set_forces_q_high: assert property (
        @(posedge CLK) SET |=> (Q == 1'b1)
    );

// When SET is low, a high D is captured into Q.
    check_capture_d_high_when_set_low: assert property (
        @(posedge CLK) (!SET && D) |=> (Q == 1'b1)
    );

// When SET is low, a low D is captured into Q.
    check_capture_d_low_when_set_low: assert property (
        @(posedge CLK) (!SET && !D) |=> (Q == 1'b0)
    );

// Sum output is the 8-bit addition of a and b.
    check_sum_matches_addition: assert property (
        @(posedge clk) s == (a + b)
    );

// Overflow follows the signed addition overflow rule.
    check_overflow_matches_sign_rule: assert property (
        @(posedge clk) overflow == ((a[7] == b[7]) && (a[7] != s[7]))
    );

// Mixed-sign additions do not assert overflow.
    check_no_overflow_for_mixed_sign_inputs: assert property (
        @(posedge clk) (a[7] != b[7]) |-> !overflow
    );

// Two positive inputs producing a negative sum must assert overflow.
    check_positive_overflow_case: assert property (
        @(posedge clk) ((a[7] == 1'b0) && (b[7] == 1'b0) && (s[7] == 1'b1)) |-> overflow
    );

// Two negative inputs producing a positive sum must assert overflow.
    check_negative_overflow_case: assert property (
        @(posedge clk) ((a[7] == 1'b1) && (b[7] == 1'b1) && (s[7] == 1'b0)) |-> overflow
    );

// clk is the only clock; reset is active-high synchronous.
    // count is a 3-bit enabled up-counter with wrap from 7 to 0.

    // Reset forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'd0)
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> $stable(count)
    );

// When enabled below 7, the counter increments by one.
    check_increment_when_enabled_below_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 3'd7)) |=> (count == ($past(count) + 3'd1))
    );

// When enabled at 7, the counter wraps back to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 3'd7)) |=> (count == 3'd0)
    );

// If d is low at a clock edge, q is low on the next cycle.
    check_q_low_when_d_low: assert property (
        @(posedge clk) !d |=> !q
    );

// Pure combinational decoder sampled on clk; RTL has no reset.

    // Y7 is high only for input 111.
    check_y7_decode: assert property (
        @(posedge clk) Y7 == (A2 & A1 & A0)
    );

// Y6 is high only for input 110.
    check_y6_decode: assert property (
        @(posedge clk) Y6 == (A2 & A1 & ~A0)
    );

// Y5 is high only for input 101.
    check_y5_decode: assert property (
        @(posedge clk) Y5 == (A2 & ~A1 & A0)
    );

// Y4 is high only for input 100.
    check_y4_decode: assert property (
        @(posedge clk) Y4 == (A2 & ~A1 & ~A0)
    );

// Y3 is high only for input 011.
    check_y3_decode: assert property (
        @(posedge clk) Y3 == (~A2 & A1 & A0)
    );

// Y2 is high only for input 010.
    check_y2_decode: assert property (
        @(posedge clk) Y2 == (~A2 & A1 & ~A0)
    );

// Y1 is high only for input 001.
    check_y1_decode: assert property (
        @(posedge clk) Y1 == (~A2 & ~A1 & A0)
    );

// Y0 is high only for input 000.
    check_y0_decode: assert property (
        @(posedge clk) Y0 == (~A2 & ~A1 & ~A0)
    );

// The output vector matches the decoded input value.
    check_output_vector_decode: assert property (
        @(posedge clk) {Y7, Y6, Y5, Y4, Y3, Y2, Y1, Y0} == (8'b0000_0001 << {A2, A1, A0})
    );

// Exactly one output is asserted for every input combination.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({Y7, Y6, Y5, Y4, Y3, Y2, Y1, Y0})
    );

// strobe_out is the combinational compare of count and rate.
    check_strobe_out_matches_count_rate: assert property (
        @(posedge clock) disable iff (reset)
        (strobe_out == (count == rate))
    );

// Disabling the block clears count on the next cycle.
    check_count_resets_when_disabled: assert property (
        @(posedge clock) disable iff (reset)
        !enable |=> (count == INITIAL_VAL)
    );

// A compare hit clears count on the next cycle.
    check_count_resets_when_count_hits_rate: assert property (
        @(posedge clock) disable iff (reset)
        (count == rate) |=> (count == INITIAL_VAL)
    );

// A high strobe_out clears count on the next cycle.
    check_count_resets_on_strobe_out: assert property (
        @(posedge clock) disable iff (reset)
        strobe_out |=> (count == INITIAL_VAL)
    );

// A qualified strobe_in increments count by INCREMENT_VAL.
    check_count_increments_on_strobe_in: assert property (
        @(posedge clock) disable iff (reset)
        enable && !strobe_out && strobe_in |=> (count == ($past(count) + INCREMENT_VAL))
    );

// Without strobe_in, count holds when enabled and below rate.
    check_count_holds_without_strobe_in: assert property (
        @(posedge clock) disable iff (reset)
        enable && !strobe_out && !strobe_in |=> (count == $past(count))
    );

// Output matches the RTL majority XOR parity equation.
    check_out_matches_rtl_definition: assert property (
        @(posedge clk)
        out == (
            ((in1 & in2 & in3) |
             (in1 & in2 & in4) |
             (in1 & in3 & in4) |
             (in2 & in3 & in4)) ^
            (in1 ^ in2 ^ in3 ^ in4)
        )
    );

// All inputs low must drive the output low.
    check_all_zero_output_low: assert property (
        @(posedge clk)
        (!in1 && !in2 && !in3 && !in4) |-> (out == 1'b0)
    );

// A one-hot input pattern must drive the output high.
    check_one_hot_output_high: assert property (
        @(posedge clk)
        (
            ( in1 && !in2 && !in3 && !in4) ||
            (!in1 &&  in2 && !in3 && !in4) ||
            (!in1 && !in2 &&  in3 && !in4) ||
            (!in1 && !in2 && !in3 &&  in4)
        ) |-> (out == 1'b1)
    );

// Any two-high input pattern must drive the output low.
    check_two_high_output_low: assert property (
        @(posedge clk)
        (
            ( in1 &&  in2 && !in3 && !in4) ||
            ( in1 && !in2 &&  in3 && !in4) ||
            ( in1 && !in2 && !in3 &&  in4) ||
            (!in1 &&  in2 &&  in3 && !in4) ||
            (!in1 &&  in2 && !in3 &&  in4) ||
            (!in1 && !in2 &&  in3 &&  in4)
        ) |-> (out == 1'b0)
    );

// Any three-high input pattern must drive the output low.
    check_three_high_output_low: assert property (
        @(posedge clk)
        (
            (!in1 &&  in2 &&  in3 &&  in4) ||
            ( in1 && !in2 &&  in3 &&  in4) ||
            ( in1 &&  in2 && !in3 &&  in4) ||
            ( in1 &&  in2 &&  in3 && !in4)
        ) |-> (out == 1'b0)
    );

// All inputs high must drive the output high.
    check_all_one_output_high: assert property (
        @(posedge clk)
        (in1 && in2 && in3 && in4) |-> (out == 1'b1)
    );

// X must equal A OR B OR inverted C_N.
    check_output_matches_or3b_function: assert property (
        @(posedge clk) X == (A | B | (~C_N))
    );

// A asserted must drive X high.
    check_a_high_forces_x_high: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == 1'b1)
    );

// B asserted must drive X high.
    check_b_high_forces_x_high: assert property (
        @(posedge clk) (B == 1'b1) |-> (X == 1'b1)
    );

// Active-low C input asserted low must drive X high.
    check_cn_low_forces_x_high: assert property (
        @(posedge clk) (C_N == 1'b0) |-> (X == 1'b1)
    );

// With A and B low, X must follow the inversion of C_N.
    check_ab_low_makes_x_follow_inverted_cn: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (X == (~C_N))
    );

// When all OR terms are inactive, X must be low.
    check_all_inputs_inactive_force_x_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C_N == 1'b1)) |-> (X == 1'b0)
    );

// In scan-hold mode, Q must retain its previous value.
    check_scan_hold: assert property (
        @(posedge CLK)
        ((SCD == 1'b0) && (SCE == 1'b1)) |=> (Q == $past(Q))
    );

// Outside scan-hold, DE high causes Q to capture D on the next cycle.
    check_capture_when_enabled: assert property (
        @(posedge CLK)
        (!((SCD == 1'b0) && (SCE == 1'b1)) && (DE == 1'b1)) |=> (Q == $past(D))
    );

// Outside scan-hold, DE low leaves Q unchanged.
    check_hold_when_disabled: assert property (
        @(posedge CLK)
        (!((SCD == 1'b0) && (SCE == 1'b1)) && (DE == 1'b0)) |=> (Q == $past(Q))
    );

// X must match the implemented pairwise-AND/or inversion.
    check_function_equation: assert property (
        @(posedge clk) (X == ~((A & B) | (B & C) | (C & A)))
    );

// 000 must drive X high.
    check_all_zero_drives_one: assert property (
        @(posedge clk) ({A, B, C} == 3'b000) |-> (X == 1'b1)
    );

// 001 must drive X high.
    check_only_c_high_drives_one: assert property (
        @(posedge clk) ({A, B, C} == 3'b001) |-> (X == 1'b1)
    );

// 010 must drive X high.
    check_only_b_high_drives_one: assert property (
        @(posedge clk) ({A, B, C} == 3'b010) |-> (X == 1'b1)
    );

// 011 must drive X low.
    check_b_and_c_high_drive_zero: assert property (
        @(posedge clk) ({A, B, C} == 3'b011) |-> (X == 1'b0)
    );

// 100 must drive X high.
    check_only_a_high_drives_one: assert property (
        @(posedge clk) ({A, B, C} == 3'b100) |-> (X == 1'b1)
    );

// 101 must drive X low.
    check_c_and_a_high_drive_zero: assert property (
        @(posedge clk) ({A, B, C} == 3'b101) |-> (X == 1'b0)
    );

// 110 must drive X low.
    check_a_and_b_high_drive_zero: assert property (
        @(posedge clk) ({A, B, C} == 3'b110) |-> (X == 1'b0)
    );

// 111 must drive X low.
    check_all_high_drive_zero: assert property (
        @(posedge clk) ({A, B, C} == 3'b111) |-> (X == 1'b0)
    );

// Output must equal the OR of all four inputs.
    check_out_matches_or: assert property (
        @(posedge clk) out == (in1 | in2 | in3 | in4)
    );

// Any asserted input must make the output high.
    check_any_input_drives_out_high: assert property (
        @(posedge clk) (in1 | in2 | in3 | in4) |-> out
    );

// A high output must be caused by at least one high input.
    check_out_high_implies_input_high: assert property (
        @(posedge clk) out |-> (in1 | in2 | in3 | in4)
    );

// All inputs low must make the output low.
    check_all_inputs_low_drives_out_low: assert property (
        @(posedge clk) !(in1 | in2 | in3 | in4) |-> !out
    );

// A low output implies all inputs are low.
    check_out_low_implies_all_inputs_low: assert property (
        @(posedge clk) !out |-> !(in1 | in2 | in3 | in4)
    );

// in1 alone being high must force the output high.
    check_in1_drives_out_high: assert property (
        @(posedge clk) in1 |-> out
    );

// in2 alone being high must force the output high.
    check_in2_drives_out_high: assert property (
        @(posedge clk) in2 |-> out
    );

// in3 alone being high must force the output high.
    check_in3_drives_out_high: assert property (
        @(posedge clk) in3 |-> out
    );

// in4 alone being high must force the output high.
    check_in4_drives_out_high: assert property (
        @(posedge clk) in4 |-> out
    );

// Carry output matches the input AND.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// Sum output matches the input XOR.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// 0 + 0 produces zero sum and zero carry.
    check_zero_zero_case: assert property (
        @(posedge clk) (!A && !B) |-> (!SUM && !COUT)
    );

// 1 + 0 produces sum with no carry.
    check_one_zero_case: assert property (
        @(posedge clk) (A && !B) |-> (SUM && !COUT)
    );

// 0 + 1 produces sum with no carry.
    check_zero_one_case: assert property (
        @(posedge clk) (!A && B) |-> (SUM && !COUT)
    );

// 1 + 1 produces carry with no sum.
    check_one_one_case: assert property (
        @(posedge clk) (A && B) |-> (!SUM && COUT)
    );

// Synchronous reset clears both counters and the sum.
    check_reset_clears_outputs: assert property (
        @(posedge CLK) RST |=> (Q1 == 8'h00) && (Q2 == 8'h00) && (sum == 8'h00)
    );

// The sum output matches the two counter outputs.
    check_sum_matches_q1_q2: assert property (
        @(posedge CLK) disable iff (RST) sum == (Q1 + Q2)
    );

// LD1 overrides the count direction and loads LOAD_IN1.
    check_q1_load_priority: assert property (
        @(posedge CLK) disable iff (RST) LD1 |=> (Q1 == $past(LOAD_IN1))
    );

// Without LD1, UD1 high increments Q1.
    check_q1_increment: assert property (
        @(posedge CLK) disable iff (RST) (!LD1 && UD1) |=> (Q1 == ($past(Q1) + 8'd1))
    );

// Without LD1, UD1 low decrements Q1.
    check_q1_decrement: assert property (
        @(posedge CLK) disable iff (RST) (!LD1 && !UD1) |=> (Q1 == ($past(Q1) - 8'd1))
    );

// LD2 overrides the count direction and loads LOAD_IN2.
    check_q2_load_priority: assert property (
        @(posedge CLK) disable iff (RST) LD2 |=> (Q2 == $past(LOAD_IN2))
    );

// Without LD2, UD2 high increments Q2.
    check_q2_increment: assert property (
        @(posedge CLK) disable iff (RST) (!LD2 && UD2) |=> (Q2 == ($past(Q2) + 8'd1))
    );

// Without LD2, UD2 low decrements Q2.
    check_q2_decrement: assert property (
        @(posedge CLK) disable iff (RST) (!LD2 && !UD2) |=> (Q2 == ($past(Q2) - 8'd1))
    );

// Reset forces the register output to zero.
  check_reset_forces_zero: assert property (
    @(posedge clk) rst |-> (out == '0)
  );

// Continuous reset keeps the sampled output zero and unchanged.
  check_reset_holds_zero: assert property (
    @(posedge clk) ($past(rst) && rst) |-> ($stable(out) && (out == '0))
  );

// The 5-bit output matches the zero-extended sum of A and B.
    check_full_sum_correct: assert property (
        @(posedge clk) disable iff (1'b0)
        ({Cout, S} == ({1'b0, A} + {1'b0, B}))
    );

// Zero plus zero produces a zero result with no carry.
    check_zero_plus_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'h0) && (B == 4'h0)) |-> ({Cout, S} == 5'h00)
    );

// Adding zero on A passes B directly to the output.
    check_a_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'h0) |-> ({Cout, S} == {1'b0, B})
    );

// Adding zero on B passes A directly to the output.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (B == 4'h0) |-> ({Cout, S} == {1'b0, A})
    );

// Maximum inputs produce 30 with carry-out asserted.
    check_max_plus_max: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 4'hf) && (B == 4'hf)) |-> ({Cout, S} == 5'h1e)
    );

// LCD_RW is the inverse of address[0].
    check_lcd_rw_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
        (LCD_RW == ~address[0])
    );

// LCD_RS follows address[1].
    check_lcd_rs_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
        (LCD_RS == address[1])
    );

// LCD_E is low while reset is asserted.
    check_lcd_e_reset_low: assert property (
        @(posedge clk)
        (!reset_n) |-> (LCD_E == 1'b0)
    );

// LCD_data is zero while reset is asserted.
    check_lcd_data_reset_zero: assert property (
        @(posedge clk)
        (!reset_n) |-> (LCD_data == 8'h00)
    );

// Any read or write drives LCD_E high on the next cycle.
    check_lcd_e_set_on_access: assert property (
        @(posedge clk) disable iff (!reset_n)
        (read || write) |=> (LCD_E == 1'b1)
    );

// No read or write drives LCD_E low on the next cycle.
    check_lcd_e_clear_without_access: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!read && !write) |=> (LCD_E == 1'b0)
    );

// A write captures writedata into LCD_data on the next cycle.
    check_lcd_data_capture_on_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        write |=> (LCD_data == $past(writedata))
    );

// Without a write, LCD_data holds its previous value.
    check_lcd_data_hold_without_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        !write |=> (LCD_data == $past(LCD_data))
    );

// A sampled reset cycle clears the parallel output by the next clock.
    check_reset_clears_busout: assert property (
        @(posedge clk) !rst |=> (BusOut == 4'b0000)
    );

// The sampled output remains zero on the first cycle after reset release.
    check_reset_release_keeps_zero_before_shift: assert property (
        @(posedge clk) (!rst ##1 rst) |-> (BusOut == 4'b0000)
    );

// In normal operation, the output shifts left and loads SerialIn into bit 0.
    check_shift_register_update: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut == { $past(BusOut[2:0]), $past(SerialIn) })
    );

// Bit 3 takes the previous value of bit 2.
    check_bit3_shift_from_bit2: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[3] == $past(BusOut[2]))
    );

// Bit 2 takes the previous value of bit 1.
    check_bit2_shift_from_bit1: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[2] == $past(BusOut[1]))
    );

// Bit 1 takes the previous value of bit 0.
    check_bit1_shift_from_bit0: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[1] == $past(BusOut[0]))
    );

// Bit 0 captures the previous SerialIn value.
    check_bit0_captures_serialin: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[0] == $past(SerialIn))
    );

// Reset clears the counter on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// The counter increments by one on each cycle out of reset.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// The counter wraps from 15 back to 0.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset) (count == 4'hF) |=> (count == 4'h0)
    );

// After reset release, the first counted value is 1.
    check_first_increment_after_reset_release: assert property (
        @(posedge clk) (reset ##1 !reset) |=> (count == 4'h1)
    );

// A sampled low reset forces q to zero by the next sampled clock edge.
    check_reset_clears_by_next_clk: assert property (
        @(posedge clk) !rst |=> (q == 4'b0000)
    );

// Outside reset, q is either zero or the previous sampled value plus one.
    check_q_advances_or_is_zero: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> ((q == 4'b0000) || (q == ($past(q) + 4'd1)))
    );

// When q leaves zero on an active cycle, the next nonzero value is one.
    check_zero_to_one_transition: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> ((!($past(q) == 4'b0000 && q != 4'b0000)) || (q == 4'b0001))
    );

// A sampled value of 4'hF wraps to zero on the next active sampled cycle.
    check_wrap_from_f_to_zero: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (($past(q) != 4'hF) || (q == 4'h0))
    );

// DUT is combinational; clk is only for assertion sampling.
    // Output must always match the RTL mux equation.
    check_mux_function_exact: assert property (
        @(posedge clk) (Y === ((S == 1'b0) ? A : B))
    );

// When select is 0, output must match A.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Y === A)
    );

// When select is 1, output must match B.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Y === B)
    );

// Equal inputs must force the same output regardless of select.
    check_equal_inputs_force_output: assert property (
        @(posedge clk) (A === B) |-> (Y === A)
    );

// Unknown select with different inputs must produce an unknown output.
    check_unknown_select_diff_inputs_x_output: assert property (
        @(posedge clk) ($isunknown(S) && (A !== B)) |-> $isunknown(Y)
    );

// Reset clears both registers and the derived output on the next clock.
    check_reset_clears_pipeline: assert property (
        @(posedge clk)
        reset |=> (adder1_out == 4'b0000) && (adder2_out == 4'b0000) && (final_output == 4'b0000)
    );

// Inputs 0 through 9 map directly to the low BCD digit.
    check_single_digit_conversion: assert property (
        @(posedge clk) (A <= 4'd9) |-> (Z == {4'h0, A})
    );

// Inputs 10 through 15 map to BCD with tens digit 1.
    check_ten_to_fifteen_conversion: assert property (
        @(posedge clk) (A >= 4'd10) |-> (Z == {4'h1, (A - 4'd10)})
    );

// Inputs below ten keep the tens digit at zero.
    check_tens_digit_below_ten: assert property (
        @(posedge clk) (A <= 4'd9) |-> (Z[7:4] == 4'h0)
    );

// Inputs ten and above drive the tens digit to one.
    check_tens_digit_ten_or_more: assert property (
        @(posedge clk) (A >= 4'd10) |-> (Z[7:4] == 4'h1)
    );

// Inputs below ten keep the ones digit equal to the input.
    check_ones_digit_below_ten: assert property (
        @(posedge clk) (A <= 4'd9) |-> (Z[3:0] == A)
    );

// Inputs ten and above drive the ones digit to input minus ten.
    check_ones_digit_ten_or_more: assert property (
        @(posedge clk) (A >= 4'd10) |-> (Z[3:0] == (A - 4'd10))
    );

// Output equals the XOR of the two inputs.
    check_x_matches_xor: assert property (
        @(posedge clk) X == (A ^ B)
    );

// Equal inputs drive the output low.
    check_equal_inputs_drive_low: assert property (
        @(posedge clk) (A == B) |-> !X
    );

// Different inputs drive the output high.
    check_different_inputs_drive_high: assert property (
        @(posedge clk) (A != B) |-> X
    );

// 0 ^ 0 produces 0.
    check_00_to_0: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// 0 ^ 1 produces 1.
    check_01_to_1: assert property (
        @(posedge clk) (!A && B) |-> X
    );

// 1 ^ 0 produces 1.
    check_10_to_1: assert property (
        @(posedge clk) (A && !B) |-> X
    );

// 1 ^ 1 produces 0.
    check_11_to_0: assert property (
        @(posedge clk) (A && B) |-> !X
    );

// Pure combinational mux; sampled on an external clock with no RTL reset.

    // When S is high, X selects A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b1) |-> (X === A1)
    );

// When S is low, X selects A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b0) |-> (X === A0)
    );

// If both data inputs are equal, X matches that common value.
    check_equal_inputs_force_same_output: assert property (
        @(posedge clk) disable iff (1'b0)
        (A0 === A1) |-> (X === A0)
    );

// RTL has no native clock or reset; clk is a sampling clock for these checks.

    // Division[0] matches the implemented mux equation with DivLenSel[0].
    check_division0_equation: assert property (
        @(posedge clk)
        Division[0] === ((DNB[0] & DivLenSel[0]) | (DSN[0] & ~DNB[0]))
    );

// Division[1] matches the implemented mux equation with DivLenSel[0].
    check_division1_equation: assert property (
        @(posedge clk)
        Division[1] === ((DNB[1] & DivLenSel[0]) | (DSN[1] & ~DNB[1]))
    );

// Division[2] matches the implemented mux equation with DivLenSel[1].
    check_division2_equation: assert property (
        @(posedge clk)
        Division[2] === ((DNB[2] & DivLenSel[1]) | (DSN[2] & ~DNB[2]))
    );

// Division[3] matches the implemented mux equation with DivLenSel[1].
    check_division3_equation: assert property (
        @(posedge clk)
        Division[3] === ((DNB[3] & DivLenSel[1]) | (DSN[3] & ~DNB[3]))
    );

// Division[4] matches the implemented mux equation with DivLenSel[2].
    check_division4_equation: assert property (
        @(posedge clk)
        Division[4] === ((DNB[4] & DivLenSel[2]) | (DSN[4] & ~DNB[4]))
    );

// Division[5] matches the implemented mux equation with DivLenSel[2].
    check_division5_equation: assert property (
        @(posedge clk)
        Division[5] === ((DNB[5] & DivLenSel[2]) | (DSN[5] & ~DNB[5]))
    );

// Division[6] matches the implemented mux equation with DivLenSel[3].
    check_division6_equation: assert property (
        @(posedge clk)
        Division[6] === ((DNB[6] & DivLenSel[3]) | (DSN[6] & ~DNB[6]))
    );

// Division[7] matches the implemented mux equation with DivLenSel[3].
    check_division7_equation: assert property (
        @(posedge clk)
        Division[7] === ((DNB[7] & DivLenSel[3]) | (DSN[7] & ~DNB[7]))
    );

// Division[8] matches the implemented mux equation with DivLenSel[3].
    check_division8_equation: assert property (
        @(posedge clk)
        Division[8] === ((DNB[8] & DivLenSel[3]) | (DSN[8] & ~DNB[8]))
    );

// A sampled reset drives the counter to 000 on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

// Outside reset, the next count follows the Johnson update function.
    check_next_state_relation: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count == {$past(count[1:0]), ~$past(count[2])})
    );

// State 000 advances to 001.
    check_state_000_to_001: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b000) |=> (count == 3'b001)
    );

// State 001 advances to 011.
    check_state_001_to_011: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b001) |=> (count == 3'b011)
    );

// State 011 advances to 111.
    check_state_011_to_111: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b011) |=> (count == 3'b111)
    );

// State 111 advances to 110.
    check_state_111_to_110: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b111) |=> (count == 3'b110)
    );

// State 110 advances to 100.
    check_state_110_to_100: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b110) |=> (count == 3'b100)
    );

// State 100 advances to 000.
    check_state_100_to_000: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b100) |=> (count == 3'b000)
    );

// When select is high, the output must follow input b.
    check_sel_high_selects_b: assert property (
        @(posedge clk) (sel === 1'b1) |-> (y === b)
    );

// When select is low, the output must follow input a.
    check_sel_low_selects_a: assert property (
        @(posedge clk) (sel === 1'b0) |-> (y === a)
    );

// If both data inputs are equal, the output must match that value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (a === b) |-> (y === a)
    );

// The output must always match one of the two data inputs.
    check_output_is_from_inputs: assert property (
        @(posedge clk) ((y === a) || (y === b))
    );

// q_a reflects the prior-cycle address_a computation.
    check_q_a_function: assert property (
        @(posedge clock)
        1'b1 |=> (q_a == ($past(address_a[8]) ? ($past(address_a[3:0]) + 4'd1)
                                              : ($past(address_a[3:0]) + 4'd2)))
    );

// q_b reflects the prior-cycle address_b computation.
    check_q_b_function: assert property (
        @(posedge clock)
        1'b1 |=> (q_b == ($past(address_b[8]) ? ($past(address_b[3:0]) + 4'd1)
                                              : ($past(address_b[3:0]) + 4'd2)))
    );

// Matching relevant bits on both inputs produce matching outputs.
    check_matching_inputs_produce_matching_outputs: assert property (
        @(posedge clock)
        ((address_a[8] == address_b[8]) &&
         (address_a[3:0] == address_b[3:0]))
        |=> (q_a == q_b)
    );

// A sampled reset forces the counter to be zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// A terminal count wraps back to zero on the next clock.
    check_wrap_from_max_count: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'b1111) |=> (count == 4'b0000)
    );

// A non-terminal count advances by one unless an asynchronous reset drives it to zero.
    check_increment_from_nonmax_or_async_reset: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'b1111) |=> ((count == ($past(count) + 4'b0001)) || (count == 4'b0000))
    );

// Active-low reset clears both outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> (valid == 1'b0 && data_out == 16'h0000)
    );

// A nonzero ADC sample sets valid on the next clock sample.
    check_nonzero_input_sets_valid: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data != 12'h000) |=> (valid == 1'b1)
    );

// A nonzero ADC sample is zero-extended into data_out.
    check_nonzero_input_updates_data_out: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data != 12'h000) |=> (data_out == {4'b0000, $past(adc_data)})
    );

// A zero ADC sample leaves valid unchanged.
    check_zero_input_holds_valid: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data == 12'h000) |=> (valid == $past(valid))
    );

// A zero ADC sample leaves data_out unchanged.
    check_zero_input_holds_data_out: assert property (
        @(posedge clk) disable iff (!reset_n)
        (adc_data == 12'h000) |=> (data_out == $past(data_out))
    );

// Once valid is high, it stays high until reset.
    check_valid_is_sticky: assert property (
        @(posedge clk) disable iff (!reset_n)
        valid |=> valid
    );

// tc_o must equal the LUT value selected by qp_i plus the mb_type offset.
    check_tc_lookup_exact: assert property (
        @(posedge clk) (tc_o == expected_tc(qp_w))
    );

// Lookup indices below 18 or above 53 must select the default zero output.
    check_tc_default_zero_outside_table: assert property (
        @(posedge clk) (((qp_w < 6'd18) || (qp_w > 6'd53)) |-> (tc_o == 5'd0))
    );

// Lookup indices within the programmed table must produce a nonzero output.
    check_tc_nonzero_inside_table: assert property (
        @(posedge clk) (((qp_w >= 6'd18) && (qp_w <= 6'd53)) |-> (tc_o != 5'd0))
    );

// Reset clears the registered output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (gray_out == 4'b0000)
    );

// Gray output matches the previous cycle's binary input encoding.
    check_gray_vector_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out == {
            $past(bin_in[3]),
            ($past(bin_in[3]) ^ $past(bin_in[2])),
            ($past(bin_in[2]) ^ $past(bin_in[1])),
            ($past(bin_in[1]) ^ $past(bin_in[0]))
        })
    );

// gray_out[3] captures the previous cycle's bin_in[3].
    check_gray_bit3_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[3] == $past(bin_in[3]))
    );

// gray_out[2] is the previous cycle's bin_in[3] XOR bin_in[2].
    check_gray_bit2_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[2] == ($past(bin_in[3]) ^ $past(bin_in[2])))
    );

// gray_out[1] is the previous cycle's bin_in[2] XOR bin_in[1].
    check_gray_bit1_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[1] == ($past(bin_in[2]) ^ $past(bin_in[1])))
    );

// gray_out[0] is the previous cycle's bin_in[1] XOR bin_in[0].
    check_gray_bit0_encoding: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (gray_out[0] == ($past(bin_in[1]) ^ $past(bin_in[0])))
    );

// X must always equal the AND of A and SLEEP_B.
    check_and_function: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// When SLEEP_B is low, X must be forced low.
    check_sleep_low_clamps_output: assert property (
        @(posedge clk) (SLEEP_B == 1'b0) |-> (X == 1'b0)
    );

// When SLEEP_B is high, X must match A.
    check_sleep_high_passes_input: assert property (
        @(posedge clk) (SLEEP_B == 1'b1) |-> (X == A)
    );

// A high output requires both A and SLEEP_B to be high.
    check_output_high_requires_both_inputs: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A == 1'b1) && (SLEEP_B == 1'b1))
    );

// Output implements (~A_N) & B.
    check_output_function: assert property (
        @(posedge clk) X == ((~A_N) & B)
    );

// High A_N forces the output low.
    check_an_high_forces_x_low: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

// Low B forces the output low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == 1'b0)
    );

// A_N low and B high drives the output high.
    check_active_inputs_drive_x_high: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1)) |-> (X == 1'b1)
    );

// High output requires A_N low and B high.
    check_x_high_implies_input_condition: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A_N == 1'b0) && (B == 1'b1))
    );

// Combinational comparator with no reset; clk is an external sampling clock for SVA.

    // EQ must match whether A and B are equal.
    check_eq_definition: assert property (
        @(posedge clk) EQ === (A == B)
    );

// GT must match whether A is greater than B.
    check_gt_definition: assert property (
        @(posedge clk) GT === (A > B)
    );

// LT must match whether A is less than B.
    check_lt_definition: assert property (
        @(posedge clk) LT === (A < B)
    );

// Equal inputs must drive only EQ high.
    check_equal_case_outputs: assert property (
        @(posedge clk) ((A == B) === 1'b1) |-> (EQ && !GT && !LT)
    );

// A greater than B must drive only GT high.
    check_greater_case_outputs: assert property (
        @(posedge clk) ((A > B) === 1'b1) |-> (GT && !EQ && !LT)
    );

// A less than B must drive only LT high.
    check_less_case_outputs: assert property (
        @(posedge clk) ((A < B) === 1'b1) |-> (LT && !EQ && !GT)
    );

// A sampled reset cycle forces the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk)
        reset |=> (count == 4'd0)
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// When enabled below 15 outside reset, the counter increments by one.
    check_increment_when_enabled_below_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'd15) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at 15 outside reset, the counter wraps to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'd15) |=> (count == 4'd0)
    );

// Entire output matches the RTL expression after width extension.
    check_final_output_function: assert property (
        @(posedge clk)
        final_output == {7'b0, (in_hi[0] ^ in_lo[0]), in_hi}
    );

// The low byte is the high input byte.
    check_low_byte_from_in_hi: assert property (
        @(posedge clk)
        final_output[7:0] == in_hi
    );

// Bit 8 is the XOR of the two input LSBs.
    check_bit8_is_lsb_xor: assert property (
        @(posedge clk)
        final_output[8] == (in_hi[0] ^ in_lo[0])
    );

// The upper seven bits are zero.
    check_upper_bits_zero: assert property (
        @(posedge clk)
        final_output[15:9] == 7'b0
    );

// The upper byte is seven zeros with the XOR bit in bit 8.
    check_upper_byte_shape: assert property (
        @(posedge clk)
        final_output[15:8] == {7'b0, (in_hi[0] ^ in_lo[0])}
    );

// Synchronous reset forces SUM to zero.
    check_reset_clears_sum: assert property (
        @(posedge CLK) RST |=> (SUM == 5'b00000)
    );

// Outside reset, SUM reflects the prior cycle addition of A and B.
    check_sum_matches_previous_addition: assert property (
        @(posedge CLK) disable iff (RST)
        !RST |=> (SUM == ({1'b0, $past(A)} + {1'b0, $past(B)}))
    );

// Zero operands produce a zero sum on the next sampled cycle.
    check_zero_inputs_produce_zero_sum: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (A == 4'b0000) && (B == 4'b0000)) |=> (SUM == 5'b00000)
    );

// Maximum operands produce 30 on the next sampled cycle.
    check_max_inputs_produce_thirty: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (A == 4'b1111) && (B == 4'b1111)) |=> (SUM == 5'd30)
    );

// When A is zero, SUM equals the prior cycle value of B.
    check_a_zero_passes_b: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (A == 4'b0000)) |=> (SUM == {1'b0, $past(B)})
    );

// When B is zero, SUM equals the prior cycle value of A.
    check_b_zero_passes_a: assert property (
        @(posedge CLK) disable iff (RST)
        (!RST && (B == 4'b0000)) |=> (SUM == {1'b0, $past(A)})
    );

// Active-low reset forces Q low whenever reset is sampled low.
    check_reset_forces_q_low: assert property (
        @(posedge CLK) !RESET_B |-> (Q == 1'b0)
    );

// A clock edge taken during reset leaves Q low at the next clock sample.
    check_reset_cycle_clears_q: assert property (
        @(posedge CLK) !RESET_B |=> (Q == 1'b0)
    );

// On a sampled reset release, Q is still low before the release-cycle update.
    check_reset_release_starts_from_zero: assert property (
        @(posedge CLK) disable iff (!RESET_B) $rose(RESET_B) |-> (Q == 1'b0)
    );

// Reset has priority over SET when both are asserted together.
    check_reset_priority_over_set: assert property (
        @(posedge CLK) (!RESET_B && SET) |-> (Q == 1'b0)
    );

// Reset drives Q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) !rst_n |-> (Q == 4'b0000)
    );

// A sampled reset keeps the next clocked state at zero.
    check_reset_keeps_zero_next_cycle: assert property (
        @(posedge clk) !rst_n |=> (Q == 4'b0000)
    );

// Each active clock follows the RTL bit rearrangement.
    check_next_state_rearrangement: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (Q == {$past(Q[2]), $past(Q[3]), $past(Q[1]), $past(Q[0])})
    );

// The upper two bits swap on each active clock.
    check_upper_bits_swap: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (Q[3:2] == {$past(Q[2]), $past(Q[3])})
    );

// The lower two bits hold their values on each active clock.
    check_lower_bits_hold: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> (Q[1:0] == $past(Q[1:0]))
    );

// Two active clocks return Q to its earlier value.
    check_two_cycle_repeat: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> ##1 (Q == $past(Q, 2))
    );

// Output must implement the RTL ternary function.
    check_out_matches_function: assert property (
        @(posedge clk) out == (en ? in : 1'b1)
    );

// When enabled, output must follow input.
    check_out_follows_input_when_enabled: assert property (
        @(posedge clk) en |-> (out == in)
    );

// When disabled, output must be driven high.
    check_out_high_when_disabled: assert property (
        @(posedge clk) !en |-> (out == 1'b1)
    );

// A low output is only possible when enabled with a low input.
    check_low_out_requires_enabled_low_input: assert property (
        @(posedge clk) !out |-> (en && !in)
    );

// LSB sum bit matches the first full-adder XOR equation.
    check_lsb_sum_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Adding zero with no carry-in passes A through unchanged.
    check_a_passthrough_when_b_zero: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

// Adding zero with no carry-in passes B through unchanged.
    check_b_passthrough_when_a_zero: assert property (
        @(posedge clk) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

// Sampling clock for this combinational cell; the RTL has no reset.

    // X implements the function (~A_N) & B & C.
    check_and3b_function: assert property (
        @(posedge clk) X == ((~A_N) & B & C)
    );

// A_N high forces X low.
    check_a_n_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// A_N low with B and C high drives X high.
    check_all_inputs_drive_x_high: assert property (
        @(posedge clk) (!A_N && B && C) |-> X
    );

// X high requires A_N low and both B and C high.
    check_x_high_requires_inputs: assert property (
        @(posedge clk) X |-> (!A_N && B && C)
    );

///// NAND behavior /////

    // Y matches the 3-input NAND of A, B, and C.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B & C)
    );

// All three HIGH inputs force Y LOW.
    check_all_high_drives_low: assert property (
        @(posedge clk) (A && B && C) |-> !Y
    );

// A LOW forces Y HIGH.
    check_a_low_drives_high: assert property (
        @(posedge clk) !A |-> Y
    );

// B LOW forces Y HIGH.
    check_b_low_drives_high: assert property (
        @(posedge clk) !B |-> Y
    );

// C LOW forces Y HIGH.
    check_c_low_drives_high: assert property (
        @(posedge clk) !C |-> Y
    );

// A LOW output requires all three inputs HIGH.
    check_low_output_requires_all_high: assert property (
        @(posedge clk) !Y |-> (A && B && C)
    );

// Reset clears the counter on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset has priority over enable when both are asserted.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// When enabled below the maximum value, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at the maximum value, the counter wraps to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// When not enabled and not in reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// Full 5-bit output must match a + b + cin.
    check_sum_matches_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// The least-significant sum bit must be a[0] ^ b[0] ^ cin.
    check_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Zero plus zero with no carry-in must produce zero.
    check_zero_inputs: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> ({cout, sum} == 5'h00)
    );

// Zero plus zero with carry-in must produce one.
    check_cin_only: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0 && cin == 1'b1) |-> ({cout, sum} == 5'h01)
    );

// Adding zero with no carry-in must pass through a.
    check_pass_through_a: assert property (
        @(posedge clk) (b == 4'h0 && cin == 1'b0) |-> ({cout, sum} == {1'b0, a})
    );

// Adding zero with no carry-in must pass through b.
    check_pass_through_b: assert property (
        @(posedge clk) (a == 4'h0 && cin == 1'b0) |-> ({cout, sum} == {1'b0, b})
    );

// Adding carry-in only must increment a.
    check_increment_a: assert property (
        @(posedge clk) (b == 4'h0 && cin == 1'b1) |-> ({cout, sum} == ({1'b0, a} + 5'h01))
    );

// Adding carry-in only must increment b.
    check_increment_b: assert property (
        @(posedge clk) (a == 4'h0 && cin == 1'b1) |-> ({cout, sum} == ({1'b0, b} + 5'h01))
    );

// Max inputs without carry-in must produce 0x1E.
    check_max_inputs_no_cin: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b0) |-> ({cout, sum} == 5'h1E)
    );

// Max inputs with carry-in must produce 0x1F.
    check_max_inputs_with_cin: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> ({cout, sum} == 5'h1F)
    );

// Carry-out must indicate 4-bit addition overflow.
    check_carry_overflow: assert property (
        @(posedge clk) cout == (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
    );

// Sum bit 0 follows the first full-adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Sum bit 2 uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (
                    ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) &
                    (a[1] ^ b[1])
                )
            )
        )
    );

// Sum bit 3 uses the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    (
                        (a[1] & b[1]) |
                        (
                            ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) &
                            (a[1] ^ b[1])
                        )
                    ) &
                    (a[2] ^ b[2])
                )
            )
        )
    );

// Adding zero with no carry-in passes operand a through.
    check_b_zero_passthrough: assert property (
        @(posedge clk)
        (b == 4'b0000 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero with no carry-in passes operand b through.
    check_a_zero_passthrough: assert property (
        @(posedge clk)
        (a == 4'b0000 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// Input a HIGH drives the output HIGH.
    check_a_drives_out_high: assert property (
        @(posedge clk) (a == 1'b1) |-> (out == 1'b1)
    );

// Input b HIGH drives the output HIGH.
    check_b_drives_out_high: assert property (
        @(posedge clk) (b == 1'b1) |-> (out == 1'b1)
    );

// Input c HIGH drives the output HIGH.
    check_c_drives_out_high: assert property (
        @(posedge clk) (c == 1'b1) |-> (out == 1'b1)
    );

// Input d HIGH drives the output HIGH.
    check_d_drives_out_high: assert property (
        @(posedge clk) (d == 1'b1) |-> (out == 1'b1)
    );

// When all inputs are LOW, the output is LOW.
    check_all_inputs_low_drive_out_low: assert property (
        @(posedge clk)
        ((a == 1'b0) && (b == 1'b0) && (c == 1'b0) && (d == 1'b0)) |-> (out == 1'b0)
    );

// Output equals the OR of the four inputs.
    check_out_matches_or_of_inputs: assert property (
        @(posedge clk) (out == (a || b || c || d))
    );

// data_out reflects the prior data_in shifted by current shift_amount[2].
    check_data_out_matches_delayed_input_shift: assert property (
        @(posedge clk) 1'b1 |=> (data_out == ($past(data_in) >> shift_amount[2]))
    );

// out[0] goes high two clocks after any contributing input bit is high.
    check_out0_high_encoding: assert property (
        @(posedge clk)
        ((in[0] | in[1] | in[3] | in[4] | in[6]) == 1'b1) |-> ##2 (out[0] == 1'b1)
    );

// out[0] stays low two clocks after all contributing input bits are low.
    check_out0_low_encoding: assert property (
        @(posedge clk)
        ((in[0] | in[1] | in[3] | in[4] | in[6]) == 1'b0) |-> ##2 (out[0] == 1'b0)
    );

// out[1] goes high two clocks after any contributing input bit is high.
    check_out1_high_encoding: assert property (
        @(posedge clk)
        ((in[2] | in[3] | in[5] | in[6] | in[7]) == 1'b1) |-> ##2 (out[1] == 1'b1)
    );

// out[1] stays low two clocks after all contributing input bits are low.
    check_out1_low_encoding: assert property (
        @(posedge clk)
        ((in[2] | in[3] | in[5] | in[6] | in[7]) == 1'b0) |-> ##2 (out[1] == 1'b0)
    );

// out[2] goes high two clocks after any contributing input bit is high.
    check_out2_high_encoding: assert property (
        @(posedge clk)
        ((in[4] | in[5] | in[6] | in[7]) == 1'b1) |-> ##2 (out[2] == 1'b1)
    );

// out[2] stays low two clocks after all contributing input bits are low.
    check_out2_low_encoding: assert property (
        @(posedge clk)
        ((in[4] | in[5] | in[6] | in[7]) == 1'b0) |-> ##2 (out[2] == 1'b0)
    );

// When disabled, the output must be all zeros.
    check_output_zero_when_disabled: assert property (
        @(posedge clk) !enable |-> (data_out == 4'b0000)
    );

// Select 00 forwards data_in[0] into the LSB and zero-extends the output.
    check_select_00_maps_bit0: assert property (
        @(posedge clk) enable && (select == 2'b00) |-> (data_out == {3'b000, data_in[0]})
    );

// Select 01 forwards data_in[1] into the LSB and zero-extends the output.
    check_select_01_maps_bit1: assert property (
        @(posedge clk) enable && (select == 2'b01) |-> (data_out == {3'b000, data_in[1]})
    );

// Select 10 forwards data_in[2] into the LSB and zero-extends the output.
    check_select_10_maps_bit2: assert property (
        @(posedge clk) enable && (select == 2'b10) |-> (data_out == {3'b000, data_in[2]})
    );

// Select 11 forwards data_in[3] into the LSB and zero-extends the output.
    check_select_11_maps_bit3: assert property (
        @(posedge clk) enable && (select == 2'b11) |-> (data_out == {3'b000, data_in[3]})
    );

// The upper three output bits are always zero due to 1-bit to 4-bit assignment.
    check_output_is_zero_extended: assert property (
        @(posedge clk) (data_out[3:1] == 3'b000)
    );

// X must equal the implemented OR of the two product terms.
    check_x_matches_boolean_function: assert property (
        @(posedge clk) disable iff (1'b0)
            X == ((A1 & A2) | (B1 & B2 & VPWR & VGND & VPB & VNB))
    );

// The A1/A2 product term alone is sufficient to drive X high.
    check_a_term_drives_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
            (A1 & A2) |-> X
    );

// The B1/B2 product term with all gating inputs high is sufficient to drive X high.
    check_b_term_drives_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
            (B1 & B2 & VPWR & VGND & VPB & VNB) |-> X
    );

// A high X must come from one of the two implemented product terms.
    check_x_high_has_valid_source: assert property (
        @(posedge clk) disable iff (1'b0)
            X |-> ((A1 & A2) | (B1 & B2 & VPWR & VGND & VPB & VNB))
    );

// If neither product term is active, X must be low.
    check_x_low_without_active_terms: assert property (
        @(posedge clk) disable iff (1'b0)
            (!(A1 & A2) && !(B1 & B2 & VPWR & VGND & VPB & VNB)) |-> !X
    );

// With the A term inactive, any low gating input blocks the B term from raising X.
    check_low_gate_blocks_b_term_when_a_term_inactive: assert property (
        @(posedge clk) disable iff (1'b0)
            (!(A1 & A2) && B1 && B2 && (!VPWR || !VGND || !VPB || !VNB)) |-> !X
    );

// pos must be zero while reset is asserted low.
    check_reset_clears_pos: assert property (
        @(posedge clk) !reset |-> (pos == 2'b00)
    );

// valid[3] has highest priority and selects position 3.
    check_valid3_priority: assert property (
        @(posedge clk) disable iff (!reset)
        valid[3] |=> (pos == 2'b11)
    );

// valid[2] selects position 2 when valid[3] is not set.
    check_valid2_priority: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && valid[2]) |=> (pos == 2'b10)
    );

// valid[1] selects position 1 when higher priority valids are not set.
    check_valid1_priority: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && !valid[2] && valid[1]) |=> (pos == 2'b01)
    );

// valid[0] selects position 0 when it is the highest valid bit.
    check_valid0_priority: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && !valid[2] && !valid[1] && valid[0]) |=> (pos == 2'b00)
    );

// No valid bits set drives the encoded position to zero.
    check_no_valid_defaults_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (!valid[3] && !valid[2] && !valid[1] && !valid[0]) |=> (pos == 2'b00)
    );

// With sel low, q shows the prior d1 value on the next clock.
    check_q_captures_d1_when_sel_low: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b0) |=> (q == $past(d1))
    );

// With sel high, q shows the prior d2 value on the next clock.
    check_q_captures_d2_when_sel_high: assert property (
        @(posedge clk) disable iff (reset)
        (sel == 1'b1) |=> (q == $past(d2))
    );

// A reset cycle leaves the internal register cleared on the next clock.
    check_flip_flop_out_cleared_after_reset: assert property (
        @(posedge clk)
        reset |=> (flip_flop_out == 8'b0)
    );

// A reset cycle leaves q cleared on the next clock.
    check_q_cleared_after_reset: assert property (
        @(posedge clk)
        reset |=> (q == 8'b0)
    );

// Reset drives Q low on the next sampled cycle.
    check_reset_forces_q_low: assert property (
        @(posedge clk) RESET |=> (Q == 1'b0)
    );

// Reset drives Q_n high on the next sampled cycle.
    check_reset_forces_qn_high: assert property (
        @(posedge clk) RESET |=> (Q_n == 1'b1)
    );

// When enabled, Q captures D.
    check_enable_loads_q_from_d: assert property (
        @(posedge clk) disable iff (RESET) EN |=> (Q == $past(D))
    );

// When enabled, Q_n captures the inverse of D.
    check_enable_loads_qn_from_inverted_d: assert property (
        @(posedge clk) disable iff (RESET) EN |=> (Q_n == ~$past(D))
    );

// When not enabled, Q holds its previous value.
    check_hold_q_when_disabled: assert property (
        @(posedge clk) disable iff (RESET) !EN |=> $stable(Q)
    );

// When not enabled, Q_n holds its previous value.
    check_hold_qn_when_disabled: assert property (
        @(posedge clk) disable iff (RESET) !EN |=> $stable(Q_n)
    );

// Output matches the implemented mux expression.
    check_mux_function: assert property (
        @(posedge clk)
        out == (({sel1, sel0} == 2'b00) ? in0 :
                ({sel1, sel0} == 2'b01) ? in1 :
                ({sel1, sel0} == 2'b10) ? in2 :
                in3)
    );

// Select 00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b00) |-> (out == in0)
    );

// Select 01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b01) |-> (out == in1)
    );

// Select 10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b10) |-> (out == in2)
    );

// Select 11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk)
        ({sel1, sel0} == 2'b11) |-> (out == in3)
    );

// Clock: Q; reset: none; logic: sequential on posedge Q.

    // From the third sampled clock onward, pulse matches a prior sampled 0->1 on D.
    check_pulse_matches_prior_sampled_rise: assert property (
        @(posedge Q) (##2 1'b1) |-> (pulse == ($past(D) && !$past(D,2)))
    );

// A prior sampled low-to-high transition on D produces pulse.
    check_prior_low_to_high_generates_pulse: assert property (
        @(posedge Q) (##2 ($past(D) && !$past(D,2))) |-> pulse
    );

// Consecutive sampled highs on D do not retrigger pulse.
    check_prior_high_to_high_suppresses_pulse: assert property (
        @(posedge Q) (##2 ($past(D) && $past(D,2))) |-> !pulse
    );

// If D was low on the prior sampled clock, pulse is low now.
    check_prior_low_clears_pulse: assert property (
        @(posedge Q) (##1 (!$past(D))) |-> !pulse
    );

// pulse can only occur if D was high on the prior sampled clock.
    check_pulse_requires_prior_high_d: assert property (
        @(posedge Q) (##1 pulse) |-> $past(D)
    );

// Once established, pulse is only one sampled clock wide.
    check_pulse_is_single_cycle: assert property (
        @(posedge Q) (##1 pulse) |-> ##1 !pulse
    );

// Sequential 4-bit up-counter with asynchronous active-low reset.

    // A sampled reset cycle forces the next sampled count to zero.
    check_reset_drives_zero_next: assert property (
        @(posedge clk)
        !rst |=> (count == 4'h0)
    );

// After a sampled low-to-high reset transition, count is still zero before incrementing.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk)
        (!rst ##1 rst) |-> (count == 4'h0)
    );

// Below max, the next sampled count is either +1 or 0 if async reset intervenes.
    check_count_advances_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (count != 4'hF) |=> ((count == ($past(count) + 4'd1)) || (count == 4'h0))
    );

// At max, the 4-bit counter wraps to zero on the next sampled clock.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

// From zero, the next sampled count is either 1 or 0 if async reset intervenes.
    check_zero_advances_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'h0) |=> ((count == 4'h1) || (count == 4'h0))
    );

// Addition opcode drives Y to A + B.
    check_add_result: assert property (
        @(posedge clk) (OP === 3'b000) |-> (Y == (A + B))
    );

// Subtraction opcode drives Y to A - B.
    check_sub_result: assert property (
        @(posedge clk) (OP === 3'b001) |-> (Y == (A - B))
    );

// AND opcode drives Y to A & B.
    check_and_result: assert property (
        @(posedge clk) (OP === 3'b010) |-> (Y == (A & B))
    );

// OR opcode drives Y to A | B.
    check_or_result: assert property (
        @(posedge clk) (OP === 3'b011) |-> (Y == (A | B))
    );

// XOR opcode drives Y to A ^ B.
    check_xor_result: assert property (
        @(posedge clk) (OP === 3'b100) |-> (Y == (A ^ B))
    );

// Output always matches the selected datapath result.
    check_output_matches_selected_result: assert property (
        @(posedge clk) S == (M ? S_sub : S_add)
    );

// In add mode, output is the 4-bit sum of A and B.
    check_add_mode_sum: assert property (
        @(posedge clk) !M |-> (S == S_add)
    );

// In M=1 mode, output follows the implemented A + ~B + C_in path.
    check_mode_one_sum: assert property (
        @(posedge clk) M |-> (S == S_sub)
    );

// In add mode with B at zero, output passes A through.
    check_add_mode_b_zero_passthrough: assert property (
        @(posedge clk) (!M && (B == 4'b0000)) |-> (S == A)
    );

// In add mode with A at zero, output passes B through.
    check_add_mode_a_zero_passthrough: assert property (
        @(posedge clk) (!M && (A == 4'b0000)) |-> (S == B)
    );

// In M=1 mode with B all ones, both inverted-B terms are zero.
    check_mode_one_all_ones_b_passthrough: assert property (
        @(posedge clk) (M && (B == 4'hF)) |-> (S == A)
    );

// In add mode, the LSB is the XOR of the input LSBs.
    check_add_mode_lsb_xor: assert property (
        @(posedge clk) !M |-> (S[0] == (A[0] ^ B[0]))
    );

// In M=1 mode, the LSB reduces to A[0].
    check_mode_one_lsb_tracks_a: assert property (
        @(posedge clk) M |-> (S[0] == A[0])
    );

// Green with a pedestrian request transitions to yellow.
    check_green_with_ped_to_yellow: assert property (
        @(posedge clk)
        (current_state == 2'b00 && pedestrian_button) |-> (next_state == 2'b01)
    );

// Green without a pedestrian request transitions to red.
    check_green_without_ped_to_red: assert property (
        @(posedge clk)
        (current_state == 2'b00 && !pedestrian_button) |-> (next_state == 2'b10)
    );

// Yellow always transitions to red.
    check_yellow_to_red: assert property (
        @(posedge clk)
        (current_state == 2'b01) |-> (next_state == 2'b10)
    );

// Red always transitions to green.
    check_red_to_green: assert property (
        @(posedge clk)
        (current_state == 2'b10) |-> (next_state == 2'b00)
    );

// Invalid state defaults to green.
    check_default_to_green: assert property (
        @(posedge clk)
        (current_state == 2'b11) |-> (next_state == 2'b00)
    );

// The next state is never the invalid encoding 2'b11.
    check_next_state_never_invalid: assert property (
        @(posedge clk)
        (1'b1) |-> (next_state != 2'b11)
    );

// Yellow output only occurs from green with a pedestrian request.
    check_yellow_output_source: assert property (
        @(posedge clk)
        (next_state == 2'b01) |-> (current_state == 2'b00 && pedestrian_button)
    );

// Green output only occurs from red or the default case.
    check_green_output_source: assert property (
        @(posedge clk)
        (next_state == 2'b00) |-> (current_state == 2'b10 || current_state == 2'b11)
    );

// Red output only occurs from yellow or green without a pedestrian request.
    check_red_output_source: assert property (
        @(posedge clk)
        (next_state == 2'b10) |-> (current_state == 2'b01 || (current_state == 2'b00 && !pedestrian_button))
    );

// On a clkin rise, the sampled low-input state must have clkout high.
    check_clkout_high_before_clkin_rise: assert property (
        @(posedge clkin) clkout === 1'b1
    );

// On a clkin fall, the sampled high-input state must have clkout low.
    check_clkout_low_before_clkin_fall: assert property (
        @(negedge clkin) clkout === 1'b0
    );

// CLK is the only clock; RST is a synchronous active-high reset.
    // DATA_OUT is an 8-bit registered output.

    ///// Reset behavior /////

    // When reset is asserted, DATA_OUT must be 0 on the following clock.
    check_reset_clears_data_out: assert property (
        @(posedge CLK)
        RST |=> (DATA_OUT === 8'h00)
    );

///// Active-state behavior /////

    // In active mode, F4 must toggle to C2 on the next clock.
    check_f4_transitions_to_c2: assert property (
        @(posedge CLK) disable iff (RST)
        (DATA_OUT === 8'hf4) |=> (DATA_OUT === 8'hc2)
    );

// In active mode, any value other than F4 must become F4 on the next clock.
    check_non_f4_transitions_to_f4: assert property (
        @(posedge CLK) disable iff (RST)
        (DATA_OUT !== 8'hf4) |=> (DATA_OUT === 8'hf4)
    );

// A load updates the register with DATA_IN.
    check_load_captures_input: assert property (
        @(posedge CLK) LOAD_EN |=> (DATA_OUT == $past(DATA_IN))
    );

// Load takes priority when both load and shift are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge CLK) (LOAD_EN && SHIFT_EN) |=> (DATA_OUT == $past(DATA_IN))
    );

// A shift rotates the previous MSB into bit 0.
    check_shift_rotates_left: assert property (
        @(posedge CLK) (!LOAD_EN && SHIFT_EN) |=> (DATA_OUT == { $past(DATA_OUT[2:0]), $past(DATA_OUT[3]) })
    );

// With both enables low, the register holds its value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) (!LOAD_EN && !SHIFT_EN) |=> (DATA_OUT == $past(DATA_OUT))
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b11) |-> (out == in3)
    );

// serial_out reflects the serial_in value sampled on the prior clock.
    check_serial_out_tracks_serial_in: assert property (
        @(posedge clk) 1'b1 |=> serial_out == $past(serial_in)
    );

// Output matches the implemented mux equation; A3 is unused.
    check_mux_equation: assert property (
        @(posedge clk) X == (S1 ? A2 : (S0 ? A1 : A0))
    );

// When both selects are low, the output comes from A0.
    check_select_a0: assert property (
        @(posedge clk) (!S1 && !S0) |-> (X == A0)
    );

// When S1 is low and S0 is high, the output comes from A1.
    check_select_a1: assert property (
        @(posedge clk) (!S1 && S0) |-> (X == A1)
    );

// When S1 is high and S0 is low, the output comes from A2.
    check_select_a2_s0_low: assert property (
        @(posedge clk) (S1 && !S0) |-> (X == A2)
    );

// When S1 is high and S0 is high, the output still comes from A2.
    check_select_a2_s0_high: assert property (
        @(posedge clk) (S1 && S0) |-> (X == A2)
    );

// Clear synchronously sets Q to all ones.
    check_clear_sets_q_to_ones: assert property (
        @(posedge Clock) disable iff (1'b0)
        Clear |=> (Q == 4'hF)
    );

// Enable decrements Q when Load is low.
    check_enable_decrements_q: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && Enable && !Load) |=> (Q == ($past(Q) - 4'd1))
    );

// Enable takes priority over Load.
    check_enable_has_priority_over_load: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && Enable && Load) |=> (Q == ($past(Q) - 4'd1))
    );

// Load sets Q to all ones when selected.
    check_load_sets_q_to_ones: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && !Enable && Load) |=> (Q == 4'hF)
    );

// Q holds its value when no control is asserted.
    check_hold_without_controls: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && !Enable && !Load) |=> (Q == $past(Q))
    );

// Decrement wraps from zero back to all ones.
    check_decrement_wraps_from_zero: assert property (
        @(posedge Clock) disable iff (1'b0)
        (!Clear && Enable && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// RTL has no native clock or reset; clk is an external sampling clock.
    // The design is purely combinational: out is the 4-bit two's complement of in.

    // Output must equal bitwise inversion plus one.
    check_twos_complement_relation: assert property (
        @(posedge clk) out == ((~in) + 4'b0001)
    );

// Input and output must sum to zero modulo 4 bits.
    check_additive_inverse: assert property (
        @(posedge clk) (in + out) == 4'b0000
    );

// Zero must map to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 4'b0000)
    );

// The most negative 4-bit value must map to itself.
    check_most_negative_maps_to_self: assert property (
        @(posedge clk) (in == 4'b1000) |-> (out == 4'b1000)
    );

// Y must always be the inverse of A.
    check_output_is_inverted_input: assert property (
        @(posedge clk) Y == ~A
    );

// A high input must produce a low output.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) A |-> !Y
    );

// A low input must produce a high output.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) !A |-> Y
    );

// RTL is combinational with no reset; assertions are sampled on clk.

    // Y must match the implemented combinational equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ~((~sel1 & A) | (~sel2 & B) | (~sel1 & ~sel2 & C))
    );

// When both selects are high, all terms are disabled and Y is high.
    check_both_selects_high: assert property (
        @(posedge clk)
        (sel1 && sel2) |-> (Y == 1'b1)
    );

// When only the A term is enabled, Y is the inverse of A.
    check_a_term_only_mode: assert property (
        @(posedge clk)
        (!sel1 && sel2) |-> (Y == ~A)
    );

// When only the B term is enabled, Y is the inverse of B.
    check_b_term_only_mode: assert property (
        @(posedge clk)
        (sel1 && !sel2) |-> (Y == ~B)
    );

// When all terms are enabled, Y is the NAND of A, B, and C.
    check_all_terms_enabled_mode: assert property (
        @(posedge clk)
        (!sel1 && !sel2) |-> (Y == ~(A | B | C))
    );

// A high with sel1 low forces the output low.
    check_a_forces_low: assert property (
        @(posedge clk)
        (!sel1 && A) |-> (Y == 1'b0)
    );

// B high with sel2 low forces the output low.
    check_b_forces_low: assert property (
        @(posedge clk)
        (!sel2 && B) |-> (Y == 1'b0)
    );

// C high with both selects low forces the output low.
    check_c_forces_low: assert property (
        @(posedge clk)
        (!sel1 && !sel2 && C) |-> (Y == 1'b0)
    );

// A low output must come from at least one active product term.
    check_low_output_has_active_term: assert property (
        @(posedge clk)
        (Y == 1'b0) |-> ((!sel1 && A) || (!sel2 && B) || (!sel1 && !sel2 && C))
    );

// A high output means none of the implemented product terms is active.
    check_high_output_has_no_active_term: assert property (
        @(posedge clk)
        (Y == 1'b1) |-> ((sel1 || !A) && (sel2 || !B) && (sel1 || sel2 || !C))
    );

// Equal inputs must assert only EQ.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

// A greater than B must assert only GT.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (!EQ && GT && !LT)
    );

// A less than B must assert only LT.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT && LT)
    );

// EQ can only be high when A equals B.
    check_eq_implies_equal: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// GT can only be high when A is greater than B.
    check_gt_implies_greater: assert property (
        @(posedge clk) GT |-> (A > B)
    );

// LT can only be high when A is less than B.
    check_lt_implies_less: assert property (
        @(posedge clk) LT |-> (A < B)
    );

// Exactly one comparison result must be asserted.
    check_result_onehot: assert property (
        @(posedge clk) $onehot({EQ, GT, LT})
    );

// input_phase_tready is a direct mirror of output_phase_tready.
    check_input_phase_ready_mirrors_output_ready: assert property (
        @(posedge clk) disable iff (rst)
        (input_phase_tready == output_phase_tready)
    );

// The constant handshake outputs also hold during reset.
    check_reset_constant_outputs: assert property (
        @(posedge clk)
        rst |-> ((input_phase_tready == output_phase_tready) &&
                 (input_phase_step_tready == 1'b1) &&
                 (output_phase_tvalid == 1'b1))
    );

// Reset reloads the phase output to INITIAL_PHASE.
    check_reset_loads_initial_phase: assert property (
        @(posedge clk)
        rst |=> (output_phase_tdata == INITIAL_PHASE)
    );

// Without a phase load or ready advance, the phase output holds.
    check_phase_holds_without_load_or_advance: assert property (
        @(posedge clk) disable iff (rst)
        (!(input_phase_tready && input_phase_tvalid) && !output_phase_tready)
        |=> (output_phase_tdata == $past(output_phase_tdata))
    );

// After reset releases, the first eligible advance uses INITIAL_PHASE_STEP.
    check_reset_step_used_on_first_increment: assert property (
        @(posedge clk)
        rst ##1 (!rst && !(input_phase_tready && input_phase_tvalid) && output_phase_tready)
        |=> (output_phase_tdata == $past(output_phase_tdata) + INITIAL_PHASE_STEP)
    );

// A written phase step is used by the next eligible advance.
    check_updated_step_used_on_next_increment: assert property (
        @(posedge clk) disable iff (rst)
        input_phase_step_tvalid ##1 (!(input_phase_tready && input_phase_tvalid) && output_phase_tready)
        |=> (output_phase_tdata == $past(output_phase_tdata) + $past(input_phase_step_tdata, 2))
    );

// Sampling clock only; the RTL itself has no clock or reset.

    // X must equal bitwise inversion of A plus 1.
    check_twos_comp_definition: assert property (
        @(posedge clk) X == ((~A) + 4'b0001)
    );

// Taking two's complement of X must recover A.
    check_reverse_twos_comp_definition: assert property (
        @(posedge clk) A == ((~X) + 4'b0001)
    );

// A and X must sum to zero modulo 16.
    check_additive_inverse: assert property (
        @(posedge clk) (A + X) == 4'b0000
    );

// Zero must map to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (A == 4'b0000) |-> (X == 4'b0000)
    );

// 4'b1000 must map to itself.
    check_min_negative_self_inverse: assert property (
        @(posedge clk) (A == 4'b1000) |-> (X == 4'b1000)
    );

// Only 0 and 8 may equal their own two's complement.
    check_only_self_inverse_values: assert property (
        @(posedge clk) (A == X) |-> ((A == 4'b0000) || (A == 4'b1000))
    );

// Active-low reset clears the stored output value.
    reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 9'b0)
    );

// Active-low reset forces read data low.
    reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

// A write to address 0 updates out_port with writedata[8:0] on the next cycle.
    write_addr0_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[8:0]))
    );

// Without a write to address 0, out_port holds its value.
    no_write_addr0_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> $stable(out_port)
    );

// Address 0 reads back the stored value zero-extended to 32 bits.
    read_addr0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {23'b0, out_port})
    );

// Nonzero addresses read as zero.
    read_other_addresses_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

// Count is zero whenever reset is asserted low.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 4'b0000)
    );

// The first sampled cycle after reset release still shows zero.
    check_post_reset_starts_at_zero: assert property (
        @(posedge clk) disable iff (!reset)
        ($past(reset) === 1'b0) |-> (count == 4'b0000)
    );

// On consecutive enabled cycles, count increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!reset)
        ($past(reset) === 1'b1) |-> (count == ($past(count) + 4'b0001))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!reset)
        (($past(reset) === 1'b1) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// The upper two output bits are always cleared.
    check_upper_bits_zero: assert property (
        @(posedge clk) Y[3:2] == 2'b00
    );

// A=0 and B=0 drives Y to 0000.
    check_decode_00: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0) |-> (Y == 4'b0000)
    );

// A=1 and B=0 drives Y to 0001.
    check_decode_10: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0) |-> (Y == 4'b0001)
    );

// A=0 and B=1 drives Y to 0010.
    check_decode_01: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1) |-> (Y == 4'b0010)
    );

// A=1 and B=1 drives Y to 0011.
    check_decode_11: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1) |-> (Y == 4'b0011)
    );

// Matching received and generated parity must be accepted.
    check_accept_matching_parity: assert property (
        @(posedge clk) (parity_in == parity_out) |-> correct
    );

// Mismatched received and generated parity must be rejected.
    check_reject_mismatched_parity: assert property (
        @(posedge clk) (parity_in != parity_out) |-> !correct
    );

// Reset clears the counter to zero by the next sampled clock.
    check_reset_clears_count: assert property (
        @(posedge clk)
        reset |=> (count == 4'b0000)
    );

// When enabled, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'b0001))
    );

// When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_from_f_to_0: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'hF) |=> (count == 4'h0)
    );

// Output must match the implemented combinational function.
    check_output_boolean_form: assert property (
        @(posedge clk) X == (A & (B | C))
    );

// When A<B for 1-bit inputs, the output must be zero.
    check_lt_branch_forces_zero: assert property (
        @(posedge clk) (!A && B) |-> (X == 1'b0)
    );

// When A>B for 1-bit inputs, the output must match C.
    check_gt_branch_matches_c: assert property (
        @(posedge clk) (A && !B) |-> (X == C)
    );

// When A and B are both zero, the equality branch drives zero.
    check_eq_low_branch_forces_zero: assert property (
        @(posedge clk) (!A && !B) |-> (X == 1'b0)
    );

// When A and B are both one, the equality branch drives one.
    check_eq_high_branch_sets_one: assert property (
        @(posedge clk) (A && B) |-> (X == 1'b1)
    );

// After reset deasserts, count remains zero until the next clocked update.
    check_post_reset_zero: assert property (
        @(posedge clk) disable iff (reset)
        $fell(reset) |-> (count == 4'b0000)
    );

// Clear has highest priority and forces count to zero.
    check_clear_forces_zero: assert property (
        @(posedge clk) disable iff (reset)
        clear |=> (count == 4'b0000)
    );

// Load updates count from data_in when clear is low.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        (!clear && load) |=> (count == $past(data_in))
    );

// Count increments when clear and load are low and up_down is high.
    check_increment_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!clear && !load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// Count decrements when clear and load are low and up_down is low.
    check_decrement_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!clear && !load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// The sampled output matches the implemented parity-based mapping.
    check_output_function: assert property (
        @(posedge clk) out == (in[0] ? in[2:1] : 2'b00)
    );

// Even inputs take the multiply-by-2 branch, which truncates to 2'b00.
    check_even_input_output_zero: assert property (
        @(posedge clk) !in[0] |-> (out == 2'b00)
    );

// Odd inputs take the divide-by-2 branch and return input bits [2:1].
    check_odd_input_divide_result: assert property (
        @(posedge clk) in[0] |-> (out == in[2:1])
    );

// The lowest input value maps to zero.
    check_zero_input_output_zero: assert property (
        @(posedge clk) (in == 4'h0) |-> (out == 2'b00)
    );

// The highest odd input value maps to the truncated quotient 2'b11.
    check_max_input_output_three: assert property (
        @(posedge clk) (in == 4'hF) |-> (out == 2'b11)
    );

// RTL is combinational; clk is an external sampling clock and there is no reset.
    // S1:S0 selects A0-A3 onto X.

    // S=00 routes A0 to X.
    check_select_00_routes_a0: assert property (
        @(posedge clk) ((S1 === 1'b0) && (S0 === 1'b0)) |-> (X === A0)
    );

// S=01 routes A1 to X.
    check_select_01_routes_a1: assert property (
        @(posedge clk) ((S1 === 1'b0) && (S0 === 1'b1)) |-> (X === A1)
    );

// S=10 routes A2 to X.
    check_select_10_routes_a2: assert property (
        @(posedge clk) ((S1 === 1'b1) && (S0 === 1'b0)) |-> (X === A2)
    );

// S=11 routes A3 to X.
    check_select_11_routes_a3: assert property (
        @(posedge clk) ((S1 === 1'b1) && (S0 === 1'b1)) |-> (X === A3)
    );

// No reset in RTL; sample combinational behavior on clk.

    // X must equal the OR of A, B, C, and D.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C | D)
    );

// A high must make X high.
    check_a_drives_x_high: assert property (
        @(posedge clk) (A == 1'b1) |-> (X == 1'b1)
    );

// B high must make X high.
    check_b_drives_x_high: assert property (
        @(posedge clk) (B == 1'b1) |-> (X == 1'b1)
    );

// C high must make X high.
    check_c_drives_x_high: assert property (
        @(posedge clk) (C == 1'b1) |-> (X == 1'b1)
    );

// D high must make X high.
    check_d_drives_x_high: assert property (
        @(posedge clk) (D == 1'b1) |-> (X == 1'b1)
    );

// All low inputs must make X low.
    check_all_inputs_low_drive_x_low: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && C == 1'b0 && D == 1'b0) |-> (X == 1'b0)
    );

// X low means all OR inputs are low.
    check_x_low_means_all_inputs_low: assert property (
        @(posedge clk) (X == 1'b0) |-> (A == 1'b0 && B == 1'b0 && C == 1'b0 && D == 1'b0)
    );

// Reset forces the decode output to zero.
    check_reset_forces_zero: assert property (
        @(posedge CCLK) rst |-> (IF == 8'd0)
    );

// Unsupported top-level opcodes decode to zero.
    check_default_opcode_zero: assert property (
        @(posedge CCLK) disable iff (rst)
        (!(instr[31:26] inside {
            6'b000000, 6'b001000, 6'b001001, 6'b001100, 6'b001101,
            6'b001110, 6'b001111, 6'b100011, 6'b101011, 6'b000100,
            6'b000101, 6'b001010, 6'b001011, 6'b000010, 6'b000011
        })) |-> (IF == 8'd0)
    );

// R-type add with nonzero rd maps to IF code 1.
    check_rtype_add_nonzero_rd: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100000) &&
         (|instr[15:11])) |-> (IF == 8'd1)
    );

// R-type add with rd equal to zero maps to IF code 0.
    check_rtype_add_zero_rd: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100000) &&
         !(|instr[15:11])) |-> (IF == 8'd0)
    );

// R-type addu maps to IF code 2.
    check_rtype_addu: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100001)) |-> (IF == 8'd2)
    );

// R-type sub maps to IF code 3.
    check_rtype_sub: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100010)) |-> (IF == 8'd3)
    );

// R-type subu maps to IF code 4.
    check_rtype_subu: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100011)) |-> (IF == 8'd4)
    );

// R-type and maps to IF code 5.
    check_rtype_and: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100100)) |-> (IF == 8'd5)
    );

// R-type or maps to IF code 6.
    check_rtype_or: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100101)) |-> (IF == 8'd6)
    );

// R-type xor maps to IF code 7.
    check_rtype_xor: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100110)) |-> (IF == 8'd7)
    );

// R-type nor maps to IF code 8.
    check_rtype_nor: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b100111)) |-> (IF == 8'd8)
    );

// R-type slt maps to IF code 9.
    check_rtype_slt: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b101010)) |-> (IF == 8'd9)
    );

// R-type sltu maps to IF code 10.
    check_rtype_sltu: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b101011)) |-> (IF == 8'd10)
    );

// R-type sll maps to IF code 11.
    check_rtype_sll: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b000000)) |-> (IF == 8'd11)
    );

// R-type srl maps to IF code 12.
    check_rtype_srl: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b000010)) |-> (IF == 8'd12)
    );

// R-type sra maps to IF code 13.
    check_rtype_sra: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b000011)) |-> (IF == 8'd13)
    );

// R-type sllv maps to IF code 14.
    check_rtype_sllv: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b000100)) |-> (IF == 8'd14)
    );

// R-type srlv maps to IF code 15.
    check_rtype_srlv: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b000110)) |-> (IF == 8'd15)
    );

// R-type srav maps to IF code 16.
    check_rtype_srav: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b000111)) |-> (IF == 8'd16)
    );

// R-type jr maps to IF code 17.
    check_rtype_jr: assert property (
        @(posedge CCLK) disable iff (rst)
        ((instr[31:26] == 6'b000000) &&
         (instr[5:0] == 6'b001000)) |-> (IF == 8'd17)
    );

// addi maps to IF code 18.
    check_opcode_addi: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001000) |-> (IF == 8'd18)
    );

// addiu maps to IF code 19.
    check_opcode_addiu: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001001) |-> (IF == 8'd19)
    );

// andi maps to IF code 20.
    check_opcode_andi: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001100) |-> (IF == 8'd20)
    );

// ori maps to IF code 15.
    check_opcode_ori: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001101) |-> (IF == 8'd15)
    );

// xori maps to IF code 22.
    check_opcode_xori: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001110) |-> (IF == 8'd22)
    );

// lui maps to IF code 23.
    check_opcode_lui: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001111) |-> (IF == 8'd23)
    );

// lw maps to IF code 24.
    check_opcode_lw: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b100011) |-> (IF == 8'd24)
    );

// sw maps to IF code 25.
    check_opcode_sw: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b101011) |-> (IF == 8'd25)
    );

// beq maps to IF code 26.
    check_opcode_beq: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b000100) |-> (IF == 8'd26)
    );

// bne maps to IF code 27.
    check_opcode_bne: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b000101) |-> (IF == 8'd27)
    );

// slti maps to IF code 28.
    check_opcode_slti: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001010) |-> (IF == 8'd28)
    );

// sltiu maps to IF code 29.
    check_opcode_sltiu: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b001011) |-> (IF == 8'd29)
    );

// j maps to IF code 30.
    check_opcode_j: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b000010) |-> (IF == 8'd30)
    );

// jal maps to IF code 31.
    check_opcode_jal: assert property (
        @(posedge CCLK) disable iff (rst)
        (instr[31:26] == 6'b000011) |-> (IF == 8'd31)
    );

// Result must match the selected shift or passthrough behavior.
    check_result_function: assert property (
        @(posedge clk)
        result == (shift_left ? (A << B) : (shift_right ? (A >> B) : A))
    );

// shift_left selects the left-shifted value.
    check_left_shift_result: assert property (
        @(posedge clk)
        shift_left |-> (result == (A << B))
    );

// shift_right selects the right-shifted value when shift_left is low.
    check_right_shift_result: assert property (
        @(posedge clk)
        (!shift_left && shift_right) |-> (result == (A >> B))
    );

// With no shift request, result passes A through unchanged.
    check_passthrough_result: assert property (
        @(posedge clk)
        (!shift_left && !shift_right) |-> (result == A)
    );

// If both controls are high, shift_left has priority over shift_right.
    check_left_priority: assert property (
        @(posedge clk)
        (shift_left && shift_right) |-> (result == (A << B))
    );

// On sel rising, the sampled output matches the mux function.
    check_out_matches_mux_on_sel_rise: assert property (
        @(posedge sel) out === (sel ? in1 : in0)
    );

// On sel falling, the sampled output matches the mux function.
    check_out_matches_mux_on_sel_fall: assert property (
        @(negedge sel) out === (sel ? in1 : in0)
    );

// On in0 rising, the sampled output matches the mux function.
    check_out_matches_mux_on_in0_rise: assert property (
        @(posedge in0) out === (sel ? in1 : in0)
    );

// On in0 falling, the sampled output matches the mux function.
    check_out_matches_mux_on_in0_fall: assert property (
        @(negedge in0) out === (sel ? in1 : in0)
    );

// On in1 rising, the sampled output matches the mux function.
    check_out_matches_mux_on_in1_rise: assert property (
        @(posedge in1) out === (sel ? in1 : in0)
    );

// On in1 falling, the sampled output matches the mux function.
    check_out_matches_mux_on_in1_fall: assert property (
        @(negedge in1) out === (sel ? in1 : in0)
    );

// External sampling clock; the DUT RTL is combinational and has no reset.

    // Y matches the OR of the two NOR terms.
    check_y_matches_or_of_nors: assert property (
        @(posedge clk) Y == ((~(A3 | A1 | A2)) | (~(B1 | B2)))
    );

// If the A-group inputs are all low, Y must be high.
    check_a_group_all_low_forces_y_high: assert property (
        @(posedge clk) (!(A3 | A1 | A2)) |-> Y
    );

// If the B-group inputs are all low, Y must be high.
    check_b_group_all_low_forces_y_high: assert property (
        @(posedge clk) (!(B1 | B2)) |-> Y
    );

// If both input groups are active, Y must be low.
    check_both_groups_active_force_y_low: assert property (
        @(posedge clk) ((A3 | A1 | A2) && (B1 | B2)) |-> !Y
    );

// A low Y requires at least one A-group input high.
    check_y_low_implies_a_group_active: assert property (
        @(posedge clk) (!Y) |-> (A3 | A1 | A2)
    );

// A low Y requires at least one B-group input high.
    check_y_low_implies_b_group_active: assert property (
        @(posedge clk) (!Y) |-> (B1 | B2)
    );

// If Y is high while the A-group is active, the B-group must be all low.
    check_y_high_with_a_group_active_implies_b_group_low: assert property (
        @(posedge clk) (Y && (A3 | A1 | A2)) |-> !(B1 | B2)
    );

// If Y is high while the B-group is active, the A-group must be all low.
    check_y_high_with_b_group_active_implies_a_group_low: assert property (
        @(posedge clk) (Y && (B1 | B2)) |-> !(A3 | A1 | A2)
    );

// Full output must match the 17-bit addition of the inputs.
    check_full_add_result: assert property (
        @(posedge clk)
        {carry_out, sum} == ({1'b0, operand1} + {1'b0, operand2} + {16'b0, carry_in})
    );

// sum must equal the lower 16 bits of the addition result.
    check_sum_lower_bits: assert property (
        @(posedge clk)
        {1'b0, sum} == (({1'b0, operand1} + {1'b0, operand2} + {16'b0, carry_in}) & 17'h0_FFFF)
    );

// carry_out must equal the overflow bit of the addition result.
    check_carry_out_overflow: assert property (
        @(posedge clk)
        carry_out == (({1'b0, operand1} + {1'b0, operand2} + {16'b0, carry_in}) > 17'h0_FFFF)
    );

// Output must always match the mux expression.
    check_mux_function: assert property (
        @(posedge clk) (y === (sel ? b : a))
    );

// When select is low, output must follow input a.
    check_select_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (y === a)
    );

// When select is high, output must follow input b.
    check_select_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (y === b)
    );

// A rising select must make the output reflect input b.
    check_sel_rise_switches_to_b: assert property (
        @(posedge clk) $rose(sel) |-> (y === b)
    );

// A falling select must make the output reflect input a.
    check_sel_fall_switches_to_a: assert property (
        @(posedge clk) $fell(sel) |-> (y === a)
    );

// With C low, no carry path is active and Y is A XOR B.
    check_xor_mode: assert property (
        @(posedge clk) (!C) |-> (Y == (A ^ B))
    );

// With B at zero, all output bits pass through A.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'b0000) |-> (Y == A)
    );

// Bit 0 follows the implemented XOR and carry-out equation.
    check_bit0_equation: assert property (
        @(posedge clk) Y[0] == (A[0] ^ B[0] ^ (C & B[0]))
    );

// Bit 1 uses a carry term only when C is high and A[0] is low.
    check_bit1_equation: assert property (
        @(posedge clk) Y[1] == (A[1] ^ B[1] ^ (C & (~A[0]) & B[1]))
    );

// Bit 2 uses a carry term only when C is high and A[1:0] are low.
    check_bit2_equation: assert property (
        @(posedge clk) Y[2] == (A[2] ^ B[2] ^ (C & (~A[1]) & (~A[0]) & B[2]))
    );

// Bit 3 uses a carry term only when C is high and A[2:0] are low.
    check_bit3_equation: assert property (
        @(posedge clk) Y[3] == (A[3] ^ B[3] ^ (C & (~A[2]) & (~A[1]) & (~A[0]) & B[3]))
    );

// When C is high, bit 0 always collapses to A[0].
    check_c_mode_bit0_passthrough: assert property (
        @(posedge clk) C |-> (Y[0] == A[0])
    );

// When C is high and A[0] is low, bit 1 collapses to A[1].
    check_c_mode_bit1_passthrough: assert property (
        @(posedge clk) (C && (A[0] == 1'b0)) |-> (Y[1] == A[1])
    );

// When C is high and A[1:0] are low, bit 2 collapses to A[2].
    check_c_mode_bit2_passthrough: assert property (
        @(posedge clk) (C && (A[1:0] == 2'b00)) |-> (Y[2] == A[2])
    );

// When C is high and A[2:0] are low, bit 3 collapses to A[3].
    check_c_mode_bit3_passthrough: assert property (
        @(posedge clk) (C && (A[2:0] == 3'b000)) |-> (Y[3] == A[3])
    );

// SELECT F routes IN16 to OUT.
    check_select_f_routes_in16: assert property (
        @(posedge clk) (SELECT == 4'hF) |-> (OUT == IN16)
    );

// Y must match the RTL mux expression on every sampled cycle.
    check_mux_expression: assert property (
        @(posedge clk)
        Y == ((S1 & S0) ? D : ((S1 & ~S0) ? C : (((~S1) & S0) ? B : A)))
    );

// Select 00 routes A to Y.
    check_select_00_routes_A: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == A)
    );

// Select 01 routes B to Y.
    check_select_01_routes_B: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Y == B)
    );

// Select 10 routes C to Y.
    check_select_10_routes_C: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Y == C)
    );

// Select 11 routes D to Y.
    check_select_11_routes_D: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Y == D)
    );

// OP=00 selects the AND result.
    check_and_select: assert property (
        @(posedge clk) (OP == 2'b00) |-> (Y == (A & B))
    );

// OP=01 selects the OR result.
    check_or_select: assert property (
        @(posedge clk) (OP == 2'b01) |-> (Y == (A | B))
    );

// OP=10 selects the XOR result.
    check_xor_select: assert property (
        @(posedge clk) (OP == 2'b10) |-> (Y == (A ^ B))
    );

// OP=11 selects the inversion of A.
    check_not_select: assert property (
        @(posedge clk) (OP == 2'b11) |-> (Y == (~A))
    );

// Y always matches the function selected by OP.
    check_selected_function: assert property (
        @(posedge clk)
        Y == ((OP == 2'b00) ? (A & B) :
              (OP == 2'b01) ? (A | B) :
              (OP == 2'b10) ? (A ^ B) :
                              (~A))
    );

// Reset forces the state register to S0.
    check_reset_forces_state_s0: assert property (
        @(posedge clk_i) !reset_n |-> (state == S0)
    );

// Reset drives sel to the S0 decode value.
    check_reset_drives_sel_s0: assert property (
        @(posedge clk_i) !reset_n |-> (sel == 3'b000)
    );

// sel only takes one of the implemented decode values.
    check_sel_legal_values: assert property (
        @(posedge clk_i) disable iff (!reset_n)
        (sel == 3'b000) || (sel == 3'b001) || (sel == 3'b011) || (sel == 3'b100)
    );

// clkout stays inverted relative to clkin on rising input edges.
    check_clkout_inverts_clkin_on_rise: assert property (
        @(posedge clkin) clkout == ~clkin
    );

// clkout stays inverted relative to clkin on falling input edges.
    check_clkout_inverts_clkin_on_fall: assert property (
        @(negedge clkin) clkout == ~clkin
    );

// No RTL clock or reset; clk is only for assertion sampling.

    // o0 directly reflects in_vec[0].
    check_o0_pass_through: assert property (
        @(posedge clk) o0 == in_vec[0]
    );

// o1 directly reflects in_vec[1].
    check_o1_pass_through: assert property (
        @(posedge clk) o1 == in_vec[1]
    );

// o2 directly reflects in_vec[2].
    check_o2_pass_through: assert property (
        @(posedge clk) o2 == in_vec[2]
    );

// With sel low, out_vec matches in_vec.
    check_out_vec_sel_low: assert property (
        @(posedge clk) !sel |-> (out_vec == in_vec)
    );

// With sel high, out_vec preserves bit 2 and ORs adjacent lower bits.
    check_out_vec_sel_high: assert property (
        @(posedge clk) sel |-> (out_vec == {in_vec[2], (in_vec[2] | in_vec[1]), (in_vec[1] | in_vec[0])})
    );

// X implements A & B & C.
    check_x_matches_and3: assert property (
        @(posedge clk) X == (A & B & C)
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// All three inputs high drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C) |-> X
    );

// X high requires all three inputs high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A & B & C)
    );

// With B and C high, X follows A.
    check_x_follows_a_when_bc_high: assert property (
        @(posedge clk) (B & C) |-> (X == A)
    );

// With A and C high, X follows B.
    check_x_follows_b_when_ac_high: assert property (
        @(posedge clk) (A & C) |-> (X == B)
    );

// With A and B high, X follows C.
    check_x_follows_c_when_ab_high: assert property (
        @(posedge clk) (A & B) |-> (X == C)
    );

// reset is active high and is the only edge-triggered signal.
    // out_alwaysblock is combinational; out_assign only updates on posedge reset.

    // out_alwaysblock selects in0 when sel is 2'b00.
    check_out_alwaysblock_sel_00: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b00) |-> (out_alwaysblock == in0)
    );

// out_alwaysblock selects in1 when sel is 2'b01.
    check_out_alwaysblock_sel_01: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b01) |-> (out_alwaysblock == in1)
    );

// out_alwaysblock selects in2 when sel is 2'b10.
    check_out_alwaysblock_sel_10: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b10) |-> (out_alwaysblock == in2)
    );

// out_alwaysblock selects in3 when sel is 2'b11.
    check_out_alwaysblock_sel_11: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b11) |-> (out_alwaysblock == in3)
    );

// out_alwaysblock drives zero on the case default branch.
    check_out_alwaysblock_default: assert property (
        @(negedge reset) disable iff (reset)
        ((sel[1] !== 1'b0) && (sel[1] !== 1'b1)) |-> (out_alwaysblock == 4'b0000)
    );

// After a prior reset assertion, out_assign is cleared to zero.
    check_out_assign_cleared_by_reset: assert property (
        @(negedge reset) disable iff (reset)
        !$isunknown($past(reset, 1, 1'b1, @(posedge reset))) |-> (out_assign == 4'b0000)
    );

// Column 1110 drives row 1110 on the following cycle.
    check_row_for_col_1110: assert property (
        @(posedge clk) (col == 4'b1110) |=> (row == 4'b1110)
    );

// Column 1101 drives row 1101 on the following cycle.
    check_row_for_col_1101: assert property (
        @(posedge clk) (col == 4'b1101) |=> (row == 4'b1101)
    );

// Column 1011 drives row 1011 on the following cycle.
    check_row_for_col_1011: assert property (
        @(posedge clk) (col == 4'b1011) |=> (row == 4'b1011)
    );

// Column 0111 drives row 0111 on the following cycle.
    check_row_for_col_0111: assert property (
        @(posedge clk) (col == 4'b0111) |=> (row == 4'b0111)
    );

// Any non-matching column value drives row to 0000 on the following cycle.
    check_row_default_for_other_cols: assert property (
        @(posedge clk)
        !((col == 4'b1110) ||
          (col == 4'b1101) ||
          (col == 4'b1011) ||
          (col == 4'b0111)) |=> (row == 4'b0000)
    );

// Row only takes values produced by the case statement.
    check_row_legal_values: assert property (
        @(posedge clk) 1'b1 |=> (
            (row == 4'b1110) ||
            (row == 4'b1101) ||
            (row == 4'b1011) ||
            (row == 4'b0111) ||
            (row == 4'b0000)
        )
    );

// A greater than B drives only GTO high.
    check_gt_case_outputs: assert property (
        @(posedge clk) (A > B) |-> ((GTO == 1'b1) && (LTO == 1'b0) && (EQO == 1'b0))
    );

// A less than B drives only LTO high.
    check_lt_case_outputs: assert property (
        @(posedge clk) (A < B) |-> ((GTO == 1'b0) && (LTO == 1'b1) && (EQO == 1'b0))
    );

// Equal inputs pass GTI through to GTO.
    check_eq_case_gto_passthrough: assert property (
        @(posedge clk) (A == B) |-> (GTO == GTI)
    );

// Equal inputs pass LTI through to LTO.
    check_eq_case_lto_passthrough: assert property (
        @(posedge clk) (A == B) |-> (LTO == LTI)
    );

// Equal inputs pass EQI through to EQO.
    check_eq_case_eqo_passthrough: assert property (
        @(posedge clk) (A == B) |-> (EQO == EQI)
    );

// No RTL reset exists; assertions are always active.
    // Y must match the RTL's full combinational expression.
    check_y_matches_rtl_expr: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((A1_N & A2_N) ? (B1 | B2) :
              (A1_N & ~A2_N) ? B1 :
              (~A1_N & A2_N) ? B2 : 1'b0)
    );

// When both select inputs are high, Y is B1 OR B2.
    check_or_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N && A2_N) |-> (Y == (B1 | B2))
    );

// When only A1_N is high, Y follows B1.
    check_b1_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N && !A2_N) |-> (Y == B1)
    );

// When only A2_N is high, Y follows B2.
    check_b2_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1_N && A2_N) |-> (Y == B2)
    );

// When both select inputs are low, Y is forced low.
    check_no_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1_N && !A2_N) |-> (Y == 1'b0)
    );

// In add mode, spr_out must equal rs1_data plus rs2_data.
    check_add_mode_result: assert property (
        @(posedge clk) cin |-> (spr_out == (rs1_data + rs2_data))
    );

// In subtract mode, spr_out must equal rs1_data minus rs2_data.
    check_sub_mode_result: assert property (
        @(posedge clk) !cin |-> (spr_out == (rs1_data - rs2_data))
    );

// Subtracting equal operands must produce zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (!cin && (rs1_data == rs2_data)) |-> (spr_out == 64'd0)
    );

// In add mode, adding zero on rs2_data must pass rs1_data through.
    check_add_zero_right_identity: assert property (
        @(posedge clk) (cin && (rs2_data == 64'd0)) |-> (spr_out == rs1_data)
    );

// In subtract mode, subtracting zero on rs2_data must pass rs1_data through.
    check_sub_zero_right_identity: assert property (
        @(posedge clk) (!cin && (rs2_data == 64'd0)) |-> (spr_out == rs1_data)
    );

// Active-low reset clears both outputs.
    reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> ((out_port == 4'h0) && (readdata == 32'h0))
    );

// A selected write to address 0 loads the low nibble into out_port.
    write_addr0_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[3:0]))
    );

// With chipselect low, out_port holds its previous value.
    no_chipselect_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!chipselect) |=> (out_port == $past(out_port))
    );

// When selected but not writing, out_port holds its previous value.
    write_high_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && write_n) |=> (out_port == $past(out_port))
    );

// Writes to nonzero addresses do not change out_port.
    write_nonzero_addr_ignored: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

// Address 0 returns out_port in the low nibble.
    read_addr0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {28'h0, out_port})
    );

// Nonzero addresses return zero on readdata.
    read_nonzero_addr_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'h0)
    );

// readdata upper bits are always zero.
    readdata_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:4] == 28'h0)
    );

// shift_amount 00 passes data through unchanged.
    check_shift_0_passthrough: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (result == data)
    );

// shift_amount 01 shifts left by 1 with zero fill.
    check_shift_1_left_by_1: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

// shift_amount 10 shifts left by 2 with zero fill.
    check_shift_2_left_by_2: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

// shift_amount 11 shifts left by 3 with zero fill.
    check_shift_3_left_by_3: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (result == {data[0], 3'b000})
    );

// Exact input match drives EQ high and GT low.
    check_equal_case: assert property (
        @(posedge clk) ((A == B) && (C == D)) |-> ((EQ == 1'b1) && (GT == 1'b0))
    );

// A greater than B drives GT high and EQ low.
    check_gt_a_greater: assert property (
        @(posedge clk) (A > B) |-> ((EQ == 1'b0) && (GT == 1'b1))
    );

// With A tied to B, C greater than D drives GT high and EQ low.
    check_gt_tiebreak_case: assert property (
        @(posedge clk) ((A == B) && (C > D)) |-> ((EQ == 1'b0) && (GT == 1'b1))
    );

// Lexicographically smaller inputs drive both outputs low.
    check_less_than_case: assert property (
        @(posedge clk) ((A < B) || ((A == B) && (C < D))) |-> ((EQ == 1'b0) && (GT == 1'b0))
    );

// EQ can only be high on an exact match.
    check_eq_only_on_exact_match: assert property (
        @(posedge clk) (EQ == 1'b1) |-> ((A == B) && (C == D))
    );

// GT can only be high on a lexicographic greater-than result.
    check_gt_only_on_greater_than: assert property (
        @(posedge clk) (GT == 1'b1) |-> ((A > B) || ((A == B) && (C > D)))
    );

// Both outputs low means the inputs are lexicographically smaller.
    check_zero_outputs_mean_less_than: assert property (
        @(posedge clk) ((EQ == 1'b0) && (GT == 1'b0)) |-> ((A < B) || ((A == B) && (C < D)))
    );

// EQ and GT are never asserted together.
    check_output_mutex: assert property (
        @(posedge clk) !((EQ == 1'b1) && (GT == 1'b1))
    );

// Output matches the implemented conversion function.
    check_full_mapping: assert property (
        @(posedge clk)
        twos_comp == (signed_mag[3] ? ((~signed_mag) + 4'b0001) : signed_mag)
    );

// Non-negative inputs pass through unchanged.
    check_nonnegative_passthrough: assert property (
        @(posedge clk)
        !signed_mag[3] |-> (twos_comp == signed_mag)
    );

// Negative inputs use bitwise invert plus one on all four bits.
    check_negative_invert_plus_one: assert property (
        @(posedge clk)
        signed_mag[3] |-> (twos_comp == ((~signed_mag) + 4'b0001))
    );

// Clock: clk
    // Reset: reset, active high asynchronous

    // A sampled reset must leave the counter at zero by the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (Q == 4'b0000)
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (Q == $past(Q))
    );

// When enabled below 15, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable && (Q != 4'hF) |=> (Q == ($past(Q) + 4'd1))
    );

// When enabled at 15, the counter wraps to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (Q == 4'hF) |=> (Q == 4'h0)
    );

// Synchronous active-high reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk)
        reset |=> (count == 4'b0000)
    );

// When enabled below 15, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at 15, the counter wraps to zero.
    check_enable_wraps_count: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'hF) |=> (count == 4'h0)
    );

// When not enabled, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Y matches the implemented combinational equation.
    check_y_equation: assert property (
        @(posedge clk) Y == ((~A1 | ~A2 | ~A3) & B1)
    );

// Y must be low whenever B1 is low.
    check_y_low_when_b1_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// Y must be low when all A inputs are high.
    check_y_low_when_all_a_high: assert property (
        @(posedge clk) (A1 && A2 && A3) |-> !Y
    );

// Y must be high when B1 is high and any A input is low.
    check_y_high_when_b1_high_and_any_a_low: assert property (
        @(posedge clk) (B1 && (!A1 || !A2 || !A3)) |-> Y
    );

// A high Y requires B1 to be high.
    check_y_implies_b1_high: assert property (
        @(posedge clk) Y |-> B1
    );

// A high Y requires at least one A input to be low.
    check_y_implies_any_a_low: assert property (
        @(posedge clk) Y |-> (!A1 || !A2 || !A3)
    );

// q[1] captures d on the next sampled clock.
    check_q1_captures_d: assert property (
        @(posedge clk) 1'b1 |=> (q[1] == $past(d))
    );

// q[0] captures the previous value of q[1].
    check_q0_captures_q1: assert property (
        @(posedge clk) 1'b1 |=> (q[0] == $past(q[1]))
    );

// q[0] is d delayed by two clock cycles.
    check_q0_two_cycle_delay_of_d: assert property (
        @(posedge clk) 1'b1 |=> ##1 (q[0] == $past(d, 2))
    );

// q holds the two most recent sampled values of d.
    check_q_is_two_stage_shift_of_d: assert property (
        @(posedge clk) 1'b1 |=> ##1 (q == { $past(d), $past(d, 2) })
    );

// When SET and CLR are both high, SET has priority and Q becomes 1.
    check_set_priority_over_clear: assert property (
        @(posedge CLK) (SET && CLR) |=> (Q == 1'b1)
    );

// When only SET is high, Q becomes 1.
    check_set_drives_q_high: assert property (
        @(posedge CLK) (SET && !CLR) |=> (Q == 1'b1)
    );

// When SET is low and CLR is high, Q becomes 0.
    check_clear_drives_q_low: assert property (
        @(posedge CLK) (!SET && CLR) |=> (Q == 1'b0)
    );

// When SET and CLR are low, D=1 is captured into Q.
    check_capture_data_one: assert property (
        @(posedge CLK) (!SET && !CLR && D) |=> (Q == 1'b1)
    );

// When SET and CLR are low, D=0 is captured into Q.
    check_capture_data_zero: assert property (
        @(posedge CLK) (!SET && !CLR && !D) |=> (Q == 1'b0)
    );

// Reset drives the output to zero by the next sampled clock.
    check_reset_clears_out_next: assert property (
        @(posedge clk) !rst |=> (out_data == 16'h0000)
    );

// While reset stays asserted, the output remains zero.
    check_reset_holds_out_zero: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (out_data == 16'h0000)
    );

// Each active clock loads input plus 16'h1234 into the output register.
    check_active_cycle_updates_sum: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (out_data == ($past(in_data) + 16'h1234))
    );

// The first active cycle after reset release also loads the sum correctly.
    check_reset_release_updates_sum: assert property (
        @(posedge clk) disable iff (!rst) !$past(rst) |=> (out_data == ($past(in_data) + 16'h1234))
    );

// Zero input produces 16'h1234 on the next sampled clock.
    check_zero_input_case: assert property (
        @(posedge clk) disable iff (!rst) (in_data == 16'h0000) |=> (out_data == 16'h1234)
    );

// Max input wraps around to 16'h1233 on the next sampled clock.
    check_max_input_wraparound: assert property (
        @(posedge clk) disable iff (!rst) (in_data == 16'hFFFF) |=> (out_data == 16'h1233)
    );

// p_out implements p AND p_prec.
    check_p_out_and_function: assert property (
        @(posedge clk) p_out == (p & p_prec)
    );

// g_out_BAR implements NOR of g_prec and p.
    check_g_out_bar_nor_function: assert property (
        @(posedge clk) g_out_BAR == ~(g_prec | p)
    );

// p_out can only be high when both inputs are high.
    check_p_out_high_requires_inputs_high: assert property (
        @(posedge clk) p_out |-> (p && p_prec)
    );

// p_out must be low if either input is low.
    check_p_out_low_when_any_input_low: assert property (
        @(posedge clk) (!p || !p_prec) |-> !p_out
    );

// g_out_BAR can only be high when both NOR inputs are low.
    check_g_out_bar_high_requires_inputs_low: assert property (
        @(posedge clk) g_out_BAR |-> (!g_prec && !p)
    );

// g_out_BAR must be low if either NOR input is high.
    check_g_out_bar_low_when_any_input_high: assert property (
        @(posedge clk) (g_prec || p) |-> !g_out_BAR
    );

// A high p_out forces g_out_BAR low because p must be high.
    check_p_out_implies_g_out_bar_low: assert property (
        @(posedge clk) p_out |-> !g_out_BAR
    );

// A low reset drives q low by the next clock sample.
    check_reset_clears_q: assert property (
        @(posedge clk)
        !rst |=> (q == 1'b0)
    );

// Set drives q high on the next cycle.
    check_set_loads_high: assert property (
        @(posedge clk) disable iff (!rst)
        set |=> (q == 1'b1)
    );

// Clear drives q low when set is not asserted.
    check_clear_loads_low: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && clr) |=> (q == 1'b0)
    );

// Data value 1 is loaded when set and clear are both low.
    check_data_one_loads_high: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && !clr && d) |=> (q == 1'b1)
    );

// Data value 0 is loaded when set and clear are both low.
    check_data_zero_loads_low: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && !clr && !d) |=> (q == 1'b0)
    );

// Set has priority over clear when both are asserted.
    check_set_priority_over_clear: assert property (
        @(posedge clk) disable iff (!rst)
        (set && clr) |=> (q == 1'b1)
    );

// Output must equal the NOR of the inputs.
    check_nor_function: assert property (
        @(posedge clk) z === ~(a | b)
    );

// z must be HIGH when both inputs are LOW.
    check_z_high_when_both_low: assert property (
        @(posedge clk) ((a === 1'b0) && (b === 1'b0)) |-> (z === 1'b1)
    );

// z must be LOW whenever a is HIGH.
    check_z_low_when_a_high: assert property (
        @(posedge clk) (a === 1'b1) |-> (z === 1'b0)
    );

// z must be LOW whenever b is HIGH.
    check_z_low_when_b_high: assert property (
        @(posedge clk) (b === 1'b1) |-> (z === 1'b0)
    );

// A HIGH output implies both inputs are LOW.
    check_z_high_implies_both_low: assert property (
        @(posedge clk) (z === 1'b1) |-> ((a === 1'b0) && (b === 1'b0))
    );

// Synchronous reset drives the state to IDLE.
    check_reset_forces_idle: assert property (
        @(posedge clk) reset |=> (estado_atual == IDLE)
    );

// LED captures the previous cycle's infrared sample.
    check_led_samples_infrared: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (led == $past(infrared))
    );

// Button outputs are never asserted.
    check_buttons_always_low: assert property (
        @(posedge clk) disable iff (reset)
        (botao_1 == 1'b0 && botao_2 == 1'b0 && botao_3 == 1'b0 && botao_4 == 1'b0)
    );

// output_1 must equal the AND of input_1 and input_2.
    check_output_1_and: assert property (
        @(posedge clk) output_1 == (input_1 & input_2)
    );

// output_2 must equal the OR of input_3 and input_4.
    check_output_2_or: assert property (
        @(posedge clk) output_2 == (input_3 | input_4)
    );

// Y must match the implemented sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ((A1 & B1 & C1) | (A2 & B2 & C1))
    );

// C1 low forces Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk)
        !C1 |-> !Y
    );

// The A1/B1 path is sufficient to drive Y high.
    check_first_product_term_drives_y: assert property (
        @(posedge clk)
        (A1 & B1 & C1) |-> Y
    );

// The A2/B2 path is sufficient to drive Y high.
    check_second_product_term_drives_y: assert property (
        @(posedge clk)
        (A2 & B2 & C1) |-> Y
    );

// Y high requires C1 to be high.
    check_y_implies_c1_high: assert property (
        @(posedge clk)
        Y |-> C1
    );

// Y high requires at least one input pair product to be true.
    check_y_implies_product_term: assert property (
        @(posedge clk)
        Y |-> ((A1 & B1) | (A2 & B2))
    );

// Outputs encode the 2-bit sum of A, B, and CIN.
    check_full_adder_encoding: assert property (
        @(posedge clk) {1'b0, COUT, SUM} == ({2'b00, A} + {2'b00, B} + {2'b00, CIN})
    );

// Carry-out is high when at least two inputs are high.
    check_cout_majority: assert property (
        @(posedge clk) COUT == ((A & B) | (A & CIN) | (B & CIN))
    );

// Sum is the odd parity of the three inputs.
    check_sum_odd_parity: assert property (
        @(posedge clk) SUM == (A ^ B ^ CIN)
    );

// All-low inputs produce zero carry and zero sum.
    check_zero_input_case: assert property (
        @(posedge clk) (!A && !B && !CIN) |-> (!COUT && !SUM)
    );

// Exactly one high input produces sum without carry.
    check_single_one_case: assert property (
        @(posedge clk)
        ((A && !B && !CIN) || (!A && B && !CIN) || (!A && !B && CIN)) |-> (!COUT && SUM)
    );

// Exactly two high inputs produce carry without sum.
    check_double_one_case: assert property (
        @(posedge clk)
        ((A && B && !CIN) || (A && !B && CIN) || (!A && B && CIN)) |-> (COUT && !SUM)
    );

// All-high inputs produce both carry and sum.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CIN) |-> (COUT && SUM)
    );

// Clock: CLK; reset: none.
    // ENCLK is a latch output that is transparent while CLK is high.

    // In test mode, ENCLK is forced high by the end of the CLK-high phase.
    check_test_mode_forces_high: assert property (
        @(negedge CLK) TE |-> (ENCLK == 1'b1)
    );

// In normal mode, ENCLK matches EN by the end of the CLK-high phase.
    check_normal_mode_passes_enable: assert property (
        @(negedge CLK) !TE |-> (ENCLK == EN)
    );

// At the end of the transparent phase, ENCLK equals the implemented latch function.
    check_latch_function: assert property (
        @(negedge CLK) ENCLK == (TE ? 1'b1 : EN)
    );

// X must match the implemented sum-of-products function.
    check_x_matches_logic_function: assert property (
        @(posedge clk)
        X == ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// An asserted A input pair must drive X high.
    check_a_term_sets_x: assert property (
        @(posedge clk)
        (A1 && A2) |-> X
    );

// An asserted B input pair must drive X high.
    check_b_term_sets_x: assert property (
        @(posedge clk)
        (B1 && B2) |-> X
    );

// An asserted C input pair must drive X high.
    check_c_term_sets_x: assert property (
        @(posedge clk)
        (C1 && C2) |-> X
    );

// If no input pair is fully asserted, X must be low.
    check_no_terms_clear_x: assert property (
        @(posedge clk)
        !((A1 && A2) || (B1 && B2) || (C1 && C2)) |-> !X
    );

// If X is high with B and C terms inactive, the A term must be active.
    check_x_high_with_only_a_path: assert property (
        @(posedge clk)
        X && !(B1 && B2) && !(C1 && C2) |-> (A1 && A2)
    );

// If X is high with A and C terms inactive, the B term must be active.
    check_x_high_with_only_b_path: assert property (
        @(posedge clk)
        X && !(A1 && A2) && !(C1 && C2) |-> (B1 && B2)
    );

// If X is high with A and B terms inactive, the C term must be active.
    check_x_high_with_only_c_path: assert property (
        @(posedge clk)
        X && !(A1 && A2) && !(B1 && B2) |-> (C1 && C2)
    );

// Q follows the RTL next-state function across clock edges.
    check_next_state_function: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> Q == ($past(DE) ? $past(D) : ($past(SCE) ? $past(SCD) : $past(Q)))
    );

// Q captures D when only DE is asserted.
    check_capture_d_when_de_only: assert property (
        @(posedge CLK) disable iff (1'b0)
        (DE && !SCE) |=> Q == $past(D)
    );

// DE has priority over SCE when both enables are asserted.
    check_de_priority_over_sce: assert property (
        @(posedge CLK) disable iff (1'b0)
        (DE && SCE) |=> Q == $past(D)
    );

// Q captures SCD when scan enable is asserted without DE.
    check_capture_scd_when_sce_only: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!DE && SCE) |=> Q == $past(SCD)
    );

// Q holds its value when neither enable is asserted.
    check_hold_when_no_enable: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!DE && !SCE) |=> Q == $past(Q)
    );

// Q can only change after a clock edge with DE or SCE asserted.
    check_change_requires_enable: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (!$changed(Q) || ($past(DE) || $past(SCE)))
    );

// Sum bits are the bitwise XOR of A and B.
    check_sum_matches_xor: assert property (
        @(posedge clk) S === (A ^ B)
    );

// Cout matches the OR of both half-adder carries and Cin.
    check_cout_matches_or_of_carries_and_cin: assert property (
        @(posedge clk) Cout === ((A[0] & B[0]) | (A[1] & B[1]) | Cin)
    );

// A carry generated on bit 0 must drive Cout high.
    check_lower_carry_forces_cout: assert property (
        @(posedge clk) (A[0] & B[0]) |-> Cout
    );

// A carry generated on bit 1 must drive Cout high.
    check_upper_carry_forces_cout: assert property (
        @(posedge clk) (A[1] & B[1]) |-> Cout
    );

// With no carry sources active, Cout must be low.
    check_no_carry_sources_clear_cout: assert property (
        @(posedge clk) (!Cin && !(A[0] & B[0]) && !(A[1] & B[1])) |-> !Cout
    );

// Y must implement A & B & ~C.
    check_y_function: assert property (
        @(posedge clk) Y === (A & B & ~C)
    );

// When A, B, and ~C are true, Y must be high.
    check_y_high_when_inputs_match: assert property (
        @(posedge clk) (A & B & ~C) |-> (Y === 1'b1)
    );

// A low forces Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b0)
    );

// B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (B === 1'b0) |-> (Y === 1'b0)
    );

// C high forces Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) (C === 1'b1) |-> (Y === 1'b0)
    );

// Y high implies A and B are high and C is low.
    check_y_high_implies_inputs_match: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A === 1'b1) && (B === 1'b1) && (C === 1'b0))
    );

// Y must follow A when SEL is low.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (Y == A)
    );

// Y must follow B when SEL is high.
    check_sel_high_routes_b: assert property (
        @(posedge clk) SEL |-> (Y == B)
    );

// Y must always match the mux select equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

// data 2'b00 drives q low.
    check_data_00_drives_q_low: assert property (
        @(posedge clk) (data == 2'b00) |-> (q == 1'b0)
    );

// data 2'b01 drives q low.
    check_data_01_drives_q_low: assert property (
        @(posedge clk) (data == 2'b01) |-> (q == 1'b0)
    );

// data 2'b10 drives q low.
    check_data_10_drives_q_low: assert property (
        @(posedge clk) (data == 2'b10) |-> (q == 1'b0)
    );

// data 2'b11 drives q high.
    check_data_11_drives_q_high: assert property (
        @(posedge clk) (data == 2'b11) |-> (q == 1'b1)
    );

// q can only be high for input 2'b11.
    check_q_high_only_for_data_11: assert property (
        @(posedge clk) (q == 1'b1) |-> (data == 2'b11)
    );

// shift=00 passes the input through unchanged.
    check_shift_00_passthrough: assert property (
        @(posedge clk) (shift == 2'b00) |-> (out == in)
    );

// shift=01 shifts left by one and inserts zero into bit 0.
    check_shift_01_left_by_one: assert property (
        @(posedge clk) (shift == 2'b01) |-> (out == {in[30:0], 1'b0})
    );

// shift=10 shifts right by one and inserts zero into bit 31.
    check_shift_10_right_by_one: assert property (
        @(posedge clk) (shift == 2'b10) |-> (out == {1'b0, in[31:1]})
    );

// shift=11 shifts right by two and inserts zeros into bits 31:30.
    check_shift_11_right_by_two: assert property (
        @(posedge clk) (shift == 2'b11) |-> (out == {2'b00, in[31:2]})
    );

// SUM is the three-input XOR of A, B, and CI.
    check_sum_parity: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT_N matches the OR of the three pairwise NOR terms.
    check_coutn_function: assert property (
        @(posedge clk) COUT_N == (((~A) & (~B)) | ((~A) & (~CI)) | ((~B) & (~CI)))
    );

// All-zero inputs produce SUM low and COUT_N high.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> ((SUM == 1'b0) && (COUT_N == 1'b1))
    );

// Any single high input produces SUM high and COUT_N high.
    check_one_high_case: assert property (
        @(posedge clk)
        (( A && !B && !CI) ||
         (!A &&  B && !CI) ||
         (!A && !B &&  CI)) |-> ((SUM == 1'b1) && (COUT_N == 1'b1))
    );

// Any two high inputs produce SUM low and COUT_N low.
    check_two_high_case: assert property (
        @(posedge clk)
        (( A &&  B && !CI) ||
         ( A && !B &&  CI) ||
         (!A &&  B &&  CI)) |-> ((SUM == 1'b0) && (COUT_N == 1'b0))
    );

// All-high inputs produce SUM high and COUT_N low.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && CI) |-> ((SUM == 1'b1) && (COUT_N == 1'b0))
    );

// RTL has no native clock or reset.
    // clk is only used to sample combinational behavior.

    // out must equal the barrel-shifted version of in0.
    check_out_matches_shift: assert property (
        @(posedge clk) out == (DIR ? (in0 >> AMT) : (in0 << AMT))
    );

// A zero shift amount must pass in0 through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk) (AMT == 2'b00) |-> (out == in0)
    );

// DIR high selects a right shift.
    check_right_shift_behavior: assert property (
        @(posedge clk) DIR |-> (out == (in0 >> AMT))
    );

// DIR low selects a left shift.
    check_left_shift_behavior: assert property (
        @(posedge clk) !DIR |-> (out == (in0 << AMT))
    );

// eq must indicate equality between out and in1.
    check_eq_definition: assert property (
        @(posedge clk) eq == (out == in1)
    );

// gt must indicate out is greater than in1.
    check_gt_definition: assert property (
        @(posedge clk) gt == (out > in1)
    );

// lt must indicate out is less than in1.
    check_lt_definition: assert property (
        @(posedge clk) lt == (out < in1)
    );

// eq cannot be high with gt or lt.
    check_eq_exclusive: assert property (
        @(posedge clk) !(eq && gt) && !(eq && lt)
    );

// gt and lt cannot be high at the same time.
    check_gt_lt_mutex: assert property (
        @(posedge clk) !(gt && lt)
    );

// The comparator must always report one relation.
    check_compare_complete: assert property (
        @(posedge clk) eq || gt || lt
    );

// External sampling clock; the RTL itself has no clock or reset.

    // X must match A0 when the select is 00.
    check_select_a0: assert property (
        @(posedge clk) ({S1, S0} == 2'b00) |-> (X == A0)
    );

// X must match A1 when the select is 01.
    check_select_a1: assert property (
        @(posedge clk) ({S1, S0} == 2'b01) |-> (X == A1)
    );

// X must match A2 when the select is 10.
    check_select_a2: assert property (
        @(posedge clk) ({S1, S0} == 2'b10) |-> (X == A2)
    );

// X must match A3 when the select is 11.
    check_select_a3: assert property (
        @(posedge clk) ({S1, S0} == 2'b11) |-> (X == A3)
    );

// Valid input with ready forwards data on the next cycle.
    check_accept_forwards_data: assert property (
        @(posedge clk) (in_valid && out_ready) |=> (out_valid && !out_error && (out_data == $past(in_data)))
    );

// Valid input without ready raises an error on the next cycle.
    check_stall_sets_error: assert property (
        @(posedge clk) (in_valid && !out_ready) |=> (!out_valid && out_error && (out_data == 16'h0000))
    );

// No valid input clears outputs on the next cycle.
    check_idle_clears_outputs: assert property (
        @(posedge clk) (!in_valid) |=> (!out_valid && !out_error && (out_data == 16'h0000))
    );

// out_valid is high only for a previous-cycle valid and ready handshake.
    check_out_valid_definition: assert property (
        @(posedge clk) 1'b1 |=> (out_valid == ($past(in_valid) && $past(out_ready)))
    );

// out_error is high only for a previous-cycle valid input without ready.
    check_out_error_definition: assert property (
        @(posedge clk) 1'b1 |=> (out_error == ($past(in_valid) && !$past(out_ready)))
    );

// out_data matches the previous input on accept, otherwise it is zero.
    check_out_data_definition: assert property (
        @(posedge clk) 1'b1 |=> (out_data == (($past(in_valid) && $past(out_ready)) ? $past(in_data) : 16'h0000))
    );

// out_valid and out_error are never asserted together.
    check_status_mutex: assert property (
        @(posedge clk) 1'b1 |=> !(out_valid && out_error)
    );

// Some status bit is set iff the previous cycle had a valid input.
    check_status_tracks_in_valid: assert property (
        @(posedge clk) 1'b1 |=> ((out_valid || out_error) == $past(in_valid))
    );

// Y matches the implemented combinational equation.
    check_output_equation: assert property (
        @(posedge clk) Y == ((~(A | B | C)) | D)
    );

// When D is low, Y reduces to the NOR of A, B, and C.
    check_d_low_reduces_to_nor3: assert property (
        @(posedge clk) !D |-> (Y == ~(A | B | C))
    );

// A high D input forces Y high.
    check_d_high_forces_y_high: assert property (
        @(posedge clk) D |-> Y
    );

// With D low, any high input among A, B, or C forces Y low.
    check_abc_high_with_d_low_forces_y_low: assert property (
        @(posedge clk) (!D && (A || B || C)) |-> !Y
    );

// Active-low reset clears Q to zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) !AR[0] |-> (Q == {N{1'b0}})
    );

// When enabled, Q accumulates D.
    check_accumulate_on_enable: assert property (
        @(posedge CLK) disable iff (!AR[0])
        E[0] |=> (Q == ($past(Q) + $past(D)))
    );

// When not enabled, Q holds its value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!AR[0])
        !E[0] |=> (Q == $past(Q))
    );

// The upper nibble of PRODUCT is always zero after the first clocked update.
    check_product_upper_nibble_zero: assert property (
        @(posedge clk) ##1 PRODUCT[7:4] == 4'h0
    );

// Y must match the O2111AI Boolean function.
    check_y_matches_o2111ai_function: assert property (
        @(posedge clk) Y == ~(((A1 | A2) & B1 & C1 & D1))
    );

// If every NAND input is high, Y must be low.
    check_y_low_when_all_terms_high: assert property (
        @(posedge clk) ((A1 | A2) & B1 & C1 & D1) |-> !Y
    );

// A low Y means the OR term and all other NAND inputs are high.
    check_y_low_implies_all_terms_high: assert property (
        @(posedge clk) !Y |-> ((A1 | A2) & B1 & C1 & D1)
    );

// If both A inputs are low, Y must be high.
    check_y_high_when_a_inputs_low: assert property (
        @(posedge clk) !(A1 | A2) |-> Y
    );

// A low B1 forces Y high.
    check_y_high_when_b1_low: assert property (
        @(posedge clk) !B1 |-> Y
    );

// A low C1 forces Y high.
    check_y_high_when_c1_low: assert property (
        @(posedge clk) !C1 |-> Y
    );

// A low D1 forces Y high.
    check_y_high_when_d1_low: assert property (
        @(posedge clk) !D1 |-> Y
    );

// SUM matches the three-input XOR.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT_N is the inverted full-adder carry.
    check_cout_n_equation: assert property (
        @(posedge clk) COUT_N == ~((A & B) | ((A ^ B) & CI))
    );

// Outputs match the 2-bit arithmetic sum.
    check_full_adder_result: assert property (
        @(posedge clk) {~COUT_N, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// With CI low, the block behaves as a half adder.
    check_half_adder_mode: assert property (
        @(posedge clk) !CI |-> (SUM == (A ^ B)) && (COUT_N == ~(A & B))
    );

// With CI high, SUM inverts A^B and carry becomes A|B.
    check_carry_in_high_mode: assert property (
        @(posedge clk) CI |-> (SUM == ~(A ^ B)) && (COUT_N == ~(A | B))
    );

// Zero inputs produce zero sum and no carry.
    check_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && COUT_N)
    );

// All-one inputs produce sum one with carry asserted.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && !COUT_N)
    );

// Exactly one high input produces sum one and no carry.
    check_one_hot_case: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + {1'b0, CI}) == 2'd1) |-> (SUM && COUT_N)
    );

// Exactly two high inputs produce zero sum with carry asserted.
    check_two_hot_case: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + {1'b0, CI}) == 2'd2) |-> (!SUM && !COUT_N)
    );

// X must implement the 3-input XNOR function.
    check_xnor_function: assert property (
        @(posedge clk) X == ~(A ^ B ^ C)
    );

// All-zero inputs must drive X high.
    check_all_zero_drives_high: assert property (
        @(posedge clk) (!A && !B && !C) |-> X
    );

// Exactly one high input must drive X low.
    check_single_one_drives_low: assert property (
        @(posedge clk)
        (( A && !B && !C) ||
         (!A &&  B && !C) ||
         (!A && !B &&  C)) |-> !X
    );

// Exactly two high inputs must drive X high.
    check_double_one_drives_high: assert property (
        @(posedge clk)
        (( A &&  B && !C) ||
         ( A && !B &&  C) ||
         (!A &&  B &&  C)) |-> X
    );

// All-one inputs must drive X low.
    check_all_one_drives_low: assert property (
        @(posedge clk) (A && B && C) |-> !X
    );

// Active-low synchronous reset clears Q.
    check_reset_clears_q: assert property (
        @(posedge C) !R |=> (Q == 1'b0)
    );

// With reset inactive, set forces Q high.
    check_set_forces_q_high: assert property (
        @(posedge C) disable iff (!R) S |=> (Q == 1'b1)
    );

// With reset inactive and set low, D=0 is captured into Q.
    check_capture_d_zero: assert property (
        @(posedge C) disable iff (!R) (!S && !D) |=> (Q == 1'b0)
    );

// With reset inactive and set low, D=1 is captured into Q.
    check_capture_d_one: assert property (
        @(posedge C) disable iff (!R) (!S && D) |=> (Q == 1'b1)
    );

// Output matches the implemented combinational function.
    check_reduced_nand_matches_function: assert property (
        @(posedge clk) Reduced_NAND == (InY == 8'b1000_0000)
    );

// A high output only occurs for input 8'b10000000.
    check_high_output_requires_exact_pattern: assert property (
        @(posedge clk) Reduced_NAND |-> (InY == 8'b1000_0000)
    );

// Input 8'b10000000 must drive the output high.
    check_exact_pattern_drives_high_output: assert property (
        @(posedge clk) (InY == 8'b1000_0000) |-> Reduced_NAND
    );

// Any other input pattern must drive the output low.
    check_nonmatching_pattern_drives_low_output: assert property (
        @(posedge clk) (InY != 8'b1000_0000) |-> !Reduced_NAND
    );

// Any asserted lower input bit forces the output low.
    check_lower_bits_force_low_output: assert property (
        @(posedge clk) (|InY[6:0]) |-> !Reduced_NAND
    );

// A low MSB forces the output low.
    check_msb_low_forces_low_output: assert property (
        @(posedge clk) !InY[7] |-> !Reduced_NAND
    );

// Y must match the implemented 4-to-1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk)
        Y == ((A & ~S0 & ~S1) | (B & S0 & ~S1) | (C & ~S0 & S1) | (D & S0 & S1))
    );

// Select 2'b00 routes A to Y.
    check_select_00_routes_a: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == A)
    );

// Select 2'b01 routes B to Y.
    check_select_01_routes_b: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Y == B)
    );

// Select 2'b10 routes C to Y.
    check_select_10_routes_c: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Y == C)
    );

// Select 2'b11 routes D to Y.
    check_select_11_routes_d: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Y == D)
    );

// Combinational RTL with no native clock or reset; sample on external clk.
    // Function implemented is Y = (~A) & B_N.

    // Y must match the implemented combinational function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ((~A) & B_N)
    );

// A high forces Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> (Y == 1'b0)
    );

// B_N low forces Y low.
    check_bn_low_forces_y_low: assert property (
        @(posedge clk) !B_N |-> (Y == 1'b0)
    );

// A low with B_N high forces Y high.
    check_only_high_output_case: assert property (
        @(posedge clk) (!A && B_N) |-> (Y == 1'b1)
    );

// Y high can only occur when A is low and B_N is high.
    check_y_high_implies_input_condition: assert property (
        @(posedge clk) Y |-> (!A && B_N)
    );

// Sum bit 2 uses the carry generated by bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) s[2] == (a[2] ^ b[2] ^ maj3(a[1], b[1], maj3(a[0], b[0], cin)))
    );

// Sum bit 3 uses the carry generated by bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) s[3] == (a[3] ^ b[3] ^ maj3(a[2], b[2], maj3(a[1], b[1], maj3(a[0], b[0], cin))))
    );

// 0 encodes to bit 0 set.
    check_encode_0: assert property (
        @(posedge clk) (DATA_IN == 4'd0) |-> (DATA_OUT == 8'b00000001)
    );

// 1 encodes to bit 1 set.
    check_encode_1: assert property (
        @(posedge clk) (DATA_IN == 4'd1) |-> (DATA_OUT == 8'b00000010)
    );

// 2 encodes to bit 2 set.
    check_encode_2: assert property (
        @(posedge clk) (DATA_IN == 4'd2) |-> (DATA_OUT == 8'b00000100)
    );

// 3 encodes to bit 3 set.
    check_encode_3: assert property (
        @(posedge clk) (DATA_IN == 4'd3) |-> (DATA_OUT == 8'b00001000)
    );

// 4 encodes to bit 4 set.
    check_encode_4: assert property (
        @(posedge clk) (DATA_IN == 4'd4) |-> (DATA_OUT == 8'b00010000)
    );

// 5 encodes to bit 5 set.
    check_encode_5: assert property (
        @(posedge clk) (DATA_IN == 4'd5) |-> (DATA_OUT == 8'b00100000)
    );

// 6 encodes to bit 6 set.
    check_encode_6: assert property (
        @(posedge clk) (DATA_IN == 4'd6) |-> (DATA_OUT == 8'b01000000)
    );

// 7 encodes to bit 7 set.
    check_encode_7: assert property (
        @(posedge clk) (DATA_IN == 4'd7) |-> (DATA_OUT == 8'b10000000)
    );

// 8 encodes to bits 7 and 0 set.
    check_encode_8: assert property (
        @(posedge clk) (DATA_IN == 4'd8) |-> (DATA_OUT == 8'b10000001)
    );

// 9 encodes to bits 7 and 1 set.
    check_encode_9: assert property (
        @(posedge clk) (DATA_IN == 4'd9) |-> (DATA_OUT == 8'b10000010)
    );

// Inputs above 9 encode to zero.
    check_encode_default: assert property (
        @(posedge clk) (DATA_IN > 4'd9) |-> (DATA_OUT == 8'b00000000)
    );

// EN low means the register is not updated, so the output holds its value.
    check_output_holds_when_disabled: assert property (
        @(posedge CLK) !EN |=> $stable(ENCLK)
    );

// TE alone does not update the output when EN is low.
    check_te_has_no_effect_without_en: assert property (
        @(posedge CLK) (TE && !EN) |=> $stable(ENCLK)
    );

// Output updates on the next clock to the value computed from the sampled input.
    check_registered_transfer: assert property (
        @(posedge clk) 1'b1 |=> (out == rtl_result($past(in)))
    );

// Inputs 0 through 13 increment by one on the next clock.
    check_low_range_increment: assert property (
        @(posedge clk) (in <= 4'd13) |=> (out == ($past(in) + 4'd1))
    );

// Input 13 reaches the upper non-zero boundary value 14 on the next clock.
    check_input_13_to_14: assert property (
        @(posedge clk) (in == 4'd13) |=> (out == 4'd14)
    );

// Input 14 produces zero on the next clock because stage1 hits 4'hf.
    check_input_14_to_zero: assert property (
        @(posedge clk) (in == 4'd14) |=> (out == 4'd0)
    );

// Input 15 also produces zero on the next clock because the 4-bit increment wraps.
    check_input_15_to_zero: assert property (
        @(posedge clk) (in == 4'd15) |=> (out == 4'd0)
    );

// The registered output can never be 4'hf after a clocked update.
    check_output_never_fifteen: assert property (
        @(posedge clk) 1'b1 |=> (out != 4'hf)
    );

// Zero output occurs only when the previously sampled input was 14 or 15.
    check_zero_output_source: assert property (
        @(posedge clk) 1'b1 |=> ((out == 4'd0) == (($past(in) == 4'd14) || ($past(in) == 4'd15)))
    );

// Upper ten bytes are constant space padding.
    check_upper_space_padding: assert property (
        @(posedge clk) out[127:48] === 80'h20202020202020202020
    );

// Output [15:0] is the ASCII hex encoding of input byte [7:0].
    check_low_byte_ascii_hex: assert property (
        @(posedge clk) out[15:0] === {hex_ascii(in[7:4]), hex_ascii(in[3:0])}
    );

// Output [31:16] is the ASCII hex encoding of input byte [15:8].
    check_middle_byte_ascii_hex: assert property (
        @(posedge clk) out[31:16] === {hex_ascii(in[15:12]), hex_ascii(in[11:8])}
    );

// Output [47:32] is the ASCII hex encoding of input byte [23:16].
    check_high_byte_ascii_hex: assert property (
        @(posedge clk) out[47:32] === {hex_ascii(in[23:20]), hex_ascii(in[19:16])}
    );

// Combinational RTL with no native reset; sample on an external clock.

    // Lower 2:1 mux routes data_in[0] when sel[0] is low.
    check_temp0_selects_data0: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (data_out_temp0 == data_in[0])
    );

// Lower 2:1 mux routes data_in[1] when sel[0] is high.
    check_temp0_selects_data1: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (data_out_temp0 == data_in[1])
    );

// Upper 2:1 mux routes data_in[2] when sel[0] is low.
    check_temp1_selects_data2: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (data_out_temp1 == data_in[2])
    );

// Upper 2:1 mux routes data_in[3] when sel[0] is high.
    check_temp1_selects_data3: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (data_out_temp1 == data_in[3])
    );

// Final 2:1 mux routes data_out_temp0 when sel[1] is low.
    check_output_selects_temp0: assert property (
        @(posedge clk) (sel[1] == 1'b0) |-> (data_out == data_out_temp0)
    );

// Final 2:1 mux routes data_out_temp1 when sel[1] is high.
    check_output_selects_temp1: assert property (
        @(posedge clk) (sel[1] == 1'b1) |-> (data_out == data_out_temp1)
    );

// Top-level mux routes data_in[0] for select 2'b00.
    check_sel_00_routes_data0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (data_out == data_in[0])
    );

// Top-level mux routes data_in[1] for select 2'b01.
    check_sel_01_routes_data1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (data_out == data_in[1])
    );

// Top-level mux routes data_in[2] for select 2'b10.
    check_sel_10_routes_data2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (data_out == data_in[2])
    );

// Top-level mux routes data_in[3] for select 2'b11.
    check_sel_11_routes_data3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (data_out == data_in[3])
    );

// Active-low reset clears the register by the next sampled cycle.
    check_reset_forces_zero: assert property (
        @(posedge clk)
        !rst |=> (out == {N{1'b0}})
    );

// Clear drives the register to zero.
    check_clear_forces_zero: assert property (
        @(posedge clk) disable iff (!rst)
        clear |=> (out == {N{1'b0}})
    );

// Clear takes priority over hold.
    check_clear_overrides_hold: assert property (
        @(posedge clk) disable iff (!rst)
        (clear && hold) |=> (out == {N{1'b0}})
    );

// Hold preserves the current register value when clear is low.
    check_hold_preserves_value: assert property (
        @(posedge clk) disable iff (!rst)
        (hold && !clear) |=> (out == $past(out))
    );

// Sum is the XOR of a, b, and cin.
    check_sum_xor_chain: assert property (
        @(posedge clk) sum == ((a ^ b) ^ cin)
    );

// Carry out matches the OR of the two half-adder carry terms.
    check_cout_from_half_adders: assert property (
        @(posedge clk) cout == ((a & b) | ((a ^ b) & cin))
    );

// The concatenated outputs equal the 2-bit sum of the inputs.
    check_full_adder_arithmetic: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + {1'b0, cin})
    );

// With cin low, the block behaves like a half adder on a and b.
    check_cin_low_half_adder_mode: assert property (
        @(posedge clk) !cin |-> ((sum == (a ^ b)) && (cout == (a & b)))
    );

// With cin high, sum inverts a^b and carry becomes a|b.
    check_cin_high_add_one_mode: assert property (
        @(posedge clk) cin |-> ((sum == ~(a ^ b)) && (cout == (a | b)))
    );

// b[0] is a_msb gated by the stored LSB carried on b[1].
    check_b_lsb_gate: assert property (
        @(posedge clk) b[0] == (a_msb & b[1])
    );

// With a_msb low, the observable accumulator slice adds zero-extended a.
    check_slice_update_no_extend: assert property (
        @(posedge clk) (!a_msb) |=> (b[14:1] == ($past(b[14:1]) + {7'h00, $past(a)}))
    );

// With a_msb high, the observable accumulator slice adds {7'h7F, a}.
    check_slice_update_with_extend: assert property (
        @(posedge clk) (a_msb) |=> (b[14:1] == ($past(b[14:1]) + {7'h7F, $past(a)}))
    );

// The stored bit0, exposed on b[1], updates with the previous a[0].
    check_state_bit0_update: assert property (
        @(posedge clk) 1'b1 |=> (b[1] == ($past(b[1]) ^ $past(a[0])))
    );

// A non-extended add without low-14 overflow leaves b_msb unchanged.
    check_b_msb_hold_without_low14_carry: assert property (
        @(posedge clk) ((!a_msb) && (({1'b0, b[14:1]} + {8'h00, a}) < 15'h4000)) |=> (b_msb == $past(b_msb))
    );

// LOAD captures DATA_IN into the register on the next cycle.
    check_load_captures_data: assert property (
        @(posedge CLK)
        LOAD |=> (DATA_OUT == $past(DATA_IN))
    );

// SHIFT rotates the stored value left when LOAD is low.
    check_shift_rotates_data: assert property (
        @(posedge CLK)
        (!LOAD && SHIFT) |=> (DATA_OUT == {$past(DATA_OUT[2:0]), $past(DATA_OUT[3])})
    );

// The register holds its value when neither control is asserted.
    check_hold_without_control: assert property (
        @(posedge CLK)
        (!LOAD && !SHIFT) |=> (DATA_OUT == $past(DATA_OUT))
    );

// LOAD takes priority over SHIFT when both are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge CLK)
        (LOAD && SHIFT) |=> (DATA_OUT == $past(DATA_IN))
    );

// No clock or reset exists in the RTL; clk is only for assertion sampling.

    // X must match the implemented combinational equation.
    check_boolean_function: assert property (
        @(posedge clk) X == ((~A_N) & (~B_N) & C & D)
    );

// X can only be high when all enabling inputs are active.
    check_x_only_when_all_inputs_enable: assert property (
        @(posedge clk) X |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

// X must be high when both active-low inputs are low and C and D are high.
    check_x_high_when_all_inputs_enable: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1)) |-> (X == 1'b1)
    );

// A_N high forces the NOR output low, so X must be low.
    check_a_n_high_forces_x_low: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

// B_N high forces the NOR output low, so X must be low.
    check_b_n_high_forces_x_low: assert property (
        @(posedge clk) (B_N == 1'b1) |-> (X == 1'b0)
    );

// C low forces the AND output low, so X must be low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == 1'b0)
    );

// D low forces the AND output low, so X must be low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (D == 1'b0) |-> (X == 1'b0)
    );

// Combined outputs match 1-bit addition.
    check_full_adder_result: assert property (
        @(posedge clk)
        ({COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI}))
    );

// SUM is the XOR of the three inputs.
    check_sum_parity: assert property (
        @(posedge clk)
        (SUM == (A ^ B ^ CI))
    );

// COUT is high when any two inputs are high.
    check_cout_majority: assert property (
        @(posedge clk)
        (COUT == ((A & B) | (A & CI) | (B & CI)))
    );

// All-zero inputs produce zero outputs.
    check_all_zero_case: assert property (
        @(posedge clk)
        ((!A && !B && !CI) |-> (!COUT && !SUM))
    );

// Exactly one high input produces SUM only.
    check_one_high_case: assert property (
        @(posedge clk)
        (((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI)) |-> (SUM && !COUT))
    );

// Exactly two high inputs produce COUT only.
    check_two_high_case: assert property (
        @(posedge clk)
        (((A && B && !CI) || (A && !B && CI) || (!A && B && CI)) |-> (!SUM && COUT))
    );

// All-one inputs produce both SUM and COUT.
    check_all_one_case: assert property (
        @(posedge clk)
        ((A && B && CI) |-> (SUM && COUT))
    );

// The 5-bit result matches A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Bit 0 sum matches the first full adder XOR function.
    check_bit0_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 1 sum uses the carry generated from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  ((A[1] ^ B[1]) &
                   ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))
    );

// Bit 3 sum uses the carry generated from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^
                 ((A[2] & B[2]) |
                  ((A[2] ^ B[2]) &
                   ((A[1] & B[1]) |
                    ((A[1] ^ B[1]) &
                     ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))))
    );

// External sampling clock; the DUT itself is combinational and has no reset.

    // out_or_bitwise[0] is the OR of a[0] and b[0].
    check_or_bit0: assert property (
        @(posedge clk) out_or_bitwise[0] == (a[0] | b[0])
    );

// out_or_bitwise[1] is the OR of a[1] and b[1].
    check_or_bit1: assert property (
        @(posedge clk) out_or_bitwise[1] == (a[1] | b[1])
    );

// out_or_bitwise[2] is the OR of a[2] and b[2].
    check_or_bit2: assert property (
        @(posedge clk) out_or_bitwise[2] == (a[2] | b[2])
    );

// out_or_logical is the OR-reduction of the bitwise OR result.
    check_logical_or_reduce: assert property (
        @(posedge clk) out_or_logical == (out_or_bitwise[0] | out_or_bitwise[1] | out_or_bitwise[2])
    );

// out_not[3] is the inversion of a[0].
    check_not_a_bit0: assert property (
        @(posedge clk) out_not[3] == ~a[0]
    );

// out_not[4] is the inversion of a[1].
    check_not_a_bit1: assert property (
        @(posedge clk) out_not[4] == ~a[1]
    );

// out_not[5] is the inversion of a[2].
    check_not_a_bit2: assert property (
        @(posedge clk) out_not[5] == ~a[2]
    );

// out_not[0] is the inversion of b[0].
    check_not_b_bit0: assert property (
        @(posedge clk) out_not[0] == ~b[0]
    );

// out_not[1] is the inversion of b[1].
    check_not_b_bit1: assert property (
        @(posedge clk) out_not[1] == ~b[1]
    );

// out_not[2] is the inversion of b[2].
    check_not_b_bit2: assert property (
        @(posedge clk) out_not[2] == ~b[2]
    );

// External clk samples a purely combinational DUT with no reset.

    // 0000 decodes to Y[0].
    check_decode_0000: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0000) |-> (Y === 16'h0001)
    );

// 0001 decodes to Y[1].
    check_decode_0001: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0001) |-> (Y === 16'h0002)
    );

// 0010 decodes to Y[2].
    check_decode_0010: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0010) |-> (Y === 16'h0004)
    );

// 0011 decodes to Y[3].
    check_decode_0011: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0011) |-> (Y === 16'h0008)
    );

// 0100 decodes to Y[4].
    check_decode_0100: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0100) |-> (Y === 16'h0010)
    );

// 0101 decodes to Y[5].
    check_decode_0101: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0101) |-> (Y === 16'h0020)
    );

// 0110 decodes to Y[6].
    check_decode_0110: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0110) |-> (Y === 16'h0040)
    );

// 0111 decodes to Y[7].
    check_decode_0111: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b0111) |-> (Y === 16'h0080)
    );

// 1000 decodes to Y[8].
    check_decode_1000: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1000) |-> (Y === 16'h0100)
    );

// 1001 decodes to Y[9].
    check_decode_1001: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1001) |-> (Y === 16'h0200)
    );

// 1010 decodes to Y[10].
    check_decode_1010: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1010) |-> (Y === 16'h0400)
    );

// 1011 decodes to Y[11].
    check_decode_1011: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1011) |-> (Y === 16'h0800)
    );

// 1100 decodes to Y[12].
    check_decode_1100: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1100) |-> (Y === 16'h1000)
    );

// 1101 decodes to Y[13].
    check_decode_1101: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1101) |-> (Y === 16'h2000)
    );

// 1110 decodes to Y[14].
    check_decode_1110: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1110) |-> (Y === 16'h4000)
    );

// 1111 decodes to Y[15].
    check_decode_1111: assert property (
        @(posedge clk) ({A,B,C,D} === 4'b1111) |-> (Y === 16'h8000)
    );

// When b is 1, q follows a.
    check_b_high_selects_a: assert property (
        @(posedge clk) (b === 1'b1) |-> (q === a)
    );

// When b is not 1, q follows b.
    check_b_not_high_selects_b: assert property (
        @(posedge clk) (b !== 1'b1) |-> (q === b)
    );

// When b is 0, q is 0.
    check_b_low_forces_q_low: assert property (
        @(posedge clk) (b === 1'b0) |-> (q === 1'b0)
    );

// When both a and b are 1, q is 1.
    check_a_and_b_high_drive_q_high: assert property (
        @(posedge clk) ((a === 1'b1) && (b === 1'b1)) |-> (q === 1'b1)
    );

// When a is 0 and b is 1, q is 0.
    check_a_low_with_b_high_drives_q_low: assert property (
        @(posedge clk) ((a === 1'b0) && (b === 1'b1)) |-> (q === 1'b0)
    );

// q can only be 1 when both inputs are 1.
    check_q_high_implies_a_and_b_high: assert property (
        @(posedge clk) (q === 1'b1) |-> ((a === 1'b1) && (b === 1'b1))
    );

// MO must always match the implemented mux expression.
    check_mux_function: assert property (
        @(posedge clk) MO === ((S == 1'b1) ? B : A)
    );

// When select is low, MO must follow A.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (MO === A)
    );

// When select is high, MO must follow B.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (MO === B)
    );

// If both inputs match, MO must match them regardless of select.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A === B) |-> (MO === A)
    );

// No RTL clock or reset; sample combinational behavior on clk.

    // Y matches the RTL pairwise-AND OR function.
    check_majority_equation: assert property (
        @(posedge clk) Y == ((A & B) | (A & C) | (B & C))
    );

// A and B high must drive Y high.
    check_ab_pair_sets_y: assert property (
        @(posedge clk) (A & B) |-> Y
    );

// A and C high must drive Y high.
    check_ac_pair_sets_y: assert property (
        @(posedge clk) (A & C) |-> Y
    );

// B and C high must drive Y high.
    check_bc_pair_sets_y: assert property (
        @(posedge clk) (B & C) |-> Y
    );

// With A low, Y high requires B and C high.
    check_y_with_a_low_requires_bc: assert property (
        @(posedge clk) (Y & ~A) |-> (B & C)
    );

// With B low, Y high requires A and C high.
    check_y_with_b_low_requires_ac: assert property (
        @(posedge clk) (Y & ~B) |-> (A & C)
    );

// With C low, Y high requires A and B high.
    check_y_with_c_low_requires_ab: assert property (
        @(posedge clk) (Y & ~C) |-> (A & B)
    );

// Zero or one high input must keep Y low.
    check_zero_or_single_high_keeps_y_low: assert property (
        @(posedge clk)
        ((~A & ~B & ~C) |
         ( A & ~B & ~C) |
         (~A &  B & ~C) |
         (~A & ~B &  C)) |-> ~Y
    );

// Output matches the RTL mux expression.
    check_output_equation: assert property (
        @(posedge clk) (O == (I[11] ? I[10] : I[11]))
    );

// Output is low whenever I[11] is low.
    check_output_low_when_i11_low: assert property (
        @(posedge clk) (!I[11]) |-> (!O)
    );

// Output follows I[10] whenever I[11] is high.
    check_output_follows_i10_when_i11_high: assert property (
        @(posedge clk) I[11] |-> (O == I[10])
    );

// A high output requires both I[11] and I[10] to be high.
    check_output_high_requires_top_bits_high: assert property (
        @(posedge clk) O |-> (I[11] && I[10])
    );

// Both top input bits high force the output high.
    check_output_high_when_top_bits_high: assert property (
        @(posedge clk) (I[11] && I[10]) |-> O
    );

// z must match the RTL compare equation.
    check_output_equation: assert property (
        @(posedge clk) z == (V[3] & (V[2] | V[1]))
    );

// z can only be high when V[3] is high.
    check_z_requires_v3: assert property (
        @(posedge clk) z |-> V[3]
    );

// z can only be high when either V[2] or V[1] is high.
    check_z_requires_v2_or_v1: assert property (
        @(posedge clk) z |-> (V[2] | V[1])
    );

// If V[3] is low, z must be low.
    check_v3_low_forces_z_low: assert property (
        @(posedge clk) !V[3] |-> !z
    );

// If both V[2] and V[1] are low, z must be low.
    check_v2_v1_low_forces_z_low: assert property (
        @(posedge clk) !(V[2] | V[1]) |-> !z
    );

// If V[3] and V[2] are high, z must be high.
    check_v3_and_v2_drive_z_high: assert property (
        @(posedge clk) (V[3] & V[2]) |-> z
    );

// If V[3] and V[1] are high, z must be high.
    check_v3_and_v1_drive_z_high: assert property (
        @(posedge clk) (V[3] & V[1]) |-> z
    );

// Supply pins hold their declared constant values.
    check_supply_constants: assert property (
        @(posedge clk) disable iff (1'b0)
        (VPWR == 1'b1) && (VGND == 1'b0) && (VPB == 1'b1) && (VNB == 1'b0)
    );

// Y matches the implemented NOR-of-NORs logic.
    check_y_boolean_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((A | B) & (C | D))
    );

// If both A and B are low, Y must be low.
    check_ab_zero_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 1'b0) && (B == 1'b0)) |-> (Y == 1'b0)
    );

// If both C and D are low, Y must be low.
    check_cd_zero_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((C == 1'b0) && (D == 1'b0)) |-> (Y == 1'b0)
    );

// A high Y requires at least one of A or B to be high.
    check_y_high_requires_ab_or: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b1) |-> ((A == 1'b1) || (B == 1'b1))
    );

// A high Y requires at least one of C or D to be high.
    check_y_high_requires_cd_or: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b1) |-> ((C == 1'b1) || (D == 1'b1))
    );

// One high input in each pair drives Y high.
    check_pairwise_or_drives_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (((A == 1'b1) || (B == 1'b1)) && ((C == 1'b1) || (D == 1'b1))) |-> (Y == 1'b1)
    );

// A sampled reset leaves the counter cleared by the next clock.
    check_reset_clears_by_next_clock: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset deassertion is observed with count still at zero.
    check_reset_release_sees_zero: assert property (
        @(posedge clk) reset ##1 !reset |-> (count == 4'b0000)
    );

// From 15, the counter wraps back to zero.
    check_wrap_from_fifteen: assert property (
        @(posedge clk) disable iff (reset)
            (count == 4'b1111) |=> (count == 4'b0000)
    );

// On non-reset cycles, the next sampled count is zero or increments by one.
    check_count_progression: assert property (
        @(posedge clk) disable iff (reset)
            1'b1 |=> ((count == 4'b0000) || (count == ($past(count) + 4'b0001)))
    );

// ForwardA selects WB forwarding when the WB condition is taken.
    check_forwarda_wb_select: assert property (
        @(posedge clk)
        ((WB_RegWrite && WB_rd && (WB_rd == EX_rs) &&
          ((MEM_rd != EX_rs) || (~MEM_RegWrite))) === 1'b1)
        |-> (ForwardA == 2'b01)
    );

// ForwardA selects MEM forwarding when WB is not taken and the MEM condition is taken.
    check_forwarda_mem_select: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rs) &&
           ((MEM_rd != EX_rs) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rs)) === 1'b1))
        |-> (ForwardA == 2'b10)
    );

// ForwardA is zero when neither forwarding condition is taken.
    check_forwarda_default_zero: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rs) &&
           ((MEM_rd != EX_rs) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rs)) !== 1'b1))
        |-> (ForwardA == 2'b00)
    );

// ForwardA gives MEM priority when both MEM and WB match EX_rs.
    check_forwarda_mem_priority: assert property (
        @(posedge clk)
        (((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rs)) === 1'b1) &&
         ((WB_RegWrite && WB_rd && (WB_rd == EX_rs)) === 1'b1))
        |-> (ForwardA == 2'b10)
    );

// ForwardA only uses implemented encodings.
    check_forwarda_valid_encoding: assert property (
        @(posedge clk)
        (ForwardA inside {2'b00, 2'b01, 2'b10})
    );

// ForwardB selects WB forwarding when the WB condition is taken.
    check_forwardb_wb_select: assert property (
        @(posedge clk)
        ((WB_RegWrite && WB_rd && (WB_rd == EX_rt) &&
          ((MEM_rd != EX_rt) || (~MEM_RegWrite))) === 1'b1)
        |-> (ForwardB == 2'b01)
    );

// ForwardB selects MEM forwarding when WB is not taken and the MEM condition is taken.
    check_forwardb_mem_select: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rt) &&
           ((MEM_rd != EX_rt) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rt)) === 1'b1))
        |-> (ForwardB == 2'b10)
    );

// ForwardB is zero when neither forwarding condition is taken.
    check_forwardb_default_zero: assert property (
        @(posedge clk)
        (((WB_RegWrite && WB_rd && (WB_rd == EX_rt) &&
           ((MEM_rd != EX_rt) || (~MEM_RegWrite))) !== 1'b1) &&
         ((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rt)) !== 1'b1))
        |-> (ForwardB == 2'b00)
    );

// ForwardB gives MEM priority when both MEM and WB match EX_rt.
    check_forwardb_mem_priority: assert property (
        @(posedge clk)
        (((MEM_RegWrite && MEM_rd && (MEM_rd == EX_rt)) === 1'b1) &&
         ((WB_RegWrite && WB_rd && (WB_rd == EX_rt)) === 1'b1))
        |-> (ForwardB == 2'b10)
    );

// ForwardB only uses implemented encodings.
    check_forwardb_valid_encoding: assert property (
        @(posedge clk)
        (ForwardB inside {2'b00, 2'b01, 2'b10})
    );

// No reset in the RTL; sample combinational behavior on clk.

    // When sel is 2'b00, out must equal a.
    check_select_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == a)
    );

// When sel is 2'b01, out must equal b.
    check_select_b: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == b)
    );

// When sel is 2'b10, out must equal a & b.
    check_select_and: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == (a & b))
    );

// When sel is 2'b11, out must equal a | b.
    check_select_or: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == (a | b))
    );

// Out must always match the full mux function.
    check_mux_function: assert property (
        @(posedge clk) out == ((sel == 2'b00) ? a :
                               (sel == 2'b01) ? b :
                               (sel == 2'b10) ? (a & b) :
                                                (a | b))
    );

// When not in reset, QN must be the inverse of Q.
    check_qn_inverse_of_q: assert property (
        @(posedge CLK) disable iff (!RST) (QN == ~Q)
    );

// A reset seen on a clock edge clears the outputs by the next sample.
    check_reset_clears_outputs: assert property (
        @(posedge CLK) (!RST) |=> ((Q == 1'b0) && (QN == 1'b1))
    );

// With reset inactive, Q captures D on the next sampled clock.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |=> (Q == $past(D))
    );

// With reset inactive, QN reflects the inverse of the captured D.
    check_qn_captures_inverted_d: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |=> (QN == ~$past(D))
    );

// DUT is combinational with no reset; assertions are sampled on clk.

    // zero must assert when the input is exactly all zeros.
    check_zero_asserted_for_zero_input: assert property (
        @(posedge clk) (in === 64'b0) |-> (zero == 1'b1)
    );

// zero must deassert for any input that is not exactly all zeros.
    check_zero_deasserted_for_nonzero_input: assert property (
        @(posedge clk) (in !== 64'b0) |-> (zero == 1'b0)
    );

// Reset drives the counter to zero by the next clock.
    check_reset_clears_counter: assert property (
        @(posedge clk) !areset |=> (count_out == 4'b0000)
    );

// Load clears the counter to zero on the next clock.
    check_load_clears_counter: assert property (
        @(posedge clk) disable iff (!areset)
        load |=> (count_out == 4'b0000)
    );

// Counting up increments the counter by one.
    check_count_up_increments: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && count_enable && up_down) |=> (count_out == ($past(count_out) + 4'b0001))
    );

// Counting down decrements the counter by one.
    check_count_down_decrements: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && count_enable && !up_down) |=> (count_out == ($past(count_out) - 4'b0001))
    );

// Without load or count enable, the counter holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && !count_enable) |=> (count_out == $past(count_out))
    );

// Counting up wraps from 15 back to 0.
    check_count_up_wraps: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && count_enable && up_down && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// Counting down wraps from 0 back to 15.
    check_count_down_wraps: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && count_enable && !up_down && (count_out == 4'h0)) |=> (count_out == 4'hF)
    );

// Sum matches the three-input XOR function.
    check_sum_function: assert property (
        @(posedge clk) sum == (a ^ b ^ cin)
    );

// Carry-out matches the full-adder carry equation.
    check_cout_function: assert property (
        @(posedge clk) cout == ((a & b) | (a & cin) | (b & cin))
    );

// All-zero inputs produce zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge clk) (!a && !b && !cin) |-> (!sum && !cout)
    );

// Any single high input produces sum high and no carry.
    check_single_one_case: assert property (
        @(posedge clk)
        ((a && !b && !cin) || (!a && b && !cin) || (!a && !b && cin))
        |-> (sum && !cout)
    );

// Any two high inputs produce sum low and carry high.
    check_two_one_case: assert property (
        @(posedge clk)
        ((a && b && !cin) || (a && !b && cin) || (!a && b && cin))
        |-> (!sum && cout)
    );

// All-one inputs produce sum high and carry high.
    check_all_one_case: assert property (
        @(posedge clk) (a && b && cin) |-> (sum && cout)
    );

// Carry-out only occurs when at least two inputs are high.
    check_carry_requires_two_ones: assert property (
        @(posedge clk) cout |-> ((a && b) || (a && cin) || (b && cin))
    );

// No carry occurs when fewer than two inputs are high.
    check_no_carry_with_fewer_than_two_ones: assert property (
        @(posedge clk) ((!a && !b) || (!a && !cin) || (!b && !cin)) |-> !cout
    );

// Sum is high for odd input parity.
    check_sum_odd_parity: assert property (
        @(posedge clk)
        ((!a && !b && cin) || (!a && b && !cin) || (a && !b && !cin) || (a && b && cin))
        |-> sum
    );

// Sum is low for even input parity.
    check_sum_even_parity: assert property (
        @(posedge clk)
        ((!a && !b && !cin) || (!a && b && cin) || (a && !b && cin) || (a && b && !cin))
        |-> !sum
    );

// No RTL clock or reset; clk is the sampling clock for this combinational cell.

    // X matches the implemented OR of A, B, and NAND(C_N, D_N).
    check_x_function: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A high forces X high.
    check_a_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C_N low forces X high through the NAND term.
    check_cn_low_forces_x_high: assert property (
        @(posedge clk) !C_N |-> X
    );

// D_N low forces X high through the NAND term.
    check_dn_low_forces_x_high: assert property (
        @(posedge clk) !D_N |-> X
    );

// With A and B low, X is determined only by the NAND term.
    check_nand_term_when_a_b_low: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~(C_N & D_N))
    );

// With C_N and D_N high, X is determined only by A or B.
    check_or_term_when_nand_inactive: assert property (
        @(posedge clk) (C_N && D_N) |-> (X == (A | B))
    );

// When all effective OR inputs are low, X is low.
    check_all_terms_low_drive_x_low: assert property (
        @(posedge clk) (!A && !B && C_N && D_N) |-> !X
    );

// If X is low, all effective OR inputs must be low.
    check_x_low_requires_all_terms_low: assert property (
        @(posedge clk) !X |-> (!A && !B && C_N && D_N)
    );

// QN is always the inverse of Q.
    check_qn_is_inverse_of_q: assert property (
        @(posedge CLK) disable iff (1'b0) (QN === ~Q)
    );

// SET alone drives Q high on the next cycle.
    check_set_drives_q_high: assert property (
        @(posedge CLK) disable iff (1'b0) (SET && !RESET) |=> (Q === 1'b1)
    );

// SET has priority over RESET on the next cycle.
    check_set_overrides_reset: assert property (
        @(posedge CLK) disable iff (1'b0) (SET && RESET) |=> (Q === 1'b1)
    );

// RESET drives Q low when SET is low.
    check_reset_drives_q_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && RESET) |=> (Q === 1'b0)
    );

// D is captured when SET and RESET are low.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (1'b0) (!SET && !RESET) |=> (Q === $past(D))
    );

// comp1 matches the combinational function implemented by the RTL.
    check_comp1_function: assert property (
        @(posedge clk)
        comp1 == (
            ((v1_reg[5:4] == 2'b00) && ((v1_reg[3:0] + 4'b0001) >= 4'h8)) ||
            (v1_reg[5:4] == 2'b01) ||
            ((v1_reg[5:4] == 2'b10) && !((v1_reg[3:0] + 4'b0001) >= 4'h8))
        )
    );

// Upper bits 01 force comp1 high.
    check_upper_01_sets_comp1: assert property (
        @(posedge clk)
        (v1_reg[5:4] == 2'b01) |-> (comp1 == 1'b1)
    );

// Upper bits 11 force comp1 low.
    check_upper_11_clears_comp1: assert property (
        @(posedge clk)
        (v1_reg[5:4] == 2'b11) |-> (comp1 == 1'b0)
    );

// Upper bits 00 make comp1 follow bit[3] of the low-nibble increment.
    check_upper_00_uses_low_increment_msb: assert property (
        @(posedge clk)
        (v1_reg[5:4] == 2'b00) |-> (comp1 == ((v1_reg[3:0] + 4'b0001) >= 4'h8))
    );

// Upper bits 10 make comp1 invert bit[3] of the low-nibble increment.
    check_upper_10_inverts_low_increment_msb: assert property (
        @(posedge clk)
        (v1_reg[5:4] == 2'b10) |-> (comp1 == !((v1_reg[3:0] + 4'b0001) >= 4'h8))
    );

// AND output matches in1 & in2.
    check_and_function: assert property (
        @(posedge clk) out_and == (in1 & in2)
    );

// OR output matches in1 | in2.
    check_or_function: assert property (
        @(posedge clk) out_or == (in1 | in2)
    );

// NOT output matches ~in1.
    check_not_function: assert property (
        @(posedge clk) out_not == (~in1)
    );

// XOR output matches in1 ^ in2.
    check_xor_function: assert property (
        @(posedge clk) out_xor == (in1 ^ in2)
    );

// XNOR output matches ~(in1 ^ in2).
    check_xnor_function: assert property (
        @(posedge clk) out_xnor == (~(in1 ^ in2))
    );

// XOR and XNOR are complements.
    check_xor_xnor_complement: assert property (
        @(posedge clk) out_xnor == (~out_xor)
    );

// Equal inputs drive XNOR high and XOR low.
    check_equal_inputs_behavior: assert property (
        @(posedge clk) (in1 == in2) |-> (out_xnor && !out_xor)
    );

// Different inputs drive XOR high and XNOR low.
    check_different_inputs_behavior: assert property (
        @(posedge clk) (in1 != in2) |-> (out_xor && !out_xnor)
    );

// Outputs match 32-bit addition with carry-in.
    check_full_addition: assert property (
        @(posedge clk) {co, s} == ({1'b0, a} + {1'b0, b} + {{32{1'b0}}, ci})
    );

// With carry-in low, outputs match a+b.
    check_addition_without_carry_in: assert property (
        @(posedge clk) (ci == 1'b0) |-> ({co, s} == ({1'b0, a} + {1'b0, b}))
    );

// A zero operand passes b and carry-in through the adder.
    check_zero_a_operand: assert property (
        @(posedge clk) (a == 32'h0000_0000) |-> ({co, s} == ({1'b0, b} + {{32{1'b0}}, ci}))
    );

// A zero operand on b passes a and carry-in through the adder.
    check_zero_b_operand: assert property (
        @(posedge clk) (b == 32'h0000_0000) |-> ({co, s} == ({1'b0, a} + {{32{1'b0}}, ci}))
    );

// Zero plus zero produces only the carry-in in bit 0 and no carry-out.
    check_zero_inputs: assert property (
        @(posedge clk) ((a == 32'h0000_0000) && (b == 32'h0000_0000)) |-> (s == {31'd0, ci} && co == 1'b0)
    );

// Sum bit 0 follows the full-adder equation.
    check_lsb_sum: assert property (
        @(posedge clk) s[0] == (a[0] ^ b[0] ^ ci)
    );

// Sum bit 1 uses the carry generated from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) s[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | ((a[0] | b[0]) & ci)))
    );

// Disjoint one bits with no carry-in reduce to bitwise OR and no carry-out.
    check_disjoint_operands_no_carry: assert property (
        @(posedge clk) (((a & b) == 32'h0000_0000) && (ci == 1'b0)) |-> (s == (a | b) && co == 1'b0)
    );

// Adding a value and its inverse with carry-in high wraps to zero with carry-out.
    check_inverse_operands_with_carry_in: assert property (
        @(posedge clk) ((b == ~a) && (ci == 1'b1)) |-> (s == 32'h0000_0000 && co == 1'b1)
    );

// Adding a value and its inverse with carry-in low yields all ones and no carry-out.
    check_inverse_operands_without_carry_in: assert property (
        @(posedge clk) ((b == ~a) && (ci == 1'b0)) |-> (s == 32'hFFFF_FFFF && co == 1'b0)
    );

// Y always matches the RTL's selected combinational expression.
    check_output_matches_rtl: assert property (
        @(posedge clk) Y == (invert ? ~((~A) + 4'h1) : ((~A) + 4'h1))
    );

// When invert is low, Y is ~A plus one.
    check_noninvert_branch: assert property (
        @(posedge clk) !invert |-> (Y == ((~A) + 4'h1))
    );

// When invert is high, Y is the complement of ~A plus one.
    check_invert_branch: assert property (
        @(posedge clk) invert |-> (Y == ~((~A) + 4'h1))
    );

// A value of zero produces zero when invert is low.
    check_zero_noninvert: assert property (
        @(posedge clk) !invert && (A == 4'h0) |-> (Y == 4'h0)
    );

// A value of zero produces all ones when invert is high.
    check_zero_invert: assert property (
        @(posedge clk) invert && (A == 4'h0) |-> (Y == 4'hF)
    );

// A value of all ones produces one when invert is low.
    check_allones_noninvert: assert property (
        @(posedge clk) !invert && (A == 4'hF) |-> (Y == 4'h1)
    );

// A value of all ones produces fourteen when invert is high.
    check_allones_invert: assert property (
        @(posedge clk) invert && (A == 4'hF) |-> (Y == 4'hE)
    );

// X matches the implemented function ~A_N & B & C.
    check_x_function: assert property (
        @(posedge clk) X == ((~A_N) & B & C)
    );

// A high X requires all effective AND terms to be high.
    check_x_high_implies_inputs: assert property (
        @(posedge clk) X |-> ((!A_N) && B && C)
    );

// When all effective AND terms are high, X must be high.
    check_inputs_imply_x_high: assert property (
        @(posedge clk) ((!A_N) && B && C) |-> X
    );

// A_N high forces X low because A_N is inverted internally.
    check_an_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// Combinational DUT with no reset; sample behavior on clk.

    // Y must match the implemented boolean equation.
    check_boolean_function: assert property (
        @(posedge clk) Y === ((~A_N) & (~B))
    );

// Both inputs low must drive Y high.
    check_output_high_when_inputs_low: assert property (
        @(posedge clk) ((A_N === 1'b0) && (B === 1'b0)) |-> (Y === 1'b1)
    );

// A_N high must drive Y low.
    check_output_low_when_a_n_high: assert property (
        @(posedge clk) (A_N === 1'b1) |-> (Y === 1'b0)
    );

// B high must drive Y low.
    check_output_low_when_b_high: assert property (
        @(posedge clk) (B === 1'b1) |-> (Y === 1'b0)
    );

// Y high implies both inputs are low.
    check_output_high_only_when_inputs_low: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A_N === 1'b0) && (B === 1'b0))
    );

// While reset is asserted, the output is cleared.
    check_reset_clears_out: assert property (
        @(posedge clk) !rst_n |-> (out == 4'b0000)
    );

// Two's complement of zero remains zero when enabled.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(en) && ($past(in) == 4'b0000)) |-> (out == 4'b0000)
    );

// Active-low reset clears the state and derived feedback by the next cycle.
    check_reset_clears_state: assert property (
        @(posedge clk)
        !rst_n |=> (shift_reg == 64'h0000000000000000) &&
                   (Q == 4'h0) &&
                   (feedback == 4'h0)
    );

// Binary inputs produce the Boolean AND result.
    check_binary_inputs_match_and: assert property (
        @(posedge clk)
        (((A === 1'b0) || (A === 1'b1)) &&
         ((B === 1'b0) || (B === 1'b1)))
        |-> (X === (A & B))
    );

// Any low input forces the output low.
    check_any_low_forces_output_low: assert property (
        @(posedge clk)
        ((A === 1'b0) || (B === 1'b0))
        |-> (X === 1'b0)
    );

// Both high inputs drive the output high.
    check_both_high_drive_output_high: assert property (
        @(posedge clk)
        (A === 1'b1 && B === 1'b1)
        |-> (X === 1'b1)
    );

// A high output requires both inputs high.
    check_output_high_requires_both_high: assert property (
        @(posedge clk)
        (X === 1'b1)
        |-> (A === 1'b1 && B === 1'b1)
    );

// A low output implies at least one input is low.
    check_output_low_requires_any_low: assert property (
        @(posedge clk)
        (X === 1'b0)
        |-> ((A === 1'b0) || (B === 1'b0))
    );

// The AND and buffer chain never drives high impedance.
    check_output_never_high_impedance: assert property (
        @(posedge clk)
        (X !== 1'bz)
    );

// addr must match the RTL continuous assignment.
    check_addr_equation: assert property (
        @(posedge clk)
        addr == ((vcount[9:1] << 8) + (vcount[9:1] << 6) + (hcount >> 1))
    );

// The low six addr bits come directly from hcount[6:1].
    check_addr_low_bits_from_hcount: assert property (
        @(posedge clk)
        addr[5:0] == hcount[6:1]
    );

// Synchronous reset clears the counter and flag on the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk)
        rst |=> (count == 32'd0) && (max_reached == 1'b0)
    );

// Below max, the counter increments by one and the flag stays low.
    check_increment_until_max: assert property (
        @(posedge clk) disable iff (rst)
        (count != 32'hFFFFFFFF) |=> (count == ($past(count) + 32'd1)) && (max_reached == 1'b0)
    );

// At max, the counter saturates and the flag asserts.
    check_saturate_and_flag_at_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == 32'hFFFFFFFF) |=> (count == $past(count)) && (max_reached == 1'b1)
    );

// Output must always be the logical inversion of the input.
    check_inverter_function: assert property (
        @(posedge clk) Y === ~A
    );

// Y must match the RTL AND of A and B.
    check_y_matches_and: assert property (
        @(posedge clk) Y == (A & B)
    );

// A must be high whenever Y is high.
    check_y_high_requires_a_high: assert property (
        @(posedge clk) Y |-> A
    );

// B must be high whenever Y is high.
    check_y_high_requires_b_high: assert property (
        @(posedge clk) Y |-> B
    );

// Both inputs high must drive Y high.
    check_ab_high_implies_y_high: assert property (
        @(posedge clk) (A & B) |-> Y
    );

// A falling select chooses multiplier 1 when its inputs are unchanged.
    check_select_low_loads_mul1: assert property (
        @(posedge clk) $fell(select) && $stable(a_1) && $stable(b_1) |-> (result == mul_result_1)
    );

// A rising select chooses multiplier 2 when its inputs are unchanged.
    check_select_high_loads_mul2: assert property (
        @(posedge clk) $rose(select) && $stable(a_2) && $stable(b_2) |-> (result == mul_result_2)
    );

// Reset clears the register on the following cycle.
    check_reset_clears_data: assert property (
        @(posedge clk) reset |=> (data_out == 4'b0000)
    );

// Load captures data_in when shift is not asserted.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset)
        (load && !shift) |=> (data_out == $past(data_in))
    );

// Shift rotates the register left when load is low.
    check_shift_rotates_data: assert property (
        @(posedge clk) disable iff (reset)
        (!load && shift) |=> (data_out == {$past(data_out[2]), $past(data_out[1]), $past(data_out[0]), $past(data_out[3])})
    );

// The register holds its value when neither control is active.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !shift) |=> (data_out == $past(data_out))
    );

// Load has priority over shift when both are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (reset)
        (load && shift) |=> (data_out == $past(data_in))
    );

// Active-high reset keeps count at zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'b0000)
    );

// Count holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        (!en) |=> (count == $past(count))
    );

// Count increments by one when enabled and ctrl is low.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        (en && !ctrl) |=> (count == ($past(count) + 4'd1))
    );

// Count decrements by one when enabled and ctrl is high.
    check_decrement_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        (en && ctrl) |=> (count == ($past(count) - 4'd1))
    );

// Overall mux equation.
    check_mux_equation: assert property (
        @(posedge clk) out == (sel1 ? (sel0 ? in3 : in2) : (sel0 ? in1 : in0))
    );

// sel1=0 and sel0=0 selects in0.
    check_select_00_routes_in0: assert property (
        @(posedge clk) (!sel1 && !sel0) |-> (out == in0)
    );

// sel1=0 and sel0=1 selects in1.
    check_select_01_routes_in1: assert property (
        @(posedge clk) (!sel1 && sel0) |-> (out == in1)
    );

// sel1=1 and sel0=0 selects in2.
    check_select_10_routes_in2: assert property (
        @(posedge clk) (sel1 && !sel0) |-> (out == in2)
    );

// sel1=1 and sel0=1 selects in3.
    check_select_11_routes_in3: assert property (
        @(posedge clk) (sel1 && sel0) |-> (out == in3)
    );

// Even a_in makes out capture b_in divided by two on the next cycle.
    check_even_selects_half: assert property (
        @(posedge clock) (a_in[0] == 1'b0) |=> (out == ($past(b_in) >> 1))
    );

// Odd a_in makes out capture b_in multiplied by two on the next cycle.
    check_odd_selects_double: assert property (
        @(posedge clock) (a_in[0] == 1'b1) |=> (out == ($past(b_in) << 1))
    );

// out always matches the transform selected by the previous cycle's a_in.
    check_out_matches_prior_inputs: assert property (
        @(posedge clock) 1'b1 |=> (out == ($past(a_in[0]) ? ($past(b_in) << 1) : ($past(b_in) >> 1)))
    );

// Zero b_in produces zero out on the next cycle in either branch.
    check_zero_b_in_yields_zero: assert property (
        @(posedge clock) (b_in == '0) |=> (out == '0)
    );

// Input 0 maps to 0x0000 on the next clock.
    check_in_0_maps_out_0000: assert property (
        @(posedge clk) (in == 4'h0) |=> (out == 16'h0000)
    );

// Input 1 maps to 0x1111 on the next clock.
    check_in_1_maps_out_1111: assert property (
        @(posedge clk) (in == 4'h1) |=> (out == 16'h1111)
    );

// Input 2 maps to 0x0101 on the next clock.
    check_in_2_maps_out_0101: assert property (
        @(posedge clk) (in == 4'h2) |=> (out == 16'h0101)
    );

// Input 3 maps to 0x1010 on the next clock.
    check_in_3_maps_out_1010: assert property (
        @(posedge clk) (in == 4'h3) |=> (out == 16'h1010)
    );

// Input 4 maps to 0x0011 on the next clock.
    check_in_4_maps_out_0011: assert property (
        @(posedge clk) (in == 4'h4) |=> (out == 16'h0011)
    );

// Input 5 maps to 0x1100 on the next clock.
    check_in_5_maps_out_1100: assert property (
        @(posedge clk) (in == 4'h5) |=> (out == 16'h1100)
    );

// Input 6 maps to 0x0110 on the next clock.
    check_in_6_maps_out_0110: assert property (
        @(posedge clk) (in == 4'h6) |=> (out == 16'h0110)
    );

// Input 7 maps to 0x1001 on the next clock.
    check_in_7_maps_out_1001: assert property (
        @(posedge clk) (in == 4'h7) |=> (out == 16'h1001)
    );

// Input 8 maps to 0x1111 on the next clock.
    check_in_8_maps_out_1111: assert property (
        @(posedge clk) (in == 4'h8) |=> (out == 16'h1111)
    );

// Input 9 maps to 0x0000 on the next clock.
    check_in_9_maps_out_0000: assert property (
        @(posedge clk) (in == 4'h9) |=> (out == 16'h0000)
    );

// Input A maps to 0x1010 on the next clock.
    check_in_a_maps_out_1010: assert property (
        @(posedge clk) (in == 4'hA) |=> (out == 16'h1010)
    );

// Input B maps to 0x0101 on the next clock.
    check_in_b_maps_out_0101: assert property (
        @(posedge clk) (in == 4'hB) |=> (out == 16'h0101)
    );

// Input C maps to 0x1100 on the next clock.
    check_in_c_maps_out_1100: assert property (
        @(posedge clk) (in == 4'hC) |=> (out == 16'h1100)
    );

// Input D maps to 0x0011 on the next clock.
    check_in_d_maps_out_0011: assert property (
        @(posedge clk) (in == 4'hD) |=> (out == 16'h0011)
    );

// Input E maps to 0x1001 on the next clock.
    check_in_e_maps_out_1001: assert property (
        @(posedge clk) (in == 4'hE) |=> (out == 16'h1001)
    );

// Input F maps to 0x0110 on the next clock.
    check_in_f_maps_out_0110: assert property (
        @(posedge clk) (in == 4'hF) |=> (out == 16'h0110)
    );

// Y must always match the NOR of A and B.
    check_nor_equation: assert property (
        @(posedge clk) Y == ~(A | B)
    );

// Y must be high when both inputs are low.
    check_output_high_when_both_low: assert property (
        @(posedge clk) (!A && !B) |-> Y
    );

// Y must be low whenever A is high.
    check_output_low_when_a_high: assert property (
        @(posedge clk) A |-> !Y
    );

// Y must be low whenever B is high.
    check_output_low_when_b_high: assert property (
        @(posedge clk) B |-> !Y
    );

// A high Y implies both inputs are low.
    check_output_high_only_when_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B)
    );

// Y[0] decodes input value 4'b0000.
    check_y0_decode: assert property (
        @(posedge clk) Y[0] == ((~A[3]) & (~A[2]) & (~A[1]) & (~A[0]))
    );

// Y[1] decodes input value 4'b0001.
    check_y1_decode: assert property (
        @(posedge clk) Y[1] == ((~A[3]) & (~A[2]) & (~A[1]) & A[0])
    );

// Y[2] decodes input value 4'b0010.
    check_y2_decode: assert property (
        @(posedge clk) Y[2] == ((~A[3]) & (~A[2]) & A[1] & (~A[0]))
    );

// Y[3] decodes input value 4'b0011.
    check_y3_decode: assert property (
        @(posedge clk) Y[3] == ((~A[3]) & (~A[2]) & A[1] & A[0])
    );

// Y[4] decodes input value 4'b0100.
    check_y4_decode: assert property (
        @(posedge clk) Y[4] == ((~A[3]) & A[2] & (~A[1]) & (~A[0]))
    );

// Y[5] decodes input value 4'b0101.
    check_y5_decode: assert property (
        @(posedge clk) Y[5] == ((~A[3]) & A[2] & (~A[1]) & A[0])
    );

// Y[6] decodes input value 4'b0110.
    check_y6_decode: assert property (
        @(posedge clk) Y[6] == ((~A[3]) & A[2] & A[1] & (~A[0]))
    );

// Y[7] decodes input value 4'b0111.
    check_y7_decode: assert property (
        @(posedge clk) Y[7] == ((~A[3]) & A[2] & A[1] & A[0])
    );

// Y[8] decodes input value 4'b1000.
    check_y8_decode: assert property (
        @(posedge clk) Y[8] == (A[3] & (~A[2]) & (~A[1]) & (~A[0]))
    );

// Y[9] decodes input value 4'b1001.
    check_y9_decode: assert property (
        @(posedge clk) Y[9] == (A[3] & (~A[2]) & (~A[1]) & A[0])
    );

// Y[10] decodes input value 4'b1010.
    check_y10_decode: assert property (
        @(posedge clk) Y[10] == (A[3] & (~A[2]) & A[1] & (~A[0]))
    );

// Y[11] decodes input value 4'b1011.
    check_y11_decode: assert property (
        @(posedge clk) Y[11] == (A[3] & (~A[2]) & A[1] & A[0])
    );

// Y[12] decodes input value 4'b1100.
    check_y12_decode: assert property (
        @(posedge clk) Y[12] == (A[3] & A[2] & (~A[1]) & (~A[0]))
    );

// Y[13] decodes input value 4'b1101.
    check_y13_decode: assert property (
        @(posedge clk) Y[13] == (A[3] & A[2] & (~A[1]) & A[0])
    );

// Y[14] decodes input value 4'b1110.
    check_y14_decode: assert property (
        @(posedge clk) Y[14] == (A[3] & A[2] & A[1] & (~A[0]))
    );

// Y[15] decodes input value 4'b1111.
    check_y15_decode: assert property (
        @(posedge clk) Y[15] == (A[3] & A[2] & A[1] & A[0])
    );

// The decoder output is always one-hot.
    check_y_onehot: assert property (
        @(posedge clk) $onehot(Y)
    );

// The full output bus matches a 4-to-16 one-hot decode.
    check_y_full_decode: assert property (
        @(posedge clk) Y == (16'h0001 << A)
    );

// A low RESET_B on a rising GATE_N edge clears Q.
    check_reset_clears_q: assert property (
        @(posedge GATE_N) !RESET_B |=> (Q == 1'b0)
    );

// With reset inactive, D=1 on a rising GATE_N edge is captured into Q.
    check_capture_one: assert property (
        @(posedge GATE_N) disable iff (!RESET_B) D |=> (Q == 1'b1)
    );

// With reset inactive, D=0 on a rising GATE_N edge is captured into Q.
    check_capture_zero: assert property (
        @(posedge GATE_N) disable iff (!RESET_B) !D |=> (Q == 1'b0)
    );

// RTL is combinational; assertions sample on an external clock.

    // Output is the 4-bit two's complement of the input.
    check_exact_twos_complement: assert property (
        @(posedge clk) out == (~in + 4'b0001)
    );

// Input and output sum to zero modulo 16.
    check_additive_inverse: assert property (
        @(posedge clk) (in + out) == 4'h0
    );

// Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'h0) |-> (out == 4'h0)
    );

// 4'b1000 is its own two's complement.
    check_min_value_maps_to_self: assert property (
        @(posedge clk) (in == 4'h8) |-> (out == 4'h8)
    );

// Positive nonzero inputs produce a negative 4-bit result.
    check_positive_nonzero_sign_flip: assert property (
        @(posedge clk) ((in[3] == 1'b0) && (in != 4'h0)) |-> (out[3] == 1'b1)
    );

// Negative inputs other than 4'b1000 produce a positive 4-bit result.
    check_negative_nonmin_sign_flip: assert property (
        @(posedge clk) ((in[3] == 1'b1) && (in != 4'h8)) |-> (out[3] == 1'b0)
    );

// A sampled low reset forces the reset state by the next cycle.
    check_reset_state: assert property (
        @(posedge CLK)
        !RESET_B |=> ((Q == 1'b0) && (Q_B == 1'b1))
    );

// SCD sets the outputs when asserted alone.
    check_scd_sets_outputs: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SCD && !SCE) |=> ((Q == 1'b1) && (Q_B == 1'b0))
    );

// SCD has priority over SCE when both are asserted.
    check_scd_priority_over_sce: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SCD && SCE) |=> ((Q == 1'b1) && (Q_B == 1'b0))
    );

// SCE loads a 1 from D when SCD is low.
    check_sce_loads_one: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && SCE && D) |=> ((Q == 1'b1) && (Q_B == 1'b0))
    );

// SCE loads a 0 from D when SCD is low.
    check_sce_loads_zero: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && SCE && !D) |=> ((Q == 1'b0) && (Q_B == 1'b1))
    );

// With both controls low, the current state is held.
    check_hold_when_controls_low: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (!SCD && !SCE) |=> ((Q == $past(Q)) && (Q_B == $past(Q_B)))
    );

// Q reflects the D value sampled on the previous GATE rise.
    check_q_tracks_previous_d: assert property (
        @(posedge GATE) 1'b1 |=> (Q === $past(D))
    );

// A sampled high on D is observed as high on Q by the next GATE rise.
    check_q_captures_high_d: assert property (
        @(posedge GATE) (D === 1'b1) |=> (Q === 1'b1)
    );

// A sampled low on D is observed as low on Q by the next GATE rise.
    check_q_captures_low_d: assert property (
        @(posedge GATE) (D === 1'b0) |=> (Q === 1'b0)
    );

// Read busy is permanently deasserted.
    check_rd_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_BUSY == 1'b0)
    );

// Read MMU flags are permanently zero.
    check_rd_mmu_flags_constant_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_MMU_FLAGS == 12'h000)
    );

// Read hit is permanently deasserted.
    check_rd_hit_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_HIT == 1'b0)
    );

// Read data is permanently zero.
    check_rd_data_constant_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oRD_DATA == 32'h00000000)
    );

// Update busy is permanently deasserted.
    check_up_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oUP_BUSY == 1'b0)
    );

// Write busy is permanently deasserted.
    check_wr_busy_constant_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (oWR_BUSY == 1'b0)
    );

// Sync reset or remove clears the registered read valid on the next cycle.
    check_rd_valid_clears_on_sync_reset_or_remove: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (iRESET_SYNC || iREMOVE) |=> (oRD_VALID == 1'b0)
    );

// Without clear conditions, a high read request sets read valid on the next cycle.
    check_rd_valid_sets_from_rd_req: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iREMOVE && iRD_REQ) |=> (oRD_VALID == 1'b1)
    );

// Without clear conditions, a low read request clears read valid on the next cycle.
    check_rd_valid_clears_from_rd_req_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iREMOVE && !iRD_REQ) |=> (oRD_VALID == 1'b0)
    );

// Y matches the buffered NOR of B1, C1, D1, and A1&A2.
    check_y_boolean_function: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~((A1 & A2) | B1 | C1 | D1)
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        B1 |-> !Y
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        C1 |-> !Y
    );

// D1 high forces the NOR output low.
    check_d1_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        D1 |-> !Y
    );

// A1 and A2 high together force the NOR output low.
    check_a1_a2_forces_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && A2) |-> !Y
    );

// With all NOR input terms low, Y must be high.
    check_all_terms_low_gives_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (!B1 && !C1 && !D1 && !(A1 && A2)) |-> Y
    );

// A high Y implies every NOR input term is low.
    check_y_high_implies_all_terms_low: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |-> (!B1 && !C1 && !D1 && !(A1 && A2))
    );

// A low Y implies at least one NOR input term is high.
    check_y_low_implies_some_term_high: assert property (
        @(posedge clk) disable iff (1'b0)
        !Y |-> (B1 || C1 || D1 || (A1 && A2))
    );

// Upper output bits are zero because a 1-bit select is assigned into an 8-bit vector.
    check_dout_upper_bits_zero: assert property (
        @(posedge clk) Dout[7:1] === 7'b0
    );

// For valid selector values 0 through 9, Dout is the zero-extended selected input bit.
    check_valid_index_maps_selected_bit: assert property (
        @(posedge clk) (Din[7:0] <= 8'd9) |-> (Dout === {7'b0, Din[Din[7:0] + 32'd8]})
    );

// A selector value of 0 picks Din[8].
    check_selector_zero_uses_bit8: assert property (
        @(posedge clk) (Din[7:0] === 8'd0) |-> (Dout === {7'b0, Din[8]})
    );

// A selector value of 9 picks Din[17].
    check_selector_nine_uses_bit17: assert property (
        @(posedge clk) (Din[7:0] === 8'd9) |-> (Dout === {7'b0, Din[17]})
    );

// X must match the implemented OR-AND logic.
    check_output_equation: assert property (
        @(posedge clk) X == ((A1 || A2 || A3) && B1 && C1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// If all A inputs are low, X must be low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) (!A1 && !A2 && !A3) |-> !X
    );

// If any A is high with B1 and C1 high, X must be high.
    check_valid_high_condition: assert property (
        @(posedge clk) ((A1 || A2 || A3) && B1 && C1) |-> X
    );

// A high X requires B1, C1, and at least one A input high.
    check_x_high_requires_valid_inputs: assert property (
        @(posedge clk) X |-> (B1 && C1 && (A1 || A2 || A3))
    );

// button[1] has priority and selects the 0x5F gray value.
    check_button1_override_color: assert property (
        @(posedge clk) button[1] |=> (RGBcolor == 24'h5F5F5F)
    );

// Each clk update produces one of the five implemented RGB encodings.
    check_rgbcolor_valid_encoding: assert property (
        @(posedge clk) 1'b1 |=> (
            (RGBcolor == 24'h5F5F5F) ||
            (RGBcolor == 24'h7F0000) ||
            (RGBcolor == 24'h007F00) ||
            (RGBcolor == 24'h00007F) ||
            (RGBcolor == 24'h3F3F3F)
        )
    );

// A greater than B must produce the greater-than code.
    check_result_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

// A less than B must produce the less-than code.
    check_result_when_a_lt_b: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b10)
    );

// Equal inputs must produce the equal code.
    check_result_when_a_eq_b: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

// The greater-than code must only appear when A is greater than B.
    check_code_01_means_a_gt_b: assert property (
        @(posedge clk) (result == 2'b01) |-> (A > B)
    );

// The less-than code must only appear when A is less than B.
    check_code_10_means_a_lt_b: assert property (
        @(posedge clk) (result == 2'b10) |-> (A < B)
    );

// The equal code must only appear when A and B are equal.
    check_code_00_means_a_eq_b: assert property (
        @(posedge clk) (result == 2'b00) |-> (A == B)
    );

// The reserved encoding is never driven.
    check_result_encoding_valid: assert property (
        @(posedge clk) (result != 2'b11)
    );

// Out matches the implemented mux equation.
    check_mux_boolean_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        out == ((in0 & ~sel) | (in1 & sel))
    );

// When sel is low, out follows in0.
    check_sel_low_routes_in0: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 1'b0) |-> (out == in0)
    );

// When sel is high, out follows in1.
    check_sel_high_routes_in1: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 1'b1) |-> (out == in1)
    );

// If both inputs are low, out is low.
    check_both_inputs_low_drive_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b0 && in1 == 1'b0) |-> (out == 1'b0)
    );

// If both inputs are high, out is high.
    check_both_inputs_high_drive_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b1 && in1 == 1'b1) |-> (out == 1'b1)
    );

// With in0 high and in1 low, out is the inverse of sel.
    check_in0_high_in1_low_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b1 && in1 == 1'b0) |-> (out == ~sel)
    );

// With in0 low and in1 high, out matches sel.
    check_in0_low_in1_high_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b0 && in1 == 1'b1) |-> (out == sel)
    );

// The 5-bit result matches unsigned addition of a, b, and cin.
    check_total_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Sum bit 0 matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == fa_sum(a[0], b[0], cin)
    );

// Sum bit 1 matches the ripple carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == fa_sum(a[1], b[1], fa_cout(a[0], b[0], cin))
    );

// Sum bit 2 matches the ripple carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == fa_sum(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin)))
    );

// Sum bit 3 matches the ripple carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == fa_sum(a[3], b[3], fa_cout(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin))))
    );

// Carry out matches the final ripple-carry stage.
    check_cout_chain: assert property (
        @(posedge clk) cout == fa_cout(a[3], b[3], fa_cout(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin))))
    );

// Adding zero with cin low passes a through unchanged.
    check_passthrough_a: assert property (
        @(posedge clk) (b == 4'h0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero with cin low passes b through unchanged.
    check_passthrough_b: assert property (
        @(posedge clk) (a == 4'h0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// Zero plus zero produces cin in the LSB with no carry out.
    check_zero_plus_cin: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0) |-> (sum == {3'b000, cin} && cout == 1'b0)
    );

// Y equals EN-gated AND of A1, A2, A3, and A4.
    check_y_matches_enabled_and: assert property (
        @(posedge clk) Y == (EN & A1 & A2 & A3 & A4)
    );

// All inputs high with EN high drives Y high.
    check_all_high_drives_y_high: assert property (
        @(posedge clk) (EN & A1 & A2 & A3 & A4) |-> Y
    );

// Y high requires EN and all data inputs high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (EN & A1 & A2 & A3 & A4)
    );

// EN low forces Y low.
    check_en_low_forces_y_low: assert property (
        @(posedge clk) !EN |-> !Y
    );

// A1 low forces Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A2 low forces Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A3 low forces Y low.
    check_a3_low_forces_y_low: assert property (
        @(posedge clk) !A3 |-> !Y
    );

// A4 low forces Y low.
    check_a4_low_forces_y_low: assert property (
        @(posedge clk) !A4 |-> !Y
    );

// Output equals the 4-input NOR of A, B, C, and D.
    check_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

// If all inputs are low, the output must be high.
    check_all_inputs_low_gives_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

// A high input forces the output low.
    check_a_high_forces_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high input forces the output low.
    check_b_high_forces_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high input forces the output low.
    check_c_high_forces_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D high input forces the output low.
    check_d_high_forces_low: assert property (
        @(posedge clk) D |-> !Y
    );

// A high output requires all inputs to be low.
    check_y_high_requires_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

// A low output requires at least one input to be high.
    check_y_low_requires_some_input_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D)
    );

// X implements (~A_N) & (~B_N) & C & D.
    check_boolean_function: assert property (
        @(posedge clk) X == ((~A_N) & (~B_N) & C & D)
    );

// X can only be high when all four effective AND terms are high.
    check_x_high_only_when_enabled: assert property (
        @(posedge clk) X |-> (!A_N && !B_N && C && D)
    );

// X must be high when all four effective AND terms are high.
    check_x_high_when_all_terms_high: assert property (
        @(posedge clk) (!A_N && !B_N && C && D) |-> X
    );

// A_N high forces X low.
    check_a_n_blocks_output: assert property (
        @(posedge clk) A_N |-> !X
    );

// B_N high forces X low.
    check_b_n_blocks_output: assert property (
        @(posedge clk) B_N |-> !X
    );

// C low forces X low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) !C |-> !X
    );

// D low forces X low.
    check_d_low_blocks_output: assert property (
        @(posedge clk) !D |-> !X
    );

// Synchronous reset clears both outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (count == 4'd0) && (overflow == 1'b0)
    );

// Count wraps to zero after reaching 15.
    check_wrap_count: assert property (
        @(posedge clk) disable iff (reset) (count == 4'd15) |=> (count == 4'd0)
    );

// Overflow is asserted when the count wraps from 15.
    check_wrap_sets_overflow: assert property (
        @(posedge clk) disable iff (reset) (count == 4'd15) |=> (overflow == 1'b1)
    );

// Count increments by one when below 15.
    check_increment_count: assert property (
        @(posedge clk) disable iff (reset) (count != 4'd15) |=> (count == ($past(count) + 4'd1))
    );

// Overflow stays low on non-wrap increments.
    check_increment_clears_overflow: assert property (
        @(posedge clk) disable iff (reset) (count != 4'd15) |=> (overflow == 1'b0)
    );

// Sum equals the 4-bit addition of A and B.
    check_sum_matches_addition: assert property (
        @(posedge clk) Sum == (A + B)
    );

// Bit 0 is the XOR of the input LSBs.
    check_sum_bit0: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0])
    );

// Bit 1 includes the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) Sum[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

// Bit 2 includes the carry propagated from lower bits.
    check_sum_bit2: assert property (
        @(posedge clk) Sum[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

// Bit 3 includes the carry propagated from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) Sum[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

// A zero A operand passes B through to Sum.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'b0000) |-> (Sum == B)
    );

// A zero B operand passes A through to Sum.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'b0000) |-> (Sum == A)
    );

// X matches the RTL combinational equation.
    check_x_matches_rtl: assert property (
        @(posedge clk)
        X == ((A && B) || (C || D) || !(E && F) || !(G || H))
    );

// A and B both high force X high.
    check_x_high_when_ab_high: assert property (
        @(posedge clk)
        (A && B) |-> X
    );

// Either C or D high forces X high.
    check_x_high_when_cd_high: assert property (
        @(posedge clk)
        (C || D) |-> X
    );

// If E and F are not both high, X must be high.
    check_x_high_when_ef_not_both_high: assert property (
        @(posedge clk)
        !(E && F) |-> X
    );

// If G and H are both low, X must be high.
    check_x_high_when_gh_both_low: assert property (
        @(posedge clk)
        !(G || H) |-> X
    );

// X low requires all four RTL terms to be false.
    check_x_low_implies_false_terms: assert property (
        @(posedge clk)
        !X |-> (!(A && B) && !(C || D) && (E && F) && (G || H))
    );

// If all four RTL terms are false, X must be low.
    check_x_low_when_false_terms: assert property (
        @(posedge clk)
        (!(A && B) && !(C || D) && (E && F) && (G || H)) |-> !X
    );

// No RTL reset is present; sample this combinational logic on clk.

    // Y matches the implemented not/and/nor function.
    check_y_matches_logic: assert property (
        @(posedge clk) Y == ~(~B1_N | (A1 & A2))
    );

// Low B1_N forces Y low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) !B1_N |-> (Y == 1'b0)
    );

// High A1 and A2 force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> (Y == 1'b0)
    );

// With B1_N high and A1 low, Y must be high.
    check_b1n_high_a1_low_gives_y_high: assert property (
        @(posedge clk) (B1_N && !A1) |-> (Y == 1'b1)
    );

// With B1_N high and A2 low, Y must be high.
    check_b1n_high_a2_low_gives_y_high: assert property (
        @(posedge clk) (B1_N && !A2) |-> (Y == 1'b1)
    );

// High Y requires B1_N to be high.
    check_y_high_requires_b1n_high: assert property (
        @(posedge clk) Y |-> B1_N
    );

// High Y requires the A1/A2 AND term to be low.
    check_y_high_requires_and_term_low: assert property (
        @(posedge clk) Y |-> !(A1 && A2)
    );

// With B1_N high, low Y implies both A inputs are high.
    check_b1n_high_y_low_requires_a1_a2_high: assert property (
        @(posedge clk) (B1_N && !Y) |-> (A1 && A2)
    );

// max_tick is asserted exactly when q is all ones.
    check_max_tick_decode: assert property (
        @(posedge clk) disable iff (rst) max_tick == (q == MAX_VAL)
    );

// min_tick is asserted exactly when q is zero.
    check_min_tick_decode: assert property (
        @(posedge clk) disable iff (rst) min_tick == (q == ZERO_VAL)
    );

// max_tick and min_tick cannot be high at the same time.
    check_ticks_mutually_exclusive: assert property (
        @(posedge clk) disable iff (rst) !(max_tick && min_tick)
    );

// When select is high, out uses b and the d-c difference.
    check_select_high_formula: assert property (
        @(posedge clk) disable iff (reset)
        select |-> (out == (b + (d - c)))
    );

// When select is low, out uses c and the c-d difference.
    check_select_low_formula: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (out == (c + (c - d)))
    );

// Equal c and d make the difference zero in the select-high case.
    check_zero_diff_select_high: assert property (
        @(posedge clk) disable iff (reset)
        (select && (c == d)) |-> (out == b)
    );

// Equal c and d make the difference zero in the select-low case.
    check_zero_diff_select_low: assert property (
        @(posedge clk) disable iff (reset)
        (!select && (c == d)) |-> (out == c)
    );

// X must match the NOR(A_N,B_N) then AND with C and D.
    check_function_equivalence: assert property (
        @(posedge clk) (X == ((~(A_N | B_N)) & C & D))
    );

// A_N high forces the output low.
    check_a_n_blocks_output: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

// B_N high forces the output low.
    check_b_n_blocks_output: assert property (
        @(posedge clk) (B_N == 1'b1) |-> (X == 1'b0)
    );

// C low forces the output low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == 1'b0)
    );

// D low forces the output low.
    check_d_low_blocks_output: assert property (
        @(posedge clk) (D == 1'b0) |-> (X == 1'b0)
    );

// The single enabling input combination drives X high.
    check_enabling_combination_sets_output: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1)) |-> (X == 1'b1)
    );

// A high output implies both inverted inputs are low and C/D are high.
    check_output_high_implies_inputs: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

// Y matches the RTL equation each sampled cycle.
    check_y_matches_rtl_equation: assert property (
        @(posedge clk)
        Y == ((A1 ^ A2) ? ~B1 : ((A1 & A2) ? B1 : (A1 & A2)))
    );

// When A1 and A2 differ, Y is the inverse of B1.
    check_y_inverts_b1_when_a_inputs_differ: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> (Y == ~B1)
    );

// When A1 and A2 are both high, Y follows B1.
    check_y_follows_b1_when_a_inputs_high: assert property (
        @(posedge clk)
        (A1 & A2) |-> (Y == B1)
    );

// When A1 and A2 are both low, Y is low.
    check_y_low_when_a_inputs_low: assert property (
        @(posedge clk)
        (!A1 && !A2) |-> (Y == 1'b0)
    );

// With B1 high, Y reduces to A1 and A2.
    check_y_equals_and_when_b1_high: assert property (
        @(posedge clk)
        B1 |-> (Y == (A1 & A2))
    );

// With B1 low, Y reduces to A1 xor A2.
    check_y_equals_xor_when_b1_low: assert property (
        @(posedge clk)
        !B1 |-> (Y == (A1 ^ A2))
    );

// The 5-bit output matches the arithmetic sum of a, b, and cin.
    check_total_sum: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// sum[0] is the full-adder sum bit for a[0], b[0], and cin.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// sum[1] uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))
        )
    );

// sum[2] uses the carry generated by bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (a[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))) |
                (b[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
            )
        )
    );

// Y must match the implemented OR-of-products equation.
    check_y_logic_equation: assert property (
        @(posedge clk) Y == ((A1 & A2) | (B1 & ~(A1 & A2)))
    );

// When both A inputs are high, Y must be high.
    check_y_high_when_a1_a2_high: assert property (
        @(posedge clk) (A1 & A2) |-> Y
    );

// When A1&A2 is low, Y must follow B1.
    check_y_follows_b1_when_a_term_low: assert property (
        @(posedge clk) ~(A1 & A2) |-> (Y == B1)
    );

// A high B1 must drive Y high.
    check_y_high_when_b1_high: assert property (
        @(posedge clk) B1 |-> Y
    );

// With B1 low and A1 low, Y must be low.
    check_y_low_when_b1_low_and_a1_low: assert property (
        @(posedge clk) (~B1 & ~A1) |-> ~Y
    );

// With B1 low and A2 low, Y must be low.
    check_y_low_when_b1_low_and_a2_low: assert property (
        @(posedge clk) (~B1 & ~A2) |-> ~Y
    );

// A low Y can only occur when B1 is low and A1&A2 is low.
    check_y_low_condition: assert property (
        @(posedge clk) ~Y |-> (~B1 & ~(A1 & A2))
    );

// Reset forces count to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

// With enable low and count at 0, the next count stays 0.
    check_zero_state_clears: assert property (
        @(posedge clk) disable iff (reset)
        (!enable && (count == 4'b0000)) |=> (count == 4'b0000)
    );

// With enable low and count at 1, the next count increments to 2.
    check_one_state_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!enable && (count == 4'b0001)) |=> (count == 4'b0010)
    );

// With enable low and count at 9, the next count clears to 0.
    check_nine_state_clears: assert property (
        @(posedge clk) disable iff (reset)
        (!enable && (count == 4'b1001)) |=> (count == 4'b0000)
    );

// With enable high, count holds its value.
    check_enable_high_holds: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> $stable(count)
    );

// With enable low and unmatched counts, count holds its value.
    check_unmatched_cases_hold: assert property (
        @(posedge clk) disable iff (reset)
        (!enable && (count != 4'b0000) && (count != 4'b0001) && (count != 4'b1001)) |=> $stable(count)
    );

// A load makes the next sampled serial output equal to the loaded MSB.
    check_load_updates_msb: assert property (
        @(posedge CLK) LOAD |=> (SER_OUT == $past(PAR_IN[31]))
    );

// One shift after a load exposes PAR_IN[30] on the serial output.
    check_first_shift_exposes_bit30: assert property (
        @(posedge CLK) (LOAD ##1 !LOAD) |=> (SER_OUT == $past(PAR_IN[30], 2))
    );

// Two shifts after a load expose PAR_IN[29] on the serial output.
    check_second_shift_exposes_bit29: assert property (
        @(posedge CLK) (LOAD ##1 !LOAD ##1 !LOAD) |=> (SER_OUT == $past(PAR_IN[29], 3))
    );

// Thirty-one shifts after a load expose PAR_IN[0] on the serial output.
    check_thirty_one_shifts_expose_bit0: assert property (
        @(posedge CLK) (LOAD ##1 (!LOAD[*31])) |=> (SER_OUT == $past(PAR_IN[0], 32))
    );

// Thirty-two shifts after a load expose the first shifted-in serial bit.
    check_thirty_two_shifts_expose_first_serial_in: assert property (
        @(posedge CLK) (LOAD ##1 (!LOAD[*32])) |=> (SER_OUT == $past(SER_IN, 32))
    );

// count must match the implemented reduction-NAND expression.
    check_count_matches_expression: assert property (
        @(posedge clk) count == {(~&data[2:1]), (~&data[1:0])}
    );

// count[1] must be the NAND reduction of data[2:1].
    check_count_msb_definition: assert property (
        @(posedge clk) count[1] == (~&data[2:1])
    );

// count[0] must be the NAND reduction of data[1:0].
    check_count_lsb_definition: assert property (
        @(posedge clk) count[0] == (~&data[1:0])
    );

// b must equal a XOR c on every sampled cycle.
    check_xor_function: assert property (
        @(posedge clk) b == (a ^ c)
    );

// Bit 0 of b must be the inverse of bit 0 of a.
    check_b0_inverts_a0: assert property (
        @(posedge clk) b[0] == ~a[0]
    );

// Bit 3 of b must be the inverse of bit 3 of a.
    check_b3_inverts_a3: assert property (
        @(posedge clk) b[3] == ~a[3]
    );

// XOR with the same constant must recover the original input.
    check_inverse_mapping: assert property (
        @(posedge clk) a == (b ^ c)
    );

// Count follows the RTL next-state function on every cycle.
    check_count_transition_relation: assert property (
        @(posedge clk) 1'b1 |=> count == ($past(load) ? $past(data) : ($past(count) + 8'd1))
    );

// A high load causes count to take the input data.
    check_load_updates_count: assert property (
        @(posedge clk) load |=> count == $past(data)
    );

// A low load causes count to increment by one.
    check_increment_updates_count: assert property (
        @(posedge clk) !load |=> count == ($past(count) + 8'd1)
    );

// Incrementing from 8'hFF wraps count back to 8'h00.
    check_increment_wraps_on_overflow: assert property (
        @(posedge clk) (!load && (count == 8'hFF)) |=> count == 8'h00
    );

// A clock sampled during reset forces result to zero by the next sample.
    check_reset_clears_result: assert property (
        @(posedge clk) !reset_n |=> (result == 32'd0)
    );

// Addition updates result with operand1 + operand2.
    check_add_result: assert property (
        @(posedge clk) disable iff (!reset_n)
        (operation == 2'b00) |=> (result == (($past(operand1) + $past(operand2)) & 32'hFFFF_FFFF))
    );

// Subtraction updates result with operand1 - operand2.
    check_sub_result: assert property (
        @(posedge clk) disable iff (!reset_n)
        (operation == 2'b01) |=> (result == (($past(operand1) - $past(operand2)) & 32'hFFFF_FFFF))
    );

// Sampling clock only; RTL has no native clock or reset.

    // X must equal the implemented OR of all input terms.
    check_functional_equivalence: assert property (
        @(posedge clk)
        X == (A | B | ~C_N | ~D_N | VPWR | VGND | VPB | VNB)
    );

// A or B high forces X high.
    check_a_or_b_drives_high: assert property (
        @(posedge clk)
        (A || B) |-> (X == 1'b1)
    );

// C_N low is an active-low term that drives X high.
    check_c_n_active_low: assert property (
        @(posedge clk)
        (!C_N) |-> (X == 1'b1)
    );

// D_N low is an active-low term that drives X high.
    check_d_n_active_low: assert property (
        @(posedge clk)
        (!D_N) |-> (X == 1'b1)
    );

// Any power or bulk input high forces X high in this RTL.
    check_power_or_bulk_drives_high: assert property (
        @(posedge clk)
        (VPWR || VGND || VPB || VNB) |-> (X == 1'b1)
    );

// With all OR terms inactive, X must be low.
    check_all_terms_inactive_drives_low: assert property (
        @(posedge clk)
        (!A && !B && C_N && D_N && !VPWR && !VGND && !VPB && !VNB) |-> (X == 1'b0)
    );

// If X is low, every OR term must be inactive.
    check_x_low_implies_all_terms_inactive: assert property (
        @(posedge clk)
        (X == 1'b0) |-> (!A && !B && C_N && D_N && !VPWR && !VGND && !VPB && !VNB)
    );

// Addition mode computes the sum and clears the other outputs.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((add_out == s8_t'(a + b)) &&
                           (sub_out == 8'sd0) &&
                           (mul_out == 8'sd0) &&
                           (div_out == 8'sd0))
    );

// Subtraction mode computes the difference and clears the other outputs.
    check_subtraction_mode: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((add_out == 8'sd0) &&
                           (sub_out == s8_t'(a - b)) &&
                           (mul_out == 8'sd0) &&
                           (div_out == 8'sd0))
    );

// add_out is cleared whenever addition is not selected.
    check_add_out_cleared_when_not_add: assert property (
        @(posedge clk)
        (op != 2'b00) |-> (add_out == 8'sd0)
    );

// sub_out is cleared whenever subtraction is not selected.
    check_sub_out_cleared_when_not_sub: assert property (
        @(posedge clk)
        (op != 2'b01) |-> (sub_out == 8'sd0)
    );

// mul_out is cleared whenever multiplication is not selected.
    check_mul_out_cleared_when_not_mul: assert property (
        @(posedge clk)
        (op != 2'b10) |-> (mul_out == 8'sd0)
    );

// div_out is cleared whenever division is not selected.
    check_div_out_cleared_when_not_div: assert property (
        @(posedge clk)
        (op != 2'b11) |-> (div_out == 8'sd0)
    );

// Output matches the 4-bit subtraction of A and B.
    check_subtract_function: assert property (
        @(posedge clk) disable iff (1'b0) Y == (A - B)
    );

// Adding B back to Y recovers A modulo 16.
    check_add_back_recovers_a: assert property (
        @(posedge clk) disable iff (1'b0) (Y + B) == A
    );

// Equal operands produce a zero result.
    check_equal_inputs_zero: assert property (
        @(posedge clk) disable iff (1'b0) (A == B) |-> (Y == 4'h0)
    );

// Subtracting zero passes A through unchanged.
    check_zero_subtrahend_passthrough: assert property (
        @(posedge clk) disable iff (1'b0) (B == 4'h0) |-> (Y == A)
    );

// Zero minus B produces the wrapped 4-bit result.
    check_zero_minuend_wrap: assert property (
        @(posedge clk) disable iff (1'b0) (A == 4'h0) |-> (Y == (4'h0 - B))
    );

// Qa captures D on the next rising clock edge.
    check_qa_captures_d: assert property (
        @(posedge Clk) disable iff (1'b0)
        1'b1 |=> (Qa == $past(D))
    );

// Qb captures Qa on the next rising clock edge.
    check_qb_captures_qa: assert property (
        @(posedge Clk) disable iff (1'b0)
        1'b1 |=> (Qb == $past(Qa))
    );

// Qc captures Qb on the next rising clock edge.
    check_qc_captures_qb: assert property (
        @(posedge Clk) disable iff (1'b0)
        1'b1 |=> (Qc == $past(Qb))
    );

// Qb is D delayed by two rising clock edges.
    check_qb_is_d_delayed_two_cycles: assert property (
        @(posedge Clk) disable iff (1'b0)
        1'b1 |=> ##1 (Qb == $past(D, 2))
    );

// Qc is D delayed by three rising clock edges.
    check_qc_is_d_delayed_three_cycles: assert property (
        @(posedge Clk) disable iff (1'b0)
        1'b1 |=> ##2 (Qc == $past(D, 3))
    );

// Constantb is always low because Func1 is contradictory.
    check_constantb_tied_low: assert property (
        @(posedge clk) Constantb == 1'b0
    );

// Constantc is always low because Func1 is contradictory.
    check_constantc_tied_low: assert property (
        @(posedge clk) Constantc == 1'b0
    );

// Constantd directly reflects Func1, which is always low.
    check_constantd_tied_low: assert property (
        @(posedge clk) Constantd == 1'b0
    );

// Constante matches the Func0 and DBnotSN decode.
    check_constante_decode: assert property (
        @(posedge clk) Constante == (RomExpConCtl[0] & ~RomExpConCtl[1] & DBnotSN)
    );

// Constantf matches the simplified Func0 decode.
    check_constantf_decode: assert property (
        @(posedge clk) Constantf == (RomExpConCtl[0] & ~RomExpConCtl[1])
    );

// Constantg matches the Func0 and SNnotDB decode.
    check_constantg_decode: assert property (
        @(posedge clk) Constantg == (RomExpConCtl[0] & ~RomExpConCtl[1] & SNnotDB)
    );

// Constanth is the inversion of the Func0 and SNnotDB term.
    check_constanth_decode: assert property (
        @(posedge clk) Constanth == ~(RomExpConCtl[0] & ~RomExpConCtl[1] & SNnotDB)
    );

// Constantg is the logical complement of Constanth.
    check_constantg_complements_constanth: assert property (
        @(posedge clk) Constantg == ~Constanth
    );

// Constante can only be high when Constantf is high.
    check_constante_implies_constantf: assert property (
        @(posedge clk) Constante |-> Constantf
    );

// Constantg can only be high when Constantf is high.
    check_constantg_implies_constantf: assert property (
        @(posedge clk) Constantg |-> Constantf
    );

// X must equal the AND of A and SLEEP_B.
    check_and_equivalence: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// SLEEP_B low forces X low.
    check_sleep_forces_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// When not sleeping, X must follow A.
    check_awake_passes_a: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// A low forces X low.
    check_low_a_forces_low_output: assert property (
        @(posedge clk) !A |-> !X
    );

// X high requires both A and SLEEP_B high.
    check_high_output_requires_both_inputs: assert property (
        @(posedge clk) X |-> (A & SLEEP_B)
    );

// A and SLEEP_B high drives X high.
    check_both_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A & SLEEP_B) |-> X
    );

// Reset forces the registered output low.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 8'b00000000)
    );

// In bypass mode, out captures the zero-extended muxed data.
    check_bypass_mode_output: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |=> (
            out == {
                4'b0000,
                selected_data(
                    $past(sel),
                    $past(data0),
                    $past(data1),
                    $past(data2),
                    $past(data3),
                    $past(data4),
                    $past(data5)
                )
            }
        )
    );

// In add mode, out captures the muxed data plus add_in.
    check_add_mode_output: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |=> (
            out == (
                {
                    4'b0000,
                    selected_data(
                        $past(sel),
                        $past(data0),
                        $past(data1),
                        $past(data2),
                        $past(data3),
                        $past(data4),
                        $past(data5)
                    )
                } + {6'b000000, $past(add_in)}
            )
        )
    );

// Bypass mode always zero-extends into the upper nibble.
    check_bypass_zero_extension: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |=> (out[7:4] == 4'b0000)
    );

// Add mode always zero-extends into the upper two bits.
    check_add_mode_zero_extension: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |=> (out[7:6] == 2'b00)
    );

// Invalid mux select codes produce zero in bypass mode.
    check_invalid_sel_bypass_zero: assert property (
        @(posedge clk) disable iff (reset)
        ((select == 1'b0) && ((sel == 3'b110) || (sel == 3'b111))) |=> (out == 8'b00000000)
    );

// Invalid mux select codes add only add_in in add mode.
    check_invalid_sel_add_uses_add_in_only: assert property (
        @(posedge clk) disable iff (reset)
        ((select == 1'b1) && ((sel == 3'b110) || (sel == 3'b111))) |=> (out == {6'b000000, $past(add_in)})
    );

// AB=00 drives F with the parity of C, D, and E.
    check_ab00_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b0) && (B == 1'b0)) |-> (F === (C ^ D ^ E))
    );

// AB=01 drives F with the inverted parity of C, D, and E.
    check_ab01_inverted_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b0) && (B == 1'b1)) |-> (F === ~(C ^ D ^ E))
    );

// AB=10 drives F with the parity of C, D, and E.
    check_ab10_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b1) && (B == 1'b0)) |-> (F === (C ^ D ^ E))
    );

// AB=11 drives F with the inverted parity of C, D, and E.
    check_ab11_inverted_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b1) && (B == 1'b1)) |-> (F === ~(C ^ D ^ E))
    );

// Overall, F reduces to B xor C xor D xor E.
    check_overall_xor_function: assert property (
        @(posedge clk)
        !$isunknown({A,B,C,D,E}) |-> (F === (B ^ C ^ D ^ E))
    );

// DUT is combinational with no reset; sample outputs on clk.

    // Gray bit 0 directly matches binary bit 0.
    check_gray_bit0: assert property (
        @(posedge clk) gray_output[0] == binary_input[0]
    );

// Gray bit 1 is the XOR of binary bits 0 and 1.
    check_gray_bit1: assert property (
        @(posedge clk) gray_output[1] == (binary_input[0] ^ binary_input[1])
    );

// Gray bit 2 is the XOR of binary bits 1 and 2.
    check_gray_bit2: assert property (
        @(posedge clk) gray_output[2] == (binary_input[1] ^ binary_input[2])
    );

// Gray bit 3 is the XOR of binary bits 2 and 3.
    check_gray_bit3: assert property (
        @(posedge clk) gray_output[3] == (binary_input[2] ^ binary_input[3])
    );

// The full output vector matches the implemented binary-to-gray mapping.
    check_gray_vector: assert property (
        @(posedge clk) gray_output == {binary_input[2] ^ binary_input[3],
                                      binary_input[1] ^ binary_input[2],
                                      binary_input[0] ^ binary_input[1],
                                      binary_input[0]}
    );

// X implements B1 OR the 4-input AND of A1-A4.
    check_x_matches_function: assert property (
        @(posedge clk) X == (B1 || (A1 && A2 && A3 && A4))
    );

// B1 being high is sufficient to drive X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// All four A inputs high is sufficient to drive X high.
    check_all_a_high_forces_x_high: assert property (
        @(posedge clk) (A1 && A2 && A3 && A4) |-> X
    );

// With B1 low, any low A input forces X low.
    check_no_b1_and_any_a_low_forces_x_low: assert property (
        @(posedge clk) (!B1 && (!A1 || !A2 || !A3 || !A4)) |-> !X
    );

// If X is high, it must come from B1 or the 4-input AND.
    check_x_high_implies_valid_source: assert property (
        @(posedge clk) X |-> (B1 || (A1 && A2 && A3 && A4))
    );

// If X is low, B1 is low and the 4-input AND is not satisfied.
    check_x_low_implies_no_valid_source: assert property (
        @(posedge clk) !X |-> (!B1 && (!A1 || !A2 || !A3 || !A4))
    );

// Opcode 00 selects the 4-bit sum.
    check_add_opcode_selects_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b00) |-> (result == (A + B))
    );

// Opcode 01 selects the 4-bit difference.
    check_sub_opcode_selects_difference: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b01) |-> (result == (A - B))
    );

// Opcode 10 selects the bitwise AND.
    check_and_opcode_selects_and: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b10) |-> (result == (A & B))
    );

// Opcode 11 selects the bitwise OR.
    check_or_opcode_selects_or: assert property (
        @(posedge clk) disable iff (1'b0)
        (opcode == 2'b11) |-> (result == (A | B))
    );

// X matches the OR of A, B, and C.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// X is low when all inputs are low.
    check_all_inputs_low_drive_low: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// A alone drives X high.
    check_a_only_drives_high: assert property (
        @(posedge clk) (A && !B && !C) |-> X
    );

// B alone drives X high.
    check_b_only_drives_high: assert property (
        @(posedge clk) (!A && B && !C) |-> X
    );

// C alone drives X high.
    check_c_only_drives_high: assert property (
        @(posedge clk) (!A && !B && C) |-> X
    );

// A high X must be caused by at least one high input.
    check_output_high_has_high_input: assert property (
        @(posedge clk) X |-> (A || B || C)
    );

// select 00 routes data_in[0] to data_out.
    check_select_00_routes_bit0: assert property (
        @(posedge clk) (select === 2'b00) |-> (data_out === data_in[0])
    );

// select 01 routes data_in[1] to data_out.
    check_select_01_routes_bit1: assert property (
        @(posedge clk) (select === 2'b01) |-> (data_out === data_in[1])
    );

// select 10 routes data_in[2] to data_out.
    check_select_10_routes_bit2: assert property (
        @(posedge clk) (select === 2'b10) |-> (data_out === data_in[2])
    );

// select 11 routes data_in[3] to data_out.
    check_select_11_routes_bit3: assert property (
        @(posedge clk) (select === 2'b11) |-> (data_out === data_in[3])
    );

// Out must match the mux RTL equation.
    check_mux_truth_table: assert property (
        @(posedge clk) out === ((sel == 1'b0) ? in0 : in1)
    );

// Select low routes in0 to out.
    check_sel_zero_routes_in0: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === in0)
    );

// Select high routes in1 to out.
    check_sel_one_routes_in1: assert property (
        @(posedge clk) (sel === 1'b1) |-> (out === in1)
    );

// Equal data inputs force the same sampled output.
    check_equal_inputs_force_output: assert property (
        @(posedge clk) (in0 === in1) |-> (out === in0)
    );

// Clock: external sampling clk. Reset: none in RTL. Logic: combinational decode.

    // JMP decodes opcode 000010.
    check_jmp_decode: assert property (
        @(posedge clk) (JMP == (opcode == 6'b000010))
    );

// RegDst decodes opcode 000000.
    check_regdst_decode: assert property (
        @(posedge clk) (RegDst == (opcode == 6'b000000))
    );

// MemToReg decodes opcode 100011.
    check_memtoreg_decode: assert property (
        @(posedge clk) (MemToReg == (opcode == 6'b100011))
    );

// MemWrite decodes opcode 101011.
    check_memwrite_decode: assert property (
        @(posedge clk) (MemWrite == (opcode == 6'b101011))
    );

// Branch decodes opcode 000100.
    check_branch_decode: assert property (
        @(posedge clk) (Branch == (opcode == 6'b000100))
    );

// ALUop1 matches the R-type decode.
    check_aluop1_decode: assert property (
        @(posedge clk) (ALUop1 == (opcode == 6'b000000))
    );

// ALUop0 matches the BEQ decode.
    check_aluop0_decode: assert property (
        @(posedge clk) (ALUop0 == (opcode == 6'b000100))
    );

// ALUsrcB is asserted for LW and SW only.
    check_alusrcb_decode: assert property (
        @(posedge clk) (ALUsrcB == ((opcode == 6'b100011) || (opcode == 6'b101011)))
    );

// RegDst and ALUop1 are driven by the same decode.
    check_aluop1_matches_regdst: assert property (
        @(posedge clk) (ALUop1 == RegDst)
    );

// Branch and ALUop0 are driven by the same decode.
    check_aluop0_matches_branch: assert property (
        @(posedge clk) (ALUop0 == Branch)
    );

// ALUsrcB is the OR of MemToReg and MemWrite.
    check_alusrcb_relation: assert property (
        @(posedge clk) (ALUsrcB == (MemToReg || MemWrite))
    );

// A reset clock edge clears the counter by the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// On consecutive non-reset cycles, the counter increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!reset ##1 !reset) |-> (count == ($past(count) + 4'd1))
    );

// A max count value wraps to zero on the next non-reset cycle.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        ((count == 4'hF) ##1 !reset) |-> (count == 4'h0)
    );

// Lower 16 bits always add a, b, and cin.
    check_lower_half_sum: assert property (
        @(posedge clk)
        z[15:0] == (a[15:0] + b[15:0] + cin)
    );

// In split mode, both halves add independently with the same cin.
    check_split_mode_full_output: assert property (
        @(posedge clk)
        !add32 |-> (z == {(a[31:16] + b[31:16] + cin), (a[15:0] + b[15:0] + cin)})
    );

// In 32-bit mode, the output matches a full 32-bit add.
    check_add32_mode_full_sum: assert property (
        @(posedge clk)
        add32 |-> (z == (a + b + cin))
    );

// In 32-bit mode, a carry from bit 15 increments the upper half.
    check_add32_upper_with_lower_carry: assert property (
        @(posedge clk)
        add32 && (({1'b0, a[15:0]} + {1'b0, b[15:0]} + cin) >= 17'h10000)
        |-> (z[31:16] == (a[31:16] + b[31:16] + 16'h0001))
    );

// In 32-bit mode, no carry from bit 15 leaves the upper half unincremented.
    check_add32_upper_without_lower_carry: assert property (
        @(posedge clk)
        add32 && (({1'b0, a[15:0]} + {1'b0, b[15:0]} + cin) < 17'h10000)
        |-> (z[31:16] == (a[31:16] + b[31:16]))
    );

// In split mode, lower-half carry does not affect the upper half.
    check_split_mode_ignores_lower_carry: assert property (
        @(posedge clk)
        !add32 && (({1'b0, a[15:0]} + {1'b0, b[15:0]} + cin) >= 17'h10000)
        |-> (z[31:16] == (a[31:16] + b[31:16] + cin))
    );

// y must implement the XOR of a and b.
    check_xor_function: assert property (
        @(posedge clk) y == (a ^ b)
    );

// When both inputs are low, y must be low.
    check_y_low_for_00: assert property (
        @(posedge clk) (!a && !b) |-> !y
    );

// When only b is high, y must be high.
    check_y_high_for_01: assert property (
        @(posedge clk) (!a && b) |-> y
    );

// When only a is high, y must be high.
    check_y_high_for_10: assert property (
        @(posedge clk) (a && !b) |-> y
    );

// When both inputs are high, y must be low.
    check_y_low_for_11: assert property (
        @(posedge clk) (a && b) |-> !y
    );

// Non-terminal count increments by one on the next clock.
    check_counter_increments: assert property (
        @(posedge clk)
        (counter != 25'd1250000) |=> (counter == ($past(counter) + 25'd1))
    );

// slower_clk holds its value when the terminal count is not reached.
    check_slower_clk_holds_between_toggles: assert property (
        @(posedge clk)
        (counter != 25'd1250000) |=> (slower_clk == $past(slower_clk))
    );

// Terminal count forces the counter back to zero on the next clock.
    check_counter_resets_at_terminal_count: assert property (
        @(posedge clk)
        (counter == 25'd1250000) |=> (counter == 25'd0)
    );

// Terminal count toggles slower_clk on the next clock.
    check_slower_clk_toggles_at_terminal_count: assert property (
        @(posedge clk)
        (counter == 25'd1250000) |=> (slower_clk == ~$past(slower_clk))
    );

// Z must equal the AND of all four inputs.
    check_z_matches_four_input_and: assert property (
        @(posedge clk) Z == (A & B & C & D)
    );

// If all inputs are high, Z must be high.
    check_all_high_implies_z_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Z
    );

// If any input is low, Z must be low.
    check_any_low_implies_z_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !Z
    );

// Z can only be high when all inputs are high.
    check_z_high_requires_all_high: assert property (
        @(posedge clk) Z |-> (A & B & C & D)
    );

// Reset forces readdata to zero.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

// Address 0 with in_port high updates readdata to 1 on the next cycle.
    check_addr0_high_sets_one: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00 && in_port) |=> (readdata == 32'h00000001)
    );

// Address 0 with in_port low updates readdata to 0 on the next cycle.
    check_addr0_low_sets_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00 && !in_port) |=> (readdata == 32'h00000000)
    );

// Any nonzero address updates readdata to 0 on the next cycle.
    check_nonzero_address_sets_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 32'h00000000)
    );

// Active updates always clear the upper 31 bits.
    check_upper_bits_zero_after_update: assert property (
        @(posedge clk) disable iff (!reset_n)
        1'b1 |=> (readdata[31:1] == 31'b0)
    );

// X matches the implemented gate-level expression.
    check_x_matches_gate_expression: assert property (
        @(posedge clk)
        X == ((A1 | A2) & (A2 | A3) & (A1 | A3) & B1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk)
        !B1 |-> !X
    );

// X high requires B1 high.
    check_x_requires_b1_high: assert property (
        @(posedge clk)
        X |-> B1
    );

// A1 and A2 high with B1 high drive X high.
    check_a1_a2_pair_drives_x: assert property (
        @(posedge clk)
        (B1 && A1 && A2) |-> X
    );

// A1 and A3 high with B1 high drive X high.
    check_a1_a3_pair_drives_x: assert property (
        @(posedge clk)
        (B1 && A1 && A3) |-> X
    );

// A2 and A3 high with B1 high drive X high.
    check_a2_a3_pair_drives_x: assert property (
        @(posedge clk)
        (B1 && A2 && A3) |-> X
    );

// Fewer than two asserted A inputs keep X low when B1 is high.
    check_insufficient_a_inputs_keep_x_low: assert property (
        @(posedge clk)
        (B1 && !((A1 & A2) | (A1 & A3) | (A2 & A3))) |-> !X
    );

// X high requires at least one asserted pair of A inputs.
    check_x_requires_two_a_inputs: assert property (
        @(posedge clk)
        X |-> ((A1 & A2) | (A1 & A3) | (A2 & A3))
    );

// Synchronous reset loads out high on the following clock sample.
    check_reset_loads_out_high: assert property (
        @(posedge m_aclk)
        rd_rst_reg_reg |=> (out == 1'b1)
    );

// When not in reset, a high count_d1_reg[1] is captured into out.
    check_capture_count_bit_high: assert property (
        @(posedge m_aclk) disable iff (rd_rst_reg_reg)
        (count_d1_reg[1] == 1'b1) |=> (out == 1'b1)
    );

// When not in reset, a low count_d1_reg[1] is captured into out.
    check_capture_count_bit_low: assert property (
        @(posedge m_aclk) disable iff (rd_rst_reg_reg)
        (count_d1_reg[1] == 1'b0) |=> (out == 1'b0)
    );

// A rising count_d1_reg[1] propagates to a rising out one cycle later.
    check_rising_count_bit_propagates_to_out: assert property (
        @(posedge m_aclk) disable iff (rd_rst_reg_reg)
        ((count_d1_reg[1] == 1'b0) ##1 (count_d1_reg[1] == 1'b1)) |=> $rose(out)
    );

// A falling count_d1_reg[1] propagates to a falling out one cycle later.
    check_falling_count_bit_propagates_to_out: assert property (
        @(posedge m_aclk) disable iff (rd_rst_reg_reg)
        ((count_d1_reg[1] == 1'b1) ##1 (count_d1_reg[1] == 1'b0)) |=> $fell(out)
    );

// Output concatenation matches the RTL adder expression.
    check_full_add_result: assert property (
        @(posedge clk) {cout, sum} == (cin + a + b)
    );

// Zero inputs produce a zero result.
    check_zero_inputs: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000) && (cin == 1'b0)) |-> ({cout, sum} == 5'b00000)
    );

// Adding zero with cin low passes a through unchanged.
    check_a_passthrough_when_b_and_cin_zero: assert property (
        @(posedge clk) ((b == 4'b0000) && (cin == 1'b0)) |-> ({cout, sum} == {1'b0, a})
    );

// Adding zero with cin low passes b through unchanged.
    check_b_passthrough_when_a_and_cin_zero: assert property (
        @(posedge clk) ((a == 4'b0000) && (cin == 1'b0)) |-> ({cout, sum} == {1'b0, b})
    );

// With only cin asserted, the result is one.
    check_cin_only_result: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000) && (cin == 1'b1)) |-> ({cout, sum} == 5'b00001)
    );

// Reset clears both state elements by the next sampled clock.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |=> (count == 32'd0) && (clk_div == 1'b0)
    );

// Terminal count makes clk_div toggle, unless async reset clears it low.
    check_clk_div_toggles_or_clears_at_terminal: assert property (
        @(posedge clk) disable iff (rst)
        (count == (constantNumber - 32'd1)) |=> ((clk_div == ~$past(clk_div)) || (clk_div == 1'b0))
    );

// Below terminal count, a low clk_div must remain low.
    check_clk_div_low_holds_below_terminal: assert property (
        @(posedge clk) disable iff (rst)
        (count != (constantNumber - 32'd1) && (clk_div == 1'b0)) |=> (clk_div == 1'b0)
    );

// At terminal count, a high clk_div must go low on the next cycle.
    check_clk_div_high_goes_low_at_terminal: assert property (
        @(posedge clk) disable iff (rst)
        (count == (constantNumber - 32'd1) && (clk_div == 1'b1)) |=> (clk_div == 1'b0)
    );

// out_hi always equals the upper input byte.
    check_out_hi_matches_upper_byte: assert property (
        @(posedge clk) out_hi == in[15:8]
    );

// out_lo selects the lower or upper byte based on select_upper.
    check_out_lo_matches_selected_byte: assert property (
        @(posedge clk) out_lo == (select_upper ? in[7:0] : in[15:8])
    );

// With select_upper high, the outputs reproduce the input halfword.
    check_passthrough_when_select_upper: assert property (
        @(posedge clk) select_upper |-> ({out_hi, out_lo} == in)
    );

// With select_upper low, both outputs equal the upper input byte.
    check_upper_byte_duplicated_when_select_lower: assert property (
        @(posedge clk) !select_upper |-> ({out_hi, out_lo} == {in[15:8], in[15:8]})
    );

// With select_upper low, the two outputs must match.
    check_outputs_match_when_select_lower: assert property (
        @(posedge clk) !select_upper |-> (out_hi == out_lo)
    );

// q must be low whenever reset is asserted.
    check_reset_clears_q: assert property (
        @(posedge clk) !rst |-> (q == 1'b0)
    );

// q stays at the reset value on the first clock where reset is released.
    check_reset_release_holds_zero_on_sampled_edge: assert property (
        @(posedge clk) $rose(rst) |-> (q == 1'b0)
    );

// A high d must be captured into q on the next active clock.
    check_capture_one: assert property (
        @(posedge clk) disable iff (!rst) d |=> (q == 1'b1)
    );

// A low d must be captured into q on the next active clock.
    check_capture_zero: assert property (
        @(posedge clk) disable iff (!rst) !d |=> (q == 1'b0)
    );

// X matches the OR of A, B, and C.
    check_or3_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// If all inputs are low, X must be low.
    check_all_low_gives_low: assert property (
        @(posedge clk) !(A | B | C) |-> !X
    );

// If any input is high, X must be high.
    check_any_high_gives_high: assert property (
        @(posedge clk) (A | B | C) |-> X
    );

// Outputs form the 5-bit sum of A, B, and Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Least-significant sum bit matches the full-adder XOR equation.
    check_lsb_sum_bit: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Adding zero with no carry-in passes A through unchanged.
    check_add_zero_to_a: assert property (
        @(posedge clk) ((B == 4'h0) && !Cin) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero with no carry-in passes B through unchanged.
    check_add_zero_to_b: assert property (
        @(posedge clk) ((A == 4'h0) && !Cin) |-> ({Cout, S} == {1'b0, B})
    );

// Zero plus zero with carry-in produces one without carry-out.
    check_zero_plus_zero_with_cin: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0) && Cin) |-> ({Cout, S} == 5'h01)
    );

// With B at zero, Cin increments A by one.
    check_increment_a_when_b_zero: assert property (
        @(posedge clk) ((B == 4'h0) && Cin) |-> ({Cout, S} == ({1'b0, A} + 5'd1))
    );

// Complementary operands with no carry-in sum to all ones with no carry-out.
    check_complementary_operands: assert property (
        @(posedge clk) ((A == ~B) && !Cin) |-> ({Cout, S} == 5'h0F)
    );

// Adding 1 to 0xF produces zero with carry-out.
    check_f_plus_one: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'h1) && !Cin) |-> ({Cout, S} == 5'h10)
    );

// Maximum inputs produce the maximum 5-bit result.
    check_max_inputs: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF) && Cin) |-> ({Cout, S} == 5'h1F)
    );

// Carry-out is high exactly when the 4-bit addition overflows.
    check_carry_out_overflow: assert property (
        @(posedge clk) Cout == ((({1'b0, A} + {1'b0, B} + Cin) >= 5'd16))
    );

// SHIFT=00 passes the input through unchanged.
    check_no_shift: assert property (
        @(posedge clk) (SHIFT == 2'b00) |-> (Y == A)
    );

// SHIFT=01 shifts left by 1 and inserts 0 in bit 0.
    check_left_shift_by_1: assert property (
        @(posedge clk) (SHIFT == 2'b01) |-> (Y == {A[2:0], 1'b0})
    );

// SHIFT=10 shifts right by 1 and inserts 0 in bit 3.
    check_right_shift_by_1: assert property (
        @(posedge clk) (SHIFT == 2'b10) |-> (Y == {1'b0, A[3:1]})
    );

// SHIFT=11 maps the output to {A[1:0], A[3:2]}.
    check_shift_11_mapping: assert property (
        @(posedge clk) (SHIFT == 2'b11) |-> (Y == {A[1:0], A[3:2]})
    );

// Low nibble is converted to its ASCII hex character.
    check_low_nibble_ascii_encoding: assert property (
        @(posedge clk) out[7:0] == hex_ascii(in[3:0])
    );

// High nibble is converted to its ASCII hex character.
    check_high_nibble_ascii_encoding: assert property (
        @(posedge clk) out[15:8] == hex_ascii(in[7:4])
    );

// Full output is the concatenation of high and low ASCII hex characters.
    check_full_output_encoding: assert property (
        @(posedge clk) out == {hex_ascii(in[7:4]), hex_ascii(in[3:0])}
    );

// Input 8'h00 maps to ASCII "00".
    check_zero_input_maps_to_ascii_00: assert property (
        @(posedge clk) (in == 8'h00) |-> (out == {"0", "0"})
    );

// Input 8'hFF maps to ASCII "FF".
    check_ff_input_maps_to_ascii_ff: assert property (
        @(posedge clk) (in == 8'hFF) |-> (out == {"F", "F"})
    );

// Master address acknowledge is the OR of all slave acknowledges.
    check_master_addr_ack_or: assert property (
        @(posedge clk) disable iff (reset)
        m_addr_ack == (s0_addr_ack | s1_addr_ack | s2_addr_ack)
    );

// Master read response is the OR of all slave read responses.
    check_master_rd_rs_or: assert property (
        @(posedge clk) disable iff (reset)
        m_rd_rs == (s0_rd_rs | s1_rd_rs | s2_rd_rs)
    );

// Master read data is the OR of write data and all slave read data.
    check_master_read_data_or: assert property (
        @(posedge clk) disable iff (reset)
        m_mb_read == (m_mb_write | s0_mb_read | s1_mb_read | s2_mb_read)
    );

// Slave 0 write data matches the shared ORed data bus.
    check_s0_write_data_fanout: assert property (
        @(posedge clk) disable iff (reset)
        s0_mb_write == (m_mb_write | s0_mb_read | s1_mb_read | s2_mb_read)
    );

// Slave 1 write data matches the shared ORed data bus.
    check_s1_write_data_fanout: assert property (
        @(posedge clk) disable iff (reset)
        s1_mb_write == (m_mb_write | s0_mb_read | s1_mb_read | s2_mb_read)
    );

// Slave 2 write data matches the shared ORed data bus.
    check_s2_write_data_fanout: assert property (
        @(posedge clk) disable iff (reset)
        s2_mb_write == (m_mb_write | s0_mb_read | s1_mb_read | s2_mb_read)
    );

// Active-low SET must drive Q high by the next clock edge.
    check_set_forces_high_by_next_clk: assert property (
        @(posedge CLK) (!SET) |=> (Q == 1'b1)
    );

// With SET inactive, capturing D=1 must make Q high on the next clock.
    check_capture_one_when_enabled: assert property (
        @(posedge CLK) disable iff (!SET) (NOTIFIER && D) |=> (Q == 1'b1)
    );

// With SET inactive, Q=1 must hold when capture is disabled.
    check_hold_high_when_notifier_low: assert property (
        @(posedge CLK) disable iff (!SET) (!NOTIFIER && (Q == 1'b1)) |=> (Q == 1'b1)
    );

// With SET inactive, Q=1 cannot clear when D is also 1.
    check_high_preserved_when_d_high: assert property (
        @(posedge CLK) disable iff (!SET) ((Q == 1'b1) && (D == 1'b1)) |=> (Q == 1'b1)
    );

// The 5-bit output must equal a + b + cin.
    check_total_addition: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0000, cin})
    );

// Sum bit 0 must match the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Sum bit 1 must use the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin))
        )
    );

// Sum bit 2 must use the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                ((a[1] ^ b[1]) & (
                    (a[0] & b[0]) |
                    ((a[0] ^ b[0]) & cin)
                ))
            )
        )
    );

// Sum bit 3 must use the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                ((a[2] ^ b[2]) & (
                    (a[1] & b[1]) |
                    ((a[1] ^ b[1]) & (
                        (a[0] & b[0]) |
                        ((a[0] ^ b[0]) & cin)
                    ))
                ))
            )
        )
    );

// Cout must be the carry out of the MSB full-adder stage.
    check_cout_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        cout == (
            (a[3] & b[3]) |
            ((a[3] ^ b[3]) & (
                (a[2] & b[2]) |
                ((a[2] ^ b[2]) & (
                    (a[1] & b[1]) |
                    ((a[1] ^ b[1]) & (
                        (a[0] & b[0]) |
                        ((a[0] ^ b[0]) & cin)
                    ))
                ))
            ))
        )
    );

// Adding zero with cin low must pass a through unchanged.
    check_add_zero_to_a: assert property (
        @(posedge clk) disable iff (1'b0)
        (b == 4'b0000 && cin == 1'b0) |-> ({cout, sum} == {1'b0, a})
    );

// Adding zero with cin low must pass b through unchanged.
    check_add_zero_to_b: assert property (
        @(posedge clk) disable iff (1'b0)
        (a == 4'b0000 && cin == 1'b0) |-> ({cout, sum} == {1'b0, b})
    );

// ENCLK captures EN on each rising edge.
    check_enclk_captures_en: assert property (
        @(posedge CLK) 1'b1 |=> (ENCLK == $past(EN))
    );

// ECK reflects the registered EN value.
    check_eck_captures_en: assert property (
        @(posedge CLK) 1'b1 |=> (TLATNTSCAX2TS_ECK == $past(EN))
    );

// E is a direct copy of EN.
    check_e_mirrors_en: assert property (
        @(posedge CLK) TLATNTSCAX2TS_E == EN
    );

// SE is a direct copy of TE.
    check_se_mirrors_te: assert property (
        @(posedge CLK) TLATNTSCAX2TS_SE == TE
    );

// CK is a direct copy of CLK.
    check_ck_mirrors_clk: assert property (
        @(posedge CLK) TLATNTSCAX2TS_CK == CLK
    );

// ECK is a direct copy of ENCLK.
    check_eck_mirrors_enclk: assert property (
        @(posedge CLK) TLATNTSCAX2TS_ECK == ENCLK
    );

// EN high drives ENCLK high on the next rising edge.
    check_en_high_sets_enclk: assert property (
        @(posedge CLK) EN |=> ENCLK
    );

// EN low drives ENCLK low on the next rising edge.
    check_en_low_clears_enclk: assert property (
        @(posedge CLK) !EN |=> !ENCLK
    );

// SET drives the outputs high/low when RESET is low.
    check_set_state: assert property (
        @(posedge CLK) disable iff (1'b0)
        (SET && !RESET) |=> (Q == 1'b1 && Q_N == 1'b0)
    );

// SET has priority over RESET when both are high.
    check_set_priority_over_reset: assert property (
        @(posedge CLK) disable iff (1'b0)
        (SET && RESET) |=> (Q == 1'b1 && Q_N == 1'b0)
    );

// RESET drives the outputs low/high when SET is low.
    check_reset_state: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!SET && RESET) |=> (Q == 1'b0 && Q_N == 1'b1)
    );

// D=1 is captured when neither control input is asserted.
    check_data_capture_one: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!SET && !RESET && D) |=> (Q == 1'b1 && Q_N == 1'b0)
    );

// D=0 is captured when neither control input is asserted.
    check_data_capture_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!SET && !RESET && !D) |=> (Q == 1'b0 && Q_N == 1'b1)
    );

// The outputs remain complementary after each clocked update.
    check_outputs_complementary: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (Q_N == ~Q)
    );

// Clock: clk
    // Reset: reset is active low
    // Logic: sequential 4-bit up-counter

    // A low reset on a clock edge clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk) (!reset) |=> (count == 4'b0000)
    );

// When reset is high, the counter increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!reset) (count == 4'hF) |=> (count == 4'h0)
    );

// Reset drives count to zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Reset has priority over enable when both are high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 4'b0000)
    );

// When enabled outside reset, count increments by one.
    check_increment_on_enable: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When disabled outside reset, count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Enabling at 4'hf wraps the counter back to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hf)) |=> (count == 4'h0)
    );

// Reset drives the registered output low.
    check_reset_forces_dout_low: assert property (
        @(posedge clk) rst |-> (dout == 1'b0)
    );

// After a sampled reset cycle, the output remains low until the next clocked update.
    check_post_reset_dout_low: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) |-> (dout == 1'b0)
    );

// q captures d on the next rising clock edge.
    check_q_captures_d: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(d))
    );

// A high d is reflected on q one cycle later.
    check_q_sets_after_high_d: assert property (
        @(posedge clk) d |=> q
    );

// A low d is reflected on q one cycle later.
    check_q_clears_after_low_d: assert property (
        @(posedge clk) !d |=> !q
    );

// Empty passes the input count through with zero extension.
    check_empty_pass_through: assert property (
        @(posedge clk)
        empty |-> (fifo_cnt_inc == {3'b000, input_tm_cnt})
    );

// Non-empty with zero input count returns 31.
    check_nonempty_count0_returns_31: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd0)) |-> (fifo_cnt_inc == 5'd31)
    );

// Non-empty with input count 1 returns 0.
    check_nonempty_count1_returns_0: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd1)) |-> (fifo_cnt_inc == 5'd0)
    );

// Non-empty with input count 2 and ge2_free set returns 1.
    check_nonempty_count2_ge2_returns_1: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd2) && ge2_free) |-> (fifo_cnt_inc == 5'd1)
    );

// Non-empty with input count 2 and ge2_free clear returns 0.
    check_nonempty_count2_no_ge2_returns_0: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd2) && !ge2_free) |-> (fifo_cnt_inc == 5'd0)
    );

// Non-empty with input count 3 and ge3_free set returns 2.
    check_nonempty_count3_ge3_returns_2: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd3) && ge3_free) |-> (fifo_cnt_inc == 5'd2)
    );

// Non-empty with input count 3 uses the ge2_free case when ge3_free is clear.
    check_nonempty_count3_ge2_only_returns_1: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd3) && !ge3_free && ge2_free) |-> (fifo_cnt_inc == 5'd1)
    );

// Non-empty with input count 3 returns 0 when neither free threshold applies.
    check_nonempty_count3_no_free_threshold_returns_0: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'd3) && !ge3_free && !ge2_free) |-> (fifo_cnt_inc == 5'd0)
    );

// Clock: clk
    // Reset: areset is asynchronous active-high
    // Logic: sequential shift_reg/q with combinational shifted_value

    // Reset clears the internal shift register.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) areset |-> (shift_reg == 4'b0000)
    );

// Reset clears the output register.
    check_reset_clears_q: assert property (
        @(posedge clk) areset |-> (q == 4'b0000)
    );

// shifted_value is always the zero-filled right shift of shift_reg.
    check_shifted_value_definition: assert property (
        @(posedge clk) disable iff (areset)
        shifted_value == {1'b0, shift_reg[3:1]}
    );

// load has priority and loads data into shift_reg.
    check_shift_reg_load_behavior: assert property (
        @(posedge clk) disable iff (areset)
        load |=> (shift_reg == $past(data))
    );

// Without load, ena shifts shift_reg right with zero fill.
    check_shift_reg_shift_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena) |=> (shift_reg == {1'b0, $past(shift_reg[3:1])})
    );

// With neither load nor ena, shift_reg holds its value.
    check_shift_reg_hold_behavior: assert property (
        @(posedge clk) disable iff (areset)
        (!load && !ena) |=> (shift_reg == $past(shift_reg))
    );

// q loads data only when both load and ena are high.
    check_q_load_when_load_and_ena: assert property (
        @(posedge clk) disable iff (areset)
        (load && ena) |=> (q == $past(data))
    );

// Otherwise q takes the prior shifted_value.
    check_q_uses_prior_shifted_value_otherwise: assert property (
        @(posedge clk) disable iff (areset)
        !(load && ena) |=> (q == $past(shifted_value))
    );

// When ena is high, q and shift_reg update to the same value.
    check_q_matches_shift_reg_after_enable: assert property (
        @(posedge clk) disable iff (areset)
        ena |=> (q == shift_reg)
    );

// Sampled on clkin rising edges, clkout stays the inverse of clkin.
    check_inversion_on_clkin_rise: assert property (
        @(posedge clkin) clkout == ~clkin
    );

// Sampled on clkout rising edges, clkout stays the inverse of clkin.
    check_inversion_on_clkout_rise: assert property (
        @(posedge clkout) clkout == ~clkin
    );

// f must always equal s minus e.
  check_subtract_relation: assert property (
    @(posedge clk) f == (s - e)
  );

// Adding e back to f must reconstruct s.
  check_reconstruct_source: assert property (
    @(posedge clk) (f + e) == s
  );

// When e is zero, f must match s.
  check_passthrough_when_e_zero: assert property (
    @(posedge clk) (e == '0) |-> (f == s)
  );

// When s equals e, the subtraction result must be zero.
  check_zero_output_when_inputs_equal: assert property (
    @(posedge clk) (s == e) |-> (f == '0)
  );

// When s is zero, f must be the negation of e.
  check_negated_e_when_s_zero: assert property (
    @(posedge clk) (s == '0) |-> (f == -e)
  );

// gray_out[3] matches the previous cycle binary_in[3].
    check_gray_msb: assert property (
        @(posedge clk) 1'b1 |=> gray_out[3] == $past(binary_in[3])
    );

// gray_out[2] matches the previous cycle binary_in[3] ^ binary_in[2].
    check_gray_bit2: assert property (
        @(posedge clk) 1'b1 |=> gray_out[2] == ($past(binary_in[3]) ^ $past(binary_in[2]))
    );

// gray_out[1] matches the previous cycle binary_in[2] ^ binary_in[1].
    check_gray_bit1: assert property (
        @(posedge clk) 1'b1 |=> gray_out[1] == ($past(binary_in[2]) ^ $past(binary_in[1]))
    );

// gray_out[0] matches the previous cycle binary_in[1] ^ binary_in[0].
    check_gray_lsb: assert property (
        @(posedge clk) 1'b1 |=> gray_out[0] == ($past(binary_in[1]) ^ $past(binary_in[0]))
    );

// gray_out matches the previous cycle Gray-code conversion of binary_in.
    check_gray_bus: assert property (
        @(posedge clk) 1'b1 |=> gray_out == {
            $past(binary_in[3]),
            ($past(binary_in[3]) ^ $past(binary_in[2])),
            ($past(binary_in[2]) ^ $past(binary_in[1])),
            ($past(binary_in[1]) ^ $past(binary_in[0]))
        }
    );

// X must equal (A1 OR A2) AND B1.
    check_o21a_function: assert property (
        @(posedge clk) X == ((A1 | A2) & B1)
    );

// B1 low forces the output low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// With both OR inputs low, the output must be low.
    check_no_a_input_forces_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// A1 high with B1 high drives the output high.
    check_a1_and_b1_drive_x_high: assert property (
        @(posedge clk) (A1 && B1) |-> X
    );

// A2 high with B1 high drives the output high.
    check_a2_and_b1_drive_x_high: assert property (
        @(posedge clk) (A2 && B1) |-> X
    );

// A high output requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// A high output requires at least one A input high.
    check_x_high_requires_a1_or_a2: assert property (
        @(posedge clk) X |-> (A1 || A2)
    );

// X must match the implemented O2111A logic equation.
    check_x_equation: assert property (
        @(posedge clk) X == (B1 & C1 & D1 & (A1 | A2))
    );

// When all product terms are true, X must be high.
    check_all_terms_true_drive_x_high: assert property (
        @(posedge clk) (B1 & C1 & D1 & (A1 | A2)) |-> X
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// D1 low forces X low.
    check_d1_low_forces_x_low: assert property (
        @(posedge clk) !D1 |-> !X
    );

// If both A inputs are low, X must be low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 & !A2) |-> !X
    );

// A high output requires all AND-side inputs to be high.
    check_x_high_requires_and_inputs: assert property (
        @(posedge clk) X |-> (B1 & C1 & D1)
    );

// A high output requires at least one A input to be high.
    check_x_high_requires_or_input: assert property (
        @(posedge clk) X |-> (A1 | A2)
    );

// Output vector matches the binary-to-Gray transform.
    check_gray_vector_encoding: assert property (
        @(posedge clk) g == ({1'b0, b[3:1]} ^ b)
    );

// g[3] passes through b[3].
    check_gray_bit3: assert property (
        @(posedge clk) g[3] == b[3]
    );

// g[2] is b[3] xor b[2].
    check_gray_bit2: assert property (
        @(posedge clk) g[2] == (b[3] ^ b[2])
    );

// g[1] is b[2] xor b[1].
    check_gray_bit1: assert property (
        @(posedge clk) g[1] == (b[2] ^ b[1])
    );

// g[0] is b[1] xor b[0].
    check_gray_bit0: assert property (
        @(posedge clk) g[0] == (b[1] ^ b[0])
    );

// MO must select A when S is low.
    check_select_a: assert property (
        @(posedge clk) (S == 1'b0) |-> (MO == A)
    );

// MO must select B when S is high.
    check_select_b: assert property (
        @(posedge clk) (S == 1'b1) |-> (MO == B)
    );

// MO must match the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) MO == (((~S) & A) | (S & B))
    );

// If both inputs are equal, MO must equal that value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A == B) |-> (MO == A)
    );

// X must match the implemented combinational equation.
    check_x_function: assert property (
        @(posedge clk) X == ((~B1) | (~B2) | (A1_N & A2_N))
    );

// If B1 is low, the shared B term is low and X must be high.
    check_x_high_when_b1_low: assert property (
        @(posedge clk) (!B1) |-> X
    );

// If B2 is low, the shared B term is low and X must be high.
    check_x_high_when_b2_low: assert property (
        @(posedge clk) (!B2) |-> X
    );

// With both B inputs high, an asserted A1 path forces X low.
    check_x_low_when_a1_path_active: assert property (
        @(posedge clk) (B1 & B2 & ~A1_N) |-> (!X)
    );

// With both B inputs high, an asserted A2 path forces X low.
    check_x_low_when_a2_path_active: assert property (
        @(posedge clk) (B1 & B2 & ~A2_N) |-> (!X)
    );

// With both B inputs high, inactive A paths keep X high.
    check_x_high_when_b_high_and_a_inactive: assert property (
        @(posedge clk) (B1 & B2 & A1_N & A2_N) |-> X
    );

// A low X can only occur when both B inputs are high and some A path is active.
    check_x_low_implies_active_b_and_a_path: assert property (
        @(posedge clk) (!X) |-> (B1 & B2 & ((~A1_N) | (~A2_N)))
    );

// If X is high while both B inputs are high, both A paths must be inactive.
    check_x_high_with_b_high_implies_a_inactive: assert property (
        @(posedge clk) (B1 & B2 & X) |-> (A1_N & A2_N)
    );

// Checks the bitwise OR output.
    check_out_or_bitwise_value: assert property (
        @(posedge clk) out_or_bitwise == (a | b)
    );

// Checks the logical OR output.
    check_out_or_logical_value: assert property (
        @(posedge clk) out_or_logical == ((a != 3'b000) || (b != 3'b000))
    );

// Checks logical OR matches whether the bitwise OR is non-zero.
    check_out_or_logical_matches_bitwise_or: assert property (
        @(posedge clk) out_or_logical == (out_or_bitwise != 3'b000)
    );

// Checks the upper half of out_not is the inverse of b.
    check_out_not_upper_inverts_b: assert property (
        @(posedge clk) out_not[5:3] == ~b
    );

// Checks the lower half of out_not is the inverse of a.
    check_out_not_lower_inverts_a: assert property (
        @(posedge clk) out_not[2:0] == ~a
    );

// Checks the full out_not bus matches the concatenated inversions.
    check_out_not_concat_value: assert property (
        @(posedge clk) out_not == {~b, ~a}
    );

// Reset clears the counter to zero.
    check_reset_clears_counter: assert property (
        @(posedge clk) rst |=> (out == 4'b0000)
    );

// A high input increments the counter by one.
    check_increment_when_in_high: assert property (
        @(posedge clk) disable iff (rst)
        (in == 1'b1) |=> (out == ($past(out) + 4'b0001))
    );

// A low input decrements the counter by one.
    check_decrement_when_in_low: assert property (
        @(posedge clk) disable iff (rst)
        (in == 1'b0) |=> (out == ($past(out) - 4'b0001))
    );

// Incrementing from 4'hF wraps the 4-bit counter to 0.
    check_increment_wraparound: assert property (
        @(posedge clk) disable iff (rst)
        ((in == 1'b1) && (out == 4'hF)) |=> (out == 4'h0)
    );

// Decrementing from 0 wraps the 4-bit counter to 4'hF.
    check_decrement_wraparound: assert property (
        @(posedge clk) disable iff (rst)
        ((in == 1'b0) && (out == 4'h0)) |=> (out == 4'hF)
    );

// In shift mode with 00, B is A logically shifted left by 1.
    check_shift_mode_logical_left: assert property (
        @(posedge clk)
        (select == 1'b1 && shift_type == 2'b00) |-> (B == (A << 1))
    );

// In shift mode with 01, B is A logically shifted right by 1.
    check_shift_mode_logical_right: assert property (
        @(posedge clk)
        (select == 1'b1 && shift_type == 2'b01) |-> (B == (A >> 1))
    );

// In shift mode with 10, B matches the RTL concatenation.
    check_shift_mode_case_10: assert property (
        @(posedge clk)
        (select == 1'b1 && shift_type == 2'b10) |-> (B == {A[2], A[3], A[3], A[3]})
    );

// In shift mode with 11, B matches the RTL concatenation.
    check_shift_mode_case_11: assert property (
        @(posedge clk)
        (select == 1'b1 && shift_type == 2'b11) |-> (B == {A[0], A[0], A[0], A[1]})
    );

// Sum and carry must match 4-bit addition with carry-in.
    check_full_add_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + {4'b0, Cin})
    );

// Carry-out must indicate overflow of the 4-bit addition.
    check_cout_matches_overflow: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + {4'b0, Cin}) > 5'd15)
    );

// Bit 0 sum must implement the full-adder XOR equation.
    check_lsb_sum_equation: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// With B and carry-in low, the adder must pass A through.
    check_a_passthrough_when_b_zero: assert property (
        @(posedge clk) ((B == 4'h0) && (Cin == 1'b0)) |-> ({Cout, Sum} == {1'b0, A})
    );

// With A and carry-in low, the adder must pass B through.
    check_b_passthrough_when_a_zero: assert property (
        @(posedge clk) ((A == 4'h0) && (Cin == 1'b0)) |-> ({Cout, Sum} == {1'b0, B})
    );

// With both operands zero, only the carry-in contributes to the sum.
    check_cin_only_when_inputs_zero: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0)) |-> ((Sum == {3'b000, Cin}) && (Cout == 1'b0))
    );

// Complementary operands with no carry-in must sum to all ones.
    check_complementary_inputs_no_carry: assert property (
        @(posedge clk) ((A == ~B) && (Cin == 1'b0)) |-> ({Cout, Sum} == 5'h0F)
    );

// Complementary operands with carry-in must wrap to zero and assert carry-out.
    check_complementary_inputs_with_carry: assert property (
        @(posedge clk) ((A == ~B) && (Cin == 1'b1)) |-> ({Cout, Sum} == 5'h10)
    );

// Maximum inputs with carry-in must produce the saturated 5-bit result.
    check_all_ones_plus_cin: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b1)) |-> ({Cout, Sum} == 5'h1F)
    );

// Output matches the RTL priority mux.
    check_full_mux_behavior: assert property (
        @(posedge clk) disable iff (1'b0)
        m68k_data == (ctrl1_zone ? 8'b00000000 :
                      ctrl2_zone ? 8'b00000000 :
                      statusb_zone ? {system_mode, nwp, ncd2, ncd1, p2_in[9:8], p1_in[9:8]} :
                                     p1_in[7:0])
    );

// ctrl1_zone forces the output to zero.
    check_ctrl1_zone_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        ctrl1_zone |-> (m68k_data == 8'b00000000)
    );

// ctrl2_zone forces the output to zero when ctrl1_zone is low.
    check_ctrl2_zone_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (!ctrl1_zone && ctrl2_zone) |-> (m68k_data == 8'b00000000)
    );

// statusb_zone selects the packed status byte when higher priorities are low.
    check_statusb_zone_encoding: assert property (
        @(posedge clk) disable iff (1'b0)
        (!ctrl1_zone && !ctrl2_zone && statusb_zone) |->
            (m68k_data == {system_mode, nwp, ncd2, ncd1, p2_in[9:8], p1_in[9:8]})
    );

// With no zone selected, p1_in[7:0] passes through.
    check_default_p1_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (!ctrl1_zone && !ctrl2_zone && !statusb_zone) |-> (m68k_data == p1_in[7:0])
    );

// Word opcode passes all 32 bits and enables all bytes.
    check_word_opcode_passthrough: assert property (
        @(posedge clk)
        (IR_out == LW_OPCODE) |-> ((mem_data_shift == mem_data_out) &&
                                   (Rd_write_byte_en == 4'b1111))
    );

// Non-word offset 0 passes all 32 bits and enables all bytes.
    check_nonword_addr_00: assert property (
        @(posedge clk)
        (IR_out != LW_OPCODE && mem_addr_in == 2'b00) |-> ((mem_data_shift == mem_data_out) &&
                                                           (Rd_write_byte_en == 4'b1111))
    );

// Non-word offset 1 clears the low byte and disables byte 0.
    check_nonword_addr_01: assert property (
        @(posedge clk)
        (IR_out != LW_OPCODE && mem_addr_in == 2'b01) |-> ((mem_data_shift == {mem_data_out[31:8], 8'b0}) &&
                                                           (Rd_write_byte_en == 4'b1110))
    );

// Non-word offset 2 clears the low two bytes and disables bytes 1:0.
    check_nonword_addr_10: assert property (
        @(posedge clk)
        (IR_out != LW_OPCODE && mem_addr_in == 2'b10) |-> ((mem_data_shift == {mem_data_out[31:16], 16'b0}) &&
                                                           (Rd_write_byte_en == 4'b1100))
    );

// Non-word offset 3 clears the low three bytes and enables only byte 3.
    check_nonword_addr_11: assert property (
        @(posedge clk)
        (IR_out != LW_OPCODE && mem_addr_in == 2'b11) |-> ((mem_data_shift == {mem_data_out[31:24], 24'b0}) &&
                                                           (Rd_write_byte_en == 4'b1000))
    );

// Result matches the full bitwise AND of the inputs.
    check_result_vector_and: assert property (
        @(posedge clk) result === (a & b)
    );

// Bit 0 of result matches a[0] & b[0].
    check_result_bit0_and: assert property (
        @(posedge clk) result[0] === (a[0] & b[0])
    );

// Bit 1 of result matches a[1] & b[1].
    check_result_bit1_and: assert property (
        @(posedge clk) result[1] === (a[1] & b[1])
    );

// Bit 2 of result matches a[2] & b[2].
    check_result_bit2_and: assert property (
        @(posedge clk) result[2] === (a[2] & b[2])
    );

// Bit 3 of result matches a[3] & b[3].
    check_result_bit3_and: assert property (
        @(posedge clk) result[3] === (a[3] & b[3])
    );

// Zero on a forces a zero result.
    check_zero_when_a_zero: assert property (
        @(posedge clk) (a === 4'h0) |-> (result === 4'h0)
    );

// Zero on b forces a zero result.
    check_zero_when_b_zero: assert property (
        @(posedge clk) (b === 4'h0) |-> (result === 4'h0)
    );

// All ones on a passes b through to the result.
    check_passthrough_when_a_all_ones: assert property (
        @(posedge clk) (a === 4'hF) |-> (result === b)
    );

// All ones on b passes a through to the result.
    check_passthrough_when_b_all_ones: assert property (
        @(posedge clk) (b === 4'hF) |-> (result === a)
    );

// All ones on both inputs produces all ones on the result.
    check_all_ones_when_both_all_ones: assert property (
        @(posedge clk) ((a === 4'hF) && (b === 4'hF)) |-> (result === 4'hF)
    );

// From state 00, x=0 keeps the state at 00.
    check_state_00_x0_hold: assert property (
        @(posedge Clk) (state == 2'b00 && x == 1'b0) |=> (state == 2'b00)
    );

// From state 00, x=1 moves the state to 01.
    check_state_00_x1_to_01: assert property (
        @(posedge Clk) (state == 2'b00 && x == 1'b1) |=> (state == 2'b01)
    );

// From state 01, y=0 moves the state to 10.
    check_state_01_y0_to_10: assert property (
        @(posedge Clk) (state == 2'b01 && y == 1'b0) |=> (state == 2'b10)
    );

// From state 01, y=1 moves the state to 11.
    check_state_01_y1_to_11: assert property (
        @(posedge Clk) (state == 2'b01 && y == 1'b1) |=> (state == 2'b11)
    );

// From state 10, x=0 moves the state to 00.
    check_state_10_x0_to_00: assert property (
        @(posedge Clk) (state == 2'b10 && x == 1'b0) |=> (state == 2'b00)
    );

// From state 10 with x,y=10, the state holds at 10.
    check_state_10_xy10_hold: assert property (
        @(posedge Clk) (state == 2'b10 && x == 1'b1 && y == 1'b0) |=> (state == 2'b10)
    );

// From state 10 with x,y=11, the state moves to 11.
    check_state_10_xy11_to_11: assert property (
        @(posedge Clk) (state == 2'b10 && x == 1'b1 && y == 1'b1) |=> (state == 2'b11)
    );

// From state 11 with x,y=00, the state moves to 10.
    check_state_11_xy00_to_10: assert property (
        @(posedge Clk) (state == 2'b11 && x == 1'b0 && y == 1'b0) |=> (state == 2'b10)
    );

// From state 11 with x,y=01, the state holds at 11.
    check_state_11_xy01_hold: assert property (
        @(posedge Clk) (state == 2'b11 && x == 1'b0 && y == 1'b1) |=> (state == 2'b11)
    );

// From state 11, x=1 moves the state to 00.
    check_state_11_x1_to_00: assert property (
        @(posedge Clk) (state == 2'b11 && x == 1'b1) |=> (state == 2'b00)
    );

// Y matches the implemented NAND-with-inverted-A function.
    check_function: assert property (
        @(posedge clk) Y == (A_N || !B || !C || !D)
    );

// A_N high forces the inverted NAND input low, so Y must be high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// A_N low with B, C, and D high drives the NAND output low.
    check_all_active_inputs_drive_y_low: assert property (
        @(posedge clk) (!A_N && B && C && D) |-> !Y
    );

// B low prevents the NAND pull-down condition and keeps Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) !B |-> Y
    );

// C low prevents the NAND pull-down condition and keeps Y high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> Y
    );

// D low prevents the NAND pull-down condition and keeps Y high.
    check_d_low_forces_y_high: assert property (
        @(posedge clk) !D |-> Y
    );

// Y low can occur only for A_N low with B, C, and D high.
    check_y_low_only_on_active_combination: assert property (
        @(posedge clk) !Y |-> (!A_N && B && C && D)
    );

// q must be low whenever the active-low reset is asserted.
    check_reset_forces_q_low: assert property (
        @(posedge clk) !reset |-> (q == 1'b0)
    );

// A cycle in reset leaves q low at the next sampled clock.
    check_reset_holds_q_low_to_next_clock: assert property (
        @(posedge clk) !reset |=> (q == 1'b0)
    );

// With reset inactive, a low d is captured as a low q on the next clock.
    check_low_d_captures_low_q: assert property (
        @(posedge clk) disable iff (!reset) (d == 1'b0) |=> (q == 1'b0)
    );

// X matches the implemented AO211 function.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | B1 | C1)
    );

// B1 directly forces the OR output high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// C1 directly forces the OR output high.
    check_c1_forces_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 together force the AND path high.
    check_a1_a2_force_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// With B1 and C1 low, X reduces to the AND term.
    check_reduces_to_and_when_or_terms_low: assert property (
        @(posedge clk) (!B1 && !C1) |-> (X == (A1 & A2))
    );

// A high X must come from one implemented source term.
    check_x_high_has_implemented_source: assert property (
        @(posedge clk) X |-> (B1 || C1 || (A1 && A2))
    );

// X matches the RTL combinational equation.
    check_x_matches_rtl_function: assert property (
        @(posedge clk) X == ((A ^ VPWR) & (SLEEP_B ^ VGND) & VPWR & VGND & VPB & VNB)
    );

// A high X requires all power-related terms to be high.
    check_x_high_requires_power_terms: assert property (
        @(posedge clk) X |-> (VPWR & VGND & VPB & VNB)
    );

// A high X requires the A isolation term to be high.
    check_x_high_requires_a_iso_term: assert property (
        @(posedge clk) X |-> (A ^ VPWR)
    );

// A high X requires the SLEEP_B isolation term to be high.
    check_x_high_requires_sleep_iso_term: assert property (
        @(posedge clk) X |-> (SLEEP_B ^ VGND)
    );

// Low VPWR forces X low.
    check_low_vpwr_forces_x_low: assert property (
        @(posedge clk) !VPWR |-> !X
    );

// Low VGND forces X low.
    check_low_vgnd_forces_x_low: assert property (
        @(posedge clk) !VGND |-> !X
    );

// Low VPB forces X low.
    check_low_vpb_forces_x_low: assert property (
        @(posedge clk) !VPB |-> !X
    );

// Low VNB forces X low.
    check_low_vnb_forces_x_low: assert property (
        @(posedge clk) !VNB |-> !X
    );

// Matching A and VPWR makes the A isolation term zero.
    check_a_equal_vpwr_blocks_x: assert property (
        @(posedge clk) (A == VPWR) |-> !X
    );

// Matching SLEEP_B and VGND makes the sleep isolation term zero.
    check_sleep_equal_vgnd_blocks_x: assert property (
        @(posedge clk) (SLEEP_B == VGND) |-> !X
    );

// Combinational DUT sampled on an external formal clock.

    // Output matches the implemented mux function on every sample.
    check_output_matches_implemented_function: assert property (
        @(posedge clk)
        out == (sel[1] ? (sel[0] ? in[2] : in[3]) : (sel[0] ? in[1] : in[0]))
    );

// When sel[1] is low, the output comes from the lower input pair.
    check_sel_msb_low_selects_lower_pair: assert property (
        @(posedge clk)
        (sel[1] == 1'b0) |-> (out == (sel[0] ? in[1] : in[0]))
    );

// When sel[1] is high, the output comes from the upper input pair in reversed sel[0] order.
    check_sel_msb_high_selects_upper_pair_reversed: assert property (
        @(posedge clk)
        (sel[1] == 1'b1) |-> (out == (sel[0] ? in[2] : in[3]))
    );

// Select 00 maps to input bit 0.
    check_sel_00_selects_in0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == in[0])
    );

// Select 01 maps to input bit 1.
    check_sel_01_selects_in1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == in[1])
    );

// Select 10 maps to input bit 3.
    check_sel_10_selects_in3: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == in[3])
    );

// Select 11 maps to input bit 2.
    check_sel_11_selects_in2: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == in[2])
    );

// A reset cycle clears shifted_data.
    check_reset_clears_shifted_data: assert property (
        @(posedge clk) reset |=> (shifted_data == 32'h00000000)
    );

// A reset cycle clears zero_flag.
    check_reset_clears_zero_flag: assert property (
        @(posedge clk) reset |=> (zero_flag == 1'b0)
    );

// shifted_data updates to the prior input_data shifted left by one.
    check_shifted_data_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (shifted_data == {$past(input_data[30:0]), 1'b0})
    );

// A zero input sets zero_flag on the next clock.
    check_zero_flag_set_on_zero_input: assert property (
        @(posedge clk) disable iff (reset)
        (input_data == 32'h00000000) |=> (zero_flag == 1'b1)
    );

// A nonzero input clears zero_flag on the next clock.
    check_zero_flag_clear_on_nonzero_input: assert property (
        @(posedge clk) disable iff (reset)
        (input_data != 32'h00000000) |=> (zero_flag == 1'b0)
    );

// Reset clears the registered sum, so the output is zero on the next cycle.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (sum_out == 32'h00000000)
    );

// Active-low reset forces count to zero.
    reset_forces_count_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'b0000)
    );

// When enabled, the counter increments by one on the next cycle.
    enable_branch_increments: assert property (
        @(posedge clk) disable iff (!rst)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When disabled below 15, the counter still increments by one.
    disabled_nonmax_branch_increments: assert property (
        @(posedge clk) disable iff (!rst)
        (!enable && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

// When disabled at 15, the counter wraps to zero on the next cycle.
    disabled_max_branch_wraps: assert property (
        @(posedge clk) disable iff (!rst)
        (!enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Outside reset, the counter advances by one every cycle.
    counter_advances_each_cycle: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Reset makes the sampled output low on the next clock.
    check_reset_clears_output_next_cycle: assert property (
        @(posedge clk) rst |=> (out == 1'b0)
    );

// Reset keeps the sampled output low two clocks later.
    check_reset_clears_output_two_cycles_later: assert property (
        @(posedge clk) rst |=> ##1 (out == 1'b0)
    );

// Reset keeps the sampled output low three clocks later.
    check_reset_clears_output_three_cycles_later: assert property (
        @(posedge clk) rst |=> ##2 (out == 1'b0)
    );

// Reset keeps the sampled output low four clocks later.
    check_reset_clears_output_four_cycles_later: assert property (
        @(posedge clk) rst |=> ##3 (out == 1'b0)
    );

// Q captures D on the enabled data-load condition.
    check_q_loads_d: assert property (
        @(posedge CLK)
        (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        |=> (Q == $past(D))
    );

// Q_N captures the inverse of D on the enabled data-load condition.
    check_qn_loads_not_d: assert property (
        @(posedge CLK)
        (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        |=> (Q_N == ~$past(D))
    );

// The alternate control pattern forces Q low.
    check_q_forced_low: assert property (
        @(posedge CLK)
        (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        |=> (Q == 1'b0)
    );

// The alternate control pattern forces Q_N high.
    check_qn_forced_high: assert property (
        @(posedge CLK)
        (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        |=> (Q_N == 1'b1)
    );

// Q holds its value when neither assignment branch is taken.
    check_q_holds_when_no_branch: assert property (
        @(posedge CLK)
        !((SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0) ||
          (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1))
        |=> (Q == $past(Q))
    );

// Q_N holds its value when neither assignment branch is taken.
    check_qn_holds_when_no_branch: assert property (
        @(posedge CLK)
        !((SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0) ||
          (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1))
        |=> (Q_N == $past(Q_N))
    );

// A data-load update produces complementary outputs.
    check_complement_after_data_load: assert property (
        @(posedge CLK)
        (SCD == 1'b0 && SCE == 1'b0 && DE == 1'b1 && VPWR == 1'b1 && VGND == 1'b0)
        |=> (Q_N == ~Q)
    );

// The alternate control pattern also produces complementary outputs.
    check_complement_after_forced_state: assert property (
        @(posedge CLK)
        (SCD == 1'b1 && SCE == 1'b1 && DE == 1'b0 && VPWR == 1'b0 && VGND == 1'b1)
        |=> (Q_N == ~Q)
    );

// X matches the implemented NAND/OR/AND logic.
    check_output_function: assert property (
        @(posedge clk)
        X == ((~(A1_N & A2_N)) & (B1 | B2))
    );

// If both B inputs are low, X must be low.
    check_b_inputs_force_low: assert property (
        @(posedge clk)
        (!B1 && !B2) |-> !X
    );

// If both A inputs are high, the NAND term is low and X must be low.
    check_a_inputs_force_low: assert property (
        @(posedge clk)
        (A1_N && A2_N) |-> !X
    );

// If A1_N is low and either B input is high, X must be high.
    check_a1_low_with_b_high_sets_x: assert property (
        @(posedge clk)
        (!A1_N && (B1 || B2)) |-> X
    );

// If A2_N is low and either B input is high, X must be high.
    check_a2_low_with_b_high_sets_x: assert property (
        @(posedge clk)
        (!A2_N && (B1 || B2)) |-> X
    );

// A high X requires at least one B input to be high.
    check_x_high_requires_b_high: assert property (
        @(posedge clk)
        X |-> (B1 || B2)
    );

// A high X requires at least one A input to be low.
    check_x_high_requires_a_low: assert property (
        @(posedge clk)
        X |-> (!A1_N || !A2_N)
    );

// out_signal is 00 when the lower three input bits are 000.
    check_out_zero_for_low3_000: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b000) |-> (out_signal == 2'b00)
    );

// out_signal is 01 when the lower three input bits are 001.
    check_out_one_for_low3_001: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b001) |-> (out_signal == 2'b01)
    );

// out_signal is 01 when the lower three input bits are 010.
    check_out_one_for_low3_010: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b010) |-> (out_signal == 2'b01)
    );

// out_signal is 01 when the lower three input bits are 011.
    check_out_one_for_low3_011: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b011) |-> (out_signal == 2'b01)
    );

// out_signal is 01 when the lower three input bits are 100.
    check_out_one_for_low3_100: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b100) |-> (out_signal == 2'b01)
    );

// out_signal is 10 when the lower three input bits are 101.
    check_out_two_for_low3_101: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b101) |-> (out_signal == 2'b10)
    );

// out_signal is 10 when the lower three input bits are 110.
    check_out_two_for_low3_110: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b110) |-> (out_signal == 2'b10)
    );

// out_signal is 10 when the lower three input bits are 111.
    check_out_two_for_low3_111: assert property (
        @(posedge clk) (in_signal[2:0] == 3'b111) |-> (out_signal == 2'b10)
    );

// out_signal is 00 only for the lower-three-bits value 000.
    check_out_zero_only_for_low3_000: assert property (
        @(posedge clk) (out_signal == 2'b00) |-> (in_signal[2:0] == 3'b000)
    );

// out_signal never takes the unused value 11.
    check_out_never_11: assert property (
        @(posedge clk) (out_signal != 2'b11)
    );

// Reset clears the counter on the next clock edge.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

// Count advances from 0 to 1 when not in reset.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b000) |=> (count == 3'b001)
    );

// Count advances from 1 to 2 when not in reset.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b001) |=> (count == 3'b010)
    );

// Count advances from 2 to 3 when not in reset.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b010) |=> (count == 3'b011)
    );

// Count advances from 3 to 4 when not in reset.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b011) |=> (count == 3'b100)
    );

// Count advances from 4 to 5 when not in reset.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b100) |=> (count == 3'b101)
    );

// Count advances from 5 to 6 when not in reset.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b101) |=> (count == 3'b110)
    );

// Count advances from 6 to 7 when not in reset.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b110) |=> (count == 3'b111)
    );

// Count wraps from 7 back to 0 when not in reset.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (reset)
        (count == 3'b111) |=> (count == 3'b000)
    );

// Output matches the two XOR stages feeding the final AND.
    check_out_final_function: assert property (
        @(posedge clk) out_final == ((a ^ b) & (c ^ d))
    );

// If the first XOR stage is low, the final output must be low.
    check_first_xor_blocks_output: assert property (
        @(posedge clk) !(a ^ b) |-> !out_final
    );

// If the second XOR stage is low, the final output must be low.
    check_second_xor_blocks_output: assert property (
        @(posedge clk) !(c ^ d) |-> !out_final
    );

// A high output requires both XOR stages to be high.
    check_output_high_requires_both_xors: assert property (
        @(posedge clk) out_final |-> ((a ^ b) && (c ^ d))
    );

// If both XOR stages are high, the final output must be high.
    check_both_xors_drive_output_high: assert property (
        @(posedge clk) ((a ^ b) && (c ^ d)) |-> out_final
    );

// The first active clock after reset release increments both counters to 1.
    check_first_cycle_after_reset_release: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        $rose(rst) |-> ((count == 1) && (count1 == 1) && (clk_4sec == 1'b0) && (clk_5KHz == 1'b0))
    );

// count increments by one whenever it is not at its terminal value.
    check_count_increments_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count != 200000000) |=> (count == ($past(count) + 1))
    );

// clk_4sec stays unchanged whenever count is not at its terminal value.
    check_clk_4sec_stable_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count != 200000000) |=> $stable(clk_4sec)
    );

// count wraps to 1 after reaching its terminal value.
    check_count_wraps_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count == 200000000) |=> (count == 1)
    );

// clk_4sec toggles when count reaches its terminal value.
    check_clk_4sec_toggles_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count == 200000000) |=> (clk_4sec != $past(clk_4sec))
    );

// count1 increments by one whenever it is not at its terminal value.
    check_count1_increments_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 != 10000) |=> (count1 == ($past(count1) + 1))
    );

// clk_5KHz stays unchanged whenever count1 is not at its terminal value.
    check_clk_5khz_stable_below_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 != 10000) |=> $stable(clk_5KHz)
    );

// count1 wraps to 1 after reaching its terminal value.
    check_count1_wraps_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 == 10000) |=> (count1 == 1)
    );

// clk_5KHz toggles when count1 reaches its terminal value.
    check_clk_5khz_toggles_at_terminal: assert property (
        @(posedge clk100MHz) disable iff (!rst)
        (count1 == 10000) |=> (clk_5KHz != $past(clk_5KHz))
    );

// When disabled, the output is driven to zero.
    check_disable_drives_zero: assert property (
        @(posedge clk) !enable |-> (data_out == 8'h00)
    );

// When enabled, the output matches the implemented 8-bit left shift.
    check_enable_shifts_left_two: assert property (
        @(posedge clk) enable |-> (data_out == {data_in[5:0], 2'b00})
    );

// When enabled, the two least-significant output bits are zero.
    check_enable_lsb_zero: assert property (
        @(posedge clk) enable |-> (data_out[1:0] == 2'b00)
    );

// When enabled, output[7:2] reflects input[5:0].
    check_enable_upper_bits_map_input: assert property (
        @(posedge clk) enable |-> (data_out[7:2] == data_in[5:0])
    );

// Valid decimal inputs pass through unchanged.
    check_valid_decimal_passthrough: assert property (
        @(posedge clk)
        ((in_value == 4'd0) || (in_value == 4'd1) || (in_value == 4'd2) || (in_value == 4'd3) ||
         (in_value == 4'd4) || (in_value == 4'd5) || (in_value == 4'd6) || (in_value == 4'd7) ||
         (in_value == 4'd8) || (in_value == 4'd9))
        |-> (out_value == in_value)
    );

// Input 0 maps to output 0.
    check_digit_0_identity: assert property (
        @(posedge clk)
        (in_value == 4'd0) |-> (out_value == 4'd0)
    );

// Input 1 maps to output 1.
    check_digit_1_identity: assert property (
        @(posedge clk)
        (in_value == 4'd1) |-> (out_value == 4'd1)
    );

// Input 2 maps to output 2.
    check_digit_2_identity: assert property (
        @(posedge clk)
        (in_value == 4'd2) |-> (out_value == 4'd2)
    );

// Input 3 maps to output 3.
    check_digit_3_identity: assert property (
        @(posedge clk)
        (in_value == 4'd3) |-> (out_value == 4'd3)
    );

// Input 4 maps to output 4.
    check_digit_4_identity: assert property (
        @(posedge clk)
        (in_value == 4'd4) |-> (out_value == 4'd4)
    );

// Input 5 maps to output 5.
    check_digit_5_identity: assert property (
        @(posedge clk)
        (in_value == 4'd5) |-> (out_value == 4'd5)
    );

// Input 6 maps to output 6.
    check_digit_6_identity: assert property (
        @(posedge clk)
        (in_value == 4'd6) |-> (out_value == 4'd6)
    );

// Input 7 maps to output 7.
    check_digit_7_identity: assert property (
        @(posedge clk)
        (in_value == 4'd7) |-> (out_value == 4'd7)
    );

// Input 8 maps to output 8.
    check_digit_8_identity: assert property (
        @(posedge clk)
        (in_value == 4'd8) |-> (out_value == 4'd8)
    );

// Input 9 maps to output 9.
    check_digit_9_identity: assert property (
        @(posedge clk)
        (in_value == 4'd9) |-> (out_value == 4'd9)
    );

// When ctrl is low, the output selects D0.
    check_select_d0: assert property (
        @(posedge clk) !ctrl |-> (S === D0)
    );

// When ctrl is high, the output selects D1.
    check_select_d1: assert property (
        @(posedge clk) ctrl |-> (S === D1)
    );

// The output always matches the mux equation.
    check_mux_equation: assert property (
        @(posedge clk) (S === (ctrl ? D1 : D0))
    );

// If both data inputs are equal, the output matches that common value.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (D0 === D1) |-> (S === D0)
    );

// Y implements ~(B1 & (A1 | A2 | A3)).
    check_functional_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~(B1 & (A1 | A2 | A3))
    );

// B1 low forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        !B1 |-> Y
    );

// All A inputs low force the OR term low and Y high.
    check_all_a_low_forces_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        !(A1 | A2 | A3) |-> Y
    );

// A1 high with B1 high forces Y low.
    check_a1_and_b1_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && B1) |-> !Y
    );

// A2 high with B1 high forces Y low.
    check_a2_and_b1_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A2 && B1) |-> !Y
    );

// A3 high with B1 high forces Y low.
    check_a3_and_b1_force_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (A3 && B1) |-> !Y
    );

// Y low requires B1 high and at least one A input high.
    check_y_low_requires_b1_and_any_a: assert property (
        @(posedge clk) disable iff (1'b0)
        !Y |-> (B1 && (A1 | A2 | A3))
    );

// Y high while B1 is high requires all A inputs low.
    check_y_high_with_b1_requires_all_a_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y && B1) |-> !(A1 | A2 | A3)
    );

// Reset drives the flop output low.
    check_reset_clears_output: assert property (
        @(posedge clk) !reset |-> (data_out == 1'b0)
    );

// With enable high and data_in high, the output becomes high on the next cycle.
    check_enable_captures_one: assert property (
        @(posedge clk) disable iff (!reset)
        (enable && data_in) |=> (data_out == 1'b1)
    );

// With enable high and data_in low, the output becomes low on the next cycle.
    check_enable_captures_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (enable && !data_in) |=> (data_out == 1'b0)
    );

// With enable low, the output holds its value.
    check_disable_holds_output: assert property (
        @(posedge clk) disable iff (!reset)
        (!enable) |=> $stable(data_out)
    );

// SUM is the XOR of A, B, and CI.
    check_sum_xor: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT is high when at least two inputs are high.
    check_cout_majority: assert property (
        @(posedge clk) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// The outputs match the 2-bit binary sum of the inputs.
    check_full_add_value: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// All-zero inputs produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> ((SUM == 1'b0) && (COUT == 1'b0))
    );

// Exactly one high input produces SUM high and COUT low.
    check_single_one_case: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI))
        |-> ((SUM == 1'b1) && (COUT == 1'b0))
    );

// Exactly two high inputs produce SUM low and COUT high.
    check_double_one_case: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI))
        |-> ((SUM == 1'b0) && (COUT == 1'b1))
    );

// All-one inputs produce SUM high and COUT high.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> ((SUM == 1'b1) && (COUT == 1'b1))
    );

// Reset clears count and the max flag on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (count == 4'd0) && (max_value_reached == 1'b0)
    );

// Count holds its value when enable is low.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> $stable(count)
    );

// The max flag holds its value when enable is low.
    check_max_flag_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> $stable(max_value_reached)
    );

// An enabled count of 15 wraps to 0 and raises the max flag.
    check_wrap_and_flag_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'd15) |=> (count == 4'd0) && (max_value_reached == 1'b1)
    );

// Any enabled non-wrap cycle clears the max flag.
    check_non_wrap_clears_flag: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'd15) |=> (max_value_reached == 1'b0)
    );

// When enabled and set_value differs from count, count loads set_value.
    check_load_set_value_when_different: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'd15) && (set_value != count)
        |=> (count == $past(set_value))
    );

// When enabled and set_value matches count, count increments by one.
    check_increment_when_set_matches_count: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'd15) && (set_value == count)
        |=> (count == ($past(count) + 4'd1))
    );

// Y must always be the bitwise complement of A.
    check_output_is_complement: assert property (
        @(posedge clk) (Y === ~A)
    );

// Y[0] must invert A[0].
    check_bit0_complement: assert property (
        @(posedge clk) (Y[0] === ~A[0])
    );

// Y[1] must invert A[1].
    check_bit1_complement: assert property (
        @(posedge clk) (Y[1] === ~A[1])
    );

// Y[2] must invert A[2].
    check_bit2_complement: assert property (
        @(posedge clk) (Y[2] === ~A[2])
    );

// Y[3] must invert A[3].
    check_bit3_complement: assert property (
        @(posedge clk) (Y[3] === ~A[3])
    );

// D is always one of the 0-to-3 encoded values.
    check_d_upper_bits_zero: assert property (
        @(posedge clk) D[3:2] == 2'b00
    );

// C is always one of the 0-to-3 encoded values.
    check_c_upper_bits_zero: assert property (
        @(posedge clk) C[3:2] == 2'b00
    );

// Output is a five-cycle delayed copy of the input.
    check_output_five_cycle_delay: assert property (
        @(posedge clk_in) 1'b1 |-> ##5 (o_out == $past(i_in,5))
    );

// equal must reflect A == B.
    check_equal_function: assert property (
        @(posedge clk) equal == (A == B)
    );

// greater_than must reflect A > B.
    check_greater_than_function: assert property (
        @(posedge clk) greater_than == (A > B)
    );

// less_than must reflect A < B.
    check_less_than_function: assert property (
        @(posedge clk) less_than == (A < B)
    );

// Outputs must be mutually exclusive.
    check_outputs_mutually_exclusive: assert property (
        @(posedge clk) !(equal && greater_than) &&
                       !(equal && less_than) &&
                       !(greater_than && less_than)
    );

// Exactly one comparison result must be active.
    check_one_result_active: assert property (
        @(posedge clk) equal || greater_than || less_than
    );

// Y implements the inverted OR of B1 and A1&A2.
    check_y_matches_a21oi_function: assert property (
        @(posedge clk) Y == ~((A1 & A2) | B1)
    );

// B1 high forces the NOR output low.
    check_b1_high_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A1 and A2 high force the AND term high and drive Y low.
    check_a1a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1 low and A1 low, the AND term is low and Y is high.
    check_b1_low_a1_low_gives_y_high: assert property (
        @(posedge clk) (!B1 && !A1) |-> Y
    );

// With B1 low and A2 low, the AND term is low and Y is high.
    check_b1_low_a2_low_gives_y_high: assert property (
        @(posedge clk) (!B1 && !A2) |-> Y
    );

// Y high only when B1 is low and the A1&A2 term is low.
    check_y_high_only_for_valid_inputs: assert property (
        @(posedge clk) Y |-> (!B1 && !(A1 && A2))
    );

// Y low only when B1 is high or the A1&A2 term is high.
    check_y_low_only_for_valid_inputs: assert property (
        @(posedge clk) !Y |-> (B1 || (A1 && A2))
    );

// The output must always match the mux expression.
    check_mux_function: assert property (
        @(posedge clk) out === (select ? in2 : in1)
    );

// When select is low, the output must match in1.
    check_select_low_routes_in1: assert property (
        @(posedge clk) (select === 1'b0) |-> (out === in1)
    );

// When select is high, the output must match in2.
    check_select_high_routes_in2: assert property (
        @(posedge clk) (select === 1'b1) |-> (out === in2)
    );

// out[0] is the OR reduction of the lower nibble.
    check_lower_or: assert property (
        @(posedge clk) out[0] == (|in[3:0])
    );

// out[1] is the AND reduction of the lower nibble.
    check_lower_and: assert property (
        @(posedge clk) out[1] == (&in[3:0])
    );

// out[2] is the OR reduction of the upper nibble.
    check_upper_or: assert property (
        @(posedge clk) out[2] == (|in[7:4])
    );

// out[3] is the AND reduction of the upper nibble.
    check_upper_and: assert property (
        @(posedge clk) out[3] == (&in[7:4])
    );

// X matches the implemented combinational function.
    check_output_equation: assert property (
        @(posedge clk)
        X == ((A ^ D) & VPWR & VGND & VPB & VNB)
    );

// Any low power pin forces X low.
    check_any_supply_low_forces_zero: assert property (
        @(posedge clk)
        (!VPWR || !VGND || !VPB || !VNB) |-> !X
    );

// With all supplies high and D low, X follows A.
    check_d_low_output_follows_a: assert property (
        @(posedge clk)
        (VPWR && VGND && VPB && VNB && !D) |-> (X == A)
    );

// With all supplies high and D high, X is the inverse of A.
    check_d_high_output_inverts_a: assert property (
        @(posedge clk)
        (VPWR && VGND && VPB && VNB && D) |-> (X == ~A)
    );

// With all supplies high, equal A and D drive X low.
    check_equal_inputs_drive_zero: assert property (
        @(posedge clk)
        (VPWR && VGND && VPB && VNB && (A == D)) |-> !X
    );

// With all supplies high, different A and D drive X high.
    check_different_inputs_drive_one: assert property (
        @(posedge clk)
        (VPWR && VGND && VPB && VNB && (A != D)) |-> X
    );

// Sum[0] is the XOR of A[0], B[0], and Cin.
    check_sum_bit0_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum[1] uses Sum[0] as the third XOR input.
    check_sum_bit1_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Sum[1] == (A[1] ^ B[1] ^ Sum[0])
    );

// Sum[2] uses Sum[1] as the third XOR input.
    check_sum_bit2_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Sum[2] == (A[2] ^ B[2] ^ Sum[1])
    );

// Sum[3] uses Sum[2] as the third XOR input.
    check_sum_bit3_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Sum[3] == (A[3] ^ B[3] ^ Sum[2])
    );

// Sum matches the expanded XOR chain from the inputs.
    check_sum_bus_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Sum == {
            (A[3] ^ B[3] ^ A[2] ^ B[2] ^ A[1] ^ B[1] ^ A[0] ^ B[0] ^ Cin),
            (A[2] ^ B[2] ^ A[1] ^ B[1] ^ A[0] ^ B[0] ^ Cin),
            (A[1] ^ B[1] ^ A[0] ^ B[0] ^ Cin),
            (A[0] ^ B[0] ^ Cin)
        }
    );

// Cout is tied directly to Sum[3].
    check_cout_matches_sum_msb: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == Sum[3]
    );

// Cout matches the expanded XOR expression for the top bit.
    check_cout_definition: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == (A[3] ^ B[3] ^ A[2] ^ B[2] ^ A[1] ^ B[1] ^ A[0] ^ B[0] ^ Cin)
    );

// Full 5-bit output matches the zero-extended addition.
    check_full_result: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Carry-out is high exactly when the total exceeds 15.
    check_cout_threshold: assert property (
        @(posedge clk) disable iff (1'b0)
        cout == (({1'b0, a} + {1'b0, b} + cin) > 5'd15)
    );

// Sum bit 0 matches the LSB addition XOR relation.
    check_sum_lsb: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Without carry-out, sum equals the full addition result.
    check_no_carry_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        !cout |-> ({1'b0, sum} == ({1'b0, a} + {1'b0, b} + cin))
    );

// With carry-out, sum holds the addition result modulo 16.
    check_carry_wrap_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        cout |-> (({1'b0, sum} + 5'd16) == ({1'b0, a} + {1'b0, b} + cin))
    );

// Bit 0 sum matches the first full adder XOR.
    check_bit0_sum: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 2 sum uses the carry from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) sum[2] == (a[2] ^ b[2] ^ fa_carry(a[1], b[1], fa_carry(a[0], b[0], cin)))
    );

// Bit 3 sum uses the carry from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk) sum[3] == (a[3] ^ b[3] ^ fa_carry(a[2], b[2], fa_carry(a[1], b[1], fa_carry(a[0], b[0], cin))))
    );

// All-zero inputs produce an all-zero result.
    check_zero_inputs: assert property (
        @(posedge clk) (a == 4'b0000 && b == 4'b0000 && cin == 1'b0) |-> ({cout, sum} == 5'b00000)
    );

// Max inputs with carry-in produce the maximum 5-bit sum.
    check_max_input_overflow: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> ({cout, sum} == 5'h1F)
    );

// Carry-in propagates through all stages when adding 0xF and 0x0.
    check_full_carry_propagation: assert property (
        @(posedge clk) (a == 4'hF && b == 4'h0 && cin == 1'b1) |-> ({cout, sum} == 5'h10)
    );

// Input 000 decodes to bit 0.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b00000001)
    );

// Input 001 decodes to bit 1.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b00000010)
    );

// Input 010 decodes to bit 2.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b00000100)
    );

// Input 011 decodes to bit 3.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b00001000)
    );

// Input 100 decodes to bit 4.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b00010000)
    );

// Input 101 decodes to bit 5.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b00100000)
    );

// Input 110 decodes to bit 6.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b01000000)
    );

// Input 111 decodes to bit 7.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b10000000)
    );

// Output is always one-hot.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// The top-level output is the internal sum bus.
    check_out_matches_sum: assert property (
        @(posedge clk) out == sum
    );

// Bit 0 sum matches the full-adder XOR equation.
    check_stage0_sum: assert property (
        @(posedge clk) sum[0] == (in1[0] ^ in2[0] ^ cin)
    );

// Stage 0 carry matches the full-adder carry equation.
    check_stage0_carry: assert property (
        @(posedge clk) c1 == ((in1[0] & in2[0]) | ((in1[0] ^ in2[0]) & cin))
    );

// Bit 1 sum uses the ripple carry from stage 0.
    check_stage1_sum: assert property (
        @(posedge clk) sum[1] == (in1[1] ^ in2[1] ^ c1)
    );

// Stage 1 carry matches the full-adder carry equation.
    check_stage1_carry: assert property (
        @(posedge clk) c2 == ((in1[1] & in2[1]) | ((in1[1] ^ in2[1]) & c1))
    );

// Bit 2 sum uses the ripple carry from stage 1.
    check_stage2_sum: assert property (
        @(posedge clk) sum[2] == (in1[2] ^ in2[2] ^ c2)
    );

// Stage 2 carry matches the full-adder carry equation.
    check_stage2_carry: assert property (
        @(posedge clk) c3 == ((in1[2] & in2[2]) | ((in1[2] ^ in2[2]) & c2))
    );

// Bit 3 sum uses the ripple carry from stage 2.
    check_stage3_sum: assert property (
        @(posedge clk) sum[3] == (in1[3] ^ in2[3] ^ c3)
    );

// Final carry-out matches the full-adder carry equation.
    check_stage3_carry: assert property (
        @(posedge clk) cout == ((in1[3] & in2[3]) | ((in1[3] ^ in2[3]) & c3))
    );

// The full 5-bit result matches arithmetic addition.
    check_full_sum: assert property (
        @(posedge clk) {cout, out} == ({1'b0, in1} + {1'b0, in2} + cin)
    );

// Count increments by one when it is below 15.
    check_count_increments_until_max: assert property (
        @(posedge clk)
        (count != 4'd15) |=> (count == ($past(count) + 4'd1))
    );

// Count wraps to 0 after reaching 15.
    check_count_wraps_after_max: assert property (
        @(posedge clk)
        (count == 4'd15) |=> (count == 4'd0)
    );

// A left shift always zero-fills the least significant output bit.
    check_left_shift_zero_fill: assert property (
        @(posedge clk) (shift_dir == 1'b0) |=> (out[0] == 1'b0)
    );

// A right shift always zero-fills the most significant output bit.
    check_right_shift_zero_fill: assert property (
        @(posedge clk) (shift_dir == 1'b1) |=> (out[3] == 1'b0)
    );

// Add mode returns the full 5-bit A+B+carry_in result.
    check_add_path_full_result: assert property (
        @(posedge clk)
        (!select) |-> ({carry_out, out} == ({1'b0, A} + {1'b0, B} + {{4{1'b0}}, carry_in}))
    );

// Shift mode returns A left-shifted by B.
    check_shift_path_output: assert property (
        @(posedge clk)
        select |-> (out == (A << B))
    );

// carry_out always matches the adder carry bit.
    check_carry_out_matches_adder: assert property (
        @(posedge clk)
        (carry_out == (({1'b0, A} + {1'b0, B} + {{4{1'b0}}, carry_in}) >= 5'd16))
    );

// In add mode, bit 0 follows the full-adder XOR equation.
    check_add_lsb_sum: assert property (
        @(posedge clk)
        (!select) |-> (out[0] == (A[0] ^ B[0] ^ carry_in))
    );

// A zero shift amount passes A through in shift mode.
    check_shift_zero_amount_passes_a: assert property (
        @(posedge clk)
        (select && (B == 4'h0)) |-> (out == A)
    );

// Shifting a 4-bit value by 4 or more clears the output.
    check_shift_large_amount_clears_out: assert property (
        @(posedge clk)
        (select && (B >= 4'd4)) |-> (out == 4'h0)
    );

// A zero input stays zero in shift mode.
    check_shift_zero_input_yields_zero: assert property (
        @(posedge clk)
        (select && (A == 4'h0)) |-> (out == 4'h0)
    );

// Zero operands in add mode only reflect carry_in.
    check_add_zero_operands_reflect_carry_in: assert property (
        @(posedge clk)
        ((!select) && (A == 4'h0) && (B == 4'h0)) |-> ((out == {3'b000, carry_in}) && (carry_out == 1'b0))
    );

// Zero B and zero carry pass A through in add mode.
    check_add_zero_b_no_carry_passes_a: assert property (
        @(posedge clk)
        ((!select) && (B == 4'h0) && (carry_in == 1'b0)) |-> ((out == A) && (carry_out == 1'b0))
    );

// Zero A and zero carry pass B through in add mode.
    check_add_zero_a_no_carry_passes_b: assert property (
        @(posedge clk)
        ((!select) && (A == 4'h0) && (carry_in == 1'b0)) |-> ((out == B) && (carry_out == 1'b0))
    );

// Y must equal the 4-input NOR of A, B, C, and D.
    check_nor_equation: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

// Y must be high when all inputs are low.
    check_all_low_gives_high: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0)) |-> (Y == 1'b1)
    );

// A high must force Y low.
    check_a_high_gives_low: assert property (
        @(posedge clk) (A == 1'b1) |-> (Y == 1'b0)
    );

// B high must force Y low.
    check_b_high_gives_low: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == 1'b0)
    );

// C high must force Y low.
    check_c_high_gives_low: assert property (
        @(posedge clk) (C == 1'b1) |-> (Y == 1'b0)
    );

// D high must force Y low.
    check_d_high_gives_low: assert property (
        @(posedge clk) (D == 1'b1) |-> (Y == 1'b0)
    );

// Y high implies every input is low.
    check_high_output_requires_all_low: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A == 1'b0) && (B == 1'b0) && (C == 1'b0) && (D == 1'b0))
    );

// Y low implies at least one input is high.
    check_low_output_requires_some_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A == 1'b1) || (B == 1'b1) || (C == 1'b1) || (D == 1'b1))
    );

// Reset drives the counter to zero.
    check_count_zero_on_reset: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// An enabled cycle increments the counter by one modulo 16.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        en |=> (count == ($past(count) + 4'd1))
    );

// A disabled cycle holds the counter value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        !en |=> (count == $past(count))
    );

// No RTL clock/reset; sample combinational behavior on clk.

    // MO always matches the RTL ternary inversion.
    check_output_function: assert property (
        @(posedge clk) MO == ((S == 1'b1) ? ~B : ~A)
    );

// When S selects B and B is low, MO is high.
    check_select_b_when_b_low: assert property (
        @(posedge clk) ((S == 1'b1) && (B == 1'b0)) |-> (MO == 1'b1)
    );

// When S selects B and B is high, MO is low.
    check_select_b_when_b_high: assert property (
        @(posedge clk) ((S == 1'b1) && (B == 1'b1)) |-> (MO == 1'b0)
    );

// When S selects A and A is low, MO is high.
    check_select_a_when_a_low: assert property (
        @(posedge clk) ((S == 1'b0) && (A == 1'b0)) |-> (MO == 1'b1)
    );

// When S selects A and A is high, MO is low.
    check_select_a_when_a_high: assert property (
        @(posedge clk) ((S == 1'b0) && (A == 1'b1)) |-> (MO == 1'b0)
    );

// Y matches the implemented combinational function.
    check_y_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((A1 & A2 & ~A3) | (B1 & ~C1) | (~C1 & (A1 ~^ A2)))
    );

// When C1 is high, only the A1/A2/A3 term can drive Y.
    check_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        C1 |-> (Y == (A1 & A2 & ~A3))
    );

// When C1 is low, Y reduces to B1 OR equality of A1 and A2.
    check_y_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        !C1 |-> (Y == (B1 | (A1 ~^ A2)))
    );

// The explicit A1&A2&~A3 term always forces Y high.
    check_a_term_drives_y: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & A2 & ~A3) |-> Y
    );

// When C1 is low and A1 equals A2, the S5 path forces Y high.
    check_equal_a_inputs_drive_y_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!C1 && (A1 ~^ A2)) |-> Y
    );

// When C1 is low, B1 is low, and A1 differs from A2, Y must be low.
    check_unequal_a_inputs_need_b1_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!C1 && !B1 && (A1 ^ A2)) |-> !Y
    );

// With C1 high, A3 high blocks the A1&A2 term.
    check_a3_blocks_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C1 && A1 && A2 && A3) |-> !Y
    );

// With C1 high, A3 low enables the A1&A2 term.
    check_a3_enables_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C1 && A1 && A2 && !A3) |-> Y
    );

// sel1=0 and sel0=0 must route in0 to out.
    check_select_00_routes_in0: assert property (
        @(posedge clk) ((sel1 == 1'b0) && (sel0 == 1'b0)) |-> (out == in0)
    );

// sel1=0 and sel0=1 must route in1 to out.
    check_select_01_routes_in1: assert property (
        @(posedge clk) ((sel1 == 1'b0) && (sel0 == 1'b1)) |-> (out == in1)
    );

// sel1=1 and sel0=0 must route in2 to out.
    check_select_10_routes_in2: assert property (
        @(posedge clk) ((sel1 == 1'b1) && (sel0 == 1'b0)) |-> (out == in2)
    );

// sel1=1 and sel0=1 must route in3 to out.
    check_select_11_routes_in3: assert property (
        @(posedge clk) ((sel1 == 1'b1) && (sel0 == 1'b1)) |-> (out == in3)
    );

// When the lower pair matches and sel1 selects it, sel0 cannot change out.
    check_sel1_low_equal_lower_pair: assert property (
        @(posedge clk) ((sel1 == 1'b0) && (in0 == in1)) |-> (out == in0)
    );

// When the upper pair matches and sel1 selects it, sel0 cannot change out.
    check_sel1_high_equal_upper_pair: assert property (
        @(posedge clk) ((sel1 == 1'b1) && (in2 == in3)) |-> (out == in2)
    );

// When left-side inputs match and sel0 selects them, sel1 cannot change out.
    check_sel0_low_equal_left_inputs: assert property (
        @(posedge clk) ((sel0 == 1'b0) && (in0 == in2)) |-> (out == in0)
    );

// When right-side inputs match and sel0 selects them, sel1 cannot change out.
    check_sel0_high_equal_right_inputs: assert property (
        @(posedge clk) ((sel0 == 1'b1) && (in1 == in3)) |-> (out == in1)
    );

// Z implements (A&B) | (C&D) | E.
    check_output_function: assert property (
        @(posedge clk) Z == ((A & B) | (C & D) | E)
    );

// E high must force Z high.
    check_e_term_drives_z: assert property (
        @(posedge clk) E |-> Z
    );

// A and B high must force Z high.
    check_ab_term_drives_z: assert property (
        @(posedge clk) (A & B) |-> Z
    );

// C and D high must force Z high.
    check_cd_term_drives_z: assert property (
        @(posedge clk) (C & D) |-> Z
    );

// If all three OR terms are low, Z must be low.
    check_no_active_term_means_z_low: assert property (
        @(posedge clk) (!(A & B) && !(C & D) && !E) |-> !Z
    );

// If Z is low, none of the three OR terms can be high.
    check_z_low_implies_no_active_term: assert property (
        @(posedge clk) !Z |-> (!(A & B) && !(C & D) && !E)
    );

// Clock: clk
    // Reset: none
    // Sequential accumulator with registered output

    // The accumulator adds the previous cycle's data on each rising clock edge.
    check_accumulates_data: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> acc == ($past(acc) + $past(data))
    );

// The cycle-to-cycle change in acc matches the previous cycle's data.
    check_cycle_delta_matches_data: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (acc - $past(acc)) == $past(data)
    );

// A zero input leaves the accumulator unchanged on the next cycle.
    check_hold_on_zero_data: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'd0 |=> acc == $past(acc)
    );

// An input of one increments the accumulator by one on the next cycle.
    check_increment_on_one: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'd1 |=> acc == ($past(acc) + 16'd1)
    );

// If the accumulator is zero, the next value equals the current input data.
    check_load_data_from_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        acc == 16'd0 |=> acc == $past(data)
    );

// Adding one to 16'hFFFF wraps the accumulator to zero.
    check_wrap_on_full_plus_one: assert property (
        @(posedge clk) disable iff (1'b0)
        (acc == 16'hFFFF) && (data == 16'd1) |=> acc == 16'd0
    );

// An input of 16'hFFFF decrements the accumulator by one on the next cycle.
    check_decrement_on_all_ones_data: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'hFFFF |=> acc == ($past(acc) - 16'd1)
    );

// Q must follow the RTL's full combinational mapping.
    check_full_mapping: assert property (
        @(posedge clk)
        Q == ((D[3] == 1'b0) ? D[2:0] : {1'b0, (D[3:2] - 2'b11)})
    );

// Inputs 0 through 7 pass D[2:0] directly to Q.
    check_low_range_passthrough: assert property (
        @(posedge clk)
        (D[3] == 1'b0) |-> (Q == D[2:0])
    );

// Inputs 8 through 15 use the subtract result, zero-extended to 3 bits.
    check_high_range_conversion: assert property (
        @(posedge clk)
        (D[3] == 1'b1) |-> (Q == {1'b0, (D[3:2] - 2'b11)})
    );

// For inputs 8 through 11, Q must be 3.
    check_range_8_to_11_value: assert property (
        @(posedge clk)
        (D[3:2] == 2'b10) |-> (Q == 3'b011)
    );

// For inputs 12 through 15, Q must be 0.
    check_range_12_to_15_value: assert property (
        @(posedge clk)
        (D[3:2] == 2'b11) |-> (Q == 3'b000)
    );

// The upper bit of Q is cleared whenever the subtract path is selected.
    check_high_range_msb_zero: assert property (
        @(posedge clk)
        (D[3] == 1'b1) |-> (Q[2] == 1'b0)
    );

// CLR1 clears the upper nibble on the next posedge sample.
    check_reg1_clear: assert property (
        @(posedge CLK) disable iff (1'b0)
        CLR1 |=> (Q[7:4] == 4'b0000)
    );

// CLR1 has priority over PL1 when both are asserted.
    check_reg1_clear_priority: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLR1 && PL1) |=> (Q[7:4] == 4'b0000)
    );

// PL1 loads D1 into the upper nibble when CLR1 is low.
    check_reg1_parallel_load: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR1 && PL1) |=> (Q[7:4] == $past(D1))
    );

// Without CLR1 or PL1, the upper nibble rotates left by one bit.
    check_reg1_rotate: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR1 && !PL1) |=> (Q[7:4] == {$past(Q[6:4]), $past(Q[7])})
    );

// EN2 loads the lower nibble with D2 on the next negedge sample.
    check_reg2_load_d2: assert property (
        @(negedge CLK) disable iff (1'b0)
        EN2 |=> (Q[3:0] == $past(D2))
    );

// Without EN2, the lower nibble holds its value across negedges.
    check_reg2_hold: assert property (
        @(negedge CLK) disable iff (1'b0)
        (!EN2) |=> (Q[3:0] == $past(Q[3:0]))
    );

// In add mode, C equals the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) (control == 1'b0) |-> (C == (A + B))
    );

// In subtract mode, C equals the 4-bit difference of A and B.
    check_sub_mode_result: assert property (
        @(posedge clk) (control == 1'b1) |-> (C == (A - B))
    );

// Addresses below 0x0800 decode to zero on the next clock.
    check_low_range_zero: assert property (
        @(posedge clock)
        (address < 15'h0800) |=> (q == 12'h000)
    );

// Addresses 0x0800 through 0x0FFF pass through the low 12 bits on the next clock.
    check_mid_range_passthrough: assert property (
        @(posedge clock)
        (address >= 15'h0800 && address < 15'h1000) |=> (q == $past(address[11:0]))
    );

// Addresses 0x1000 and above decode to address[14:3] on the next clock.
    check_high_range_slice: assert property (
        @(posedge clock)
        (address >= 15'h1000) |=> (q == $past(address[14:3]))
    );

// 0x07FF is still in the zero-decoded range.
    check_boundary_07ff: assert property (
        @(posedge clock)
        (address == 15'h07FF) |=> (q == 12'h000)
    );

// 0x0800 is the first address that passes through its low 12 bits.
    check_boundary_0800: assert property (
        @(posedge clock)
        (address == 15'h0800) |=> (q == 12'h800)
    );

// 0x0FFF is the last address in the pass-through range.
    check_boundary_0fff: assert property (
        @(posedge clock)
        (address == 15'h0FFF) |=> (q == 12'hFFF)
    );

// 0x1000 is the first address that uses address[14:3].
    check_boundary_1000: assert property (
        @(posedge clock)
        (address == 15'h1000) |=> (q == 12'h200)
    );

// 0x7FFF maps to the maximum sliced output value.
    check_boundary_7fff: assert property (
        @(posedge clock)
        (address == 15'h7FFF) |=> (q == 12'hFFF)
    );

// ALU B passes through its input when no forwarding condition matches.
    check_alu_b_sel_default: assert property (
        @(posedge clk)
        (!((addr_alu_b_in == ex_mem_reg_a_addr_in) & ex_mem_reg_a_wr_ena_in) &&
         !((addr_alu_b_in == ex_mem_reg_b_addr_in) & ex_mem_reg_b_wr_ena_in) &&
         !((addr_alu_b_in == wb_reg_a_addr_in) & wb_reg_a_wr_ena_in) &&
         !((addr_alu_b_in == wb_reg_b_addr_in) & wb_reg_b_wr_ena_in))
        |-> (alu_b_mux_sel_out == data_alu_b_in)
    );

// When enabled in test mode, q captures d by the next clock.
    check_capture_te_branch: assert property (
        @(posedge clk) (en && te) |=> (q == $past(d))
    );

// When enabled in normal mode, q captures d by the next clock.
    check_capture_normal_branch: assert property (
        @(posedge clk) (en && !te) |=> (q == $past(d))
    );

// When disabled with te high, q holds its value.
    check_hold_disabled_te_high: assert property (
        @(posedge clk) (!en && te) |=> (q == $past(q))
    );

// When disabled with te low, q holds its value.
    check_hold_disabled_te_low: assert property (
        @(posedge clk) (!en && !te) |=> (q == $past(q))
    );

// If enabled and d differs from q, q updates to the new value on the next clock.
    check_update_when_enabled_and_data_differs: assert property (
        @(posedge clk) (en && (d != q)) |=> ((q == $past(d)) && (q != $past(q)))
    );

// c_out equals group generate OR propagated input carry.
    check_cout_group_relation: assert property (
        @(posedge clk) c_out == (G | (P & c_in))
    );

// trn_pending is cleared while reset is active.
    check_trn_pending_reset: assert property (
        @(posedge clk) !rst_n |-> (trn_pending == 1'b0)
    );

// cfg_turnoff_ok is cleared while reset is active.
    check_cfg_turnoff_ok_reset: assert property (
        @(posedge clk) !rst_n |-> (cfg_turnoff_ok == 1'b0)
    );

// Without a turnoff request, cfg_turnoff_ok is low on the next cycle.
    check_turnoff_ok_low_without_request: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!cfg_to_turnoff) |=> (cfg_turnoff_ok == 1'b0)
    );

// The output matches the full input-derived expression.
    check_out_end_to_end: assert property (
        @(posedge clk) out == (in[15:12] + expected_stage3_from_in(in))
    );

// No clock or reset exists in the RTL; sample combinational behavior on clk.

    // Positive in-phase and positive quadrature map to 00.
    check_pospos_symbol: assert property (
        @(posedge clk)
        (in0_re > 16'sd0 && in0_im > 16'sd0) |-> (out0 == 2'b00)
    );

// Positive in-phase and zero quadrature map to 00.
    check_poszero_symbol: assert property (
        @(posedge clk)
        (in0_re > 16'sd0 && in0_im == 16'sd0) |-> (out0 == 2'b00)
    );

// Positive in-phase and negative quadrature map to 10.
    check_posneg_symbol: assert property (
        @(posedge clk)
        (in0_re > 16'sd0 && in0_im < 16'sd0) |-> (out0 == 2'b10)
    );

// Zero in-phase and positive quadrature map to 01.
    check_zeropos_symbol: assert property (
        @(posedge clk)
        (in0_re == 16'sd0 && in0_im > 16'sd0) |-> (out0 == 2'b01)
    );

// Zero in-phase and zero quadrature map to 00.
    check_zerozero_symbol: assert property (
        @(posedge clk)
        (in0_re == 16'sd0 && in0_im == 16'sd0) |-> (out0 == 2'b00)
    );

// Zero in-phase and negative quadrature map to 10.
    check_zeroneg_symbol: assert property (
        @(posedge clk)
        (in0_re == 16'sd0 && in0_im < 16'sd0) |-> (out0 == 2'b10)
    );

// Negative in-phase and positive quadrature map to 01.
    check_negpos_symbol: assert property (
        @(posedge clk)
        (in0_re < 16'sd0 && in0_im > 16'sd0) |-> (out0 == 2'b01)
    );

// Negative in-phase and zero quadrature map to 11.
    check_negzero_symbol: assert property (
        @(posedge clk)
        (in0_re < 16'sd0 && in0_im == 16'sd0) |-> (out0 == 2'b11)
    );

// Negative in-phase and negative quadrature map to 11.
    check_negneg_symbol: assert property (
        @(posedge clk)
        (in0_re < 16'sd0 && in0_im < 16'sd0) |-> (out0 == 2'b11)
    );

// Q2 shifts in the previous Q1 value.
    check_q2_shift: assert property (
        @(posedge CLK) 1'b1 |=> (Q2 == $past(Q1))
    );

// Q1 shifts in the previous Q0 value.
    check_q1_shift: assert property (
        @(posedge CLK) 1'b1 |=> (Q1 == $past(Q0))
    );

// Q0 is the XOR of the previous Q2 and Q1 values.
    check_q0_feedback: assert property (
        @(posedge CLK) 1'b1 |=> (Q0 == ($past(Q2) ^ $past(Q1)))
    );

// The full 3-bit output state follows the RTL next-state function.
    check_state_update: assert property (
        @(posedge CLK) 1'b1 |=> ({Q2, Q1, Q0} == {$past(Q1), $past(Q0), ($past(Q2) ^ $past(Q1))})
    );

// Equal previous Q2 and Q1 drive Q0 low on the next cycle.
    check_feedback_zero_case: assert property (
        @(posedge CLK) (Q2 == Q1) |=> (Q0 == 1'b0)
    );

// Different previous Q2 and Q1 drive Q0 high on the next cycle.
    check_feedback_one_case: assert property (
        @(posedge CLK) (Q2 != Q1) |=> (Q0 == 1'b1)
    );

// The all-zero state remains all-zero on the next cycle.
    check_zero_lockup: assert property (
        @(posedge CLK) ({Q2, Q1, Q0} == 3'b000) |=> ({Q2, Q1, Q0} == 3'b000)
    );

// Y must implement the 2:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == ((~S & A) | (S & B))
    );

// When S is low, Y must select A.
    check_select_a: assert property (
        @(posedge clk) !S |-> (Y == A)
    );

// When S is high, Y must select B.
    check_select_b: assert property (
        @(posedge clk) S |-> (Y == B)
    );

// If both inputs are equal, Y must match that value.
    check_equal_inputs: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

// With A=0 and B=1, Y must follow S.
    check_follow_s: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1) |-> (Y == S)
    );

// With A=1 and B=0, Y must follow inverted S.
    check_follow_not_s: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0) |-> (Y == ~S)
    );

// MemWrite low suppresses all byte write enables.
    check_memwrite_masks_all_bytes: assert property (
        @(posedge clk) !MemWrite |-> (mem_byte_write_out == 4'b0000)
    );

// Store-word opcode passes rt_out through unchanged.
    check_sw_shift_passthrough: assert property (
        @(posedge clk) (IR_out == 6'b101011) |-> (rt_out_shift == rt_out)
    );

// Store-word opcode enables all byte lanes when writing.
    check_sw_full_byte_enable: assert property (
        @(posedge clk) (IR_out == 6'b101011 && MemWrite) |-> (mem_byte_write_out == 4'b1111)
    );

// Non-store-word at address 00 moves the low byte into the top byte lane.
    check_addr00_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b00) |-> (rt_out_shift == {rt_out[7:0], 24'b0})
    );

// Non-store-word at address 00 enables only the top byte lane when writing.
    check_addr00_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b00 && MemWrite) |-> (mem_byte_write_out == 4'b1000)
    );

// Non-store-word at address 01 moves the low halfword into the top halfword lanes.
    check_addr01_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b01) |-> (rt_out_shift == {rt_out[15:0], 16'b0})
    );

// Non-store-word at address 01 enables the upper two byte lanes when writing.
    check_addr01_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b01 && MemWrite) |-> (mem_byte_write_out == 4'b1100)
    );

// Non-store-word at address 10 moves the low 24 bits into the upper three byte lanes.
    check_addr10_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b10) |-> (rt_out_shift == {rt_out[23:0], 8'b0})
    );

// Non-store-word at address 10 enables the upper three byte lanes when writing.
    check_addr10_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b10 && MemWrite) |-> (mem_byte_write_out == 4'b1110)
    );

// Non-store-word at address 11 passes rt_out through unchanged.
    check_addr11_shift_passthrough: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b11) |-> (rt_out_shift == rt_out)
    );

// Non-store-word at address 11 enables all byte lanes when writing.
    check_addr11_full_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b11 && MemWrite) |-> (mem_byte_write_out == 4'b1111)
    );

// Synchronous reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// Active-low clear forces q low and qn high.
    check_sync_clear_values: assert property (
        @(posedge clk) (!clr) |=> (q == 1'b0 && qn == 1'b1)
    );

// Clear overrides enable when both are asserted.
    check_clear_priority_over_enable: assert property (
        @(posedge clk) ((!clr) && en) |=> (q == 1'b0 && qn == 1'b1)
    );

// When enabled, q captures d.
    check_enable_captures_d_to_q: assert property (
        @(posedge clk) disable iff (!clr) en |=> (q == $past(d))
    );

// When enabled, qn captures the inverse of d.
    check_enable_captures_inv_d_to_qn: assert property (
        @(posedge clk) disable iff (!clr) en |=> (qn == ~$past(d))
    );

// When enabled, q and qn remain complementary.
    check_enable_outputs_complementary: assert property (
        @(posedge clk) disable iff (!clr) en |=> (qn == ~q)
    );

// When disabled, q holds its value.
    check_hold_q_when_disabled: assert property (
        @(posedge clk) disable iff (!clr) (!en) |=> (q == $past(q))
    );

// When disabled, qn holds its value.
    check_hold_qn_when_disabled: assert property (
        @(posedge clk) disable iff (!clr) (!en) |=> (qn == $past(qn))
    );

// Output matches the 4-input OR function.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C | D)
    );

// A high forces the output high.
    check_a_drives_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces the output high.
    check_b_drives_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C high forces the output high.
    check_c_drives_x_high: assert property (
        @(posedge clk) C |-> X
    );

// D high forces the output high.
    check_d_drives_x_high: assert property (
        @(posedge clk) D |-> X
    );

// All inputs low force the output low.
    check_all_inputs_low_drives_x_low: assert property (
        @(posedge clk) !(A | B | C | D) |-> !X
    );

// Y matches the implemented OR-then-NAND function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((A1 | A2) & B1 & C1)
    );

// Y can be low only when B1, C1, and one A input are high.
    check_y_low_condition: assert property (
        @(posedge clk) (!Y) |-> (B1 & C1 & (A1 | A2))
    );

// A low B1 input forces the NAND output high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) (!B1) |-> Y
    );

// A low C1 input forces the NAND output high.
    check_c1_low_forces_y_high: assert property (
        @(posedge clk) (!C1) |-> Y
    );

// Both A inputs low force the OR term low and Y high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) ((!A1) & (!A2)) |-> Y
    );

// A1 high with B1 and C1 high drives Y low.
    check_a1_path_drives_y_low: assert property (
        @(posedge clk) (A1 & B1 & C1) |-> (!Y)
    );

// A2 high with B1 and C1 high drives Y low.
    check_a2_path_drives_y_low: assert property (
        @(posedge clk) (A2 & B1 & C1) |-> (!Y)
    );

// Y must equal the three-input AND of A, B, and C.
    check_y_matches_three_input_and: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == (A & B & C)
    );

// Y high requires all three inputs high.
    check_y_high_implies_all_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b1) |-> ((A == 1'b1) && (B == 1'b1) && (C == 1'b1))
    );

// All three inputs high must drive Y high.
    check_all_inputs_high_implies_y_high: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 1'b1) && (B == 1'b1) && (C == 1'b1)) |-> (Y == 1'b1)
    );

// Any low input must drive Y low.
    check_any_low_input_implies_y_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A == 1'b0) || (B == 1'b0) || (C == 1'b0)) |-> (Y == 1'b0)
    );

// Y low means at least one input is low.
    check_y_low_implies_at_least_one_input_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (Y == 1'b0) |-> ((A == 1'b0) || (B == 1'b0) || (C == 1'b0))
    );

// Y matches the implemented combinational equation.
    check_output_matches_equation: assert property (
        @(posedge clk) Y == (~((~A) & (~B)))
    );

// A high drives Y high.
    check_a_high_drives_output_high: assert property (
        @(posedge clk) A |-> Y
    );

// B high drives Y high.
    check_b_high_drives_output_high: assert property (
        @(posedge clk) B |-> Y
    );

// Both inputs low drive Y low.
    check_both_inputs_low_drive_output_low: assert property (
        @(posedge clk) (!A && !B) |-> !Y
    );

// A low output means both inputs are low.
    check_output_low_requires_both_inputs_low: assert property (
        @(posedge clk) !Y |-> (!A && !B)
    );

// Input 0 selects output bit 0.
    check_decode_i0: assert property (
        @(posedge clk) (I == 4'h0) |-> (O == 16'b0000000000000001)
    );

// Input 1 selects output bit 1.
    check_decode_i1: assert property (
        @(posedge clk) (I == 4'h1) |-> (O == 16'b0000000000000010)
    );

// Input 2 selects output bit 2.
    check_decode_i2: assert property (
        @(posedge clk) (I == 4'h2) |-> (O == 16'b0000000000000100)
    );

// Input 3 selects output bit 3.
    check_decode_i3: assert property (
        @(posedge clk) (I == 4'h3) |-> (O == 16'b0000000000001000)
    );

// Input 4 selects output bit 4.
    check_decode_i4: assert property (
        @(posedge clk) (I == 4'h4) |-> (O == 16'b0000000000010000)
    );

// Input 5 selects output bit 5.
    check_decode_i5: assert property (
        @(posedge clk) (I == 4'h5) |-> (O == 16'b0000000000100000)
    );

// Input 6 selects output bit 6.
    check_decode_i6: assert property (
        @(posedge clk) (I == 4'h6) |-> (O == 16'b0000000001000000)
    );

// Input 7 selects output bit 7.
    check_decode_i7: assert property (
        @(posedge clk) (I == 4'h7) |-> (O == 16'b0000000010000000)
    );

// Input 8 selects output bit 8.
    check_decode_i8: assert property (
        @(posedge clk) (I == 4'h8) |-> (O == 16'b0000000100000000)
    );

// Input 9 selects output bit 9.
    check_decode_i9: assert property (
        @(posedge clk) (I == 4'h9) |-> (O == 16'b0000001000000000)
    );

// Input A selects output bit 10.
    check_decode_ia: assert property (
        @(posedge clk) (I == 4'ha) |-> (O == 16'b0000010000000000)
    );

// Input B selects output bit 11.
    check_decode_ib: assert property (
        @(posedge clk) (I == 4'hb) |-> (O == 16'b0000100000000000)
    );

// Input C selects output bit 12.
    check_decode_ic: assert property (
        @(posedge clk) (I == 4'hc) |-> (O == 16'b0001000000000000)
    );

// Input D selects output bit 13.
    check_decode_id: assert property (
        @(posedge clk) (I == 4'hd) |-> (O == 16'b0010000000000000)
    );

// Input E selects output bit 14.
    check_decode_ie: assert property (
        @(posedge clk) (I == 4'he) |-> (O == 16'b0100000000000000)
    );

// Input F selects output bit 15.
    check_decode_if: assert property (
        @(posedge clk) (I == 4'hf) |-> (O == 16'b1000000000000000)
    );

// Output always has exactly one bit asserted.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(O)
    );

// sel=00 routes in[0] to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// sel=01 routes in[1] to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// sel=10 routes in[2] to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// sel=11 routes in[3] to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// A zero stage advances to the first active stage.
    check_stage_zero_advances: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000000) |=> (stage == 6'b000001)
    );

// Any nonzero stage shifts left by one bit.
    check_stage_nonzero_shifts_left: assert property (
        @(posedge ABCDEFGH[7]) (stage != 6'b000000) |=> (stage == {$past(stage[4:0]), 1'b0})
    );

// Stage 0 drives 64'h40 onto Y on the following clock.
    check_output_for_stage_zero: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000000) |=> (Y == 64'h0000000000000040)
    );

// Stage 1 drives 64'h01 onto Y on the following clock.
    check_output_for_stage_one: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000001) |=> (Y == 64'h0000000000000001)
    );

// Stage 2 drives 64'h02 onto Y on the following clock.
    check_output_for_stage_two: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000010) |=> (Y == 64'h0000000000000002)
    );

// Stage 4 drives 64'h04 onto Y on the following clock.
    check_output_for_stage_four: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b000100) |=> (Y == 64'h0000000000000004)
    );

// Stage 8 drives 64'h08 onto Y on the following clock.
    check_output_for_stage_eight: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b001000) |=> (Y == 64'h0000000000000008)
    );

// Stage 16 drives 64'h10 onto Y on the following clock.
    check_output_for_stage_sixteen: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b010000) |=> (Y == 64'h0000000000000010)
    );

// Stage 32 drives 64'h20 onto Y on the following clock.
    check_output_for_stage_thirty_two: assert property (
        @(posedge ABCDEFGH[7]) (stage == 6'b100000) |=> (Y == 64'h0000000000000020)
    );

// Sampling clock for this combinational DUT.

    // X matches the implemented sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        X == ((~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N))
    );

// With B1_N high, X reduces to A1 XOR A2.
    check_b1n_high_xor_behavior: assert property (
        @(posedge clk)
        B1_N |-> (X == (A1 ^ A2))
    );

// With B1_N low, X reduces to A1 AND A2.
    check_b1n_low_and_behavior: assert property (
        @(posedge clk)
        ~B1_N |-> (X == (A1 & A2))
    );

// If X is high, the inputs match one implemented minterm.
    check_x_high_only_on_implemented_minterms: assert property (
        @(posedge clk)
        X |-> ((~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N))
    );

// Any implemented minterm drives X high.
    check_implemented_minterms_drive_high: assert property (
        @(posedge clk)
        ((~A1 & A2 & B1_N) | (A1 & ~A2 & B1_N) | (A1 & A2 & ~B1_N)) |-> X
    );

// When A1 and A2 are both low, X is low.
    check_both_a_low_forces_x_low: assert property (
        @(posedge clk)
        (~A1 & ~A2) |-> ~X
    );

// When A1 and A2 are both high, X is the inverse of B1_N.
    check_both_a_high_invert_b1n: assert property (
        @(posedge clk)
        (A1 & A2) |-> (X == ~B1_N)
    );

// When exactly one of A1 or A2 is high, X follows B1_N.
    check_one_hot_a_inputs_follow_b1n: assert property (
        @(posedge clk)
        (A1 ^ A2) |-> (X == B1_N)
    );

// Up increments Q when it is not at the maximum value.
    check_up_increment: assert property (
        @(posedge clk) disable iff (1'b0)
        Up && (Q != 4'hF) |=> (Q == ($past(Q) + 4'h1))
    );

// Up wraps Q from 15 back to 0.
    check_up_wrap: assert property (
        @(posedge clk) disable iff (1'b0)
        Up && (Q == 4'hF) |=> (Q == 4'h0)
    );

// Down decrements Q when Up is low and Q is not at zero.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (1'b0)
        !Up && Down && (Q != 4'h0) |=> (Q == ($past(Q) - 4'h1))
    );

// Down wraps Q from 0 back to 15 when Up is low.
    check_down_wrap: assert property (
        @(posedge clk) disable iff (1'b0)
        !Up && Down && (Q == 4'h0) |=> (Q == 4'hF)
    );

// Q holds its value when neither Up nor Down is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (1'b0)
        !Up && !Down |=> (Q == $past(Q))
    );

// X must implement ((A1 | A2) & B1 & C1).
    check_output_function: assert property (
        @(posedge clk) X === (((A1 | A2) & B1) & C1)
    );

// X high requires B1 high.
    check_x_high_requires_b1: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires C1 high.
    check_x_high_requires_c1: assert property (
        @(posedge clk) X |-> C1
    );

// X high requires at least one of A1 or A2 high.
    check_x_high_requires_or_input: assert property (
        @(posedge clk) X |-> (A1 | A2)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// Both OR inputs low force X low.
    check_or_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// A1 with B1 and C1 high drives X high.
    check_a1_path_drives_x: assert property (
        @(posedge clk) (A1 && B1 && C1) |-> X
    );

// A2 with B1 and C1 high drives X high.
    check_a2_path_drives_x: assert property (
        @(posedge clk) (A2 && B1 && C1) |-> X
    );

// Y equals the enabled AND of A and B.
    check_y_matches_and_enable: assert property (
        @(posedge clk) Y == (A & B & C1)
    );

// Y high requires all three inputs high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A && B && C1)
    );

// All three inputs high drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A && B && C1) |-> Y
    );

// C1 low forces Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// A low forces Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// With C1 high, Y matches the AND of A and B.
    check_c1_high_passes_and_result: assert property (
        @(posedge clk) C1 |-> (Y == (A & B))
    );

// When reset is sampled high, count must be zero.
    reset_holds_count_zero: assert property (
        @(posedge clk)
        rst |-> (count == 4'b0000)
    );

// A sampled reset keeps count at zero on the next sampled cycle.
    reset_keeps_next_count_zero: assert property (
        @(posedge clk)
        rst |=> (count == 4'b0000)
    );

// Between sampled clocks, count can only increment or be cleared by async reset.
    count_next_is_zero_or_incremented: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> ((count == 4'b0000) || (count == ($past(count) + 4'd1)))
    );

// A sampled max count must wrap to zero on the next sampled active cycle.
    count_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

// EQ must be high when A and B are equal.
    check_eq_high_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ == 1'b1)
    );

// EQ must be low when A and B are different.
    check_eq_low_when_different: assert property (
        @(posedge clk) (A != B) |-> (EQ == 1'b0)
    );

// A high EQ must only occur for equal inputs.
    check_eq_high_implies_equal: assert property (
        @(posedge clk) (EQ == 1'b1) |-> (A == B)
    );

// A low EQ must only occur for different inputs.
    check_eq_low_implies_different: assert property (
        @(posedge clk) (EQ == 1'b0) |-> (A != B)
    );

// Pure combinational XNOR sampled on an external clock.

    // Y must always equal A XNOR B.
    check_xnor_function: assert property (
        @(posedge clk) Y == (A ~^ B)
    );

// Equal low inputs drive Y high.
    check_both_low_drive_high: assert property (
        @(posedge clk) (!A && !B) |-> Y
    );

// A low and B high drive Y low.
    check_a_low_b_high_drive_low: assert property (
        @(posedge clk) (!A && B) |-> !Y
    );

// A high and B low drive Y low.
    check_a_high_b_low_drive_low: assert property (
        @(posedge clk) (A && !B) |-> !Y
    );

// Equal high inputs drive Y high.
    check_both_high_drive_high: assert property (
        @(posedge clk) (A && B) |-> Y
    );

// The internal enable signal is permanently asserted.
    check_enable_const: assert property (
        @(posedge A) enable == 1'b1
    );

// The write pointer increments by one on each rising edge of A.
    check_wr_ptr_increments: assert property (
        @(posedge A) 1'b1 |=> (wr_ptr == ($past(wr_ptr) + 1'b1))
    );

// X reflects the buffer entry addressed by rd_ptr on the previous rising edge.
    check_x_updates_from_buffer: assert property (
        @(posedge A) (rd_ptr <= LAST_INDEX) |=> (X == $past(buffer[rd_ptr]))
    );

// EQ must be the only asserted output when A equals B.
    check_eq_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

// GT must be the only asserted output when A is greater than B.
    check_gt_when_greater: assert property (
        @(posedge clk) (A > B) |-> (GT && !EQ && !LT)
    );

// LT must be the only asserted output when A is less than B.
    check_lt_when_less: assert property (
        @(posedge clk) (A < B) |-> (LT && !EQ && !GT)
    );

// EQ can only assert for equal inputs.
    check_eq_only_when_equal: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// GT can only assert when A is greater than B.
    check_gt_only_when_greater: assert property (
        @(posedge clk) GT |-> (A > B)
    );

// LT can only assert when A is less than B.
    check_lt_only_when_less: assert property (
        @(posedge clk) LT |-> (A < B)
    );

// Exactly one comparison result must be asserted each cycle.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({EQ, GT, LT})
    );

// Reset keeps the output low.
    check_reset_output: assert property (
        @(posedge clock) !reset |-> (enable_out == 1'b0)
    );

// KEY_FREE with a low input decodes to KEY_PRESSED.
    check_next_free_to_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b0) |-> (next_key_state == KEY_PRESSED)
    );

// KEY_FREE with a high input stays in KEY_FREE.
    check_next_free_stays_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b1) |-> (next_key_state == KEY_FREE)
    );

// KEY_PRESSED with a low input stays in KEY_PRESSED.
    check_next_pressed_stays_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b0) |-> (next_key_state == KEY_PRESSED)
    );

// KEY_PRESSED with a high input decodes to KEY_RELEASED.
    check_next_pressed_to_released: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b1) |-> (next_key_state == KEY_RELEASED)
    );

// KEY_RELEASED always decodes back to KEY_FREE.
    check_next_released_to_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_RELEASED) |-> (next_key_state == KEY_FREE)
    );

// KEY_FREE advances to KEY_PRESSED when the input is low.
    check_state_free_to_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b0) |=> (key_state == KEY_PRESSED)
    );

// KEY_FREE stays in KEY_FREE when the input is high.
    check_state_free_stays_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE && enable_in == 1'b1) |=> (key_state == KEY_FREE)
    );

// KEY_PRESSED stays in KEY_PRESSED while the input remains low.
    check_state_pressed_stays_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b0) |=> (key_state == KEY_PRESSED)
    );

// KEY_PRESSED advances to KEY_RELEASED when the input goes high.
    check_state_pressed_to_released: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED && enable_in == 1'b1) |=> (key_state == KEY_RELEASED)
    );

// KEY_RELEASED always returns to KEY_FREE on the next cycle.
    check_state_released_to_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_RELEASED) |=> (key_state == KEY_FREE)
    );

// The output is low in KEY_FREE.
    check_output_low_in_free: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_FREE) |-> (enable_out == 1'b0)
    );

// The output is low in KEY_PRESSED.
    check_output_low_in_pressed: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_PRESSED) |-> (enable_out == 1'b0)
    );

// The output is high in KEY_RELEASED.
    check_output_high_in_released: assert property (
        @(posedge clock) disable iff (!reset)
        (key_state == KEY_RELEASED) |-> (enable_out == 1'b1)
    );

// Left direction must match the implemented rotation table.
    check_left_rotation_table: assert property (
        @(posedge clk) (direction == 1'b1) |-> (q == rot_left16(data, shift_amount))
    );

// Right direction must match the implemented rotation table.
    check_right_rotation_table: assert property (
        @(posedge clk) (direction == 1'b0) |-> (q == rot_right16(data, shift_amount))
    );

// Left rotation by zero returns the input unchanged.
    check_left_shift_zero_identity: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b0000) |-> (q == data)
    );

// Right rotation by zero returns the input unchanged.
    check_right_shift_zero_identity: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b0000) |-> (q == data)
    );

// Left rotation by one wraps the MSB into bit 0.
    check_left_shift_one_wraps_msb: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b0001) |-> (q == {data[14:0], data[15]})
    );

// Right rotation by one wraps the LSB into bit 15.
    check_right_shift_one_wraps_lsb: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b0001) |-> (q == {data[0], data[15:1]})
    );

// Left rotation by eight swaps the upper and lower bytes.
    check_left_shift_eight_swaps_bytes: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b1000) |-> (q == {data[7:0], data[15:8]})
    );

// Right rotation by eight swaps the upper and lower bytes.
    check_right_shift_eight_swaps_bytes: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b1000) |-> (q == {data[7:0], data[15:8]})
    );

// Left rotation by fifteen matches the RTL wrap-around mapping.
    check_left_shift_fifteen_wraps: assert property (
        @(posedge clk) (direction == 1'b1) && (shift_amount == 4'b1111) |-> (q == {data[0], data[15:1]})
    );

// Right rotation by fifteen matches the RTL wrap-around mapping.
    check_right_shift_fifteen_wraps: assert property (
        @(posedge clk) (direction == 1'b0) && (shift_amount == 4'b1111) |-> (q == {data[14:0], data[15]})
    );

// q is zero whenever reset is sampled high.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |-> (q == 34'b0)
    );

// q stays zero on the first clock after reset is released.
    check_q_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (q == 34'b0)
    );

// Outside reset, q captures d from the previous clock edge.
    check_q_captures_d: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (q == $past(d))
    );

// Sample the combinational NAND relation on clk; RTL has no reset.
    check_out_matches_nand: assert property (
        @(posedge clk) disable iff (1'b0) out == ~(in1 & in2)
    );

// Bit 0 must implement a NAND of in1[0] and in2[0].
    check_out0_matches_nand: assert property (
        @(posedge clk) disable iff (1'b0) out[0] == ~(in1[0] & in2[0])
    );

// Bit 1 must implement a NAND of in1[1] and in2[1].
    check_out1_matches_nand: assert property (
        @(posedge clk) disable iff (1'b0) out[1] == ~(in1[1] & in2[1])
    );

// If either bit-0 input is 0, bit-0 output must be 1.
    check_out0_high_when_any_input_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[0] == 1'b0) || (in2[0] == 1'b0)) |-> (out[0] == 1'b1)
    );

// If both bit-0 inputs are 1, bit-0 output must be 0.
    check_out0_low_when_both_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[0] == 1'b1) && (in2[0] == 1'b1)) |-> (out[0] == 1'b0)
    );

// If either bit-1 input is 0, bit-1 output must be 1.
    check_out1_high_when_any_input_low: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[1] == 1'b0) || (in2[1] == 1'b0)) |-> (out[1] == 1'b1)
    );

// If both bit-1 inputs are 1, bit-1 output must be 0.
    check_out1_low_when_both_inputs_high: assert property (
        @(posedge clk) disable iff (1'b0)
        ((in1[1] == 1'b1) && (in2[1] == 1'b1)) |-> (out[1] == 1'b0)
    );

// Output bit 2 is a direct copy of input bit 2.
    check_bit2_passthrough: assert property (
        @(posedge clk) salidas_o[2] == entradas_i[2]
    );

// Output bit 1 is the XOR of input bits 2 and 1.
    check_bit1_xor_decode: assert property (
        @(posedge clk) salidas_o[1] == (entradas_i[2] ^ entradas_i[1])
    );

// Output bit 0 is the XOR of output bit 1 and input bit 0.
    check_bit0_chained_xor: assert property (
        @(posedge clk) salidas_o[0] == (salidas_o[1] ^ entradas_i[0])
    );

// The full output vector matches the implemented Gray-to-binary decode.
    check_full_decode_vector: assert property (
        @(posedge clk) salidas_o == {entradas_i[2], (entradas_i[2] ^ entradas_i[1]), (entradas_i[2] ^ entradas_i[1] ^ entradas_i[0])}
    );

// Combinational decoder sampled on an external clock; no reset exists in the RTL.

    // sel=00 drives bit 0 high.
    check_sel_00_decodes_bit0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == 16'b0000000000000001)
    );

// sel=01 drives bit 1 high.
    check_sel_01_decodes_bit1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == 16'b0000000000000010)
    );

// sel=10 drives bit 2 high.
    check_sel_10_decodes_bit2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == 16'b0000000000000100)
    );

// sel=11 drives bit 3 high.
    check_sel_11_decodes_bit3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == 16'b0000000000001000)
    );

// The full output matches a 1 shifted by sel.
    check_full_output_matches_decode: assert property (
        @(posedge clk) out == (16'h0001 << sel)
    );

// Upper output bits are always zero.
    check_upper_bits_zero: assert property (
        @(posedge clk) out[15:4] == 12'b0
    );

// Outputs are cleared while reset is active.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (rst_n == 1'b0) |-> ((rise == 1'b0) && (fall == 1'b0))
    );

// On the first clock after reset, a low input produces no edge outputs.
    check_no_edge_after_reset_release_with_a_low: assert property (
        @(posedge clk) disable iff (!rst_n)
        (($past(rst_n) === 1'b0) && (a == 1'b0)) |-> ((rise == 1'b0) && (fall == 1'b0))
    );

// rise and fall are never asserted together.
    check_rise_fall_mutually_exclusive: assert property (
        @(posedge clk) disable iff (!rst_n)
        !(rise && fall)
    );

// Combinational divider sampled with external clk; RTL has no reset.

    // Divide-by-zero drives zero outputs.
    check_divide_by_zero_outputs_zero: assert property (
        @(posedge clk) (divisor == 4'b0000) |-> ((quotient == 4'b0000) && (remainder == 4'b0000))
    );

// Reset forces the registered output to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 4'sd0)
    );

// No RTL reset; assertions are always enabled.

    // comparison_result only uses the three implemented encodings.
    check_comparison_result_legal: assert property (
        @(posedge clk) disable iff (1'b0)
        (comparison_result == 3'b001) || (comparison_result == 3'b010) || (comparison_result == 3'b100)
    );

// Shift 00 compares unshifted a against b.
    check_compare_shift_00: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b00) |-> (comparison_result == ((a > b) ? 3'b001 : ((a < b) ? 3'b010 : 3'b100)))
    );

// Shift 01 compares a left-shifted by 1 against b.
    check_compare_shift_01: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b01) |-> (comparison_result == (({a[2:0], 1'b0} > b) ? 3'b001 : (({a[2:0], 1'b0} < b) ? 3'b010 : 3'b100)))
    );

// Shift 10 compares a right-shifted by 1 against b.
    check_compare_shift_10: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b10) |-> (comparison_result == (({1'b0, a[3:1]} > b) ? 3'b001 : (({1'b0, a[3:1]} < b) ? 3'b010 : 3'b100)))
    );

// Shift 11 compares a left-shifted by 2 against b.
    check_compare_shift_11: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b11) |-> (comparison_result == (({a[1:0], 2'b00} > b) ? 3'b001 : (({a[1:0], 2'b00} < b) ? 3'b010 : 3'b100)))
    );

// Shift 00 drives final_output from the implemented compare/select logic.
    check_output_shift_00: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b00) |-> (final_output == ((a > b) ? a : ((a < b) ? b : (a | b))))
    );

// Shift 01 drives final_output from the implemented compare/select logic.
    check_output_shift_01: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b01) |-> (final_output == (({a[2:0], 1'b0} > b) ? {a[2:0], 1'b0} : (({a[2:0], 1'b0} < b) ? b : ({a[2:0], 1'b0} | b))))
    );

// Shift 10 drives final_output from the implemented compare/select logic.
    check_output_shift_10: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b10) |-> (final_output == (({1'b0, a[3:1]} > b) ? {1'b0, a[3:1]} : (({1'b0, a[3:1]} < b) ? b : ({1'b0, a[3:1]} | b))))
    );

// Shift 11 drives final_output from the implemented compare/select logic.
    check_output_shift_11: assert property (
        @(posedge clk) disable iff (1'b0)
        (shift == 2'b11) |-> (final_output == (({a[1:0], 2'b00} > b) ? {a[1:0], 2'b00} : (({a[1:0], 2'b00} < b) ? b : ({a[1:0], 2'b00} | b))))
    );

// Q captures the previous cycle's bitwise AND of A and B.
    check_q_updates_to_prev_and: assert property (
        @(posedge clk) 1'b1 |=> (Q == ($past(A) & $past(B)))
    );

// If A and B have no overlapping 1 bits, Q becomes zero on the next cycle.
    check_zero_when_no_bit_overlap: assert property (
        @(posedge clk) ((A & B) == 32'h0000_0000) |=> (Q == 32'h0000_0000)
    );

// If A is all ones, Q captures the previous value of B.
    check_q_matches_prev_b_when_a_all_ones: assert property (
        @(posedge clk) (A == 32'hFFFF_FFFF) |=> (Q == $past(B))
    );

// If B is all ones, Q captures the previous value of A.
    check_q_matches_prev_a_when_b_all_ones: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |=> (Q == $past(A))
    );

// Q cannot contain 1 bits that were not set in the previous A value.
    check_q_subset_of_prev_a: assert property (
        @(posedge clk) 1'b1 |=> ((Q & ~$past(A)) == 32'h0000_0000)
    );

// Q cannot contain 1 bits that were not set in the previous B value.
    check_q_subset_of_prev_b: assert property (
        @(posedge clk) 1'b1 |=> ((Q & ~$past(B)) == 32'h0000_0000)
    );

// Clock: clk
    // Synchronous controls: clr is active-low, reset is active-high, set is active-high
    // q is sequential and qn is combinational

    // Low clear has highest priority and drives q low.
    check_clear_priority_drives_q_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b0) |=> (q == 1'b0)
    );

// High reset drives q low when clear is inactive.
    check_reset_drives_q_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b1 && reset == 1'b1) |=> (q == 1'b0)
    );

// High set drives q high when clear and reset are inactive.
    check_set_drives_q_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b1 && reset == 1'b0 && set == 1'b1) |=> (q == 1'b1)
    );

// d is captured when clear, reset, and set are inactive.
    check_d_captured_when_controls_inactive: assert property (
        @(posedge clk) disable iff (1'b0)
        (clr == 1'b1 && reset == 1'b0 && set == 1'b0) |=> (q == $past(d))
    );

// q matches the previous cycle's prioritized input selection.
    check_q_matches_prioritized_next_state: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (
            q == (
                ($past(clr) == 1'b0) ? 1'b0 :
                ($past(reset) == 1'b1) ? 1'b0 :
                ($past(set) == 1'b1) ? 1'b1 :
                                       $past(d)
            )
        )
    );

// qn is always the inverse of q.
    check_qn_is_inverse_of_q: assert property (
        @(posedge clk) disable iff (1'b0)
        (qn == ~q)
    );

// decap matches the implemented combinational equation.
    check_decap_equation: assert property (
        @(posedge clk)
        decap === (((VPWR == 1'b0) && (VGND == 1'b1)) ? 1'b1 : 1'b0)
    );

// decap can only be high when VPWR is low and VGND is high.
    check_decap_high_condition: assert property (
        @(posedge clk)
        (decap === 1'b1) |-> ((VPWR === 1'b0) && (VGND === 1'b1))
    );

// VPWR low and VGND high must drive decap high.
    check_decap_asserted_for_active_combination: assert property (
        @(posedge clk)
        ((VPWR === 1'b0) && (VGND === 1'b1)) |-> (decap === 1'b1)
    );

// VPWR high forces decap low.
    check_decap_low_when_vpwr_high: assert property (
        @(posedge clk)
        (VPWR === 1'b1) |-> (decap === 1'b0)
    );

// VGND low forces decap low.
    check_decap_low_when_vgnd_low: assert property (
        @(posedge clk)
        (VGND === 1'b0) |-> (decap === 1'b0)
    );

// cpu_d_address mirrors d_address.
    check_cpu_d_address_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (cpu_d_address == d_address)
    );

// cpu_d_read mirrors d_read.
    check_cpu_d_read_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (cpu_d_read == d_read)
    );

// cpu_d_readdata mirrors av_ld_data_aligned_filtered.
    check_cpu_d_readdata_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (cpu_d_readdata == av_ld_data_aligned_filtered)
    );

// cpu_d_writedata mirrors E_st_data.
    check_cpu_d_writedata_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (cpu_d_writedata == E_st_data)
    );

// cpu_d_write mirrors d_write.
    check_cpu_d_write_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (cpu_d_write == d_write)
    );

// cpu_d_wait mirrors d_waitrequest.
    check_cpu_d_wait_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n) (cpu_d_wait == d_waitrequest)
    );

// dbrk_break is low while reset is asserted.
    check_dbrk_break_reset_low: assert property (
        @(posedge clk) (!reset_n) |-> (dbrk_break == 1'b0)
    );

// dbrk_break never asserts after reset.
    check_dbrk_break_stays_low: assert property (
        @(posedge clk) disable iff (!reset_n) (dbrk_break == 1'b0)
    );

// dbrk_goto0 is tied low.
    check_dbrk_goto0_low: assert property (
        @(posedge clk) disable iff (!reset_n) (dbrk_goto0 == 1'b0)
    );

// dbrk_goto1 is tied low.
    check_dbrk_goto1_low: assert property (
        @(posedge clk) disable iff (!reset_n) (dbrk_goto1 == 1'b0)
    );

// dbrk_traceme is tied low.
    check_dbrk_traceme_low: assert property (
        @(posedge clk) disable iff (!reset_n) (dbrk_traceme == 1'b0)
    );

// dbrk_traceoff is tied low.
    check_dbrk_traceoff_low: assert property (
        @(posedge clk) disable iff (!reset_n) (dbrk_traceoff == 1'b0)
    );

// dbrk_traceon is tied low.
    check_dbrk_traceon_low: assert property (
        @(posedge clk) disable iff (!reset_n) (dbrk_traceon == 1'b0)
    );

// dbrk_trigout is tied low.
    check_dbrk_trigout_low: assert property (
        @(posedge clk) disable iff (!reset_n) (dbrk_trigout == 1'b0)
    );

// data_out always matches data_in incremented by one.
    check_data_increment: assert property (
        @(posedge clk) data_out == (data_in + 16'd1)
    );

// data_out wraps to zero when data_in is all ones.
    check_data_wraparound: assert property (
        @(posedge clk) (data_in == 16'hFFFF) |-> (data_out == 16'h0000)
    );

// Incrementing by one always toggles the least-significant bit.
    check_data_lsb_toggle: assert property (
        @(posedge clk) data_out[0] == ~data_in[0]
    );

// control_out always matches control_in shifted left by one.
    check_control_shift: assert property (
        @(posedge clk) control_out == (control_in << 1)
    );

// A left shift by one always drives the low bit to zero.
    check_control_lsb_zero: assert property (
        @(posedge clk) control_out[0] == 1'b0
    );

// Shifted control bits map to the next higher positions.
    check_control_shifted_bits: assert property (
        @(posedge clk) control_out[3:1] == control_in[2:0]
    );

// Reset drives both outputs low by the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        reset |=> (count_out == 4'h0 && wrap_around == 1'b0)
    );

// A load updates count_out from data_in and clears wrap_around.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count_out == $past(data_in) && wrap_around == 1'b0)
    );

// Without load, non-max values increment and keep wrap_around low.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && (count_out != 4'hF)) |=> (count_out == ($past(count_out) + 4'h1) && wrap_around == 1'b0)
    );

// Without load, 4'hF wraps to zero and asserts wrap_around.
    check_wrap_at_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && (count_out == 4'hF)) |=> (count_out == 4'h0 && wrap_around == 1'b1)
    );

// Low RESET_B forces the reset state on the next cycle.
    check_reset_value: assert property (
        @(posedge CLK)
        !RESET_B |=> (Q == 1'b0 && Q_B == 1'b1)
    );

// Low RESET_B overrides low SET_B.
    check_reset_priority_over_set: assert property (
        @(posedge CLK)
        (!RESET_B && !SET_B) |=> (Q == 1'b0 && Q_B == 1'b1)
    );

// Low SET_B forces the set state when reset is inactive.
    check_set_value: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        !SET_B |=> (Q == 1'b1 && Q_B == 1'b0)
    );

// With reset and set inactive, D=1 is captured on the next cycle.
    check_capture_d_high: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SET_B && D) |=> (Q == 1'b1 && Q_B == 1'b0)
    );

// With reset and set inactive, D=0 is captured on the next cycle.
    check_capture_d_low: assert property (
        @(posedge CLK) disable iff (!RESET_B)
        (SET_B && !D) |=> (Q == 1'b0 && Q_B == 1'b1)
    );

// The two outputs remain complementary after each clocked update.
    check_outputs_complementary: assert property (
        @(posedge CLK)
        1'b1 |=> (Q_B == ~Q)
    );

// Z matches the RTL's nested conditional expression.
    check_z_matches_rtl_expression: assert property (
        @(posedge clk)
        Z == ((A & ~B) ? 1'b1 : ((~A & B) ? 1'b0 : ((A & B) ? C : D)))
    );

// When A is high and B is low, Z is forced high.
    check_a1_b0_forces_z_high: assert property (
        @(posedge clk)
        (A && !B) |-> (Z == 1'b1)
    );

// When A is low and B is high, Z is forced low.
    check_a0_b1_forces_z_low: assert property (
        @(posedge clk)
        (!A && B) |-> (Z == 1'b0)
    );

// When both A and B are high, Z follows C.
    check_a1_b1_selects_c: assert property (
        @(posedge clk)
        (A && B) |-> (Z == C)
    );

// When both A and B are low, Z follows D.
    check_a0_b0_selects_d: assert property (
        @(posedge clk)
        (!A && !B) |-> (Z == D)
    );

// Shift 00 passes the input through unchanged.
    check_pass_through: assert property (
        @(posedge clk) (shift == 2'b00) |-> (out == data_in)
    );

// Shift 01 performs a left shift by 1 with zero fill.
    check_shift_left_by_1: assert property (
        @(posedge clk) (shift == 2'b01) |-> (out == {data_in[2:0], 1'b0})
    );

// Shift 10 performs a right shift by 1 with zero fill.
    check_shift_right_by_1: assert property (
        @(posedge clk) (shift == 2'b10) |-> (out == {1'b0, data_in[3:1]})
    );

// Shift 11 performs a left shift by 2 with zero fill.
    check_shift_left_by_2: assert property (
        @(posedge clk) (shift == 2'b11) |-> (out == {data_in[1:0], 2'b00})
    );

// Output always matches the selected shift operation.
    check_functional_mapping: assert property (
        @(posedge clk)
        (out == ((shift == 2'b00) ? data_in :
                 (shift == 2'b01) ? {data_in[2:0], 1'b0} :
                 (shift == 2'b10) ? {1'b0, data_in[3:1]} :
                                    {data_in[1:0], 2'b00}))
    );

// Output matches the 4-input AND when inputs are known.
    check_and4_function_known_inputs: assert property (
        @(posedge clk) !$isunknown({A, B, C, D}) |-> (X === (A & B & C & D))
    );

// Output is high when all inputs are high.
    check_output_high_when_all_inputs_high: assert property (
        @(posedge clk) (A === 1'b1 && B === 1'b1 && C === 1'b1 && D === 1'b1) |-> (X === 1'b1)
    );

// Output is low when any input is low.
    check_output_low_when_any_input_low: assert property (
        @(posedge clk) (A === 1'b0 || B === 1'b0 || C === 1'b0 || D === 1'b0) |-> (X === 1'b0)
    );

// A high output requires all inputs to be high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) (X === 1'b1) |-> (A === 1'b1 && B === 1'b1 && C === 1'b1 && D === 1'b1)
    );

// A low output with known inputs requires at least one low input.
    check_output_low_requires_low_input_when_inputs_known: assert property (
        @(posedge clk) (!$isunknown({A, B, C, D}) && X === 1'b0) |-> (A === 1'b0 || B === 1'b0 || C === 1'b0 || D === 1'b0)
    );

// When sel is low, the mux passes a.
    check_select_a_path: assert property (
        @(posedge clk) !sel |-> (out == a)
    );

// When sel is high, the mux passes b.
    check_select_b_path: assert property (
        @(posedge clk) sel |-> (out == b)
    );

// Output always matches the mux equation.
    check_mux_equation: assert property (
        @(posedge clk) (out == (sel ? b : a))
    );

// If both inputs are equal, output matches that value.
    check_equal_inputs_consistency: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// Full 5-bit result matches a + b + cin.
    check_full_result: assert property (
        @(posedge clk)
        {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0000, cin})
    );

// Bit 0 sum is the XOR of a[0], b[0], and cin.
    check_sum_bit0: assert property (
        @(posedge clk)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        sum[2] == (a[2] ^ b[2] ^ (
            (a[1] & b[1]) |
            (a[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))) |
            (b[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
        ))
    );

// X must match the OR-OR-AND function every cycle.
    check_x_matches_function: assert property (
        @(posedge clk) disable iff (1'b0)
        X == ((A1 | A2) & (B1 | B2))
    );

// A high X requires at least one A-side input to be high.
    check_x_high_requires_a_side: assert property (
        @(posedge clk) disable iff (1'b0)
        X |-> (A1 | A2)
    );

// A high X requires at least one B-side input to be high.
    check_x_high_requires_b_side: assert property (
        @(posedge clk) disable iff (1'b0)
        X |-> (B1 | B2)
    );

// If both A-side inputs are low, X must be low.
    check_no_a_side_forces_x_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!(A1 | A2)) |-> (!X)
    );

// If both B-side inputs are low, X must be low.
    check_no_b_side_forces_x_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!(B1 | B2)) |-> (!X)
    );

// A1 with B1 high must drive X high.
    check_a1_b1_drive_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & B1) |-> X
    );

// A1 with B2 high must drive X high.
    check_a1_b2_drive_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & B2) |-> X
    );

// A2 with B1 high must drive X high.
    check_a2_b1_drive_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A2 & B1) |-> X
    );

// A2 with B2 high must drive X high.
    check_a2_b2_drive_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A2 & B2) |-> X
    );

// S=00 routes C to Y.
    check_select_00_routes_c: assert property (
        @(posedge clk) (S == 2'b00) |-> (Y === C)
    );

// S=01 routes D to Y.
    check_select_01_routes_d: assert property (
        @(posedge clk) (S == 2'b01) |-> (Y === D)
    );

// S=10 routes A to Y.
    check_select_10_routes_a: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y === A)
    );

// S=11 routes B to Y.
    check_select_11_routes_b: assert property (
        @(posedge clk) (S == 2'b11) |-> (Y === B)
    );

// Y implements the 2-bit unsigned A >= B comparison.
    check_unsigned_compare: assert property (
        @(posedge clk) (Y == (A >= B))
    );

// When MSBs are equal, Y follows the LSB comparison.
    check_equal_msb_branch: assert property (
        @(posedge clk) (A[1] == B[1]) |-> (Y == (A[0] >= B[0]))
    );

// If A's MSB is greater than B's MSB, Y must be high.
    check_msb_greater_sets_y: assert property (
        @(posedge clk) (A[1] > B[1]) |-> (Y == 1'b1)
    );

// If A's MSB is less than B's MSB, Y must be low.
    check_msb_less_clears_y: assert property (
        @(posedge clk) (A[1] < B[1]) |-> (Y == 1'b0)
    );

// Equal inputs must produce a high output.
    check_equal_inputs_set_y: assert property (
        @(posedge clk) (A == B) |-> (Y == 1'b1)
    );

// With equal MSBs and smaller LSB, Y must be low.
    check_equal_msb_lsb_less: assert property (
        @(posedge clk) ((A[1] == B[1]) && (A[0] < B[0])) |-> (Y == 1'b0)
    );

// With equal MSBs and greater-or-equal LSB, Y must be high.
    check_equal_msb_lsb_ge: assert property (
        @(posedge clk) ((A[1] == B[1]) && (A[0] >= B[0])) |-> (Y == 1'b1)
    );

// Addition mode returns the low 8 bits of A + B.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> (result == ((A + B) & 8'hFF))
    );

// Subtraction mode returns the low 8 bits of A - B.
    check_sub_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> (result == ((A - B) & 8'hFF))
    );

// GT and EQ are never asserted together.
    check_gt_eq_mutex: assert property (
        @(posedge clk) !(GT && EQ)
    );

// GT and LT are never asserted together.
    check_gt_lt_mutex: assert property (
        @(posedge clk) !(GT && LT)
    );

// EQ and LT are never asserted together.
    check_eq_lt_mutex: assert property (
        @(posedge clk) !(EQ && LT)
    );

// At least one comparison result is asserted.
    check_result_present: assert property (
        @(posedge clk) (GT || EQ || LT)
    );

// Load clears the counter to zero.
    check_load_clears_count: assert property (
        @(posedge clk) load |=> (count == 4'b0000)
    );

// The counter increments when load is low and up_down is high.
    check_count_increments: assert property (
        @(posedge clk) (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// The counter decrements when load is low and up_down is low.
    check_count_decrements: assert property (
        @(posedge clk) (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// Load has priority over the direction control.
    check_load_priority: assert property (
        @(posedge clk) (load && up_down) |=> (count == 4'b0000)
    );

// Increment wraps from 15 back to 0.
    check_increment_wraps_from_max: assert property (
        @(posedge clk) (!load && up_down && (count == 4'hF)) |=> (count == 4'h0)
    );

// Decrement wraps from 0 down to 15.
    check_decrement_wraps_from_zero: assert property (
        @(posedge clk) (!load && !up_down && (count == 4'h0)) |=> (count == 4'hF)
    );

// Reset clears the register on the next sampled cycle.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 16'b0)
    );

// Reset overrides a simultaneous enabled write.
    check_reset_priority_over_write: assert property (
        @(posedge clk) (reset && enable && write) |=> (out == 16'b0)
    );

// An enabled write loads the input value.
    check_capture_on_write: assert property (
        @(posedge clk) disable iff (reset) (enable && write) |=> (out == $past(in))
    );

// When disabled, the register holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (out == $past(out))
    );

// When enabled without write, the register holds its value.
    check_hold_when_no_write: assert property (
        @(posedge clk) disable iff (reset) (enable && !write) |=> (out == $past(out))
    );

// Write has no effect unless enable is high.
    check_write_ignored_without_enable: assert property (
        @(posedge clk) disable iff (reset) (!enable && write) |=> (out == $past(out))
    );

// Output matches the decoded input value.
    check_exact_decode: assert property (
        @(posedge clk) out == (16'h0001 << in)
    );

// Exactly one output bit is asserted.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// The selected output bit is high.
    check_selected_bit_high: assert property (
        @(posedge clk) out[in] == 1'b1
    );

// All non-selected output bits are low.
    check_unselected_bits_low: assert property (
        @(posedge clk) (out & ~(16'h0001 << in)) == 16'h0000
    );

// Output always matches 32-bit addition of a and b.
    check_sum_matches_addition: assert property (
        @(posedge clk) sum == (a + b)
    );

// With sub low, the output matches addition.
    check_add_mode_matches_addition: assert property (
        @(posedge clk) !sub |-> (sum == (a + b))
    );

// With sub high, the output still matches addition.
    check_sub_mode_still_matches_addition: assert property (
        @(posedge clk) sub |-> (sum == (a + b))
    );

// The low 16 bits match the low-half addition result.
    check_low_half_matches_addition: assert property (
        @(posedge clk) sum[15:0] == (a[15:0] + b[15:0])
    );

// A carry from the low half increments the high-half result.
    check_high_half_with_low_carry: assert property (
        @(posedge clk)
        (({1'b0, a[15:0]} + {1'b0, b[15:0]}) >= 17'h1_0000)
        |-> (sum[31:16] == (a[31:16] + b[31:16] + 16'd1))
    );

// Without a low-half carry, the high half is a simple add.
    check_high_half_without_low_carry: assert property (
        @(posedge clk)
        (({1'b0, a[15:0]} + {1'b0, b[15:0]}) < 17'h1_0000)
        |-> (sum[31:16] == (a[31:16] + b[31:16]))
    );

// Zero on a passes b through to the output.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (a == 32'd0) |-> (sum == b)
    );

// Zero on b passes a through to the output.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (b == 32'd0) |-> (sum == a)
    );

// Top output mirrors the internal Y wire.
    check_output_matches_internal: assert property (
        @(posedge clk) Y === Y_wire
    );

// Internal gate output implements the coded 3-input NOR.
    check_internal_nor_equation: assert property (
        @(posedge clk) Y_wire === ~(A_wire | B_wire | C_N_wire)
    );

// Top output matches the NOR of the internal gate inputs.
    check_output_nor_equation: assert property (
        @(posedge clk) Y === ~(A_wire | B_wire | C_N_wire)
    );

// All internal inputs low drives the internal output high.
    check_internal_high_when_all_inputs_low: assert property (
        @(posedge clk)
        ((A_wire === 1'b0) && (B_wire === 1'b0) && (C_N_wire === 1'b0))
        |-> (Y_wire === 1'b1)
    );

// Internal A high forces the internal output low.
    check_internal_low_when_a_high: assert property (
        @(posedge clk) (A_wire === 1'b1) |-> (Y_wire === 1'b0)
    );

// Internal B high forces the internal output low.
    check_internal_low_when_b_high: assert property (
        @(posedge clk) (B_wire === 1'b1) |-> (Y_wire === 1'b0)
    );

// Internal C_N high forces the internal output low.
    check_internal_low_when_c_n_high: assert property (
        @(posedge clk) (C_N_wire === 1'b1) |-> (Y_wire === 1'b0)
    );

// Internal output high implies all internal inputs are low.
    check_inputs_low_when_internal_output_high: assert property (
        @(posedge clk) (Y_wire === 1'b1)
        |-> ((A_wire === 1'b0) && (B_wire === 1'b0) && (C_N_wire === 1'b0))
    );

// Internal output low implies at least one internal input is high.
    check_some_input_high_when_internal_output_low: assert property (
        @(posedge clk) (Y_wire === 1'b0)
        |-> ((A_wire === 1'b1) || (B_wire === 1'b1) || (C_N_wire === 1'b1))
    );

// All internal inputs low drives the top output high.
    check_output_high_when_all_inputs_low: assert property (
        @(posedge clk)
        ((A_wire === 1'b0) && (B_wire === 1'b0) && (C_N_wire === 1'b0))
        |-> (Y === 1'b1)
    );

// Any internal input high forces the top output low.
    check_output_low_when_any_input_high: assert property (
        @(posedge clk)
        ((A_wire === 1'b1) || (B_wire === 1'b1) || (C_N_wire === 1'b1))
        |-> (Y === 1'b0)
    );

// The gray bus matches the implemented binary-to-gray conversion.
    check_gray_matches_conversion: assert property (
        @(posedge clk) gray == (binary ^ {1'b0, binary[7:1]})
    );

// The gray MSB is passed through from the binary MSB.
    check_gray_bit7_passthrough: assert property (
        @(posedge clk) gray[7] == binary[7]
    );

// Gray bit 6 is binary[6] XOR binary[7].
    check_gray_bit6_xor: assert property (
        @(posedge clk) gray[6] == (binary[6] ^ binary[7])
    );

// Gray bit 5 is binary[5] XOR binary[6].
    check_gray_bit5_xor: assert property (
        @(posedge clk) gray[5] == (binary[5] ^ binary[6])
    );

// Gray bit 4 is binary[4] XOR binary[5].
    check_gray_bit4_xor: assert property (
        @(posedge clk) gray[4] == (binary[4] ^ binary[5])
    );

// Gray bit 3 is binary[3] XOR binary[4].
    check_gray_bit3_xor: assert property (
        @(posedge clk) gray[3] == (binary[3] ^ binary[4])
    );

// Gray bit 2 is binary[2] XOR binary[3].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray[2] == (binary[2] ^ binary[3])
    );

// Gray bit 1 is binary[1] XOR binary[2].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray[1] == (binary[1] ^ binary[2])
    );

// Gray bit 0 is binary[0] XOR binary[1].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray[0] == (binary[0] ^ binary[1])
    );

// A sampled high d causes q to hold after the k pipeline stage.
    check_d_high_causes_q_hold_after_two_cycles: assert property (
        @(posedge clk) d |=> ##1 (q == $past(q))
    );

// A sampled low d causes q to toggle after the k pipeline stage.
    check_d_low_causes_q_toggle_after_two_cycles: assert property (
        @(posedge clk) (!d) |=> ##1 (q == ~$past(q))
    );

// A shift always inserts 0 into q[0].
    check_shift_inserts_zero: assert property (
        @(posedge clk) !load |=> (q[0] == 1'b0)
    );

// Four consecutive shifts clear the register.
    check_four_shifts_clear_register: assert property (
        @(posedge clk) ((!load)[*4]) |=> (q == 4'b0000)
    );

// Zero remains zero while shifting without a load.
    check_zero_holds_without_load: assert property (
        @(posedge clk) (!load && (q == 4'b0000)) |=> (q == 4'b0000)
    );

// Combined output must equal the RTL addition result.
    check_full_add_result: assert property (
        @(posedge clk) {cout, sum} == (a + b + cin)
    );

// Zero inputs must produce a zero result.
    check_zero_addition: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000) && (cin == 1'b0)) |-> ({cout, sum} == 5'b00000)
    );

// Adding zero with no carry-in must pass through a.
    check_passthrough_a: assert property (
        @(posedge clk) ((b == 4'b0000) && (cin == 1'b0)) |-> ({cout, sum} == {1'b0, a})
    );

// Adding zero with no carry-in must pass through b.
    check_passthrough_b: assert property (
        @(posedge clk) ((a == 4'b0000) && (cin == 1'b0)) |-> ({cout, sum} == {1'b0, b})
    );

// Maximum inputs with carry-in must produce the full 5-bit maximum sum.
    check_max_addition: assert property (
        @(posedge clk) ((a == 4'hf) && (b == 4'hf) && (cin == 1'b1)) |-> ({cout, sum} == 5'h1f)
    );

// Output equals the five-input AND of all inputs.
    check_out_matches_and: assert property (
        @(posedge clk)
        out_signal == (in_signal_1 & in_signal_2 & in_signal_3 & in_signal_4 & in_signal_5)
    );

// A HIGH output requires all inputs to be HIGH.
    check_out_high_requires_all_inputs_high: assert property (
        @(posedge clk)
        out_signal |-> (in_signal_1 && in_signal_2 && in_signal_3 && in_signal_4 && in_signal_5)
    );

// All inputs HIGH drives the output HIGH.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk)
        (in_signal_1 && in_signal_2 && in_signal_3 && in_signal_4 && in_signal_5) |-> out_signal
    );

// A LOW on input 1 forces the output LOW.
    check_input1_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal_1 |-> !out_signal
    );

// A LOW on input 2 forces the output LOW.
    check_input2_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal_2 |-> !out_signal
    );

// A LOW on input 3 forces the output LOW.
    check_input3_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal_3 |-> !out_signal
    );

// A LOW on input 4 forces the output LOW.
    check_input4_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal_4 |-> !out_signal
    );

// A LOW on input 5 forces the output LOW.
    check_input5_low_forces_output_low: assert property (
        @(posedge clk)
        !in_signal_5 |-> !out_signal
    );

// With no test override and EN low, the gated clock output is low.
    check_gate_disabled_low: assert property (
        @(posedge CLK) (!TE && !EN) |-> !ENCLK
    );

// A low functional-mode output stays low while TE remains low and EN stays high.
    check_functional_low_is_sticky: assert property (
        @(posedge CLK) (!TE && EN && !ENCLK) ##1 (!TE && EN) |-> !ENCLK
    );

// A high functional-mode output stays high while TE remains low and EN stays high.
    check_functional_high_is_sticky: assert property (
        @(posedge CLK) (!TE && EN && ENCLK) ##1 (!TE && EN) |-> ENCLK
    );

// Clear has highest priority on the clock edge.
    check_clear_priority: assert property (
        @(posedge CK) C |=> (Q == 1'b0 && QN == 1'b1)
    );

// Set drives the outputs when clear is not asserted.
    check_set_priority: assert property (
        @(posedge CK) (!C && S) |=> (Q == 1'b1 && QN == 1'b0)
    );

// Reset drives the outputs when clear and set are not asserted.
    check_reset_priority: assert property (
        @(posedge CK) (!C && !S && R) |=> (Q == 1'b0 && QN == 1'b1)
    );

// Data is captured when no control input is asserted.
    check_data_capture: assert property (
        @(posedge CK) (!C && !S && !R) |=> (Q == $past(D) && QN == ~$past(D))
    );

// The two outputs remain complementary after each clock update.
    check_complementary_outputs: assert property (
        @(posedge CK) 1'b1 |=> (QN == ~Q)
    );

// The concatenated carry-out and sum equal the 5-bit addition result.
    check_full_add_result: assert property (
        @(posedge clk)
        {COUT, S} == ({1'b0, A} + {1'b0, B} + CIN)
    );

// Sum bit 0 matches a full-adder XOR of A[0], B[0], and CIN.
    check_sum_bit0: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ CIN)
    );

// Sum bit 1 matches a full-adder XOR using the bit-0 carry.
    check_sum_bit1: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^
                 ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))
    );

// Sum bit 2 matches a full-adder XOR using the bit-1 carry.
    check_sum_bit2: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                  (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))))
    );

// When num1 is greater than num2, larger must equal num1.
    check_num1_selected_when_greater: assert property (
        @(posedge clk) (num1 > num2) |-> (larger == num1)
    );

// When num2 is greater than num1, larger must equal num2.
    check_num2_selected_when_greater: assert property (
        @(posedge clk) (num2 > num1) |-> (larger == num2)
    );

// When the inputs are equal, larger must equal that common value.
    check_equal_inputs_return_value: assert property (
        @(posedge clk) (num1 == num2) |-> (larger == num1)
    );

// The output must always match the RTL's max-selection behavior.
    check_output_matches_max_function: assert property (
        @(posedge clk) larger == ((num1 >= num2) ? num1 : num2)
    );

// The output must always be one of the input values.
    check_output_is_one_of_inputs: assert property (
        @(posedge clk) (larger == num1) || (larger == num2)
    );

// The output must not be smaller than num1.
    check_output_not_smaller_than_num1: assert property (
        @(posedge clk) larger >= num1
    );

// The output must not be smaller than num2.
    check_output_not_smaller_than_num2: assert property (
        @(posedge clk) larger >= num2
    );

// Y matches the implemented O2BB2AI boolean function.
    check_y_matches_logic: assert property (
        @(posedge clk) Y == ((A1_N & A2_N) | (~B1 & ~B2))
    );

// Y is high whenever both B inputs are low.
    check_y_high_when_b_inputs_low: assert property (
        @(posedge clk) (~B1 & ~B2) |-> Y
    );

// Y is high whenever both A inputs are high.
    check_y_high_when_a_inputs_high: assert property (
        @(posedge clk) (A1_N & A2_N) |-> Y
    );

// Y is low when any B input is high and at least one A input is low.
    check_y_low_when_b_active_and_a_not_both_high: assert property (
        @(posedge clk) ((B1 | B2) & (~A1_N | ~A2_N)) |-> ~Y
    );

// A low Y requires at least one B input to be high.
    check_y_low_requires_b_activity: assert property (
        @(posedge clk) (~Y) |-> (B1 | B2)
    );

// A low Y requires at least one A input to be low.
    check_y_low_requires_one_a_low: assert property (
        @(posedge clk) (~Y) |-> (~A1_N | ~A2_N)
    );

// X must equal the 4-input AND of A, B, C, and D.
    check_output_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// A high output requires all four inputs to be high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

// If all four inputs are high, X must be high.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// If A is low, X must be low.
    check_a_low_blocks_output: assert property (
        @(posedge clk) !A |-> !X
    );

// If B is low, X must be low.
    check_b_low_blocks_output: assert property (
        @(posedge clk) !B |-> !X
    );

// If C is low, X must be low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) !C |-> !X
    );

// If D is low, X must be low.
    check_d_low_blocks_output: assert property (
        @(posedge clk) !D |-> !X
    );

// X matches the implemented sum-of-products function.
    check_x_function: assert property (
        @(posedge clk) X === ((A1 & A2 & A3) | (B1 & B2))
    );

// The A-side 3-input AND drives X high.
    check_a_product_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// The B-side 2-input AND drives X high.
    check_b_product_sets_x: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// X is low when neither AND term is active.
    check_no_product_means_x_low: assert property (
        @(posedge clk) (!(A1 & A2 & A3) && !(B1 & B2)) |-> !X
    );

// Combinational DUT sampled on an external formal clock.

    // Y matches the implemented NOT-then-NAND function.
    check_output_function: assert property (
        @(posedge clk) (Y == ~(B & ~A_N & C))
    );

// A_N high forces the inverted NAND input low, so Y must be high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// B low forces the NAND output high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

// C low forces the NAND output high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b1)
    );

// The only way Y can be low is with A_N low, B high, and C high.
    check_y_low_only_for_active_input_combo: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1))
    );

// With A_N low and both B and C high, Y must be low.
    check_active_input_combo_drives_y_low: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1)) |-> (Y == 1'b0)
    );

// Sample the combinational DUT on an external clock; the RTL has no reset.

    // Output must implement a 4-input NAND.
    check_y_matches_nand_function: assert property (
        @(posedge clk) y == ~(a & b & c & d)
    );

// All inputs high forces the output low.
    check_all_inputs_high_drive_y_low: assert property (
        @(posedge clk) (a & b & c & d) |-> (y == 1'b0)
    );

// A low output only occurs when all inputs are high.
    check_y_low_only_when_all_inputs_high: assert property (
        @(posedge clk) (y == 1'b0) |-> (a & b & c & d)
    );

// Any low input forces the output high.
    check_any_input_low_drives_y_high: assert property (
        @(posedge clk) (!(a & b & c & d)) |-> (y == 1'b1)
    );

// X matches the implemented OR-of-AND function.
    check_output_function: assert property (
        @(posedge clk) X == ((A1 & A2) | B1)
    );

// B1 drives X high through the OR gate.
    check_b1_forces_high: assert property (
        @(posedge clk) B1 |-> X
    );

// The A1/A2 AND term drives X high when B1 is low.
    check_and_term_drives_high: assert property (
        @(posedge clk) (!B1 && A1 && A2) |-> X
    );

// A low A1 forces X low when B1 is low.
    check_a1_low_forces_low_without_b1: assert property (
        @(posedge clk) (!B1 && !A1) |-> !X
    );

// A low A2 forces X low when B1 is low.
    check_a2_low_forces_low_without_b1: assert property (
        @(posedge clk) (!B1 && !A2) |-> !X
    );

// A high X must come from B1 or the A1/A2 AND term.
    check_high_output_has_valid_cause: assert property (
        @(posedge clk) X |-> (B1 || (A1 && A2))
    );

// A low X means B1 is low and the AND term is not asserted.
    check_low_output_has_valid_cause: assert property (
        @(posedge clk) !X |-> (!B1 && (!A1 || !A2))
    );

// OUT must match the implemented mux equation.
    check_mux_boolean_equation: assert property (
        @(posedge clk) (OUT == ((IN0 & ~S0) | (IN1 & S0)))
    );

// When select is low, OUT must equal IN0.
    check_select_low_path: assert property (
        @(posedge clk) (S0 == 1'b0) |-> (OUT == IN0)
    );

// When select is high, OUT must equal IN1.
    check_select_high_path: assert property (
        @(posedge clk) (S0 == 1'b1) |-> (OUT == IN1)
    );

// If both inputs match, OUT must equal that common value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (IN0 == IN1) |-> (OUT == IN0)
    );

// Y ignores A1/A2 and matches the B inputs.
    check_y_matches_b_inputs: assert property (
        @(posedge clk) Y == {B1, B2}
    );

// VOUT selects VPWR for even Y and VGND for odd Y.
    check_vout_follows_y_lsb: assert property (
        @(posedge clk) VOUT == (Y[0] ? VGND : VPWR)
    );

// VREF selects VPB for Y below 2 and VNB otherwise.
    check_vref_follows_y_msb: assert property (
        @(posedge clk) VREF == (Y[1] ? VNB : VPB)
    );

// VOUT is ultimately controlled by B2 through Y.
    check_vout_matches_b2: assert property (
        @(posedge clk) VOUT == (B2 ? VGND : VPWR)
    );

// VREF is ultimately controlled by B1 through Y.
    check_vref_matches_b1: assert property (
        @(posedge clk) VREF == (B1 ? VNB : VPB)
    );

// Q reflects the previous cycle's clear-or-data selection.
    check_transfer_function: assert property (
        @(posedge Clk) disable iff (1'b0)
        1'b1 |=> (Q == ($past(Clr) ? 1'b0 : $past(D)))
    );

// A high clear forces Q low on the next sampled clock.
    check_sync_clear: assert property (
        @(posedge Clk) disable iff (1'b0)
        Clr |=> (Q == 1'b0)
    );

// With clear low, Q captures D on the next sampled clock.
    check_data_capture: assert property (
        @(posedge Clk) disable iff (1'b0)
        !Clr |=> (Q == $past(D))
    );

// Clear has priority over a high D input.
    check_clear_priority: assert property (
        @(posedge Clk) disable iff (1'b0)
        (Clr && D) |=> (Q == 1'b0)
    );

// comp is 01 when in1 is less than in2.
    check_less_than_encoding: assert property (
        @(posedge clk) (in1 < in2) |-> (comp == 2'b01)
    );

// comp is 10 when in1 equals in2.
    check_equal_encoding: assert property (
        @(posedge clk) (in1 == in2) |-> (comp == 2'b10)
    );

// comp is 10 when in1 is greater than in2.
    check_greater_than_encoding: assert property (
        @(posedge clk) (in1 > in2) |-> (comp == 2'b10)
    );

// 01 only appears for the less-than case.
    check_01_implies_less_than: assert property (
        @(posedge clk) (comp == 2'b01) |-> (in1 < in2)
    );

// 10 only appears when in1 is not less than in2.
    check_10_implies_not_less_than: assert property (
        @(posedge clk) (comp == 2'b10) |-> (in1 >= in2)
    );

// comp never drives 00.
    check_comp_not_00: assert property (
        @(posedge clk) (comp != 2'b00)
    );

// comp never drives 11.
    check_comp_not_11: assert property (
        @(posedge clk) (comp != 2'b11)
    );

// comp matches the implemented comparator function.
    check_comp_function: assert property (
        @(posedge clk) comp == ((in1 < in2) ? 2'b01 : 2'b10)
    );

// Sum is the low 4 bits of the full addition.
    check_sum_matches_low_nibble: assert property (
        @(posedge clk) {1'b0, sum} == (({1'b0, a} + {1'b0, b}) & 5'h0f)
    );

// When there is no overflow, sum matches the full result.
    check_sum_no_overflow: assert property (
        @(posedge clk) (({1'b0, a} + {1'b0, b}) <= 5'd15) |-> ({1'b0, sum} == ({1'b0, a} + {1'b0, b}))
    );

// When there is overflow, sum wraps modulo 16.
    check_sum_wraps_on_overflow: assert property (
        @(posedge clk) (({1'b0, a} + {1'b0, b}) > 5'd15) |-> ({1'b0, sum} == (({1'b0, a} + {1'b0, b}) - 5'd16))
    );

// Adding zero on a leaves b unchanged.
    check_zero_a_identity: assert property (
        @(posedge clk) (a == 4'd0) |-> (sum == b)
    );

// Adding zero on b leaves a unchanged.
    check_zero_b_identity: assert property (
        @(posedge clk) (b == 4'd0) |-> (sum == a)
    );

// The least significant sum bit is the XOR of operand LSBs.
    check_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0])
    );

// Each digit byte matches the implemented BCD-to-7seg lookup.
            check_digit_encoding: assert property (
                @(posedge clk)
                out[(i + 1) * 8 - 1 : i * 8] ==
                expected_out(bcd[(i + 1) * 4 - 1 : i * 4], dot[i])
            );

// The dot input drives the LSB of the corresponding output byte.
            check_dot_passthrough: assert property (
                @(posedge clk)
                out[i * 8] == dot[i]
            );

// Invalid BCD values blank the segments and preserve the dot bit.
            check_invalid_digit_blank: assert property (
                @(posedge clk)
                (bcd[(i + 1) * 4 - 1 : i * 4] == 4'ha ||
                 bcd[(i + 1) * 4 - 1 : i * 4] == 4'hb ||
                 bcd[(i + 1) * 4 - 1 : i * 4] == 4'hc ||
                 bcd[(i + 1) * 4 - 1 : i * 4] == 4'hd ||
                 bcd[(i + 1) * 4 - 1 : i * 4] == 4'he ||
                 bcd[(i + 1) * 4 - 1 : i * 4] == 4'hf)
                |-> out[(i + 1) * 8 - 1 : i * 8] == {7'b0000000, dot[i]}
            );

// add reflects the 4-bit sum of A and B.
    check_add_matches_sum: assert property (
        @(posedge clk) add == ((A + B) & 4'hF)
    );

// sub reflects the 4-bit difference of A and B.
    check_sub_matches_difference: assert property (
        @(posedge clk) sub == ((A - B) & 4'hF)
    );

// adding zero leaves A unchanged.
    check_add_zero_identity: assert property (
        @(posedge clk) (B == 4'd0) |-> (add == A)
    );

// subtracting zero leaves A unchanged.
    check_sub_zero_identity: assert property (
        @(posedge clk) (B == 4'd0) |-> (sub == A)
    );

// equal operands subtract to zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (A == B) |-> (sub == 4'd0)
    );

// SUM matches the three-input XOR of A, B, and CI.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT matches the majority function of A, B, and CI.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// All-zero inputs produce zero sum and no carry.
    check_zero_inputs_result_zero: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

// Exactly one high input produces sum without carry.
    check_one_hot_inputs_result_sum_only: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI))
        |-> (SUM == 1'b1 && COUT == 1'b0)
    );

// Exactly two high inputs produce carry without sum.
    check_two_hot_inputs_result_carry_only: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI))
        |-> (SUM == 1'b0 && COUT == 1'b1)
    );

// All-high inputs produce both sum and carry.
    check_all_inputs_high_result_sum_and_carry: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

// Synchronous reset clears result and valid on the next cycle.
    check_sync_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> ((result == 8'h00) && (valid == 1'b0))
    );

// Any non-reset cycle drives valid high on the next cycle.
    check_valid_set_after_active_cycle: assert property (
        @(posedge clk) disable iff (rst)
        1'b1 |=> (valid == 1'b1)
    );

// ADD stores the prior-cycle sum and asserts valid.
    check_add_updates_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == ADD) |=> ((result == (($past(num1) + $past(num2)) & 8'hFF)) && (valid == 1'b1))
    );

// SUB stores the prior-cycle difference and asserts valid.
    check_sub_updates_result: assert property (
        @(posedge clk) disable iff (rst)
        (op == SUB) |=> ((result == (($past(num1) - $past(num2)) & 8'hFF)) && (valid == 1'b1))
    );

// Low reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk)
        (reset == 1'b0) |=> (count == 4'd0)
    );

// When enabled below 15, the counter increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable == 1'b1 && count != 4'd15) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at 15, the counter wraps to zero.
    check_count_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable == 1'b1 && count == 4'd15) |=> (count == 4'd0)
    );

// When disabled, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable == 1'b0) |=> $stable(count)
    );

// X must be low whenever the mux is disabled.
    check_x_low_when_disabled: assert property (
        @(posedge clk) !EN |-> (X == 1'b0)
    );

// When enabled with S1S0=00, X must select A2.
    check_select_00_routes_a2: assert property (
        @(posedge clk) EN && !S1 && !S0 |-> (X == A2)
    );

// When enabled with S1S0=01, X must select A0.
    check_select_01_routes_a0: assert property (
        @(posedge clk) EN && !S1 && S0 |-> (X == A0)
    );

// When enabled with S1S0=10, X must select A1.
    check_select_10_routes_a1: assert property (
        @(posedge clk) EN && S1 && !S0 |-> (X == A1)
    );

// When enabled with S1S0=11, X must select A3.
    check_select_11_routes_a3: assert property (
        @(posedge clk) EN && S1 && S0 |-> (X == A3)
    );

// 000 selects Y[0] low.
    check_decode_000: assert property (
        @(posedge clk) ({A, B, C} == 3'b000) |-> (Y == 8'b11111110)
    );

// 001 selects Y[1] low.
    check_decode_001: assert property (
        @(posedge clk) ({A, B, C} == 3'b001) |-> (Y == 8'b11111101)
    );

// 010 selects Y[2] low.
    check_decode_010: assert property (
        @(posedge clk) ({A, B, C} == 3'b010) |-> (Y == 8'b11111011)
    );

// 011 selects Y[3] low.
    check_decode_011: assert property (
        @(posedge clk) ({A, B, C} == 3'b011) |-> (Y == 8'b11110111)
    );

// 100 selects Y[4] low.
    check_decode_100: assert property (
        @(posedge clk) ({A, B, C} == 3'b100) |-> (Y == 8'b11101111)
    );

// 101 selects Y[5] low.
    check_decode_101: assert property (
        @(posedge clk) ({A, B, C} == 3'b101) |-> (Y == 8'b11011111)
    );

// 110 selects Y[6] low.
    check_decode_110: assert property (
        @(posedge clk) ({A, B, C} == 3'b110) |-> (Y == 8'b10111111)
    );

// 111 selects Y[7] low.
    check_decode_111: assert property (
        @(posedge clk) ({A, B, C} == 3'b111) |-> (Y == 8'b01111111)
    );

// Output is always active-low one-hot.
    check_active_low_onehot: assert property (
        @(posedge clk) $onehot(~Y)
    );

// Active-low reset forces the counter output to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) !rst |-> (q == 4'b0000)
    );

// When enabled, the counter increments by one on the next cycle.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) en |=> (q == ($past(q) + 4'b0001))
    );

// When disabled, the counter holds its value on the next cycle.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst) !en |=> (q == $past(q))
    );

// Counting wraps from 4'hF back to 4'h0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!rst) (en && (q == 4'hF)) |=> (q == 4'h0)
    );

// After reset release with enable high, the first counted value is 1.
    check_first_count_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst) ($rose(rst) && en) |=> (q == 4'b0001)
    );

// After reset release with enable low, the counter remains at zero.
    check_hold_zero_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst) ($rose(rst) && !en) |=> (q == 4'b0000)
    );

// No RTL clock or reset; clk is a sampling clock for this combinational DUT.

    // notAM31_3 matches the NAND of AM[31:19].
    check_notAM31_3_nand_equation: assert property (
        @(posedge clk) (notAM31_3 == ~(&AM[31:19]))
    );

// All-high AM[31:19] drives notAM31_3 low.
    check_notAM31_3_all_high_drives_low: assert property (
        @(posedge clk) (&AM[31:19]) |-> (notAM31_3 == 1'b0)
    );

// Any low bit in AM[31:19] drives notAM31_3 high.
    check_notAM31_3_any_low_drives_high: assert property (
        @(posedge clk) (~(&AM[31:19])) |-> (notAM31_3 == 1'b1)
    );

// notAM2_0 matches the NAND of AM[2:0].
    check_notAM2_0_nand_equation: assert property (
        @(posedge clk) (notAM2_0 == ~(&AM[2:0]))
    );

// All-high AM[2:0] drives notAM2_0 low.
    check_notAM2_0_all_high_drives_low: assert property (
        @(posedge clk) (&AM[2:0]) |-> (notAM2_0 == 1'b0)
    );

// Any low bit in AM[2:0] drives notAM2_0 high.
    check_notAM2_0_any_low_drives_high: assert property (
        @(posedge clk) (~(&AM[2:0])) |-> (notAM2_0 == 1'b1)
    );

// Y matches the NOR of B1 and the three-input AND of A1, A2, and A3.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2 & A3))
    );

// A high B1 forces the NOR output low.
    check_b1_forces_output_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// With B1 low, all three A inputs high force Y low.
    check_all_a_high_forces_output_low: assert property (
        @(posedge clk) (!B1 && A1 && A2 && A3) |-> !Y
    );

// With B1 low, A1 low makes the AND term low and Y high.
    check_a1_low_forces_output_high: assert property (
        @(posedge clk) (!B1 && !A1) |-> Y
    );

// With B1 low, A2 low makes the AND term low and Y high.
    check_a2_low_forces_output_high: assert property (
        @(posedge clk) (!B1 && !A2) |-> Y
    );

// With B1 low, A3 low makes the AND term low and Y high.
    check_a3_low_forces_output_high: assert property (
        @(posedge clk) (!B1 && !A3) |-> Y
    );

// If Y is high, B1 must be low and at least one A input must be low.
    check_output_high_conditions: assert property (
        @(posedge clk) Y |-> (!B1 && (!A1 || !A2 || !A3))
    );

// If Y is low while B1 is low, then all three A inputs must be high.
    check_low_without_b1_requires_all_a_high: assert property (
        @(posedge clk) (!Y && !B1) |-> (A1 && A2 && A3)
    );

// Combined output must match the 5-bit addition result.
    check_full_add_result: assert property (
        @(posedge clk)
        {carry_out, sum} == ({1'b0, addend1} + {1'b0, addend2} + carry_in)
    );

// sum must equal the low 4 bits of the addition result.
    check_sum_low_bits: assert property (
        @(posedge clk)
        {1'b0, sum} == (({1'b0, addend1} + {1'b0, addend2} + carry_in) & 5'h0F)
    );

// carry_out must indicate overflow beyond 4 bits.
    check_carry_out_overflow: assert property (
        @(posedge clk)
        carry_out == (({1'b0, addend1} + {1'b0, addend2} + carry_in) > 5'd15)
    );

// Zero operands with no carry-in must produce zero.
    check_zero_result: assert property (
        @(posedge clk)
        ((addend1 == 4'd0) && (addend2 == 4'd0) && (carry_in == 1'b0)) |-> ({carry_out, sum} == 5'd0)
    );

// With addend2 cleared and no carry-in, the output must pass through addend1.
    check_addend1_passthrough: assert property (
        @(posedge clk)
        ((addend2 == 4'd0) && (carry_in == 1'b0)) |-> ({carry_out, sum} == {1'b0, addend1})
    );

// With addend1 cleared and no carry-in, the output must pass through addend2.
    check_addend2_passthrough: assert property (
        @(posedge clk)
        ((addend1 == 4'd0) && (carry_in == 1'b0)) |-> ({carry_out, sum} == {1'b0, addend2})
    );

// A lone carry-in must increment zero operands to one without overflow.
    check_carry_in_increment: assert property (
        @(posedge clk)
        ((addend1 == 4'd0) && (addend2 == 4'd0) && (carry_in == 1'b1)) |-> ((sum == 4'd1) && (carry_out == 1'b0))
    );

// Maximum operands with carry-in must overflow and leave sum at 4'hF.
    check_maximum_overflow: assert property (
        @(posedge clk)
        ((addend1 == 4'hF) && (addend2 == 4'hF) && (carry_in == 1'b1)) |-> ((sum == 4'hF) && (carry_out == 1'b1))
    );

// Checks the full combinational equation for Z.
    check_full_boolean_equation: assert property (
        @(posedge clk)
        Z == (((A & ~B) & ~S1 & ~S0) |
              ((~A & B) &  S1 & ~S0) |
              ((~A & ~B) & S1 &  S0) |
              ((A & ~B) & ~S1 &  S0))
    );

// Checks that S1 low makes Z equal A and not B.
    check_s1_low_selects_a_and_not_b: assert property (
        @(posedge clk)
        (!S1) |-> (Z == (A & ~B))
    );

// Checks that S1 high and S0 low make Z equal not A and B.
    check_s1_high_s0_low_selects_not_a_and_b: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Z == (~A & B))
    );

// Checks that S1 high and S0 high make Z equal not A and not B.
    check_s1_high_s0_high_selects_not_a_and_not_b: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Z == (~A & ~B))
    );

// Checks that A and B both high force Z low.
    check_ab_11_forces_zero: assert property (
        @(posedge clk)
        (A && B) |-> (Z == 1'b0)
    );

// Checks that A high and B low make Z depend only on S1.
    check_ab_10_matches_not_s1: assert property (
        @(posedge clk)
        (A && !B) |-> (Z == (~S1))
    );

// Checks that A low and B high produce S1 and not S0.
    check_ab_01_matches_s1_and_not_s0: assert property (
        @(posedge clk)
        (!A && B) |-> (Z == (S1 & ~S0))
    );

// Checks that A and B both low produce S1 and S0.
    check_ab_00_matches_s1_and_s0: assert property (
        @(posedge clk)
        (!A && !B) |-> (Z == (S1 & S0))
    );

// With x4 low, only the x1x2x3 term can make y high.
    check_x4_low_only_x123_controls_y: assert property (
        @(posedge clk)
        (!x4) |-> (y == (x1 & x2 & x3))
    );

// With x4 high, y reduces to x1 OR x2 OR x3.
    check_x4_high_reduces_to_or123: assert property (
        @(posedge clk)
        x4 |-> (y == (x1 | x2 | x3))
    );

// If x1, x2, and x3 are all low, y must be low.
    check_all_x123_low_forces_y_low: assert property (
        @(posedge clk)
        (!(x1 | x2 | x3)) |-> (!y)
    );

// If x1, x2, and x3 are all high, y must be high.
    check_x123_high_forces_y_high: assert property (
        @(posedge clk)
        (x1 & x2 & x3) |-> y
    );

// Any asserted x1, x2, or x3 with x4 high must drive y high.
    check_x4_with_any_x123_sets_y: assert property (
        @(posedge clk)
        (x4 & (x1 | x2 | x3)) |-> y
    );

// If y is high while x4 is low, x1, x2, and x3 must all be high.
    check_y_high_without_x4_requires_x123: assert property (
        @(posedge clk)
        (y & !x4) |-> (x1 & x2 & x3)
    );

// If y is high while x4 is high, at least one of x1, x2, or x3 must be high.
    check_y_high_with_x4_requires_any_x123: assert property (
        @(posedge clk)
        (y & x4) |-> (x1 | x2 | x3)
    );

// X equals the AND of A, B, C, and D.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// All inputs high drives X high.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A && B && C && D) |-> X
    );

// Any low input drives X low.
    check_any_low_drives_x_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !X
    );

// X high requires all inputs high.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A && B && C && D)
    );

// X low requires at least one input low.
    check_x_low_requires_some_input_low: assert property (
        @(posedge clk) !X |-> (!A || !B || !C || !D)
    );

// Reset clears Q on the following clock sample.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (Q == 4'h0)
    );

// A load captures the current 4-bit sum of A and B.
    check_load_captures_sum: assert property (
        @(posedge clk) disable iff (rst) load |=> (Q == $past(A + B))
    );

// Without a load, Q holds its previous value.
    check_hold_when_not_load: assert property (
        @(posedge clk) disable iff (rst) !load |=> (Q == $past(Q))
    );

// Reset overrides load when both are asserted together.
    check_reset_priority_over_load: assert property (
        @(posedge clk) rst && load |=> (Q == 4'h0)
    );

// Reset clears the internal state and both outputs.
    check_reset_clears_state: assert property (
        @(posedge clk)
        !rst_n |-> (rden == 3'b000) &&
                  (wren == 3'b000) &&
                  (c_rd_en == 1'b0) &&
                  (c_wr_en == 1'b0) &&
                  (reg_en == 1'b0) &&
                  (reg_wr_en == 1'b0)
    );

// reg_wr_en is a single-cycle pulse.
    check_reg_wr_en_single_cycle: assert property (
        @(posedge clk) disable iff (!rst_n)
        reg_wr_en |=> !reg_wr_en
    );

// Any write-enable output pulse must also assert reg_en.
    check_reg_wr_en_implies_reg_en: assert property (
        @(posedge clk) disable iff (!rst_n)
        reg_wr_en |-> reg_en
    );

// External sampling clock; the RTL is combinational and has no reset.

    // op 000 selects bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (op == 3'b000) |-> (result == (a & b))
    );

// op 001 selects bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (op == 3'b001) |-> (result == (a | b))
    );

// op 010 selects bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (op == 3'b010) |-> (result == (a ^ b))
    );

// op 011 selects addition.
    check_add_result: assert property (
        @(posedge clk) (op == 3'b011) |-> (result == (a + b))
    );

// op 100 selects subtraction.
    check_sub_result: assert property (
        @(posedge clk) (op == 3'b100) |-> (result == (a - b))
    );

// Unsupported op values drive zero.
    check_default_result: assert property (
        @(posedge clk) ((op == 3'b101) || (op == 3'b110) || (op == 3'b111)) |-> (result == 8'b0)
    );

// When select is 00, output must match input a.
    check_select_a: assert property (
        @(posedge clk) (s === 2'b00) |-> (w === a)
    );

// When select is 01, output must match input b.
    check_select_b: assert property (
        @(posedge clk) (s === 2'b01) |-> (w === b)
    );

// When select is 10, output must match input c.
    check_select_c: assert property (
        @(posedge clk) (s === 2'b10) |-> (w === c)
    );

// When select is 11, output must match input d.
    check_select_d: assert property (
        @(posedge clk) (s === 2'b11) |-> (w === d)
    );

// Reset holds sum low.
    check_reset_clears_sum: assert property (
        @(posedge clk) rst |-> (sum == 1'b0)
    );

// Reset holds the carry state low.
    check_reset_clears_sc: assert property (
        @(posedge clk) rst |-> (sc == 1'b0)
    );

// tri_o_out follows tri_o_in when gpio_sel is 0 or 1.
    check_tri_o_out_sel01: assert property (
        @(posedge clk)
        ((gpio_sel == 2'h0) || (gpio_sel == 2'h1)) |-> (tri_o_out == tri_o_in)
    );

// tri_o_out follows sda_o_in when gpio_sel is 2.
    check_tri_o_out_sel2: assert property (
        @(posedge clk)
        (gpio_sel == 2'h2) |-> (tri_o_out == sda_o_in)
    );

// tri_o_out follows scl_o_in when gpio_sel is 3.
    check_tri_o_out_sel3: assert property (
        @(posedge clk)
        (gpio_sel == 2'h3) |-> (tri_o_out == scl_o_in)
    );

// tri_t_out follows tri_t_in when gpio_sel is 0 or 1.
    check_tri_t_out_sel01: assert property (
        @(posedge clk)
        ((gpio_sel == 2'h0) || (gpio_sel == 2'h1)) |-> (tri_t_out == tri_t_in)
    );

// tri_t_out follows sda_t_in when gpio_sel is 2.
    check_tri_t_out_sel2: assert property (
        @(posedge clk)
        (gpio_sel == 2'h2) |-> (tri_t_out == sda_t_in)
    );

// tri_t_out follows scl_t_in when gpio_sel is 3.
    check_tri_t_out_sel3: assert property (
        @(posedge clk)
        (gpio_sel == 2'h3) |-> (tri_t_out == scl_t_in)
    );

// tri_i_out is routed to tri_i_in only when gpio_sel is 0 or 1.
    check_tri_i_demux_sel01: assert property (
        @(posedge clk)
        ((gpio_sel == 2'h0) || (gpio_sel == 2'h1)) |-> ({scl_i_in, sda_i_in, tri_i_in} == {1'b0, 1'b0, tri_i_out})
    );

// tri_i_out is routed to sda_i_in only when gpio_sel is 2.
    check_tri_i_demux_sel2: assert property (
        @(posedge clk)
        (gpio_sel == 2'h2) |-> ({scl_i_in, sda_i_in, tri_i_in} == {1'b0, tri_i_out, 1'b0})
    );

// tri_i_out is routed to scl_i_in only when gpio_sel is 3.
    check_tri_i_demux_sel3: assert property (
        @(posedge clk)
        (gpio_sel == 2'h3) |-> ({scl_i_in, sda_i_in, tri_i_in} == {tri_i_out, 1'b0, 1'b0})
    );

// A reset cycle clears the counter for the following sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// When below 15 and not in reset, the counter increments by one.
    check_increment_when_below_max: assert property (
        @(posedge clk) disable iff (rst) (count < 4'd15) |=> (count == ($past(count) + 4'd1))
    );

// When at 15 and not in reset, the counter wraps to zero.
    check_wrap_from_max_to_zero: assert property (
        @(posedge clk) disable iff (rst) (count == 4'd15) |=> (count == 4'd0)
    );

// Reset drives q low.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 1'b0)
    );

// Reset has priority over set.
    check_reset_priority_over_set: assert property (
        @(posedge clk) (reset && set) |=> (q == 1'b0)
    );

// Set drives q high when reset is low.
    check_set_drives_q_high: assert property (
        @(posedge clk) disable iff (reset) set |=> (q == 1'b1)
    );

// Set overrides d when d is low.
    check_set_priority_over_d_low: assert property (
        @(posedge clk) disable iff (reset) (set && (d == 1'b0)) |=> (q == 1'b1)
    );

// q captures d=1 when reset and set are low.
    check_data_capture_one: assert property (
        @(posedge clk) disable iff (reset) (!set && (d == 1'b1)) |=> (q == 1'b1)
    );

// q captures d=0 when reset and set are low.
    check_data_capture_zero: assert property (
        @(posedge clk) disable iff (reset) (!set && (d == 1'b0)) |=> (q == 1'b0)
    );

// The combined outputs must equal A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// The least-significant sum bit must match the first full-adder XOR.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// When A is zero, the result must be B plus Cin.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> ({Cout, S} == ({1'b0, B} + Cin))
    );

// When B is zero, the result must be A plus Cin.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> ({Cout, S} == ({1'b0, A} + Cin))
    );

// Complementary operands with no carry-in must sum to all ones.
    check_complementary_no_carryin: assert property (
        @(posedge clk) ((A == ~B) && !Cin) |-> ((S == 4'hF) && !Cout)
    );

// Complementary operands with carry-in must wrap to zero with carry-out.
    check_complementary_with_carryin: assert property (
        @(posedge clk) ((A == ~B) && Cin) |-> ((S == 4'h0) && Cout)
    );

// Maximum inputs with carry-in must produce 5'b1_1111.
    check_maximum_sum: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF) && Cin) |-> ((S == 4'hF) && Cout)
    );

// Zero operands must only propagate Cin into bit 0.
    check_all_zero_inputs: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h0)) |-> ((S == {3'b000, Cin}) && !Cout)
    );

// An extended sum of 16 or more must assert carry-out.
    check_overflow_sets_cout: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> Cout
    );

// An extended sum below 16 must deassert carry-out.
    check_no_overflow_clears_cout: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |-> !Cout
    );

// Reset forces q low on the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 16'h0000)
    );

// When reset is low, q captures d from the previous rising edge.
    check_q_captures_d: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q == $past(d))
    );

// Clear drives Y low.
    check_clear_forces_y_low: assert property (
        @(posedge clk) CLR |-> (Y == 1'b0)
    );

// Clear drives Yn high.
    check_clear_forces_yn_high: assert property (
        @(posedge clk) CLR |-> (Yn == 1'b1)
    );

// Without clear, Y is the NAND of A and B.
    check_y_matches_nand_when_not_cleared: assert property (
        @(posedge clk) disable iff (CLR) (Y == ~(A & B))
    );

// Without clear, Yn is the AND of A and B.
    check_yn_matches_and_when_not_cleared: assert property (
        @(posedge clk) disable iff (CLR) (Yn == (A & B))
    );

// The outputs are always complementary.
    check_outputs_are_complementary: assert property (
        @(posedge clk) (Y == ~Yn)
    );

// Reset clears the LED output register.
    check_reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 4'b0000)
    );

// Reset clears the readback data.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

// Read data is always zero-extended.
    check_readdata_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:4] == 28'b0)
    );

// Address 0 reads back the current output value.
    check_readback_at_address_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {28'b0, out_port})
    );

// Nonzero addresses read back zero.
    check_readback_at_other_addresses: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

// A selected write to address 0 updates the output on the next cycle.
    check_write_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[3:0]))
    );

// Without a selected write to address 0, the output holds its value.
    check_out_port_holds_without_valid_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

// Combinational RTL with no native clock or reset; sample on an external clock.

    // out[7:0] is the bitwise XOR of the two inputs.
    check_out_low_is_xor: assert property (
        @(posedge clk) out[7:0] == (in1 ^ in2)
    );

// out[8] is the parity of the XOR result.
    check_out_msb_is_input_parity: assert property (
        @(posedge clk) out[8] == (^(in1 ^ in2))
    );

// out[8] matches the parity of out[7:0].
    check_out_msb_matches_out_low_parity: assert property (
        @(posedge clk) out[8] == (^out[7:0])
    );

// out concatenates the parity bit with the XOR result.
    check_out_concatenation: assert property (
        @(posedge clk) out == { (^(in1 ^ in2)), (in1 ^ in2) }
    );

// sum equals in1 plus in2 plus the connected out[8] bit.
    check_sum_uses_out_msb: assert property (
        @(posedge clk) sum == (in1 + in2 + out[8])
    );

// sum equals in1 plus in2 plus parity of the XOR result.
    check_sum_matches_input_parity: assert property (
        @(posedge clk) sum == (in1 + in2 + (^(in1 ^ in2)))
    );

// X matches the implemented NOR/AND/OR function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((~A1_N & ~A2_N) | (B1 & B2))
    );

// X is high whenever both B inputs are high.
    check_b_inputs_force_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// X is high whenever both A inputs are low.
    check_a_inputs_force_high: assert property (
        @(posedge clk) (~A1_N & ~A2_N) |-> X
    );

// X is low when neither logic path is active.
    check_no_active_path_means_low: assert property (
        @(posedge clk) ((A1_N | A2_N) & (~B1 | ~B2)) |-> ~X
    );

// A high X without the B path must come from the A-side NOR path.
    check_high_without_b_path_comes_from_a_path: assert property (
        @(posedge clk) (X & ~(B1 & B2)) |-> (~A1_N & ~A2_N)
    );

// A high X with the A-side NOR path inactive must come from the B-side AND path.
    check_high_without_a_path_comes_from_b_path: assert property (
        @(posedge clk) (X & (A1_N | A2_N)) |-> (B1 & B2)
    );

// A low X implies the B-side AND path is inactive.
    check_low_output_disables_b_path: assert property (
        @(posedge clk) (~X) |-> ~(B1 & B2)
    );

// A low X implies the A-side NOR path is inactive.
    check_low_output_disables_a_path: assert property (
        @(posedge clk) (~X) |-> (A1_N | A2_N)
    );

// S=00 passes I directly to O.
    check_sel_00_passthrough: assert property (
        @(posedge clk) (S === 2'b00) |-> (O === I)
    );

// S=01 passes I directly to O.
    check_sel_01_passthrough: assert property (
        @(posedge clk) (S === 2'b01) |-> (O === {I[11:0]})
    );

// S=10 swaps the upper and lower 6-bit halves.
    check_sel_10_swap_halves: assert property (
        @(posedge clk) (S === 2'b10) |-> (O === {I[5:0], I[11:6]})
    );

// S=11 keeps the original 6-bit half ordering.
    check_sel_11_passthrough: assert property (
        @(posedge clk) (S === 2'b11) |-> (O === {I[11:6], I[5:0]})
    );

// Invalid 4-state select values drive O to unknown.
    check_invalid_select_unknown_output: assert property (
        @(posedge clk)
        ((S !== 2'b00) && (S !== 2'b01) && (S !== 2'b10) && (S !== 2'b11))
        |-> (O === 12'hxxx)
    );

// RTL is combinational and has no native clock or reset; sample it on clk.

    // min must match the RTL's nested minimum calculation.
    check_min_matches_rtl_function: assert property (
        @(posedge clk)
        min == ((((a < b) ? a : b) < ((c < d) ? c : d)) ? ((a < b) ? a : b) : ((c < d) ? c : d))
    );

// min must be less than or equal to every input.
    check_min_le_all_inputs: assert property (
        @(posedge clk)
        (min <= a) && (min <= b) && (min <= c) && (min <= d)
    );

// min must equal one of the four inputs.
    check_min_matches_an_input: assert property (
        @(posedge clk)
        (min == a) || (min == b) || (min == c) || (min == d)
    );

// If a is a minimum value, min must equal a.
    check_a_drives_min_when_lowest: assert property (
        @(posedge clk)
        (a <= b && a <= c && a <= d) |-> (min == a)
    );

// If b is a minimum value, min must equal b.
    check_b_drives_min_when_lowest: assert property (
        @(posedge clk)
        (b <= a && b <= c && b <= d) |-> (min == b)
    );

// If c is a minimum value, min must equal c.
    check_c_drives_min_when_lowest: assert property (
        @(posedge clk)
        (c <= a && c <= b && c <= d) |-> (min == c)
    );

// If d is a minimum value, min must equal d.
    check_d_drives_min_when_lowest: assert property (
        @(posedge clk)
        (d <= a && d <= b && d <= c) |-> (min == d)
    );

// In S0 with data low, the FSM stays in S0.
    check_s0_data0_stays_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S0 && data == 1'b0) |=> (state == S0)
    );

// In S0 with data high, the FSM advances to S1.
    check_s0_data1_to_s1: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S0 && data == 1'b1) |=> (state == S1)
    );

// In S1 with data low, the FSM returns to S0.
    check_s1_data0_to_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S1 && data == 1'b0) |=> (state == S0)
    );

// In S1 with data high, the FSM advances to S2.
    check_s1_data1_to_s2: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S1 && data == 1'b1) |=> (state == S2)
    );

// In S2 with data low, the FSM returns to S0.
    check_s2_data0_to_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S2 && data == 1'b0) |=> (state == S0)
    );

// In S2 with data high, the FSM advances to S3.
    check_s2_data1_to_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S2 && data == 1'b1) |=> (state == S3)
    );

// In S3 with data low, the FSM stays in S3.
    check_s3_data0_stays_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S3 && data == 1'b0) |=> (state == S3)
    );

// In S3 with data high, the FSM wraps back to S0.
    check_s3_data1_to_s0: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S3 && data == 1'b1) |=> (state == S0)
    );

// Match must be high whenever the FSM is in S3.
    check_match_high_in_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S3) |-> (match == 1'b1)
    );

// Match must be low in all non-S3 states.
    check_match_low_outside_s3: assert property (
        @(posedge clk) disable iff (!reset)
        (state == S0 || state == S1 || state == S2) |-> (match == 1'b0)
    );

// Y matches the AND of A and B.
    check_and_function: assert property (
        @(posedge clk) Y == (A & B)
    );

// Both high inputs drive Y high.
    check_both_inputs_high_drive_output_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (Y == 1'b1)
    );

// A low drives Y low.
    check_a_low_drives_output_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b0)
    );

// B low drives Y low.
    check_b_low_drives_output_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b0)
    );

// A high output requires both inputs high.
    check_output_high_requires_both_inputs_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A == 1'b1) && (B == 1'b1))
    );

// When hsync is high, the truncated concatenation captured into rgb equals rgb_1.
    check_capture_on_hsync: assert property (
        @(posedge clock) hsync |=> (rgb == $past(rgb_1))
    );

// When hsync is low, rgb holds its previous value.
    check_hold_when_hsync_low: assert property (
        @(posedge clock) !hsync |=> (rgb == $past(rgb))
    );

// When hsync is high, rgb upper byte is taken from rgb_1 upper byte.
    check_capture_upper_byte_on_hsync: assert property (
        @(posedge clock) hsync |=> (rgb[15:8] == $past(rgb_1[15:8]))
    );

// When hsync is high, rgb lower byte is taken from rgb_1 lower byte.
    check_capture_lower_byte_on_hsync: assert property (
        @(posedge clock) hsync |=> (rgb[7:0] == $past(rgb_1[7:0]))
    );

// Outputs match the 9-bit zero-extended addition of A and B.
    check_result_matches_extended_addition: assert property (
        @(posedge clk) {carry_out, sum} == ({1'b0, A} + {1'b0, B})
    );

// Zero on A passes B through with no carry.
    check_a_zero_passes_b: assert property (
        @(posedge clk) (A == 8'h00) |-> (sum == B && carry_out == 1'b0)
    );

// Zero on B passes A through with no carry.
    check_b_zero_passes_a: assert property (
        @(posedge clk) (B == 8'h00) |-> (sum == A && carry_out == 1'b0)
    );

// 8'hFF plus 8'h01 wraps sum and raises carry.
    check_overflow_boundary_ff_plus_01: assert property (
        @(posedge clk) (A == 8'hFF && B == 8'h01) |-> (sum == 8'h00 && carry_out == 1'b1)
    );

// 8'hFF plus 8'hFF produces 8'hFE with carry high.
    check_max_operands_overflow: assert property (
        @(posedge clk) (A == 8'hFF && B == 8'hFF) |-> (sum == 8'hFE && carry_out == 1'b1)
    );

// When select is 00, out matches inputs[0].
    check_select_00_routes_input0: assert property (
        @(posedge clk) disable iff (1'b0)
        (select == 2'b00) |-> (out == inputs[0])
    );

// When select is 01, out matches inputs[1].
    check_select_01_routes_input1: assert property (
        @(posedge clk) disable iff (1'b0)
        (select == 2'b01) |-> (out == inputs[1])
    );

// When select is 10, out matches inputs[2].
    check_select_10_routes_input2: assert property (
        @(posedge clk) disable iff (1'b0)
        (select == 2'b10) |-> (out == inputs[2])
    );

// When select is 11, out matches inputs[3].
    check_select_11_routes_input3: assert property (
        @(posedge clk) disable iff (1'b0)
        (select == 2'b11) |-> (out == inputs[3])
    );

// X must equal the AND of all four inputs.
    check_output_definition: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// If all inputs are high, X must be high.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// If X is high, all inputs must be high.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A & B & C & D)
    );

// A low input forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (!A) |-> (!X)
    );

// A low input forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) (!B) |-> (!X)
    );

// A low input forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) (!C) |-> (!X)
    );

// A low input forces X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) (!D) |-> (!X)
    );

// If X is low, at least one input must be low.
    check_x_low_requires_some_input_low: assert property (
        @(posedge clk) (!X) |-> ((!A) | (!B) | (!C) | (!D))
    );

// PPi must match the implemented combinational equation.
    check_ppi_matches_logic: assert property (
        @(posedge clk)
        PPi == (((Yi & Single) | (Yi_m1 & Double)) ^ Negate)
    );

// With no active partial-product terms and no negate, PPi must be low.
    check_inactive_terms_no_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b0) && (Negate == 1'b0)) |-> (PPi == 1'b0)
    );

// With no active partial-product terms and negate asserted, PPi must be high.
    check_inactive_terms_with_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b0) && (Negate == 1'b1)) |-> (PPi == 1'b1)
    );

// With any active partial-product term and no negate, PPi must be high.
    check_active_term_no_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b1) && (Negate == 1'b0)) |-> (PPi == 1'b1)
    );

// With any active partial-product term and negate asserted, PPi must be low.
    check_active_term_with_negate: assert property (
        @(posedge clk)
        ((((Yi & Single) | (Yi_m1 & Double)) == 1'b1) && (Negate == 1'b1)) |-> (PPi == 1'b0)
    );

// Result matches the selected add or subtract operation.
    check_result_matches_selected_operation: assert property (
        @(posedge clk) result == (op ? (a - b) : (a + b))
    );

// Carry is asserted only for overflow during addition.
    check_carry_matches_add_overflow: assert property (
        @(posedge clk) carry == ((op == 1'b0) && (({1'b0, a} + {1'b0, b}) > 5'd15))
    );

// In add mode, the outputs match the full 5-bit sum.
    check_add_outputs_match_sum: assert property (
        @(posedge clk) (op == 1'b0) |-> ({carry, result} == ({1'b0, a} + {1'b0, b}))
    );

// In subtract mode, result matches the 4-bit difference.
    check_subtract_result_matches_difference: assert property (
        @(posedge clk) (op == 1'b1) |-> (result == (a - b))
    );

// In subtract mode, carry is always low.
    check_subtract_carry_is_zero: assert property (
        @(posedge clk) (op == 1'b1) |-> (carry == 1'b0)
    );

// Clear synchronously forces the counter to zero.
    check_clear_forces_zero: assert property (
        @(posedge Clock) Clear |=> (Q == 2'b00)
    );

// Load sets the counter to 2'b11 when clear is inactive.
    check_load_sets_q_to_11: assert property (
        @(posedge Clock) disable iff (Clear) Load |=> (Q == 2'b11)
    );

// With no control active, the counter holds its value.
    check_idle_holds_q: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && !Enable) |=> (Q == $past(Q))
    );

// Enable increments 2'b00 to 2'b01.
    check_enable_00_to_01: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b00)) |=> (Q == 2'b01)
    );

// Enable increments 2'b01 to 2'b10.
    check_enable_01_to_10: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b01)) |=> (Q == 2'b10)
    );

// Enable increments 2'b10 to 2'b11.
    check_enable_10_to_11: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b10)) |=> (Q == 2'b11)
    );

// Enable wraps 2'b11 back to 2'b00.
    check_enable_11_to_00: assert property (
        @(posedge Clock) disable iff (Clear) (!Load && Enable && (Q == 2'b11)) |=> (Q == 2'b00)
    );

// dio_o always matches dio_p.
            check_dio_o_matches_dio_p: assert property (
                @(posedge clk) dio_o[n] == dio_p[n]
            );

// High dio_t makes dio_p follow dio_i.
            check_dio_p_follows_dio_i_when_dio_t_high: assert property (
                @(posedge clk) dio_t[n] |-> (dio_p[n] == dio_i[n])
            );

// Low dio_t forces dio_p high.
            check_dio_p_forced_high_when_dio_t_low: assert property (
                @(posedge clk) !dio_t[n] |-> (dio_p[n] == 1'b1)
            );

// High dio_t makes dio_o follow dio_i.
            check_dio_o_follows_dio_i_when_dio_t_high: assert property (
                @(posedge clk) dio_t[n] |-> (dio_o[n] == dio_i[n])
            );

// Low dio_t forces dio_o high.
            check_dio_o_forced_high_when_dio_t_low: assert property (
                @(posedge clk) !dio_t[n] |-> (dio_o[n] == 1'b1)
            );

// A sampled reset clears r and l.
    check_reset_clears_r_l: assert property (
        @(posedge clk) reset |=> (r == 8'd0 && l == 1'b0)
    );

// out must equal the implemented Boolean expression.
    check_out_matches_rtl_expression: assert property (
        @(posedge clk)
        out == (((in & (in - 32'd1)) == 32'd0) && (in[0] == 1'b0))
    );

// Any input with bit 0 set forces out low.
    check_lsb_one_forces_out_low: assert property (
        @(posedge clk)
        in[0] |-> !out
    );

// All-zero input produces a high output.
    check_zero_input_sets_out_high: assert property (
        @(posedge clk)
        (in == 32'd0) |-> out
    );

// A nonzero one-hot input above bit 0 produces a high output.
    check_upper_onehot_sets_out_high: assert property (
        @(posedge clk)
        ((in != 32'd0) && ((in & (in - 32'd1)) == 32'd0) && (in[0] == 1'b0)) |-> out
    );

// Inputs with multiple set bits produce a low output.
    check_multi_bit_input_clears_out: assert property (
        @(posedge clk)
        ((in & (in - 32'd1)) != 32'd0) |-> !out
    );

// X must always be the AND of A and B.
    check_x_is_and: assert property (
        @(posedge clk) X == (A & B)
    );

// Y must always be the XOR of A and B.
    check_y_is_xor: assert property (
        @(posedge clk) Y == (A ^ B)
    );

// When both inputs are high, X is high and Y is low.
    check_both_high_outputs: assert property (
        @(posedge clk) (A && B) |-> (X && !Y)
    );

// When both inputs are low, both outputs are low.
    check_both_low_outputs: assert property (
        @(posedge clk) (!A && !B) |-> (!X && !Y)
    );

// When the inputs differ, X is low and Y is high.
    check_inputs_differ_outputs: assert property (
        @(posedge clk) (A ^ B) |-> (!X && Y)
    );

// AND and XOR outputs can never both be high.
    check_outputs_not_both_high: assert property (
        @(posedge clk) !(X && Y)
    );

// EN low forces the output low.
    check_disabled_zero: assert property (
        @(posedge clk) (EN == 1'b0) |-> (Y == 8'b00000000)
    );

// Enabled decode of A=0, B=0, C=0 sets bit 0.
    check_decode_c000: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b000) |-> (Y == 8'b00000001)
    );

// Enabled decode of A=0, B=0, C=1 sets bit 1.
    check_decode_c001: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b001) |-> (Y == 8'b00000010)
    );

// Enabled decode of A=0, B=0, C=2 sets bit 2.
    check_decode_c010: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b010) |-> (Y == 8'b00000100)
    );

// Enabled decode of A=0, B=0, C=3 sets bit 3.
    check_decode_c011: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b011) |-> (Y == 8'b00001000)
    );

// Enabled decode of A=0, B=0, C=4 sets bit 4.
    check_decode_c100: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b100) |-> (Y == 8'b00010000)
    );

// Enabled decode of A=0, B=0, C=5 sets bit 5.
    check_decode_c101: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b101) |-> (Y == 8'b00100000)
    );

// Enabled decode of A=0, B=0, C=6 sets bit 6.
    check_decode_c110: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b110) |-> (Y == 8'b01000000)
    );

// Enabled decode of A=0, B=0, C=7 sets bit 7.
    check_decode_c111: assert property (
        @(posedge clk) (EN == 1'b1 && A == 3'b000 && B == 3'b000 && C == 3'b111) |-> (Y == 8'b10000000)
    );

// Any other enabled input combination drives zero.
    check_enabled_default_zero: assert property (
        @(posedge clk) (EN == 1'b1 && (A != 3'b000 || B != 3'b000)) |-> (Y == 8'b00000000)
    );

// Y matches the implemented combinational function.
    check_y_function: assert property (
        @(posedge clk) Y == ~(~B1_N & (A1 | A2))
    );

// A high B1_N forces Y high.
    check_b1n_high_forces_y_high: assert property (
        @(posedge clk) B1_N |-> Y
    );

// Both A inputs low force Y high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) (!A1 && !A2) |-> Y
    );

// With B1_N low, any high A input forces Y low.
    check_or_term_with_b1n_low_forces_y_low: assert property (
        @(posedge clk) (!B1_N && (A1 || A2)) |-> !Y
    );

// A low output requires B1_N low and the OR term high.
    check_y_low_only_when_expected: assert property (
        @(posedge clk) (!Y) |-> (!B1_N && (A1 || A2))
    );

// S=00 selects input A.
    check_select_a: assert property (
        @(posedge clk) (S == 2'b00) |-> (Y == A)
    );

// S=01 selects input B.
    check_select_b: assert property (
        @(posedge clk) (S == 2'b01) |-> (Y == B)
    );

// S=10 selects input C.
    check_select_c: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y == C)
    );

// S=11 selects input D.
    check_select_d: assert property (
        @(posedge clk) (S == 2'b11) |-> (Y == D)
    );

// Reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// Reset has priority even when enable is high.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (rst && en) |=> (count == 4'b0000)
    );

// Counter increments by one when enabled.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (rst)
        en |=> (count == ($past(count) + 4'd1))
    );

// Counter holds its value when enable is low.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        (!en) |=> (count == $past(count))
    );

// Counter wraps from 15 back to 0 when enabled.
    check_count_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst)
        (en && (count == 4'hF)) |=> (count == 4'h0)
    );

// The 5-bit output matches A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Bit 0 sum matches the first full adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 1 sum uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1] == (A[1] ^ B[1] ^ fa_cout(A[0], B[0], Cin))
    );

// Bit 2 sum uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2] == (A[2] ^ B[2] ^ fa_cout(A[1], B[1], fa_cout(A[0], B[0], Cin)))
    );

// Bit 3 sum uses the ripple carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        S[3] == (A[3] ^ B[3] ^ fa_cout(A[2], B[2], fa_cout(A[1], B[1], fa_cout(A[0], B[0], Cin))))
    );

// Carry-out matches the final full adder carry equation.
    check_cout: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == fa_cout(A[3], B[3], fa_cout(A[2], B[2], fa_cout(A[1], B[1], fa_cout(A[0], B[0], Cin))))
    );

// No reset in RTL; assertions are sampled on clk.

    // B matches the bitwise complement of A.
    check_vector_complement: assert property (
        @(posedge clk) B === ~A
    );

// B[0] is the complement of A[0].
    check_bit0_complement: assert property (
        @(posedge clk) B[0] === ~A[0]
    );

// B[1] is the complement of A[1].
    check_bit1_complement: assert property (
        @(posedge clk) B[1] === ~A[1]
    );

// B[2] is the complement of A[2].
    check_bit2_complement: assert property (
        @(posedge clk) B[2] === ~A[2]
    );

// B[3] is the complement of A[3].
    check_bit3_complement: assert property (
        @(posedge clk) B[3] === ~A[3]
    );

// free3 with tm_count of 3 selects increment 3.
    check_free3_tm3_increment3: assert property (
        @(posedge clk)
        (free3 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

// free2 with tm_count of 2 or 3 selects increment 2 when the free3 case is absent.
    check_free2_high_count_increment2: assert property (
        @(posedge clk)
        (!(free3 && (tm_count == 2'b11)) && free2 && (tm_count >= 2'b10)) |-> (fifowp_inc == 4'b0010)
    );

// Any remaining nonzero tm_count selects increment 1.
    check_fallback_nonzero_count_increment1: assert property (
        @(posedge clk)
        (!(free3 && (tm_count == 2'b11)) &&
         !(free2 && (tm_count >= 2'b10)) &&
         (tm_count >= 2'b01)) |-> (fifowp_inc == 4'b0001)
    );

// tm_count of 0 selects increment 0.
    check_zero_count_increment0: assert property (
        @(posedge clk)
        (tm_count == 2'b00) |-> (fifowp_inc == 4'b0000)
    );

// Output 3 only occurs for free3 with tm_count of 3.
    check_increment3_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0011) |-> (free3 && (tm_count == 2'b11))
    );

// Output 2 only occurs for the second branch condition.
    check_increment2_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0010) |-> (!(free3 && (tm_count == 2'b11)) && free2 && (tm_count >= 2'b10))
    );

// Output 1 only occurs for the third branch condition.
    check_increment1_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0001) |-> (!(free3 && (tm_count == 2'b11)) &&
                                     !(free2 && (tm_count >= 2'b10)) &&
                                     (tm_count >= 2'b01))
    );

// Output 0 only occurs when tm_count is 0.
    check_increment0_condition: assert property (
        @(posedge clk)
        (fifowp_inc == 4'b0000) |-> (tm_count == 2'b00)
    );

// No clock or reset exists in the RTL; sample on an external clock.
    // Sum output matches the implemented XOR-of-three function.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// When A and B are equal, sum follows Ci.
    check_sum_equal_ab: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

// When A and B differ, sum is the inverse of Ci.
    check_sum_different_ab: assert property (
        @(posedge clk) (A != B) |-> (S == ~Ci)
    );

// Carry output matches the implemented A & (B | Ci) function.
    check_carry_function: assert property (
        @(posedge clk) Co == (A & (B | Ci))
    );

// Carry can only assert when A is high.
    check_carry_requires_a: assert property (
        @(posedge clk) Co |-> A
    );

// A and B high must assert carry.
    check_carry_from_ab: assert property (
        @(posedge clk) (A & B) |-> Co
    );

// A and Ci high must assert carry.
    check_carry_from_aci: assert property (
        @(posedge clk) (A & Ci) |-> Co
    );

// A low must force carry low.
    check_no_carry_when_a_low: assert property (
        @(posedge clk) (!A) |-> (!Co)
    );

// With only A high, carry must remain low.
    check_no_carry_with_a_only: assert property (
        @(posedge clk) (A & !B & !Ci) |-> (!Co)
    );

// Reset forces the counter output to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// Counts below fifteen increment by one on the next cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'd15) |=> (count == ($past(count) + 4'd1))
    );

// Fifteen wraps back to zero on the next cycle.
    check_count_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'd15) |=> (count == 4'd0)
    );

// Every non-reset cycle follows the implemented next-state function.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count == (($past(count) == 4'd15) ? 4'd0 : ($past(count) + 4'd1)))
    );

// Active-low reset forces state to 00.
    check_reset_forces_state_00: assert property (
        @(posedge clk) (!reset) |-> (state == 2'b00)
    );

// State 00 with input 0 transitions to 01.
    check_state_00_input_0_to_01: assert property (
        @(posedge clk) disable iff (!reset)
        ((state == 2'b00) && (input_bit == 1'b0)) |=> (state == 2'b01)
    );

// State 00 with input 1 stays at 00.
    check_state_00_input_1_stays_00: assert property (
        @(posedge clk) disable iff (!reset)
        ((state == 2'b00) && (input_bit == 1'b1)) |=> (state == 2'b00)
    );

// State 01 with input 0 transitions to 10.
    check_state_01_input_0_to_10: assert property (
        @(posedge clk) disable iff (!reset)
        ((state == 2'b01) && (input_bit == 1'b0)) |=> (state == 2'b10)
    );

// State 01 with input 1 stays at 01.
    check_state_01_input_1_stays_01: assert property (
        @(posedge clk) disable iff (!reset)
        ((state == 2'b01) && (input_bit == 1'b1)) |=> (state == 2'b01)
    );

// State 10 with input 0 transitions to 01.
    check_state_10_input_0_to_01: assert property (
        @(posedge clk) disable iff (!reset)
        ((state == 2'b10) && (input_bit == 1'b0)) |=> (state == 2'b01)
    );

// State 10 with input 1 stays at 10.
    check_state_10_input_1_stays_10: assert property (
        @(posedge clk) disable iff (!reset)
        ((state == 2'b10) && (input_bit == 1'b1)) |=> (state == 2'b10)
    );

// Unhandled encoding 11 holds its value.
    check_state_11_holds_value: assert property (
        @(posedge clk) disable iff (!reset)
        (state == 2'b11) |=> (state == 2'b11)
    );

// Exact mux equation sampled on the formal clock.
    check_mux_function: assert property (
        @(posedge clk) X === ((S == 1'b0) ? A0 : A1)
    );

// Select low routes A0 to X.
    check_select_zero_routes_a0: assert property (
        @(posedge clk) (S === 1'b0) |-> (X === A0)
    );

// Select high routes A1 to X.
    check_select_one_routes_a1: assert property (
        @(posedge clk) (S === 1'b1) |-> (X === A1)
    );

// Equal data inputs force the same output value.
    check_equal_inputs_force_output: assert property (
        @(posedge clk) (A0 === A1) |-> (X === A0)
    );

// Full 5-bit result matches A + B + Cin.
    check_full_result: assert property (
        @(posedge clk) disable iff (1'b0)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Sum bit 0 matches the full-adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Lower two sum bits match a 2-bit add with carry-in.
    check_lower_two_bits: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1:0] == (A[1:0] + B[1:0] + Cin)
    );

// Lower three sum bits match a 3-bit add with carry-in.
    check_lower_three_bits: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2:0] == (A[2:0] + B[2:0] + Cin)
    );

// Adding zero on B with Cin low passes A through.
    check_add_zero_on_b: assert property (
        @(posedge clk) disable iff (1'b0)
        (B == 4'b0000 && Cin == 1'b0) |-> (S == A && Cout == 1'b0)
    );

// Adding zero on A with Cin low passes B through.
    check_add_zero_on_a: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'b0000 && Cin == 1'b0) |-> (S == B && Cout == 1'b0)
    );

// All-zero inputs produce an all-zero result.
    check_all_zero_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'b0000 && B == 4'b0000 && Cin == 1'b0) |-> (S == 4'b0000 && Cout == 1'b0)
    );

// Carry-in alone produces a value of one.
    check_cin_only: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'b0000 && B == 4'b0000 && Cin == 1'b1) |-> (S == 4'b0001 && Cout == 1'b0)
    );

// Maximum inputs with carry-in produce 5'h1F.
    check_max_with_cin: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> (S == 4'hF && Cout == 1'b1)
    );

// SUM implements A XOR B XOR inverted CIN.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// COUT implements (A&B) | (A&~CIN) | (B&~CIN).
    check_cout_equation: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// With CIN high, SUM reduces to A XOR B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) CIN |-> (SUM == (A ^ B))
    );

// With CIN high, COUT reduces to A AND B.
    check_cout_when_cin_high: assert property (
        @(posedge clk) CIN |-> (COUT == (A & B))
    );

// With CIN low, SUM reduces to XNOR of A and B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) !CIN |-> (SUM == ~(A ^ B))
    );

// With CIN low, COUT reduces to OR of A and B.
    check_cout_when_cin_low: assert property (
        @(posedge clk) !CIN |-> (COUT == (A | B))
    );

// When A and B match, SUM equals inverted CIN.
    check_sum_when_a_b_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == ~CIN)
    );

// When A and B differ, SUM equals CIN.
    check_sum_when_a_b_differ: assert property (
        @(posedge clk) (A != B) |-> (SUM == CIN)
    );

// When A and B match, COUT equals A.
    check_cout_when_a_b_equal: assert property (
        @(posedge clk) (A == B) |-> (COUT == A)
    );

// When A and B differ, COUT equals inverted CIN.
    check_cout_when_a_b_differ: assert property (
        @(posedge clk) (A != B) |-> (COUT == ~CIN)
    );

// When ctrl is low, the output selects D0.
    check_select_d0_when_ctrl_low: assert property (
        @(posedge clk) (ctrl === 1'b0) |-> (S === D0)
    );

// When ctrl is high, the unmatched selector drives zero.
    check_default_zero_when_ctrl_high: assert property (
        @(posedge clk) (ctrl === 1'b1) |-> (S === 1'b0)
    );

// A rising ctrl drives the output to zero.
    check_ctrl_rise_forces_zero: assert property (
        @(posedge clk) $rose(ctrl) |-> (S === 1'b0)
    );

// A falling ctrl makes the output select D0.
    check_ctrl_fall_selects_d0: assert property (
        @(posedge clk) $fell(ctrl) |-> (S === D0)
    );

// OUT always matches the implemented shift-or-pass-through function.
    check_output_matches_function: assert property (
        @(posedge clk)
        OUT == (SHIFT ? (DIR ? {IN[14:0], 1'b0} : {1'b0, IN[15:1]}) : IN)
    );

// When SHIFT is low, OUT passes IN through unchanged.
    check_no_shift_passthrough: assert property (
        @(posedge clk)
        !SHIFT |-> (OUT == IN)
    );

// When SHIFT and DIR are high, OUT is IN shifted left by one.
    check_left_shift_selected: assert property (
        @(posedge clk)
        SHIFT && DIR |-> (OUT == {IN[14:0], 1'b0})
    );

// Left shift inserts a zero into the least-significant bit.
    check_left_shift_zero_fill: assert property (
        @(posedge clk)
        SHIFT && DIR |-> (OUT[0] == 1'b0)
    );

// When SHIFT is high and DIR is low, OUT is IN shifted right by one.
    check_right_shift_selected: assert property (
        @(posedge clk)
        SHIFT && !DIR |-> (OUT == {1'b0, IN[15:1]})
    );

// Right shift inserts a zero into the most-significant bit.
    check_right_shift_zero_fill: assert property (
        @(posedge clk)
        SHIFT && !DIR |-> (OUT[15] == 1'b0)
    );

// Reset clears q.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 1'b0)
    );

// Enable loads a 1 from d.
    check_enable_loads_one: assert property (
        @(posedge clk) disable iff (rst)
        (ena && (d == 1'b1)) |=> (q == 1'b1)
    );

// Enable loads a 0 from d.
    check_enable_loads_zero: assert property (
        @(posedge clk) disable iff (rst)
        (ena && (d == 1'b0)) |=> (q == 1'b0)
    );

// q holds high when disabled.
    check_hold_one_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        ((!ena) && (q == 1'b1)) |=> (q == 1'b1)
    );

// q holds low when disabled.
    check_hold_zero_when_disabled: assert property (
        @(posedge clk) disable iff (rst)
        ((!ena) && (q == 1'b0)) |=> (q == 1'b0)
    );

// X matches the implemented O2111A logic function.
    check_function_equivalence: assert property (
        @(posedge clk) X == (B1 & C1 & D1 & (A1 | A2))
    );

// A low B1 input forces the output low.
    check_b1_blocks_output: assert property (
        @(posedge clk) !B1 |-> !X
    );

// A low C1 input forces the output low.
    check_c1_blocks_output: assert property (
        @(posedge clk) !C1 |-> !X
    );

// A low D1 input forces the output low.
    check_d1_blocks_output: assert property (
        @(posedge clk) !D1 |-> !X
    );

// Both A inputs low force the output low.
    check_a_inputs_block_output: assert property (
        @(posedge clk) (!A1 & !A2) |-> !X
    );

// With B1, C1, and D1 high, A1 can drive the output high.
    check_a1_path_drives_output: assert property (
        @(posedge clk) (A1 & B1 & C1 & D1) |-> X
    );

// With B1, C1, and D1 high, A2 can drive the output high.
    check_a2_path_drives_output: assert property (
        @(posedge clk) (A2 & B1 & C1 & D1) |-> X
    );

// A high output implies all required product terms are satisfied.
    check_output_implies_inputs: assert property (
        @(posedge clk) X |-> (B1 & C1 & D1 & (A1 | A2))
    );

// Shift amount 0 passes the input through unchanged.
    check_no_shift_passthrough: assert property (
        @(posedge clk) (shift_amt == 2'b00) |-> (data_out == data_in)
    );

// Shift amount 1 shifts left by one and inserts 0 in bit 0.
    check_shift_by_one: assert property (
        @(posedge clk) (shift_amt == 2'b01) |-> (data_out == {data_in[2:0], 1'b0})
    );

// Shift amount 2 shifts left by two and inserts 0s in bits [1:0].
    check_shift_by_two: assert property (
        @(posedge clk) (shift_amt == 2'b10) |-> (data_out == {data_in[1:0], 2'b00})
    );

// Shift amount 3 shifts left by three and inserts 0s in bits [2:0].
    check_shift_by_three: assert property (
        @(posedge clk) (shift_amt == 2'b11) |-> (data_out == {data_in[0], 3'b000})
    );

// Y matches the implemented gate equation.
    check_y_matches_gate_equation: assert property (
        @(posedge clk) Y == ~(~B1_N | (A1 & A2))
    );

// Low B1_N forces Y low.
    check_b1_n_low_forces_y_low: assert property (
        @(posedge clk) !B1_N |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// High B1_N with low A1 makes Y high.
    check_b1_n_high_a1_low_drives_y_high: assert property (
        @(posedge clk) (B1_N && !A1) |-> Y
    );

// High B1_N with low A2 makes Y high.
    check_b1_n_high_a2_low_drives_y_high: assert property (
        @(posedge clk) (B1_N && !A2) |-> Y
    );

// Y high requires B1_N high.
    check_y_high_requires_b1_n_high: assert property (
        @(posedge clk) Y |-> B1_N
    );

// Y high means A1 and A2 are not both high.
    check_y_high_requires_not_a1_a2_high: assert property (
        @(posedge clk) Y |-> !(A1 && A2)
    );

// Low Y with high B1_N requires both A inputs high.
    check_y_low_with_b1_n_high_requires_a1_a2_high: assert property (
        @(posedge clk) (!Y && B1_N) |-> (A1 && A2)
    );

// Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) (!rst) |-> (count == 4'd0)
    );

// When count is below 15, it increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst)
        (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

// When count reaches 15, it wraps to zero on the next clock.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

// Sampled on external clk because the RTL has no clock or reset.

    // ack=1 and ack_syn=0 selects a left shift by one bit.
    check_left_shift: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && ack && !ack_syn
        |-> reg_out == {reg_input[30:0], 1'b0}
    );

// ack=0 and ack_syn=1 selects a right shift by one bit.
    check_right_shift: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && !ack && ack_syn
        |-> reg_out == {1'b0, reg_input[31:1]}
    );

// ack=1 and ack_syn=1 selects the byte-reversed value.
    check_byte_reverse: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && ack && ack_syn
        |-> reg_out == {reg_input[7:0], reg_input[15:8], reg_input[23:16], reg_input[31:24]}
    );

// ack=0 and ack_syn=0 passes reg_input through unchanged.
    check_passthrough: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && !ack && !ack_syn
        |-> reg_out == reg_input
    );

// Reset holds count at zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 8'd0)
    );

// Up-counting below max increments by one.
    check_up_count_increment: assert property (
        @(posedge clk) disable iff (rst)
        (ctrl && (count != max_val)) |=> (count == ($past(count) + 8'd1))
    );

// Up-counting at max wraps to zero.
    check_up_count_wrap_zero: assert property (
        @(posedge clk) disable iff (rst)
        (ctrl && (count == max_val)) |=> (count == 8'd0)
    );

// Down-counting above min decrements by one.
    check_down_count_decrement: assert property (
        @(posedge clk) disable iff (rst)
        ((!ctrl) && (count != min_val)) |=> (count == ($past(count) - 8'd1))
    );

// Down-counting at min reloads max_val.
    check_down_count_wrap_max: assert property (
        @(posedge clk) disable iff (rst)
        ((!ctrl) && (count == min_val)) |=> (count == $past(max_val))
    );

// Reset loads the counter to init.
    check_reset_loads_init: assert property (
        @(posedge CLK) RST |=> (Q_OUT == init)
    );

// SETF has highest non-reset priority and loads DATA_F.
    check_setf_loads_data_f: assert property (
        @(posedge CLK) disable iff (RST)
        SETF |=> (Q_OUT == $past(DATA_F))
    );

// SETC loads DATA_C when SETF is low.
    check_setc_loads_data_c: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && SETC |=> (Q_OUT == $past(DATA_C))
    );

// ADDA adds DATA_A when no higher-priority control is active.
    check_adda_updates_counter: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && !SETC && ADDA |=> (Q_OUT == ($past(Q_OUT) + $past(DATA_A)))
    );

// ADDB adds DATA_B when no higher-priority control is active.
    check_addb_updates_counter: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && !SETC && !ADDA && ADDB |=> (Q_OUT == ($past(Q_OUT) + $past(DATA_B)))
    );

// Without reset or controls, the counter holds its value.
    check_holds_without_controls: assert property (
        @(posedge CLK) disable iff (RST)
        !SETF && !SETC && !ADDA && !ADDB |=> (Q_OUT == $past(Q_OUT))
    );

// Reset forces count to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 2'b00)
    );

// When enabled, count increments by one modulo 4.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 2'b01))
    );

// When not enabled, count holds its previous value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// A max count of 3 wraps back to 0 when enabled.
    check_wraps_from_three_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 2'b11)) |=> (count == 2'b00)
    );

// Reset forces Q low on the following clock sample.
    check_reset_forces_zero: assert property (
        @(posedge CLK) RST |=> (Q == 1'b0)
    );

// A high D is captured into Q on the next clock when not in reset.
    check_capture_one: assert property (
        @(posedge CLK) disable iff (RST) D |=> (Q == 1'b1)
    );

// A low D is captured into Q on the next clock when not in reset.
    check_capture_zero: assert property (
        @(posedge CLK) disable iff (RST) !D |=> (Q == 1'b0)
    );

// External sampling clock for this combinational DUT.

    // Z matches the implemented OR of A and B.
    check_z_is_or_of_inputs: assert property (
        @(posedge clk) Z == (A | B)
    );

// Input 00 drives Z low.
    check_zero_zero_case: assert property (
        @(posedge clk) (!A && !B) |-> !Z
    );

// Input 01 drives Z high.
    check_zero_one_case: assert property (
        @(posedge clk) (!A && B) |-> Z
    );

// Input 10 drives Z high.
    check_one_zero_case: assert property (
        @(posedge clk) (A && !B) |-> Z
    );

// Input 11 drives Z high.
    check_one_one_case: assert property (
        @(posedge clk) (A && B) |-> Z
    );

// Z low can only occur for input 00.
    check_z_low_requires_both_inputs_low: assert property (
        @(posedge clk) !Z |-> (!A && !B)
    );

// Externally, q is the previous rising-edge sample of d.
    check_q_matches_previous_d: assert property (
        @(posedge clk) 1'b1 |=> q === $past(d)
    );

// All-zero input drives 10.
    check_all_zero_outputs: assert property (
        @(posedge clk)
        ({in2, in1, in0} == 3'b000) |-> (out1 == 1'b1 && out0 == 1'b0)
    );

// All-one input drives 10.
    check_all_one_outputs: assert property (
        @(posedge clk)
        ({in2, in1, in0} == 3'b111) |-> (out1 == 1'b1 && out0 == 1'b0)
    );

// Any mixed input pattern drives 01.
    check_mixed_inputs_outputs: assert property (
        @(posedge clk)
        (({in2, in1, in0} != 3'b000) && ({in2, in1, in0} != 3'b111)) |-> (out1 == 1'b0 && out0 == 1'b1)
    );

// out1 can only be high for 000 or 111.
    check_out1_only_for_uniform_inputs: assert property (
        @(posedge clk)
        (out1 == 1'b1) |-> (({in2, in1, in0} == 3'b000) || ({in2, in1, in0} == 3'b111))
    );

// out0 can only be high for non-uniform inputs.
    check_out0_only_for_mixed_inputs: assert property (
        @(posedge clk)
        (out0 == 1'b1) |-> (({in2, in1, in0} != 3'b000) && ({in2, in1, in0} != 3'b111))
    );

// Outputs are always complementary.
    check_outputs_complementary: assert property (
        @(posedge clk)
        (out1 ^ out0)
    );

// Output always equals the bitwise AND of the two inputs.
    check_out_matches_bitwise_and: assert property (
        @(posedge clk) out == (a & b)
    );

// Reset drives disp_num to zero.
    check_reset_clears_disp_num: assert property (
        @(negedge clk)
        rst |=> (disp_num == 32'h0000_0000)
    );

// Test==0 with write low holds the previous value.
    check_hold_when_test0_no_write: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd0 && !GPIOe0000000_we) |=> (disp_num == $past(disp_num))
    );

// Test==0 with write high loads disp_cpudata.
    check_load_cpudata_when_test0_write: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd0 && GPIOe0000000_we) |=> (disp_num == $past(disp_cpudata))
    );

// Test==1 loads Test_data0.
    check_load_test_data0: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd1) |=> (disp_num == $past(Test_data0))
    );

// Test==2 loads Test_data1.
    check_load_test_data1: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd2) |=> (disp_num == $past(Test_data1))
    );

// Test==3 loads Test_data2.
    check_load_test_data2: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd3) |=> (disp_num == $past(Test_data2))
    );

// Test==4 loads Test_data3.
    check_load_test_data3: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd4) |=> (disp_num == $past(Test_data3))
    );

// Test==5 loads Test_data4.
    check_load_test_data4: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd5) |=> (disp_num == $past(Test_data4))
    );

// Test==6 loads Test_data5.
    check_load_test_data5: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd6) |=> (disp_num == $past(Test_data5))
    );

// Test==7 loads Test_data6.
    check_load_test_data6: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd7) |=> (disp_num == $past(Test_data6))
    );

// Y must match the 4-input NAND of A, B, C, and D.
    check_nand_function: assert property (
        @(posedge clk) Y === ~(A & B & C & D)
    );

// All inputs high must drive Y low.
    check_all_inputs_high_drives_low: assert property (
        @(posedge clk)
        (A === 1'b1 && B === 1'b1 && C === 1'b1 && D === 1'b1) |-> (Y === 1'b0)
    );

// A low must force Y high.
    check_a_low_forces_high: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// B low must force Y high.
    check_b_low_forces_high: assert property (
        @(posedge clk) (B === 1'b0) |-> (Y === 1'b1)
    );

// C low must force Y high.
    check_c_low_forces_high: assert property (
        @(posedge clk) (C === 1'b0) |-> (Y === 1'b1)
    );

// D low must force Y high.
    check_d_low_forces_high: assert property (
        @(posedge clk) (D === 1'b0) |-> (Y === 1'b1)
    );

// A low output requires all inputs to be high.
    check_low_output_requires_all_inputs_high: assert property (
        @(posedge clk)
        (Y === 1'b0) |-> (A === 1'b1 && B === 1'b1 && C === 1'b1 && D === 1'b1)
    );

// y matches the reduction AND of a.
            check_and_reduction: assert property (
                @(posedge clk) y == (&a)
            );

// All input bits high drives y high.
            check_and_all_ones_drive_high: assert property (
                @(posedge clk) (&a) |-> y
            );

// Any low input bit forces y low.
            check_and_any_zero_forces_low: assert property (
                @(posedge clk) !(&a) |-> !y
            );

// out1 must always mirror the low byte of in.
    check_splitter_lower_byte: assert property (
        @(posedge clk) out1 == in[7:0]
    );

// out2 must always mirror the high byte of in.
    check_splitter_upper_byte: assert property (
        @(posedge clk) out2 == in[15:8]
    );

// RTL has no clock or reset; assertions are sampled on an external clock.

    // Output must match the RTL equation.
    check_output_equation: assert property (
        @(posedge clk) out == (in1 & ~in2)
    );

// Output high requires in1 high and in2 low.
    check_output_high_inputs: assert property (
        @(posedge clk) out |-> (in1 & ~in2)
    );

// in1 high with in2 low must drive output high.
    check_true_minterm: assert property (
        @(posedge clk) (in1 & ~in2) |-> out
    );

// in2 high must force output low.
    check_in2_blocks_output: assert property (
        @(posedge clk) in2 |-> !out
    );

// in1 low must force output low.
    check_in1_low_forces_output_low: assert property (
        @(posedge clk) !in1 |-> !out
    );

// Any bit set in and_out must also be set in or_out.
    check_and_is_subset_of_or: assert property (
        @(posedge clk) (and_out & ~or_out) == 4'b0000
    );

// xor_out and and_out cannot share a set bit.
    check_xor_and_and_do_not_overlap: assert property (
        @(posedge clk) (xor_out & and_out) == 4'b0000
    );

// xor_out equals or_out with the common set bits removed.
    check_xor_matches_or_minus_and: assert property (
        @(posedge clk) xor_out == (or_out & ~and_out)
    );

// All-one active inputs force AND and OR high and XOR low.
    check_all_one_inputs_force_expected_outputs: assert property (
        @(posedge clk) (in[7:0] == 8'b11111111) |-> ((and_out == 4'b1111) && (or_out == 4'b1111) && (xor_out == 4'b0000))
    );

// When sel is low, the output must match a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (sel === 1'b0) |-> (out === a)
    );

// When sel is high, the output must match b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (sel === 1'b1) |-> (out === b)
    );

// Reset clears shift_reg.
    check_reset_clears_shift_reg: assert property (
        @(posedge clk) reset |=> (shift_reg == 3'b000)
    );

// Reset clears flip_flop.
    check_reset_clears_flip_flop: assert property (
        @(posedge clk) reset |=> (flip_flop == 2'b00)
    );

// Reset clears count.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

// Without enable, count holds its value.
    check_idle_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst_n |-> (count == 4'b0000)
    );

// The first sampled cycle after reset release still sees zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) disable iff (!rst_n) (!$past(rst_n)) |-> (count == 4'b0000)
    );

// The counter wraps from 15 back to zero.
    check_count_rolls_over: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// Full 5-bit output matches the arithmetic sum of the inputs.
    check_full_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0, cin})
    );

// Bit 0 sum is the XOR of a[0], b[0], and cin.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin))
        )
    );

// Bit 2 sum uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (
                    (a[1] ^ b[1]) &
                    (
                        (a[0] & b[0]) |
                        ((a[0] ^ b[0]) & cin)
                    )
                )
            )
        )
    );

// Bit 3 sum uses the ripple carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    (a[2] ^ b[2]) &
                    (
                        (a[1] & b[1]) |
                        (
                            (a[1] ^ b[1]) &
                            (
                                (a[0] & b[0]) |
                                ((a[0] ^ b[0]) & cin)
                            )
                        )
                    )
                )
            )
        )
    );

// Carry out is the final ripple carry from the MSB stage.
    check_carry_out: assert property (
        @(posedge clk) cout == (
            (a[3] & b[3]) |
            (
                (a[3] ^ b[3]) &
                (
                    (a[2] & b[2]) |
                    (
                        (a[2] ^ b[2]) &
                        (
                            (a[1] & b[1]) |
                            (
                                (a[1] ^ b[1]) &
                                (
                                    (a[0] & b[0]) |
                                    ((a[0] ^ b[0]) & cin)
                                )
                            )
                        )
                    )
                )
            )
        )
    );

// Top strip uses the wall color.
    check_top_strip_wall: assert property (
        @(posedge clk_vga)
        (CurrentY < 9'd40) |=> (mapData == $past(wall))
    );

// Right side uses the wall color.
    check_right_side_wall: assert property (
        @(posedge clk_vga)
        (CurrentX >= 10'd600) |=> (mapData == $past(wall))
    );

// Bottom-left region uses the wall color.
    check_bottom_left_wall: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd440 && CurrentX < 10'd260) |=> (mapData == $past(wall))
    );

// Bottom-right region uses the wall color.
    check_bottom_right_wall: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd440 && CurrentX >= 10'd380) |=> (mapData == $past(wall))
    );

// Upper interior region uses the default color.
    check_upper_interior_default: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd40 && CurrentY < 9'd440 && CurrentX < 10'd600) |=> (mapData == 8'b10110110)
    );

// Lower center opening uses the default color.
    check_lower_center_default: assert property (
        @(posedge clk_vga)
        (CurrentY >= 9'd440 && CurrentX >= 10'd260 && CurrentX < 10'd380) |=> (mapData == 8'b10110110)
    );

// Reset sets id_pcplus4 to 4.
    check_reset_pcplus4: assert property (
        @(posedge clk) rst |-> (id_pcplus4 == 32'd4)
    );

// Reset sets id_instr to the defined bubble value.
    check_reset_instr: assert property (
        @(posedge clk) rst |-> (id_instr == 32'h0000_0020)
    );

// Stall or BJ causes pcplus4 capture and bubble insertion.
    check_stall_or_bj_behavior: assert property (
        @(posedge clk) disable iff (rst)
        (stall || BJ) |=> ((id_pcplus4 == $past(if_pcplus4)) &&
                           (id_instr   == 32'h0000_0020))
    );

// Without stall or BJ, both outputs capture the input values.
    check_normal_capture: assert property (
        @(posedge clk) disable iff (rst)
        !(stall || BJ) |=> ((id_pcplus4 == $past(if_pcplus4)) &&
                            (id_instr   == $past(if_instr)))
    );

// Clock: clk; reset: reset_n active low; mixed sequential/combinational logic.

    // Reset forces the registered output low.
    reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 2'b00)
    );

// Reset forces the readback value low.
    reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

// Read data is always zero-extended in the upper 30 bits.
    read_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:2] == 30'b0)
    );

// Address 0 returns the current output register value.
    read_addr_zero_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {30'b0, out_port})
    );

// Nonzero addresses return zero.
    read_nonzero_addr_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

// A write to address 0 updates the output register with writedata[1:0].
    write_addr_zero_captures_low_bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[1:0]))
    );

// When not selected, the output register holds its value.
    unselected_cycle_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!chipselect) |=> (out_port == $past(out_port))
    );

// Read cycles do not modify the output register.
    read_cycle_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && write_n) |=> (out_port == $past(out_port))
    );

// Writes to nonzero addresses do not modify the output register.
    write_nonzero_addr_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

// por is the inverse of por_l.
    check_por_inversion: assert property (
        @(posedge clk) disable iff (1'b0) (por == ~por_l)
    );

// pad_up is asserted only when data and oe are both high.
    check_pad_up_function: assert property (
        @(posedge clk) disable iff (1'b0) (pad_up == (data && oe))
    );

// pad_dn_l follows the implemented active-low drive equation.
    check_pad_dn_l_function: assert property (
        @(posedge clk) disable iff (1'b0) (pad_dn_l == ~(~data && oe))
    );

// bsr_up mirrors pad_up.
    check_bsr_up_mirror: assert property (
        @(posedge clk) disable iff (1'b0) (bsr_up == pad_up)
    );

// bsr_dn_l mirrors pad_dn_l.
    check_bsr_dn_l_mirror: assert property (
        @(posedge clk) disable iff (1'b0) (bsr_dn_l == pad_dn_l)
    );

// to_core follows the mux implemented in the RTL.
    check_to_core_mux_function: assert property (
        @(posedge clk) disable iff (1'b0)
        (to_core == ((bsr_mode && !se) ? bsr_data_to_core : rcvr_data))
    );

// In boundary-scan mode with se low, to_core selects bsr_data_to_core.
    check_to_core_bsr_path: assert property (
        @(posedge clk) disable iff (1'b0)
        (bsr_mode && !se) |-> (to_core == bsr_data_to_core)
    );

// Otherwise, to_core selects rcvr_data.
    check_to_core_rcvr_path: assert property (
        @(posedge clk) disable iff (1'b0)
        (!bsr_mode || se) |-> (to_core == rcvr_data)
    );

// With output enable low, the pad outputs remain in their inactive state.
    check_outputs_when_oe_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!oe) |-> (!pad_up && pad_dn_l)
    );

// With output enable high, both pad outputs track data as implemented.
    check_outputs_when_oe_high: assert property (
        @(posedge clk) disable iff (1'b0)
        oe |-> ((pad_up == data) && (pad_dn_l == data))
    );

// Gray MSB matches binary MSB.
    check_gray_bit3_passthrough: assert property (
        @(posedge clk) gray_out[3] === bin_in[3]
    );

// Gray bit 2 is bin_in[3] XOR bin_in[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray_out[2] === (bin_in[3] ^ bin_in[2])
    );

// Gray bit 1 is bin_in[2] XOR bin_in[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_out[1] === (bin_in[2] ^ bin_in[1])
    );

// Gray bit 0 is bin_in[1] XOR bin_in[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray_out[0] === (bin_in[1] ^ bin_in[0])
    );

// Synchronous reset clears both registered outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        rst |=> (out_round == 16'sd0 && out_sat == 16'sd0)
    );

// Odd input values are rounded up by one.
    check_round_odd_adds_one: assert property (
        @(posedge clk) disable iff (rst)
        in_val[0] |=> (out_round == ($past(in_val) + 16'sd1))
    );

// Even input values pass through the round block unchanged.
    check_round_even_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        !in_val[0] |=> (out_round == $past(in_val))
    );

// Inputs below the minimum clamp to min_val.
    check_sat_low_clamps_to_min: assert property (
        @(posedge clk) disable iff (rst)
        (in_val < min_val) |=> (out_sat == $past(min_val))
    );

// Inputs above the maximum clamp to max_val when not already below min_val.
    check_sat_high_clamps_to_max: assert property (
        @(posedge clk) disable iff (rst)
        (!(in_val < min_val) && (in_val > max_val)) |=> (out_sat == $past(max_val))
    );

// Inputs within the range pass through the saturation block unchanged.
    check_sat_in_range_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        (!(in_val < min_val) && !(in_val > max_val)) |=> (out_sat == $past(in_val))
    );

// temp_reg reflects i_reg_example sampled on the previous rst edge.
    check_temp_reg_captures_previous_input_on_rst: assert property (
        @(posedge rst) disable iff (1'b0)
        1'b1 |=> (temp_reg == $past(i_reg_example))
    );

// If input is unchanged across rst samples, temp_reg matches current input.
    check_temp_matches_current_input_when_input_stable: assert property (
        @(posedge rst) disable iff (1'b0)
        1'b1 |=> ((i_reg_example == $past(i_reg_example)) |-> (temp_reg == i_reg_example))
    );

// If input changes between rst samples, temp_reg still lags current input.
    check_temp_lags_current_input_when_input_changes: assert property (
        @(posedge rst) disable iff (1'b0)
        1'b1 |=> ((i_reg_example != $past(i_reg_example)) |-> (temp_reg != i_reg_example))
    );

// Q reflects D from the previous rising clock edge.
    check_q_captures_previous_d: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(d))
    );

// If D matches Q at a clock edge, Q holds its value on the next edge.
    check_q_holds_when_d_matches_q: assert property (
        @(posedge clk) (d == q) |=> (q == $past(q))
    );

// If D differs from Q at a clock edge, Q changes on the next edge.
    check_q_changes_when_d_differs: assert property (
        @(posedge clk) (d != q) |=> (q != $past(q))
    );

// out must always equal the input selected by sel.
    check_selected_input_drives_out: assert property (
        @(posedge clk)
        out == ((sel == 2'b00) ? in0 :
                (sel == 2'b01) ? in1 :
                (sel == 2'b10) ? in2 : in3)
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == in3)
    );

// b1x is the XOR of bits [5:0].
    check_b1x_slice: assert property (
        @(posedge clk) b1x == (e[5:0] ^ k[5:0])
    );

// b2x is the XOR of bits [11:6].
    check_b2x_slice: assert property (
        @(posedge clk) b2x == (e[11:6] ^ k[11:6])
    );

// b3x is the XOR of bits [17:12].
    check_b3x_slice: assert property (
        @(posedge clk) b3x == (e[17:12] ^ k[17:12])
    );

// b4x is the XOR of bits [23:18].
    check_b4x_slice: assert property (
        @(posedge clk) b4x == (e[23:18] ^ k[23:18])
    );

// b5x is the XOR of bits [29:24].
    check_b5x_slice: assert property (
        @(posedge clk) b5x == (e[29:24] ^ k[29:24])
    );

// b6x is the XOR of bits [35:30].
    check_b6x_slice: assert property (
        @(posedge clk) b6x == (e[35:30] ^ k[35:30])
    );

// b7x is the XOR of bits [41:36].
    check_b7x_slice: assert property (
        @(posedge clk) b7x == (e[41:36] ^ k[41:36])
    );

// b8x is the XOR of bits [47:42].
    check_b8x_slice: assert property (
        @(posedge clk) b8x == (e[47:42] ^ k[47:42])
    );

// The eight outputs reconstruct the full XOR result.
    check_outputs_reconstruct_xor: assert property (
        @(posedge clk) {b8x, b7x, b6x, b5x, b4x, b3x, b2x, b1x} == (e ^ k)
    );

// Equal inputs produce an all-zero output vector.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (e == k) |-> ({b8x, b7x, b6x, b5x, b4x, b3x, b2x, b1x} == 48'h0)
    );

// Output matches the implemented AND function.
    check_output_matches_and_function: assert property (
        @(posedge clk) Y == (A & B)
    );

// Both inputs low drive the output low.
    check_inputs_00_drive_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (Y == 1'b0)
    );

// A low and B high drive the output low.
    check_inputs_01_drive_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b1)) |-> (Y == 1'b0)
    );

// A high and B low drive the output low.
    check_inputs_10_drive_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b0)) |-> (Y == 1'b0)
    );

// Both inputs high drive the output high.
    check_inputs_11_drive_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (Y == 1'b1)
    );

// A high output requires both inputs high.
    check_output_high_requires_both_inputs_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A == 1'b1) && (B == 1'b1))
    );

// No reset in the RTL; sample the combinational function on clk.

    // The AOI network implements XOR of A and B.
    check_output_matches_xor: assert property (
        @(posedge clk) Z == (A ^ B)
    );

// Equal inputs must drive the output low.
    check_output_low_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (Z == 1'b0)
    );

// Different inputs must drive the output high.
    check_output_high_when_inputs_differ: assert property (
        @(posedge clk) (A != B) |-> (Z == 1'b1)
    );

// sel=00 routes in0 to out.
    check_select_in0: assert property (
        @(posedge clk)
        ((sel1 == 1'b0) && (sel0 == 1'b0)) |-> (out === in0)
    );

// sel=01 routes in1 to out.
    check_select_in1: assert property (
        @(posedge clk)
        ((sel1 == 1'b0) && (sel0 == 1'b1)) |-> (out === in1)
    );

// sel=10 routes in2 to out.
    check_select_in2: assert property (
        @(posedge clk)
        ((sel1 == 1'b1) && (sel0 == 1'b0)) |-> (out === in2)
    );

// sel=11 routes in3 to out.
    check_select_in3: assert property (
        @(posedge clk)
        ((sel1 == 1'b1) && (sel0 == 1'b1)) |-> (out === in3)
    );

// EQ matches the all-inputs-equal comparison.
    check_eq_definition: assert property (
        @(posedge clk) EQ == ((A == B) && (B == C) && (C == D))
    );

// GT matches the comparator decision logic.
    check_gt_definition: assert property (
        @(posedge clk) GT == ((A > B) || ((A == B) && (C > D)))
    );

// Equal inputs force GT low.
    check_eq_implies_not_gt: assert property (
        @(posedge clk) EQ |-> !GT
    );

// A greater than B forces GT high.
    check_a_greater_b_sets_gt: assert property (
        @(posedge clk) (A > B) |-> GT
    );

// A less than B forces GT low.
    check_a_less_b_clears_gt: assert property (
        @(posedge clk) (A < B) |-> !GT
    );

// With A tied to B, C greater than D forces GT high.
    check_tie_breaker_sets_gt: assert property (
        @(posedge clk) ((A == B) && (C > D)) |-> GT
    );

// With A tied to B, C not greater than D forces GT low.
    check_tie_breaker_clears_gt: assert property (
        @(posedge clk) ((A == B) && (C <= D)) |-> !GT
    );

// When A equals B, GT can only come from C greater than D.
    check_gt_with_equal_ab_requires_c_greater_d: assert property (
        @(posedge clk) (GT && (A == B)) |-> (C > D)
    );

// When A differs from B, GT can only come from A greater than B.
    check_gt_with_unequal_ab_requires_a_greater_b: assert property (
        @(posedge clk) (GT && (A != B)) |-> (A > B)
    );

// X equals (~B1_N) & (A1 | A2).
    check_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0) X == ((A1 | A2) & ~B1_N)
    );

// B1_N high blocks the output.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk) disable iff (1'b0) B1_N |-> (X == 1'b0)
    );

// With both A inputs low, X stays low.
    check_no_a_inputs_force_x_low: assert property (
        @(posedge clk) disable iff (1'b0) (!A1 && !A2) |-> (X == 1'b0)
    );

// A1 high passes through when B1_N is low.
    check_a1_high_with_b1n_low_drives_x_high: assert property (
        @(posedge clk) disable iff (1'b0) (!B1_N && A1) |-> (X == 1'b1)
    );

// A2 high passes through when B1_N is low.
    check_a2_high_with_b1n_low_drives_x_high: assert property (
        @(posedge clk) disable iff (1'b0) (!B1_N && A2) |-> (X == 1'b1)
    );

// X high requires B1_N low and at least one A input high.
    check_x_high_requires_enable_and_a_input: assert property (
        @(posedge clk) disable iff (1'b0) X |-> (!B1_N && (A1 || A2))
    );

// Active-low reset clears the synchronized pointer.
    check_reset_clears_dest_ptr: assert property (
        @(posedge dest_clk)
        !dest_rst_n |-> (dest_ptr == '0)
    );

// When enabled, Z is A in the upper byte and zero in the lower byte.
    check_enabled_mapping: assert property (
        @(posedge clk) TE_B |-> (Z == {A, 8'h00})
    );

// When disabled, Z is driven to zero.
    check_disabled_zero: assert property (
        @(posedge clk) !TE_B |-> (Z == 16'h0000)
    );

// The upper byte of Z matches A whenever the buffer is enabled.
    check_enabled_upper_byte_matches_a: assert property (
        @(posedge clk) TE_B |-> (Z[15:8] == A)
    );

// The lower byte of Z is always zero.
    check_lower_byte_always_zero: assert property (
        @(posedge clk) Z[7:0] == 8'h00
    );

// A rising enable produces the enabled output mapping.
    check_enable_rise_sets_output: assert property (
        @(posedge clk) $rose(TE_B) |-> (Z == {A, 8'h00})
    );

// A falling enable clears the output.
    check_enable_fall_clears_output: assert property (
        @(posedge clk) $fell(TE_B) |-> (Z == 16'h0000)
    );

// X must always match the mux select function.
    check_mux_function: assert property (
        @(posedge clk) X === (SEL ? B : A)
    );

// When SEL is low, X must route A.
    check_sel_low_routes_a: assert property (
        @(posedge clk) (SEL == 1'b0) |-> (X === A)
    );

// When SEL is high, X must route B.
    check_sel_high_routes_b: assert property (
        @(posedge clk) (SEL == 1'b1) |-> (X === B)
    );

// If both inputs are equal, X must equal that common value.
    check_equal_inputs_same_output: assert property (
        @(posedge clk) (A === B) |-> (X === A)
    );

// Full 5-bit result matches A + B + CIN.
    check_total_addition: assert property (
        @(posedge clk)
        {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {4'b0, CIN})
    );

// LSB sum matches the first full-adder XOR equation.
    check_lsb_xor: assert property (
        @(posedge clk)
        SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

// Carry-out matches arithmetic overflow.
    check_cout_overflow: assert property (
        @(posedge clk)
        COUT == (({1'b0, A} + {1'b0, B} + {4'b0, CIN}) >= 5'd16)
    );

// Adding zero with no carry-in preserves A.
    check_add_zero_to_a: assert property (
        @(posedge clk)
        (B == 4'h0 && CIN == 1'b0) |-> (SUM == A && COUT == 1'b0)
    );

// Adding zero with no carry-in preserves B.
    check_add_zero_to_b: assert property (
        @(posedge clk)
        (A == 4'h0 && CIN == 1'b0) |-> (SUM == B && COUT == 1'b0)
    );

// With zero operands, only CIN contributes to the result.
    check_zero_operands_with_cin: assert property (
        @(posedge clk)
        (A == 4'h0 && B == 4'h0) |-> (SUM == {3'b000, CIN} && COUT == 1'b0)
    );

// A carry-in can ripple through all four stages.
    check_full_carry_propagation: assert property (
        @(posedge clk)
        (A == 4'hF && B == 4'h0 && CIN == 1'b1) |-> (SUM == 4'h0 && COUT == 1'b1)
    );

// No RTL clock/reset; sample the combinational outputs on an external clock.

    // out_l must match the RTL left-shift expression.
    check_left_shift_value: assert property (
        @(posedge clk) out_l == (in << shift)
    );

// out_r must match the RTL right-shift expression.
    check_right_shift_value: assert property (
        @(posedge clk) out_r == (in >> shift)
    );

// out_a must match the RTL conditional expression exactly.
    check_conditional_a_value: assert property (
        @(posedge clk) out_a == ((in[31] == 1'b0) ? (in >> shift) : (({32{in[31]}} >> shift) | (in >> shift)))
    );

// With MSB clear, out_a must equal the logical right shift.
    check_a_matches_right_shift_when_msb_zero: assert property (
        @(posedge clk) (in[31] == 1'b0) |-> (out_a == out_r)
    );

// With MSB set, out_a must follow the RTL mask-and-OR branch.
    check_a_mask_branch_when_msb_one: assert property (
        @(posedge clk) (in[31] == 1'b1) |-> (out_a == ((32'hFFFF_FFFF >> shift) | out_r))
    );

// A zero shift must pass in through to out_l and out_r.
    check_zero_shift_passthrough_lr: assert property (
        @(posedge clk) (shift == 5'd0) |-> ((out_l == in) && (out_r == in))
    );

// A zero shift with MSB clear must pass in through to out_a.
    check_zero_shift_passthrough_a_when_msb_zero: assert property (
        @(posedge clk) ((shift == 5'd0) && (in[31] == 1'b0)) |-> (out_a == in)
    );

// A zero shift with MSB set must drive out_a to all ones per the RTL.
    check_zero_shift_a_all_ones_when_msb_one: assert property (
        @(posedge clk) ((shift == 5'd0) && (in[31] == 1'b1)) |-> (out_a == 32'hFFFF_FFFF)
    );

// A shift of 31 must leave only the original MSB in out_r bit 0.
    check_max_shift_right_shape: assert property (
        @(posedge clk) (shift == 5'd31) |-> (out_r == {31'b0, in[31]})
    );

// A shift of 31 must leave only the original LSB in out_l bit 31.
    check_max_shift_left_shape: assert property (
        @(posedge clk) (shift == 5'd31) |-> (out_l == {in[0], 31'b0})
    );

// Terminal count resets cnt_100M and raises Core.
    check_core_pulse_on_terminal_count: assert property (
        @(posedge slowest_sync_clk)
        (cnt_100M == 32'd100_000_000) |=> (cnt_100M == 32'd0 && Core == 1'b1)
    );

// Non-terminal count increments cnt_100M and keeps Core low.
    check_core_low_on_nonterminal_count: assert property (
        @(posedge slowest_sync_clk)
        (cnt_100M != 32'd100_000_000) |=> (cnt_100M == ($past(cnt_100M) + 32'd1) && Core == 1'b0)
    );

// cnt_core increments when Core is sampled high.
    check_cnt_core_increments_when_core_high: assert property (
        @(posedge lpf_int)
        (Core == 1'b1) |=> (cnt_core == ($past(cnt_core) + 8'd1))
    );

// cnt_core holds when Core is sampled low.
    check_cnt_core_holds_when_core_low: assert property (
        @(posedge lpf_int)
        (Core == 1'b0) |=> (cnt_core == $past(cnt_core))
    );

// bsr is driven low after each lpf_int edge.
    check_bsr_clears_each_lpf_tick: assert property (
        @(posedge lpf_int)
        1'b1 |=> (bsr == 1'b0)
    );

// cnt_bsr increments when bsr is sampled high.
    check_cnt_bsr_increments_when_bsr_high: assert property (
        @(posedge lpf_int)
        (bsr == 1'b1) |=> (cnt_bsr == ($past(cnt_bsr) + 6'd1) && pr == 1'b0)
    );

// cnt_bsr holds when bsr is sampled low.
    check_cnt_bsr_holds_when_bsr_low: assert property (
        @(posedge lpf_int)
        (bsr == 1'b0) |=> (cnt_bsr == $past(cnt_bsr))
    );

// pr is driven low after each lpf_int edge.
    check_pr_clears_each_lpf_tick: assert property (
        @(posedge lpf_int)
        1'b1 |=> (pr == 1'b0)
    );

// Synchronous reset clears the counter on the next cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

// Reset takes priority over enable.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count == 3'b000)
    );

// When enabled, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 3'd1))
    );

// When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Incrementing from the maximum value wraps to zero.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 3'b111)) |=> (count == 3'b000)
    );

// G[0] directly matches A[0].
    check_gray_bit0: assert property (
        @(posedge clk) G[0] == A[0]
    );

// G[1] is the XOR of A[0] and A[1].
    check_gray_bit1: assert property (
        @(posedge clk) G[1] == (A[0] ^ A[1])
    );

// G[2] is the XOR of A[1] and A[2].
    check_gray_bit2: assert property (
        @(posedge clk) G[2] == (A[1] ^ A[2])
    );

// G[3] is the XOR of A[2] and A[3].
    check_gray_bit3: assert property (
        @(posedge clk) G[3] == (A[2] ^ A[3])
    );

// The full Gray output matches the defined bit mapping.
    check_gray_vector: assert property (
        @(posedge clk) G == {(A[2] ^ A[3]), (A[1] ^ A[2]), (A[0] ^ A[1]), A[0]}
    );

// External sampling clock; the RTL has no clock or reset.

    // v4642b6 is the OR of the two inputs.
    check_or_function: assert property (
        @(posedge clk) v4642b6 === (v27dec4 | v82de4f)
    );

// OR low implies both inputs are low.
    check_or_low_means_inputs_low: assert property (
        @(posedge clk)
        (v4642b6 === 1'b0)
        |-> ((v27dec4 === 1'b0) && (v82de4f === 1'b0))
    );

// lookup 0 returns UNDEF.
    check_lookup_0_maps_undef: assert property (
        @(posedge clk) (lookup == 4'd0) |-> (duration == UNDEF)
    );

// lookup 1 returns SEMIQUAVER.
    check_lookup_1_maps_semiquaver: assert property (
        @(posedge clk) (lookup == 4'd1) |-> (duration == SEMIQUAVER)
    );

// lookup 2 returns TUPLET.
    check_lookup_2_maps_tuplet: assert property (
        @(posedge clk) (lookup == 4'd2) |-> (duration == TUPLET)
    );

// lookup 3 returns QUAVER.
    check_lookup_3_maps_quaver: assert property (
        @(posedge clk) (lookup == 4'd3) |-> (duration == QUAVER)
    );

// lookup 4 returns DOTTED_QUAVER.
    check_lookup_4_maps_dotted_quaver: assert property (
        @(posedge clk) (lookup == 4'd4) |-> (duration == DOTTED_QUAVER)
    );

// lookup 5 returns CROTCHET.
    check_lookup_5_maps_crotchet: assert property (
        @(posedge clk) (lookup == 4'd5) |-> (duration == CROTCHET)
    );

// lookup 6 returns DOTTED_CROTCHET.
    check_lookup_6_maps_dotted_crotchet: assert property (
        @(posedge clk) (lookup == 4'd6) |-> (duration == DOTTED_CROTCHET)
    );

// lookup 7 returns MINIM.
    check_lookup_7_maps_minim: assert property (
        @(posedge clk) (lookup == 4'd7) |-> (duration == MINIM)
    );

// lookup 8 returns DOTTED_MINIM.
    check_lookup_8_maps_dotted_minim: assert property (
        @(posedge clk) (lookup == 4'd8) |-> (duration == DOTTED_MINIM)
    );

// lookup 9 returns SEMIBREVE.
    check_lookup_9_maps_semibreve: assert property (
        @(posedge clk) (lookup == 4'd9) |-> (duration == SEMIBREVE)
    );

// lookup 10 returns BREVE.
    check_lookup_10_maps_breve: assert property (
        @(posedge clk) (lookup == 4'd10) |-> (duration == BREVE)
    );

// lookup 11 through 15 return UNDEF.
    check_lookup_11_to_15_maps_undef: assert property (
        @(posedge clk) (lookup >= 4'd11) |-> (duration == UNDEF)
    );

// When SUB is 0, Y must equal the 4-bit sum of A and B.
    check_addition_mode_result: assert property (
        @(posedge clk) (SUB === 1'b0) |-> (Y === (A + B))
    );

// When SUB is not 0, the else branch must drive Y with A - B.
    check_subtraction_mode_result: assert property (
        @(posedge clk) (SUB !== 1'b0) |-> (Y === (A - B))
    );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
