            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// O matches the slice of A selected by S.
            check_selected_slice: assert property (
                @(posedge clk) (S == SEL_VALUE) |-> (O == A[SEL_LSB +: C_DATA_WIDTH])
            );

// BSout must match the implemented S-box lookup on every sampled cycle.
    check_lookup_exact: assert property (
        @(posedge clk) BSout == expected_bsout(offset)
    );

// Offsets 00xxxx must map to the first table row.
    check_row_00: assert property (
        @(posedge clk) (offset[6:5] == 2'b00) |-> (BSout == expected_bsout(offset))
    );

// Offsets 01xxxx must map to the second table row.
    check_row_01: assert property (
        @(posedge clk) (offset[6:5] == 2'b01) |-> (BSout == expected_bsout(offset))
    );

// Offsets 10xxxx must map to the third table row.
    check_row_10: assert property (
        @(posedge clk) (offset[6:5] == 2'b10) |-> (BSout == expected_bsout(offset))
    );

// Offsets 11xxxx must map to the fourth table row.
    check_row_11: assert property (
        @(posedge clk) (offset[6:5] == 2'b11) |-> (BSout == expected_bsout(offset))
    );

// While reset is asserted, disp_num stays at the reset constant.
    check_reset_value: assert property (
        @(negedge clk) disable iff (!rst)
        1'b1 |-> (disp_num == 32'hAA5555AA)
    );

// In Test 0 with write enable, disp_num loads disp_cpudata on the next clock.
    check_test0_cpu_write_load: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd0 && GPIOfffffe00_we) |=> (disp_num == $past(disp_cpudata))
    );

// In Test 0 without write enable, disp_num holds its previous value.
    check_test0_hold_without_write: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd0 && !GPIOfffffe00_we) |=> (disp_num == $past(disp_num))
    );

// In Test 1, disp_num loads Test_data0 on the next clock.
    check_test1_selects_data0: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd1) |=> (disp_num == $past(Test_data0))
    );

// In Test 2, disp_num loads Test_data1 on the next clock.
    check_test2_selects_data1: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd2) |=> (disp_num == $past(Test_data1))
    );

// In Test 3, disp_num loads Test_data2 on the next clock.
    check_test3_selects_data2: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd3) |=> (disp_num == $past(Test_data2))
    );

// In Test 4, disp_num loads Test_data3 on the next clock.
    check_test4_selects_data3: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd4) |=> (disp_num == $past(Test_data3))
    );

// In Test 5, disp_num loads Test_data4 on the next clock.
    check_test5_selects_data4: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd5) |=> (disp_num == $past(Test_data4))
    );

// In Test 6, disp_num loads Test_data5 on the next clock.
    check_test6_selects_data5: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd6) |=> (disp_num == $past(Test_data5))
    );

// In Test 7, disp_num loads Test_data6 on the next clock.
    check_test7_selects_data6: assert property (
        @(negedge clk) disable iff (rst)
        (Test == 3'd7) |=> (disp_num == $past(Test_data6))
    );

// X is the reduction OR of all bits from A, B, C, and D.
    check_output_matches_reduction_or: assert property (
        @(posedge clk) X == (|{A, B, C, D})
    );

// All-zero data inputs force X low.
    check_zero_inputs_produce_zero: assert property (
        @(posedge clk) ({A, B, C, D} == 16'h0000) |-> (X == 1'b0)
    );

// X low implies all data input bits are low.
    check_output_low_implies_all_inputs_low: assert property (
        @(posedge clk) (X == 1'b0) |-> ({A, B, C, D} == 16'h0000)
    );

// X high implies at least one data input bit is high.
    check_output_high_implies_some_input_high: assert property (
        @(posedge clk) (X == 1'b1) |-> (|{A, B, C, D})
    );

// Any asserted bit in A forces X high.
    check_a_nonzero_sets_output: assert property (
        @(posedge clk) (|A) |-> (X == 1'b1)
    );

// Any asserted bit in B forces X high.
    check_b_nonzero_sets_output: assert property (
        @(posedge clk) (|B) |-> (X == 1'b1)
    );

// Any asserted bit in C forces X high.
    check_c_nonzero_sets_output: assert property (
        @(posedge clk) (|C) |-> (X == 1'b1)
    );

// Any asserted bit in D forces X high.
    check_d_nonzero_sets_output: assert property (
        @(posedge clk) (|D) |-> (X == 1'b1)
    );

// Y must match the 4-input NAND function.
    check_nand_equation: assert property (
        @(posedge clk) (Y === ~(A & B & C & D))
    );

// All inputs high drives Y low.
    check_all_high_drives_low: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1) && (C === 1'b1) && (D === 1'b1)) |-> (Y === 1'b0)
    );

// A low forces Y high.
    check_a_low_forces_high: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// B low forces Y high.
    check_b_low_forces_high: assert property (
        @(posedge clk) (B === 1'b0) |-> (Y === 1'b1)
    );

// C low forces Y high.
    check_c_low_forces_high: assert property (
        @(posedge clk) (C === 1'b0) |-> (Y === 1'b1)
    );

// D low forces Y high.
    check_d_low_forces_high: assert property (
        @(posedge clk) (D === 1'b0) |-> (Y === 1'b1)
    );

// a_prim must match the quarterround a result.
    check_a_prim_matches_quarterround: assert property (
        @(posedge clk) a_prim == a1_fn(a, b, c, d)
    );

// b_prim must match the quarterround b result.
    check_b_prim_matches_quarterround: assert property (
        @(posedge clk) b_prim == b3_fn(a, b, c, d)
    );

// c_prim must match the quarterround c result.
    check_c_prim_matches_quarterround: assert property (
        @(posedge clk) c_prim == c1_fn(a, b, c, d)
    );

// d_prim must match the quarterround d result.
    check_d_prim_matches_quarterround: assert property (
        @(posedge clk) d_prim == d3_fn(a, b, c, d)
    );

// a_prim must be the first sum plus the rotated b path.
    check_a_prim_uses_first_sum_and_b1: assert property (
        @(posedge clk) a_prim == ((a + b) + b1_fn(a, b, c, d))
    );

// d_prim must be the rotated xor of d1 and a_prim.
    check_d_prim_uses_d1_and_a_prim: assert property (
        @(posedge clk) d_prim == rotl8(d1_fn(a, b, d) ^ a_prim)
    );

// c_prim must be c0 plus d_prim.
    check_c_prim_uses_c0_and_d_prim: assert property (
        @(posedge clk) c_prim == (c0_fn(a, b, c, d) + d_prim)
    );

// b_prim must be the rotated xor of b1 and c_prim.
    check_b_prim_uses_b1_and_c_prim: assert property (
        @(posedge clk) b_prim == rotl7(b1_fn(a, b, c, d) ^ c_prim)
    );

// All-zero inputs must produce all-zero outputs.
    check_zero_inputs_produce_zero_outputs: assert property (
        @(posedge clk)
        ({a, b, c, d} == 128'h0) |-> ({a_prim, b_prim, c_prim, d_prim} == 128'h0)
    );

// Y equals the implemented A & B & SEL logic.
    check_y_function: assert property (
        @(posedge clk) Y == (A & B & SEL)
    );

// SEL low forces Y low.
    check_sel_low_forces_y_low: assert property (
        @(posedge clk) !SEL |-> !Y
    );

// With SEL high, Y matches A & B.
    check_sel_high_y_matches_a_and_b: assert property (
        @(posedge clk) SEL |-> (Y == (A & B))
    );

// A low forces Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// All inputs high drive Y high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A & B & SEL) |-> Y
    );

// Output matches the implemented combinational function.
    check_out_matches_function: assert property (
        @(posedge clk) out == ((a | b) & ~c)
    );

// A high c forces the output low.
    check_c_high_forces_out_low: assert property (
        @(posedge clk) c |-> !out
    );

// With c low, the output behaves as a OR b.
    check_c_low_reduces_to_a_or_b: assert property (
        @(posedge clk) !c |-> (out == (a | b))
    );

// With c low and a high, the output is high.
    check_c_low_a_high_sets_out: assert property (
        @(posedge clk) (!c && a) |-> out
    );

// With c low and b high, the output is high.
    check_c_low_b_high_sets_out: assert property (
        @(posedge clk) (!c && b) |-> out
    );

// With both a and b low, the output is low.
    check_a_b_low_clear_out: assert property (
        @(posedge clk) (!a && !b) |-> !out
    );

// A high output requires c to be low.
    check_out_high_requires_c_low: assert property (
        @(posedge clk) out |-> !c
    );

// A high output requires at least one of a or b to be high.
    check_out_high_requires_a_or_b: assert property (
        @(posedge clk) out |-> (a | b)
    );

// When enabled, Y matches the implemented logic cone.
    check_enabled_output_matches_implemented_logic: assert property (
        @(posedge clk) (EN === 1'b0) |-> (Y === (D3 & SEL[0] & SEL[1]))
    );

// With EN low and SEL[1] low, the final stage forces Y low.
    check_sel1_low_forces_zero_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL[1] === 1'b0) |-> (Y === 1'b0)
    );

// With EN low and SEL equal 2'b10, Y remains low.
    check_sel_10_forces_zero_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL === 2'b10) |-> (Y === 1'b0)
    );

// With EN low and SEL equal 2'b11, Y follows D3.
    check_sel_11_passes_d3_when_enabled: assert property (
        @(posedge clk) (EN === 1'b0 && SEL === 2'b11) |-> (Y === D3)
    );

// Bit 7 has highest priority.
    check_pos_from_bit7: assert property (
        @(posedge sel) in[7] |-> (pos == 3'd7)
    );

// Bit 6 is selected when bit 7 is clear.
    check_pos_from_bit6: assert property (
        @(posedge sel) ((!in[7]) && in[6]) |-> (pos == 3'd6)
    );

// Bit 5 is selected when bits 7:6 are clear.
    check_pos_from_bit5: assert property (
        @(posedge sel) ((in[7:6] == 2'b00) && in[5]) |-> (pos == 3'd5)
    );

// Bit 4 is selected when bits 7:5 are clear.
    check_pos_from_bit4: assert property (
        @(posedge sel) ((in[7:5] == 3'b000) && in[4]) |-> (pos == 3'd4)
    );

// Bit 3 is selected when bits 7:4 are clear.
    check_pos_from_bit3: assert property (
        @(posedge sel) ((in[7:4] == 4'b0000) && in[3]) |-> (pos == 3'd3)
    );

// Bit 2 is selected when bits 7:3 are clear.
    check_pos_from_bit2: assert property (
        @(posedge sel) ((in[7:3] == 5'b00000) && in[2]) |-> (pos == 3'd2)
    );

// Bit 1 is selected when bits 7:2 are clear.
    check_pos_from_bit1: assert property (
        @(posedge sel) ((in[7:2] == 6'b000000) && in[1]) |-> (pos == 3'd1)
    );

// Bit 0 is selected when bits 7:1 are clear.
    check_pos_from_bit0: assert property (
        @(posedge sel) ((in[7:1] == 7'b0000000) && in[0]) |-> (pos == 3'd0)
    );

// No asserted input bits produce position 0.
    check_pos_when_no_bits_set: assert property (
        @(posedge sel) (in == 8'b00000000) |-> (pos == 3'd0)
    );

// 000 advances to 001 on the next clock.
    check_count_000_to_001: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b000) |=> (counter == 3'b001)
    );

// 001 advances to 010 on the next clock.
    check_count_001_to_010: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b001) |=> (counter == 3'b010)
    );

// 010 advances to 011 on the next clock.
    check_count_010_to_011: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b010) |=> (counter == 3'b011)
    );

// 011 advances to 100 on the next clock.
    check_count_011_to_100: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b011) |=> (counter == 3'b100)
    );

// 100 advances to 101 on the next clock.
    check_count_100_to_101: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b100) |=> (counter == 3'b101)
    );

// 101 advances to 110 on the next clock.
    check_count_101_to_110: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b101) |=> (counter == 3'b110)
    );

// 110 advances to 111 on the next clock.
    check_count_110_to_111: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b110) |=> (counter == 3'b111)
    );

// 111 wraps back to 000 on the next clock.
    check_count_111_to_000: assert property (
        @(posedge clk) disable iff (reset)
        (counter == 3'b111) |=> (counter == 3'b000)
    );

// HI matches the RTL combinational equation.
    check_hi_matches_expr: assert property (
        @(posedge clk)
        HI == ((VPWR || VPB) ? 1'b1 : (VNB ? 1'b0 : (VGND ? 1'b0 : 1'b0)))
    );

// LO matches the RTL combinational equation.
    check_lo_matches_expr: assert property (
        @(posedge clk)
        LO == ((VGND || VNB) ? 1'b1 : (VPB ? 1'b0 : (VPWR ? 1'b1 : 1'b0)))
    );

// HI is high whenever VPWR or VPB is high.
    check_hi_high_on_vpwr_or_vpb: assert property (
        @(posedge clk)
        (VPWR || VPB) |-> (HI == 1'b1)
    );

// HI is low when both VPWR and VPB are low.
    check_hi_low_when_no_vpwr_or_vpb: assert property (
        @(posedge clk)
        (!VPWR && !VPB) |-> (HI == 1'b0)
    );

// LO is high whenever VGND or VNB is high.
    check_lo_high_on_vgnd_or_vnb: assert property (
        @(posedge clk)
        (VGND || VNB) |-> (LO == 1'b1)
    );

// LO is low when VPB is high without VGND or VNB overriding it.
    check_lo_low_on_vpb_without_override: assert property (
        @(posedge clk)
        (!VGND && !VNB && VPB) |-> (LO == 1'b0)
    );

// LO is high when VPWR is high and VPB, VGND, and VNB are low.
    check_lo_high_on_vpwr_only: assert property (
        @(posedge clk)
        (!VGND && !VNB && !VPB && VPWR) |-> (LO == 1'b1)
    );

// LO is low when all controlling inputs are low.
    check_lo_low_when_all_inputs_low: assert property (
        @(posedge clk)
        (!VGND && !VNB && !VPB && !VPWR) |-> (LO == 1'b0)
    );

// S[0] is the XOR of the first two input XOR terms.
    check_s0_equation: assert property (
        @(posedge clk)
        S[0] == ((A[0] ^ B[0]) ^ (A[1] ^ B[1]))
    );

// S[1] is the XOR of the upper two input XOR terms.
    check_s1_equation: assert property (
        @(posedge clk)
        S[1] == ((A[2] ^ B[2]) ^ (A[3] ^ B[3]))
    );

// S[2] is the XOR of the middle input XOR terms.
    check_s2_equation: assert property (
        @(posedge clk)
        S[2] == ((A[1] ^ B[1]) ^ (A[2] ^ B[2]))
    );

// S[3] matches the final XOR of S[2] and the first AND term.
    check_s3_equation: assert property (
        @(posedge clk)
        S[3] == (((A[1] ^ B[1]) ^ (A[2] ^ B[2])) ^ ((A[0] ^ B[0]) & (A[1] ^ B[1])))
    );

// C_out matches the OR of the three carry product terms.
    check_cout_equation: assert property (
        @(posedge clk)
        C_out == (
            (((A[0] ^ B[0]) & (A[1] ^ B[1])) & ((A[2] ^ B[2]) & (A[3] ^ B[3]))) |
            (((A[1] ^ B[1]) & (A[2] ^ B[2])) & ((A[0] ^ B[0]) & (A[1] ^ B[1]))) |
            (((A[2] ^ B[2]) & (A[3] ^ B[3])) & ((A[1] ^ B[1]) & (A[2] ^ B[2])))
        )
    );

// Equal inputs drive all XOR-derived outputs low.
    check_equal_inputs_zero_outputs: assert property (
        @(posedge clk)
        (A == B) |-> ((S == 4'b0000) && (C_out == 1'b0))
    );

// Any carry-out requires both middle XOR terms to be high.
    check_cout_requires_middle_terms: assert property (
        @(posedge clk)
        C_out |-> ((A[1] ^ B[1]) & (A[2] ^ B[2]))
    );

// Checks enb_array[0] matches its combinational equation.
    check_enb_array_bit0_function: assert property (
        @(posedge clk) enb_array[0] == ((addrb[1] & ~addrb[0]) | enb)
    );

// Checks enb_array[1] matches its combinational equation.
    check_enb_array_bit1_function: assert property (
        @(posedge clk) enb_array[1] == ((addrb[0] & ~addrb[1]) | enb)
    );

// Checks enb_array[2] matches its combinational equation.
    check_enb_array_bit2_function: assert property (
        @(posedge clk) enb_array[2] == ((enb & ~addrb[0]) | addrb[1])
    );

// Checks enb forces enb_array[1:0] high.
    check_enable_sets_low_bits: assert property (
        @(posedge clk) enb |-> (enb_array[1:0] == 2'b11)
    );

// Checks addrb[1] directly forces enb_array[2] high.
    check_addrb1_sets_bit2: assert property (
        @(posedge clk) addrb[1] |-> enb_array[2]
    );

// Checks bits 0 and 1 are never both high when enb is low.
    check_disabled_low_bits_mutually_exclusive: assert property (
        @(posedge clk) (!enb) |-> !(enb_array[0] && enb_array[1])
    );

// Checks the disabled decode for addrb == 2'b00.
    check_disabled_decode_00: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b00)) |-> (enb_array == 3'b000)
    );

// Checks the disabled decode for addrb == 2'b01.
    check_disabled_decode_01: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b01)) |-> (enb_array == 3'b010)
    );

// Checks the disabled decode for addrb == 2'b10.
    check_disabled_decode_10: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b10)) |-> (enb_array == 3'b101)
    );

// Checks the disabled decode for addrb == 2'b11.
    check_disabled_decode_11: assert property (
        @(posedge clk) ((!enb) && (addrb == 2'b11)) |-> (enb_array == 3'b100)
    );

// When select is exactly 0, Y captures A on the following clock.
    check_capture_a_when_s_low: assert property (
        @(posedge CLK) (S === 1'b0) |=> (Y == $past(A))
    );

// When select is not exactly 0, Y captures B on the following clock.
    check_capture_b_when_s_not_low: assert property (
        @(posedge CLK) (S !== 1'b0) |=> (Y == $past(B))
    );

// Y always reflects the input selected on the previous clock edge.
    check_output_matches_previous_selection: assert property (
        @(posedge CLK) 1'b1 |=> (Y == (($past(S) === 1'b0) ? $past(A) : $past(B)))
    );

// Sampled active-low reset forces count to zero.
    check_reset_drives_zero: assert property (
        @(posedge clk) !rst |-> (count == 4'd0)
    );

// First clock after a sampled reset low sets count to one.
    check_reset_release_starts_at_one: assert property (
        @(posedge clk) disable iff (!rst) (!$past(rst)) |-> (count == 4'd1)
    );

// With reset high on consecutive samples, count increments or restarts from one after an async reset pulse.
    check_running_step_or_restart: assert property (
        @(posedge clk) disable iff (!rst) $past(rst) |-> ((count == ($past(count) + 4'd1)) || (count == 4'd1))
    );

// A sampled zero while running can only come from wrapping past 15.
    check_zero_only_after_wrap: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && (count == 4'd0)) |-> ($past(count) == 4'hF)
    );

// A sampled zero while running advances to one on the next clock.
    check_zero_advances_to_one: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && ($past(count) == 4'd0)) |-> (count == 4'd1)
    );

// Y matches the implemented combinational function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == (!(A1 && A2 && A3) && !(B1 && B2))
    );

// A1/A2/A3 all high forces Y low.
    check_a_triplet_forces_low: assert property (
        @(posedge clk) (A1 && A2 && A3) |-> !Y
    );

// B1/B2 both high forces Y low.
    check_b_pair_forces_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// If neither input product is active, Y is high.
    check_no_active_product_gives_high: assert property (
        @(posedge clk) (!(A1 && A2 && A3) && !(B1 && B2)) |-> Y
    );

// Y high means the A-side product is not active.
    check_y_high_blocks_a_triplet: assert property (
        @(posedge clk) Y |-> !(A1 && A2 && A3)
    );

// Y high means the B-side product is not active.
    check_y_high_blocks_b_pair: assert property (
        @(posedge clk) Y |-> !(B1 && B2)
    );

// Y low must come from an active A-side or B-side product.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) !Y |-> ((A1 && A2 && A3) || (B1 && B2))
    );

// All-low inputs produce a high output.
    check_all_low_inputs_high_output: assert property (
        @(posedge clk) (!A1 && !A2 && !A3 && !B1 && !B2) |-> Y
    );

// All-high inputs produce a low output.
    check_all_high_inputs_low_output: assert property (
        @(posedge clk) (A1 && A2 && A3 && B1 && B2) |-> !Y
    );

// Reset clears the counter and forces the delayed reset low.
    check_reset_clears_counter: assert property (
        @(posedge ref_clk)
        !sys_reset_n |-> (reg_count_7_0 == 8'h00) &&
                         (reg_count_15_8 == 8'h00) &&
                         (reg_count_23_16 == 8'h00) &&
                         (delayed_sys_reset_n == 1'b0)
    );

// The counter stops changing once the delayed reset goes high.
    check_counter_holds_while_output_high: assert property (
        @(posedge ref_clk) disable iff (!sys_reset_n)
        delayed_sys_reset_n |=> $stable(concat_count)
    );

// Once high, the delayed reset remains high until reset is asserted.
    check_output_stays_high_once_asserted: assert property (
        @(posedge ref_clk) disable iff (!sys_reset_n)
        delayed_sys_reset_n |=> delayed_sys_reset_n
    );

// 4-bit up-counter on posedge clk with active-high synchronous reset.

    // Synchronous reset clears the counter.
    check_sync_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 4'b0000)
    );

// While reset stays asserted, the sampled counter value remains zero.
    check_reset_holds_q_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (q == 4'b0000)
    );

// When below 15, the counter increments by one.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (rst) (q != 4'b1111) |=> (q == ($past(q) + 4'b0001))
    );

// When at 15, the counter wraps back to zero.
    check_counter_wraps: assert property (
        @(posedge clk) disable iff (rst) (q == 4'b1111) |=> (q == 4'b0000)
    );

// Inputs below 1000 map to 01.
    check_low_range_encoding: assert property (
        @(posedge clk) (input_signal < 16'd1000) |-> (output_signal == 2'b01)
    );

// Inputs from 1000 through 2000 map to 10.
    check_mid_range_encoding: assert property (
        @(posedge clk) ((input_signal >= 16'd1000) && (input_signal <= 16'd2000)) |-> (output_signal == 2'b10)
    );

// Inputs above 2000 map to 11.
    check_high_range_encoding: assert property (
        @(posedge clk) (input_signal > 16'd2000) |-> (output_signal == 2'b11)
    );

// Boundary value 999 stays in the low range.
    check_boundary_999: assert property (
        @(posedge clk) (input_signal == 16'd999) |-> (output_signal == 2'b01)
    );

// Boundary value 1000 enters the middle range.
    check_boundary_1000: assert property (
        @(posedge clk) (input_signal == 16'd1000) |-> (output_signal == 2'b10)
    );

// Boundary value 2000 remains in the middle range.
    check_boundary_2000: assert property (
        @(posedge clk) (input_signal == 16'd2000) |-> (output_signal == 2'b10)
    );

// Boundary value 2001 enters the high range.
    check_boundary_2001: assert property (
        @(posedge clk) (input_signal == 16'd2001) |-> (output_signal == 2'b11)
    );

// The 5-bit output must equal A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Sum bit 0 must match the least-significant full-adder equation.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum bit 1 must include carry propagation from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1] == (
            A[1] ^ B[1] ^
            (
                (A[0] & B[0]) |
                ((A[0] ^ B[0]) & Cin)
            )
        )
    );

// Sum bit 2 must include carry propagation from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    (A[1] ^ B[1]) &
                    (
                        (A[0] & B[0]) |
                        ((A[0] ^ B[0]) & Cin)
                    )
                )
            )
        )
    );

// Sum bit 3 must include carry propagation through the lower bits.
    check_sum_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (A[2] ^ B[2]) &
                    (
                        (A[1] & B[1]) |
                        (
                            (A[1] ^ B[1]) &
                            (
                                (A[0] & B[0]) |
                                ((A[0] ^ B[0]) & Cin)
                            )
                        )
                    )
                )
            )
        )
    );

// Carry-out must match the final ripple-carry equation.
    check_cout_logic: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == (
            (A[3] & B[3]) |
            (
                (A[3] ^ B[3]) &
                (
                    (A[2] & B[2]) |
                    (
                        (A[2] ^ B[2]) &
                        (
                            (A[1] & B[1]) |
                            (
                                (A[1] ^ B[1]) &
                                (
                                    (A[0] & B[0]) |
                                    ((A[0] ^ B[0]) & Cin)
                                )
                            )
                        )
                    )
                )
            )
        )
    );

// Adding zero on B with no carry-in must pass A through unchanged.
    check_b_zero_identity: assert property (
        @(posedge clk) disable iff (1'b0)
        (B == 4'b0000 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero on A with no carry-in must pass B through unchanged.
    check_a_zero_identity: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'b0000 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, B})
    );

// X must always equal A XOR B.
    check_x_matches_xor: assert property (
        @(posedge clk) X == (A ^ B)
    );

// X must be low when both inputs are low.
    check_both_low_output_low: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// X must be high when only B is high.
    check_only_b_high_output_high: assert property (
        @(posedge clk) (!A && B) |-> X
    );

// X must be high when only A is high.
    check_only_a_high_output_high: assert property (
        @(posedge clk) (A && !B) |-> X
    );

// X must be low when both inputs are high.
    check_both_high_output_low: assert property (
        @(posedge clk) (A && B) |-> !X
    );

// Reset clears all four control bytes.
    reset_clears_control_regs: assert property (
        @(posedge mclk)
        puc_rst |-> (cntrl1 == 8'h00) && (cntrl2 == 8'h00) && (cntrl3 == 8'h00) && (cntrl4 == 8'h00)
    );

// Register select matches the peripheral base address decode.
    check_reg_select_decode: assert property (
        @(posedge mclk) disable iff (puc_rst)
        reg_sel == (per_en & (per_addr[13:DEC_WD-1] == BASE_ADDR[14:DEC_WD]))
    );

// Register address is the zero-extended low address field.
    check_reg_address_decode: assert property (
        @(posedge mclk) disable iff (puc_rst)
        reg_addr == {1'b0, per_addr[DEC_WD-2:0]}
    );

// Register decode matches the two-word control map.
    check_register_decode_map: assert property (
        @(posedge mclk) disable iff (puc_rst)
        reg_dec == ((CNTRL1_D & {DEC_SZ{(reg_addr == (CNTRL1 >> 1))}}) |
                    (CNTRL2_D & {DEC_SZ{(reg_addr == (CNTRL2 >> 1))}}) |
                    (CNTRL3_D & {DEC_SZ{(reg_addr == (CNTRL3 >> 1))}}) |
                    (CNTRL4_D & {DEC_SZ{(reg_addr == (CNTRL4 >> 1))}}))
    );

// Read and write qualifiers come directly from per_we and reg_sel.
    check_access_qualifiers: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (reg_lo_write == (per_we[0] & reg_sel)) &&
        (reg_hi_write == (per_we[1] & reg_sel)) &&
        (reg_read     == ((~|per_we) & reg_sel))
    );

// Masked decode vectors are gated versions of reg_dec.
    check_mask_generation: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (reg_hi_wr == (reg_dec & {DEC_SZ{reg_hi_write}})) &&
        (reg_lo_wr == (reg_dec & {DEC_SZ{reg_lo_write}})) &&
        (reg_rd    == (reg_dec & {DEC_SZ{reg_read}}))
    );

// cntrl1 write strobe and data select the proper byte lane.
    check_cntrl1_write_path: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (cntrl1_wr  == (CNTRL1[0] ? reg_hi_wr[CNTRL1] : reg_lo_wr[CNTRL1])) &&
        (cntrl1_nxt == (CNTRL1[0] ? per_din[15:8]     : per_din[7:0]))
    );

// cntrl1 follows its write enable and otherwise holds value.
    check_cntrl1_state_update: assert property (
        @(posedge mclk) disable iff (puc_rst)
        1'b1 |=> cntrl1 == ($past(cntrl1_wr) ? $past(cntrl1_nxt) : $past(cntrl1))
    );

// cntrl2 write strobe and data select the proper byte lane.
    check_cntrl2_write_path: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (cntrl2_wr  == (CNTRL2[0] ? reg_hi_wr[CNTRL2] : reg_lo_wr[CNTRL2])) &&
        (cntrl2_nxt == (CNTRL2[0] ? per_din[15:8]     : per_din[7:0]))
    );

// cntrl2 follows its write enable and otherwise holds value.
    check_cntrl2_state_update: assert property (
        @(posedge mclk) disable iff (puc_rst)
        1'b1 |=> cntrl2 == ($past(cntrl2_wr) ? $past(cntrl2_nxt) : $past(cntrl2))
    );

// cntrl3 write strobe and data select the proper byte lane.
    check_cntrl3_write_path: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (cntrl3_wr  == (CNTRL3[0] ? reg_hi_wr[CNTRL3] : reg_lo_wr[CNTRL3])) &&
        (cntrl3_nxt == (CNTRL3[0] ? per_din[15:8]     : per_din[7:0]))
    );

// cntrl3 follows its write enable and otherwise holds value.
    check_cntrl3_state_update: assert property (
        @(posedge mclk) disable iff (puc_rst)
        1'b1 |=> cntrl3 == ($past(cntrl3_wr) ? $past(cntrl3_nxt) : $past(cntrl3))
    );

// cntrl4 write strobe and data select the proper byte lane.
    check_cntrl4_write_path: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (cntrl4_wr  == (CNTRL4[0] ? reg_hi_wr[CNTRL4] : reg_lo_wr[CNTRL4])) &&
        (cntrl4_nxt == (CNTRL4[0] ? per_din[15:8]     : per_din[7:0]))
    );

// cntrl4 follows its write enable and otherwise holds value.
    check_cntrl4_state_update: assert property (
        @(posedge mclk) disable iff (puc_rst)
        1'b1 |=> cntrl4 == ($past(cntrl4_wr) ? $past(cntrl4_nxt) : $past(cntrl4))
    );

// Reads of the first word return cntrl2:cntrl1.
    check_readback_low_word: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (reg_rd[CNTRL1] && reg_rd[CNTRL2]) |-> (per_dout == {cntrl2, cntrl1})
    );

// Reads of the second word return cntrl4:cntrl3.
    check_readback_high_word: assert property (
        @(posedge mclk) disable iff (puc_rst)
        (reg_rd[CNTRL3] && reg_rd[CNTRL4]) |-> (per_dout == {cntrl4, cntrl3})
    );

// Non-read cycles must not drive peripheral read data.
    check_nonread_dout_zero: assert property (
        @(posedge mclk) disable iff (puc_rst)
        !reg_read |-> (per_dout == 16'h0000)
    );

// Y matches the implemented A2111OI Boolean equation.
    check_y_equation: assert property (
        @(posedge clk) Y == ~(B1 | C1 | D1 | (A1 & A2))
    );

// B1 high forces the NOR output low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// D1 high forces the NOR output low.
    check_d1_forces_y_low: assert property (
        @(posedge clk) D1 |-> !Y
    );

// A1 and A2 high together force the NOR output low.
    check_a1_a2_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// Y is high when all NOR inputs are low.
    check_all_nor_inputs_low_force_y_high: assert property (
        @(posedge clk) (!B1 && !C1 && !D1 && !(A1 && A2)) |-> Y
    );

// SW=00 selects xAxis directly when xAxis is non-negative.
    check_select_x_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b00 && xAxis[9] == 1'b0)
        |=> (LED == 3'b001 && DOUT == $past(xAxis))
    );

// SW=00 selects xAxis sign-plus-magnitude when xAxis is negative.
    check_select_x_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b00 && xAxis[9] == 1'b1)
        |=> (LED == 3'b001 &&
             DOUT == {$past(xAxis[9]), (9'b000000000 - $past(xAxis[8:0]))})
    );

// SW=01 selects yAxis directly when yAxis is non-negative.
    check_select_y_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b01 && yAxis[9] == 1'b0)
        |=> (LED == 3'b010 && DOUT == $past(yAxis))
    );

// SW=01 selects yAxis sign-plus-magnitude when yAxis is negative.
    check_select_y_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b01 && yAxis[9] == 1'b1)
        |=> (LED == 3'b010 &&
             DOUT == {$past(yAxis[9]), (9'b000000000 - $past(yAxis[8:0]))})
    );

// SW=10 selects zAxis directly when zAxis is non-negative.
    check_select_z_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b10 && zAxis[9] == 1'b0)
        |=> (LED == 3'b100 && DOUT == $past(zAxis))
    );

// SW=10 selects zAxis sign-plus-magnitude when zAxis is negative.
    check_select_z_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b10 && zAxis[9] == 1'b1)
        |=> (LED == 3'b100 &&
             DOUT == {$past(zAxis[9]), (9'b000000000 - $past(zAxis[8:0]))})
    );

// SW=11 takes the default path and selects xAxis directly when xAxis is non-negative.
    check_default_x_positive: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b11 && xAxis[9] == 1'b0)
        |=> (LED == 3'b001 && DOUT == $past(xAxis))
    );

// SW=11 takes the default path and selects xAxis sign-plus-magnitude when xAxis is negative.
    check_default_x_negative: assert property (
        @(posedge CLK) disable iff (RST)
        (SW == 2'b11 && xAxis[9] == 1'b1)
        |=> (LED == 3'b001 &&
             DOUT == {$past(xAxis[9]), (9'b000000000 - $past(xAxis[8:0]))})
    );

// When disabled, all outputs are low.
    check_disabled_forces_zero: assert property (
        @(posedge clk)
        !enable |-> (data_out == 4'b0000)
    );

// Select 00 routes only data_in[0] to data_out[3].
    check_select_00_route: assert property (
        @(posedge clk)
        enable && (select == 2'b00) |-> (data_out == {data_in[0], 1'b0, 1'b0, 1'b0})
    );

// Select 01 routes only data_in[1] to data_out[2].
    check_select_01_route: assert property (
        @(posedge clk)
        enable && (select == 2'b01) |-> (data_out == {1'b0, data_in[1], 1'b0, 1'b0})
    );

// Select 10 routes only data_in[2] to data_out[1].
    check_select_10_route: assert property (
        @(posedge clk)
        enable && (select == 2'b10) |-> (data_out == {1'b0, 1'b0, data_in[2], 1'b0})
    );

// Select 11 forces all outputs low.
    check_select_11_zero: assert property (
        @(posedge clk)
        enable && (select == 2'b11) |-> (data_out == 4'b0000)
    );

// The least significant output bit is always zero.
    check_lsb_always_zero: assert property (
        @(posedge clk)
        data_out[0] == 1'b0
    );

// The output is always zero or a single active routed bit.
    check_legal_output_patterns: assert property (
        @(posedge clk)
        (data_out == 4'b0000) || (data_out == 4'b1000) || (data_out == 4'b0100) || (data_out == 4'b0010)
    );

// data_out[3] can only be high for select 00 with data_in[0] high.
    check_bit3_source_condition: assert property (
        @(posedge clk)
        data_out[3] |-> enable && (select == 2'b00) && data_in[0]
    );

// data_out[2] can only be high for select 01 with data_in[1] high.
    check_bit2_source_condition: assert property (
        @(posedge clk)
        data_out[2] |-> enable && (select == 2'b01) && data_in[1]
    );

// data_out[1] can only be high for select 10 with data_in[2] high.
    check_bit1_source_condition: assert property (
        @(posedge clk)
        data_out[1] |-> enable && (select == 2'b10) && data_in[2]
    );

// RESET clears Q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) RESET |=> (Q == 4'b0000)
    );

// LOAD captures DIN when SHIFT is low.
    check_load_captures_din: assert property (
        @(posedge clk) disable iff (RESET)
        (LOAD && !SHIFT) |=> (Q == $past(DIN))
    );

// LOAD has priority over SHIFT when both are high.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (RESET)
        (LOAD && SHIFT) |=> (Q == $past(DIN))
    );

// SHIFT moves Q left and inserts zero when LOAD is low.
    check_shift_updates_q: assert property (
        @(posedge clk) disable iff (RESET)
        (!LOAD && SHIFT) |=> (
            (Q[3] == $past(Q[2])) &&
            (Q[2] == $past(Q[1])) &&
            (Q[1] == $past(Q[0])) &&
            (Q[0] == 1'b0)
        )
    );

// Q holds its value when no control is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (RESET)
        (!LOAD && !SHIFT) |=> (Q == $past(Q))
    );

// Output matches the AND of the two inputs.
    check_and_equivalence: assert property (
        @(posedge clk) out == (in1 & in2)
    );

// Both inputs high drive the output high.
    check_both_inputs_high: assert property (
        @(posedge clk) (in1 & in2) |-> out
    );

// A low in1 forces the output low.
    check_in1_low_forces_out_low: assert property (
        @(posedge clk) !in1 |-> !out
    );

// A low in2 forces the output low.
    check_in2_low_forces_out_low: assert property (
        @(posedge clk) !in2 |-> !out
    );

// A high output requires both inputs high.
    check_out_high_requires_both_inputs: assert property (
        @(posedge clk) out |-> (in1 & in2)
    );

// Y matches the 4-input NAND of A, B, C, and D.
    check_nand_function: assert property (
        @(posedge clk) (Y == ~(A & B & C & D))
    );

// Y is low when all four inputs are high.
    check_all_high_drives_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1)) |-> (Y == 1'b0)
    );

// A low input forces the NAND output high.
    check_a_low_drives_high: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b1)
    );

// B low input forces the NAND output high.
    check_b_low_drives_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

// C low input forces the NAND output high.
    check_c_low_drives_high: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b1)
    );

// D low input forces the NAND output high.
    check_d_low_drives_high: assert property (
        @(posedge clk) (D == 1'b0) |-> (Y == 1'b1)
    );

// A low Y can only occur when all four inputs are high.
    check_low_output_requires_all_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A == 1'b1) && (B == 1'b1) && (C == 1'b1) && (D == 1'b1))
    );

// Y must always be the bitwise complement of A.
    check_output_is_complement: assert property (
        @(posedge clk) Y == ~A
    );

// A low input must drive Y high.
    check_low_input_drives_high_output: assert property (
        @(posedge clk) !A |-> Y
    );

// A high input must drive Y low.
    check_high_input_drives_low_output: assert property (
        @(posedge clk) A |-> !Y
    );

// A sampled reset cycle clears the counter and output by the next clock.
    check_reset_clears_state: assert property (
        @(posedge clk_i)
        (!reset_n) |=> (count == 15'd0 && clk_o == 1'b0)
    );

// and_out and xor_out cannot be high on the same bit.
  check_and_xor_mutex: assert property (
    @(posedge clk) disable iff (1'b0) (and_out & xor_out) == '0
  );

// Reset clears the registered result on the next cycle.
    check_reset_clears_result: assert property (
        @(posedge clk) rst |=> (result == 8'h00)
    );

// Clear clears the registered result on the next cycle.
    check_clear_clears_result: assert property (
        @(posedge clk) disable iff (rst)
        clear |=> (result == 8'h00)
    );

// Add operation updates result with the previous cycle sum.
    check_add_updates_result: assert property (
        @(posedge clk) disable iff (rst)
        (!clear && (op == 2'b00)) |=> (result == (($past(num1) + $past(num2)) & 8'hFF))
    );

// Subtract operation updates result with the previous cycle difference.
    check_sub_updates_result: assert property (
        @(posedge clk) disable iff (rst)
        (!clear && (op == 2'b01)) |=> (result == (($past(num1) - $past(num2)) & 8'hFF))
    );

// Reset clears stage and output.
    check_reset_clears_state: assert property (
        @(posedge clk) reset |=> (stage == 2'd0 && num_out == 16'd0)
    );

// If R is high at a clock edge, Q is cleared on the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge CLK) disable iff (1'b0)
        R |=> (Q == 1'b0)
    );

// If S is high while R is low, Q is set on the next sampled cycle.
    check_set_sets_q: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!R && S) |=> (Q == 1'b1)
    );

// If neither R nor S is high, Q captures D on the next sampled cycle.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!R && !S) |=> (Q == $past(D))
    );

// If both R and S are high, R has priority and Q is cleared.
    check_reset_priority_over_set: assert property (
        @(posedge CLK) disable iff (1'b0)
        (R && S) |=> (Q == 1'b0)
    );

// On every cycle, Q matches the previous cycle's selected input.
    check_full_next_state_function: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |=> (Q == ($past(R) ? 1'b0 : ($past(S) ? 1'b1 : $past(D))))
    );

// RES is zero whenever reset is asserted.
    check_reset_clears_res: assert property (
        @(posedge clk) rst |-> (RES == 32'b0)
    );

// Addition result is registered on the next clock.
    check_addition_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00000) |=> (RES == ($past(A) + $past(B)))
    );

// Subtraction result is registered on the next clock.
    check_subtraction_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00001) |=> (RES == ($past(A) - $past(B)))
    );

// Bitwise AND result is registered on the next clock.
    check_and_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00010) |=> (RES == ($past(A) & $past(B)))
    );

// Bitwise OR result is registered on the next clock.
    check_or_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00011) |=> (RES == ($past(A) | $past(B)))
    );

// Bitwise XOR result is registered on the next clock.
    check_xor_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00100) |=> (RES == ($past(A) ^ $past(B)))
    );

// Logical left shift result is registered on the next clock.
    check_shift_left_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL == 5'b00101) |=> (RES == ($past(A) << $past(B)))
    );

// Unsupported control values drive zero on the next clock.
    check_default_zero_result: assert property (
        @(posedge clk) disable iff (rst)
        (CTRL >= 5'b00110) |=> (RES == 32'b0)
    );

// When sel selects x_axis, data must match x_axis.
    check_select_x_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b00) |-> (data == x_axis)
    );

// When sel selects y_axis, data must match y_axis.
    check_select_y_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b01) |-> (data == y_axis)
    );

// When sel selects z_axis, data must match z_axis.
    check_select_z_axis: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b10) |-> (data == z_axis)
    );

// When sel selects temp_data, data must be zero-extended temp_data.
    check_select_temp_data: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 2'b11) |-> (data == {8'h00, temp_data})
    );

// External sampling clock; DUT has no native clock or reset and is combinational.

    // out must match the implemented 3-of-4 OR expression.
    check_out_matches_expression: assert property (
        @(posedge clk)
        out == ((in1 & in2 & in3) |
                (in1 & in2 & in4) |
                (in1 & in3 & in4) |
                (in2 & in3 & in4))
    );

// in1, in2, and in3 high must force out high.
    check_triplet_123_sets_out: assert property (
        @(posedge clk)
        (in1 & in2 & in3) |-> out
    );

// in1, in2, and in4 high must force out high.
    check_triplet_124_sets_out: assert property (
        @(posedge clk)
        (in1 & in2 & in4) |-> out
    );

// in1, in3, and in4 high must force out high.
    check_triplet_134_sets_out: assert property (
        @(posedge clk)
        (in1 & in3 & in4) |-> out
    );

// in2, in3, and in4 high must force out high.
    check_triplet_234_sets_out: assert property (
        @(posedge clk)
        (in2 & in3 & in4) |-> out
    );

// If no three-input combination is high, out must be low.
    check_no_triplet_means_out_low: assert property (
        @(posedge clk)
        !((in1 & in2 & in3) |
          (in1 & in2 & in4) |
          (in1 & in3 & in4) |
          (in2 & in3 & in4)) |-> !out
    );

// Reset clears the registered result on the following cycle.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |=> (result == 32'd0)
    );

// q must be low whenever the active-low reset is asserted.
    check_reset_forces_q_low: assert property (
        @(posedge clk) !reset |-> (q == 1'b0)
    );

// q_n must be high whenever the active-low reset is asserted.
    check_reset_forces_qn_high: assert property (
        @(posedge clk) !reset |-> (q_n == 1'b1)
    );

// q_n must be the inverse of q during normal operation.
    check_qn_is_inverse_of_q: assert property (
        @(posedge clk) disable iff (!reset) (q_n == ~q)
    );

// A sampled low reset keeps q low through the next clock sample.
    check_reset_keeps_q_low_next_cycle: assert property (
        @(posedge clk) !reset |=> (q == 1'b0)
    );

// A rise on q must come from a prior clock with reset high and d high.
    check_q_rise_requires_prior_d_high: assert property (
        @(posedge clk) disable iff (!reset) $rose(q) |-> (($past(reset) == 1'b1) && ($past(d) == 1'b1))
    );

// Reset clears all pipeline stages.
    check_reset_clears_pipeline: assert property (
        @(posedge clk)
        reset |=> ({pipeline_reg_16, pipeline_reg_15, pipeline_reg_14, pipeline_reg_13,
                    pipeline_reg_12, pipeline_reg_11, pipeline_reg_10, pipeline_reg_9,
                    pipeline_reg_8, pipeline_reg_7, pipeline_reg_6, pipeline_reg_5,
                    pipeline_reg_4, pipeline_reg_3, pipeline_reg_2, pipeline_reg_1,
                    pipeline_reg_0} == 17'b0)
    );

// The pipeline holds state when clock enable is low.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !clk_ena |=> $stable({pipeline_reg_16, pipeline_reg_15, pipeline_reg_14, pipeline_reg_13,
                              pipeline_reg_12, pipeline_reg_11, pipeline_reg_10, pipeline_reg_9,
                              pipeline_reg_8, pipeline_reg_7, pipeline_reg_6, pipeline_reg_5,
                              pipeline_reg_4, pipeline_reg_3, pipeline_reg_2, pipeline_reg_1,
                              pipeline_reg_0})
    );

// Stage 0 captures the input when enabled.
    check_stage0_captures_input: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_0 == $past(in_stream))
    );

// Stage 1 captures stage 0 when enabled.
    check_stage1_captures_stage0: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_1 == $past(pipeline_reg_0))
    );

// Stage 2 captures stage 1 when enabled.
    check_stage2_captures_stage1: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_2 == $past(pipeline_reg_1))
    );

// Stage 3 captures stage 2 when enabled.
    check_stage3_captures_stage2: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_3 == $past(pipeline_reg_2))
    );

// Stage 4 captures stage 3 when enabled.
    check_stage4_captures_stage3: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_4 == $past(pipeline_reg_3))
    );

// Stage 5 captures stage 4 when enabled.
    check_stage5_captures_stage4: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_5 == $past(pipeline_reg_4))
    );

// Stage 6 captures stage 5 when enabled.
    check_stage6_captures_stage5: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_6 == $past(pipeline_reg_5))
    );

// Stage 7 captures stage 6 when enabled.
    check_stage7_captures_stage6: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_7 == $past(pipeline_reg_6))
    );

// Stage 8 captures stage 7 when enabled.
    check_stage8_captures_stage7: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_8 == $past(pipeline_reg_7))
    );

// Stage 9 captures stage 8 when enabled.
    check_stage9_captures_stage8: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_9 == $past(pipeline_reg_8))
    );

// Stage 10 captures stage 9 when enabled.
    check_stage10_captures_stage9: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_10 == $past(pipeline_reg_9))
    );

// Stage 11 captures stage 10 when enabled.
    check_stage11_captures_stage10: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_11 == $past(pipeline_reg_10))
    );

// Stage 12 captures stage 11 when enabled.
    check_stage12_captures_stage11: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_12 == $past(pipeline_reg_11))
    );

// Stage 13 captures stage 12 when enabled.
    check_stage13_captures_stage12: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_13 == $past(pipeline_reg_12))
    );

// Stage 14 captures stage 13 when enabled.
    check_stage14_captures_stage13: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_14 == $past(pipeline_reg_13))
    );

// Stage 15 captures stage 14 when enabled.
    check_stage15_captures_stage14: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_15 == $past(pipeline_reg_14))
    );

// Stage 16 captures stage 15 when enabled.
    check_stage16_captures_stage15: assert property (
        @(posedge clk) disable iff (reset)
        clk_ena |=> (pipeline_reg_16 == $past(pipeline_reg_15))
    );

// Bit 0 sum matches the first full-adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ CIN)
    );

// Bit 1 sum uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^
                 ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))
    );

// The low three bits and COUT equal the 3-bit addition result.
    check_lower_three_bit_addition: assert property (
        @(posedge clk)
        {COUT, S[2:0]} == ({1'b0, A[2:0]} + {1'b0, B[2:0]} + CIN)
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                  (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))))
    );

// Bit 3 sum XORs A[3] and B[3] with COUT.
    check_sum_bit3_uses_cout: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^ COUT)
    );

// Before clk rises, clk is low so the output must be high.
    check_gated_clk_high_before_clk_rise: assert property (
        @(posedge clk) (gated_clk == 1'b1)
    );

// Before clk falls, a low enable keeps the output high.
    check_gated_clk_high_when_clk_high_and_en_low: assert property (
        @(negedge clk) (!en) |-> (gated_clk == 1'b1)
    );

// Before clk falls, a high enable drives the output low.
    check_gated_clk_low_when_clk_high_and_en_high: assert property (
        @(negedge clk) en |-> (gated_clk == 1'b0)
    );

// SUM must match the XOR of A, B, and CI.
    check_sum_equation: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT must match the implemented carry equation.
    check_cout_equation: assert property (
        @(posedge clk) COUT == ((A & B) | ((A ^ B) & CI))
    );

// All-zero input must produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && !COUT)
    );

// Exactly one high input must produce sum one and carry zero.
    check_single_one_case: assert property (
        @(posedge clk)
        (( A && !B && !CI) ||
         (!A &&  B && !CI) ||
         (!A && !B &&  CI)) |-> (SUM && !COUT)
    );

// Exactly two high inputs must produce sum zero and carry one.
    check_double_one_case: assert property (
        @(posedge clk)
        (( A &&  B && !CI) ||
         ( A && !B &&  CI) ||
         (!A &&  B &&  CI)) |-> (!SUM && COUT)
    );

// All-one input must produce sum one and carry one.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && COUT)
    );

// vbb8263 directly mirrors vc83501.
    check_vbb8263_matches_vc83501: assert property (
        @(posedge clk) vbb8263 == vc83501
    );

// Bit 1 of vbb8263 matches bit 1 of vc83501.
    check_vbb8263_bit1_matches: assert property (
        @(posedge clk) vbb8263[1] == vc83501[1]
    );

// Bit 0 of vbb8263 matches bit 0 of vc83501.
    check_vbb8263_bit0_matches: assert property (
        @(posedge clk) vbb8263[0] == vc83501[0]
    );

// v6f5c59 is the bitwise inverse of v78d66e.
    check_v6f5c59_is_inversion_of_v78d66e: assert property (
        @(posedge clk) v6f5c59 == ~v78d66e
    );

// Bit 1 of v6f5c59 inverts bit 1 of v78d66e.
    check_v6f5c59_bit1_inverts: assert property (
        @(posedge clk) v6f5c59[1] == ~v78d66e[1]
    );

// Bit 0 of v6f5c59 inverts bit 0 of v78d66e.
    check_v6f5c59_bit0_inverts: assert property (
        @(posedge clk) v6f5c59[0] == ~v78d66e[0]
    );

// A sampled reset clears both synchronizer stages by the next clock.
    check_reset_clears_pipeline: assert property (
        @(posedge clk)
        reset |=> ((sync_reg0 == {(DW){1'b0}}) && (out == {(DW){1'b0}}))
    );

// On the first clock after reset deasserts, both stages are still zero.
    check_first_cycle_after_reset_release_zero: assert property (
        @(posedge clk)
        reset ##1 !reset |-> ((sync_reg0 == {(DW){1'b0}}) && (out == {(DW){1'b0}}))
    );

// On the second clock after reset deasserts, out is still zero.
    check_second_cycle_after_reset_release_out_zero: assert property (
        @(posedge clk)
        reset ##1 !reset ##1 !reset |-> (out == {(DW){1'b0}})
    );

// After two reset-free clocks, out is either the two-cycle delayed input or zero from reset.
    check_out_is_delayed_input_or_zero: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 ##1 1'b1 |=> ((out == $past(in,2)) || (out == {(DW){1'b0}}))
    );

// X matches the implemented function (~A_N) & B.
    check_function: assert property (
        @(posedge clk) X == ((~A_N) & B)
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// A_N high forces X low.
    check_an_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// A_N low with B high drives X high.
    check_selected_high: assert property (
        @(posedge clk) (!A_N && B) |-> X
    );

// X high implies B is high and A_N is low.
    check_x_high_conditions: assert property (
        @(posedge clk) X |-> (B && !A_N)
    );

// SUM matches the three-input parity bit.
    check_sum_parity: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT matches the implemented top-level logic.
    check_cout_function: assert property (
        @(posedge clk) COUT == (CI && !A && !B)
    );

// All-zero inputs produce zero outputs.
    check_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && !COUT)
    );

// Only CI high produces both outputs high.
    check_ci_only_case: assert property (
        @(posedge clk) (!A && !B && CI) |-> (SUM && COUT)
    );

// CI low forces COUT low.
    check_ci_low_blocks_cout: assert property (
        @(posedge clk) !CI |-> !COUT
    );

// Any asserted A or B forces COUT low.
    check_ab_high_blocks_cout: assert property (
        @(posedge clk) (A || B) |-> !COUT
    );

// ack_o is a direct copy of stb_i.
    check_ack_matches_stb: assert property (
        @(posedge clk) disable iff (1'b0)
        (ack_o == stb_i)
    );

// Address 0 and 4 return 16'h0113.
    check_data_addr_0_or_4: assert property (
        @(posedge clk) disable iff (1'b0)
        ((adr_i == 7'd0) || (adr_i == 7'd4)) |-> (dat_o == 16'h0113)
    );

// Address 1 returns 16'h0000.
    check_data_addr_1: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd1) |-> (dat_o == 16'h0000)
    );

// Address 2 returns 16'h01B7.
    check_data_addr_2: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd2) |-> (dat_o == 16'h01B7)
    );

// Address 3 returns 16'h0010.
    check_data_addr_3: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd3) |-> (dat_o == 16'h0010)
    );

// Address 5 and 7 return 16'h0011.
    check_data_addr_5_or_7: assert property (
        @(posedge clk) disable iff (1'b0)
        ((adr_i == 7'd5) || (adr_i == 7'd7)) |-> (dat_o == 16'h0011)
    );

// Address 6 returns 16'h5213.
    check_data_addr_6: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd6) |-> (dat_o == 16'h5213)
    );

// Address 8 returns 16'h9123.
    check_data_addr_8: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd8) |-> (dat_o == 16'h9123)
    );

// Address 9 returns 16'h0041.
    check_data_addr_9: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd9) |-> (dat_o == 16'h0041)
    );

// Address 10 returns 16'hF06F.
    check_data_addr_10: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd10) |-> (dat_o == 16'hF06F)
    );

// Address 11 returns 16'hFF5F.
    check_data_addr_11: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i == 7'd11) |-> (dat_o == 16'hFF5F)
    );

// Addresses 12 through 127 return 16'hCCCC.
    check_data_addr_12_to_127: assert property (
        @(posedge clk) disable iff (1'b0)
        (adr_i >= 7'd12) |-> (dat_o == 16'hCCCC)
    );

// max matches the nested comparator implementation.
    check_nested_compare_equivalence: assert property (
        @(posedge clk)
        max == ((((a > b) ? a : b) > ((c > d) ? c : d)) ? ((a > b) ? a : b) : ((c > d) ? c : d))
    );

// max is never smaller than a.
    check_max_ge_a: assert property (
        @(posedge clk)
        max >= a
    );

// max is never smaller than b.
    check_max_ge_b: assert property (
        @(posedge clk)
        max >= b
    );

// max is never smaller than c.
    check_max_ge_c: assert property (
        @(posedge clk)
        max >= c
    );

// max is never smaller than d.
    check_max_ge_d: assert property (
        @(posedge clk)
        max >= d
    );

// max must equal one of the four inputs.
    check_max_matches_an_input: assert property (
        @(posedge clk)
        (max == a) || (max == b) || (max == c) || (max == d)
    );

// If a is at least as large as all others, max equals a.
    check_a_is_max_value: assert property (
        @(posedge clk)
        ((a >= b) && (a >= c) && (a >= d)) |-> (max == a)
    );

// If b is at least as large as all others, max equals b.
    check_b_is_max_value: assert property (
        @(posedge clk)
        ((b >= a) && (b >= c) && (b >= d)) |-> (max == b)
    );

// If c is at least as large as all others, max equals c.
    check_c_is_max_value: assert property (
        @(posedge clk)
        ((c >= a) && (c >= b) && (c >= d)) |-> (max == c)
    );

// If d is at least as large as all others, max equals d.
    check_d_is_max_value: assert property (
        @(posedge clk)
        ((d >= a) && (d >= b) && (d >= c)) |-> (max == d)
    );

// DUT is purely combinational and has no reset; clk is a sampling clock.

    // The 5-bit output must equal A + B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// The least-significant sum bit is the XOR of the LSB inputs and carry-in.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 1 must use the carry generated from bit 0.
    check_bit1_ripple: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

// Adding zero with no carry-in must reproduce A with no carry-out.
    check_add_zero_to_a: assert property (
        @(posedge clk) (B == 4'h0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero with no carry-in must reproduce B with no carry-out.
    check_add_zero_to_b: assert property (
        @(posedge clk) (A == 4'h0 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, B})
    );

// All-zero inputs must produce a zero result.
    check_all_zero_inputs: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && Cin == 1'b0) |-> ({Cout, S} == 5'h00)
    );

// Carry-in alone must increment the zero input case to 1.
    check_cin_only: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && Cin == 1'b1) |-> ({Cout, S} == 5'h01)
    );

// Carry-out must be high exactly when the arithmetic result is 16 or more.
    check_cout_overflow: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

// Maximum operands without carry-in must produce 0xE with carry-out.
    check_max_operands_no_cin: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b0) |-> ({Cout, S} == 5'h1E)
    );

// Maximum operands with carry-in must produce 0xF with carry-out.
    check_max_operands_with_cin: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> ({Cout, S} == 5'h1F)
    );

// Reset drives the counter to zero on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count_out == 4'b0000)
    );

// Reset has priority over enable and still clears the counter.
    check_reset_priority_over_enable: assert property (
        @(posedge clk) (reset && enable) |=> (count_out == 4'b0000)
    );

// When enabled outside reset, the counter increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count_out == ($past(count_out) + 4'd1))
    );

// When disabled outside reset, the counter holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count_out == $past(count_out))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wraps_from_max_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// A write updates q with the written data two cycles later.
    check_write_reaches_q_after_two_cycles: assert property (
        @(posedge clock) wren |-> ##2 (q == $past(data, 2))
    );

// Without a write, q holds its prior sampled value two cycles later.
    check_no_write_holds_q_after_two_cycles: assert property (
        @(posedge clock) !wren |-> ##2 (q == $past(q))
    );

// Back-to-back writes appear on q in the same order, two cycles later.
    check_back_to_back_writes_preserve_order: assert property (
        @(posedge clock) (wren ##1 wren) |=> ((q == $past(data, 2)) ##1 (q == $past(data, 2)))
    );

// A write followed by an idle cycle makes q take the write data, then hold it.
    check_write_then_idle_holds_value: assert property (
        @(posedge clock) (wren ##1 !wren) |=> ((q == $past(data, 2)) ##1 (q == $past(q)))
    );

// An idle cycle before a write delays any q update until the write reaches q.
    check_idle_then_write_delays_update: assert property (
        @(posedge clock) (!wren ##1 wren) |=> ((q == $past(q)) ##1 (q == $past(data, 2)))
    );

// SLEEP high forces X low.
    check_sleep_forces_low: assert property (
        @(posedge clk) SLEEP |-> (X == 1'b0)
    );

// SLEEP low makes X follow A.
    check_awake_passes_input: assert property (
        @(posedge clk) !SLEEP |-> (X == A)
    );

// F matches the selected arithmetic operation every sampled cycle.
    check_selected_operation: assert property (
        @(posedge clk) F == (S ? (A - B) : (A + B))
    );

// In add mode, F is the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) (S == 1'b0) |-> (F == (A + B))
    );

// In subtract mode, F is the 4-bit difference of A and B.
    check_sub_mode_result: assert property (
        @(posedge clk) (S == 1'b1) |-> (F == (A - B))
    );

// Adding zero on B passes A through to F.
    check_add_zero_on_b: assert property (
        @(posedge clk) ((S == 1'b0) && (B == 4'h0)) |-> (F == A)
    );

// Adding zero on A passes B through to F.
    check_add_zero_on_a: assert property (
        @(posedge clk) ((S == 1'b0) && (A == 4'h0)) |-> (F == B)
    );

// Subtracting zero on B passes A through to F.
    check_sub_zero_on_b: assert property (
        @(posedge clk) ((S == 1'b1) && (B == 4'h0)) |-> (F == A)
    );

// Subtracting equal operands produces zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) ((S == 1'b1) && (A == B)) |-> (F == 4'h0)
    );

// op=00 drives C with the 8-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (C == ((A + B) & 8'hFF))
    );

// op=01 drives C with the 8-bit difference of A and B.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (C == ((A - B) & 8'hFF))
    );

// Sum matches the three-input parity function.
    check_sum_matches_xor: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry matches the AND of A and B.
    check_carry_matches_ab_and: assert property (
        @(posedge clk) Co == (A & B)
    );

// Equal A and B make the sum follow Ci.
    check_sum_follows_cin_when_ab_equal: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

// Different A and B make the sum invert Ci.
    check_sum_inverts_cin_when_ab_different: assert property (
        @(posedge clk) (A ^ B) |-> (S == ~Ci)
    );

// A low forces carry low.
    check_carry_low_when_a_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (Co == 1'b0)
    );

// B low forces carry low.
    check_carry_low_when_b_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (Co == 1'b0)
    );

// A and B high force carry high.
    check_carry_high_when_ab_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (Co == 1'b1)
    );

// High carry implies the sum equals Ci.
    check_sum_matches_cin_when_carry_high: assert property (
        @(posedge clk) (Co == 1'b1) |-> (S == Ci)
    );

// Y must implement the RTL NAND function of the four inputs.
    check_function_equivalence: assert property (
        @(posedge clk) Y === ~(A1 & A2 & B1_N & B2_N)
    );

// If all four inputs are high, Y must be low.
    check_all_high_drives_low: assert property (
        @(posedge clk)
        (A1 === 1'b1 && A2 === 1'b1 && B1_N === 1'b1 && B2_N === 1'b1) |-> (Y === 1'b0)
    );

// If A1 is low, Y must be high.
    check_a1_low_drives_high: assert property (
        @(posedge clk)
        (A1 === 1'b0) |-> (Y === 1'b1)
    );

// If A2 is low, Y must be high.
    check_a2_low_drives_high: assert property (
        @(posedge clk)
        (A2 === 1'b0) |-> (Y === 1'b1)
    );

// If B1_N is low, Y must be high.
    check_b1_n_low_drives_high: assert property (
        @(posedge clk)
        (B1_N === 1'b0) |-> (Y === 1'b1)
    );

// If B2_N is low, Y must be high.
    check_b2_n_low_drives_high: assert property (
        @(posedge clk)
        (B2_N === 1'b0) |-> (Y === 1'b1)
    );

// A low Y can only occur when all four inputs are high.
    check_low_output_requires_all_high: assert property (
        @(posedge clk)
        (Y === 1'b0) |-> (A1 === 1'b1 && A2 === 1'b1 && B1_N === 1'b1 && B2_N === 1'b1)
    );

// Reset forces the counter output to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// When load is asserted, count updates with data on the next clock.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (rst) load |=> (count == $past(data))
    );

// When load is deasserted, count increments by one on the next clock.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (rst) !load |=> (count == ($past(count) + 4'd1))
    );

// Incrementing from 4'hF wraps the 4-bit counter back to zero.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && load) |-> (count == 4'd0)
    );

// Reset drives sum to zero on the next cycle.
    check_sum_resets_to_zero: assert property (
        @(posedge clock) reset |=> (sum == 34'sd0)
    );

// Clear loads the sign-extended addend into sum.
    check_sum_loads_addend_on_clear: assert property (
        @(posedge clock) disable iff (reset)
        clear |=> (sum == {{3{$past(addend[30])}}, $past(addend)})
    );

// Enable accumulates addend into sum when clear is low.
    check_sum_accumulates_on_enable: assert property (
        @(posedge clock) disable iff (reset)
        (!clear && enable_in) |=> (sum == ($past(sum) + $past(addend)))
    );

// Sum holds when reset, clear, and enable are all inactive.
    check_sum_holds_when_idle: assert property (
        @(posedge clock) disable iff (reset)
        (!clear && !enable_in) |=> (sum == $past(sum))
    );

// Clear has priority over enable for sum updates.
    check_clear_priority_over_enable: assert property (
        @(posedge clock) disable iff (reset)
        (clear && enable_in) |=> (sum == {{3{$past(addend[30])}}, $past(addend)})
    );

// Enable_out goes high one cycle after enable_in is high.
    check_enable_out_follows_enable_high: assert property (
        @(posedge clock) enable_in |=> enable_out
    );

// Enable_out goes low one cycle after enable_in is low.
    check_enable_out_follows_enable_low: assert property (
        @(posedge clock) !enable_in |=> !enable_out
    );

// When A is less than B, O must indicate less-than.
    check_less_than_output: assert property (
        @(posedge clk) (A < B) |-> (O == CMP_LT)
    );

// When A equals B, O must indicate equality.
    check_equal_output: assert property (
        @(posedge clk) (A == B) |-> (O == CMP_EQ)
    );

// When A is greater than B, O must indicate greater-than.
    check_greater_than_output: assert property (
        @(posedge clk) (A > B) |-> (O == CMP_GT)
    );

// The less-than code must only occur when A is less than B.
    check_less_than_code_meaning: assert property (
        @(posedge clk) (O == CMP_LT) |-> (A < B)
    );

// The equality code must only occur when A equals B.
    check_equal_code_meaning: assert property (
        @(posedge clk) (O == CMP_EQ) |-> (A == B)
    );

// The greater-than code must only occur when A is greater than B.
    check_greater_than_code_meaning: assert property (
        @(posedge clk) (O == CMP_GT) |-> (A > B)
    );

// O must always be one of the three implemented encodings.
    check_output_encoding_legal: assert property (
        @(posedge clk) (O == CMP_LT) || (O == CMP_EQ) || (O == CMP_GT)
    );

// The MSB of O is always zero in all implemented encodings.
    check_output_msb_low: assert property (
        @(posedge clk) O[2] == 1'b0
    );

// Output matches the RTL three-input AND.
    check_ce_expnd_matches_and: assert property (
        @(posedge clk)
        ce_expnd_i_3 == (bus2ip_addr_i_reg_2 & start2 & bus2ip_addr_i_reg_3)
    );

// A high output requires all three inputs to be high.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk)
        ce_expnd_i_3 |-> (bus2ip_addr_i_reg_2 && start2 && bus2ip_addr_i_reg_3)
    );

// All three high inputs drive the output high.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk)
        (bus2ip_addr_i_reg_2 && start2 && bus2ip_addr_i_reg_3) |-> ce_expnd_i_3
    );

// A low bus2ip_addr_i_reg_2 forces the output low.
    check_addr2_low_drives_output_low: assert property (
        @(posedge clk)
        !bus2ip_addr_i_reg_2 |-> !ce_expnd_i_3
    );

// A low start2 forces the output low.
    check_start2_low_drives_output_low: assert property (
        @(posedge clk)
        !start2 |-> !ce_expnd_i_3
    );

// A low bus2ip_addr_i_reg_3 forces the output low.
    check_addr3_low_drives_output_low: assert property (
        @(posedge clk)
        !bus2ip_addr_i_reg_3 |-> !ce_expnd_i_3
    );

// Reset drives the default state.
    check_reset_values: assert property (
        @(posedge clk)
        (!rst) |-> ((count == 4'h0) && (dir == 1'b1))
    );

// Count holds when enable is low.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!rst)
        (!en) |=> (count == $past(count))
    );

// Direction holds when enable is low.
    check_dir_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!rst)
        (!en) |=> (dir == $past(dir))
    );

// In up mode, count increments when below 15.
    check_count_increment_up: assert property (
        @(posedge clk) disable iff (!rst)
        (en && dir && (count != 4'hF)) |=> ((count == ($past(count) + 4'd1)) && (dir == 1'b0))
    );

// In up mode, count wraps from 15 to 0.
    check_count_wrap_up: assert property (
        @(posedge clk) disable iff (!rst)
        (en && dir && (count == 4'hF)) |=> ((count == 4'h0) && (dir == 1'b0))
    );

// In down mode, count decrements when above 0.
    check_count_decrement_down: assert property (
        @(posedge clk) disable iff (!rst)
        (en && !dir && (count != 4'h0)) |=> ((count == ($past(count) - 4'd1)) && (dir == 1'b1))
    );

// In down mode, count wraps from 0 to 15.
    check_count_wrap_down: assert property (
        @(posedge clk) disable iff (!rst)
        (en && !dir && (count == 4'h0)) |=> ((count == 4'hF) && (dir == 1'b1))
    );

// Direction toggles on every enabled cycle.
    check_dir_toggles_when_enabled: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> (dir == ~$past(dir))
    );

// Count changes on every enabled cycle.
    check_count_changes_when_enabled: assert property (
        @(posedge clk) disable iff (!rst)
        en |=> (count != $past(count))
    );

// External sampling clock; RTL has no reset and is purely combinational.

    // G must always implement the greater-of-two function.
    check_g_matches_max_function: assert property (
        @(posedge clk) G == ((A > B) ? A : B)
    );

// When A is greater than B, G must equal A.
    check_a_greater_selects_a: assert property (
        @(posedge clk) (A > B) |-> (G == A)
    );

// When A is not greater than B, G must equal B.
    check_a_not_greater_selects_b: assert property (
        @(posedge clk) (A <= B) |-> (G == B)
    );

// When A and B are equal, G must equal that shared value.
    check_equal_inputs_select_shared_value: assert property (
        @(posedge clk) (A == B) |-> (G == A)
    );

// G must always be one of the two inputs.
    check_g_is_one_of_the_inputs: assert property (
        @(posedge clk) ((G == A) || (G == B))
    );

// G must never be less than A.
    check_g_not_less_than_a: assert property (
        @(posedge clk) (G >= A)
    );

// G must never be less than B.
    check_g_not_less_than_b: assert property (
        @(posedge clk) (G >= B)
    );

// Y equals the AND of all four inputs.
    check_y_matches_and4: assert property (
        @(posedge clk) Y == (A & B & C & D)
    );

// Y is high when all inputs are high.
    check_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (A && B && C && D) |-> (Y == 1'b1)
    );

// Y can only be high when all inputs are high.
    check_y_high_requires_all_inputs_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (A && B && C && D)
    );

// Y is low when A is low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b0)
    );

// Y is low when B is low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b0)
    );

// Y is low when C is low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b0)
    );

// Y is low when D is low.
    check_d_low_forces_y_low: assert property (
        @(posedge clk) (D == 1'b0) |-> (Y == 1'b0)
    );

// C must equal the 5-bit sum of A and B.
    check_full_add_result: assert property (
        @(posedge clk) C == ({1'b0, A} + {1'b0, B})
    );

// C[3:0] must match the low 4 bits of the addition.
    check_lower_sum_bits: assert property (
        @(posedge clk) C[3:0] == (A + B)
    );

// C[4] must reflect carry-out from the 4-bit addition.
    check_carry_out_bit: assert property (
        @(posedge clk) C[4] == (({1'b0, A} + {1'b0, B}) >= 5'd16)
    );

// The least-significant sum bit must be A[0] XOR B[0].
    check_bit0_xor: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0])
    );

// Bit 1 must include the carry from bit 0.
    check_bit1_with_carry0: assert property (
        @(posedge clk) C[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

// Adding zero on A must pass B through.
    check_zero_a_identity: assert property (
        @(posedge clk) (A == 4'h0) |-> (C == {1'b0, B})
    );

// Adding zero on B must pass A through.
    check_zero_b_identity: assert property (
        @(posedge clk) (B == 4'h0) |-> (C == {1'b0, A})
    );

// X matches the OR of B1 and the 4-input A AND term.
    check_x_matches_function: assert property (
        @(posedge clk) disable iff (1'b0)
        X == (B1 || (A1 && A2 && A3 && A4))
    );

// A high B1 forces X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        B1 |-> X
    );

// All A inputs high force X high.
    check_all_a_high_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 && A2 && A3 && A4) |-> X
    );

// With B1 low, any low A input forces X low.
    check_b1_low_and_missing_a_forces_x_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!B1 && (!A1 || !A2 || !A3 || !A4)) |-> !X
    );

// If X is high without B1, all A inputs must be high.
    check_x_high_without_b1_requires_all_a_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (X && !B1) |-> (A1 && A2 && A3 && A4)
    );

// A low X requires B1 low and the A AND term low.
    check_x_low_requires_b1_low_and_a_term_low: assert property (
        @(posedge clk) disable iff (1'b0)
        !X |-> (!B1 && (!A1 || !A2 || !A3 || !A4))
    );

// Purely combinational DUT with no native clock or reset; sample on clk.

    // Y matches the implemented gate function.
    check_output_function: assert property (
        @(posedge clk) Y == (C & ~(A & B))
    );

// C low forces the output low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) !C |-> !Y
    );

// A and B high force the output low.
    check_ab_high_forces_y_low: assert property (
        @(posedge clk) (A && B) |-> !Y
    );

// With C high, A low forces the output high.
    check_c_high_a_low_forces_y_high: assert property (
        @(posedge clk) (C && !A) |-> Y
    );

// With C high, B low forces the output high.
    check_c_high_b_low_forces_y_high: assert property (
        @(posedge clk) (C && !B) |-> Y
    );

// A high output requires C to be high.
    check_y_high_requires_c_high: assert property (
        @(posedge clk) Y |-> C
    );

// A high output means A and B are not both high.
    check_y_high_excludes_ab_high: assert property (
        @(posedge clk) Y |-> !(A && B)
    );

// With C high, a low output implies A and B are both high.
    check_c_high_y_low_requires_ab_high: assert property (
        @(posedge clk) (C && !Y) |-> (A && B)
    );

// If EN is low, the gated clock output is low on the next rising edge.
    check_disable_clears_output: assert property (
        @(posedge CLK) disable iff (1'b0) (!EN) |=> (ENCLK == 1'b0)
    );

// If EN and TE are high, the gated clock output is high on the next rising edge.
    check_test_enable_sets_output: assert property (
        @(posedge CLK) disable iff (1'b0) (EN && TE) |=> (ENCLK == 1'b1)
    );

// The mux output must match the currently selected input slice.
    check_mux_mapping: assert property (
        @(posedge clk)
        ((sel === 2'b00) ? (out === a[1:0]) :
         (sel === 2'b01) ? (out === b[1:0]) :
         (sel === 2'b10) ? (out === c[1:0]) :
         (sel === 2'b11) ? (out === d[1:0]) :
         1'b1)
    );

// sel=00 selects a[1:0].
    check_select_a: assert property (
        @(posedge clk) (sel === 2'b00) |-> (out === a[1:0])
    );

// sel=01 selects b[1:0].
    check_select_b: assert property (
        @(posedge clk) (sel === 2'b01) |-> (out === b[1:0])
    );

// sel=10 selects c[1:0].
    check_select_c: assert property (
        @(posedge clk) (sel === 2'b10) |-> (out === c[1:0])
    );

// sel=11 selects d[1:0].
    check_select_d: assert property (
        @(posedge clk) (sel === 2'b11) |-> (out === d[1:0])
    );

// Reset clears the counter to zero by the next clock sample.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled outside reset, count increments by one modulo 16.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'b0001))
    );

// When disabled outside reset, count holds its previous value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Enabling at the maximum value wraps the counter to zero.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hf)) |=> (count == 4'h0)
    );

// Output matches the RTL shift/subtract implementation.
    check_output_chain: assert property (
        @(posedge clk)
        o_data0 == (((((i_data0 << 2) - i_data0) << 7) - i_data0) << 2)
    );

// Output also matches the equivalent 1532*x shift/add form.
    check_output_simplified: assert property (
        @(posedge clk)
        o_data0 == ((i_data0 << 10) + (i_data0 << 9) - (i_data0 << 2))
    );

// Final left shift by 2 forces the two LSBs low.
    check_output_low_bits_zero: assert property (
        @(posedge clk)
        o_data0[1:0] == 2'b00
    );

// Zero input must produce zero output.
    check_zero_input_zero_output: assert property (
        @(posedge clk)
        (i_data0 == 32'h00000000) |-> (o_data0 == 32'h00000000)
    );

// Inputs divisible by 4 produce outputs divisible by 16.
    check_input_multiple_of_4_output_multiple_of_16: assert property (
        @(posedge clk)
        (i_data0[1:0] == 2'b00) |-> (o_data0[3:0] == 4'b0000)
    );

// Inputs with only the top two bits set map to zero.
    check_top_bits_only_input_zero_output: assert property (
        @(posedge clk)
        (i_data0[29:0] == 30'b0) |-> (o_data0 == 32'h00000000)
    );

// When A owns, B sees no ack/err and a permanent stall.
    check_a_owner_blocks_b_return_channel: assert property (
        @(posedge i_clk) disable iff (i_rst)
        r_a_owner |-> ((o_b_ack == 1'b0) && (o_b_err == 1'b0) && (o_b_stall == 1'b1))
    );

// B ownership routes the slave return channel directly to B.
    check_b_owner_routes_return_channel_direct: assert property (
        @(posedge i_clk) disable iff (i_rst)
        (!r_a_owner) |-> ((o_b_ack == i_ack) && (o_b_stall == i_stall) && (o_b_err == i_err))
    );

// X must implement A OR not SLEEP_B.
    check_output_matches_or_function: assert property (
        @(posedge clk) X == (A | ~SLEEP_B)
    );

// When awake, X must pass A.
    check_awake_mode_passes_input: assert property (
        @(posedge clk) SLEEP_B |-> (X == A)
    );

// When sleep is asserted low, X must be forced high.
    check_sleep_mode_forces_high: assert property (
        @(posedge clk) !SLEEP_B |-> (X == 1'b1)
    );

// A high must force X high.
    check_high_input_forces_high_output: assert property (
        @(posedge clk) A |-> (X == 1'b1)
    );

// The only low-output case is A low while awake.
    check_low_output_case: assert property (
        @(posedge clk) (!A && SLEEP_B) |-> (X == 1'b0)
    );

// C=2'b10 selects A^B, registered to out on the next cycle.
    check_c10_selects_xor_next_cycle: assert property (
        @(posedge clk)
        (C === 2'b10) |=> (out === ($past(A) ^ $past(B)))
    );

// C=2'b01 selects B, registered to out on the next cycle.
    check_c01_selects_b_next_cycle: assert property (
        @(posedge clk)
        (C === 2'b01) |=> (out === $past(B))
    );

// All other C values select A, registered to out on the next cycle.
    check_default_selects_a_next_cycle: assert property (
        @(posedge clk)
        ((C !== 2'b10) && (C !== 2'b01)) |=> (out === $past(A))
    );

// out always matches the prior cycle's selected value.
    check_out_matches_delayed_selected_value: assert property (
        @(posedge clk)
        1'b1 |=> (
            (($past(C) === 2'b10) && (out === ($past(A) ^ $past(B)))) ||
            (($past(C) === 2'b01) && (out === $past(B))) ||
            (($past(C) !== 2'b10) && ($past(C) !== 2'b01) && (out === $past(A)))
        )
    );

// out holds when the current selected value already equals out.
    check_out_holds_when_selected_value_repeats: assert property (
        @(posedge clk)
        (((C === 2'b10) && ((A ^ B) === out)) ||
         ((C === 2'b01) && (B === out)) ||
         ((C !== 2'b10) && (C !== 2'b01) && (A === out)))
        |=> (out === $past(out))
    );

// out changes when the current selected value differs from out.
    check_out_changes_when_selected_value_differs: assert property (
        @(posedge clk)
        (((C === 2'b10) && ((A ^ B) !== out)) ||
         ((C === 2'b01) && (B !== out)) ||
         ((C !== 2'b10) && (C !== 2'b01) && (A !== out)))
        |=> (out !== $past(out))
    );

// Reset clears the counter by the next clock sample.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 3'b000)
    );

// When disabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> $stable(count)
    );

// When enabled from 0, the counter increments to 1.
    check_increment_000_to_001: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b000) |=> (count == 3'b001)
    );

// When enabled from 1, the counter increments to 2.
    check_increment_001_to_010: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b001) |=> (count == 3'b010)
    );

// When enabled from 2, the counter increments to 3.
    check_increment_010_to_011: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b010) |=> (count == 3'b011)
    );

// When enabled from 3, the counter increments to 4.
    check_increment_011_to_100: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b011) |=> (count == 3'b100)
    );

// When enabled from 4, the counter increments to 5.
    check_increment_100_to_101: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b100) |=> (count == 3'b101)
    );

// When enabled from 5, the counter increments to 6.
    check_increment_101_to_110: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b101) |=> (count == 3'b110)
    );

// When enabled from 6, the counter increments to 7.
    check_increment_110_to_111: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b110) |=> (count == 3'b111)
    );

// When enabled from 7, the counter wraps to 0.
    check_increment_111_to_000: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 3'b111) |=> (count == 3'b000)
    );

// Reset clears all pipeline outputs on the next cycle.
    check_reset_clears_pipeline: assert property (
        @(posedge CLK) CLR |=> (Q0 == 4'b0000) && (Q1 == 4'b0000) && (Q2 == 4'b0000) && (Q3 == 4'b0000)
    );

// A load cycle captures DATA into Q0 on the next cycle.
    check_load_captures_data_to_q0: assert property (
        @(posedge CLK) disable iff (CLR) LD |=> (Q0 == $past(DATA))
    );

// A count cycle updates Q0 from the previous Q3 plus one.
    check_count_advances_q0_from_q3: assert property (
        @(posedge CLK) disable iff (CLR) !LD |=> (Q0 == ($past(Q3) + 4'b0001))
    );

// Q1 shifts in the previous Q0 whenever reset is not active.
    check_q1_shifts_previous_q0: assert property (
        @(posedge CLK) disable iff (CLR) 1'b1 |=> (Q1 == $past(Q0))
    );

// Q2 shifts in the previous Q1 whenever reset is not active.
    check_q2_shifts_previous_q1: assert property (
        @(posedge CLK) disable iff (CLR) 1'b1 |=> (Q2 == $past(Q1))
    );

// Q3 shifts in the previous Q2 whenever reset is not active.
    check_q3_shifts_previous_q2: assert property (
        @(posedge CLK) disable iff (CLR) 1'b1 |=> (Q3 == $past(Q2))
    );

// max_val matches the RTL max function.
    check_max_function: assert property (
        @(posedge clk) max_val == ((a >= b) ? a : b)
    );

// When a is at least b, max_val selects a.
    check_select_a_when_a_ge_b: assert property (
        @(posedge clk) (a >= b) |-> (max_val == a)
    );

// When b is greater than a, max_val selects b.
    check_select_b_when_b_gt_a: assert property (
        @(posedge clk) (a < b) |-> (max_val == b)
    );

// max_val is never smaller than a.
    check_max_not_less_than_a: assert property (
        @(posedge clk) max_val >= a
    );

// max_val is never smaller than b.
    check_max_not_less_than_b: assert property (
        @(posedge clk) max_val >= b
    );

// max_val must equal one of the inputs.
    check_max_matches_input: assert property (
        @(posedge clk) (max_val == a) || (max_val == b)
    );

// Equal inputs pass through unchanged.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (max_val == a)
    );

// Combinational DUT sampled on clk; the RTL has no reset.

    // valid must match the RTL expression exactly.
    check_valid_definition: assert property (
        @(posedge clk) disable iff (1'b0)
            valid == (((tuple[0] ^ tuple[1]) == tuple[2]) &&
                      ((tuple[1] ^ tuple[2]) == tuple[0]) &&
                      ((tuple[0] ^ tuple[2]) == tuple[1]))
    );

// valid is high exactly for even-parity tuples.
    check_valid_even_parity: assert property (
        @(posedge clk) disable iff (1'b0)
            valid == (~^tuple)
    );

// A high valid requires tuple[0] ^ tuple[1] to equal tuple[2].
    check_valid_implies_xor01_eq_2: assert property (
        @(posedge clk) disable iff (1'b0)
            valid |-> ((tuple[0] ^ tuple[1]) == tuple[2])
    );

// A high valid requires tuple[1] ^ tuple[2] to equal tuple[0].
    check_valid_implies_xor12_eq_0: assert property (
        @(posedge clk) disable iff (1'b0)
            valid |-> ((tuple[1] ^ tuple[2]) == tuple[0])
    );

// A high valid requires tuple[0] ^ tuple[2] to equal tuple[1].
    check_valid_implies_xor02_eq_1: assert property (
        @(posedge clk) disable iff (1'b0)
            valid |-> ((tuple[0] ^ tuple[2]) == tuple[1])
    );

// tuple[0] ^ tuple[1] matching tuple[2] is sufficient for valid.
    check_xor01_eq_2_implies_valid: assert property (
        @(posedge clk) disable iff (1'b0)
            ((tuple[0] ^ tuple[1]) == tuple[2]) |-> valid
    );

// tuple[1] ^ tuple[2] matching tuple[0] is sufficient for valid.
    check_xor12_eq_0_implies_valid: assert property (
        @(posedge clk) disable iff (1'b0)
            ((tuple[1] ^ tuple[2]) == tuple[0]) |-> valid
    );

// tuple[0] ^ tuple[2] matching tuple[1] is sufficient for valid.
    check_xor02_eq_1_implies_valid: assert property (
        @(posedge clk) disable iff (1'b0)
            ((tuple[0] ^ tuple[2]) == tuple[1]) |-> valid
    );

// Q captures a high D value by the next clock sample.
    check_q_captures_high_d: assert property (
        @(posedge CLK) D |=> Q
    );

// Q captures a low D value by the next clock sample.
    check_q_captures_low_d: assert property (
        @(posedge CLK) !D |=> !Q
    );

// Q_N is always the inverse of Q.
    check_qn_inverts_q: assert property (
        @(posedge CLK) Q_N == ~Q
    );

// Q remains unchanged when D already matches Q.
    check_q_stable_when_d_matches_q: assert property (
        @(posedge CLK) (D == Q) |=> $stable(Q)
    );

// Q changes when D differs from Q.
    check_q_updates_when_d_differs_q: assert property (
        @(posedge CLK) (D != Q) |=> !$stable(Q)
    );

// Q_N goes low after a high D value is captured.
    check_qn_after_high_d: assert property (
        @(posedge CLK) D |=> !Q_N
    );

// Q_N goes high after a low D value is captured.
    check_qn_after_low_d: assert property (
        @(posedge CLK) !D |=> Q_N
    );

// The 5-bit output must equal a + b + cin.
    check_total_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0000, cin})
    );

// Bit 0 sum matches the first full-adder XOR result.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ fa_carry(a[0], b[0], cin))
    );

// Bit 2 sum uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (a[2] ^ b[2] ^ fa_carry(a[1], b[1], fa_carry(a[0], b[0], cin)))
    );

// Bit 3 sum uses the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (a[3] ^ b[3] ^ fa_carry(a[2], b[2], fa_carry(a[1], b[1], fa_carry(a[0], b[0], cin))))
    );

// Carry out matches the final full-adder carry.
    check_cout_equation: assert property (
        @(posedge clk) cout == fa_carry(a[3], b[3], fa_carry(a[2], b[2], fa_carry(a[1], b[1], fa_carry(a[0], b[0], cin))))
    );

// Adding zero on b reduces to a plus cin.
    check_add_zero_on_b: assert property (
        @(posedge clk) (b == 4'b0000) |-> ({cout, sum} == ({1'b0, a} + {4'b0000, cin}))
    );

// Adding zero on a reduces to b plus cin.
    check_add_zero_on_a: assert property (
        @(posedge clk) (a == 4'b0000) |-> ({cout, sum} == ({1'b0, b} + {4'b0000, cin}))
    );

// Complementary operands with cin low produce all ones and no carry.
    check_complement_no_carryin: assert property (
        @(posedge clk) ((b == ~a) && (cin == 1'b0)) |-> ({cout, sum} == 5'b0_1111)
    );

// Complementary operands with cin high produce zero and a carry.
    check_complement_with_carryin: assert property (
        @(posedge clk) ((b == ~a) && (cin == 1'b1)) |-> ({cout, sum} == 5'b1_0000)
    );

// gray_out must equal the prior cycle's binary input converted to Gray code.
    check_gray_vector: assert property (
        @(posedge clk)
        1'b1 |=> gray_out == {
            $past(binary_in[3]),
            ($past(binary_in[3]) ^ $past(binary_in[2])),
            ($past(binary_in[2]) ^ $past(binary_in[1])),
            ($past(binary_in[1]) ^ $past(binary_in[0]))
        }
    );

// gray_out[3] must copy the prior cycle's binary_in[3].
    check_gray_msb: assert property (
        @(posedge clk)
        1'b1 |=> gray_out[3] == $past(binary_in[3])
    );

// gray_out[2] must be the prior cycle XOR of binary_in[3] and binary_in[2].
    check_gray_bit2: assert property (
        @(posedge clk)
        1'b1 |=> gray_out[2] == ($past(binary_in[3]) ^ $past(binary_in[2]))
    );

// gray_out[1] must be the prior cycle XOR of binary_in[2] and binary_in[1].
    check_gray_bit1: assert property (
        @(posedge clk)
        1'b1 |=> gray_out[1] == ($past(binary_in[2]) ^ $past(binary_in[1]))
    );

// gray_out[0] must be the prior cycle XOR of binary_in[1] and binary_in[0].
    check_gray_lsb: assert property (
        @(posedge clk)
        1'b1 |=> gray_out[0] == ($past(binary_in[1]) ^ $past(binary_in[0]))
    );

// X matches the 3-input XNOR of A, B, and C.
    check_xnor3_function: assert property (
        @(posedge clk) X === ~(A ^ B ^ C)
    );

// With C low, X reduces to the XNOR of A and B.
    check_c_low_reduces_to_ab_xnor: assert property (
        @(posedge clk) (C == 1'b0) |-> (X === ~(A ^ B))
    );

// With C high, X reduces to the XOR of A and B.
    check_c_high_reduces_to_ab_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (X === (A ^ B))
    );

// When A and B are equal, X is the inversion of C.
    check_ab_equal_inverts_c: assert property (
        @(posedge clk) (A == B) |-> (X === ~C)
    );

// When A and B differ, X follows C.
    check_ab_different_follows_c: assert property (
        @(posedge clk) (A != B) |-> (X === C)
    );

// When B and C are equal, X is the inversion of A.
    check_bc_equal_inverts_a: assert property (
        @(posedge clk) (B == C) |-> (X === ~A)
    );

// When B and C differ, X follows A.
    check_bc_different_follows_a: assert property (
        @(posedge clk) (B != C) |-> (X === A)
    );

// When A and C are equal, X is the inversion of B.
    check_ac_equal_inverts_b: assert property (
        @(posedge clk) (A == C) |-> (X === ~B)
    );

// When A and C differ, X follows B.
    check_ac_different_follows_b: assert property (
        @(posedge clk) (A != C) |-> (X === B)
    );

// All-zero inputs must produce a high output.
    check_all_zero_case: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && C == 1'b0) |-> (X === 1'b1)
    );

// All-one inputs must produce a low output.
    check_all_one_case: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && C == 1'b1) |-> (X === 1'b0)
    );

// out is the 4-bit sum of in1 and in2.
    check_out_matches_sum: assert property (
        @(posedge clk) out == (in1 + in2)
    );

// max_out follows the RTL max expression using out and the sum.
    check_max_out_matches_rtl_max_expr: assert property (
        @(posedge clk) max_out == ((out > (in1 + in2)) ? out : (in1 + in2))
    );

// Since out is assigned from the sum, max_out must equal out.
    check_max_out_equals_out: assert property (
        @(posedge clk) max_out == out
    );

// max_out also equals the computed 4-bit sum.
    check_max_out_matches_sum: assert property (
        @(posedge clk) max_out == (in1 + in2)
    );

// Output matches the selected shift operation for all control values.
    check_functional_mapping: assert property (
        @(posedge clk)
        out == ((ctrl == 2'b00) ? {in[2:0], 1'b0} :
                (ctrl == 2'b01) ? {in[1:0], 2'b00} :
                (ctrl == 2'b10) ? {1'b0, in[3:1]} :
                                  {2'b00, in[3:2]})
    );

// ctrl 00 shifts left by 1 with zero fill.
    check_ctrl_00_shift_left_1: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (out == {in[2:0], 1'b0})
    );

// ctrl 01 shifts left by 2 with zero fill.
    check_ctrl_01_shift_left_2: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (out == {in[1:0], 2'b00})
    );

// ctrl 10 shifts right by 1 with zero fill.
    check_ctrl_10_shift_right_1: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (out == {1'b0, in[3:1]})
    );

// ctrl 11 shifts right by 2 with zero fill.
    check_ctrl_11_shift_right_2: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (out == {2'b00, in[3:2]})
    );

// X must equal the AND of A and SLEEP_B.
    check_x_matches_and: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// X must be low when isolation is active.
    check_x_low_when_sleep_b_low: assert property (
        @(posedge clk) !SLEEP_B |-> (X == 1'b0)
    );

// X must be low when A is low.
    check_x_low_when_a_low: assert property (
        @(posedge clk) !A |-> (X == 1'b0)
    );

// X must be high when both inputs are high.
    check_x_high_when_both_inputs_high: assert property (
        @(posedge clk) (A && SLEEP_B) |-> (X == 1'b1)
    );

// A high X requires both inputs to be high.
    check_x_high_requires_both_inputs: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// A sampled reset must leave the output cleared by the next clock.
    check_reset_clears_motor_speed: assert property (
        @(posedge clk) reset |=> (motor_speed == 8'd0)
    );

// Low-range inputs are scaled by 7 bits on the following cycle.
    check_low_range_scaling: assert property (
        @(posedge clk) disable iff (reset)
        (input_signal <= 16'd32767) |=> (motor_speed == $past(input_signal[14:7]))
    );

// High-range inputs are scaled by 8 bits on the following cycle.
    check_high_range_scaling: assert property (
        @(posedge clk) disable iff (reset)
        (input_signal > 16'd32767) |=> (motor_speed == $past(input_signal[15:8]))
    );

// The low-range threshold value maps to full-scale output.
    check_low_range_boundary: assert property (
        @(posedge clk) disable iff (reset)
        (input_signal == 16'h7FFF) |=> (motor_speed == 8'hFF)
    );

// The first high-range value maps to 0x80.
    check_high_range_boundary: assert property (
        @(posedge clk) disable iff (reset)
        (input_signal == 16'h8000) |=> (motor_speed == 8'h80)
    );

// DUT is combinational; clk is only used for assertion sampling.

    // Sum matches the XOR of all three inputs.
    check_sum_function: assert property (
        @(posedge clk) s === (a ^ b ^ cin)
    );

// Carry-out matches the implemented full-adder carry equation.
    check_cout_function: assert property (
        @(posedge clk) cout === (((a ^ b) & cin) | (a & b))
    );

// With cin low, sum reduces to the half-adder sum of a and b.
    check_half_adder_sum_when_cin_low: assert property (
        @(posedge clk) !cin |-> (s === (a ^ b))
    );

// With cin low, carry reduces to the half-adder carry of a and b.
    check_half_adder_carry_when_cin_low: assert property (
        @(posedge clk) !cin |-> (cout === (a & b))
    );

// With cin high, sum is the inverse of a XOR b.
    check_sum_when_cin_high: assert property (
        @(posedge clk) cin |-> (s === ~(a ^ b))
    );

// With cin high, carry-out is the OR of a and b.
    check_carry_when_cin_high: assert property (
        @(posedge clk) cin |-> (cout === (a | b))
    );

// When a and b are equal, the sum output follows cin.
    check_sum_when_inputs_equal: assert property (
        @(posedge clk) (a == b) |-> (s === cin)
    );

// When a and b differ, the carry output follows cin.
    check_carry_when_inputs_differ: assert property (
        @(posedge clk) (a != b) |-> (cout === cin)
    );

// full and emptyp can never be high together.
    check_flags_mutex: assert property (
        @(posedge clk) disable iff (!rst) !(full && emptyp)
    );

// Idle cycles keep both flags unchanged.
    check_idle_holds_flags: assert property (
        @(posedge clk) disable iff (!rst)
        (!wr_en && !rd_en) |=> ($stable(full) && $stable(emptyp))
    );

// Simultaneous read and write keep both flags unchanged.
    check_simul_rw_holds_flags: assert property (
        @(posedge clk) disable iff (!rst)
        (wr_en && rd_en) |=> ($stable(full) && $stable(emptyp))
    );

// When empty, no-write cycles keep emptyp asserted.
    check_empty_without_write_stays_empty: assert property (
        @(posedge clk) disable iff (!rst)
        (emptyp && !wr_en) |=> (emptyp && !full)
    );

// A write-only cycle from empty clears emptyp.
    check_empty_write_only_clears_empty: assert property (
        @(posedge clk) disable iff (!rst)
        (emptyp && wr_en && !rd_en) |=> (!emptyp && !full)
    );

// When full, no-read cycles keep full asserted.
    check_full_without_read_stays_full: assert property (
        @(posedge clk) disable iff (!rst)
        (full && !rd_en) |=> (full && !emptyp)
    );

// A read-only cycle from full clears full.
    check_full_read_only_clears_full: assert property (
        @(posedge clk) disable iff (!rst)
        (full && rd_en && !wr_en) |=> (!full && !emptyp)
    );

// emptyp can only fall after an empty write-only cycle.
    check_empty_fall_requires_write_only: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(rst) && $fell(emptyp)) |-> $past(emptyp && wr_en && !rd_en)
    );

// full can only fall after a full read-only cycle.
    check_full_fall_requires_read_only: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(rst) && $fell(full)) |-> $past(full && rd_en && !wr_en)
    );

// When op is 0, result must be the signed sum of a and b.
    check_add_operation: assert property (
        @(posedge clk)
        (op === 1'b0) |-> (result == ($signed(a) + $signed(b)))
    );

// When op is not 0, result must be the signed difference of a and b.
    check_sub_operation: assert property (
        @(posedge clk)
        (op !== 1'b0) |-> (result == ($signed(a) - $signed(b)))
    );

// SEL=00 selects the sum result.
    check_select_sum: assert property (
        @(posedge clk) (SEL == 2'b00) |-> (OUT === sum)
    );

// SEL=01 selects the difference result.
    check_select_diff: assert property (
        @(posedge clk) (SEL == 2'b01) |-> (OUT === diff)
    );

// No reset in RTL; sample combinational behavior on clk.

    // EQ matches the selected input compared against B.
    check_eq_function: assert property (
        @(posedge clk) EQ == (enable ? 1'b1 : (A == B))
    );

// GT matches the selected input compared against B.
    check_gt_function: assert property (
        @(posedge clk) GT == (enable ? 1'b0 : (A > B))
    );

// OR is the OR of the comparator outputs.
    check_or_combination: assert property (
        @(posedge clk) OR == (EQ | GT)
    );

// EQ and GT cannot both be high at the same time.
    check_compare_mutex: assert property (
        @(posedge clk) !(EQ && GT)
    );

// When enable is high, the mux selects B so the compare is B vs B.
    check_enable_selects_b: assert property (
        @(posedge clk) enable |-> (EQ && !GT && OR)
    );

// When enable is low and A is less than B, all compare outputs are low.
    check_disable_less_than_case: assert property (
        @(posedge clk) (!enable && (A < B)) |-> (!EQ && !GT && !OR)
    );

// When enable is low and A equals B, EQ and OR are high and GT is low.
    check_disable_equal_case: assert property (
        @(posedge clk) (!enable && (A == B)) |-> (EQ && !GT && OR)
    );

// When enable is low and A is greater than B, GT and OR are high and EQ is low.
    check_disable_greater_than_case: assert property (
        @(posedge clk) (!enable && (A > B)) |-> (!EQ && GT && OR)
    );

// Load captures data into q on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

// With ena=00 and no load, q holds its previous value.
    check_hold_when_ena_zero: assert property (
        @(posedge clk) (!load && (ena == 2'b00)) |=> (q == $past(q))
    );

// With ena=01 and no load, q rotates left by one bit.
    check_rotate_left: assert property (
        @(posedge clk) (!load && (ena == 2'b01)) |=> (q == { $past(q[98:0]), $past(q[99]) })
    );

// With ena=10 and no load, q rotates right by one bit.
    check_rotate_right: assert property (
        @(posedge clk) (!load && (ena == 2'b10)) |=> (q == { $past(q[0]), $past(q[99:1]) })
    );

// With ena=11 and no load, q holds because no assignment occurs.
    check_hold_when_ena_three: assert property (
        @(posedge clk) (!load && (ena == 2'b11)) |=> (q == $past(q))
    );

// A left rotation followed by a right rotation restores q.
    check_left_then_right_restore: assert property (
        @(posedge clk) (!load && (ena == 2'b01)) ##1 (!load && (ena == 2'b10)) |=> (q == $past(q,2))
    );

// A right rotation followed by a left rotation restores q.
    check_right_then_left_restore: assert property (
        @(posedge clk) (!load && (ena == 2'b10)) ##1 (!load && (ena == 2'b01)) |=> (q == $past(q,2))
    );

// The output vector updates as a shift register driven only by the previous in[0].
    check_output_vector_update: assert property (
        @(posedge clk) 1'b1 |=> out == { $past(in[0]), $past(out[99:1]) }
    );

// The output MSB captures the previous cycle value of in[0].
    check_output_msb_from_input0: assert property (
        @(posedge clk) 1'b1 |=> out[99] == $past(in[0])
    );

// The lower 99 output bits shift from the previous cycle's higher output bits.
    check_output_lower_bits_shift: assert property (
        @(posedge clk) 1'b1 |=> out[98:0] == $past(out[99:1])
    );

// EN low forces ENCLK low.
    check_en_low_forces_enclk_low: assert property (
        @(posedge CLK) !EN |-> !ENCLK
    );

// ENCLK can only be high when EN is high.
    check_enclk_high_requires_en: assert property (
        @(posedge CLK) ENCLK |-> EN
    );

// When TE is high, the next-cycle ENCLK reflects the captured EN value.
    check_capture_when_te: assert property (
        @(posedge CLK) TE |=> (ENCLK == (EN ? $past(EN) : 1'b0))
    );

// With EN high and TE low, ENCLK holds if EN stays high.
    check_hold_when_te_low_and_enabled: assert property (
        @(posedge CLK) (EN && !TE) |=> (!EN || (ENCLK == $past(ENCLK)))
    );

// RTL has no clock or reset; clk is an external sampling clock.

    // Output equals the bitwise AND of the two inputs.
    check_out_matches_bitwise_and: assert property (
        @(posedge clk) out == (A & B)
    );

// A value of zero forces the output to zero.
    check_zero_a_forces_zero_out: assert property (
        @(posedge clk) (A == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

// B value of zero forces the output to zero.
    check_zero_b_forces_zero_out: assert property (
        @(posedge clk) (B == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

// All ones on A makes the output follow B.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (A == 32'hFFFF_FFFF) |-> (out == B)
    );

// All ones on B makes the output follow A.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |-> (out == A)
    );

// Any high output bit must also be high in A.
    check_output_ones_subset_of_a: assert property (
        @(posedge clk) ((out & ~A) == 32'h0000_0000)
    );

// Any high output bit must also be high in B.
    check_output_ones_subset_of_b: assert property (
        @(posedge clk) ((out & ~B) == 32'h0000_0000)
    );

// Equal inputs pass through unchanged to the output.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A == B) |-> (out == A)
    );

// Reset drives gray_out to 0000 on the following clock.
    check_reset_drives_zero: assert property (
        @(posedge clk) rst |=> (gray_out == 4'b0000)
    );

// 0000 advances to 0001.
    check_gray_0000_to_0001: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0000) |=> (gray_out == 4'b0001)
    );

// 0001 advances to 0011.
    check_gray_0001_to_0011: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0001) |=> (gray_out == 4'b0011)
    );

// 0011 advances to 0010.
    check_gray_0011_to_0010: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0011) |=> (gray_out == 4'b0010)
    );

// 0010 advances to 0110.
    check_gray_0010_to_0110: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0010) |=> (gray_out == 4'b0110)
    );

// 0110 advances to 0111.
    check_gray_0110_to_0111: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0110) |=> (gray_out == 4'b0111)
    );

// 0111 advances to 0101.
    check_gray_0111_to_0101: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0111) |=> (gray_out == 4'b0101)
    );

// 0101 advances to 0100.
    check_gray_0101_to_0100: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0101) |=> (gray_out == 4'b0100)
    );

// 0100 advances to 1100.
    check_gray_0100_to_1100: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b0100) |=> (gray_out == 4'b1100)
    );

// 1100 advances to 1101.
    check_gray_1100_to_1101: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1100) |=> (gray_out == 4'b1101)
    );

// 1101 advances to 1111.
    check_gray_1101_to_1111: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1101) |=> (gray_out == 4'b1111)
    );

// 1111 advances to 1110.
    check_gray_1111_to_1110: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1111) |=> (gray_out == 4'b1110)
    );

// 1110 advances to 1010.
    check_gray_1110_to_1010: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1110) |=> (gray_out == 4'b1010)
    );

// 1010 advances to 1011.
    check_gray_1010_to_1011: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1010) |=> (gray_out == 4'b1011)
    );

// 1011 advances to 1001.
    check_gray_1011_to_1001: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1011) |=> (gray_out == 4'b1001)
    );

// 1001 advances to 1000.
    check_gray_1001_to_1000: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1001) |=> (gray_out == 4'b1000)
    );

// 1000 wraps to 0000.
    check_gray_1000_to_0000: assert property (
        @(posedge clk) disable iff (rst) (gray_out == 4'b1000) |=> (gray_out == 4'b0000)
    );

// set drives q high on the next clock.
    check_set_forces_q_high: assert property (
        @(posedge clk) set |=> (q == 1'b1)
    );

// set has priority over clr when both are high.
    check_set_overrides_clear: assert property (
        @(posedge clk) (set && clr) |=> (q == 1'b1)
    );

// clr drives q low when set is not asserted.
    check_clear_forces_q_low: assert property (
        @(posedge clk) (!set && clr) |=> (q == 1'b0)
    );

// d=1 is captured when neither set nor clr is asserted.
    check_data_one_captured: assert property (
        @(posedge clk) (!set && !clr && d) |=> (q == 1'b1)
    );

// d=0 is captured when neither set nor clr is asserted.
    check_data_zero_captured: assert property (
        @(posedge clk) (!set && !clr && !d) |=> (q == 1'b0)
    );

// RGB outputs are forced to zero when either sync is high.
    check_rgb_zero_when_sync_not_both_low: assert property (
        @(posedge clk) disable iff (rst)
        !(hsync == 1'b0 && vsync == 1'b0)
        |=> (r == 8'h00 && g == 8'h00 && b == 8'h00)
    );

// Result matches the full comparator function.
    check_complete_result_mapping: assert property (
        @(posedge clk) res == ((a > b) ? 2'b01 : ((a < b) ? 2'b10 : 2'b11))
    );

// Greater-than case produces 01.
    check_gt_result_encoding: assert property (
        @(posedge clk) (a > b) |-> (res == 2'b01)
    );

// Less-than case produces 10.
    check_lt_result_encoding: assert property (
        @(posedge clk) (a < b) |-> (res == 2'b10)
    );

// Equality case produces 11.
    check_eq_result_encoding: assert property (
        @(posedge clk) (a == b) |-> (res == 2'b11)
    );

// Result 01 only occurs when a is greater than b.
    check_result_01_implies_gt: assert property (
        @(posedge clk) (res == 2'b01) |-> (a > b)
    );

// Result 10 only occurs when a is less than b.
    check_result_10_implies_lt: assert property (
        @(posedge clk) (res == 2'b10) |-> (a < b)
    );

// Result 11 only occurs when a equals b.
    check_result_11_implies_eq: assert property (
        @(posedge clk) (res == 2'b11) |-> (a == b)
    );

// The RTL never drives the unused 00 encoding.
    check_result_never_zero: assert property (
        @(posedge clk) res != 2'b00
    );

// X matches the implemented OR-then-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (B1 & (A1 | A2 | A3 | A4))
    );

// B1 low forces the output low.
    check_b1_gates_output_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// No asserted A input forces the output low.
    check_all_a_low_forces_x_low: assert property (
        @(posedge clk) !(A1 | A2 | A3 | A4) |-> !X
    );

// A high output requires B1 to be high.
    check_x_high_requires_b1: assert property (
        @(posedge clk) X |-> B1
    );

// A high output requires at least one A input high.
    check_x_high_requires_any_a: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3 | A4)
    );

// A1 can drive the output high when B1 is high.
    check_a1_path_to_x: assert property (
        @(posedge clk) (B1 & A1) |-> X
    );

// A2 can drive the output high when B1 is high.
    check_a2_path_to_x: assert property (
        @(posedge clk) (B1 & A2) |-> X
    );

// A3 can drive the output high when B1 is high.
    check_a3_path_to_x: assert property (
        @(posedge clk) (B1 & A3) |-> X
    );

// A4 can drive the output high when B1 is high.
    check_a4_path_to_x: assert property (
        @(posedge clk) (B1 & A4) |-> X
    );

// Output matches the RTL AND expression.
    check_out_matches_and: assert property (
        @(posedge clk) out === ((a & b) ? 1'b1 : 1'b0)
    );

// Both high inputs drive the output high.
    check_out_high_when_both_high: assert property (
        @(posedge clk) ((a === 1'b1) && (b === 1'b1)) |-> (out === 1'b1)
    );

// A low on input a forces the output low.
    check_out_low_when_a_low: assert property (
        @(posedge clk) (a === 1'b0) |-> (out === 1'b0)
    );

// A low on input b forces the output low.
    check_out_low_when_b_low: assert property (
        @(posedge clk) (b === 1'b0) |-> (out === 1'b0)
    );

// A high output requires both inputs high.
    check_out_high_only_if_both_high: assert property (
        @(posedge clk) (out === 1'b1) |-> ((a === 1'b1) && (b === 1'b1))
    );

// When disabled, the output is forced low.
    check_disable_forces_low: assert property (
        @(posedge clk) !enable |-> (out == 1'b0)
    );

// When enabled and select is 00, output matches data_in[0].
    check_select_00_routes_bit0: assert property (
        @(posedge clk) (enable && (select == 2'b00)) |-> (out == data_in[0])
    );

// When enabled and select is 01, output matches data_in[1].
    check_select_01_routes_bit1: assert property (
        @(posedge clk) (enable && (select == 2'b01)) |-> (out == data_in[1])
    );

// When enabled and select is 10, output matches data_in[2].
    check_select_10_routes_bit2: assert property (
        @(posedge clk) (enable && (select == 2'b10)) |-> (out == data_in[2])
    );

// When enabled and select is 11, output matches data_in[3].
    check_select_11_routes_bit3: assert property (
        @(posedge clk) (enable && (select == 2'b11)) |-> (out == data_in[3])
    );

// A load updates serial_out to the loaded LSB on the next cycle.
    check_load_updates_serial_lsb: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (serial_out == $past(load_data[0]))
    );

// One shift after a load moves the loaded MSB to serial_out.
    check_one_shift_outputs_loaded_msb: assert property (
        @(posedge clk) disable iff (reset)
        (load) ##1 (!load) |=> (serial_out == $past(load_data[2], 2))
    );

// Two shifts after a load move the loaded middle bit to serial_out.
    check_two_shifts_output_loaded_mid: assert property (
        @(posedge clk) disable iff (reset)
        (load) ##1 (!load) ##1 (!load) |=> (serial_out == $past(load_data[1], 3))
    );

// Three shifts after a load wrap serial_out back to the loaded LSB.
    check_three_shifts_wrap_to_loaded_lsb: assert property (
        @(posedge clk) disable iff (reset)
        (load) ##1 (!load) ##1 (!load) ##1 (!load) |=> (serial_out == $past(load_data[0], 4))
    );

// Clock: clk
    // Reset: rst, active-high synchronous
    // Logic: sequential delay_reg with combinational next_delay_reg and out

    // next_delay_reg is the shifted version of delay_reg with in loaded into bit 0.
    check_next_delay_reg_wiring: assert property (
        @(posedge clk) disable iff (rst)
        next_delay_reg == {delay_reg[2], delay_reg[1], delay_reg[0], in}
    );

// out always reflects the most significant bit of delay_reg.
    check_out_matches_delay_reg_msb: assert property (
        @(posedge clk) disable iff (rst)
        out == delay_reg[3]
    );

// RTL is combinational with no reset; clk is a sampling clock for these checks.

    // When sel selects a, out must equal a.
    check_select_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == a)
    );

// When sel selects b, out must equal b.
    check_select_b: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == b)
    );

// When sel selects c, out must equal c.
    check_select_c: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == c)
    );

// When sel selects d, out must equal d.
    check_select_d: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == d)
    );

// Clock: clk
    // Reset: areset, async active-high
    // Mixed logic: q1/q2 are sequential, out is combinational

    // Reset forces all state-derived outputs to zero.
    check_reset_clears_state: assert property (
        @(posedge clk)
        areset |-> (q1 == 4'b0000 && q2 == 4'b0000 && out == 4'b0000)
    );

// Load captures data1/data2 into q1/q2 on the next cycle, regardless of ena.
    check_load_captures_q: assert property (
        @(posedge clk) disable iff (areset)
        load |=> (q1 == $past(data1) && q2 == $past(data2))
    );

// Load updates out to the XOR of the loaded internal values.
    check_load_updates_out: assert property (
        @(posedge clk) disable iff (areset)
        load |=> (out == ($past(data1) ^ $past(data2)))
    );

// With ena and no load, q1 and q2 shift left and insert 0 in the LSB.
    check_shift_updates_q: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena) |=> (q1 == {$past(q1[2:0]), 1'b0} &&
                            q2 == {$past(q2[2:0]), 1'b0})
    );

// With ena and no load, out shifts left and inserts 0 in the LSB.
    check_shift_updates_out: assert property (
        @(posedge clk) disable iff (areset)
        (!load && ena) |=> (out == {$past(out[2:0]), 1'b0})
    );

// With neither load nor ena, q1, q2, and out hold their values.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (areset)
        (!load && !ena) |=> (q1 == $past(q1) &&
                             q2 == $past(q2) &&
                             out == $past(out))
    );

// Q clears both registers on the next sampled cycle.
    check_sync_clear: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        Q |=> (out == 12'h000 && O1 == 12'h000)
    );

// Q has priority over sel when both are high.
    check_clear_priority_over_sel: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (Q && sel) |=> (out == 12'h000 && O1 == 12'h000)
    );

// sel increments out when Q is low.
    check_out_increments_on_sel: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (out == ($past(out) + 12'd1))
    );

// sel loads O1 with the previous out value when Q is low.
    check_o1_captures_previous_out: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (O1 == $past(out))
    );

// With Q low and sel low, both registers hold their values.
    check_hold_when_idle: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && !sel) |=> (out == $past(out) && O1 == $past(O1))
    );

// After a sel update, out is exactly one count ahead of O1.
    check_sel_creates_expected_offset: assert property (
        @(posedge rd_clk) disable iff (1'b0)
        (!Q && sel) |=> (out == (O1 + 12'd1))
    );

// in1_hi is the upper nibble of the upper input byte.
    check_in1_hi_slice: assert property (
        @(posedge clk) in1_hi == in[15:12]
    );

// in1_lo is the lower nibble of the upper input byte.
    check_in1_lo_slice: assert property (
        @(posedge clk) in1_lo == in[11:8]
    );

// in2_hi is the upper nibble of the lower input byte.
    check_in2_hi_slice: assert property (
        @(posedge clk) in2_hi == in[7:4]
    );

// in2_lo is the lower nibble of the lower input byte.
    check_in2_lo_slice: assert property (
        @(posedge clk) in2_lo == in[3:0]
    );

// out lower nibble is the truncated sum of the two absolute nibble differences.
    check_out_lower_nibble_absdiff_sum: assert property (
        @(posedge clk)
        out[3:0] ==
            (((in[15:12] >= in[7:4]) ? (in[15:12] - in[7:4]) : (in[7:4] - in[15:12])) +
             ((in[11:8]  >= in[3:0]) ? (in[11:8]  - in[3:0]) : (in[3:0]  - in[11:8])))
    );

// Equal upper and lower bytes produce a zero output.
    check_equal_bytes_zero_out: assert property (
        @(posedge clk) (in[15:8] == in[7:0]) |-> (out == 8'h00)
    );

// If the high nibbles match, only the low-nibble absolute difference remains.
    check_equal_high_nibbles_reduce_to_low_diff: assert property (
        @(posedge clk)
        (in[15:12] == in[7:4]) |->
            (out[3:0] == ((in[11:8] >= in[3:0]) ? (in[11:8] - in[3:0]) : (in[3:0] - in[11:8])))
    );

// If the low nibbles match, only the high-nibble absolute difference remains.
    check_equal_low_nibbles_reduce_to_high_diff: assert property (
        @(posedge clk)
        (in[11:8] == in[3:0]) |->
            (out[3:0] == ((in[15:12] >= in[7:4]) ? (in[15:12] - in[7:4]) : (in[7:4] - in[15:12])))
    );

// External sampling clock; RTL itself is combinational and has no reset.

    // shift_amt 000 passes input through unchanged.
    check_no_shift: assert property (
        @(posedge clk) (shift_amt == 3'b000) |-> (out == in)
    );

// shift_amt 001 shifts left by 1 and fills LSB with 0.
    check_shift_left_1: assert property (
        @(posedge clk) (shift_amt == 3'b001) |-> (out == {in[6:0], 1'b0})
    );

// shift_amt 010 shifts left by 2 and fills low bits with 0.
    check_shift_left_2: assert property (
        @(posedge clk) (shift_amt == 3'b010) |-> (out == {in[5:0], 2'b00})
    );

// shift_amt 011 shifts left by 3 and fills low bits with 0.
    check_shift_left_3: assert property (
        @(posedge clk) (shift_amt == 3'b011) |-> (out == {in[4:0], 3'b000})
    );

// shift_amt 100 shifts left by 4 and fills low bits with 0.
    check_shift_left_4: assert property (
        @(posedge clk) (shift_amt == 3'b100) |-> (out == {in[3:0], 4'b0000})
    );

// shift_amt 101 shifts right by 1 and fills MSB with 0.
    check_shift_right_1: assert property (
        @(posedge clk) (shift_amt == 3'b101) |-> (out == {1'b0, in[7:1]})
    );

// shift_amt 110 shifts right by 2 and fills high bits with 0.
    check_shift_right_2: assert property (
        @(posedge clk) (shift_amt == 3'b110) |-> (out == {2'b00, in[7:2]})
    );

// shift_amt 111 shifts right by 3 and fills high bits with 0.
    check_shift_right_3: assert property (
        @(posedge clk) (shift_amt == 3'b111) |-> (out == {3'b000, in[7:3]})
    );

// X matches the implemented combinational function.
    check_x_matches_function: assert property (
        @(posedge clk)
        X == (A1 ? (~B1) : (A2 ? B1 : 1'b0))
    );

// When A1 is high, X inverts B1.
    check_x_inverts_b1_when_a1_high: assert property (
        @(posedge clk)
        A1 |-> (X == (~B1))
    );

// When A1 is low, X reduces to A2 AND B1.
    check_x_is_a2_and_b1_when_a1_low: assert property (
        @(posedge clk)
        (!A1) |-> (X == (A2 & B1))
    );

// When A2 is low, X reduces to A1 AND not B1.
    check_x_is_a1_and_not_b1_when_a2_low: assert property (
        @(posedge clk)
        (!A2) |-> (X == (A1 & (~B1)))
    );

// When only A2 is high, X equals B1.
    check_x_follows_b1_when_only_a2_high: assert property (
        @(posedge clk)
        (!A1 && A2) |-> (X == B1)
    );

// When A1 and A2 are both low, X is low.
    check_x_low_when_a1_a2_low: assert property (
        @(posedge clk)
        (!A1 && !A2) |-> (X == 1'b0)
    );

// When A1 is low and B1 is high, X equals A2.
    check_x_follows_a2_when_a1_low_b1_high: assert property (
        @(posedge clk)
        (!A1 && B1) |-> (X == A2)
    );

// Clock is CLK1; there is no reset in the RTL.

    // Read data always reflects the selected memory bit.
    check_read_data_matches_mem: assert property (
        @(posedge CLK1) B1DATA == mem[B1ADDR]
    );

// With write enable low, the memory contents hold.
    check_no_write_holds_mem: assert property (
        @(posedge CLK1) !A1EN |=> $stable(mem)
    );

// A write updates memory exactly at the addressed bit.
    check_write_updates_full_mem_state: assert property (
        @(posedge CLK1)
        A1EN |=> mem == (($past(mem) & ~(32'h1 << $past(A1ADDR))) |
                         ({31'b0, $past(A1DATA)} << $past(A1ADDR)))
    );

// A write stores A1DATA into the addressed location.
    check_write_updates_addressed_bit: assert property (
        @(posedge CLK1) A1EN |=> mem[$past(A1ADDR)] == $past(A1DATA)
    );

// A write does not change any unaddressed memory bits.
    check_write_preserves_unaddressed_bits: assert property (
        @(posedge CLK1)
        A1EN |=> (((mem ^ $past(mem)) & ~(32'h1 << $past(A1ADDR))) == 32'h0)
    );

// Writing the existing value leaves memory unchanged.
    check_same_value_write_keeps_mem_stable: assert property (
        @(posedge CLK1) (A1EN && (A1DATA == mem[A1ADDR])) |=> $stable(mem)
    );

// A subsequent read of the written address returns the stored data.
    check_read_after_write_same_address: assert property (
        @(posedge CLK1)
        A1EN |=> ((B1ADDR != $past(A1ADDR)) || (B1DATA == $past(A1DATA)))
    );

// Q holds its value when enable is low.
    check_hold_when_disabled: assert property (
        @(posedge C) (!E) |=> (Q == $past(Q))
    );

// Q is set high when enabled with set asserted and reset deasserted.
    check_set_when_enabled: assert property (
        @(posedge C) (E && S && !R) |=> (Q == 1'b1)
    );

// Q is cleared when enabled with reset asserted and set deasserted.
    check_reset_when_enabled: assert property (
        @(posedge C) (E && !S && R) |=> (Q == 1'b0)
    );

// Q captures D when enabled with neither set nor reset asserted.
    check_data_capture_when_enabled: assert property (
        @(posedge C) (E && !S && !R) |=> (Q == $past(D))
    );

// Set has priority over reset when both are asserted with enable.
    check_set_priority_over_reset: assert property (
        @(posedge C) (E && S && R) |=> (Q == 1'b1)
    );

// Y matches the implemented OAI32 logic.
    check_oai32_function: assert property (
        @(posedge clk)
        Y == !((A1 && A2 && A3) || (B1 && B2))
    );

// All three A inputs high force Y low.
    check_a_triplet_forces_low: assert property (
        @(posedge clk)
        (A1 && A2 && A3) |-> !Y
    );

// Both B inputs high force Y low.
    check_b_pair_forces_low: assert property (
        @(posedge clk)
        (B1 && B2) |-> !Y
    );

// Y is high when neither input product term is active.
    check_output_high_when_no_product_active: assert property (
        @(posedge clk)
        (!(A1 && A2 && A3) && !(B1 && B2)) |-> Y
    );

// A low Y must be caused by at least one active product term.
    check_low_output_has_cause: assert property (
        @(posedge clk)
        !Y |-> ((A1 && A2 && A3) || (B1 && B2))
    );

// Rtout captures Rtin on the previous rising edge.
    check_rtout_captures_rtin: assert property (
        @(posedge clk) 1'b1 |=> (Rtout == $past(Rtin))
    );

// Rdout captures Rdin on the previous rising edge.
    check_rdout_captures_rdin: assert property (
        @(posedge clk) 1'b1 |=> (Rdout == $past(Rdin))
    );

// PCplusout captures PCplusin on the previous rising edge.
    check_pcplusout_captures_pcplusin: assert property (
        @(posedge clk) 1'b1 |=> (PCplusout == $past(PCplusin))
    );

// ALUresultout captures ALUresultin on the previous rising edge.
    check_aluresultout_captures_aluresultin: assert property (
        @(posedge clk) 1'b1 |=> (ALUresultout == $past(ALUresultin))
    );

// DatabusBout captures DatabusBin on the previous rising edge.
    check_databusbout_captures_databusbin: assert property (
        @(posedge clk) 1'b1 |=> (DatabusBout == $past(DatabusBin))
    );

// RegDstout captures RegDstin on the previous rising edge.
    check_regdstout_captures_regdstin: assert property (
        @(posedge clk) 1'b1 |=> (RegDstout == $past(RegDstin))
    );

// RegWrout captures RegWrin on the previous rising edge.
    check_regwrout_captures_regwrin: assert property (
        @(posedge clk) 1'b1 |=> (RegWrout == $past(RegWrin))
    );

// MemWrout captures MemWrin on the previous rising edge.
    check_memwrout_captures_memwrin: assert property (
        @(posedge clk) 1'b1 |=> (MemWrout == $past(MemWrin))
    );

// MemRdout captures MemRdin on the previous rising edge.
    check_memrdout_captures_memrdin: assert property (
        @(posedge clk) 1'b1 |=> (MemRdout == $past(MemRdin))
    );

// MemtoRegout captures MemtoRegin on the previous rising edge.
    check_memtoregout_captures_memtoregin: assert property (
        @(posedge clk) 1'b1 |=> (MemtoRegout == $past(MemtoRegin))
    );

// Q is zero whenever reset is low.
    check_reset_clears_q_now: assert property (
        @(posedge clk) !reset |-> (Q == 4'b0000)
    );

// Q is still zero on the next sampled clock after a reset-low cycle.
    check_reset_clears_q_next: assert property (
        @(posedge clk) !reset |=> (Q == 4'b0000)
    );

// A count of 15 wraps to 0 on the next active clock.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (!reset)
            (Q == 4'hF) |=> (Q == 4'h0)
    );

// A count of 0 advances to 1 on the next active clock.
    check_zero_to_one: assert property (
        @(posedge clk) disable iff (!reset)
            (Q == 4'h0) |=> (Q == 4'h1)
    );

// Q_N is always the inverse of Q.
    check_qn_complement: assert property (
        @(posedge CLK) (Q_N == ~Q)
    );

// A high SET_B forces Q high on the next observed cycle.
    check_set_forces_q_high: assert property (
        @(posedge CLK) SET_B |=> (Q == 1'b1)
    );

// A high SET_B forces Q_N low on the next observed cycle.
    check_set_forces_qn_low: assert property (
        @(posedge CLK) SET_B |=> (Q_N == 1'b0)
    );

// A low SET_B captures D into Q.
    check_data_capture_q: assert property (
        @(posedge CLK) (!SET_B) |=> (Q == $past(D))
    );

// A low SET_B captures the inverse of D into Q_N.
    check_data_capture_qn: assert property (
        @(posedge CLK) (!SET_B) |=> (Q_N == ~$past(D))
    );

// Binary 0 maps to the expected encoded value.
    check_binary_0_encoding: assert property (
        @(posedge clk) (binary == 4'd0) |-> (excess_3 == 8'b0011_0011)
    );

// Binary 1 maps to the expected encoded value.
    check_binary_1_encoding: assert property (
        @(posedge clk) (binary == 4'd1) |-> (excess_3 == 8'b0011_0100)
    );

// Binary 2 maps to the expected encoded value.
    check_binary_2_encoding: assert property (
        @(posedge clk) (binary == 4'd2) |-> (excess_3 == 8'b0011_0101)
    );

// Binary 3 maps to the expected encoded value.
    check_binary_3_encoding: assert property (
        @(posedge clk) (binary == 4'd3) |-> (excess_3 == 8'b0011_0110)
    );

// Binary 4 maps to the expected encoded value.
    check_binary_4_encoding: assert property (
        @(posedge clk) (binary == 4'd4) |-> (excess_3 == 8'b0011_0111)
    );

// Binary 5 maps to the expected encoded value.
    check_binary_5_encoding: assert property (
        @(posedge clk) (binary == 4'd5) |-> (excess_3 == 8'b0011_1000)
    );

// Binary 6 maps to the expected encoded value.
    check_binary_6_encoding: assert property (
        @(posedge clk) (binary == 4'd6) |-> (excess_3 == 8'b0011_1001)
    );

// Binary 7 maps to the expected encoded value.
    check_binary_7_encoding: assert property (
        @(posedge clk) (binary == 4'd7) |-> (excess_3 == 8'b0011_1010)
    );

// Binary 8 maps to the expected encoded value.
    check_binary_8_encoding: assert property (
        @(posedge clk) (binary == 4'd8) |-> (excess_3 == 8'b0011_1011)
    );

// Binary 9 maps to the expected encoded value.
    check_binary_9_encoding: assert property (
        @(posedge clk) (binary == 4'd9) |-> (excess_3 == 8'b0011_1100)
    );

// Binary 10 maps to the expected encoded value.
    check_binary_10_encoding: assert property (
        @(posedge clk) (binary == 4'd10) |-> (excess_3 == 8'b0011_1101)
    );

// Binary 11 maps to the expected encoded value.
    check_binary_11_encoding: assert property (
        @(posedge clk) (binary == 4'd11) |-> (excess_3 == 8'b0011_1110)
    );

// Binary 12 maps to the expected encoded value.
    check_binary_12_encoding: assert property (
        @(posedge clk) (binary == 4'd12) |-> (excess_3 == 8'b0011_1111)
    );

// Binary 13 maps to the expected encoded value.
    check_binary_13_encoding: assert property (
        @(posedge clk) (binary == 4'd13) |-> (excess_3 == 8'b0100_0000)
    );

// Binary 14 maps to the expected encoded value.
    check_binary_14_encoding: assert property (
        @(posedge clk) (binary == 4'd14) |-> (excess_3 == 8'b0100_0001)
    );

// Binary 15 maps to the expected encoded value.
    check_binary_15_encoding: assert property (
        @(posedge clk) (binary == 4'd15) |-> (excess_3 == 8'b0100_0010)
    );

// While reset is low, the counter output is zero.
    check_reset_clears_out: assert property (
        @(posedge clk) !rst |-> (out == 4'b0000)
    );

// After a clock sampled in reset, the next sampled value is still zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) !rst |=> (out == 4'b0000)
    );

// For counts below 15, the counter increments by one on the next clock.
    check_counter_increments: assert property (
        @(posedge clk) disable iff (!rst)
        (out != 4'hF) |=> (out == ($past(out) + 4'h1))
    );

// When the counter reaches 15, it wraps back to zero on the next clock.
    check_counter_wraps: assert property (
        @(posedge clk) disable iff (!rst)
        (out == 4'hF) |=> (out == 4'b0000)
    );

// gray_out matches the binary-to-gray conversion.
    check_gray_encoding: assert property (
        @(posedge clk) gray_out == {bin_in[2], (bin_in[1] ^ bin_in[2]), (bin_in[0] ^ bin_in[1])}
    );

// The MSB of gray_out passes through bin_in[2].
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_out[2] == bin_in[2]
    );

// gray_out[1] is the XOR of bin_in[1] and bin_in[2].
    check_gray_mid_xor: assert property (
        @(posedge clk) gray_out[1] == (bin_in[1] ^ bin_in[2])
    );

// gray_out[0] is the XOR of bin_in[0] and bin_in[1].
    check_gray_lsb_xor: assert property (
        @(posedge clk) gray_out[0] == (bin_in[0] ^ bin_in[1])
    );

// Reset clears count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 3'b000)
    );

// Count increments from 0 to 1.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b000) |=> (count == 3'b001)
    );

// Count increments from 1 to 2.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b001) |=> (count == 3'b010)
    );

// Count increments from 2 to 3.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b010) |=> (count == 3'b011)
    );

// Count increments from 3 to 4.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b011) |=> (count == 3'b100)
    );

// Count increments from 4 to 5.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b100) |=> (count == 3'b101)
    );

// Count increments from 5 to 6.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b101) |=> (count == 3'b110)
    );

// Count increments from 6 to 7.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b110) |=> (count == 3'b111)
    );

// Count wraps from 7 to 0.
    check_count_7_to_0: assert property (
        @(posedge clk) disable iff (rst)
        (count == 3'b111) |=> (count == 3'b000)
    );

// Reset clears all synchronizer stages.
    check_reset_clears_ff: assert property (
        @(posedge clk) !reset_n |-> (ff == {depth{1'b0}})
    );

// Reset drives the synchronized output low.
    check_reset_clears_dout: assert property (
        @(posedge clk) !reset_n |-> (dout == 1'b0)
    );

// A sampled reset keeps all stages at zero on the next sampled cycle.
    check_reset_holds_zero_ff_to_next_cycle: assert property (
        @(posedge clk) !reset_n |=> (ff == {depth{1'b0}})
    );

// A sampled reset keeps the output low on the next sampled cycle.
    check_reset_holds_zero_dout_to_next_cycle: assert property (
        @(posedge clk) !reset_n |=> (dout == 1'b0)
    );

// On the sampled release of reset, the output still starts low.
    check_release_starts_from_zero_dout: assert property (
        @(posedge clk) disable iff (!reset_n) $rose(reset_n) |-> (dout == 1'b0)
    );

// Y matches the RTL boolean equation.
    check_output_equation: assert property (
        @(posedge clk) Y == ~((~A & B) | (A & ~B))
    );

// 00 on the inputs drives Y high.
    check_00_high: assert property (
        @(posedge clk) (!A && !B) |-> (Y == 1'b1)
    );

// 01 on the inputs drives Y low.
    check_01_low: assert property (
        @(posedge clk) (!A && B) |-> (Y == 1'b0)
    );

// 10 on the inputs drives Y low.
    check_10_low: assert property (
        @(posedge clk) (A && !B) |-> (Y == 1'b0)
    );

// 11 on the inputs drives Y high.
    check_11_high: assert property (
        @(posedge clk) (A && B) |-> (Y == 1'b1)
    );

// Combinational DUT sampled on clk; no reset is present in the RTL.

    // Checks the output matches the RTL min-selection expression.
    check_output_matches_rtl_expression: assert property (
        @(posedge clk)
        min_val_out == ((a < b) ? ((a < c) ? ((a < d) ? a : d) : ((c < d) ? c : d))
                                : ((b < c) ? ((b < d) ? b : d) : ((c < d) ? c : d)))
    );

// Checks the output is not greater than input a.
    check_output_le_a: assert property (
        @(posedge clk)
        min_val_out <= a
    );

// Checks the output is not greater than input b.
    check_output_le_b: assert property (
        @(posedge clk)
        min_val_out <= b
    );

// Checks the output is not greater than input c.
    check_output_le_c: assert property (
        @(posedge clk)
        min_val_out <= c
    );

// Checks the output is not greater than input d.
    check_output_le_d: assert property (
        @(posedge clk)
        min_val_out <= d
    );

// Checks the output matches one of the input values.
    check_output_is_one_of_inputs: assert property (
        @(posedge clk)
        (min_val_out == a) || (min_val_out == b) || (min_val_out == c) || (min_val_out == d)
    );

// Checks a is produced when a is less than or equal to all inputs.
    check_select_a_when_a_is_minimum: assert property (
        @(posedge clk)
        (a <= b && a <= c && a <= d) |-> (min_val_out == a)
    );

// Checks b is produced when b is less than or equal to all inputs.
    check_select_b_when_b_is_minimum: assert property (
        @(posedge clk)
        (b <= a && b <= c && b <= d) |-> (min_val_out == b)
    );

// Checks c is produced when c is less than or equal to all inputs.
    check_select_c_when_c_is_minimum: assert property (
        @(posedge clk)
        (c <= a && c <= b && c <= d) |-> (min_val_out == c)
    );

// Checks d is produced when d is less than or equal to all inputs.
    check_select_d_when_d_is_minimum: assert property (
        @(posedge clk)
        (d <= a && d <= b && d <= c) |-> (min_val_out == d)
    );

// AND selection produces a bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (op_select == 3'b000) |-> (out_value == (in_value & mask_value))
    );

// OR selection produces a bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (op_select == 3'b001) |-> (out_value == (in_value | mask_value))
    );

// XOR selection produces a bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (op_select == 3'b010) |-> (out_value == (in_value ^ mask_value))
    );

// Left-shift selection shifts by shift_value.
    check_left_shift_result: assert property (
        @(posedge clk) (op_select == 3'b011) |-> (out_value == (in_value << shift_value))
    );

// Right-shift selection shifts by shift_value.
    check_right_shift_result: assert property (
        @(posedge clk) (op_select == 3'b100) |-> (out_value == (in_value >> shift_value))
    );

// Unused op_select values pass the input through.
    check_default_passthrough: assert property (
        @(posedge clk) ((op_select == 3'b101) || (op_select == 3'b110) || (op_select == 3'b111)) |-> (out_value == in_value)
    );

// Left shift by zero leaves the input unchanged.
    check_left_shift_zero_identity: assert property (
        @(posedge clk) ((op_select == 3'b011) && (shift_value == 4'h0)) |-> (out_value == in_value)
    );

// Right shift by zero leaves the input unchanged.
    check_right_shift_zero_identity: assert property (
        @(posedge clk) ((op_select == 3'b100) && (shift_value == 4'h0)) |-> (out_value == in_value)
    );

// AND with a zero mask yields zero.
    check_and_zero_mask: assert property (
        @(posedge clk) ((op_select == 3'b000) && (mask_value == 16'h0000)) |-> (out_value == 16'h0000)
    );

// OR with a zero mask leaves the input unchanged.
    check_or_zero_mask_identity: assert property (
        @(posedge clk) ((op_select == 3'b001) && (mask_value == 16'h0000)) |-> (out_value == in_value)
    );

// XOR with a zero mask leaves the input unchanged.
    check_xor_zero_mask_identity: assert property (
        @(posedge clk) ((op_select == 3'b010) && (mask_value == 16'h0000)) |-> (out_value == in_value)
    );

// sum_out accumulates the previous cycle's data_in every clock.
    check_sum_accumulates: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (sum_out == ($past(sum_out) + $past(data_in)))
    );

// A zero input leaves sum_out unchanged on the next clock.
    check_zero_input_holds: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (($past(data_in) == 8'h00) -> (sum_out == $past(sum_out)))
    );

// The low byte updates as the previous low byte plus previous data_in.
    check_low_byte_updates: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (sum_out[7:0] == ($past(sum_out[7:0]) + $past(data_in)))
    );

// Without a low-byte carry, the upper 24 bits stay unchanged.
    check_no_low_byte_carry_keeps_upper: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ((({1'b0, $past(sum_out[7:0])} + {1'b0, $past(data_in)}) < 9'h100) ->
                  (sum_out[31:8] == $past(sum_out[31:8])))
    );

// A low-byte carry increments the upper 24 bits by one.
    check_low_byte_carry_increments_upper: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> ((({1'b0, $past(sum_out[7:0])} + {1'b0, $past(data_in)}) >= 9'h100) ->
                  (sum_out[31:8] == ($past(sum_out[31:8]) + 24'd1)))
    );

// branch_flushD is the OR of jump-register and misprediction.
    check_branch_flushD_equation: assert property (
        @(posedge clk)
        branch_flushD == (ID_jmp_reg || ID_misprediction)
    );

// A jump-register request forces branch_flushD high.
    check_branch_flushD_on_jmp_reg: assert property (
        @(posedge clk)
        ID_jmp_reg |-> branch_flushD
    );

// A misprediction forces branch_flushD high.
    check_branch_flushD_on_misprediction: assert property (
        @(posedge clk)
        ID_misprediction |-> branch_flushD
    );

// branch_flushD is low when neither source requests a flush.
    check_branch_flushD_clear_without_cause: assert property (
        @(posedge clk)
        (!ID_jmp_reg && !ID_misprediction) |-> !branch_flushD
    );

// branch_flushE matches the implemented EX/MEM hazard expression.
    check_branch_flushE_equation: assert property (
        @(posedge clk)
        branch_flushE == (
            (ID_jmp_need_reg && EX_regwe && (EX_RW != 5'd0) &&
             ((EX_RW == ID_rs) || (EX_RW == ID_rt))) ||
            (ID_jmp_need_reg && MEM_ramtoreg && (MEM_RW != 5'd0) &&
             ((MEM_RW == ID_rs) || (MEM_RW == ID_rt)))
        )
    );

// An EX-stage register dependency forces branch_flushE high.
    check_branch_flushE_on_ex_dependency: assert property (
        @(posedge clk)
        (ID_jmp_need_reg && EX_regwe && (EX_RW != 5'd0) &&
         ((EX_RW == ID_rs) || (EX_RW == ID_rt))) |-> branch_flushE
    );

// A MEM-stage load dependency forces branch_flushE high.
    check_branch_flushE_on_mem_dependency: assert property (
        @(posedge clk)
        (ID_jmp_need_reg && MEM_ramtoreg && (MEM_RW != 5'd0) &&
         ((MEM_RW == ID_rs) || (MEM_RW == ID_rt))) |-> branch_flushE
    );

// branch_flushE can only be high for a real jump-register data hazard.
    check_branch_flushE_implies_valid_dependency: assert property (
        @(posedge clk)
        branch_flushE |-> (
            ID_jmp_need_reg &&
            (
                (EX_regwe && (EX_RW != 5'd0) &&
                 ((EX_RW == ID_rs) || (EX_RW == ID_rt))) ||
                (MEM_ramtoreg && (MEM_RW != 5'd0) &&
                 ((MEM_RW == ID_rs) || (MEM_RW == ID_rt)))
            )
        )
    );

// branch_flushE is low when neither EX nor MEM hazard condition is present.
    check_branch_flushE_clear_without_dependency: assert property (
        @(posedge clk)
        (!(ID_jmp_need_reg && EX_regwe && (EX_RW != 5'd0) &&
           ((EX_RW == ID_rs) || (EX_RW == ID_rt))) &&
         !(ID_jmp_need_reg && MEM_ramtoreg && (MEM_RW != 5'd0) &&
           ((MEM_RW == ID_rs) || (MEM_RW == ID_rt)))) |-> !branch_flushE
    );

// Active-low reset clears the registered read data.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 4'b0000)
    );

// Address 0 loads the next read data value from the sampled input port.
    check_address_zero_returns_input: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |=> (readdata == $past(in_port))
    );

// Any nonzero address loads zero into the read data register.
    check_nonzero_address_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |=> (readdata == 4'b0000)
    );

// Addition mode returns the 4-bit signed sum.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result === calc_expected(op1, op2, op))
    );

// Subtraction mode returns the 4-bit signed difference.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result === calc_expected(op1, op2, op))
    );

// Addition opcode returns A + B, truncated to 8 bits.
    check_add_operation: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == ((A + B) & 8'hff))
    );

// Subtraction opcode returns A - B, truncated to 8 bits.
    check_sub_operation: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == ((A - B) & 8'hff))
    );

// Division by zero forces the result to zero.
    check_div_by_zero: assert property (
        @(posedge clk) (op == 2'b11 && B == 8'h00) |-> (result == 8'h00)
    );

// Count is the parity of the four input bits.
    check_count_matches_parity: assert property (
        @(posedge clk) count == (in[0] ^ in[1] ^ in[2] ^ in[3])
    );

// Zero or four asserted input bits drive count low.
    check_zero_or_four_ones_drive_low: assert property (
        @(posedge clk) ((in == 4'b0000) || (in == 4'b1111)) |-> (count == 1'b0)
    );

// Any one-hot input drives count high.
    check_one_hot_drives_high: assert property (
        @(posedge clk) (in inside {4'b0001, 4'b0010, 4'b0100, 4'b1000}) |-> (count == 1'b1)
    );

// Any two-hot input drives count low.
    check_two_ones_drive_low: assert property (
        @(posedge clk) (in inside {4'b0011, 4'b0101, 4'b0110, 4'b1001, 4'b1010, 4'b1100}) |-> (count == 1'b0)
    );

// Any three-hot input drives count high.
    check_three_ones_drive_high: assert property (
        @(posedge clk) (in inside {4'b0111, 4'b1011, 4'b1101, 4'b1110}) |-> (count == 1'b1)
    );

// X matches the implemented A21O logic function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | B1)
    );

// B1 alone is sufficient to drive X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// The A1/A2 AND path drives X high when both inputs are high.
    check_and_path_forces_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// When B1 is low, X reduces to the A1/A2 AND result.
    check_b1_low_reduces_to_and: assert property (
        @(posedge clk) !B1 |-> (X == (A1 & A2))
    );

// With B1 low and an incomplete AND path, X must be low.
    check_no_active_input_path_means_x_low: assert property (
        @(posedge clk) (!B1 && (!A1 || !A2)) |-> !X
    );

// When reset is high, out is zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) reset |-> (out == 4'b0000)
    );

// A terminal-count match drives the next sampled value to zero.
    check_match_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset) (out == N) |=> (out == 4'b0000)
    );

// A non-match advances by one, unless async reset forces zero between clocks.
    check_nonmatch_advances_or_resets: assert property (
        @(posedge clk) disable iff (reset)
            (out != N) |=> ((out == 4'b0000) || (out == ($past(out) + 4'b0001)))
    );

// Incrementing from 4'hF wraps the 4-bit counter to zero.
    check_overflow_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset) (out == 4'hF && N != 4'hF) |=> (out == 4'b0000)
    );

// A nonzero, nonterminal count cannot repeat on the next sampled cycle.
    check_nonterminal_nonzero_changes: assert property (
        @(posedge clk) disable iff (reset) (out != 4'b0000 && out != N) |=> (out != $past(out))
    );

// TE high captures a high EN into ENCLK.
    check_capture_high: assert property (
        @(posedge CLK) (TE && EN) |=> ENCLK
    );

// TE high captures a low EN into ENCLK.
    check_capture_low: assert property (
        @(posedge CLK) (TE && !EN) |=> !ENCLK
    );

// TE low holds ENCLK high.
    check_hold_high_when_te_low: assert property (
        @(posedge CLK) (!TE && ENCLK) |=> ENCLK
    );

// TE low holds ENCLK low.
    check_hold_low_when_te_low: assert property (
        @(posedge CLK) (!TE && !ENCLK) |=> !ENCLK
    );

// With TE high, ENCLK matches the prior EN value.
    check_enabled_update_matches_en: assert property (
        @(posedge CLK) TE |=> (ENCLK == $past(EN))
    );

// With TE low, ENCLK keeps its prior value.
    check_disabled_hold_matches_previous: assert property (
        @(posedge CLK) !TE |=> (ENCLK == $past(ENCLK))
    );

// Reset sampled low clears Q.
    check_reset_clears_q: assert property (
        @(posedge GATE) (!RESET_B) |=> (Q == 1'b0)
    );

// Outside reset, Q reflects the D sampled on the prior GATE edge.
    check_data_capture: assert property (
        @(posedge GATE) disable iff (!RESET_B) 1'b1 |=> (Q == $past(D))
    );

// A sampled high D is captured into Q.
    check_capture_high: assert property (
        @(posedge GATE) disable iff (!RESET_B) (D == 1'b1) |=> (Q == 1'b1)
    );

// A sampled low D is captured into Q.
    check_capture_low: assert property (
        @(posedge GATE) disable iff (!RESET_B) (D == 1'b0) |=> (Q == 1'b0)
    );

// X must always equal the OR of A and B.
    check_or_equivalence: assert property (
        @(posedge clk) X == (A | B)
    );

// If both inputs are low, the output must be low.
    check_or_both_low: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (X == 1'b0)
    );

// If only A is high, the output must be high.
    check_or_a_only_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b0)) |-> (X == 1'b1)
    );

// If only B is high, the output must be high.
    check_or_b_only_high: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b1)) |-> (X == 1'b1)
    );

// If both inputs are high, the output must be high.
    check_or_both_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (X == 1'b1)
    );

// Y matches the implemented invert-then-NAND function.
    check_output_function: assert property (
        @(posedge clk) Y == ~(D & C & B & ~A_N)
    );

// A_N high forces the output high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// Any low data input forces the output high.
    check_any_low_data_input_forces_y_high: assert property (
        @(posedge clk) (!B || !C || !D) |-> Y
    );

// A_N low with all other inputs high forces the output low.
    check_all_active_inputs_drive_y_low: assert property (
        @(posedge clk) (!A_N && B && C && D) |-> !Y
    );

// A low output can only occur for the single active-input case.
    check_y_low_has_unique_cause: assert property (
        @(posedge clk) !Y |-> (!A_N && B && C && D)
    );

// Out is the input value captured on the previous clock.
    check_out_is_registered_input: assert property (
        @(posedge clk) 1'b1 |=> (out == $past(in))
    );

// If input is unchanged across clocks, output matches that value on the next clock.
    check_out_matches_held_input: assert property (
        @(posedge clk) 1'b1 |=> (($past(in) != in) || (out == in))
    );

// If input changes across clocks, output still shows the earlier sampled value.
    check_out_lags_input_change: assert property (
        @(posedge clk) 1'b1 |=> (($past(in) == in) || (out != in))
    );

// A sampled low reset forces the count to zero by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) (!reset_n) |=> (count == 4'd0)
    );

// On the sampled release of reset, the count is still zero.
    check_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (!reset_n)
        $rose(reset_n) |-> (count == 4'd0)
    );

// Counts below nine increment by one on the next clock.
    check_increment_when_below_nine: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count < 4'd9) |=> (count == ($past(count) + 4'd1))
    );

// A count of nine wraps back to zero on the next clock.
    check_wrap_when_nine: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count == 4'd9) |=> (count == 4'd0)
    );

// During normal operation, the count stays in the 0 to 9 range.
    check_count_in_decade_range: assert property (
        @(posedge clk) disable iff (!reset_n)
        (count <= 4'd9)
    );

// A sampled reset drives both digits to zero by the following cycle.
    check_reset_clears_digits: assert property (
        @(posedge clk)
        reset |=> (dig0 == 4'd0 && dig1 == 4'd0)
    );

// Clear forces both digits to zero on the next cycle.
    check_clear_sets_zero: assert property (
        @(posedge clk) disable iff (reset)
        d_clr |=> (dig0 == 4'd0 && dig1 == 4'd0)
    );

// With no command asserted, the displayed value holds.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && !d_inc && !d_dec) |=> (dig0 == $past(dig0) && dig1 == $past(dig1))
    );

// Increment without carry increases only the ones digit.
    check_inc_without_carry: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && d_inc && (dig0 < 4'd9)) |=> (dig0 == ($past(dig0) + 4'd1) && dig1 == $past(dig1))
    );

// Increment at x9 carries into the tens digit.
    check_inc_with_carry: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && d_inc && (dig0 == 4'd9) && (dig1 < 4'd9)) |=> (dig0 == 4'd0 && dig1 == ($past(dig1) + 4'd1))
    );

// Increment at 99 wraps the count to 00.
    check_inc_wraps_99_to_00: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && d_inc && (dig0 == 4'd9) && (dig1 == 4'd9)) |=> (dig0 == 4'd0 && dig1 == 4'd0)
    );

// Decrement from 00 or 01 clamps the value to 10.
    check_dec_floor_to_ten: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && !d_inc && d_dec && (dig1 == 4'd0) && (dig0 < 4'd2)) |=> (dig0 == 4'd0 && dig1 == 4'd1)
    );

// Decrement from x1 borrows and produces x-1,9.
    check_dec_borrow_from_x1: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && !d_inc && d_dec && (dig1 > 4'd0) && (dig0 == 4'd1)) |=> (dig0 == 4'd9 && dig1 == ($past(dig1) - 4'd1))
    );

// Decrement from x0 borrows and produces x-1,8.
    check_dec_borrow_from_x0: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && !d_inc && d_dec && (dig1 > 4'd0) && (dig0 == 4'd0)) |=> (dig0 == 4'd8 && dig1 == ($past(dig1) - 4'd1))
    );

// All other decrement cases subtract two from the ones digit.
    check_dec_subtracts_two: assert property (
        @(posedge clk) disable iff (reset)
        (!d_clr && !d_inc && d_dec &&
         !((dig1 == 4'd0) && (dig0 < 4'd2)) &&
         !((dig1 > 4'd0) && (dig0 == 4'd1)) &&
         !((dig1 > 4'd0) && (dig0 == 4'd0)))
        |=> (dig0 == ($past(dig0) - 4'd2) && dig1 == $past(dig1))
    );

// Synchronous reset clears Q on the next clock.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |=> (Q == 4'b0000)
    );

// LD causes Q to take LOAD_IN on the next clock.
    check_load_updates_q: assert property (
        @(posedge CLK) disable iff (RST) LD |=> (Q == $past(LOAD_IN))
    );

// LD has priority over UD when both are high.
    check_load_priority_over_ud: assert property (
        @(posedge CLK) disable iff (RST) (LD && UD) |=> (Q == $past(LOAD_IN))
    );

// Without load, UD=1 increments Q by one.
    check_count_up: assert property (
        @(posedge CLK) disable iff (RST) (!LD && UD) |=> (Q == ($past(Q) + 4'b0001))
    );

// Without load, UD=0 decrements Q by one.
    check_count_down: assert property (
        @(posedge CLK) disable iff (RST) (!LD && !UD) |=> (Q == ($past(Q) - 4'b0001))
    );

// Incrementing from 4'hF wraps Q to 4'h0.
    check_count_up_wrap: assert property (
        @(posedge CLK) disable iff (RST) (!LD && UD && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Decrementing from 4'h0 wraps Q to 4'hF.
    check_count_down_wrap: assert property (
        @(posedge CLK) disable iff (RST) (!LD && !UD && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Each cycle, serial_out follows the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge clk)
        1'b1 |=> serial_out ==
                 ($past(load) ? $past(parallel_in) :
                  ($past(shift_dir) ? {$past(serial_in), $past(serial_out[7:1])} :
                                      {$past(serial_out[6:0]), $past(serial_in)}))
    );

// When load is high, the register captures parallel_in on the next clock.
    check_load_captures_parallel_in: assert property (
        @(posedge clk)
        load |=> serial_out == $past(parallel_in)
    );

// When not loading and shift_dir is high, the register shifts right.
    check_shift_right_updates_register: assert property (
        @(posedge clk)
        (!load && shift_dir) |=> serial_out == {$past(serial_in), $past(serial_out[7:1])}
    );

// When not loading and shift_dir is low, the register shifts left.
    check_shift_left_updates_register: assert property (
        @(posedge clk)
        (!load && !shift_dir) |=> serial_out == {$past(serial_out[6:0]), $past(serial_in)}
    );

// A right shift inserts serial_in into the MSB.
    check_shift_right_inserts_serial_in: assert property (
        @(posedge clk)
        (!load && shift_dir) |=> serial_out[7] == $past(serial_in)
    );

// A right shift moves bits [7:1] into [6:0].
    check_shift_right_moves_data: assert property (
        @(posedge clk)
        (!load && shift_dir) |=> serial_out[6:0] == $past(serial_out[7:1])
    );

// A left shift inserts serial_in into the LSB.
    check_shift_left_inserts_serial_in: assert property (
        @(posedge clk)
        (!load && !shift_dir) |=> serial_out[0] == $past(serial_in)
    );

// A left shift moves bits [6:0] into [7:1].
    check_shift_left_moves_data: assert property (
        @(posedge clk)
        (!load && !shift_dir) |=> serial_out[7:1] == $past(serial_out[6:0])
    );

// Next countout matches the RTL next-state function.
    check_next_state_matches_rtl: assert property (
        @(posedge countClock) disable iff (1'b0)
        1'b1 |=> countout == ($past(load) ? $past(loadvalue) : ($past(countout) - $past(count)))
    );

// load causes countout to take loadvalue on the next clock.
    check_load_captures_value: assert property (
        @(posedge countClock) disable iff (1'b0)
        load |=> countout == $past(loadvalue)
    );

// With load low and count low, countout holds its value.
    check_hold_when_idle: assert property (
        @(posedge countClock) disable iff (1'b0)
        !load && !count |=> countout == $past(countout)
    );

// With load low and count high, countout decrements by one.
    check_decrement_when_count_high: assert property (
        @(posedge countClock) disable iff (1'b0)
        !load && count |=> countout == ($past(countout) - 8'd1)
    );

// EN high with TE low drives ENCLK high on the next cycle.
    check_en_and_not_te_sets_enclk: assert property (
        @(posedge CLK) (EN && !TE) |=> ENCLK
    );

// EN low drives ENCLK low on the next cycle.
    check_en_low_clears_enclk: assert property (
        @(posedge CLK) !EN |=> !ENCLK
    );

// TE high drives ENCLK low on the next cycle.
    check_te_high_clears_enclk: assert property (
        @(posedge CLK) TE |=> !ENCLK
    );

// Output bit equals the NAND of the aligned input bits.
            check_nand_function: assert property (
                @(posedge clk) data_out[i] === (~aligned_inputs_and(data_in, i))
            );

// All aligned inputs high drive the output low.
            check_all_ones_drive_zero: assert property (
                @(posedge clk) (aligned_inputs_and(data_in, i) === 1'b1) |-> (data_out[i] === 1'b0)
            );

// Any aligned zero drives the output high.
            check_any_zero_drive_one: assert property (
                @(posedge clk) (aligned_inputs_and(data_in, i) === 1'b0) |-> (data_out[i] === 1'b1)
            );

// A low output only occurs when all aligned inputs are high.
            check_low_output_requires_all_ones: assert property (
                @(posedge clk) (data_out[i] === 1'b0) |-> (aligned_inputs_and(data_in, i) === 1'b1)
            );

// Q0 samples A on every clock edge.
    check_q0_captures_a: assert property (
        @(posedge clk) 1'b1 |=> (Q0 == $past(A))
    );

// When load is high, all three bits load the input value.
    check_parallel_load_all_bits: assert property (
        @(posedge clk) load |=> ((Q2 == $past(A)) && (Q1 == $past(A)) && (Q0 == $past(A)))
    );

// In shift mode, Q2 takes the previous Q1 value.
    check_shift_q2_from_q1: assert property (
        @(posedge clk) !load |=> (Q2 == $past(Q1))
    );

// In shift mode, Q1 takes the previous Q0 value.
    check_shift_q1_from_q0: assert property (
        @(posedge clk) !load |=> (Q1 == $past(Q0))
    );

// clk is the only clock; the RTL has no reset.
    // out is the registered low 7 bits of operand_a + operand_b.

    // out captures the lower 7 bits of the previous cycle sum.
    check_registered_truncated_sum: assert property (
        @(posedge clk) 1'b1 |=> ({1'b0, out} == (($past(operand_a) + $past(operand_b)) & 8'h7f))
    );

// Zero plus zero produces zero on the next cycle.
    check_zero_plus_zero: assert property (
        @(posedge clk) (operand_a == 8'h00 && operand_b == 8'h00) |=> (out == 7'h00)
    );

// A zero operand_a passes operand_b's low 7 bits to out on the next cycle.
    check_zero_a_passthrough: assert property (
        @(posedge clk) (operand_a == 8'h00) |=> ({1'b0, out} == ($past(operand_b) & 8'h7f))
    );

// A zero operand_b passes operand_a's low 7 bits to out on the next cycle.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (operand_b == 8'h00) |=> ({1'b0, out} == ($past(operand_a) & 8'h7f))
    );

// out[0] is the XOR of the previous cycle operand LSBs.
    check_lsb_xor: assert property (
        @(posedge clk) 1'b1 |=> (out[0] == ($past(operand_a[0]) ^ $past(operand_b[0])))
    );

// When the previous 8-bit sum has bit 7 clear, out matches that full 8-bit sum.
    check_sum_without_bit7_matches_out: assert property (
        @(posedge clk) (((operand_a + operand_b) & 8'h80) == 8'h00) |=> ({1'b0, out} == ($past(operand_a) + $past(operand_b)))
    );

// When the previous 8-bit sum has bit 7 set, out drops that bit on the next cycle.
    check_sum_with_bit7_drops_msb: assert property (
        @(posedge clk) (((operand_a + operand_b) & 8'h80) == 8'h80) |=> ({1'b0, out} == (($past(operand_a) + $past(operand_b)) - 8'h80))
    );

// sum reflects the combinational addition of d1 and d2.
    check_sum_matches_addition: assert property (
        @(posedge clk) disable iff (rst)
            sum == (d1 + d2)
    );

// With sel low, q captures d1 on the next clock.
    check_q_captures_d1_when_sel_low: assert property (
        @(posedge clk) disable iff (rst)
            !sel |=> (q == $past(d1))
    );

// With sel high, q captures d2 on the next clock.
    check_q_captures_d2_when_sel_high: assert property (
        @(posedge clk) disable iff (rst)
            sel |=> (q == $past(d2))
    );

// If reset stays asserted across clocks, q remains zero.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk)
            rst && $past(rst) |-> (q == 8'h00)
    );

// On the first clock after reset deasserts, q is still zero.
    check_q_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (rst)
            $fell(rst) |-> (q == 8'h00)
    );

// Q_N is the complement of Q when reset is inactive.
    check_qn_inverse: assert property (
        @(posedge CLK) disable iff (!RESET_B) (Q_N == ~Q)
    );

// Active-low set drives Q high.
    check_set_forces_q_high: assert property (
        @(posedge CLK) (!SET_B) |=> (Q == 1'b1)
    );

// Active-low set drives Q_N low.
    check_set_forces_qn_low: assert property (
        @(posedge CLK) (!SET_B) |=> (Q_N == 1'b0)
    );

// Active-low reset drives Q low when set is inactive.
    check_reset_forces_q_low: assert property (
        @(posedge CLK) (SET_B && !RESET_B) |=> (Q == 1'b0)
    );

// Active-low reset drives Q_N high when set is inactive.
    check_reset_forces_qn_high: assert property (
        @(posedge CLK) (SET_B && !RESET_B) |=> (Q_N == 1'b1)
    );

// Set has priority when set and reset are both low.
    check_set_priority_over_reset: assert property (
        @(posedge CLK) (!SET_B && !RESET_B) |=> (Q == 1'b1)
    );

// With set and reset inactive, Q captures D.
    check_data_capture: assert property (
        @(posedge CLK) (SET_B && RESET_B) |=> (Q == $past(D))
    );

// With set and reset inactive, Q_N reflects the inverse of D.
    check_data_capture_qn: assert property (
        @(posedge CLK) (SET_B && RESET_B) |=> (Q_N == ~$past(D))
    );

// Reset clears all stages on the clock edge where reset is sampled high.
    check_reset_clears_all_stages: assert property (
        @(posedge shift_clk)
        reset |=> (q0 == 4'b0000 && q1 == 4'b0000 && q2 == 4'b0000 && q3 == 4'b0000)
    );

// q0 captures data_in on each non-reset clock.
    check_q0_captures_data_in: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q0 == $past(data_in))
    );

// q1 captures the previous value of q0 on each non-reset clock.
    check_q1_shifts_q0: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q1 == $past(q0))
    );

// q2 captures the previous value of q1 on each non-reset clock.
    check_q2_shifts_q1: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q2 == $past(q1))
    );

// q3 captures the previous value of q2 on each non-reset clock.
    check_q3_shifts_q2: assert property (
        @(posedge shift_clk) disable iff (reset)
        1'b1 |=> (q3 == $past(q2))
    );

// Y matches the implemented two-stage NAND expression.
    check_y_matches_implemented_logic: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ~(~(A & B) & ~(C & D))
    );

// A and B both high force Y high.
    check_ab_pair_forces_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (A & B) |-> Y
    );

// C and D both high force Y high.
    check_cd_pair_forces_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C & D) |-> Y
    );

// If neither input pair is fully high, Y is low.
    check_no_active_pair_forces_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!(A & B) && !(C & D)) |-> !Y
    );

// Y can only be high when at least one input pair is fully high.
    check_y_high_requires_active_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        Y |-> ((A & B) || (C & D))
    );

// Y must match the implemented NOR/AND boolean function.
    check_y_matches_boolean_function: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces the NOR output low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force the NOR output low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> !Y
    );

// B1 and B2 high together force the NOR output low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// A single asserted A input is not enough to pull Y low when other terms are clear.
    check_single_a_input_keeps_y_high: assert property (
        @(posedge clk) (!C1 && !(B1 & B2) && (A1 ^ A2)) |-> Y
    );

// A single asserted B input is not enough to pull Y low when other terms are clear.
    check_single_b_input_keeps_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 & A2) && (B1 ^ B2)) |-> Y
    );

// With all NOR inputs low, Y must be high.
    check_all_nor_inputs_low_gives_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 & A2) && !(B1 & B2)) |-> Y
    );

// F is high for input 000.
    check_f_high_000: assert property (
        @(posedge clk) ({A,B,C} == 3'b000) |-> (F == 1'b1)
    );

// F is high for input 011.
    check_f_high_011: assert property (
        @(posedge clk) ({A,B,C} == 3'b011) |-> (F == 1'b1)
    );

// F is low for all other input combinations.
    check_f_low_other_inputs: assert property (
        @(posedge clk)
        !((({A,B,C} == 3'b000) || ({A,B,C} == 3'b011))) |-> (F == 1'b0)
    );

// F matches the implemented truth table each cycle.
    check_f_truth_table: assert property (
        @(posedge clk)
        F == (({A,B,C} == 3'b000) || ({A,B,C} == 3'b011))
    );

// IN=000 decodes to OUT[0].
    check_decode_000: assert property (
        @(posedge clk) (IN == 3'b000) |-> (OUT == 8'b0000_0001)
    );

// IN=001 decodes to OUT[1].
    check_decode_001: assert property (
        @(posedge clk) (IN == 3'b001) |-> (OUT == 8'b0000_0010)
    );

// IN=010 decodes to OUT[2].
    check_decode_010: assert property (
        @(posedge clk) (IN == 3'b010) |-> (OUT == 8'b0000_0100)
    );

// IN=011 decodes to OUT[3].
    check_decode_011: assert property (
        @(posedge clk) (IN == 3'b011) |-> (OUT == 8'b0000_1000)
    );

// IN=100 decodes to OUT[4].
    check_decode_100: assert property (
        @(posedge clk) (IN == 3'b100) |-> (OUT == 8'b0001_0000)
    );

// IN=101 decodes to OUT[5].
    check_decode_101: assert property (
        @(posedge clk) (IN == 3'b101) |-> (OUT == 8'b0010_0000)
    );

// IN=110 decodes to OUT[6].
    check_decode_110: assert property (
        @(posedge clk) (IN == 3'b110) |-> (OUT == 8'b0100_0000)
    );

// IN=111 decodes to OUT[7].
    check_decode_111: assert property (
        @(posedge clk) (IN == 3'b111) |-> (OUT == 8'b1000_0000)
    );

// OUT matches a left-shifted one-hot decode of IN.
    check_exact_shift_decode: assert property (
        @(posedge clk) OUT == (8'b0000_0001 << IN)
    );

// OUT is always exactly one-hot.
    check_onehot_output: assert property (
        @(posedge clk) $onehot(OUT)
    );

// Out routes In0 when the select value is 00.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) ({Sel1, Sel2} == 2'b00) |-> (Out == In0)
    );

// Out routes In1 when the select value is 01.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) ({Sel1, Sel2} == 2'b01) |-> (Out == In1)
    );

// Out routes In2 when the select value is 10.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) ({Sel1, Sel2} == 2'b10) |-> (Out == In2)
    );

// Out routes In3 when the select value is 11.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) ({Sel1, Sel2} == 2'b11) |-> (Out == In3)
    );

// No DUT clock or reset; assertions are sampled on external clk.

    // The top output must match the full add/sub, shift, and select behavior.
    check_top_function: assert property (
        @(posedge clk)
        Y == (
            select
                ? (SHIFT[1]
                    ? (((SUB ? (in0 - in1) : (in0 + in1)) >> SHIFT))
                    : (((SUB ? (in0 - in1) : (in0 + in1)) << SHIFT)))
                : (SUB ? (in0 - in1) : (in0 + in1))
        )
    );

// When select is low and SUB is low, Y must be the 4-bit sum.
    check_bypass_add: assert property (
        @(posedge clk)
        (!select && !SUB) |-> (Y == (in0 + in1))
    );

// When select is low and SUB is high, Y must be the 4-bit difference.
    check_bypass_sub: assert property (
        @(posedge clk)
        (!select && SUB) |-> (Y == (in0 - in1))
    );

// When select is high and SHIFT[1] is low, Y must be the left-shifted add/sub result.
    check_selected_left_shift: assert property (
        @(posedge clk)
        (select && !SHIFT[1]) |-> (Y == ((SUB ? (in0 - in1) : (in0 + in1)) << SHIFT))
    );

// When select is high and SHIFT[1] is high, Y must be the right-shifted add/sub result.
    check_selected_right_shift: assert property (
        @(posedge clk)
        (select && SHIFT[1]) |-> (Y == ((SUB ? (in0 - in1) : (in0 + in1)) >> SHIFT))
    );

// A selected zero shift must leave the add/sub result unchanged.
    check_zero_shift_identity: assert property (
        @(posedge clk)
        (select && (SHIFT == 2'b00)) |-> (Y == (SUB ? (in0 - in1) : (in0 + in1)))
    );

// CK is the only clock and the RTL has no reset.

    // Outputs equal the previous cycle's 5-bit sum.
    check_registered_sum: assert property (
        @(posedge CK) 1'b1 |=> ({Cout, S} == ({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)))
    );

// Sum bits match the low 4 bits of the previous addition.
    check_sum_bits_match: assert property (
        @(posedge CK) 1'b1 |=> ({1'b0, S} == (({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)) & 5'h0F))
    );

// Carry-out matches overflow from the previous addition.
    check_carry_bit_match: assert property (
        @(posedge CK) 1'b1 |=> (Cout == (({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)) > 5'h0F))
    );

// All-zero inputs produce an all-zero registered result.
    check_zero_inputs_produce_zero: assert property (
        @(posedge CK) (A == 4'h0 && B == 4'h0 && Cin == 1'b0) |=> ({Cout, S} == 5'h00)
    );

// Maximum inputs produce the full-scale registered result.
    check_max_inputs_produce_full_scale: assert property (
        @(posedge CK) (A == 4'hF && B == 4'hF && Cin == 1'b1) |=> ({Cout, S} == 5'h1F)
    );

// With B and Cin zero, the registered result passes A through.
    check_pass_through_a_when_b_and_cin_zero: assert property (
        @(posedge CK) (B == 4'h0 && Cin == 1'b0) |=> ({Cout, S} == {1'b0, $past(A)})
    );

// With A and Cin zero, the registered result passes B through.
    check_pass_through_b_when_a_and_cin_zero: assert property (
        @(posedge CK) (A == 4'h0 && Cin == 1'b0) |=> ({Cout, S} == {1'b0, $past(B)})
    );

// out matches the full case mapping.
    check_output_function: assert property (
        @(posedge clk)
        out == ((shift_amt == 2'b00) ? in :
                (shift_amt == 2'b01) ? ((dir == 1'b1) ? {in[2:0], in[3]} : {in[1:0], in[3:2]}) :
                (shift_amt == 2'b10) ? ((dir == 1'b1) ? {in[1:0], in[3:2]} : {in[2:0], in[3]}) :
                                      {in[0], in[3:1]})
    );

// shift_amt 00 passes in directly to out.
    check_shift_amt_00_passthrough: assert property (
        @(posedge clk)
        (shift_amt == 2'b00) |-> (out == in)
    );

// shift_amt 01 dir 1, or shift_amt 10 dir 0, selects {in[2:0],in[3]}.
    check_rotate_pattern_2301: assert property (
        @(posedge clk)
        (((shift_amt == 2'b01) && (dir == 1'b1)) ||
         ((shift_amt == 2'b10) && (dir == 1'b0)))
        |-> (out == {in[2:0], in[3]})
    );

// shift_amt 01 dir 0, or shift_amt 10 dir 1, selects {in[1:0],in[3:2]}.
    check_rotate_pattern_0123: assert property (
        @(posedge clk)
        (((shift_amt == 2'b01) && (dir == 1'b0)) ||
         ((shift_amt == 2'b10) && (dir == 1'b1)))
        |-> (out == {in[1:0], in[3:2]})
    );

// shift_amt 11 selects {in[0],in[3:1]} regardless of dir.
    check_shift_amt_11_mapping: assert property (
        @(posedge clk)
        (shift_amt == 2'b11) |-> (out == {in[0], in[3:1]})
    );

// In add mode, SUM is the low 8 bits of A plus B.
    check_add_mode_sum: assert property (
        @(posedge clk)
        (!SUB) |-> (SUM == (A + B))
    );

// In subtract mode, SUM is the low 8 bits of A plus two's-complement B.
    check_sub_mode_sum: assert property (
        @(posedge clk)
        (SUB) |-> (SUM == (A + (~B + 8'h01)))
    );

// With CIN high in add mode, outputs match the 9-bit sum of A and B.
    check_add_with_cin: assert property (
        @(posedge clk)
        (!SUB && CIN) |-> ({OVF, SUM} == ({1'b0, A} + {1'b0, B}))
    );

// With CIN high in subtract mode, outputs match the 9-bit sum of A and two's-complement B.
    check_sub_with_cin: assert property (
        @(posedge clk)
        (SUB && CIN) |-> ({OVF, SUM} == ({1'b0, A} + {1'b0, (~B + 8'h01)}))
    );

// RTL is combinational; clk is an external sampling clock.
    // There is no reset in the DUT.

    // S=00 passes A directly to B.
    check_passthrough_when_s0: assert property (
        @(posedge clk)
        (S == 2'b00) |-> (B == A)
    );

// D=1 and S=01 rotate then shift right by 1.
    check_right_path_when_s1: assert property (
        @(posedge clk)
        ((D == 1'b1) && (S == 2'b01)) |-> (B == {1'b0, A[2:0]})
    );

// D=1 and S=10 rotate then shift right by 2.
    check_right_path_when_s2: assert property (
        @(posedge clk)
        ((D == 1'b1) && (S == 2'b10)) |-> (B == {2'b00, A[1:0]})
    );

// D=1 and S=11 rotate then shift right by 3.
    check_right_path_when_s3: assert property (
        @(posedge clk)
        ((D == 1'b1) && (S == 2'b11)) |-> (B == {3'b000, A[0]})
    );

// D=0 and S=01 rotate then shift left by 1.
    check_left_path_when_s1: assert property (
        @(posedge clk)
        ((D == 1'b0) && (S == 2'b01)) |-> (B == {A[1:0], A[3], 1'b0})
    );

// D=0 and S=10 rotate then shift left by 2.
    check_left_path_when_s2: assert property (
        @(posedge clk)
        ((D == 1'b0) && (S == 2'b10)) |-> (B == {A[3:2], 2'b00})
    );

// D=0 and S=11 rotate then shift left by 3.
    check_left_path_when_s3: assert property (
        @(posedge clk)
        ((D == 1'b0) && (S == 2'b11)) |-> (B == {A[1], 3'b000})
    );

// Outputs are zero whenever reset is asserted low.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        !rst |-> ((o_0 == 25'sd0) && (o_1 == 25'sd0) && (o_2 == 25'sd0) && (o_3 == 25'sd0))
    );

// A sampled reset-low cycle leaves outputs at zero at the next sample.
    check_reset_holds_zero_to_next_sample: assert property (
        @(posedge clk)
        !rst |=> ((o_0 == 25'sd0) && (o_1 == 25'sd0) && (o_2 == 25'sd0) && (o_3 == 25'sd0))
    );

// o_0 registers the previous-cycle i_0 + i_3 value.
    check_o0_registers_b0: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_0 == $past(i_0 + i_3))
    );

// o_1 registers the previous-cycle i_1 + i_2 value.
    check_o1_registers_b1: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_1 == $past(i_1 + i_2))
    );

// o_2 registers the previous-cycle i_1 - i_2 value.
    check_o2_registers_b2: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_2 == $past(i_1 - i_2))
    );

// o_3 registers the previous-cycle i_0 - i_3 value.
    check_o3_registers_b3: assert property (
        @(posedge clk) disable iff (!rst)
        $past(rst) |-> (o_3 == $past(i_0 - i_3))
    );

// Output matches the mux truth table.
    check_mux_function: assert property (
        @(posedge clk)
        out == ((s == 2'b00) ? in[0] :
                (s == 2'b01) ? in[1] :
                (s == 2'b10) ? in[2] : in[3])
    );

// Select 00 routes in[0] to out.
    check_sel_00: assert property (
        @(posedge clk)
        (s == 2'b00) |-> (out == in[0])
    );

// Select 01 routes in[1] to out.
    check_sel_01: assert property (
        @(posedge clk)
        (s == 2'b01) |-> (out == in[1])
    );

// Select 10 routes in[2] to out.
    check_sel_10: assert property (
        @(posedge clk)
        (s == 2'b10) |-> (out == in[2])
    );

// Select 11 routes in[3] to out.
    check_sel_11: assert property (
        @(posedge clk)
        (s == 2'b11) |-> (out == in[3])
    );

// When SEL is 0, Y must match A.
    check_select_a: assert property (
        @(posedge clk) (SEL === 1'b0) |-> (Y === A)
    );

// When SEL is not 0, Y must match B.
    check_select_b: assert property (
        @(posedge clk) (SEL !== 1'b0) |-> (Y === B)
    );

// Y implements the NOR4-with-inverted-D function.
    check_y_matches_function: assert property (
        @(posedge clk) Y == (!A && !B && !C && D_N)
    );

// A asserted forces the NOR output low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B asserted forces the NOR output low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C asserted forces the NOR output low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D_N low makes the inverted D input high and forces Y low.
    check_dn_low_forces_y_low: assert property (
        @(posedge clk) !D_N |-> !Y
    );

// Y high requires all three direct inputs low and D_N high.
    check_y_high_only_for_all_clear: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && D_N)
    );

// When all three direct inputs are low and D_N is high, Y is high.
    check_all_clear_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> Y
    );

// Checks incrementing 4'hF produces wraparound with carry.
    check_increment_overflow: assert property (
        @(posedge clk) ((A == 4'b1111) && (B == 4'b0000) && (Cin == 1'b1)) |-> ((S == 4'b0000) && (Cout == 1'b1))
    );

// busXOR simplifies to the bitwise NAND of the inputs.
    check_output_nand_function: assert property (
        @(posedge clk) busXOR == (~(busA & busB))
    );

// enclk updates according to the registered enable/te equation.
    check_enclk_next_state: assert property (
        @(posedge clk) 1'b1 |=> (enclk == ($past(en) ? $past(te) : $past(enclk)))
    );

// An enabled cycle with te high drives enclk high on the next clock.
    check_enclk_set_when_enabled_and_te_high: assert property (
        @(posedge clk) en && te |=> enclk
    );

// An enabled cycle with te low drives enclk low on the next clock.
    check_enclk_clear_when_enabled_and_te_low: assert property (
        @(posedge clk) en && !te |=> !enclk
    );

// A disabled cycle leaves enclk unchanged.
    check_enclk_holds_when_disabled: assert property (
        @(posedge clk) !en |=> $stable(enclk)
    );

// X matches the RTL sum-of-products mux equation.
    check_mux_sum_of_products: assert property (
        @(posedge clk)
        X == ((A0 & ~S[1] & ~S[0]) |
              (A1 & ~S[1] &  S[0]) |
              (A2 &  S[1] & ~S[0]) |
              (A3 &  S[1] &  S[0]))
    );

// When S is 00, X routes A0.
    check_sel_00_routes_a0: assert property (
        @(posedge clk) (S == 2'b00) |-> (X == A0)
    );

// When S is 01, X routes A1.
    check_sel_01_routes_a1: assert property (
        @(posedge clk) (S == 2'b01) |-> (X == A1)
    );

// When S is 10, X routes A2.
    check_sel_10_routes_a2: assert property (
        @(posedge clk) (S == 2'b10) |-> (X == A2)
    );

// When S is 11, X routes A3.
    check_sel_11_routes_a3: assert property (
        @(posedge clk) (S == 2'b11) |-> (X == A3)
    );

// clk is the only clock; rst is an active-high synchronous reset.

    // A reset cycle clears count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// On each non-reset cycle, count increments by one on the next cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'h1))
    );

// A maximum count value rolls over to zero on the next non-reset cycle.
    check_count_rollover: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Sum output matches the XOR of the three inputs.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ CIN)
    );

// Carry output matches the implemented generate/propagate logic.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (CIN & (A ^ B)))
    );

// All-zero inputs produce zero sum and zero carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CIN) |-> (!S && !COUT)
    );

// Any one-hot input combination produces sum only.
    check_one_hot_case: assert property (
        @(posedge clk) $onehot({A, B, CIN}) |-> (S && !COUT)
    );

// Any two-high input combination produces carry only.
    check_two_high_case: assert property (
        @(posedge clk) ((A && B && !CIN) || (A && CIN && !B) || (B && CIN && !A)) |-> (!S && COUT)
    );

// All-high inputs produce both sum and carry.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && CIN) |-> (S && COUT)
    );

// Combinational RTL with no native clock or reset; clk is a sampling clock.

    // ctrl=00 inverts all input bits.
    check_invert_mode: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (out_data == ~in_data)
    );

// ctrl=01 computes the two's complement of the input.
    check_twos_complement_mode: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (out_data == (~in_data + 4'b0001))
    );

// ctrl=10 shifts left by one and inserts zero at the LSB.
    check_left_shift_mode: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (out_data == {in_data[2:0], 1'b0})
    );

// ctrl=11 shifts right by one and inserts zero at the MSB.
    check_right_shift_mode: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (out_data == {1'b0, in_data[3:1]})
    );

// Addition mode drives result to A plus B.
    check_addition_mode: assert property (
        @(posedge clk) (op == 1'b1) |-> (result == (A + B))
    );

// Subtraction mode drives result to A minus B.
    check_subtraction_mode: assert property (
        @(posedge clk) (op == 1'b0) |-> (result == (A - B))
    );

// Result always matches the operation selected by op.
    check_selected_operation: assert property (
        @(posedge clk) result == (op ? (A + B) : (A - B))
    );

// Adding zero on B leaves A unchanged.
    check_add_zero_identity: assert property (
        @(posedge clk) (op == 1'b1 && B == 4'h0) |-> (result == A)
    );

// Subtracting zero leaves A unchanged.
    check_subtract_zero_identity: assert property (
        @(posedge clk) (op == 1'b0 && B == 4'h0) |-> (result == A)
    );

// Subtracting equal operands produces zero.
    check_equal_operands_subtract_zero: assert property (
        @(posedge clk) (op == 1'b0 && A == B) |-> (result == 4'h0)
    );

// pos[0] is high only when all encoder inputs are low.
    check_encoder_pos_lsb: assert property (
        @(posedge clk) pos[0] == ~(|in)
    );

// pos[1] matches the implemented enc_out[1] truth table.
    check_encoder_pos_msb: assert property (
        @(posedge clk) pos[1] == (in[3] & ~(in[2] ^ in[1]))
    );

// q[0] captures d from the previous clock edge.
    check_shift_reg_q0_updates: assert property (
        @(posedge clk) 1'b1 |=> (q[0] == $past(d))
    );

// q[1] captures the previous value of q[0].
    check_shift_reg_q1_updates: assert property (
        @(posedge clk) 1'b1 |=> (q[1] == $past(q[0]))
    );

// q[2] captures the previous value of q[1].
    check_shift_reg_q2_updates: assert property (
        @(posedge clk) 1'b1 |=> (q[2] == $past(q[1]))
    );

// out is the XOR of q[2] and the encoder MSB.
    check_out_xor_function: assert property (
        @(posedge clk) out[0] == (q[2] ^ pos[1])
    );

// Full 5-bit result matches the arithmetic sum.
    check_full_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Sum bit 0 is the XOR of the LSB inputs and carry-in.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Sum bit 1 uses the carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ maj3(a[0], b[0], cin))
    );

// Sum bit 2 uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (a[2] ^ b[2] ^ maj3(a[1], b[1], maj3(a[0], b[0], cin)))
    );

// Sum bit 3 uses the ripple carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (a[3] ^ b[3] ^ maj3(a[2], b[2], maj3(a[1], b[1], maj3(a[0], b[0], cin))))
    );

// Carry-out is the final ripple carry from the MSB stage.
    check_cout_bit: assert property (
        @(posedge clk) cout == maj3(a[3], b[3], maj3(a[2], b[2], maj3(a[1], b[1], maj3(a[0], b[0], cin))))
    );

// Any fully known input decodes to the matching one-hot output.
    check_decode_mapping_known: assert property (
        @(posedge clk) !$isunknown(A) |-> (Y === (16'h0001 << A))
    );

// Any input containing X or Z drives the default zero output.
    check_default_zero_for_unknown_input: assert property (
        @(posedge clk) $isunknown(A) |-> (Y === 16'h0000)
    );

// Any fully known input produces exactly one asserted output bit.
    check_onehot_for_known_input: assert property (
        @(posedge clk) !$isunknown(A) |-> $onehot(Y)
    );

// A zero output can only occur when the input falls through the default case.
    check_zero_output_only_for_unknown_input: assert property (
        @(posedge clk) (Y === 16'h0000) |-> $isunknown(A)
    );

// o_0r0 is i_0r0 gated by the inverse of o_0a.
    check_o0r0_gate: assert property (
        @(posedge clk) disable iff (reset)
        o_0r0 == (i_0r0 & ~o_0a)
    );

// o_0r1 is i_0r1 gated by the inverse of o_0a.
    check_o0r1_gate: assert property (
        @(posedge clk) disable iff (reset)
        o_0r1 == (i_0r1 & ~o_0a)
    );

// i_0a is the OR of the two output request signals.
    check_i0a_from_outputs: assert property (
        @(posedge clk) disable iff (reset)
        i_0a == (o_0r0 | o_0r1)
    );

// i_0a equals the gated OR of the two input request signals.
    check_i0a_from_inputs: assert property (
        @(posedge clk) disable iff (reset)
        i_0a == ((i_0r0 | i_0r1) & ~o_0a)
    );

// o_0a high blocks o_0r0.
    check_o0a_blocks_o0r0: assert property (
        @(posedge clk) disable iff (reset)
        o_0a |-> !o_0r0
    );

// o_0a high blocks o_0r1.
    check_o0a_blocks_o0r1: assert property (
        @(posedge clk) disable iff (reset)
        o_0a |-> !o_0r1
    );

// o_0a high blocks i_0a.
    check_o0a_blocks_i0a: assert property (
        @(posedge clk) disable iff (reset)
        o_0a |-> !i_0a
    );

// o_0r0 can only be high when i_0r0 is high and o_0a is low.
    check_o0r0_source_conditions: assert property (
        @(posedge clk) disable iff (reset)
        o_0r0 |-> (i_0r0 && !o_0a)
    );

// o_0r1 can only be high when i_0r1 is high and o_0a is low.
    check_o0r1_source_conditions: assert property (
        @(posedge clk) disable iff (reset)
        o_0r1 |-> (i_0r1 && !o_0a)
    );

// Any asserted output request drives i_0a high.
    check_output_request_sets_i0a: assert property (
        @(posedge clk) disable iff (reset)
        (o_0r0 || o_0r1) |-> i_0a
    );

// Combinational decoder sampled on external clk; no reset in RTL.

    // Output must equal the one-hot decode of the 5-bit input.
    check_decode_matches_shift: assert property (
        @(posedge clk) b == (32'h0000_0001 << a)
    );

// Exactly one output bit must be asserted.
    check_output_is_onehot: assert property (
        @(posedge clk) $onehot(b)
    );

// Inputs with a[4:3]==00 can only drive outputs 0 through 7.
    check_quadrant_00_range: assert property (
        @(posedge clk) (a[4:3] == 2'b00) |-> (b[31:8] == 24'h0)
    );

// Inputs with a[4:3]==01 can only drive outputs 8 through 15.
    check_quadrant_01_range: assert property (
        @(posedge clk) (a[4:3] == 2'b01) |-> ((b[31:16] == 16'h0) && (b[7:0] == 8'h0))
    );

// Inputs with a[4:3]==10 can only drive outputs 16 through 23.
    check_quadrant_10_range: assert property (
        @(posedge clk) (a[4:3] == 2'b10) |-> ((b[31:24] == 8'h0) && (b[15:0] == 16'h0))
    );

// Inputs with a[4:3]==11 can only drive outputs 24 through 31.
    check_quadrant_11_range: assert property (
        @(posedge clk) (a[4:3] == 2'b11) |-> (b[23:0] == 24'h0)
    );

// Input 0 must select b[0].
    check_zero_input_decode: assert property (
        @(posedge clk) (a == 5'd0) |-> (b == 32'h0000_0001)
    );

// Input 15 must select b[15].
    check_input_15_decode: assert property (
        @(posedge clk) (a == 5'd15) |-> (b == 32'h0000_8000)
    );

// Input 16 must select b[16].
    check_input_16_decode: assert property (
        @(posedge clk) (a == 5'd16) |-> (b == 32'h0001_0000)
    );

// Input 31 must select b[31].
    check_max_input_decode: assert property (
        @(posedge clk) (a == 5'd31) |-> (b == 32'h8000_0000)
    );

// Reset forces all synchronized reset outputs low.
    check_reset_forces_low: assert property (
        @(posedge clk)
        !reset_n |-> (reset_n_sync == ALL_ZERO)
    );

// Output stays low before the release delay expires.
                check_release_low_before_assert: assert property (
                    @(posedge clk) disable iff (!reset_n)
                    $rose(reset_n) |-> ##d (reset_n_sync == ALL_ZERO)
                );

// Output stays low before the release delay expires.
                check_release_low_before_assert: assert property (
                    @(posedge clk) disable iff (!reset_n)
                    $rose(reset_n) |-> ##d (reset_n_sync == ALL_ZERO)
                );

// Output stays low before the release delay expires.
                check_release_low_before_assert: assert property (
                    @(posedge clk) disable iff (!reset_n)
                    $rose(reset_n) |-> ##d (reset_n_sync == ALL_ZERO)
                );

// A single-stage case stays high one clock later.
            check_release_stays_high_next_cycle: assert property (
                @(posedge clk) disable iff (!reset_n)
                $rose(reset_n) |-> ##1 (reset_n_sync == ALL_ONE)
            );

// Sampling clock: clk.
    // Reset: none in RTL.
    // DUT is a combinational 4-bit ripple-carry adder.

    // Full 5-bit result matches A + B + CIN.
    check_total_sum: assert property (
        @(posedge clk)
        {COUT, S} == ({1'b0, A} + {1'b0, B} + CIN)
    );

// Bit 0 sum matches the first full adder.
    check_bit0_sum: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ CIN)
    );

// Bit 1 sum uses the carry from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk)
        S[1] == (
            A[1] ^ B[1] ^
            ((A[0] & B[0]) | ((A[0] ^ B[0]) & CIN))
        )
    );

// Bit 2 sum uses the carry from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk)
        S[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & CIN)))
            )
        )
    );

// Bit 3 sum uses the carry from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk)
        S[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                ((A[2] ^ B[2]) & (
                    (A[1] & B[1]) |
                    ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & CIN)))
                ))
            )
        )
    );

// Final carry-out matches the last full adder.
    check_final_carry: assert property (
        @(posedge clk)
        COUT == (
            (A[3] & B[3]) |
            ((A[3] ^ B[3]) & (
                (A[2] & B[2]) |
                ((A[2] ^ B[2]) & (
                    (A[1] & B[1]) |
                    ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & CIN)))
                ))
            ))
        )
    );

// Adding zero on B with no carry-in returns A.
    check_add_zero_on_b: assert property (
        @(posedge clk)
        ((B == 4'h0) && (CIN == 1'b0)) |-> ({COUT, S} == {1'b0, A})
    );

// Adding zero on A with no carry-in returns B.
    check_add_zero_on_a: assert property (
        @(posedge clk)
        ((A == 4'h0) && (CIN == 1'b0)) |-> ({COUT, S} == {1'b0, B})
    );

// Zero operands reduce the result to the carry-in.
    check_zero_operands_cin_only: assert property (
        @(posedge clk)
        ((A == 4'h0) && (B == 4'h0)) |-> ({COUT, S} == {4'h0, CIN})
    );

// oLDST_REQ selects the request source by iUSE_SEL.
    check_ldst_req_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_REQ == (iUSE_SEL ? iEXCEPT_REQ : iEXE_REQ))
    );

// oLDST_ORDER selects exception or execution order by iUSE_SEL.
    check_ldst_order_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_ORDER == (iUSE_SEL ? iEXCEPT_ORDER : iEXE_ORDER))
    );

// oLDST_MASK is fixed to 4'hf for exception traffic, else iEXE_MASK.
    check_ldst_mask_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_MASK == (iUSE_SEL ? 4'hf : iEXE_MASK))
    );

// oLDST_RW selects the read/write control by iUSE_SEL.
    check_ldst_rw_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_RW == (iUSE_SEL ? iEXCEPT_RW : iEXE_RW))
    );

// oLDST_TID selects the transaction ID by iUSE_SEL.
    check_ldst_tid_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_TID == (iUSE_SEL ? iEXCEPT_TID : iEXE_TID))
    );

// oLDST_MMUMOD selects the MMU mode by iUSE_SEL.
    check_ldst_mmumod_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_MMUMOD == (iUSE_SEL ? iEXCEPT_MMUMOD : iEXE_MMUMOD))
    );

// oLDST_PDT selects the PDT value by iUSE_SEL.
    check_ldst_pdt_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_PDT == (iUSE_SEL ? iEXCEPT_PDT : iEXE_PDT))
    );

// oLDST_ADDR selects the address by iUSE_SEL.
    check_ldst_addr_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_ADDR == (iUSE_SEL ? iEXCEPT_ADDR : iEXE_ADDR))
    );

// oLDST_DATA selects the write data by iUSE_SEL.
    check_ldst_data_mux: assert property (
        @(posedge clk) disable iff (1'b0)
        (oLDST_DATA == (iUSE_SEL ? iEXCEPT_DATA : iEXE_DATA))
    );

// Exception busy mirrors iLDST_BUSY only when exception is selected.
    check_except_busy_routing: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXCEPT_BUSY == (iUSE_SEL ? iLDST_BUSY : 1'b1))
    );

// Exception request is valid only when exception is selected.
    check_except_req_routing: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXCEPT_REQ == (iUSE_SEL ? iLDST_VALID : 1'b0))
    );

// Exception data always forwards iLDST_DATA.
    check_except_data_forward: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXCEPT_DATA == iLDST_DATA)
    );

// Execution busy mirrors iLDST_BUSY only when execution is selected.
    check_exe_busy_routing: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXE_BUSY == (iUSE_SEL ? 1'b1 : iLDST_BUSY))
    );

// Execution request is valid only when execution is selected.
    check_exe_req_routing: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXE_REQ == (iUSE_SEL ? 1'b0 : iLDST_VALID))
    );

// Execution pagefault always forwards iLDST_PAGEFAULT.
    check_exe_pagefault_forward: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXE_PAGEFAULT == iLDST_PAGEFAULT)
    );

// Execution MMU flags always forward iLDST_MMU_FLAGS.
    check_exe_mmu_flags_forward: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXE_MMU_FLAGS == iLDST_MMU_FLAGS)
    );

// Execution data always forwards iLDST_DATA.
    check_exe_data_forward: assert property (
        @(posedge clk) disable iff (1'b0)
        (oEXE_DATA == iLDST_DATA)
    );

// A low input forces all outputs low.
    check_input_low_clears_all: assert property (
        @(posedge clk) (!in) |-> (out == '0)
    );

// A high input produces exactly one asserted output.
    check_input_high_onehot: assert property (
        @(posedge clk) in |-> $onehot(out)
    );

// Out equals the reduction OR of the input bus.
    check_out_matches_reduction_or: assert property (
        @(posedge clk) out === (|in)
    );

// Zero input drives the output low.
    check_zero_input_drives_low: assert property (
        @(posedge clk) ((|in) === 1'b0) |-> (out === 1'b0)
    );

// Any set input bit drives the output high.
    check_nonzero_input_drives_high: assert property (
        @(posedge clk) ((|in) === 1'b1) |-> (out === 1'b1)
    );

// A low output means no input bits are set.
    check_low_output_implies_zero_input: assert property (
        @(posedge clk) (out === 1'b0) |-> ((|in) === 1'b0)
    );

// A high output means at least one input bit is set.
    check_high_output_implies_nonzero_input: assert property (
        @(posedge clk) (out === 1'b1) |-> ((|in) === 1'b1)
    );

// In addition mode, result captures the prior cycle sum.
    check_addition_mode: assert property (
        @(posedge clk) (mode == 1'b1) |=> (result == ($past(a) + $past(b)))
    );

// In subtraction mode, result captures the prior cycle difference.
    check_subtraction_mode: assert property (
        @(posedge clk) (mode == 1'b0) |=> (result == ($past(a) - $past(b)))
    );

// Result always matches the prior cycle operation selected by mode.
    check_selected_operation: assert property (
        @(posedge clk) 1'b1 |=> (result == ($past(mode) ? ($past(a) + $past(b)) : ($past(a) - $past(b))))
    );

// Adding zero passes a through on the next cycle.
    check_add_zero_identity: assert property (
        @(posedge clk) ((mode == 1'b1) && (b == 4'b0000)) |=> (result == $past(a))
    );

// Subtracting zero passes a through on the next cycle.
    check_sub_zero_identity: assert property (
        @(posedge clk) ((mode == 1'b0) && (b == 4'b0000)) |=> (result == $past(a))
    );

// Subtracting equal operands yields zero on the next cycle.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) ((mode == 1'b0) && (a == b)) |=> (result == 4'b0000)
    );

// Count is zero whenever the active-low reset is asserted.
    check_reset_clears_count: assert property (
        @(posedge clock) !reset |-> (count == 4'h0)
    );

// A load sampled on the prior clock drives the count to zero.
    check_load_clears_count: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && $past(load)) |-> (count == 4'h0)
    );

// An up-count step that ends nonzero must be previous count plus one.
    check_count_up_nonzero_step: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && $past(up_down) && (count != 4'h0))
        |-> (count == ($past(count) + 4'h1))
    );

// Counting up from 4'hF wraps to 4'h0.
    check_count_up_wrap_to_zero: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && $past(up_down) && ($past(count) == 4'hF))
        |-> (count == 4'h0)
    );

// A down-count step that ends nonzero must be previous count minus one.
    check_count_down_nonzero_step: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && !$past(up_down) && (count != 4'h0))
        |-> (count == ($past(count) - 4'h1))
    );

// Counting down from 4'h1 reaches 4'h0.
    check_count_down_to_zero: assert property (
        @(posedge clock) disable iff (!reset)
        ($past(reset) && !$past(load) && !$past(up_down) && ($past(count) == 4'h1))
        |-> (count == 4'h0)
    );

// Reset clears all stages and the output.
    check_reset_clears_state: assert property (
        @(posedge clk)
        reset |=> (reg1 == 4'b0000) &&
                  (reg2 == 4'b0000) &&
                  (reg3 == 4'b0000) &&
                  (reg4 == 4'b0000) &&
                  (data_out == 4'b0000)
    );

// A loaded input value appears at the output four cycles later.
    check_load_reaches_output_after_four_cycles: assert property (
        @(posedge clk) disable iff (reset)
        load |-> ##4 (data_out == $past(data_in, 4))
    );

// Output must equal the one-hot decode of the 3-bit input.
    check_decode_function: assert property (
        @(posedge clk) out == (8'b00000001 << in)
    );

// Output must always contain exactly one asserted bit.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// Input 000 must decode to bit 0.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b00000001)
    );

// Input 001 must decode to bit 1.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b00000010)
    );

// Input 010 must decode to bit 2.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b00000100)
    );

// Input 011 must decode to bit 3.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b00001000)
    );

// Input 100 must decode to bit 4.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b00010000)
    );

// Input 101 must decode to bit 5.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b00100000)
    );

// Input 110 must decode to bit 6.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b01000000)
    );

// Input 111 must decode to bit 7.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b10000000)
    );

// Reset forces the counter to zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// Load updates count with data_in on the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// Load has priority over increment when both are asserted.
    check_load_priority_over_increment: assert property (
        @(posedge clk) disable iff (reset) (load && up_down) |=> (count == $past(data_in))
    );

// Without load, up_down high increments the counter.
    check_increment_operation: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// Without load, up_down low decrements the counter.
    check_decrement_operation: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// Increment wraps from 4'hF to 4'h0.
    check_increment_wraparound: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down && (count == 4'hF)) |=> (count == 4'h0)
    );

// Decrement wraps from 4'h0 to 4'hF.
    check_decrement_wraparound: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down && (count == 4'h0)) |=> (count == 4'hF)
    );

// Active-low reset forces the counter output to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count_out == 4'b0000)
    );

// When load is high, the counter captures data_in on the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!rst)
        load |=> (count_out == $past(data_in))
    );

// When load is low, the counter increments by one on the next clock.
    check_increment_when_not_load: assert property (
        @(posedge clk) disable iff (!rst)
        !load |=> (count_out == ($past(count_out) + 4'b0001))
    );

// The overall next-state behavior matches the RTL load-or-increment logic.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (count_out == ($past(load) ? $past(data_in) : ($past(count_out) + 4'b0001)))
    );

// Incrementing from 4'hF wraps around to 4'h0.
    check_wraparound_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && (count_out == 4'hF)) |=> (count_out == 4'h0)
    );

// X implements (A1 | A2) & ~B1_N.
    check_boolean_function: assert property (
        @(posedge clk) X == ((A1 | A2) & ~B1_N)
    );

// B1_N high blocks the output.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk) (B1_N == 1'b1) |-> (X == 1'b0)
    );

// With both A inputs low, the output is low.
    check_a_inputs_low_forces_x_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// A low B1_N and any asserted A input drives the output high.
    check_enabled_a_path_drives_x_high: assert property (
        @(posedge clk) ((B1_N == 1'b0) && ((A1 == 1'b1) || (A2 == 1'b1))) |-> (X == 1'b1)
    );

// A high output requires B1_N to be low.
    check_x_high_requires_b1n_low: assert property (
        @(posedge clk) (X == 1'b1) |-> (B1_N == 1'b0)
    );

// A high output requires at least one A input high.
    check_x_high_requires_a_input: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A1 == 1'b1) || (A2 == 1'b1))
    );

// Synchronous reset loads Q with zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |=> (Q == 4'b0000)
    );

// When counting up, Q increments by one.
    check_count_up_increments_q: assert property (
        @(posedge CLK) disable iff (RST)
        UP_DOWN |=> (Q == ($past(Q) + 4'b0001))
    );

// When counting down, Q decrements by one.
    check_count_down_decrements_q: assert property (
        @(posedge CLK) disable iff (RST)
        !UP_DOWN |=> (Q == ($past(Q) - 4'b0001))
    );

// Counting up wraps from 15 back to 0.
    check_count_up_wraps_to_zero: assert property (
        @(posedge CLK) disable iff (RST)
        (UP_DOWN && (Q == 4'b1111)) |=> (Q == 4'b0000)
    );

// Counting down wraps from 0 back to 15.
    check_count_down_wraps_to_max: assert property (
        @(posedge CLK) disable iff (RST)
        (!UP_DOWN && (Q == 4'b0000)) |=> (Q == 4'b1111)
    );

// One cycle later, q uses the prior sampled d and current selected input bit.
    check_q_end_to_end_behavior: assert property (
        @(posedge clk) 1'b1 |=> (q == ($past(d) ^ in[8'd255 - sel]))
    );

// No clock or reset exists in the DUT; clk is an external sampling clock.
    // The DUT is combinational and selects the first low bit from [25] down to [0].

    // If bit 25 is low, the output maps to 0.
    check_bit25_low_maps_to_0: assert property (
        @(posedge clk) (~Data_Dec_i[25]) |-> (Data_Bin_o == 5'b00000)
    );

// If bit 24 is the first low bit, the output maps to 1.
    check_bit24_first_low_maps_to_1: assert property (
        @(posedge clk) (Data_Dec_i[25] && (~Data_Dec_i[24])) |-> (Data_Bin_o == 5'b00001)
    );

// If bit 23 is the first low bit, the output maps to 2.
    check_bit23_first_low_maps_to_2: assert property (
        @(posedge clk) ((&Data_Dec_i[25:24]) && (~Data_Dec_i[23])) |-> (Data_Bin_o == 5'b00010)
    );

// If bit 22 is the first low bit, the output maps to 3.
    check_bit22_first_low_maps_to_3: assert property (
        @(posedge clk) ((&Data_Dec_i[25:23]) && (~Data_Dec_i[22])) |-> (Data_Bin_o == 5'b00011)
    );

// If bit 21 is the first low bit, the output maps to 4.
    check_bit21_first_low_maps_to_4: assert property (
        @(posedge clk) ((&Data_Dec_i[25:22]) && (~Data_Dec_i[21])) |-> (Data_Bin_o == 5'b00100)
    );

// If bit 20 is the first low bit, the output maps to 5.
    check_bit20_first_low_maps_to_5: assert property (
        @(posedge clk) ((&Data_Dec_i[25:21]) && (~Data_Dec_i[20])) |-> (Data_Bin_o == 5'b00101)
    );

// If bit 19 is the first low bit, the output maps to 6.
    check_bit19_first_low_maps_to_6: assert property (
        @(posedge clk) ((&Data_Dec_i[25:20]) && (~Data_Dec_i[19])) |-> (Data_Bin_o == 5'b00110)
    );

// If bit 18 is the first low bit, the output maps to 7.
    check_bit18_first_low_maps_to_7: assert property (
        @(posedge clk) ((&Data_Dec_i[25:19]) && (~Data_Dec_i[18])) |-> (Data_Bin_o == 5'b00111)
    );

// If bit 17 is the first low bit, the output maps to 8.
    check_bit17_first_low_maps_to_8: assert property (
        @(posedge clk) ((&Data_Dec_i[25:18]) && (~Data_Dec_i[17])) |-> (Data_Bin_o == 5'b01000)
    );

// If bit 16 is the first low bit, the output maps to 9.
    check_bit16_first_low_maps_to_9: assert property (
        @(posedge clk) ((&Data_Dec_i[25:17]) && (~Data_Dec_i[16])) |-> (Data_Bin_o == 5'b01001)
    );

// If bit 15 is the first low bit, the output maps to 10.
    check_bit15_first_low_maps_to_10: assert property (
        @(posedge clk) ((&Data_Dec_i[25:16]) && (~Data_Dec_i[15])) |-> (Data_Bin_o == 5'b01010)
    );

// If bit 14 is the first low bit, the output maps to 11.
    check_bit14_first_low_maps_to_11: assert property (
        @(posedge clk) ((&Data_Dec_i[25:15]) && (~Data_Dec_i[14])) |-> (Data_Bin_o == 5'b01011)
    );

// If bit 13 is the first low bit, the output maps to 12.
    check_bit13_first_low_maps_to_12: assert property (
        @(posedge clk) ((&Data_Dec_i[25:14]) && (~Data_Dec_i[13])) |-> (Data_Bin_o == 5'b01100)
    );

// If bit 12 is the first low bit, the output maps to 13.
    check_bit12_first_low_maps_to_13: assert property (
        @(posedge clk) ((&Data_Dec_i[25:13]) && (~Data_Dec_i[12])) |-> (Data_Bin_o == 5'b01101)
    );

// If bit 11 is the first low bit, the output maps to 14.
    check_bit11_first_low_maps_to_14: assert property (
        @(posedge clk) ((&Data_Dec_i[25:12]) && (~Data_Dec_i[11])) |-> (Data_Bin_o == 5'b01110)
    );

// If bit 10 is the first low bit, the output maps to 15.
    check_bit10_first_low_maps_to_15: assert property (
        @(posedge clk) ((&Data_Dec_i[25:11]) && (~Data_Dec_i[10])) |-> (Data_Bin_o == 5'b01111)
    );

// If bit 9 is the first low bit, the output maps to 16.
    check_bit9_first_low_maps_to_16: assert property (
        @(posedge clk) ((&Data_Dec_i[25:10]) && (~Data_Dec_i[9])) |-> (Data_Bin_o == 5'b10000)
    );

// If bit 8 is the first low bit, the output maps to 17.
    check_bit8_first_low_maps_to_17: assert property (
        @(posedge clk) ((&Data_Dec_i[25:9]) && (~Data_Dec_i[8])) |-> (Data_Bin_o == 5'b10001)
    );

// If bit 7 is the first low bit, the output maps to 18.
    check_bit7_first_low_maps_to_18: assert property (
        @(posedge clk) ((&Data_Dec_i[25:8]) && (~Data_Dec_i[7])) |-> (Data_Bin_o == 5'b10010)
    );

// If bit 6 is the first low bit, the output maps to 19.
    check_bit6_first_low_maps_to_19: assert property (
        @(posedge clk) ((&Data_Dec_i[25:7]) && (~Data_Dec_i[6])) |-> (Data_Bin_o == 5'b10011)
    );

// If bit 5 is the first low bit, the output maps to 20.
    check_bit5_first_low_maps_to_20: assert property (
        @(posedge clk) ((&Data_Dec_i[25:6]) && (~Data_Dec_i[5])) |-> (Data_Bin_o == 5'b10100)
    );

// If bit 4 is the first low bit, the output maps to 21.
    check_bit4_first_low_maps_to_21: assert property (
        @(posedge clk) ((&Data_Dec_i[25:5]) && (~Data_Dec_i[4])) |-> (Data_Bin_o == 5'b10101)
    );

// If bit 3 is the first low bit, the output maps to 22.
    check_bit3_first_low_maps_to_22: assert property (
        @(posedge clk) ((&Data_Dec_i[25:4]) && (~Data_Dec_i[3])) |-> (Data_Bin_o == 5'b10110)
    );

// If bit 2 is the first low bit, the output maps to 23.
    check_bit2_first_low_maps_to_23: assert property (
        @(posedge clk) ((&Data_Dec_i[25:3]) && (~Data_Dec_i[2])) |-> (Data_Bin_o == 5'b10111)
    );

// If bit 1 is the first low bit, the output maps to 24.
    check_bit1_first_low_maps_to_24: assert property (
        @(posedge clk) ((&Data_Dec_i[25:2]) && (~Data_Dec_i[1])) |-> (Data_Bin_o == 5'b11000)
    );

// If bit 0 is the first low bit, the output maps to 21 per the RTL.
    check_bit0_first_low_maps_to_21: assert property (
        @(posedge clk) ((&Data_Dec_i[25:1]) && (~Data_Dec_i[0])) |-> (Data_Bin_o == 5'b10101)
    );

// If all bits are high, the fall-through output is 0.
    check_all_high_maps_to_0: assert property (
        @(posedge clk) (&Data_Dec_i[25:0]) |-> (Data_Bin_o == 5'b00000)
    );

// A4 has highest priority and forces X to 11.
    check_a4_priority: assert property (
        @(posedge clk) A4 |-> (X == 2'b11)
    );

// A3 is encoded as 10 when A4 is low.
    check_a3_priority: assert property (
        @(posedge clk) (!A4 && A3) |-> (X == 2'b10)
    );

// A2 is encoded as 01 when A4 and A3 are low.
    check_a2_priority: assert property (
        @(posedge clk) (!A4 && !A3 && A2) |-> (X == 2'b01)
    );

// A1 is encoded as 00 when all higher-priority inputs are low.
    check_a1_encoding: assert property (
        @(posedge clk) (!A4 && !A3 && !A2 && A1) |-> (X == 2'b00)
    );

// No asserted inputs produce 00.
    check_no_input_encoding: assert property (
        @(posedge clk) (!A4 && !A3 && !A2 && !A1) |-> (X == 2'b00)
    );

// Output 11 can only occur when A4 is asserted.
    check_x11_source: assert property (
        @(posedge clk) (X == 2'b11) |-> A4
    );

// Output 10 can only occur when A3 is asserted and A4 is low.
    check_x10_source: assert property (
        @(posedge clk) (X == 2'b10) |-> (!A4 && A3)
    );

// Output 01 can only occur when A2 is asserted and higher inputs are low.
    check_x01_source: assert property (
        @(posedge clk) (X == 2'b01) |-> (!A4 && !A3 && A2)
    );

// Output 00 requires all higher-priority inputs to be low.
    check_x00_source: assert property (
        @(posedge clk) (X == 2'b00) |-> (!A4 && !A3 && !A2)
    );

// X matches the priority-encoded value of the inputs.
    check_full_function: assert property (
        @(posedge clk) X == (A4 ? 2'b11 : (A3 ? 2'b10 : (A2 ? 2'b01 : 2'b00)))
    );

// Output always equals the inversion of the input.
    check_inversion_function: assert property (
        @(posedge clk) Y === ~A
    );

// A low input drives Y high.
    check_low_input_high_output: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// A high input drives Y low.
    check_high_input_low_output: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// A known input produces a known output.
    check_known_input_known_output: assert property (
        @(posedge clk) !$isunknown(A) |-> !$isunknown(Y)
    );

// Sampling clock only; the RTL has no clock or reset.
    // DUT is combinational: X = ~(B1_N | ~(A1 | A2)).

    // X must match the implemented boolean function.
    check_output_function: assert property (
        @(posedge clk) X == (~(B1_N | ~(A1 | A2)))
    );

// A high B1_N forces the second NOR output low.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk) B1_N |-> !X
    );

// Both A inputs low force the first NOR high and X low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// A1 can drive X high when B1_N is low.
    check_a1_high_with_b1n_low_drives_x_high: assert property (
        @(posedge clk) (!B1_N && A1) |-> X
    );

// A2 can drive X high when B1_N is low.
    check_a2_high_with_b1n_low_drives_x_high: assert property (
        @(posedge clk) (!B1_N && A2) |-> X
    );

// ENCLK is low whenever CLK is sampled low.
    check_enclk_low_on_clk_low_phase: assert property (
        @(posedge CLK) ENCLK == 1'b0
    );

// With both controls high, ENCLK is high while CLK is high.
    check_enclk_high_when_en_and_te_high: assert property (
        @(negedge CLK) ((EN == 1'b1) && (TE == 1'b1)) |-> (ENCLK == 1'b1)
    );

// ENCLK is low while CLK is high if EN is low.
    check_enclk_low_when_en_low: assert property (
        @(negedge CLK) (EN == 1'b0) |-> (ENCLK == 1'b0)
    );

// ENCLK is low while CLK is high if TE is low.
    check_enclk_low_when_te_low: assert property (
        @(negedge CLK) (TE == 1'b0) |-> (ENCLK == 1'b0)
    );

// ENCLK can only be high while CLK is high when both controls are high.
    check_enclk_high_requires_en_and_te: assert property (
        @(negedge CLK) (ENCLK == 1'b1) |-> ((EN == 1'b1) && (TE == 1'b1))
    );

// Addition opcode drives the sum of A and B.
    check_addition: assert property (
        @(posedge clk) (opcode == 3'b000) |-> (out == (A + B))
    );

// Subtraction opcode drives A minus B.
    check_subtraction: assert property (
        @(posedge clk) (opcode == 3'b001) |-> (out == (A - B))
    );

// AND opcode drives the bitwise AND of A and B.
    check_bitwise_and: assert property (
        @(posedge clk) (opcode == 3'b100) |-> (out == (A & B))
    );

// OR opcode drives the bitwise OR of A and B.
    check_bitwise_or: assert property (
        @(posedge clk) (opcode == 3'b101) |-> (out == (A | B))
    );

// XOR opcode drives the bitwise XOR of A and B.
    check_bitwise_xor: assert property (
        @(posedge clk) (opcode == 3'b110) |-> (out == (A ^ B))
    );

// The default opcode value drives zero.
    check_default_zero: assert property (
        @(posedge clk) (opcode == 3'b111) |-> (out == 8'h00)
    );

// Y must match the implemented AOI311 function.
    check_y_matches_a311oi_function: assert property (
        @(posedge clk) Y == ~((A1 & A2 & A3) | B1 | C1)
    );

// B1 high must force Y low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// C1 high must force Y low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// All three A inputs high must force Y low.
    check_a_triplet_forces_y_low: assert property (
        @(posedge clk) (A1 && A2 && A3) |-> !Y
    );

// With no asserted NOR inputs, Y must be high.
    check_y_high_when_no_or_term: assert property (
        @(posedge clk) (!B1 && !C1 && !(A1 && A2 && A3)) |-> Y
    );

// A high Y implies none of the NOR inputs are asserted.
    check_y_high_implies_no_or_term: assert property (
        @(posedge clk) Y |-> (!B1 && !C1 && !(A1 && A2 && A3))
    );

// If B1 and C1 are low and Y is low, the A triplet must be high.
    check_y_low_without_b1_c1_requires_a_triplet: assert property (
        @(posedge clk) (!B1 && !C1 && !Y) |-> (A1 && A2 && A3)
    );

// Y must equal the XNOR of A and B.
    check_xnor_function: assert property (
        @(posedge clk) Y == (A ~^ B)
    );

// Matching inputs must drive Y high.
    check_equal_inputs_high: assert property (
        @(posedge clk) (A == B) |-> (Y == 1'b1)
    );

// Different inputs must drive Y low.
    check_different_inputs_low: assert property (
        @(posedge clk) (A != B) |-> (Y == 1'b0)
    );

// Reset clears q on the following clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// q stays zero across consecutive reset cycles.
    check_reset_holds_q_zero: assert property (
        @(posedge clk) reset ##1 reset |-> (q == 4'b0000)
    );

// When not in reset, q captures d on the next clock.
    check_q_captures_d: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (q == $past(d))
    );

// No reset in RTL; this combinational logic is sampled on clk.

    // Output matches the selected add/sub result.
    check_function_select: assert property (
        @(posedge clk) (S == (sub ? (A + (~B + 4'b0001)) : (A + B)))
    );

// In add mode, S is A plus B.
    check_add_mode_result: assert property (
        @(posedge clk) (!sub) |-> (S == (A + B))
    );

// In subtract mode, S is A plus two's complement of B.
    check_sub_mode_result: assert property (
        @(posedge clk) sub |-> (S == (A + (~B + 4'b0001)))
    );

// B equal to zero leaves A unchanged in either mode.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> (S == A)
    );

// In add mode, zero on A passes B through.
    check_add_zero_a_passthrough: assert property (
        @(posedge clk) ((!sub) && (A == 4'h0)) |-> (S == B)
    );

// Subtracting equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (sub && (A == B)) |-> (S == 4'h0)
    );

// Subtraction result plus B reconstructs A modulo 16.
    check_sub_inverse_relation: assert property (
        @(posedge clk) sub |-> ((S + B) == A)
    );

// Subtracting from zero yields the two's complement of B.
    check_sub_from_zero_twos_complement: assert property (
        @(posedge clk) (sub && (A == 4'h0)) |-> (S == (~B + 4'b0001))
    );

// MSB passes through unchanged.
    check_gray_msb_passthrough: assert property (
        @(posedge clk) gray_output[3] === binary_input[3]
    );

// Bit 2 is binary_input[3] XOR binary_input[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray_output[2] === (binary_input[3] ^ binary_input[2])
    );

// Bit 1 is binary_input[2] XOR binary_input[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_output[1] === (binary_input[2] ^ binary_input[1])
    );

// Bit 0 is binary_input[1] XOR binary_input[0].
    check_gray_lsb_xor: assert property (
        @(posedge clk) gray_output[0] === (binary_input[1] ^ binary_input[0])
    );

// Full output matches the standard binary-to-Gray conversion.
    check_gray_vector_relation: assert property (
        @(posedge clk) gray_output === (binary_input ^ (binary_input >> 1))
    );

// clk is the clock; reset is an active-low asynchronous reset; q captures d on rising clk.

    // q is held low whenever reset is asserted.
    check_q_low_during_reset: assert property (
        @(posedge clk)
        !reset |-> (q == 1'b0)
    );

// q is still low on the first clock edge after reset is released.
    check_q_low_on_reset_release: assert property (
        @(posedge clk)
        (!reset ##1 reset) |-> (q == 1'b0)
    );

// q becomes 1 on the next clock when d is 1 in normal operation.
    check_q_captures_one: assert property (
        @(posedge clk) disable iff (!reset)
        d |=> (q == 1'b1)
    );

// q becomes 0 on the next clock when d is 0 in normal operation.
    check_q_captures_zero: assert property (
        @(posedge clk) disable iff (!reset)
        !d |=> (q == 1'b0)
    );

// Sum output must equal a plus b.
    check_sum_matches_adder: assert property (
        @(posedge clk) disable iff (reset)
        sum == (a + b)
    );

// Diff output must equal a minus b.
    check_diff_matches_subtractor: assert property (
        @(posedge clk) disable iff (reset)
        diff == (a - b)
    );

// Mux must pass sum when select is low.
    check_abs_diff_selects_sum: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |-> (abs_diff == sum)
    );

// Mux must pass diff when select is high.
    check_abs_diff_selects_diff: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |-> (abs_diff == diff)
    );

// End-to-end output must equal a plus b when select is low.
    check_abs_diff_matches_add_when_selected: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |-> (abs_diff == (a + b))
    );

// End-to-end output must equal a minus b when select is high.
    check_abs_diff_matches_sub_when_selected: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |-> (abs_diff == (a - b))
    );

// RTL is combinational with no reset; clk is only a sampling clock for SVA.

    // Right-shift mode must match the RTL shift operation.
    check_right_shift_function: assert property (
        @(posedge clk) (shift_direction == 1'b0) |-> (data_out == (data_in >> shift_amount))
    );

// Left-shift mode must match the RTL shift operation.
    check_left_shift_function: assert property (
        @(posedge clk) (shift_direction == 1'b1) |-> (data_out == (data_in << shift_amount))
    );

// A zero shift must pass the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk) (shift_amount == 3'b000) |-> (data_out == data_in)
    );

// Right shift by one must insert a zero into the MSB.
    check_right_shift_by_one: assert property (
        @(posedge clk) (shift_direction == 1'b0 && shift_amount == 3'b001) |-> (data_out == {1'b0, data_in[7:1]})
    );

// Left shift by one must insert a zero into the LSB.
    check_left_shift_by_one: assert property (
        @(posedge clk) (shift_direction == 1'b1 && shift_amount == 3'b001) |-> (data_out == {data_in[6:0], 1'b0})
    );

// Right shift by seven must leave only the original MSB.
    check_right_shift_by_seven: assert property (
        @(posedge clk) (shift_direction == 1'b0 && shift_amount == 3'b111) |-> (data_out == {7'b0, data_in[7]})
    );

// Left shift by seven must leave only the original LSB.
    check_left_shift_by_seven: assert property (
        @(posedge clk) (shift_direction == 1'b1 && shift_amount == 3'b111) |-> (data_out == {data_in[0], 7'b0})
    );

// Any non-zero right shift must zero-fill the MSB.
    check_right_shift_zero_fills_msb: assert property (
        @(posedge clk) (shift_direction == 1'b0 && shift_amount != 3'b000) |-> (data_out[7] == 1'b0)
    );

// Any non-zero left shift must zero-fill the LSB.
    check_left_shift_zero_fills_lsb: assert property (
        @(posedge clk) (shift_direction == 1'b1 && shift_amount != 3'b000) |-> (data_out[0] == 1'b0)
    );

// 000 advances to 001.
    check_count_000_to_001: assert property (
        @(posedge clk) (count == 3'b000) |=> (count == 3'b001)
    );

// 001 advances to 010.
    check_count_001_to_010: assert property (
        @(posedge clk) (count == 3'b001) |=> (count == 3'b010)
    );

// 010 advances to 011.
    check_count_010_to_011: assert property (
        @(posedge clk) (count == 3'b010) |=> (count == 3'b011)
    );

// 011 advances to 100.
    check_count_011_to_100: assert property (
        @(posedge clk) (count == 3'b011) |=> (count == 3'b100)
    );

// 100 advances to 101.
    check_count_100_to_101: assert property (
        @(posedge clk) (count == 3'b100) |=> (count == 3'b101)
    );

// 101 advances to 110.
    check_count_101_to_110: assert property (
        @(posedge clk) (count == 3'b101) |=> (count == 3'b110)
    );

// 110 advances to 111.
    check_count_110_to_111: assert property (
        @(posedge clk) (count == 3'b110) |=> (count == 3'b111)
    );

// 111 wraps back to 000.
    check_count_111_to_000: assert property (
        @(posedge clk) (count == 3'b111) |=> (count == 3'b000)
    );

// Bit 0 sum matches the first full adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 2 sum uses the carry propagated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carry3(A[1], B[1], carry3(A[0], B[0], Cin)))
    );

// Bit 3 sum uses the carry propagated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Cin))))
    );

// Adding zero with no carry in preserves A.
    check_add_zero_to_a: assert property (
        @(posedge clk) (B == 4'b0000 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero with no carry in preserves B.
    check_add_zero_to_b: assert property (
        @(posedge clk) (A == 4'b0000 && Cin == 1'b0) |-> ({Cout, S} == {1'b0, B})
    );

// All-zero inputs must drive out low.
    check_all_zero_drives_zero: assert property (
        @(posedge clk)
        ((in0 == 1'b0) && (in1 == 1'b0) && (in2 == 1'b0) && (in3 == 1'b0)) |-> (out == 1'b0)
    );

// All-one inputs must drive out high.
    check_all_one_drives_one: assert property (
        @(posedge clk)
        ((in0 == 1'b1) && (in1 == 1'b1) && (in2 == 1'b1) && (in3 == 1'b1)) |-> (out == 1'b1)
    );

// Any case that is not all ones must drive out low.
    check_not_all_one_drives_zero: assert property (
        @(posedge clk)
        (!((in0 == 1'b1) && (in1 == 1'b1) && (in2 == 1'b1) && (in3 == 1'b1))) |-> (out == 1'b0)
    );

// Out can only be high when all inputs are high.
    check_out_high_only_when_all_high: assert property (
        @(posedge clk)
        (out == 1'b1) |-> ((in0 == 1'b1) && (in1 == 1'b1) && (in2 == 1'b1) && (in3 == 1'b1))
    );

// Out must match the implemented four-input AND behavior.
    check_out_matches_function: assert property (
        @(posedge clk)
        (out == ((in0 == 1'b1) && (in1 == 1'b1) && (in2 == 1'b1) && (in3 == 1'b1)))
    );

// LOAD captures D into Q on the next clock.
    check_load_captures_q: assert property (
        @(posedge CLK) LOAD |=> (Q == $past(D))
    );

// LOAD captures bitwise-inverted D into Qbar on the next clock.
    check_load_captures_qbar: assert property (
        @(posedge CLK) LOAD |=> (Qbar == ~$past(D))
    );

// SHIFT moves Q[2:0] into Q[3:1] when LOAD is low.
    check_shift_moves_q_upper_bits: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Q[3:1] == $past(Q[2:0]))
    );

// SHIFT inserts 0 into Q[0] when LOAD is low.
    check_shift_inserts_zero_into_q_lsb: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Q[0] == 1'b0)
    );

// SHIFT moves Qbar[2:0] into Qbar[3:1] when LOAD is low.
    check_shift_moves_qbar_upper_bits: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Qbar[3:1] == $past(Qbar[2:0]))
    );

// SHIFT inserts 1 into Qbar[0] when LOAD is low.
    check_shift_inserts_one_into_qbar_lsb: assert property (
        @(posedge CLK) (!LOAD && SHIFT) |=> (Qbar[0] == 1'b1)
    );

// With neither LOAD nor SHIFT, Q holds its value.
    check_q_holds_when_idle: assert property (
        @(posedge CLK) (!LOAD && !SHIFT) |=> (Q == $past(Q))
    );

// With neither LOAD nor SHIFT, Qbar holds its value.
    check_qbar_holds_when_idle: assert property (
        @(posedge CLK) (!LOAD && !SHIFT) |=> (Qbar == $past(Qbar))
    );

// Reset high before the rising edge clears the sampled output low.
    check_reset_clears_out: assert property (
        @(posedge clock) reset |-> (out == 1'b0)
    );

// With reset low, functional mode captures in on the next sampled edge.
    check_functional_capture: assert property (
        @(posedge clock) disable iff (reset)
        (!scanen) |=> (out == $past(in))
    );

// With reset low, scan mode captures sin on the next sampled edge.
    check_scan_capture: assert property (
        @(posedge clock) disable iff (reset)
        scanen |=> (out == $past(sin))
    );

// When inputs differ, scan mode must not capture the functional input.
    check_scan_selects_sin: assert property (
        @(posedge clock) disable iff (reset)
        (scanen && (sin != in)) |=> (out != $past(in))
    );

// When inputs differ, functional mode must not capture the scan input.
    check_functional_selects_in: assert property (
        @(posedge clock) disable iff (reset)
        ((!scanen) && (sin != in)) |=> (out != $past(sin))
    );

// Combinational RTL with no reset; clk is a sampling clock.

    // Addition mode returns the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == ((num1 + num2) & 8'hFF))
    );

// Subtraction mode returns the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == ((num1 - num2) & 8'hFF))
    );

// Division by zero forces the result to zero.
    check_division_by_zero_result: assert property (
        @(posedge clk) (op == 2'b11 && num2 == 8'h00) |-> (result == 8'h00)
    );

// Blank forces the blanked display pattern.
    check_blank_output: assert property (
        @(posedge clk) blank |-> (s7 == ~7'b0000000)
    );

// Minus selects the minus pattern when not blanked.
    check_minus_output: assert property (
        @(posedge clk) (!blank && minus) |-> (s7 == ~7'b1000000)
    );

// Value 0 selects the 0 segment pattern.
    check_value_0_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h0)) |-> (s7 == ~7'b0111111)
    );

// Value 1 selects the 1 segment pattern.
    check_value_1_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h1)) |-> (s7 == ~7'b0000110)
    );

// Value 2 selects the 2 segment pattern.
    check_value_2_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h2)) |-> (s7 == ~7'b1011011)
    );

// Value 3 selects the 3 segment pattern.
    check_value_3_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h3)) |-> (s7 == ~7'b1001111)
    );

// Value 4 selects the 4 segment pattern.
    check_value_4_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h4)) |-> (s7 == ~7'b1100110)
    );

// Value 5 selects the 5 segment pattern.
    check_value_5_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h5)) |-> (s7 == ~7'b1101101)
    );

// Value 6 selects the 6 segment pattern.
    check_value_6_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h6)) |-> (s7 == ~7'b1111101)
    );

// Value 7 selects the 7 segment pattern.
    check_value_7_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h7)) |-> (s7 == ~7'b0000111)
    );

// Value 8 selects the 8 segment pattern.
    check_value_8_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h8)) |-> (s7 == ~7'b1111111)
    );

// Value 9 selects the 9 segment pattern.
    check_value_9_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'h9)) |-> (s7 == ~7'b1101111)
    );

// Value A selects the A segment pattern.
    check_value_a_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hA)) |-> (s7 == ~7'b1110111)
    );

// Value B selects the B segment pattern.
    check_value_b_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hB)) |-> (s7 == ~7'b1111100)
    );

// Value C selects the C segment pattern.
    check_value_c_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hC)) |-> (s7 == ~7'b0111001)
    );

// Value D selects the D segment pattern.
    check_value_d_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hD)) |-> (s7 == ~7'b1011110)
    );

// Value E selects the E segment pattern.
    check_value_e_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hE)) |-> (s7 == ~7'b1111001)
    );

// Value F selects the F segment pattern.
    check_value_f_output: assert property (
        @(posedge clk) (!blank && !minus && (value == 4'hF)) |-> (s7 == ~7'b1110001)
    );

// Y matches the implemented AOI function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((A1 & A2) | B1 | C1 | D1)
    );

// B1 high forces the output low.
    check_b1_forces_output_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// C1 high forces the output low.
    check_c1_forces_output_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// D1 high forces the output low.
    check_d1_forces_output_low: assert property (
        @(posedge clk) D1 |-> !Y
    );

// A1 and A2 high together force the output low.
    check_and_term_forces_output_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1, C1, and D1 low, A1 low keeps the output high.
    check_a1_low_keeps_output_high: assert property (
        @(posedge clk) (!B1 && !C1 && !D1 && !A1) |-> Y
    );

// With B1, C1, and D1 low, A2 low keeps the output high.
    check_a2_low_keeps_output_high: assert property (
        @(posedge clk) (!B1 && !C1 && !D1 && !A2) |-> Y
    );

// A high output requires all NOR inputs low and the AND term inactive.
    check_output_high_requires_all_inputs_clear: assert property (
        @(posedge clk) Y |-> (!B1 && !C1 && !D1 && !(A1 && A2))
    );

// A low output must be caused by a high NOR input or the AND term.
    check_output_low_has_active_input: assert property (
        @(posedge clk) !Y |-> (B1 || C1 || D1 || (A1 && A2))
    );

// No RTL clock/reset; sample combinational behavior on clk.

    // q[2] indicates whether the lower nibble is all zero.
    check_lower_zero_flag: assert property (
        @(posedge clk) q[2] == !(|data[3:0])
    );

// When the lower nibble is zero, q[1:0] comes from the upper nibble pairs.
    check_upper_pairs_selected_when_lower_zero: assert property (
        @(posedge clk) (!(|data[3:0])) |-> (q[1:0] == {(|data[7:6]), (|data[5:4])})
    );

// When the lower nibble is nonzero, q[1:0] comes from the lower nibble pairs.
    check_lower_pairs_selected_when_lower_nonzero: assert property (
        @(posedge clk) (|data[3:0]) |-> (q[1:0] == {(|data[3:2]), (|data[1:0])})
    );

// q[0] matches the selected low pair OR result.
    check_q0_selected_pair_or: assert property (
        @(posedge clk) q[0] == ((!(|data[3:0])) ? (|data[5:4]) : (|data[1:0]))
    );

// q[1] matches the selected high pair OR result.
    check_q1_selected_pair_or: assert property (
        @(posedge clk) q[1] == ((!(|data[3:0])) ? (|data[7:6]) : (|data[3:2]))
    );

// All-zero input produces the lower-zero indication and zero pair bits.
    check_all_zero_output: assert property (
        @(posedge clk) (data == 8'h00) |-> (q == 3'b100)
    );

// Any set input bit must set at least one of the encoded pair bits.
    check_nonzero_input_sets_pair_code: assert property (
        @(posedge clk) (|data[7:0]) |-> (|q[1:0])
    );

// q matches the complete combinational expression implemented in the RTL.
    check_full_output_expression: assert property (
        @(posedge clk) q == {(!(|data[3:0])), ((!(|data[3:0])) ? {(|data[7:6]), (|data[5:4])} : {(|data[3:2]), (|data[1:0])})}
    );

// On rising-edge samples of CLK_IN, CLK_OUT matches the inversion of CLK_IN.
    check_clk_out_inverts_on_posedge: assert property (
        @(posedge CLK_IN) (CLK_OUT == !CLK_IN)
    );

// On falling-edge samples of CLK_IN, CLK_OUT matches the inversion of CLK_IN.
    check_clk_out_inverts_on_negedge: assert property (
        @(negedge CLK_IN) (CLK_OUT == !CLK_IN)
    );

// On rising-edge samples of CLK_IN, PREEDGE is driven high.
    check_preedge_high_on_posedge: assert property (
        @(posedge CLK_IN) (PREEDGE == 1'b1)
    );

// On falling-edge samples of CLK_IN, PREEDGE is driven high.
    check_preedge_high_on_negedge: assert property (
        @(negedge CLK_IN) (PREEDGE == 1'b1)
    );

// clk is the sampling clock for this combinational block.

    // Output matches the 4-bit sum of A, B, and Cin.
    check_total_sum: assert property (
        @(posedge clk) C == (A + B + Cin)
    );

// With Cin low, output is the 4-bit sum of A and B.
    check_sum_without_carry_in: assert property (
        @(posedge clk) (Cin == 1'b0) |-> (C == (A + B))
    );

// With Cin high, output is the 4-bit sum of A, B, and one.
    check_sum_with_carry_in: assert property (
        @(posedge clk) (Cin == 1'b1) |-> (C == (A + B + 1'b1))
    );

// Zero inputs with no carry-in produce zero.
    check_zero_inputs_no_carry: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && Cin == 1'b0) |-> (C == 4'h0)
    );

// Zero inputs with carry-in produce one.
    check_zero_inputs_with_carry: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0 && Cin == 1'b1) |-> (C == 4'h1)
    );

// The least-significant sum bit matches xor addition.
    check_lsb_sum: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0] ^ Cin)
    );

// Overflow is truncated to the low 4 bits.
    check_overflow_truncation: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h1 && Cin == 1'b0) |-> (C == 4'h0)
    );

// Full-scale addition with carry-in keeps only the low 4 bits.
    check_max_sum_truncation: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> (C == 4'hF)
    );

// Y matches the implemented logic A_N | ~B.
    check_output_function: assert property (
        @(posedge clk) Y == (A_N | ~B)
    );

// A_N high forces Y high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> Y
    );

// B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) !B |-> Y
    );

// A_N low with B high drives Y low.
    check_low_input_combination_drives_y_low: assert property (
        @(posedge clk) (!A_N && B) |-> !Y
    );

// Y low implies the unique low-output input combination.
    check_y_low_implies_unique_input_case: assert property (
        @(posedge clk) !Y |-> (!A_N && B)
    );

// If Y is high while A_N is low, then B must be low.
    check_y_high_with_a_n_low_implies_b_low: assert property (
        @(posedge clk) (Y && !A_N) |-> !B
    );

// Reset clears all registered state.
    check_reset_clears_state: assert property (
        @(posedge Clk) Reset |-> ((Lfsr == 16'h0000) && (Data == 16'h0000) && (Done == 1'b0))
    );

// Enable drives Done high on the next cycle.
    check_enable_sets_done: assert property (
        @(posedge Clk) disable iff (Reset)
        Enable |=> (Done == 1'b1)
    );

// Disable drives Done low on the next cycle.
    check_disable_clears_done: assert property (
        @(posedge Clk) disable iff (Reset)
        !Enable |=> (Done == 1'b0)
    );

// Data holds its value when Enable is low.
    check_disable_holds_data: assert property (
        @(posedge Clk) disable iff (Reset)
        !Enable |=> $stable(Data)
    );

// Assertions are sampled on CLK; the RTL has no reset.

    // OUT_ADDSUB selects the adder result when CTRL is low.
    check_out_addsub_select_add: assert property (
        @(posedge CLK) (!CTRL) |-> (OUT_ADDSUB == (in0 + in1))
    );

// OUT_ADDSUB selects the subtractor result when CTRL is high.
    check_out_addsub_select_sub: assert property (
        @(posedge CLK) CTRL |-> (OUT_ADDSUB == (in0 - in1))
    );

// OUT_DIFF uses add_out - sub_out when add_out is larger.
    check_out_diff_add_greater_branch: assert property (
        @(posedge CLK) ((in0 + in1) > (in0 - in1)) |-> (OUT_DIFF == ((in0 + in1) - (in0 - in1)))
    );

// OUT_DIFF uses sub_out - add_out when sub_out is larger or equal.
    check_out_diff_sub_greater_equal_branch: assert property (
        @(posedge CLK) ((in0 + in1) <= (in0 - in1)) |-> (OUT_DIFF == ((in0 - in1) - (in0 + in1)))
    );

// Zero on in1 makes the absolute difference zero.
    check_zero_in1_zero_diff: assert property (
        @(posedge CLK) (in1 == 16'h0000) |-> (OUT_DIFF == 16'h0000)
    );

// Zero on in1 makes OUT_ADDSUB pass through in0.
    check_zero_in1_addsub_passthrough: assert property (
        @(posedge CLK) (in1 == 16'h0000) |-> (OUT_ADDSUB == in0)
    );

// Equal inputs make the subtractor-selected output zero.
    check_equal_inputs_sub_zero: assert property (
        @(posedge CLK) (CTRL && (in0 == in1)) |-> (OUT_ADDSUB == 16'h0000)
    );

// Equal inputs make OUT_DIFF equal the adder result.
    check_equal_inputs_diff_matches_sum: assert property (
        @(posedge CLK) (in0 == in1) |-> (OUT_DIFF == (in0 + in1))
    );

// RTL is combinational, so assertions are sampled on an external clock.

    // Checks left mode performs two successive left shifts.
    check_left_direction_double_shift: assert property (
        @(posedge clk)
        (dir == 1'b0) |-> (out == ((in << shift) << shift))
    );

// Checks right mode performs two successive right shifts.
    check_right_direction_double_shift: assert property (
        @(posedge clk)
        (dir == 1'b1) |-> (out == ((in >> shift) >> shift))
    );

// Checks a zero shift passes the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk)
        (shift == 4'd0) |-> (out == in)
    );

// Checks shifts of 8 or more clear the 16-bit result after two stages.
    check_large_shift_clears_output: assert property (
        @(posedge clk)
        (shift >= 4'd8) |-> (out == 16'h0000)
    );

// Checks left shifts insert zeros into the low bits.
    check_left_shift_zero_fills_low_bits: assert property (
        @(posedge clk)
        (dir == 1'b0 && shift != 4'd0) |-> (out[1:0] == 2'b00)
    );

// Checks right shifts insert zeros into the high bits.
    check_right_shift_zero_fills_high_bits: assert property (
        @(posedge clk)
        (dir == 1'b1 && shift != 4'd0) |-> (out[15:14] == 2'b00)
    );

// Output matches the implemented bit transformation.
    check_full_output_transform: assert property (
        @(posedge clk)
        output_signal == {~input_signal[3:0], input_signal[5:4], 2'b00}
    );

// Upper output nibble is the inverse of the lower input nibble.
    check_upper_nibble_inversion: assert property (
        @(posedge clk)
        output_signal[7:4] == ~input_signal[3:0]
    );

// Lower output nibble is the shifted upper input nibble.
    check_lower_nibble_shift: assert property (
        @(posedge clk)
        output_signal[3:0] == {input_signal[5:4], 2'b00}
    );

// Output bits [3:2] map directly from input bits [5:4].
    check_shifted_bit_mapping: assert property (
        @(posedge clk)
        output_signal[3:2] == input_signal[5:4]
    );

// Output bits [1:0] are always zero.
    check_low_bits_zero: assert property (
        @(posedge clk)
        output_signal[1:0] == 2'b00
    );

// S must equal A plus the constant 4'hA.
    check_sum_matches_constant: assert property (
        @(posedge clk) S == (A + B)
    );

// Bit 0 passes through because B[0] is 0.
    check_bit0_passthrough: assert property (
        @(posedge clk) S[0] == A[0]
    );

// Bit 1 inverts because B[1] is 1 and bit 0 generates no carry.
    check_bit1_relation: assert property (
        @(posedge clk) S[1] == ~A[1]
    );

// Bit 2 is A[2] XOR the carry from bit 1.
    check_bit2_relation: assert property (
        @(posedge clk) S[2] == (A[2] ^ A[1])
    );

// Bit 3 includes the constant 1 and the carry from bit 2.
    check_bit3_relation: assert property (
        @(posedge clk) S[3] == (A[3] ^ 1'b1 ^ (A[2] & A[1]))
    );

// A sampled reset leaves Q_OUT at the init value by the next clock.
    check_reset_forces_init: assert property (
        @(posedge CLK) RST |=> (Q_OUT == init)
    );

// With EN high, Q_OUT loads D_IN unless reset forces init between clocks.
    check_load_when_enabled: assert property (
        @(posedge CLK) disable iff (RST)
        EN |=> ((Q_OUT == $past(D_IN)) || (Q_OUT == init))
    );

// With EN low, Q_OUT holds its value unless reset forces init between clocks.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RST)
        !EN |=> ((Q_OUT == $past(Q_OUT)) || (Q_OUT == init))
    );

// branch_eq can only be asserted by the BEQ decode.
    check_branch_eq_only_beq: assert property (
        @(posedge clk)
        branch_eq |-> (
            opcode    == OPC_BEQ &&
            branch_ne == 1'b0 &&
            aluop     == 2'b01 &&
            regwrite  == 1'b0 &&
            memread   == 1'b0 &&
            memwrite  == 1'b0 &&
            jump      == 1'b0
        )
    );

// branch_ne can only be asserted by the BNE decode.
    check_branch_ne_only_bne: assert property (
        @(posedge clk)
        branch_ne |-> (
            opcode    == OPC_BNE &&
            branch_eq == 1'b0 &&
            aluop     == 2'b01 &&
            regwrite  == 1'b0 &&
            memread   == 1'b0 &&
            memwrite  == 1'b0 &&
            jump      == 1'b0
        )
    );

// memread can only be asserted by the LW decode.
    check_memread_only_lw: assert property (
        @(posedge clk)
        memread |-> (
            opcode    == OPC_LW &&
            memwrite  == 1'b0 &&
            memtoreg  == 1'b1 &&
            regdst    == 1'b0 &&
            regwrite  == 1'b1 &&
            alusrc    == 1'b1 &&
            jump      == 1'b0
        )
    );

// memwrite can only be asserted by the SW decode.
    check_memwrite_only_sw: assert property (
        @(posedge clk)
        memwrite |-> (
            opcode    == OPC_SW &&
            memread   == 1'b0 &&
            memtoreg  == 1'b0 &&
            regwrite  == 1'b0 &&
            alusrc    == 1'b1 &&
            jump      == 1'b0
        )
    );

// jump can only be asserted by the J decode.
    check_jump_only_jump_opcode: assert property (
        @(posedge clk)
        jump |-> (
            opcode    == OPC_J &&
            branch_eq == 1'b0 &&
            branch_ne == 1'b0 &&
            memread   == 1'b0 &&
            memwrite  == 1'b0 &&
            alusrc    == 1'b0
        )
    );

// Reset drives out to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 4'b0000)
    );

// Load updates out from data[3:0].
    check_load_updates_out: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (out == $past(data[3:0]))
    );

// Load has priority over select.
    check_load_priority_over_select: assert property (
        @(posedge clk) disable iff (reset)
        (load && select) |=> (out == $past(data[3:0]))
    );

// Select rotates in when load is low.
    check_select_rotation: assert property (
        @(posedge clk) disable iff (reset)
        (!load && select) |=> (out == $past({in[2:0], in[3]}))
    );

// Default path rotates in when both controls are low.
    check_default_rotation: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !select) |=> (out == $past({in[0], in[3:1]}))
    );

// Every non-reset cycle follows the RTL next-state function.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (
            out == ($past(load) ? $past(data[3:0]) :
                    ($past(select) ? $past({in[2:0], in[3]}) :
                                     $past({in[0], in[3:1]})))
        )
    );

// Bit 2 includes the ripple carry from lower bits.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carry_bit(A[1], B[1], carry_bit(A[0], B[0], 1'b0)))
    );

// Bit 3 includes the ripple carry from lower bits.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carry_bit(A[2], B[2], carry_bit(A[1], B[1], carry_bit(A[0], B[0], 1'b0))))
    );

// Complementary inputs sum to all ones with no carry out.
    check_complement_case: assert property (
        @(posedge clk) (B == ~A) |-> ((S == 4'hF) && (Cout == 1'b0))
    );

// No reset exists in the RTL; properties are sampled on an external clock.

    // Output must equal the adder result ORed with its left-shifted version.
    check_output_function: assert property (
        @(posedge clk) (out == ((a + b) | ((a + b) << shift)))
    );

// When select is high, output still matches the same implemented function.
    check_select_high_function: assert property (
        @(posedge clk) select |-> (out == ((a + b) | ((a + b) << shift)))
    );

// When select is low, output still matches the same implemented function.
    check_select_low_function: assert property (
        @(posedge clk) !select |-> (out == ((a + b) | ((a + b) << shift)))
    );

// A zero shift makes the output equal to the adder result.
    check_shift_zero_passthrough: assert property (
        @(posedge clk) (shift == 4'd0) |-> (out == (a + b))
    );

// Every asserted bit of the adder result must appear in the output.
    check_output_contains_sum_bits: assert property (
        @(posedge clk) (((a + b) & ~out) == 16'h0000)
    );

// Every asserted bit of the shifted adder result must appear in the output.
    check_output_contains_shifted_sum_bits: assert property (
        @(posedge clk) ((((a + b) << shift) & ~out) == 16'h0000)
    );

// A zero adder result forces the output low.
    check_zero_sum_gives_zero_out: assert property (
        @(posedge clk) ((a + b) == 16'h0000) |-> (out == 16'h0000)
    );

// A zero output implies the adder result is also zero.
    check_zero_out_implies_zero_sum: assert property (
        @(posedge clk) (out == 16'h0000) |-> ((a + b) == 16'h0000)
    );

// Output bit 0 always matches bit 0 of the adder result.
    check_lsb_matches_sum_lsb: assert property (
        @(posedge clk) (out[0] == (a[0] ^ b[0]))
    );

// For nonzero shifts, the shifted-off low bits remain equal to the adder result.
    check_shifted_off_low_bits_unchanged: assert property (
        @(posedge clk) (shift != 4'd0) |-> ((out & ((16'h0001 << shift) - 16'h0001)) == ((a + b) & ((16'h0001 << shift) - 16'h0001)))
    );

// 000 maps to d_0.
    check_map_row_000: assert property (
        @(posedge clk) (in_row == 3'b000) |-> (out_code == D_0)
    );

// 001 maps to d_1.
    check_map_row_001: assert property (
        @(posedge clk) (in_row == 3'b001) |-> (out_code == D_1)
    );

// 010 maps to d_2.
    check_map_row_010: assert property (
        @(posedge clk) (in_row == 3'b010) |-> (out_code == D_2)
    );

// 011 maps to d_3.
    check_map_row_011: assert property (
        @(posedge clk) (in_row == 3'b011) |-> (out_code == D_3)
    );

// 100 maps to d_4.
    check_map_row_100: assert property (
        @(posedge clk) (in_row == 3'b100) |-> (out_code == D_4)
    );

// 101 selects the default zero code.
    check_map_row_101: assert property (
        @(posedge clk) (in_row == 3'b101) |-> (out_code == 5'b00000)
    );

// 110 selects the default zero code.
    check_map_row_110: assert property (
        @(posedge clk) (in_row == 3'b110) |-> (out_code == 5'b00000)
    );

// 111 selects the default zero code.
    check_map_row_111: assert property (
        @(posedge clk) (in_row == 3'b111) |-> (out_code == 5'b00000)
    );

// Arithmetic overflow must raise COUT.
    check_overflow_sets_cout: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + CIN) > 5'd15) |-> (COUT == 1'b1)
    );

// 15 plus carry-in must wrap to zero with carry-out.
    check_f_plus_cin_wraps: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h0 && CIN == 1'b1) |-> (S == 4'h0 && COUT == 1'b1)
    );

// Maximum operands with carry-in must produce 5'h1F.
    check_max_operands_case: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> ({COUT, S} == 5'h1F)
    );

// Input value 0 maps to output 0.
    check_zero_input_mapping: assert property (
        @(posedge clk) (input_val == 10'd0) |-> (binary_val == 4'd0)
    );

// Input values 1 through 8 map to their 4-bit value.
    check_midrange_input_mapping: assert property (
        @(posedge clk) ((input_val >= 10'd1) && (input_val <= 10'd8)) |-> (binary_val == input_val[3:0])
    );

// Input value 9 maps to output 9.
    check_nine_input_mapping: assert property (
        @(posedge clk) (input_val == 10'd9) |-> (binary_val == 4'd9)
    );

// Unsupported input values drive the default zero output.
    check_default_zero_for_invalid_inputs: assert property (
        @(posedge clk) (input_val > 10'd9) |-> (binary_val == 4'd0)
    );

// The output never exceeds the highest encoded value.
    check_output_range: assert property (
        @(posedge clk) (binary_val <= 4'd9)
    );

// X matches the implemented combined logic.
    check_output_equation: assert property (
        @(posedge clk) X == (A1 & A2 & ~B1_N & ~C1)
    );

// When all required terms are enabled, X is high.
    check_enable_combination_sets_x: assert property (
        @(posedge clk) (A1 & A2 & ~B1_N & ~C1) |-> X
    );

// A high X requires all enabling conditions.
    check_x_high_requires_all_enables: assert property (
        @(posedge clk) X |-> (A1 & A2 & ~B1_N & ~C1)
    );

// A low A1 forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) !A1 |-> !X
    );

// A low A2 forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) !A2 |-> !X
    );

// A high B1_N forces X low.
    check_b1_n_high_forces_x_low: assert property (
        @(posedge clk) B1_N |-> !X
    );

// A high C1 forces X low.
    check_c1_high_forces_x_low: assert property (
        @(posedge clk) C1 |-> !X
    );

// Sequential logic on posedge CLK; no reset is present in the RTL.

    // When SET_B is high at a clock edge, Q is set to 1 on the next cycle.
    check_sync_set_forces_one: assert property (
        @(posedge CLK) SET_B |=> (Q == 1'b1)
    );

// When SET_B is low and D is 0, Q captures 0 on the next cycle.
    check_capture_zero_when_set_low: assert property (
        @(posedge CLK) (!SET_B && (D == 1'b0)) |=> (Q == 1'b0)
    );

// When SET_B is low and D is 1, Q captures 1 on the next cycle.
    check_capture_one_when_set_low: assert property (
        @(posedge CLK) (!SET_B && (D == 1'b1)) |=> (Q == 1'b1)
    );

// Q follows the RTL next-state equation from the prior sampled inputs.
    check_next_state_equation: assert property (
        @(posedge CLK) 1'b1 |=> (Q == ($past(SET_B) ? 1'b1 : $past(D)))
    );

// Y implements (A_N & B_N) | (C & D).
    check_y_matches_boolean_function: assert property (
        @(posedge clk) Y == ((A_N & B_N) | (C & D))
    );

// A_N and B_N both high force Y high.
    check_y_high_when_ab_high: assert property (
        @(posedge clk) (A_N & B_N) |-> (Y == 1'b1)
    );

// C and D both high force Y high.
    check_y_high_when_cd_high: assert property (
        @(posedge clk) (C & D) |-> (Y == 1'b1)
    );

// If neither input pair is high, Y must be low.
    check_y_low_when_no_pair_high: assert property (
        @(posedge clk) !((A_N & B_N) | (C & D)) |-> (Y == 1'b0)
    );

// A high Y requires at least one high input pair.
    check_y_high_requires_ab_or_cd: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A_N & B_N) | (C & D))
    );

// Count increments by one when start is high below seven.
    check_count_increments: assert property (
        @(posedge clk) (start && (count != 3'd7)) |=> (count == ($past(count) + 3'd1))
    );

// Count wraps to zero when start is high at seven.
    check_count_wraps_at_seven: assert property (
        @(posedge clk) (start && (count == 3'd7)) |=> (count == 3'd0)
    );

// Count holds its value when start is low.
    check_count_holds_when_start_low: assert property (
        @(posedge clk) (!start) |=> (count == $past(count))
    );

// Next-state behavior always matches the RTL update rule.
    check_count_next_state_rule: assert property (
        @(posedge clk) 1'b1 |=> (
            count == ($past(start) ? (($past(count) == 3'd7) ? 3'd0 : ($past(count) + 3'd1)) : $past(count))
        )
    );

// Reset clears the register on the following cycle.
    check_reset_clears_output: assert property (
        @(posedge clk)
        reset |=> (data_out == 4'b0000)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk)
        (reset && load) |=> (data_out == 4'b0000)
    );

// Load captures data_in into the register on the following cycle.
    check_load_captures_input: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (data_out == $past(data_in))
    );

// Without load, the register rotates left by one bit.
    check_shift_rotates_left: assert property (
        @(posedge clk) disable iff (reset)
        !load |=> (data_out == {$past(data_out[2:0]), $past(data_out[3])})
    );

// During a shift, the new LSB comes from the previous MSB.
    check_shift_wraps_msb_to_lsb: assert property (
        @(posedge clk) disable iff (reset)
        !load |=> (data_out[0] == $past(data_out[3]))
    );

// Four consecutive shifts restore the previous 4-bit value.
    check_four_shifts_restore_value: assert property (
        @(posedge clk) disable iff (reset)
        (!load ##1 !load ##1 !load ##1 !load) |=> (data_out == $past(data_out, 4))
    );

// clkout must remain the inverse of clkin on clkin rising edges.
    check_inversion_on_clkin_rise: assert property (
        @(posedge clkin) (clkout === ~clkin)
    );

// clkout must remain the inverse of clkin on clkout rising edges.
    check_inversion_on_clkout_rise: assert property (
        @(posedge clkout) (clkout === ~clkin)
    );

// OUT always matches the mux select function.
    check_mux_function: assert property (
        @(posedge clk) OUT == ((SEL == 1'b0) ? A : B)
    );

// When SEL is low, OUT routes A.
    check_sel_zero_routes_a: assert property (
        @(posedge clk) (SEL == 1'b0) |-> (OUT == A)
    );

// When SEL is high, OUT routes B.
    check_sel_one_routes_b: assert property (
        @(posedge clk) (SEL == 1'b1) |-> (OUT == B)
    );

// A rising SEL causes OUT to select B.
    check_sel_rise_selects_b: assert property (
        @(posedge clk) $rose(SEL) |-> (OUT == B)
    );

// A falling SEL causes OUT to select A.
    check_sel_fall_selects_a: assert property (
        @(posedge clk) $fell(SEL) |-> (OUT == A)
    );

// X matches the implemented sum-of-products logic.
    check_full_equation: assert property (
        @(posedge clk) X == ((A0 & ~S0) | (A1 & S0) | (A2 & ~S1) | (A3 & S1))
    );

// With both selects low, X is the OR of A0 and A2.
    check_sel_00: assert property (
        @(posedge clk) (!S0 && !S1) |-> (X == (A0 | A2))
    );

// With S0 low and S1 high, X is the OR of A0 and A3.
    check_sel_01: assert property (
        @(posedge clk) (!S0 && S1) |-> (X == (A0 | A3))
    );

// With S0 high and S1 low, X is the OR of A1 and A2.
    check_sel_10: assert property (
        @(posedge clk) (S0 && !S1) |-> (X == (A1 | A2))
    );

// With both selects high, X is the OR of A1 and A3.
    check_sel_11: assert property (
        @(posedge clk) (S0 && S1) |-> (X == (A1 | A3))
    );

// Sampled input and output are complementary on clkin rising edges.
    check_inv_relation_on_clkin_rise: assert property (
        @(posedge clkin) clkout === ~clkin
    );

// Sampled input and output are complementary on clkin falling edges.
    check_inv_relation_on_clkin_fall: assert property (
        @(negedge clkin) clkout === ~clkin
    );

// Sampled input and output are complementary on clkout rising edges.
    check_inv_relation_on_clkout_rise: assert property (
        @(posedge clkout) clkout === ~clkin
    );

// Sampled input and output are complementary on clkout falling edges.
    check_inv_relation_on_clkout_fall: assert property (
        @(negedge clkout) clkout === ~clkin
    );

// Output bits [4:1] match the truncated 4-bit addition result.
    check_sum_upper_bits: assert property (
        @(posedge clk) sum[4:1] == (a + b + c)
    );

// External sampling clock; the RTL itself has no clock or reset.

    // When error changes, noise can only settle to 00 or error[1:0].
    check_error_change_noise_is_zero_or_lsb: assert property (
        @(posedge clk) $changed(error) |-> ((noise == 2'b00) || (noise == error[1:0]))
    );

// If error changes to a value with low bits 00, noise must be 00.
    check_error_change_zero_lsb_forces_zero_noise: assert property (
        @(posedge clk) $changed(error) && (error[1:0] == 2'b00) |-> (noise == 2'b00)
    );

// Any observed noise update must produce either 00 or error[1:0].
    check_noise_change_noise_is_zero_or_lsb: assert property (
        @(posedge clk) $changed(noise) |-> ((noise == 2'b00) || (noise == error[1:0]))
    );

// A nonzero noise update must match the current error low bits.
    check_noise_change_nonzero_matches_error_lsb: assert property (
        @(posedge clk) $changed(noise) && (noise != 2'b00) |-> (noise == error[1:0])
    );

// When ctrl is high, S selects D1.
    check_select_d1: assert property (
        @(posedge clk) disable iff (1'b0)
        (ctrl === 1'b1) |-> (S === D1)
    );

// When reset is high, count must be zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// When count is 9, it wraps to 0 on the next clock if reset stays low.
    check_wrap_from_nine: assert property (
        @(posedge clk) disable iff (rst)
        (count == 4'd9) |=> (count == 4'd0)
    );

// When count is not 9, it increments by 1 on the next clock if reset stays low.
    check_increment_when_not_nine: assert property (
        @(posedge clk) disable iff (rst)
        (count != 4'd9) |=> (count == ($past(count) + 4'd1))
    );

// Y must match the implemented NAND3B logic.
    check_nand3b_function: assert property (
        @(posedge clk) Y == ~(B & ~A_N & C)
    );

// A_N high forces the output high.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (Y == 1'b1)
    );

// B low forces the output high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

// C low forces the output high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b1)
    );

// The active input combination drives the output low.
    check_active_inputs_force_y_low: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1)) |-> (Y == 1'b0)
    );

// A low output can only occur for the active input combination.
    check_y_low_only_for_active_inputs: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B == 1'b1) && (C == 1'b1))
    );

// and_result is masked low when select is high, else it is the 3-input AND.
    check_and_output_function: assert property (
        @(posedge clk)
        and_result == (select ? 1'b0 : (in[0] & in[1] & in[2]))
    );

// or_result passes the 3-input OR when select is high, else it is low.
    check_or_output_function: assert property (
        @(posedge clk)
        or_result == (select ? (in[0] | in[1] | in[2]) : 1'b0)
    );

// xor_result is always the XOR of the raw AND and raw OR results.
    check_xor_output_function: assert property (
        @(posedge clk)
        xor_result == ((in[0] & in[1] & in[2]) ^ (in[0] | in[1] | in[2]))
    );

// When select is high, AND is blocked and OR is selected.
    check_select_high_routing: assert property (
        @(posedge clk)
        select |-> ((and_result == 1'b0) && (or_result == (in[0] | in[1] | in[2])))
    );

// When select is low, OR is blocked and AND is selected.
    check_select_low_routing: assert property (
        @(posedge clk)
        !select |-> ((and_result == (in[0] & in[1] & in[2])) && (or_result == 1'b0))
    );

// All outputs are low when all inputs are low.
    check_all_zero_input_case: assert property (
        @(posedge clk)
        (in == 3'b000) |-> ((and_result == 1'b0) && (or_result == 1'b0) && (xor_result == 1'b0))
    );

// xor_result is high for any nonzero input pattern that is not all ones.
    check_partial_one_input_xor_high: assert property (
        @(posedge clk)
        ((in != 3'b000) && (in != 3'b111)) |-> (xor_result == 1'b1)
    );

// xor_result is low when all inputs are high.
    check_all_one_input_xor_low: assert property (
        @(posedge clk)
        (in == 3'b111) |-> (xor_result == 1'b0)
    );

// Y is forced low when C1 is low.
    check_ctrl_low_forces_zero: assert property (
        @(posedge clk) (C1 == 1'b0) |-> (Y == 1'b0)
    );

// Y matches A&B when C1 is high.
    check_ctrl_high_passes_and: assert property (
        @(posedge clk) (C1 == 1'b1) |-> (Y == (A & B))
    );

// Y can only be high when C1, A, and B are all high.
    check_output_high_requires_all_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((C1 == 1'b1) && (A == 1'b1) && (B == 1'b1))
    );

// Y is high when C1, A, and B are all high.
    check_all_high_drive_high: assert property (
        @(posedge clk) ((C1 == 1'b1) && (A == 1'b1) && (B == 1'b1)) |-> (Y == 1'b1)
    );

// Active-low reset forces the count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'h0)
    );

// Normal mode increments every cycle with wraparound.
    check_normal_mode_increment: assert property (
        @(posedge clk) disable iff (!rst)
        (!test_mode) |=> (count == (($past(count) == 4'hF) ? 4'h0 : ($past(count) + 4'd1)))
    );

// In test mode, up increments the count and has priority over down.
    check_test_mode_up_increment: assert property (
        @(posedge clk) disable iff (!rst)
        (test_mode && up) |=> (count == (($past(count) == 4'hF) ? 4'h0 : ($past(count) + 4'd1)))
    );

// In test mode, down decrements the count when up is not asserted.
    check_test_mode_down_decrement: assert property (
        @(posedge clk) disable iff (!rst)
        (test_mode && !up && down) |=> (count == (($past(count) == 4'h0) ? 4'hF : ($past(count) - 4'd1)))
    );

// In test mode with no direction request, the count holds.
    check_test_mode_idle_hold: assert property (
        @(posedge clk) disable iff (!rst)
        (test_mode && !up && !down) |=> (count == $past(count))
    );

// Reset returns the FSM to green with a zero counter.
    check_reset_state: assert property (
        @(posedge clk) reset |=> (state == GREEN_STATE) && (counter == 6'd0)
    );

// Reset leads to the green output pattern.
    check_reset_outputs: assert property (
        @(posedge clk) reset |=> (green == 1'b1) && (yellow == 1'b0) && (red == 1'b0)
    );

// Y always matches the RTL mux expression.
    check_output_matches_rtl: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((S == 2'b00) ? (OE ? D0 : 1'b0) :
              (S == 2'b01) ? (OE ? D1 : 1'b0) :
              (S == 2'b10) ? (OE ? D2 : 1'b0) :
              (S == 2'b11) ? (OE ? D3 : 1'b0) : 1'b0)
    );

// Disabling the output forces Y low.
    check_oe_low_forces_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (!OE) |-> (Y == 1'b0)
    );

// With output enabled and S=00, Y selects D0.
    check_select_d0_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0)
        (OE && (S == 2'b00)) |-> (Y == D0)
    );

// With output enabled and S=01, Y selects D1.
    check_select_d1_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0)
        (OE && (S == 2'b01)) |-> (Y == D1)
    );

// With output enabled and S=10, Y selects D2.
    check_select_d2_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0)
        (OE && (S == 2'b10)) |-> (Y == D2)
    );

// With output enabled and S=11, Y selects D3.
    check_select_d3_when_enabled: assert property (
        @(posedge clk) disable iff (1'b0)
        (OE && (S == 2'b11)) |-> (Y == D3)
    );

// Y must equal the 4-input NOR of A, B, C, and D.
    check_y_matches_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

// When all inputs are low, Y must be high.
    check_all_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

// When any input is high, Y must be low.
    check_any_high_drives_y_low: assert property (
        @(posedge clk) (A || B || C || D) |-> !Y
    );

// A high Y implies all inputs are low.
    check_y_high_implies_all_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

// A low Y implies at least one input is high.
    check_y_low_implies_some_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D)
    );

// Z must match the four-input AND of A, B, C, and D.
    check_and_function: assert property (
        @(posedge clk) Z == (A & B & C & D)
    );

// A high output requires all four inputs to be high.
    check_high_output_requires_all_high: assert property (
        @(posedge clk) Z |-> (A && B && C && D)
    );

// All four high inputs must drive the output high.
    check_all_high_drives_output_high: assert property (
        @(posedge clk) (A && B && C && D) |-> Z
    );

// Any low input must force the output low.
    check_any_low_forces_output_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !Z
    );

// data_out follows the prior cycle's selected assignment.
    check_registered_update: assert property (
        @(posedge clk)
        1'b1 |=> data_out == ($past(shift_control) ? {$past(data_in[14:0]), 1'b0} : $past(data_in))
    );

// In shift mode, the next upper bits come from the prior lower bits.
    check_shift_upper_bits: assert property (
        @(posedge clk)
        shift_control |=> data_out[15:1] == $past(data_in[14:0])
    );

// In shift mode, the next least significant bit is zero.
    check_shift_lsb_zero: assert property (
        @(posedge clk)
        shift_control |=> data_out[0] == 1'b0
    );

// In pass-through mode, the next output equals the prior input.
    check_passthrough_update: assert property (
        @(posedge clk)
        !shift_control |=> data_out == $past(data_in)
    );

// load captures data on the next clock, regardless of ena.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> q == $past(data)
    );

// With only ena[1] set, q follows the {q[98:0], q[99]} update.
    check_ena1_updates_with_wrap: assert property (
        @(posedge clk) !load && (ena == 2'b10) |=> q == { $past(q[98:0]), $past(q[99]) }
    );

// When both enable bits are set, ena[1] has priority over ena[0].
    check_ena1_priority_when_both_high: assert property (
        @(posedge clk) !load && (ena == 2'b11) |=> q == { $past(q[98:0]), $past(q[99]) }
    );

// With only ena[0] set, the upper 97 bits are cleared by the implemented assignment.
    check_ena0_clears_upper_bits: assert property (
        @(posedge clk) !load && (ena == 2'b01) |=> q[99:3] == 97'b0
    );

// With only ena[0] set, the low 3 bits match the implemented concatenation.
    check_ena0_updates_low_bits: assert property (
        @(posedge clk) !load && (ena == 2'b01) |=> q[2:0] == { $past(q[1:0]), $past(q[0]) }
    );

// Without load or enable, q holds its previous value.
    check_hold_when_idle: assert property (
        @(posedge clk) !load && (ena == 2'b00) |=> q == $past(q)
    );

// Reset forces Q low.
    check_reset_forces_q_low: assert property (
        @(posedge CLK) !RESET |-> (Q == 1'b0)
    );

// Q is still low on the first clock after reset is released.
    check_q_low_on_reset_release: assert property (
        @(posedge CLK) disable iff (!RESET) $rose(RESET) |-> (Q == 1'b0)
    );

// With reset high, Q reflects D from the previous clock.
    check_q_captures_previous_d: assert property (
        @(posedge CLK) disable iff (!RESET) 1'b1 |=> (Q == $past(D))
    );

// A sampled high input sets the event output on the next cycle.
    check_event_asserts_after_high_input: assert property (
        @(posedge clk) proximity_signal |=> (proximity_event == 1'b1)
    );

// A sampled low input clears the event output on the next cycle.
    check_event_clears_after_low_input: assert property (
        @(posedge clk) !proximity_signal |=> (proximity_event == 1'b0)
    );

// The reported position is driven to zero after every clock update.
    check_position_forced_zero: assert property (
        @(posedge clk) 1'b1 |=> (proximity_position == 8'h00)
    );

// Sum matches 4-bit addition when mode selects add.
    check_add_mode_sum: assert property (
        @(posedge clk) (!mode) |-> (sum == (A + B))
    );

// Sum matches 4-bit subtraction when mode selects subtract.
    check_sub_mode_sum: assert property (
        @(posedge clk) mode |-> (sum == (A - B))
    );

// Sum always matches the selected 4-bit arithmetic operation.
    check_selected_operation_sum: assert property (
        @(posedge clk) sum == (mode ? (A - B) : (A + B))
    );

// Adding zero on B leaves A unchanged.
    check_add_zero_b: assert property (
        @(posedge clk) (!mode && (B == 4'h0)) |-> (sum == A)
    );

// Adding zero on A leaves B unchanged.
    check_add_zero_a: assert property (
        @(posedge clk) (!mode && (A == 4'h0)) |-> (sum == B)
    );

// Subtracting zero leaves A unchanged.
    check_sub_zero_b: assert property (
        @(posedge clk) (mode && (B == 4'h0)) |-> (sum == A)
    );

// Subtracting equal operands yields zero.
    check_sub_equal_operands: assert property (
        @(posedge clk) (mode && (A == B)) |-> (sum == 4'h0)
    );

// Y matches the RTL boolean function.
    check_output_function: assert property (
        @(posedge clk) Y == ((A & B) | (B & C))
    );

// B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b0)
    );

// A and B high force Y high.
    check_ab_high_drives_y_high: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (Y == 1'b1)
    );

// B and C high force Y high.
    check_bc_high_drives_y_high: assert property (
        @(posedge clk) ((B == 1'b1) && (C == 1'b1)) |-> (Y == 1'b1)
    );

// A high cannot raise Y when B is low.
    check_a_without_b_keeps_y_low: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b0)) |-> (Y == 1'b0)
    );

// C high cannot raise Y when B is low.
    check_c_without_b_keeps_y_low: assert property (
        @(posedge clk) ((C == 1'b1) && (B == 1'b0)) |-> (Y == 1'b0)
    );

// Y high requires B high.
    check_y_high_requires_b_high: assert property (
        @(posedge clk) (Y == 1'b1) |-> (B == 1'b1)
    );

// Y high requires A or C high.
    check_y_high_requires_a_or_c: assert property (
        @(posedge clk) (Y == 1'b1) |-> ((A == 1'b1) || (C == 1'b1))
    );

// Reset clears all registers and the output.
    check_reset_clears_state: assert property (
        @(posedge CLK)
        !RST |-> (shift_reg == 8'h00 && not_reg == 8'h00 && zero_reg == 8'h00 && RGZ == 8'h00)
    );

// ENA low leaves all registers unchanged.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (!RST)
        (!ENA) |=> ($stable(shift_reg) && $stable(not_reg) && $stable(zero_reg))
    );

// OPT=0, KEY=2 updates shift_reg with a 1-bit left shift.
    check_shift_left_1: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b10) |=> (shift_reg == {$past(RGA[6:0]), 1'b0} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

// OPT=0, KEY=0 updates shift_reg with a 1-bit right shift.
    check_shift_right_1: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b00) |=> (shift_reg == {1'b0, $past(RGA[7:1])} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

// OPT=0, KEY=3 updates shift_reg with a 2-bit left shift.
    check_shift_left_2: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b11) |=> (shift_reg == {$past(RGA[5:0]), 2'b00} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

// OPT=0, KEY=1 updates shift_reg with a 2-bit right shift.
    check_shift_right_2: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h00 && KEY == 2'b01) |=> (shift_reg == {2'b00, $past(RGA[7:2])} &&
                                                    $stable(not_reg) &&
                                                    $stable(zero_reg))
    );

// OPT=1, KEY=0 updates not_reg with bitwise inversion of RGA.
    check_not_load: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && OPT == 8'h01 && KEY == 2'b00) |=> (not_reg == ~$past(RGA) &&
                                                    $stable(shift_reg) &&
                                                    $stable(zero_reg))
    );

// All other enabled cases load raw RGA into shift_reg.
    check_default_load: assert property (
        @(posedge CLK) disable iff (!RST)
        (ENA && !(OPT == 8'h00) && !((OPT == 8'h01) && (KEY == 2'b00))) |=> (shift_reg == $past(RGA) &&
                                                                               $stable(not_reg) &&
                                                                               $stable(zero_reg))
    );

// RGB high selects not_reg onto RGZ.
    check_rgz_selects_not_reg: assert property (
        @(posedge CLK) disable iff (!RST)
        (RGB == 1'b1) |-> (RGZ == not_reg)
    );

// RGB low with KEY=2 selects zero_reg onto RGZ.
    check_rgz_selects_zero_reg: assert property (
        @(posedge CLK) disable iff (!RST)
        (RGB == 1'b0 && KEY == 2'b10) |-> (RGZ == zero_reg)
    );

// Otherwise RGZ reflects shift_reg.
    check_rgz_selects_shift_reg: assert property (
        @(posedge CLK) disable iff (!RST)
        (RGB == 1'b0 && KEY != 2'b10) |-> (RGZ == shift_reg)
    );

// Reset clears the register by the next clock.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (data_out == 8'h00)
    );

// Load captures parallel_in when shift is low.
    check_load_captures_parallel_in: assert property (
        @(posedge clk) disable iff (reset)
        (load && !shift) |=> (data_out == $past(parallel_in))
    );

// Load has priority over shift when both are high.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (reset)
        (load && shift) |=> (data_out == $past(parallel_in))
    );

// Shift moves data left and inserts 0 into bit 0.
    check_shift_left_zero_fill: assert property (
        @(posedge clk) disable iff (reset)
        (!load && shift) |=> (data_out == {$past(data_out[6:0]), 1'b0})
    );

// Without load or shift, data_in is captured.
    check_default_captures_data_in: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !shift) |=> (data_out == $past(data_in))
    );

// Addition mode drives out to a + b.
    check_addition_result: assert property (
        @(posedge clk) (op == 1'b0) |-> (out == (a + b))
    );

// Subtraction mode drives out to a - b.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 1'b1) |-> (out == (a - b))
    );

// sel=00 routes data0x to result.
    check_sel_00_routes_data0: assert property (
        @(posedge clk) (sel === 2'b00) |-> (result === data0x)
    );

// sel=01 routes data1x to result.
    check_sel_01_routes_data1: assert property (
        @(posedge clk) (sel === 2'b01) |-> (result === data1x)
    );

// sel=10 routes data2x to result.
    check_sel_10_routes_data2: assert property (
        @(posedge clk) (sel === 2'b10) |-> (result === data2x)
    );

// Z matches the bitwise XOR of A and B.
    check_z_matches_xor: assert property (
        @(posedge clk) Z === (A ^ B)
    );

// Bit 0 of Z is A[0] XOR B[0].
    check_z_bit0_xor: assert property (
        @(posedge clk) Z[0] === (A[0] ^ B[0])
    );

// Bit 1 of Z is A[1] XOR B[1].
    check_z_bit1_xor: assert property (
        @(posedge clk) Z[1] === (A[1] ^ B[1])
    );

// Bit 2 of Z is A[2] XOR B[2].
    check_z_bit2_xor: assert property (
        @(posedge clk) Z[2] === (A[2] ^ B[2])
    );

// Bit 3 of Z is A[3] XOR B[3].
    check_z_bit3_xor: assert property (
        @(posedge clk) Z[3] === (A[3] ^ B[3])
    );

// Bit 4 of Z is A[4] XOR B[4].
    check_z_bit4_xor: assert property (
        @(posedge clk) Z[4] === (A[4] ^ B[4])
    );

// Bit 5 of Z is A[5] XOR B[5].
    check_z_bit5_xor: assert property (
        @(posedge clk) Z[5] === (A[5] ^ B[5])
    );

// Bit 6 of Z is A[6] XOR B[6].
    check_z_bit6_xor: assert property (
        @(posedge clk) Z[6] === (A[6] ^ B[6])
    );

// Bit 7 of Z is A[7] XOR B[7].
    check_z_bit7_xor: assert property (
        @(posedge clk) Z[7] === (A[7] ^ B[7])
    );

// Equal inputs produce zero.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (A == B) |-> (Z == 8'h00)
    );

// Zero on B passes A through.
    check_b_zero_passthrough_a: assert property (
        @(posedge clk) (B == 8'h00) |-> (Z === A)
    );

// Zero on A passes B through.
    check_a_zero_passthrough_b: assert property (
        @(posedge clk) (A == 8'h00) |-> (Z === B)
    );

// Complementary inputs produce all ones.
    check_complement_inputs_all_ones: assert property (
        @(posedge clk) (A == ~B) |-> (Z == 8'hFF)
    );

// RESULT is the 8-bit sum when CTRL is exactly 0.
    check_add_mode: assert property (
        @(posedge clk) (CTRL === 1'b0) |-> (RESULT == (A + B))
    );

// RESULT is the 8-bit difference when CTRL is not exactly 0.
    check_sub_mode: assert property (
        @(posedge clk) (CTRL !== 1'b0) |-> (RESULT == (A - B))
    );

// Synchronous active-high reset clears q on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 4'b0000)
    );

// When disabled and not in reset, q holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!ena) |=> (q == $past(q))
    );

// When enabled and not in reset, q[0] follows the RTL next-state equation.
    check_update_q0_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[0] == ($past(q[3]) ^ (~$past(q[1]))))
    );

// When enabled and not in reset, q[1] follows the RTL next-state equation.
    check_update_q1_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[1] == ($past(q[0]) ^ (~$past(q[2]))))
    );

// When enabled and not in reset, q[2] follows the RTL next-state equation.
    check_update_q2_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[2] == ($past(q[1]) ^ (~$past(q[3]))))
    );

// When enabled and not in reset, q[3] follows the RTL next-state equation.
    check_update_q3_when_enabled: assert property (
        @(posedge clk) disable iff (rst) ena |=> (q[3] == ($past(q[2]) ^ (~$past(q[0]))))
    );

// No reset in RTL; clk is a sampling clock for combinational checks.

    // op 00 selects 4-bit addition of A, B, and C.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (Z == (A + B + C))
    );

// op 01 selects 4-bit subtraction of B and C from A.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (Z == (A - B - C))
    );

// op 10 selects bitwise AND across A, B, and C.
    check_and_result: assert property (
        @(posedge clk) (op == 2'b10) |-> (Z == (A & B & C))
    );

// op 11 selects bitwise OR across A, B, and C.
    check_or_result: assert property (
        @(posedge clk) (op == 2'b11) |-> (Z == (A | B | C))
    );

// A sampled high AND must propagate to y after the pipeline delay.
    check_high_and_reaches_output: assert property (
        @(posedge clk) (a & b) |=> ##2 y
    );

// A sampled low on a must force y low after the pipeline delay.
    check_a_low_reaches_output_low: assert property (
        @(posedge clk) (!a) |=> ##2 !y
    );

// A sampled low on b must force y low after the pipeline delay.
    check_b_low_reaches_output_low: assert property (
        @(posedge clk) (!b) |=> ##2 !y
    );

// Y matches the RTL NAND equation.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A_N & B_N & C & D)
    );

// All four inputs high drives Y low.
    check_all_high_drives_low: assert property (
        @(posedge clk) (A_N & B_N & C & D) |-> !Y
    );

// A_N low forces Y high.
    check_a_low_drives_high: assert property (
        @(posedge clk) !A_N |-> Y
    );

// B_N low forces Y high.
    check_b_low_drives_high: assert property (
        @(posedge clk) !B_N |-> Y
    );

// C low forces Y high.
    check_c_low_drives_high: assert property (
        @(posedge clk) !C |-> Y
    );

// D low forces Y high.
    check_d_low_drives_high: assert property (
        @(posedge clk) !D |-> Y
    );

// Y low can only occur when all inputs are high.
    check_low_output_requires_all_high: assert property (
        @(posedge clk) !Y |-> (A_N & B_N & C & D)
    );

// Y high implies at least one input is low.
    check_high_output_requires_some_low_input: assert property (
        @(posedge clk) Y |-> (!A_N || !B_N || !C || !D)
    );

// Segments must match the RTL decode table for the sampled HEXnumber.
    check_hex_to_7segment_decode: assert property (
        @(posedge clk) Segments === expected_segments(HEXnumber)
    );

// Y must implement the mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == ((A & ~S) | (B & S))
    );

// When S is low, Y must equal A.
    check_select_a_when_s_low: assert property (
        @(posedge clk) !S |-> (Y == A)
    );

// When S is high, Y must equal B.
    check_select_b_when_s_high: assert property (
        @(posedge clk) S |-> (Y == B)
    );

// If both inputs are low, Y must be low.
    check_both_inputs_low: assert property (
        @(posedge clk) (!A && !B) |-> !Y
    );

// If both inputs are high, Y must be high.
    check_both_inputs_high: assert property (
        @(posedge clk) (A && B) |-> Y
    );

// If A is low and B is high, Y must follow S.
    check_low_high_case: assert property (
        @(posedge clk) (!A && B) |-> (Y == S)
    );

// If A is high and B is low, Y must follow inverted S.
    check_high_low_case: assert property (
        @(posedge clk) (A && !B) |-> (Y == ~S)
    );

// 000 selects td_mode 0000.
    check_td_mode_decode_000: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b000) |-> (td_mode == 4'b0000)
    );

// 001 selects td_mode 1000.
    check_td_mode_decode_001: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b001) |-> (td_mode == 4'b1000)
    );

// 010 selects td_mode 0100.
    check_td_mode_decode_010: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b010) |-> (td_mode == 4'b0100)
    );

// 011 selects td_mode 1100.
    check_td_mode_decode_011: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b011) |-> (td_mode == 4'b1100)
    );

// 100 selects td_mode 0010.
    check_td_mode_decode_100: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b100) |-> (td_mode == 4'b0010)
    );

// 101 selects td_mode 1010.
    check_td_mode_decode_101: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b101) |-> (td_mode == 4'b1010)
    );

// 110 selects td_mode 0101.
    check_td_mode_decode_110: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b110) |-> (td_mode == 4'b0101)
    );

// 111 selects td_mode 1111.
    check_td_mode_decode_111: assert property (
        @(posedge clk) (ctrl[7:5] == 3'b111) |-> (td_mode == 4'b1111)
    );

// Output matches the RTL transform of the previous cycle input.
    check_output_transform_function: assert property (
        @(posedge clk)
        1'b1 |=> (
            data_out ==
            (($past(data_in[31:24]) == 8'hFF) ? 16'hFF00 :
             (($past(data_in[7:0]) == 8'h00) ? 16'h000F :
              {$past(data_in[31:24]), $past(data_in[7:0])}))
        )
    );

// A top input byte of 0xFF forces FF00 on the next cycle.
    check_ff_prefix_transform: assert property (
        @(posedge clk)
        (data_in[31:24] == 8'hFF) |=> (data_out == 16'hFF00)
    );

// A low input byte of 0x00 forces 000F when the 0xFF case is not active.
    check_zero_suffix_transform: assert property (
        @(posedge clk)
        (data_in[31:24] != 8'hFF && data_in[7:0] == 8'h00) |=> (data_out == 16'h000F)
    );

// Without either special case, the selected input bytes pass through.
    check_passthrough_transform: assert property (
        @(posedge clk)
        (data_in[31:24] != 8'hFF && data_in[7:0] != 8'h00) |=> (
            data_out == {$past(data_in[31:24]), $past(data_in[7:0])}
        )
    );

// When both conditions are true, the 0xFF check has priority.
    check_ff_priority_over_zero_suffix: assert property (
        @(posedge clk)
        (data_in[31:24] == 8'hFF && data_in[7:0] == 8'h00) |=> (data_out == 16'hFF00)
    );

// A reset cycle clears the counter by the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 16'h0000)
    );

// While reset stays asserted, the sampled count remains zero.
    check_reset_holds_count_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 16'h0000)
    );

// reg_out mirrors reg_in combinationally.
    check_reg_out_mirrors_reg_in: assert property (
        @(posedge clk) reg_out == reg_in
    );

// out is directly driven from reg_out.
    check_out_matches_reg_out: assert property (
        @(posedge clk) out == reg_out
    );

// reg_in captures the input from the prior clock.
    check_reg_in_captures_prior_input: assert property (
        @(posedge clk) 1'b1 |=> (reg_in == $past(in))
    );

// reg_out reflects the previously captured input.
    check_reg_out_reflects_prior_input: assert property (
        @(posedge clk) 1'b1 |=> (reg_out == $past(in))
    );

// out is a one-cycle delayed version of in.
    check_out_is_one_cycle_delayed_input: assert property (
        @(posedge clk) 1'b1 |=> (out == $past(in))
    );

// Y matches the implemented NOR-AND-buffer function.
    check_output_function: assert property (
        @(posedge clk) Y === (C_N & (~A) & (~B))
    );

// A high forces the output low.
    check_a_high_forces_low: assert property (
        @(posedge clk) (A === 1'b1) |-> (Y === 1'b0)
    );

// B high forces the output low.
    check_b_high_forces_low: assert property (
        @(posedge clk) (B === 1'b1) |-> (Y === 1'b0)
    );

// C_N low blocks the output.
    check_cn_low_forces_low: assert property (
        @(posedge clk) (C_N === 1'b0) |-> (Y === 1'b0)
    );

// With A and B low, Y follows C_N.
    check_ab_low_y_follows_cn: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (Y === C_N)
    );

// A high output requires both inputs low and C_N high.
    check_y_high_requires_inputs: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A === 1'b0) && (B === 1'b0) && (C_N === 1'b1))
    );

// Output matches the composed mux-and-OR function.
    check_full_function: assert property (
        @(posedge clk) out == ((select ? data1 : data0) | (select ? data3 : data2))
    );

// Low select chooses data0 and data2.
    check_select_low_function: assert property (
        @(posedge clk) !select |-> (out == (data0 | data2))
    );

// High select chooses data1 and data3.
    check_select_high_function: assert property (
        @(posedge clk) select |-> (out == (data1 | data3))
    );

// Bit 0 matches the selected inputs after the OR.
    check_bit0_function: assert property (
        @(posedge clk) out[0] == ((select ? data1[0] : data0[0]) | (select ? data3[0] : data2[0]))
    );

// Bit 1 matches the selected inputs after the OR.
    check_bit1_function: assert property (
        @(posedge clk) out[1] == ((select ? data1[1] : data0[1]) | (select ? data3[1] : data2[1]))
    );

// Bit 2 matches the selected inputs after the OR.
    check_bit2_function: assert property (
        @(posedge clk) out[2] == ((select ? data1[2] : data0[2]) | (select ? data3[2] : data2[2]))
    );

// Bit 3 matches the selected inputs after the OR.
    check_bit3_function: assert property (
        @(posedge clk) out[3] == ((select ? data1[3] : data0[3]) | (select ? data3[3] : data2[3]))
    );

// Sum bit 0 follows b[0] plus c[0].
    check_sum_bit0_behavior: assert property (
        @(posedge clk)
        sum[0] == (b[0] & ~a[0])
    );

// No low-nibble generate means the output is just {a,b}.
    check_no_generate_passthrough: assert property (
        @(posedge clk)
        ((a[3:0] & b[3:0]) == 4'b0000) |-> (sum == {a, b})
    );

// All low-nibble generates force the adder to add 15.
    check_all_generate_adds_fifteen: assert property (
        @(posedge clk)
        ((a[3:0] & b[3:0]) == 4'b1111) |-> (sum == ({a, b} + 32'd15))
    );

// With bits [3:1] clear, only c[0] can contribute.
    check_only_bit0_region_can_add: assert property (
        @(posedge clk)
        ((a[3:1] == 3'b000) && (b[3:1] == 3'b000)) |-> (sum == ({a, b} + {31'b0, (a[0] & b[0])}))
    );

// With bits [3:2] clear and no bit0 generate, only c[1] can contribute.
    check_only_bit1_region_can_add: assert property (
        @(posedge clk)
        ((a[3:2] == 2'b00) && (b[3:2] == 2'b00) && ((a[0] & b[0]) == 1'b0)) |-> (sum == ({a, b} + {30'b0, (a[1] & b[1]), 1'b0}))
    );

// When select is low, Y follows A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b0) |-> (Y === A0)
    );

// When select is high, Y follows A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) disable iff (1'b0)
        (S === 1'b1) |-> (Y === A1)
    );

// External clock is used only to sample this combinational DUT.

    // byte_num 0 selects the fixed padding value.
    check_byte0_constant_padding: assert property (
        @(posedge clk) (byte_num == 2'd0) |-> (out == 32'h01000000)
    );

// byte_num 1 preserves the upper 24 bits and sets the low byte to 01.
    check_byte1_low_byte_padding: assert property (
        @(posedge clk) (byte_num == 2'd1) |-> (out == {in[31:8], 8'h01})
    );

// byte_num 2 preserves the upper 16 bits and sets the low halfword to 0100.
    check_byte2_low_halfword_padding: assert property (
        @(posedge clk) (byte_num == 2'd2) |-> (out == {in[31:16], 16'h0100})
    );

// byte_num 3 preserves the upper 8 bits and sets the low 24 bits to 010000.
    check_byte3_low_24bit_padding: assert property (
        @(posedge clk) (byte_num == 2'd3) |-> (out == {in[31:24], 24'h010000})
    );

// When load is high, bit 3 captures input bit 3 on the next clock.
    check_load_captures_bit3: assert property (
        @(posedge clk) load |=> data_out[3] == $past(data_in[3])
    );

// When load is high, bit 2 captures input bit 2 on the next clock.
    check_load_captures_bit2: assert property (
        @(posedge clk) load |=> data_out[2] == $past(data_in[2])
    );

// When load is high, bit 1 captures input bit 1 on the next clock.
    check_load_captures_bit1: assert property (
        @(posedge clk) load |=> data_out[1] == $past(data_in[1])
    );

// When load is high, bit 0 captures input bit 0 on the next clock.
    check_load_captures_bit0: assert property (
        @(posedge clk) load |=> data_out[0] == $past(data_in[0])
    );

// When load is low, bit 3 takes the previous bit 2 on the next clock.
    check_rotate_bit3_from_bit2: assert property (
        @(posedge clk) !load |=> data_out[3] == $past(data_out[2])
    );

// When load is low, bit 2 takes the previous bit 1 on the next clock.
    check_rotate_bit2_from_bit1: assert property (
        @(posedge clk) !load |=> data_out[2] == $past(data_out[1])
    );

// When load is low, bit 1 takes the previous bit 0 on the next clock.
    check_rotate_bit1_from_bit0: assert property (
        @(posedge clk) !load |=> data_out[1] == $past(data_out[0])
    );

// When load is low, bit 0 takes the previous bit 3 on the next clock.
    check_rotate_bit0_from_bit3: assert property (
        @(posedge clk) !load |=> data_out[0] == $past(data_out[3])
    );

// logic_out must match the implemented priority mux and datapath.
    check_logic_out_mux_function: assert property (
        @(posedge clk)
        logic_out == (
            isand ? (rs1_data & (rs2_data ^ {64{inv_logic}})) :
            isor  ? (rs1_data | (rs2_data ^ {64{inv_logic}})) :
            isxor ? (rs1_data ^ (rs2_data ^ {64{inv_logic}})) :
                    {(rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}}), rs2_data[31:0]}
        )
    );

// isand selects the AND path regardless of other select inputs.
    check_and_selected: assert property (
        @(posedge clk)
        isand |-> (logic_out == (rs1_data & (rs2_data ^ {64{inv_logic}})))
    );

// isor selects the OR path when isand is not asserted.
    check_or_selected: assert property (
        @(posedge clk)
        (!isand && isor) |-> (logic_out == (rs1_data | (rs2_data ^ {64{inv_logic}})))
    );

// isxor selects the XOR path when higher-priority selects are not asserted.
    check_xor_selected: assert property (
        @(posedge clk)
        (!isand && !isor && isxor) |-> (logic_out == (rs1_data ^ (rs2_data ^ {64{inv_logic}})))
    );

// With no boolean select asserted, logic_out must follow mov_data.
    check_mov_selected: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (
            logic_out == {(rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}}), rs2_data[31:0]}
        )
    );

// In mov mode, the upper half is masked off only by ifu_exu_sethi_inst_e.
    check_mov_upper_half_masked: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (
            logic_out[63:32] == (rs2_data[63:32] & {32{~ifu_exu_sethi_inst_e}})
        )
    );

// In mov mode, the lower half always passes rs2_data unchanged.
    check_mov_lower_half_passes_rs2: assert property (
        @(posedge clk)
        (!isand && !isor && !isxor) |-> (logic_out[31:0] == rs2_data[31:0])
    );

// Q updates each cycle from either D or the rotated previous Q.
    check_state_update: assert property (
        @(posedge CK)
        1'b1 |=> Q == ($past(S) ? $past(D) : {$past(Q[2:0]), $past(Q[3])})
    );

// When S is high, Q loads D.
    check_load_on_select: assert property (
        @(posedge CK)
        S |=> Q == $past(D)
    );

// When S is low, Q rotates left by one bit.
    check_rotate_on_shift: assert property (
        @(posedge CK)
        !S |=> Q == {$past(Q[2:0]), $past(Q[3])}
    );

// In shift mode, Q[3] comes from the previous Q[2].
    check_rotate_bit3: assert property (
        @(posedge CK)
        !S |=> Q[3] == $past(Q[2])
    );

// In shift mode, Q[2] comes from the previous Q[1].
    check_rotate_bit2: assert property (
        @(posedge CK)
        !S |=> Q[2] == $past(Q[1])
    );

// In shift mode, Q[1] comes from the previous Q[0].
    check_rotate_bit1: assert property (
        @(posedge CK)
        !S |=> Q[1] == $past(Q[0])
    );

// In shift mode, Q[0] comes from the previous Q[3].
    check_rotate_bit0: assert property (
        @(posedge CK)
        !S |=> Q[0] == $past(Q[3])
    );

// Four consecutive shifts restore the original value.
    check_four_shifts_restore_state: assert property (
        @(posedge CK)
        (!S)[*4] |=> Q == $past(Q, 4)
    );

// Enabled updates follow RESET, then SET, then D priority.
    check_enabled_update_value: assert property (
        @(posedge CLK)
        CE |=> (Q == ($past(RESET) ? 1'b0 : ($past(SET) ? 1'b1 : $past(D))))
    );

// RESET clears Q on the next clock when CE is high.
    check_reset_clears_q: assert property (
        @(posedge CLK)
        CE && RESET |=> (Q == 1'b0)
    );

// RESET overrides SET when both are high and CE is high.
    check_reset_priority_over_set: assert property (
        @(posedge CLK)
        CE && RESET && SET |=> (Q == 1'b0)
    );

// SET drives Q high when enabled and not in reset.
    check_set_sets_q: assert property (
        @(posedge CLK) disable iff (RESET)
        CE && SET |=> (Q == 1'b1)
    );

// D is captured when enabled with neither RESET nor SET active.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (RESET)
        CE && !SET |=> (Q == $past(D))
    );

// Q holds its value whenever CE is low.
    check_ce_low_holds_q: assert property (
        @(posedge CLK)
        !CE |=> (Q == $past(Q))
    );

// External sampling clock; DUT has no clock or reset.

    // SUM matches A xor B xor inverted CIN.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ (~CIN))
    );

// COUT matches the OR of the three carry product terms.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & (~CIN)) | (B & (~CIN)))
    );

// With CIN high, the inverted carry-in term is zero.
    check_cin_high_mode: assert property (
        @(posedge clk) CIN |-> ((SUM == (A ^ B)) && (COUT == (A & B)))
    );

// With CIN low, the inverted carry-in term is one.
    check_cin_low_mode: assert property (
        @(posedge clk) !CIN |-> ((SUM == (~(A ^ B))) && (COUT == (A | B)))
    );

// When both data inputs are low, carry out stays low.
    check_inputs_00: assert property (
        @(posedge clk) (!A && !B) |-> ((SUM == (~CIN)) && (COUT == 1'b0))
    );

// When both data inputs are high, carry out stays high.
    check_inputs_11: assert property (
        @(posedge clk) (A && B) |-> ((SUM == (~CIN)) && (COUT == 1'b1))
    );

// When only A is high, outputs depend only on CIN inversion.
    check_inputs_10: assert property (
        @(posedge clk) (A && !B) |-> ((SUM == CIN) && (COUT == (~CIN)))
    );

// When only B is high, outputs depend only on CIN inversion.
    check_inputs_01: assert property (
        @(posedge clk) (!A && B) |-> ((SUM == CIN) && (COUT == (~CIN)))
    );

// Equal A and B produce SUM equal to inverted CIN and COUT equal to A.
    check_equal_inputs_relation: assert property (
        @(posedge clk) !(A ^ B) |-> ((SUM == (~CIN)) && (COUT == A))
    );

// Unequal A and B produce SUM equal to CIN and COUT equal to inverted CIN.
    check_unequal_inputs_relation: assert property (
        @(posedge clk) (A ^ B) |-> ((SUM == CIN) && (COUT == (~CIN)))
    );

// X matches the implemented O221A Boolean function.
    check_x_matches_o221a_function: assert property (
        @(posedge clk) X == (((B2 | B1) & (A2 | A1)) & C1)
    );

// C1 low forces the output low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// If both A inputs are low, the output is low.
    check_a_inputs_low_force_x_low: assert property (
        @(posedge clk) !(A2 | A1) |-> !X
    );

// If both B inputs are low, the output is low.
    check_b_inputs_low_force_x_low: assert property (
        @(posedge clk) !(B2 | B1) |-> !X
    );

// A high output requires C1 and one A input and one B input high.
    check_x_high_requires_all_enables: assert property (
        @(posedge clk) X |-> (C1 && (A2 | A1) && (B2 | B1))
    );

// C1 and one A input and one B input high drive the output high.
    check_all_enables_drive_x_high: assert property (
        @(posedge clk) (C1 && (A2 | A1) && (B2 | B1)) |-> X
    );

// Output always equals input plus three.
    check_add_three_function: assert property (
        @(posedge clk) out == (in + 4'b0011)
    );

// Bit 0 inverts when adding three.
    check_out_bit0: assert property (
        @(posedge clk) out[0] == ~in[0]
    );

// Bit 1 includes the carry from bit 0.
    check_out_bit1: assert property (
        @(posedge clk) out[1] == ~(in[1] ^ in[0])
    );

// Bit 2 includes carry propagation from the low bits.
    check_out_bit2: assert property (
        @(posedge clk) out[2] == (in[2] ^ (in[1] | in[0]))
    );

// Bit 3 includes carry propagation into the MSB.
    check_out_bit3: assert property (
        @(posedge clk) out[3] == (in[3] ^ (in[2] & (in[1] | in[0])))
    );

// module1 output clears on the cycle after reset is asserted.
    check_module1_reset_clears: assert property (
        @(posedge clk) reset |=> (out_module1 == 32'b0)
    );

// module1 shifts prior bits [30:0] into bits [31:1].
    check_module1_shift_upper_bits: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out_module1[31:1] == $past(out_module1[30:0]))
    );

// module1 loads the previous in[31] into bit 0.
    check_module1_loads_input_into_lsb: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out_module1[0] == $past(in[31]))
    );

// module2 registers the previous out_module1[0].
    check_module2_captures_module1_lsb: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (q_module2 == $past(out_module1[0]))
    );

// functional_module passes out_module1 when select is high.
    check_functional_select_high: assert property (
        @(posedge clk) disable iff (reset)
        select |-> (out_functional == out_module1)
    );

// functional_module zero-extends q_module2 when select is low.
    check_functional_select_low: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (out_functional == {31'b0, q_module2})
    );

// top-level q is the low bit of out_functional.
    check_top_q_matches_out_functional_lsb: assert property (
        @(posedge clk) disable iff (reset)
        q == out_functional[0]
    );

// q matches out_module1[0] when select is high.
    check_top_q_select_high: assert property (
        @(posedge clk) disable iff (reset)
        select |-> (q == out_module1[0])
    );

// q matches q_module2 when select is low.
    check_top_q_select_low: assert property (
        @(posedge clk) disable iff (reset)
        !select |-> (q == q_module2)
    );

// Writing DEVOPTS2 updates the mapped outputs on the next cycle.
    write_devopts2_updates_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((zxuno_regwr == 1'b1) && (zxuno_addr == DEVOPTS2))
        |=> (disable_timexscr == $past(din[0])) &&
            (disable_ulaplus == $past(din[1])) &&
            (disable_radas == $past(din[2]))
    );

// Writing DEVOPTIONS does not change DEVOPTS2-controlled outputs.
    write_devoptions_preserves_devopts2_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((zxuno_regwr == 1'b1) && (zxuno_addr == DEVOPTIONS))
        |=> ({disable_radas, disable_ulaplus, disable_timexscr} ==
             $past({disable_radas, disable_ulaplus, disable_timexscr}))
    );

// Writing DEVOPTS2 does not change DEVOPTIONS-controlled outputs.
    write_devopts2_preserves_devoptions_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((zxuno_regwr == 1'b1) && (zxuno_addr == DEVOPTS2))
        |=> ({disable_spisd, enable_timexmmu, disable_romsel1f, disable_romsel7f,
              disable_1ffd, disable_7ffd, disable_turboay, disable_ay} ==
             $past({disable_spisd, enable_timexmmu, disable_romsel1f, disable_romsel7f,
                    disable_1ffd, disable_7ffd, disable_turboay, disable_ay}))
    );

// When no register read is requested, the bus stays deasserted.
    no_read_returns_default_bus: assert property (
        @(posedge clk) disable iff (!rst_n)
        (zxuno_regrd == 1'b0) |-> (oe_n == 1'b1) && (dout == 8'hFF)
    );

// Reading an unmapped address returns the default bus value.
    read_unknown_address_returns_default_bus: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((zxuno_regrd == 1'b1) &&
         (zxuno_addr != DEVOPTIONS) &&
         (zxuno_addr != DEVOPTS2))
        |-> (oe_n == 1'b1) && (dout == 8'hFF)
    );

// Reading DEVOPTIONS enables the bus and returns the current bits.
    read_devoptions_returns_current_value: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((zxuno_regrd == 1'b1) && (zxuno_addr == DEVOPTIONS))
        |-> (oe_n == 1'b0) &&
            (dout == {disable_spisd, enable_timexmmu, disable_romsel1f, disable_romsel7f,
                      disable_1ffd, disable_7ffd, disable_turboay, disable_ay})
    );

// Reading DEVOPTS2 enables the bus and returns the visible low bits.
    read_devopts2_returns_current_low_bits: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((zxuno_regrd == 1'b1) && (zxuno_addr == DEVOPTS2))
        |-> (oe_n == 1'b0) &&
            (dout[2:0] == {disable_radas, disable_ulaplus, disable_timexscr})
    );

// An immediate DEVOPTS2 read after a write returns the written byte.
    write_then_read_devopts2_returns_written_byte: assert property (
        @(posedge clk) disable iff (!rst_n)
        ((zxuno_regwr == 1'b1) && (zxuno_addr == DEVOPTS2))
        ##1 ((zxuno_regrd == 1'b1) && (zxuno_addr == DEVOPTS2))
        |-> (oe_n == 1'b0) && (dout == $past(din))
    );

// MO always matches the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) MO === ((S == 1'b1) ? B : A)
    );

// When S is low, MO follows A.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (MO === A)
    );

// When S is high, MO follows B.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (MO === B)
    );

// If both inputs are identical, MO matches that common value.
    check_equal_inputs_preserved: assert property (
        @(posedge clk) (A === B) |-> (MO === A)
    );

// Active-low reset clears the register output.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !rst_n |-> (data_out == 8'h00)
    );

// When load is high, the next output matches the input value.
    check_load_captures_data_in: assert property (
        @(posedge clk) disable iff (!rst_n)
        load |=> (data_out == $past(data_in))
    );

// When load is low, the next output shifts left and inserts 0 in bit 0.
    check_shift_updates_data_out: assert property (
        @(posedge clk) disable iff (!rst_n)
        !load |=> (data_out == {$past(data_out[6:0]), 1'b0})
    );

// A shift operation always drives the new LSB to 0.
    check_shift_inserts_zero_lsb: assert property (
        @(posedge clk) disable iff (!rst_n)
        !load |=> (data_out[0] == 1'b0)
    );

// A shift operation moves prior bits [6:0] into current bits [7:1].
    check_shift_moves_upper_bits: assert property (
        @(posedge clk) disable iff (!rst_n)
        !load |=> (data_out[7:1] == $past(data_out[6:0]))
    );

// All valid signals are tied high.
    check_valid_always_high: assert property (
        @(posedge csi_MCLK_clk) disable iff (rsi_MRST_reset)
        (aso_fled0_valid == 1'b1) &&
        (aso_fled1_valid == 1'b1) &&
        (aso_fled2_valid == 1'b1) &&
        (aso_fled3_valid == 1'b1)
    );

// Each output bus is the documented permutation of the RGB counters.
    check_output_data_mappings: assert property (
        @(posedge csi_MCLK_clk) disable iff (rsi_MRST_reset)
        (aso_fled0_data == {r_cnt, g_cnt, b_cnt}) &&
        (aso_fled1_data == {g_cnt, b_cnt, r_cnt}) &&
        (aso_fled2_data == {b_cnt, r_cnt, g_cnt}) &&
        (aso_fled3_data == {g_cnt, r_cnt, b_cnt})
    );

// Ramp states increment the delay counter on non-terminal counts.
    check_ramp_delay_increments: assert property (
        @(posedge csi_MCLK_clk) disable iff (rsi_MRST_reset)
        (((state == 6'd0) || (state == 6'd2) || (state == 6'd4) ||
          (state == 6'd6) || (state == 6'd8) || (state == 6'd10)) &&
         (delay_cnt != 19'h7FFFF))
        |=> (delay_cnt == ($past(delay_cnt) + 19'd1))
    );

// Full-scale counts move the rise phases into their transition states.
    check_full_scale_phase_transitions: assert property (
        @(posedge csi_MCLK_clk) disable iff (rsi_MRST_reset)
        (((state == 6'd0) && (r_cnt == 8'hFF)) ||
         ((state == 6'd4) && (g_cnt == 8'hFF)) ||
         ((state == 6'd8) && (b_cnt == 8'hFF)))
        |=> (
                (($past(state) == 6'd0) && (state == 6'd1)) ||
                (($past(state) == 6'd4) && (state == 6'd5)) ||
                (($past(state) == 6'd8) && (state == 6'd9))
            )
    );

// States 1, 5, and 9 are single-cycle transitions that clear delay_cnt.
    check_transition_states_advance: assert property (
        @(posedge csi_MCLK_clk) disable iff (rsi_MRST_reset)
        ((state == 6'd1) || (state == 6'd5) || (state == 6'd9))
        |=> (delay_cnt == 19'd0) &&
            (
                (($past(state) == 6'd1) && (state == 6'd2)) ||
                (($past(state) == 6'd5) && (state == 6'd6)) ||
                (($past(state) == 6'd9) && (state == 6'd10))
            )
    );

// Zero counts move the fall phases into their clear states.
    check_zero_scale_phase_transitions: assert property (
        @(posedge csi_MCLK_clk) disable iff (rsi_MRST_reset)
        (((state == 6'd2) && (r_cnt == 8'h00)) ||
         ((state == 6'd6) && (g_cnt == 8'h00)) ||
         ((state == 6'd10) && (b_cnt == 8'h00)))
        |=> (
                (($past(state) == 6'd2) && (state == 6'd3)) ||
                (($past(state) == 6'd6) && (state == 6'd7)) ||
                (($past(state) == 6'd10) && (state == 6'd11))
            )
    );

// Any out-of-range state follows the default branch back to state 0.
    check_illegal_state_recovers: assert property (
        @(posedge csi_MCLK_clk) disable iff (rsi_MRST_reset)
        (state > 6'd11)
        |=> (state == 6'd0) &&
            (r_cnt == 8'd0) &&
            (g_cnt == 8'd0) &&
            (b_cnt == 8'd0) &&
            (delay_cnt == 19'd0)
    );

// X matches the implemented NOR/NOR/BUF logic.
    check_function: assert property (
        @(posedge clk) X == ((~B1_N) & (A1 | A2))
    );

// A high B1_N forces X low.
    check_b1n_high_forces_low: assert property (
        @(posedge clk) (B1_N == 1'b1) |-> (X == 1'b0)
    );

// With both A inputs low, X must be low.
    check_no_a_inputs_forces_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// With B1_N low and A1 high, X must be high.
    check_a1_high_with_b1n_low_drives_high: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

// With B1_N low and A2 high, X must be high.
    check_a2_high_with_b1n_low_drives_high: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

// A high X requires B1_N to be low.
    check_high_output_requires_b1n_low: assert property (
        @(posedge clk) (X == 1'b1) |-> (B1_N == 1'b0)
    );

// A high X requires at least one A input to be high.
    check_high_output_requires_a_input: assert property (
        @(posedge clk) (X == 1'b1) |-> ((A1 == 1'b1) || (A2 == 1'b1))
    );

// If B1_N is low and X is low, both A inputs must be low.
    check_low_output_with_b1n_low_requires_no_a_input: assert property (
        @(posedge clk) ((B1_N == 1'b0) && (X == 1'b0)) |-> ((A1 == 1'b0) && (A2 == 1'b0))
    );

// Active-low reset forces count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 3'b000)
    );

// When enabled, count increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable == 1'b1) |=> (count == ($past(count) + 3'b001))
    );

// When not enabled, count decrements by one on the next clock.
    check_count_decrements: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable != 1'b1) |=> (count == ($past(count) - 3'b001))
    );

// Incrementing from 7 wraps back to 0.
    check_increment_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable == 1'b1) && (count == 3'b111) |=> (count == 3'b000)
    );

// Decrementing from 0 wraps back to 7.
    check_decrement_wraps_to_seven: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        (enable != 1'b1) && (count == 3'b000) |=> (count == 3'b111)
    );

// Outside reset, count must change every clock.
    check_count_never_stalls: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
        1'b1 |=> (count != $past(count))
    );

// Y matches the implemented nand-of-nands logic.
    check_nand4_function: assert property (
        @(posedge clk) Y == ~((~(A & B)) & (~(C & D)))
    );

// A and B both high force Y high.
    check_ab_pair_sets_y_high: assert property (
        @(posedge clk) (A & B) |-> Y
    );

// C and D both high force Y high.
    check_cd_pair_sets_y_high: assert property (
        @(posedge clk) (C & D) |-> Y
    );

// If neither pair is high, Y must be low.
    check_no_active_pair_sets_y_low: assert property (
        @(posedge clk) (!(A & B) && !(C & D)) |-> !Y
    );

// All inputs low produce a low Y.
    check_all_inputs_low: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> !Y
    );

// All inputs high produce a high Y.
    check_all_inputs_high: assert property (
        @(posedge clk) (A && B && C && D) |-> Y
    );

// Y implements A & B & ~C.
    check_output_function: assert property (
        @(posedge clk) Y == (A & B & ~C)
    );

// Y can only be high when A and B are high and C is low.
    check_y_high_requires_inputs: assert property (
        @(posedge clk) Y |-> (A && B && !C)
    );

// A low forces Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// C high forces Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// A and B high with C low forces Y high.
    check_all_true_inputs_drive_y_high: assert property (
        @(posedge clk) (A && B && !C) |-> Y
    );

// With A and B high, Y equals the inverse of C.
    check_ab_high_makes_y_follow_not_c: assert property (
        @(posedge clk) (A && B) |-> (Y == !C)
    );

// With C low, Y matches A AND B.
    check_c_low_makes_y_follow_a_and_b: assert property (
        @(posedge clk) !C |-> (Y == (A & B))
    );

// No clock or reset exists in the RTL; sample combinational behavior on clk.

    // Sum[0] matches the implemented XOR with Cin.
    check_sum_bit0_logic: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum[1] matches the implemented XOR with bit-0 AND.
    check_sum_bit1_logic: assert property (
        @(posedge clk) Sum[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

// Sum[2] matches the implemented XOR with bit-1 AND.
    check_sum_bit2_logic: assert property (
        @(posedge clk) Sum[2] == (A[2] ^ B[2] ^ (A[1] & B[1]))
    );

// Sum[3] matches the implemented XOR with bit-2 AND.
    check_sum_bit3_logic: assert property (
        @(posedge clk) Sum[3] == (A[3] ^ B[3] ^ (A[2] & B[2]))
    );

// Cout matches the implemented carry equation.
    check_cout_logic: assert property (
        @(posedge clk) Cout == (
            ((A[0] & B[0]) & (A[1] & B[1])) |
            ((A[1] & B[1]) & (A[2] & B[2])) |
            ((A[2] & B[2]) & (A[3] & B[3])) |
            ((A[3] & B[3]) & Cin)
        )
    );

// S must equal the 8-bit sum of A and B.
    check_sum_function: assert property (
        @(posedge clk) S == (A + B)
    );

// D must equal the 8-bit difference of A and B.
    check_diff_function: assert property (
        @(posedge clk) D == (A - B)
    );

// Equal inputs must produce a zero difference.
    check_equal_inputs_zero_diff: assert property (
        @(posedge clk) (A == B) |-> (D == 8'h00)
    );

// B equal to zero must pass A through both outputs.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 8'h00) |-> ((S == A) && (D == A))
    );

// A equal to zero must make S equal B and D equal 0 minus B.
    check_zero_a_behavior: assert property (
        @(posedge clk) (A == 8'h00) |-> ((S == B) && (D == (8'h00 - B)))
    );

// SLEEP asserted forces virtual power low.
    check_sleep_forces_off: assert property (
        @(posedge clk) SLEEP |-> !VIRTPWR
    );

// Loss of VPWR forces virtual power low.
    check_vpwr_loss_forces_off: assert property (
        @(posedge clk) !VPWR |-> !VIRTPWR
    );

// Loss of VPB forces virtual power low.
    check_vpb_loss_forces_off: assert property (
        @(posedge clk) !VPB |-> !VIRTPWR
    );

// Loss of VNB forces virtual power low.
    check_vnb_loss_forces_off: assert property (
        @(posedge clk) !VNB |-> !VIRTPWR
    );

// All valid inputs drive virtual power high.
    check_all_conditions_enable_power: assert property (
        @(posedge clk) (!SLEEP && VPWR && VPB && VNB) |-> VIRTPWR
    );

// Virtual power high requires all inputs to be valid.
    check_output_high_requires_valid_inputs: assert property (
        @(posedge clk) VIRTPWR |-> (!SLEEP && VPWR && VPB && VNB)
    );

// Virtual power low requires at least one disabling condition.
    check_output_low_requires_disable_condition: assert property (
        @(posedge clk) !VIRTPWR |-> (SLEEP || !VPWR || !VPB || !VNB)
    );

// Output matches the implemented combinational equation.
    check_output_matches_equation: assert property (
        @(posedge clk) VIRTPWR == (!SLEEP && VPWR && VPB && VNB)
    );

// Combined carry and sum must match 4-bit addition with carry-in.
    check_full_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + {4'b0000, Cin})
    );

// Bit 0 sum must implement the full-adder XOR equation.
    check_bit0_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Lower two sum bits must match the 2-bit addition result.
    check_low2_sum: assert property (
        @(posedge clk) S[1:0] == (A[1:0] + B[1:0] + Cin)
    );

// Lower three sum bits must match the 3-bit addition result.
    check_low3_sum: assert property (
        @(posedge clk) S[2:0] == (A[2:0] + B[2:0] + Cin)
    );

// Zero B and zero carry-in must pass A through with no carry-out.
    check_b_zero_passthrough: assert property (
        @(posedge clk) ((B == 4'b0000) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

// Zero A and zero carry-in must pass B through with no carry-out.
    check_a_zero_passthrough: assert property (
        @(posedge clk) ((A == 4'b0000) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

// Zero A and zero B must pass Cin into the least-significant sum bit only.
    check_cin_only_behavior: assert property (
        @(posedge clk) ((A == 4'b0000) && (B == 4'b0000)) |-> ((S == {3'b000, Cin}) && (Cout == 1'b0))
    );

// Carry-out must be asserted exactly when the 5-bit sum exceeds 15.
    check_cout_threshold: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + {4'b0000, Cin}) > 5'd15)
    );

// Output captures the prior-cycle selected function of a and b.
    check_registered_mux_function: assert property (
        @(posedge clk)
        1'b1 |=> (out_always_ff == ($past(select)
                                   ? ($past(a) | $past(b))
                                   : (($past(a) & ~$past(b)) | (~$past(a) & $past(b))))
        )
    );

// When select is low, output captures the prior XOR function.
    check_xor_path: assert property (
        @(posedge clk)
        !select |=> (out_always_ff == (($past(a) & ~$past(b)) | (~$past(a) & $past(b)))
        )
    );

// When select is high, output captures the prior OR function.
    check_or_path: assert property (
        @(posedge clk)
        select |=> (out_always_ff == ($past(a) | $past(b)))
    );

// With select low and equal inputs, output is low on the next clock.
    check_xor_equal_inputs_zero: assert property (
        @(posedge clk)
        (!select && (a == b)) |=> (out_always_ff == 1'b0)
    );

// With select low and different inputs, output is high on the next clock.
    check_xor_different_inputs_one: assert property (
        @(posedge clk)
        (!select && (a != b)) |=> (out_always_ff == 1'b1)
    );

// With select high and both inputs low, output is low on the next clock.
    check_or_both_low_zero: assert property (
        @(posedge clk)
        (select && !a && !b) |=> (out_always_ff == 1'b0)
    );

// With select high and any input high, output is high on the next clock.
    check_or_any_high_one: assert property (
        @(posedge clk)
        (select && (a || b)) |=> (out_always_ff == 1'b1)
    );

// Before clk rises, the gated clock must be low.
    check_gated_clk_low_on_posedge: assert property (
        @(posedge clk) gated_clk == 1'b0
    );

// With enable low, the gated clock must be low before clk falls.
    check_gated_clk_blocked_when_disabled: assert property (
        @(negedge clk) !enable |-> (gated_clk == 1'b0)
    );

// With enable high, the gated clock must be high before clk falls.
    check_gated_clk_passes_when_enabled: assert property (
        @(negedge clk) enable |-> (gated_clk == 1'b1)
    );

// goto_readDestAdrNib1 is the same decode as state1a.
    check_goto_matches_state1a: assert property (
        @(posedge s_axi_aclk) goto_readDestAdrNib1 == state1a
    );

// The two exported state decodes are never high together.
    check_state_decodes_mutex: assert property (
        @(posedge s_axi_aclk) !(state1a && state0a)
    );

// out_1 matches the combinational definition from state0a and ram_valid_i.
    check_out1_definition: assert property (
        @(posedge s_axi_aclk) out_1 == (state0a && ram_valid_i)
    );

// In state0a, ram_valid_i drives a transition to state1a on the next cycle.
    check_idle_to_state1_on_ram_valid: assert property (
        @(posedge s_axi_aclk) (state0a && ram_valid_i) |=> state1a
    );

// In state0a without ram_valid_i, the state stays in state0a.
    check_idle_holds_without_ram_valid: assert property (
        @(posedge s_axi_aclk) (state0a && !ram_valid_i) |=> state0a
    );

// In state1a with startReadDestAdrNib low, the next cycle returns to state0a.
    check_state1_to_state0_when_start_low: assert property (
        @(posedge s_axi_aclk) (state1a && !startReadDestAdrNib) |=> state0a
    );

// In state1a with startReadDestAdrNib high, the state remains state1a.
    check_state1_holds_when_start_high: assert property (
        @(posedge s_axi_aclk) (state1a && startReadDestAdrNib) |=> state1a
    );

// out_1 can only be high while the exported state decode is state0a.
    check_out1_only_in_state0: assert property (
        @(posedge s_axi_aclk) out_1 |-> state0a
    );

// out_1 implies the machine will be in state1a on the next cycle.
    check_out1_leads_to_state1: assert property (
        @(posedge s_axi_aclk) out_1 |=> state1a
    );

// 000 selects bit 0.
    check_decode_000: assert property (
        @(posedge clk) (in === 3'b000) |-> (out === 8'b00000001)
    );

// 001 selects bit 1.
    check_decode_001: assert property (
        @(posedge clk) (in === 3'b001) |-> (out === 8'b00000010)
    );

// 010 selects bit 2.
    check_decode_010: assert property (
        @(posedge clk) (in === 3'b010) |-> (out === 8'b00000100)
    );

// 011 selects bit 3.
    check_decode_011: assert property (
        @(posedge clk) (in === 3'b011) |-> (out === 8'b00001000)
    );

// 100 selects bit 4.
    check_decode_100: assert property (
        @(posedge clk) (in === 3'b100) |-> (out === 8'b00010000)
    );

// 101 selects bit 5.
    check_decode_101: assert property (
        @(posedge clk) (in === 3'b101) |-> (out === 8'b00100000)
    );

// 110 selects bit 6.
    check_decode_110: assert property (
        @(posedge clk) (in === 3'b110) |-> (out === 8'b01000000)
    );

// 111 selects bit 7.
    check_decode_111: assert property (
        @(posedge clk) (in === 3'b111) |-> (out === 8'b10000000)
    );

// For known inputs, the output is one-hot.
    check_output_onehot: assert property (
        @(posedge clk) !$isunknown(in) |-> $onehot(out)
    );

// For known inputs, the output matches a left-shifted decode.
    check_output_matches_shift: assert property (
        @(posedge clk) !$isunknown(in) |-> (out === (8'b00000001 << in))
    );

// Y matches the RTL XNOR function of A and B.
    check_y_matches_xnor_function: assert property (
        @(posedge clk) (Y == ~(A ^ B))
    );

// A=0 and B=0 drive Y high.
    check_00_outputs_high: assert property (
        @(posedge clk) ((!A && !B) |-> (Y == 1'b1))
    );

// A=0 and B=1 drive Y low.
    check_01_outputs_low: assert property (
        @(posedge clk) ((!A && B) |-> (Y == 1'b0))
    );

// A=1 and B=0 drive Y low.
    check_10_outputs_low: assert property (
        @(posedge clk) ((A && !B) |-> (Y == 1'b0))
    );

// A=1 and B=1 drive Y high.
    check_11_outputs_high: assert property (
        @(posedge clk) ((A && B) |-> (Y == 1'b1))
    );

// Y must implement the 2-input NOR equation.
    check_nor_equation: assert property (
        @(posedge clk) Y == ~(A | B)
    );

// Both inputs low must drive Y high.
    check_nor_00: assert property (
        @(posedge clk) (!A && !B) |-> Y
    );

// A low and B high must drive Y low.
    check_nor_01: assert property (
        @(posedge clk) (!A && B) |-> !Y
    );

// A high and B low must drive Y low.
    check_nor_10: assert property (
        @(posedge clk) (A && !B) |-> !Y
    );

// Both inputs high must drive Y low.
    check_nor_11: assert property (
        @(posedge clk) (A && B) |-> !Y
    );

// X matches the implemented AO31 logic function.
    check_output_matches_a31o: assert property (
        @(posedge clk) disable iff (1'b0) X == ((A1 & A2 & A3) | B1)
    );

// B1 high forces the OR output high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0) B1 |-> X
    );

// A1, A2, and A3 high force the AND term high.
    check_and_term_forces_x_high: assert property (
        @(posedge clk) disable iff (1'b0) (A1 & A2 & A3) |-> X
    );

// With B1 low, X follows the three-input AND term.
    check_b1_low_makes_x_follow_and_term: assert property (
        @(posedge clk) disable iff (1'b0) !B1 |-> (X == (A1 & A2 & A3))
    );

// If neither term is active, X must be low.
    check_no_active_term_keeps_x_low: assert property (
        @(posedge clk) disable iff (1'b0) (!B1 && !(A1 & A2 & A3)) |-> !X
    );

// X low implies the B1 OR input is low.
    check_x_low_requires_b1_low: assert property (
        @(posedge clk) disable iff (1'b0) !X |-> !B1
    );

// X low implies the three-input AND term is low.
    check_x_low_requires_and_term_low: assert property (
        @(posedge clk) disable iff (1'b0) !X |-> !(A1 & A2 & A3)
    );

// Clock: CLK
    // Reset: none
    // Mixed logic: combinational select feeding sequential Q_out

    // When SCE is low, Q_out captures D on the next clock.
    check_capture_d_when_sce_low: assert property (
        @(posedge CLK)
        (SCE === 1'b0) |=> (Q_out === $past(D))
    );

// When SCE is high, Q_out captures SCD on the next clock.
    check_capture_scd_when_sce_high: assert property (
        @(posedge CLK)
        (SCE === 1'b1) |=> (Q_out === $past(SCD))
    );

// When SCE is neither 0 nor 1, Q_out holds its previous value.
    check_hold_when_sce_unknown: assert property (
        @(posedge CLK)
        ((SCE !== 1'b0) && (SCE !== 1'b1)) |=> (Q_out === $past(Q_out))
    );

// ctrl=00 places data in the low byte.
    check_display_beginning_of_line: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (display == {8'b0, data})
    );

// ctrl=01 places data in the high byte.
    check_display_end_of_line: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (display == {data, 8'b0})
    );

// ctrl=10 centers data with zero padding.
    check_display_centered: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (display == {4'b0, data, 4'b0})
    );

// ctrl=11 clears the display.
    check_display_clear: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (display == 16'h0000)
    );

// clk is the only assertion clock.
    // reset is active-high and synchronous.

    // A reset cycle clears the registered output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (out_data == 18'b0)
    );

// The upper 17 bits shift toward MSB on each active cycle.
    check_shift_upper_bits: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out_data[17:1] == $past(out_data[16:0]))
    );

// The LSB captures data[0] on each active cycle.
    check_shift_lsb_capture: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out_data[0] == $past(data[0]))
    );

// Eighteen shifted-in zeros flush the whole register to zero.
    check_zero_stream_flushes_register: assert property (
        @(posedge clk) disable iff (reset)
        (data[0] == 1'b0)[*18] |=> (out_data == 18'b0)
    );

// Eighteen shifted-in ones fill the whole register with ones.
    check_one_stream_fills_register: assert property (
        @(posedge clk) disable iff (reset)
        (data[0] == 1'b1)[*18] |=> (out_data == 18'h3FFFF)
    );

// RTL is combinational with no reset; clk is the SVA sampling clock.

    // Y must match the selected boolean function.
    check_y_functional_equivalence: assert property (
        @(posedge clk)
        Y == ((sel == 2'b00) ? (A ^ B) :
              (sel == 2'b01) ? (A & B) :
              (sel == 2'b10) ? (A | B) :
                               ~(A & B))
    );

// sel=00 selects XOR of A and B.
    check_sel_xor: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (Y == (A ^ B))
    );

// sel=01 selects AND of A and B.
    check_sel_and: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (Y == (A & B))
    );

// sel=10 selects OR of A and B.
    check_sel_or: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (Y == (A | B))
    );

// sel=11 selects NAND of A and B.
    check_sel_nand: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (Y == ~(A & B))
    );

// sprsel must match the RTL decision tree.
    check_sprsel_function: assert property (
        @(posedge clk)
        sprsel == ((sprcode != 3'd7) &&
                   !(pf1front && nplayfield[1]) &&
                   !(pf2front && nplayfield[2]))
    );

// No active sprite group forces sprsel low.
    check_no_active_sprite_clears_sprsel: assert property (
        @(posedge clk)
        (nsprite == 8'h00) |-> (sprsel == 1'b0)
    );

// Any active sprite is selected when both playfields are absent.
    check_active_sprite_selected_without_playfields: assert property (
        @(posedge clk)
        (nsprite != 8'h00 && !nplayfield[1] && !nplayfield[2]) |-> (sprsel == 1'b1)
    );

// PF1 blocks the chosen sprite when its priority is in front.
    check_pf1_front_blocks_sprite: assert property (
        @(posedge clk)
        (sprcode != 3'd7 && pf1front && nplayfield[1]) |-> (sprsel == 1'b0)
    );

// PF2 blocks the chosen sprite when PF1 does not already block it.
    check_pf2_front_blocks_sprite: assert property (
        @(posedge clk)
        (sprcode != 3'd7 && !(pf1front && nplayfield[1]) && pf2front && nplayfield[2]) |-> (sprsel == 1'b0)
    );

// Group 0 has priority over group 1.
    check_group0_priority_over_group1: assert property (
        @(posedge clk)
        (sprgroup[0] && sprgroup[1] && nplayfield[1] && !nplayfield[2] && (bplcon2[2:0] == 3'd1)) |-> (sprsel == 1'b1)
    );

// Group 1 has priority over group 2 when group 0 is inactive.
    check_group1_priority_over_group2: assert property (
        @(posedge clk)
        (!sprgroup[0] && sprgroup[1] && sprgroup[2] && nplayfield[1] && !nplayfield[2] && (bplcon2[2:0] == 3'd2)) |-> (sprsel == 1'b1)
    );

// Group 2 has priority over group 3 when groups 0 and 1 are inactive.
    check_group2_priority_over_group3: assert property (
        @(posedge clk)
        (!sprgroup[0] && !sprgroup[1] && sprgroup[2] && sprgroup[3] && nplayfield[1] && !nplayfield[2] && (bplcon2[2:0] == 3'd3)) |-> (sprsel == 1'b1)
    );

// A lone group 3 sprite is hidden by PF1 at threshold 3.
    check_group3_hidden_by_pf1_at_threshold3: assert property (
        @(posedge clk)
        (!sprgroup[0] && !sprgroup[1] && !sprgroup[2] && sprgroup[3] &&
         nplayfield[1] && !nplayfield[2] && (bplcon2[2:0] == 3'd3)) |-> (sprsel == 1'b0)
    );

// A lone group 3 sprite remains visible against PF1 at threshold 4.
    check_group3_visible_against_pf1_at_threshold4: assert property (
        @(posedge clk)
        (!sprgroup[0] && !sprgroup[1] && !sprgroup[2] && sprgroup[3] &&
         nplayfield[1] && !nplayfield[2] && (bplcon2[2:0] == 3'd4)) |-> (sprsel == 1'b1)
    );

// PF2 hides a lone group 2 sprite when the upper priority field is 2.
    check_group2_hidden_by_pf2_at_threshold2: assert property (
        @(posedge clk)
        (!sprgroup[0] && !sprgroup[1] && sprgroup[2] && !sprgroup[3] &&
         !nplayfield[1] && nplayfield[2] && (bplcon2[5:3] == 3'd2)) |-> (sprsel == 1'b0)
    );

// PF2 does not hide a lone group 2 sprite when the upper priority field is 3.
    check_group2_visible_against_pf2_at_threshold3: assert property (
        @(posedge clk)
        (!sprgroup[0] && !sprgroup[1] && sprgroup[2] && !sprgroup[3] &&
         !nplayfield[1] && nplayfield[2] && (bplcon2[5:3] == 3'd3)) |-> (sprsel == 1'b1)
    );

// gated_clk is low just before each src_clk rising edge.
    check_gated_clk_low_before_src_clk_rise: assert property (
        @(posedge src_clk) (gated_clk == 1'b0)
    );

// Clock: clk. Reset: reset, asynchronous active-high.
    // Mixed logic: sequential counter with combinational parity and output mapping.

    // During reset, the counter nibble is held at zero.
    check_reset_count_zero: assert property (
        @(posedge clk) reset |-> (out[3:0] == 4'h0)
    );

// During reset, the difference nibble is 0 minus the input parity.
    check_reset_diff_matches_parity: assert property (
        @(posedge clk) reset |-> (out[7:4] == ((^in) ? 4'hF : 4'h0))
    );

// After any sampled reset cycle, the next sampled counter nibble is still zero.
    check_post_reset_count_zero: assert property (
        @(posedge clk) reset |=> (out[3:0] == 4'h0)
    );

// After any sampled reset cycle, the next sampled difference nibble still reflects zero count.
    check_post_reset_diff_matches_parity: assert property (
        @(posedge clk) reset |=> (out[7:4] == ((^in) ? 4'hF : 4'h0))
    );

// Across non-reset cycles, the counter nibble increments by one modulo 16.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (out[3:0] == ($past(out[3:0]) + 4'h1))
    );

// With even input parity, the difference nibble matches the counter nibble.
    check_even_parity_diff: assert property (
        @(posedge clk) disable iff (reset) ((^in) == 1'b0) |-> (out[7:4] == out[3:0])
    );

// With odd input parity, the difference nibble is one less than the counter nibble.
    check_odd_parity_diff: assert property (
        @(posedge clk) disable iff (reset) ((^in) == 1'b1) |-> (out[7:4] == (out[3:0] - 4'h1))
    );

// ctrl 000 selects bitwise AND.
    check_and_operation: assert property (
        @(posedge clk) (ctrl == 3'b000) |-> (out == (A & B))
    );

// ctrl 001 selects bitwise OR.
    check_or_operation: assert property (
        @(posedge clk) (ctrl == 3'b001) |-> (out == (A | B))
    );

// ctrl 010 selects bitwise XOR.
    check_xor_operation: assert property (
        @(posedge clk) (ctrl == 3'b010) |-> (out == (A ^ B))
    );

// ctrl 011 selects addition.
    check_add_operation: assert property (
        @(posedge clk) (ctrl == 3'b011) |-> (out == (A + B))
    );

// ctrl 100 selects subtraction.
    check_sub_operation: assert property (
        @(posedge clk) (ctrl == 3'b100) |-> (out == (A - B))
    );

// Output matches the mux select function.
    check_mux_function: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

// When select is low, the output routes A.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !SEL |-> (Y == A)
    );

// When select is high, the output routes B.
    check_sel_high_routes_b: assert property (
        @(posedge clk) SEL |-> (Y == B)
    );

// The output is always equal to one of the two inputs.
    check_output_is_input_a_or_b: assert property (
        @(posedge clk) (Y == A) || (Y == B)
    );

// If both inputs match, the output matches that value.
    check_equal_inputs_produce_same_output: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

// If output differs from A, B must be selected and drive the output.
    check_output_differs_from_a_only_when_b_selected: assert property (
        @(posedge clk) (Y != A) |-> (SEL && (Y == B))
    );

// If output differs from B, A must be selected and drive the output.
    check_output_differs_from_b_only_when_a_selected: assert property (
        @(posedge clk) (Y != B) |-> ((!SEL) && (Y == A))
    );

// 000001 maps to 000.
    check_encode_000001: assert property (
        @(posedge clk) (data == 6'b000001) |-> (q == 3'b000)
    );

// 000010 maps to 001.
    check_encode_000010: assert property (
        @(posedge clk) (data == 6'b000010) |-> (q == 3'b001)
    );

// 000100 maps to 010.
    check_encode_000100: assert property (
        @(posedge clk) (data == 6'b000100) |-> (q == 3'b010)
    );

// 001000 maps to 011.
    check_encode_001000: assert property (
        @(posedge clk) (data == 6'b001000) |-> (q == 3'b011)
    );

// 010000 maps to 100.
    check_encode_010000: assert property (
        @(posedge clk) (data == 6'b010000) |-> (q == 3'b100)
    );

// 100000 maps to 101.
    check_encode_100000: assert property (
        @(posedge clk) (data == 6'b100000) |-> (q == 3'b101)
    );

// All other inputs map to the default code.
    check_default_encoding: assert property (
        @(posedge clk)
        (data != 6'b000001 &&
         data != 6'b000010 &&
         data != 6'b000100 &&
         data != 6'b001000 &&
         data != 6'b010000 &&
         data != 6'b100000) |-> (q == 3'b110)
    );

// The output never produces 111.
    check_q_never_111: assert property (
        @(posedge clk) (q != 3'b111)
    );

// Q_N is always the sampled inverse of Q.
    check_qn_inverse_of_q: assert property (
        @(posedge CLK) (Q_N === ~Q)
    );

// When scan is enabled, Q captures SCD on the next sampled cycle.
    check_scan_loads_q_from_scd: assert property (
        @(posedge CLK) (SCE === 1'b1) |=> (Q === $past(SCD))
    );

// When scan is not enabled, Q captures D on the next sampled cycle.
    check_data_loads_q_from_d: assert property (
        @(posedge CLK) (SCE !== 1'b1) |=> (Q === $past(D))
    );

// When scan is enabled, Q_N reflects the inverse of prior SCD.
    check_scan_loads_qn_from_scd: assert property (
        @(posedge CLK) (SCE === 1'b1) |=> (Q_N === (~$past(SCD)))
    );

// When scan is not enabled, Q_N reflects the inverse of prior D.
    check_data_loads_qn_from_d: assert property (
        @(posedge CLK) (SCE !== 1'b1) |=> (Q_N === (~$past(D)))
    );

// RTL is combinational with no reset; clk is the sampling clock for assertions.

    // equal_sgn must be high whenever the two inputs are equal.
    check_output_high_on_equal_inputs: assert property (
        @(posedge clk) (Data_A == Data_B) |-> (equal_sgn == 1'b1)
    );

// equal_sgn must be low whenever the two inputs are different.
    check_output_low_on_unequal_inputs: assert property (
        @(posedge clk) (Data_A != Data_B) |-> (equal_sgn == 1'b0)
    );

// equal_sgn must exactly match the RTL compare expression, including X behavior.
    check_output_matches_rtl_expression: assert property (
        @(posedge clk) equal_sgn === ((Data_A == Data_B) ? 1'b1 : 1'b0)
    );

// byte_num 0 forces the output to 0x01000000.
    check_byte_num_zero_value: assert property (
        @(posedge clk)
        (byte_num === 2'd0) |-> (out === 32'h1000000)
    );

// byte_num 1 keeps the top byte and appends 0x010000.
    check_byte_num_one_value: assert property (
        @(posedge clk)
        (byte_num === 2'd1) |-> (out === {in[31:24], 24'h010000})
    );

// byte_num 2 keeps the top two bytes and appends 0x0100.
    check_byte_num_two_value: assert property (
        @(posedge clk)
        (byte_num === 2'd2) |-> (out === {in[31:16], 16'h0100})
    );

// byte_num 3 keeps the top three bytes and appends 0x01.
    check_byte_num_three_value: assert property (
        @(posedge clk)
        (byte_num === 2'd3) |-> (out === {in[31:8], 8'h01})
    );

// Synchronous reset clears out.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 1'b0)
    );

// When enabled and not in reset, out captures data.
    check_enable_captures_data: assert property (
        @(posedge clk) disable iff (reset) enable |=> (out == $past(data))
    );

// When not enabled and not in reset, out holds its value.
    check_disable_holds_out: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (out == $past(out))
    );

// Active-low reset forces Y low.
    check_reset_clears_y: assert property (
        @(posedge CLK) !RST |-> (Y == 1'b0)
    );

// When S is low, Y captures A on the next clock.
    check_select_a_capture: assert property (
        @(posedge CLK) disable iff (!RST)
        (S == 1'b0) |=> (Y == $past(A))
    );

// When S is high, Y captures B on the next clock.
    check_select_b_capture: assert property (
        @(posedge CLK) disable iff (!RST)
        (S == 1'b1) |=> (Y == $past(B))
    );

// MO must match the mux expression implemented in the RTL.
    check_mux_equation: assert property (
        @(posedge clk) MO === ((S == 1'b1) ? B : A)
    );

// A high select routes B to the output.
    check_select_high_routes_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (MO === B)
    );

// A low select routes A to the output.
    check_select_low_routes_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (MO === A)
    );

// Equal inputs make the output independent of select.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A === B) |-> (MO === A)
    );

// x=0 maps to sineh=0, cosh=1, tanh=0.
    check_x0_lookup: assert property (
        @(posedge clk)
        (x == 3'd0) |-> (sineh == 16'd0 && cosh == 16'd1 && tanh == 16'd0)
    );

// x=1 maps to sineh=1, cosh=1, tanh=1.
    check_x1_lookup: assert property (
        @(posedge clk)
        (x == 3'd1) |-> (sineh == 16'd1 && cosh == 16'd1 && tanh == 16'd1)
    );

// x=2 maps to sineh=3, cosh=4, tanh=1.
    check_x2_lookup: assert property (
        @(posedge clk)
        (x == 3'd2) |-> (sineh == 16'd3 && cosh == 16'd4 && tanh == 16'd1)
    );

// x=3 maps to sineh=10, cosh=11, tanh=1.
    check_x3_lookup: assert property (
        @(posedge clk)
        (x == 3'd3) |-> (sineh == 16'd10 && cosh == 16'd11 && tanh == 16'd1)
    );

// x=4 maps to sineh=27, cosh=28, tanh=1.
    check_x4_lookup: assert property (
        @(posedge clk)
        (x == 3'd4) |-> (sineh == 16'd27 && cosh == 16'd28 && tanh == 16'd1)
    );

// x=5,6,7 take the default mapping of sineh=0, cosh=1, tanh=0.
    check_default_lookup: assert property (
        @(posedge clk)
        (x == 3'd5 || x == 3'd6 || x == 3'd7) |-> (sineh == 16'd0 && cosh == 16'd1 && tanh == 16'd0)
    );

// tanh is 1 only for inputs 1 through 4.
    check_tanh_region: assert property (
        @(posedge clk)
        ((x == 3'd1 || x == 3'd2 || x == 3'd3 || x == 3'd4) |-> (tanh == 16'd1))
    );

// tanh is 0 for input 0 and all default cases.
    check_tanh_default_region: assert property (
        @(posedge clk)
        ((x == 3'd0 || x == 3'd5 || x == 3'd6 || x == 3'd7) |-> (tanh == 16'd0))
    );

// Reset drives the CRC state to all ones.
    check_reset_value: assert property (
        @(posedge clk) rst |=> (crc_out == 32'hffffffff && serial_out == 1'b1)
    );

// serial_out always mirrors the CRC LSB.
    check_serial_matches_lsb: assert property (
        @(posedge clk) disable iff (rst) (serial_out == crc_out[0])
    );

// clr loads all ones and has priority over enable and shift.
    check_clear_sets_all_ones: assert property (
        @(posedge clk) disable iff (rst)
        clr |=> (crc_out == 32'hffffffff && serial_out == 1'b1)
    );

// enable updates the CRC with the implemented feedback polynomial.
    check_enable_updates_crc: assert property (
        @(posedge clk) disable iff (rst)
        (enable && !clr) |=> (crc_out == next_crc($past(crc_out), $past(data)))
    );

// shift right occurs only when enable and clr are not active.
    check_shift_right: assert property (
        @(posedge clk) disable iff (rst)
        (shift && !enable && !clr) |=> (crc_out == {1'b0, $past(crc_out[31:1])})
    );

// With no control active, the CRC register holds its value.
    check_idle_holds_crc: assert property (
        @(posedge clk) disable iff (rst)
        (!clr && !enable && !shift) |=> (crc_out == $past(crc_out))
    );

// op 00 loads the sum of a and b into result.
    check_addition_result: assert property (
        @(posedge clk) disable iff (reset)
        (op == 2'b00) |=> (result == (($past(a) + $past(b)) & 16'h00ff))
    );

// op 01 loads the difference of a and b into result.
    check_subtraction_result: assert property (
        @(posedge clk) disable iff (reset)
        (op == 2'b01) |=> (result == (($past(a) - $past(b)) & 16'h00ff))
    );

// Reset clears count on the following clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Count wraps from 9 back to 0 when not in reset.
    check_wrap_at_nine: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'b1001) |=> (count == 4'b0000)
    );

// Count increments by one on all other non-reset cycles.
    check_increment_otherwise: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'b1001) |=> (count == ($past(count) + 4'b0001))
    );

// If a is greater than b, out must be high.
    check_a_gt_b_sets_out_high: assert property (
        @(posedge clk) (a > b) |-> (out == 1'b1)
    );

// If a is less than b, out must be low.
    check_a_lt_b_sets_out_low: assert property (
        @(posedge clk) (a < b) |-> (out == 1'b0)
    );

// For unequal inputs, out must match the a>b comparison.
    check_unequal_inputs_match_compare: assert property (
        @(posedge clk) (a != b) |-> (out == (a > b))
    );

// For unequal inputs, a high out implies a is greater than b.
    check_unequal_out_high_implies_a_gt_b: assert property (
        @(posedge clk) ((a != b) && (out == 1'b1)) |-> (a > b)
    );

// For unequal inputs, a low out implies a is less than b.
    check_unequal_out_low_implies_a_lt_b: assert property (
        @(posedge clk) ((a != b) && (out == 1'b0)) |-> (a < b)
    );

// DUT is combinational; clk is only used to sample assertions and there is no reset.

    // When enable is 0, out must select in1.
    check_select_in1: assert property (
        @(posedge clk) (enable === 1'b0) |-> (out === in1)
    );

// When enable is not 0, out must select in2.
    check_select_in2: assert property (
        @(posedge clk) (enable !== 1'b0) |-> (out === in2)
    );

// The output must always match the implemented mux branch.
    check_mux_function: assert property (
        @(posedge clk)
        (((enable === 1'b0) && (out === in1)) ||
         ((enable !== 1'b0) && (out === in2)))
    );

// Stall still forwards ex_pc because the later assignment overrides the zero write.
    check_stall_forwards_pc: assert property (
        @(posedge clk) disable iff (rst)
        stall |=> (me_pc == $past(ex_pc))
    );

// Without stall, the ALU result is registered into the ME stage.
    check_pass_aluresult: assert property (
        @(posedge clk) disable iff (rst)
        !stall |=> (me_aluresult == $past(ex_aluresult))
    );

// Without stall, store data and destination register are registered.
    check_pass_d2_td: assert property (
        @(posedge clk) disable iff (rst)
        !stall |=> ((me_d2 == $past(ex_d2)) &&
                    (me_td == $past(ex_td)))
    );

// Without stall, the writeback and memory control bits are registered.
    check_pass_controls: assert property (
        @(posedge clk) disable iff (rst)
        !stall |=> ((me_WREG == $past(ex_WREG)) &&
                    (me_WMEM == $past(ex_WMEM)) &&
                    (me_LW   == $past(ex_LW)))
    );

// Without stall, the instruction is registered into the ME stage.
    check_pass_instr: assert property (
        @(posedge clk) disable iff (rst)
        !stall |=> (me_instr == $past(ex_instr))
    );

// Without stall, the PC is registered into the ME stage.
    check_pass_pc: assert property (
        @(posedge clk) disable iff (rst)
        !stall |=> (me_pc == $past(ex_pc))
    );

// cpu_d_address mirrors d_address.
    check_cpu_d_address_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (cpu_d_address == d_address)
    );

// cpu_d_read mirrors d_read.
    check_cpu_d_read_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (cpu_d_read == d_read)
    );

// cpu_d_readdata mirrors av_ld_data_aligned_filtered.
    check_cpu_d_readdata_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (cpu_d_readdata == av_ld_data_aligned_filtered)
    );

// cpu_d_wait mirrors d_waitrequest.
    check_cpu_d_wait_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (cpu_d_wait == d_waitrequest)
    );

// cpu_d_write mirrors d_write.
    check_cpu_d_write_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (cpu_d_write == d_write)
    );

// cpu_d_writedata mirrors E_st_data.
    check_cpu_d_writedata_passthrough: assert property (
        @(posedge clk) disable iff (!reset_n)
        (cpu_d_writedata == E_st_data)
    );

// dbrk_break is cleared on the first clock after reset release.
    check_dbrk_break_clear_on_reset_release: assert property (
        @(posedge clk) disable iff (!reset_n)
        $rose(reset_n) |-> (dbrk_break == 1'b0)
    );

// dbrk_break goes high one cycle after debugack is high.
    check_dbrk_break_follows_debugack_high: assert property (
        @(posedge clk) disable iff (!reset_n)
        debugack |=> (dbrk_break == 1'b1)
    );

// dbrk_break goes low one cycle after debugack is low.
    check_dbrk_break_follows_debugack_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!debugack) |=> (dbrk_break == 1'b0)
    );

// dbrk_goto0 is always low outside reset.
    check_dbrk_goto0_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (dbrk_goto0 == 1'b0)
    );

// dbrk_goto1 is always low outside reset.
    check_dbrk_goto1_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (dbrk_goto1 == 1'b0)
    );

// dbrk_traceme is always low outside reset.
    check_dbrk_traceme_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (dbrk_traceme == 1'b0)
    );

// dbrk_traceoff is always low outside reset.
    check_dbrk_traceoff_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (dbrk_traceoff == 1'b0)
    );

// dbrk_traceon is always low outside reset.
    check_dbrk_traceon_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (dbrk_traceon == 1'b0)
    );

// dbrk_trigout is always low outside reset.
    check_dbrk_trigout_low: assert property (
        @(posedge clk) disable iff (!reset_n)
        (dbrk_trigout == 1'b0)
    );
